UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo palabras nuevas 🗣️', body_es = '¿Qué palabra nueva ha dicho hoy?', title_fr = 'Un nouveau mot découvert 🗣️', body_fr = 'Quel nouveau mot a-t-il dit aujourd''hui ?', title_hi = 'नए शब्द की खोज 🗣️', body_hi = 'आज उसने कौन-सा नया शब्द बोला?', title_id = 'Menemukan kata baru 🗣️', body_id = 'Kata baru apa yang ia ucapkan hari ini?', title_ja = '新しい言葉の発見 🗣️', body_ja = '今日はどんな新しい言葉を言いましたか？', title_ko = '새로운 단어 발견 🗣️', body_ko = '오늘은 어떤 새로운 단어를 말했나요?', title_nl = 'Nieuwe woorden ontdekken 🗣️', body_nl = 'Welk nieuw woord zei hij vandaag?', title_pl = 'Odkrywanie nowych słów 🗣️', body_pl = 'Jakie nowe słowo powiedział dziś?', title_pt = 'Uma palavra nova 🗣️', body_pt = 'Que palavra nova disse hoje?', title_sv = 'Nytt ord upptäckt 🗣️', body_sv = 'Vilket nytt ord sa barnet i dag?', title_vi = 'Khám phá từ mới 🗣️', body_vi = 'Hôm nay bé đã nói từ mới nào?', title_zh = '发现新词 🗣️', body_zh = '宝宝今天说了什么新词？' WHERE id = 'fcfa5044-061e-4832-8787-ddd94f46ab93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Risas de la noche 📸', body_es = '¡No te pierdas esa cosa graciosa que hace antes de dormir!', title_fr = 'Fous rires du soir 📸', body_fr = 'Ne manquez pas le geste rigolo qu''il fait avant de dormir !', title_hi = 'शाम की खिलखिलाहट 📸', body_hi = 'सोने से पहले की उसकी वह मज़ेदार हरकत मत चूकिए!', title_id = 'Tawa di sore hari 📸', body_id = 'Jangan lewatkan gerakan lucunya sebelum tidur!', title_ja = '夕方の大笑い 📸', body_ja = '寝る前のおもしろいしぐさを見逃さないで！', title_ko = '저녁의 깔깔 웃음 📸', body_ko = '자기 전에 하는 그 웃긴 행동을 놓치지 마세요!', title_nl = 'Avondgegiechel 📸', body_nl = 'Mis dat grappige ding niet dat hij doet voor het slapengaan!', title_pl = 'Wieczorne chichoty 📸', body_pl = 'Nie przegap tej zabawnej rzeczy, którą robi przed snem!', title_pt = 'Gargalhadas ao fim do dia 📸', body_pt = 'Não perca aquele gesto engraçado que faz antes de dormir!', title_sv = 'Kvällsskratt 📸', body_sv = 'Missa inte det där roliga barnet gör innan läggdags!', title_vi = 'Tiếng cười buổi tối 📸', body_vi = 'Đừng bỏ lỡ trò ngộ nghĩnh bé làm trước khi ngủ!', title_zh = '傍晚的欢笑 📸', body_zh = '别错过宝宝睡前那个搞笑动作！' WHERE id = 'f9d59314-c8fe-45fa-9d77-efb82ec57626' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🌟', body_es = 'Cada nueva habilidad que aprende es fruto de tu esfuerzo.', title_fr = 'L''héroïne du jour, c''est vous 🌟', body_fr = 'Chaque nouvelle compétence qu''il apprend, c''est grâce à vous.', title_hi = 'आज की हीरो आप हैं 🌟', body_hi = 'हर दिन वह जो नई चीज़ सीखता है, वह आपकी मेहनत है।', title_id = 'Pahlawan hari ini adalah Anda 🌟', body_id = 'Setiap keterampilan baru yang ia pelajari adalah hasil kerja keras Anda.', title_ja = '今日のヒーローはあなたです 🌟', body_ja = '毎日新しくできるようになることは、あなたのがんばりのおかげです。', title_ko = '오늘의 주인공은 엄마예요 🌟', body_ko = '아이가 매일 배우는 새로운 능력은 엄마의 노력 덕분이에요.', title_nl = 'Jij bent de held van vandaag 🌟', body_nl = 'Elke nieuwe vaardigheid die hij leert, is dankzij jou.', title_pl = 'Dzisiejszą bohaterką jesteś ty 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, to twoja zasługa.', title_pt = 'A heroína do dia é a mãe 🌟', body_pt = 'Cada nova competência que ele aprende é fruto do seu esforço.', title_sv = 'Dagens hjälte är du 🌟', body_sv = 'Varje ny färdighet barnet lär sig är tack vare ditt arbete.', title_vi = 'Mẹ là người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày đều là công sức của mẹ.', title_zh = '今天的英雄是你 🌟', body_zh = '宝宝每天学会的新本领都有你的功劳。' WHERE id = '40782485-009f-459f-b399-6e2d09a90f95' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce