UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá 📖', body_es = 'Esta noche deja descansar tus cuerdas vocales. Que papá se encargue de leer los libros favoritos de tu peque con voces distintas y de forma divertida.', title_fr = 'L''histoire de papa 📖', body_fr = 'Ce soir, reposez vos cordes vocales. Laissez papa lire ses livres préférés en changeant de voix, de façon rigolote.', title_hi = 'पापा की कहानी 📖', body_hi = 'आज शाम अपनी आवाज़ को आराम दीजिए। बच्चे की सबसे पसंदीदा किताबें अलग-अलग आवाज़ों में, मज़ेदार ढंग से पढ़ने का काम पापा को करने दीजिए।', title_id = 'Cerita dari Ayah 📖', body_id = 'Istirahatkan pita suara Anda malam ini. Biarkan Ayah yang bertugas membacakan buku favorit si kecil dengan berbagai nada suara yang lucu.', title_ja = 'パパのお話 📖', body_ja = '今夜はあなたののどを休ませましょう。お子さんの大好きな絵本を、いろいろな声色でおもしろく読む役目は、パパにお任せして。', title_ko = '아빠의 이야기 시간 📖', body_ko = '오늘 밤엔 목을 쉬게 해 주세요. 아이가 가장 좋아하는 책을 다양한 목소리로 재미있게 읽어 주는 일은 아빠에게 맡기세요.', title_nl = 'Papa''s verhaal 📖', body_nl = 'Laat je stembanden vanavond rusten. Laat papa de lievelingsboeken van je kindje grappig voorlezen met verschillende stemmetjes.', title_pl = 'Bajka od taty 📖', body_pl = 'Daj dziś wieczorem odpocząć strunom głosowym. Niech to tata czyta ulubione książeczki malucha zabawnie, różnymi głosami.', title_pt = 'A história do pai 📖', body_pt = 'Esta noite, descanse as cordas vocais. Deixe o pai ler os livros preferidos dele com vozes diferentes e de forma divertida.', title_sv = 'Pappas berättelse 📖', body_sv = 'Vila stämbanden i kväll. Låt pappa läsa barnets favoritböcker med olika röster och på ett roligt sätt.', title_vi = 'Câu chuyện của bố 📖', body_vi = 'Tối nay hãy để dây thanh quản của mẹ được nghỉ. Để bố đảm nhận việc đọc những cuốn sách bé yêu thích bằng nhiều giọng khác nhau thật hài hước.', title_zh = '爸爸讲故事 📖', body_zh = '今晚让你的嗓子休息一下。让爸爸用不同的声音、搞笑地读宝宝最爱的书吧。' WHERE id = '01e01b8e-03c9-4797-b794-5c6f68c813f6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
