UPDATE public.mommy_day_notifications SET title_es = 'Caprichos de la mañana ☁️', title_fr = 'Caprices du matin ☁️', title_hi = 'सुबह के नखरे ☁️', title_id = 'Rewel di pagi hari ☁️', title_ja = '朝の不機嫌 ☁️', title_ko = '아침 투정 ☁️', title_nl = 'Ochtendhumeur ☁️', title_pl = 'Poranne kaprysy ☁️', title_pt = 'Rabugice da manhã ☁️', title_sv = 'Morgongnäll ☁️', title_vi = 'Nhõng nhẽo buổi sáng ☁️', title_zh = '早上的小脾气 ☁️' WHERE id = 'a40edf39-5245-44c1-a544-58bd483fee61' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de lavarse los dientes 🦷', body_es = '¿No te deja acercarle el cepillo a la boca? No lo conviertas en una obligación, sino en un juego. Deja que te lave los dientes a ti y luego le toca a él.', title_fr = 'La bataille du brossage de dents 🦷', body_fr = 'Il ne laisse pas la brosse s''approcher de sa bouche ? N''en faites pas une obligation mais un jeu. Laissez-le vous brosser les dents, puis ce sera votre tour.', title_hi = 'दाँत ब्रश करने की जंग 🦷', body_hi = 'ब्रश मुँह के पास नहीं आने देता? इसे मजबूरी नहीं, खेल बनाइए। उसे आपके दाँत ब्रश करने दीजिए, फिर अगली बारी आपकी।', title_id = 'Perang sikat gigi 🦷', body_id = 'Tidak mau sikat gigi didekatkan ke mulutnya? Jadikan permainan, bukan paksaan. Biarkan ia menyikat gigi Anda dulu, lalu giliran Anda.', title_ja = '歯みがきバトル 🦷', body_ja = '歯ブラシを口に近づけさせてくれない？無理やりではなく、遊びに変えましょう。まずお子さんにあなたの歯をみがかせて、次はあなたの番です。', title_ko = '양치 전쟁 🦷', body_ko = '칫솔을 입 가까이 대지도 못하게 하나요? 억지로 하지 말고 놀이로 바꿔 보세요. 먼저 아이가 엄마 이를 닦게 하고, 다음은 아이 차례예요.', title_nl = 'Strijd om het tandenpoetsen 🦷', body_nl = 'Laat hij de borstel niet in de buurt van zijn mond komen? Maak er geen verplichting, maar een spel van. Laat hem jouw tanden poetsen, en daarna ben jij aan de beurt.', title_pl = 'Bitwa o mycie ząbków 🦷', body_pl = 'Nie pozwala zbliżyć szczoteczki do buzi? Zamień to nie w przymus, tylko w zabawę. Pozwól mu umyć twoje zęby, a potem twoja kolej.', title_pt = 'A guerra da escova de dentes 🦷', body_pt = 'Não deixa aproximar a escova da boca? Transforme isto num jogo, não numa obrigação. Deixe-o escovar-lhe os dentes a si e depois é a sua vez.', title_sv = 'Kampen om tandborstningen 🦷', body_sv = 'Låter barnet dig inte föra tandborsten mot munnen? Gör det till en lek, inte ett tvång. Låt barnet borsta dina tänder först, och sedan är det din tur.', title_vi = 'Cuộc chiến đánh răng 🦷', body_vi = 'Bé không cho đưa bàn chải lại gần miệng? Hãy biến việc này thành trò chơi chứ đừng ép buộc. Để bé đánh răng cho mẹ trước, rồi sau đó đến lượt mẹ.', title_zh = '刷牙大战 🦷', body_zh = '不让牙刷靠近嘴巴？别强迫，把它变成游戏。先让宝宝给你刷牙，然后轮到你。' WHERE id = 'a805f1c5-c4c1-4bb3-8f2d-828f16d9efaf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
