UPDATE public.mommy_day_notifications SET title_es = 'Escudo de calcio 🦴', title_fr = 'Bouclier calcium 🦴', title_hi = 'कैल्शियम की ढाल 🦴', title_id = 'Perisai kalsium 🦴', title_ja = 'カルシウムのシールド 🦴', title_ko = '칼슘 방패 🦴', title_nl = 'Calciumschild 🦴', title_pl = 'Tarcza z wapnia 🦴', title_pt = 'Escudo de cálcio 🦴', title_sv = 'Kalciumskölden 🦴', title_vi = 'Lá chắn canxi 🦴', title_zh = '钙的护盾 🦴' WHERE id = '87c32869-7e9b-4faa-bbbe-1c640a3da5bb' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juntos, pero por separado 👶', body_es = '¿En el parque no juega con otros niños, sino que los observa? ¡Es el juego paralelo! Pregunta a Anacan AI datos curiosos sobre esta etapa de socialización.', title_fr = 'Ensemble, mais chacun de son côté 👶', body_fr = 'Au parc, il ne joue pas avec les autres enfants mais les observe ? C''est le jeu parallèle ! Demandez à Anacan AI des faits intéressants sur cette étape de socialisation.', title_hi = 'साथ-साथ, पर अलग-अलग 👶', body_hi = 'पार्क में बच्चों के साथ खेलता नहीं, बस दूर से देखता है? यह पैरेलल प्ले है! Anacan AI से मेल-जोल के इस दौर के बारे में दिलचस्प बातें पूछिए।', title_id = 'Bersama, tapi terpisah 👶', body_id = 'Di taman ia tidak bermain dengan anak lain, hanya mengamati dari pinggir? Ini bermain paralel! Tanyakan fakta menarik tentang tahap sosialisasi ini kepada Anacan AI.', title_ja = '一緒に、でも別々に 👶', body_ja = '公園でほかの子と遊ばず、そばで見ているだけ？これは「平行遊び」です！この社会性の段階について、Anacan AIにおもしろい豆知識を聞いてみましょう。', title_ko = '함께, 하지만 따로 👶', body_ko = '공원에서 아이들과 놀지 않고 옆에서 지켜만 보나요? 이건 평행 놀이예요! 이 사회성 발달 단계에 관한 흥미로운 사실을 Anacan AI에게 물어보세요.', title_nl = 'Samen, maar apart 👶', body_nl = 'Speelt hij in het park niet met andere kinderen, maar kijkt hij alleen toe? Dat is parallel spel! Vraag Anacan AI naar leuke feitjes over deze fase van socialisatie.', title_pl = 'Razem, ale osobno 👶', body_pl = 'W parku nie bawi się z dziećmi, tylko patrzy z boku? To zabawa równoległa! Zapytaj Anacan AI o ciekawostki na temat tego etapu uspołecznienia.', title_pt = 'Juntos, mas separados 👶', body_pt = 'No parque não brinca com as outras crianças, só observa? É a brincadeira paralela! Pergunte ao Anacan AI factos curiosos sobre esta fase da socialização.', title_sv = 'Tillsammans, men var för sig 👶', body_sv = 'Leker barnet inte med de andra barnen i parken utan tittar bara på? Det är parallellek! Fråga Anacan AI om intressanta fakta om det här sociala stadiet.', title_vi = 'Cùng nhau nhưng riêng lẻ 👶', body_vi = 'Ở công viên bé không chơi cùng các bạn mà chỉ đứng nhìn? Đó là chơi song song! Hãy hỏi Anacan AI những điều thú vị về giai đoạn hòa nhập xã hội này.', title_zh = '在一起，又各玩各的 👶', body_zh = '在公园不和小朋友玩，只在旁边看？这是平行游戏！向Anacan AI问问关于这个社交阶段的有趣知识。' WHERE id = '9a0a29d7-d513-4158-b204-99c831639c23' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le aprietan los zapatos? 📏', body_es = '¿Últimamente tropieza a menudo al correr? ¡Puede que le haya crecido el pie! Introduce su talla y medidas actuales en el Seguimiento del desarrollo y sigue su crecimiento físico.', title_fr = 'Ses chaussures le serrent ? 📏', body_fr = 'Il trébuche souvent en courant ces derniers temps ? Son pied a peut-être grandi ! Entrez sa taille et ses mesures actuelles dans le Suivi de croissance et suivez son développement physique.', title_hi = 'जूते तंग हो रहे हैं? 📏', body_hi = 'आजकल दौड़ते समय अक्सर लड़खड़ाता है? शायद पैर बड़े हो गए हैं! ग्रोथ ट्रैकर में मौजूदा लंबाई और माप दर्ज कीजिए और शारीरिक विकास पर नज़र रखिए।', title_id = 'Sepatunya sesak? 📏', body_id = 'Akhir-akhir ini sering tersandung saat berlari? Kakinya mungkin sudah bertambah besar! Masukkan tinggi dan ukuran terbarunya ke Pelacak Perkembangan dan pantau pertumbuhan fisiknya.', title_ja = '靴がきつい？📏', body_ja = '最近、走るとよくつまずきますか？足が大きくなったのかもしれません！「発達トラッカー」に今の身長やサイズを入力して、体の成長を記録しましょう。', title_ko = '신발이 끼나요? 📏', body_ko = '요즘 뛰다가 자주 넘어지나요? 발이 자랐을 수도 있어요! 성장 기록에 현재 키와 치수를 입력하고 신체 발달을 지켜보세요.', title_nl = 'Knellen de schoenen? 📏', body_nl = 'Struikelt hij de laatste tijd vaak bij het rennen? Zijn voetjes kunnen gegroeid zijn! Voer zijn huidige lengte en maten in de Groeitracker in en volg zijn lichamelijke ontwikkeling.', title_pl = 'Buciki uciskają? 📏', body_pl = 'Ostatnio często potyka się podczas biegania? Może urosła mu stopa! Wpisz aktualny wzrost i wymiary w Śledzeniu rozwoju i śledź jego rozwój fizyczny.', title_pt = 'Os sapatos apertam? 📏', body_pt = 'Ultimamente tropeça muito quando corre? O pé pode ter crescido! Introduza a altura e as medidas atuais no Registo de Desenvolvimento e acompanhe o crescimento físico.', title_sv = 'Klämmer skorna? 📏', body_sv = 'Snubblar barnet ofta när hen springer på sistone? Foten kan ha växt! Ange aktuell längd och mått i Utvecklingsspåraren och följ den fysiska utvecklingen.', title_vi = 'Giày bị chật? 📏', body_vi = 'Dạo này bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập chiều cao và số đo hiện tại vào Theo dõi phát triển để theo sát sự phát triển thể chất.', title_zh = '鞋子挤脚了？📏', body_zh = '最近跑的时候经常绊倒？可能是脚长大了！在发育追踪里输入当前的身高和尺寸，跟进身体发育情况。' WHERE id = '8ad462c4-33b5-4c76-be29-aa192feb14a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de hierro 🥩', body_es = '¡Alimenta esos músculos que no paran de correr! Comprueba con el Seguimiento de tomas si hoy ha tomado suficiente hierro y ajusta su menú.', title_fr = 'Besoins en fer 🥩', body_fr = 'Nourrissez ses muscles qui courent ! Vérifiez avec le Suivi des repas s''il a eu assez de fer aujourd''hui et ajustez son menu.', title_hi = 'आयरन की ज़रूरत 🥩', body_hi = 'दौड़ती मांसपेशियों को पोषण दीजिए! फ़ीडिंग ट्रैकर से जाँचिए कि आज उसे पर्याप्त आयरन मिला या नहीं, और मेन्यू ठीक कीजिए।', title_id = 'Kebutuhan zat besi 🥩', body_id = 'Beri nutrisi untuk otot yang terus berlari! Cek dengan alat Pemantau Nutrisi apakah hari ini ia cukup mendapat zat besi, lalu sesuaikan menunya.', title_ja = '鉄分が必要 🥩', body_ja = '走り回る筋肉に栄養を！「栄養管理ツール」で、今日鉄分を十分とれたか確認して、メニューを調整しましょう。', title_ko = '철분이 필요해요 🥩', body_ko = '뛰어노는 근육에 영양을 주세요! 수유 기록 도구로 오늘 철분을 충분히 섭취했는지 확인하고 식단을 조절하세요.', title_nl = 'IJzerbehoefte 🥩', body_nl = 'Geef die rennende spiertjes brandstof! Check met de Voedingstracker of hij vandaag genoeg ijzer heeft gehad en pas zijn menu aan.', title_pl = 'Zapotrzebowanie na żelazo 🥩', body_pl = 'Odżywiaj biegające mięśnie! Sprawdź w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco żelaza, i dopasuj menu.', title_pt = 'Necessidade de ferro 🥩', body_pt = 'Alimente esses músculos que não param de correr! Verifique com o Registo de Alimentação se hoje recebeu ferro suficiente e ajuste a ementa.', title_sv = 'Behov av järn 🥩', body_sv = 'Ge musklerna som springer näring! Kontrollera med Matningskoll om barnet fått tillräckligt med järn i dag och justera menyn.', title_vi = 'Nhu cầu sắt 🥩', body_vi = 'Hãy nuôi dưỡng đôi chân chạy nhảy không ngừng! Kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã nhận đủ sắt chưa và điều chỉnh thực đơn.', title_zh = '铁的需求 🥩', body_zh = '给跑个不停的小肌肉补充营养！用喂养记录工具看看宝宝今天是否摄入了足够的铁，调整一下菜单。' WHERE id = '8665ce13-4bbc-4643-86cd-402909af004b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por la pasta 🍝', title_fr = 'L''amour des pâtes 🍝', title_hi = 'पास्ता से प्यार 🍝', title_id = 'Cinta pasta 🍝', title_ja = 'パスタが大好き 🍝', title_ko = '파스타 사랑 🍝', title_nl = 'Dol op pasta 🍝', title_pl = 'Miłość do makaronu 🍝', title_pt = 'O gosto pela massa 🍝', title_sv = 'Kärlek till pasta 🍝', title_vi = 'Mê mì ống 🍝', title_zh = '爱吃意面 🍝' WHERE id = '383239b8-7f85-4507-9f51-cdc8a13d1e8f' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se acabó la pelea de la comida ⏱️', body_es = '¿Aparta la cuchara en la mesa? Para el temporizador de tomas, ya está lleno. Analiza el gráfico de apetito y evita obligarle a comer.', title_fr = 'Fini la bataille des repas ⏱️', body_fr = 'Il repousse la cuillère à table ? Arrêtez le minuteur des repas, il n''a plus faim. Analysez le graphique de l''appétit et évitez de le forcer à manger.', title_hi = 'खाने की लड़ाई खत्म ⏱️', body_hi = 'मेज़ पर चम्मच फेंक देता है? फ़ीडिंग टाइमर रोकिए, बच्चे का पेट भर गया है। भूख के चार्ट का विश्लेषण कीजिए और ज़बरदस्ती खिलाने से बचिए।', title_id = 'Drama makan selesai ⏱️', body_id = 'Melempar sendok ke samping di meja? Hentikan Timer Makan, si kecil sudah kenyang. Analisis grafik nafsu makannya dan hindari memaksanya makan.', title_ja = '食事のバトルはおしまい ⏱️', body_ja = '食卓でスプーンを投げますか？食事タイマーを止めましょう、おなかいっぱいのサインです。食欲のグラフを分析して、無理に食べさせるのは避けましょう。', title_ko = '식사 전쟁은 끝 ⏱️', body_ko = '식탁에서 숟가락을 던지나요? 수유 타이머를 멈추세요. 아이는 배가 부른 거예요. 식욕 그래프를 분석해 억지로 먹이지 않도록 하세요.', title_nl = 'De eetstrijd is voorbij ⏱️', body_nl = 'Gooit hij de lepel opzij aan tafel? Stop de Voedingstimer, hij zit vol. Analyseer de eetlustgrafiek en voorkom dat je hem dwingt te eten.', title_pl = 'Koniec wojny o jedzenie ⏱️', body_pl = 'Odrzuca łyżkę przy stole? Zatrzymaj timer karmienia, maluch jest najedzony. Analizując wykres apetytu, unikniesz karmienia na siłę.', title_pt = 'Acabou a guerra à mesa ⏱️', body_pt = 'Atira a colher para o lado? Pare o temporizador de alimentação: está satisfeito. Analise o gráfico do apetite e evite obrigá-lo a comer.', title_sv = 'Matbråket är över ⏱️', body_sv = 'Kastar barnet skeden åt sidan vid bordet? Stoppa matningstimern, barnet är mätt. Analysera aptitgrafen och undvik att tvångsmata.', title_vi = 'Cuộc chiến bữa ăn đã kết thúc ⏱️', body_vi = 'Bé vứt thìa sang bên? Hãy dừng Hẹn giờ cho bú, bé đã no rồi. Phân tích biểu đồ khẩu vị và tránh ép bé ăn.', title_zh = '吃饭之战结束了 ⏱️', body_zh = '在餐桌上把勺子扔到一边？停下喂养计时器，孩子吃饱了。分析一下食欲图表，避免强迫喂饭。' WHERE id = '60b3ac1d-dc8e-4802-b644-6bc09bfcea1f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño y sigue el gráfico. Quizá sea el momento de acortar la siesta 15 minutos.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil et suivez le graphique. C''est peut-être le bon moment pour raccourcir la sieste de 15 minutes.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 15 मिनट कम करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin inilah saatnya memangkas tidur siang 15 menit.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにして、グラフをチェックしましょう。お昼寝を15分短くするちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 15분 줄일 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan en volg de grafiek. Misschien is het precies tijd om het middagdutje met 15 minuten in te korten.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu i śledź wykres. Może to dobry moment, by skrócić drzemkę o 15 minut.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono e acompanhe o gráfico. Talvez seja a altura certa de encurtar a sesta 15 minutos.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern och följ grafen. Kanske är det precis rätt tid att korta dagsömnen med 15 minuter.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 15 phút.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器，看看图表。也许正是把白天小睡缩短15分钟的时候了。' WHERE id = '19a9511e-358f-41a2-bbf2-d966afa6ffa9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Artista cubierto de pintura! 📸', body_es = '¿Se ha pintado a sí mismo y la pared? En lugar de enfadarte, decora este momento tan gracioso con las pegatinas alegres de la Sesión de fotos del bebé y súbelo al álbum como recuerdo para siempre.', title_fr = 'Un artiste couvert de peinture ! 📸', body_fr = 'Il s''est peint lui-même, et le mur avec ? Au lieu de vous énerver, décorez ce gribouillage rigolo avec les stickers joyeux de la Séance photo bébé et ajoutez-le à l''album en souvenir.', title_hi = 'रंगों में डूबा कलाकार! 📸', body_hi = 'खुद को और दीवार को रंग दिया? गुस्सा होने के बजाय इस मज़ेदार चित्रकारी वाले पल को बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में हमेशा की याद के रूप में अपलोड कीजिए।', title_id = 'Seniman berlumur cat! 📸', body_id = 'Ia mewarnai dirinya dan dinding? Daripada kesal, hiasi momen corat-coret yang lucu ini dengan stiker ceria dari Sesi Foto Bayi dan unggah ke album sebagai kenangan abadi.', title_ja = '絵の具まみれのアーティスト！📸', body_ja = '自分も壁も絵の具だらけに？怒る代わりに、このおもしろいお絵かきの瞬間を「ベビーフォトセッション」の楽しいステッカーで飾って、永遠の思い出としてアルバムにアップしましょう。', title_ko = '물감투성이 예술가! 📸', body_ko = '자기 몸과 벽을 칠했나요? 화내는 대신 이 재미있는 낙서의 순간을 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 영원한 추억으로 올리세요.', title_nl = 'Kunstenaar onder de verf! 📸', body_nl = 'Heeft hij zichzelf en de muur beschilderd? Word niet boos, maar versier dit grappige krabbelmoment met vrolijke stickers in Babyfotoshoot en zet het als blijvende herinnering in het album.', title_pl = 'Artysta cały w farbie! 📸', body_pl = 'Pomalował siebie i ścianę? Zamiast się złościć, ozdób tę zabawną chwilę bazgrania wesołymi naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu na wieczną pamiątkę.', title_pt = 'Artista coberto de tinta! 📸', body_pt = 'Pintou-se a si próprio e à parede? Em vez de se enervar, decore este momento divertido de rabiscos com os autocolantes alegres da Sessão Fotográfica do Bebé e carregue-o no álbum como recordação.', title_sv = 'Konstnär full av färg! 📸', body_sv = 'Har barnet målat både sig själv och väggen? I stället för att bli irriterad, dekorera det roliga klotterögonblicket med glada klistermärken i Babyfotografering och ladda upp det i albumet som ett minne för alltid.', title_vi = 'Nghệ sĩ lấm lem màu vẽ! 📸', body_vi = 'Bé tô màu lên cả người và tường? Thay vì bực mình, hãy trang trí khoảnh khắc vẽ nguệch ngoạc vui nhộn này bằng sticker trong Chụp ảnh cho bé và lưu vào album làm kỷ niệm mãi mãi.', title_zh = '满身颜料的小艺术家！📸', body_zh = '把自己和墙都涂花了？与其生气，不如用宝宝写真里欢乐的贴纸装饰这个有趣的涂鸦时刻，上传到相册作为永远的纪念。' WHERE id = '61d69ed1-ecb9-44fd-ac6a-cb922359921f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
