UPDATE public.mommy_day_notifications SET title_es = '¡El café de la mañana no basta! ☕', body_es = 'Empezar el día con café en ayunas agota tu energía enseguida. Elige en Recetas saludables para mujeres un bizcocho de avena lleno de energía que se prepara en 5 minutos.', title_fr = 'Le café du matin ne suffit pas ! ☕', body_fr = 'Commencer la journée avec un café à jeun épuise vite votre énergie. Choisissez plutôt un muffin à l''avoine plein d''énergie, prêt en 5 minutes, dans les Recettes saines pour femmes.', title_hi = 'सुबह की कॉफ़ी काफ़ी नहीं! ☕', body_hi = 'खाली पेट कॉफ़ी से दिन शुरू करने से आपकी ऊर्जा जल्दी खत्म हो जाएगी। महिलाओं के लिए सेहतमंद रेसिपी से 5 मिनट में बनने वाला ऊर्जा से भरा ओट्स मफ़िन चुनिए।', title_id = 'Kopi pagi saja tidak cukup! ☕', body_id = 'Memulai hari dengan kopi saat perut kosong akan cepat menguras energi Anda. Pilih muffin oat penuh energi yang siap dalam 5 menit dari Resep Sehat untuk wanita.', title_ja = '朝のコーヒーだけでは足りない！☕', body_ja = '空腹のままコーヒーで一日を始めると、エネルギーがすぐに切れてしまいます。「女性のためのヘルシーレシピ」から、5分でできる元気いっぱいのオートミールマフィンを選びましょう。', title_ko = '아침 커피로는 부족해요! ☕', body_ko = '빈속에 커피로 하루를 시작하면 기운이 금방 바닥나요. 여성을 위한 건강한 레시피에서 5분이면 만드는 든든한 오트밀 머핀을 골라 보세요.', title_nl = 'Ochtendkoffie is niet genoeg! ☕', body_nl = 'De dag beginnen met koffie op een lege maag put je energie snel uit. Kies uit Gezonde recepten voor vrouwen een energierijke havermuffin, klaar in 5 minuten.', title_pl = 'Poranna kawa to za mało! ☕', body_pl = 'Kawa na pusty żołądek szybko wyczerpie twoją energię. Wybierz ze Zdrowych przepisów dla kobiet energetyczną babeczkę owsianą gotową w 5 minut.', title_pt = 'O café da manhã não chega! ☕', body_pt = 'Começar o dia com café em jejum vai esgotar depressa a sua energia. Escolha nas Receitas Saudáveis para Mulheres um queque de aveia cheio de energia, pronto em 5 minutos.', title_sv = 'Morgonkaffe räcker inte! ☕', body_sv = 'Att börja dagen med kaffe på fastande mage tömmer snabbt din energi. Välj en energirik havremuffins som är klar på 5 minuter från Hälsosamma recept för kvinnor.', title_vi = 'Cà phê sáng thôi chưa đủ! ☕', body_vi = 'Bắt đầu ngày mới bằng cà phê lúc bụng đói sẽ khiến mẹ nhanh cạn năng lượng. Hãy chọn món bánh muffin yến mạch giàu năng lượng làm trong 5 phút từ Công thức lành mạnh cho phụ nữ.', title_zh = '早上的咖啡不够！☕', body_zh = '空腹喝咖啡开始一天，会让精力很快耗尽。从女性健康食谱里选一款5分钟就能做好、充满能量的燕麦玛芬吧。' WHERE id = '49af58d4-c188-43d7-a0b2-43f4cd255337' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Bien hecho! 👏', body_es = '¿Hoy la casa se ha quedado desordenada? ¡No le des importancia! Los momentos de risas con tu peque valen mucho más. Felicítate sin falta en el Diario de ánimo.', title_fr = 'Bravo à vous ! 👏', body_fr = 'La maison est restée en désordre aujourd''hui ? Ne vous en souciez pas ! Les fous rires partagés avec votre enfant valent bien plus. Félicitez-vous absolument dans le Journal d''humeur.', title_hi = 'शाबाश आपको! 👏', body_hi = 'आज घर बिखरा रह गया? बिल्कुल परवाह मत कीजिए! बच्चे के साथ बिताए हँसी भरे पल ज़्यादा कीमती हैं। मूड डायरी में खुद की तारीफ़ ज़रूर कीजिए।', title_id = 'Hebat sekali Anda! 👏', body_id = 'Rumah berantakan hari ini? Tidak usah dipikirkan! Momen penuh tawa bersama anak Anda jauh lebih berharga. Jangan lupa memuji diri sendiri di Buku Harian Suasana Hati.', title_ja = 'よくがんばっています！👏', body_ja = '今日は家が散らかったまま？まったく気にしないで！お子さんと笑い合った時間のほうがずっと大切です。「気分日記」でぜひ自分を褒めてあげましょう。', title_ko = '정말 잘하고 있어요! 👏', body_ko = '오늘 집이 어질러졌나요? 전혀 신경 쓰지 마세요! 아이와 함께 웃은 순간이 훨씬 소중해요. 기분 일기에 스스로를 꼭 칭찬해 주세요.', title_nl = 'Goed gedaan! 👏', body_nl = 'Bleef het huis vandaag een rommeltje? Trek het je niet aan! De momenten vol gelach met je kindje zijn veel waardevoller. Geef jezelf zeker een compliment in je Stemmingsdagboek.', title_pl = 'Brawo dla ciebie! 👏', body_pl = 'Dziś w domu został bałagan? Zupełnie się tym nie przejmuj! Chwile pełne śmiechu z dzieckiem są cenniejsze. Koniecznie pochwal się w Dzienniku nastroju.', title_pt = 'Parabéns para si! 👏', body_pt = 'Hoje a casa ficou desarrumada? Não ligue nenhuma! Os momentos cheios de gargalhadas com o seu filho valem muito mais. Elogie-se sem falta no Diário de Humor.', title_sv = 'Bra jobbat! 👏', body_sv = 'Blev det stökigt hemma i dag? Strunta i det! Stunderna fulla av skratt med barnet är värda mer. Glöm inte att berömma dig själv i Humördagboken.', title_vi = 'Mẹ giỏi lắm! 👏', body_vi = 'Hôm nay nhà cửa bừa bộn? Đừng bận tâm! Những khoảnh khắc đầy tiếng cười bên bé quý giá hơn nhiều. Nhất định hãy tự khen mình trong Nhật ký tâm trạng nhé.', title_zh = '给你点赞！👏', body_zh = '今天家里乱糟糟的？完全不用在意！和孩子一起度过的欢笑时光更珍贵。一定要在心情日记里夸夸自己。' WHERE id = '869af623-de96-421f-808b-d64172a8f765' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Separemos los colores! 🔴🔵', body_es = 'Los juguetes rojos a un lado y los azules al otro. Lee en el Blog juegos caseros que mejoran la atención y la lógica de los niños de 19,5 meses y ponlos en práctica.', title_fr = 'Trions les couleurs ! 🔴🔵', body_fr = 'Les jouets rouges d''un côté, les bleus de l''autre. Lisez dans la rubrique Blogs des jeux à faire à la maison qui stimulent l''attention et la logique à 19,5 mois, et essayez-les.', title_hi = 'रंग अलग करें! 🔴🔵', body_hi = 'लाल खिलौने एक तरफ़, नीले दूसरी तरफ़। ब्लॉग सेक्शन में 19.5 महीने के बच्चों के लिए ध्यान और तर्क बढ़ाने वाले घरेलू खेल पढ़िए और आज़माइए।', title_id = 'Ayo pisahkan warna! 🔴🔵', body_id = 'Mainan merah di satu sisi, yang biru di sisi lain. Baca dan praktikkan permainan rumahan yang melatih fokus dan logika untuk anak usia 19,5 bulan di bagian Blog.', title_ja = '色を分けよう！🔴🔵', body_ja = '赤いおもちゃはこっち、青いおもちゃはあっち。1歳7か月半の子の集中力と論理的思考を育てるおうち遊びを、ブログで読んで試してみましょう。', title_ko = '색깔을 나눠 볼까요! 🔴🔵', body_ko = '빨간 장난감은 이쪽, 파란 장난감은 저쪽. 블로그에서 19.5개월 아이의 집중력과 논리력을 키우는 집 놀이를 읽고 해 보세요.', title_nl = 'Kleuren sorteren! 🔴🔵', body_nl = 'Rode speeltjes aan de ene kant, blauwe aan de andere. Lees in Blogs over spelletjes voor thuis die de aandacht en logica van kinderen van 19,5 maanden versterken, en probeer ze uit.', title_pl = 'Rozdzielamy kolory! 🔴🔵', body_pl = 'Czerwone zabawki na jedną stronę, niebieskie na drugą. Przeczytaj w sekcji Blog o domowych zabawach rozwijających uwagę i logikę dla dzieci w wieku 19,5 miesiąca i wypróbuj je.', title_pt = 'Vamos separar as cores! 🔴🔵', body_pt = 'Brinquedos vermelhos para um lado, azuis para o outro. Leia nos Blogues e experimente jogos caseiros que estimulam a atenção e a lógica em crianças de 19,5 meses.', title_sv = 'Vi sorterar färger! 🔴🔵', body_sv = 'Röda leksaker på ena sidan, blå på den andra. Läs i Bloggar om lekar hemma som stärker koncentration och logik hos barn på 19,5 månader och prova dem.', title_vi = 'Cùng phân loại màu sắc! 🔴🔵', body_vi = 'Đồ chơi màu đỏ một bên, màu xanh một bên. Hãy đọc trong mục Blog và thử các trò chơi tại nhà giúp tăng khả năng tập trung và tư duy logic cho trẻ 19,5 tháng tuổi.', title_zh = '来分颜色吧！🔴🔵', body_zh = '红色玩具放一边，蓝色的放另一边。去博客板块读读适合19.5个月宝宝、能提升专注力和逻辑的居家游戏，一起玩起来。' WHERE id = '348430a9-4730-49e1-90ac-91076b5c5d7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Líquidos por la noche 🚰', body_es = 'Si el pañal de la mañana pesa mucho, quizá haya que ajustar el agua que bebe por la tarde. Anótalo en el Seguimiento de pañales y revisa las estadísticas del día.', title_fr = 'Les boissons du soir 🚰', body_fr = 'Si la couche du matin est très lourde, il faut peut-être ajuster ce qu''il boit le soir. Notez-le dans le Suivi des couches et consultez les statistiques du jour.', title_hi = 'रात में तरल 🚰', body_hi = 'अगर सुबह का डायपर बहुत भारी है, तो शाम को पानी पीना कम-ज़्यादा करने की ज़रूरत हो सकती है। डायपर ट्रैकर में दर्ज कीजिए और रोज़ के आँकड़े देखिए।', title_id = 'Asupan cairan malam 🚰', body_id = 'Jika popok paginya sangat berat, minum airnya di sore hari mungkin perlu diatur. Catat di Pelacak Popok dan tinjau statistik hariannya.', title_ja = '夜の水分補給 🚰', body_ja = '朝のおむつがとても重いなら、夕方の水分のとり方を調整する必要があるかもしれません。「おむつトラッカー」に記録して、毎日の統計を見直しましょう。', title_ko = '밤 수분 섭취 🚰', body_ko = '아침 기저귀가 아주 무겁다면 저녁 물 섭취를 조절해야 할 수 있어요. 기저귀 기록에 남기고 하루 통계를 살펴보세요.', title_nl = 'Drinken in de nacht 🚰', body_nl = 'Is de ochtendluier erg zwaar? Dan moet je misschien het drinken in de avond aanpassen. Noteer het in de Luiertracker en bekijk de dagstatistieken.', title_pl = 'Picie przed nocą 🚰', body_pl = 'Jeśli poranna pieluszka jest bardzo ciężka, może trzeba ograniczyć picie wieczorem. Zapisz to w narzędziu do śledzenia pieluszek i przejrzyj dzienne statystyki.', title_pt = 'Líquidos à noite 🚰', body_pt = 'Se a fralda da manhã está muito pesada, pode ser preciso ajustar a água que bebe à noite. Registe-o no Registo de Fraldas e reveja as estatísticas diárias.', title_sv = 'Vätska på kvällen 🚰', body_sv = 'Är morgonblöjan väldigt tung kan vattenintaget på kvällen behöva justeras. Anteckna i Blöjkollen och gå igenom den dagliga statistiken.', title_vi = 'Uống nước buổi tối 🚰', body_vi = 'Nếu tã buổi sáng quá nặng, có thể cần điều chỉnh lượng nước bé uống buổi tối. Hãy ghi lại trong Theo dõi tã và xem thống kê hằng ngày.', title_zh = '夜间饮水 🚰', body_zh = '早上的尿布很沉的话，可能需要调整晚上的饮水。记在尿布记录里，看看每天的统计。' WHERE id = 'a3aeb0cd-d49a-4a1a-a82c-e3dc837e022c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Picas algo de pie a mediodía? Prepara en Recetas saludables para mujeres una tostada de aguacate que te sacie y te dé energía al momento.', body_fr = 'Vous grignotez debout à midi ? Préparez avec les Recettes saines pour femmes un toast à l''avocat qui vous rassasie et vous donne de l''énergie tout de suite.', body_hi = 'दोपहर में खड़े-खड़े कुछ भी खा लेती हैं? महिलाओं के लिए सेहतमंद रेसिपी से पेट भरा रखने वाला और तुरंत ऊर्जा देने वाला एवोकाडो टोस्ट बनाइए।', body_id = 'Siang-siang makan camilan sambil berdiri? Buat roti panggang alpukat dari Resep Sehat untuk wanita yang membuat Anda kenyang dan langsung berenergi.', body_ja = 'お昼、立ったままちょこっとつまんでいませんか？「女性のためのヘルシーレシピ」から、腹持ちがよく、すぐに元気が出るアボカドトーストをつくりましょう。', body_ko = '점심을 서서 대충 때우나요? 여성을 위한 건강한 레시피에서 든든하고 바로 힘이 나는 아보카도 토스트를 만들어 보세요.', body_nl = 'Eet je ''s middags staand iets tussendoor? Maak uit Gezonde recepten voor vrouwen een avocadotoast die je verzadigt en meteen energie geeft.', body_pl = 'Jesz w biegu coś na szybko w południe? Przygotuj ze Zdrowych przepisów dla kobiet tost z awokado, który cię nasyci i od razu doda energii.', body_pt = 'Ao meio-dia come qualquer coisa de pé? Prepare nas Receitas Saudáveis para Mulheres uma tosta de abacate que sacia e dá energia na hora.', body_sv = 'Småäter du stående mitt på dagen? Gör en avokadotoast som mättar och ger energi direkt från Hälsosamma recept för kvinnor.', body_vi = 'Buổi trưa mẹ chỉ ăn vội vài miếng? Hãy làm món bánh mì nướng bơ giúp no lâu và tiếp năng lượng ngay từ Công thức lành mạnh cho phụ nữ.', body_zh = '中午站着随便吃两口？从女性健康食谱里做一份顶饱又能马上补充能量的牛油果吐司吧。' WHERE id = '8ae66558-ee37-4cd1-9102-46bab1a97b21' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El espectáculo sin fin de la mesa 🥣', body_es = 'Juega con la comida, la tira al suelo, pero no come. Pon el temporizador de tomas y analiza con precisión la evolución de su apetito con el gráfico de la app.', title_fr = 'Le show sans fin à table 🥣', body_fr = 'Il joue avec la nourriture, la jette par terre mais ne mange pas. Lancez le minuteur des repas et analysez précisément son appétit grâce au graphique de l''appli.', title_hi = 'मेज़ पर कभी न खत्म होने वाला शो 🥣', body_hi = 'खाने से खेलता है, नीचे फेंकता है, पर खाता नहीं। फ़ीडिंग टाइमर चालू कीजिए और ऐप के चार्ट से भूख के रुझान को सटीक समझिए।', title_id = 'Pertunjukan tanpa akhir di meja makan 🥣', body_id = 'Ia bermain dengan makanan, melemparnya ke lantai, tapi tidak makan. Nyalakan Timer Makan dan analisis perkembangan nafsu makannya secara akurat lewat grafik di aplikasi.', title_ja = '食卓のエンドレスショー 🥣', body_ja = '食べ物で遊んで床に投げるけれど、食べない。食事タイマーをオンにして、アプリのグラフで食欲の変化をしっかり分析しましょう。', title_ko = '식탁 위 끝없는 공연 🥣', body_ko = '음식으로 장난치고 바닥에 던지면서 먹지는 않나요? 수유 타이머를 켜고 앱의 그래프로 식욕의 변화를 정확히 살펴보세요.', title_nl = 'De eindeloze show aan tafel 🥣', body_nl = 'Speelt hij met eten en gooit hij het op de grond, maar eet hij niet? Zet de Voedingstimer aan en analyseer zijn eetlust precies met de grafiek in de app.', title_pl = 'Niekończący się show przy stole 🥣', body_pl = 'Bawi się jedzeniem, rzuca je na podłogę, ale nie je. Włącz timer karmienia i dokładnie przeanalizuj apetyt dzięki wykresowi w aplikacji.', title_pt = 'O espetáculo sem fim à mesa 🥣', body_pt = 'Brinca com a comida, atira-a ao chão, mas não come. Ligue o temporizador de alimentação e analise com precisão a evolução do apetite no gráfico da app.', title_sv = 'Showen vid bordet som aldrig tar slut 🥣', body_sv = 'Barnet leker med maten och kastar den på golvet, men äter inte. Starta matningstimern och analysera aptitens utveckling noga med grafen i appen.', title_vi = 'Màn trình diễn bất tận trên bàn ăn 🥣', body_vi = 'Bé nghịch thức ăn, ném xuống sàn nhưng không ăn. Hãy bật Hẹn giờ cho bú và phân tích chính xác khẩu vị của bé qua biểu đồ trong ứng dụng.', title_zh = '餐桌上停不下来的表演 🥣', body_zh = '玩食物、扔到地上，就是不吃。打开喂养计时器，用应用里的图表准确分析食欲的变化。' WHERE id = '53a89401-1ea0-43b5-9469-65a0d422f72c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🌟', body_es = 'Cada nueva habilidad que aprende es fruto de tu esfuerzo. ¡Abre el Diario de ánimo y escribe hoy una nota para aplaudirte de pie!', title_fr = 'L''héroïne du jour, c''est vous 🌟', body_fr = 'Chaque nouvelle compétence qu''il apprend, c''est grâce à vous. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note qui mérite une ovation debout !', title_hi = 'आज की हीरो आप हैं 🌟', body_hi = 'हर दिन वह जो नई चीज़ सीखता है, वह आपकी मेहनत है। मूड डायरी खोलिए और आज खुद को शाबाशी देने वाली एक बात लिखिए!', title_id = 'Pahlawan hari ini adalah Anda 🌟', body_id = 'Setiap keterampilan baru yang ia pelajari adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati dan tulis catatan yang membuat Anda bertepuk tangan untuk diri sendiri hari ini!', title_ja = '今日のヒーローはあなたです 🌟', body_ja = '毎日新しくできるようになることは、あなたのがんばりのおかげです。「気分日記」を開いて、今日の自分にスタンディングオベーションを送るメモを書きましょう！', title_ko = '오늘의 주인공은 엄마예요 🌟', body_ko = '아이가 매일 배우는 새로운 능력은 엄마의 노력 덕분이에요. 기분 일기를 열고 오늘의 나에게 기립 박수를 보낼 기록을 남겨 보세요!', title_nl = 'Jij bent de held van vandaag 🌟', body_nl = 'Elke nieuwe vaardigheid die hij leert, is dankzij jou. Open je Stemmingsdagboek en schrijf vandaag een notitie waarmee je jezelf een staande ovatie geeft!', title_pl = 'Dzisiejszą bohaterką jesteś ty 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, to twoja zasługa. Otwórz Dziennik nastroju i napisz dziś notatkę, za którą nagrodzisz się owacją na stojąco!', title_pt = 'A heroína do dia é a mãe 🌟', body_pt = 'Cada nova competência que ele aprende é fruto do seu esforço. Abra o Diário de Humor e escreva hoje uma nota que a faça aplaudir-se de pé!', title_sv = 'Dagens hjälte är du 🌟', body_sv = 'Varje ny färdighet barnet lär sig är tack vare ditt arbete. Öppna Humördagboken och skriv en anteckning i dag som ger dig själv stående ovationer!', title_vi = 'Mẹ là người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng để tự vỗ tay cho mình hôm nay!', title_zh = '今天的英雄是你 🌟', body_zh = '宝宝每天学会的新本领都有你的功劳。打开心情日记，写下一句为自己热烈鼓掌的话吧！' WHERE id = '31a9cc16-de41-4012-b357-b74232182120' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía en 5 minutos ⚡', body_es = 'No corras a las tareas de casa por la mañana. Prepara en Recetas saludables una avena con frutos rojos cargada de antioxidantes y renueva tu cuerpo.', title_fr = '5 minutes d''énergie ⚡', body_fr = 'Ne vous ruez pas sur les tâches ménagères le matin. Préparez des flocons d''avoine aux baies, pleins d''antioxydants, avec les Recettes saines et ressourcez votre corps.', title_hi = '5 मिनट की ऊर्जा ⚡', body_hi = 'सुबह घर के कामों की ओर मत भागिए। सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर बेरी वाले ओट्स बनाइए और अपने शरीर को तरोताज़ा कीजिए।', title_id = 'Energi 5 menit ⚡', body_id = 'Jangan buru-buru mengerjakan pekerjaan rumah di pagi hari. Buat oat beri kaya antioksidan dari Resep Sehat dan segarkan kembali tubuh Anda.', title_ja = '5分でエネルギー ⚡', body_ja = '朝から家事に走らないで。「ヘルシーレシピ」から抗酸化物質たっぷりのベリーのオートミールをつくって、体をリフレッシュさせましょう。', title_ko = '5분 에너지 ⚡', body_ko = '아침부터 집안일로 달려가지 마세요. 건강한 레시피에서 항산화 성분 가득한 베리 오트밀을 만들어 몸에 활력을 채우세요.', title_nl = 'Energie in 5 minuten ⚡', body_nl = 'Ren ''s ochtends niet meteen naar het huishouden. Maak uit Gezonde recepten havermout met bessen vol antioxidanten en geef je lichaam nieuwe energie.', title_pl = 'Energia w 5 minut ⚡', body_pl = 'Nie rzucaj się rano w wir obowiązków. Przygotuj ze Zdrowych przepisów owsiankę z owocami jagodowymi pełną antyoksydantów i odnów organizm.', title_pt = 'Energia em 5 minutos ⚡', body_pt = 'De manhã, não corra para as tarefas da casa. Prepare com as Receitas Saudáveis papas de aveia com frutos vermelhos, cheias de antioxidantes, e renove o seu corpo.', title_sv = 'Energi på 5 minuter ⚡', body_sv = 'Rusa inte till hushållssysslorna på morgonen. Gör havregrynsgröt med bär full av antioxidanter från Hälsosamma recept och ge kroppen ny kraft.', title_vi = 'Năng lượng trong 5 phút ⚡', body_vi = 'Buổi sáng đừng vội lao vào việc nhà. Hãy làm món yến mạch quả mọng giàu chất chống oxy hóa từ Công thức lành mạnh để cơ thể được tái tạo.', title_zh = '5分钟能量补给 ⚡', body_zh = '早上别急着做家务。从健康食谱里做一份富含抗氧化物的莓果燕麦，让身体焕然一新。' WHERE id = '3f5ef83a-d114-41da-8dd2-6bd3c11c45e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No te da la cuchara? Pon el temporizador de tomas y analiza cuánto dura esta prueba de independencia. A la comida derramada, solo sonríele.', body_fr = 'Il refuse de vous laisser la cuillère ? Lancez le minuteur des repas et analysez combien de temps dure ce test d''autonomie. Et devant la nourriture renversée, souriez simplement.', body_hi = 'चम्मच आपको नहीं देता? फ़ीडिंग टाइमर चालू कीजिए और देखिए कि आज़ादी की यह कोशिश कितना समय लेती है। बिखरे खाने पर बस मुस्कुरा दीजिए।', body_id = 'Tidak mau memberikan sendoknya? Nyalakan Timer Makan dan lihat berapa lama ujian kemandirian ini berlangsung. Untuk makanan yang berceceran, cukup tersenyum saja.', body_ja = 'スプーンを渡してくれない？食事タイマーをオンにして、この自立の挑戦にどれくらい時間がかかるか分析しましょう。こぼれた食べ物には、ただほほえんで。', body_ko = '숟가락을 넘겨주지 않나요? 수유 타이머를 켜고 이 자립 도전이 얼마나 걸리는지 살펴보세요. 흘린 음식에는 그냥 웃어 주세요.', body_nl = 'Geeft hij de lepel niet aan je? Zet de Voedingstimer aan en kijk hoe lang deze zelfstandigheidstest duurt. Om het gemorste eten kun je gewoon glimlachen.', body_pl = 'Nie oddaje ci łyżki? Włącz timer karmienia i sprawdź, ile trwa ta próba samodzielności. Do rozsypanego jedzenia po prostu się uśmiechnij.', body_pt = 'Não lhe dá a colher? Ligue o temporizador de alimentação e analise quanto tempo demora este teste de independência. À comida entornada, responda só com um sorriso.', body_sv = 'Vill barnet inte ge dig skeden? Starta matningstimern och analysera hur lång tid självständighetsförsöket tar. Le bara åt maten som spills.', body_vi = 'Bé không đưa thìa cho mẹ? Hãy bật Hẹn giờ cho bú để xem thử thách tự lập này mất bao lâu. Thức ăn vương vãi thì cứ mỉm cười thôi.', body_zh = '不肯把勺子给你？打开喂养计时器，分析这场自主挑战花了多长时间。撒了一地的饭，笑一笑就好。' WHERE id = '622216cc-100d-4e85-95dc-7d70e41c5761' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La pelea de vestirse! 👗', body_es = '¿Vestirse por la mañana es una gran crisis? Ofrécele dos camisetas distintas y dale libertad para elegir.', title_fr = 'La bataille de l''habillage ! 👗', body_fr = 'S''habiller le matin est une vraie crise ? Proposez-lui deux t-shirts différents et laissez-lui la liberté de choisir.', title_hi = 'कपड़े पहनने की लड़ाई! 👗', body_hi = 'सुबह कपड़े पहनना बड़ा झगड़ा बन जाता है? उसे दो अलग कमीज़ें दिखाकर चुनने की आज़ादी दीजिए।', title_id = 'Drama berpakaian! 👗', body_id = 'Berpakaian di pagi hari jadi drama besar? Tawarkan dua kaus yang berbeda dan beri ia kebebasan memilih.', title_ja = '着替えのバトル！👗', body_ja = '朝の着替えが大きなかんしゃくの時間に？2枚のちがうシャツを見せて、選ぶ自由をあげましょう。', title_ko = '옷 입기 전쟁! 👗', body_ko = '아침 옷 입기가 큰 전쟁인가요? 서로 다른 셔츠 두 벌을 보여 주고 고를 자유를 주세요.', title_nl = 'Strijd om het aankleden! 👗', body_nl = 'Is aankleden in de ochtend een grote strijd? Leg twee verschillende shirtjes klaar en geef hem de vrijheid om te kiezen.', title_pl = 'Wojna o ubieranie! 👗', body_pl = 'Poranne ubieranie to wielki kryzys? Daj mu swobodę wyboru, proponując dwie różne koszulki.', title_pt = 'A guerra da roupa! 👗', body_pt = 'Vestir-se de manhã é uma grande crise? Mostre-lhe duas camisolas diferentes e dê-lhe liberdade de escolha.', title_sv = 'Kampen om kläderna! 👗', body_sv = 'Är påklädningen på morgonen ett stort utbrott? Erbjud barnet två olika tröjor och ge friheten att välja.', title_vi = 'Cuộc chiến mặc đồ! 👗', body_vi = 'Mặc quần áo buổi sáng là một cuộc khủng hoảng lớn? Hãy đưa ra hai chiếc áo khác nhau để bé được tự do lựa chọn.', title_zh = '穿衣大战！👗', body_zh = '早上穿衣服就是一场大崩溃？给宝宝两件不同的衣服，让宝宝自由选择。' WHERE id = '057bf87f-0bbd-415e-a240-9562e85f263d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tiene estreñimiento? 💩', body_es = 'Al cambiar el pañal de la mañana, fíjate en las cacas. Si hay estreñimiento, anótalo en la app y añade sin falta alimentos ricos en fibra a su menú con el Seguimiento de tomas.', title_fr = 'Un souci de constipation ? 💩', body_fr = 'En changeant la couche du matin, observez les selles. En cas de constipation, notez-le dans l''appli et ajoutez absolument des aliments riches en fibres à son menu avec le Suivi des repas.', title_hi = 'कब्ज़ की परेशानी? 💩', body_hi = 'सुबह डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ हो तो ऐप में दर्ज कीजिए और फ़ीडिंग ट्रैकर की मदद से मेन्यू में फ़ाइबर वाली चीज़ें ज़रूर जोड़िए।', title_id = 'Ada masalah sembelit? 💩', body_id = 'Perhatikan kotorannya saat mengganti popok pagi. Jika ia sembelit, catat di aplikasi dan pastikan menambahkan makanan berserat ke menunya dengan alat Pemantau Nutrisi.', title_ja = '便秘ぎみ？💩', body_ja = '朝のおむつ替えのときに、うんちの様子をチェックしましょう。便秘ならアプリに記録して、「栄養管理ツール」で食物繊維の多い食べ物を必ずメニューに加えましょう。', title_ko = '변비가 있나요? 💩', body_ko = '아침에 기저귀를 갈 때 배변을 살펴보세요. 변비가 있다면 앱에 기록하고 수유 기록 도구로 식단에 섬유질 음식을 꼭 추가하세요.', title_nl = 'Last van verstopping? 💩', body_nl = 'Let bij het verschonen van de ochtendluier op de ontlasting. Bij verstopping: noteer het in de app en voeg met de Voedingstracker zeker vezelrijk eten toe aan zijn menu.', title_pl = 'Problem z zaparciami? 💩', body_pl = 'Przy porannej zmianie pieluszki obserwuj kupkę. Jeśli są zaparcia, zapisz to w aplikacji i w narzędziu do śledzenia karmienia koniecznie dodaj do menu produkty bogate w błonnik.', title_pt = 'Prisão de ventre? 💩', body_pt = 'Ao mudar a fralda da manhã, observe as fezes. Se houver prisão de ventre, registe-o na app e, com o Registo de Alimentação, acrescente sem falta à ementa alimentos ricos em fibra.', title_sv = 'Förstoppning? 💩', body_sv = 'Håll koll på avföringen när du byter morgonblöjan. Vid förstoppning, anteckna det i appen och lägg till fiberrik mat i menyn med Matningskoll.', title_vi = 'Bé bị táo bón? 💩', body_vi = 'Hãy để ý phân khi thay tã buổi sáng. Nếu bé bị táo bón, hãy ghi vào ứng dụng và nhất định thêm thực phẩm giàu chất xơ vào thực đơn bằng Theo dõi cữ bú.', title_zh = '便秘了？💩', body_zh = '早上换尿布时留意一下排便。如果便秘，记到应用里，并用喂养记录工具在菜单里一定加上富含纤维的食物。' WHERE id = 'f52268ca-f991-4824-88f4-73fcbe961356' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Señales del orinal? 🚽', body_es = '¿El pañal de la mañana está totalmente seco? Puede ser el momento ideal para empezar a dejar el pañal. Anótalo en el Seguimiento de pañales y echa un vistazo a los artículos de preparación de la app.', title_fr = 'Des signes pour le pot ? 🚽', body_fr = 'La couche du matin est toute sèche ? C''est peut-être le moment idéal pour commencer l''apprentissage. Notez-le dans le Suivi des couches et lisez les articles de préparation dans l''appli.', title_hi = 'पॉटी के संकेत? 🚽', body_hi = 'सुबह का डायपर बिल्कुल सूखा है? ट्रेनिंग शुरू करने का यह सही समय हो सकता है। डायपर ट्रैकर में दर्ज कीजिए और ऐप में तैयारी वाले लेख देखिए।', title_id = 'Tanda siap pispot? 🚽', body_id = 'Popok paginya kering sama sekali? Ini bisa jadi waktu ideal untuk mulai latihan. Catat di Pelacak Popok dan lihat artikel persiapan di aplikasi.', title_ja = 'トイレのサイン？🚽', body_ja = '朝のおむつがすっかり乾いていますか？トイレトレーニングを始めるのにぴったりの時期かもしれません。「おむつトラッカー」に記録して、アプリの準備に関する記事をのぞいてみましょう。', title_ko = '배변 훈련 신호? 🚽', body_ko = '아침 기저귀가 보송보송한가요? 배변 훈련을 시작하기 좋은 때일 수 있어요. 기저귀 기록에 남기고 앱의 준비 관련 글을 살펴보세요.', title_nl = 'Signalen voor het potje? 🚽', body_nl = 'Is de ochtendluier kurkdroog? Dit kan het ideale moment zijn om met zindelijkheidstraining te beginnen. Noteer het in de Luiertracker en lees de artikelen over voorbereiding in de app.', title_pl = 'Sygnały gotowości do nocnika? 🚽', body_pl = 'Poranna pieluszka zupełnie sucha? To może być idealny moment na naukę. Zapisz to w narzędziu do śledzenia pieluszek i zajrzyj do artykułów o przygotowaniu w aplikacji.', title_pt = 'Sinais de bacio? 🚽', body_pt = 'A fralda da manhã está completamente seca? Pode ser a altura ideal para começar o treino. Registe-o no Registo de Fraldas e espreite os artigos de preparação na app.', title_sv = 'Signaler om pottan? 🚽', body_sv = 'Är morgonblöjan helt torr? Det kan vara perfekt tid att börja träna. Anteckna i Blöjkollen och titta på artiklarna om förberedelser i appen.', title_vi = 'Tín hiệu sẵn sàng ngồi bô? 🚽', body_vi = 'Tã buổi sáng khô cong? Có thể đây là thời điểm lý tưởng để bắt đầu tập. Hãy ghi lại trong Theo dõi tã và xem các bài viết về chuẩn bị trong ứng dụng.', title_zh = '便盆信号？🚽', body_zh = '早上的尿布干干的？可能是开始训练的理想时机。记在尿布记录里，再看看应用里关于准备工作的文章。' WHERE id = '8fc02957-0717-4600-94a0-03ec95b3ecc9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Protege tu energía de la mañana ⚡', body_es = '¡No empieces el día en ayunas! Cuídate eligiendo en Recetas saludables para mujeres un bizcocho de avena delicioso y saciante que se prepara en 5 minutos.', title_fr = 'Préservez votre énergie du matin ⚡', body_fr = 'Ne commencez pas la journée le ventre vide ! Prenez soin de vous avec un délicieux muffin à l''avoine rassasiant, prêt en 5 minutes, des Recettes saines pour femmes.', title_hi = 'सुबह की ऊर्जा बचाइए ⚡', body_hi = 'दिन की शुरुआत खाली पेट मत कीजिए! महिलाओं के लिए सेहतमंद रेसिपी से 5 मिनट में बनने वाला, पेट भरा रखने वाला स्वादिष्ट ओट्स मफ़िन चुनिए और अपना ख्याल रखिए।', title_id = 'Jaga energi pagi Anda ⚡', body_id = 'Jangan memulai hari dengan perut kosong! Rawat diri Anda dengan memilih muffin oat yang lezat dan mengenyangkan, siap dalam 5 menit dari Resep Sehat untuk wanita.', title_ja = '朝のエネルギーを守ろう ⚡', body_ja = '空腹のまま一日を始めないで！「女性のためのヘルシーレシピ」から、5分でできて腹持ちのいいおいしいオートミールマフィンを選んで、自分をいたわりましょう。', title_ko = '아침 에너지를 지켜요 ⚡', body_ko = '빈속으로 하루를 시작하지 마세요! 여성을 위한 건강한 레시피에서 5분이면 만드는 든든하고 맛있는 오트밀 머핀을 골라 나를 챙기세요.', title_nl = 'Bescherm je ochtendenergie ⚡', body_nl = 'Begin de dag niet op een lege maag! Zorg voor jezelf met een vullend, lekker havermuffin uit Gezonde recepten voor vrouwen, klaar in 5 minuten.', title_pl = 'Zadbaj o poranną energię ⚡', body_pl = 'Nie zaczynaj dnia na czczo! Zadbaj o siebie i wybierz ze Zdrowych przepisów dla kobiet sycącą, pyszną babeczkę owsianą gotową w 5 minut.', title_pt = 'Proteja a sua energia da manhã ⚡', body_pt = 'Não comece o dia em jejum! Cuide de si escolhendo nas Receitas Saudáveis para Mulheres um queque de aveia saboroso, que sacia e fica pronto em 5 minutos.', title_sv = 'Skydda din morgonenergi ⚡', body_sv = 'Börja inte dagen på fastande mage! Välj en god och mättande havremuffins som är klar på 5 minuter från Hälsosamma recept för kvinnor och ta hand om dig själv.', title_vi = 'Giữ năng lượng buổi sáng ⚡', body_vi = 'Đừng bắt đầu ngày mới với cái bụng đói! Hãy chăm sóc bản thân bằng một chiếc bánh muffin yến mạch thơm ngon, no lâu, làm trong 5 phút từ Công thức lành mạnh cho phụ nữ.', title_zh = '守护早上的精力 ⚡', body_zh = '别空着肚子开始一天！从女性健康食谱里选一款5分钟就能做好、顶饱又美味的燕麦玛芬，好好照顾自己。' WHERE id = '1ecb40c2-379b-4b51-a326-4d93bf0ac050' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas a tus amigas 👯‍♀️', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás centros con grupos de juego, socializa con otras madres y comparte experiencias.', title_fr = 'Vous aussi, vous avez besoin d''amies 👯‍♀️', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez des centres avec groupes de jeu dans les Lieux adaptés aux mamans, rencontrez d''autres mamans et partagez vos expériences.', title_hi = 'आपको भी दोस्तों की ज़रूरत है 👯‍♀️', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में प्ले ग्रुप वाले सेंटर ढूँढिए, दूसरी माँओं से मिलिए और अनुभव बाँटिए।', title_id = 'Anda juga butuh teman 👯‍♀️', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan tempat dengan kelompok bermain di Tempat Ramah Ibu, bersosialisasi dengan ibu lain, dan berbagi pengalaman.', title_ja = 'あなたにも友だちが必要です 👯‍♀️', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」で遊びのグループがある施設を見つけて、ほかのママと交流し、経験を分かち合いましょう。', title_ko = '엄마에게도 친구가 필요해요 👯‍♀️', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 놀이 모임이 있는 센터를 찾아 다른 엄마들과 어울리고 경험을 나눠 보세요.', title_nl = 'Jij hebt ook vriendinnen nodig 👯‍♀️', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken centra met speelgroepjes, maak contact met andere moeders en deel ervaringen.', title_pl = 'Ty też potrzebujesz przyjaciółek 👯‍♀️', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom centra z grupami zabaw, poznaj inne mamy i wymieniajcie się doświadczeniami.', title_pt = 'Também precisa de amigas 👯‍♀️', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães centros com grupos de brincadeira, conviva com outras mães e partilhe experiências.', title_sv = 'Du behöver också vänner 👯‍♀️', body_sv = 'Trött på att bara prata med barnet? Hitta center med lekgrupper i Mammavänliga platser, umgås med andra mammor och dela erfarenheter.', title_vi = 'Mẹ cũng cần bạn bè 👯‍♀️', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm các trung tâm có nhóm chơi trong Địa điểm thân thiện với mẹ để giao lưu và chia sẻ kinh nghiệm với các mẹ khác.', title_zh = '你也需要朋友 👯‍♀️', body_zh = '只和孩子说话说累了？在妈妈友好场所里找到有游戏小组的中心，和其他妈妈交流、分享经验吧。' WHERE id = '69fe7fde-913c-4ff4-8fe2-fcbdad210e16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La siesta se acorta? ⏱️', body_es = '¿Anoche le costó mucho dormirse? Pon el temporizador de sueño y sigue el gráfico. Quizá sea el momento de acortar la siesta 15-20 minutos.', title_fr = 'Siestes plus courtes ? ⏱️', body_fr = 'Il a mis longtemps à s''endormir hier soir ? Lancez le minuteur de sommeil et suivez le graphique. C''est peut-être le bon moment pour raccourcir la sieste de 15 à 20 minutes.', title_hi = 'दिन की नींद छोटी हो रही है? ⏱️', body_hi = 'रात को सोने में बहुत समय लगा? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 15-20 मिनट कम करने का सही समय आ गया है।', title_id = 'Tidur siang makin singkat? ⏱️', body_id = 'Semalam butuh waktu lama untuk tertidur? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin inilah saatnya memangkas tidur siang 15-20 menit.', title_ja = 'お昼寝が短くなってきた？⏱️', body_ja = '夜、寝つくまで時間がかかりましたか？睡眠タイマーをオンにして、グラフを見守りましょう。お昼寝を15-20分短くするちょうどいいタイミングかもしれません。', title_ko = '낮잠이 짧아지나요? ⏱️', body_ko = '밤에 잠드는 데 오래 걸렸나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 15~20분 줄일 때가 되었을지도 몰라요.', title_nl = 'Worden de dutjes korter? ⏱️', body_nl = 'Duurde het inslapen vannacht lang? Zet de Slaaptimer aan en volg de grafiek. Misschien is het precies tijd om het middagdutje met 15-20 minuten in te korten.', title_pl = 'Drzemki coraz krótsze? ⏱️', body_pl = 'Wieczorne zasypianie trwało bardzo długo? Włącz timer snu i śledź wykres. Może to dobry moment, by skrócić drzemkę o 15-20 minut.', title_pt = 'A sesta está a encurtar? ⏱️', body_pt = 'À noite demorou muito a adormecer? Ligue o temporizador de sono e acompanhe o gráfico. Talvez seja a altura certa de encurtar a sesta 15-20 minutos.', title_sv = 'Kortare dagsömn? ⏱️', body_sv = 'Tog det lång tid att somna i kväll? Starta sömntimern och följ grafen. Kanske är det precis rätt tid att korta dagsömnen med 15-20 minuter.', title_vi = 'Giấc ngủ ngày ngắn lại? ⏱️', body_vi = 'Tối qua bé mất nhiều thời gian để ngủ? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đây đúng là lúc giảm giấc ngủ ngày 15-20 phút.', title_zh = '午睡变短了？⏱️', body_zh = '晚上入睡花了很久？打开睡眠计时器，看看图表。也许正是把白天小睡减少15-20分钟的时候了。' WHERE id = 'f7991ada-b885-400f-9f72-4df6d1f9477e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Os habéis quedado en casa porque el tiempo está raro?', body_es = 'Deja que Tiempo y ropa te diga al momento la velocidad del viento y la ropa adecuada, y sal al parque con confianza.', title_fr = 'Vous restez à la maison parce que le temps est bizarre ?', body_fr = 'Laissez l''outil Météo et tenue vous indiquer tout de suite la vitesse du vent et la bonne tenue, puis filez au parc en toute confiance.', title_hi = 'मौसम अजीब है, इसलिए घर पर रुकी हैं?', body_hi = 'मौसम और कपड़े टूल आपको हवा की रफ़्तार और सही कपड़ों का मेल तुरंत बताएगा, बेझिझक पार्क जाइए।', title_id = 'Tetap di rumah karena cuacanya aneh?', body_id = 'Biarkan alat Cuaca dan Pakaian langsung memberi tahu kecepatan angin dan kombinasi pakaian yang tepat, lalu pergilah ke taman dengan percaya diri.', title_ja = 'なんだか変な天気だから家にいますか？', body_ja = '「天気と服装」なら、風の強さとぴったりのコーデをすぐに教えてくれます。思いきって公園へ出かけましょう。', title_ko = '날씨가 애매해서 집에만 있었나요?', body_ko = '날씨와 옷차림 도구로 풍속과 알맞은 옷차림을 바로 확인하고 자신 있게 공원으로 나가 보세요.', title_nl = 'Thuisgebleven omdat het weer raar is?', body_nl = 'Laat Weer en kleding je meteen de windsnelheid en de juiste outfit vertellen, en ga gerust naar het park.', title_pl = 'Zostałyście w domu, bo pogoda jest dziwna?', body_pl = 'Niech narzędzie Pogoda i ubiór od razu powie ci, jaki wieje wiatr i jaki zestaw ubrań wybrać. Śmiało ruszajcie do parku.', title_pt = 'Ficou em casa porque o tempo está estranho?', body_pt = 'Deixe que o Tempo e Roupa lhe diga na hora a velocidade do vento e a combinação certa, e vá ao parque com confiança.', title_sv = 'Har ni stannat inne för att vädret är konstigt?', body_sv = 'Låt Väder och kläder direkt berätta vindhastigheten och rätt klädsel, och gå modigt till parken.', title_vi = 'Thời tiết thất thường nên cả nhà ở trong nhà?', body_vi = 'Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió và cách phối đồ phù hợp, rồi tự tin ra công viên nhé.', title_zh = '天气怪怪的，就待在家里了？', body_zh = '让天气与穿衣工具立刻告诉你风速和合适的穿搭，勇敢地去公园吧。' WHERE id = '41e1758f-79bb-43e3-8304-d4d74fa983b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de paciencia en la mesa 🥣', body_es = '¿Juega con la comida y lo mancha todo? Pon el temporizador de tomas, analiza la evolución de su apetito con el gráfico y controla con precisión cuánto dura la comida.', title_fr = 'Patience à table 🥣', body_fr = 'Il joue avec la nourriture et en met partout ? Lancez le minuteur des repas, analysez son appétit sur le graphique et suivez précisément la durée du repas.', title_hi = 'मेज़ पर सब्र की परीक्षा 🥣', body_hi = 'खाने से खेलता है और सब जगह गंदा कर देता है? फ़ीडिंग टाइमर चालू कीजिए, चार्ट से भूख का रुझान देखिए और सटीक जानिए कि खाने में कितना समय लगता है।', title_id = 'Ujian kesabaran di meja makan 🥣', body_id = 'Bermain dengan makanan dan membuat semuanya berantakan? Nyalakan Timer Makan, analisis nafsu makannya lewat grafik, dan pantau dengan tepat berapa lama waktu makannya.', title_ja = '食卓で試される忍耐 🥣', body_ja = '食べ物で遊んで、あちこち汚していますか？食事タイマーをオンにして、グラフで食欲の変化を分析し、食事にどれくらい時間がかかっているかしっかり記録しましょう。', title_ko = '식탁에서의 인내심 시험 🥣', body_ko = '음식으로 장난치며 온 사방을 어지르나요? 수유 타이머를 켜고 그래프로 식욕의 변화를 분석해 식사 시간이 얼마나 걸리는지 정확히 확인하세요.', title_nl = 'Geduldproef aan tafel 🥣', body_nl = 'Speelt hij met eten en maakt hij alles vies? Zet de Voedingstimer aan, analyseer zijn eetlust met de grafiek en volg precies hoe lang het duurt.', title_pl = 'Test cierpliwości przy stole 🥣', body_pl = 'Bawi się jedzeniem i wszystko brudzi? Włącz timer karmienia, przeanalizuj apetyt na wykresie i dokładnie śledź, ile trwa posiłek.', title_pt = 'Teste de paciência à mesa 🥣', body_pt = 'Brinca com a comida e suja tudo? Ligue o temporizador de alimentação, analise no gráfico a evolução do apetite e acompanhe com precisão quanto tempo demora.', title_sv = 'Tålamodsprov vid bordet 🥣', body_sv = 'Leker barnet med maten och kladdar ner allt? Starta matningstimern, analysera aptitens utveckling med grafen och följ noga hur lång tid måltiden tar.', title_vi = 'Thử thách kiên nhẫn trên bàn ăn 🥣', body_vi = 'Bé nghịch thức ăn và bôi bẩn khắp nơi? Hãy bật Hẹn giờ cho bú, phân tích khẩu vị qua biểu đồ và theo dõi chính xác bữa ăn kéo dài bao lâu.', title_zh = '餐桌上的耐心考验 🥣', body_zh = '玩食物，弄得到处都是？打开喂养计时器，用图表分析食欲变化，准确跟踪这一餐花了多长时间。' WHERE id = 'd816b4dc-5206-4a90-9e61-8c02ef8f5c68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hoy todo ha sido difícil? 💆‍♀️', body_es = '¿Has oído gritos y llantos sin parar? Respira hondo, deja de juzgarte: ¡lo haces genial!', title_fr = 'Tout a été difficile aujourd''hui ? 💆‍♀️', body_fr = 'Des cris et des pleurs sans arrêt ? Respirez profondément, arrêtez de vous juger : vous êtes formidable !', title_hi = 'आज सब कुछ मुश्किल था? 💆‍♀️', body_hi = 'लगातार चीखें और रोना सुनती रहीं? गहरी साँस लीजिए, खुद को परखना बंद कीजिए, आप कमाल की हैं!', title_id = 'Hari ini semuanya terasa berat? 💆‍♀️', body_id = 'Mendengar teriakan dan tangisan tanpa henti? Tarik napas dalam-dalam, berhentilah menghakimi diri sendiri, Anda luar biasa!', title_ja = '今日は何もかも大変だった？💆‍♀️', body_ja = '叫び声や泣き声をずっと聞いていましたか？深呼吸をして、自分を責めるのはやめましょう。あなたは最高です！', title_ko = '오늘 모든 게 힘들었나요? 💆‍♀️', body_ko = '하루 종일 비명과 울음소리를 들었나요? 깊게 숨을 쉬고 자신을 탓하지 마세요. 엄마는 정말 잘하고 있어요!', title_nl = 'Was vandaag alles zwaar? 💆‍♀️', body_nl = 'Hoorde je de hele dag geschreeuw en gehuil? Adem diep in en stop met jezelf te veroordelen, je doet het geweldig!', title_pl = 'Dziś wszystko było trudne? 💆‍♀️', body_pl = 'Słyszałaś dziś bez przerwy krzyki i płacz? Weź głęboki oddech i przestań się osądzać, jesteś wspaniała!', title_pt = 'Hoje foi tudo difícil? 💆‍♀️', body_pt = 'Ouviu gritos e choro sem parar? Respire fundo e deixe de se julgar: é fantástica!', title_sv = 'Var allt svårt i dag? 💆‍♀️', body_sv = 'Har du hört skrik och gråt utan uppehåll? Andas djupt, sluta döma dig själv, du är fantastisk!', title_vi = 'Hôm nay mọi thứ đều khó khăn? 💆‍♀️', body_vi = 'Cả ngày chỉ nghe la hét và khóc lóc? Hãy hít thở sâu, đừng phán xét bản thân nữa, mẹ tuyệt vời lắm!', title_zh = '今天一切都很难？💆‍♀️', body_zh = '听了一整天的尖叫和哭闹？深呼吸，别再评判自己，你很棒！' WHERE id = '842a46f0-f832-4901-8e08-572103acff74' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Compartir es difícil 🧸', body_es = '¿Se porta brusco con su hermano o con el niño del parque? Compartir aún es un concepto abstracto para él. No le castigues: demuéstrale que entiendes sus emociones.', title_fr = 'Partager, c''est difficile 🧸', body_fr = 'Il est brusque avec son frère ou un enfant au parc ? Partager reste pour lui une notion abstraite. Ne le punissez pas, montrez-lui que vous comprenez ses émotions.', title_hi = 'बाँटना मुश्किल है 🧸', body_hi = 'भाई-बहन या पार्क के बच्चे के साथ सख्ती से पेश आता है? बाँटना अभी उसके लिए एक अमूर्त बात है। सज़ा मत दीजिए, दिखाइए कि आप उसकी भावनाएँ समझती हैं।', title_id = 'Berbagi itu sulit 🧸', body_id = 'Bersikap kasar pada saudaranya atau anak lain di taman? Berbagi masih konsep yang abstrak baginya. Jangan menghukum, tunjukkan bahwa Anda memahami perasaannya.', title_ja = '分け合うのは難しい 🧸', body_ja = 'きょうだいや公園の子に乱暴にふるまいますか？分け合うことは、お子さんにとってまだ抽象的な考えです。罰を与えず、気持ちをわかっていることを伝えましょう。', title_ko = '나누기는 어려워요 🧸', body_ko = '동생이나 공원의 아이에게 거칠게 행동하나요? 나누기는 아직 아이에게 추상적인 개념이에요. 벌주지 말고 마음을 이해한다는 걸 보여 주세요.', title_nl = 'Delen is moeilijk 🧸', body_nl = 'Doet hij ruw tegen zijn broertje of zusje of een kind in het park? Delen is voor hem nog een abstract begrip. Straf hem niet, maar laat zien dat je zijn gevoelens begrijpt.', title_pl = 'Dzielenie się jest trudne 🧸', body_pl = 'Jest szorstki wobec rodzeństwa albo dziecka w parku? Dzielenie się to dla niego wciąż abstrakcyjne pojęcie. Nie karz go, pokaż, że rozumiesz jego emocje.', title_pt = 'Partilhar é difícil 🧸', body_pt = 'É bruto com o irmão ou com a criança do parque? Partilhar ainda é para ele uma ideia abstrata. Não o castigue, mostre-lhe que compreende o que sente.', title_sv = 'Att dela är svårt 🧸', body_sv = 'Är barnet hårt mot sitt syskon eller ett barn i parken? Att dela är fortfarande ett abstrakt begrepp för barnet. Straffa inte, visa att du förstår känslorna.', title_vi = 'Chia sẻ thật khó 🧸', body_vi = 'Bé đối xử gay gắt với anh chị em hay bạn ở công viên? Chia sẻ vẫn còn là khái niệm trừu tượng với bé. Đừng phạt, hãy cho bé thấy mẹ hiểu cảm xúc của bé.', title_zh = '分享很难 🧸', body_zh = '对哥哥姐姐、弟弟妹妹或公园里的小朋友很凶？分享对宝宝来说还是个抽象的概念。别惩罚，让宝宝知道你理解宝宝的情绪。' WHERE id = '37bdad79-de07-4752-a75a-2761546b1523' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Solo abrázale 🫂', body_es = 'No hace falta ninguna herramienta, libro ni cuento. Esta noche simplemente estréchale contra tu pecho, respira su olor y susúrrale tu amor en la oscuridad.', title_fr = 'Juste un câlin 🫂', body_fr = 'Pas besoin d''outil, de livre ou de conte. Ce soir, serrez-le simplement contre vous, respirez son odeur et murmurez-lui votre amour dans le noir.', title_hi = 'बस गले लगाइए 🫂', body_hi = 'किसी टूल, किताब या कहानी की ज़रूरत नहीं। आज शाम बस उसे सीने से लगाइए, उसकी खुशबू महसूस कीजिए और अँधेरे में उसके कान में अपना प्यार फुसफुसाइए।', title_id = 'Cukup peluk ia 🫂', body_id = 'Tidak perlu alat, buku, atau dongeng apa pun. Malam ini, cukup dekap ia di dada, hirup aromanya, dan bisikkan rasa sayang Anda dalam gelap.', title_ja = 'ただ抱きしめて 🫂', body_ja = '道具も、絵本も、お話もいりません。今夜はただ胸にぎゅっと抱きしめて、お子さんの香りを吸いこみ、暗やみの中で愛をささやきましょう。', title_ko = '그냥 안아 주세요 🫂', body_ko = '도구도, 책도, 동화도 필요 없어요. 오늘 밤에는 그냥 아이를 가슴에 꼭 안고, 아이 냄새를 깊이 들이마시며 어둠 속에서 사랑을 속삭여 주세요.', title_nl = 'Gewoon knuffelen 🫂', body_nl = 'Je hebt geen tool, boek of sprookje nodig. Druk hem vanavond gewoon tegen je borst, ruik zijn geur en fluister in het donker hoeveel je van hem houdt.', title_pl = 'Po prostu przytul 🫂', body_pl = 'Nie potrzeba żadnych narzędzi, książek ani bajek. Dziś wieczorem po prostu przytul go do serca, poczuj jego zapach i wyszeptaj mu w ciemności, jak go kochasz.', title_pt = 'Basta um abraço 🫂', body_pt = 'Não precisa de nenhuma ferramenta, livro ou história. Esta noite, aperte-o simplesmente contra o peito, respire o cheiro dele e sussurre-lhe o seu amor no escuro.', title_sv = 'Bara krama 🫂', body_sv = 'Inga verktyg, böcker eller sagor behövs. Håll bara barnet tätt intill dig i kväll, andas in doften och viska din kärlek i mörkret.', title_vi = 'Chỉ cần ôm thôi 🫂', body_vi = 'Không cần công cụ, sách hay truyện. Tối nay chỉ cần ôm bé vào lòng, hít hà mùi hương của bé và thì thầm lời yêu thương trong bóng tối.', title_zh = '只要一个拥抱 🫂', body_zh = '不需要任何工具、书或故事。今晚只要把宝宝紧紧抱在怀里，闻闻宝宝的味道，在黑暗中轻声说出你的爱。' WHERE id = '561010fd-17de-4698-b582-1c91bc73389a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Para el pelo y la piel 🥑', body_es = 'Cuida tu cuerpo, cansado de la rutina diaria. Prepara en Recetas saludables para mujeres una ensalada de la juventud con aguacate y nueces, cargada de antioxidantes.', title_fr = 'Pour les cheveux et la peau 🥑', body_fr = 'Prenez soin de votre corps fatigué par la routine. Préparez une salade jeunesse avocat-noix, riche en antioxydants, avec les Recettes saines pour femmes.', title_hi = 'बालों और त्वचा के लिए 🥑', body_hi = 'रोज़ की भागदौड़ से थके अपने शरीर का ख्याल रखिए। महिलाओं के लिए सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर एवोकाडो और अखरोट वाला ''यूथ सलाद'' बनाइए।', title_id = 'Untuk rambut dan kulit 🥑', body_id = 'Rawat tubuh Anda yang lelah oleh rutinitas harian. Buat salad awet muda alpukat dan kenari yang kaya antioksidan dari Resep Sehat untuk wanita.', title_ja = '髪と肌のために 🥑', body_ja = '毎日の家事や育児で疲れた体をいたわりましょう。「女性のためのヘルシーレシピ」から、抗酸化物質たっぷりのアボカドとくるみの「若返りサラダ」をつくってみて。', title_ko = '머릿결과 피부를 위해 🥑', body_ko = '매일의 일상에 지친 몸을 돌봐 주세요. 여성을 위한 건강한 레시피에서 항산화 성분이 가득한 아보카도 호두 샐러드를 만들어 보세요.', title_nl = 'Voor haar en huid 🥑', body_nl = 'Zorg voor je lichaam dat moe is van de dagelijkse sleur. Maak uit Gezonde recepten voor vrouwen de jeugdsalade met avocado en walnoten, boordevol antioxidanten.', title_pl = 'Dla włosów i skóry 🥑', body_pl = 'Zadbaj o ciało zmęczone codzienną rutyną. Przygotuj ze Zdrowych przepisów dla kobiet sałatkę młodości z awokado i orzechami włoskimi, prawdziwą skarbnicę antyoksydantów.', title_pt = 'Para o cabelo e a pele 🥑', body_pt = 'Cuide do seu corpo, cansado da rotina diária. Prepare nas Receitas Saudáveis para Mulheres uma salada da juventude com abacate e nozes, uma reserva de antioxidantes.', title_sv = 'För hår och hud 🥑', body_sv = 'Ta hand om din kropp som är trött efter vardagsrutinen. Gör en föryngrande sallad med avokado och valnötter, full av antioxidanter, från Hälsosamma recept för kvinnor.', title_vi = 'Cho tóc và làn da khỏe đẹp 🥑', body_vi = 'Hãy chăm sóc cơ thể đang mệt mỏi vì nhịp sống hằng ngày. Làm món salad thanh xuân với bơ và óc chó, kho chống oxy hóa trong Công thức lành mạnh cho phụ nữ nhé.', title_zh = '为了秀发和肌肤 🥑', body_zh = '照顾一下被日常琐事累坏的身体吧。从女性健康食谱里做一份富含抗氧化物的牛油果核桃青春沙拉。' WHERE id = '5bcd3758-fc71-4b21-a0a4-008b6ec5eec1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«Agua», «Mamá, ven» 🗣️', body_es = '¿Ya intenta juntar dos palabras para formar frases cortas? ¡Un salto enorme en el desarrollo del lenguaje! Refuerza siempre sus intentos y anímale a hablar.', title_fr = '« De l''eau, maman viens » 🗣️', body_fr = 'Il essaie déjà d''assembler deux mots pour faire de petites phrases ? Quel bond dans son langage ! Encouragez toujours ses essais et faites-le parler.', title_hi = '''पानी दो'', ''माँ आओ'' 🗣️', body_hi = 'अब दो शब्द जोड़कर छोटे वाक्य बनाने की कोशिश करता है? भाषा के विकास में यह शानदार छलांग है! उसकी इन कोशिशों की हमेशा तारीफ़ कीजिए और उसे बोलने के लिए प्रेरित कीजिए।', title_id = 'Minta Air, Mama Sini 🗣️', body_id = 'Ia mulai menggabungkan dua kata menjadi kalimat kecil? Lompatan bahasa yang luar biasa! Terus tanggapi usahanya dan ajak ia bicara.', title_ja = '「お水ちょうだい」「ママきて」 🗣️', body_ja = 'もう2つの言葉をつなげて、小さな文をつくろうとしていますか？言葉の発達のすばらしい飛躍です！その挑戦をいつも受け止めて、たくさん話しかけてあげましょう。', title_ko = '''물 줘'', ''엄마 와'' 🗣️', body_ko = '벌써 두 단어를 이어 짧은 문장을 만들려고 하나요? 언어 발달의 멋진 도약이에요! 아이의 시도를 늘 인정해 주고 계속 말을 걸어 주세요.', title_nl = 'Water geven, mama kom 🗣️', body_nl = 'Probeert je kindje al twee woorden te combineren tot kleine zinnetjes? Een geweldige sprong in de taalontwikkeling! Bevestig zijn pogingen steeds en praat veel met hem.', title_pl = '„Daj pić”, „Mama, chodź” 🗣️', body_pl = 'Już próbuje łączyć dwa słowa w małe zdania? Wspaniały skok w rozwoju mowy! Stale chwal jego próby i zachęcaj do mówienia.', title_pt = 'Dá água, mamã, vem 🗣️', body_pt = 'Já tenta juntar duas palavras e formar pequenas frases? Um salto fantástico no desenvolvimento da linguagem! Confirme sempre estas tentativas e puxe-o para a conversa.', title_sv = 'Ge vatten, mamma kom 🗣️', body_sv = 'Försöker barnet redan sätta ihop två ord till små meningar? Ett fantastiskt språng i språkutvecklingen! Bekräfta alltid försöken och prata mycket tillsammans.', title_vi = '"Cho nước", "Mẹ ơi lại đây" 🗣️', body_vi = 'Bé đã thử ghép hai từ để nói câu ngắn? Một bước nhảy vọt tuyệt vời về ngôn ngữ! Hãy luôn khen ngợi những cố gắng này và trò chuyện nhiều với bé.', title_zh = '“给水水”“妈妈来” 🗣️', body_zh = '宝宝已经在尝试把两个词连成小句子了？语言发展的一大飞跃！要经常肯定宝宝的尝试，多和宝宝说话。' WHERE id = 'a832a387-bccf-4a1a-823c-3930e73e4c07' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía sin fin 🔋', body_es = '¿No se cansa de correr? Pon el temporizador de sueño y baja las luces de la habitación. Con el susurro del bosque de Ruido blanco, llévale poco a poco al modo sueño.', title_fr = 'Une énergie sans fin 🔋', body_fr = 'Jamais fatigué de courir ? Lancez le minuteur de sommeil et baissez les lumières. Avec le bruissement de la forêt des Bruits blancs, amenez-le doucement vers le sommeil.', title_hi = 'कभी न खत्म होने वाली ऊर्जा 🔋', body_hi = 'भागते-भागते थकता ही नहीं? स्लीप टाइमर चालू कीजिए और कमरे की रोशनी धीमी कीजिए। व्हाइट नॉइज़ में जंगल की सरसराहट से उसे धीरे-धीरे नींद के मूड में लाइए।', title_id = 'Energi tanpa habis 🔋', body_id = 'Tak pernah lelah berlari? Nyalakan Timer Tidur dan redupkan lampu kamar. Pelan-pelan arahkan ia ke mode tidur dengan suara gemerisik hutan dari Suara Putih.', title_ja = '尽きないエネルギー 🔋', body_ja = '走り回っても疲れ知らず？睡眠タイマーをオンにして、部屋の照明を落としましょう。「ホワイトノイズ」の森のざわめきで、ゆっくり眠りのモードへ導いてあげて。', title_ko = '끝없는 에너지 🔋', body_ko = '뛰어다녀도 지치지 않나요? 수면 타이머를 켜고 방의 불을 낮춰 주세요. 백색소음의 숲 바스락 소리로 천천히 잠들 준비를 도와주세요.', title_nl = 'Eindeloze energie 🔋', body_nl = 'Wordt hij nooit moe van het rennen? Zet de Slaaptimer aan en dim het licht. Breng hem met bosgeruis uit Witte ruis langzaam in de slaapstand.', title_pl = 'Niekończąca się energia 🔋', body_pl = 'Nie męczy się bieganiem? Włącz timer snu i przygaś światło w pokoju. Szumem lasu z Białego szumu powoli wprowadź go w tryb snu.', title_pt = 'Energia sem fim 🔋', body_pt = 'Não se cansa de correr? Ligue o temporizador de sono e baixe as luzes do quarto. Com o sussurro da floresta do Ruído Branco, prepare-o aos poucos para dormir.', title_sv = 'Energi som aldrig tar slut 🔋', body_sv = 'Blir barnet aldrig trött på att springa? Starta sömntimern och dämpa ljuset i rummet. Låt skogens sus från Vitt brus sakta ställa in barnet på sömnläge.', title_vi = 'Năng lượng không bao giờ cạn 🔋', body_vi = 'Bé chạy mãi không biết mệt? Hãy bật Bộ hẹn giờ ngủ và giảm ánh sáng trong phòng. Dùng tiếng rì rào của rừng trong Tiếng ồn trắng để dần đưa bé vào giấc ngủ.', title_zh = '用不完的精力 🔋', body_zh = '跑个不停都不累？打开睡眠计时器，把房间灯光调暗。用白噪音里的森林沙沙声，慢慢把宝宝带入睡眠模式。' WHERE id = 'd1f9f7f1-6831-4583-9dbd-fab805703b8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal la digestión? 🚽', body_es = '¿Tiene estreñimiento? Anótalo al cambiar el pañal de la mañana y, con el Seguimiento de tomas, añade sin falta alimentos ricos en fibra (pera, avena) a su menú.', title_fr = 'Comment va la digestion ? 🚽', body_fr = 'Il est constipé ? Notez-le en changeant la couche du matin et ajoutez à son menu des aliments riches en fibres (poire, avoine) avec le Suivi des repas.', title_hi = 'पाचन कैसा चल रहा है? 🚽', body_hi = 'कब्ज़ की परेशानी है? सुबह डायपर बदलते समय इसे दर्ज कीजिए और फ़ीडिंग ट्रैकर की मदद से उसके मेन्यू में फ़ाइबर वाली चीज़ें (नाशपाती, ओट्स) ज़रूर जोड़िए।', title_id = 'Bagaimana pencernaannya? 🚽', body_id = 'Ia sedang sembelit? Catat saat mengganti popok pagi, lalu pastikan menambahkan makanan berserat (pir, oat) ke menunya dengan alat Pemantau Nutrisi.', title_ja = '消化の調子はどう？🚽', body_ja = '便秘で困っていますか？朝のおむつ替えのときに記録して、「栄養管理ツール」で食物繊維の多い食べ物（洋なし、オートミール）を必ずメニューに加えましょう。', title_ko = '소화는 잘 되고 있나요? 🚽', body_ko = '변비가 있나요? 아침에 기저귀를 갈 때 기록하고, 수유 기록 도구로 식단에 섬유질 음식(배, 귀리)을 꼭 추가해 주세요.', title_nl = 'Hoe gaat de spijsvertering? 🚽', body_nl = 'Last van verstopping? Noteer het bij de ochtendluier en voeg met de Voedingstracker zeker vezelrijk eten (peer, havermout) toe aan zijn menu.', title_pl = 'Jak trawienie? 🚽', body_pl = 'Zmaga się z zaparciami? Zanotuj to przy porannej zmianie pieluszki i w narzędziu do śledzenia karmienia koniecznie dodaj do menu produkty bogate w błonnik (gruszka, płatki owsiane).', title_pt = 'Como vai a digestão? 🚽', body_pt = 'Há prisão de ventre? Registe-o ao mudar a fralda da manhã e, com o Registo de Alimentação, acrescente sem falta à ementa alimentos ricos em fibra (pera, aveia).', title_sv = 'Hur går matsmältningen? 🚽', body_sv = 'Har barnet förstoppning? Anteckna det när du byter morgonblöjan och lägg till fiberrik mat (päron, havre) i menyn med Matningskoll.', title_vi = 'Tiêu hóa của bé thế nào? 🚽', body_vi = 'Bé bị táo bón? Hãy ghi lại khi thay tã buổi sáng và nhất định thêm thực phẩm giàu chất xơ (lê, yến mạch) vào thực đơn của bé bằng công cụ Theo dõi cữ bú.', title_zh = '消化还好吗？🚽', body_zh = '宝宝便秘了？早上换尿布时记下来，并用喂养记录工具在菜单里一定加上富含纤维的食物（梨、燕麦）。' WHERE id = '34104368-1e25-46df-8c68-910d16cd40b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo te sientes? 🧘‍♀️', body_es = '¿Hoy has dicho muchos «¡no!»? No te sientas culpable. Vuelca tu voz interior en el Diario de ánimo y recuerda lo entregada que eres como madre.', title_fr = 'Comment vous sentez-vous ? 🧘‍♀️', body_fr = 'Vous avez beaucoup dit « non » aujourd''hui ? Ne culpabilisez pas. Confiez votre voix intérieure au Journal d''humeur et rappelez-vous à quel point vous êtes une maman dévouée.', title_hi = 'आप कैसा महसूस कर रही हैं? 🧘‍♀️', body_hi = 'आज बहुत बार ''नहीं!'' कहा? खुद को दोष मत दीजिए। मूड डायरी में अपने मन की बात लिखिए और याद कीजिए कि एक माँ के रूप में आप कितनी त्याग करती हैं।', title_id = 'Bagaimana perasaan Anda? 🧘‍♀️', body_id = 'Hari ini Anda banyak berkata tidak? Jangan merasa bersalah. Curahkan suara hati Anda di Buku Harian Suasana Hati dan ingat betapa besar pengorbanan Anda sebagai ibu.', title_ja = '今の気分はいかがですか？🧘‍♀️', body_ja = '今日は「ダメ！」をたくさん言ってしまいましたか？罪悪感を持たないで。「気分日記」に心の声を書き出して、ママとしてどれほど献身的か思い出しましょう。', title_ko = '오늘 기분은 어때요? 🧘‍♀️', body_ko = '오늘 ''안 돼!''를 많이 했나요? 죄책감은 내려놓으세요. 기분 일기에 속마음을 털어놓고, 엄마로서 얼마나 헌신하고 있는지 떠올려 보세요.', title_nl = 'Hoe voel je je? 🧘‍♀️', body_nl = 'Heb je vandaag vaak nee gezegd? Voel je niet schuldig. Schrijf je innerlijke stem van je af in je Stemmingsdagboek en herinner jezelf eraan hoeveel je als moeder geeft.', title_pl = 'Jak się czujesz? 🧘‍♀️', body_pl = 'Dziś często mówiłaś „nie”? Nie miej wyrzutów sumienia. Wylej swój wewnętrzny głos w Dzienniku nastroju i przypomnij sobie, jak wiele poświęcasz jako mama.', title_pt = 'Como se sente? 🧘‍♀️', body_pt = 'Hoje disse muitas vezes "não!"? Não se sinta culpada. Deixe sair a sua voz interior no Diário de Humor e lembre-se de como é dedicada como mãe.', title_sv = 'Hur mår du? 🧘‍♀️', body_sv = 'Har du sagt ”nej!” många gånger i dag? Känn inget dåligt samvete. Skriv av dig i Humördagboken och påminn dig om hur uppoffrande du är som mamma.', title_vi = 'Mẹ cảm thấy thế nào? 🧘‍♀️', body_vi = 'Hôm nay mẹ đã nói "Không!" quá nhiều? Đừng tự trách. Hãy trút hết tiếng lòng vào Nhật ký tâm trạng và nhớ rằng mẹ đã hy sinh nhiều đến thế nào.', title_zh = '你感觉怎么样？🧘‍♀️', body_zh = '今天说了太多次“不行！”？别内疚。把内心的声音倒进心情日记，想想作为妈妈你付出了多少。' WHERE id = '79b083b6-1c72-4250-a120-ca8846206ce5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Artistas de la naturaleza 🍂', body_es = '¡Hojas, piedras y ramas son los mejores juguetes! Busca en Lugares para mamás un parque con mucho verde y salid a explorar al aire libre.', title_fr = 'Petits artistes de la nature 🍂', body_fr = 'Feuilles, cailloux et branches sont les meilleurs jouets ! Trouvez un parc bien vert dans les Lieux adaptés aux mamans et partez en vraie exploration en plein air.', title_hi = 'प्रकृति के नन्हे कलाकार 🍂', body_hi = 'पत्ते, पत्थर और टहनियाँ सबसे अच्छे खिलौने हैं! माँ के लिए अनुकूल जगहें में हरियाली से भरा पार्क ढूँढिए और खुली हवा में असली खोज पर निकलिए।', title_id = 'Seniman alam cilik 🍂', body_id = 'Daun, batu, dan ranting adalah mainan terbaik! Temukan taman yang hijau di Tempat Ramah Ibu dan ajak ia bertualang di alam terbuka.', title_ja = '自然のアーティスト 🍂', body_ja = '葉っぱや石、小枝は最高のおもちゃ！「ママにやさしいスポット」で緑の多い公園を見つけて、外で本格的な探検に出かけましょう。', title_ko = '자연 속 꼬마 예술가 🍂', body_ko = '나뭇잎, 돌멩이, 나뭇가지가 최고의 장난감이에요! 엄마 친화 장소에서 푸른 공원을 찾아 진짜 야외 탐험을 떠나 보세요.', title_nl = 'Kleine natuurkunstenaars 🍂', body_nl = 'Bladeren, steentjes en takjes zijn het beste speelgoed! Zoek in Mamavriendelijke plekken een groen park en ga samen echt op ontdekkingstocht buiten.', title_pl = 'Mali artyści natury 🍂', body_pl = 'Liście, kamienie i patyki to najlepsze zabawki! Znajdź w Miejscach przyjaznych mamom zielony park i wyruszcie na prawdziwą wyprawę badawczą na świeżym powietrzu.', title_pt = 'Artistas da natureza 🍂', body_pt = 'Folhas, pedras e ramos são os melhores brinquedos! Encontre nos Locais Amigos das Mães um parque bem verde e partam numa verdadeira exploração ao ar livre.', title_sv = 'Naturens konstnärer 🍂', body_sv = 'Löv, stenar och pinnar är de bästa leksakerna! Hitta en grön park i Mammavänliga platser och ge er ut på en riktig upptäcktsfärd utomhus.', title_vi = 'Những nghệ sĩ thiên nhiên nhí 🍂', body_vi = 'Lá, đá và cành cây là những món đồ chơi tuyệt nhất! Hãy tìm một công viên nhiều cây xanh trong Địa điểm thân thiện với mẹ và cùng bé khám phá ngoài trời.', title_zh = '大自然的小艺术家 🍂', body_zh = '树叶、石头和树枝就是最好的玩具！在妈妈友好场所里找一个绿树成荫的公园，去户外来一场真正的探险吧。' WHERE id = 'bfb35c45-0163-48f3-be24-eff4697cb9e8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabietas en el súper 🛒', body_es = '¿Se ha tirado al suelo porque no le compraste lo que quería? Que no cunda el pánico. Ignora las miradas y agáchate con calma a la altura de sus ojos.', title_fr = 'Crises au supermarché 🛒', body_fr = 'Il s''est jeté par terre parce que vous n''avez pas acheté ce qu''il voulait ? Pas de panique. Ignorez les regards et baissez-vous calmement à sa hauteur.', title_hi = 'बाज़ार में नखरे 🛒', body_hi = 'दुकान में मनचाही चीज़ नहीं मिली तो ज़मीन पर लोट गया? घबराइए मत। आसपास के लोगों की नज़रों की परवाह किए बिना शांति से झुककर उसकी आँखों के स्तर पर आइए।', title_id = 'Tantrum di supermarket 🛒', body_id = 'Ia menjatuhkan diri ke lantai karena tidak dibelikan yang diinginkannya di toko? Jangan panik. Abaikan tatapan orang lain dan dengan tenang turunkan badan sejajar matanya.', title_ja = 'お店でのかんしゃく 🛒', body_ja = 'お店でほしいものを買ってもらえず、床にひっくり返りましたか？慌てないで。周りの視線は気にせず、落ち着いて目線の高さまでしゃがみましょう。', title_ko = '마트에서 떼쓰기 🛒', body_ko = '가게에서 원하는 걸 안 사 줬다고 바닥에 드러누웠나요? 당황하지 마세요. 주변 시선은 신경 쓰지 말고 조용히 아이 눈높이로 몸을 낮춰 주세요.', title_nl = 'Driftbuien in de supermarkt 🛒', body_nl = 'Gooide hij zich op de grond omdat je in de winkel niet kocht wat hij wilde? Geen paniek. Negeer de blikken van anderen en zak rustig door je knieën tot zijn ooghoogte.', title_pl = 'Histerie w sklepie 🛒', body_pl = 'Rzucił się na podłogę, bo nie kupiłaś mu tego, co chciał? Bez paniki. Nie zwracaj uwagi na spojrzenia innych i spokojnie zniż się do poziomu jego oczu.', title_pt = 'Birras no supermercado 🛒', body_pt = 'Atirou-se para o chão porque não lhe comprou o que queria na loja? Não entre em pânico. Ignore os olhares à volta e baixe-se com calma ao nível dos olhos dele.', title_sv = 'Utbrott i affären 🛒', body_sv = 'Kastade sig barnet på golvet för att hen inte fick det hen ville ha i affären? Få inte panik. Strunta i andras blickar och böj dig lugnt ner till barnets ögonhöjd.', title_vi = 'Ăn vạ ở siêu thị 🛒', body_vi = 'Bé nằm lăn ra sàn vì không được mua món mình muốn? Đừng hoảng. Mặc kệ ánh nhìn xung quanh, hãy bình tĩnh cúi xuống ngang tầm mắt bé.', title_zh = '超市里的崩溃 🛒', body_zh = '在商店没买到想要的东西就躺地上打滚？别慌。不用理会旁人的目光，平静地蹲下来和宝宝视线齐平。' WHERE id = '01861a89-1cc1-4443-8c58-c79d90402305' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta la carga emocional 📝', body_es = '¿Ha sido un día difícil? Desahógate escribiendo el estrés de hoy en el Diario de ánimo. Todas las madres pasan por esto, no estás sola.', title_fr = 'Déposez votre charge émotionnelle 📝', body_fr = 'Journée difficile ? Videz-vous la tête en écrivant le stress du jour dans le Journal d''humeur. Toutes les mamans passent par là, vous n''êtes pas seule.', title_hi = 'मन का बोझ उतारिए 📝', body_hi = 'मुश्किल दिन था? आज का तनाव मूड डायरी में लिखकर मन हल्का कीजिए। हर माँ इन रास्तों से गुज़रती है, आप अकेली नहीं हैं।', title_id = 'Lepaskan beban emosi 📝', body_id = 'Hari yang berat? Lepaskan beban dengan menuliskan stres hari ini di Buku Harian Suasana Hati. Semua ibu pernah melewatinya, Anda tidak sendirian.', title_ja = '心の荷物を下ろして 📝', body_ja = '大変な一日でしたか？「気分日記」に今日のストレスを書いて、気持ちを軽くしましょう。どのママも通る道です。あなたはひとりではありません。', title_ko = '마음의 짐을 내려놓아요 📝', body_ko = '힘든 하루였나요? 기분 일기에 오늘의 스트레스를 적으며 마음을 비워 보세요. 모든 엄마가 이 길을 지나가요. 혼자가 아니에요.', title_nl = 'Laat je emotionele last los 📝', body_nl = 'Was het een zware dag? Schrijf de stress van vandaag van je af in je Stemmingsdagboek. Alle moeders gaan hierdoor, je staat er niet alleen voor.', title_pl = 'Zrzuć emocjonalny ciężar 📝', body_pl = 'To był trudny dzień? Wypisz dzisiejszy stres w Dzienniku nastroju i ulżyj sobie. Każda mama przez to przechodzi, nie jesteś sama.', title_pt = 'Liberte a carga emocional 📝', body_pt = 'Foi um dia difícil? Desabafe escrevendo o stress de hoje no Diário de Humor. Todas as mães passam por isto, não está sozinha.', title_sv = 'Släpp den känslomässiga bördan 📝', body_sv = 'Har det varit en tuff dag? Skriv av dig dagens stress i Humördagboken. Alla mammor går igenom det här, du är inte ensam.', title_vi = 'Trút bỏ gánh nặng cảm xúc 📝', body_vi = 'Hôm nay vất vả quá? Hãy viết những căng thẳng hôm nay vào Nhật ký tâm trạng cho nhẹ lòng. Người mẹ nào cũng trải qua điều này, mẹ không đơn độc đâu.', title_zh = '卸下情绪的包袱 📝', body_zh = '今天很难熬？把今天的压力写进心情日记，把心里清空。每个妈妈都经历过这些，你并不孤单。' WHERE id = '32e724db-ca0f-4d6b-9d07-716443a9dcdd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Saltos con los dos pies 🦘', body_es = '¿Intenta saltar con los dos pies a la vez sin moverse del sitio? Queda graciosísimo, ¿verdad? Inmortaliza este momento con la Sesión de fotos del bebé.', title_fr = 'Sauter à pieds joints 🦘', body_fr = 'Il essaie de sauter sur place à pieds joints ? C''est trop drôle, non ? Immortalisez absolument ce moment avec la Séance photo bébé.', title_hi = 'दोनों पैरों से कूदना 🦘', body_hi = 'एक ही जगह खड़े होकर दोनों पैरों से एक साथ कूदने की कोशिश करता है? बहुत मज़ेदार लगता है, है ना? इस पल को बेबी फ़ोटोशूट से ज़रूर हमेशा के लिए सहेजिए।', title_id = 'Melompat dengan dua kaki 🦘', body_id = 'Ia mencoba melompat dengan dua kaki sekaligus di tempat? Lucu sekali, bukan? Abadikan momen ini dengan Sesi Foto Bayi.', title_ja = '両足ジャンプ 🦘', body_ja = 'その場で両足をそろえてジャンプしようとしていますか？とってもおもしろい姿ですよね？この瞬間をぜひ「ベビーフォトセッション」で残しましょう。', title_ko = '두 발로 깡충 🦘', body_ko = '제자리에서 두 발로 동시에 뛰어 보려고 하나요? 정말 귀엽죠? 이 순간을 아기 사진 촬영으로 꼭 남겨 두세요.', title_nl = 'Springen met twee voeten 🦘', body_nl = 'Probeert hij op de plek met beide voeten tegelijk te springen? Wat ziet dat er grappig uit, toch? Leg dit moment zeker vast met Babyfotoshoot.', title_pl = 'Skoki obunóż 🦘', body_pl = 'Próbuje podskakiwać w miejscu obiema nogami naraz? Wygląda to przezabawnie, prawda? Koniecznie uwiecznij tę chwilę w Sesji zdjęciowej dziecka.', title_pt = 'Saltar a pés juntos 🦘', body_pt = 'Tenta saltar no mesmo sítio com os dois pés ao mesmo tempo? É muito engraçado, não é? Eternize sem falta este momento com a Sessão Fotográfica do Bebé.', title_sv = 'Hopp med båda fötterna 🦘', body_sv = 'Försöker barnet hoppa med båda fötterna samtidigt på stället? Det ser så roligt ut, eller hur? Förevig ögonblicket med Babyfotografering.', title_vi = 'Bật nhảy bằng hai chân 🦘', body_vi = 'Bé đứng tại chỗ và cố nhảy bằng cả hai chân cùng lúc? Trông thật buồn cười phải không? Nhất định hãy lưu lại khoảnh khắc này bằng Chụp ảnh cho bé.', title_zh = '双脚跳 🦘', body_zh = '宝宝站在原地，想用双脚同时起跳？看起来超搞笑吧？一定要用宝宝写真把这一刻永远留下来。' WHERE id = 'a0570819-b575-49b5-bbf4-bc21cf5fc939' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere dormir? 🥱', body_es = '¿Se resiste a la siesta? Pide a Anacan AI información precisa sobre las ventanas de sueño a los 20 meses y un horario de rutina.', title_fr = 'Il refuse de dormir ? 🥱', body_fr = 'Il résiste à la sieste ? Demandez à Anacan AI des informations précises sur les fenêtres de sommeil à 20 mois et un planning adapté.', title_hi = 'सोने से इनकार? 🥱', body_hi = 'दिन में सोना नहीं चाहता और विरोध करता है? Anacan AI से 20 महीने के बच्चों की नींद की खिड़कियों के बारे में सटीक जानकारी और रूटीन चार्ट माँगिए।', title_id = 'Menolak tidur? 🥱', body_id = 'Ia menolak dan melawan saat waktu tidur siang? Minta informasi akurat tentang jendela tidur anak usia 20 bulan beserta jadwalnya dari Anacan AI.', title_ja = 'お昼寝いやいや？🥱', body_ja = 'お昼寝を嫌がって抵抗しますか？Anacan AIに、1歳8か月の子の活動時間（眠りのタイミング）と生活リズム表を聞いてみましょう。', title_ko = '낮잠 거부? 🥱', body_ko = '낮잠을 안 자려고 버티나요? Anacan AI에게 20개월 아이의 수면 간격에 대한 정확한 정보와 일과표를 물어보세요.', title_nl = 'Geen zin in slapen? 🥱', body_nl = 'Wil hij niet naar zijn middagdutje en verzet hij zich? Vraag Anacan AI om precieze info over slaapvensters en een dagschema voor kinderen van 20 maanden.', title_pl = 'Odmawia spania? 🥱', body_pl = 'Nie chce iść na drzemkę i się opiera? Poproś Anacan AI o dokładne informacje o oknach snu 20-miesięcznych dzieci i plan dnia.', title_pt = 'Recusa dormir? 🥱', body_pt = 'Não quer fazer a sesta e resiste? Peça ao Anacan AI informação precisa sobre as janelas de sono das crianças de 20 meses e um horário de rotina.', title_sv = 'Vägrar sova? 🥱', body_sv = 'Vill barnet inte sova middag och gör motstånd? Be Anacan AI om exakt information om vakenfönster för 20 månader gamla barn och ett förslag på dagsrytm.', title_vi = 'Không chịu ngủ? 🥱', body_vi = 'Bé không muốn ngủ ngày và cứ cưỡng lại? Hãy hỏi Anacan AI thông tin chính xác về khung giờ ngủ và lịch sinh hoạt cho trẻ 20 tháng tuổi.', title_zh = '不肯睡觉？🥱', body_zh = '不想睡午觉，一直抗拒？问问Anacan AI，了解20个月宝宝的清醒时间窗口和作息表。' WHERE id = '1eeadb7c-f8e9-45ae-bbde-edff2903cb9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma musical 🎶', body_es = 'La forma más fácil de calmar el llanto de última hora de la tarde es poner su melodía favorita, abrazarle y bailar despacito juntos.', title_fr = 'Sérénité en musique 🎶', body_fr = 'Le plus simple pour apaiser les pleurnicheries de fin de journée : mettez une mélodie qu''il aime, prenez-le dans vos bras et dansez doucement.', title_hi = 'संगीत भरा सुकून 🎶', body_hi = 'शाम को होने वाली चिड़चिड़ाहट को संभालने का सबसे आसान तरीका है उसकी पसंदीदा धुन लगाकर उसे गले लगाकर धीरे-धीरे नाचना।', title_id = 'Damai bersama musik 🎶', body_id = 'Cara termudah meredakan rewel di sore hari adalah memutar melodi favoritnya, memeluknya, lalu berdansa pelan bersamanya.', title_ja = '音楽でほっとひと息 🎶', body_ja = '夕方のぐずりをいちばん簡単に落ち着かせる方法は、好きな曲をかけて、ぎゅっと抱っこしながらゆっくり踊ることです。', title_ko = '음악과 함께 평온하게 🎶', body_ko = '저녁 무렵의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안은 채 천천히 춤추는 거예요.', title_nl = 'Muzikale rust 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsmelodie op, knuffel hem en dans samen langzaam.', title_pl = 'Muzyczny spokój 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną melodię, przytulić go i powoli razem zatańczyć.', title_pt = 'Tranquilidade com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma melodia de que ele goste, abraçá-lo e dançar devagarinho.', title_sv = 'Lugn med musik 🎶', body_sv = 'Det enklaste sättet att lösa gnälligheten framåt kvällen är att sätta på en favoritmelodi, krama barnet och dansa långsamt tillsammans.', title_vi = 'Bình yên cùng âm nhạc 🎶', body_vi = 'Cách dễ nhất để xoa dịu cơn quấy khóc lúc chiều tối là bật giai điệu bé yêu thích, ôm bé vào lòng và nhẹ nhàng nhảy cùng bé.', title_zh = '音乐中的安宁 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝喜欢的曲子，抱着宝宝慢慢跳舞。' WHERE id = '2edb626b-eafe-49c0-a743-e6dae9f9eddd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Haces de todo para que coma. ¿Y tú? Elige en Recetas saludables una comida rica en hierro que te dé fuerza, siéntate y come con calma.', body_fr = 'Vous faites tout pour qu''il mange bien. Et vous ? Choisissez dans les Recettes saines un déjeuner riche en fer qui vous donnera de l''énergie, et mangez assise, au calme.', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप? सेहतमंद रेसिपी से आपको ताकत देने वाला आयरन से भरपूर लंच चुनिए और आराम से बैठकर खाइए।', body_id = 'Anda melakukan segalanya agar ia kenyang. Lalu bagaimana dengan Anda? Pilih makan siang kaya zat besi dari Resep Sehat yang memberi Anda tenaga, lalu duduk dan makan dengan tenang.', body_ja = 'お子さんにたっぷり食べさせようとがんばっていますね。では、あなたは？「ヘルシーレシピ」から元気が出る鉄分たっぷりのランチを選んで、座ってゆっくり食べましょう。', body_ko = '아이를 배불리 먹이려고 뭐든 하죠. 그럼 엄마는요? 건강한 레시피에서 힘이 되는 철분 가득한 점심을 골라 편히 앉아 드세요.', body_nl = 'Je doet alles om hem te laten eten. En jij? Kies uit Gezonde recepten een ijzerrijke lunch die je kracht geeft, ga rustig zitten en eet.', body_pl = 'Robisz wszystko, żeby był najedzony. A ty? Wybierz w Zdrowych przepisach bogaty w żelazo obiad, który doda ci sił, usiądź spokojnie i zjedz.', body_pt = 'Faz tudo para que ele coma bem. E a mãe? Escolha nas Receitas Saudáveis um almoço rico em ferro que lhe dê força, sente-se e coma com calma.', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv? Välj en järnrik lunch som ger dig kraft från Hälsosamma recept, sätt dig ner och ät i lugn och ro.', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chọn một bữa trưa giàu sắt trong Công thức lành mạnh để nạp năng lượng, rồi ngồi xuống thong thả ăn nhé.', body_zh = '你想尽办法喂饱宝宝，那你自己呢？从健康食谱里选一份富含铁、能给你力量的午餐，安安静静坐下来吃吧。' WHERE id = 'b174df30-8e63-488e-ae9b-4d227f3136f1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Muelas grandes? 🦷', body_es = '¿Lo muerde todo y llora sin motivo? Puede que vengan las muelas del fondo. Anota el proceso en el Seguimiento de dentición y ten listos los mordedores fríos.', title_fr = 'Les grosses molaires ? 🦷', body_fr = 'Il mâchouille tout et pleure sans raison ? Les molaires du fond arrivent peut-être. Notez l''évolution dans le Suivi des dents et préparez des anneaux de dentition froids.', title_hi = 'बड़ी दाढ़ें? 🦷', body_hi = 'बिना वजह सब कुछ चबाता और रोता है? सबसे पीछे की दाढ़ें आने वाली हो सकती हैं। दाँत निकलने के ट्रैकर में इसे दर्ज कीजिए और ठंडे टीदर तैयार रखिए।', title_id = 'Geraham besar? 🦷', body_id = 'Menggigit apa saja dan menangis tanpa sebab? Geraham paling belakang mungkin sedang tumbuh. Catat prosesnya di Pelacak Tumbuh Gigi dan siapkan teether dingin.', title_ja = '大きな奥歯？🦷', body_ja = '理由もなくなんでもかじって泣いていますか？いちばん奥の奥歯が生えてきているのかもしれません。「歯の生え始めトラッカー」に記録して、冷やした歯がためを用意しましょう。', title_ko = '큰 어금니가 나오나요? 🦷', body_ko = '이유 없이 뭐든 깨물고 우나요? 가장 안쪽 어금니가 나오는 중일 수 있어요. 이앓이 기록에 과정을 남기고 차가운 치발기를 준비해 두세요.', title_nl = 'Grote kiezen onderweg? 🦷', body_nl = 'Knaagt hij op alles en huilt hij zonder reden? De achterste kiezen kunnen eraan komen. Noteer het in de Tandjestracker en leg koele bijtringen klaar.', title_pl = 'Duże trzonowce? 🦷', body_pl = 'Gryzie wszystko i płacze bez powodu? Mogą wychodzić ostatnie trzonowce. Zapisz to w narzędziu do śledzenia ząbkowania i przygotuj schłodzone gryzaki.', title_pt = 'Os molares grandes? 🦷', body_pt = 'Rói tudo e chora sem motivo? Os molares de trás podem estar a caminho. Registe o processo no Registo de Dentição e prepare mordedores frios.', title_sv = 'Stora kindtänder? 🦷', body_sv = 'Tuggar barnet på allt och gråter utan anledning? De bakersta kindtänderna kan vara på väg. Anteckna det i Tandspåraren och ta fram kalla bitringar.', title_vi = 'Răng hàm lớn đang mọc? 🦷', body_vi = 'Bé gặm mọi thứ và khóc không rõ lý do? Có thể những chiếc răng hàm trong cùng đang mọc. Hãy ghi lại trong Theo dõi mọc răng và chuẩn bị vòng gặm nướu mát lạnh.', title_zh = '大磨牙要来了？🦷', body_zh = '无缘无故什么都咬，还一直哭？最里面的磨牙可能正在长。在出牙记录里记下过程，准备好冰凉的牙胶吧。' WHERE id = '5d951093-5ada-49f6-9750-d303bcf8d918' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe del cuento 🪄', body_es = 'Esta noche crea en Cuentos inteligentes una historia especial cuyo héroe sea tu peque: «El pequeño valiente al que le encanta lavarse los dientes».', title_fr = 'Le héros du conte 🪄', body_fr = 'Ce soir, créez dans les Contes intelligents une histoire spéciale dont votre enfant est le héros : « Le petit courageux qui adore se brosser les dents ».', title_hi = 'कहानी का हीरो 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: दाँत ब्रश करना पसंद करने वाला एक बहादुर नन्हा।', title_id = 'Tokoh utama dongeng 🪄', body_id = 'Malam ini, buat cerita istimewa di Dongeng Pintar dengan anak Anda sebagai tokoh utamanya: Si kecil pemberani yang suka menyikat gigi.', title_ja = 'お話の主人公 🪄', body_ja = '今夜は「スマートおはなし」で、お子さんが主人公の特別なお話をつくりましょう：「歯みがきが大好きな勇敢なおちびさん」。', title_ko = '동화 속 주인공 🪄', body_ko = '오늘 밤 스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: ''양치를 좋아하는 용감한 꼬마''.', title_nl = 'De held van het sprookje 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: de dappere kleine die graag zijn tanden poetst.', title_pl = 'Bohater bajki 🪄', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Dzielny maluch, który uwielbia myć ząbki”.', title_pt = 'O herói da história 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "O pequeno corajoso que adora escovar os dentes".', title_sv = 'Sagans hjälte 🪄', body_sv = 'Skapa i kväll en speciell berättelse i Smarta sagor där ditt eget barn är hjälten: den modiga lilla som älskar att borsta tänderna.', title_vi = 'Nhân vật chính của câu chuyện 🪄', body_vi = 'Tối nay, hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là bé: "Em bé dũng cảm thích đánh răng".', title_zh = '故事的主角 🪄', body_zh = '今晚在智能故事里创作一个以你的孩子为主角的特别故事：一个爱刷牙的勇敢小家伙。' WHERE id = '9fe66081-4fad-49c8-891d-2ca85484f87d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Atrévete a salir ⛅', body_es = '¿Os habéis quedado en casa porque el tiempo está raro? Deja que Tiempo y ropa te diga al momento la velocidad del viento que no se ve desde la ventana y la ropa adecuada, y sal al parque con confianza.', title_fr = 'Oser sortir ⛅', body_fr = 'Vous restez à la maison parce que le temps est bizarre ? Laissez l''outil Météo et tenue vous indiquer tout de suite la vitesse du vent, invisible depuis la fenêtre, et la bonne tenue, puis filez au parc.', title_hi = 'बाहर निकलने की हिम्मत ⛅', body_hi = 'मौसम अजीब है, इसलिए घर पर रुकी हैं? मौसम और कपड़े टूल आपको खिड़की से न दिखने वाली हवा की रफ़्तार और सही कपड़ों का मेल तुरंत बताएगा, बेझिझक पार्क जाइए।', title_id = 'Berani keluar rumah ⛅', body_id = 'Tetap di rumah karena cuacanya aneh? Biarkan alat Cuaca dan Pakaian langsung memberi tahu kecepatan angin yang tak terlihat dari jendela dan kombinasi pakaian yang tepat, lalu pergilah ke taman dengan percaya diri.', title_ja = 'お出かけする勇気 ⛅', body_ja = 'なんだか変な天気だから家にいますか？「天気と服装」なら、窓からは見えない風の強さとぴったりのコーデをすぐに教えてくれます。思いきって公園へ出かけましょう。', title_ko = '용기 내서 밖으로 ⛅', body_ko = '날씨가 애매해서 집에만 있었나요? 날씨와 옷차림 도구로 창밖으로는 안 보이는 풍속과 알맞은 옷차림을 바로 확인하고 자신 있게 공원으로 나가 보세요.', title_nl = 'Durven naar buiten ⛅', body_nl = 'Ben je thuisgebleven omdat het weer raar is? Laat Weer en kleding je meteen de windsnelheid vertellen die je door het raam niet ziet, plus de juiste outfit, en ga gerust naar het park.', title_pl = 'Odwaga, by wyjść na dwór ⛅', body_pl = 'Zostałyście w domu, bo pogoda jest dziwna? Niech narzędzie Pogoda i ubiór od razu powie ci, jaki wieje wiatr, którego nie widać przez okno, i jaki zestaw ubrań wybrać. Śmiało ruszajcie do parku.', title_pt = 'Coragem para sair ⛅', body_pt = 'Ficou em casa porque o tempo está estranho? Deixe que o Tempo e Roupa lhe diga na hora a velocidade do vento que não se vê da janela e a combinação certa, e vá ao parque com confiança.', title_sv = 'Mod att gå ut ⛅', body_sv = 'Har ni stannat inne för att vädret är konstigt? Låt Väder och kläder direkt berätta vindhastigheten du inte ser genom fönstret och rätt klädsel, och gå modigt till parken.', title_vi = 'Mạnh dạn ra ngoài nào ⛅', body_vi = 'Thời tiết thất thường nên cả nhà ở trong nhà? Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay tốc độ gió mà nhìn qua cửa sổ không thấy được cùng cách phối đồ phù hợp, rồi tự tin ra công viên nhé.', title_zh = '出门的勇气 ⛅', body_zh = '天气怪怪的，就待在家里了？让天气与穿衣工具立刻告诉你窗外看不出的风速和合适的穿搭，勇敢地去公园吧。' WHERE id = 'c638741f-2af1-4bf3-a4de-09ffcb406144' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Mascarilla de yogur! 🥣', body_es = '¿Se ha untado la comida por la cara y el pelo? En lugar de enfadarte, añade esta genial obra de arte al Álbum del bebé, ponle pegatinas divertidas y guárdala en la memoria.', title_fr = 'Masque au yaourt ! 🥣', body_fr = 'Il s''est étalé la nourriture sur le visage et les cheveux ? Au lieu de vous énerver, ajoutez ce chef-d''œuvre à l''Album de bébé avec des stickers rigolos pour en garder le souvenir.', title_hi = 'दही का मास्क! 🥣', body_hi = 'खाना चेहरे और बालों पर मल लिया? गुस्सा होने के बजाय इस अनोखी कलाकृति को बेबी एल्बम में जोड़िए और मज़ेदार स्टिकर लगाकर यादों में सहेजिए।', title_id = 'Masker yogurt! 🥣', body_id = 'Ia mengoleskan makanan ke wajah dan rambutnya? Daripada kesal, tambahkan karya seni jenius ini ke Album Bayi, hiasi dengan stiker lucu, dan jadikan kenangan.', title_ja = 'ヨーグルトパック！🥣', body_ja = '食べ物を顔や髪に塗りたくりましたか？怒る代わりに、この天才的な作品を「ベビーアルバム」に追加して、楽しいステッカーで飾り、思い出に残しましょう。', title_ko = '요거트 마스크! 🥣', body_ko = '음식을 얼굴과 머리에 다 발랐나요? 화내는 대신 이 천재적인 작품을 아기 앨범에 올리고 재미있는 스티커를 붙여 추억으로 남겨 보세요.', title_nl = 'Yoghurtmasker! 🥣', body_nl = 'Heeft hij eten over zijn gezicht en haar gesmeerd? Word niet boos, maar voeg dit geniale kunstwerk toe aan het Babyalbum, plak er grappige stickers op en maak er een blijvende herinnering van.', title_pl = 'Maseczka z jogurtu! 🥣', body_pl = 'Rozsmarował jedzenie na buzi i włosach? Zamiast się denerwować, dodaj to genialne dzieło sztuki do Albumu dziecka, ozdób zabawnymi naklejkami i zachowaj na pamiątkę.', title_pt = 'Máscara de iogurte! 🥣', body_pt = 'Espalhou a comida pela cara e pelo cabelo? Em vez de se enervar, adicione esta obra-prima ao Álbum do Bebé e guarde-a na memória com autocolantes divertidos.', title_sv = 'Yoghurtmask! 🥣', body_sv = 'Har barnet smetat maten i ansiktet och håret? I stället för att bli irriterad, lägg till detta geniala konstverk i Babyalbumet, dekorera med roliga klistermärken och spara minnet.', title_vi = 'Mặt nạ sữa chua! 🥣', body_vi = 'Bé bôi thức ăn lên khắp mặt và tóc? Thay vì bực mình, hãy thêm tác phẩm nghệ thuật này vào Album của bé, dán thêm sticker vui nhộn và lưu giữ thành kỷ niệm.', title_zh = '酸奶面膜！🥣', body_zh = '把饭抹到脸上和头发上了？与其生气，不如把这件天才艺术作品加进宝宝相册，贴上有趣的贴纸，永远留在回忆里。' WHERE id = '3d75b744-8440-4e62-83c6-4a08b865c0f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El temporizador se ha parado, descansa 🍵', body_es = 'Has parado el temporizador de sueño y has salido de la habitación. ¡Ahora ni toques las tareas de casa! Prepárate una manzanilla y deja que el vapor caliente se lleve el cansancio del día.', title_fr = 'Minuteur arrêté, à vous de vous reposer 🍵', body_fr = 'Vous avez arrêté le minuteur de sommeil et quitté la chambre. Maintenant, ne touchez pas aux tâches ménagères ! Préparez-vous une camomille et laissez la fatigue du jour s''envoler avec la vapeur.', title_hi = 'टाइमर रुक गया, अब आप आराम कीजिए 🍵', body_hi = 'स्लीप टाइमर रोककर आप कमरे से बाहर आ गईं। अब घर के कामों को हाथ मत लगाइए! अपने लिए कैमोमाइल चाय बनाइए और दिन की थकान को गर्म भाप के साथ उड़ा दीजिए।', title_id = 'Timer berhenti, Anda istirahat 🍵', body_id = 'Anda menghentikan Timer Tidur dan keluar kamar. Sekarang jangan sentuh pekerjaan rumah! Seduh teh chamomile dan biarkan lelah hari ini menguap bersama uap hangatnya.', title_ja = 'タイマーが止まったら、あなたも休憩 🍵', body_ja = '睡眠タイマーを止めて部屋を出ましたね。今は家事に手をつけないで！カモミールティーをいれて、一日の疲れを温かい湯気に溶かしましょう。', title_ko = '타이머는 멈췄어요, 이제 쉬세요 🍵', body_ko = '수면 타이머를 켜고 방을 나왔나요? 이제 집안일은 손대지 마세요! 캐모마일 차를 우려 따뜻한 김에 하루의 피로를 날려 보내세요.', title_nl = 'Timer gestopt, nu rust jij 🍵', body_nl = 'Je hebt de Slaaptimer gestopt en bent de kamer uit. Raak het huishouden nu niet aan! Zet een kopje kamillethee en laat de vermoeidheid van de dag wegdampen.', title_pl = 'Timer stop, czas na odpoczynek 🍵', body_pl = 'Zatrzymałaś timer snu i wyszłaś z pokoju. Teraz nie ruszaj obowiązków domowych! Zaparz sobie rumianek i pozwól, by ciepła para zabrała zmęczenie całego dnia.', title_pt = 'O temporizador parou, descanse 🍵', body_pt = 'Parou o temporizador de sono e saiu do quarto. Agora não toque nas tarefas da casa! Prepare um chá de camomila e deixe o cansaço do dia ir-se com o vapor quente.', title_sv = 'Timern stoppad, nu vilar du 🍵', body_sv = 'Du har stoppat sömntimern och lämnat rummet. Rör inte hushållssysslorna nu! Brygg en kopp kamomillte och låt dagens trötthet försvinna med den varma ångan.', title_vi = 'Hẹn giờ đã dừng, mẹ nghỉ ngơi thôi 🍵', body_vi = 'Mẹ đã tắt Bộ hẹn giờ ngủ và ra khỏi phòng. Giờ đừng động vào việc nhà nhé! Hãy pha cho mình một tách trà hoa cúc và để hơi ấm cuốn trôi mệt mỏi cả ngày.', title_zh = '计时器停了，你休息吧 🍵', body_zh = '你停下睡眠计时器，走出了房间。现在别碰家务！给自己泡一杯洋甘菊茶，让一天的疲惫随热气散去。' WHERE id = '69c1e419-f8f2-4b2f-90e3-9b51e78ff197' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le pican las encías? 🦷', body_es = 'Puede que vengan las últimas muelas. Para aliviar el picor de encías, prepara en Recetas para bebé polos de fruta fresquitos, sanos y sin azúcar.', title_fr = 'Les gencives qui grattent ? 🦷', body_fr = 'Les dernières molaires arrivent peut-être. Pour calmer ses gencives, préparez des glaces aux fruits fraîches, sans sucre et saines avec les Recettes pour bébés.', title_hi = 'दाँतों में खुजली? 🦷', body_hi = 'आखिरी दाढ़ें आने वाली हो सकती हैं। मसूड़ों की खुजली कम करने के लिए बच्चों की रेसिपी से ठंडी, बिना चीनी वाली और सेहतमंद फ्रूट पॉप्सिकल बनाइए।', title_id = 'Gusi gatal? 🦷', body_id = 'Geraham terakhir mungkin sedang tumbuh. Untuk meredakan gatal di gusi, buat es loli buah (popsicle) yang sejuk, tanpa gula, dan sehat dari Resep Bayi.', title_ja = '歯ぐきがむずむず？🦷', body_ja = '最後の奥歯が生えてくるところかもしれません。歯ぐきのかゆみをやわらげるために、「離乳食を始める赤ちゃんのレシピ」から、冷たくて砂糖不使用のヘルシーなフルーツアイスキャンディーをつくりましょう。', title_ko = '잇몸이 간지러워요? 🦷', body_ko = '마지막 어금니가 나오는 중일 수 있어요. 잇몸 간지러움을 덜어 주도록 아기 레시피에서 시원하고 설탕 없는 건강한 과일 아이스바를 만들어 보세요.', title_nl = 'Jeukend tandvlees? 🦷', body_nl = 'De laatste kiezen kunnen eraan komen. Maak tegen jeukend tandvlees koele, suikervrije en gezonde fruitijsjes uit Babyrecepten.', title_pl = 'Swędzą dziąsła? 🦷', body_pl = 'Mogą wychodzić ostatnie trzonowce. Aby złagodzić swędzenie dziąseł, przygotuj z Przepisów dla niemowląt chłodne, zdrowe owocowe lody na patyku bez cukru.', title_pt = 'Comichão nas gengivas? 🦷', body_pt = 'Os últimos molares podem estar a caminho. Para aliviar a comichão nas gengivas, prepare com as Receitas para bebés gelados de fruta frescos, sem açúcar e saudáveis.', title_sv = 'Kliar det i tänderna? 🦷', body_sv = 'De sista kindtänderna kan vara på väg. Gör svala, sockerfria och nyttiga fruktglassar (isglassar) från Recept för bebisar för att lindra klådan i tandköttet.', title_vi = 'Nướu ngứa ngáy? 🦷', body_vi = 'Những chiếc răng hàm cuối cùng có thể đang mọc. Để giảm ngứa nướu, hãy làm kem que trái cây mát lạnh, không đường và bổ dưỡng từ Công thức cho bé.', title_zh = '牙龈痒痒？🦷', body_zh = '最后几颗磨牙可能就要长出来了。为了缓解牙龈发痒，从宝宝食谱里做一些清凉、无糖又健康的水果冰棒吧。' WHERE id = '934796d5-42af-4c49-9cb9-67f18b657e36' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Chef independiente! 👨‍🍳', body_es = '¿No quiere darte la cuchara? Prepara en Recetas para bebé albóndigas fáciles de coger con la mano. Con el temporizador de tomas, analiza cuánto tarda comiendo solo y sigue su apetito.', title_fr = 'Petit chef indépendant ! 👨‍🍳', body_fr = 'Il ne veut pas vous laisser la cuillère ? Préparez des boulettes faciles à attraper avec les Recettes pour bébés. Analysez la durée de ses repas en autonomie et suivez son appétit avec le minuteur des repas.', title_hi = 'आत्मनिर्भर शेफ़! 👨‍🍳', body_hi = 'चम्मच आपको देना नहीं चाहता? बच्चों की रेसिपी से हाथ में आसानी से पकड़ में आने वाले कोफ़्ते बनाइए। फ़ीडिंग टाइमर से खुद खाने का समय देखिए और उसकी भूख पर नज़र रखिए।', title_id = 'Koki mandiri! 👨‍🍳', body_id = 'Tidak mau menyerahkan sendok kepada Anda? Buat bola-bola daging yang mudah digenggam dari Resep Bayi. Pantau lama waktu makan mandirinya dengan Timer Makan dan perhatikan nafsu makannya.', title_ja = 'ひとりでできる小さなシェフ！👨‍🍳', body_ja = 'スプーンを渡してくれない？「離乳食を始める赤ちゃんのレシピ」から、手でつかみやすいミートボールをつくってみましょう。食事タイマーで自分で食べる時間を分析して、食欲を見守りましょう。', title_ko = '꼬마 셰프의 독립! 👨‍🍳', body_ko = '숟가락을 넘겨주지 않으려 하나요? 아기 레시피에서 손으로 집기 쉬운 미트볼을 만들어 보세요. 수유 타이머로 혼자 먹는 시간을 분석하고 식욕을 지켜보세요.', title_nl = 'Zelfstandige chef! 👨‍🍳', body_nl = 'Wil hij de lepel niet aan je geven? Maak uit Babyrecepten balletjes die hij makkelijk kan vastpakken. Volg met de Voedingstimer hoe lang hij zelf eet en houd zijn eetlust in de gaten.', title_pl = 'Samodzielny szef kuchni! 👨‍🍳', body_pl = 'Nie chce oddać ci łyżki? Przygotuj z Przepisów dla niemowląt klopsiki, które łatwo chwycić. Timerem karmienia sprawdzaj, jak długo je samodzielnie, i obserwuj jego apetyt.', title_pt = 'Chef independente! 👨‍🍳', body_pt = 'Não lhe quer dar a colher? Prepare com as Receitas para bebés almôndegas fáceis de agarrar. Analise com o temporizador de alimentação o tempo que come sozinho e acompanhe o apetite.', title_sv = 'Självständig kock! 👨‍🍳', body_sv = 'Vill barnet inte ge dig skeden? Gör lättgreppade köttbullar från Recept för bebisar. Följ hur länge barnet äter själv med matningstimern och håll koll på aptiten.', title_vi = 'Đầu bếp tự lập! 👨‍🍳', body_vi = 'Bé không chịu đưa thìa cho mẹ? Hãy làm những viên thịt dễ cầm từ Công thức cho bé. Dùng Hẹn giờ cho bú để theo dõi thời gian bé tự ăn và khẩu vị của bé.', title_zh = '独立的小厨师！👨‍🍳', body_zh = '不肯把勺子交给你？从宝宝食谱里做些方便小手抓的肉丸子。用喂养计时器分析宝宝自主进食的时长，留意食欲变化。' WHERE id = '06d75280-127a-43d4-a7f0-42d2871b24c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Caras graciosas 🤪', body_es = '¿Hace muecas delante del espejo? ¡No te pierdas este momento tan divertido! Decóralo con las pegatinas graciosas de la Sesión de fotos del bebé y conviértelo en la foto más alegre del álbum.', title_fr = 'Grimaces rigolotes 🤪', body_fr = 'Il fait des grimaces devant le miroir ? Ne manquez pas ce moment amusant ! Décorez-le avec les stickers drôles de la Séance photo bébé pour en faire la photo la plus joyeuse de l''album.', title_hi = 'मज़ेदार चेहरे 🤪', body_hi = 'आईने के सामने मुँह बनाता है? यह मज़ेदार पल मत चूकिए! बेबी फ़ोटोशूट के मज़ेदार स्टिकर से सजाकर इसे एल्बम की सबसे खुशनुमा तस्वीर बनाइए।', title_id = 'Ekspresi wajah lucu 🤪', body_id = 'Ia memasang wajah lucu di depan cermin? Jangan lewatkan momen seru ini! Hiasi dengan stiker lucu dari Sesi Foto Bayi dan jadikan foto paling ceria di album.', title_ja = 'おもしろい顔 🤪', body_ja = '鏡の前で変な顔をしていますか？この楽しい瞬間を見逃さないで！「ベビーフォトセッション」のおもしろいステッカーで飾って、アルバムでいちばん楽しい一枚にしましょう。', title_ko = '웃긴 표정 🤪', body_ko = '거울 앞에서 얼굴을 찡그리고 있나요? 이 재미있는 순간을 놓치지 마세요! 아기 사진 촬영의 재미있는 스티커로 꾸며 앨범에서 가장 유쾌한 사진으로 만들어 보세요.', title_nl = 'Grappige gezichtjes 🤪', body_nl = 'Trekt hij gekke bekken voor de spiegel? Mis dit leuke moment niet! Versier het met grappige stickers in Babyfotoshoot en maak er de vrolijkste foto van het album van.', title_pl = 'Śmieszne miny 🤪', body_pl = 'Robi miny przed lustrem? Nie przegap tej zabawnej chwili! Ozdób zdjęcie śmiesznymi naklejkami z Sesji zdjęciowej dziecka i zrób z niego najweselszy kadr w albumie.', title_pt = 'Caretas engraçadas 🤪', body_pt = 'Faz caretas em frente ao espelho? Não perca este momento divertido! Decore-o com os autocolantes engraçados da Sessão Fotográfica do Bebé e transforme-o na foto mais alegre do álbum.', title_sv = 'Roliga miner 🤪', body_sv = 'Gör barnet grimaser framför spegeln? Missa inte det roliga ögonblicket! Dekorera med roliga klistermärken i Babyfotografering och gör det till albumets gladaste bild.', title_vi = 'Biểu cảm khuôn mặt hài hước 🤪', body_vi = 'Bé nhăn mặt làm trò trước gương? Đừng bỏ lỡ khoảnh khắc vui nhộn này! Hãy trang trí bằng sticker ngộ nghĩnh trong Chụp ảnh cho bé để có tấm ảnh vui nhất trong album.', title_zh = '搞怪表情 🤪', body_zh = '在镜子前挤眉弄眼？别错过这个有趣的时刻！用宝宝写真里的搞笑贴纸装饰一下，变成相册里最欢乐的一张。' WHERE id = '4b7fd5a1-3084-40d7-9f2d-e7fb4777d2eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se sube a todo? 🧗‍♀️', body_es = 'Sofá, mesa, armario... ¡Es todo un escalador! Lee en el Blog cómo responder con seguridad en casa a esta necesidad motriz, arriesgada pero necesaria.', title_fr = 'Il grimpe partout ? 🧗‍♀️', body_fr = 'Canapé, table, armoire... C''est un vrai alpiniste ! Lisez dans la rubrique Blogs comment répondre en toute sécurité à ce besoin moteur risqué mais essentiel.', title_hi = 'हर चीज़ पर चढ़ता है? 🧗‍♀️', body_hi = 'सोफ़ा, मेज़, अलमारी... वह तो असली पर्वतारोही है! ब्लॉग सेक्शन में पढ़िए कि मोटर स्किल्स की इस जोखिम भरी लेकिन ज़रूरी चाह को घर पर सुरक्षित तरीके से कैसे पूरा करें।', title_id = 'Memanjat apa saja? 🧗‍♀️', body_id = 'Sofa, meja, lemari... Ia benar-benar pendaki cilik! Baca di bagian Blog cara memenuhi kebutuhan motorik yang berisiko tapi penting ini dengan aman di rumah.', title_ja = 'なんにでもよじ登る？🧗‍♀️', body_ja = 'ソファ、テーブル、戸棚…本物の登山家ですね！危険だけれど欠かせないこの運動の欲求に、家で安全に応える方法をブログで読んでみましょう。', title_ko = '어디든 기어오르나요? 🧗‍♀️', body_ko = '소파, 탁자, 옷장... 진정한 등반가예요! 위험하지만 꼭 필요한 이 운동 욕구를 집에서 안전하게 채워 주는 방법을 블로그에서 읽어 보세요.', title_nl = 'Klimt hij overal op? 🧗‍♀️', body_nl = 'Bank, tafel, kast... Hij is een echte bergbeklimmer! Lees in Blogs hoe je deze riskante, maar noodzakelijke motorische behoefte thuis veilig opvangt.', title_pl = 'Wspina się na wszystko? 🧗‍♀️', body_pl = 'Kanapa, stół, szafka... To prawdziwy alpinista! Przeczytaj w sekcji Blog, jak bezpiecznie zaspokoić w domu tę ryzykowną, ale potrzebną potrzebę ruchu.', title_pt = 'Trepa a tudo? 🧗‍♀️', body_pt = 'Sofá, mesa, armário... É um verdadeiro alpinista! Leia nos Blogues como responder em segurança, em casa, a esta necessidade motora arriscada mas essencial.', title_sv = 'Klättrar på allt? 🧗‍♀️', body_sv = 'Soffan, bordet, skåpet... Barnet är en riktig bergsklättrare! Läs i Bloggar hur du tryggt kan möta detta riskfyllda men nödvändiga motoriska behov hemma.', title_vi = 'Leo trèo khắp nơi? 🧗‍♀️', body_vi = 'Ghế sofa, bàn, tủ... Bé đúng là một nhà leo núi thực thụ! Hãy đọc trong mục Blog cách đáp ứng nhu cầu vận động nguy hiểm nhưng cần thiết này một cách an toàn tại nhà.', title_zh = '什么都想爬？🧗‍♀️', body_zh = '沙发、桌子、柜子……简直是个登山家！去博客板块读读如何在家安全地满足这种有风险却必要的运动需求。' WHERE id = '739af07d-8466-4c3f-a164-5e408385ca93' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Los pantalones se le quedan cortos? 👖', body_es = '¡El estirón va a toda velocidad! Introduce su talla y peso actuales en el Registro de peso y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Le pantalon est devenu trop court ? 👖', body_fr = 'Le pic de croissance bat son plein ! Entrez sa taille et son poids actuels dans le Suivi du poids et regardez fièrement sa courbe de croissance grimper.', title_hi = 'पैंट छोटी हो गई? 👖', body_hi = 'ग्रोथ स्पर्ट पूरी रफ़्तार पर है! वेट ट्रैकर में मौजूदा लंबाई और वज़न दर्ज कीजिए और गर्व से देखिए कि विकास चार्ट कैसे ऊपर जा रहा है।', title_id = 'Celananya jadi cutbray? 👖', body_id = 'Lonjakan pertumbuhan sedang berlangsung pesat! Masukkan tinggi dan berat badannya saat ini ke Pelacak Berat Badan dan lihat dengan bangga grafik pertumbuhannya naik.', title_ja = 'ズボンの丈が短くなった？👖', body_ja = '成長期の真っ最中！「体重トラッカー」に今の身長と体重を入力して、成長グラフが伸びていく様子を誇らしく眺めましょう。', title_ko = '바지가 짧아졌나요? 👖', body_ko = '성장 급등기가 한창이에요! 체중 기록에 현재 키와 몸무게를 입력하고 성장 그래프가 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Broek al te kort? 👖', body_nl = 'De groeispurt is in volle gang! Voer zijn huidige lengte en gewicht in de Gewichtstracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Spodnie za krótkie? 👖', body_pl = 'Skok wzrostowy w pełni! Wpisz aktualny wzrost i wagę w Liczniku wagi i z dumą zobacz, jak pnie się wykres rozwoju.', title_pt = 'As calças ficaram curtas? 👖', body_pt = 'O pico de crescimento continua a toda a velocidade! Introduza a altura e o peso atuais no Registo de Peso e veja com orgulho como sobe o gráfico de desenvolvimento.', title_sv = 'För korta byxben? 👖', body_sv = 'Tillväxtspurten är i full gång! Ange aktuell längd och vikt i Viktspåraren och titta stolt på hur tillväxtkurvan stiger.', title_vi = 'Quần đã bị ngắn rồi? 👖', body_vi = 'Giai đoạn tăng trưởng vọt đang diễn ra hết tốc lực! Hãy nhập chiều cao và cân nặng hiện tại vào Theo dõi cân nặng và tự hào ngắm biểu đồ phát triển đi lên.', title_zh = '裤腿变短了？👖', body_zh = '生长突增正在全速进行！在体重记录里输入当前的身高和体重，骄傲地看看成长曲线是怎么往上走的。' WHERE id = '8ac7016a-7613-48aa-a952-59cc5f8a6354' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando juguetes educativos 🧩', body_es = 'Hacen falta juguetes que no solo hagan ruido, sino que le hagan pensar. Echa un vistazo en Productos recomendados a los puzles de lógica y formas para mayores de 1,5 años.', title_fr = 'À la recherche de jouets éducatifs 🧩', body_fr = 'Il lui faut des jouets qui font réfléchir, pas seulement du bruit. Jetez un œil aux puzzles de logique et de formes dès 1,5 an dans les Produits recommandés.', title_hi = 'सिखाने वाले खिलौनों की तलाश 🧩', body_hi = 'सिर्फ़ आवाज़ करने वाले नहीं, सोचने पर मजबूर करने वाले खिलौने चाहिए। सुझाए गए प्रोडक्ट में 1.5 साल से ऊपर के बच्चों के लिए लॉजिक और आकार वाली पहेलियाँ (पज़ल) ज़रूर देखिए।', title_id = 'Mencari mainan edukatif 🧩', body_id = 'Ia butuh mainan yang mengajak berpikir, bukan sekadar berbunyi. Lihat puzzle logika dan bentuk untuk usia 1,5 tahun ke atas di Produk Rekomendasi.', title_ja = '知育おもちゃ探し 🧩', body_ja = '音が出るだけでなく、考える力を育てるおもちゃが必要です。「おすすめ商品」で、1歳半以上向けの論理パズルや形合わせパズルをぜひチェックしてみて。', title_ko = '교육용 장난감 찾기 🧩', body_ko = '소리만 나는 장난감이 아니라 생각하게 하는 장난감이 필요해요. 추천 제품에서 18개월 이상을 위한 논리·모양 퍼즐을 꼭 살펴보세요.', title_nl = 'Op zoek naar leerzaam speelgoed 🧩', body_nl = 'Hij heeft speelgoed nodig dat niet alleen geluid maakt, maar ook laat nadenken. Bekijk zeker de logica- en vormpuzzels voor 1,5 jaar en ouder in Aanbevolen producten.', title_pl = 'W poszukiwaniu edukacyjnych zabawek 🧩', body_pl = 'Potrzebne są zabawki, które nie tylko hałasują, ale też uczą myśleć. Koniecznie zajrzyj w Polecanych produktach do łamigłówek logicznych i układanek z kształtami dla dzieci od 1,5 roku.', title_pt = 'À procura de brinquedos educativos 🧩', body_pt = 'São precisos brinquedos que façam pensar, não só que façam barulho. Espreite sem falta nos Produtos Recomendados os puzzles de lógica e formas para mais de 1,5 anos.', title_sv = 'På jakt efter lärorika leksaker 🧩', body_sv = 'Barnet behöver leksaker som får det att tänka, inte bara låter. Titta in i Rekommenderade produkter efter logik- och formpussel för barn över 1,5 år.', title_vi = 'Tìm đồ chơi giáo dục 🧩', body_vi = 'Bé cần những món đồ chơi giúp tư duy chứ không chỉ phát ra âm thanh. Hãy xem ngay các trò ghép hình logic và hình khối (puzzle) cho trẻ trên 1,5 tuổi trong Sản phẩm gợi ý.', title_zh = '寻找益智玩具 🧩', body_zh = '需要的不只是会发声的玩具，而是能让宝宝动脑的玩具。一定要在推荐商品里看看适合1.5岁以上的逻辑和形状拼图。' WHERE id = 'db467018-0ec9-41a9-a3a3-3ef1c48cda53' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Mordiscos de enfado? 🦖', body_es = '¿Pega o muerde cuando se enfada? Son emociones que aún no sabe expresar con palabras. Aprende con Anacan AI a reconducir esta conducta con suavidad.', title_fr = 'Morsures de colère ? 🦖', body_fr = 'Il tape ou mord quand il est en colère ? Ce sont des émotions qu''il ne sait pas encore exprimer avec des mots. Découvrez avec Anacan AI comment faire évoluer ce comportement en douceur.', title_hi = 'गुस्से में काटना? 🦖', body_hi = 'गुस्से में मारता या काटता है? ये वे भावनाएँ हैं जिन्हें वह शब्दों में नहीं कह पाता। Anacan AI से जानिए कि इस व्यवहार को नरमी से कैसे बदलें।', title_id = 'Gigitan saat marah? 🦖', body_id = 'Memukul atau menggigit saat marah? Itu adalah perasaan yang belum bisa ia ungkapkan dengan kata-kata. Pelajari cara mengubah perilaku ini dengan lembut dari Anacan AI.', title_ja = '怒ってかみつく？🦖', body_ja = '怒るとたたいたり、かんだりしますか？これは言葉でまだ表せない気持ちです。この行動をやさしく変えていく方法を、Anacan AIで学びましょう。', title_ko = '화가 나서 깨물어요? 🦖', body_ko = '화가 나면 때리거나 깨무나요? 아직 말로 표현하지 못하는 감정 때문이에요. 이 행동을 부드럽게 바꿔 주는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Boos bijten? 🦖', body_nl = 'Slaat of bijt hij als hij boos is? Dat zijn gevoelens die hij nog niet in woorden kan uiten. Leer bij Anacan AI hoe je dit gedrag zacht kunt bijsturen.', title_pl = 'Gryzienie ze złości? 🦖', body_pl = 'Gdy się złości, bije albo gryzie? To emocje, których nie potrafi jeszcze wyrazić słowami. Dowiedz się od Anacan AI, jak łagodnie zmienić to zachowanie.', title_pt = 'Mordidas de raiva? 🦖', body_pt = 'Quando se zanga, bate ou morde? São emoções que ainda não consegue expressar com palavras. Saiba com o Anacan AI como mudar este comportamento com suavidade.', title_sv = 'Biter när hen är arg? 🦖', body_sv = 'Slår eller biter barnet när hen blir arg? Det är känslor som barnet ännu inte kan uttrycka med ord. Lär dig av Anacan AI hur du varsamt kan förändra beteendet.', title_vi = 'Cắn vì tức giận? 🦖', body_vi = 'Bé đánh hoặc cắn khi tức giận? Đó là những cảm xúc bé chưa thể diễn đạt bằng lời. Hãy học từ Anacan AI cách nhẹ nhàng thay đổi hành vi này.', title_zh = '生气就咬人？🦖', body_zh = '一生气就打人或咬人？这是宝宝还无法用语言表达的情绪。向Anacan AI了解如何温和地改变这种行为。' WHERE id = 'df8f7402-1277-45bd-a743-5c24bdaf48e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se ha tirado al suelo llorando en un lugar público? Olvida las miradas de los demás. Desahógate con Anacan AI y aprende métodos para gestionar estas rabietas con calma.', body_fr = 'Il s''est jeté par terre en pleurant en public ? Oubliez les regards des autres. Discutez avec Anacan AI pour apprendre des méthodes et gérer ces crises avec sang-froid.', body_hi = 'सबके सामने ज़मीन पर लोटकर रोया? दूसरों की नज़रों को भूल जाइए। ऐसे नखरों को शांति से संभालने के तरीके Anacan AI से बात करके सीखिए।', body_id = 'Ia menjatuhkan diri dan menangis di tempat umum? Lupakan tatapan orang lain. Ngobrollah dengan Anacan AI dan pelajari cara menghadapi tantrum seperti ini dengan tenang.', body_ja = '人前で床にひっくり返って泣きましたか？周りの視線は忘れましょう。こうしたかんしゃくに落ち着いて対応する方法を、Anacan AIに相談して学びましょう。', body_ko = '사람들 앞에서 바닥에 드러누워 울었나요? 남들의 시선은 잊으세요. 이런 떼쓰기를 침착하게 다루는 방법을 Anacan AI와 이야기하며 배워 보세요.', body_nl = 'Gooide hij zich in het openbaar huilend op de grond? Vergeet de blikken van anderen. Praat erover met Anacan AI en leer methoden om zulke driftbuien kalm aan te pakken.', body_pl = 'Rzucił się z płaczem na ziemię w miejscu publicznym? Zapomnij o spojrzeniach innych. Porozmawiaj z Anacan AI i poznaj sposoby, by spokojnie radzić sobie z takimi kryzysami.', body_pt = 'Atirou-se para o chão a chorar num local público? Esqueça os olhares dos outros. Converse com o Anacan AI e aprenda métodos para gerir estas crises com calma.', body_sv = 'Har barnet kastat sig på golvet och gråtit på en offentlig plats? Glöm andras blickar. Prata med Anacan AI och lär dig metoder för att hantera sådana utbrott lugnt.', body_vi = 'Bé nằm lăn ra khóc giữa nơi công cộng? Hãy quên ánh nhìn của người khác. Trò chuyện với Anacan AI để học cách bình tĩnh xử lý những cơn ăn vạ như vậy.', body_zh = '在公共场合躺地上大哭？忘掉别人的目光。和Anacan AI聊聊，学习冷静应对这类崩溃的方法。' WHERE id = '907f2a4d-a45c-43e1-8024-d6c91a18d072' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La siesta se acorta? ⏱️', body_es = '¿No quiere dormir la siesta del mediodía? Revisa las estadísticas del temporizador de sueño. Quizá toque pasar a una sola siesta y adelantar la hora de dormir.', title_fr = 'Siestes plus courtes ? ⏱️', body_fr = 'Il ne veut pas faire la sieste de l''après-midi ? Consultez les statistiques du minuteur de sommeil. Il est peut-être temps de passer complètement à une seule sieste et d''avancer le coucher.', title_hi = 'दिन की नींद छोटी हो रही है? ⏱️', body_hi = 'दोपहर में सोना नहीं चाहता? स्लीप टाइमर के आँकड़े देखिए। शायद अब एक झपकी वाले रूटीन पर पूरी तरह आना और शाम की नींद जल्दी करना होगा।', title_id = 'Tidur siang makin singkat? ⏱️', body_id = 'Tidak mau tidur siang? Pantau statistik Timer Tidur. Mungkin sudah waktunya beralih ke satu kali tidur siang dan memajukan jam tidur malam.', title_ja = 'お昼寝が短くなってきた？⏱️', body_ja = 'お昼寝を嫌がりますか？睡眠タイマーの統計をチェックしましょう。お昼寝を1回に完全に移して、夜の寝る時間を早めるときかもしれません。', title_ko = '낮잠이 짧아지나요? ⏱️', body_ko = '점심 낮잠을 안 자려 하나요? 수면 타이머 통계를 살펴보세요. 이제 낮잠을 한 번으로 완전히 바꾸고 저녁 잠을 더 일찍 재워야 할지도 몰라요.', title_nl = 'Worden de dutjes korter? ⏱️', body_nl = 'Wil hij niet naar zijn middagdutje? Bekijk de statistieken van de Slaaptimer. Misschien is het tijd om helemaal over te stappen op één dutje en de avond vroeger te beginnen.', title_pl = 'Drzemki coraz krótsze? ⏱️', body_pl = 'Nie chce iść na popołudniową drzemkę? Śledź statystyki timera snu. Może czas całkiem przejść na jedną drzemkę i wcześniej kłaść go wieczorem spać.', title_pt = 'A sesta está a encurtar? ⏱️', body_pt = 'Não quer fazer a sesta do meio-dia? Acompanhe as estatísticas do temporizador de sono. Talvez esteja na altura de passar de vez para uma só sesta e antecipar a hora de deitar.', title_sv = 'Kortare dagsömn? ⏱️', body_sv = 'Vill barnet inte sova middag? Följ statistiken i sömntimern. Kanske är det dags att gå över helt till en tupplur och lägga barnet tidigare på kvällen.', title_vi = 'Giấc ngủ ngày ngắn lại? ⏱️', body_vi = 'Bé không muốn ngủ trưa? Hãy theo dõi thống kê của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc chuyển hẳn sang một giấc ngủ ngày và cho bé đi ngủ tối sớm hơn.', title_zh = '午睡变短了？⏱️', body_zh = '不想睡午觉？看看睡眠计时器的统计。也许该完全改成一次午睡，并把晚上的就寝时间提前了。' WHERE id = 'e6ec7f70-00dc-438b-af17-5f764a9d8216' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de los zapatos 👟', body_es = '¿Al salir quiere ponerse sí o sí las botas de invierno en pleno verano? Deja que a veces elija él, eso refuerza su voluntad.', title_fr = 'L''obstination des chaussures 👟', body_fr = 'Il tient absolument à porter ses chaussures d''hiver en plein été pour sortir ? Laissez-le choisir de temps en temps, cela renforce sa volonté.', title_hi = 'जूतों की ज़िद 👟', body_hi = 'बाहर जाते समय गर्मी में भी वही सर्दियों वाले जूते पहनने की ज़िद करता है? कभी-कभी उसकी पसंद को मान लीजिए, इससे उसकी इच्छाशक्ति मज़बूत होती है।', title_id = 'Ngotot soal sepatu 👟', body_id = 'Ia bersikeras memakai sepatu musim dingin di musim panas saat keluar rumah? Sesekali biarkan ia memilih sendiri, ini memperkuat kemauannya.', title_ja = '靴へのこだわり 👟', body_ja = 'お出かけのとき、夏なのにどうしても冬の靴をはきたがりますか？ときにはその選択を認めてあげましょう。意志の力が育ちます。', title_ko = '신발 고집 👟', body_ko = '외출할 때 여름인데도 꼭 겨울 신발을 신겠다고 하나요? 가끔은 아이의 선택을 허락해 주세요. 의지가 더 단단해져요.', title_nl = 'Schoenenstrijd 👟', body_nl = 'Wil hij per se zijn winterschoenen aan in de zomer? Laat hem soms zelf kiezen, dat versterkt zijn wilskracht.', title_pl = 'Butowy upór 👟', body_pl = 'Przy każdym wyjściu koniecznie chce założyć latem zimowe buty? Czasem pozwól mu wybrać, to wzmacnia jego siłę woli.', title_pt = 'A teimosia dos sapatos 👟', body_pt = 'Para sair, quer mesmo calçar as botas de inverno em pleno verão? Deixe-o às vezes escolher: isso fortalece a vontade dele.', title_sv = 'Envis med skorna 👟', body_sv = 'Vill barnet absolut ha vinterskorna på sig ute mitt i sommaren? Låt barnet välja ibland, det stärker viljan.', title_vi = 'Cuộc chiến giày dép 👟', body_vi = 'Ra ngoài là bé nhất định đòi đi đôi giày mùa đông giữa mùa hè? Thỉnh thoảng hãy để bé tự chọn, điều này giúp bé rèn ý chí.', title_zh = '鞋子之争 👟', body_zh = '出门非要在夏天穿那双冬鞋？有时候允许宝宝自己选择，这会增强宝宝的意志力。' WHERE id = '46ef9700-c667-4312-ac63-98bd03625249' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se resiste a dormir? 🛌', body_es = '¡No se va a la cama porque jugar es más divertido que dormir! Pon el temporizador de sueño y frena poco a poco su mente con las olas del mar de Ruido blanco.', title_fr = 'Il résiste au sommeil ? 🛌', body_fr = 'Il ne va pas au lit parce que jouer est plus amusant que dormir ! Lancez le minuteur de sommeil et ralentissez doucement son esprit avec les vagues de l''océan des Bruits blancs.', title_hi = 'नींद से लड़ाई? 🛌', body_hi = 'खेलना सोने से ज़्यादा मज़ेदार है, इसलिए बिस्तर पर नहीं जाता! स्लीप टाइमर चालू कीजिए और व्हाइट नॉइज़ में समुद्र की लहरों से उसके दिमाग को धीरे-धीरे शांत कीजिए।', title_id = 'Melawan kantuk? 🛌', body_id = 'Bermain lebih seru daripada tidur, jadi ia tak mau ke tempat tidur! Nyalakan Timer Tidur dan pelan-pelan tenangkan pikirannya dengan suara ombak dari Suara Putih.', title_ja = '眠りに抵抗？🛌', body_ja = '寝るより遊ぶほうがおもしろくて、ベッドに行きたがらない！睡眠タイマーをオンにして、「ホワイトノイズ」の波の音で、頭の中をゆっくり落ち着かせましょう。', title_ko = '잠과의 씨름? 🛌', body_ko = '노는 게 자는 것보다 재미있어서 침대에 안 가나요? 수면 타이머를 켜고 백색소음의 파도 소리로 머릿속을 천천히 진정시켜 주세요.', title_nl = 'Verzet tegen slapen? 🛌', body_nl = 'Spelen is leuker dan slapen, dus hij wil niet naar bed! Zet de Slaaptimer aan en laat zijn hoofdje met oceaangolven uit Witte ruis langzaam tot rust komen.', title_pl = 'Opór przed snem? 🛌', body_pl = 'Nie idzie do łóżka, bo zabawa jest ciekawsza niż spanie! Włącz timer snu i falami oceanu z Białego szumu powoli wycisz jego umysł.', title_pt = 'Resiste ao sono? 🛌', body_pt = 'Brincar é mais interessante do que dormir, por isso não vai para a cama! Ligue o temporizador de sono e acalme-lhe a mente aos poucos com as ondas do mar do Ruído Branco.', title_sv = 'Gör motstånd mot sömnen? 🛌', body_sv = 'Barnet vill inte gå och lägga sig för att lek är roligare än sömn! Starta sömntimern och låt havsvågor från Vitt brus sakta bromsa in hjärnan.', title_vi = 'Cưỡng lại giấc ngủ? 🛌', body_vi = 'Chơi thú vị hơn ngủ nên bé không chịu lên giường! Hãy bật Bộ hẹn giờ ngủ và dùng tiếng sóng biển trong Tiếng ồn trắng để từ từ làm dịu tâm trí bé.', title_zh = '抗拒睡觉？🛌', body_zh = '觉得玩比睡觉有趣，就是不肯上床！打开睡眠计时器，用白噪音里的海浪声让宝宝的大脑慢慢踩下刹车。' WHERE id = '5541587a-ad73-4e1d-9174-d4fe1c028c3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Empieza el interés por el baño? 🚽', body_es = '¿Quiere acompañarte al baño? Es preparación visual. Lee en el Blog cuándo y cómo empezar a dejar el pañal y prepárate.', title_fr = 'Il s''intéresse aux toilettes ? 🚽', body_fr = 'Il veut vous suivre à la salle de bain ? C''est une préparation visuelle. Lisez dans la rubrique Blogs quand et comment commencer l''apprentissage du pot, et soyez prête.', title_hi = 'टॉयलेट में दिलचस्पी शुरू हुई? 🚽', body_hi = 'आपके साथ बाथरूम आना चाहता है? यह देखकर सीखने की तैयारी है। ब्लॉग सेक्शन में पढ़िए कि पॉटी ट्रेनिंग कब और कैसे शुरू करें, और तैयार रहिए।', title_id = 'Mulai tertarik dengan toilet? 🚽', body_id = 'Ingin ikut Anda ke kamar mandi? Ini tanda kesiapan visual. Baca di bagian Blog kapan dan bagaimana memulai latihan pispot, dan bersiaplah.', title_ja = 'トイレに興味が出てきた？🚽', body_ja = 'あなたと一緒にトイレについてきたがりますか？これは目で見て学ぶ準備です。トイレトレーニングをいつ、どう始めればいいか、ブログで読んで準備しておきましょう。', title_ko = '화장실에 관심이 생겼나요? 🚽', body_ko = '화장실에 따라오고 싶어 하나요? 눈으로 익히는 준비 단계예요. 블로그에서 배변 훈련을 언제, 어떻게 시작하면 좋을지 읽고 미리 준비하세요.', title_nl = 'Interesse in de wc? 🚽', body_nl = 'Wil hij met je mee naar de badkamer? Dat is visuele voorbereiding. Lees in Blogs wanneer en hoe je met zindelijkheidstraining begint, zodat je goed voorbereid bent.', title_pl = 'Zaczyna interesować się toaletą? 🚽', body_pl = 'Chce chodzić z tobą do łazienki? To przygotowanie wzrokowe. Przeczytaj w sekcji Blog, kiedy i jak zacząć naukę korzystania z nocnika, i bądź gotowa.', title_pt = 'Começou o interesse pela casa de banho? 🚽', body_pt = 'Quer ir consigo à casa de banho? É uma preparação visual. Leia nos Blogues quando e como começar a usar o bacio e esteja preparada.', title_sv = 'Nyfiken på toaletten? 🚽', body_sv = 'Vill barnet följa med dig in i badrummet? Det är visuell förberedelse. Läs i Bloggar när och hur ni kan börja med pottträning och var förberedd.', title_vi = 'Bé bắt đầu tò mò về nhà vệ sinh? 🚽', body_vi = 'Bé muốn theo mẹ vào phòng tắm? Đây là sự chuẩn bị bằng quan sát. Hãy đọc trong mục Blog khi nào và cách bắt đầu tập ngồi bô để sẵn sàng nhé.', title_zh = '开始对厕所好奇了？🚽', body_zh = '想跟你一起进卫生间？这是视觉上的准备。去博客板块读读什么时候、怎样开始如厕训练，提前做好准备。' WHERE id = 'c2f59a7d-198f-4c77-831a-cca0b1b7e5e6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rumbo a la calma 🎶', body_es = 'Es hora de que descansen esos piececitos que han corrido todo el día. Pon el sonido del interior de un coche en Ruido blanco y crea con su monotonía el ambiente perfecto para dormir.', title_fr = 'Vers le calme 🎶', body_fr = 'C''est l''heure de repos pour ces petits pieds qui ont couru toute la journée. Lancez le bruit d''habitacle de voiture dans les Bruits blancs et créez une ambiance parfaite pour dormir grâce à sa monotonie.', title_hi = 'सुकून की ओर 🎶', body_hi = 'दिनभर दौड़ने वाले नन्हे पैरों के आराम का समय है। व्हाइट नॉइज़ में कार के अंदर की आवाज़ चलाकर एक जैसी लय से नींद का बढ़िया माहौल बनाइए।', title_id = 'Beralih ke ketenangan 🎶', body_id = 'Saatnya kaki kecil yang berlari seharian beristirahat. Putar suara kabin mobil dari Suara Putih dan ciptakan suasana tidur sempurna dengan bunyinya yang monoton.', title_ja = '静けさへの切りかえ 🎶', body_ja = '一日中走り回った小さな足が休む時間です。「ホワイトノイズ」の車内の音を流して、単調な音で最高の眠りの環境をつくりましょう。', title_ko = '차분함으로 넘어가요 🎶', body_ko = '하루 종일 뛰어다닌 작은 발이 쉴 시간이에요. 백색소음에서 자동차 안 소리를 틀어 단조로운 소리로 완벽한 수면 환경을 만들어 주세요.', title_nl = 'Op weg naar rust 🎶', body_nl = 'Tijd voor de kleine voetjes die de hele dag hebben gerend om uit te rusten. Zet het geluid van een auto-interieur uit Witte ruis aan en creëer met dat monotone gebrom de perfecte slaapsfeer.', title_pl = 'Przejście do spokoju 🎶', body_pl = 'Czas na odpoczynek dla małych nóżek, które biegały cały dzień. Włącz w Białym szumie odgłos wnętrza samochodu i jego monotonią stwórz idealne warunki do snu.', title_pt = 'Rumo à tranquilidade 🎶', body_pt = 'É hora de descansar para os pezinhos que correram o dia todo. Ligue no Ruído Branco o som do interior de um carro e crie com essa monotonia o ambiente perfeito para dormir.', title_sv = 'Över till lugnet 🎶', body_sv = 'Dags för vila för de små fötterna som sprungit hela dagen. Sätt på billjud från Vitt brus och skapa en perfekt sömnmiljö med monotona ljud.', title_vi = 'Chuyển sang bình yên 🎶', body_vi = 'Đã đến lúc đôi chân bé nhỏ chạy nhảy cả ngày được nghỉ ngơi. Hãy bật âm thanh trong xe ô tô từ Tiếng ồn trắng để tạo không gian ngủ hoàn hảo với âm thanh đều đều.', title_zh = '切换到安静模式 🎶', body_zh = '跑了一整天的小脚丫该休息了。打开白噪音里的车内声音，用单调的声音营造完美的睡眠环境。' WHERE id = '45af46ac-18bf-499b-a5c7-56bbe71e4564' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas a tus amigas 👯‍♀️', body_es = '¿Te apetece charlar con otras madres mientras tu peque juega en el parque? Descubre en Lugares para mamás centros con grupos de juego y socializa.', title_fr = 'Vous aussi, vous avez besoin d''amies 👯‍♀️', body_fr = 'Envie de discuter avec d''autres mamans pendant qu''il joue au parc ? Découvrez des centres avec groupes de jeu dans les Lieux adaptés aux mamans et faites des rencontres.', title_hi = 'आपको भी दोस्तों की ज़रूरत है 👯‍♀️', body_hi = 'बच्चा पार्क में खेलते समय आप भी दूसरी माँओं से बात करना चाहती हैं? माँ के लिए अनुकूल जगहें में प्ले ग्रुप वाले सेंटर खोजिए और लोगों से मिलिए-जुलिए।', title_id = 'Anda juga butuh teman 👯‍♀️', body_id = 'Ingin mengobrol dengan ibu lain saat si kecil bermain di taman? Temukan tempat dengan kelompok bermain di Tempat Ramah Ibu dan bersosialisasilah.', title_ja = 'あなたにも友だちが必要です 👯‍♀️', body_ja = 'お子さんが公園で遊んでいる間、ほかのママとおしゃべりしたいですか？「ママにやさしいスポット」で遊びのグループがある施設を見つけて、交流を楽しみましょう。', title_ko = '엄마에게도 친구가 필요해요 👯‍♀️', body_ko = '아이가 공원에서 노는 동안 다른 엄마들과 이야기하고 싶나요? 엄마 친화 장소에서 놀이 모임이 있는 센터를 찾아 함께 어울려 보세요.', title_nl = 'Jij hebt ook vriendinnen nodig 👯‍♀️', body_nl = 'Wil je met andere moeders kletsen terwijl je kindje in het park speelt? Ontdek in Mamavriendelijke plekken centra met speelgroepjes en maak contact.', title_pl = 'Ty też potrzebujesz przyjaciółek 👯‍♀️', body_pl = 'Chcesz porozmawiać z innymi mamami, gdy maluch bawi się w parku? Odkryj w Miejscach przyjaznych mamom centra z grupami zabaw i poznawaj ludzi.', title_pt = 'Também precisa de amigas 👯‍♀️', body_pt = 'Enquanto ele brinca no parque, também quer conversar com outras mães? Descubra nos Locais Amigos das Mães centros com grupos de brincadeira e conviva.', title_sv = 'Du behöver också vänner 👯‍♀️', body_sv = 'Vill du också prata med andra mammor medan barnet leker i parken? Upptäck center med lekgrupper i Mammavänliga platser och umgås.', title_vi = 'Mẹ cũng cần bạn bè 👯‍♀️', body_vi = 'Mẹ muốn trò chuyện với các mẹ khác khi bé chơi ở công viên? Hãy khám phá các trung tâm có nhóm chơi trong Địa điểm thân thiện với mẹ và kết bạn nhé.', title_zh = '你也需要朋友 👯‍♀️', body_zh = '宝宝在公园玩的时候，你也想和其他妈妈聊聊天？在妈妈友好场所里发现有游戏小组的中心，去社交一下吧。' WHERE id = '47b68bdb-a1fd-4da7-9316-dcca5fdae94f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No le gusta beber agua? 💧', body_es = '¿El pañal de la mañana estaba muy seco? Hay que aumentar el aporte de líquidos. Anótalo en el Seguimiento de pañales y mira en la app recetas de agua con fruta y distintos modelos de vasos.', title_fr = 'Il n''aime pas l''eau ? 💧', body_fr = 'La couche du matin était très sèche ? Il faut augmenter ses apports en liquide. Notez-le dans le Suivi des couches et regardez dans l''appli les recettes d''eau aux fruits et différents modèles de gourdes.', title_hi = 'पानी पीना पसंद नहीं? 💧', body_hi = 'सुबह का डायपर बहुत सूखा था? तरल की ज़रूरत बढ़ानी होगी। डायपर ट्रैकर में दर्ज कीजिए और ऐप में फ्रूट वॉटर की रेसिपी और अलग-अलग तरह की सिपर बोतलें देखिए।', title_id = 'Tidak suka minum air? 💧', body_id = 'Popok paginya sangat kering? Kebutuhan cairannya perlu ditambah. Catat di Pelacak Popok, lalu lihat resep air buah dan berbagai model gelas minum di aplikasi.', title_ja = 'お水が苦手？💧', body_ja = '朝のおむつがとても乾いていましたか？水分を増やす必要があります。「おむつトラッカー」に記録して、アプリでフルーツウォーターのレシピやいろいろなマグをチェックしましょう。', title_ko = '물 마시기를 싫어하나요? 💧', body_ko = '아침 기저귀가 너무 말라 있었나요? 수분 섭취를 늘려야 해요. 기저귀 기록에 남기고, 앱에서 과일 물 레시피와 다양한 빨대컵을 살펴보세요.', title_nl = 'Drinkt hij niet graag water? 💧', body_nl = 'Was de ochtendluier erg droog? Dan heeft hij meer vocht nodig. Noteer het in de Luiertracker en bekijk in de app recepten voor fruitwater en verschillende drinkbekers.', title_pl = 'Nie lubi pić wody? 💧', body_pl = 'Poranna pieluszka była bardzo sucha? Trzeba zwiększyć ilość płynów. Zapisz to w narzędziu do śledzenia pieluszek i zajrzyj w aplikacji do przepisów na wodę z owocami i różnych modeli bidonów.', title_pt = 'Não gosta de beber água? 💧', body_pt = 'A fralda da manhã estava muito seca? É preciso aumentar a ingestão de líquidos. Registe-o no Registo de Fraldas e veja na app receitas de água com fruta e diferentes modelos de copos.', title_sv = 'Gillar inte att dricka vatten? 💧', body_sv = 'Var morgonblöjan väldigt torr? Vätskeintaget behöver öka. Anteckna i Blöjkollen och titta på recept för fruktvatten och olika pipmuggar i appen.', title_vi = 'Bé không thích uống nước? 💧', body_vi = 'Tã buổi sáng quá khô? Bé cần được uống thêm nước. Hãy ghi lại trong Theo dõi tã và xem công thức nước trái cây cùng các mẫu bình tập uống khác nhau trong ứng dụng.', title_zh = '不爱喝水？💧', body_zh = '早上的尿布很干？需要多补充水分。记在尿布记录里，再去应用里看看果味水食谱和各种不同的水杯款式。' WHERE id = 'aaf473f6-79bc-44cf-97f4-687dfa4eb293' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Huesos más fuertes! 🦴', body_es = 'Calcula con el Seguimiento de tomas si hoy ha tomado suficiente calcio y vitamina D. Estos dos elementos son inseparables para un desarrollo físico tan rápido.', title_fr = 'Des os plus solides ! 🦴', body_fr = 'Vérifiez avec le Suivi des repas s''il a eu assez de calcium et de vitamine D aujourd''hui. Ces deux éléments sont indissociables d''une croissance physique rapide.', title_hi = 'हड्डियाँ मज़बूत हो रही हैं! 🦴', body_hi = 'फ़ीडिंग ट्रैकर से देखिए कि आज उसे पर्याप्त कैल्शियम और विटामिन D मिला या नहीं। तेज़ शारीरिक विकास के लिए ये दोनों तत्व साथ-साथ ज़रूरी हैं।', title_id = 'Tulang makin kuat! 🦴', body_id = 'Hitung dengan alat Pemantau Nutrisi apakah hari ini ia sudah cukup mendapat kalsium dan vitamin D. Keduanya tak terpisahkan untuk pertumbuhan fisik yang pesat.', title_ja = '骨が強くなる！🦴', body_ja = '「栄養管理ツール」で、今日カルシウムとビタミンDを十分とれたか確認しましょう。急速な体の成長には、この2つが欠かせません。', title_ko = '뼈가 튼튼해져요! 🦴', body_ko = '수유 기록 도구로 오늘 칼슘과 비타민 D를 충분히 섭취했는지 확인하세요. 빠른 신체 발달에 이 두 가지는 꼭 필요해요.', title_nl = 'Sterkere botten! 🦴', body_nl = 'Bereken met de Voedingstracker of hij vandaag genoeg calcium en vitamine D heeft gehad. Deze twee zijn onmisbaar voor een snelle lichamelijke ontwikkeling.', title_pl = 'Kości stają się mocniejsze! 🦴', body_pl = 'Sprawdź w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco wapnia i witaminy D. Te dwa składniki są nieodzowne przy szybkim rozwoju fizycznym.', title_pt = 'Os ossos ficam mais fortes! 🦴', body_pt = 'Calcule com o Registo de Alimentação se hoje recebeu cálcio e vitamina D suficientes. Estes dois elementos são indispensáveis para um desenvolvimento físico rápido.', title_sv = 'Skelettet blir starkare! 🦴', body_sv = 'Räkna ut med Matningskoll om barnet fått tillräckligt med kalcium och D-vitamin i dag. Dessa två är oumbärliga för den snabba fysiska utvecklingen.', title_vi = 'Xương chắc khỏe hơn! 🦴', body_vi = 'Hãy dùng công cụ Theo dõi cữ bú để tính xem hôm nay bé đã nhận đủ canxi và vitamin D chưa. Hai dưỡng chất này không thể thiếu cho sự phát triển thể chất nhanh chóng.', title_zh = '骨骼越来越强壮！🦴', body_zh = '用喂养记录工具算一算宝宝今天是否摄入了足够的钙和维生素D。快速的身体发育离不开这两种营养素。' WHERE id = 'ff614b36-4091-473e-b7fa-91411bd4e2a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Es difícil que gaste toda su energía en casa. Busca en Lugares para mamás un centro de juegos seguro donde tú puedas tomar un café y él pueda correr.', body_fr = 'Difficile de lui faire dépenser son énergie à la maison. Trouvez dans les Lieux adaptés aux mamans une aire de jeux sûre où il pourra courir pendant que vous buvez un café.', body_hi = 'घर में ऊर्जा निकालना मुश्किल है। माँ के लिए अनुकूल जगहें में ऐसा सुरक्षित प्ले सेंटर ढूँढिए जहाँ आप कॉफ़ी पी सकें और वह दौड़ सके।', body_id = 'Sulit menyalurkan energinya di rumah. Temukan tempat bermain yang aman di Tempat Ramah Ibu, tempat Anda bisa minum kopi sementara ia berlarian.', body_ja = '家の中ではエネルギーを発散しにくいですよね。「ママにやさしいスポット」で、あなたはコーヒーを飲めて、お子さんは安全に走り回れる遊び場を見つけましょう。', body_ko = '집에서는 에너지를 다 쓰기 어렵죠. 엄마 친화 장소에서 엄마는 커피를 마시고 아이는 마음껏 뛰어놀 수 있는 안전한 놀이 센터를 찾아보세요.', body_nl = 'Energie kwijtraken in huis is lastig. Zoek in Mamavriendelijke plekken een veilig speelcentrum waar jij koffie kunt drinken en hij kan rennen.', body_pl = 'Trudno rozładować energię w domu. Znajdź w Miejscach przyjaznych mamom bezpieczną salę zabaw, gdzie ty napijesz się kawy, a on się wybiega.', body_pt = 'É difícil gastar energia em casa. Encontre nos Locais Amigos das Mães um espaço de brincar seguro onde a mãe pode beber um café e ele pode correr.', body_sv = 'Det är svårt att få ut energin hemma. Hitta en trygg lekplats i Mammavänliga platser där du kan dricka kaffe och barnet kan springa.', body_vi = 'Thật khó để bé xả năng lượng trong nhà. Hãy tìm trong Địa điểm thân thiện với mẹ một khu vui chơi an toàn, nơi mẹ có thể uống cà phê còn bé thì thỏa sức chạy nhảy.', body_zh = '在家里很难释放精力。在妈妈友好场所里找一个既能让你喝咖啡、又能让宝宝安全奔跑的游乐中心吧。' WHERE id = '0a81bd63-014b-4d25-b347-1808455aea49' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Desordenado, pero independiente! 🥣', body_es = '¿Insiste en comer solo? Pon el temporizador de tomas, sigue cuánto dura y anota cómo esta independencia favorece su motricidad fina.', title_fr = 'En désordre, mais autonome ! 🥣', body_fr = 'Il tient à manger tout seul ? Lancez le minuteur des repas, suivez la durée du repas et notez combien cette autonomie aide sa motricité fine.', title_hi = 'बिखरा हुआ, पर आज़ाद! 🥣', body_hi = 'खुद खाने की ज़िद करता है? फ़ीडिंग टाइमर चालू कीजिए, समय पर नज़र रखिए और दर्ज कीजिए कि यह आज़ादी उसकी बारीक मोटर स्किल्स के लिए कितनी फ़ायदेमंद है।', title_id = 'Berantakan, tapi mandiri! 🥣', body_id = 'Ia bersikeras makan sendiri? Nyalakan Timer Makan, pantau durasinya, dan catat bagaimana kemandirian ini bermanfaat bagi motorik halusnya.', title_ja = '散らかっても、自分でできる！🥣', body_ja = '自分で食べるとゆずらない？食事タイマーをオンにして時間を記録し、この自立が手先の発達にどう役立っているかメモしましょう。', title_ko = '엉망이어도 스스로! 🥣', body_ko = '혼자 먹겠다고 고집하나요? 수유 타이머를 켜서 시간을 재고, 이런 독립심이 소근육 발달에 얼마나 도움이 되는지 기록해 보세요.', title_nl = 'Rommelig, maar zelfstandig! 🥣', body_nl = 'Wil hij per se zelf eten? Zet de Voedingstimer aan, volg hoe lang het duurt en noteer hoe deze zelfstandigheid zijn fijne motoriek helpt.', title_pl = 'Bałagan, ale samodzielnie! 🥣', body_pl = 'Upiera się, że zje sam? Włącz timer karmienia, śledź, ile to trwa, i zanotuj, jak ta samodzielność wspiera jego motorykę małą.', title_pt = 'Desarrumado, mas independente! 🥣', body_pt = 'Insiste em comer sozinho? Ligue o temporizador de alimentação, acompanhe a duração e registe como esta independência beneficia a motricidade fina dele.', title_sv = 'Kladdigt, men självständigt! 🥣', body_sv = 'Insisterar barnet på att äta själv? Starta matningstimern, följ hur lång tid det tar och anteckna hur friheten gynnar finmotoriken.', title_vi = 'Bừa bộn nhưng tự lập! 🥣', body_vi = 'Bé nhất quyết tự ăn? Hãy bật Hẹn giờ cho bú, theo dõi thời gian và ghi lại sự tự lập này giúp ích thế nào cho kỹ năng vận động tinh của bé.', title_zh = '乱是乱，但很自由！🥣', body_zh = '坚持要自己吃饭？打开喂养计时器，记录用餐时长，并记下这种自主如何帮助宝宝锻炼精细动作。' WHERE id = '657f4585-c7bb-41c0-9574-51e8f943398b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelven los despertares nocturnos? ⏱️', body_es = 'Puede ser la regresión del sueño de los 20 meses. Mira el gráfico del temporizador de sueño y comprueba si es momento de acortar la siesta 15 minutos.', title_fr = 'Les réveils nocturnes sont de retour ? ⏱️', body_fr = 'C''est peut-être la régression du sommeil des 20 mois. Regardez le graphique du minuteur de sommeil et voyez s''il est temps de raccourcir la sieste de 15 minutes.', title_hi = 'रात में जागना फिर शुरू? ⏱️', body_hi = 'यह 20 महीने का स्लीप रिग्रेशन हो सकता है। स्लीप टाइमर का चार्ट देखिए और जाँचिए कि कहीं दिन की नींद 15 मिनट कम करने का समय तो नहीं आ गया।', title_id = 'Sering terbangun malam lagi? ⏱️', body_id = 'Mungkin ini regresi tidur usia 20 bulan. Lihat grafik Timer Tidur dan cek apakah sudah waktunya mengurangi tidur siang 15 menit.', title_ja = '夜中に起きるのが復活？⏱️', body_ja = '1歳8か月の睡眠退行かもしれません。睡眠タイマーのグラフを見て、お昼寝を15分短くするときが来ているか確認しましょう。', title_ko = '밤에 다시 깨나요? ⏱️', body_ko = '20개월 수면 퇴행일 수 있어요. 수면 타이머 그래프를 보고 낮잠을 15분 줄일 때가 되었는지 확인해 보세요.', title_nl = 'Wordt hij weer ''s nachts wakker? ⏱️', body_nl = 'Het kan de slaapregressie van 20 maanden zijn. Bekijk de grafiek van de Slaaptimer en kijk of het tijd is om het middagdutje met 15 minuten in te korten.', title_pl = 'Nocne pobudki wróciły? ⏱️', body_pl = 'To może być regres snu 20. miesiąca. Spójrz na wykres timera snu i sprawdź, czy nie czas skrócić drzemki o 15 minut.', title_pt = 'Os despertares noturnos voltaram? ⏱️', body_pt = 'Pode ser a regressão do sono dos 20 meses. Veja o gráfico do temporizador de sono e confirme se está na altura de encurtar a sesta 15 minutos.', title_sv = 'Nattliga uppvaknanden igen? ⏱️', body_sv = 'Det kan vara 20-månaders sömnregression. Titta på grafen i sömntimern och se om det är dags att korta dagsömnen med 15 minuter.', title_vi = 'Bé lại thức giấc ban đêm? ⏱️', body_vi = 'Có thể là giai đoạn thoái lui giấc ngủ 20 tháng. Hãy xem biểu đồ của Bộ hẹn giờ ngủ và kiểm tra xem đã đến lúc giảm giấc ngủ ngày 15 phút chưa.', title_zh = '夜醒又回来了？⏱️', body_zh = '可能是20个月的睡眠倒退。看看睡眠计时器的图表，确认是否到了把白天小睡减少15分钟的时候。' WHERE id = '7feaa5c7-f1f9-4df2-a08a-b9cef56c0ce4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te sientas culpable 📝', body_es = '¿Hoy has levantado un poco la voz? No te juzgues. Vuelca tus agobios en el Diario de ánimo y recuerda que no hay mejor madre que tú.', title_fr = 'Ne culpabilisez pas 📝', body_fr = 'Vous avez un peu haussé le ton aujourd''hui ? Ne vous le reprochez pas. Confiez vos tensions au Journal d''humeur et rappelez-vous qu''il n''existe pas de meilleure maman que vous.', title_hi = 'खुद को दोष मत दीजिए 📝', body_hi = 'आज आपकी आवाज़ थोड़ी ऊँची हो गई? खुद को कोसिए मत। मूड डायरी में मन की घुटन लिखिए और याद रखिए कि आपसे अच्छी माँ कोई नहीं है।', title_id = 'Jangan merasa bersalah 📝', body_id = 'Hari ini suara Anda sedikit meninggi? Jangan menyalahkan diri sendiri. Curahkan beban hati di Buku Harian Suasana Hati dan ingatlah bahwa tidak ada ibu yang lebih baik untuknya selain Anda.', title_ja = '罪悪感を持たないで 📝', body_ja = '今日は少し声を荒らげてしまいましたか？自分を責めないで。「気分日記」に心のもやもやを書き出して、あなたほどすてきなママはいないことを思い出しましょう。', title_ko = '죄책감은 내려놓으세요 📝', body_ko = '오늘 목소리가 조금 커졌나요? 자책하지 마세요. 기분 일기에 속상한 마음을 털어놓고, 그렇다고 좋은 엄마가 아닌 게 아니라는 걸 기억하세요.', title_nl = 'Voel je niet schuldig 📝', body_nl = 'Verhief je vandaag je stem een beetje? Veroordeel jezelf niet. Schrijf je zorgen van je af in je Stemmingsdagboek en onthoud dat er geen betere moeder is dan jij.', title_pl = 'Nie miej wyrzutów sumienia 📝', body_pl = 'Podniosłaś dziś trochę głos? Nie obwiniaj się. Wylej swoje troski w Dzienniku nastroju i pamiętaj, że nie ma lepszej mamy niż ty.', title_pt = 'Não se sinta culpada 📝', body_pt = 'Hoje levantou um pouco a voz? Não se culpe. Deixe sair as suas angústias no Diário de Humor e lembre-se de que não há mãe melhor do que a mãe.', title_sv = 'Känn inget dåligt samvete 📝', body_sv = 'Höjde du rösten lite i dag? Döm inte dig själv. Skriv av dig det som tynger dig i Humördagboken och påminn dig om att det inte finns någon bättre mamma än du.', title_vi = 'Đừng tự trách mình 📝', body_vi = 'Hôm nay mẹ lỡ to tiếng một chút? Đừng tự trách. Hãy trút những nỗi niềm vào Nhật ký tâm trạng và nhớ rằng không ai làm mẹ tốt hơn mẹ cả.', title_zh = '别内疚 📝', body_zh = '今天说话声音有点大了？别责怪自己。把心里的烦闷倒进心情日记，记住这并不代表你不是好妈妈。' WHERE id = '385a8205-8e28-4c23-94fa-a2a8fe32e28c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Frases de 2 palabras! 🗣️', body_es = '«Mamá, ven», «Dame pelota»: su vocabulario crece a toda velocidad. Añade enseguida estos dulces intentos de hablar en vídeo con sonido al Álbum del bebé y conviértelos en un recuerdo para siempre.', title_fr = 'Des phrases de 2 mots ! 🗣️', body_fr = '« Maman viens », « Donne ballon » : son vocabulaire grandit vite. Ajoutez tout de suite ces mignons essais en vidéo avec le son à l''Album de bébé pour en faire un souvenir pour la vie.', title_hi = '2 शब्दों वाले वाक्य! 🗣️', body_hi = '''माँ आओ'', ''गेंद दो'' - उसका शब्द भंडार तेज़ी से बढ़ रहा है। बोलने की इन प्यारी कोशिशों को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़िए और उम्रभर की याद बनाइए।', title_id = 'Kalimat 2 kata! 🗣️', body_id = 'Mama sini, Minta bola, kosakatanya bertambah pesat. Segera simpan usaha bicaranya yang manis ini sebagai video bersuara di Album Bayi dan jadikan kenangan seumur hidup.', title_ja = '2語文！🗣️', body_ja = '「ママきて」「ボールちょうだい」語彙がどんどん増えています。このかわいいおしゃべりの挑戦を、すぐに音声付きの動画で「ベビーアルバム」に追加して、一生の思い出にしましょう。', title_ko = '두 단어 문장! 🗣️', body_ko = '''엄마 와'', ''공 줘'', 어휘가 쑥쑥 늘고 있어요. 이 귀여운 말하기 시도를 소리가 담긴 영상으로 바로 아기 앨범에 올려 평생의 추억으로 만드세요.', title_nl = 'Zinnetjes van 2 woorden! 🗣️', body_nl = 'Mama kom, bal geven: zijn woordenschat groeit snel. Voeg deze lieve praatpogingen meteen als video met geluid toe aan het Babyalbum en maak er een herinnering voor altijd van.', title_pl = 'Zdania z 2 słów! 🗣️', body_pl = '„Mama, chodź”, „Daj piłkę”: jego słownik szybko rośnie. Od razu dodaj te słodkie próby mówienia jako film z dźwiękiem do Albumu dziecka i zachowaj je na zawsze.', title_pt = 'Frases de 2 palavras! 🗣️', body_pt = '"Mamã, vem", "Dá bola": o vocabulário cresce depressa. Adicione já estas tentativas tão doces em vídeo com som ao Álbum do Bebé e transforme-as numa recordação para a vida.', title_sv = 'Meningar med 2 ord! 🗣️', body_sv = '”Mamma kom”, ”Ge boll”: ordförrådet växer snabbt. Spela in de söta pratförsöken som video med ljud, lägg dem direkt i Babyalbumet och gör dem till ett minne för livet.', title_vi = 'Câu hai từ! 🗣️', body_vi = '"Mẹ ơi lại đây", "Đưa bóng": vốn từ của bé tăng nhanh chóng. Hãy quay video có tiếng những lần tập nói đáng yêu này và thêm ngay vào Album của bé để làm kỷ niệm trọn đời.', title_zh = '两个词的句子！🗣️', body_zh = '“妈妈来”“给球球”，词汇量增长飞快。马上把这些可爱的说话尝试录成有声视频加进宝宝相册，变成一生的回忆。' WHERE id = '49b18c8f-b30b-4368-9445-6af88b1d8115' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calcio para los huesos 🦴', body_es = 'Un peque que corre tanto necesita huesos fuertes. Comprueba en el Seguimiento de tomas el calcio de hoy (queso, yogur) y completa lo que falte.', title_fr = 'Du calcium pour les os 🦴', body_fr = 'Un petit qui court beaucoup a besoin d''os solides. Vérifiez dans le Suivi des repas son calcium du jour (fromage, yaourt) et complétez ce qui manque.', title_hi = 'हड्डियों के लिए कैल्शियम 🦴', body_hi = 'खूब दौड़ने वाले नन्हे की हड्डियाँ मज़बूत होनी चाहिए। फ़ीडिंग ट्रैकर में आज का कैल्शियम (पनीर, दही) जाँचिए और मात्रा पूरी कीजिए।', title_id = 'Kalsium untuk tulang 🦴', body_id = 'Si kecil yang banyak berlari butuh tulang yang kuat. Cek asupan kalsium hari ini (keju, yogurt) di alat Pemantau Nutrisi dan lengkapi kebutuhannya.', title_ja = '骨のためのカルシウム 🦴', body_ja = 'よく走り回る子には、丈夫な骨が必要です。「栄養管理ツール」で今日のカルシウム（チーズ、ヨーグルト）の摂取量を確認して、目安を満たしましょう。', title_ko = '뼈를 위한 칼슘 🦴', body_ko = '많이 뛰어노는 아이는 뼈가 튼튼해야 해요. 수유 기록 도구로 오늘 칼슘(치즈, 요거트) 섭취를 확인하고 기준량을 채워 주세요.', title_nl = 'Calcium voor de botten 🦴', body_nl = 'Een kleintje dat veel rent, heeft sterke botten nodig. Controleer in de Voedingstracker de calcium van vandaag (kaas, yoghurt) en vul aan tot de norm.', title_pl = 'Wapń dla kości 🦴', body_pl = 'Maluch, który dużo biega, potrzebuje mocnych kości. Sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie wapnia (ser, jogurt) i uzupełnij normę.', title_pt = 'Cálcio para os ossos 🦴', body_pt = 'Um pequenino que corre tanto precisa de ossos fortes. Verifique no Registo de Alimentação o cálcio de hoje (queijo, iogurte) e complete a dose recomendada.', title_sv = 'Kalcium för skelettet 🦴', body_sv = 'Ett barn som springer mycket behöver starka ben. Kontrollera dagens kalciumintag (ost, yoghurt) i Matningskoll och fyll på upp till normen.', title_vi = 'Canxi cho xương 🦴', body_vi = 'Bé chạy nhảy nhiều cần có bộ xương chắc khỏe. Hãy kiểm tra lượng canxi (phô mai, sữa chua) hôm nay trong Theo dõi cữ bú và bổ sung cho đủ định mức.', title_zh = '为骨骼补钙 🦴', body_zh = '跑个不停的小家伙需要强壮的骨骼。在喂养记录工具里查看今天的钙（奶酪、酸奶）摄入量，补足参考量。' WHERE id = '5d516faa-7c77-4db9-b201-49bff969e3d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de vestirse solo 👕', body_es = '¿Ha empezado la tozudez del «¡No quiero esta camiseta!»? Pregunta a Anacan AI cómo reducir las batallas de ropa por la mañana y darle libertad para elegir.', title_fr = 'La bataille de l''habillage 👕', body_fr = 'La période « Je ne veux pas ce t-shirt ! » a commencé ? Demandez à Anacan AI comment réduire les crises d''habillage du matin et lui laisser le droit de choisir.', title_hi = 'खुद कपड़े पहनने की जंग 👕', body_hi = '''यह कमीज़ नहीं चाहिए!'' वाली ज़िद शुरू हो गई? सुबह कपड़ों के झगड़े कम करने और उसे अपनी पसंद चुनने का मौका देने के तरीके Anacan AI से पूछिए।', title_id = 'Perang ingin berpakaian sendiri 👕', body_id = 'Aku tidak mau baju ini! Masa keras kepala sudah dimulai? Tanyakan kepada Anacan AI cara mengurangi drama berpakaian di pagi hari dan memberinya hak memilih.', title_ja = '自分で着たい！の攻防 👕', body_ja = '「このシャツはいや！」というこだわりが始まりましたか？朝の着替えのかんしゃくを減らし、自分で選ぶ機会をあげる方法を、Anacan AIに聞いてみましょう。', title_ko = '혼자 입겠다는 전쟁 👕', body_ko = '''이 옷 싫어!'' 고집이 시작됐나요? 아침 옷 입기 전쟁을 줄이고 스스로 고를 기회를 주는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Strijd om zelf aankleden 👕', body_nl = 'Begint het ik wil dit shirt niet!-gedoe? Vraag Anacan AI hoe je de ochtendstrijd om kleding vermindert en hem vrij laat kiezen.', title_pl = 'Walka o samodzielne ubieranie 👕', body_pl = 'Zaczął się upór w stylu „Nie chcę tej koszulki!”? Zapytaj Anacan AI, jak ograniczyć poranne kryzysy przy ubieraniu i dać mu prawo do samodzielnego wyboru.', title_pt = 'A batalha de se vestir sozinho 👕', body_pt = 'Começou a teimosia do "Não quero esta camisola!"? Pergunte ao Anacan AI como reduzir as crises da roupa de manhã e dar-lhe liberdade de escolha.', title_sv = 'Kampen om att klä på sig själv 👕', body_sv = 'Har envisheten ”Jag vill inte ha den här tröjan!” börjat? Fråga Anacan AI hur du kan minska morgonens klädbråk och ge barnet frihet att välja.', title_vi = 'Cuộc chiến tự mặc đồ 👕', body_vi = 'Bé bắt đầu bướng bỉnh "Con không thích áo này!"? Hãy hỏi Anacan AI cách giảm những cuộc chiến quần áo buổi sáng và cho bé quyền tự chọn.', title_zh = '自己穿衣服之战 👕', body_zh = '开始“我不要这件衣服！”的倔强了？问问Anacan AI，如何减少早上穿衣时的冲突，并给宝宝自由选择的权利。' WHERE id = '3b603489-95c3-4a32-b0e0-5191fc844b75' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de omega-3 🐟', body_es = 'El desarrollo del cerebro no se detiene. Comprueba en el Seguimiento de tomas si esta semana ha comido suficiente pescado o nueces y, si falta, anótalo sin falta.', title_fr = 'Réserve d''oméga-3 🐟', body_fr = 'Le cerveau ne cesse de se développer. Vérifiez dans le Suivi des repas s''il a mangé assez de poisson ou de noix cette semaine, et notez absolument tout manque.', title_hi = 'ओमेगा-3 का भंडार 🐟', body_hi = 'दिमाग का विकास रुकता नहीं। फ़ीडिंग ट्रैकर में देखिए कि इस हफ़्ते उसने पर्याप्त मछली या अखरोट खाए या नहीं, कमी हो तो ज़रूर दर्ज कीजिए।', title_id = 'Cadangan omega-3 🐟', body_id = 'Perkembangan otak terus berjalan. Cek di alat Pemantau Nutrisi apakah minggu ini ia cukup makan ikan atau kenari, dan catat jika ada kekurangan.', title_ja = 'オメガ3はとれている？🐟', body_ja = '脳の発達は止まりません。「栄養管理ツール」で、今週お魚やくるみを十分とれたか確認し、足りなければ必ず記録しましょう。', title_ko = '오메가3 채우기 🐟', body_ko = '뇌 발달은 멈추지 않아요. 수유 기록 도구로 이번 주에 생선이나 호두를 충분히 먹었는지 확인하고, 부족하다면 꼭 기록해 두세요.', title_nl = 'Omega-3-voorraad 🐟', body_nl = 'De hersenontwikkeling gaat door. Controleer in de Voedingstracker of hij deze week genoeg vis of walnoten heeft gehad, en noteer het zeker als er een tekort is.', title_pl = 'Zapas omega-3 🐟', body_pl = 'Mózg nie przestaje się rozwijać. Sprawdź w narzędziu do śledzenia karmienia, czy w tym tygodniu zjadł wystarczająco ryb lub orzechów, a jeśli czegoś brakuje, koniecznie to zanotuj.', title_pt = 'Reserva de ómega-3 🐟', body_pt = 'O desenvolvimento do cérebro não para. Verifique no Registo de Alimentação se esta semana comeu peixe ou nozes suficientes e, se faltar, registe-o sem falta.', title_sv = 'Påfyllning av omega-3 🐟', body_sv = 'Hjärnans utveckling tar ingen paus. Kontrollera i Matningskoll om barnet ätit tillräckligt med fisk eller nötter den här veckan och anteckna det om något fattas.', title_vi = 'Nguồn omega-3 🐟', body_vi = 'Não bộ không ngừng phát triển. Hãy kiểm tra trong Theo dõi cữ bú xem tuần này bé đã ăn đủ cá hoặc óc chó chưa, nếu thiếu thì nhất định ghi lại nhé.', title_zh = '补充欧米伽-3 🐟', body_zh = '大脑发育从不停歇。在喂养记录工具里看看宝宝这周是否吃了足够的鱼或核桃，如有不足一定要记下来。' WHERE id = '89933e6a-484e-4f2e-bf20-8262f6a74c72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo quemar energía en casa? 🏃‍♂️', body_es = '¿No podéis salir? Mira en Productos recomendados minicamas elásticas o toboganes para interior y canaliza su energía.', title_fr = 'Comment dépenser son énergie à la maison ? 🏃‍♂️', body_fr = 'Impossible de sortir ? Canalisez son énergie avec un mini-trampoline ou un toboggan d''intérieur, à découvrir dans les Produits recommandés.', title_hi = 'घर में ऊर्जा कैसे निकालें? 🏃‍♂️', body_hi = 'बाहर नहीं जा पा रहीं? सुझाए गए प्रोडक्ट में घर के अंदर के लिए बने मिनी ट्रैम्पोलिन या स्लाइड देखिए और उसकी ऊर्जा को सही दिशा दीजिए।', title_id = 'Bagaimana menyalurkan energi di rumah? 🏃‍♂️', body_id = 'Tidak bisa keluar rumah? Lihat trampolin mini atau perosotan untuk dalam ruangan di Produk Rekomendasi dan salurkan energinya ke arah yang tepat.', title_ja = '家の中でどうエネルギーを発散する？🏃‍♂️', body_ja = '外に出られませんか？「おすすめ商品」で室内用のミニトランポリンやすべり台をチェックして、エネルギーを上手に発散させましょう。', title_ko = '집에서 에너지를 어떻게 발산할까요? 🏃‍♂️', body_ko = '밖에 나갈 수 없나요? 추천 제품에서 실내용 미니 트램펄린이나 미끄럼틀을 살펴보고 에너지를 즐겁게 쓰게 해 주세요.', title_nl = 'Energie kwijt in huis? 🏃‍♂️', body_nl = 'Kun je niet naar buiten? Bekijk in Aanbevolen producten mini-trampolines of glijbanen voor binnen en geef zijn energie een doel.', title_pl = 'Jak rozładować energię w domu? 🏃‍♂️', body_pl = 'Nie możecie wyjść na dwór? Zajrzyj w Polecanych produktach do mini trampolin lub zjeżdżalni do domu i skieruj jego energię we właściwą stronę.', title_pt = 'Como gastar energia em casa? 🏃‍♂️', body_pt = 'Não podem sair? Veja nos Produtos Recomendados mini trampolins ou escorregas para interior e canalize a energia dele.', title_sv = 'Hur får man ut energin inomhus? 🏃‍♂️', body_sv = 'Kan ni inte gå ut? Titta på minitrampoliner eller rutschkanor för inomhusbruk i Rekommenderade produkter och styr energin rätt.', title_vi = 'Giải phóng năng lượng trong nhà thế nào? 🏃‍♂️', body_vi = 'Không thể ra ngoài? Hãy xem bạt nhún mini hoặc cầu trượt dành cho trong nhà ở Sản phẩm gợi ý để bé xả năng lượng đúng chỗ.', title_zh = '在家怎么释放精力？🏃‍♂️', body_zh = '出不了门？去推荐商品看看室内用的迷你蹦床或滑梯，把宝宝的精力引到正确的地方。' WHERE id = 'fa46cf0a-85f0-484c-8aa5-b60eb52b320b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de la sorpresa matutina 🧻', body_es = '¿Hay más pañales secos o la digestión va más lenta? Anota el cambio de la mañana en el Seguimiento de pañales y analiza al momento sus necesidades de líquido y fibra.', title_fr = 'Contrôle surprise du matin 🧻', body_fr = 'Plus de couches sèches ou une digestion qui ralentit ? Notez le change du matin dans le Suivi des couches et analysez tout de suite ses besoins en liquide et en fibres.', title_hi = 'सुबह के सरप्राइज़ की जाँच 🧻', body_hi = 'सूखे डायपर बढ़ रहे हैं या पाचन धीमा है? सुबह डायपर बदलना डायपर ट्रैकर में दर्ज कीजिए और नन्हे की तरल और फ़ाइबर की ज़रूरत तुरंत समझिए।', title_id = 'Cek kejutan pagi 🧻', body_id = 'Popok kering makin sering, atau pencernaannya melambat? Catat ganti popok pagi di Pelacak Popok dan langsung analisis kebutuhan cairan dan serat si kecil.', title_ja = '朝のおむつチェック 🧻', body_ja = '乾いたおむつが増えていますか？それとも消化がゆっくりに？朝のおむつ替えを「おむつトラッカー」に記録して、水分と食物繊維が足りているかすぐに分析しましょう。', title_ko = '아침 기저귀 확인 🧻', body_ko = '마른 기저귀가 늘었나요, 아니면 소화가 느려졌나요? 아침 기저귀 교체를 기저귀 기록에 남겨 아이의 수분과 섬유질 필요량을 바로 확인하세요.', title_nl = 'Ochtendverrassing checken 🧻', body_nl = 'Meer droge luiers, of gaat de spijsvertering trager? Noteer de ochtendwissel in de Luiertracker en zie meteen hoeveel vocht en vezels je kleintje nodig heeft.', title_pl = 'Poranna kontrola niespodzianki 🧻', body_pl = 'Coraz więcej suchych pieluszek, a może trawienie zwalnia? Zapisz poranną zmianę w narzędziu do śledzenia pieluszek i od razu sprawdź, ile płynów i błonnika potrzebuje maluch.', title_pt = 'A surpresa da manhã 🧻', body_pt = 'Há mais fraldas secas ou a digestão está mais lenta? Registe a muda da manhã no Registo de Fraldas e analise logo as necessidades de líquidos e fibra do pequenino.', title_sv = 'Morgonens överraskningskoll 🧻', body_sv = 'Blir blöjorna torrare, eller går matsmältningen långsamt? Anteckna morgonbytet i Blöjkollen och analysera direkt barnets behov av vätska och fibrer.', title_vi = 'Kiểm tra "bất ngờ" buổi sáng 🧻', body_vi = 'Tã khô nhiều hơn hay tiêu hóa chậm lại? Hãy ghi lần thay tã buổi sáng vào Theo dõi tã để phân tích ngay nhu cầu nước và chất xơ của bé.', title_zh = '早晨惊喜检查 🧻', body_zh = '干尿布越来越多，还是消化变慢了？把早上换尿布的情况记在尿布记录里，马上分析小家伙对水分和纤维的需求。' WHERE id = '00691751-d785-4fc6-8036-d313adccdad6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ahora toca descansar 🍵', body_es = '¡Se acabó el ajetreo! Prepárate una bebida de Recetas saludables, túmbate en el sofá y disfruta del silencio.', title_fr = 'C''est l''heure de souffler 🍵', body_fr = 'La course est terminée ! Préparez une boisson avec les Recettes saines, allongez-vous sur le canapé et savourez simplement le silence.', title_hi = 'अब आराम का समय है 🍵', body_hi = 'भागदौड़ खत्म! सेहतमंद रेसिपी से कोई ड्रिंक बनाइए, सोफ़े पर लेटिए और बस खामोशी का मज़ा लीजिए।', title_id = 'Sekarang waktunya istirahat 🍵', body_id = 'Kejar-kejaran sudah selesai! Buat minuman dari Resep Sehat, berbaring di sofa, dan nikmati keheningan.', title_ja = '今は休む時間です 🍵', body_ja = '追いかけっこはおしまい！「ヘルシーレシピ」からドリンクをつくって、ソファに横になり、静けさだけを味わいましょう。', title_ko = '이제 쉴 시간이에요 🍵', body_ko = '정신없던 하루가 끝났어요! 건강한 레시피에서 음료를 만들어 소파에 누워 오직 고요함만 즐기세요.', title_nl = 'Nu is het tijd om te rusten 🍵', body_nl = 'Het rennen en vliegen is voorbij! Maak een drankje uit Gezonde recepten, ga op de bank liggen en geniet gewoon van de stilte.', title_pl = 'Teraz czas odpocząć 🍵', body_pl = 'Bieganina skończona! Przygotuj napój ze Zdrowych przepisów, połóż się na kanapie i po prostu delektuj się ciszą.', title_pt = 'Agora é hora de descansar 🍵', body_pt = 'A correria acabou! Prepare uma bebida das Receitas Saudáveis, deite-se no sofá e saboreie apenas o silêncio.', title_sv = 'Nu är det dags att vila 🍵', body_sv = 'Springet är över! Gör en dryck från Hälsosamma recept, lägg dig på soffan och njut bara av tystnaden.', title_vi = 'Giờ là lúc nghỉ ngơi 🍵', body_vi = 'Chạy nhảy xong rồi! Hãy pha một thức uống từ Công thức lành mạnh, nằm dài trên sofa và tận hưởng sự yên tĩnh.', title_zh = '现在是休息时间 🍵', body_zh = '追来跑去终于结束了！从健康食谱里做一杯饮品，躺在沙发上，好好享受这份安静。' WHERE id = '0bde6683-6d18-4d98-bc39-b122396c0b17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los gritos de «¡Es mío!» 🧸', body_es = '¿En el parque le quita los juguetes a otros niños? Aprende con Anacan AI las estrategias psicológicas más eficaces para gestionar las crisis egocéntricas de esta edad.', title_fr = 'Les cris de « C''est à moi ! » 🧸', body_fr = 'Il prend les jouets des autres au parc ? Découvrez avec Anacan AI les approches psychologiques les plus efficaces pour gérer les crises égocentriques de cet âge.', title_hi = '''मेरा है!'' की चीखें 🧸', body_hi = 'पार्क में दूसरों के हाथ से खिलौना छीन लेता है? इस उम्र के ''सब मेरा'' वाले दौर को संभालने के सबसे असरदार मनोवैज्ञानिक तरीके Anacan AI से जानिए।', title_id = 'Teriakan Punyaku! 🧸', body_id = 'Ia merebut mainan anak lain di taman? Pelajari strategi psikologis paling efektif dari Anacan AI untuk menghadapi fase egosentris di usia ini.', title_ja = '「ぼくの！」「わたしの！」の叫び 🧸', body_ja = '公園でほかの子のおもちゃを取り上げてしまいますか？この年齢特有の自己中心的なかんしゃくに対応する、いちばん効果的な心理的アプローチをAnacan AIで学びましょう。', title_ko = '''내 거야!'' 외침 🧸', body_ko = '공원에서 다른 아이의 장난감을 빼앗나요? 이 시기의 자기중심적인 떼쓰기를 다루는 가장 효과적인 심리 요령을 Anacan AI에게 배워 보세요.', title_nl = 'Van mij!-geschreeuw 🧸', body_nl = 'Pakt hij in het park speelgoed van anderen af? Leer bij Anacan AI de beste psychologische trucs om de egocentrische buien van deze leeftijd aan te pakken.', title_pl = 'Krzyki „Moje!” 🧸', body_pl = 'W parku zabiera zabawki innym dzieciom? Poznaj od Anacan AI najskuteczniejsze psychologiczne sposoby radzenia sobie z egocentrycznymi kryzysami w tym wieku.', title_pt = 'Os gritos de "É meu!" 🧸', body_pt = 'No parque tira os brinquedos às outras crianças? Aprenda com o Anacan AI as estratégias psicológicas mais eficazes para gerir as crises egocêntricas desta idade.', title_sv = 'Skrik om ”Min!” 🧸', body_sv = 'Tar barnet andras leksaker i parken? Lär dig de mest effektiva psykologiska knepen från Anacan AI för att hantera den här ålderns egocentriska utbrott.', title_vi = 'Những tiếng hét "Của con!" 🧸', body_vi = 'Bé giật đồ chơi của bạn khác ở công viên? Hãy học từ Anacan AI những cách tâm lý hiệu quả nhất để xử lý giai đoạn vị kỷ của lứa tuổi này.', title_zh = '“是我的！”的尖叫 🧸', body_zh = '在公园抢别的小朋友的玩具？向Anacan AI学习应对这个年龄自我中心式崩溃的最有效心理技巧。' WHERE id = '0eecf770-9ba2-463c-9b39-bbe24d01b4e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cuánto tarda en dormirse? ⏱️', body_es = '¿Da muchas vueltas en la cama? Activa el temporizador de sueño y anota cuánto tarda en dormirse. Quizá haya que terminar antes los juegos de la tarde.', title_fr = 'Combien de temps pour s''endormir ? ⏱️', body_fr = 'Il se tourne et se retourne dans son lit ? Activez le minuteur de sommeil et notez le temps d''endormissement. Il faudrait peut-être finir les jeux du soir plus tôt.', title_hi = 'सोने में कितना समय लगता है? ⏱️', body_hi = 'बिस्तर पर बहुत करवटें बदलता है? स्लीप टाइमर चालू करके सोने में लगने वाला समय दर्ज कीजिए। शायद शाम के खेल थोड़ा जल्दी खत्म करने होंगे।', title_id = 'Berapa lama ia tertidur? ⏱️', body_id = 'Banyak berguling di tempat tidur? Aktifkan Timer Tidur dan catat berapa lama ia butuh untuk terlelap. Mungkin permainan sore perlu diakhiri lebih awal.', title_ja = '寝つくまでどれくらいかかる？⏱️', body_ja = 'ベッドでごろごろ寝返りばかり？睡眠タイマーをオンにして、眠りにつくまでの時間を記録しましょう。夜の遊びをもう少し早めに切り上げる必要があるかもしれません。', title_ko = '잠드는 데 얼마나 걸리나요? ⏱️', body_ko = '침대에서 계속 뒤척이나요? 수면 타이머를 켜고 잠들기까지 걸리는 시간을 기록하세요. 저녁 놀이를 더 일찍 끝내야 할지도 몰라요.', title_nl = 'Hoe lang duurt het inslapen? ⏱️', body_nl = 'Draait hij veel rond in bed? Zet de Slaaptimer aan en noteer hoe lang het inslapen duurt. Misschien moeten de avondspelletjes eerder stoppen.', title_pl = 'Ile trwa zasypianie? ⏱️', body_pl = 'Długo wierci się w łóżku? Włącz timer snu i zapisz, ile trwa zasypianie. Może wieczorne zabawy trzeba kończyć wcześniej.', title_pt = 'Quanto tempo demora a adormecer? ⏱️', body_pt = 'Dá muitas voltas na cama? Ative o temporizador de sono e registe quanto tempo demora a adormecer. Talvez seja preciso acabar mais cedo as brincadeiras da noite.', title_sv = 'Hur lång tid tar det att somna? ⏱️', body_sv = 'Vrider sig barnet mycket i sängen? Aktivera sömntimern och anteckna hur lång tid det tar att somna. Kanske behöver kvällslekarna avslutas tidigare.', title_vi = 'Bé mất bao lâu để ngủ? ⏱️', body_vi = 'Bé trằn trọc mãi trên giường? Hãy bật Bộ hẹn giờ ngủ và ghi lại thời gian bé chìm vào giấc ngủ. Có lẽ nên kết thúc các trò chơi buổi tối sớm hơn.', title_zh = '入睡要多久？⏱️', body_zh = '在床上翻来覆去？启动睡眠计时器，记录入睡所需的时间。也许晚上的游戏需要早点结束。' WHERE id = '68ef19de-c144-4be9-8878-9cc1b34a6483' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué llora de repente? 🤖', body_es = '¿Se despierta gritando por la noche y no se calma? Escribe enseguida tus dudas sobre los terrores nocturnos al experto Anacan AI y aprende los pasos correctos.', title_fr = 'Pourquoi pleure-t-il soudain ? 🤖', body_fr = 'Il se réveille la nuit en hurlant et ne se calme pas ? Écrivez tout de suite à l''expert Anacan AI vos doutes sur les terreurs nocturnes et découvrez les bons gestes.', title_hi = 'अचानक क्यों रोता है? 🤖', body_hi = 'रात को चीखकर जागता है और शांत नहीं होता? नाइट टेरर को लेकर अपनी शंकाएँ तुरंत Anacan AI एक्सपर्ट को लिखिए और सही कदम जानिए।', title_id = 'Kenapa tiba-tiba menangis? 🤖', body_id = 'Terbangun malam sambil menjerit dan tak bisa ditenangkan? Segera tulis kekhawatiran Anda soal teror malam (night terror) kepada ahli Anacan AI dan pelajari langkah yang tepat.', title_ja = 'どうして急に泣くの？🤖', body_ja = '夜中に叫んで起きて、泣き止まない？夜驚症かもと気になったら、すぐにAnacan AIのエキスパートに書き込んで、正しい対応を学びましょう。', title_ko = '왜 갑자기 울까요? 🤖', body_ko = '밤에 비명을 지르며 깨고 진정이 안 되나요? 야경증이 걱정된다면 바로 Anacan AI 전문가에게 물어보고 올바른 대처법을 알아보세요.', title_nl = 'Waarom huilt hij ineens? 🤖', body_nl = 'Wordt hij ''s nachts gillend wakker en is hij niet te troosten? Schrijf je vermoedens over nachtangst meteen aan de Anacan AI-expert en leer de juiste stappen.', title_pl = 'Dlaczego nagle płacze? 🤖', body_pl = 'Budzi się w nocy z krzykiem i nie daje się uspokoić? Od razu napisz o swoich podejrzeniach dotyczących lęków nocnych do eksperta Anacan AI i poznaj właściwe kroki.', title_pt = 'Porque chora de repente? 🤖', body_pt = 'Acorda de noite aos gritos e não se acalma? Escreva já as suas dúvidas sobre terrores noturnos ao especialista Anacan AI e saiba quais os passos certos.', title_sv = 'Varför gråter barnet plötsligt? 🤖', body_sv = 'Vaknar barnet skrikande på natten och går inte att lugna? Skriv direkt till experten Anacan AI om dina misstankar om nattskräck och lär dig rätt steg.', title_vi = 'Vì sao bé bỗng dưng khóc? 🤖', body_vi = 'Bé thét lên thức giấc giữa đêm và không chịu dịu lại? Hãy viết ngay những nghi ngờ về chứng hoảng sợ ban đêm cho chuyên gia Anacan AI để biết cách xử lý đúng.', title_zh = '为什么突然大哭？🤖', body_zh = '夜里尖叫着醒来，怎么也安抚不下来？马上把你对夜惊的疑虑写给Anacan AI专家，了解正确的做法。' WHERE id = '70a3e410-6335-466b-99bc-28ac0c3d913f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuente de energía de mamá 🥗', body_es = '¿Estás agotada de correr detrás de tu peque? ¡Apuesta por las proteínas, no por los dulces! Prepara en Recetas saludables para mujeres un batido de crema de cacahuete que da energía al instante.', title_fr = 'La source d''énergie de maman 🥗', body_fr = 'Épuisée à force de courir ? Misez sur les protéines plutôt que sur le sucre ! Préparez un smoothie au beurre de cacahuète, énergisant en un instant, avec les Recettes saines pour femmes.', title_hi = 'माँ की ताकत का स्रोत 🥗', body_hi = 'भागदौड़ से थककर चूर हैं? मिठाई नहीं, प्रोटीन चुनिए! महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ऊर्जा देने वाली पीनट बटर स्मूदी बनाइए।', title_id = 'Sumber tenaga Bunda 🥗', body_id = 'Kehabisan tenaga karena terus berlari? Pilih protein, bukan manisan! Buat smoothie selai kacang yang langsung memberi energi dari Resep Sehat untuk wanita.', title_ja = 'ママのパワーの源 🥗', body_ja = '追いかけ回して、くたくたですか？甘いものではなく、たんぱく質を！「女性のためのヘルシーレシピ」から、すぐに元気が出るピーナッツバタースムージーをつくりましょう。', title_ko = '엄마의 에너지원 🥗', body_ko = '쫓아다니느라 기운이 다 빠졌나요? 단 음식 말고 단백질을 챙기세요! 여성을 위한 건강한 레시피에서 바로 힘이 나는 땅콩버터 스무디를 만들어 보세요.', title_nl = 'Krachtbron van mama 🥗', body_nl = 'Ben je uitgeput van het achter hem aan rennen? Kies niet voor snoep, maar voor eiwit! Maak uit Gezonde recepten voor vrouwen een smoothie met pindakaas die je meteen energie geeft.', title_pl = 'Źródło siły mamy 🥗', body_pl = 'Opadasz z sił od ciągłej bieganiny? Zamiast słodyczy postaw na białko! Przygotuj ze Zdrowych przepisów dla kobiet smoothie z masłem orzechowym, które od razu doda energii.', title_pt = 'A fonte de força da mãe 🥗', body_pt = 'Está sem forças de tanto correr? Aposte na proteína, não nos doces! Prepare nas Receitas Saudáveis para Mulheres um batido de manteiga de amendoim que dá energia na hora.', title_sv = 'Mammas kraftkälla 🥗', body_sv = 'Helt slut efter allt springande? Satsa på protein, inte godis! Gör en smoothie med jordnötssmör som ger energi direkt från Hälsosamma recept för kvinnor.', title_vi = 'Nguồn sức mạnh của mẹ 🥗', body_vi = 'Chạy theo bé đến kiệt sức? Đừng tìm đến đồ ngọt mà hãy chọn đạm! Làm ngay món sinh tố bơ đậu phộng tiếp năng lượng tức thì từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的能量来源 🥗', body_zh = '跑得筋疲力尽了？别找甜食，多补充蛋白质！从女性健康食谱里做一杯立刻补充能量的花生酱奶昔。' WHERE id = '80e71246-05ae-4bc6-857d-5ce3af704b5e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Felicítate! 🌟', body_es = '¿Hoy has conseguido darle de comer sin lágrimas? Escribe hasta tu logro más pequeño en el Diario de ánimo y aplaude tu talento como madre.', title_fr = 'Félicitez-vous ! 🌟', body_fr = 'Vous avez réussi à le faire manger sans pleurs aujourd''hui ? Notez même votre plus petite réussite dans le Journal d''humeur et applaudissez debout vos talents de maman.', title_hi = 'खुद की तारीफ़ कीजिए! 🌟', body_hi = 'आज उसे बिना रुलाए खाना खिला पाईं? मूड डायरी में अपनी छोटी से छोटी सफलता भी लिखिए और अपनी माँ होने की काबिलियत के लिए खुद को शाबाशी दीजिए।', title_id = 'Puji diri Anda! 🌟', body_id = 'Hari ini berhasil menyuapinya tanpa tangisan? Tulis keberhasilan sekecil apa pun di Buku Harian Suasana Hati dan beri tepuk tangan untuk kemampuan Anda sebagai ibu.', title_ja = '自分を褒めてあげて！🌟', body_ja = '今日は泣かせずにごはんを食べさせられましたか？「気分日記」にどんな小さな成功も書いて、ママとしての自分にスタンディングオベーションを送りましょう。', title_ko = '스스로를 칭찬하세요! 🌟', body_ko = '오늘 울리지 않고 밥을 먹였나요? 기분 일기에 아주 작은 성공이라도 적고, 엄마로서의 능력에 기립 박수를 보내 주세요.', title_nl = 'Geef jezelf een compliment! 🌟', body_nl = 'Is het je vandaag gelukt hem te laten eten zonder tranen? Schrijf zelfs je kleinste succes op in je Stemmingsdagboek en geef jezelf een staande ovatie als moeder.', title_pl = 'Pochwal się! 🌟', body_pl = 'Udało ci się dziś nakarmić go bez płaczu? Zapisz w Dzienniku nastroju nawet najmniejszy sukces i nagródź swoje macierzyńskie umiejętności owacją na stojąco.', title_pt = 'Elogie-se! 🌟', body_pt = 'Hoje conseguiu dar-lhe de comer sem choro? Escreva no Diário de Humor até o seu sucesso mais pequeno e aplauda de pé a sua capacidade de ser mãe.', title_sv = 'Beröm dig själv! 🌟', body_sv = 'Lyckades du mata barnet i dag utan tårar? Skriv ner även den minsta framgången i Humördagboken och ge dina mammakunskaper stående ovationer.', title_vi = 'Hãy tự khen mình! 🌟', body_vi = 'Hôm nay mẹ cho bé ăn mà bé không khóc? Hãy ghi cả thành công nhỏ nhất vào Nhật ký tâm trạng và tự vỗ tay cho kỹ năng làm mẹ của mình.', title_zh = '夸夸自己！🌟', body_zh = '今天没让宝宝哭就喂完饭了？哪怕再小的成功，也写进心情日记，为自己当妈妈的本领热烈鼓掌。' WHERE id = '145211fa-74d2-4e28-8a64-c14921db5185' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El equilibrio de agua es vital 💧', body_es = 'Tanto correr deshidrata el cuerpo. Haz la anotación de la mañana en el Seguimiento de pañales y mira en Productos recomendados botellas deportivas que pueda abrir fácilmente.', title_fr = 'L''hydratation est essentielle 💧', body_fr = 'Courir partout déshydrate. Notez le change du matin dans le Suivi des couches et regardez dans les Produits recommandés des gourdes sport qu''il pourra ouvrir facilement.', title_hi = 'पानी का संतुलन बेहद ज़रूरी है 💧', body_hi = 'खूब दौड़ने से शरीर में पानी की कमी होती है। डायपर ट्रैकर में सुबह की एंट्री कीजिए और सुझाए गए प्रोडक्ट में ऐसी स्पोर्ट्स बोतलें देखिए जिन्हें वह आसानी से खोल सके।', title_id = 'Keseimbangan cairan sangat penting 💧', body_id = 'Berlari aktif membuat tubuh kekurangan cairan. Buat catatan pagi di Pelacak Popok dan lihat botol minum sport yang mudah ia buka di Produk Rekomendasi.', title_ja = '水分バランスはとても大切 💧', body_ja = '活発に走り回ると体は水分不足になります。「おむつトラッカー」に朝の記録をつけて、「おすすめ商品」でお子さんが自分で開けやすいスポーツボトルをチェックしましょう。', title_ko = '수분 균형은 정말 중요해요 💧', body_ko = '활발하게 뛰면 몸에 수분이 부족해져요. 기저귀 기록에 아침 기록을 남기고, 추천 제품에서 아이가 쉽게 열 수 있는 스포츠 물병을 살펴보세요.', title_nl = 'Vochtbalans is van levensbelang 💧', body_nl = 'Actief rennen droogt het lichaam uit. Noteer de ochtendluier in de Luiertracker en bekijk in Aanbevolen producten sportbidons die hij zelf makkelijk open krijgt.', title_pl = 'Nawodnienie jest kluczowe 💧', body_pl = 'Aktywne bieganie odwadnia organizm. Zrób poranny wpis w narzędziu do śledzenia pieluszek i zajrzyj w Polecanych produktach do sportowych bidonów, które łatwo sam otworzy.', title_pt = 'O equilíbrio de água é vital 💧', body_pt = 'As correrias deixam o corpo sem água. Faça o registo da manhã no Registo de Fraldas e veja nos Produtos Recomendados garrafas desportivas que ele consiga abrir facilmente.', title_sv = 'Vätskebalansen är livsviktig 💧', body_sv = 'Aktivt springande torkar ut kroppen. Gör morgonanteckningen i Blöjkollen och titta på sportflaskor som barnet lätt kan öppna i Rekommenderade produkter.', title_vi = 'Cân bằng nước rất quan trọng 💧', body_vi = 'Chạy nhảy nhiều khiến cơ thể bé mất nước. Hãy ghi lại lần thay tã buổi sáng trong Theo dõi tã và xem các bình nước thể thao bé dễ tự mở trong Sản phẩm gợi ý.', title_zh = '水分平衡至关重要 💧', body_zh = '跑来跑去会让身体缺水。在尿布记录里做好早上的记录，再去推荐商品看看宝宝能轻松打开的运动水杯。' WHERE id = '4f60f5e8-df5e-4892-aa2e-dcffda8f877b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Charla con otras madres ☕', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás cafeterías infantiles donde se reúnen muchas madres y regálate un poco de vida social.', title_fr = 'Discuter avec d''autres mamans ☕', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez dans les Lieux adaptés aux mamans des cafés pour enfants où les mamans se retrouvent, et offrez-vous un moment social.', title_hi = 'दूसरी माँओं से बातचीत ☕', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में वे किड्स कैफ़े ढूँढिए जहाँ बहुत सी माँएँ आती हैं, और खुद को भी मेल-जोल का तोहफ़ा दीजिए।', title_id = 'Mengobrol dengan ibu lain ☕', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan kafe anak tempat banyak ibu berkumpul di Tempat Ramah Ibu, dan hadiahi diri Anda waktu bersosialisasi.', title_ja = 'ほかのママとおしゃべり ☕', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」でママたちが集まるキッズカフェを見つけて、自分にも人とのつながりをプレゼントしましょう。', title_ko = '다른 엄마들과 수다 ☕', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 엄마들이 많이 모이는 키즈 카페를 찾아 나에게도 사람들과의 시간을 선물하세요.', title_nl = 'Kletsen met andere moeders ☕', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken kindercafés waar veel moeders komen en gun jezelf ook wat gezelligheid.', title_pl = 'Rozmowa z innymi mamami ☕', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, w których spotyka się wiele mam, i podaruj sobie trochę towarzystwa.', title_pt = 'Conversa com outras mães ☕', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães cafés para crianças onde se juntam muitas mães e ofereça a si própria um pouco de convívio.', title_sv = 'Prata med andra mammor ☕', body_sv = 'Trött på att bara prata med barnet? Hitta barncaféer där många mammor samlas i Mammavänliga platser och ge dig själv lite socialt umgänge.', title_vi = 'Trò chuyện cùng các mẹ khác ☕', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm những quán cà phê trẻ em nơi các mẹ hay gặp nhau trong Địa điểm thân thiện với mẹ và tặng mình chút thời gian giao lưu.', title_zh = '和其他妈妈聊聊 ☕', body_zh = '只和孩子说话说累了？在妈妈友好场所里找找妈妈们常聚的亲子咖啡馆，也送自己一点社交时光。' WHERE id = 'edd993f1-ac76-4300-8ed0-6009d7897f2b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Están llenas las reservas de hierro? 🥩', body_es = 'Para que tu peque tan activo no tenga anemia, comprueba en el Seguimiento de tomas el hierro de hoy (carne, legumbres) y ajusta su menú.', title_fr = 'Les réserves de fer sont-elles pleines ? 🥩', body_fr = 'Pour que votre petit plein d''énergie ne manque pas de fer, vérifiez dans le Suivi des repas ses apports en fer du jour (viande, légumineuses) et ajustez son menu.', title_hi = 'आयरन का भंडार भरा है? 🥩', body_hi = 'चंचल नन्हे को खून की कमी न हो, इसके लिए फ़ीडिंग ट्रैकर में आज का आयरन (मांस, दालें) जाँचिए और मेन्यू ठीक कीजिए।', title_id = 'Cadangan zat besi cukup? 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia, cek asupan zat besi hari ini (daging, kacang-kacangan) di alat Pemantau Nutrisi dan sesuaikan menunya.', title_ja = '鉄分は足りている？🥩', body_ja = '活発なお子さんが貧血にならないよう、「栄養管理ツール」で今日の鉄分（お肉、豆類）の摂取量を確認して、メニューを調整しましょう。', title_ko = '철분은 충분한가요? 🥩', body_ko = '활발한 아이가 빈혈을 겪지 않도록 수유 기록 도구로 오늘의 철분 섭취(고기, 콩류)를 확인하고 식단을 조절하세요.', title_nl = 'Is de ijzervoorraad op peil? 🥩', body_nl = 'Controleer in de Voedingstracker het ijzer van vandaag (vlees, peulvruchten) en pas het menu aan, zodat je beweeglijke kleintje geen bloedarmoede krijgt.', title_pl = 'Zapas żelaza pełny? 🥩', body_pl = 'Aby ruchliwy maluch nie miał anemii, sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza (mięso, rośliny strączkowe) i dopasuj menu.', title_pt = 'As reservas de ferro estão cheias? 🥩', body_pt = 'Para que o seu pequenino tão ativo não tenha anemia, verifique no Registo de Alimentação o ferro de hoje (carne, leguminosas) e ajuste a ementa.', title_sv = 'Är järnförrådet fyllt? 🥩', body_sv = 'För att ett aktivt barn inte ska få blodbrist, kontrollera dagens järnintag (kött, baljväxter) i Matningskoll och justera menyn.', title_vi = 'Kho sắt đã đầy chưa? 🥩', body_vi = 'Để bé hiếu động không bị thiếu máu, hãy kiểm tra lượng sắt (thịt, các loại đậu) hôm nay trong Theo dõi cữ bú và điều chỉnh thực đơn.', title_zh = '铁储备够吗？🥩', body_zh = '为了让好动的小家伙不贫血，在喂养记录工具里查看今天的铁（肉类、豆类）摄入量，调整一下菜单。' WHERE id = '6f516c4d-5db5-4d3e-8fca-8c461e614752' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisemos la reserva de calcio 🧀', body_es = '¡Unos huesos que crecen tan rápido necesitan calcio! Mira con el Seguimiento de tomas cuánto queso y yogur ha tomado hoy y completa lo que falte.', title_fr = 'Vérifions le calcium 🧀', body_fr = 'Des os qui s''allongent vite ont besoin de calcium ! Regardez dans le Suivi des repas sa ration de fromage et de yaourt du jour et comblez les manques.', title_hi = 'कैल्शियम का भंडार जाँचें 🧀', body_hi = 'तेज़ी से बढ़ती हड्डियों को कैल्शियम चाहिए! फ़ीडिंग ट्रैकर से आज का पनीर और दही देखिए और कमी पूरी कीजिए।', title_id = 'Cek cadangan kalsium 🧀', body_id = 'Tulang yang cepat memanjang butuh kalsium! Lihat porsi keju dan yogurt hari ini dengan alat Pemantau Nutrisi dan lengkapi kekurangannya.', title_ja = 'カルシウムをチェックしよう 🧀', body_ja = 'ぐんぐん伸びる骨にはカルシウムが必要です！「栄養管理ツール」で今日のチーズやヨーグルトの量を確認して、足りない分を補いましょう。', title_ko = '칼슘 확인해 볼까요 🧀', body_ko = '빠르게 자라는 뼈에는 칼슘이 필요해요! 수유 기록 도구로 오늘의 치즈, 요거트 섭취량을 보고 부족한 만큼 채워 주세요.', title_nl = 'Calciumvoorraad checken 🧀', body_nl = 'Snelgroeiende botten hebben calcium nodig! Bekijk met de Voedingstracker de kaas en yoghurt van vandaag en vul tekorten aan.', title_pl = 'Sprawdźmy zapas wapnia 🧀', body_pl = 'Szybko rosnące kości potrzebują wapnia! Sprawdź w narzędziu do śledzenia karmienia dzisiejszą porcję sera i jogurtu i uzupełnij braki.', title_pt = 'Vamos ver as reservas de cálcio 🧀', body_pt = 'Ossos que crescem depressa precisam de cálcio! Veja no Registo de Alimentação o queijo e o iogurte de hoje e complete o que faltar.', title_sv = 'Vi kollar kalciumförrådet 🧀', body_sv = 'Benen som växer snabbt behöver kalcium! Titta på dagens ost- och yoghurtnorm med Matningskoll och fyll på det som fattas.', title_vi = 'Kiểm tra kho canxi 🧀', body_vi = 'Xương dài ra nhanh rất cần canxi! Hãy xem định mức phô mai, sữa chua hôm nay bằng công cụ Theo dõi cữ bú và bổ sung phần còn thiếu.', title_zh = '来查查钙储备 🧀', body_zh = '快速生长的骨骼需要钙！用喂养记录工具看看今天奶酪、酸奶的参考量，补上不足的部分。' WHERE id = 'b003834c-8ce3-4da4-a17e-0b837c04f7f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los sonidos misteriosos del bosque 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de rabietas? Pon el susurro de las hojas de Ruido blanco y regala un masaje al sistema nervioso de los dos.', title_fr = 'Les sons mystérieux de la forêt 🍃', body_fr = 'Une journée bruyante et pleine de crises ? Lancez le bruissement des feuilles des Bruits blancs pour masser son système nerveux comme le vôtre.', title_hi = 'जंगल की रहस्यमयी आवाज़ें 🍃', body_hi = 'बहुत शोर और नखरों भरा दिन था? व्हाइट नॉइज़ में पत्तों की सरसराहट चलाइए और उसके और अपने, दोनों के तंत्रिका तंत्र को आराम दीजिए।', title_id = 'Suara misterius hutan 🍃', body_id = 'Hari ini sangat bising dan penuh tantrum? Putar suara gemerisik daun dari Suara Putih untuk menenangkan saraf ia dan Anda.', title_ja = '森のふしぎな音 🍃', body_ja = 'にぎやかで、かんしゃくの多い一日でしたか？「ホワイトノイズ」の木の葉のざわめきを流して、お子さんとあなたの神経をやさしくほぐしましょう。', title_ko = '숲의 신비로운 소리 🍃', body_ko = '시끄럽고 떼쓰기 많은 하루였나요? 백색소음의 나뭇잎 바스락 소리를 틀어 아이와 엄마의 신경을 함께 달래 주세요.', title_nl = 'Geheimzinnige bosgeluiden 🍃', body_nl = 'Was het een luidruchtige dag vol driftbuien? Zet bladergeruis uit Witte ruis aan en geef zijn zenuwstelsel en dat van jezelf een massage.', title_pl = 'Tajemnicze odgłosy lasu 🍃', body_pl = 'To był bardzo głośny i pełen kryzysów dzień? Włącz szelest liści z Białego szumu i ukój układ nerwowy jego i swój.', title_pt = 'Os sons misteriosos da floresta 🍃', body_pt = 'Foi um dia muito barulhento e cheio de crises? Ligue o sussurro das folhas do Ruído Branco e faça uma massagem ao sistema nervoso dele e ao seu.', title_sv = 'Skogens hemlighetsfulla ljud 🍃', body_sv = 'Har dagen varit väldigt bullrig och full av utbrott? Sätt på lövsus från Vitt brus och ge både barnets och ditt eget nervsystem en massage.', title_vi = 'Âm thanh bí ẩn của rừng 🍃', body_vi = 'Hôm nay quá ồn ào và nhiều cơn ăn vạ? Hãy bật tiếng lá xào xạc trong Tiếng ồn trắng để xoa dịu hệ thần kinh của cả bé lẫn mẹ.', title_zh = '森林的神秘声音 🍃', body_zh = '今天又吵又闹，崩溃不断？打开白噪音里的树叶沙沙声，给宝宝和你自己的神经系统都做个按摩。' WHERE id = 'b5cae897-2c37-4223-8c5a-201bd9d0229a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tentempié sin azúcar 🍪', body_es = 'No hacen falta galletas del súper. Descubre en Recetas para bebé dulces sanos caseros de dátiles y avena que se preparan en 10 minutos.', title_fr = 'En-cas sans sucre 🍪', body_fr = 'Pas besoin de biscuits du commerce. Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à l''avoine, prêtes en 10 minutes à la maison.', title_hi = 'बिना चीनी का स्नैक 🍪', body_hi = 'बाज़ार के बिस्किट की ज़रूरत नहीं। बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और ओट्स की सेहतमंद मिठाइयाँ खोजिए।', title_id = 'Camilan tanpa gula 🍪', body_id = 'Tak perlu biskuit dari toko. Temukan camilan manis sehat dari kurma dan oat yang siap dalam 10 menit di Resep Bayi.', title_ja = '砂糖不使用のおやつ 🍪', body_ja = '市販のクッキーはいりません。「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとオートミールのヘルシーなおやつを見つけましょう。', title_ko = '설탕 없는 간식 🍪', body_ko = '마트 쿠키는 필요 없어요. 아기 레시피에서 집에서 10분이면 만드는 대추야자 귀리 간식을 찾아보세요.', title_nl = 'Suikervrij tussendoortje 🍪', body_nl = 'Koekjes uit de winkel zijn niet nodig. Ontdek in Babyrecepten gezonde lekkernijen met dadels en havermout, thuis klaar in 10 minuten.', title_pl = 'Przekąska bez cukru 🍪', body_pl = 'Sklepowe ciastka nie są potrzebne. Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i płatkami owsianymi, które zrobisz w domu w 10 minut.', title_pt = 'Lanche sem açúcar 🍪', body_pt = 'Não precisa de bolachas do supermercado. Descubra nas Receitas para bebés doces saudáveis de tâmaras e aveia, feitos em casa em 10 minutos.', title_sv = 'Sockerfritt mellanmål 🍪', body_sv = 'Ni behöver inga kex från affären. Upptäck nyttiga sötsaker med dadlar och havre som är klara på 10 minuter hemma i Recept för bebisar.', title_vi = 'Món ăn vặt không đường 🍪', body_vi = 'Không cần bánh quy mua sẵn. Hãy khám phá các món ngọt lành mạnh từ chà là và yến mạch làm tại nhà trong 10 phút trong Công thức cho bé.', title_zh = '无糖小零食 🍪', body_zh = '不需要超市的饼干。在宝宝食谱里发现10分钟就能在家做好的椰枣燕麦健康甜点吧。' WHERE id = '20cf6725-2fdc-45bb-965b-09069424fe0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño ayudante de casa 🧹', body_es = '¿Mientras tú barres, él limpia la mesa con un trapo? Graba enseguida este dulce momento de responsabilidad y conviértelo en la foto más orgullosa del Álbum del bebé.', title_fr = 'Petit assistant à la maison 🧹', body_fr = 'Quand vous balayez, il essuie la table avec un chiffon ? Filmez tout de suite ce mignon moment de responsabilité et faites-en la photo la plus fière de l''Album de bébé.', title_hi = 'घर का नन्हा मददगार 🧹', body_hi = 'आप झाड़ू लगाती हैं तो वह भी कपड़े से मेज़ पोंछता है? ज़िम्मेदारी के इस प्यारे पल को तुरंत रिकॉर्ड कीजिए और बेबी एल्बम की सबसे गर्व भरी तस्वीर बनाइए।', title_id = 'Asisten rumah cilik 🧹', body_id = 'Saat Anda menyapu, ia ikut mengelap meja dengan kain? Segera rekam momen tanggung jawab yang manis ini dan jadikan foto paling membanggakan di Album Bayi.', title_ja = '小さなお手伝いさん 🧹', body_ja = 'あなたが掃除をしていると、お子さんも布でテーブルを拭いていますか？このかわいい責任感の芽生えをすぐに撮影して、「ベビーアルバム」でいちばん誇らしい一枚にしましょう。', title_ko = '꼬마 집안일 도우미 🧹', body_ko = '엄마가 청소할 때 아이도 걸레로 탁자를 닦나요? 이 사랑스러운 책임감의 순간을 바로 찍어 아기 앨범의 가장 자랑스러운 장면으로 남기세요.', title_nl = 'Kleine hulp in huis 🧹', body_nl = 'Veegt hij met een doekje de tafel af terwijl jij stofzuigt? Leg dit lieve moment van verantwoordelijkheid meteen vast en maak er de trotste foto van het Babyalbum van.', title_pl = 'Mały domowy pomocnik 🧹', body_pl = 'Gdy zamiatasz, on wyciera ściereczką stół? Od razu nagraj tę słodką chwilę odpowiedzialności i zrób z niej najbardziej dumny kadr w Albumie dziecka.', title_pt = 'Pequeno ajudante da casa 🧹', body_pt = 'Enquanto varre a casa, ele limpa a mesa com um pano? Filme já este doce momento de responsabilidade e faça dele a foto mais orgulhosa do Álbum do Bebé.', title_sv = 'Liten hjälpreda hemma 🧹', body_sv = 'Torkar barnet bordet med en trasa medan du sopar? Filma det här söta ögonblicket av ansvar direkt och gör det till Babyalbumets stoltaste bild.', title_vi = 'Người giúp việc nhà tí hon 🧹', body_vi = 'Mẹ quét nhà thì bé cũng cầm khăn lau bàn? Hãy quay ngay khoảnh khắc biết nhận trách nhiệm đáng yêu này để có khung hình đáng tự hào nhất trong Album của bé.', title_zh = '家里的小帮手 🧹', body_zh = '你扫地的时候，宝宝也拿抹布擦桌子？马上把这个可爱的担当时刻拍下来，做成宝宝相册里最让人骄傲的一张。' WHERE id = 'f527de5c-afa8-4884-a173-da37070a2826' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pegar o empujar 🛑', body_es = '¿Levanta la mano de repente cuando se enfada? Consulta a Anacan AI para aprender a resolver con juegos esta conducta tan propia del mes 20.', title_fr = 'Taper ou pousser 🛑', body_fr = 'Il lève soudain la main quand il est en colère ? Consultez Anacan AI pour apprendre à gérer par le jeu ce comportement typique du 20e mois.', title_hi = 'मारना या धक्का देना 🛑', body_hi = 'गुस्से में अचानक हाथ उठाता है? 20वें महीने के इस खास व्यवहार को खेलों से कैसे सुलझाएँ, यह जानने के लिए Anacan AI से पूछिए।', title_id = 'Memukul atau mendorong 🛑', body_id = 'Tiba-tiba mengangkat tangan saat marah? Tanyakan kepada Anacan AI cara mengatasi perilaku khas usia 20 bulan ini lewat permainan.', title_ja = 'たたく、押す 🛑', body_ja = '怒ると急に手が出ますか？1歳8か月ごろに見られるこの行動に、遊びを通してどう対応すればいいか、Anacan AIに相談してみましょう。', title_ko = '때리거나 밀 때 🛑', body_ko = '화가 나면 갑자기 손을 드나요? 20개월 무렵의 이런 행동을 놀이로 다루는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Slaan of duwen 🛑', body_nl = 'Haalt hij ineens uit als hij boos is? Vraag Anacan AI hoe je dit typische gedrag van de 20e maand met spelletjes kunt aanpakken.', title_pl = 'Bicie albo popychanie 🛑', body_pl = 'Gdy się złości, nagle podnosi rękę? Zapytaj Anacan AI, jak poprzez zabawę poradzić sobie z tym typowym dla 20. miesiąca zachowaniem.', title_pt = 'Bater ou empurrar 🛑', body_pt = 'Quando se zanga, levanta a mão de repente? Recorra ao Anacan AI para saber como resolver com brincadeiras este comportamento típico dos 20 meses.', title_sv = 'Slår eller knuffar 🛑', body_sv = 'Lyfter barnet plötsligt handen när hen blir arg? Vänd dig till Anacan AI för att lära dig hur du kan hantera detta typiska beteende i 20:e månaden med lek.', title_vi = 'Đánh hoặc xô đẩy 🛑', body_vi = 'Bé bất ngờ vung tay khi tức giận? Hãy hỏi Anacan AI cách xử lý hành vi đặc trưng của tháng thứ 20 này qua các trò chơi.', title_zh = '打人或推人 🛑', body_zh = '一生气就突然动手？向Anacan AI请教，学习如何通过游戏解决第20个月的这种特有行为。' WHERE id = '18518788-d8e2-4971-93f7-6fbf0592ca33' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🧘‍♀️', body_es = 'Tu peque se ha dormido. Deja todas las tareas de casa. Escribe cómo te sientes en el Diario de ánimo, pon una música tranquila y dedícate esta noche solo a ti.', title_fr = 'L''héroïne du jour, c''est vous 🧘‍♀️', body_fr = 'Il s''est endormi. Arrêtez toutes les tâches ménagères. Écrivez vos émotions dans le Journal d''humeur, mettez une musique douce et consacrez cette soirée à vous seule.', title_hi = 'आज की हीरो आप हैं 🧘‍♀️', body_hi = 'बच्चा सो गया। घर के सारे काम रोक दीजिए। मूड डायरी में अपनी भावनाएँ लिखिए, कोई सुकून भरा संगीत लगाइए और यह शाम सिर्फ़ खुद को दीजिए।', title_id = 'Pahlawan hari ini adalah Anda 🧘‍♀️', body_id = 'Si kecil sudah tidur. Hentikan semua pekerjaan rumah. Tulis perasaan Anda di Buku Harian Suasana Hati, putar musik yang menenangkan, dan khususkan malam ini untuk diri Anda.', title_ja = '今日のヒーローはあなたです 🧘‍♀️', body_ja = 'お子さんが眠りました。家事は全部ストップ。「気分日記」に気持ちを書いて、心地よい音楽をかけ、今夜はただ自分のために過ごしましょう。', title_ko = '오늘의 주인공은 엄마예요 🧘‍♀️', body_ko = '아이가 잠들었어요. 집안일은 모두 멈추세요. 기분 일기에 마음을 적고 편안한 음악을 틀어 오늘 저녁은 오롯이 나를 위해 보내세요.', title_nl = 'Jij bent de held van vandaag 🧘‍♀️', body_nl = 'Je kindje slaapt. Stop met al het huishouden. Schrijf je gevoelens op in je Stemmingsdagboek, zet rustige muziek op en wijd deze avond helemaal aan jezelf.', title_pl = 'Dzisiejszą bohaterką jesteś ty 🧘‍♀️', body_pl = 'Maluch zasnął. Odłóż wszystkie domowe obowiązki. Zapisz swoje uczucia w Dzienniku nastroju, włącz spokojną muzykę i ten wieczór poświęć tylko sobie.', title_pt = 'A heroína do dia é a mãe 🧘‍♀️', body_pt = 'Ele adormeceu. Pare todas as tarefas da casa. Escreva o que sente no Diário de Humor, ponha uma música tranquila e dedique esta noite só a si.', title_sv = 'Dagens hjälte är du 🧘‍♀️', body_sv = 'Barnet sover. Lägg alla hushållssysslor åt sidan. Skriv ner dina känslor i Humördagboken, sätt på lugn musik och ägna kvällen bara åt dig själv.', title_vi = 'Mẹ là người hùng của ngày hôm nay 🧘‍♀️', body_vi = 'Bé đã ngủ. Hãy dừng hết việc nhà. Viết cảm xúc vào Nhật ký tâm trạng, bật một bản nhạc êm dịu và dành trọn buổi tối nay cho riêng mình.', title_zh = '今天的英雄是你 🧘‍♀️', body_zh = '孩子睡着了。停下所有家务。在心情日记里写下你的感受，放一首舒缓的音乐，今晚只属于你自己。' WHERE id = 'a6200253-33e2-4142-a4a9-811aa67d4feb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de paciencia en la mesa ⏱️', body_es = '¿Tarda 5 minutos en cada cucharada? Pon el temporizador de tomas, ten paciencia y analiza con precisión la evolución de su apetito con el informe de la app.', title_fr = 'Patience à table ⏱️', body_fr = 'Il met 5 minutes pour une cuillerée ? Lancez le minuteur des repas, soyez patiente et analysez précisément l''évolution de son appétit grâce au rapport de l''appli.', title_hi = 'खाने की मेज़ पर सब्र की परीक्षा ⏱️', body_hi = 'एक चम्मच 5 मिनट में खाता है? फ़ीडिंग टाइमर चालू कीजिए, धैर्य रखिए और ऐप की रिपोर्ट से भूख के रुझान को सटीक समझिए।', title_id = 'Ujian kesabaran di meja makan ⏱️', body_id = 'Satu suap butuh 5 menit? Nyalakan Timer Makan, bersabarlah, dan analisis perkembangan nafsu makannya secara akurat lewat laporan di aplikasi.', title_ja = '食卓で試される忍耐 ⏱️', body_ja = 'ひと口に5分もかかりますか？食事タイマーをオンにして、気長に見守りながら、アプリのレポートで食欲の変化をしっかり分析しましょう。', title_ko = '식탁에서의 인내심 시험 ⏱️', body_ko = '한 숟가락을 5분 동안 먹나요? 수유 타이머를 켜고 느긋하게 기다리며, 앱의 리포트로 식욕의 변화를 정확히 살펴보세요.', title_nl = 'Geduldproef aan tafel ⏱️', body_nl = 'Doet hij 5 minuten over één lepel? Zet de Voedingstimer aan, wees geduldig en analyseer zijn eetlust precies met het rapport in de app.', title_pl = 'Test cierpliwości przy stole ⏱️', body_pl = 'Jedną łyżkę je 5 minut? Włącz timer karmienia, uzbrój się w cierpliwość i dokładnie przeanalizuj apetyt dzięki raportowi w aplikacji.', title_pt = 'Um teste de paciência à mesa ⏱️', body_pt = 'Demora 5 minutos a comer uma colher? Ligue o temporizador de alimentação, tenha paciência e analise com precisão a evolução do apetite com o relatório da app.', title_sv = 'Tålamodsprov vid matbordet ⏱️', body_sv = 'Tar en sked 5 minuter? Starta matningstimern, ha tålamod och analysera aptitens utveckling noga med rapporten i appen.', title_vi = 'Thử thách kiên nhẫn trên bàn ăn ⏱️', body_vi = 'Bé ăn một thìa mất 5 phút? Hãy bật Hẹn giờ cho bú, kiên nhẫn và phân tích chính xác diễn biến khẩu vị của bé qua báo cáo trong ứng dụng.', title_zh = '餐桌上的耐心考验 ⏱️', body_zh = '一勺饭要吃5分钟？打开喂养计时器，保持耐心，用应用里的报告准确分析食欲的变化。' WHERE id = 'eefd67fd-3835-4f65-abf3-9ced6b705e30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Empiezan los juegos de imaginación 🧸', body_es = '¿Le da agua a su osito o te cura a ti? Guarda para el futuro estos momentos maravillosos de empatía añadiéndolos en vídeo con sonido al Álbum del bebé.', title_fr = 'Les jeux d''imagination ont commencé 🧸', body_fr = 'Il donne à boire à son nounours ou vous soigne ? Gardez ces superbes moments d''empathie pour plus tard en les ajoutant en vidéo avec le son à l''Album de bébé.', title_hi = 'कल्पना वाले खेल शुरू हो गए 🧸', body_hi = 'अपने भालू को पानी पिलाता है या आपका इलाज करता है? हमदर्दी के इन शानदार पलों को आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़कर भविष्य के लिए सहेजिए।', title_id = 'Permainan imajinasi dimulai 🧸', body_id = 'Ia memberi minum boneka beruangnya, atau mengobati Anda? Simpan momen empati yang luar biasa ini sebagai video bersuara di Album Bayi untuk masa depan.', title_ja = 'ごっこ遊びが始まった 🧸', body_ja = 'くまさんにお水をあげたり、あなたを手当てしてくれたり？このすてきな思いやりの瞬間を音声付きの動画で「ベビーアルバム」に追加して、未来に残しましょう。', title_ko = '상상 놀이가 시작됐어요 🧸', body_ko = '곰 인형에게 물을 주거나 엄마를 치료해 주나요? 이 멋진 공감의 순간을 소리가 담긴 영상으로 아기 앨범에 올려 간직하세요.', title_nl = 'Fantasiespel is begonnen 🧸', body_nl = 'Geeft hij zijn beer water of verzorgt hij jou? Bewaar deze prachtige momenten van empathie als video met geluid in het Babyalbum voor later.', title_pl = 'Zaczęły się zabawy w udawanie 🧸', body_pl = 'Daje misiowi pić albo cię „leczy”? Zachowaj te wspaniałe chwile empatii na przyszłość, dodając je jako film z dźwiękiem do Albumu dziecka.', title_pt = 'Começaram as brincadeiras de imaginação 🧸', body_pt = 'Dá água ao ursinho ou faz de conta que a trata? Guarde para o futuro estes momentos maravilhosos de empatia, adicionando-os em vídeo com som ao Álbum do Bebé.', title_sv = 'Låtsaslekarna har börjat 🧸', body_sv = 'Ger barnet nallen vatten eller låtsas behandla dig? Spara dessa underbara stunder av empati för framtiden som video med ljud i Babyalbumet.', title_vi = 'Trò chơi tưởng tượng đã bắt đầu 🧸', body_vi = 'Bé cho gấu bông uống nước hay "chữa bệnh" cho mẹ? Hãy lưu giữ những khoảnh khắc đồng cảm tuyệt vời này bằng video có tiếng trong Album của bé.', title_zh = '想象游戏开始了 🧸', body_zh = '给小熊喂水，或者给你“看病”？把这些了不起的共情时刻录成有声视频加进宝宝相册，留给未来。' WHERE id = '070b2f75-0440-4e85-b828-292900301f9e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de las reservas de hierro 🥩', body_es = 'Para unos músculos activos y un desarrollo sano no debe haber anemia. Comprueba con el Seguimiento de tomas el hierro de hoy (carne, legumbres) y completa enseguida lo que falte.', title_fr = 'Contrôle des réserves de fer 🥩', body_fr = 'Pour des muscles actifs et un développement sain, il ne doit pas manquer de fer. Vérifiez avec le Suivi des repas ses apports en fer du jour (viande, légumineuses) et comblez tout de suite les manques.', title_hi = 'आयरन के भंडार की जाँच 🥩', body_hi = 'चंचल मांसपेशियों और सेहतमंद विकास के लिए खून की कमी नहीं होनी चाहिए। फ़ीडिंग ट्रैकर से आज का आयरन (मांस, दालें) जाँचिए और कमी तुरंत पूरी कीजिए।', title_id = 'Cek cadangan zat besi 🥩', body_id = 'Untuk otot yang aktif dan tumbuh kembang sehat, anemia harus dicegah. Cek asupan zat besi hari ini (daging, kacang-kacangan) dengan alat Pemantau Nutrisi dan segera lengkapi kekurangannya.', title_ja = '鉄分チェック 🥩', body_ja = '活発に動く筋肉と健やかな成長のためには、貧血を防ぐことが大切です。「栄養管理ツール」で今日の鉄分（お肉、豆類）の摂取量を確認し、足りない分をすぐに補いましょう。', title_ko = '철분 확인 🥩', body_ko = '활발한 근육과 건강한 성장을 위해 빈혈은 막아야 해요. 수유 기록 도구로 오늘의 철분 섭취(고기, 콩류)를 확인하고 부족한 만큼 바로 채워 주세요.', title_nl = 'IJzervoorraad checken 🥩', body_nl = 'Voor actieve spieren en een gezonde groei mag er geen bloedarmoede zijn. Controleer met de Voedingstracker het ijzer van vandaag (vlees, peulvruchten) en vul tekorten meteen aan.', title_pl = 'Kontrola zapasu żelaza 🥩', body_pl = 'Dla aktywnych mięśni i zdrowego rozwoju nie może być anemii. Sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza (mięso, rośliny strączkowe) i od razu uzupełnij braki.', title_pt = 'Verificar as reservas de ferro 🥩', body_pt = 'Para músculos ativos e um desenvolvimento saudável, não pode haver anemia. Verifique com o Registo de Alimentação o ferro de hoje (carne, leguminosas) e complete já o que faltar.', title_sv = 'Kontroll av järnförrådet 🥩', body_sv = 'För aktiva muskler och sund utveckling får det inte finnas blodbrist. Kontrollera dagens järnintag (kött, baljväxter) med Matningskoll och fyll direkt på det som fattas.', title_vi = 'Kiểm tra kho sắt 🥩', body_vi = 'Để cơ bắp hoạt động tốt và phát triển khỏe mạnh, bé không được thiếu máu. Hãy kiểm tra lượng sắt (thịt, các loại đậu) hôm nay bằng Theo dõi cữ bú và bổ sung ngay phần thiếu.', title_zh = '铁储备检查 🥩', body_zh = '为了肌肉有力、发育健康，不能贫血。用喂养记录工具查看今天的铁（肉类、豆类）摄入量，马上补足不够的部分。' WHERE id = '388f83f4-0bb5-4306-abf6-b75f9dc65017' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Del ruido al silencio 🎶', body_es = 'Después del ruido de la tele y los juguetes, un silencio repentino le asusta. Pon en la habitación el sonido del secador de Ruido blanco y verás cómo la monotonía mejora el ambiente para dormir.', title_fr = 'Du bruit au silence 🎶', body_fr = 'Après la télé et les jouets bruyants, le silence soudain lui fait peur. Lancez dans la chambre le bruit de sèche-cheveux des Bruits blancs et voyez comme la monotonie aide son sommeil.', title_hi = 'शोर से खामोशी की ओर 🎶', body_hi = 'टीवी और खिलौनों की आवाज़ों के बाद अचानक की खामोशी उसे डराती है। कमरे में व्हाइट नॉइज़ से हेयर ड्रायर की आवाज़ चलाइए और देखिए कि एक जैसी आवाज़ नींद के माहौल पर कितना अच्छा असर डालती है।', title_id = 'Dari bising ke hening 🎶', body_id = 'Setelah suara TV dan mainan, hening yang tiba-tiba bisa membuatnya takut. Putar suara pengering rambut dari Suara Putih di kamar dan lihat bagaimana bunyi monoton membantu suasana tidur.', title_ja = '音から静けさへ 🎶', body_ja = 'テレビやおもちゃの音のあとの急な静けさは、お子さんを不安にさせます。部屋で「ホワイトノイズ」のドライヤーの音を流して、単調な音が眠りの環境にどれほど良い影響を与えるか確かめてみましょう。', title_ko = '소리에서 고요함으로 🎶', body_ko = 'TV와 장난감 소리 뒤의 갑작스러운 정적은 아이를 놀라게 해요. 백색소음에서 헤어드라이어 소리를 틀어 단조로운 소리가 수면 환경에 주는 좋은 효과를 확인해 보세요.', title_nl = 'Van geluid naar stilte 🎶', body_nl = 'Na het geluid van tv en speelgoed kan plotselinge stilte hem laten schrikken. Zet in de kamer het föhngeluid uit Witte ruis aan en zie hoe dat monotone geluid zijn slaapsfeer positief beïnvloedt.', title_pl = 'Od dźwięku do ciszy 🎶', body_pl = 'Nagła cisza po dźwiękach telewizora i zabawek go niepokoi. Włącz w pokoju odgłos suszarki z Białego szumu i zobacz, jak monotonia dobrze wpływa na warunki do snu.', title_pt = 'Do barulho ao silêncio 🎶', body_pt = 'Depois dos sons da televisão e dos brinquedos, o silêncio repentino assusta-o. Ligue no quarto o som do secador de cabelo do Ruído Branco e veja como a monotonia ajuda o ambiente de sono.', title_sv = 'Från ljud till tystnad 🎶', body_sv = 'Efter tv- och leksaksljud kan plötslig tystnad skrämma barnet. Sätt på hårtorksljud från Vitt brus i rummet och se hur positivt monotona ljud påverkar sömnmiljön.', title_vi = 'Từ ồn ào sang yên tĩnh 🎶', body_vi = 'Sau tiếng TV và đồ chơi, sự im lặng đột ngột có thể khiến bé sợ. Hãy bật tiếng máy sấy tóc trong Tiếng ồn trắng và xem âm thanh đều đều giúp ích cho giấc ngủ thế nào.', title_zh = '从嘈杂到安静 🎶', body_zh = '在电视和玩具的声音之后，突然的安静会让宝宝害怕。在房间里打开白噪音里的吹风机声，看看单调的声音如何对睡眠环境产生积极影响。' WHERE id = '9cb7efe6-c6c0-4032-89de-12eeec5119ee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El espectáculo sin fin de la mesa ⏱️', body_es = 'Juega con la comida, la tira al suelo, pero no come. Pon el temporizador de tomas, ten paciencia y analiza con precisión la evolución de su apetito en esta etapa de independencia con el gráfico de la app.', title_fr = 'Le show sans fin à table ⏱️', body_fr = 'Il joue avec la nourriture, la jette par terre mais ne mange pas. Lancez le minuteur des repas, soyez patiente et analysez précisément son appétit pendant cette période d''autonomie grâce au graphique de l''appli.', title_hi = 'मेज़ पर कभी न खत्म होने वाला शो ⏱️', body_hi = 'खाने से खेलता है, नीचे फेंकता है, पर खाता नहीं। फ़ीडिंग टाइमर चालू कीजिए, धैर्य रखिए और आज़ादी के इस दौर में ऐप के चार्ट से भूख के रुझान को सटीक समझिए।', title_id = 'Pertunjukan tanpa akhir di meja makan ⏱️', body_id = 'Ia bermain dengan makanan, melemparnya ke lantai, tapi tidak makan. Nyalakan Timer Makan, bersabarlah, dan analisis nafsu makannya di masa mandiri ini lewat grafik di aplikasi.', title_ja = '食卓のエンドレスショー ⏱️', body_ja = '食べ物で遊んで床に投げるけれど、食べない。食事タイマーをオンにして、気長に見守りながら、この自立の時期の食欲の変化をアプリのグラフでしっかり分析しましょう。', title_ko = '식탁 위 끝없는 공연 ⏱️', body_ko = '음식으로 장난치고 바닥에 던지면서 먹지는 않나요? 수유 타이머를 켜고 느긋하게 기다리며, 이 자립의 시기에 식욕의 변화를 앱의 그래프로 정확히 살펴보세요.', title_nl = 'De eindeloze show aan tafel ⏱️', body_nl = 'Speelt hij met eten en gooit hij het op de grond, maar eet hij niet? Zet de Voedingstimer aan, wees geduldig en analyseer zijn eetlust in deze zelfstandige fase precies met de grafiek in de app.', title_pl = 'Niekończący się show przy stole ⏱️', body_pl = 'Bawi się jedzeniem, rzuca je na podłogę, ale nie je? Włącz timer karmienia, bądź cierpliwa i w tym okresie samodzielności dokładnie analizuj apetyt dzięki wykresowi w aplikacji.', title_pt = 'O espetáculo sem fim à mesa ⏱️', body_pt = 'Brinca com a comida, atira-a ao chão, mas não come. Ligue o temporizador de alimentação, tenha paciência e analise com precisão, no gráfico da app, a evolução do apetite nesta fase de independência.', title_sv = 'Showen vid bordet som aldrig tar slut ⏱️', body_sv = 'Barnet leker med maten och kastar den på golvet, men äter inte. Starta matningstimern, ha tålamod och analysera aptitens utveckling under den här självständiga perioden noga med grafen i appen.', title_vi = 'Màn trình diễn bất tận trên bàn ăn ⏱️', body_vi = 'Bé nghịch thức ăn, ném xuống sàn nhưng không ăn. Hãy bật Hẹn giờ cho bú, kiên nhẫn và phân tích chính xác khẩu vị của bé trong giai đoạn tự lập này qua biểu đồ trong ứng dụng.', title_zh = '餐桌上停不下来的表演 ⏱️', body_zh = '玩食物、扔到地上，就是不吃。打开喂养计时器，保持耐心，用应用里的图表准确分析这个自主阶段的食欲变化。' WHERE id = '847e9a71-981a-4920-b6be-a1986674dd92' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando juguetes inteligentes 🧩', body_es = '¿Ya domina meter figuras por los agujeros? Descubre ahora en Productos recomendados puzles adecuados a su edad que afinarán aún más su inteligencia.', title_fr = 'À la recherche d''un jouet malin 🧩', body_fr = 'Il maîtrise l''art de faire passer les formes dans les trous ? Découvrez tout de suite dans les Produits recommandés des puzzles adaptés à son âge pour affûter encore son intelligence.', title_hi = 'स्मार्ट खिलौनों की तलाश 🧩', body_hi = 'आकृतियों को छेदों में डालने में माहिर हो गया? उसकी बुद्धि को और तेज़ करने वाली, उम्र के हिसाब से पज़ल तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Mencari mainan cerdas 🧩', body_id = 'Sudah mahir memasukkan bentuk ke lubangnya? Temukan puzzle sesuai usia yang makin mengasah kecerdasannya di bagian Produk Rekomendasi.', title_ja = 'かしこいおもちゃ探し 🧩', body_ja = '形を穴に入れるのが上手になりましたか？知性をさらに磨く、年齢に合ったパズルを「おすすめ商品」ですぐに見つけましょう。', title_ko = '똑똑한 장난감 찾기 🧩', body_ko = '모양을 구멍에 척척 끼우나요? 두뇌를 더 키워 줄 연령별 퍼즐을 추천 제품 섹션에서 바로 찾아보세요.', title_nl = 'Op zoek naar slim speelgoed 🧩', body_nl = 'Is hij een kei in vormpjes in gaatjes stoppen? Ontdek meteen in Aanbevolen producten puzzels voor zijn leeftijd die zijn verstand nog verder scherpen.', title_pl = 'Szukamy mądrej zabawki 🧩', body_pl = 'Opanował wkładanie figur do otworów? Od razu odkryj w sekcji Polecane produkty układanki dopasowane do wieku, które jeszcze bardziej wyostrzą jego umysł.', title_pt = 'À procura de brinquedos inteligentes 🧩', body_pt = 'Já é mestre a encaixar formas nos buracos? Descubra já na secção Produtos Recomendados puzzles adequados à idade, que vão aguçar ainda mais a inteligência dele.', title_sv = 'På jakt efter smarta leksaker 🧩', body_sv = 'Har barnet blivit en mästare på att stoppa figurer i hål? Upptäck direkt åldersanpassade pussel som skärper tänkandet ännu mer i Rekommenderade produkter.', title_vi = 'Tìm đồ chơi thông minh 🧩', body_vi = 'Bé đã thành thạo thả hình khối vào lỗ? Hãy khám phá ngay các bộ ghép hình phù hợp lứa tuổi giúp bé thêm nhanh trí trong mục Sản phẩm gợi ý.', title_zh = '寻找聪明玩具 🧩', body_zh = '已经能熟练地把形状块塞进洞里了？马上去推荐商品板块，发现让宝宝更聪明的适龄拼图吧。' WHERE id = '890ee8d7-3315-4b7a-994a-c41900d8c960' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué llora de repente? 🤖', body_es = '¿Jugaba tan tranquilo y de repente le cambió el humor y se echó a llorar? Escribe a nuestro asistente experto Anacan AI para entender la causa de estos altibajos emocionales.', title_fr = 'Pourquoi pleure-t-il soudain ? 🤖', body_fr = 'Il jouait tranquillement et soudain son humeur a changé et il s''est mis à pleurer ? Écrivez à notre assistant expert Anacan AI pour comprendre ces montagnes russes émotionnelles.', title_hi = 'अचानक क्यों रोता है? 🤖', body_hi = 'अच्छे से खेलते-खेलते अचानक मूड बदला और रोने लगा? भावनाओं के इस उतार-चढ़ाव की वजह जानने के लिए हमारे Anacan AI एक्सपर्ट असिस्टेंट को लिखिए।', title_id = 'Kenapa tiba-tiba menangis? 🤖', body_id = 'Sedang asyik bermain lalu tiba-tiba suasana hatinya berubah dan menangis? Tanyakan kepada asisten ahli Anacan AI untuk mencari penyebab naik turunnya emosi ini.', title_ja = 'どうして急に泣くの？🤖', body_ja = '楽しく遊んでいたのに、急に機嫌が変わって泣き出しましたか？気持ちの揺れの原因を知るために、Anacan AIのエキスパートアシスタントに書き込んでみましょう。', title_ko = '왜 갑자기 울까요? 🤖', body_ko = '잘 놀다가 갑자기 기분이 바뀌어 울기 시작했나요? 감정 기복의 이유를 알고 싶다면 Anacan AI 전문가 도우미에게 물어보세요.', title_nl = 'Waarom huilt hij ineens? 🤖', body_nl = 'Speelde hij heerlijk en sloeg zijn stemming ineens om in huilen? Schrijf naar onze Anacan AI-expert om de oorzaak van die emotionele schommelingen te vinden.', title_pl = 'Dlaczego nagle płacze? 🤖', body_pl = 'Bawił się w najlepsze i nagle zmienił mu się humor i zaczął płakać? Napisz do naszego eksperta Anacan AI, by poznać przyczynę tych emocjonalnych wahań.', title_pt = 'Porque chora de repente? 🤖', body_pt = 'Estava a brincar muito bem e, de repente, mudou de humor e começou a chorar? Escreva ao nosso assistente especialista Anacan AI para perceber a causa destas oscilações emocionais.', title_sv = 'Varför gråter barnet plötsligt? 🤖', body_sv = 'Ändrades humöret plötsligt mitt i en rolig lek och barnet började gråta? Skriv till vår expertassistent Anacan AI för att hitta orsaken till känslosvängningarna.', title_vi = 'Vì sao bé bỗng dưng khóc? 🤖', body_vi = 'Đang chơi vui thì bé bỗng đổi tâm trạng và bật khóc? Hãy nhắn cho trợ lý chuyên gia Anacan AI để tìm hiểu nguyên nhân của những dao động cảm xúc này.', title_zh = '为什么突然大哭？🤖', body_zh = '玩得好好的，突然情绪一变就哭了起来？写信给我们的Anacan AI专家助手，找找情绪波动的原因。' WHERE id = '2e662854-2d0b-4e0d-be84-f71f33b1ed5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Su inteligencia no para de crecer 🧠', body_es = '¡Le encanta clasificarlo todo! Lee sin falta en el Blog el artículo sobre juegos caseros que mejoran la percepción de colores y formas a los 20-21 meses.', title_fr = 'Son intelligence ne cesse de grandir 🧠', body_fr = 'Il adore tout trier ! Lisez absolument l''article de la rubrique Blogs sur les jeux à la maison qui développent la perception des couleurs et des formes à 20-21 mois.', title_hi = 'बुद्धि का विकास रुकता नहीं 🧠', body_hi = 'उसे हर चीज़ छाँटना पसंद है! ब्लॉग सेक्शन में 20-21 महीने के बच्चों में रंग और आकार की समझ बढ़ाने वाले घरेलू खेलों पर लेख ज़रूर पढ़िए।', title_id = 'Kecerdasannya terus berkembang 🧠', body_id = 'Ia suka memilah-milah segala hal! Baca artikel di bagian Blog tentang permainan rumahan yang meningkatkan pengenalan warna dan bentuk untuk anak usia 20-21 bulan.', title_ja = '知性の発達は止まらない 🧠', body_ja = 'なんでも分類するのが大好き！1歳8-9か月の子の色や形の認識を育てるおうち遊びについて、ブログの記事をぜひ読んでみましょう。', title_ko = '두뇌 발달은 멈추지 않아요 🧠', body_ko = '뭐든 분류하는 걸 좋아해요! 블로그에서 20~21개월 아이의 색과 모양 인지를 키우는 집 놀이에 관한 글을 꼭 읽어 보세요.', title_nl = 'De slimheid groeit door 🧠', body_nl = 'Hij sorteert graag alles! Lees zeker het artikel in Blogs over spelletjes voor thuis die kleur- en vormherkenning bij kinderen van 20-21 maanden versterken.', title_pl = 'Umysł nieustannie się rozwija 🧠', body_pl = 'Uwielbia wszystko sortować! Koniecznie przeczytaj w sekcji Blog artykuł o domowych zabawach, które rozwijają postrzeganie kolorów i kształtów u dzieci w wieku 20-21 miesięcy.', title_pt = 'A inteligência não para de crescer 🧠', body_pt = 'Adora separar tudo por grupos! Leia sem falta nos Blogues o artigo sobre jogos caseiros que melhoram a perceção de cores e formas em crianças de 20-21 meses.', title_sv = 'Tänkandet utvecklas hela tiden 🧠', body_sv = 'Barnet älskar att sortera allt! Läs artikeln i Bloggar om lekar hemma som stärker uppfattningen av färger och former hos barn på 20-21 månader.', title_vi = 'Trí tuệ không ngừng phát triển 🧠', body_vi = 'Bé thích phân loại mọi thứ! Nhất định hãy đọc bài viết trong mục Blog về các trò chơi tại nhà giúp trẻ 20-21 tháng nhận biết màu sắc và hình dạng tốt hơn.', title_zh = '智力发展从不停歇 🧠', body_zh = '宝宝什么都爱分类！一定要读读博客板块里关于提升20-21个月宝宝颜色和形状认知的居家游戏文章。' WHERE id = 'b30cbe06-794a-4924-bc78-63ebe289b716' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía en 5 minutos 🔋', body_es = 'Tomar café en ayunas acabará con tu energía a mediodía. Elige en Recetas saludables un bizcocho de avena delicioso, rápido y que sacia.', title_fr = '5 minutes d''énergie 🔋', body_fr = 'Un café à jeun, et votre énergie s''effondre à midi. Choisissez plutôt dans les Recettes saines un délicieux muffin à l''avoine, vite prêt et rassasiant.', title_hi = '5 मिनट की ऊर्जा 🔋', body_hi = 'खाली पेट कॉफ़ी पीने से आपकी ऊर्जा दोपहर तक खत्म हो जाएगी। सेहतमंद रेसिपी से झटपट बनने वाला, पेट भरा रखने वाला स्वादिष्ट ओट्स मफ़िन चुनिए।', title_id = 'Energi 5 menit 🔋', body_id = 'Minum kopi saat perut kosong akan menghabiskan energi Anda sebelum siang. Pilih muffin oat lezat yang mengenyangkan dan cepat dibuat dari Resep Sehat.', title_ja = '5分でエネルギーチャージ 🔋', body_ja = '空腹のままコーヒーを飲むと、お昼にはエネルギー切れに。「ヘルシーレシピ」から、すぐにできて腹持ちのいいおいしいオートミールマフィンを選びましょう。', title_ko = '5분 에너지 충전 🔋', body_ko = '빈속에 마시는 커피는 오후가 되면 기운을 바닥내요. 건강한 레시피에서 금방 만들 수 있는 든든하고 맛있는 오트밀 머핀을 골라 보세요.', title_nl = 'Energie in 5 minuten 🔋', body_nl = 'Koffie op een lege maag laat je energie in de middag opraken. Kies uit Gezonde recepten een snel klaar, lekker en vullend havermuffin.', title_pl = 'Energia w 5 minut 🔋', body_pl = 'Kawa na pusty żołądek sprawi, że do południa zabraknie ci energii. Wybierz ze Zdrowych przepisów szybką, sycącą i pyszną babeczkę owsianą.', title_pt = 'Energia em 5 minutos 🔋', body_pt = 'Beber café em jejum vai esgotar a sua energia a meio do dia. Escolha nas Receitas Saudáveis um queque de aveia saboroso, rápido de fazer e que sacia.', title_sv = 'Energi på 5 minuter 🔋', body_sv = 'Kaffe på fastande mage tar slut på din energi redan till lunch. Välj en god och mättande havremuffins som går snabbt att göra från Hälsosamma recept.', title_vi = 'Năng lượng trong 5 phút 🔋', body_vi = 'Uống cà phê lúc bụng đói sẽ khiến mẹ cạn năng lượng vào buổi trưa. Hãy chọn một chiếc bánh muffin yến mạch thơm ngon, no lâu, làm nhanh từ Công thức lành mạnh.', title_zh = '5分钟能量补给 🔋', body_zh = '空腹喝咖啡，到中午精力就耗光了。从健康食谱里选一款马上能做、又顶饱的美味燕麦玛芬吧。' WHERE id = 'dcfe0150-6b59-46be-be17-cba289272768' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena 🏖️', body_es = '¡No tengas miedo a que se ensucie! Busca en Lugares para mamás un sitio con arenero. Tocar la arena es mejor para su desarrollo sensorial que los juguetes caros.', title_fr = 'Thérapie par le sable 🏖️', body_fr = 'N''ayez pas peur qu''il se salisse ! Trouvez un lieu avec bac à sable dans les Lieux adaptés aux mamans. Toucher le sable aide plus son développement sensoriel que des jouets coûteux.', title_hi = 'रेत थेरेपी 🏖️', body_hi = 'गंदा होने से मत डरिए! माँ के लिए अनुकूल जगहें में सैंडपिट वाली जगह ढूँढिए। रेत छूना सेंसरी विकास के लिए महँगे खिलौनों से ज़्यादा फ़ायदेमंद है।', title_id = 'Terapi pasir 🏖️', body_id = 'Jangan takut kotor! Temukan tempat dengan bak pasir di Tempat Ramah Ibu. Menyentuh pasir lebih bermanfaat untuk perkembangan sensorik daripada mainan mahal.', title_ja = '砂あそびセラピー 🏖️', body_ja = '汚れるのをこわがらないで！「ママにやさしいスポット」で砂場のある場所を見つけましょう。砂にさわることは、高価なおもちゃよりも感覚の発達に役立ちます。', title_ko = '모래 놀이 테라피 🏖️', body_ko = '더러워지는 걸 두려워하지 마세요! 엄마 친화 장소에서 모래 놀이터가 있는 곳을 찾아보세요. 모래를 만지는 건 비싼 장난감보다 감각 발달에 더 좋아요.', title_nl = 'Zandtherapie 🏖️', body_nl = 'Wees niet bang voor vieze handjes! Zoek in Mamavriendelijke plekken een plek met een zandbak. Zand voelen is voor de zintuiglijke ontwikkeling nuttiger dan duur speelgoed.', title_pl = 'Terapia piaskiem 🏖️', body_pl = 'Nie bój się brudu! Znajdź w Miejscach przyjaznych mamom miejsce z piaskownicą. Dotykanie piasku jest dla rozwoju sensorycznego cenniejsze niż drogie zabawki.', title_pt = 'Terapia com areia 🏖️', body_pt = 'Não tenha medo que se suje! Encontre nos Locais Amigos das Mães um sítio com caixa de areia. Tocar na areia é mais útil para o desenvolvimento sensorial do que brinquedos caros.', title_sv = 'Sandterapi 🏖️', body_sv = 'Var inte rädd för smuts! Hitta ett ställe med sandlåda i Mammavänliga platser. Att känna på sand är nyttigare för sinnesutvecklingen än dyra leksaker.', title_vi = 'Liệu pháp cát 🏖️', body_vi = 'Đừng sợ bé bị bẩn! Hãy tìm một nơi có hố cát trong Địa điểm thân thiện với mẹ. Chạm vào cát giúp phát triển giác quan hơn cả đồ chơi đắt tiền.', title_zh = '沙子疗法 🏖️', body_zh = '别怕弄脏！在妈妈友好场所里找一个有沙池的地方。触摸沙子对感官发展的好处比昂贵的玩具还大。' WHERE id = '41523bc6-ac22-4b48-a7b5-8663ed9c74c3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Artista cubierto de pintura! 📸', body_es = '¿Se ha pintado a sí mismo y la pared? En lugar de enfadarte, sube este momento tan gracioso de garabatos al Álbum del bebé y ponle pegatinas divertidas.', title_fr = 'Un artiste couvert de peinture ! 📸', body_fr = 'Il s''est peint lui-même, et le mur avec ? Au lieu de vous énerver, ajoutez ce gribouillage rigolo à l''Album de bébé et décorez-le de stickers amusants.', title_hi = 'रंगों में डूबा कलाकार! 📸', body_hi = 'खुद को और दीवार को रंग दिया? गुस्सा होने के बजाय इस मज़ेदार चित्रकारी वाले पल को बेबी एल्बम में अपलोड कीजिए और मज़ेदार स्टिकर लगाइए।', title_id = 'Seniman berlumur cat! 📸', body_id = 'Ia mewarnai dirinya dan dinding? Daripada kesal, unggah momen corat-coret yang lucu ini ke Album Bayi dan tempelkan stiker seru di atasnya.', title_ja = '絵の具まみれのアーティスト！📸', body_ja = '自分も壁も絵の具だらけに？怒る代わりに、このおもしろいお絵かきの瞬間を「ベビーアルバム」にアップして、楽しいステッカーを貼りましょう。', title_ko = '물감투성이 예술가! 📸', body_ko = '자기 몸과 벽을 칠했나요? 화내는 대신 이 재미있는 낙서의 순간을 아기 앨범에 올리고 재미있는 스티커를 붙여 보세요.', title_nl = 'Kunstenaar onder de verf! 📸', body_nl = 'Heeft hij zichzelf en de muur beschilderd? Word niet boos, maar zet dit grappige krabbelmoment in het Babyalbum en plak er leuke stickers op.', title_pl = 'Artysta cały w farbie! 📸', body_pl = 'Pomalował siebie i ścianę? Zamiast się złościć, dodaj tę zabawną chwilę bazgrania do Albumu dziecka i ozdób ją wesołymi naklejkami.', title_pt = 'Artista coberto de tinta! 📸', body_pt = 'Pintou-se a si próprio e à parede? Em vez de se enervar, carregue este momento divertido de rabiscos no Álbum do Bebé e cole-lhe autocolantes engraçados.', title_sv = 'Konstnär full av färg! 📸', body_sv = 'Har barnet målat både sig själv och väggen? I stället för att bli irriterad, ladda upp det roliga klotterögonblicket i Babyalbumet och dekorera med roliga klistermärken.', title_vi = 'Nghệ sĩ lấm lem màu vẽ! 📸', body_vi = 'Bé tô màu lên cả người và tường? Thay vì bực mình, hãy tải khoảnh khắc vẽ nguệch ngoạc vui nhộn này lên Album của bé và dán thêm sticker ngộ nghĩnh.', title_zh = '满身颜料的小艺术家！📸', body_zh = '把自己和墙都涂花了？与其生气，不如把这个有趣的涂鸦时刻上传到宝宝相册，再贴上好玩的贴纸。' WHERE id = '863859ae-c920-41fe-b876-915ee50bba17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El monstruo de las tortitas 🥞', body_es = '¿Rechaza el desayuno? Prueba en Recetas para bebé las tortitas de plátano sin azúcar. Podrá cogerlas y comerlas solo, y se le abrirá el apetito.', title_fr = 'Le monstre des pancakes 🥞', body_fr = 'Il refuse le petit-déjeuner ? Essayez la recette de pancakes à la banane sans sucre des Recettes pour bébés. Il les mangera tout seul avec les mains, et l''appétit reviendra.', title_hi = 'पैनकेक मॉन्स्टर 🥞', body_hi = 'नाश्ते से मना करता है? बच्चों की रेसिपी में बिना चीनी वाला केले का पैनकेक देखिए। वह उसे हाथ में लेकर खुद खाएगा और उसकी भूख भी खुलेगी।', title_id = 'Monster panekuk 🥞', body_id = 'Menolak sarapan? Coba resep panekuk pisang tanpa gula di Resep Bayi. Ia bisa memegang dan memakannya sendiri, dan nafsu makannya pun terbuka.', title_ja = 'パンケーキモンスター 🥞', body_ja = '朝ごはんを嫌がりますか？「離乳食を始める赤ちゃんのレシピ」で、砂糖不使用のバナナパンケーキのレシピをチェックしましょう。自分で持って食べられて、食欲もわいてきます。', title_ko = '팬케이크 괴물 🥞', body_ko = '아침밥을 거부하나요? 아기 레시피에서 설탕 없는 바나나 팬케이크를 확인해 보세요. 손에 들고 혼자 먹으면서 입맛도 살아날 거예요.', title_nl = 'Pannenkoekenmonster 🥞', body_nl = 'Wil hij niet ontbijten? Probeer in Babyrecepten de suikervrije bananenpannenkoekjes. Hij kan ze zelf vastpakken en eten, en krijgt er trek van.', title_pl = 'Naleśnikowy potwór 🥞', body_pl = 'Nie chce jeść śniadania? Sprawdź w Przepisach dla niemowląt przepis na bananowe placuszki bez cukru. Sam weźmie je do rączki i zje, a apetyt wróci.', title_pt = 'O monstro das panquecas 🥞', body_pt = 'Recusa o pequeno-almoço? Experimente nas Receitas para bebés a receita de panquecas de banana sem açúcar. Vai pegar nelas e comer sozinho, e o apetite vai abrir.', title_sv = 'Pannkaksmonstret 🥞', body_sv = 'Vägrar barnet frukost? Prova receptet på sockerfria bananpannkakor i Recept för bebisar. Barnet kan hålla dem och äta själv, och aptiten väcks.', title_vi = 'Quái vật bánh kếp 🥞', body_vi = 'Bé không chịu ăn sáng? Hãy thử công thức bánh kếp chuối không đường trong Công thức cho bé. Bé vừa tự cầm ăn được, vừa ăn ngon miệng hơn.', title_zh = '松饼小怪兽 🥞', body_zh = '不肯吃早餐？看看宝宝食谱里的无糖香蕉松饼。宝宝既能自己拿着吃，胃口也会变好。' WHERE id = 'af623bf2-6a45-452d-a9c0-bd16d67bf74d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Clase de física con agua 🛁', body_es = '¿En el baño no se cansa de pasar agua de un vaso a otro? Echa un vistazo en Productos recomendados a juguetes de agua divertidos y relajantes.', title_fr = 'Un cours de physique avec de l''eau 🛁', body_fr = 'Dans le bain, il ne se lasse pas de transvaser l''eau d''un gobelet à l''autre ? Jetez un œil aux jouets de bain amusants et apaisants des Produits recommandés.', title_hi = 'पानी के साथ फ़िज़िक्स की क्लास 🛁', body_hi = 'नहाते समय पानी एक गिलास से दूसरे में डालते थकता नहीं? इन मज़ेदार और सुकून देने वाले पानी के खिलौनों के लिए सुझाए गए प्रोडक्ट देखिए।', title_id = 'Pelajaran fisika dengan air 🛁', body_id = 'Tak bosan menuang air dari satu gelas ke gelas lain saat mandi? Lihat mainan air yang seru dan menenangkan di Produk Rekomendasi.', title_ja = '水で学ぶ物理のレッスン 🛁', body_ja = 'お風呂でコップからコップへ水を移すのに夢中ですか？楽しくて心が落ち着く水遊びのおもちゃを、「おすすめ商品」でのぞいてみましょう。', title_ko = '물로 배우는 과학 시간 🛁', body_ko = '목욕할 때 컵에서 컵으로 물 옮기기를 끝없이 하나요? 재미있고 마음을 차분하게 하는 물놀이 장난감을 추천 제품에서 살펴보세요.', title_nl = 'Natuurkundeles met water 🛁', body_nl = 'Wordt hij in bad nooit moe van water van het ene bekertje in het andere gieten? Bekijk Aanbevolen producten voor leuk en rustgevend waterspeelgoed.', title_pl = 'Lekcja fizyki z wodą 🛁', body_pl = 'W kąpieli bez końca przelewa wodę z kubeczka do kubeczka? Zajrzyj do Polecanych produktów po zabawne i uspokajające zabawki do wody.', title_pt = 'Aula de física com água 🛁', body_pt = 'No banho não se cansa de passar água de um copo para outro? Espreite nos Produtos Recomendados brinquedos de água divertidos e calmantes.', title_sv = 'Fysiklektion med vatten 🛁', body_sv = 'Blir barnet aldrig trött på att hälla vatten från en mugg till en annan i badet? Titta på roliga och lugnande vattenleksaker i Rekommenderade produkter.', title_vi = 'Bài học vật lý với nước 🛁', body_vi = 'Bé không chán việc rót nước từ cốc này sang cốc khác trong bồn tắm? Hãy xem Sản phẩm gợi ý để tìm những đồ chơi nước vui nhộn và giúp bé bình tĩnh.', title_zh = '玩水物理课 🛁', body_zh = '在浴室里把水从一个杯子倒进另一个杯子，怎么都玩不腻？去推荐商品看看这些有趣又能让人平静下来的戏水玩具。' WHERE id = 'a7786d73-a362-4a32-a77f-3c09e4ab2ffb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de calcio 🦴', body_es = 'El calcio es imprescindible para dientes y huesos. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de yogur y queso.', title_fr = 'Bouclier calcium 🦴', body_fr = 'Le calcium est indispensable aux dents et aux os. Vérifiez avec le Suivi des repas qu''il a bien eu sa ration de yaourt et de fromage aujourd''hui.', title_hi = 'कैल्शियम की ढाल 🦴', body_hi = 'दाँतों और हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज दही और पनीर की मात्रा पूरी हुई।', title_id = 'Perisai kalsium 🦴', body_id = 'Kalsium wajib untuk gigi dan tulang. Pastikan dengan alat Pemantau Nutrisi bahwa porsi yogurt dan keju hari ini sudah terpenuhi.', title_ja = 'カルシウムのシールド 🦴', body_ja = '歯と骨にはカルシウムが欠かせません。「栄養管理ツール」で、今日のヨーグルトやチーズの目安量をとれたか確認しましょう。', title_ko = '칼슘 방패 🦴', body_ko = '치아와 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 요거트와 치즈 기준량을 채웠는지 확인하세요.', title_nl = 'Calciumschild 🦴', body_nl = 'Calcium is onmisbaar voor tanden en botten. Check met de Voedingstracker of hij vandaag genoeg yoghurt en kaas heeft gehad.', title_pl = 'Tarcza z wapnia 🦴', body_pl = 'Wapń jest niezbędny dla zębów i kości. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja jogurtu i sera została osiągnięta.', title_pt = 'Escudo de cálcio 🦴', body_pt = 'O cálcio é indispensável para os dentes e os ossos. Confirme com o Registo de Alimentação que hoje cumpriu a dose de iogurte e queijo.', title_sv = 'Kalciumskölden 🦴', body_sv = 'Kalcium är ett måste för tänder och skelett. Kontrollera med Matningskoll att barnet fått dagens norm av yoghurt och ost.', title_vi = 'Lá chắn canxi 🦴', body_vi = 'Canxi rất cần cho răng và xương. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sữa chua, phô mai chưa.', title_zh = '钙的护盾 🦴', body_zh = '钙对牙齿和骨骼必不可少。用喂养记录工具确认今天酸奶、奶酪的参考量是否达到了。' WHERE id = 'ccc521b5-a8ef-4b74-a8d7-bf2ba2f22793' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño y sigue el gráfico. Quizá sea el momento de acortar la siesta 15 minutos.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil et suivez le graphique. C''est peut-être le bon moment pour raccourcir la sieste de 15 minutes.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 15 मिनट कम करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin inilah saatnya memangkas tidur siang 15 menit.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにして、グラフをチェックしましょう。お昼寝を15分短くするちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 15분 줄일 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan en volg de grafiek. Misschien is het precies tijd om het middagdutje met 15 minuten in te korten.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu i śledź wykres. Może to dobry moment, by skrócić drzemkę o 15 minut.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono e acompanhe o gráfico. Talvez seja a altura certa de encurtar a sesta 15 minutos.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern och följ grafen. Kanske är det precis rätt tid att korta dagsömnen med 15 minuter.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 15 phút.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器，看看图表。也许正是把白天小睡缩短15分钟的时候了。' WHERE id = 'e8d46282-de1c-4981-9242-f0dff7014b1d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Dulces sueños o batalla? 🛌', body_es = 'Si irse a la cama se ha convertido en una gran crisis, pregunta enseguida a Anacan AI por rituales para dormir y trucos psicológicos para niños de 21 meses.', title_fr = 'Doux sommeil ou bataille ? 🛌', body_fr = 'Le coucher est devenu une grosse crise ? Demandez tout de suite à Anacan AI des rituels d''endormissement et des astuces psychologiques pour les enfants de 21 mois.', title_hi = 'मीठी नींद या जंग? 🛌', body_hi = 'अगर सोने जाना बड़ा झगड़ा बन गया है, तो Anacan AI से 21 महीने के बच्चों के लिए नींद में जाने की रस्में और मनोवैज्ञानिक तरकीबें तुरंत पूछिए।', title_id = 'Tidur nyenyak, atau perang? 🛌', body_id = 'Jika waktu tidur berubah jadi drama besar, segera tanyakan kepada Anacan AI ritual menjelang tidur dan trik psikologis untuk anak usia 21 bulan.', title_ja = 'すやすや眠る？それとも戦い？🛌', body_ja = '寝る時間が大きなかんしゃくの時間になっているなら、1歳9か月の子のための入眠の習慣と心理的なコツを、すぐにAnacan AIに聞いてみましょう。', title_ko = '달콤한 잠, 아니면 전쟁? 🛌', body_ko = '잠자리에 드는 게 큰 전쟁이 되었다면 Anacan AI에게 21개월 아이를 위한 잠자리 의식과 심리 요령을 바로 물어보세요.', title_nl = 'Zoete slaap of oorlog? 🛌', body_nl = 'Is naar bed gaan een grote strijd geworden? Vraag Anacan AI meteen naar slaaprituelen en psychologische trucjes voor kinderen van 21 maanden.', title_pl = 'Słodki sen czy wojna? 🛌', body_pl = 'Jeśli kładzenie się spać zamieniło się w wielki kryzys, od razu zapytaj Anacan AI o rytuały zasypiania i psychologiczne sztuczki dla dzieci w wieku 21 miesięcy.', title_pt = 'Sono doce ou guerra? 🛌', body_pt = 'Se ir para a cama se tornou uma grande crise, pergunte já ao Anacan AI rituais de transição para o sono e truques psicológicos para crianças de 21 meses.', title_sv = 'Söt sömn eller krig? 🛌', body_sv = 'Har läggdags blivit ett stort utbrott? Fråga Anacan AI direkt om insomningsritualer och psykologiska knep för barn på 21 månader.', title_vi = 'Giấc ngủ ngọt ngào hay cuộc chiến? 🛌', body_vi = 'Nếu giờ đi ngủ đã thành cuộc khủng hoảng lớn, hãy hỏi ngay Anacan AI về các nghi thức trước giờ ngủ và mẹo tâm lý cho trẻ 21 tháng tuổi.', title_zh = '甜美的梦，还是一场战争？🛌', body_zh = '上床睡觉变成了大崩溃？马上问问Anacan AI，了解21个月宝宝的入睡仪式和心理小技巧。' WHERE id = '527e5a17-444d-47c4-8578-4ebb1ee870b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal la noche? 🌙', body_es = 'Si el pañal de la mañana pesa mucho, quizá haya que ajustar los líquidos de la noche. Anótalo en el Seguimiento de pañales y revisa el equilibrio de agua del día.', title_fr = 'Comment s''est passée la nuit ? 🌙', body_fr = 'Si la couche du matin est très lourde, il faut peut-être ajuster ce qu''il boit le soir. Notez-le dans le Suivi des couches et vérifiez son hydratation sur la journée.', title_hi = 'रात कैसी बीती? 🌙', body_hi = 'अगर सुबह का डायपर बहुत भारी है, तो रात में तरल लेने को ठीक करने की ज़रूरत हो सकती है। डायपर ट्रैकर में दर्ज कीजिए और दिनभर का पानी का संतुलन देखिए।', title_id = 'Bagaimana malamnya? 🌙', body_id = 'Jika popok paginya sangat berat, asupan cairan di malam hari mungkin perlu diatur. Catat di Pelacak Popok dan cek keseimbangan cairannya sepanjang hari.', title_ja = '夜はどうでしたか？🌙', body_ja = '朝のおむつがとても重いなら、夜の水分のとり方を調整する必要があるかもしれません。「おむつトラッカー」に記録して、一日の水分バランスを確認しましょう。', title_ko = '밤은 어땠나요? 🌙', body_ko = '아침 기저귀가 아주 무겁다면 밤 수분 섭취를 조절해야 할 수 있어요. 기저귀 기록에 남기고 하루 동안의 수분 균형을 확인하세요.', title_nl = 'Hoe was de nacht? 🌙', body_nl = 'Is de ochtendluier erg zwaar? Dan moet je misschien het drinken in de avond aanpassen. Noteer het in de Luiertracker en controleer zijn vochtbalans over de dag.', title_pl = 'Jak minęła noc? 🌙', body_pl = 'Jeśli poranna pieluszka jest bardzo ciężka, może trzeba ograniczyć picie wieczorem. Zapisz to w narzędziu do śledzenia pieluszek i sprawdź bilans wody w ciągu dnia.', title_pt = 'Como correu a noite? 🌙', body_pt = 'Se a fralda da manhã está muito pesada, pode ser preciso ajustar os líquidos da noite. Registe-o no Registo de Fraldas e verifique o equilíbrio de água ao longo do dia.', title_sv = 'Hur gick natten? 🌙', body_sv = 'Är morgonblöjan väldigt tung kan vätskeintaget på kvällen behöva justeras. Anteckna i Blöjkollen och kontrollera vätskebalansen under dagen.', title_vi = 'Đêm qua thế nào? 🌙', body_vi = 'Nếu tã buổi sáng quá nặng, có thể cần điều chỉnh lượng nước bé uống buổi tối. Hãy ghi lại trong Theo dõi tã và kiểm tra cân bằng nước trong ngày.', title_zh = '昨晚过得怎么样？🌙', body_zh = '早上的尿布很沉的话，可能需要调整晚上的饮水量。记在尿布记录里，看看一整天的水分平衡。' WHERE id = '9c6e3d93-ba09-4cda-8c01-9c820b1e3ed6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Motricidad de los dedos 🧩', body_es = 'Ya domina encajar las figuras en su sitio. Descubre ahora en Productos recomendados puzles adecuados a su edad que afinarán aún más su inteligencia.', title_fr = 'Motricité des doigts 🧩', body_fr = 'Il est devenu expert pour emboîter les formes. Découvrez tout de suite dans les Produits recommandés des puzzles adaptés à son âge pour affûter encore son intelligence.', title_hi = 'उँगलियों की मोटर स्किल्स 🧩', body_hi = 'आकृतियों को सही जगह डालने में माहिर हो गया है। उसकी बुद्धि को और तेज़ करने वाली, उम्र के हिसाब से पज़ल तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Motorik jari 🧩', body_id = 'Ia sudah mahir memasukkan bentuk ke tempatnya. Temukan puzzle sesuai usia yang makin mengasah kecerdasannya di bagian Produk Rekomendasi.', title_ja = '指先の運動 🧩', body_ja = '形をぴったりはめるのが上手になってきました。知性をさらに磨く、年齢に合ったパズルを「おすすめ商品」ですぐに見つけましょう。', title_ko = '손가락 소근육 🧩', body_ko = '모양을 제자리에 척척 끼워요. 두뇌를 더 키워 줄 연령별 퍼즐을 추천 제품 섹션에서 바로 찾아보세요.', title_nl = 'Fijne motoriek van de vingers 🧩', body_nl = 'Hij is een kei in vormpjes op hun plek stoppen. Ontdek meteen in Aanbevolen producten puzzels voor zijn leeftijd die zijn verstand nog verder scherpen.', title_pl = 'Motoryka paluszków 🧩', body_pl = 'Opanował wkładanie figur na miejsce. Od razu odkryj w sekcji Polecane produkty układanki dopasowane do wieku, które jeszcze bardziej wyostrzą jego umysł.', title_pt = 'Motricidade dos dedos 🧩', body_pt = 'Já é mestre a encaixar as formas no sítio certo. Descubra já na secção Produtos Recomendados puzzles adequados à idade, que vão aguçar ainda mais a inteligência dele.', title_sv = 'Fingermotorik 🧩', body_sv = 'Barnet har blivit en mästare på att sätta figurerna på rätt plats. Upptäck direkt åldersanpassade pussel som skärper tänkandet ännu mer i Rekommenderade produkter.', title_vi = 'Vận động tinh của ngón tay 🧩', body_vi = 'Bé đã thành thạo đặt các hình khối vào đúng chỗ. Hãy khám phá ngay các bộ ghép hình phù hợp lứa tuổi giúp bé thêm nhanh trí trong mục Sản phẩm gợi ý.', title_zh = '手指精细动作 🧩', body_zh = '已经能熟练地把形状块放到对应位置了。马上去推荐商品板块，发现让宝宝更聪明的适龄拼图吧。' WHERE id = 'ac8ebb1f-1fc4-47f7-86d8-2eb0fa26e0a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de bajar el ritmo 🎶', body_es = 'Un día tan activo puede cansar el cerebro. Pon el susurro del bosque de Ruido blanco y crea en la habitación un fondo relajante perfecto que invite al sueño.', title_fr = 'L''heure de ralentir 🎶', body_fr = 'Une journée active peut fatiguer le cerveau. Lancez le bruissement de la forêt des Bruits blancs pour créer dans la chambre un fond apaisant parfait pour s''endormir.', title_hi = 'धीमे होने का समय 🎶', body_hi = 'भाग-दौड़ भरा दिन दिमाग को थका सकता है। व्हाइट नॉइज़ में जंगल की सरसराहट चलाकर कमरे में सुकून भरा, नींद लाने वाला बढ़िया माहौल बनाइए।', title_id = 'Waktunya mengerem 🎶', body_id = 'Hari yang aktif bisa melelahkan otak. Putar suara gemerisik hutan dari Suara Putih dan ciptakan latar yang menenangkan dan mengundang kantuk di kamar.', title_ja = 'ブレーキをかける時間 🎶', body_ja = '活発な一日は脳を疲れさせることがあります。「ホワイトノイズ」の森のざわめきを流して、部屋に心落ち着く、眠りを誘う最高のBGMをつくりましょう。', title_ko = '속도를 늦출 시간 🎶', body_ko = '활발한 하루는 머리를 지치게 할 수 있어요. 백색소음의 숲 바스락 소리를 틀어 방에 차분하고 잠이 솔솔 오는 완벽한 배경을 만들어 주세요.', title_nl = 'Tijd om af te remmen 🎶', body_nl = 'Een actieve dag kan het hoofdje vermoeien. Zet bosgeruis uit Witte ruis aan en creëer in de kamer een rustgevende achtergrond die slaap brengt.', title_pl = 'Czas na wyciszenie 🎶', body_pl = 'Aktywny dzień może zmęczyć umysł. Włącz szum lasu z Białego szumu i stwórz w pokoju idealne, kojące tło do snu.', title_pt = 'Hora de abrandar 🎶', body_pt = 'Um dia ativo pode cansar o cérebro. Ligue o sussurro da floresta do Ruído Branco e crie no quarto o fundo perfeito, calmante e que dá sono.', title_sv = 'Dags att bromsa in 🎶', body_sv = 'En aktiv dag kan trötta ut hjärnan. Sätt på skogens sus från Vitt brus och skapa en perfekt lugnande och sövande bakgrund i rummet.', title_vi = 'Giờ để chậm lại 🎶', body_vi = 'Một ngày năng động có thể khiến não bộ mệt mỏi. Hãy bật tiếng rì rào của rừng trong Tiếng ồn trắng để tạo nền âm thanh êm dịu, dễ ngủ trong phòng.', title_zh = '踩刹车的时间 🎶', body_zh = '活跃的一天会让大脑疲惫。打开白噪音里的森林沙沙声，在房间里营造让人平静、催人入睡的完美背景音。' WHERE id = 'b322d3bf-6cd3-46c1-9a5f-bb9f3a106c60' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Invítate a un café ☕', body_es = '¡Estás agotada de correr todo el día! Busca en el mapa de Lugares para mamás una cafetería con zona de juegos infantil y date un pequeño capricho.', title_fr = 'Offrez-vous un café ☕', body_fr = 'Vous êtes épuisée d''avoir couru toute la journée ! Trouvez sur la carte des Lieux adaptés aux mamans un café avec aire de jeux et faites-vous un petit plaisir.', title_hi = 'खुद को एक कॉफ़ी पिलाइए ☕', body_hi = 'पूरे दिन भागकर आप थककर चूर हो गईं! माँ के लिए अनुकूल जगहें के नक्शे में बच्चों के खेलने की जगह वाला कैफ़े ढूँढिए और खुद को एक छोटा सा तोहफ़ा दीजिए।', title_id = 'Traktir diri Anda kopi ☕', body_id = 'Kehabisan tenaga setelah berlari seharian! Temukan kafe dengan area bermain anak di peta Tempat Ramah Ibu dan manjakan diri Anda sedikit.', title_ja = '自分にコーヒーのごほうびを ☕', body_ja = '一日中走り回って、くたくたですね！「ママにやさしいスポット」のマップでキッズスペースのあるカフェを見つけて、自分に小さなごほうびをあげましょう。', title_ko = '나에게 커피 한 잔 선물하기 ☕', body_ko = '하루 종일 뛰어다니느라 기운이 다 빠졌죠! 엄마 친화 장소 지도에서 키즈 놀이 공간이 있는 카페를 찾아 나에게 작은 선물을 해 주세요.', title_nl = 'Trakteer jezelf op koffie ☕', body_nl = 'Je bent uitgeput van de hele dag rennen! Zoek op de kaart Mamavriendelijke plekken een café met speelhoek en gun jezelf iets kleins.', title_pl = 'Postaw sobie kawę ☕', body_pl = 'Cały dzień bieganiny wyczerpał cię! Znajdź na mapie Miejsc przyjaznych mamom kawiarnię z placem zabaw dla dzieci i zrób sobie małą przyjemność.', title_pt = 'Ofereça a si própria um café ☕', body_pt = 'Ficou sem forças de tanto correr o dia todo! Encontre no mapa dos Locais Amigos das Mães um café com espaço de brincar e dê a si própria um pequeno mimo.', title_sv = 'Bjud dig själv på kaffe ☕', body_sv = 'Du är helt slut efter en hel dag av springande! Hitta ett kafé med lekhörna på kartan i Mammavänliga platser och unna dig något litet.', title_vi = 'Tự thưởng cho mình ly cà phê ☕', body_vi = 'Mẹ đã kiệt sức sau cả ngày chạy theo bé! Hãy tìm một quán cà phê có khu vui chơi trẻ em trên bản đồ Địa điểm thân thiện với mẹ và tự chiều chuộng bản thân một chút.', title_zh = '请自己喝杯咖啡 ☕', body_zh = '跑了一整天，筋疲力尽了吧！在妈妈友好场所地图上找一家带儿童游乐区的咖啡馆，犒劳一下自己。' WHERE id = 'd93eedfc-78de-4d26-810d-89c2b8c71690' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales de la digestión 💩', body_es = 'El paso completo a alimentos sólidos puede complicar la digestión. Haz la anotación de la mañana en el Seguimiento de pañales y comprueba fácilmente si hay que ajustar el equilibrio de líquidos y fibra.', title_fr = 'Les signaux de la digestion 💩', body_fr = 'Le passage complet aux aliments solides peut compliquer la digestion. Notez la couche du matin dans le Suivi des couches et voyez facilement s''il faut ajuster l''équilibre liquides/fibres.', title_hi = 'पेट और आँतों के संकेत 💩', body_hi = 'ठोस खाने पर पूरी तरह आने से पाचन मुश्किल हो सकता है। डायपर ट्रैकर में सुबह की एंट्री कीजिए और आसानी से देखिए कि तरल/फ़ाइबर का संतुलन ठीक करने की ज़रूरत है या नहीं।', title_id = 'Sinyal dari perut 💩', body_id = 'Beralih penuh ke makanan padat bisa membuat pencernaan lebih sulit. Buat catatan pagi di Pelacak Popok dan cek dengan mudah apakah keseimbangan cairan/serat perlu diatur.', title_ja = 'おなかからのサイン 💩', body_ja = '固形食への完全な移行で、消化が大変になることがあります。「おむつトラッカー」に朝の記録をつけて、水分と食物繊維のバランスを調整する必要があるか簡単に確認しましょう。', title_ko = '장이 보내는 신호 💩', body_ko = '고형식으로 완전히 넘어가면 소화가 어려워질 수 있어요. 기저귀 기록에 아침 기록을 남기고 수분과 섬유질 균형을 조절해야 할지 쉽게 확인하세요.', title_nl = 'Signalen van de darmen 💩', body_nl = 'De volledige overstap op vast eten kan de spijsvertering lastiger maken. Noteer de ochtendluier in de Luiertracker en kijk makkelijk of de balans van vocht en vezels moet worden bijgesteld.', title_pl = 'Sygnały z brzuszka 💩', body_pl = 'Pełne przejście na stałe pokarmy może utrudniać trawienie. Zrób poranny wpis w narzędziu do śledzenia pieluszek i łatwo sprawdź, czy trzeba wyrównać bilans płynów i błonnika.', title_pt = 'Sinais do intestino 💩', body_pt = 'A passagem total para alimentos sólidos pode dificultar a digestão. Faça o registo da manhã no Registo de Fraldas e veja facilmente se é preciso ajustar o equilíbrio de líquidos e fibra.', title_sv = 'Signaler från magen 💩', body_sv = 'Den fullständiga övergången till fast föda kan göra matsmältningen trögare. Gör morgonanteckningen i Blöjkollen och se enkelt om balansen mellan vätska och fibrer behöver justeras.', title_vi = 'Tín hiệu từ đường ruột 💩', body_vi = 'Chuyển hẳn sang thức ăn đặc có thể khiến tiêu hóa khó khăn hơn. Hãy ghi lại lần thay tã buổi sáng trong Theo dõi tã và dễ dàng kiểm tra xem có cần điều chỉnh cân bằng nước/chất xơ không.', title_zh = '肠胃发出的信号 💩', body_zh = '完全过渡到固体食物可能让消化变难。在尿布记录里做好早上的记录，轻松看看是否需要调整水分和纤维的平衡。' WHERE id = 'a1bb5dc0-7875-44dc-a4df-f9fa8c0a427f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de rabietas? Pon el susurro de las hojas de Ruido blanco y regala un masaje al sistema nervioso de los dos.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée pleine de crises et de bruit ? Lancez le bruissement des feuilles des Bruits blancs pour masser son système nerveux comme le vôtre.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत नखरों और शोर भरा दिन था? व्हाइट नॉइज़ में पत्तों की सरसराहट चलाइए और उसके और अपने, दोनों के तंत्रिका तंत्र को आराम दीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari ini penuh tantrum dan bising? Putar suara gemerisik daun dari Suara Putih untuk menenangkan saraf ia dan Anda.', title_ja = '自然のリラックス効果 🍃', body_ja = 'かんしゃくが多く、にぎやかな一日でしたか？「ホワイトノイズ」の木の葉のざわめきを流して、お子さんとあなたの神経をやさしくほぐしましょう。', title_ko = '자연의 진정제 🍃', body_ko = '떼쓰기 많고 시끄러운 하루였나요? 백색소음의 나뭇잎 바스락 소리를 틀어 아이와 엄마의 신경을 함께 달래 주세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een dag vol driftbuien en lawaai? Zet bladergeruis uit Witte ruis aan en geef zijn zenuwstelsel en dat van jezelf een massage.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był dzień pełen kryzysów i hałasu? Włącz szelest liści z Białego szumu i ukój układ nerwowy jego i swój.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia cheio de crises e barulho? Ligue o sussurro das folhas do Ruído Branco e faça uma massagem ao sistema nervoso dele e ao seu.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit full av utbrott och buller? Sätt på lövsus från Vitt brus och ge både barnets och ditt eget nervsystem en massage.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Hôm nay quá nhiều cơn ăn vạ và ồn ào? Hãy bật tiếng lá xào xạc trong Tiếng ồn trắng để xoa dịu hệ thần kinh của cả bé lẫn mẹ.', title_zh = '天然的镇静剂 🍃', body_zh = '今天又闹又吵，崩溃不断？打开白噪音里的树叶沙沙声，给宝宝和你自己的神经系统都做个按摩。' WHERE id = 'c4d895de-4842-4a9b-ae46-1557c6e3d2cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de vestirse 👗', body_es = '¿No se acaba la tozudez del «¡No quiero esta camiseta!»? Para reducir las batallas de la mañana, convierte vestirse en un juego diciéndole que le vais a hacer fotos en la Sesión de fotos del bebé.', title_fr = 'La bataille de l''habillage 👗', body_fr = 'Le « Je ne veux pas ce t-shirt ! » ne s''arrête pas ? Pour réduire les crises du matin, transformez l''habillage en jeu en lui disant qu''il va poser pour la Séance photo bébé.', title_hi = 'कपड़े पहनने की जंग 👗', body_hi = '''यह कमीज़ नहीं चाहिए!'' वाली ज़िद खत्म नहीं होती? सुबह कपड़ों के झगड़े कम करने के लिए ''बेबी फ़ोटोशूट में तुम्हारी फ़ोटो खींचेंगे'' कहकर कपड़े पहनने को खेल बना दीजिए।', title_id = 'Perang berpakaian 👗', body_id = 'Aku tidak mau baju ini! Keras kepalanya tak kunjung reda? Untuk mengurangi drama berpakaian di pagi hari, jadikan permainan dengan bilang kita akan berfoto di Sesi Foto Bayi.', title_ja = '着替えの攻防 👗', body_ja = '「このシャツはいや！」のこだわりが終わらない？朝の着替えのかんしゃくを減らすために、「ベビーフォトセッション」で写真を撮るよと伝えて、着替えを遊びに変えましょう。', title_ko = '옷 입기 전쟁 👗', body_ko = '''이 옷 싫어!'' 고집이 끝나지 않나요? 아침 옷 입기 전쟁을 줄이려면 아기 사진 촬영으로 사진을 찍자고 말하며 옷 입기를 놀이로 바꿔 보세요.', title_nl = 'Strijd om het aankleden 👗', body_nl = 'Blijft het maar ik wil dit shirt niet!? Maak van aankleden een spelletje om de ochtendstrijd te verminderen: zeg dat jullie een foto gaan maken in Babyfotoshoot.', title_pl = 'Walka o ubieranie 👗', body_pl = 'Upór w stylu „Nie chcę tej koszulki!” nie mija? Aby ograniczyć poranne kryzysy, zamień ubieranie w zabawę: powiedz, że zrobicie zdjęcia w Sesji zdjęciowej dziecka.', title_pt = 'A batalha da roupa 👗', body_pt = 'A teimosia do "Não quero esta camisola!" não acaba? Para reduzir as crises da roupa de manhã, transforme o vestir num jogo, dizendo-lhe que vão tirar fotos na Sessão Fotográfica do Bebé.', title_sv = 'Kampen om kläderna 👗', body_sv = 'Tar envisheten ”Jag vill inte ha den här tröjan!” aldrig slut? Minska morgonens klädbråk genom att göra påklädningen till en lek: säg att ni ska ta bilder i Babyfotografering.', title_vi = 'Cuộc chiến mặc quần áo 👗', body_vi = 'Cơn bướng "Con không thích áo này!" mãi chưa dứt? Để giảm những cuộc chiến quần áo buổi sáng, hãy biến việc mặc đồ thành trò chơi bằng cách nói "Mình sẽ chụp ảnh cho con trong Chụp ảnh cho bé".', title_zh = '穿衣大战 👗', body_zh = '“我不要这件衣服！”的倔强没完没了？为了减少早上的穿衣冲突，就说“我们要去宝宝写真拍照啦”，把穿衣变成游戏。' WHERE id = 'f1307d3d-156d-45b5-82ac-2f5c2abfa1a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día 🌟', body_es = 'Cada nueva habilidad que aprende es fruto de tu esfuerzo. Abre el Diario de ánimo, escribe hasta lo más pequeño que has hecho hoy por tu peque ¡y siéntete orgullosa de ti!', title_fr = 'Le héros du jour 🌟', body_fr = 'Chaque nouvelle compétence qu''il apprend, c''est grâce à vous. Ouvrez le Journal d''humeur, notez même la plus petite attention que vous lui avez offerte aujourd''hui et soyez fière de vous !', title_hi = 'आज की हीरो 🌟', body_hi = 'हर दिन वह जो नई चीज़ सीखता है, वह आपकी मेहनत है। मूड डायरी खोलिए, आज उसके लिए की गई छोटी से छोटी अच्छाई भी लिखिए और खुद पर गर्व कीजिए!', title_id = 'Pahlawan hari ini 🌟', body_id = 'Setiap keterampilan baru yang ia pelajari adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati, tulis kebaikan sekecil apa pun yang Anda lakukan untuknya hari ini, dan banggalah pada diri sendiri!', title_ja = '今日のヒーロー 🌟', body_ja = '毎日新しくできるようになることは、あなたのがんばりのおかげです。「気分日記」を開いて、今日お子さんのためにしたどんな小さなことも書いて、自分を誇りに思いましょう！', title_ko = '오늘의 주인공 🌟', body_ko = '아이가 매일 배우는 새로운 능력은 엄마의 노력 덕분이에요. 기분 일기를 열고 오늘 아이를 위해 한 아주 작은 일이라도 적으며 스스로를 자랑스러워하세요!', title_nl = 'De held van de dag 🌟', body_nl = 'Elke nieuwe vaardigheid die hij leert, is dankzij jou. Open je Stemmingsdagboek, schrijf zelfs het kleinste liefs op dat je vandaag voor hem deed, en wees trots op jezelf!', title_pl = 'Bohaterka dnia 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, to twoja zasługa. Otwórz Dziennik nastroju, zapisz nawet najmniejszą dobrą rzecz, którą dziś dla niego zrobiłaś, i bądź z siebie dumna!', title_pt = 'A heroína do dia 🌟', body_pt = 'Cada nova competência que ele aprende é fruto do seu esforço. Abra o Diário de Humor, escreva até o gesto mais pequeno que fez hoje por ele e orgulhe-se de si!', title_sv = 'Dagens hjälte 🌟', body_sv = 'Varje ny färdighet barnet lär sig är tack vare ditt arbete. Öppna Humördagboken, skriv ner även det minsta du gjort för barnet i dag och var stolt över dig själv!', title_vi = 'Người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng, ghi lại cả việc tốt nhỏ nhất mẹ đã làm cho bé hôm nay và tự hào về bản thân nhé!', title_zh = '今天的英雄 🌟', body_zh = '宝宝每天学会的新本领都有你的功劳。打开心情日记，哪怕是今天为宝宝做的最小的一件好事也写下来，为自己骄傲吧！' WHERE id = '0daafb47-5c27-4a37-935b-b3612abf5506' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Quiere hablar, pero... 🗣️', body_es = '¿Entiende muchas más palabras de las que dice? Aunque no las pronuncie bien, lee en el Blog cómo apoyar este gran salto del lenguaje.', title_fr = 'Il veut parler, mais... 🗣️', body_fr = 'Son vocabulaire passif dépasse l''actif ? Même s''il prononce mal les mots, lisez dans la rubrique Blogs comment soutenir ce formidable bond du langage.', title_hi = 'बोलना चाहता है, पर... 🗣️', body_hi = 'समझता ज़्यादा है, बोलता कम? भले ही वह शब्द ठीक से न बोले, भाषा की इस शानदार छलांग में उसका साथ कैसे दें, यह ब्लॉग सेक्शन में पढ़िए।', title_id = 'Ingin bicara, tapi... 🗣️', body_id = 'Kosakata pasifnya lebih banyak daripada yang aktif? Meski pengucapannya belum tepat, baca di bagian Blog cara mendukung lompatan bahasa yang luar biasa ini.', title_ja = '話したいけれど… 🗣️', body_ja = 'わかる言葉が、話せる言葉よりずっと多い？うまく発音できなくても、このすばらしい言葉の飛躍をどう応援すればいいか、ブログで読んでみましょう。', title_ko = '말하고 싶은데... 🗣️', body_ko = '알아듣는 말이 하는 말보다 많나요? 발음이 정확하지 않더라도 이 멋진 언어 도약을 어떻게 도와주면 좋을지 블로그에서 읽어 보세요.', title_nl = 'Hij wil praten, maar... 🗣️', body_nl = 'Begrijpt hij meer woorden dan hij zegt? Lees in Blogs hoe je deze geweldige taalsprong steunt, ook als hij de woorden nog niet goed uitspreekt.', title_pl = 'Chce mówić, ale... 🗣️', body_pl = 'Rozumie więcej słów, niż mówi? Nawet jeśli nie wymawia ich poprawnie, przeczytaj w sekcji Blog, jak wspierać ten wspaniały skok językowy.', title_pt = 'Quer falar, mas... 🗣️', body_pt = 'O vocabulário passivo é maior do que o ativo? Mesmo que ainda não pronuncie bem as palavras, leia nos Blogues como apoiar este salto fantástico na linguagem.', title_sv = 'Vill prata, men... 🗣️', body_sv = 'Är det passiva ordförrådet större än det aktiva? Läs i Bloggar hur du stöttar detta fantastiska språksprång, även om barnet inte uttalar orden rätt.', title_vi = 'Bé muốn nói, nhưng... 🗣️', body_vi = 'Vốn từ thụ động nhiều hơn chủ động? Dù bé chưa phát âm đúng, hãy đọc trong mục Blog cách hỗ trợ bước nhảy vọt ngôn ngữ tuyệt vời này.', title_zh = '想说话，但是…… 🗣️', body_zh = '被动词汇比主动词汇多？即使发音还不准确，也去博客板块读读该怎样支持这次了不起的语言飞跃。' WHERE id = '3b1eb831-8b25-40be-89a6-b50384eeb49b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de independencia 🥣', body_es = '¿No te da la cuchara? Pon el temporizador de tomas y analiza cuánto dura esta prueba de independencia. Y a la comida derramada, solo sonríele.', title_fr = 'En quête d''autonomie 🥣', body_fr = 'Il refuse de vous laisser la cuillère ? Lancez le minuteur des repas et analysez combien de temps dure ce test d''autonomie. Quant à la nourriture renversée, souriez simplement.', title_hi = 'आज़ादी की तलाश 🥣', body_hi = 'चम्मच आपको नहीं देता? फ़ीडिंग टाइमर चालू कीजिए और देखिए कि आज़ादी की यह कोशिश कितना समय लेती है। बिखरे खाने पर बस मुस्कुरा दीजिए।', title_id = 'Mencari kemandirian 🥣', body_id = 'Tidak mau memberikan sendoknya? Nyalakan Timer Makan dan lihat berapa lama ujian kemandirian ini berlangsung. Untuk makanan yang berceceran, cukup tersenyum saja.', title_ja = '自立への挑戦 🥣', body_ja = 'スプーンを渡してくれない？食事タイマーをオンにして、この自立の挑戦にどれくらい時間がかかるか分析しましょう。こぼれた食べ物には、ただほほえんで。', title_ko = '스스로 하고 싶어요 🥣', body_ko = '숟가락을 넘겨주지 않나요? 수유 타이머를 켜고 이 자립 도전이 얼마나 걸리는지 살펴보세요. 흘린 음식에는 그냥 웃어 주세요.', title_nl = 'Op zoek naar zelfstandigheid 🥣', body_nl = 'Geeft hij de lepel niet aan je? Zet de Voedingstimer aan en kijk hoe lang deze zelfstandigheidstest duurt. Om het gemorste eten kun je gewoon glimlachen.', title_pl = 'W poszukiwaniu samodzielności 🥣', body_pl = 'Nie oddaje ci łyżki? Włącz timer karmienia i sprawdź, ile trwa ta próba samodzielności. A do rozsypanego jedzenia po prostu się uśmiechnij.', title_pt = 'Em busca de independência 🥣', body_pt = 'Não lhe dá a colher? Ligue o temporizador de alimentação e analise quanto tempo demora este teste de independência. E à comida entornada, responda só com um sorriso.', title_sv = 'Längtan efter självständighet 🥣', body_sv = 'Vill barnet inte ge dig skeden? Starta matningstimern och analysera hur lång tid självständighetsförsöket tar. Och le bara åt maten som spills.', title_vi = 'Hành trình tự lập 🥣', body_vi = 'Bé không đưa thìa cho mẹ? Hãy bật Hẹn giờ cho bú để xem thử thách tự lập này mất bao lâu. Còn thức ăn vương vãi thì cứ mỉm cười thôi.', title_zh = '追求自主 🥣', body_zh = '不肯把勺子给你？打开喂养计时器，分析这场自主挑战花了多长时间。撒了一地的饭，就笑一笑吧。' WHERE id = 'a4477b67-ebfc-489b-b2e5-165c0ebb273f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón! 📏', body_es = '¿Notas que tu peque ha pegado un estirón de repente? Introduce las nuevas cifras en el Seguimiento del desarrollo y mira con orgullo su curva de crecimiento sano.', title_fr = 'Poussée de croissance ! 📏', body_fr = 'Vous avez l''impression qu''il a grandi d''un coup ? Entrez les nouveaux chiffres dans le Suivi de croissance et regardez fièrement sa courbe de croissance saine.', title_hi = 'लंबाई में उछाल! 📏', body_hi = 'लग रहा है कि बच्चा अचानक लंबा हो गया? ग्रोथ ट्रैकर में नए आँकड़े दर्ज कीजिए और गर्व से सेहतमंद विकास का चार्ट देखिए।', title_id = 'Lonjakan tinggi badan! 📏', body_id = 'Merasa si kecil tiba-tiba bertambah tinggi? Masukkan angka terbarunya ke Pelacak Perkembangan dan lihat dengan bangga grafik pertumbuhannya yang sehat.', title_ja = '背がぐんと伸びた！📏', body_ja = 'お子さんが急に背が伸びたと感じますか？「発達トラッカー」に新しい数値を入力して、健やかな成長グラフを誇らしく眺めましょう。', title_ko = '키가 쑥! 📏', body_ko = '아이가 갑자기 훌쩍 큰 것 같나요? 성장 기록에 새 수치를 입력하고 건강한 성장 그래프를 뿌듯하게 확인하세요.', title_nl = 'Groeispurt! 📏', body_nl = 'Merk je dat je kindje ineens is gegroeid? Voer de nieuwe cijfers in de Groeitracker in en kijk trots naar zijn gezonde groeicurve.', title_pl = 'Skok wzrostowy! 📏', body_pl = 'Czujesz, że twoje dziecko nagle urosło? Wpisz nowe pomiary w Śledzeniu rozwoju i z dumą spójrz na zdrowy wykres wzrostu.', title_pt = 'Salto de crescimento! 📏', body_pt = 'Sente que o seu filho cresceu de repente? Introduza os novos valores no Registo de Desenvolvimento e veja com orgulho o gráfico de crescimento saudável.', title_sv = 'Längdspurt! 📏', body_sv = 'Känns det som att barnet plötsligt har vuxit? Ange de nya siffrorna i Utvecklingsspåraren och titta stolt på den sunda tillväxtkurvan.', title_vi = 'Bé cao vọt! 📏', body_vi = 'Mẹ thấy bé bỗng cao lên? Hãy nhập số đo mới vào Theo dõi phát triển và tự hào ngắm biểu đồ tăng trưởng khỏe mạnh.', title_zh = '长个子啦！📏', body_zh = '感觉孩子突然长高了？在发育追踪里输入新数字，骄傲地看看健康的成长曲线。' WHERE id = '4dbfd2fe-196e-4f4f-9fd6-89ab8dff4f94' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de recargar energía 🔋', body_es = '¡No te olvides de ti! Prepara en Recetas saludables un batido rico en proteínas, rápido y delicioso para el desayuno, y renuévate.', title_fr = 'L''heure de recharger les batteries 🔋', body_fr = 'Ne vous oubliez pas ! Préparez avec les Recettes saines un délicieux smoothie riche en protéines, vite fait le matin, et retrouvez de l''énergie.', title_hi = 'ऊर्जा जुटाने का समय 🔋', body_hi = 'खुद को मत भूलिए! सेहतमंद रेसिपी से सुबह के लिए झटपट बनने वाली, प्रोटीन से भरपूर स्वादिष्ट स्मूदी बनाइए और तरोताज़ा हो जाइए।', title_id = 'Waktunya mengisi energi 🔋', body_id = 'Jangan lupakan diri Anda! Buat smoothie lezat kaya protein yang cepat disiapkan untuk pagi hari dari Resep Sehat, dan segarkan diri Anda.', title_ja = 'エネルギーをためる時間 🔋', body_ja = '自分のことも忘れないで！「ヘルシーレシピ」から、朝にさっとつくれるたんぱく質たっぷりのおいしいスムージーで、リフレッシュしましょう。', title_ko = '에너지 충전 시간 🔋', body_ko = '엄마 자신을 잊지 마세요! 건강한 레시피에서 아침에 금방 만드는 단백질 가득 맛있는 스무디로 기운을 되찾으세요.', title_nl = 'Tijd om op te laden 🔋', body_nl = 'Vergeet jezelf niet! Maak uit Gezonde recepten een snelle, eiwitrijke smoothie voor het ontbijt en voel je weer fris.', title_pl = 'Czas naładować baterie 🔋', body_pl = 'Nie zapominaj o sobie! Przygotuj ze Zdrowych przepisów szybkie, pyszne smoothie bogate w białko na śniadanie i nabierz sił.', title_pt = 'Hora de recarregar energias 🔋', body_pt = 'Não se esqueça de si! Prepare com as Receitas Saudáveis um batido saboroso, rápido e rico em proteína para a manhã, e renove-se.', title_sv = 'Dags att ladda energi 🔋', body_sv = 'Glöm inte bort dig själv! Gör en god och proteinrik smoothie till frukost som går snabbt från Hälsosamma recept och känn dig piggare.', title_vi = 'Giờ nạp năng lượng 🔋', body_vi = 'Đừng quên bản thân! Hãy làm một ly sinh tố giàu đạm, ngon miệng và nhanh gọn cho buổi sáng từ Công thức lành mạnh để tràn đầy sức sống.', title_zh = '积攒能量的时间 🔋', body_zh = '别忘了你自己！从健康食谱里做一杯早上能快速完成、富含蛋白质的美味奶昔，焕然一新吧。' WHERE id = '9167bebc-9c9c-4cbb-8cf3-b64e9ea99677' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía en 5 minutos ⚡', body_es = 'Cuando tu peque duerma la siesta, no corras a las tareas de casa. Prepara en Recetas saludables un batido cargado de antioxidantes y renueva tu cuerpo.', title_fr = '5 minutes d''énergie ⚡', body_fr = 'Quand il fait la sieste l''après-midi, ne vous ruez pas sur les tâches ménagères. Préparez un smoothie plein d''antioxydants avec les Recettes saines et ressourcez votre corps.', title_hi = '5 मिनट की ऊर्जा ⚡', body_hi = 'दोपहर में बच्चा सोए तो घर के कामों की ओर मत भागिए। सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर स्मूदी बनाइए और अपने शरीर को तरोताज़ा कीजिए।', title_id = 'Energi 5 menit ⚡', body_id = 'Saat si kecil tidur siang, jangan buru-buru mengerjakan pekerjaan rumah. Buat smoothie kaya antioksidan dari Resep Sehat dan segarkan kembali tubuh Anda.', title_ja = '5分でエネルギー ⚡', body_ja = 'お昼にお子さんが寝たら、家事に走らないで。「ヘルシーレシピ」から抗酸化物質たっぷりのスムージーをつくって、体をリフレッシュさせましょう。', title_ko = '5분 에너지 ⚡', body_ko = '오후에 아이가 낮잠을 자면 집안일로 달려가지 마세요. 건강한 레시피에서 항산화 성분 가득한 스무디를 만들어 몸에 활력을 채우세요.', title_nl = 'Energie in 5 minuten ⚡', body_nl = 'Ren niet naar het huishouden als je kindje ''s middags slaapt. Maak uit Gezonde recepten een smoothie vol antioxidanten en geef je lichaam nieuwe energie.', title_pl = 'Energia w 5 minut ⚡', body_pl = 'Gdy maluch ma popołudniową drzemkę, nie rzucaj się w wir obowiązków. Przygotuj ze Zdrowych przepisów smoothie pełne antyoksydantów i zregeneruj organizm.', title_pt = 'Energia em 5 minutos ⚡', body_pt = 'Quando ele dorme a sesta, não corra para as tarefas da casa. Prepare com as Receitas Saudáveis um batido cheio de antioxidantes e renove o seu corpo.', title_sv = 'Energi på 5 minuter ⚡', body_sv = 'Rusa inte till hushållssysslorna när barnet sover middag. Gör en smoothie full av antioxidanter från Hälsosamma recept och ge kroppen ny kraft.', title_vi = 'Năng lượng trong 5 phút ⚡', body_vi = 'Buổi trưa khi bé ngủ, đừng vội lao vào việc nhà. Hãy làm một ly sinh tố giàu chất chống oxy hóa từ Công thức lành mạnh để cơ thể được tái tạo.', title_zh = '5分钟能量补给 ⚡', body_zh = '中午孩子睡着时，别急着去做家务。从健康食谱里做一杯富含抗氧化物的奶昔，让身体焕然一新。' WHERE id = 'e61cda6e-e7ca-46f3-a40c-42185a9f8216' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Leer libros juntos 📖', body_es = '¿Quiere pasar él mismo las páginas del libro? Lee en el Blog un artículo estupendo sobre cómo despertar el amor por la lectura jugando a esta edad.', title_fr = 'Lire des livres ensemble 📖', body_fr = 'Il veut tourner lui-même les pages du livre ? Lisez dans la rubrique Blogs un super article sur la façon de lui transmettre l''amour de la lecture par le jeu à cet âge.', title_hi = 'साथ मिलकर किताब पढ़ना 📖', body_hi = 'किताब के पन्ने खुद पलटना चाहता है? ब्लॉग सेक्शन में इस उम्र में खेल-खेल में पढ़ने का शौक जगाने पर शानदार लेख पढ़िए।', title_id = 'Membaca buku bersama 📖', body_id = 'Ingin membalik halaman buku sendiri? Baca artikel menarik di bagian Blog tentang cara menumbuhkan cinta membaca lewat permainan di usia ini.', title_ja = '一緒に絵本を読もう 📖', body_ja = '自分でページをめくりたがりますか？この年齢で遊びを通して本好きに育てる方法について、ブログのすてきな記事を読んでみましょう。', title_ko = '함께 책 읽기 📖', body_ko = '책장을 직접 넘기고 싶어 하나요? 이 나이에 놀이로 책 읽는 즐거움을 키워 주는 방법에 관한 멋진 글을 블로그에서 읽어 보세요.', title_nl = 'Samen boekjes lezen 📖', body_nl = 'Wil hij zelf de bladzijden omslaan? Lees in Blogs het mooie artikel over hoe je op deze leeftijd spelenderwijs liefde voor lezen meegeeft.', title_pl = 'Wspólne czytanie książek 📖', body_pl = 'Chce sam przewracać strony książki? Przeczytaj w sekcji Blog świetny artykuł o tym, jak poprzez zabawę zaszczepić w tym wieku miłość do czytania.', title_pt = 'Ler livros juntos 📖', body_pt = 'Quer virar sozinho as páginas do livro? Leia nos Blogues um artigo fantástico sobre como, a brincar, incutir o gosto pela leitura nesta idade.', title_sv = 'Läsa böcker tillsammans 📖', body_sv = 'Vill barnet vända bladen själv? Läs den fantastiska artikeln i Bloggar om hur du med lek väcker läslust i den här åldern.', title_vi = 'Cùng nhau đọc sách 📖', body_vi = 'Bé muốn tự lật trang sách? Hãy đọc bài viết tuyệt vời trong mục Blog về cách nuôi dưỡng tình yêu đọc sách qua trò chơi ở lứa tuổi này.', title_zh = '一起读书 📖', body_zh = '想自己翻书页？去博客板块读读那篇很棒的文章，看看在这个年龄如何通过游戏培养对阅读的热爱。' WHERE id = '733a062a-9528-4b89-8399-8894cdcd37ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se le queda pequeña la casa? Busca en Lugares para mamás un parque amplio y seguro y ayúdale a gastar energía en la naturaleza.', body_fr = 'Il se sent à l''étroit à la maison ? Trouvez un parc grand et sûr dans les Lieux adaptés aux mamans et aidez-le à se dépenser dans la nature.', body_hi = 'घर की दीवारें उसके लिए छोटी पड़ रही हैं? माँ के लिए अनुकूल जगहें में बड़ा और सुरक्षित पार्क ढूँढिए और उसकी ऊर्जा प्रकृति में निकालने में मदद कीजिए।', body_id = 'Rumah terasa sempit baginya? Temukan taman yang luas dan aman di Tempat Ramah Ibu dan bantu ia menyalurkan energinya di alam.', body_ja = '家の中では狭すぎる？「ママにやさしいスポット」で広くて安全な公園を見つけて、自然の中でエネルギーを発散させてあげましょう。', body_ko = '집이 답답하게 느껴지나요? 엄마 친화 장소에서 넓고 안전한 공원을 찾아 자연 속에서 에너지를 마음껏 발산하게 해 주세요.', body_nl = 'Wordt het huis te klein voor hem? Zoek in Mamavriendelijke plekken een ruim en veilig park en help hem zijn energie in de natuur kwijt te raken.', body_pl = 'W domu robi mu się za ciasno? Znajdź w Miejscach przyjaznych mamom duży i bezpieczny park i pomóż mu wyszaleć się na łonie natury.', body_pt = 'As paredes de casa ficam-lhe apertadas? Encontre nos Locais Amigos das Mães um parque amplo e seguro e ajude-o a gastar energia na natureza.', body_sv = 'Känns väggarna hemma för trånga? Hitta en stor och trygg park i Mammavänliga platser och hjälp barnet att få ut energin i naturen.', body_vi = 'Nhà trở nên chật chội với bé? Hãy tìm một công viên rộng rãi và an toàn trong Địa điểm thân thiện với mẹ để bé xả năng lượng giữa thiên nhiên.', body_zh = '家里的墙关不住宝宝了？在妈妈友好场所里找一个宽敞安全的公园，帮宝宝在大自然里释放精力。' WHERE id = '840a48c0-60b0-4169-a7a4-bfd97c049d9d' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Limpieza y análisis de la mañana 💧', body_es = '¿Has cambiado el primer pañal del día? Anota los detalles en la app y comprueba fácilmente si toma suficiente líquido y si la digestión va bien.', title_fr = 'Change du matin et analyse 💧', body_fr = 'Vous avez changé la première couche de la journée ? Notez les selles et urines dans l''appli et vérifiez facilement si ses apports en liquide et sa digestion sont suffisants.', title_hi = 'सुबह की सफ़ाई और विश्लेषण 💧', body_hi = 'दिन का पहला डायपर बदल दिया? पेशाब-पॉटी की जानकारी ऐप में दर्ज कीजिए और आसानी से देखिए कि तरल और पाचन ठीक हैं या नहीं।', title_id = 'Bersih-bersih pagi dan analisis 💧', body_id = 'Sudah mengganti popok pertama hari ini? Catat data BAK/BAB-nya di aplikasi dan pantau dengan mudah apakah asupan cairan dan pencernaannya cukup.', title_ja = '朝のおむつ替えとチェック 💧', body_ja = '今日最初のおむつを替えましたか？おしっこやうんちの記録をアプリにつけて、水分と消化が十分かどうか簡単にチェックしましょう。', title_ko = '아침 정리와 확인 💧', body_ko = '오늘의 첫 기저귀를 갈았나요? 배변 정보를 앱에 기록하고 수분 섭취와 소화가 충분한지 쉽게 확인하세요.', title_nl = 'Ochtendverschoning en analyse 💧', body_nl = 'Heb je de eerste luier van de dag verschoond? Noteer de gegevens in de app en volg makkelijk of hij genoeg drinkt en of de spijsvertering goed gaat.', title_pl = 'Poranne przewijanie i analiza 💧', body_pl = 'Zmieniłaś pierwszą pieluszkę dnia? Zapisz w aplikacji informacje o wypróżnieniu i łatwo sprawdzaj, czy ilość płynów i trawienie są w normie.', title_pt = 'Higiene da manhã e análise 💧', body_pt = 'Já mudou a primeira fralda do dia? Registe os dados na app e acompanhe facilmente se a ingestão de líquidos e a digestão estão bem.', title_sv = 'Morgonbyte och analys 💧', body_sv = 'Har du bytt dagens första blöja? Anteckna uppgifterna i appen och följ enkelt om vätskeintag och matsmältning räcker till.', title_vi = 'Vệ sinh buổi sáng và phân tích 💧', body_vi = 'Mẹ đã thay chiếc tã đầu tiên trong ngày? Hãy ghi lại thông tin bài tiết vào ứng dụng để dễ dàng theo dõi bé uống nước và tiêu hóa có đủ tốt không.', title_zh = '早晨清洁与分析 💧', body_zh = '换了今天的第一片尿布？把排泄情况记到应用里，轻松跟踪水分摄入和消化是否足够。' WHERE id = 'fc70b034-70d7-48ac-b093-b541c3d08e54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Pon el temporizador de tomas. Analiza cuánto tardan sus intentos de comer solo y revisa en la app su ración diaria de alimentos.', body_fr = 'Lancez le minuteur des repas. Analysez combien de temps durent ses essais pour manger seul et vérifiez sa ration alimentaire du jour dans l''appli.', body_hi = 'फ़ीडिंग टाइमर चालू कीजिए। खुद खाने की कोशिशें कितना समय लेती हैं, यह देखिए और ऐप में रोज़ के खाने का मानक जाँचिए।', body_id = 'Nyalakan Timer Makan. Analisis berapa lama usahanya makan sendiri, lalu cek porsi makan hariannya di aplikasi.', body_ja = '食事タイマーをオンにしましょう。自分で食べるのにどれくらいかかるか分析して、1日の食事の目安をアプリで確認しましょう。', body_ko = '수유 타이머를 켜세요. 혼자 먹는 시도가 얼마나 걸리는지 분석하고, 앱에서 하루 식사 기준량을 확인하세요.', body_nl = 'Zet de Voedingstimer aan. Analyseer hoe lang zijn pogingen om zelf te eten duren en bekijk in de app zijn dagelijkse voedingsnorm.', body_pl = 'Włącz timer karmienia. Sprawdź, ile trwają próby samodzielnego jedzenia, i zobacz w aplikacji dzienną normę karmienia.', body_pt = 'Ligue o temporizador de alimentação. Analise quanto tempo demoram as tentativas de comer sozinho e verifique na app a dose diária de alimentação.', body_sv = 'Starta matningstimern. Analysera hur lång tid försöken att äta själv tar och kontrollera den dagliga matnormen i appen.', body_vi = 'Hãy bật Hẹn giờ cho bú. Phân tích xem những lần bé tự ăn mất bao lâu và kiểm tra định mức dinh dưỡng hằng ngày trong ứng dụng.', body_zh = '打开喂养计时器。分析自主进食尝试花了多长时间，并在应用里查看每日喂养参考量。' WHERE id = '8139b24d-f8c3-4b60-b4f1-38bd25e609a6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena 🏖️', body_es = '¡No tengas miedo a que se ensucie! Descubre ahora en Productos recomendados lo mejor en arena cinética y juegos sensoriales.', title_fr = 'Thérapie par le sable 🏖️', body_fr = 'N''ayez pas peur qu''il se salisse ! Découvrez tout de suite dans les Produits recommandés le meilleur matériel pour le sable cinétique et les jeux sensoriels.', title_hi = 'रेत थेरेपी 🏖️', body_hi = 'गंदा होने से मत डरिए! काइनेटिक सैंड या सेंसरी खेलों के लिए सबसे अच्छी चीज़ें तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Terapi pasir 🏖️', body_id = 'Jangan takut kotor! Temukan perlengkapan terbaik untuk pasir kinetik dan permainan sensorik di bagian Produk Rekomendasi.', title_ja = '砂あそびセラピー 🏖️', body_ja = '汚れるのをこわがらないで！キネティックサンドや感覚遊びにぴったりのアイテムを、「おすすめ商品」ですぐに見つけましょう。', title_ko = '모래 테라피 🏖️', body_ko = '더러워지는 걸 두려워하지 마세요! 키네틱 샌드와 감각 놀이에 좋은 도구를 추천 제품 섹션에서 바로 찾아보세요.', title_nl = 'Zandtherapie 🏖️', body_nl = 'Wees niet bang voor vieze handjes! Ontdek meteen in Aanbevolen producten de beste spullen voor kinetisch zand en zintuiglijke spelletjes.', title_pl = 'Terapia piaskiem 🏖️', body_pl = 'Nie bój się brudu! Od razu odkryj w sekcji Polecane produkty najlepsze akcesoria do piasku kinetycznego i zabaw sensorycznych.', title_pt = 'Terapia com areia 🏖️', body_pt = 'Não tenha medo que se suje! Descubra já na secção Produtos Recomendados os melhores materiais de areia cinética e brincadeiras sensoriais.', title_sv = 'Sandterapi 🏖️', body_sv = 'Var inte rädd för smuts! Upptäck direkt de bästa produkterna för kinetisk sand och sinneslekar i Rekommenderade produkter.', title_vi = 'Liệu pháp cát 🏖️', body_vi = 'Đừng sợ bé bị bẩn! Hãy khám phá ngay những món đồ tốt nhất về cát động lực học hoặc trò chơi giác quan trong mục Sản phẩm gợi ý.', title_zh = '沙子疗法 🏖️', body_zh = '别怕弄脏！马上去推荐商品板块，发现最好的动力沙和感官游戏用品。' WHERE id = '9cda88a3-f6c1-4cc3-92c3-5cb54bd45a91' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No consigue dormirse después de un día lleno de descubrimientos? Elige las olas del mar en Ruido blanco y crea en la habitación una calma mágica que le prepare para dormir.', body_fr = 'Il n''arrive pas à dormir après une journée pleine de découvertes ? Choisissez les vagues de l''océan dans les Bruits blancs et créez un calme magique dans la chambre pour l''aider à s''endormir.', body_hi = 'खोजों से भरे सक्रिय दिन के बाद सो नहीं पा रहा? व्हाइट नॉइज़ में समुद्र की लहरें चुनिए और कमरे में जादुई खामोशी बनाकर उसे नींद के लिए तैयार कीजिए।', body_id = 'Sulit tidur setelah seharian penuh penjelajahan? Pilih suara ombak dari Suara Putih, ciptakan keheningan ajaib di kamar, dan antar ia ke alam mimpi.', body_ja = '発見いっぱいの一日のあとで、なかなか眠れない？「ホワイトノイズ」から波の音を選んで、部屋に魔法のような静けさをつくり、眠りへ導きましょう。', body_ko = '신나는 탐험으로 가득한 하루 뒤라 잠들지 못하나요? 백색소음에서 파도 소리를 골라 방에 마법 같은 고요함을 만들고 잠들 준비를 도와주세요.', body_nl = 'Kan hij na een dag vol ontdekkingen niet slapen? Kies oceaangolven in Witte ruis en creëer in de kamer een magische rust die hem naar de slaap brengt.', body_pl = 'Nie może zasnąć po dniu pełnym aktywnych odkryć? Wybierz fale oceanu w Białym szumie, stwórz w pokoju magiczną ciszę i nastrój go do snu.', body_pt = 'Não consegue dormir depois de um dia cheio de descobertas? Escolha as ondas do mar no Ruído Branco, crie no quarto um silêncio mágico e prepare-o para dormir.', body_sv = 'Kan barnet inte somna efter en dag full av aktiva upptäckter? Välj havsvågor i Vitt brus och skapa en magisk tystnad i rummet som stämmer för sömn.', body_vi = 'Sau một ngày đầy khám phá bé vẫn không ngủ được? Hãy chọn tiếng sóng biển trong Tiếng ồn trắng, tạo không gian yên tĩnh kỳ diệu trong phòng và đưa bé vào giấc ngủ.', body_zh = '探索了一整天还睡不着？选择白噪音里的海浪声，在房间里营造神奇的宁静，让宝宝进入睡眠状态。' WHERE id = 'f71cc78c-d1eb-4694-b94a-1843f80e2db1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pegar y empujar 🛑', body_es = '¿Levanta la mano o muerde de repente cuando se enfada? Pregunta a Anacan AI cómo afrontar con cariño esta conducta tan propia del mes 21.', title_fr = 'Taper et pousser 🛑', body_fr = 'Quand il est en colère, il lève soudain la main ou mord ? Demandez à Anacan AI comment gérer avec amour ce comportement typique du 21e mois.', title_hi = 'मारना और धक्का देना 🛑', body_hi = 'गुस्से में अचानक हाथ उठाता है या काटता है? 21वें महीने के इस खास व्यवहार को प्यार से कैसे सुलझाएँ, यह Anacan AI से पूछिए।', title_id = 'Memukul dan mendorong 🛑', body_id = 'Tiba-tiba mengangkat tangan atau menggigit saat marah? Tanyakan kepada Anacan AI cara mengatasi perilaku khas usia 21 bulan ini dengan penuh kasih.', title_ja = 'たたく、押す 🛑', body_ja = '怒ると急に手が出たり、かみついたりしますか？1歳9か月ごろに見られるこの行動に、愛情をもってどう対応すればいいか、Anacan AIに聞いてみましょう。', title_ko = '때리기와 밀기 🛑', body_ko = '화가 나면 갑자기 손을 들거나 깨무나요? 21개월 무렵의 이런 행동을 사랑으로 다루는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Slaan en duwen 🛑', body_nl = 'Haalt hij ineens uit of bijt hij als hij boos is? Vraag Anacan AI hoe je dit typische gedrag van de 21e maand liefdevol aanpakt.', title_pl = 'Bicie i popychanie 🛑', body_pl = 'Gdy się złości, nagle podnosi rękę albo gryzie? Zapytaj Anacan AI, jak z miłością poradzić sobie z tym typowym dla 21. miesiąca zachowaniem.', title_pt = 'Bater e empurrar 🛑', body_pt = 'Quando se zanga, levanta a mão de repente ou morde? Pergunte ao Anacan AI como resolver com amor este comportamento típico dos 21 meses.', title_sv = 'Slår och knuffar 🛑', body_sv = 'Lyfter barnet plötsligt handen eller biter när hen blir arg? Fråga Anacan AI hur du med kärlek kan hantera detta typiska beteende i 21:a månaden.', title_vi = 'Đánh và xô đẩy 🛑', body_vi = 'Bé bất ngờ vung tay hoặc cắn khi tức giận? Hãy hỏi Anacan AI cách xử lý hành vi đặc trưng của tháng thứ 21 này bằng tình yêu thương.', title_zh = '打人和推人 🛑', body_zh = '一生气就突然动手或咬人？问问Anacan AI，如何用爱解决第21个月的这种特有行为。' WHERE id = '3787f491-d618-4351-acd6-86ff87689c17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡A la cama! Pon el temporizador de sueño, analiza su rutina para asegurarte de que duerme lo recomendado al día y descansa.', body_fr = 'On va au lit ! Lancez le minuteur de sommeil, analysez son rythme pour vérifier qu''il dort assez chaque jour, puis reposez-vous.', body_hi = 'चलो सोने चलें! स्लीप टाइमर चालू कीजिए, रोज़ की नींद का मानक पूरा हो रहा है यह पक्का करने के लिए रूटीन का विश्लेषण कीजिए और आराम कीजिए।', body_id = 'Waktunya tidur! Nyalakan Timer Tidur, analisis rutinitasnya untuk memastikan kebutuhan tidur hariannya terpenuhi, lalu istirahatlah.', body_ja = 'ベッドに行く時間！睡眠タイマーをオンにして、1日の睡眠の目安を満たしているか生活リズムを分析し、あなたも休みましょう。', body_ko = '이제 잘 시간이에요! 수면 타이머를 켜고, 하루 수면 기준량을 지키는지 일과를 분석한 뒤 엄마도 쉬세요.', body_nl = 'Naar bed! Zet de Slaaptimer aan, analyseer zijn ritme om zeker te weten dat hij genoeg slaapt, en rust zelf ook uit.', body_pl = 'Idziemy spać! Włącz timer snu, przeanalizuj rytm dnia, by mieć pewność, że wysypia się zgodnie z normą, i odpocznij.', body_pt = 'Vamos para a cama! Ligue o temporizador de sono, analise a rotina para ter a certeza de que cumpre as horas de sono diárias e descanse.', body_sv = 'Nu går vi och lägger oss! Starta sömntimern, analysera rytmen för att se att barnet får sin dagliga sömn och vila sedan.', body_vi = 'Đi ngủ thôi! Hãy bật Bộ hẹn giờ ngủ, phân tích nếp sinh hoạt để chắc chắn bé ngủ đủ định mức hằng ngày, rồi mẹ nghỉ ngơi nhé.', body_zh = '上床睡觉啦！打开睡眠计时器，分析作息，确认宝宝达到了每日睡眠参考量，然后你也休息吧。' WHERE id = 'e90a6ec1-ff62-4f86-8635-bb93512c7c35' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando juguetes inteligentes 🧩', body_es = '¿Le encanta meter figuras por los agujeros? Descubre en Productos recomendados puzles de madera adecuados a su edad que afinarán aún más su inteligencia.', title_fr = 'À la recherche d''un jouet malin 🧩', body_fr = 'Il adore faire passer les formes dans les trous ? Découvrez dans les Produits recommandés des puzzles en bois adaptés à son âge pour affûter encore son intelligence.', title_hi = 'स्मार्ट खिलौनों की तलाश 🧩', body_hi = 'आकृतियों को छेदों में डालना पसंद है? उसकी बुद्धि को और तेज़ करने वाली, उम्र के हिसाब से लकड़ी की पहेलियाँ (पज़ल) सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Mencari mainan cerdas 🧩', body_id = 'Suka memasukkan bentuk ke lubangnya? Temukan puzzle kayu sesuai usia yang makin mengasah kecerdasannya di bagian Produk Rekomendasi.', title_ja = 'かしこいおもちゃ探し 🧩', body_ja = '形を穴に入れる遊びが好きですか？知性をさらに磨く、年齢に合った木のパズルを「おすすめ商品」で見つけましょう。', title_ko = '똑똑한 장난감 찾기 🧩', body_ko = '모양을 구멍에 끼우는 걸 좋아하나요? 두뇌를 더 키워 줄 연령별 원목 퍼즐을 추천 제품 섹션에서 찾아보세요.', title_nl = 'Op zoek naar slim speelgoed 🧩', body_nl = 'Stopt hij graag vormpjes in gaatjes? Ontdek in Aanbevolen producten houten puzzels voor zijn leeftijd die zijn verstand nog verder scherpen.', title_pl = 'Szukamy mądrej zabawki 🧩', body_pl = 'Uwielbia wkładać figury do otworów? Odkryj w sekcji Polecane produkty drewniane układanki dopasowane do wieku, które jeszcze bardziej wyostrzą jego umysł.', title_pt = 'À procura de brinquedos inteligentes 🧩', body_pt = 'Adora encaixar formas nos buracos? Descubra na secção Produtos Recomendados puzzles de madeira adequados à idade, que vão aguçar ainda mais a inteligência dele.', title_sv = 'På jakt efter smarta leksaker 🧩', body_sv = 'Älskar barnet att stoppa figurer i hål? Upptäck åldersanpassade träpussel som skärper tänkandet ännu mer i Rekommenderade produkter.', title_vi = 'Tìm đồ chơi thông minh 🧩', body_vi = 'Bé thích thả hình khối vào lỗ? Hãy khám phá các bộ ghép hình (puzzle) bằng gỗ phù hợp lứa tuổi giúp bé thêm nhanh trí trong mục Sản phẩm gợi ý.', title_zh = '寻找聪明玩具 🧩', body_zh = '喜欢把形状块塞进洞里？在推荐商品板块发现适龄的木制拼图，让宝宝的小脑瓜更灵光。' WHERE id = 'ad033330-a436-4b30-84e7-2df370198c16' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Miedo a la oscuridad? 🌌', body_es = '¿Se inquieta cuando apagas la luz de la habitación? Pon el sonido del vientre materno (latido del corazón) de Ruido blanco y dale una cálida sensación de seguridad.', title_fr = 'Peur du noir ? 🌌', body_fr = 'Il s''inquiète quand vous éteignez la lumière ? Lancez le son du ventre maternel (battements de cœur) des Bruits blancs pour lui offrir un doux sentiment de sécurité.', title_hi = 'अँधेरे से डर? 🌌', body_hi = 'कमरे की बत्ती बुझाते ही बेचैन हो जाता है? व्हाइट नॉइज़ में गर्भ की आवाज़ (दिल की धड़कन) चलाकर उसे गर्माहट और सुरक्षा का एहसास दीजिए।', title_id = 'Takut gelap? 🌌', body_id = 'Gelisah saat lampu kamar dimatikan? Putar suara rahim (detak jantung) dari Suara Putih dan beri ia rasa aman yang hangat.', title_ja = '暗いのがこわい？🌌', body_ja = '部屋の電気を消すと不安になりますか？「ホワイトノイズ」の胎内の音（心臓の音）を流して、温かい安心感を届けましょう。', title_ko = '어둠이 무서워요? 🌌', body_ko = '방의 불을 끄면 불안해하나요? 백색소음에서 엄마 배 속 소리(심장 박동)를 틀어 따뜻한 안정감을 선물하세요.', title_nl = 'Bang in het donker? 🌌', body_nl = 'Wordt hij onrustig als het licht uitgaat? Zet het baarmoedergeluid (hartslag) uit Witte ruis aan en geef hem een warm, veilig gevoel.', title_pl = 'Strach przed ciemnością? 🌌', body_pl = 'Niepokoi się, gdy gasisz światło w pokoju? Włącz w Białym szumie odgłosy z brzucha mamy (bicie serca) i daj mu ciepłe poczucie bezpieczeństwa.', title_pt = 'Medo do escuro? 🌌', body_pt = 'Fica inquieto quando apaga a luz do quarto? Ligue no Ruído Branco o som do útero materno (batimento cardíaco) e dê-lhe uma sensação quente de segurança.', title_sv = 'Mörkrädd? 🌌', body_sv = 'Blir barnet oroligt när du släcker ljuset i rummet? Sätt på ljudet från livmodern (hjärtslag) i Vitt brus och ge barnet en varm känsla av trygghet.', title_vi = 'Bé sợ bóng tối? 🌌', body_vi = 'Bé lo lắng khi tắt đèn trong phòng? Hãy bật âm thanh trong bụng mẹ (tiếng tim đập) trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn ấm áp.', title_zh = '怕黑？🌌', body_zh = '关灯时宝宝会不安？打开白噪音里的子宫声（心跳声），给宝宝温暖的安全感。' WHERE id = '0ac93f21-93e2-449d-b93b-ae00befc33f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si se ha dormido, ¡a la cocina! Descubre en Recetas saludables para mujeres una ensalada con proteínas o un agua detox que te dé fuerza al instante.', body_fr = 'Il s''est endormi ? Direction la cuisine ! Découvrez dans les Recettes saines pour femmes une salade protéinée ou une eau détox qui vous redonne de l''énergie en un instant.', body_hi = 'बच्चा सो गया तो रसोई में चलिए! महिलाओं के लिए सेहतमंद रेसिपी में तुरंत ताकत देने वाला प्रोटीन सलाद या डिटॉक्स वॉटर खोजिए।', body_id = 'Si kecil sudah tidur? Ke dapur! Temukan salad kaya protein atau infused water detoks yang langsung memberi tenaga dari Resep Sehat untuk wanita.', body_ja = 'お子さんが眠ったら、キッチンへ！「女性のためのヘルシーレシピ」から、すぐに元気が出るたんぱく質たっぷりのサラダやデトックスウォーターを見つけましょう。', body_ko = '아이가 잠들었다면 주방으로! 여성을 위한 건강한 레시피에서 바로 힘이 나는 단백질 샐러드나 디톡스 워터를 찾아보세요.', body_nl = 'Slaapt je kindje? Op naar de keuken! Ontdek in Gezonde recepten voor vrouwen een eiwitrijke salade of detoxwater dat je meteen kracht geeft.', body_pl = 'Maluch zasnął? Czas do kuchni! Odkryj w Zdrowych przepisach dla kobiet białkową sałatkę albo wodę detoks, które od razu dodadzą ci sił.', body_pt = 'Se ele adormeceu, vá para a cozinha! Descubra nas Receitas Saudáveis para Mulheres uma salada rica em proteína ou uma água detox que dão força na hora.', body_sv = 'Sover barnet? Ta dig till köket! Upptäck en proteinrik sallad eller ett detoxvatten som ger kraft direkt från Hälsosamma recept för kvinnor.', body_vi = 'Bé ngủ rồi thì mẹ vào bếp thôi! Hãy khám phá món salad giàu đạm hoặc nước detox tiếp sức tức thì trong Công thức lành mạnh cho phụ nữ.', body_zh = '孩子睡着了，就去厨房吧！在女性健康食谱里发现能马上补充能量的高蛋白沙拉或排毒水。' WHERE id = '5831d6e0-9735-485f-be90-56915bc7047f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño artista en acción 🖍️', body_es = '¿Le encanta garabatear? ¡No te enfades aunque acabe lleno de pintura! Añade ya este momento creativo al Álbum del bebé y conviértelo en un recuerdo para siempre.', title_fr = 'Petit artiste au travail 🖍️', body_fr = 'Il adore gribouiller ? Même s''il est couvert de peinture, ne vous énervez pas ! Ajoutez tout de suite ce moment créatif à l''Album de bébé pour en faire un souvenir pour la vie.', title_hi = 'नन्हा चित्रकार काम पर 🖍️', body_hi = 'आड़ी-तिरछी लकीरें खींचना पसंद है? कपड़ों पर रंग लग जाए तो भी गुस्सा मत होइए! इस रचनात्मक पल को तुरंत बेबी एल्बम में जोड़कर उम्रभर की याद बनाइए।', title_id = 'Pelukis cilik sedang beraksi 🖍️', body_id = 'Suka mencoret-coret? Jangan kesal meski bajunya penuh cat! Segera tambahkan momen kreatif ini ke Album Bayi dan jadikan kenangan seumur hidup.', title_ja = '小さな画家が作業中 🖍️', body_ja = 'お絵かきが大好き？服が絵の具だらけでも怒らないで！この創造的な瞬間をすぐに「ベビーアルバム」に追加して、一生の思い出にしましょう。', title_ko = '꼬마 화가 작업 중 🖍️', body_ko = '낙서를 좋아하나요? 온몸이 물감투성이여도 화내지 마세요! 이 창의적인 순간을 바로 아기 앨범에 올려 평생의 추억으로 만드세요.', title_nl = 'Kleine kunstenaar aan het werk 🖍️', body_nl = 'Krabbelt hij graag? Word niet boos, ook al zit hij onder de verf! Voeg dit creatieve moment meteen toe aan het Babyalbum en maak er een herinnering voor altijd van.', title_pl = 'Mały artysta przy pracy 🖍️', body_pl = 'Uwielbia bazgrać? Nie denerwuj się, nawet jeśli jest cały w farbie! Od razu dodaj tę twórczą chwilę do Albumu dziecka i zachowaj ją na zawsze.', title_pt = 'Pequeno artista em ação 🖍️', body_pt = 'Adora rabiscar? Mesmo que fique todo pintado, não se enerve! Adicione já este momento criativo ao Álbum do Bebé e transforme-o numa recordação para a vida.', title_sv = 'Den lilla konstnären i farten 🖍️', body_sv = 'Älskar barnet att klottra? Bli inte irriterad även om kläderna är fulla av färg! Lägg direkt till detta kreativa ögonblick i Babyalbumet och gör det till ett minne för livet.', title_vi = 'Họa sĩ nhí đang làm việc 🖍️', body_vi = 'Bé thích vẽ nguệch ngoạc? Dù quần áo dính đầy màu cũng đừng bực mình! Hãy thêm ngay khoảnh khắc sáng tạo này vào Album của bé để thành kỷ niệm trọn đời.', title_zh = '小画家上班啦 🖍️', body_zh = '喜欢涂涂画画？就算弄得满身颜料也别生气！马上把这个充满创意的时刻加进宝宝相册，变成一生的回忆。' WHERE id = '5c1e8139-b38e-4666-8558-f6706af826d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Comprueba con el Seguimiento de tomas si hoy ha tomado suficiente vitamina C. Para verduras de colores, consulta Recetas para bebé.', body_fr = 'Vérifiez avec le Suivi des repas s''il a eu assez de vitamine C aujourd''hui. Pour des légumes colorés, consultez les Recettes pour bébés.', body_hi = 'फ़ीडिंग ट्रैकर से जाँचिए कि आज उसे पर्याप्त विटामिन C मिला या नहीं। रंग-बिरंगी सब्ज़ियों के लिए बच्चों की रेसिपी देखिए।', body_id = 'Cek dengan alat Pemantau Nutrisi apakah hari ini ia sudah cukup mendapat vitamin C. Untuk sayuran warna-warni, lihat Resep Bayi.', body_ja = '「栄養管理ツール」で、今日ビタミンCを十分とれたか確認しましょう。カラフルな野菜料理は「離乳食を始める赤ちゃんのレシピ」をチェックして。', body_ko = '수유 기록 도구로 오늘 비타민 C를 충분히 섭취했는지 확인하세요. 알록달록한 채소 메뉴는 아기 레시피를 참고하세요.', body_nl = 'Check met de Voedingstracker of hij vandaag genoeg vitamine C heeft gehad. Kijk voor kleurrijke groenten in Babyrecepten.', body_pl = 'Sprawdź w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco witaminy C. Po kolorowe warzywa zajrzyj do Przepisów dla niemowląt.', body_pt = 'Verifique com o Registo de Alimentação se hoje recebeu vitamina C suficiente. Para legumes coloridos, recorra às Receitas para bebés.', body_sv = 'Kontrollera med Matningskoll att barnet fått tillräckligt med C-vitamin i dag. Titta i Recept för bebisar efter färgglada grönsaker.', body_vi = 'Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã nhận đủ vitamin C chưa. Tìm các món rau củ nhiều màu sắc trong Công thức cho bé nhé.', body_zh = '用喂养记录工具看看宝宝今天是否摄入了足够的维生素C。想要色彩丰富的蔬菜，就去宝宝食谱看看吧。' WHERE id = '04f3e5a5-25b9-471b-9c8e-e6c96050313b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Nos lavamos los dientes? 🪥', body_es = '¿Sale corriendo en cuanto ve el cepillo? Mira en Productos recomendados cepillos musicales o de dedo y convierte esta higiene tan importante en un juego divertido.', title_fr = 'On se brosse les dents ? 🪥', body_fr = 'Il s''enfuit dès qu''il voit la brosse ? Regardez dans les Produits recommandés les brosses musicales ou à doigt pour transformer ce geste d''hygiène essentiel en jeu amusant.', title_hi = 'दाँत ब्रश हो रहे हैं? 🪥', body_hi = 'ब्रश देखते ही भाग जाता है? सुझाए गए प्रोडक्ट में म्यूज़िकल या फ़िंगर ब्रश देखिए और सफ़ाई की इस ज़रूरी आदत को मज़ेदार खेल बना दीजिए।', title_id = 'Sudah sikat gigi? 🪥', body_id = 'Langsung kabur begitu melihat sikat gigi? Lihat sikat gigi bermusik atau sikat jari di Produk Rekomendasi dan jadikan rutinitas kebersihan penting ini permainan seru.', title_ja = '歯みがきできた？🪥', body_ja = '歯ブラシを見たとたんに逃げますか？「おすすめ商品」で音楽付きや指にはめるタイプの歯ブラシをチェックして、この大切な習慣を楽しい遊びに変えましょう。', title_ko = '양치는 했나요? 🪥', body_ko = '칫솔만 보면 도망가나요? 추천 제품에서 음악이 나오는 칫솔이나 손가락 칫솔을 살펴보고 중요한 위생 습관을 재미있는 놀이로 바꿔 보세요.', title_nl = 'Tandenpoetsen? 🪥', body_nl = 'Rent hij weg zodra hij de tandenborstel ziet? Bekijk in Aanbevolen producten muzikale of vingertandenborstels en maak van deze belangrijke verzorging een leuk spel.', title_pl = 'Ząbki umyte? 🪥', body_pl = 'Ucieka na widok szczoteczki? Zajrzyj w Polecanych produktach do grających szczoteczek lub szczoteczek na palec i zamień tę ważną higienę w zabawę.', title_pt = 'Já lavou os dentes? 🪥', body_pt = 'Foge mal vê a escova? Veja nos Produtos Recomendados escovas musicais ou de dedo e transforme esta rotina de higiene tão importante num jogo divertido.', title_sv = 'Borstar vi tänderna? 🪥', body_sv = 'Springer barnet iväg så fort tandborsten syns? Titta på tandborstar med musik eller fingertandborstar i Rekommenderade produkter och gör den viktiga hygienrutinen till en rolig lek.', title_vi = 'Đánh răng chưa nào? 🪥', body_vi = 'Vừa thấy bàn chải là bé chạy mất? Hãy xem các loại bàn chải có nhạc hoặc bàn chải xỏ ngón trong Sản phẩm gợi ý để biến việc vệ sinh quan trọng này thành trò chơi vui nhộn.', title_zh = '刷牙了吗？🪥', body_zh = '一看到牙刷就跑？去推荐商品看看音乐牙刷或指套牙刷，把这项重要的卫生习惯变成有趣的游戏。' WHERE id = '41231bd2-e2dd-4432-bc31-3952982f012e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La heroína del día eres tú! 🌟', body_es = '¡A pesar de todas las rabietas y el cansancio, lo haces genial! Abre el Diario de ánimo y escribe hoy una nota para aplaudirte de pie.', title_fr = 'L''héroïne du jour, c''est vous ! 🌟', body_fr = 'Malgré les crises et la fatigue, vous êtes formidable ! Ouvrez le Journal d''humeur et écrivez aujourd''hui une note qui mérite une ovation debout.', title_hi = 'आज की हीरो आप हैं! 🌟', body_hi = 'सारे नखरों और थकान के बावजूद आप कमाल की हैं! मूड डायरी खोलिए और आज खुद को शाबाशी देने वाली एक बात लिखिए।', title_id = 'Pahlawan hari ini adalah Anda! 🌟', body_id = 'Di tengah semua tantrum dan rasa lelah, Anda luar biasa! Buka Buku Harian Suasana Hati dan tulis catatan yang membuat Anda bertepuk tangan untuk diri sendiri hari ini.', title_ja = '今日のヒーローはあなたです！🌟', body_ja = 'かんしゃくや疲れがあっても、あなたは最高です！「気分日記」を開いて、今日の自分にスタンディングオベーションを送るメモを書きましょう。', title_ko = '오늘의 주인공은 엄마예요! 🌟', body_ko = '온갖 떼쓰기와 피로에도 엄마는 정말 대단해요! 기분 일기를 열고 오늘의 나에게 기립 박수를 보낼 기록을 남겨 보세요.', title_nl = 'Jij bent de held van vandaag! 🌟', body_nl = 'Ondanks alle buien en vermoeidheid ben je geweldig! Open je Stemmingsdagboek en schrijf een notitie waarmee je jezelf vandaag een staande ovatie geeft.', title_pl = 'Dzisiejszą bohaterką jesteś ty! 🌟', body_pl = 'Mimo wszystkich kryzysów i zmęczenia jesteś wspaniała! Otwórz Dziennik nastroju i napisz dziś notatkę, za którą nagrodzisz się owacją na stojąco.', title_pt = 'A heroína do dia é a mãe! 🌟', body_pt = 'Apesar de todas as crises e do cansaço, é fantástica! Abra o Diário de Humor e escreva hoje uma nota que a faça aplaudir-se de pé.', title_sv = 'Dagens hjälte är du! 🌟', body_sv = 'Trots alla utbrott och all trötthet är du fantastisk! Öppna Humördagboken och skriv en anteckning i dag som ger dig själv stående ovationer.', title_vi = 'Mẹ là người hùng của ngày hôm nay! 🌟', body_vi = 'Dù bao cơn ăn vạ và mệt mỏi, mẹ vẫn thật tuyệt vời! Hãy mở Nhật ký tâm trạng và viết một dòng để tự vỗ tay cho mình hôm nay.', title_zh = '今天的英雄是你！🌟', body_zh = '尽管有那么多崩溃和疲惫，你依然很棒！打开心情日记，写下一句为自己热烈鼓掌的话吧。' WHERE id = '9603c325-693c-472c-b02b-2c75bd255571' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de calmar la mente 🎶', body_es = 'Un niño sobreestimulado no consigue dormir por la noche. Oscurece la habitación, pon las olas del mar de Ruido blanco y prepárale con suavidad para un sueño profundo.', title_fr = 'L''art de ralentir le cerveau 🎶', body_fr = 'Un enfant trop stimulé n''arrive pas à dormir le soir. Faites l''obscurité dans la chambre, lancez les vagues de l''océan des Bruits blancs et préparez-le doucement à un sommeil profond.', title_hi = 'दिमाग को धीमा करने की कला 🎶', body_hi = 'बहुत ज़्यादा उत्तेजना पाने वाला बच्चा रात को सो नहीं पाता। कमरे में अँधेरा कीजिए और व्हाइट नॉइज़ में समुद्र की लहरें चलाकर उसे धीरे-धीरे गहरी नींद के लिए तैयार कीजिए।', title_id = 'Seni menenangkan otak 🎶', body_id = 'Anak yang terlalu banyak stimulasi sulit tidur malam. Gelapkan kamar, putar suara ombak dari Suara Putih, dan siapkan ia pelan-pelan untuk tidur nyenyak.', title_ja = '脳をゆっくり休ませるコツ 🎶', body_ja = '刺激を受けすぎた子は、夜なかなか眠れません。部屋を暗くして、「ホワイトノイズ」の波の音を流し、深い眠りへとゆっくり導きましょう。', title_ko = '머리를 차분하게 하는 기술 🎶', body_ko = '자극을 많이 받은 아이는 밤에 잠들기 어려워요. 방을 어둡게 하고 백색소음의 파도 소리를 틀어 깊은 잠을 천천히 준비시켜 주세요.', title_nl = 'De kunst van het hoofdje laten rusten 🎶', body_nl = 'Een overprikkeld kind kan ''s nachts niet slapen. Verduister de kamer, zet oceaangolven uit Witte ruis aan en bereid hem rustig voor op een diepe slaap.', title_pl = 'Sztuka wyciszania umysłu 🎶', body_pl = 'Przestymulowane dziecko nie może zasnąć w nocy. Zaciemnij pokój, włącz fale oceanu z Białego szumu i powoli przygotuj go do głębokiego snu.', title_pt = 'A arte de abrandar o cérebro 🎶', body_pt = 'Uma criança muito estimulada não consegue dormir à noite. Escureça o quarto, ligue as ondas do mar do Ruído Branco e prepare-o devagar para um sono profundo.', title_sv = 'Konsten att varva ner hjärnan 🎶', body_sv = 'Ett överstimulerat barn kan inte sova på natten. Mörklägg rummet, sätt på havsvågor från Vitt brus och förbered barnet varsamt för djup sömn.', title_vi = 'Nghệ thuật giúp não bộ chậm lại 🎶', body_vi = 'Bé bị kích thích quá nhiều sẽ khó ngủ vào ban đêm. Hãy làm tối phòng và bật tiếng sóng biển trong Tiếng ồn trắng để nhẹ nhàng đưa bé vào giấc ngủ sâu.', title_zh = '让大脑慢下来的艺术 🎶', body_zh = '受到过多刺激的孩子晚上会睡不着。把房间调暗，打开白噪音里的海浪声，慢慢帮宝宝准备进入深度睡眠。' WHERE id = 'd22a5573-d857-4918-90d2-9def6a084f6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Artista cubierto de pintura! 🎨', body_es = '¿Se ha pintado entero mientras garabateaba? En lugar de enfadarte, decora este momento divertido con las pegatinas alegres de la Sesión de fotos del bebé y súbelo al álbum.', title_fr = 'Un artiste couvert de peinture ! 🎨', body_fr = 'Il s''est couvert de peinture en gribouillant ? Au lieu de vous énerver, décorez ce moment drôle avec les stickers joyeux de la Séance photo bébé et ajoutez-le à l''album.', title_hi = 'रंगों में डूबा कलाकार! 🎨', body_hi = 'आड़ी-तिरछी लकीरें खींचते हुए कपड़े रंग लिए? गुस्सा होने के बजाय इस मज़ेदार पल को बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में अपलोड कीजिए।', title_id = 'Seniman berlumur cat! 🎨', body_id = 'Bajunya penuh cat saat mencoret-coret? Daripada kesal, hiasi momen lucu ini dengan stiker ceria dari Sesi Foto Bayi dan unggah ke album.', title_ja = '絵の具まみれのアーティスト！🎨', body_ja = 'お絵かき中に服まで絵の具だらけに？怒る代わりに、このおもしろい瞬間を「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムにアップしましょう。', title_ko = '물감투성이 예술가! 🎨', body_ko = '낙서하다가 온몸에 물감을 묻혔나요? 화내는 대신 이 재미있는 순간을 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 올려 보세요.', title_nl = 'Kunstenaar onder de verf! 🎨', body_nl = 'Zit hij na het krabbelen helemaal onder de verf? Word niet boos, maar versier dit grappige moment met vrolijke stickers in Babyfotoshoot en zet het in het album.', title_pl = 'Artysta cały w farbie! 🎨', body_pl = 'Bazgrząc, pomazał się farbą od stóp do głów? Zamiast się złościć, ozdób tę zabawną chwilę wesołymi naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'Artista coberto de tinta! 🎨', body_pt = 'Ficou todo pintado enquanto rabiscava? Em vez de se enervar, decore este momento engraçado com os autocolantes alegres da Sessão Fotográfica do Bebé e carregue-o no álbum.', title_sv = 'Konstnär full av färg! 🎨', body_sv = 'Har barnet målat ner sig när hen klottrade? I stället för att bli irriterad, dekorera det roliga ögonblicket med glada klistermärken i Babyfotografering och ladda upp det i albumet.', title_vi = 'Nghệ sĩ lấm lem màu vẽ! 🎨', body_vi = 'Bé vẽ nguệch ngoạc rồi dính màu khắp người? Thay vì bực mình, hãy trang trí khoảnh khắc vui nhộn này bằng sticker trong Chụp ảnh cho bé rồi tải lên album.', title_zh = '满身颜料的小艺术家！🎨', body_zh = '涂涂画画时把自己弄得满身颜料？与其生气，不如用宝宝写真里欢乐的贴纸装饰这个有趣的瞬间，上传到相册。' WHERE id = 'fb035079-cf24-4146-9049-8d721e68f53f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La ropa se le queda corta? 📏', body_es = 'Si los pantalones se le quedan cortos, ¡está dando un estirón! Introduce sus medidas actuales en el Registro de peso y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Les vêtements deviennent trop petits ? 📏', body_fr = 'Si son pantalon devient trop court, c''est un pic de croissance ! Entrez ses mesures actuelles dans le Suivi du poids et regardez fièrement sa courbe grimper.', title_hi = 'कपड़े छोटे पड़ रहे हैं? 📏', body_hi = 'पैंट छोटी हो गई है तो ग्रोथ स्पर्ट चल रहा है! वेट ट्रैकर में मौजूदा माप दर्ज कीजिए और गर्व से विकास चार्ट को ऊपर जाते देखिए।', title_id = 'Bajunya mulai kekecilan? 📏', body_id = 'Kalau celananya mulai cutbray, berarti ada lonjakan pertumbuhan! Masukkan ukuran terbarunya ke Pelacak Berat Badan dan lihat dengan bangga grafik pertumbuhannya naik.', title_ja = '服が小さくなってきた？📏', body_ja = 'ズボンの丈が短くなったら、成長期です！「体重トラッカー」に今のサイズを入力して、成長グラフが伸びていく様子を誇らしく見守りましょう。', title_ko = '옷이 작아졌나요? 📏', body_ko = '바지 길이가 짧아졌다면 성장 급등기예요! 체중 기록에 현재 수치를 입력하고 성장 그래프가 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Kleren te kort? 📏', body_nl = 'Is de broek te kort geworden? Dan is er een groeispurt! Voer de huidige maten in de Gewichtstracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Ubranka za krótkie? 📏', body_pl = 'Jeśli nogawki zrobiły się za krótkie, to skok wzrostowy! Wpisz aktualne pomiary w Liczniku wagi i z dumą patrz, jak rośnie wykres rozwoju.', title_pt = 'A roupa está a ficar curta? 📏', body_pt = 'Se as calças ficaram curtas, é um pico de crescimento! Introduza as medidas atuais no Registo de Peso e veja com orgulho o gráfico de desenvolvimento a subir.', title_sv = 'Kläderna för små? 📏', body_sv = 'Har byxbenen blivit korta är det en tillväxtspurt! Ange aktuella mått i Viktspåraren och titta stolt på hur tillväxtkurvan stiger.', title_vi = 'Quần áo bị ngắn? 📏', body_vi = 'Ống quần bị ngắn tức là bé đang tăng trưởng vọt! Hãy nhập số đo hiện tại vào Theo dõi cân nặng và tự hào ngắm biểu đồ phát triển đi lên.', title_zh = '衣服变小了？📏', body_zh = '裤腿变短了，说明正在经历生长突增！在体重记录里输入当前的尺寸，骄傲地看着成长曲线往上走。' WHERE id = '0b2c56b1-a7a8-4553-8880-13254eeb155b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se despierta gritando?', body_es = 'Sin encender la luz, pon el sonido del vientre materno de Ruido blanco para que se sienta seguro y vuelva a dormirse.', title_fr = 'Il se réveille en hurlant ?', body_fr = 'Sans allumer la lumière, lancez le son du ventre maternel des Bruits blancs pour qu''il se sente en sécurité et se rendorme.', title_hi = 'नींद से चीखकर जागता है?', body_hi = 'कमरे की बत्ती जलाए बिना व्हाइट नॉइज़ में गर्भ की आवाज़ चलाइए, उसे सुरक्षित महसूस कराइए और फिर से सुला दीजिए।', title_id = 'Terbangun sambil menjerit?', body_id = 'Tanpa menyalakan lampu kamar, putar suara rahim dari Suara Putih agar ia merasa aman dan kembali tertidur.', title_ja = '叫んで目を覚ます？', body_ja = '部屋の電気はつけずに、「ホワイトノイズ」の胎内の音を流して安心させ、もう一度眠りに戻してあげましょう。', title_ko = '비명을 지르며 깨나요?', body_ko = '방의 불은 켜지 말고 백색소음에서 엄마 배 속 소리를 틀어 안전하다고 느끼게 하고 다시 잠들도록 도와주세요.', title_nl = 'Wordt hij gillend wakker?', body_nl = 'Doe het licht niet aan, maar zet het baarmoedergeluid uit Witte ruis aan, zodat hij zich veilig voelt en weer in slaap valt.', title_pl = 'Budzi się z krzykiem?', body_pl = 'Nie zapalając światła, włącz w Białym szumie odgłosy z brzucha mamy, by poczuł się bezpiecznie i znów zasnął.', title_pt = 'Acorda aos gritos?', body_pt = 'Sem acender a luz do quarto, ligue no Ruído Branco o som do útero materno, faça-o sentir-se seguro e ajude-o a voltar a adormecer.', title_sv = 'Vaknar barnet skrikande?', body_sv = 'Tänd inte ljuset i rummet. Sätt på ljudet från livmodern i Vitt brus så att barnet känner sig tryggt och somnar om.', title_vi = 'Bé thét lên khi thức giấc?', body_vi = 'Không cần bật đèn, hãy mở âm thanh trong bụng mẹ trong Tiếng ồn trắng để bé thấy an toàn và ngủ lại.', title_zh = '尖叫着醒来？', body_zh = '不用开灯，打开白噪音里的子宫声，让宝宝感到安全，再次入睡。' WHERE id = '03d03133-0370-4630-9d2e-153f9459d86d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡«No» a todo! 🛑', body_es = '¿Se opone a todo lo que le propones? En lugar de luchar contra la tozudez, pregunta ya a Anacan AI cómo ofrecerle las opciones adecuadas.', title_fr = '« Non ! » à tout 🛑', body_fr = 'Il refuse toutes vos propositions ? Au lieu de lutter contre son obstination, demandez tout de suite à Anacan AI comment lui proposer les bons choix.', title_hi = 'हर बात पर ''नहीं!'' 🛑', body_hi = 'आपकी हर बात का विरोध करता है? ज़िद से लड़ने के बजाय तुरंत Anacan AI से पूछिए कि उसे सही विकल्प कैसे दें।', title_id = 'Tidak! untuk segalanya 🛑', body_id = 'Menolak semua tawaran Anda? Daripada melawan sikap keras kepalanya, segera tanyakan kepada Anacan AI cara memberinya pilihan dengan tepat.', title_ja = 'なんでも「いや！」🛑', body_ja = 'あなたの提案にすべて反対しますか？こだわりと戦う代わりに、上手な選択肢の出し方をすぐにAnacan AIに聞いてみましょう。', title_ko = '뭐든 ''싫어!'' 🛑', body_ko = '엄마의 모든 제안에 반대하나요? 고집과 씨름하는 대신, 올바른 선택지를 주는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Nee! tegen alles 🛑', body_nl = 'Protesteert hij tegen al je voorstellen? Ga niet de strijd aan met zijn koppigheid, maar vraag Anacan AI meteen hoe je hem de juiste keuzes voorlegt.', title_pl = '„Nie!” na wszystko 🛑', body_pl = 'Sprzeciwia się wszystkim twoim propozycjom? Zamiast walczyć z uporem, od razu zapytaj Anacan AI, jak dawać mu właściwe wybory.', title_pt = '"Não!" a tudo 🛑', body_pt = 'Contesta todas as suas propostas? Em vez de lutar contra a teimosia, pergunte já ao Anacan AI como lhe oferecer as escolhas certas.', title_sv = '”Nej!” till allt 🛑', body_sv = 'Protesterar barnet mot alla dina förslag? I stället för att kämpa mot envisheten, fråga Anacan AI direkt hur du kan erbjuda barnet rätt val.', title_vi = '"Không!" với mọi thứ 🛑', body_vi = 'Bé phản đối mọi đề nghị của mẹ? Thay vì đấu với sự bướng bỉnh, hãy hỏi ngay Anacan AI cách đưa ra cho bé những lựa chọn phù hợp.', title_zh = '什么都说“不！”🛑', body_zh = '你的每个提议都被反对？与其和倔强对抗，不如马上问问Anacan AI，怎样给宝宝提供正确的选择。' WHERE id = '8ed6f8ef-f210-4aaa-96f8-4667b80d657e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La siesta se alarga? ⏱️', body_es = '¿Se resiste a ir a la cama por la noche? Pon el temporizador de sueño y sigue el gráfico. ¿Quizá se despierta demasiado tarde de la siesta?', title_fr = 'La sieste s''allonge ? ⏱️', body_fr = 'Il résiste au coucher le soir ? Lancez le minuteur de sommeil et suivez le graphique. Il se réveille peut-être trop tard de sa sieste ?', title_hi = 'दिन की नींद लंबी हो रही है? ⏱️', body_hi = 'शाम को सोने से मना करता है? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। कहीं वह दिन की नींद से बहुत देर से तो नहीं उठता?', title_id = 'Tidur siang makin panjang? ⏱️', body_id = 'Melawan saat waktu tidur malam? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin ia bangun terlalu sore dari tidur siangnya?', title_ja = 'お昼寝が長くなってきた？⏱️', body_ja = '夜、ベッドに行くのを嫌がりますか？睡眠タイマーをオンにして、グラフをチェックしましょう。お昼寝から起きるのが遅すぎるのかもしれません。', title_ko = '낮잠이 길어지나요? ⏱️', body_ko = '저녁에 잠자리를 거부하나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠에서 너무 늦게 깨는 건 아닐까요?', title_nl = 'Wordt het middagdutje langer? ⏱️', body_nl = 'Verzet hij zich ''s avonds tegen naar bed gaan? Zet de Slaaptimer aan en volg de grafiek. Wordt hij misschien te laat wakker uit zijn middagdutje?', title_pl = 'Drzemka się wydłuża? ⏱️', body_pl = 'Wieczorem nie chce iść do łóżka? Włącz timer snu i śledź wykres. Może za późno budzi się z drzemki?', title_pt = 'A sesta está a ficar mais longa? ⏱️', body_pt = 'Resiste a ir para a cama à noite? Ligue o temporizador de sono e acompanhe o gráfico. Talvez esteja a acordar demasiado tarde da sesta?', title_sv = 'Längre dagsömn? ⏱️', body_sv = 'Gör barnet motstånd vid läggdags på kvällen? Starta sömntimern och följ grafen. Kanske vaknar barnet för sent från dagsömnen?', title_vi = 'Giấc ngủ ngày kéo dài? ⏱️', body_vi = 'Buổi tối bé không chịu lên giường? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ bé thức dậy sau giấc ngủ ngày quá muộn?', title_zh = '白天小睡变长了？⏱️', body_zh = '晚上抗拒上床？打开睡眠计时器，看看图表。也许是白天小睡醒得太晚了？' WHERE id = '0b3896bc-de1d-4dd2-b68d-bd0aa3890750' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El calcio y los huesos 🦴', body_es = 'Un desarrollo físico tan rápido necesita calcio. Calcula con el Seguimiento de tomas cuánto queso y yogur necesita y, si falta, mira Recetas para bebé.', title_fr = 'Calcium et os 🦴', body_fr = 'Une croissance physique rapide demande du calcium. Calculez ses besoins en fromage et yaourt avec le Suivi des repas et, s''il en manque, consultez les Recettes pour bébés.', title_hi = 'कैल्शियम और हड्डियाँ 🦴', body_hi = 'तेज़ शारीरिक विकास के लिए कैल्शियम चाहिए। फ़ीडिंग ट्रैकर से पनीर और दही की ज़रूरत गिनिए और कमी हो तो बच्चों की रेसिपी देखिए।', title_id = 'Kalsium dan tulang 🦴', body_id = 'Pertumbuhan fisik yang pesat butuh kalsium. Hitung kebutuhan keju dan yogurtnya dengan alat Pemantau Nutrisi, dan jika kurang, lihat Resep Bayi.', title_ja = 'カルシウムと骨 🦴', body_ja = '急速な体の成長にはカルシウムが必要です。「栄養管理ツール」でチーズやヨーグルトの必要量を計算して、足りなければ「離乳食を始める赤ちゃんのレシピ」をのぞいてみましょう。', title_ko = '칼슘과 뼈 🦴', body_ko = '빠른 신체 발달에는 칼슘이 필요해요. 수유 기록 도구로 치즈와 요거트 필요량을 계산하고, 부족하다면 아기 레시피를 살펴보세요.', title_nl = 'Calcium en botten 🦴', body_nl = 'Een snelle lichamelijke groei vraagt om calcium. Bereken met de Voedingstracker hoeveel kaas en yoghurt hij nodig heeft en kijk bij een tekort in Babyrecepten.', title_pl = 'Wapń i kości 🦴', body_pl = 'Szybki rozwój fizyczny wymaga wapnia. Oblicz w narzędziu do śledzenia karmienia zapotrzebowanie na ser i jogurt, a jeśli czegoś brakuje, zajrzyj do Przepisów dla niemowląt.', title_pt = 'Cálcio e ossos 🦴', body_pt = 'Um desenvolvimento físico rápido exige cálcio. Calcule com o Registo de Alimentação as necessidades de queijo e iogurte e, se faltar, veja as Receitas para bebés.', title_sv = 'Kalcium och skelett 🦴', body_sv = 'Snabb fysisk utveckling kräver kalcium. Räkna ut behovet av ost och yoghurt med Matningskoll och titta i Recept för bebisar om något fattas.', title_vi = 'Canxi và xương 🦴', body_vi = 'Phát triển thể chất nhanh cần nhiều canxi. Hãy tính nhu cầu phô mai, sữa chua bằng Theo dõi cữ bú và nếu thiếu thì xem Công thức cho bé.', title_zh = '钙与骨骼 🦴', body_zh = '快速的身体发育需要钙。用喂养记录工具算一算奶酪、酸奶的需求量，不够的话就看看宝宝食谱。' WHERE id = '7c7fefdb-4a4d-41d2-bca8-742c9430dc8d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sin fuerzas? 🔋', body_es = '¿Se te ha acabado la energía? No corras a por dulces. Recarga tu batería preparando bolitas energéticas sin azúcar de Recetas saludables para mujeres.', title_fr = 'Vous vous sentez à plat ? 🔋', body_fr = 'Plus d''énergie ? Ne vous jetez pas sur le sucre. Rechargez vos batteries avec des boules d''énergie sans sucre, efficaces tout de suite, des Recettes saines pour femmes.', title_hi = 'थकान महसूस हो रही है? 🔋', body_hi = 'ऊर्जा खत्म हो गई? मिठाई की ओर मत भागिए। महिलाओं के लिए सेहतमंद रेसिपी से बिना चीनी वाले, तुरंत ताकत देने वाले एनर्जी बॉल्स बनाकर अपनी बैटरी चार्ज कीजिए।', title_id = 'Merasa terkuras? 🔋', body_id = 'Energi habis? Jangan lari ke manisan. Isi ulang baterai Anda dengan membuat energy ball tanpa gula yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = 'くたくたな気分？🔋', body_ja = 'エネルギー切れですか？甘いものに頼らないで。「女性のためのヘルシーレシピ」から、砂糖不使用ですぐに元気が出るエナジーボールをつくって、自分のバッテリーを充電しましょう。', title_ko = '기운이 바닥났나요? 🔋', body_ko = '에너지가 다 떨어졌나요? 단 음식으로 달려가지 마세요. 여성을 위한 건강한 레시피에서 설탕 없이 바로 힘이 나는 에너지 볼을 만들어 배터리를 충전하세요.', title_nl = 'Opgebrand? 🔋', body_nl = 'Is je energie op? Grijp niet naar snoep. Laad je batterij op met suikervrije energieballetjes uit Gezonde recepten voor vrouwen die je meteen kracht geven.', title_pl = 'Brak sił? 🔋', body_pl = 'Skończyła ci się energia? Nie sięgaj po słodycze. Naładuj baterie kulkami mocy bez cukru ze Zdrowych przepisów dla kobiet, które od razu dodają sił.', title_pt = 'Sente-se esgotada? 🔋', body_pt = 'Ficou sem energia? Não corra para os doces. Prepare nas Receitas Saudáveis para Mulheres bolinhas energéticas sem açúcar que dão força na hora e recarregue as suas baterias.', title_sv = 'Känner du dig utmattad? 🔋', body_sv = 'Har energin tagit slut? Rusa inte efter godis. Gör sockerfria energibollar som ger kraft direkt från Hälsosamma recept för kvinnor och ladda dina egna batterier.', title_vi = 'Cảm thấy cạn kiệt? 🔋', body_vi = 'Hết năng lượng rồi? Đừng tìm đến đồ ngọt. Hãy làm những viên năng lượng không đường tiếp sức tức thì từ Công thức lành mạnh cho phụ nữ để sạc đầy pin cho mình.', title_zh = '感觉被掏空了？🔋', body_zh = '精力耗尽了？别急着吃甜食。从女性健康食谱里做些无糖、马上补充体力的能量球，给自己充充电。' WHERE id = 'c7f42861-81dc-4ed2-b93f-7c30709d92ed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te entiende, pero no habla? 🧠', body_es = 'El vocabulario pasivo se desarrolla más rápido que el activo. Lee sin falta en el Blog el artículo sobre juegos caseros que aceleran el habla a los 20 meses.', title_fr = 'Il vous comprend, mais ne parle pas ? 🧠', body_fr = 'Le vocabulaire passif se développe plus vite que l''actif. Lisez absolument l''article de la rubrique Blogs sur les jeux à la maison qui accélèrent le langage à 20 mois.', title_hi = 'आपको समझता है, पर बोलता नहीं? 🧠', body_hi = 'समझे जाने वाले शब्द बोले जाने वाले शब्दों से तेज़ी से बढ़ते हैं। ब्लॉग सेक्शन में 20 महीने के बच्चे की बोली तेज़ करने वाले घरेलू खेलों पर लेख ज़रूर पढ़िए।', title_id = 'Paham, tapi belum bicara? 🧠', body_id = 'Kosakata pasif berkembang lebih cepat daripada kosakata aktif. Baca artikel di bagian Blog tentang permainan rumahan yang mempercepat kemampuan bicara anak usia 20 bulan.', title_ja = 'わかっているのに、話さない？🧠', body_ja = '理解できる言葉（受容語彙）は、話せる言葉よりも早く増えていきます。1歳8か月の子の言葉の発達を促すおうち遊びについて、ブログの記事をぜひ読んでみましょう。', title_ko = '알아듣는데 말은 안 하나요? 🧠', body_ko = '알아듣는 어휘는 말하는 어휘보다 빨리 늘어요. 블로그에서 20개월 아이의 말문을 틔워 주는 집 놀이에 관한 글을 꼭 읽어 보세요.', title_nl = 'Begrijpt hij je, maar zegt hij niets? 🧠', body_nl = 'De passieve woordenschat groeit sneller dan de actieve. Lees zeker het artikel in Blogs over spelletjes voor thuis die de spraak van een kind van 20 maanden versnellen.', title_pl = 'Rozumie, ale nie mówi? 🧠', body_pl = 'Słownik bierny rozwija się szybciej niż czynny. Koniecznie przeczytaj w sekcji Blog artykuł o domowych zabawach, które przyspieszają rozwój mowy 20-miesięcznego dziecka.', title_pt = 'Percebe, mas não diz? 🧠', body_pt = 'O vocabulário passivo desenvolve-se mais depressa do que o ativo. Leia sem falta nos Blogues o artigo sobre jogos caseiros que aceleram a fala de uma criança de 20 meses.', title_sv = 'Förstår dig, men säger inget? 🧠', body_sv = 'Det passiva ordförrådet utvecklas snabbare än det aktiva. Läs artikeln i Bloggar om lekar hemma som snabbar på talet hos 20 månader gamla barn.', title_vi = 'Bé hiểu nhưng chưa nói? 🧠', body_vi = 'Vốn từ thụ động phát triển nhanh hơn vốn từ chủ động. Nhất định hãy đọc bài viết trong mục Blog về các trò chơi tại nhà giúp trẻ 20 tháng nói nhanh hơn.', title_zh = '听得懂，却不说？🧠', body_zh = '被动词汇比主动词汇发展得更快。一定要读读博客板块里关于促进20个月宝宝语言发展的居家游戏的文章。' WHERE id = '9f2ceaa6-0d99-46a0-884c-3460db78351b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación vitamina secreta 🥕', body_es = '¿Aparta la verdura y las hojas verdes? Aprende en Recetas para bebé a esconder con maña las espinacas y la zanahoria en unas tortitas deliciosas.', title_fr = 'Opération vitamines cachées 🥕', body_fr = 'Il repousse les herbes et les légumes ? Découvrez dans les Recettes pour bébés comment cacher habilement les épinards et les carottes dans de délicieuses crêpes.', title_hi = 'छिपे विटामिन का मिशन 🥕', body_hi = 'हरी पत्तियाँ और सब्ज़ियाँ एक तरफ़ हटा देता है? बच्चों की रेसिपी में जानिए कि पालक और गाजर को स्वादिष्ट पैनकेक में चतुराई से कैसे छिपाएँ।', title_id = 'Misi vitamin rahasia 🥕', body_id = 'Ia menyingkirkan sayuran dan daun hijau? Pelajari di Resep Bayi cara pintar menyembunyikan bayam dan wortel di dalam panekuk yang lezat.', title_ja = 'こっそりビタミン作戦 🥕', body_ja = '青菜や野菜を押しのけてしまいますか？「離乳食を始める赤ちゃんのレシピ」で、ほうれん草やにんじんをおいしいパンケーキに上手に隠す方法を覚えましょう。', title_ko = '비타민 몰래 작전 🥕', body_ko = '채소를 옆으로 밀어내나요? 아기 레시피에서 시금치와 당근을 맛있는 팬케이크 속에 감쪽같이 숨기는 법을 배워 보세요.', title_nl = 'Geheime vitamine-operatie 🥕', body_nl = 'Schuift hij groenten en kruiden opzij? Ontdek in Babyrecepten hoe je spinazie en wortel slim verstopt in lekkere pannenkoekjes.', title_pl = 'Tajna misja witaminowa 🥕', body_pl = 'Odsuwa zieleninę i warzywa? Dowiedz się w Przepisach dla niemowląt, jak zręcznie ukryć szpinak i marchewkę w pysznych placuszkach.', title_pt = 'Operação vitamina escondida 🥕', body_pt = 'Afasta as verduras e os legumes? Aprenda nas Receitas para bebés a esconder com mestria espinafres e cenoura em panquecas deliciosas.', title_sv = 'Hemlig vitaminoperation 🥕', body_sv = 'Skjuter barnet undan grönsaker och örter? Lär dig i Recept för bebisar hur du skickligt gömmer spenat och morötter i goda pannkakor.', title_vi = 'Chiến dịch giấu vitamin 🥕', body_vi = 'Bé gạt rau xanh và rau củ sang một bên? Hãy học cách khéo léo giấu rau chân vịt và cà rốt vào những chiếc bánh kếp ngon lành trong Công thức cho bé.', title_zh = '秘密维生素行动 🥕', body_zh = '把绿叶菜和蔬菜推到一边？在宝宝食谱里学学怎样把菠菜和胡萝卜巧妙地藏进美味的小煎饼里。' WHERE id = 'f641f443-9a8d-4060-a2b5-fe5d5562fa9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Olvídate de la perfección 🧘‍♀️', body_es = '¿La casa está desordenada? ¡No pasa nada! Escribe cómo te sientes en el Diario de ánimo. Recuerda que una madre feliz es más importante que una casa perfecta.', title_fr = 'Lâchez la quête de perfection 🧘‍♀️', body_fr = 'La maison est en désordre ? Ce n''est pas grave ! Écrivez vos émotions dans le Journal d''humeur. N''oubliez pas : une maman heureuse compte plus qu''une maison parfaite.', title_hi = 'परफ़ेक्ट होने की चाह छोड़िए 🧘‍♀️', body_hi = 'घर बिखरा है? कोई बात नहीं! मूड डायरी में अपनी भावनाएँ लिखिए। याद रखिए, खुश माँ परफ़ेक्ट घर से ज़्यादा ज़रूरी है।', title_id = 'Lepaskan tuntutan sempurna 🧘‍♀️', body_id = 'Rumah berantakan? Tidak apa-apa! Tulis perasaan Anda di Buku Harian Suasana Hati. Ingat, ibu yang bahagia lebih penting daripada rumah yang sempurna.', title_ja = '完璧を目指すのはやめよう 🧘‍♀️', body_ja = '家が散らかっている？大丈夫！「気分日記」に気持ちを書きましょう。完璧な家よりも、幸せなママのほうがずっと大切だということを忘れないで。', title_ko = '완벽하려는 마음을 내려놓아요 🧘‍♀️', body_ko = '집이 어질러졌나요? 괜찮아요! 기분 일기에 마음을 적어 보세요. 행복한 엄마가 완벽한 집보다 더 중요하다는 걸 잊지 마세요.', title_nl = 'Laat het streven naar perfectie los 🧘‍♀️', body_nl = 'Is het huis een rommeltje? Geeft niks! Schrijf je gevoelens op in je Stemmingsdagboek. Vergeet niet: een gelukkige moeder is belangrijker dan een perfect huis.', title_pl = 'Odpuść perfekcjonizm 🧘‍♀️', body_pl = 'W domu bałagan? Nic nie szkodzi! Zapisz swoje uczucia w Dzienniku nastroju. Pamiętaj, że szczęśliwa mama jest ważniejsza niż idealny dom.', title_pt = 'Deixe de procurar a perfeição 🧘‍♀️', body_pt = 'A casa está desarrumada? Não faz mal! Escreva o que sente no Diário de Humor. Lembre-se: uma mãe feliz é mais importante do que uma casa perfeita.', title_sv = 'Släpp jakten på perfektion 🧘‍♀️', body_sv = 'Stökigt hemma? Det gör inget! Skriv ner dina känslor i Humördagboken. Kom ihåg att en lycklig mamma är viktigare än ett perfekt hem.', title_vi = 'Buông bỏ sự hoàn hảo 🧘‍♀️', body_vi = 'Nhà cửa bừa bộn? Không sao cả! Hãy viết cảm xúc vào Nhật ký tâm trạng. Đừng quên rằng một người mẹ hạnh phúc quan trọng hơn một ngôi nhà hoàn hảo.', title_zh = '放下对完美的追求 🧘‍♀️', body_zh = '家里乱糟糟的？没关系！在心情日记里写下你的感受。记住，快乐的妈妈比完美的家更重要。' WHERE id = '2ecfbac7-2e44-4661-8705-95fe2f59e9a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas una pausa ☕', body_es = '¡Sal de casa y respira un poco! Busca en Lugares para mamás una cafetería cercana con rincón infantil y disfruta de tu café caliente.', title_fr = 'Vous aussi, vous avez besoin d''une pause ☕', body_fr = 'Sortez prendre un peu l''air ! Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants près de chez vous et savourez votre café chaud.', title_hi = 'आपको भी ब्रेक चाहिए ☕', body_hi = 'घर से निकलकर थोड़ी साँस लीजिए! माँ के लिए अनुकूल जगहें में पास का बच्चों के कोने वाला कैफ़े ढूँढिए और अपनी गर्म कॉफ़ी का मज़ा लीजिए।', title_id = 'Anda juga butuh rehat ☕', body_id = 'Keluar rumah dan hirup udara sebentar! Temukan kafe terdekat dengan sudut bermain anak di Tempat Ramah Ibu dan nikmati kopi hangat Anda.', title_ja = 'あなたにも休憩が必要です ☕', body_ja = '家を出て、ひと息つきましょう！「ママにやさしいスポット」で近くのキッズコーナーのあるカフェを見つけて、温かいコーヒーをゆっくり味わいましょう。', title_ko = '엄마에게도 휴식이 필요해요 ☕', body_ko = '집을 나서서 잠시 숨을 돌리세요! 엄마 친화 장소에서 가까운 키즈 코너 카페를 찾아 따뜻한 커피를 즐겨 보세요.', title_nl = 'Jij hebt ook een pauze nodig ☕', body_nl = 'Ga de deur uit en haal even adem! Zoek in Mamavriendelijke plekken een café met kinderhoek in de buurt en geniet van je warme koffie.', title_pl = 'Ty też potrzebujesz przerwy ☕', body_pl = 'Wyjdź z domu i odetchnij! Znajdź w Miejscach przyjaznych mamom pobliską kawiarnię z kącikiem dla dzieci i delektuj się gorącą kawą.', title_pt = 'Também precisa de uma pausa ☕', body_pt = 'Saia de casa e respire um pouco! Encontre nos Locais Amigos das Mães um café perto com cantinho para crianças e saboreie o seu café quente.', title_sv = 'Du behöver också en paus ☕', body_sv = 'Gå ut och andas lite! Hitta ett kafé med barnhörna i närheten i Mammavänliga platser och lyssna på ljudet av ditt varma kaffe.', title_vi = 'Mẹ cũng cần nghỉ ngơi ☕', body_vi = 'Hãy ra ngoài hít thở một chút! Tìm quán cà phê có góc trẻ em gần nhà trong Địa điểm thân thiện với mẹ và tận hưởng ly cà phê nóng của mình.', title_zh = '你也需要歇一歇 ☕', body_zh = '出门透透气吧！在妈妈友好场所里找一家附近带儿童角的咖啡馆，听听热咖啡的声音。' WHERE id = '31e46f9b-eb74-4b8a-8369-6c0eb709b2d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño chef de la casa 👩‍🍳', body_es = '¿Te ayuda en la cocina removiendo las cazuelas? Decora este momento tan gracioso, lleno de harina, con las pegatinas de cocinero de la Sesión de fotos del bebé.', title_fr = 'Le petit chef de la maison 👩‍🍳', body_fr = 'Il vous aide en cuisine et remue les casseroles ? Décorez ce moment rigolo, couvert de farine, avec les stickers de cuisinier de la Séance photo bébé.', title_hi = 'घर का नन्हा शेफ़ 👩‍🍳', body_hi = 'रसोई में आपकी मदद करता है, बर्तन में चम्मच चलाता है? आटे से सने इस मज़ेदार पल को बेबी फ़ोटोशूट के शेफ़ स्टिकर से सजाइए।', title_id = 'Koki cilik di rumah 👩‍🍳', body_id = 'Ia membantu Anda di dapur dan mengaduk panci? Hiasi momen lucu saat ia berlumur tepung ini dengan stiker koki dari Sesi Foto Bayi.', title_ja = 'おうちの小さなシェフ 👩‍🍳', body_ja = 'キッチンでお手伝いして、お鍋をかき混ぜていますか？粉まみれのこのおもしろい瞬間を、「ベビーフォトセッション」のシェフのステッカーで飾りましょう。', title_ko = '우리 집 꼬마 셰프 👩‍🍳', body_ko = '주방에서 엄마를 도와 냄비를 젓나요? 밀가루투성이가 된 이 재미있는 순간을 아기 사진 촬영의 요리사 스티커로 꾸며 보세요.', title_nl = 'De kleine chef van het huis 👩‍🍳', body_nl = 'Helpt hij je in de keuken en roert hij in de pannen? Versier dit grappige moment onder de bloem met koksstickers in Babyfotoshoot.', title_pl = 'Mały domowy szef kuchni 👩‍🍳', body_pl = 'Pomaga ci w kuchni i miesza w garnkach? Ozdób tę zabawną chwilę, gdy jest cały w mące, kucharskimi naklejkami z Sesji zdjęciowej dziecka.', title_pt = 'O pequeno chef da casa 👩‍🍳', body_pt = 'Ajuda-a na cozinha e mexe os tachos? Decore este momento divertido, todo coberto de farinha, com os autocolantes de cozinheiro da Sessão Fotográfica do Bebé.', title_sv = 'Husets lilla kock 👩‍🍳', body_sv = 'Hjälper barnet dig i köket och rör i kastrullerna? Dekorera det roliga ögonblicket med mjöl överallt med kockklistermärken i Babyfotografering.', title_vi = 'Đầu bếp nhí của gia đình 👩‍🍳', body_vi = 'Bé phụ mẹ trong bếp, khuấy nồi? Hãy trang trí khoảnh khắc lấm lem bột này bằng sticker đầu bếp trong Chụp ảnh cho bé.', title_zh = '家里的小厨师 👩‍🍳', body_zh = '在厨房帮你忙，搅拌锅子？用宝宝写真里的厨师贴纸，装饰这个满身面粉的有趣瞬间吧。' WHERE id = 'f9b61a4f-eba1-4cee-bf4a-958278a9300c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestro de los puzles 🧩', body_es = '¿Se le da cada vez mejor encajar figuras? Descubre en Productos recomendados rompecabezas geométricos pensados para niños de 21 meses y afina su inteligencia.', title_fr = 'Maître du puzzle 🧩', body_fr = 'Il devient expert pour assortir les formes ? Affûtez son intelligence avec les puzzles géométriques pensés pour les 21 mois, à découvrir dans les Produits recommandés.', title_hi = 'पज़ल मास्टर 🧩', body_hi = 'आकृतियाँ मिलाने में माहिर हो रहा है? उसकी बुद्धि तेज़ करने के लिए सुझाए गए प्रोडक्ट में 21 महीने के बच्चों के लिए बनी ज्यामितीय पहेलियाँ खोजिए।', title_id = 'Jago puzzle 🧩', body_id = 'Makin mahir mencocokkan bentuk? Asah kecerdasannya dengan puzzle geometri untuk anak usia 21 bulan di Produk Rekomendasi.', title_ja = 'パズル名人 🧩', body_ja = '形合わせが上手になってきましたか？知性を磨くために、「おすすめ商品」で1歳9か月向けの図形パズルを見つけましょう。', title_ko = '퍼즐 달인 🧩', body_ko = '모양 맞추기에 능숙해지고 있나요? 두뇌를 키워 줄 21개월 아이용 도형 퍼즐을 추천 제품에서 찾아보세요.', title_nl = 'Puzzelmeester 🧩', body_nl = 'Wordt hij steeds beter in vormen passen? Ontdek in Aanbevolen producten geometrische puzzels voor kinderen van 21 maanden om zijn verstand te scherpen.', title_pl = 'Mistrz układanek 🧩', body_pl = 'Coraz lepiej dopasowuje figury? Odkryj w Polecanych produktach geometryczne układanki dla 21-miesięcznych dzieci i wyostrz jego umysł.', title_pt = 'Mestre dos puzzles 🧩', body_pt = 'Está a ficar mestre a encaixar formas? Para aguçar a inteligência dele, descubra nos Produtos Recomendados puzzles geométricos pensados para crianças de 21 meses.', title_sv = 'Pusselmästare 🧩', body_sv = 'Blir barnet allt bättre på att matcha figurer? Upptäck geometriska pussel för 21 månader gamla barn i Rekommenderade produkter och skärp tänkandet.', title_vi = 'Bậc thầy ghép hình 🧩', body_vi = 'Bé đã thành thạo ghép các hình khối? Để bé thêm nhanh trí, hãy khám phá các trò ghép hình học dành cho trẻ 21 tháng trong Sản phẩm gợi ý.', title_zh = '拼图小达人 🧩', body_zh = '越来越会配对形状了？为了让宝宝更聪明，去推荐商品里发现专为21个月宝宝设计的几何拼图。' WHERE id = '2c0cd78a-df37-49ab-8eae-44063551c7d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de romper libros 📖', body_es = '¿En lugar de leer, arranca las páginas? Lee ya en el Blog cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'L''envie de déchirer les livres 📖', body_fr = 'Il déchire les pages au lieu de lire ? Lisez tout de suite dans la rubrique Blogs comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'किताब फाड़ने का शौक 📖', body_hi = 'पढ़ने के बजाय पन्ने फाड़ता है? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह तुरंत ब्लॉग सेक्शन में पढ़िए।', title_id = 'Hobi merobek buku 📖', body_id = 'Bukannya membaca, ia malah merobek halamannya? Segera baca di bagian Blog cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = '絵本を破りたい気持ち 📖', body_ja = '読む代わりにページを破ってしまいますか？読書の習慣を損なわずにこの問題に対応する方法を、すぐにブログで読んでみましょう。', title_ko = '책을 찢고 싶어요 📖', body_ko = '읽는 대신 책장을 찢나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 블로그에서 바로 읽어 보세요.', title_nl = 'Zin om boeken te scheuren 📖', body_nl = 'Scheurt hij de bladzijden in plaats van te lezen? Lees meteen in Blogs hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Ochota na darcie książek 📖', body_pl = 'Zamiast czytać, drze strony? Od razu przeczytaj w sekcji Blog, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'A mania de rasgar livros 📖', body_pt = 'Em vez de ler, rasga as páginas? Leia já nos Blogues como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Lust att riva sönder böcker 📖', body_sv = 'River barnet sönder sidorna i stället för att läsa? Läs direkt i Bloggar hur du löser problemet utan att skada läsvanan.', title_vi = 'Mê xé sách 📖', body_vi = 'Bé xé trang sách thay vì đọc? Hãy đọc ngay trong mục Blog cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '爱撕书 📖', body_zh = '不是读书，而是把书页撕碎？马上去博客板块读读，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = 'eeefba30-2a67-4d29-87df-2dbd7f03271f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa de jugar con la comida 🥣', body_es = '¿Tira la cuchara y toca la comida con las manos? Pon el temporizador de tomas, analiza la evolución de su apetito y vive este desarrollo sensorial con paciencia.', title_fr = 'L''étape où l''on joue avec la nourriture 🥣', body_fr = 'Il jette la cuillère et tripote la nourriture ? Lancez le minuteur des repas, analysez l''évolution de son appétit et accueillez avec patience ce développement sensoriel.', title_hi = 'खाने से खेलने का दौर 🥣', body_hi = 'चम्मच फेंककर खाने को हाथों से मसलता है? फ़ीडिंग टाइमर चालू कीजिए, भूख के रुझान को देखिए और इस सेंसरी विकास को धैर्य से अपनाइए।', title_id = 'Fase bermain dengan makanan 🥣', body_id = 'Ia membuang sendok dan meremas makanan dengan tangan? Nyalakan Timer Makan, analisis nafsu makannya, dan hadapi perkembangan sensorik ini dengan sabar.', title_ja = '食べ物で遊ぶ時期 🥣', body_ja = 'スプーンを投げて、手で食べ物をさわっていますか？食事タイマーをオンにして食欲の変化を分析し、この感覚の発達を気長に見守りましょう。', title_ko = '음식으로 노는 시기 🥣', body_ko = '숟가락은 던지고 손으로 음식을 만지나요? 수유 타이머를 켜서 식욕의 변화를 분석하고, 이 감각 발달을 너그럽게 지켜봐 주세요.', title_nl = 'De fase van spelen met eten 🥣', body_nl = 'Gooit hij de lepel weg en voelt hij met zijn handjes aan het eten? Zet de Voedingstimer aan, analyseer zijn eetlust en ga geduldig om met deze zintuiglijke ontwikkeling.', title_pl = 'Etap zabawy jedzeniem 🥣', body_pl = 'Odrzuca łyżkę i je rączkami? Włącz timer karmienia, przeanalizuj apetyt i podejdź z cierpliwością do tego rozwoju sensorycznego.', title_pt = 'A fase de brincar com a comida 🥣', body_pt = 'Atira a colher para o lado e mexe na comida com as mãos? Ligue o temporizador de alimentação, analise a evolução do apetite e encare com paciência este desenvolvimento sensorial.', title_sv = 'Leka med maten 🥣', body_sv = 'Kastar barnet skeden åt sidan och kladdar med maten? Starta matningstimern, analysera aptitens utveckling och möt denna sinnesutveckling med tålamod.', title_vi = 'Giai đoạn nghịch thức ăn 🥣', body_vi = 'Bé vứt thìa sang bên và bốc thức ăn bằng tay? Hãy bật Hẹn giờ cho bú, phân tích khẩu vị của bé và kiên nhẫn với quá trình phát triển giác quan này.', title_zh = '玩食物的阶段 🥣', body_zh = '把勺子扔到一边，用手抓饭？打开喂养计时器，分析食欲变化，耐心对待这种感官发展。' WHERE id = 'f7f548f7-29ae-4098-8eb1-12f16f94c4b9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Risas de la noche 📸', body_es = '¡No te pierdas esa cosa graciosa que hace antes de dormir! Grábala en vídeo, añádela al Álbum del bebé y convierte el cansancio del día en una sonrisa.', title_fr = 'Fous rires du soir 📸', body_fr = 'Ne manquez pas le geste rigolo qu''il fait avant de dormir ! Filmez-le tout de suite et ajoutez-le à l''Album de bébé pour transformer la fatigue du jour en sourire.', title_hi = 'शाम की खिलखिलाहट 📸', body_hi = 'सोने से पहले की उसकी वह मज़ेदार हरकत मत चूकिए! तुरंत वीडियो बनाकर बेबी एल्बम में जोड़िए और दिन की थकान को मुस्कान में बदल दीजिए।', title_id = 'Tawa di sore hari 📸', body_id = 'Jangan lewatkan gerakan lucunya sebelum tidur! Segera rekam videonya dan tambahkan ke Album Bayi, ubah lelah hari ini menjadi senyuman.', title_ja = '夕方の大笑い 📸', body_ja = '寝る前のおもしろいしぐさを見逃さないで！すぐに動画を撮って「ベビーアルバム」に追加し、一日の疲れを笑顔に変えましょう。', title_ko = '저녁의 깔깔 웃음 📸', body_ko = '자기 전에 하는 그 웃긴 행동을 놓치지 마세요! 바로 영상으로 찍어 아기 앨범에 올리고 하루의 피로를 미소로 바꿔 보세요.', title_nl = 'Avondgegiechel 📸', body_nl = 'Mis dat grappige ding niet dat hij doet voor het slapengaan! Film het meteen, zet het in het Babyalbum en laat de vermoeidheid van de dag omslaan in een glimlach.', title_pl = 'Wieczorne chichoty 📸', body_pl = 'Nie przegap tej zabawnej rzeczy, którą robi przed snem! Od razu nagraj film, dodaj go do Albumu dziecka i zamień zmęczenie całego dnia w uśmiech.', title_pt = 'Gargalhadas ao fim do dia 📸', body_pt = 'Não perca aquele gesto engraçado que faz antes de dormir! Filme-o já, adicione-o ao Álbum do Bebé e transforme o cansaço do dia num sorriso.', title_sv = 'Kvällsskratt 📸', body_sv = 'Missa inte det där roliga barnet gör innan läggdags! Filma direkt, lägg till i Babyalbumet och gör dagens trötthet till ett leende.', title_vi = 'Tiếng cười buổi tối 📸', body_vi = 'Đừng bỏ lỡ trò ngộ nghĩnh bé làm trước khi ngủ! Hãy quay video ngay và thêm vào Album của bé để biến mệt mỏi cả ngày thành nụ cười.', title_zh = '傍晚的欢笑 📸', body_zh = '别错过宝宝睡前那个搞笑动作！马上拍成视频加进宝宝相册，让一天的疲惫变成微笑。' WHERE id = '3512adbc-96b2-42e9-8a54-b673dc404876' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Llegan palabras nuevas! 🗣️', body_es = '¿Hace muchos sonidos pero aún no dice palabras completas? Aprende con Anacan AI los juegos caseros y ejercicios de sílabas más eficaces para activar su vocabulario pasivo.', title_fr = 'De nouveaux mots arrivent ! 🗣️', body_fr = 'Il fait plein de sons mais ne dit pas encore de vrais mots ? Découvrez avec Anacan AI les jeux à la maison et exercices de syllabes les plus efficaces pour activer son vocabulaire passif.', title_hi = 'नए शब्द आ रहे हैं! 🗣️', body_hi = 'बहुत आवाज़ें निकालता है, पर पूरा शब्द नहीं बोलता? Anacan AI से समझे हुए शब्दों को बोलने में बदलने के लिए सबसे असरदार घरेलू खेल और अक्षरों के अभ्यास जानिए।', title_id = 'Kata-kata baru segera hadir! 🗣️', body_id = 'Banyak bersuara tapi belum mengucapkan kata utuh? Pelajari permainan rumahan dan latihan suku kata paling efektif dari Anacan AI untuk mengaktifkan kosakata pasifnya.', title_ja = '新しい言葉がやってくる！🗣️', body_ja = 'たくさん声を出すけれど、まだはっきりした言葉にならない？わかる言葉を話せる言葉に変えるための、いちばん効果的なおうち遊びや音節の練習を、Anacan AIで学びましょう。', title_ko = '새로운 단어가 와요! 🗣️', body_ko = '소리는 많이 내는데 온전한 단어는 아직인가요? 알아듣는 어휘를 말로 끌어내는 가장 효과적인 집 놀이와 음절 연습을 Anacan AI에게 배워 보세요.', title_nl = 'Nieuwe woorden komen eraan! 🗣️', body_nl = 'Maakt hij veel geluidjes, maar zegt hij nog geen hele woorden? Leer bij Anacan AI de beste spelletjes en lettergreepoefeningen om zijn passieve woordenschat actief te maken.', title_pl = 'Nadchodzą nowe słowa! 🗣️', body_pl = 'Wydaje mnóstwo dźwięków, ale nie mówi jeszcze całych słów? Poznaj z Anacan AI najskuteczniejsze domowe zabawy i ćwiczenia sylab, które uaktywnią jego bierny słownik.', title_pt = 'Aí vêm palavras novas! 🗣️', body_pt = 'Faz muitos sons, mas ainda não diz palavras completas? Aprenda com o Anacan AI os jogos caseiros e os exercícios de sílabas mais eficazes para ativar o vocabulário passivo.', title_sv = 'Nya ord på väg! 🗣️', body_sv = 'Låter barnet mycket men säger inte riktiga ord? Lär dig de mest effektiva lekarna hemma och stavelseövningarna från Anacan AI för att aktivera det passiva ordförrådet.', title_vi = 'Từ mới đang đến! 🗣️', body_vi = 'Bé phát ra nhiều âm nhưng chưa nói được từ hoàn chỉnh? Hãy học từ Anacan AI những trò chơi tại nhà và bài tập âm tiết hiệu quả nhất để kích hoạt vốn từ thụ động.', title_zh = '新词要来了！🗣️', body_zh = '发出很多声音，但还说不出完整的词？向Anacan AI学习激活被动词汇最有效的居家游戏和音节练习。' WHERE id = '42cda594-bd4d-4a45-a1f6-1f894ad11fe7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le aprietan los zapatos? 👟', body_es = '¿Últimamente tropieza a menudo al correr? ¡Puede que le haya crecido el pie! Introduce sus medidas actuales en el Seguimiento del desarrollo y sigue su crecimiento.', title_fr = 'Ses chaussures deviennent trop petites ? 👟', body_fr = 'Il trébuche souvent en courant ces derniers temps ? Son pied a peut-être grandi ! Entrez ses mesures actuelles dans le Suivi de croissance et suivez son évolution.', title_hi = 'जूते तंग हो रहे हैं? 👟', body_hi = 'आजकल दौड़ते समय अक्सर लड़खड़ाता है? शायद पैर बड़े हो गए हैं! ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और विकास पर नज़र रखिए।', title_id = 'Sepatunya mulai sempit? 👟', body_id = 'Akhir-akhir ini sering tersandung saat berlari? Kakinya mungkin sudah bertambah besar! Masukkan ukuran terbarunya ke Pelacak Perkembangan dan pantau pertumbuhannya.', title_ja = '靴がきつくなってきた？👟', body_ja = '最近、走るとよくつまずきますか？足が大きくなったのかもしれません！「発達トラッカー」に今のサイズを入力して、成長を記録しましょう。', title_ko = '신발이 작아졌나요? 👟', body_ko = '요즘 뛰다가 자주 넘어지나요? 발이 자랐을 수도 있어요! 성장 기록에 현재 치수를 입력하고 성장을 지켜보세요.', title_nl = 'Worden de schoenen te klein? 👟', body_nl = 'Struikelt hij de laatste tijd vaak bij het rennen? Zijn voetjes kunnen gegroeid zijn! Voer de huidige maten in de Groeitracker in en volg zijn ontwikkeling.', title_pl = 'Buty robią się ciasne? 👟', body_pl = 'Ostatnio często potyka się podczas biegania? Może urosła mu stopa! Wpisz aktualne wymiary w Śledzeniu rozwoju i śledź jego rozwój.', title_pt = 'Os sapatos estão a ficar apertados? 👟', body_pt = 'Ultimamente tropeça muito quando corre? O pé pode ter crescido! Introduza as medidas atuais no Registo de Desenvolvimento e acompanhe o crescimento.', title_sv = 'Blir skorna trånga? 👟', body_sv = 'Snubblar barnet ofta när hen springer på sistone? Foten kan ha växt! Ange aktuella mått i Utvecklingsspåraren och följ utvecklingen.', title_vi = 'Giày bị chật? 👟', body_vi = 'Dạo này bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập số đo hiện tại vào Theo dõi phát triển để theo sát sự phát triển.', title_zh = '鞋子变紧了？👟', body_zh = '最近跑的时候经常绊倒？可能是脚长大了！在发育追踪里输入当前的尺寸，跟进成长情况。' WHERE id = 'ad6e0b2f-1d5f-4db6-82ee-93ed492c1c54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se retrasa la hora de dormir? ⏱️', body_es = '¿Pasa más tiempo despierto por la tarde? Pon el temporizador de sueño y, analizando el gráfico, vuelve a calcular sus ventanas de sueño.', title_fr = 'L''heure du coucher se décale ? ⏱️', body_fr = 'Il reste éveillé plus longtemps le soir ? Lancez le minuteur de sommeil, analysez le graphique et recalculez ses fenêtres de sommeil.', title_hi = 'सोने का समय खिसक रहा है? ⏱️', body_hi = 'शाम को जागने का समय लंबा हो गया? स्लीप टाइमर चालू कीजिए, चार्ट का विश्लेषण कीजिए और नींद की खिड़कियाँ फिर से तय कीजिए।', title_id = 'Jam tidurnya bergeser? ⏱️', body_id = 'Waktu terjaga di sore hari makin panjang? Nyalakan Timer Tidur, analisis grafiknya, dan hitung ulang jendela tidurnya.', title_ja = '寝る時間がずれてきた？⏱️', body_ja = '夕方に起きている時間が長くなりましたか？睡眠タイマーをオンにしてグラフを分析し、眠りのタイミングを計算し直しましょう。', title_ko = '잠드는 시간이 밀리나요? ⏱️', body_ko = '저녁에 깨어 있는 시간이 길어졌나요? 수면 타이머를 켜고 그래프를 분석해 수면 간격을 다시 계산해 보세요.', title_nl = 'Schuift de bedtijd op? ⏱️', body_nl = 'Is hij ''s avonds langer wakker? Zet de Slaaptimer aan, analyseer de grafiek en bereken zijn slaapvensters opnieuw.', title_pl = 'Pora snu się przesuwa? ⏱️', body_pl = 'Wieczorny czas czuwania się wydłużył? Włącz timer snu, przeanalizuj wykres i na nowo oblicz okna snu.', title_pt = 'A hora de dormir está a mudar? ⏱️', body_pt = 'O tempo acordado ao fim do dia aumentou? Ligue o temporizador de sono, analise o gráfico e volte a calcular as janelas de sono.', title_sv = 'Glider sovtiden? ⏱️', body_sv = 'Har vakentiden på kvällen blivit längre? Starta sömntimern, analysera grafen och räkna om vakenfönstren.', title_vi = 'Giờ ngủ bị lệch? ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài? Hãy bật Bộ hẹn giờ ngủ, phân tích biểu đồ và tính lại các khung giờ ngủ.', title_zh = '睡觉时间推迟了？⏱️', body_zh = '晚上清醒的时间变长了？打开睡眠计时器，分析图表，重新计算清醒时间窗口。' WHERE id = 'a3eb6f02-e9da-422e-a243-1f395cf4661e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La digestión va lenta? 🚽', body_es = 'Al cambiar el pañal de la mañana, fíjate en las cacas. Si hay estreñimiento, anótalo en la app y no olvides añadir al menú alimentos ricos en fibra (pera, avena).', title_fr = 'La digestion ralentit ? 🚽', body_fr = 'En changeant la couche du matin, observez les selles. En cas de constipation, notez-le dans l''appli et pensez à ajouter des aliments riches en fibres (poire, avoine) à son menu.', title_hi = 'पाचन धीमा हो गया? 🚽', body_hi = 'सुबह डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ हो तो ऐप में दर्ज कीजिए और मेन्यू में फ़ाइबर वाली चीज़ें (नाशपाती, ओट्स) जोड़ना मत भूलिए।', title_id = 'Pencernaannya melambat? 🚽', body_id = 'Perhatikan kotorannya saat mengganti popok pagi. Jika ia sembelit, catat di aplikasi dan jangan lupa menambahkan makanan berserat (pir, oat) ke menunya.', title_ja = '消化がゆっくりに？🚽', body_ja = '朝のおむつ替えのときに、うんちの様子をチェックしましょう。便秘ならアプリに記録して、食物繊維の多い食べ物（洋なし、オートミール）をメニューに加えるのを忘れずに。', title_ko = '소화가 느려졌나요? 🚽', body_ko = '아침에 기저귀를 갈 때 배변을 살펴보세요. 변비가 있다면 앱에 기록하고 식단에 섬유질 음식(배, 귀리)을 추가하는 걸 잊지 마세요.', title_nl = 'Gaat de spijsvertering trager? 🚽', body_nl = 'Let bij het verschonen van de ochtendluier op de ontlasting. Bij verstopping: noteer het in de app en vergeet niet vezelrijk eten (peer, havermout) aan het menu toe te voegen.', title_pl = 'Trawienie zwolniło? 🚽', body_pl = 'Przy porannej zmianie pieluszki obserwuj kupkę. Jeśli są zaparcia, zapisz to w aplikacji i nie zapomnij dodać do menu produktów bogatych w błonnik (gruszka, płatki owsiane).', title_pt = 'A digestão abrandou? 🚽', body_pt = 'Ao mudar a fralda da manhã, observe as fezes. Se houver prisão de ventre, registe-o na app e não se esqueça de acrescentar à ementa alimentos ricos em fibra (pera, aveia).', title_sv = 'Går matsmältningen trögt? 🚽', body_sv = 'Håll koll på avföringen när du byter morgonblöjan. Vid förstoppning, anteckna det i appen och glöm inte att lägga till fiberrik mat (päron, havre) i menyn.', title_vi = 'Tiêu hóa chậm lại? 🚽', body_vi = 'Hãy để ý phân khi thay tã buổi sáng. Nếu bé bị táo bón, hãy ghi vào ứng dụng và đừng quên thêm thực phẩm giàu chất xơ (lê, yến mạch) vào thực đơn.', title_zh = '消化变慢了？🚽', body_zh = '早上换尿布时留意一下排便。如果便秘，记到应用里，别忘了在菜单里加入富含纤维的食物（梨、燕麦）。' WHERE id = 'aac102d8-edd5-4708-bab2-8cf3fcc9802c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si empieza a tirar o escupir la comida, te está diciendo que ya está lleno. Para el temporizador de tomas, anota que ha completado su ración y analiza su apetito.', body_fr = 'S''il commence à jeter ou à recracher la nourriture, il vous dit qu''il n''a plus faim. Arrêtez le minuteur des repas, notez que sa ration est atteinte et analysez son appétit.', body_hi = 'अगर खाना फेंकने या थूकने लगा है, तो वह कह रहा है ''मेरा पेट भर गया''। फ़ीडिंग टाइमर रोकिए, मात्रा पूरी होने को दर्ज कीजिए और भूख का विश्लेषण कीजिए।', body_id = 'Jika ia mulai melempar atau meludahkan makanan, artinya ia bilang sudah kenyang. Hentikan Timer Makan, catat bahwa porsinya terpenuhi, dan analisis nafsu makannya.', body_ja = '食べ物を投げたり吐き出したりし始めたら、「おなかいっぱい」のサインです。食事タイマーを止めて、目安量をとれたことを記録し、食欲を分析しましょう。', body_ko = '음식을 던지거나 뱉기 시작했다면 ''배불러요''라는 뜻이에요. 수유 타이머를 멈추고 충분히 먹었다고 기록한 뒤 식욕을 분석해 보세요.', body_nl = 'Begint hij eten te gooien of uit te spugen? Dan zegt hij: ik zit vol. Stop de Voedingstimer, noteer dat hij genoeg heeft gehad en analyseer zijn eetlust.', body_pl = 'Jeśli zaczyna rzucać jedzeniem albo je wypluwać, mówi „jestem syty”. Zatrzymaj timer karmienia, zanotuj, że norma została osiągnięta, i przeanalizuj apetyt.', body_pt = 'Se começou a atirar ou a cuspir a comida, está a dizer que está satisfeito. Pare o temporizador de alimentação, registe que a dose foi cumprida e analise o apetite.', body_sv = 'Har barnet börjat kasta eller spotta ut maten betyder det ”jag är mätt”. Stoppa matningstimern, anteckna att normen är nådd och analysera aptiten.', body_vi = 'Nếu bé bắt đầu ném hoặc nhổ thức ăn, tức là bé đang nói "Con no rồi". Hãy dừng Hẹn giờ cho bú, ghi nhận đã đủ định mức và phân tích khẩu vị của bé.', body_zh = '如果开始扔食物或吐出来，那就是在说“我吃饱了”。停下喂养计时器，记下已达到参考量，分析一下食欲。' WHERE id = '4bdcd931-fb36-41ca-9759-7a92226d97f9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de lavarse los dientes 🪥', body_es = '¿Sale corriendo en cuanto ve el cepillo? Mira en Productos recomendados cepillos musicales o de dedo y convierte esta higiene tan importante en un juego divertido.', title_fr = 'La bataille du brossage de dents 🪥', body_fr = 'Il s''enfuit dès qu''il voit la brosse ? Regardez dans les Produits recommandés les brosses musicales ou à doigt pour transformer ce geste d''hygiène essentiel en jeu amusant.', title_hi = 'दाँत ब्रश करने की लड़ाई 🪥', body_hi = 'ब्रश देखते ही भाग जाता है? सुझाए गए प्रोडक्ट में म्यूज़िकल या फ़िंगर ब्रश देखिए और सफ़ाई की इस ज़रूरी आदत को मज़ेदार खेल बना दीजिए।', title_id = 'Drama sikat gigi 🪥', body_id = 'Langsung kabur begitu melihat sikat gigi? Lihat sikat gigi bermusik atau sikat jari di Produk Rekomendasi dan jadikan rutinitas kebersihan penting ini permainan seru.', title_ja = '歯みがきバトル 🪥', body_ja = '歯ブラシを見たとたんに逃げますか？「おすすめ商品」で音楽付きや指にはめるタイプの歯ブラシをチェックして、この大切な習慣を楽しい遊びに変えましょう。', title_ko = '양치 전쟁 🪥', body_ko = '칫솔만 보면 도망가나요? 추천 제품에서 음악이 나오는 칫솔이나 손가락 칫솔을 살펴보고 중요한 위생 습관을 재미있는 놀이로 바꿔 보세요.', title_nl = 'Gedoe met tandenpoetsen 🪥', body_nl = 'Rent hij weg zodra hij de tandenborstel ziet? Bekijk in Aanbevolen producten muzikale of vingertandenborstels en maak van deze belangrijke verzorging een leuk spel.', title_pl = 'Bitwa o mycie ząbków 🪥', body_pl = 'Ucieka na widok szczoteczki? Zajrzyj w Polecanych produktach do grających szczoteczek lub szczoteczek na palec i zamień tę ważną higienę w zabawę.', title_pt = 'A luta da escova de dentes 🪥', body_pt = 'Foge mal vê a escova? Veja nos Produtos Recomendados escovas musicais ou de dedo e transforme esta rotina de higiene tão importante num jogo divertido.', title_sv = 'Kampen om tandborstningen 🪥', body_sv = 'Springer barnet iväg så fort tandborsten syns? Titta på tandborstar med musik eller fingertandborstar i Rekommenderade produkter och gör den viktiga hygienrutinen till en rolig lek.', title_vi = 'Cuộc chiến đánh răng 🪥', body_vi = 'Vừa thấy bàn chải là bé chạy mất? Hãy xem các loại bàn chải có nhạc hoặc bàn chải xỏ ngón trong Sản phẩm gợi ý để biến việc vệ sinh quan trọng này thành trò chơi vui nhộn.', title_zh = '刷牙大作战 🪥', body_zh = '一看到牙刷就跑？去推荐商品看看音乐牙刷或指套牙刷，把这项重要的卫生习惯变成有趣的游戏。' WHERE id = 'be36c558-6f81-4ee5-9a59-f79497bbff2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te duele la cabeza? Corriendo detrás de tu peque te has quedado sin beber. Prepara aguas detox de Recetas saludables para mujeres y revitaliza tu cuerpo.', body_fr = 'Vous avez mal à la tête ? À force de lui courir après, vous avez oublié de boire. Revitalisez votre corps avec les eaux détox des Recettes saines pour femmes.', body_hi = 'सिर दर्द है? बच्चे के पीछे भागते हुए आपके शरीर में पानी की कमी हो गई है। महिलाओं के लिए सेहतमंद रेसिपी से डिटॉक्स वॉटर बनाइए और शरीर में ताज़गी लाइए।', body_id = 'Sakit kepala? Anda mungkin kurang minum karena terus mengejar si kecil. Segarkan tubuh Anda dengan infused water detoks dari Resep Sehat untuk wanita.', body_ja = '頭が痛いですか？お子さんを追いかけて、水分が足りていないのかもしれません。「女性のためのヘルシーレシピ」からデトックスウォーターをつくって、体をリフレッシュさせましょう。', body_ko = '머리가 아프나요? 아이를 쫓아다니느라 수분이 부족해졌을 수 있어요. 여성을 위한 건강한 레시피에서 디톡스 워터를 만들어 몸에 활력을 되찾으세요.', body_nl = 'Hoofdpijn? Je bent uitgedroogd geraakt van het achter hem aan rennen. Maak detoxwater uit Gezonde recepten voor vrouwen en geef je lichaam een opkikker.', body_pl = 'Boli cię głowa? Biegając za maluchem, zapomniałaś pić. Przygotuj wodę detoks ze Zdrowych przepisów dla kobiet i ożyw swój organizm.', body_pt = 'Tem dores de cabeça? Ficou desidratada a correr atrás dele. Prepare águas detox das Receitas Saudáveis para Mulheres e revitalize o seu corpo.', body_sv = 'Har du huvudvärk? Du har nog glömt att dricka medan du sprungit efter barnet. Gör detoxvatten från Hälsosamma recept för kvinnor och pigga upp kroppen.', body_vi = 'Mẹ bị đau đầu? Có thể mẹ đã bị thiếu nước khi chạy theo bé. Hãy làm nước detox từ Công thức lành mạnh cho phụ nữ để cơ thể tươi tỉnh lại.', body_zh = '头疼吗？追着孩子跑，你可能缺水了。从女性健康食谱里做些排毒水，让身体重新充满活力。' WHERE id = 'cd9296b3-74e7-4229-8871-9f5ee4fe977a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas vida social 👯‍♀️', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás centros con grupos de juego y conoce a otras madres.', title_fr = 'Vous aussi, vous avez besoin de voir du monde 👯‍♀️', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez des centres avec groupes de jeu dans les Lieux adaptés aux mamans et rencontrez d''autres mamans.', title_hi = 'आपको भी मेल-जोल चाहिए 👯‍♀️', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में प्ले ग्रुप वाले सेंटर ढूँढिए और दूसरी माँओं से मिलिए।', title_id = 'Anda juga butuh bersosialisasi 👯‍♀️', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan tempat dengan kelompok bermain di Tempat Ramah Ibu dan berkenalan dengan ibu-ibu lain.', title_ja = 'あなたにも人との交流が必要です 👯‍♀️', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」で遊びのグループがある施設を見つけて、ほかのママと知り合いましょう。', title_ko = '엄마에게도 어울림이 필요해요 👯‍♀️', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 놀이 모임이 있는 센터를 찾아 다른 엄마들과 만나 보세요.', title_nl = 'Jij hebt ook sociaal contact nodig 👯‍♀️', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken centra met speelgroepjes en leer andere moeders kennen.', title_pl = 'Ty też potrzebujesz towarzystwa 👯‍♀️', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom centra z grupami zabaw i poznaj inne mamy.', title_pt = 'Também precisa de convívio 👯‍♀️', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães centros com grupos de brincadeira e conheça outras mães.', title_sv = 'Du behöver också umgås 👯‍♀️', body_sv = 'Trött på att bara prata med barnet? Hitta center med lekgrupper i Mammavänliga platser och lär känna andra mammor.', title_vi = 'Mẹ cũng cần giao lưu 👯‍♀️', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm các trung tâm có nhóm chơi trong Địa điểm thân thiện với mẹ và làm quen với các mẹ khác.', title_zh = '你也需要社交 👯‍♀️', body_zh = '只和孩子说话说累了？在妈妈友好场所里找到有游戏小组的中心，认识其他妈妈吧。' WHERE id = '2fbfd933-5095-452a-808e-4209aab75b80' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El pequeño imitador 📱', body_es = '¿Habla por teléfono como tú e imita tus gestos? ¡Los niños son el mayor espejo!', title_fr = 'Petit imitateur 📱', body_fr = 'Il parle au téléphone comme vous et imite vos gestes ? Les enfants sont notre plus grand miroir !', title_hi = 'नन्हा नकलची 📱', body_hi = 'आपकी तरह फ़ोन पर बात करता है, आपके हाव-भाव की नकल करता है? बच्चे सबसे बड़ा आईना होते हैं!', title_id = 'Peniru cilik 📱', body_id = 'Ia bicara di telepon seperti Anda dan meniru gerak-gerik Anda? Anak adalah cermin terbesar kita!', title_ja = '小さなものまね名人 📱', body_ja = 'あなたのように電話で話したり、身ぶり手ぶりをまねしたりしていますか？子どもはいちばんの鏡です！', title_ko = '꼬마 따라쟁이 📱', body_ko = '엄마처럼 전화 통화를 하고 몸짓을 흉내 내나요? 아이는 가장 큰 거울이에요!', title_nl = 'Kleine na-aper 📱', body_nl = 'Praat hij net als jij aan de telefoon en doet hij je gebaren na? Kinderen zijn onze grootste spiegel!', title_pl = 'Mały naśladowca 📱', body_pl = 'Rozmawia przez telefon jak ty i naśladuje twoje gesty? Dzieci to najwierniejsze lustro!', title_pt = 'O pequeno imitador 📱', body_pt = 'Fala ao telefone como a mãe e imita os seus gestos? As crianças são o maior dos espelhos!', title_sv = 'Liten härmapa 📱', body_sv = 'Pratar barnet i telefon som du och härmar dina gester? Barn är den största spegeln!', title_vi = 'Bé bắt chước tài tình 📱', body_vi = 'Bé nói chuyện điện thoại giống mẹ, bắt chước cả cử chỉ tay chân của mẹ? Trẻ con là tấm gương lớn nhất!', title_zh = '小小模仿家 📱', body_zh = '像你一样打电话，模仿你的手势动作？孩子就是最大的镜子！' WHERE id = 'a7d068ee-6f98-437e-b7f3-f2284f8fbdbc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juntos, pero por separado 👶', body_es = '¿En el parque no juega con otros niños, solo los observa? ¡Es el juego paralelo! Descubre en el Blog datos curiosos sobre esta etapa de socialización.', title_fr = 'Ensemble, mais chacun de son côté 👶', body_fr = 'Au parc, il ne joue pas avec les autres enfants, il les observe ? C''est le jeu parallèle ! Découvrez dans la rubrique Blogs des faits intéressants sur cette étape de socialisation.', title_hi = 'साथ-साथ, पर अलग-अलग 👶', body_hi = 'पार्क में दूसरे बच्चों के साथ खेलता नहीं, बस देखता है? यह पैरेलल प्ले है! ब्लॉग सेक्शन में मेल-जोल के इस दौर के बारे में दिलचस्प बातें जानिए।', title_id = 'Bersama, tapi terpisah 👶', body_id = 'Di taman ia tidak bermain dengan anak lain, hanya mengamati? Ini bermain paralel! Temukan fakta menarik tentang tahap sosialisasi ini di bagian Blog.', title_ja = '一緒に、でも別々に 👶', body_ja = '公園でほかの子と遊ばず、見ているだけ？これは「平行遊び」です！この社会性の段階についてのおもしろい豆知識を、ブログで見つけましょう。', title_ko = '함께, 하지만 따로 👶', body_ko = '공원에서 다른 아이들과 놀지 않고 지켜만 보나요? 이건 평행 놀이예요! 이 사회성 발달 단계에 관한 흥미로운 사실을 블로그에서 찾아보세요.', title_nl = 'Samen, maar apart 👶', body_nl = 'Speelt hij in het park niet met andere kinderen, maar kijkt hij alleen toe? Dat is parallel spel! Ontdek in Blogs leuke feitjes over deze fase van socialisatie.', title_pl = 'Razem, ale osobno 👶', body_pl = 'W parku nie bawi się z innymi dziećmi, tylko patrzy? To zabawa równoległa! Odkryj w sekcji Blog ciekawostki o tym etapie uspołecznienia.', title_pt = 'Juntos, mas separados 👶', body_pt = 'No parque não brinca com as outras crianças, só observa? É a brincadeira paralela! Descubra nos Blogues factos curiosos sobre esta fase da socialização.', title_sv = 'Tillsammans, men var för sig 👶', body_sv = 'Leker barnet inte med de andra barnen i parken utan tittar bara på? Det är parallellek! Upptäck intressanta fakta om det här sociala stadiet i Bloggar.', title_vi = 'Cùng nhau nhưng riêng lẻ 👶', body_vi = 'Ở công viên bé không chơi cùng các bạn mà chỉ đứng nhìn? Đó là chơi song song! Hãy khám phá những điều thú vị về giai đoạn hòa nhập xã hội này trong mục Blog.', title_zh = '在一起，又各玩各的 👶', body_zh = '在公园不和其他小朋友玩，只在旁边看？这是平行游戏！去博客板块发现关于这个社交阶段的有趣知识。' WHERE id = 'bf157f3f-185f-45b5-aae0-091b2cf00653' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de dulces sanos 🍪', body_es = '¿Necesitas un tentempié sin azúcar pero delicioso? Descubre en Recetas para bebé galletas de plátano y dátiles que se preparan en 10 minutos.', title_fr = 'À la recherche d''une douceur saine 🍪', body_fr = 'Besoin d''un en-cas savoureux mais sans sucre ? Découvrez dans les Recettes pour bébés des biscuits à la banane et aux dattes, prêts en 10 minutes.', title_hi = 'सेहतमंद मिठाई की तलाश 🍪', body_hi = 'चीनी से दूर, पर स्वादिष्ट स्नैक चाहिए? बच्चों की रेसिपी में 10 मिनट में बनने वाली केले और खजूर की कुकीज़ खोजिए।', title_id = 'Mencari camilan manis sehat 🍪', body_id = 'Butuh camilan lezat tanpa gula? Temukan kue kering pisang dan kurma yang siap dalam 10 menit di Resep Bayi.', title_ja = 'ヘルシーなおやつ探し 🍪', body_ja = '砂糖なしでもおいしいおやつが必要ですか？「離乳食を始める赤ちゃんのレシピ」で、10分でつくれるバナナとデーツのクッキーを見つけましょう。', title_ko = '건강한 간식 찾기 🍪', body_ko = '설탕은 없지만 맛있는 간식이 필요한가요? 아기 레시피에서 10분이면 만드는 바나나 대추야자 쿠키를 찾아보세요.', title_nl = 'Op zoek naar gezond lekkers 🍪', body_nl = 'Zin in iets lekkers zonder suiker? Ontdek in Babyrecepten koekjes met banaan en dadels, klaar in 10 minuten.', title_pl = 'W poszukiwaniu zdrowych słodkości 🍪', body_pl = 'Potrzebujesz pysznej przekąski bez cukru? Odkryj w Przepisach dla niemowląt ciasteczka z bananem i daktylami gotowe w 10 minut.', title_pt = 'À procura de doces saudáveis 🍪', body_pt = 'Precisa de um lanche saboroso e longe do açúcar? Descubra nas Receitas para bebés bolachas de banana e tâmaras, prontas em 10 minutos.', title_sv = 'På jakt efter nyttigt godis 🍪', body_sv = 'Behöver ni ett gott mellanmål utan socker? Upptäck kakor med banan och dadlar som är klara på 10 minuter i Recept för bebisar.', title_vi = 'Tìm món ngọt lành mạnh 🍪', body_vi = 'Cần món ăn vặt ngon mà không đường? Hãy khám phá những chiếc bánh quy chuối và chà là làm trong 10 phút trong Công thức cho bé.', title_zh = '寻找健康甜点 🍪', body_zh = '想要不含糖但又好吃的小零食？在宝宝食谱里发现10分钟就能做好的香蕉椰枣饼干。' WHERE id = '205f33e0-59b6-4cce-bdf2-72feb1805167' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El «no» tozudo! 🛑', body_es = '¿Lo protesta todo y grita? Consulta a nuestro asistente Anacan AI sobre la tozudez del mes 21 y aprende a gestionar las crisis emocionales.', title_fr = 'Le « Non ! » obstiné 🛑', body_fr = 'Il s''oppose à tout et crie ? Parlez de l''obstination du 21e mois avec notre assistant Anacan AI et apprenez à gérer les crises émotionnelles.', title_hi = 'ज़िद्दी ''नहीं!'' 🛑', body_hi = 'हर बात का विरोध करता है और चिल्लाता है? 21वें महीने की ज़िद के बारे में हमारे Anacan AI असिस्टेंट से सलाह लीजिए और भावनाओं के तूफ़ान को संभालना सीखिए।', title_id = 'Tidak! yang keras kepala 🛑', body_id = 'Menolak segalanya dan berteriak? Konsultasikan sikap keras kepala usia 21 bulan ini dengan asisten Anacan AI dan pelajari cara menghadapi ledakan emosinya.', title_ja = 'がんこな「いや！」🛑', body_ja = 'なんにでも反対して叫びますか？1歳9か月のこだわりについてAnacan AIアシスタントに相談して、気持ちの爆発への対応を学びましょう。', title_ko = '고집스러운 ''싫어!'' 🛑', body_ko = '모든 것에 반대하며 소리 지르나요? 21개월의 고집에 대해 Anacan AI 도우미와 상담하고 감정 폭발을 다루는 법을 배워 보세요.', title_nl = 'Het koppige Nee! 🛑', body_nl = 'Protesteert en schreeuwt hij tegen alles? Overleg met onze Anacan AI-assistent over de koppigheid van de 21e maand en leer emotionele buien aanpakken.', title_pl = 'Uparte „Nie!” 🛑', body_pl = 'Sprzeciwia się wszystkiemu i krzyczy? Porozmawiaj z naszym asystentem Anacan AI o uporze 21. miesiąca i naucz się radzić sobie z kryzysami emocjonalnymi.', title_pt = 'O "Não!" teimoso 🛑', body_pt = 'Protesta contra tudo e grita? Fale com o nosso assistente Anacan AI sobre a teimosia dos 21 meses e aprenda a gerir as crises emocionais.', title_sv = 'Envist ”Nej!” 🛑', body_sv = 'Protesterar och skriker barnet mot allt? Rådgör med vår assistent Anacan AI om envisheten i 21:a månaden och lär dig hantera känslomässiga utbrott.', title_vi = 'Chữ "Không!" bướng bỉnh 🛑', body_vi = 'Bé phản đối mọi thứ và la hét? Hãy trò chuyện với trợ lý Anacan AI về sự bướng bỉnh của tháng thứ 21 và học cách xử lý các cơn bùng nổ cảm xúc.', title_zh = '倔强的“不！”🛑', body_zh = '什么都反对，还大喊大叫？和我们的Anacan AI助手聊聊第21个月的倔强，学习如何应对情绪崩溃。' WHERE id = 'db60a4c8-3ab7-4727-9545-2ff3fea13946' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se despierta a menudo por la noche? Analiza el gráfico del temporizador de sueño. Quizá haya que acortar un poco la siesta para que llegue más cansado a la noche.', body_fr = 'Il se réveille souvent la nuit ? Analysez le graphique du minuteur de sommeil. Il faudrait peut-être raccourcir un peu la sieste pour qu''il arrive plus fatigué le soir.', body_hi = 'रात में बार-बार जागता है? स्लीप टाइमर के चार्ट का विश्लेषण कीजिए। शायद दिन की नींद थोड़ी कम करनी होगी ताकि वह शाम तक ज़्यादा थक जाए।', body_id = 'Sering terbangun di malam hari? Analisis grafik Timer Tidur. Mungkin tidur siangnya perlu sedikit dipersingkat agar ia lebih lelah di malam hari.', body_ja = '夜中によく起きますか？睡眠タイマーのグラフを分析しましょう。お昼寝を少し短くして、夕方にほどよく疲れているようにする必要があるかもしれません。', body_ko = '밤에 자주 깨나요? 수면 타이머 그래프를 분석해 보세요. 낮잠을 조금 줄여 저녁에 더 피곤하게 만들어야 할지도 몰라요.', body_nl = 'Wordt hij ''s nachts vaak wakker? Analyseer de grafiek van de Slaaptimer. Misschien moet het middagdutje iets korter, zodat hij ''s avonds vermoeider is.', body_pl = 'Często budzi się w nocy? Przeanalizuj wykres timera snu. Może trzeba trochę skrócić drzemkę, żeby wieczorem był bardziej zmęczony.', body_pt = 'Acorda muitas vezes de noite? Analise o gráfico do temporizador de sono. Talvez seja preciso encurtar um pouco a sesta para que chegue à noite mais cansado.', body_sv = 'Vaknar barnet ofta på natten? Analysera grafen i sömntimern. Kanske behöver dagsömnen kortas lite så att barnet är tröttare på kvällen.', body_vi = 'Bé hay thức giấc ban đêm? Hãy phân tích biểu đồ của Bộ hẹn giờ ngủ. Có lẽ nên rút ngắn giấc ngủ ngày một chút để buổi tối bé mệt hơn.', body_zh = '夜里经常醒？分析一下睡眠计时器的图表。也许需要把白天小睡稍微缩短，让宝宝晚上更累一些。' WHERE id = 'ec464aff-d0a0-4b3d-ac5c-7d32cf5dcf36' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de vitaminas 🥗', body_es = 'Calcula con el Seguimiento de tomas las vitaminas que necesita hoy y planifica el menú. Revisa sin falta el equilibrio de omega-3 y vitamina D.', title_fr = 'Plein de vitamines 🥗', body_fr = 'Calculez avec le Suivi des repas ses besoins en vitamines du jour et planifiez son menu. Vérifiez absolument l''équilibre en oméga-3 et vitamine D.', title_hi = 'विटामिन का भंडार 🥗', body_hi = 'फ़ीडिंग ट्रैकर से आज की विटामिन की ज़रूरत गिनिए और मेन्यू प्लान कीजिए। ओमेगा-3 और विटामिन D का संतुलन ज़रूर जाँचिए।', title_id = 'Gudang vitamin 🥗', body_id = 'Hitung kebutuhan vitamin hari ini dengan alat Pemantau Nutrisi dan rencanakan menunya. Jangan lupa cek keseimbangan omega-3 dan vitamin D.', title_ja = 'ビタミンの宝庫 🥗', body_ja = '「栄養管理ツール」で今日必要なビタミンを計算して、メニューを計画しましょう。オメガ3とビタミンDのバランスも必ずチェックして。', title_ko = '비타민 창고 🥗', body_ko = '수유 기록 도구로 오늘 필요한 비타민을 계산하고 식단을 계획하세요. 오메가3와 비타민 D 균형도 꼭 확인하세요.', title_nl = 'Vitaminevoorraad 🥗', body_nl = 'Bereken met de Voedingstracker de vitamines die hij vandaag nodig heeft en plan het menu. Controleer zeker de balans van omega-3 en vitamine D.', title_pl = 'Skarbnica witamin 🥗', body_pl = 'Oblicz w narzędziu do śledzenia karmienia dzisiejsze zapotrzebowanie na witaminy i zaplanuj menu. Koniecznie sprawdź bilans omega-3 i witaminy D.', title_pt = 'Reserva de vitaminas 🥗', body_pt = 'Calcule com o Registo de Alimentação as necessidades de vitaminas de hoje e planeie a ementa. Verifique sem falta o equilíbrio de ómega-3 e vitamina D.', title_sv = 'Vitaminförråd 🥗', body_sv = 'Räkna ut dagens vitaminbehov med Matningskoll och planera menyn. Glöm inte att kontrollera balansen av omega-3 och D-vitamin.', title_vi = 'Kho vitamin 🥗', body_vi = 'Hãy tính nhu cầu vitamin hôm nay bằng Theo dõi cữ bú và lên kế hoạch thực đơn. Nhất định kiểm tra cân bằng omega-3 và vitamin D nhé.', title_zh = '维生素储备 🥗', body_zh = '用喂养记录工具算出今天的维生素需求，规划好菜单。一定要检查欧米伽-3和维生素D的平衡。' WHERE id = '87662f03-ab51-47a9-bb0d-dc1172cdf859' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Esta edad es ideal para los juegos de lógica. Descubre en Productos recomendados puzles y juguetes para clasificar formas adecuados a su edad y afina su inteligencia.', body_fr = 'Cet âge est idéal pour les jeux de logique. Découvrez dans les Produits recommandés des puzzles et des jouets à trier les formes adaptés à son âge pour affûter son intelligence.', body_hi = 'यह उम्र लॉजिक वाले खेलों के लिए सबसे सही समय है। सुझाए गए प्रोडक्ट में उम्र के हिसाब से पज़ल और आकार छाँटने वाले खिलौने खोजिए और उसकी बुद्धि तेज़ कीजिए।', body_id = 'Usia ini waktu ideal untuk permainan logika. Temukan puzzle dan mainan pemilah bentuk sesuai usia di Produk Rekomendasi dan asah kecerdasannya.', body_ja = 'この年齢は論理遊びにぴったりの時期です。「おすすめ商品」で年齢に合ったパズルや形の分類おもちゃを見つけて、知性を磨きましょう。', body_ko = '이 시기는 논리 놀이에 딱 좋아요. 추천 제품에서 연령별 퍼즐과 모양 맞추기 장난감을 찾아 두뇌를 키워 주세요.', body_nl = 'Deze leeftijd is ideaal voor logische spelletjes. Ontdek in Aanbevolen producten puzzels en vormsorteerders voor zijn leeftijd en scherp zijn verstand.', body_pl = 'To idealny wiek na zabawy logiczne. Odkryj w Polecanych produktach układanki i sortery kształtów dopasowane do wieku i wyostrz jego umysł.', body_pt = 'Esta idade é ideal para jogos de lógica. Descubra nos Produtos Recomendados puzzles adequados à idade e brinquedos de separar formas, e estimule a inteligência dele.', body_sv = 'Den här åldern är perfekt för logiklekar. Upptäck åldersanpassade pussel och sorteringsleksaker med former i Rekommenderade produkter och skärp tänkandet.', body_vi = 'Lứa tuổi này là thời điểm lý tưởng cho các trò chơi tư duy. Hãy khám phá các bộ ghép hình và đồ chơi phân loại hình khối phù hợp lứa tuổi trong Sản phẩm gợi ý để bé thêm nhanh trí.', body_zh = '这个年龄是玩逻辑游戏的理想时期。在推荐商品里发现适龄的拼图和形状分类玩具，让宝宝更聪明。' WHERE id = 'a1ffdcb1-2aeb-4842-a0b3-6bc2096bceb7' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'No todos los días son perfectos, y es normal. Escribe tus agobios de hoy en el Diario de ánimo, suelta el estrés y descansa tranquila.', body_fr = 'Toutes les journées ne sont pas parfaites, et c''est normal. Écrivez vos tensions du jour dans le Journal d''humeur, libérez-vous du stress et reposez-vous au calme.', body_hi = 'हर दिन परफ़ेक्ट नहीं होता, और यह सामान्य है। मूड डायरी में आज की मन की घुटन लिखिए, तनाव से मुक्त होकर आराम कीजिए।', body_id = 'Tidak setiap hari sempurna, dan itu wajar. Tulis beban hati Anda hari ini di Buku Harian Suasana Hati, lepaskan stres, dan beristirahatlah dengan tenang.', body_ja = '毎日が完璧なわけではなく、それでいいんです。「気分日記」に今日の心のもやもやを書いて、ストレスから解放され、ゆっくり休みましょう。', body_ko = '매일이 완벽할 수는 없고, 그래도 괜찮아요. 기분 일기에 오늘의 속상한 마음을 적고 스트레스를 털어 낸 뒤 편히 쉬세요.', body_nl = 'Niet elke dag is perfect, en dat is normaal. Schrijf je zorgen van vandaag op in je Stemmingsdagboek, laat de stress los en rust lekker uit.', body_pl = 'Nie każdy dzień jest idealny i to normalne. Zapisz w Dzienniku nastroju swoje dzisiejsze troski, uwolnij się od stresu i spokojnie odpocznij.', body_pt = 'Nem todos os dias são perfeitos, e isso é normal. Escreva no Diário de Humor as angústias de hoje, liberte-se do stress e descanse com calma.', body_sv = 'Alla dagar blir inte perfekta, och det är helt normalt. Skriv ner det som tynger dig i dag i Humördagboken, släpp stressen och vila i lugn och ro.', body_vi = 'Không phải ngày nào cũng hoàn hảo và điều đó là bình thường. Hãy viết những nỗi niềm hôm nay vào Nhật ký tâm trạng, giải tỏa căng thẳng và nghỉ ngơi thật yên bình.', body_zh = '不是每一天都完美，这很正常。把今天心里的烦闷写进心情日记，放下压力，静静地休息。' WHERE id = 'b4b68202-2497-420c-9cf0-d0f43130a249' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿La memoria te ha vuelto a fallar? No guardes en la cabeza cada cosita que se acaba en casa: añádela al momento a la Lista de la compra y que tu pareja se encargue.', body_fr = 'Votre mémoire vous a encore joué un tour ? Ne gardez pas en tête chaque petite chose qui manque à la maison : ajoutez-la tout de suite à la Liste de courses et laissez votre conjoint s''en charger.', body_hi = 'याददाश्त ने फिर धोखा दिया? घर में खत्म होने वाली हर छोटी चीज़ दिमाग में मत रखिए, तुरंत शॉपिंग लिस्ट में डालिए, आपके जीवनसाथी संभाल लेंगे।', body_id = 'Lupa lagi? Tak perlu mengingat setiap barang kecil yang habis di rumah, langsung masukkan ke Daftar Belanja dan biarkan pasangan Anda yang mengurusnya.', body_ja = 'またもの忘れ？家で切れた細かいものを頭で覚えておかないで、すぐに「買い物リスト」に入れて、パートナーに任せましょう。', body_ko = '또 깜빡하셨나요? 집에 떨어진 자잘한 물건까지 머릿속에 담아 두지 말고 바로 쇼핑 목록에 넣어 배우자에게 맡기세요.', body_nl = 'Laat je geheugen je weer in de steek? Onthoud niet elk klein ding dat thuis op is, maar zet het meteen op het Boodschappenlijstje en laat je partner het regelen.', body_pl = 'Pamięć znów cię zawiodła? Nie trzymaj w głowie każdej drobnostki, która skończyła się w domu. Od razu dodaj ją do Listy zakupów, a partner się tym zajmie.', body_pt = 'A memória voltou a pregar-lhe uma partida? Não guarde na cabeça cada coisinha que acaba em casa: ponha-a logo na Lista de Compras e o seu companheiro trata disso.', body_sv = 'Svek minnet dig igen? Håll inte varje liten sak som tagit slut hemma i huvudet, lägg den direkt i Inköpslistan och låt din partner ta hand om det.', body_vi = 'Trí nhớ lại đánh lừa mẹ? Đừng cố nhớ từng món lặt vặt sắp hết trong nhà, hãy thêm ngay vào Danh sách mua sắm để bố lo.', body_zh = '记性又跟你开玩笑了？家里用完的小东西别都记在脑子里，马上丢进购物清单，让另一半去搞定。' WHERE id = '6b045729-7aac-44f1-99aa-a2dbeb7985f2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Patada al balón! ⚽', body_es = '¿Intenta dar patadas al balón que está en el suelo? Su equilibrio y la coordinación de los pies están mejorando. Jugad un ratito a pasaros la pelota.', title_fr = 'Tir au ballon ⚽', body_fr = 'Il essaie de taper dans le ballon avec le pied ? Son équilibre et sa coordination s''améliorent. Faites quelques petites passes avec lui.', title_hi = 'गेंद पर किक ⚽', body_hi = 'ज़मीन पर पड़ी गेंद को पैर से मारने की कोशिश करता है? संतुलन और पैरों का तालमेल बेहतर हो रहा है। उसके साथ गेंद आगे-पीछे करने का छोटा खेल खेलिए।', title_id = 'Tendang bolanya ⚽', body_id = 'Mencoba menendang bola di lantai? Keseimbangan dan koordinasi kakinya makin sempurna. Ajak ia bermain oper-operan kecil.', title_ja = 'ボールをキック ⚽', body_ja = '床のボールを足でけろうとしていますか？バランスと足の協調がどんどん上達しています。一緒に小さなパス遊びをしましょう。', title_ko = '공을 뻥! ⚽', body_ko = '바닥에 있는 공을 발로 차려고 하나요? 균형 감각과 발의 협응력이 좋아지고 있어요. 아이와 작은 공 주고받기 놀이를 해 보세요.', title_nl = 'Tegen de bal schoppen ⚽', body_nl = 'Probeert hij met zijn voet tegen een bal op de grond te schoppen? Zijn evenwicht en coördinatie worden steeds beter. Speel samen een klein overspelletje.', title_pl = 'Strzał do piłki ⚽', body_pl = 'Próbuje kopnąć piłkę leżącą na ziemi? Równowaga i koordynacja nóg coraz lepsze. Zagrajcie razem w małą grę w podania.', title_pt = 'Pontapé na bola ⚽', body_pt = 'Tenta dar pontapés na bola que está no chão? O equilíbrio e a coordenação das pernas estão a aperfeiçoar-se. Façam juntos um pequeno jogo de passes.', title_sv = 'Sparka på bollen ⚽', body_sv = 'Försöker barnet sparka på bollen som ligger på marken? Balansen och fotkoordinationen blir allt bättre. Spela en liten passningslek tillsammans.', title_vi = 'Sút bóng ⚽', body_vi = 'Bé cố dùng chân đá quả bóng dưới đất? Thăng bằng và phối hợp chân đang hoàn thiện. Hãy cùng bé chơi một trò chuyền bóng nho nhỏ.', title_zh = '踢球 ⚽', body_zh = '想用脚去踢地上的球？平衡和腿部协调越来越好了。和宝宝玩一个小小的传球游戏吧。' WHERE id = '7abb85ab-0b3c-4464-a5f4-15bfe391f1ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Le cuesta dormirse? Crea un cuento original en Cuentos inteligentes y léeselo.', body_fr = 'Il a du mal à s''endormir ? Créez et lisez-lui un conte unique dans les Contes intelligents.', body_hi = 'सोने में मुश्किल होती है? स्मार्ट कहानियों में एक अनोखी कहानी बनाइए और पढ़कर सुनाइए।', body_id = 'Sulit tertidur? Buat dan bacakan dongeng orisinal di Dongeng Pintar.', body_ja = 'なかなか寝つけない？「スマートおはなし」でオリジナルのお話をつくって、読んであげましょう。', body_ko = '잠들기 힘들어하나요? 스마트 동화에서 세상에 하나뿐인 동화를 만들어 읽어 주세요.', body_nl = 'Moeite met inslapen? Maak een eigen sprookje in Slimme sprookjes en lees het voor.', body_pl = 'Trudno mu zasnąć? Stwórz w Mądrych bajkach oryginalną bajkę i przeczytaj ją.', body_pt = 'Tem dificuldade em adormecer? Crie uma história original nas Histórias Inteligentes e leia-lha.', body_sv = 'Har barnet svårt att somna? Skapa en egen saga i Smarta sagor och läs den.', body_vi = 'Bé khó đi vào giấc ngủ? Hãy tạo và đọc một câu chuyện độc đáo trong Truyện cổ tích thông minh.', body_zh = '入睡有困难？在智能故事里创作一个原创故事，读给宝宝听吧。' WHERE id = 'eec0d21f-e4e1-482b-ae4c-9c9f182e42a1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez con la ropa 👗', body_es = '¿Quiere ponerse el jersey gordo en verano y la camiseta de verano en invierno? Su voluntad se está formando. Saca dos prendas adecuadas y deja que elija preguntándole: «¿Cuál quieres?».', title_fr = 'L''obstination pour les vêtements 👗', body_fr = 'Il veut porter un gros pull en été et un t-shirt en hiver ? Sa volonté se construit. Sortez deux tenues adaptées et laissez-le choisir en demandant « Laquelle tu veux ? ».', title_hi = 'कपड़े चुनने की ज़िद 👗', body_hi = 'मोटा स्वेटर गर्मी में और गर्मी की कमीज़ सर्दी में पहनना चाहता है? उसकी इच्छाशक्ति बन रही है। दो सही कपड़े निकालिए और ''कौन-सा चाहिए?'' पूछकर चुनाव उस पर छोड़िए।', title_id = 'Ngotot memilih baju 👗', body_id = 'Ingin memakai sweter tebal di musim panas, atau kaus tipis di musim dingin? Kemauannya sedang terbentuk. Siapkan dua baju yang sesuai dan biarkan ia memilih dengan bertanya: Mau yang mana?', title_ja = '服選びのこだわり 👗', body_ja = '夏に厚手のセーター、冬に夏のシャツを着たがりますか？意志が育っています。ふさわしい服を2着出して、「どっちがいい？」と選ばせてあげましょう。', title_ko = '옷 고르기 고집 👗', body_ko = '여름에 두꺼운 스웨터를, 겨울에 여름 티셔츠를 입겠다고 하나요? 의지가 자라고 있어요. 알맞은 옷 두 벌을 꺼내 ''어떤 게 좋아?'' 하고 선택을 맡겨 보세요.', title_nl = 'Koppig bij het kiezen van kleren 👗', body_nl = 'Wil hij in de zomer een dikke trui aan en in de winter een zomershirt? Zijn wil wordt gevormd. Leg twee passende kledingstukken klaar en laat hem kiezen: welke wil je?', title_pl = 'Upór przy wyborze ubrań 👗', body_pl = 'Chce nosić gruby sweter latem, a letnią koszulkę zimą? Kształtuje się jego wola. Wyjmij dwa odpowiednie ubrania i zostaw mu wybór, pytając: „Które chcesz?”.', title_pt = 'A teimosia na escolha da roupa 👗', body_pt = 'Quer vestir a camisola grossa no verão e a t-shirt no inverno? A vontade dele está a formar-se. Escolha duas peças adequadas e deixe-o decidir, perguntando "Qual queres?".', title_sv = 'Envis med klädvalet 👗', body_sv = 'Vill barnet ha tjock tröja på sommaren och sommartröja på vintern? Viljan håller på att formas. Ta fram två lämpliga plagg, fråga ”Vilken vill du ha?” och låt barnet välja.', title_vi = 'Bướng bỉnh chọn quần áo 👗', body_vi = 'Bé đòi mặc áo len dày vào mùa hè, áo cộc tay vào mùa đông? Ý chí của bé đang hình thành. Hãy lấy ra hai bộ phù hợp và hỏi "Con muốn mặc bộ nào?" để bé tự chọn.', title_zh = '挑衣服的倔强 👗', body_zh = '夏天想穿厚毛衣，冬天想穿夏装？宝宝的意志正在形成。拿出两件合适的衣服，问“你想穿哪件？”，把选择权交给宝宝。' WHERE id = '81f2ea67-6d6b-45a8-9d3f-bdbc71d94739' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Está muy inquieto y no para en casa? Consulta Tiempo y ropa y salid enseguida al parque. La naturaleza es su calmante más rápido.', body_fr = 'Il est très agité et ne tient pas en place à la maison ? Vérifiez Météo et tenue et filez au parc. La nature est son calmant le plus rapide.', body_hi = 'बच्चा बहुत बेचैन है और घर में टिकता नहीं? मौसम और कपड़े देखिए और तुरंत पार्क की ओर निकलिए। प्रकृति उसके लिए सबसे तेज़ सुकून देने वाली है।', body_id = 'Si kecil sangat gelisah dan tidak betah di rumah? Cek cuaca dan pakaian, lalu langsung ke taman. Alam adalah penenang tercepat baginya.', body_ja = '落ち着かなくて、家の中にじっとしていられない？「天気と服装」をチェックして、すぐに公園へ出かけましょう。自然はお子さんにとって、いちばん早く心を落ち着かせてくれるものです。', body_ko = '아이가 너무 안절부절못하고 집에 있으려 하지 않나요? 날씨와 옷차림을 확인하고 바로 공원으로 가 보세요. 자연은 아이를 가장 빨리 진정시켜 줘요.', body_nl = 'Is je kindje erg onrustig en wil hij niet binnen blijven? Check het weer en de kleding en ga meteen naar het park. De natuur kalmeert hem het snelst.', body_pl = 'Maluch jest bardzo niespokojny i nie może usiedzieć w domu? Sprawdź Pogodę i ubiór i od razu ruszajcie do parku. Natura to dla niego najszybszy sposób na wyciszenie.', body_pt = 'Está muito inquieto e não para em casa? Veja o Tempo e Roupa e siga já para o parque. A natureza é para ele o calmante mais rápido.', body_sv = 'Är barnet väldigt rastlöst och vill inte vara inne? Kolla Väder och kläder och gå direkt till parken. Naturen är det snabbaste sättet att lugna barnet.', body_vi = 'Bé bồn chồn và không chịu ở trong nhà? Hãy xem Thời tiết và trang phục rồi ra công viên ngay. Thiên nhiên là liều thuốc xoa dịu nhanh nhất cho bé.', body_zh = '孩子很烦躁，在家待不住？看看天气与穿衣，马上去公园。大自然是让宝宝最快平静下来的良方。' WHERE id = 'c6ce4007-ba3b-4772-8fba-7c4797ad17dd' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se le queda pequeña la casa? Busca en Lugares para mamás un parque seguro con un gran arenero y columpios, y salid a tomar aire fresco.', body_fr = 'Il se sent à l''étroit à la maison ? Trouvez dans les Lieux adaptés aux mamans un parc sûr avec un grand bac à sable et des balançoires, et sortez prendre l''air.', body_hi = 'घर की दीवारें उसके लिए छोटी पड़ रही हैं? माँ के लिए अनुकूल जगहें में बड़े सैंडपिट और झूलों वाला सुरक्षित पार्क ढूँढिए और ताज़ी हवा में निकलिए।', body_id = 'Rumah terasa sempit baginya? Temukan taman aman dengan bak pasir luas dan ayunan di Tempat Ramah Ibu, lalu keluar menghirup udara segar.', body_ja = '家の中では狭すぎる？「ママにやさしいスポット」で、大きな砂場やブランコのある安全な公園を見つけて、新鮮な空気を吸いに出かけましょう。', body_ko = '집이 답답하게 느껴지나요? 엄마 친화 장소에서 넓은 모래 놀이터와 그네가 있는 안전한 공원을 찾아 맑은 공기를 마시러 나가 보세요.', body_nl = 'Wordt het huis te klein voor hem? Zoek in Mamavriendelijke plekken een veilig park met een grote zandbak en schommels en ga lekker naar buiten.', body_pl = 'W domu robi mu się za ciasno? Znajdź w Miejscach przyjaznych mamom bezpieczny park z dużą piaskownicą i huśtawkami i wyjdźcie na świeże powietrze.', body_pt = 'As paredes de casa ficam-lhe apertadas? Encontre nos Locais Amigos das Mães um parque seguro com uma caixa de areia grande e baloiços e vão apanhar ar puro.', body_sv = 'Känns väggarna hemma för trånga? Hitta en trygg park med stor sandlåda och gungor i Mammavänliga platser och gå ut i friska luften.', body_vi = 'Nhà trở nên chật chội với bé? Hãy tìm một công viên an toàn có hố cát rộng và xích đu trong Địa điểm thân thiện với mẹ rồi ra ngoài hít thở không khí trong lành.', body_zh = '家里的墙关不住宝宝了？在妈妈友好场所里找一个有大沙池和秋千的安全公园，出去呼吸新鲜空气吧。' WHERE id = '5bf406ee-d6c9-4691-8b5e-2df617ed2939' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Carrera de pasta! 🍝', body_es = '¿No quiere sentarse a la mesa? Mira en Recetas para bebé ideas de pasta colorida con verduras y vuelve a atraer su atención al plato.', title_fr = 'La course aux pâtes ! 🍝', body_fr = 'Il ne veut pas rester assis à table ? Regardez les idées de pâtes colorées aux légumes des Recettes pour bébés pour ramener son attention vers l''assiette.', title_hi = 'पास्ता की दौड़! 🍝', body_hi = 'खाने की मेज़ पर बैठना नहीं चाहता? बच्चों की रेसिपी में रंग-बिरंगे सब्ज़ियों वाले पास्ता के आइडिया देखिए और उसका ध्यान फिर से प्लेट पर लाइए।', title_id = 'Pesta pasta! 🍝', body_id = 'Tidak mau duduk di meja makan? Lihat ide pasta sayur warna-warni di Resep Bayi dan tarik kembali perhatiannya ke piring.', title_ja = 'パスタで追いかけっこ！🍝', body_ja = '食卓に座りたがらない？「離乳食を始める赤ちゃんのレシピ」で、カラフルな野菜入りパスタのアイデアをチェックして、もう一度お皿に注目させましょう。', title_ko = '파스타 대작전! 🍝', body_ko = '식탁에 앉기 싫어하나요? 아기 레시피에서 알록달록한 채소 파스타 아이디어를 찾아 다시 접시로 관심을 끌어 보세요.', title_nl = 'Pastarace! 🍝', body_nl = 'Wil hij niet aan tafel zitten? Bekijk in Babyrecepten kleurrijke pasta-ideeën met groenten en trek zijn aandacht weer naar het bord.', title_pl = 'Makaronowy wyścig! 🍝', body_pl = 'Nie chce siedzieć przy stole? Zajrzyj w Przepisach dla niemowląt do pomysłów na kolorowy makaron z warzywami i znów skup jego uwagę na talerzu.', title_pt = 'Corrida da massa! 🍝', body_pt = 'Não quer ficar sentado à mesa? Veja nas Receitas para bebés ideias de massa colorida com legumes e volte a chamar a atenção dele para o prato.', title_sv = 'Pastajakt! 🍝', body_sv = 'Vill barnet inte sitta vid matbordet? Titta på idéer för färgglad pasta med grönsaker i Recept för bebisar och locka tillbaka uppmärksamheten till tallriken.', title_vi = 'Cuộc đua mì ống! 🍝', body_vi = 'Bé không chịu ngồi vào bàn ăn? Hãy xem các ý tưởng mì ống nhiều màu sắc với rau củ trong Công thức cho bé để bé lại chú ý vào đĩa ăn.', title_zh = '意面赛跑！🍝', body_zh = '不愿意坐在餐桌前？看看宝宝食谱里色彩缤纷的蔬菜意面创意，把宝宝的注意力重新吸引回盘子上。' WHERE id = 'ad873c49-3118-429c-a9cf-3328699e514f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la monotonía 🌬️', body_es = '¿El silencio le asusta? Pon en la habitación el sonido del secador o del ventilador de Ruido blanco y verás qué sensación de seguridad crea para dormir.', title_fr = 'La force de la monotonie 🌬️', body_fr = 'Le silence lui fait peur ? Lancez dans la chambre le bruit de sèche-cheveux ou de ventilateur des Bruits blancs et voyez comme il crée un sentiment de sécurité pour dormir.', title_hi = 'एक जैसी आवाज़ की ताकत 🌬️', body_hi = 'खामोशी उसे डराती है? कमरे में व्हाइट नॉइज़ से हेयर ड्रायर या पंखे की आवाज़ चलाइए और देखिए कि यह नींद के माहौल में कैसे सुरक्षा का एहसास देती है।', title_id = 'Kekuatan suara monoton 🌬️', body_id = 'Keheningan membuatnya takut? Putar suara pengering rambut atau kipas angin dari Suara Putih di kamar dan lihat bagaimana suara itu menciptakan rasa aman saat tidur.', title_ja = '単調な音の力 🌬️', body_ja = '静けさがこわい？部屋で「ホワイトノイズ」のドライヤーや扇風機の音を流して、眠りの環境にどれほど安心感が生まれるか確かめてみましょう。', title_ko = '단조로운 소리의 힘 🌬️', body_ko = '조용하면 무서워하나요? 백색소음에서 헤어드라이어나 선풍기 소리를 틀어 수면 환경에 어떻게 안정감을 주는지 확인해 보세요.', title_nl = 'De kracht van eentonigheid 🌬️', body_nl = 'Maakt stilte hem bang? Zet in de kamer het geluid van een föhn of ventilator uit Witte ruis aan en zie hoe het in zijn slaapomgeving een veilig gevoel geeft.', title_pl = 'Moc monotonii 🌬️', body_pl = 'Cisza go przeraża? Włącz w pokoju odgłos suszarki lub wentylatora z Białego szumu i zobacz, jak daje mu poczucie bezpieczeństwa podczas snu.', title_pt = 'A força da monotonia 🌬️', body_pt = 'O silêncio assusta-o? Ligue no quarto o som do secador de cabelo ou da ventoinha do Ruído Branco e veja como cria uma sensação de segurança no ambiente de sono.', title_sv = 'Kraften i monotona ljud 🌬️', body_sv = 'Skrämmer tystnaden barnet? Sätt på hårtorks- eller fläktljud från Vitt brus i rummet och se hur det skapar en känsla av trygghet i sömnmiljön.', title_vi = 'Sức mạnh của âm thanh đều đều 🌬️', body_vi = 'Sự im lặng khiến bé sợ? Hãy bật tiếng máy sấy tóc hoặc quạt trong Tiếng ồn trắng và xem âm thanh này tạo cảm giác an toàn cho giấc ngủ thế nào.', title_zh = '单调声音的力量 🌬️', body_zh = '安静会让宝宝害怕？在房间里打开白噪音里的吹风机或风扇声，看看它如何在睡眠环境中带来安全感。' WHERE id = 'dca5184f-26ea-4b5e-b78d-2f4c36c6bf42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Felicítate! 🌟', body_es = '¿Hoy has conseguido vestirle sin lágrimas? Escribe hasta tu logro más pequeño en el Diario de ánimo y aplaude tu talento como madre.', title_fr = 'Félicitez-vous ! 🌟', body_fr = 'Vous avez réussi à l''habiller sans pleurs aujourd''hui ? Notez même votre plus petite réussite dans le Journal d''humeur et applaudissez debout vos talents de maman.', title_hi = 'खुद की तारीफ़ कीजिए! 🌟', body_hi = 'आज उसे बिना रुलाए कपड़े पहना पाईं? मूड डायरी में अपनी छोटी से छोटी सफलता भी लिखिए और अपनी माँ होने की काबिलियत के लिए खुद को शाबाशी दीजिए।', title_id = 'Puji diri Anda! 🌟', body_id = 'Hari ini berhasil memakaikan bajunya tanpa tangisan? Tulis keberhasilan sekecil apa pun di Buku Harian Suasana Hati dan beri tepuk tangan untuk kemampuan Anda sebagai ibu.', title_ja = '自分を褒めてあげて！🌟', body_ja = '今日は泣かせずに着替えさせられましたか？「気分日記」にどんな小さな成功も書いて、ママとしての自分にスタンディングオベーションを送りましょう。', title_ko = '스스로를 칭찬하세요! 🌟', body_ko = '오늘 울리지 않고 옷을 입혔나요? 기분 일기에 아주 작은 성공이라도 적고, 엄마로서의 능력에 기립 박수를 보내 주세요.', title_nl = 'Geef jezelf een compliment! 🌟', body_nl = 'Is het je vandaag gelukt hem aan te kleden zonder tranen? Schrijf zelfs je kleinste succes op in je Stemmingsdagboek en geef jezelf een staande ovatie als moeder.', title_pl = 'Pochwal się! 🌟', body_pl = 'Udało ci się dziś ubrać go bez płaczu? Zapisz w Dzienniku nastroju nawet najmniejszy sukces i nagródź swoje macierzyńskie umiejętności owacją na stojąco.', title_pt = 'Elogie-se! 🌟', body_pt = 'Hoje conseguiu vesti-lo sem choro? Escreva no Diário de Humor até o seu sucesso mais pequeno e aplauda de pé a sua capacidade de ser mãe.', title_sv = 'Beröm dig själv! 🌟', body_sv = 'Lyckades du klä på barnet i dag utan tårar? Skriv ner även den minsta framgången i Humördagboken och ge dina mammakunskaper stående ovationer.', title_vi = 'Hãy tự khen mình! 🌟', body_vi = 'Hôm nay mẹ mặc đồ cho bé mà bé không khóc? Hãy ghi cả thành công nhỏ nhất vào Nhật ký tâm trạng và tự vỗ tay cho kỹ năng làm mẹ của mình.', title_zh = '夸夸自己！🌟', body_zh = '今天没让宝宝哭就给穿好衣服了？哪怕再小的成功，也写进心情日记，为自己当妈妈的本领热烈鼓掌。' WHERE id = '04ea5cc7-5f44-4fc9-ad82-59f8e294f0a5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo inmunitario 🛡️', body_es = '¿Lista para el cambio de estación? Comprueba con el Seguimiento de tomas si hoy ha tomado suficiente vitamina C y actualiza su menú.', title_fr = 'Bouclier immunitaire 🛡️', body_fr = 'Prête pour le changement de saison ? Vérifiez avec le Suivi des repas s''il a eu assez de vitamine C aujourd''hui et mettez son menu à jour.', title_hi = 'इम्युनिटी की ढाल 🛡️', body_hi = 'मौसम बदलने के लिए तैयार हैं? फ़ीडिंग ट्रैकर से जाँचिए कि आज उसे पर्याप्त विटामिन C मिला या नहीं, और मेन्यू अपडेट कीजिए।', title_id = 'Perisai imunitas 🛡️', body_id = 'Siap menghadapi pergantian musim? Cek dengan alat Pemantau Nutrisi apakah hari ini ia sudah cukup mendapat vitamin C, lalu perbarui menunya.', title_ja = '免疫のシールド 🛡️', body_ja = '季節の変わり目の準備はできていますか？「栄養管理ツール」で、今日ビタミンCを十分とれたか確認して、メニューを見直しましょう。', title_ko = '면역력 방패 🛡️', body_ko = '환절기 준비는 되셨나요? 수유 기록 도구로 오늘 비타민 C를 충분히 섭취했는지 확인하고 식단을 새로 짜 보세요.', title_nl = 'Immuunschild 🛡️', body_nl = 'Klaar voor de seizoenswissel? Check met de Voedingstracker of hij vandaag genoeg vitamine C heeft gehad en pas het menu aan.', title_pl = 'Tarcza odporności 🛡️', body_pl = 'Gotowa na zmianę pory roku? Sprawdź w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco witaminy C, i odśwież menu.', title_pt = 'Escudo de imunidade 🛡️', body_pt = 'Está preparada para a mudança de estação? Verifique com o Registo de Alimentação se hoje recebeu vitamina C suficiente e atualize a ementa.', title_sv = 'Immunförsvarets sköld 🛡️', body_sv = 'Är ni redo för årstidsskiftet? Kontrollera med Matningskoll att barnet fått tillräckligt med C-vitamin i dag och uppdatera menyn.', title_vi = 'Lá chắn miễn dịch 🛡️', body_vi = 'Mẹ đã sẵn sàng cho lúc giao mùa? Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã nhận đủ vitamin C chưa và làm mới thực đơn.', title_zh = '免疫护盾 🛡️', body_zh = '准备好迎接换季了吗？用喂养记录工具看看宝宝今天是否摄入了足够的维生素C，更新一下菜单。' WHERE id = '5d85dda7-f62e-4490-8b4e-2ca037fd60ac' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pegar y empujar 🛑', body_es = '¿Levanta la mano o empuja cuando se enfada de repente? Pregunta a Anacan AI cómo resolver esta conducta difícil de los 21,5 meses convirtiéndola en un juego.', title_fr = 'Taper et pousser 🛑', body_fr = 'Il lève la main ou pousse quand il se fâche soudain ? Demandez à Anacan AI comment gérer par le jeu ce comportement difficile à 21,5 mois.', title_hi = 'मारना और धक्का देना 🛑', body_hi = 'अचानक गुस्से में हाथ उठाता है या धक्का देता है? 21.5 महीने के इस मुश्किल व्यवहार को खेल बनाकर कैसे सुलझाएँ, यह Anacan AI से पूछिए।', title_id = 'Memukul dan mendorong 🛑', body_id = 'Tiba-tiba mengangkat tangan atau mendorong saat marah? Tanyakan kepada Anacan AI cara mengatasi perilaku sulit usia 21,5 bulan ini dengan menjadikannya permainan.', title_ja = 'たたく、押す 🛑', body_ja = '急に怒ると手が出たり、押したりしますか？1歳9か月半ごろのこの難しい行動に、遊びを通してどう対応すればいいか、Anacan AIに聞いてみましょう。', title_ko = '때리기와 밀기 🛑', body_ko = '갑자기 화가 나면 손을 들거나 밀치나요? 21.5개월의 이 어려운 행동을 놀이로 바꿔 다루는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Slaan en duwen 🛑', body_nl = 'Haalt hij uit of duwt hij als hij ineens boos wordt? Vraag Anacan AI hoe je dit lastige gedrag op 21,5 maand met spelletjes aanpakt.', title_pl = 'Bicie i popychanie 🛑', body_pl = 'Gdy nagle się złości, podnosi rękę albo popycha? Zapytaj Anacan AI, jak zamienić w zabawę to trudne zachowanie 21,5 miesiąca i sobie z nim poradzić.', title_pt = 'Bater e empurrar 🛑', body_pt = 'Quando se zanga de repente, levanta a mão ou empurra? Pergunte ao Anacan AI como resolver este comportamento difícil dos 21,5 meses transformando-o num jogo.', title_sv = 'Slår och knuffar 🛑', body_sv = 'Lyfter barnet handen eller knuffar när hen plötsligt blir arg? Fråga Anacan AI hur du kan hantera detta svåra beteende vid 21,5 månader genom att göra det till en lek.', title_vi = 'Đánh và xô đẩy 🛑', body_vi = 'Bé bất ngờ vung tay hoặc xô đẩy khi tức giận? Hãy hỏi Anacan AI cách xử lý hành vi khó khăn của tháng 21,5 này bằng cách biến nó thành trò chơi.', title_zh = '打人和推人 🛑', body_zh = '一生气就突然动手或推人？问问Anacan AI，如何把21.5个月的这种棘手行为变成游戏来解决。' WHERE id = '680f971c-231a-40e8-a772-413975915698' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Protesta contra el verde 🥦', body_es = '¿Rechaza las verduras? Descubre en Recetas para bebés que empiezan con la alimentación complementaria cómo esconderlas en unas tortitas deliciosas.', title_fr = 'Le vert, très peu pour lui 🥦', body_fr = 'Il refuse les légumes ? Découvrez dans les Recettes pour bébés qui commencent la diversification comment les cacher dans de délicieuses crêpes.', title_hi = 'हरे रंग से इनकार 🥦', body_hi = 'सब्ज़ियाँ नहीं खाता? ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी में जानिए कि उन्हें स्वादिष्ट पैनकेक में कैसे छिपाएँ।', title_id = 'Protes pada warna hijau 🥦', body_id = 'Menolak sayuran? Temukan di Resep untuk bayi yang mulai MPASI cara menyembunyikannya di dalam panekuk yang lezat.', title_ja = '緑の野菜に反対 🥦', body_ja = '野菜を嫌がりますか？「離乳食を始める赤ちゃんのレシピ」で、おいしいパンケーキの中に野菜を隠す方法を見つけましょう。', title_ko = '초록색은 싫어요 🥦', body_ko = '채소를 거부하나요? 이유식을 시작하는 아기를 위한 레시피에서 맛있는 팬케이크 속에 채소를 숨기는 법을 찾아보세요.', title_nl = 'Protest tegen groen 🥦', body_nl = 'Weigert hij groenten? Ontdek in Recepten voor baby''s die met bijvoeding beginnen hoe je ze verstopt in lekkere pannenkoekjes.', title_pl = 'Protest przeciw zieleni 🥦', body_pl = 'Odrzuca warzywa? Odkryj w Przepisach dla niemowląt rozpoczynających rozszerzanie diety, jak ukryć je w pysznych placuszkach.', title_pt = 'Protesto contra o verde 🥦', body_pt = 'Rejeita os legumes? Descubra nas Receitas para bebés em diversificação alimentar como escondê-los dentro de panquecas deliciosas.', title_sv = 'Protest mot det gröna 🥦', body_sv = 'Vägrar barnet grönsaker? Upptäck i Recept för bebisar som börjar med fast föda hur du gömmer dem i goda pannkakor.', title_vi = 'Phản đối màu xanh 🥦', body_vi = 'Bé từ chối rau củ? Hãy khám phá cách giấu rau vào những chiếc bánh kếp ngon lành trong Công thức cho bé bắt đầu ăn dặm.', title_zh = '拒绝绿色 🥦', body_zh = '不吃蔬菜？在适合刚开始添加辅食宝宝的食谱里，发现如何把蔬菜藏进美味的小煎饼里。' WHERE id = '9faf82e4-78ff-4782-a4bb-0d745a808c97' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te rindas al cansancio 🛋️', body_es = '¿Hoy te han dado ganas de dejarlo todo? ¡Es normal! Abre el Diario de ánimo, escribe tus agobios y dedícate esta noche solo a ti.', title_fr = 'Ne cédez pas à la fatigue 🛋️', body_fr = 'Vous aviez envie de tout lâcher aujourd''hui ? C''est normal ! Ouvrez le Journal d''humeur, écrivez ce qui vous pèse et consacrez cette soirée à vous seule.', title_hi = 'थकान के आगे हार मत मानिए 🛋️', body_hi = 'आज सब कुछ छोड़ देने का मन हुआ? यह सामान्य है! मूड डायरी खोलिए, मन की घुटन लिखिए और यह शाम सिर्फ़ खुद को दीजिए।', title_id = 'Jangan menyerah pada rasa lelah 🛋️', body_id = 'Hari ini ingin melepaskan semuanya? Itu wajar! Buka Buku Harian Suasana Hati, tulis beban hati Anda, dan khususkan malam ini hanya untuk diri sendiri.', title_ja = '疲れに負けないで 🛋️', body_ja = '今日は何もかも投げ出したくなりましたか？それは普通のことです！「気分日記」を開いて心のもやもやを書き、今夜は自分のためだけに過ごしましょう。', title_ko = '피로에 지지 마세요 🛋️', body_ko = '오늘 다 내려놓고 싶었나요? 자연스러운 일이에요! 기분 일기를 열어 속상한 마음을 적고, 오늘 저녁은 오롯이 나를 위해 보내세요.', title_nl = 'Geef niet toe aan vermoeidheid 🛋️', body_nl = 'Wilde je vandaag alles laten vallen? Dat is normaal! Open je Stemmingsdagboek, schrijf je zorgen op en wijd deze avond helemaal aan jezelf.', title_pl = 'Nie poddawaj się zmęczeniu 🛋️', body_pl = 'Chciałaś dziś wszystko rzucić? To normalne! Otwórz Dziennik nastroju, zapisz, co cię gnębi, i poświęć ten wieczór tylko sobie.', title_pt = 'Não se renda ao cansaço 🛋️', body_pt = 'Hoje apeteceu-lhe largar tudo? É normal! Abra o Diário de Humor, escreva a sua angústia e dedique esta noite só a si.', title_sv = 'Ge inte upp för tröttheten 🛋️', body_sv = 'Ville du släppa allt i dag? Det är helt normalt! Öppna Humördagboken, skriv ner det som tynger dig och ägna kvällen bara åt dig själv.', title_vi = 'Đừng gục ngã trước mệt mỏi 🛋️', body_vi = 'Hôm nay mẹ muốn buông bỏ tất cả? Điều đó là bình thường! Hãy mở Nhật ký tâm trạng, viết ra nỗi niềm và dành trọn buổi tối nay cho riêng mình.', title_zh = '别向疲惫投降 🛋️', body_zh = '今天想把一切都放下？这很正常！打开心情日记，写下心里的烦闷，今晚只属于你自己。' WHERE id = 'c2142ff9-9553-4737-9602-95ee907b4599' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿El pañal sigue seco? 🧻', body_es = '¡Revisión de la mañana! Si el pañal se mantiene seco mucho tiempo, se acerca el momento del orinal. Anótalo en el Seguimiento de pañales y revisa las estadísticas.', title_fr = 'La couche reste sèche ? 🧻', body_fr = 'Contrôle du matin ! Si sa couche reste sèche longtemps, l''heure du pot approche. Notez-le dans le Suivi des couches et consultez les statistiques.', title_hi = 'डायपर सूखा रहता है? 🧻', body_hi = 'सुबह की जाँच! अगर डायपर लंबे समय तक सूखा रहता है, तो पॉटी का समय करीब है। डायपर ट्रैकर में दर्ज कीजिए और आँकड़े देखिए।', title_id = 'Popoknya tetap kering? 🧻', body_id = 'Cek pagi! Jika popoknya tetap kering dalam waktu lama, waktu latihan pispot sudah dekat. Catat di Pelacak Popok dan cek statistiknya.', title_ja = 'おむつが乾いたまま？🧻', body_ja = '朝のチェック！おむつが長い時間乾いたままなら、トイレトレーニングの時期が近づいています。「おむつトラッカー」に記録して、統計を確認しましょう。', title_ko = '기저귀가 보송보송한가요? 🧻', body_ko = '아침 확인! 기저귀가 오랫동안 젖지 않는다면 배변 훈련 시기가 다가오고 있어요. 기저귀 기록에 남기고 통계를 확인하세요.', title_nl = 'Blijft de luier droog? 🧻', body_nl = 'Ochtendcheck! Blijft de luier lang droog, dan komt de tijd van het potje dichterbij. Noteer het in de Luiertracker en bekijk de statistieken.', title_pl = 'Pieluszka zostaje sucha? 🧻', body_pl = 'Poranna kontrola! Jeśli pieluszka długo pozostaje sucha, zbliża się czas na nocnik. Zapisz to w narzędziu do śledzenia pieluszek i sprawdź statystyki.', title_pt = 'A fralda fica seca? 🧻', body_pt = 'Verificação da manhã! Se a fralda fica seca durante muito tempo, a hora do bacio está a aproximar-se. Registe-o no Registo de Fraldas e veja as estatísticas.', title_sv = 'Är blöjan torr? 🧻', body_sv = 'Morgonkoll! Om blöjan håller sig torr länge närmar sig dags för pottan. Anteckna i Blöjkollen och titta på statistiken.', title_vi = 'Tã vẫn khô? 🧻', body_vi = 'Kiểm tra buổi sáng! Nếu tã của bé khô trong thời gian dài, đã sắp đến lúc tập ngồi bô. Hãy ghi lại trong Theo dõi tã và xem thống kê.', title_zh = '尿布一直是干的？🧻', body_zh = '早上检查一下！如果尿布能长时间保持干爽，说明用便盆的时机快到了。记在尿布记录里，看看统计吧。' WHERE id = 'cc7b1b1f-1c7c-4424-996a-a223a00c890e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasión por hacer girar 🌀', body_es = '¿No para de hacer girar ruedas o tapones? Lee en el Blog sobre esta necesidad motriz tan concreta y su papel en el desarrollo cognitivo.', title_fr = 'Il adore faire tourner 🌀', body_fr = 'Il fait tourner sans arrêt les roues ou les couvercles ? Lisez dans la rubrique Blogs ce besoin moteur particulier et son rôle dans le développement cognitif.', title_hi = 'घुमाने का शौक 🌀', body_hi = 'पहियों या ढक्कनों को लगातार घुमाता रहता है? मोटर स्किल्स की इस खास ज़रूरत और समझ के विकास में इसकी भूमिका के बारे में ब्लॉग में पढ़िए।', title_id = 'Suka memutar-mutar 🌀', body_id = 'Terus memutar roda atau tutup botol? Baca di Blog tentang kebutuhan motorik khusus ini dan perannya dalam perkembangan kognitif.', title_ja = 'くるくる回すのが大好き 🌀', body_ja = 'タイヤやふたを休みなく回していますか？この特有の運動の欲求と、それが認知の発達に果たす役割について、ブログで読んでみましょう。', title_ko = '빙글빙글 돌리기 사랑 🌀', body_ko = '바퀴나 뚜껑을 쉬지 않고 돌리나요? 이 특별한 운동 욕구와 인지 발달에서의 역할을 블로그에서 읽어 보세요.', title_nl = 'Dol op draaien 🌀', body_nl = 'Laat hij wieltjes of dopjes zonder ophouden draaien? Lees in Blogs over deze specifieke motorische behoefte en de rol ervan in zijn cognitieve ontwikkeling.', title_pl = 'Miłość do kręcenia 🌀', body_pl = 'Bez przerwy kręci kółkami albo nakrętkami? Przeczytaj na Blogu o tej szczególnej potrzebie ruchowej i jej roli w rozwoju poznawczym.', title_pt = 'O gosto de fazer girar 🌀', body_pt = 'Faz girar rodas ou tampas sem parar? Leia nos Blogues sobre esta necessidade motora específica e o seu papel no desenvolvimento cognitivo.', title_sv = 'Älskar att snurra saker 🌀', body_sv = 'Snurrar barnet oavbrutet på hjul eller lock? Läs i Bloggar om detta typiska motoriska behov och dess roll i den kognitiva utvecklingen.', title_vi = 'Mê xoay tròn 🌀', body_vi = 'Bé xoay bánh xe hay nắp hộp không ngừng? Hãy đọc trong mục Blog về nhu cầu vận động đặc biệt này và vai trò của nó trong phát triển nhận thức.', title_zh = '爱转圈圈 🌀', body_zh = '不停地转轮子或盖子？去博客读读这种特殊的动作需求，以及它在认知发展中的作用。' WHERE id = '86da0f7a-f021-4c65-aed2-e8e15433a92d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena 🏖️', body_es = '¡No tengas miedo a que se ensucie! Busca en Lugares para mamás un sitio con arenero. Tocar la arena es perfecto para su desarrollo sensorial.', title_fr = 'Thérapie par le sable 🏖️', body_fr = 'N''ayez pas peur qu''il se salisse ! Trouvez un lieu avec bac à sable dans les Lieux adaptés aux mamans. Toucher le sable est parfait pour son développement sensoriel.', title_hi = 'रेत थेरेपी 🏖️', body_hi = 'गंदा होने से मत डरिए! माँ के लिए अनुकूल जगहें में सैंडपिट वाली जगह ढूँढिए। रेत छूना सेंसरी विकास के लिए बेहतरीन है।', title_id = 'Terapi pasir 🏖️', body_id = 'Jangan takut kotor! Temukan tempat dengan bak pasir di Tempat Ramah Ibu. Menyentuh pasir sangat baik untuk perkembangan sensorik.', title_ja = '砂あそびセラピー 🏖️', body_ja = '汚れるのをこわがらないで！「ママにやさしいスポット」で砂場のある場所を見つけましょう。砂にさわるのは、感覚の発達にぴったりです。', title_ko = '모래 놀이 테라피 🏖️', body_ko = '더러워지는 걸 두려워하지 마세요! 엄마 친화 장소에서 모래 놀이터가 있는 곳을 찾아보세요. 모래를 만지는 건 감각 발달에 아주 좋아요.', title_nl = 'Zandtherapie 🏖️', body_nl = 'Wees niet bang voor vieze handjes! Zoek in Mamavriendelijke plekken een plek met een zandbak. Zand voelen is perfect voor de zintuiglijke ontwikkeling.', title_pl = 'Terapia piaskiem 🏖️', body_pl = 'Nie bój się brudu! Znajdź w Miejscach przyjaznych mamom miejsce z piaskownicą. Dotykanie piasku jest wspaniałe dla rozwoju sensorycznego.', title_pt = 'Terapia com areia 🏖️', body_pt = 'Não tenha medo que se suje! Encontre nos Locais Amigos das Mães um sítio com caixa de areia. Tocar na areia é perfeito para o desenvolvimento sensorial.', title_sv = 'Sandterapi 🏖️', body_sv = 'Var inte rädd för smuts! Hitta ett ställe med sandlåda i Mammavänliga platser. Att känna på sand är perfekt för sinnesutvecklingen.', title_vi = 'Liệu pháp cát 🏖️', body_vi = 'Đừng sợ bé bị bẩn! Hãy tìm một nơi có hố cát trong Địa điểm thân thiện với mẹ. Chạm vào cát rất tuyệt cho sự phát triển giác quan.', title_zh = '沙子疗法 🏖️', body_zh = '别怕弄脏！在妈妈友好场所里找一个有沙池的地方。触摸沙子对感官发展非常好。' WHERE id = '9ea6bc21-5003-4afe-8fca-e2eebb549250' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tiene estreñimiento? 🚽', body_es = 'Al cambiar el pañal de la mañana, fíjate en las cacas. Si hay estreñimiento, anótalo en la app y elige alimentos ricos en fibra (pera, avena) en Recetas para bebés que empiezan con la alimentación complementaria.', title_fr = 'Un souci de constipation ? 🚽', body_fr = 'En changeant la couche du matin, observez les selles. En cas de constipation, notez-le dans l''appli et choisissez des aliments riches en fibres (poire, avoine) dans les Recettes pour bébés qui commencent la diversification.', title_hi = 'कब्ज़ की परेशानी? 🚽', body_hi = 'सुबह डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ हो तो ऐप में दर्ज कीजिए और ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी से फ़ाइबर वाली चीज़ें (नाशपाती, ओट्स) चुनिए।', title_id = 'Ada masalah sembelit? 🚽', body_id = 'Perhatikan kotorannya saat mengganti popok pagi. Jika ia sembelit, catat di aplikasi dan pilih makanan berserat (pir, oat) dari Resep untuk bayi yang mulai MPASI.', title_ja = '便秘ぎみ？🚽', body_ja = '朝のおむつ替えのときに、うんちの様子をチェックしましょう。便秘ならアプリに記録して、「離乳食を始める赤ちゃんのレシピ」から食物繊維の多い食べ物（洋なし、オートミール）を選びましょう。', title_ko = '변비가 있나요? 🚽', body_ko = '아침에 기저귀를 갈 때 배변을 살펴보세요. 변비가 있다면 앱에 기록하고 이유식을 시작하는 아기를 위한 레시피에서 섬유질 음식(배, 귀리)을 골라 보세요.', title_nl = 'Last van verstopping? 🚽', body_nl = 'Let bij het verschonen van de ochtendluier op de ontlasting. Bij verstopping: noteer het in de app en kies vezelrijk eten (peer, havermout) uit Recepten voor baby''s die met bijvoeding beginnen.', title_pl = 'Problem z zaparciami? 🚽', body_pl = 'Przy porannej zmianie pieluszki obserwuj kupkę. Jeśli są zaparcia, zapisz to w aplikacji i wybierz w Przepisach dla niemowląt rozpoczynających rozszerzanie diety produkty bogate w błonnik (gruszka, płatki owsiane).', title_pt = 'Prisão de ventre? 🚽', body_pt = 'Ao mudar a fralda da manhã, observe as fezes. Se houver prisão de ventre, registe-o na app e escolha nas Receitas para bebés em diversificação alimentar alimentos ricos em fibra (pera, aveia).', title_sv = 'Förstoppning? 🚽', body_sv = 'Håll koll på avföringen när du byter morgonblöjan. Vid förstoppning, anteckna det i appen och välj fiberrik mat (päron, havre) från Recept för bebisar som börjar med fast föda.', title_vi = 'Bé bị táo bón? 🚽', body_vi = 'Hãy để ý phân khi thay tã buổi sáng. Nếu bé bị táo bón, hãy ghi vào ứng dụng và chọn thực phẩm giàu chất xơ (lê, yến mạch) từ Công thức cho bé bắt đầu ăn dặm.', title_zh = '便秘了？🚽', body_zh = '早上换尿布时留意一下排便。如果便秘，记到应用里，并在适合刚开始添加辅食宝宝的食谱里选择富含纤维的食物（梨、燕麦）。' WHERE id = '081299bb-b5c9-4af5-8361-9fa39bbdf0bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Artista en acción 🎨', body_es = '¿Mientras garabatea también se pinta a sí mismo? Para pinturas inofensivas y lavables, mira en Productos recomendados los productos que más eligen las madres.', title_fr = 'Artiste au travail 🎨', body_fr = 'Il se colorie lui-même en gribouillant ? Pour des peintures sans danger et lavables, regardez les produits préférés des mamans dans les Produits recommandés.', title_hi = 'चित्रकार काम पर 🎨', body_hi = 'आड़ी-तिरछी लकीरें खींचते हुए खुद को भी रंग लेता है? सुरक्षित, धुलने वाले रंगों के लिए सुझाए गए प्रोडक्ट में माँओं की सबसे पसंदीदा चीज़ें देखिए।', title_id = 'Pelukis sedang beraksi 🎨', body_id = 'Ikut mewarnai dirinya saat mencoret-coret? Untuk cat yang aman dan bisa dicuci, lihat produk pilihan favorit para ibu di Produk Rekomendasi.', title_ja = '画家が作業中 🎨', body_ja = 'お絵かき中に自分まで塗っていますか？安全で洗える絵の具は、「おすすめ商品」でママたちにいちばん選ばれているアイテムをチェックしましょう。', title_ko = '화가 작업 중 🎨', body_ko = '낙서하다가 자기 몸까지 칠하나요? 안전하고 잘 지워지는 물감은 추천 제품에서 엄마들이 가장 많이 고른 제품을 살펴보세요.', title_nl = 'Kunstenaar aan het werk 🎨', body_nl = 'Kleurt hij zichzelf mee tijdens het krabbelen? Bekijk in Aanbevolen producten de onschadelijke, afwasbare verf die moeders het vaakst kiezen.', title_pl = 'Artysta przy pracy 🎨', body_pl = 'Bazgrząc, maluje też siebie? Zajrzyj w Polecanych produktach do bezpiecznych, zmywalnych farb, które mamy wybierają najczęściej.', title_pt = 'Artista em ação 🎨', body_pt = 'Pinta-se a si próprio enquanto rabisca? Para tintas inofensivas e laváveis, veja nos Produtos Recomendados os produtos mais escolhidos pelas mães.', title_sv = 'Konstnären i farten 🎨', body_sv = 'Målar barnet även sig själv när hen klottrar? Titta på de produkter mammor väljer mest för ofarliga, tvättbara färger i Rekommenderade produkter.', title_vi = 'Họa sĩ đang làm việc 🎨', body_vi = 'Bé vẽ nguệch ngoạc rồi tô cả lên người? Hãy xem những sản phẩm màu vẽ an toàn, dễ giặt sạch được các mẹ chọn nhiều nhất trong Sản phẩm gợi ý.', title_zh = '画家上班啦 🎨', body_zh = '涂鸦时把自己也涂成了彩色？去推荐商品看看妈妈们最常选的无害、可水洗颜料。' WHERE id = 'a11b2562-1cd1-41dc-ac6f-d1a7d36b53bb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Frases como «¡Mamá, ven!» 🗣️', body_es = '¿Ya intenta juntar dos palabras para formar una frase? ¡Un gran salto en el desarrollo del lenguaje! Guarda sus primeras frases como recuerdo en el Seguimiento del desarrollo.', title_fr = 'Les phrases « Maman viens ! » 🗣️', body_fr = 'Il essaie déjà d''assembler deux mots pour faire une phrase ? Quel bond dans son langage ! Notez ses premières petites phrases en souvenir dans le Suivi de développement.', title_hi = '''माँ आओ!'' वाले वाक्य 🗣️', body_hi = 'अब दो शब्द जोड़कर वाक्य बनाने की कोशिश करता है? भाषा के विकास में बड़ी छलांग! ग्रोथ ट्रैकर में उसके पहले छोटे वाक्य याद के रूप में दर्ज कीजिए।', title_id = 'Kalimat Mama sini! 🗣️', body_id = 'Ia sudah mencoba menggabungkan dua kata menjadi kalimat? Lompatan besar dalam perkembangan bahasa! Simpan kalimat-kalimat kecil pertamanya sebagai kenangan di Pelacak Perkembangan.', title_ja = '「ママきて！」の文 🗣️', body_ja = 'もう2つの言葉をつなげて文をつくろうとしていますか？言葉の発達の大きな飛躍です！はじめての小さな文を、思い出として「発達トラッカー」に記録しましょう。', title_ko = '''엄마 와!'' 문장 🗣️', body_ko = '벌써 두 단어를 이어 문장을 만들려고 하나요? 언어 발달의 큰 도약이에요! 성장 기록에 아이의 첫 짧은 문장을 추억으로 남겨 두세요.', title_nl = 'Mama kom!-zinnetjes 🗣️', body_nl = 'Probeert hij al twee woorden te combineren tot een zinnetje? Een grote sprong in de taalontwikkeling! Noteer zijn eerste zinnetjes als herinnering in de Groeitracker.', title_pl = 'Zdania w stylu „Mama, chodź!” 🗣️', body_pl = 'Już próbuje łączyć dwa słowa w zdania? Wielki skok w rozwoju mowy! Zapisz jego pierwsze małe zdania na pamiątkę w Śledzeniu rozwoju.', title_pt = 'Frases como "Mamã, vem!" 🗣️', body_pt = 'Já tenta juntar duas palavras e formar uma frase? Um grande salto no desenvolvimento da linguagem! Registe no Registo de Desenvolvimento as primeiras frasezinhas dele como recordação.', title_sv = 'Meningar som ”Mamma kom!” 🗣️', body_sv = 'Försöker barnet redan sätta ihop två ord till en mening? Ett stort språng i språkutvecklingen! Spara barnets första små meningar som minnen i Utvecklingsspåraren.', title_vi = 'Những câu "Mẹ ơi lại đây!" 🗣️', body_vi = 'Bé đã thử ghép hai từ để nói câu? Một bước nhảy vọt lớn về ngôn ngữ! Hãy ghi lại những câu nói nhỏ đầu tiên của bé vào Theo dõi phát triển để làm kỷ niệm.', title_zh = '“妈妈来！”的句子 🗣️', body_zh = '已经在尝试把两个词连成句子了？语言发展的一大飞跃！把宝宝最初的小句子作为纪念记在发育追踪里。' WHERE id = '3e9ffaf8-f631-4e99-946e-651b683eab7f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabietas en el súper 🛒', body_es = '¿Se ha tirado al suelo porque no le compraste lo que quería? Que no cunda el pánico. Ignora las miradas y agáchate con calma a la altura de sus ojos.', title_fr = 'Crises au supermarché 🛒', body_fr = 'Il s''est jeté par terre parce que vous n''avez pas acheté ce qu''il voulait ? Pas de panique. Ignorez les regards et baissez-vous calmement à sa hauteur.', title_hi = 'बाज़ार में नखरे 🛒', body_hi = 'दुकान में मनचाही चीज़ नहीं मिली तो ज़मीन पर लोट गया? घबराइए मत। आसपास के लोगों की नज़रों की परवाह किए बिना शांति से झुककर उसकी आँखों के स्तर पर आइए।', title_id = 'Tantrum di supermarket 🛒', body_id = 'Ia menjatuhkan diri ke lantai karena tidak dibelikan yang diinginkannya di toko? Jangan panik. Abaikan tatapan orang lain dan dengan tenang turunkan badan sejajar matanya.', title_ja = 'お店でのかんしゃく 🛒', body_ja = 'お店でほしいものを買ってもらえず、床にひっくり返りましたか？慌てないで。周りの視線は気にせず、落ち着いて目線の高さまでしゃがみましょう。', title_ko = '마트에서 떼쓰기 🛒', body_ko = '가게에서 원하는 걸 안 사 줬다고 바닥에 드러누웠나요? 당황하지 마세요. 주변 시선은 신경 쓰지 말고 조용히 아이 눈높이로 몸을 낮춰 주세요.', title_nl = 'Driftbuien in de supermarkt 🛒', body_nl = 'Gooide hij zich op de grond omdat je in de winkel niet kocht wat hij wilde? Geen paniek. Negeer de blikken van anderen en zak rustig door je knieën tot zijn ooghoogte.', title_pl = 'Histerie w sklepie 🛒', body_pl = 'Rzucił się na podłogę, bo nie kupiłaś mu tego, co chciał? Bez paniki. Nie zwracaj uwagi na spojrzenia innych i spokojnie zniż się do poziomu jego oczu.', title_pt = 'Birras no supermercado 🛒', body_pt = 'Atirou-se para o chão porque não lhe comprou o que queria na loja? Não entre em pânico. Ignore os olhares à volta e baixe-se com calma ao nível dos olhos dele.', title_sv = 'Utbrott i affären 🛒', body_sv = 'Kastade sig barnet på golvet för att hen inte fick det hen ville ha i affären? Få inte panik. Strunta i andras blickar och böj dig lugnt ner till barnets ögonhöjd.', title_vi = 'Ăn vạ ở siêu thị 🛒', body_vi = 'Bé nằm lăn ra sàn vì không được mua món mình muốn? Đừng hoảng. Mặc kệ ánh nhìn xung quanh, hãy bình tĩnh cúi xuống ngang tầm mắt bé.', title_zh = '超市里的崩溃 🛒', body_zh = '在商店没买到想要的东西就躺地上打滚？别慌。不用理会旁人的目光，平静地蹲下来和宝宝视线齐平。' WHERE id = '473def83-9d3b-4698-becd-a16f81aed11d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta la carga emocional 📝', body_es = '¿Ha sido un día difícil? Desahógate escribiendo el estrés de hoy en el Diario de ánimo. Todas las madres viven estas rabietas en público, no estás sola.', title_fr = 'Déposez votre charge émotionnelle 📝', body_fr = 'Journée difficile ? Videz-vous la tête en écrivant le stress du jour dans le Journal d''humeur. Toutes les mamans vivent ces crises en public, vous n''êtes pas seule.', title_hi = 'मन का बोझ उतारिए 📝', body_hi = 'मुश्किल दिन था? आज का तनाव मूड डायरी में लिखकर मन हल्का कीजिए। हर माँ सबके सामने होने वाले ऐसे नखरों से गुज़रती है, आप अकेली नहीं हैं।', title_id = 'Lepaskan beban emosi 📝', body_id = 'Hari yang berat? Lepaskan beban dengan menuliskan stres hari ini di Buku Harian Suasana Hati. Semua ibu pernah mengalami tantrum di depan umum seperti ini, Anda tidak sendirian.', title_ja = '心の荷物を下ろして 📝', body_ja = '大変な一日でしたか？「気分日記」に今日のストレスを書いて、気持ちを軽くしましょう。人前でのかんしゃくは、どのママも経験することです。あなたはひとりではありません。', title_ko = '마음의 짐을 내려놓아요 📝', body_ko = '힘든 하루였나요? 기분 일기에 오늘의 스트레스를 적으며 마음을 비워 보세요. 모든 엄마가 이런 순간을 겪어요. 혼자가 아니에요.', title_nl = 'Laat je emotionele last los 📝', body_nl = 'Was het een zware dag? Schrijf de stress van vandaag van je af in je Stemmingsdagboek. Alle moeders maken zulke buien in het openbaar mee, je staat er niet alleen voor.', title_pl = 'Zrzuć emocjonalny ciężar 📝', body_pl = 'To był trudny dzień? Wypisz dzisiejszy stres w Dzienniku nastroju i ulżyj sobie. Każda mama przeżywa takie kryzysy w miejscach publicznych, nie jesteś sama.', title_pt = 'Liberte a carga emocional 📝', body_pt = 'Foi um dia difícil? Desabafe escrevendo o stress de hoje no Diário de Humor. Todas as mães passam por estas crises em público, não está sozinha.', title_sv = 'Släpp den känslomässiga bördan 📝', body_sv = 'Har det varit en tuff dag? Skriv av dig dagens stress i Humördagboken. Alla mammor upplever sådana utbrott inför andra, du är inte ensam.', title_vi = 'Trút bỏ gánh nặng cảm xúc 📝', body_vi = 'Hôm nay vất vả quá? Hãy viết những căng thẳng hôm nay vào Nhật ký tâm trạng cho nhẹ lòng. Mẹ nào cũng từng trải qua những cơn ăn vạ nơi công cộng, mẹ không đơn độc đâu.', title_zh = '卸下情绪的包袱 📝', body_zh = '今天很难熬？把今天的压力写进心情日记，把心里清空。每个妈妈都经历过这种当众崩溃，你并不孤单。' WHERE id = 'fdbb311e-3b42-4723-986f-c65a632fb53e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = 'Tu peque se ha dormido. ¡Olvida las tareas de casa! Prepárate una infusión de melisa de Recetas saludables para mujeres, túmbate en el sofá y disfruta del silencio.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Il s''est endormi. Oubliez les tâches ménagères ! Préparez une tisane de mélisse des Recettes saines pour femmes, allongez-vous sur le canapé et savourez simplement le silence.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बच्चा सो गया। घर के काम भूल जाइए! महिलाओं के लिए सेहतमंद रेसिपी से लेमन बाम की चाय बनाइए, सोफ़े पर लेटिए और बस खामोशी का मज़ा लीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Si kecil sudah tidur. Lupakan pekerjaan rumah! Seduh teh lemon balm dari Resep Sehat untuk wanita, berbaring di sofa, dan nikmati keheningan.', title_ja = '自然のリラックス効果 🍃', body_ja = 'お子さんが眠りました。家事は忘れて！「女性のためのヘルシーレシピ」からレモンバームティーをいれて、ソファに横になり、静けさだけを味わいましょう。', title_ko = '자연의 진정제 🍃', body_ko = '아이가 잠들었어요. 집안일은 잊으세요! 여성을 위한 건강한 레시피에서 레몬밤 차를 우려 소파에 누워 오직 고요함만 즐기세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Je kindje slaapt. Vergeet het huishouden! Zet citroenmelissethee uit Gezonde recepten voor vrouwen, ga op de bank liggen en geniet gewoon van de stilte.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'Maluch zasnął. Zapomnij o obowiązkach! Zaparz melisę ze Zdrowych przepisów dla kobiet, połóż się na kanapie i po prostu delektuj się ciszą.', title_pt = 'Calmante natural 🍃', body_pt = 'Ele adormeceu. Esqueça as tarefas da casa! Prepare um chá de erva-cidreira das Receitas Saudáveis para Mulheres, deite-se no sofá e saboreie apenas o silêncio.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Barnet sover. Glöm hushållssysslorna! Brygg citronmelissate från Hälsosamma recept för kvinnor, lägg dig på soffan och njut bara av tystnaden.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Bé đã ngủ. Quên việc nhà đi! Hãy pha trà tía tô đất từ Công thức lành mạnh cho phụ nữ, nằm dài trên sofa và tận hưởng sự yên tĩnh.', title_zh = '天然的镇静剂 🍃', body_zh = '孩子睡着了。忘掉家务吧！从女性健康食谱里泡一杯香蜂草茶，躺在沙发上，好好享受这份安静。' WHERE id = '34d9fbb9-7747-4964-9067-399afa7f0a7c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de vitamina C 🍊', body_es = 'Sus defensas tienen que estar fuertes. Calcula con el Seguimiento de tomas si hoy ha tomado suficiente vitamina C y llena su menú de color.', title_fr = 'Bouclier vitamine C 🍊', body_fr = 'Son immunité doit être solide. Calculez avec le Suivi des repas s''il a eu assez de vitamine C aujourd''hui et mettez de la couleur dans son menu.', title_hi = 'विटामिन C की ढाल 🍊', body_hi = 'इम्युनिटी मज़बूत होनी चाहिए। फ़ीडिंग ट्रैकर से गिनिए कि आज उसे पर्याप्त विटामिन C मिला या नहीं, और मेन्यू को रंग-बिरंगा बनाइए।', title_id = 'Perisai vitamin C 🍊', body_id = 'Daya tahan tubuh harus kuat. Hitung dengan alat Pemantau Nutrisi apakah hari ini ia sudah cukup mendapat vitamin C, dan buat menunya lebih berwarna.', title_ja = 'ビタミンCのシールド 🍊', body_ja = '免疫を強くしておくことが大切です。「栄養管理ツール」で、今日ビタミンCを十分とれたか計算して、メニューをカラフルにしましょう。', title_ko = '비타민 C 방패 🍊', body_ko = '면역력은 튼튼해야 해요. 수유 기록 도구로 오늘 비타민 C를 충분히 섭취했는지 계산하고 식단을 알록달록하게 꾸며 보세요.', title_nl = 'Vitamine C-schild 🍊', body_nl = 'Zijn afweer moet sterk zijn. Bereken met de Voedingstracker of hij vandaag genoeg vitamine C heeft gehad en maak zijn menu kleurrijk.', title_pl = 'Tarcza z witaminy C 🍊', body_pl = 'Odporność musi być silna. Oblicz w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco witaminy C, i dodaj menu trochę kolorów.', title_pt = 'Escudo de vitamina C 🍊', body_pt = 'A imunidade tem de ser forte. Calcule com o Registo de Alimentação se hoje recebeu vitamina C suficiente e dê mais cor à ementa.', title_sv = 'C-vitaminskölden 🍊', body_sv = 'Immunförsvaret behöver vara starkt. Räkna ut med Matningskoll om barnet fått tillräckligt med C-vitamin i dag och gör menyn mer färgglad.', title_vi = 'Lá chắn vitamin C 🍊', body_vi = 'Hệ miễn dịch cần khỏe mạnh. Hãy tính bằng Theo dõi cữ bú xem hôm nay bé đã nhận đủ vitamin C chưa và làm thực đơn thêm nhiều màu sắc.', title_zh = '维生素C护盾 🍊', body_zh = '免疫力要强。用喂养记录工具算一算宝宝今天是否摄入了足够的维生素C，让菜单更丰富多彩。' WHERE id = 'e79393de-a250-4c25-b9a8-93a1bc3692aa' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de vestirse 👗', body_es = '¿Ha empezado la tozudez del «¡No quiero esta camiseta!»? Aprende con Anacan AI cómo reducir las batallas de ropa por la mañana y darle libertad para elegir.', title_fr = 'La bataille de l''habillage 👗', body_fr = 'La période « Je ne veux pas ce t-shirt ! » a commencé ? Découvrez avec Anacan AI comment réduire les crises d''habillage du matin et lui laisser le libre choix.', title_hi = 'कपड़े पहनने की जंग 👗', body_hi = '''यह कमीज़ नहीं चाहिए!'' वाली ज़िद शुरू हो गई? सुबह कपड़ों के झगड़े कम करने और उसे अपनी पसंद चुनने का मौका देने के तरीके Anacan AI से जानिए।', title_id = 'Perang berpakaian 👗', body_id = 'Aku tidak mau baju ini! Masa keras kepala sudah dimulai? Pelajari dari Anacan AI cara mengurangi drama berpakaian di pagi hari dan memberinya hak memilih.', title_ja = '着替えの攻防 👗', body_ja = '「このシャツはいや！」というこだわりが始まりましたか？朝の着替えのかんしゃくを減らし、自分で選ぶ機会をあげる方法を、Anacan AIで学びましょう。', title_ko = '옷 입기 전쟁 👗', body_ko = '''이 옷 싫어!'' 고집이 시작됐나요? 아침 옷 입기 전쟁을 줄이고 스스로 고를 기회를 주는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Strijd om het aankleden 👗', body_nl = 'Begint het ik wil dit shirt niet!-gedoe? Leer bij Anacan AI hoe je de ochtendstrijd om kleding vermindert en hem vrij laat kiezen.', title_pl = 'Walka o ubieranie 👗', body_pl = 'Zaczął się upór w stylu „Nie chcę tej koszulki!”? Dowiedz się od Anacan AI, jak ograniczyć poranne kryzysy przy ubieraniu i dać mu prawo do samodzielnego wyboru.', title_pt = 'A batalha da roupa 👗', body_pt = 'Começou a teimosia do "Não quero esta camisola!"? Aprenda com o Anacan AI como reduzir as crises da roupa de manhã e dar-lhe liberdade de escolha.', title_sv = 'Kampen om kläderna 👗', body_sv = 'Har envisheten ”Jag vill inte ha den här tröjan!” börjat? Lär dig av Anacan AI hur du kan minska morgonens klädbråk och ge barnet frihet att välja.', title_vi = 'Cuộc chiến mặc quần áo 👗', body_vi = 'Bé bắt đầu bướng bỉnh "Con không thích áo này!"? Hãy học từ Anacan AI cách giảm những cuộc chiến quần áo buổi sáng và cho bé quyền tự chọn.', title_zh = '穿衣大战 👗', body_zh = '开始“我不要这件衣服！”的倔强了？向Anacan AI了解如何减少早上穿衣时的冲突，并给宝宝自由选择的权利。' WHERE id = 'f29d2f2b-6e38-44f2-9d6b-467c0c3431e7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de independencia 🥣', body_es = '¿No te da la cuchara? Pon el temporizador de tomas y analiza cuánto dura esta prueba de independencia. A la comida derramada, solo sonríele.', title_fr = 'En quête d''autonomie 🥣', body_fr = 'Il refuse de vous laisser la cuillère ? Lancez le minuteur des repas et analysez combien de temps dure ce test d''autonomie. Et devant la nourriture renversée, souriez simplement.', title_hi = 'आज़ादी की तलाश 🥣', body_hi = 'चम्मच आपको नहीं देता? फ़ीडिंग टाइमर चालू कीजिए और देखिए कि आज़ादी की यह कोशिश कितना समय लेती है। बिखरे खाने पर बस मुस्कुरा दीजिए।', title_id = 'Mencari kemandirian 🥣', body_id = 'Tidak mau memberikan sendoknya? Nyalakan Timer Makan dan lihat berapa lama ujian kemandirian ini berlangsung. Untuk makanan yang berceceran, cukup tersenyum saja.', title_ja = '自立への挑戦 🥣', body_ja = 'スプーンを渡してくれない？食事タイマーをオンにして、この自立の挑戦にどれくらい時間がかかるか分析しましょう。こぼれた食べ物には、ただほほえんで。', title_ko = '스스로 하고 싶어요 🥣', body_ko = '숟가락을 넘겨주지 않나요? 수유 타이머를 켜고 이 자립 도전이 얼마나 걸리는지 살펴보세요. 흘린 음식에는 그냥 웃어 주세요.', title_nl = 'Op zoek naar zelfstandigheid 🥣', body_nl = 'Geeft hij de lepel niet aan je? Zet de Voedingstimer aan en kijk hoe lang deze zelfstandigheidstest duurt. Om het gemorste eten kun je gewoon glimlachen.', title_pl = 'W poszukiwaniu samodzielności 🥣', body_pl = 'Nie oddaje ci łyżki? Włącz timer karmienia i sprawdź, ile trwa ta próba samodzielności. Do rozsypanego jedzenia po prostu się uśmiechnij.', title_pt = 'Em busca de independência 🥣', body_pt = 'Não lhe dá a colher? Ligue o temporizador de alimentação e analise quanto tempo demora este teste de independência. À comida entornada, responda só com um sorriso.', title_sv = 'Längtan efter självständighet 🥣', body_sv = 'Vill barnet inte ge dig skeden? Starta matningstimern och analysera hur lång tid självständighetsförsöket tar. Le bara åt maten som spills.', title_vi = 'Hành trình tự lập 🥣', body_vi = 'Bé không đưa thìa cho mẹ? Hãy bật Hẹn giờ cho bú để xem thử thách tự lập này mất bao lâu. Thức ăn vương vãi thì cứ mỉm cười thôi.', title_zh = '追求自主 🥣', body_zh = '不肯把勺子给你？打开喂养计时器，分析这场自主挑战花了多长时间。撒了一地的饭，笑一笑就好。' WHERE id = '2a640acf-5bf6-44d4-b56f-00e902c2ddd2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Miedo a la separación? 🌌', body_es = '¿Llora en cuanto sales de la habitación? Pon el sonido del vientre materno (latido del corazón) de Ruido blanco y devuélvele aquella cálida sensación de seguridad.', title_fr = 'Peur de la séparation ? 🌌', body_fr = 'Il pleure dès que vous quittez la pièce ? Lancez le son du ventre maternel (battements de cœur) des Bruits blancs pour lui rendre ce doux sentiment de sécurité d''autrefois.', title_hi = 'अलग होने का डर? 🌌', body_hi = 'आप कमरे से निकलते ही वह रोने लगता है? व्हाइट नॉइज़ में गर्भ की आवाज़ (दिल की धड़कन) चलाकर उसे वही पुरानी गर्माहट और सुरक्षा का एहसास दीजिए।', title_id = 'Takut berpisah? 🌌', body_id = 'Menangis begitu Anda keluar kamar? Putar suara rahim (detak jantung) dari Suara Putih dan beri ia rasa aman yang hangat dan akrab.', title_ja = '離れるのがこわい？🌌', body_ja = '部屋を出たとたん、あとを追って泣きますか？「ホワイトノイズ」の胎内の音（心臓の音）を流して、なつかしい温かな安心感を届けましょう。', title_ko = '분리 불안? 🌌', body_ko = '방을 나가자마자 울며 따라오나요? 백색소음에서 엄마 배 속 소리(심장 박동)를 틀어 익숙하고 따뜻한 안정감을 선물하세요.', title_nl = 'Verlatingsangst? 🌌', body_nl = 'Huilt hij zodra je de kamer uit gaat? Zet het baarmoedergeluid (hartslag) uit Witte ruis aan en geef hem dat oude, warme gevoel van veiligheid.', title_pl = 'Lęk przed rozstaniem? 🌌', body_pl = 'Płacze, gdy tylko wychodzisz z pokoju? Włącz w Białym szumie odgłosy z brzucha mamy (bicie serca) i daj mu znajome, ciepłe poczucie bezpieczeństwa.', title_pt = 'Medo da separação? 🌌', body_pt = 'Mal sai do quarto, chora atrás de si? Ligue no Ruído Branco o som do útero materno (batimento cardíaco) e dê-lhe aquela antiga sensação quente de segurança.', title_sv = 'Separationsångest? 🌌', body_sv = 'Gråter barnet så fort du lämnar rummet? Sätt på ljudet från livmodern (hjärtslag) i Vitt brus och ge barnet den gamla varma känslan av trygghet.', title_vi = 'Sợ phải xa mẹ? 🌌', body_vi = 'Mẹ vừa ra khỏi phòng là bé khóc theo? Hãy bật âm thanh trong bụng mẹ (tiếng tim đập) trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn ấm áp quen thuộc.', title_zh = '分离焦虑？🌌', body_zh = '你一离开房间就在后面哭？打开白噪音里的子宫声（心跳声），给宝宝熟悉而温暖的安全感。' WHERE id = 'cb94164a-0ea2-471c-9c17-a09778ea707c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de lavarse los dientes 🪥', body_es = '¿Cierra la boca en cuanto ve el cepillo? Mira en Productos recomendados cepillos musicales o de dedo y convierte esta rutina de higiene en un juego divertido.', title_fr = 'La bataille du brossage de dents 🪥', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse ? Regardez dans les Produits recommandés les brosses musicales ou à doigt pour transformer ce rituel d''hygiène en jeu amusant.', title_hi = 'दाँत ब्रश करने की लड़ाई 🪥', body_hi = 'ब्रश देखते ही मुँह बंद कर लेता है? सुझाए गए प्रोडक्ट में म्यूज़िकल या फ़िंगर ब्रश देखिए और सफ़ाई के इस रूटीन को मज़ेदार खेल बना दीजिए।', title_id = 'Drama sikat gigi 🪥', body_id = 'Langsung mengatupkan mulut begitu melihat sikat gigi? Lihat sikat gigi bermusik atau sikat jari di Produk Rekomendasi dan jadikan rutinitas kebersihan ini permainan seru.', title_ja = '歯みがきバトル 🪥', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？「おすすめ商品」で音楽付きや指にはめるタイプの歯ブラシをチェックして、この歯みがきの習慣を楽しい遊びに変えましょう。', title_ko = '양치 전쟁 🪥', body_ko = '칫솔만 보면 입을 꾹 다무나요? 추천 제품에서 음악이 나오는 칫솔이나 손가락 칫솔을 살펴보고 양치 습관을 재미있는 놀이로 바꿔 보세요.', title_nl = 'Gedoe met tandenpoetsen 🪥', body_nl = 'Klemt hij zijn mond dicht zodra hij de tandenborstel ziet? Bekijk in Aanbevolen producten muzikale of vingertandenborstels en maak van deze verzorging een leuk spel.', title_pl = 'Bitwa o mycie ząbków 🪥', body_pl = 'Zaciska buzię na widok szczoteczki? Zajrzyj w Polecanych produktach do grających szczoteczek lub szczoteczek na palec i zamień tę higieniczną rutynę w zabawę.', title_pt = 'A luta da escova de dentes 🪥', body_pt = 'Mal vê a escova, fecha a boca? Veja nos Produtos Recomendados escovas musicais ou de dedo e transforme esta rotina de higiene num jogo divertido.', title_sv = 'Kampen om tandborstningen 🪥', body_sv = 'Stänger barnet munnen så fort tandborsten syns? Titta på tandborstar med musik eller fingertandborstar i Rekommenderade produkter och gör hygienrutinen till en rolig lek.', title_vi = 'Cuộc chiến đánh răng 🪥', body_vi = 'Vừa thấy bàn chải là bé mím chặt miệng? Hãy xem các loại bàn chải có nhạc hoặc bàn chải xỏ ngón trong Sản phẩm gợi ý để biến thói quen vệ sinh này thành trò chơi vui nhộn.', title_zh = '刷牙大作战 🪥', body_zh = '一看到牙刷就紧闭小嘴？去推荐商品看看音乐牙刷或指套牙刷，把这项卫生习惯变成有趣的游戏。' WHERE id = 'd3ae908a-552f-4504-a171-436173eaeceb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Date un respiro 🧘‍♀️', body_es = '¿Hoy todo ha salido al revés? Escribe tu voz interior en el Diario de ánimo, perdónate, respira hondo y descansa.', title_fr = 'Soyez indulgente avec vous-même 🧘‍♀️', body_fr = 'Tout est allé de travers aujourd''hui ? Confiez votre voix intérieure au Journal d''humeur, pardonnez-vous, respirez profondément et reposez-vous.', title_hi = 'खुद पर मेहरबानी कीजिए 🧘‍♀️', body_hi = 'आज सब कुछ उल्टा हुआ? मूड डायरी में अपने मन की बात लिखिए, खुद को माफ़ कीजिए, गहरी साँस लीजिए और आराम कीजिए।', title_id = 'Berbaik hatilah pada diri sendiri 🧘‍♀️', body_id = 'Hari ini semuanya serba salah? Tulis suara hati Anda di Buku Harian Suasana Hati, maafkan diri sendiri, tarik napas dalam-dalam, dan beristirahatlah.', title_ja = '自分にやさしく 🧘‍♀️', body_ja = '今日は何もかもうまくいかなかった？「気分日記」に心の声を書いて、自分を許し、深呼吸をして休みましょう。', title_ko = '나에게 너그러워지세요 🧘‍♀️', body_ko = '오늘 모든 게 꼬였나요? 기분 일기에 속마음을 적고, 스스로를 용서하고, 깊게 숨을 쉬며 쉬세요.', title_nl = 'Wees lief voor jezelf 🧘‍♀️', body_nl = 'Ging vandaag alles mis? Schrijf je innerlijke stem op in je Stemmingsdagboek, vergeef jezelf, adem diep in en rust uit.', title_pl = 'Bądź dla siebie łaskawa 🧘‍♀️', body_pl = 'Dziś wszystko poszło nie tak? Zapisz swój wewnętrzny głos w Dzienniku nastroju, wybacz sobie, weź głęboki oddech i odpocznij.', title_pt = 'Seja gentil consigo 🧘‍♀️', body_pt = 'Hoje correu tudo ao contrário? Escreva a sua voz interior no Diário de Humor, perdoe-se, respire fundo e descanse.', title_sv = 'Var snäll mot dig själv 🧘‍♀️', body_sv = 'Gick allt snett i dag? Skriv ner dina tankar i Humördagboken, förlåt dig själv, andas djupt och vila.', title_vi = 'Hãy chiều chuộng bản thân 🧘‍♀️', body_vi = 'Hôm nay mọi thứ đều trục trặc? Hãy viết tiếng lòng vào Nhật ký tâm trạng, tha thứ cho bản thân, hít thở sâu và nghỉ ngơi.', title_zh = '善待自己 🧘‍♀️', body_zh = '今天一切都不顺？把内心的声音写进心情日记，原谅自己，深呼吸，好好休息。' WHERE id = '4932b8a8-d024-498c-ba06-d790b59bc198' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Su vocabulario crece 🗣️', body_es = '¿Cada vez dice más frases de dos palabras? Pregunta ya a Anacan AI cómo apoyar este gran desarrollo del lenguaje y cómo conversar con tu peque.', title_fr = 'Son vocabulaire s''enrichit 🗣️', body_fr = 'Les phrases de deux mots se multiplient ? Demandez tout de suite à Anacan AI comment soutenir ce formidable développement du langage et dialoguer avec lui.', title_hi = 'शब्द भंडार बढ़ रहा है 🗣️', body_hi = 'दो शब्दों वाले वाक्य बढ़ रहे हैं? भाषा के इस शानदार विकास में उसका साथ कैसे दें और उससे बातचीत कैसे करें, यह तुरंत Anacan AI से पूछिए।', title_id = 'Kosakata makin bertambah 🗣️', body_id = 'Kalimat dua katanya makin banyak? Segera tanyakan kepada Anacan AI cara mendukung perkembangan bahasa yang luar biasa ini dan mengajaknya berdialog.', title_ja = '語彙が広がっていく 🗣️', body_ja = '2語文が増えてきましたか？このすばらしい言葉の発達をどう応援し、どう会話をすればいいか、すぐにAnacan AIに聞いてみましょう。', title_ko = '어휘가 늘어나요 🗣️', body_ko = '두 단어 문장이 늘고 있나요? 이 멋진 언어 발달을 어떻게 돕고 대화를 이어 가면 좋을지 Anacan AI에게 바로 물어보세요.', title_nl = 'Zijn woordenschat groeit 🗣️', body_nl = 'Komen er meer zinnetjes van twee woorden? Vraag Anacan AI meteen hoe je deze geweldige taalontwikkeling steunt en een gesprekje met hem voert.', title_pl = 'Słownictwo się poszerza 🗣️', body_pl = 'Coraz więcej zdań z dwóch słów? Od razu zapytaj Anacan AI, jak wspierać ten wspaniały rozwój mowy i jak z nim rozmawiać.', title_pt = 'O vocabulário está a crescer 🗣️', body_pt = 'As frases de duas palavras estão a aumentar? Pergunte já ao Anacan AI como apoiar este desenvolvimento fantástico da linguagem e como conversar com ele.', title_sv = 'Ordförrådet växer 🗣️', body_sv = 'Blir det fler meningar med två ord? Fråga Anacan AI direkt hur du kan stötta denna fantastiska språkutveckling och föra samtal med barnet.', title_vi = 'Vốn từ đang mở rộng 🗣️', body_vi = 'Bé nói câu hai từ ngày càng nhiều? Hãy hỏi ngay Anacan AI cách hỗ trợ sự phát triển ngôn ngữ tuyệt vời này và trò chuyện với bé.', title_zh = '词汇量在扩大 🗣️', body_zh = '两个词的句子越来越多了？马上问问Anacan AI，该如何支持这次了不起的语言发展，怎样和宝宝对话。' WHERE id = 'ed014436-2469-48a6-b579-7bce93de1ae7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El color de la caca 💩', body_es = '¡Anótalo al cambiar el pañal! Usa el Seguimiento de tomas para controlar el equilibrio de líquidos y fibra y prevenir el estreñimiento.', title_fr = 'La couleur des selles 💩', body_fr = 'Prenez note en changeant la couche ! Utilisez le Suivi des repas pour surveiller l''équilibre liquides/fibres et prévenir la constipation.', title_hi = 'पॉटी का रंग 💩', body_hi = 'डायपर बदलते समय दर्ज कीजिए! तरल और फ़ाइबर के संतुलन पर नज़र रखकर कब्ज़ से बचने के लिए फ़ीडिंग ट्रैकर का इस्तेमाल कीजिए।', title_id = 'Warna kotorannya 💩', body_id = 'Catat saat mengganti popok! Gunakan alat Pemantau Nutrisi untuk memantau keseimbangan cairan dan serat demi mencegah sembelit.', title_ja = 'うんちの色 💩', body_ja = 'おむつ替えのときに記録しましょう！水分と食物繊維のバランスを見守って便秘を防ぐために、「栄養管理ツール」を活用しましょう。', title_ko = '변의 색깔 💩', body_ko = '기저귀를 갈 때 기록하세요! 수유 기록 도구로 수분과 섬유질 균형을 살펴 변비를 예방하세요.', title_nl = 'De kleur van de ontlasting 💩', body_nl = 'Let op bij het verschonen! Gebruik de Voedingstracker om de balans van vocht en vezels te volgen en verstopping te voorkomen.', title_pl = 'Kolor kupki 💩', body_pl = 'Notuj przy zmianie pieluszki! Śledź bilans płynów i błonnika w narzędziu do śledzenia karmienia, by zapobiegać zaparciom.', title_pt = 'A cor das fezes 💩', body_pt = 'Registe-o ao mudar a fralda! Recorra ao Registo de Alimentação para acompanhar o equilíbrio de líquidos e fibra e prevenir a prisão de ventre.', title_sv = 'Avföringens färg 💩', body_sv = 'Anteckna när du byter blöja! Använd Matningskoll för att följa balansen mellan vätska och fibrer och förebygga förstoppning.', title_vi = 'Màu sắc của phân 💩', body_vi = 'Hãy ghi lại khi thay tã! Dùng công cụ Theo dõi cữ bú để theo dõi cân bằng nước và chất xơ, giúp phòng ngừa táo bón.', title_zh = '大便的颜色 💩', body_zh = '换尿布时记下来！用喂养记录工具跟踪水分和纤维的平衡，预防便秘。' WHERE id = 'ed579060-f78c-4890-b8e4-2bb0c7729792' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siesta al aire libre 🌳', body_es = '¿No consigue dormir en casa? Busca en Lugares para mamás un parque tranquilo y con árboles. El aire fresco le abrirá el apetito y le ayudará a dormir.', title_fr = 'Sieste en plein air 🌳', body_fr = 'Il n''arrive pas à dormir à la maison ? Trouvez un parc calme et arboré dans les Lieux adaptés aux mamans. Le grand air lui ouvrira l''appétit et l''aidera à dormir.', title_hi = 'खुली हवा में नींद 🌳', body_hi = 'घर पर सो नहीं पाता? माँ के लिए अनुकूल जगहें में शांत, पेड़ों वाला पार्क ढूँढिए। ताज़ी हवा से उसकी भूख भी खुलेगी और नींद भी अच्छी आएगी।', title_id = 'Tidur di udara terbuka 🌳', body_id = 'Tidak bisa tidur di rumah? Temukan taman yang tenang dan rindang di Tempat Ramah Ibu. Udara segar akan membuka nafsu makan sekaligus membuatnya mengantuk.', title_ja = '外でお昼寝 🌳', body_ja = '家ではなかなか眠れない？「ママにやさしいスポット」で、静かで木の多い公園を見つけましょう。新鮮な空気で、食欲も眠りもよくなります。', title_ko = '바깥에서 낮잠 🌳', body_ko = '집에서 잠을 못 자나요? 엄마 친화 장소에서 조용하고 나무가 많은 공원을 찾아보세요. 맑은 공기가 입맛도 잠도 살려 줄 거예요.', title_nl = 'Slapen in de buitenlucht 🌳', body_nl = 'Kan hij thuis niet slapen? Zoek in Mamavriendelijke plekken een rustig park met veel bomen. Frisse lucht geeft hem zowel trek als slaap.', title_pl = 'Sen na świeżym powietrzu 🌳', body_pl = 'Nie może zasnąć w domu? Znajdź w Miejscach przyjaznych mamom cichy park pełen drzew. Świeże powietrze poprawi i apetyt, i sen.', title_pt = 'Sesta ao ar livre 🌳', body_pt = 'Não consegue dormir em casa? Encontre nos Locais Amigos das Mães um parque calmo e arborizado. O ar puro vai abrir-lhe o apetite e o sono.', title_sv = 'Sova utomhus 🌳', body_sv = 'Kan barnet inte sova hemma? Hitta en lugn park med träd i Mammavänliga platser. Frisk luft ger både bättre aptit och bättre sömn.', title_vi = 'Ngủ ngoài trời 🌳', body_vi = 'Bé không ngủ được trong nhà? Hãy tìm một công viên yên tĩnh, nhiều cây xanh trong Địa điểm thân thiện với mẹ. Không khí trong lành giúp bé ăn ngon và ngủ ngon hơn.', title_zh = '在户外睡觉 🌳', body_zh = '在家睡不着？在妈妈友好场所里找一个安静、树木多的公园。新鲜空气会让宝宝胃口好、睡得香。' WHERE id = '15f9bb81-a16f-4753-a3f5-a2b604b16a46' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos ⏱️', body_es = '¡Pon el temporizador de sueño! Analiza enseguida con el gráfico de estadísticas si se trata de terrores nocturnos o de una regresión del sueño.', title_fr = 'Réveils nocturnes ⏱️', body_fr = 'Lancez le minuteur de sommeil ! Analysez tout de suite sur son graphique statistique s''il s''agit de terreurs nocturnes ou d''une régression du sommeil.', title_hi = 'रात में जागना ⏱️', body_hi = 'स्लीप टाइमर चालू कीजिए! टाइमर के आँकड़ों वाले चार्ट से तुरंत समझिए कि कहीं यह नाइट टेरर या स्लीप रिग्रेशन तो नहीं।', title_id = 'Terbangun di malam hari ⏱️', body_id = 'Nyalakan Timer Tidur! Segera analisis lewat grafik statistik timer apakah ini teror malam atau regresi tidur.', title_ja = '夜中に起きる ⏱️', body_ja = '睡眠タイマーをオンにしましょう！夜驚症なのか睡眠退行なのか、タイマーの統計グラフですぐに分析しましょう。', title_ko = '밤에 깨요 ⏱️', body_ko = '수면 타이머를 켜세요! 야경증인지 수면 퇴행인지 타이머의 통계 그래프로 바로 분석해 보세요.', title_nl = 'Nachtelijk wakker worden ⏱️', body_nl = 'Zet de Slaaptimer aan! Analyseer meteen in de statistiekgrafiek van de timer of het om nachtangst of een slaapregressie gaat.', title_pl = 'Nocne pobudki ⏱️', body_pl = 'Włącz timer snu! Na wykresie statystyk od razu sprawdzisz, czy to lęki nocne, czy regres snu.', title_pt = 'Despertares noturnos ⏱️', body_pt = 'Ligue o temporizador de sono! Analise já no gráfico de estatísticas do temporizador se se trata de terrores noturnos ou de uma regressão do sono.', title_sv = 'Nattliga uppvaknanden ⏱️', body_sv = 'Starta sömntimern! Analysera direkt med timerns statistikgraf om det kan vara nattskräck eller sömnregression.', title_vi = 'Thức giấc ban đêm ⏱️', body_vi = 'Hãy bật Bộ hẹn giờ ngủ! Phân tích ngay biểu đồ thống kê để xem bé có bị hoảng sợ ban đêm hay thoái lui giấc ngủ không.', title_zh = '夜间醒来 ⏱️', body_zh = '打开睡眠计时器！从计时器的统计图表中马上分析是夜惊还是睡眠倒退。' WHERE id = '1e63b6e0-14e2-4999-89f7-2f0db3539031' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hace muecas o se ríe a carcajadas al mirarte? Decora este dulce momento con las pegatinas de la Sesión de fotos del bebé y añádelo al álbum como recuerdo para siempre.', body_fr = 'Il fait des grimaces ou éclate de rire en vous regardant ? Décorez ce mignon moment avec les stickers de la Séance photo bébé et ajoutez-le à l''album comme souvenir pour toujours.', body_hi = 'मुँह बनाता है या आपको देखकर ठहाके लगाता है? इस प्यारे पल को बेबी फ़ोटोशूट के स्टिकर से सजाकर एल्बम में हमेशा की याद के रूप में जोड़िए।', body_id = 'Ia memasang wajah lucu atau tertawa terbahak-bahak sambil menatap Anda? Hiasi momen manis ini dengan stiker dari Sesi Foto Bayi dan tambahkan ke album sebagai kenangan abadi.', body_ja = '顔をしかめたり、あなたを見て大笑いしたりしていますか？このかわいい瞬間を「ベビーフォトセッション」のステッカーで飾って、永遠の思い出としてアルバムに追加しましょう。', body_ko = '얼굴을 찡그리거나 엄마를 보며 깔깔 웃나요? 이 사랑스러운 순간을 아기 사진 촬영의 스티커로 꾸며 앨범에 영원한 추억으로 남기세요.', body_nl = 'Trekt hij een zuur gezicht of schatert hij als hij naar je kijkt? Versier dit lieve moment met stickers in Babyfotoshoot en zet het als blijvende herinnering in het album.', body_pl = 'Robi miny albo patrzy na ciebie i zanosi się śmiechem? Ozdób tę słodką chwilę naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu na wieczną pamiątkę.', body_pt = 'Faz caretas ou ri-se às gargalhadas a olhar para si? Decore este momento doce com os autocolantes da Sessão Fotográfica do Bebé e adicione-o ao álbum como recordação para sempre.', body_sv = 'Gör barnet grimaser eller skrattar högt när hen tittar på dig? Dekorera det söta ögonblicket med klistermärken i Babyfotografering och spara det i albumet som ett minne för alltid.', body_vi = 'Bé nhăn mặt làm trò hay nhìn mẹ cười giòn tan? Hãy trang trí khoảnh khắc đáng yêu này bằng sticker trong Chụp ảnh cho bé và lưu vào album làm kỷ niệm mãi mãi.', body_zh = '做鬼脸，还是看着你哈哈大笑？用宝宝写真里的贴纸装饰这个可爱的瞬间，加进相册作为永远的纪念。' WHERE id = '2097babe-f9a8-45d7-927c-24d3ef08f38a' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder de la monotonía 🎶', body_es = 'Después de un día ruidoso, un silencio repentino le asusta. Pon el sonido del secador de Ruido blanco y crea una sensación de seguridad para dormir.', title_fr = 'La force de la monotonie 🎶', body_fr = 'Après une journée bruyante, le silence soudain lui fait peur. Lancez le bruit de sèche-cheveux des Bruits blancs pour créer un sentiment de sécurité au moment de dormir.', title_hi = 'एक जैसी आवाज़ की ताकत 🎶', body_hi = 'शोर भरे दिन के बाद अचानक की खामोशी उसे डराती है। व्हाइट नॉइज़ में हेयर ड्रायर की आवाज़ चलाकर नींद के माहौल में सुरक्षा का एहसास दीजिए।', title_id = 'Kekuatan suara monoton 🎶', body_id = 'Setelah hari yang bising, hening yang tiba-tiba bisa membuatnya takut. Putar suara pengering rambut dari Suara Putih dan ciptakan rasa aman saat tidur.', title_ja = '単調な音の力 🎶', body_ja = 'にぎやかな一日のあとの急な静けさは、お子さんを不安にさせます。「ホワイトノイズ」のドライヤーの音を流して、眠りの環境に安心感をつくりましょう。', title_ko = '단조로운 소리의 힘 🎶', body_ko = '시끄러운 하루 뒤의 갑작스러운 정적은 아이를 놀라게 해요. 백색소음에서 헤어드라이어 소리를 틀어 수면 환경에 안정감을 만들어 주세요.', title_nl = 'De kracht van eentonigheid 🎶', body_nl = 'Na een lawaaierige dag kan plotselinge stilte hem laten schrikken. Zet het föhngeluid uit Witte ruis aan en geef zijn slaapomgeving een veilig gevoel.', title_pl = 'Moc monotonii 🎶', body_pl = 'Nagła cisza po głośnym dniu go niepokoi. Włącz odgłos suszarki z Białego szumu i daj mu poczucie bezpieczeństwa podczas snu.', title_pt = 'A força da monotonia 🎶', body_pt = 'Depois de um dia barulhento, o silêncio repentino assusta-o. Ligue o som do secador de cabelo do Ruído Branco e crie uma sensação de segurança no ambiente de sono.', title_sv = 'Kraften i monotona ljud 🎶', body_sv = 'Efter en bullrig dag kan plötslig tystnad skrämma barnet. Sätt på hårtorksljud från Vitt brus och skapa en känsla av trygghet i sömnmiljön.', title_vi = 'Sức mạnh của âm thanh đều đều 🎶', body_vi = 'Sau một ngày ồn ào, sự im lặng đột ngột có thể khiến bé sợ. Hãy bật tiếng máy sấy tóc trong Tiếng ồn trắng để tạo cảm giác an toàn cho giấc ngủ.', title_zh = '单调声音的力量 🎶', body_zh = '吵闹的一天之后，突然的安静会让宝宝害怕。打开白噪音里的吹风机声，在睡眠环境中营造安全感。' WHERE id = '3d45eb72-a379-4b0c-95b5-43a9f90cd232' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batería de mamá 🔋', body_es = '¿Te has quedado sin energía? ¡No corras a por dulces! Prepara en Recetas saludables para mujeres un batido de crema de cacahuete con proteínas que da fuerza al instante.', title_fr = 'La batterie de maman 🔋', body_fr = 'Plus d''énergie ? Ne vous jetez pas sur le sucre ! Préparez un smoothie protéiné au beurre de cacahuète, énergisant en un instant, avec les Recettes saines pour femmes.', title_hi = 'माँ की बैटरी 🔋', body_hi = 'ऊर्जा खत्म हो गई? मिठाई की ओर मत भागिए! महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाली, प्रोटीन से भरपूर पीनट बटर स्मूदी बनाइए।', title_id = 'Baterai Bunda 🔋', body_id = 'Energi Anda habis? Jangan lari ke manisan! Buat smoothie selai kacang kaya protein yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = 'ママのバッテリー 🔋', body_ja = 'エネルギー切れですか？甘いものに頼らないで！「女性のためのヘルシーレシピ」から、すぐに元気が出るたんぱく質たっぷりのピーナッツバタースムージーをつくりましょう。', title_ko = '엄마의 배터리 🔋', body_ko = '에너지가 다 떨어졌나요? 단 음식으로 달려가지 마세요! 여성을 위한 건강한 레시피에서 바로 힘이 나는 단백질 땅콩버터 스무디를 만들어 보세요.', title_nl = 'Mama''s batterij 🔋', body_nl = 'Is je energie op? Grijp niet naar snoep! Maak uit Gezonde recepten voor vrouwen een eiwitrijke smoothie met pindakaas die je meteen kracht geeft.', title_pl = 'Bateria mamy 🔋', body_pl = 'Skończyła ci się energia? Nie sięgaj po słodycze! Przygotuj ze Zdrowych przepisów dla kobiet białkowe smoothie z masłem orzechowym, które od razu doda ci sił.', title_pt = 'A bateria da mãe 🔋', body_pt = 'Ficou sem energia? Não corra para os doces! Prepare nas Receitas Saudáveis para Mulheres um batido de manteiga de amendoim rico em proteína que dá força na hora.', title_sv = 'Mammas batteri 🔋', body_sv = 'Har energin tagit slut? Rusa inte efter godis! Gör en proteinrik smoothie med jordnötssmör som ger kraft direkt från Hälsosamma recept för kvinnor.', title_vi = 'Pin năng lượng của mẹ 🔋', body_vi = 'Hết năng lượng rồi? Đừng tìm đến đồ ngọt! Hãy làm ly sinh tố bơ đậu phộng giàu đạm, tiếp sức tức thì từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的电池 🔋', body_zh = '精力耗尽了？别急着吃甜食！从女性健康食谱里做一杯马上补充能量、富含蛋白质的花生酱奶昔。' WHERE id = 'af588f6b-bdb1-4b34-b380-81bc42d5db3f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿La ropa vuelve a quedarle pequeña? 📏', body_es = '¡Está dando un estirón! Introduce su talla y número de pie actuales en el Seguimiento del desarrollo y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Les vêtements serrent encore ? 📏', body_fr = 'C''est un pic de croissance physique ! Entrez sa taille et sa pointure actuelles dans le Suivi de croissance et regardez fièrement sa courbe grimper.', title_hi = 'कपड़े फिर से तंग हो रहे हैं? 📏', body_hi = 'शारीरिक विकास में उछाल है! ग्रोथ ट्रैकर में मौजूदा लंबाई और जूतों का साइज़ दर्ज कीजिए और गर्व से देखिए कि ग्रोथ कर्व कैसे ऊपर जा रहा है।', title_id = 'Bajunya kekecilan lagi? 📏', body_id = 'Ada lonjakan pertumbuhan fisik! Masukkan tinggi dan ukuran sepatunya saat ini ke Pelacak Perkembangan dan lihat dengan bangga kurva pertumbuhannya naik.', title_ja = '服がまた小さくなってきた？📏', body_ja = '体がぐんと成長する時期です！「発達トラッカー」に今の身長と靴のサイズを入力して、成長曲線が伸びていく様子を誇らしく眺めましょう。', title_ko = '옷이 또 끼나요? 📏', body_ko = '신체 성장 급등기예요! 성장 기록에 현재 키와 신발 치수를 입력하고 성장 곡선이 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Worden de kleren weer te klein? 📏', body_nl = 'Er is een groeispurt! Voer zijn huidige lengte en schoenmaat in de Groeitracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Ubranka znów za ciasne? 📏', body_pl = 'Skok w rozwoju fizycznym! Wpisz aktualny wzrost i rozmiar butów w Śledzeniu rozwoju i z dumą patrz, jak pnie się krzywa rozwoju.', title_pt = 'A roupa está outra vez a ficar apertada? 📏', body_pt = 'Há um salto no crescimento físico! Introduza a altura e o tamanho do sapato atuais no Registo de Desenvolvimento e veja com orgulho a curva de crescimento a subir.', title_sv = 'Blir kläderna för små igen? 📏', body_sv = 'Det är en fysisk tillväxtspurt! Ange aktuell längd och skostorlek i Utvecklingsspåraren och titta stolt på hur tillväxtkurvan stiger.', title_vi = 'Quần áo lại chật rồi? 📏', body_vi = 'Bé đang tăng trưởng vọt! Hãy nhập chiều cao và cỡ giày hiện tại vào Theo dõi phát triển và tự hào ngắm đường cong phát triển đi lên.', title_zh = '衣服又变紧了？📏', body_zh = '身体发育突飞猛进！在发育追踪里输入当前的身高和鞋码，骄傲地看看成长曲线是怎么往上走的。' WHERE id = '3f0a8eb7-b5c5-4230-90cc-9ba54d5ff248' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de lógica 🧩', body_es = '¿Se aburre de los mismos juguetes? Descubre en Productos recomendados puzles seguros y adecuados a su edad que afinarán su inteligencia.', title_fr = 'En quête de logique 🧩', body_fr = 'Il se lasse des mêmes jouets ? Découvrez dans les Produits recommandés des puzzles sûrs et adaptés à son âge pour affûter son intelligence.', title_hi = 'तर्क की तलाश 🧩', body_hi = 'एक जैसे खिलौनों से ऊब गया? उसकी बुद्धि तेज़ करने वाली, उम्र के हिसाब से सुरक्षित पज़ल सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Mencari tantangan logika 🧩', body_id = 'Bosan dengan mainan yang itu-itu saja? Temukan puzzle yang aman dan sesuai usia untuk mengasah kecerdasannya di bagian Produk Rekomendasi.', title_ja = '論理的な思考を育てよう 🧩', body_ja = 'いつものおもちゃに飽きてきた？知性を磨く、年齢に合った安全なパズルを「おすすめ商品」で見つけましょう。', title_ko = '논리를 찾아서 🧩', body_ko = '늘 같은 장난감에 싫증 났나요? 두뇌를 키워 줄 연령별 안전한 퍼즐을 추천 제품 섹션에서 찾아보세요.', title_nl = 'Op zoek naar logica 🧩', body_nl = 'Verveelt hij zich met hetzelfde speelgoed? Ontdek in Aanbevolen producten veilige puzzels voor zijn leeftijd die zijn verstand scherpen.', title_pl = 'W poszukiwaniu logiki 🧩', body_pl = 'Nudzą go te same zabawki? Odkryj w sekcji Polecane produkty bezpieczne układanki dopasowane do wieku, które wyostrzą jego umysł.', title_pt = 'Em busca da lógica 🧩', body_pt = 'Está farto dos mesmos brinquedos? Descubra na secção Produtos Recomendados puzzles seguros e adequados à idade, que vão aguçar a inteligência dele.', title_sv = 'På jakt efter logik 🧩', body_sv = 'Har barnet tröttnat på samma leksaker? Upptäck åldersanpassade och säkra pussel som skärper tänkandet i Rekommenderade produkter.', title_vi = 'Tìm kiếm tư duy 🧩', body_vi = 'Bé chán những món đồ chơi cũ? Hãy khám phá các bộ ghép hình an toàn, phù hợp lứa tuổi giúp bé thêm nhanh trí trong mục Sản phẩm gợi ý.', title_zh = '寻找逻辑游戏 🧩', body_zh = '玩腻了同样的玩具？在推荐商品板块发现让宝宝更聪明、适龄又安全的拼图。' WHERE id = '5bace5b1-8b66-491f-869e-157ff26e9bbf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pegar y morder de repente 🦖', body_es = '¿Se pone agresivo cuando se enfada? Aprende con Anacan AI a cambiar esta conducta con suavidad convirtiéndola en un juego.', title_fr = 'Taper et mordre soudain 🦖', body_fr = 'Il devient agressif quand il se fâche ? Découvrez avec Anacan AI comment faire évoluer ce comportement en douceur en le transformant en jeu.', title_hi = 'अचानक मारना और काटना 🦖', body_hi = 'गुस्से में आक्रामक हो जाता है? Anacan AI के साथ जानिए कि इस व्यवहार को खेल बनाकर नरमी से कैसे बदलें।', title_id = 'Tiba-tiba memukul dan menggigit 🦖', body_id = 'Menjadi agresif saat marah? Pelajari bersama Anacan AI cara mengubah perilaku ini dengan lembut lewat permainan.', title_ja = '急にたたく、かみつく 🦖', body_ja = '怒ると乱暴になりますか？この行動を遊びに変えて、やさしく変えていく方法を、Anacan AIで学びましょう。', title_ko = '갑자기 때리고 깨물어요 🦖', body_ko = '화가 나면 공격적으로 변하나요? 이 행동을 놀이로 바꿔 부드럽게 고쳐 가는 방법을 Anacan AI와 함께 배워 보세요.', title_nl = 'Plotseling slaan en bijten 🦖', body_nl = 'Wordt hij agressief als hij boos is? Leer met Anacan AI hoe je dit gedrag zacht verandert door er een spelletje van te maken.', title_pl = 'Nagłe bicie i gryzienie 🦖', body_pl = 'Gdy się złości, robi się agresywny? Dowiedz się z Anacan AI, jak łagodnie zmienić to zachowanie, zamieniając je w zabawę.', title_pt = 'Bater e morder de repente 🦖', body_pt = 'Fica agressivo quando se zanga? Aprenda com o Anacan AI a mudar este comportamento com suavidade, transformando-o num jogo.', title_sv = 'Slår och biter plötsligt 🦖', body_sv = 'Blir barnet aggressivt när hen är arg? Lär dig med Anacan AI hur du varsamt kan förändra beteendet genom att göra det till en lek.', title_vi = 'Bất ngờ đánh và cắn 🦖', body_vi = 'Bé trở nên hung hăng khi tức giận? Hãy cùng Anacan AI học cách nhẹ nhàng thay đổi hành vi này bằng cách biến nó thành trò chơi.', title_zh = '突然打人和咬人 🦖', body_zh = '一生气就变得有攻击性？和Anacan AI一起学习如何把这种行为变成游戏，温和地加以改变。' WHERE id = 'e03c5d95-be6c-414b-b518-86431da64323' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juego secreto con verduras 🥕', body_es = '¿Rechaza la zanahoria y las espinacas? Descubre en Recetas para bebé cómo esconder con maña estas vitaminas en unas tortitas deliciosas.', title_fr = 'Cache-cache avec les légumes 🥕', body_fr = 'Il refuse carottes et épinards ? Découvrez dans les Recettes pour bébés comment cacher habilement ces vitamines dans de délicieuses crêpes.', title_hi = 'सब्ज़ियों के साथ छुपा खेल 🥕', body_hi = 'गाजर और पालक नहीं खाता? बच्चों की रेसिपी में जानिए कि इन विटामिनों को स्वादिष्ट पैनकेक में चतुराई से कैसे छिपाएँ।', title_id = 'Permainan rahasia dengan sayuran 🥕', body_id = 'Menolak wortel dan bayam? Temukan di Resep Bayi cara pintar menyembunyikan vitamin-vitamin ini di dalam panekuk yang lezat.', title_ja = '野菜でこっそり作戦 🥕', body_ja = 'にんじんやほうれん草を嫌がりますか？「離乳食を始める赤ちゃんのレシピ」で、これらのビタミンをおいしいパンケーキに上手に隠す方法を見つけましょう。', title_ko = '채소 숨바꼭질 🥕', body_ko = '당근과 시금치를 거부하나요? 아기 레시피에서 이 비타민들을 맛있는 팬케이크 속에 감쪽같이 숨기는 법을 찾아보세요.', title_nl = 'Verstoppertje met groenten 🥕', body_nl = 'Weigert hij wortel en spinazie? Ontdek in Babyrecepten hoe je deze vitamines slim verstopt in lekkere pannenkoekjes.', title_pl = 'Zabawa w ukrywanie warzyw 🥕', body_pl = 'Odrzuca marchewkę i szpinak? Odkryj w Przepisach dla niemowląt, jak zręcznie ukryć te witaminy w pysznych placuszkach.', title_pt = 'Jogo escondido com legumes 🥕', body_pt = 'Rejeita cenoura e espinafres? Descubra nas Receitas para bebés como esconder com mestria estas vitaminas em panquecas deliciosas.', title_sv = 'Hemlig lek med grönsaker 🥕', body_sv = 'Vägrar barnet morötter och spenat? Upptäck i Recept för bebisar hur du skickligt gömmer dessa vitaminer i goda pannkakor.', title_vi = 'Trò chơi giấu rau củ 🥕', body_vi = 'Bé từ chối cà rốt và rau chân vịt? Hãy khám phá cách khéo léo giấu những vitamin này vào bánh kếp ngon lành trong Công thức cho bé.', title_zh = '和蔬菜玩捉迷藏 🥕', body_zh = '不吃胡萝卜和菠菜？在宝宝食谱里发现如何把这些维生素巧妙地藏进美味的小煎饼里。' WHERE id = '53335520-c239-4dc6-bb98-8950aeac052d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy has levantado la voz? No te juzgues. Escribe cómo te sientes en el Diario de ánimo: ya eres la mejor madre para tu peque.', body_fr = 'Vous avez haussé le ton aujourd''hui ? Ne vous le reprochez pas. Écrivez vos émotions dans le Journal d''humeur : vous restez la meilleure maman pour lui.', body_hi = 'आज आपकी आवाज़ ऊँची हो गई? खुद को कोसिए मत। मूड डायरी में अपनी भावनाएँ लिखिए, आप वैसे भी उसके लिए सबसे अच्छी माँ हैं।', body_id = 'Hari ini suara Anda meninggi? Jangan menyalahkan diri sendiri. Tulis perasaan Anda di Buku Harian Suasana Hati, Anda tetap ibu terbaik untuknya.', body_ja = '今日は声を荒らげてしまいましたか？自分を責めないで。「気分日記」に気持ちを書きましょう。あなたはお子さんにとって、すでに最高のママです。', body_ko = '오늘 목소리가 커졌나요? 자책하지 마세요. 기분 일기에 마음을 적어 보세요. 엄마는 이미 아이에게 최고의 엄마예요.', body_nl = 'Verhief je vandaag je stem? Veroordeel jezelf niet. Schrijf je gevoelens op in je Stemmingsdagboek, je bent hoe dan ook de beste moeder voor hem.', body_pl = 'Podniosłaś dziś głos? Nie obwiniaj się. Zapisz swoje uczucia w Dzienniku nastroju, i tak jesteś dla niego najlepszą mamą.', body_pt = 'Hoje levantou a voz? Não se culpe. Escreva o que sente no Diário de Humor: continua a ser a melhor mãe para ele.', body_sv = 'Höjde du rösten i dag? Döm inte dig själv. Skriv ner dina känslor i Humördagboken, du är redan den bästa mamman för ditt barn.', body_vi = 'Hôm nay mẹ lỡ to tiếng? Đừng tự trách. Hãy viết cảm xúc vào Nhật ký tâm trạng, vì mẹ vẫn là người mẹ tốt nhất của bé.', body_zh = '今天提高嗓门了？别责怪自己。把感受写进心情日记，你本来就是宝宝最好的妈妈。' WHERE id = '9cc1439a-0d58-4e5e-94b1-3125467bf825' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El espectáculo sin fin de la mesa ⏱️', body_es = '¿Juega con la comida pero no come? Pon el temporizador de tomas, controla cuánto dura y analiza con precisión la evolución de su apetito.', title_fr = 'Le show sans fin à table ⏱️', body_fr = 'Il joue avec la nourriture mais ne mange pas ? Lancez le minuteur des repas, suivez la durée du repas et analysez précisément l''évolution de son appétit.', title_hi = 'मेज़ पर कभी न खत्म होने वाला शो ⏱️', body_hi = 'खाने से खेलता है, पर खाता नहीं? फ़ीडिंग टाइमर चालू कीजिए, समय पर नज़र रखिए और भूख के रुझान को सटीक समझिए।', title_id = 'Pertunjukan tanpa akhir di meja makan ⏱️', body_id = 'Bermain dengan makanan, tapi tidak makan? Nyalakan Timer Makan, pantau durasinya, dan analisis perkembangan nafsu makannya secara akurat.', title_ja = '食卓のエンドレスショー ⏱️', body_ja = '食べ物で遊ぶけれど、食べない？食事タイマーをオンにして、時間を記録し、食欲の変化をしっかり分析しましょう。', title_ko = '식탁 위 끝없는 공연 ⏱️', body_ko = '음식으로 장난만 치고 먹지는 않나요? 수유 타이머를 켜서 시간을 재고 식욕의 변화를 정확히 분석해 보세요.', title_nl = 'De eindeloze show aan tafel ⏱️', body_nl = 'Speelt hij met eten, maar eet hij niet? Zet de Voedingstimer aan, volg hoe lang het duurt en analyseer zijn eetlust precies.', title_pl = 'Niekończący się show przy stole ⏱️', body_pl = 'Bawi się jedzeniem, ale nie je? Włącz timer karmienia, śledź czas posiłku i dokładnie przeanalizuj apetyt.', title_pt = 'O espetáculo sem fim à mesa ⏱️', body_pt = 'Brinca com a comida, mas não come? Ligue o temporizador de alimentação, acompanhe a duração e analise com precisão a evolução do apetite.', title_sv = 'Showen vid bordet som aldrig tar slut ⏱️', body_sv = 'Leker barnet med maten men äter inte? Starta matningstimern, följ hur lång tid det tar och analysera aptitens utveckling noga.', title_vi = 'Màn trình diễn bất tận trên bàn ăn ⏱️', body_vi = 'Bé nghịch thức ăn mà không ăn? Hãy bật Hẹn giờ cho bú, theo dõi thời gian và phân tích chính xác khẩu vị của bé.', title_zh = '餐桌上停不下来的表演 ⏱️', body_zh = '玩食物，就是不吃？打开喂养计时器，记录用餐时长，准确分析食欲的变化。' WHERE id = 'bd4e1f9a-2949-4f64-b861-47344e3cdbfc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juntos, pero por separado 👶', body_es = '¿En el parque no juega con otros niños, solo los observa? ¡Es el juego paralelo! Lee en el Blog sobre esta sana etapa de socialización.', title_fr = 'Ensemble, mais chacun de son côté 👶', body_fr = 'Au parc, il ne joue pas avec les autres enfants, il les observe ? C''est le jeu parallèle ! Lisez dans la rubrique Blogs cette étape saine de socialisation.', title_hi = 'साथ-साथ, पर अलग-अलग 👶', body_hi = 'पार्क में दूसरे बच्चों के साथ खेलता नहीं, बस देखता है? यह पैरेलल प्ले है! ब्लॉग सेक्शन में मेल-जोल के इस सेहतमंद दौर के बारे में पढ़िए।', title_id = 'Bersama, tapi terpisah 👶', body_id = 'Di taman ia tidak bermain dengan anak lain, hanya mengamati? Ini bermain paralel! Baca tentang tahap sosialisasi yang sehat ini di bagian Blog.', title_ja = '一緒に、でも別々に 👶', body_ja = '公園でほかの子と遊ばず、見ているだけ？これは「平行遊び」です！この健やかな社会性の段階について、ブログで読んでみましょう。', title_ko = '함께, 하지만 따로 👶', body_ko = '공원에서 다른 아이들과 놀지 않고 지켜만 보나요? 이건 평행 놀이예요! 이 건강한 사회성 발달 단계에 대해 블로그에서 읽어 보세요.', title_nl = 'Samen, maar apart 👶', body_nl = 'Speelt hij in het park niet met andere kinderen, maar kijkt hij alleen toe? Dat is parallel spel! Lees in Blogs over deze gezonde fase van socialisatie.', title_pl = 'Razem, ale osobno 👶', body_pl = 'W parku nie bawi się z innymi dziećmi, tylko patrzy? To zabawa równoległa! Przeczytaj w sekcji Blog o tym zdrowym etapie uspołecznienia.', title_pt = 'Juntos, mas separados 👶', body_pt = 'No parque não brinca com as outras crianças, só observa? É a brincadeira paralela! Leia nos Blogues sobre esta fase saudável da socialização.', title_sv = 'Tillsammans, men var för sig 👶', body_sv = 'Leker barnet inte med de andra barnen i parken utan tittar bara på? Det är parallellek! Läs om det här sunda sociala stadiet i Bloggar.', title_vi = 'Cùng nhau nhưng riêng lẻ 👶', body_vi = 'Ở công viên bé không chơi cùng các bạn mà chỉ đứng nhìn? Đó là chơi song song! Hãy đọc về giai đoạn hòa nhập xã hội lành mạnh này trong mục Blog.', title_zh = '在一起，又各玩各的 👶', body_zh = '在公园不和其他小朋友玩，只在旁边看？这是平行游戏！去博客板块读读这个健康的社交阶段。' WHERE id = '39267d40-2480-48f4-9716-e425031ba3b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tentempié sin azúcar 🍪', body_es = 'No hacen falta galletas del súper. Descubre en Recetas para bebé dulces sanos caseros de dátiles y manzana que se preparan en 10 minutos.', title_fr = 'En-cas sans sucre 🍪', body_fr = 'Pas besoin de biscuits du commerce. Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à la pomme, prêtes en 10 minutes à la maison.', title_hi = 'बिना चीनी का स्नैक 🍪', body_hi = 'बाज़ार के बिस्किट की ज़रूरत नहीं। बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और सेब की सेहतमंद मिठाइयाँ खोजिए।', title_id = 'Camilan tanpa gula 🍪', body_id = 'Tak perlu biskuit dari toko. Temukan camilan manis sehat dari kurma dan apel yang siap dalam 10 menit di Resep Bayi.', title_ja = '砂糖不使用のおやつ 🍪', body_ja = '市販のクッキーはいりません。「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとりんごのヘルシーなおやつを見つけましょう。', title_ko = '설탕 없는 간식 🍪', body_ko = '마트 쿠키는 필요 없어요. 아기 레시피에서 집에서 10분이면 만드는 대추야자 사과 건강 간식을 찾아보세요.', title_nl = 'Suikervrij tussendoortje 🍪', body_nl = 'Koekjes uit de winkel zijn niet nodig. Ontdek in Babyrecepten gezonde lekkernijen met dadels en appel, thuis klaar in 10 minuten.', title_pl = 'Przekąska bez cukru 🍪', body_pl = 'Sklepowe ciastka nie są potrzebne. Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i jabłkiem, które zrobisz w domu w 10 minut.', title_pt = 'Lanche sem açúcar 🍪', body_pt = 'Não precisa de bolachas do supermercado. Descubra nas Receitas para bebés doces saudáveis de tâmaras e maçã, feitos em casa em 10 minutos.', title_sv = 'Sockerfritt mellanmål 🍪', body_sv = 'Ni behöver inga kex från affären. Upptäck nyttiga sötsaker med dadlar och äpple som är klara på 10 minuter hemma i Recept för bebisar.', title_vi = 'Món ăn vặt không đường 🍪', body_vi = 'Không cần bánh quy mua sẵn. Hãy khám phá các món ngọt bổ dưỡng từ chà là và táo làm tại nhà trong 10 phút trong Công thức cho bé.', title_zh = '无糖小零食 🍪', body_zh = '不需要超市的饼干。在宝宝食谱里发现10分钟就能在家做好的椰枣苹果健康甜点。' WHERE id = '7ae07c2d-565f-4b45-bebf-b9e3ab799a99' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo se desarrolla la inteligencia? 🧠', body_es = 'Lee sin falta en el Blog el artículo sobre juegos caseros que estimulan el cerebro y mejoran la percepción de colores y formas a los 21,5 meses.', title_fr = 'Comment se développe son intelligence ? 🧠', body_fr = 'Lisez absolument l''article de la rubrique Blogs sur les jeux à la maison qui stimulent le cerveau et la perception des couleurs et des formes à 21,5 mois.', title_hi = 'बुद्धि कैसे विकसित होती है? 🧠', body_hi = 'ब्लॉग सेक्शन में 21.5 महीने के बच्चों में रंग और आकार की समझ बढ़ाने वाले, दिमाग को सक्रिय करने वाले घरेलू खेलों पर लेख ज़रूर पढ़िए।', title_id = 'Bagaimana kecerdasannya berkembang? 🧠', body_id = 'Baca artikel di bagian Blog tentang permainan rumahan yang menstimulasi otak dan meningkatkan pengenalan warna dan bentuk anak usia 21,5 bulan.', title_ja = '知性はどう育つ？🧠', body_ja = '1歳9か月半の子の色や形の認識を育て、脳を刺激するおうち遊びについて、ブログの記事をぜひ読んでみましょう。', title_ko = '두뇌는 어떻게 자랄까요? 🧠', body_ko = '블로그에서 21.5개월 아이의 색과 모양 인지를 키우고 두뇌를 자극하는 집 놀이에 관한 글을 꼭 읽어 보세요.', title_nl = 'Hoe groeit zijn verstand? 🧠', body_nl = 'Lees zeker het artikel in Blogs over spelletjes voor thuis die kleur- en vormherkenning versterken en de hersenen prikkelen bij kinderen van 21,5 maand.', title_pl = 'Jak rozwija się umysł? 🧠', body_pl = 'Koniecznie przeczytaj w sekcji Blog artykuł o domowych zabawach, które rozwijają postrzeganie kolorów i kształtów i stymulują mózg dzieci w wieku 21,5 miesiąca.', title_pt = 'Como se desenvolve a inteligência? 🧠', body_pt = 'Leia sem falta nos Blogues o artigo sobre jogos caseiros que estimulam o cérebro e melhoram a perceção de cores e formas em crianças de 21,5 meses.', title_sv = 'Hur utvecklas tänkandet? 🧠', body_sv = 'Läs artikeln i Bloggar om lekar hemma som stimulerar hjärnan och stärker uppfattningen av färger och former hos barn på 21,5 månader.', title_vi = 'Trí tuệ phát triển thế nào? 🧠', body_vi = 'Nhất định hãy đọc bài viết trong mục Blog về các trò chơi tại nhà giúp kích thích não bộ, tăng khả năng nhận biết màu sắc và hình dạng cho trẻ 21,5 tháng.', title_zh = '智力是怎样发展的？🧠', body_zh = '一定要读读博客板块里关于提升21.5个月宝宝颜色和形状认知、刺激大脑的居家游戏文章。' WHERE id = '02902252-366d-405a-a62b-9c6f129b4a84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de las reservas de hierro 🥩', body_es = 'Unos músculos tan activos no pueden tener anemia. Comprueba con el Seguimiento de tomas el hierro de hoy y completa enseguida lo que falte.', title_fr = 'Contrôle des réserves de fer 🥩', body_fr = 'Pour des muscles actifs, il ne doit pas manquer de fer. Vérifiez avec le Suivi des repas ses apports en fer du jour et comblez tout de suite les manques.', title_hi = 'आयरन के भंडार की जाँच 🥩', body_hi = 'चंचल मांसपेशियों के लिए खून की कमी नहीं होनी चाहिए। फ़ीडिंग ट्रैकर से आज का आयरन जाँचिए और कमी तुरंत पूरी कीजिए।', title_id = 'Cek cadangan zat besi 🥩', body_id = 'Otot yang aktif tidak boleh kekurangan darah. Cek asupan zat besi hari ini dengan alat Pemantau Nutrisi dan segera lengkapi kekurangannya.', title_ja = '鉄分チェック 🥩', body_ja = '活発に動く筋肉のためには、貧血を防ぐことが大切です。「栄養管理ツール」で今日の鉄分の摂取量を確認し、足りない分をすぐに補いましょう。', title_ko = '철분 확인 🥩', body_ko = '활발한 근육을 위해 빈혈은 막아야 해요. 수유 기록 도구로 오늘의 철분 섭취를 확인하고 부족한 만큼 바로 채워 주세요.', title_nl = 'IJzervoorraad checken 🥩', body_nl = 'Voor actieve spieren mag er geen bloedarmoede zijn. Controleer met de Voedingstracker het ijzer van vandaag en vul tekorten meteen aan.', title_pl = 'Kontrola zapasu żelaza 🥩', body_pl = 'Aktywne mięśnie nie mogą cierpieć na anemię. Sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza i od razu uzupełnij braki.', title_pt = 'Verificar as reservas de ferro 🥩', body_pt = 'Músculos ativos não combinam com anemia. Verifique com o Registo de Alimentação o ferro de hoje e complete já o que faltar.', title_sv = 'Kontroll av järnförrådet 🥩', body_sv = 'Aktiva muskler behöver ett barn utan blodbrist. Kontrollera dagens järnintag med Matningskoll och fyll direkt på det som fattas.', title_vi = 'Kiểm tra kho sắt 🥩', body_vi = 'Để cơ bắp hoạt động tốt, bé không được thiếu máu. Hãy kiểm tra lượng sắt hôm nay bằng Theo dõi cữ bú và bổ sung ngay phần thiếu.', title_zh = '铁储备检查 🥩', body_zh = '为了肌肉活力十足，不能贫血。用喂养记录工具查看今天的铁摄入量，马上补足不够的部分。' WHERE id = '08bbbba1-9e53-4379-a09e-82d1079f7df6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se llena el pañal de noche? 🧻', body_es = 'Si el pañal de la mañana pesa mucho, el sueño nocturno puede alterarse. Anota las deposiciones en el Seguimiento de pañales y analiza las estadísticas para ajustar los líquidos de la tarde.', title_fr = 'Les couches de nuit débordent ? 🧻', body_fr = 'Une couche du matin très lourde peut perturber le sommeil de nuit. Notez-la dans le Suivi des couches et analysez les statistiques pour ajuster ce qu''il boit le soir.', title_hi = 'रात के डायपर भर जाते हैं? 🧻', body_hi = 'अगर सुबह का डायपर बहुत भारी है, तो रात की नींद टूट सकती है। डायपर ट्रैकर में दर्ज कीजिए और शाम का तरल ठीक करने के लिए आँकड़ों का विश्लेषण कीजिए।', title_id = 'Popok malamnya penuh? 🧻', body_id = 'Jika popok paginya sangat berat, tidur malamnya bisa terganggu. Catat di Pelacak Popok dan analisis statistiknya untuk mengatur asupan cairan di sore hari.', title_ja = '夜のおむつがいっぱい？🧻', body_ja = '朝のおむつがとても重いと、夜の眠りが妨げられることがあります。「おむつトラッカー」に記録して統計を分析し、夕方の水分のとり方を調整しましょう。', title_ko = '밤 기저귀가 가득 차나요? 🧻', body_ko = '아침 기저귀가 아주 무겁다면 밤잠이 방해받을 수 있어요. 기저귀 기록에 배변을 남기고 통계를 분석해 저녁 수분 섭취를 조절하세요.', title_nl = 'Lopen de nachtluiers vol? 🧻', body_nl = 'Een erg zware ochtendluier kan de nachtrust verstoren. Noteer de plas in de Luiertracker en analyseer de statistieken om het drinken in de avond aan te passen.', title_pl = 'Nocne pieluszki przepełnione? 🧻', body_pl = 'Jeśli poranna pieluszka jest bardzo ciężka, nocny sen może być zaburzony. Zapisz to w narzędziu do śledzenia pieluszek i przeanalizuj statystyki, by dopasować wieczorne picie.', title_pt = 'As fraldas da noite ficam cheias? 🧻', body_pt = 'Se a fralda da manhã está muito pesada, o sono noturno pode ser perturbado. Registe-o no Registo de Fraldas e analise as estatísticas para ajustar os líquidos à noite.', title_sv = 'Fulla nattblöjor? 🧻', body_sv = 'Är morgonblöjan väldigt tung kan nattsömnen störas. Anteckna avföringen i Blöjkollen och analysera statistiken för att justera vätskeintaget på kvällen.', title_vi = 'Tã đêm đầy ắp? 🧻', body_vi = 'Nếu tã buổi sáng quá nặng, giấc ngủ đêm có thể bị gián đoạn. Hãy ghi lại trong Theo dõi tã và phân tích thống kê để điều chỉnh lượng nước bé uống buổi tối.', title_zh = '夜里尿布满了？🧻', body_zh = '早上的尿布很沉的话，夜间睡眠可能会受影响。在尿布记录里记下排泄情况，分析统计，调整晚上的饮水量。' WHERE id = '4c3b97db-69e0-4349-8a8d-b599fed49f3d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorador en la cocina 🥦', body_es = '¿Quiere cocinar contigo? Descubre en Recetas para bebés que empiezan con la alimentación complementaria magdalenas fáciles y deliciosas con verduras para preparar juntos.', title_fr = 'Un explorateur en cuisine 🥦', body_fr = 'Il veut cuisiner avec vous ? Découvrez dans les Recettes pour bébés qui commencent la diversification des muffins aux légumes faciles et délicieux à préparer ensemble.', title_hi = 'रसोई में नन्हा खोजी 🥦', body_hi = 'वह भी आपके साथ खाना बनाना चाहता है? ऊपरी आहार शुरू करने वाले बच्चों के लिए रेसिपी में साथ मिलकर बनाए जा सकने वाले आसान, सब्ज़ियों वाले स्वादिष्ट मफ़िन खोजिए।', title_id = 'Penjelajah di dapur 🥦', body_id = 'Ia juga ingin memasak bersama Anda? Temukan resep muffin sayur yang mudah dan lezat untuk dibuat bersama di Resep untuk bayi yang mulai MPASI.', title_ja = 'キッチンの探検家 🥦', body_ja = 'お子さんも一緒に料理をしたがりますか？「離乳食を始める赤ちゃんのレシピ」で、一緒につくれる簡単でおいしい野菜入りマフィンのレシピを見つけましょう。', title_ko = '주방 탐험가 🥦', body_ko = '엄마랑 같이 요리하고 싶어 하나요? 이유식을 시작하는 아기를 위한 레시피에서 함께 만들 수 있는 쉽고 맛있는 채소 머핀을 찾아보세요.', title_nl = 'Ontdekker in de keuken 🥦', body_nl = 'Wil hij ook met je koken? Ontdek in Recepten voor baby''s die met bijvoeding beginnen makkelijke en lekkere groentemuffins die jullie samen kunnen maken.', title_pl = 'Odkrywca w kuchni 🥦', body_pl = 'Też chce gotować z tobą? Odkryj w Przepisach dla niemowląt rozpoczynających rozszerzanie diety łatwe i pyszne babeczki z warzywami, które przygotujecie razem.', title_pt = 'Explorador na cozinha 🥦', body_pt = 'Também quer cozinhar consigo? Descubra nas Receitas para bebés em diversificação alimentar receitas de queques fáceis, saborosos e com legumes para fazerem juntos.', title_sv = 'Upptäcktsresande i köket 🥦', body_sv = 'Vill barnet också laga mat med dig? Upptäck enkla och goda muffinsrecept med grönsaker som ni kan göra tillsammans i Recept för bebisar som börjar med fast föda.', title_vi = 'Nhà thám hiểm trong bếp 🥦', body_vi = 'Bé cũng muốn nấu ăn cùng mẹ? Hãy khám phá các công thức bánh muffin rau củ dễ làm, ngon miệng mà hai mẹ con có thể cùng làm trong Công thức cho bé bắt đầu ăn dặm.', title_zh = '厨房里的小探险家 🥦', body_zh = '也想和你一起做饭？在适合刚开始添加辅食宝宝的食谱里，发现可以一起做的简单美味蔬菜玛芬。' WHERE id = 'c15f640c-d99c-497d-be3f-c7f256e90fd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sonido del silencio 🌧️', body_es = 'Tras un día tan movido hay que calmar el cerebro. Pon en la habitación el sonido de la lluvia de Ruido blanco y relaja de forma natural el ambiente para dormir.', title_fr = 'Le son du calme 🌧️', body_fr = 'Après une journée trop agitée, il faut ralentir le cerveau. Lancez dans la chambre le bruit de la pluie des Bruits blancs pour apaiser naturellement l''ambiance du sommeil.', title_hi = 'खामोशी की आवाज़ 🌧️', body_hi = 'बहुत भाग-दौड़ भरे दिन के बाद दिमाग को धीमा करना ज़रूरी है। कमरे में व्हाइट नॉइज़ से बारिश की आवाज़ चलाइए और नींद के माहौल को कुदरती तरीके से शांत कीजिए।', title_id = 'Suara keheningan 🌧️', body_id = 'Setelah hari yang terlalu aktif, otaknya perlu diperlambat. Putar suara hujan dari Suara Putih di kamar dan tenangkan suasana tidur secara alami.', title_ja = '静けさの音 🌧️', body_ja = '活発すぎる一日のあとは、脳をゆっくり休ませることが必要です。部屋で「ホワイトノイズ」の雨の音を流して、眠りの環境を自然に落ち着かせましょう。', title_ko = '고요함의 소리 🌧️', body_ko = '너무 활발했던 하루 뒤에는 머리를 차분하게 해 줘야 해요. 백색소음에서 빗소리를 틀어 수면 환경을 자연스럽게 진정시켜 주세요.', title_nl = 'Het geluid van stilte 🌧️', body_nl = 'Na een superactieve dag moet zijn hoofdje tot rust komen. Zet in de kamer regengeluid uit Witte ruis aan en maak de slaapomgeving op een natuurlijke manier rustig.', title_pl = 'Odgłos ciszy 🌧️', body_pl = 'Po bardzo aktywnym dniu trzeba wyciszyć umysł. Włącz w pokoju odgłos deszczu z Białego szumu i w naturalny sposób uspokój atmosferę do snu.', title_pt = 'O som do silêncio 🌧️', body_pt = 'Depois de um dia demasiado agitado, é preciso abrandar o cérebro. Ligue no quarto o som da chuva do Ruído Branco e acalme de forma natural o ambiente de sono.', title_sv = 'Tystnadens ljud 🌧️', body_sv = 'Efter en väldigt aktiv dag behöver hjärnan varva ner. Sätt på regnljud från Vitt brus i rummet och lugna sömnmiljön på ett naturligt sätt.', title_vi = 'Âm thanh của tĩnh lặng 🌧️', body_vi = 'Sau một ngày quá năng động, não bộ cần được chậm lại. Hãy bật tiếng mưa trong Tiếng ồn trắng để không gian ngủ dịu lại một cách tự nhiên.', title_zh = '安静的声音 🌧️', body_zh = '活动量特别大的一天之后，需要让大脑慢下来。在房间里打开白噪音里的雨声，让睡眠环境自然地安静下来。' WHERE id = 'e02612f3-415f-450d-9411-e60c3bd32d09' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de rabietas? Pon el susurro de las hojas de Ruido blanco y regala un masaje al sistema nervioso de los dos.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée pleine de crises et de bruit ? Lancez le bruissement des feuilles des Bruits blancs pour masser son système nerveux comme le vôtre.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत नखरों और शोर भरा दिन था? व्हाइट नॉइज़ में पत्तों की सरसराहट चलाइए और उसके और अपने, दोनों के तंत्रिका तंत्र को आराम दीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari ini penuh tantrum dan bising? Putar suara gemerisik daun dari Suara Putih untuk menenangkan saraf ia dan Anda.', title_ja = '自然のリラックス効果 🍃', body_ja = 'かんしゃくが多く、にぎやかな一日でしたか？「ホワイトノイズ」の木の葉のざわめきを流して、お子さんとあなたの神経をやさしくほぐしましょう。', title_ko = '자연의 진정제 🍃', body_ko = '떼쓰기 많고 시끄러운 하루였나요? 백색소음의 나뭇잎 바스락 소리를 틀어 아이와 엄마의 신경을 함께 달래 주세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een dag vol driftbuien en lawaai? Zet bladergeruis uit Witte ruis aan en geef zijn zenuwstelsel en dat van jezelf een massage.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był dzień pełen kryzysów i hałasu? Włącz szelest liści z Białego szumu i ukój układ nerwowy jego i swój.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia cheio de crises e barulho? Ligue o sussurro das folhas do Ruído Branco e faça uma massagem ao sistema nervoso dele e ao seu.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit full av utbrott och buller? Sätt på lövsus från Vitt brus och ge både barnets och ditt eget nervsystem en massage.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Hôm nay quá nhiều cơn ăn vạ và ồn ào? Hãy bật tiếng lá xào xạc trong Tiếng ồn trắng để xoa dịu hệ thần kinh của cả bé lẫn mẹ.', title_zh = '天然的镇静剂 🍃', body_zh = '今天又闹又吵，崩溃不断？打开白噪音里的树叶沙沙声，给宝宝和你自己的神经系统都做个按摩。' WHERE id = '3dca59c4-0add-4ccb-919d-3806c0dfdbf4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas compañía ☕', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás cafeterías infantiles donde se reúnen muchas madres y socializa.', title_fr = 'Vous aussi, vous avez besoin de compagnie ☕', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez dans les Lieux adaptés aux mamans des cafés pour enfants où les mamans se retrouvent, et voyez du monde.', title_hi = 'आपको भी लोगों का साथ चाहिए ☕', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में वे किड्स कैफ़े ढूँढिए जहाँ बहुत सी माँएँ आती हैं, और लोगों से मिलिए।', title_id = 'Anda juga butuh pergaulan ☕', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan kafe anak tempat banyak ibu berkumpul di Tempat Ramah Ibu dan bersosialisasilah.', title_ja = 'あなたにも仲間が必要です ☕', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」でママたちが集まるキッズカフェを見つけて、交流を楽しみましょう。', title_ko = '엄마에게도 사람들이 필요해요 ☕', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 엄마들이 많이 모이는 키즈 카페를 찾아 함께 어울려 보세요.', title_nl = 'Jij hebt ook gezelschap nodig ☕', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken kindercafés waar veel moeders komen en maak contact.', title_pl = 'Ty też potrzebujesz towarzystwa ☕', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, w których spotyka się wiele mam, i poznawaj ludzi.', title_pt = 'Também precisa de companhia ☕', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães cafés para crianças onde se juntam muitas mães e conviva.', title_sv = 'Du behöver också sällskap ☕', body_sv = 'Trött på att bara prata med barnet? Hitta barncaféer där många mammor samlas i Mammavänliga platser och umgås.', title_vi = 'Mẹ cũng cần kết nối ☕', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm những quán cà phê trẻ em nơi các mẹ hay gặp nhau trong Địa điểm thân thiện với mẹ và giao lưu nhé.', title_zh = '你也需要社交圈 ☕', body_zh = '只和孩子说话说累了？在妈妈友好场所里找找妈妈们常聚的亲子咖啡馆，去社交一下吧。' WHERE id = 'e5117ef0-d242-45f1-b114-50b3bfca72d9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Del ruido al silencio 🎶', body_es = 'Después de los juegos ruidosos, un silencio repentino le asusta. Pon en la habitación el sonido del secador de Ruido blanco y verás el efecto positivo de la monotonía en su sueño.', title_fr = 'Du bruit au silence 🎶', body_fr = 'Après des jeux bruyants, le silence soudain lui fait peur. Lancez dans la chambre le bruit de sèche-cheveux des Bruits blancs et voyez l''effet positif de la monotonie sur son sommeil.', title_hi = 'शोर से खामोशी की ओर 🎶', body_hi = 'शोर भरे खेलों के बाद अचानक की खामोशी उसे डराती है। कमरे में व्हाइट नॉइज़ से हेयर ड्रायर की आवाज़ चलाइए और देखिए कि एक जैसी आवाज़ नींद पर कितना अच्छा असर डालती है।', title_id = 'Dari bising ke hening 🎶', body_id = 'Setelah permainan yang bising, hening yang tiba-tiba bisa membuatnya takut. Putar suara pengering rambut dari Suara Putih di kamar dan lihat manfaat bunyi monoton untuk tidurnya.', title_ja = '音から静けさへ 🎶', body_ja = 'にぎやかな遊びのあとの急な静けさは、お子さんを不安にさせます。部屋で「ホワイトノイズ」のドライヤーの音を流して、単調な音が眠りに与える良い効果を確かめてみましょう。', title_ko = '소리에서 고요함으로 🎶', body_ko = '시끄러운 놀이 뒤의 갑작스러운 정적은 아이를 놀라게 해요. 백색소음에서 헤어드라이어 소리를 틀어 단조로운 소리가 잠에 주는 좋은 효과를 확인해 보세요.', title_nl = 'Van geluid naar stilte 🎶', body_nl = 'Na lawaaierige spelletjes kan plotselinge stilte hem laten schrikken. Zet in de kamer het föhngeluid uit Witte ruis aan en zie hoe eentonigheid zijn slaap positief beïnvloedt.', title_pl = 'Od dźwięku do ciszy 🎶', body_pl = 'Nagła cisza po głośnych zabawach go niepokoi. Włącz w pokoju odgłos suszarki z Białego szumu i zobacz, jak monotonia dobrze wpływa na sen.', title_pt = 'Do barulho ao silêncio 🎶', body_pt = 'Depois de brincadeiras barulhentas, o silêncio repentino assusta-o. Ligue no quarto o som do secador de cabelo do Ruído Branco e veja o efeito positivo da monotonia no sono.', title_sv = 'Från ljud till tystnad 🎶', body_sv = 'Efter bullriga lekar kan plötslig tystnad skrämma barnet. Sätt på hårtorksljud från Vitt brus i rummet och se hur monotona ljud påverkar sömnen positivt.', title_vi = 'Từ ồn ào sang yên tĩnh 🎶', body_vi = 'Sau những trò chơi ồn ào, sự im lặng đột ngột có thể khiến bé sợ. Hãy bật tiếng máy sấy tóc trong Tiếng ồn trắng và xem âm thanh đều đều giúp ích cho giấc ngủ thế nào.', title_zh = '从嘈杂到安静 🎶', body_zh = '吵闹的游戏之后，突然的安静会让宝宝害怕。在房间里打开白噪音里的吹风机声，看看单调的声音对睡眠的积极作用。' WHERE id = 'cd9b8bec-56d4-42a3-a245-f71b148a61ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te duele la cabeza? Corriendo detrás de tu peque te has quedado sin beber. Prepara aguas detox de Recetas saludables y revitaliza tu cuerpo.', body_fr = 'Vous avez mal à la tête ? À force de lui courir après, vous avez oublié de boire. Revitalisez votre corps avec les eaux détox des Recettes saines.', body_hi = 'सिर दर्द है? बच्चे के पीछे भागते हुए आपके शरीर में पानी की कमी हो गई है। सेहतमंद रेसिपी से डिटॉक्स वॉटर बनाइए और शरीर में ताज़गी लाइए।', body_id = 'Sakit kepala? Anda mungkin kurang minum karena terus mengejar si kecil. Segarkan tubuh Anda dengan infused water detoks dari Resep Sehat.', body_ja = '頭が痛いですか？お子さんを追いかけて、水分が足りていないのかもしれません。「ヘルシーレシピ」からデトックスウォーターをつくって、体をリフレッシュさせましょう。', body_ko = '머리가 아프나요? 아이를 쫓아다니느라 수분이 부족해졌을 수 있어요. 건강한 레시피에서 디톡스 워터를 만들어 몸에 활력을 되찾으세요.', body_nl = 'Hoofdpijn? Je bent uitgedroogd geraakt van het achter hem aan rennen. Maak detoxwater uit Gezonde recepten en geef je lichaam een opkikker.', body_pl = 'Boli cię głowa? Biegając za maluchem, zapomniałaś pić. Przygotuj wodę detoks ze Zdrowych przepisów i ożyw swój organizm.', body_pt = 'Tem dores de cabeça? Ficou desidratada a correr atrás dele. Prepare águas detox das Receitas Saudáveis e revitalize o seu corpo.', body_sv = 'Har du huvudvärk? Du har nog glömt att dricka medan du sprungit efter barnet. Gör detoxvatten från Hälsosamma recept och pigga upp kroppen.', body_vi = 'Mẹ bị đau đầu? Có thể mẹ đã bị thiếu nước khi chạy theo bé. Hãy làm nước detox từ Công thức lành mạnh để cơ thể tươi tỉnh lại.', body_zh = '头疼吗？追着孩子跑，你可能缺水了。从健康食谱里做些排毒水，让身体重新充满活力。' WHERE id = '54f26234-4c50-45b3-9088-6a5b0c08fcd2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de clasificar 🔴🔵', body_es = '¿Le encanta poner los rojos a un lado y los azules al otro? Para que este desarrollo de la lógica sea aún más divertido, pide ideas de juegos a Anacan AI.', title_fr = 'Jeux de tri 🔴🔵', body_fr = 'Il adore mettre les rouges d''un côté et les bleus de l''autre ? Demandez à Anacan AI des idées de jeux pour rendre ce développement logique encore plus amusant.', title_hi = 'छाँटने वाले खेल 🔴🔵', body_hi = 'लाल एक तरफ़ और नीले दूसरी तरफ़ रखना पसंद है? इस तार्किक विकास को और मज़ेदार बनाने के लिए Anacan AI से खेल के आइडिया पूछिए।', title_id = 'Permainan memilah 🔴🔵', body_id = 'Suka mengumpulkan yang merah di satu sisi dan yang biru di sisi lain? Tanyakan ide permainan kepada Anacan AI agar perkembangan logika ini makin seru.', title_ja = '分類あそび 🔴🔵', body_ja = '赤いものはこっち、青いものはあっちに集めるのが好きですか？この論理的な発達をもっと楽しくするために、Anacan AIに遊びのアイデアを聞いてみましょう。', title_ko = '분류 놀이 🔴🔵', body_ko = '빨간 것은 이쪽, 파란 것은 저쪽에 모으는 걸 좋아하나요? 이 논리 발달을 더 재미있게 만들 놀이 아이디어를 Anacan AI에게 물어보세요.', title_nl = 'Sorteerspelletjes 🔴🔵', body_nl = 'Legt hij graag de rode dingen aan de ene kant en de blauwe aan de andere? Vraag Anacan AI om spelideeën om deze logische ontwikkeling nog leuker te maken.', title_pl = 'Zabawy w sortowanie 🔴🔵', body_pl = 'Uwielbia układać czerwone na jedną stronę, a niebieskie na drugą? Zapytaj Anacan AI o pomysły na zabawy, które uczynią ten rozwój logiczny jeszcze ciekawszym.', title_pt = 'Jogos de separar 🔴🔵', body_pt = 'Adora juntar os vermelhos de um lado e os azuis do outro? Para tornar este desenvolvimento lógico ainda mais divertido, peça ideias de jogos ao Anacan AI.', title_sv = 'Sorteringslekar 🔴🔵', body_sv = 'Älskar barnet att samla de röda på ena sidan och de blå på den andra? Be Anacan AI om lekidéer som gör den här logiska utvecklingen ännu roligare.', title_vi = 'Trò chơi phân loại 🔴🔵', body_vi = 'Bé thích xếp đồ màu đỏ một bên, màu xanh một bên? Hãy hỏi Anacan AI ý tưởng trò chơi để sự phát triển tư duy này thêm thú vị.', title_zh = '分类游戏 🔴🔵', body_zh = '喜欢把红色的放一边，蓝色的放另一边？向Anacan AI要些游戏点子，让这种逻辑发展变得更有趣。' WHERE id = 'a27861d3-4efc-4b58-bec5-f3117fe589e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exploraciones seguras ⚠️', body_es = 'Armarios, cajones... ¡Peligro para un pequeño explorador! Echa un vistazo en Productos recomendados a los protectores de muebles y cierres de seguridad.', title_fr = 'Explorer en sécurité ⚠️', body_fr = 'Placards, tiroirs... Dangereux pour un petit explorateur ! Jetez un œil aux protections de meubles et aux verrous de sécurité dans les Produits recommandés.', title_hi = 'सुरक्षित खोज ⚠️', body_hi = 'अलमारियाँ, दराज़ें... नन्हे खोजी के लिए खतरनाक हैं! सुझाए गए प्रोडक्ट में फ़र्नीचर गार्ड और सेफ़्टी लॉक देखिए।', title_id = 'Penjelajahan yang aman ⚠️', body_id = 'Lemari, laci... Berbahaya bagi si penjelajah! Lihat pengaman furnitur dan kunci pengaman di Produk Rekomendasi.', title_ja = '安全な探検 ⚠️', body_ja = '戸棚、引き出し…小さな探検家には危険がいっぱい！「おすすめ商品」で家具の転倒防止グッズやチャイルドロックをチェックしましょう。', title_ko = '안전한 탐험 ⚠️', body_ko = '옷장, 서랍... 꼬마 탐험가에게는 위험해요! 추천 제품에서 가구 전도 방지 장치와 안전 잠금장치를 살펴보세요.', title_nl = 'Veilig ontdekken ⚠️', body_nl = 'Kasten, laden... Gevaarlijk voor een ontdekkingsreiziger! Bekijk in Aanbevolen producten meubelbeveiligingen en veiligheidssloten.', title_pl = 'Bezpieczne odkrywanie ⚠️', body_pl = 'Szafki, szuflady... Dla małego odkrywcy to niebezpieczne! Zajrzyj w Polecanych produktach do zabezpieczeń mebli i blokad.', title_pt = 'Descobertas em segurança ⚠️', body_pt = 'Armários, gavetas... São perigosos para um explorador! Espreite nos Produtos Recomendados os protetores de móveis e as trancas de segurança.', title_sv = 'Säkra upptäckter ⚠️', body_sv = 'Skåp, lådor... Farligt för en upptäcktsresande! Titta på möbelskydd och säkerhetslås i Rekommenderade produkter.', title_vi = 'Khám phá an toàn ⚠️', body_vi = 'Tủ, ngăn kéo... Thật nguy hiểm với nhà thám hiểm nhí! Hãy xem các miếng bảo vệ góc đồ đạc và khóa an toàn trong Sản phẩm gợi ý.', title_zh = '安全地探索 ⚠️', body_zh = '柜子、抽屉……对小探险家来说很危险！去推荐商品看看家具防护角和安全锁。' WHERE id = '9387504c-dde1-4fdb-977d-53c3dfbb83a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño. Quizá sea el momento de acortar la siesta 15 minutos.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 15 minutes.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए। शायद दिन की नींद 15 मिनट कम करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 15 menit.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにしましょう。お昼寝を15分短くするちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜세요. 낮잠을 15분 줄일 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan. Misschien is het precies tijd om het middagdutje met 15 minuten in te korten.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu. Może to dobry moment, by skrócić drzemkę o 15 minut.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono. Talvez seja a altura certa de encurtar a sesta 15 minutos.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 15 minuter.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 15 phút.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器。也许正是把白天小睡缩短15分钟的时候了。' WHERE id = 'bdef77ef-7476-4b14-a4a3-51d31635951f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dolor de espalda de mamá 🧘‍♀️', body_es = '¿Te duele la espalda de cogerle en brazos? Cuida tu cuerpo preparando en Recetas saludables un té verde con jengibre, antiinflamatorio y reparador.', title_fr = 'Le mal de dos de maman 🧘‍♀️', body_fr = 'Vous avez mal au dos à force de le porter ? Prenez soin de vous avec un thé vert au gingembre, anti-inflammatoire et réparateur, des Recettes saines.', title_hi = 'माँ की कमर का दर्द 🧘‍♀️', body_hi = 'उसे उठाते-उठाते कमर दर्द करती है? सेहतमंद रेसिपी से सूजन कम करने वाली और ताकत लौटाने वाली अदरक वाली ग्रीन टी बनाइए और अपने शरीर का ख्याल रखिए।', title_id = 'Sakit punggung Bunda 🧘‍♀️', body_id = 'Punggung pegal karena terus menggendongnya? Rawat tubuh Anda dengan menyeduh teh hijau jahe yang antiradang dan memulihkan dari Resep Sehat.', title_ja = 'ママの腰痛 🧘‍♀️', body_ja = '抱っこのしすぎで腰が痛いですか？「ヘルシーレシピ」から、炎症をおさえて回復を助けるしょうが入り緑茶をいれて、体をいたわりましょう。', title_ko = '엄마의 허리 통증 🧘‍♀️', body_ko = '아이를 안아 올리느라 허리가 아프나요? 건강한 레시피에서 염증을 줄이고 회복을 돕는 생강 녹차를 우려 몸을 돌봐 주세요.', title_nl = 'Rugpijn van mama 🧘‍♀️', body_nl = 'Doet je rug pijn van het tillen? Zorg voor je lichaam met ontstekingsremmende, herstellende groene thee met gember uit Gezonde recepten.', title_pl = 'Ból pleców mamy 🧘‍♀️', body_pl = 'Bolą cię plecy od noszenia go? Zadbaj o siebie i zaparz ze Zdrowych przepisów przeciwzapalną, regenerującą zieloną herbatę z imbirem.', title_pt = 'As dores de costas da mãe 🧘‍♀️', body_pt = 'As costas doem-lhe de tanto o pegar ao colo? Cuide do seu corpo com um chá verde com gengibre das Receitas Saudáveis, anti-inflamatório e reparador.', title_sv = 'Mammas ryggont 🧘‍♀️', body_sv = 'Gör ryggen ont av alla lyft? Brygg ett antiinflammatoriskt och återuppbyggande grönt te med ingefära från Hälsosamma recept och ta hand om kroppen.', title_vi = 'Mẹ bị đau lưng 🧘‍♀️', body_vi = 'Bế bé nhiều khiến mẹ đau lưng? Hãy pha trà xanh gừng chống viêm, giúp phục hồi từ Công thức lành mạnh để chăm sóc cơ thể mình.', title_zh = '妈妈的腰痛 🧘‍♀️', body_zh = '抱宝宝抱得腰疼？从健康食谱里泡一杯抗炎、帮助恢复的姜味绿茶，照顾好自己的身体。' WHERE id = '1221d1a0-4818-4be5-bd89-1e05d41e52f3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Pelea por el vaso equivocado? 🥤', body_es = '¿Se ha montado un drama porque le diste el agua en el vaso azul y no en el rojo? Pregunta ya a Anacan AI cómo resolver con calma estas rabietas que parecen absurdas.', title_fr = 'La crise du mauvais gobelet ? 🥤', body_fr = 'Tout a explosé parce que vous avez servi l''eau dans le gobelet bleu et pas le rouge ? Demandez tout de suite à Anacan AI comment gérer avec calme ces crises qui semblent absurdes.', title_hi = 'गलत गिलास पर झगड़ा? 🥤', body_hi = 'पानी लाल की जगह नीले गिलास में दिया तो तूफ़ान आ गया? ऐसे बेतुके लगने वाले नखरों को शांति से कैसे सुलझाएँ, यह तुरंत Anacan AI से पूछिए।', title_id = 'Drama gelas yang salah? 🥤', body_id = 'Kiamat kecil terjadi karena Anda memberi air di gelas biru, bukan merah? Segera tanyakan kepada Anacan AI cara menghadapi tantrum yang tampak absurd ini dengan tenang.', title_ja = '「コップがちがう！」の大騒ぎ？🥤', body_ja = 'お水を赤ではなく青いコップで出したら大騒ぎに？一見ばかげたようなこうしたかんしゃくに落ち着いて対応する方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '''잘못된 컵'' 소동? 🥤', body_ko = '빨간 컵이 아니라 파란 컵에 물을 줬다고 난리가 났나요? 이렇게 엉뚱해 보이는 떼쓰기를 침착하게 다루는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Strijd om de verkeerde beker? 🥤', body_nl = 'Brak de hel los omdat je water in de blauwe beker gaf in plaats van de rode? Vraag Anacan AI meteen hoe je zulke absurd lijkende buien kalm oplost.', title_pl = 'Wojna o zły kubek? 🥤', body_pl = 'Rozpętała się burza, bo dałaś wodę w niebieskim kubku, a nie w czerwonym? Od razu zapytaj Anacan AI, jak spokojnie radzić sobie z takimi pozornie absurdalnymi kryzysami.', title_pt = 'A guerra do copo errado? 🥤', body_pt = 'Foi o fim do mundo porque lhe deu água no copo azul e não no vermelho? Pergunte já ao Anacan AI como resolver com calma estas crises que parecem absurdas.', title_sv = 'Bråk om fel mugg? 🥤', body_sv = 'Brakade allt loss för att du gav vattnet i den blå muggen i stället för den röda? Fråga Anacan AI direkt hur du lugnt kan hantera sådana utbrott som verkar absurda.', title_vi = 'Cuộc chiến vì "nhầm cốc"? 🥤', body_vi = 'Mẹ đưa nước trong cốc xanh thay vì cốc đỏ và bé ăn vạ ầm ĩ? Hãy hỏi ngay Anacan AI cách bình tĩnh xử lý những cơn khủng hoảng tưởng như vô lý này.', title_zh = '杯子拿错了引发的战争？🥤', body_zh = '因为用蓝杯子而不是红杯子装水，就天塌了？马上问问Anacan AI，如何冷静应对这类看似荒唐的崩溃。' WHERE id = '5e592d03-eefe-420f-a53e-496dd3dda1cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Hoy no ha parado de llorar y estás agotada. No te juzgues. Escribe todo tu cansancio en el Diario de ánimo, vacía la mente y descansa.', body_fr = 'Il a pleuré sans arrêt aujourd''hui et vous êtes épuisée. Ne vous le reprochez pas. Videz-vous la tête en écrivant toute votre fatigue dans le Journal d''humeur, puis reposez-vous.', body_hi = 'आज वह लगातार रोया और आप बहुत थक गईं। खुद को कोसिए मत। मूड डायरी में अपनी सारी थकान लिखकर मन खाली कीजिए और आराम कीजिए।', body_id = 'Hari ini ia menangis tanpa henti dan Anda sangat lelah. Jangan menyalahkan diri sendiri. Tuliskan semua rasa lelah di Buku Harian Suasana Hati, kosongkan pikiran, dan beristirahatlah.', body_ja = '今日はずっと泣いていて、あなたもくたくたですね。自分を責めないで。「気分日記」に疲れをすべて書き出して、頭をからっぽにして休みましょう。', body_ko = '오늘 아이가 쉬지 않고 울어서 너무 지쳤나요? 자책하지 마세요. 기분 일기에 피로를 모두 적어 머리를 비우고 쉬세요.', body_nl = 'Huilde hij vandaag zonder ophouden en ben je erg moe? Veroordeel jezelf niet. Schrijf al je vermoeidheid op in je Stemmingsdagboek, maak je hoofd leeg en rust uit.', body_pl = 'Dziś płakał bez przerwy, a ty jesteś bardzo zmęczona. Nie obwiniaj się. Wypisz całe zmęczenie w Dzienniku nastroju, oczyść głowę i odpocznij.', body_pt = 'Hoje chorou sem parar e ficou muito cansada. Não se culpe. Escreva todo o seu cansaço no Diário de Humor, esvazie a cabeça e descanse.', body_sv = 'Barnet har gråtit oavbrutet i dag och du är väldigt trött. Döm inte dig själv. Skriv av dig all trötthet i Humördagboken, rensa tankarna och vila.', body_vi = 'Hôm nay bé khóc suốt và mẹ đã rất mệt. Đừng tự trách. Hãy viết hết mệt mỏi vào Nhật ký tâm trạng để đầu óc nhẹ nhõm và nghỉ ngơi.', body_zh = '今天宝宝哭个不停，你也累坏了。别责怪自己。把所有疲惫写进心情日记，清空大脑，好好休息。' WHERE id = '5fa9e0c4-2198-4898-832b-73dabf54c160' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño y sigue el gráfico. Quizá sea el momento de acortar la siesta 15 minutos.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil et suivez le graphique. C''est peut-être le bon moment pour raccourcir la sieste de 15 minutes.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 15 मिनट कम करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin inilah saatnya memangkas tidur siang 15 menit.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにして、グラフをチェックしましょう。お昼寝を15分短くするちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 15분 줄일 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan en volg de grafiek. Misschien is het precies tijd om het middagdutje met 15 minuten in te korten.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu i śledź wykres. Może to dobry moment, by skrócić drzemkę o 15 minut.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono e acompanhe o gráfico. Talvez seja a altura certa de encurtar a sesta 15 minutos.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern och följ grafen. Kanske är det precis rätt tid att korta dagsömnen med 15 minuter.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 15 phút.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器，看看图表。也许正是把白天小睡缩短15分钟的时候了。' WHERE id = 'd5617275-bfe2-4829-8f3f-d3b94dc34cfe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que cuente él el cuento 📖', body_es = '¿Mira los dibujos del libro y cuenta cosas en su propio idioma? Añade ya este momento de imaginación en vídeo con sonido al Álbum del bebé y guárdalo para el futuro.', title_fr = 'Laissez-le raconter l''histoire 📖', body_fr = 'Il regarde les images du livre et raconte des choses dans sa langue à lui ? Ajoutez tout de suite ce beau moment d''imagination en vidéo avec le son à l''Album de bébé pour le garder.', title_hi = 'कहानी उसे सुनाने दीजिए 📖', body_hi = 'किताब की तस्वीरें देखकर अपनी भाषा में कुछ बोलता है? कल्पना के इस शानदार पल को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़कर भविष्य के लिए सहेजिए।', title_id = 'Biarkan ia yang bercerita 📖', body_id = 'Ia melihat gambar di buku dan bercerita dengan bahasanya sendiri? Segera simpan momen imajinasi yang luar biasa ini sebagai video bersuara di Album Bayi untuk masa depan.', title_ja = 'お話はお子さんにおまかせ 📖', body_ja = '絵本の絵を見ながら、自分の言葉で何かお話ししていますか？このすばらしい想像力の瞬間を、すぐに音声付きの動画で「ベビーアルバム」に追加して、未来に残しましょう。', title_ko = '이야기는 아이가 들려줘요 📖', body_ko = '책 속 그림을 보며 자기만의 말로 무언가를 이야기하나요? 이 멋진 상상의 순간을 바로 소리가 담긴 영상으로 아기 앨범에 올려 간직하세요.', title_nl = 'Laat hem het verhaal vertellen 📖', body_nl = 'Kijkt hij naar de plaatjes in een boek en vertelt hij iets in zijn eigen taal? Zet dit prachtige fantasiemoment meteen als video met geluid in het Babyalbum en bewaar het voor later.', title_pl = 'Niech on opowie bajkę 📖', body_pl = 'Ogląda obrazki w książce i coś opowiada po swojemu? Od razu dodaj tę wspaniałą chwilę wyobraźni jako film z dźwiękiem do Albumu dziecka i zachowaj na przyszłość.', title_pt = 'Deixe-o contar a história 📖', body_pt = 'Olha para as imagens do livro e conta qualquer coisa na sua língua? Adicione já este momento maravilhoso de imaginação em vídeo com som ao Álbum do Bebé e guarde-o para o futuro.', title_sv = 'Låt barnet berätta sagan 📖', body_sv = 'Tittar barnet på bilderna i boken och berättar något på sitt eget språk? Spela in detta fantastiska fantasiögonblick som video med ljud, lägg det i Babyalbumet och spara det för framtiden.', title_vi = 'Để bé kể chuyện 📖', body_vi = 'Bé nhìn tranh trong sách và líu lo kể bằng ngôn ngữ của riêng mình? Hãy quay ngay video có tiếng khoảnh khắc tưởng tượng tuyệt vời này và lưu vào Album của bé.', title_zh = '让宝宝来讲故事 📖', body_zh = '看着书里的图画，用自己的语言说着什么？马上把这个了不起的想象时刻录成有声视频加进宝宝相册，留给未来。' WHERE id = '17a5c3c0-5b0c-46d3-a055-3e4119a58d57' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escapa de las cuatro paredes 🌳', body_es = '¿En casa no consigue gastar energía y lo desordena todo? Abre el mapa de Lugares para mamás, busca un parque con una zona segura para correr y salid a tomar aire fresco.', title_fr = 'Sortir de ses quatre murs 🌳', body_fr = 'Il ne peut pas se dépenser à la maison et met tout sens dessus dessous ? Ouvrez la carte des Lieux adaptés aux mamans, trouvez un parc avec un espace sûr pour courir et sortez prendre l''air.', title_hi = 'चार दीवारों से आज़ादी 🌳', body_hi = 'घर के अंदर ऊर्जा नहीं निकाल पाता और सब कुछ बिखेर देता है? माँ के लिए अनुकूल जगहें का नक्शा खोलिए, दौड़ने की सुरक्षित जगह वाला पार्क ढूँढिए और ताज़ी हवा में निकलिए।', title_id = 'Lepas dari empat dinding 🌳', body_id = 'Tak bisa menyalurkan energi di dalam rumah dan mengacak-acak segalanya? Buka peta Tempat Ramah Ibu, temukan taman dengan area lari yang aman, dan hirup udara segar.', title_ja = '4つの壁から脱出 🌳', body_ja = '家の中でエネルギーを発散できず、なんでも散らかしていますか？「ママにやさしいスポット」のマップを開いて、安全に走れる公園を見つけ、新鮮な空気を吸いに出かけましょう。', title_ko = '네 벽에서 탈출 🌳', body_ko = '집 안에서 에너지를 다 쓰지 못해 다 어지르나요? 엄마 친화 장소 지도를 열어 안전하게 뛸 수 있는 공원을 찾아 맑은 공기를 마시러 나가세요.', title_nl = 'Ontsnap aan de vier muren 🌳', body_nl = 'Kan hij binnen zijn energie niet kwijt en haalt hij alles overhoop? Open de kaart Mamavriendelijke plekken, zoek een park met een veilige renplek en ga naar buiten.', title_pl = 'Ucieczka z czterech ścian 🌳', body_pl = 'Nie może rozładować energii w domu i wszystko rozrzuca? Otwórz mapę Miejsc przyjaznych mamom, znajdź park z bezpiecznym miejscem do biegania i wyjdźcie na świeże powietrze.', title_pt = 'Fugir das quatro paredes 🌳', body_pt = 'Não consegue gastar energia em casa e desarruma tudo? Abra o mapa dos Locais Amigos das Mães, encontre um parque com espaço seguro para correr e vão apanhar ar puro.', title_sv = 'Bort från de fyra väggarna 🌳', body_sv = 'Kan barnet inte få ut energin inomhus och river ner allt? Öppna kartan i Mammavänliga platser, hitta en park med säker yta att springa på och gå ut i friska luften.', title_vi = 'Thoát khỏi bốn bức tường 🌳', body_vi = 'Bé không thể xả năng lượng trong nhà và bày bừa mọi thứ? Hãy mở bản đồ Địa điểm thân thiện với mẹ, tìm một công viên có khu chạy nhảy an toàn và ra ngoài hít thở không khí trong lành.', title_zh = '逃离四面墙 🌳', body_zh = '在家里释放不了精力，什么都弄得乱七八糟？打开妈妈友好场所地图，找一个有安全跑步区域的公园，出去呼吸新鲜空气。' WHERE id = '200bc386-90fc-4565-9a45-00b11604777d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere compartir? 🧸', body_es = '¿En el parque no le deja sus juguetes a nadie? Lee sin falta en el Blog el artículo práctico sobre cómo enseñar a respetar turnos a los niños de 22 meses.', title_fr = 'Il ne veut pas partager ? 🧸', body_fr = 'Au parc, il ne prête ses jouets à personne ? Lisez absolument l''article pratique de la rubrique Blogs qui explique comment apprendre à jouer chacun son tour à 22 mois.', title_hi = 'बाँटना नहीं चाहता? 🧸', body_hi = 'पार्क में किसी को खिलौना नहीं देता? ब्लॉग सेक्शन में 22 महीने के बच्चों को बारी-बारी से खेलना सिखाने वाला काम का लेख ज़रूर पढ़िए।', title_id = 'Tidak mau berbagi? 🧸', body_id = 'Di taman ia tidak mau meminjamkan mainan ke siapa pun? Baca artikel praktis di bagian Blog tentang cara mengajarkan konsep bergiliran kepada anak usia 22 bulan.', title_ja = '貸したくない？🧸', body_ja = '公園で誰にもおもちゃを貸さない？1歳10か月の子に「順番」を教える実践的な記事を、ブログでぜひ読んでみましょう。', title_ko = '나누기 싫어요? 🧸', body_ko = '공원에서 아무에게도 장난감을 안 주나요? 블로그에서 22개월 아이에게 차례 지키기를 가르치는 실용적인 글을 꼭 읽어 보세요.', title_nl = 'Wil hij niet delen? 🧸', body_nl = 'Geeft hij in het park niemand zijn speelgoed? Lees zeker het praktische artikel in Blogs over hoe je kinderen van 22 maanden leert om om de beurt te spelen.', title_pl = 'Nie chce się dzielić? 🧸', body_pl = 'W parku nikomu nie daje swoich zabawek? Koniecznie przeczytaj w sekcji Blog praktyczny artykuł o tym, jak nauczyć 22-miesięczne dziecko bawić się po kolei.', title_pt = 'Não quer partilhar? 🧸', body_pt = 'No parque não empresta os brinquedos a ninguém? Leia sem falta nos Blogues o artigo prático que ensina às crianças de 22 meses a ideia de brincar à vez.', title_sv = 'Vill inte dela? 🧸', body_sv = 'Ger barnet inte sina leksaker till någon i parken? Läs den praktiska artikeln i Bloggar om hur du lär barn på 22 månader att turas om.', title_vi = 'Bé không muốn chia sẻ? 🧸', body_vi = 'Ở công viên bé không đưa đồ chơi cho ai? Nhất định hãy đọc bài viết thực tế trong mục Blog về cách dạy trẻ 22 tháng biết chơi lần lượt.', title_zh = '不愿意分享？🧸', body_zh = '在公园谁都不给玩具？一定要读读博客板块里教22个月宝宝学会轮流玩的实用文章。' WHERE id = 'f2808bcb-7bbf-4422-8d7a-f49af045384f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de calcio 🦴', body_es = 'El calcio es imprescindible para huesos y dientes. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de yogur y queso.', title_fr = 'Bouclier calcium 🦴', body_fr = 'Le calcium est indispensable aux os et aux dents. Vérifiez avec le Suivi des repas qu''il a bien eu sa ration de yaourt et de fromage aujourd''hui.', title_hi = 'कैल्शियम की ढाल 🦴', body_hi = 'हड्डियों और दाँतों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज दही और पनीर की मात्रा पूरी हुई।', title_id = 'Perisai kalsium 🦴', body_id = 'Kalsium wajib untuk tulang dan gigi. Pastikan dengan alat Pemantau Nutrisi bahwa porsi yogurt dan keju hari ini sudah terpenuhi.', title_ja = 'カルシウムのシールド 🦴', body_ja = '骨と歯にはカルシウムが欠かせません。「栄養管理ツール」で、今日のヨーグルトやチーズの目安量をとれたか確認しましょう。', title_ko = '칼슘 방패 🦴', body_ko = '뼈와 치아에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 요거트와 치즈 기준량을 채웠는지 확인하세요.', title_nl = 'Calciumschild 🦴', body_nl = 'Calcium is onmisbaar voor botten en tanden. Check met de Voedingstracker of hij vandaag genoeg yoghurt en kaas heeft gehad.', title_pl = 'Tarcza z wapnia 🦴', body_pl = 'Wapń jest niezbędny dla kości i zębów. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja jogurtu i sera została osiągnięta.', title_pt = 'Escudo de cálcio 🦴', body_pt = 'O cálcio é indispensável para os ossos e os dentes. Confirme com o Registo de Alimentação que hoje cumpriu a dose de iogurte e queijo.', title_sv = 'Kalciumskölden 🦴', body_sv = 'Kalcium är ett måste för skelett och tänder. Kontrollera med Matningskoll att barnet fått dagens norm av yoghurt och ost.', title_vi = 'Lá chắn canxi 🦴', body_vi = 'Canxi rất cần cho xương và răng. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sữa chua, phô mai chưa.', title_zh = '钙的护盾 🦴', body_zh = '钙对骨骼和牙齿必不可少。用喂养记录工具确认今天酸奶、奶酪的参考量是否达到了。' WHERE id = '5ba12c84-c569-4cd8-9800-87090cc15d44' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le aprietan los zapatos? 📏', body_es = '¿Últimamente tropieza a menudo al correr? ¡Puede que le haya crecido el pie! Introduce su talla y medidas actuales en el Registro de peso y sigue su crecimiento físico.', title_fr = 'Ses chaussures le serrent ? 📏', body_fr = 'Il trébuche souvent en courant ces derniers temps ? Son pied a peut-être grandi ! Entrez sa taille et ses mesures actuelles dans le Suivi du poids et suivez son développement physique.', title_hi = 'जूते तंग हो रहे हैं? 📏', body_hi = 'आजकल दौड़ते समय अक्सर लड़खड़ाता है? शायद पैर बड़े हो गए हैं! वेट ट्रैकर में मौजूदा लंबाई और माप दर्ज कीजिए और शारीरिक विकास पर नज़र रखिए।', title_id = 'Sepatunya sesak? 📏', body_id = 'Akhir-akhir ini sering tersandung saat berlari? Kakinya mungkin sudah bertambah besar! Masukkan tinggi dan ukuran terbarunya ke Pelacak Berat Badan dan pantau pertumbuhan fisiknya.', title_ja = '靴がきつい？📏', body_ja = '最近、走るとよくつまずきますか？足が大きくなったのかもしれません！「体重トラッカー」に今の身長やサイズを入力して、体の成長を記録しましょう。', title_ko = '신발이 끼나요? 📏', body_ko = '요즘 뛰다가 자주 넘어지나요? 발이 자랐을 수도 있어요! 체중 기록에 현재 키와 치수를 입력하고 신체 발달을 지켜보세요.', title_nl = 'Knellen de schoenen? 📏', body_nl = 'Struikelt hij de laatste tijd vaak bij het rennen? Zijn voetjes kunnen gegroeid zijn! Voer zijn huidige lengte en maten in de Gewichtstracker in en volg zijn lichamelijke ontwikkeling.', title_pl = 'Buciki uciskają? 📏', body_pl = 'Ostatnio często potyka się podczas biegania? Może urosła mu stopa! Wpisz aktualny wzrost i wymiary w Liczniku wagi i śledź jego rozwój fizyczny.', title_pt = 'Os sapatos apertam? 📏', body_pt = 'Ultimamente tropeça muito quando corre? O pé pode ter crescido! Introduza a altura e as medidas atuais no Registo de Peso e acompanhe o crescimento físico.', title_sv = 'Klämmer skorna? 📏', body_sv = 'Snubblar barnet ofta när hen springer på sistone? Foten kan ha växt! Ange aktuell längd och mått i Viktspåraren och följ den fysiska utvecklingen.', title_vi = 'Giày bị chật? 📏', body_vi = 'Dạo này bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập chiều cao và số đo hiện tại vào Theo dõi cân nặng để theo sát sự phát triển thể chất.', title_zh = '鞋子挤脚了？📏', body_zh = '最近跑的时候经常绊倒？可能是脚长大了！在体重记录里输入当前的身高和尺寸，跟进身体发育情况。' WHERE id = '7ecc82ad-1a38-4c53-9465-dd5ae12ea103' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tira la comida al suelo? 🥣', body_es = 'Si empieza a tirar la cuchara y la comida de la mesa, está lleno o aburrido. Para el temporizador de tomas, analiza su apetito con el gráfico y da por terminada la comida.', title_fr = 'Il jette la nourriture par terre ? 🥣', body_fr = 'S''il commence à jeter la cuillère et la nourriture de la table, il n''a plus faim ou s''ennuie. Arrêtez le minuteur des repas, analysez son appétit sur le graphique et terminez le repas.', title_hi = 'खाना नीचे फेंकता है? 🥣', body_hi = 'अगर चम्मच और खाना मेज़ से नीचे फेंकने लगा है, तो उसका पेट भर गया है या वह ऊब गया है। फ़ीडिंग टाइमर रोकिए, चार्ट से भूख का रुझान देखिए और खाना खत्म कीजिए।', title_id = 'Membuang makanan ke lantai? 🥣', body_id = 'Jika ia mulai melempar sendok dan makanan dari meja, artinya ia sudah kenyang atau bosan. Hentikan Timer Makan, analisis nafsu makannya lewat grafik, dan akhiri waktu makan.', title_ja = '食べ物を床に投げる？🥣', body_ja = 'スプーンや食べ物をテーブルから落とし始めたら、おなかいっぱいか、飽きてしまったサインです。食事タイマーを止めて、グラフで食欲の変化を分析し、食事を終えましょう。', title_ko = '음식을 바닥에 던지나요? 🥣', body_ko = '숟가락과 음식을 식탁 아래로 던지기 시작했다면 배가 부르거나 지루한 거예요. 수유 타이머를 멈추고 그래프로 식욕의 변화를 분석한 뒤 식사를 마무리하세요.', title_nl = 'Gooit hij eten op de grond? 🥣', body_nl = 'Gooit hij de lepel en het eten van tafel? Dan zit hij vol of verveelt hij zich. Stop de Voedingstimer, analyseer zijn eetlust met de grafiek en rond de maaltijd af.', title_pl = 'Rzuca jedzenie na podłogę? 🥣', body_pl = 'Jeśli zaczął zrzucać łyżkę i jedzenie ze stołu, jest najedzony albo znudzony. Zatrzymaj timer karmienia, przeanalizuj apetyt na wykresie i zakończ posiłek.', title_pt = 'Atira a comida ao chão? 🥣', body_pt = 'Se começou a atirar a colher e a comida da mesa, está satisfeito ou aborrecido. Pare o temporizador de alimentação, analise no gráfico a evolução do apetite e termine a refeição.', title_sv = 'Kastar maten på golvet? 🥣', body_sv = 'Har barnet börjat kasta skeden och maten från bordet är hen mätt eller uttråkad. Stoppa matningstimern, analysera aptitens utveckling med grafen och avsluta måltiden.', title_vi = 'Bé ném thức ăn xuống sàn? 🥣', body_vi = 'Nếu bé bắt đầu ném thìa và thức ăn khỏi bàn, có lẽ bé đã no hoặc chán. Hãy dừng Hẹn giờ cho bú, phân tích khẩu vị qua biểu đồ và kết thúc bữa ăn.', title_zh = '把饭扔到地上？🥣', body_zh = '开始把勺子和饭从桌上往下扔，说明吃饱了或者烦了。停下喂养计时器，用图表分析食欲变化，结束这一餐吧。' WHERE id = 'd79dc60f-8bf8-4657-a15d-609886c6c332' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sensación de seguridad 🌌', body_es = '¿Le da miedo cuando apagas la luz? Pon el sonido del vientre materno (latido del corazón) de Ruido blanco, devuélvele aquella cálida sensación de seguridad y prepárale para dormir.', title_fr = 'Un sentiment de sécurité 🌌', body_fr = 'Il a peur quand vous éteignez la lumière ? Lancez le son du ventre maternel (battements de cœur) des Bruits blancs pour lui rendre ce doux sentiment de sécurité et l''aider à s''endormir.', title_hi = 'सुरक्षा का एहसास 🌌', body_hi = 'कमरे की बत्ती बुझाते ही डर जाता है? व्हाइट नॉइज़ में गर्भ की आवाज़ (दिल की धड़कन) चलाकर उसे वही पुरानी गर्माहट और सुरक्षा का एहसास दीजिए और नींद के लिए तैयार कीजिए।', title_id = 'Rasa aman 🌌', body_id = 'Takut saat lampu kamar dimatikan? Putar suara rahim (detak jantung) dari Suara Putih, beri ia rasa aman yang hangat dan akrab, lalu antar ia tidur.', title_ja = '安心できる気持ち 🌌', body_ja = '部屋の電気を消すとこわがりますか？「ホワイトノイズ」の胎内の音（心臓の音）を流して、なつかしい温かな安心感を届け、眠りへ導きましょう。', title_ko = '안정감 🌌', body_ko = '불을 끄면 무서워하나요? 백색소음에서 엄마 배 속 소리(심장 박동)를 틀어 익숙하고 따뜻한 안정감을 주며 잠들 준비를 도와주세요.', title_nl = 'Een veilig gevoel 🌌', body_nl = 'Is hij bang als het licht uitgaat? Zet het baarmoedergeluid (hartslag) uit Witte ruis aan, geef hem dat oude, warme gevoel van veiligheid en help hem in slaap.', title_pl = 'Poczucie bezpieczeństwa 🌌', body_pl = 'Boi się, gdy gasisz światło w pokoju? Włącz w Białym szumie odgłosy z brzucha mamy (bicie serca), daj mu znajome, ciepłe poczucie bezpieczeństwa i nastrój go do snu.', title_pt = 'Sensação de segurança 🌌', body_pt = 'Tem medo quando apaga a luz do quarto? Ligue no Ruído Branco o som do útero materno (batimento cardíaco), dê-lhe aquela antiga sensação quente de segurança e prepare-o para dormir.', title_sv = 'Känsla av trygghet 🌌', body_sv = 'Blir barnet rädd när du släcker ljuset i rummet? Sätt på ljudet från livmodern (hjärtslag) i Vitt brus, ge barnet den gamla varma känslan av trygghet och stäm för sömn.', title_vi = 'Cảm giác an toàn 🌌', body_vi = 'Bé sợ khi tắt đèn trong phòng? Hãy bật âm thanh trong bụng mẹ (tiếng tim đập) trong Tiếng ồn trắng để mang lại cảm giác an toàn ấm áp quen thuộc và đưa bé vào giấc ngủ.', title_zh = '安全感 🌌', body_zh = '关灯时会害怕？打开白噪音里的子宫声（心跳声），给宝宝熟悉而温暖的安全感，帮宝宝进入睡眠。' WHERE id = '596bb7f3-6693-46d8-ab7c-2abd702c9a04' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas vida social ☕', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás cafeterías infantiles donde se reúnen muchas madres y date un ambiente nuevo.', title_fr = 'Vous aussi, vous avez besoin de voir du monde ☕', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez dans les Lieux adaptés aux mamans des cafés pour enfants où les mamans se retrouvent, et changez d''air.', title_hi = 'आपको भी मेल-जोल चाहिए ☕', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में वे किड्स कैफ़े ढूँढिए जहाँ बहुत सी माँएँ आती हैं, और अपने लिए भी नया माहौल बनाइए।', title_id = 'Anda juga butuh bersosialisasi ☕', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan kafe anak tempat banyak ibu berkumpul di Tempat Ramah Ibu dan ciptakan suasana baru untuk diri Anda.', title_ja = 'あなたにも人との交流が必要です ☕', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」でママたちが集まるキッズカフェを見つけて、自分にも新しい環境をつくりましょう。', title_ko = '엄마에게도 어울림이 필요해요 ☕', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 엄마들이 많이 모이는 키즈 카페를 찾아 나에게도 새로운 분위기를 선물하세요.', title_nl = 'Jij hebt ook sociaal contact nodig ☕', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken kindercafés waar veel moeders komen en zorg ook voor jezelf voor een nieuwe omgeving.', title_pl = 'Ty też potrzebujesz towarzystwa ☕', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, w których spotyka się wiele mam, i zmień otoczenie.', title_pt = 'Também precisa de convívio ☕', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães cafés para crianças onde se juntam muitas mães e mude também de ambiente.', title_sv = 'Du behöver också umgås ☕', body_sv = 'Trött på att bara prata med barnet? Hitta barncaféer där många mammor samlas i Mammavänliga platser och ge dig själv en ny miljö.', title_vi = 'Mẹ cũng cần giao lưu ☕', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm những quán cà phê trẻ em nơi các mẹ hay gặp nhau trong Địa điểm thân thiện với mẹ và tạo cho mình một không gian mới.', title_zh = '你也需要社交 ☕', body_zh = '只和孩子说话说累了？在妈妈友好场所里找找妈妈们常聚的亲子咖啡馆，也给自己换个新环境。' WHERE id = '85644ffd-0693-4b98-8af6-f0210f7b50a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pegar o empujar 🛑', body_es = '¿Levanta la mano de repente cuando se enfada? Consulta a Anacan AI para aprender a cambiar con suavidad estas emociones agresivas propias de la edad convirtiéndolas en un juego.', title_fr = 'Taper ou pousser 🛑', body_fr = 'Il lève soudain la main quand il se fâche ? Consultez Anacan AI pour apprendre à transformer en jeu les émotions agressives de cet âge et les faire évoluer en douceur.', title_hi = 'मारना या धक्का देना 🛑', body_hi = 'गुस्से में अचानक हाथ उठाता है? इस उम्र की तेज़ होती भावनाओं को खेल बनाकर नरमी से कैसे बदलें, यह जानने के लिए Anacan AI से पूछिए।', title_id = 'Memukul atau mendorong 🛑', body_id = 'Tiba-tiba mengangkat tangan saat marah? Tanyakan kepada Anacan AI cara mengubah emosi agresif khas usia ini dengan lembut lewat permainan.', title_ja = 'たたく、押す 🛑', body_ja = '怒ると急に手が出ますか？この年齢の激しくなる気持ちを遊びに変えて、やさしく変えていく方法を、Anacan AIに相談して学びましょう。', title_ko = '때리거나 밀 때 🛑', body_ko = '화가 나면 갑자기 손을 드나요? 이 나이의 거칠어지는 감정을 놀이로 바꿔 부드럽게 다루는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Slaan of duwen 🛑', body_nl = 'Haalt hij ineens uit als hij boos is? Vraag Anacan AI hoe je de heftige emoties van deze leeftijd zacht verandert door er een spelletje van te maken.', title_pl = 'Bicie albo popychanie 🛑', body_pl = 'Gdy się złości, nagle podnosi rękę? Zapytaj Anacan AI, jak łagodnie zmienić te agresywne emocje typowe dla tego wieku, zamieniając je w zabawę.', title_pt = 'Bater ou empurrar 🛑', body_pt = 'Quando se zanga, levanta a mão de repente? Recorra ao Anacan AI para aprender a mudar com suavidade estas emoções agressivas típicas da idade, transformando-as num jogo.', title_sv = 'Slår eller knuffar 🛑', body_sv = 'Lyfter barnet plötsligt handen när hen blir arg? Vänd dig till Anacan AI för att lära dig hur du varsamt kan förändra den här ålderns allt starkare känslor genom att göra det till en lek.', title_vi = 'Đánh hoặc xô đẩy 🛑', body_vi = 'Bé bất ngờ vung tay khi tức giận? Hãy hỏi Anacan AI cách nhẹ nhàng thay đổi những cảm xúc ngày càng mạnh mẽ của lứa tuổi này bằng cách biến chúng thành trò chơi.', title_zh = '打人或推人 🛑', body_zh = '一生气就突然动手？向Anacan AI请教，学习如何把这个年龄越来越激烈的情绪变成游戏，温和地加以改变。' WHERE id = 'bafa81ec-ed9b-4642-a5cd-3249a43a8c84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Salto en la lógica 🧩', body_es = 'Ha empezado a entender la relación causa-efecto. Lee en el Blog los mejores juegos caseros para acelerar el desarrollo cognitivo a los 22 meses y ponlos en práctica.', title_fr = 'Un bond dans la logique 🧩', body_fr = 'Il commence à comprendre les liens de cause à effet. Lisez dans la rubrique Blogs les meilleurs jeux à la maison qui accélèrent le développement cognitif à 22 mois, et essayez-les.', title_hi = 'तर्क में छलांग 🧩', body_hi = 'वह कारण और नतीजे का रिश्ता समझने लगा है। ब्लॉग सेक्शन में 22 महीने के बच्चों की समझ का विकास तेज़ करने वाले सबसे अच्छे घरेलू खेल पढ़िए और आज़माइए।', title_id = 'Lompatan logika 🧩', body_id = 'Ia mulai memahami sebab-akibat. Baca dan praktikkan permainan rumahan terbaik yang mempercepat perkembangan kognitif anak usia 22 bulan di bagian Blog.', title_ja = '論理的な思考の飛躍 🧩', body_ja = '原因と結果のつながりを理解し始めています。1歳10か月の子の認知の発達を促す、いちばんいいおうち遊びをブログで読んで、試してみましょう。', title_ko = '논리의 도약 🧩', body_ko = '원인과 결과를 이해하기 시작했어요. 블로그에서 22개월 아이의 인지 발달을 앞당기는 최고의 집 놀이를 읽고 해 보세요.', title_nl = 'Logische sprong 🧩', body_nl = 'Hij begint oorzaak en gevolg te begrijpen. Lees in Blogs de beste spelletjes voor thuis die de cognitieve ontwikkeling van kinderen van 22 maanden versnellen, en probeer ze uit.', title_pl = 'Skok w logice 🧩', body_pl = 'Zaczyna rozumieć związek przyczyny i skutku. Przeczytaj w sekcji Blog o najlepszych domowych zabawach przyspieszających rozwój poznawczy 22-miesięcznych dzieci i wypróbuj je.', title_pt = 'Salto na lógica 🧩', body_pt = 'Começa a perceber a relação de causa e efeito. Leia nos Blogues e experimente os melhores jogos caseiros que aceleram o desenvolvimento cognitivo das crianças de 22 meses.', title_sv = 'Logiskt språng 🧩', body_sv = 'Barnet har börjat förstå orsak och verkan. Läs om de bästa lekarna hemma som snabbar på den kognitiva utvecklingen hos barn på 22 månader i Bloggar och prova dem.', title_vi = 'Bước nhảy vọt về tư duy 🧩', body_vi = 'Bé bắt đầu hiểu mối quan hệ nguyên nhân và kết quả. Hãy đọc trong mục Blog và thử những trò chơi tại nhà tốt nhất giúp thúc đẩy nhận thức của trẻ 22 tháng.', title_zh = '逻辑飞跃 🧩', body_zh = '宝宝开始理解因果关系了。去博客板块读读能促进22个月宝宝认知发展的最佳居家游戏，一起玩起来。' WHERE id = '1b86b21d-6e02-4ac7-a965-21bdbcf95db5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño y sigue el gráfico. Quizá sea el momento de acortar la siesta 15 minutos.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil et suivez le graphique. C''est peut-être le bon moment pour raccourcir la sieste de 15 minutes.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 15 मिनट कम करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin inilah saatnya memangkas tidur siang 15 menit.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにして、グラフをチェックしましょう。お昼寝を15分短くするちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 15분 줄일 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan en volg de grafiek. Misschien is het precies tijd om het middagdutje met 15 minuten in te korten.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu i śledź wykres. Może to dobry moment, by skrócić drzemkę o 15 minut.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono e acompanhe o gráfico. Talvez seja a altura certa de encurtar a sesta 15 minutos.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern och följ grafen. Kanske är det precis rätt tid att korta dagsömnen med 15 minuter.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 15 phút.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器，看看图表。也许正是把白天小睡缩短15分钟的时候了。' WHERE id = '6351737e-949c-4fb6-a2b3-5af919c832cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de las reservas de hierro 🥩', body_es = 'Unos músculos tan activos no pueden tener anemia. Comprueba con el Seguimiento de tomas el hierro de hoy y completa enseguida lo que falte.', title_fr = 'Contrôle des réserves de fer 🥩', body_fr = 'Pour des muscles actifs, il ne doit pas manquer de fer. Vérifiez avec le Suivi des repas ses apports en fer du jour et comblez tout de suite les manques.', title_hi = 'आयरन के भंडार की जाँच 🥩', body_hi = 'चंचल मांसपेशियों के लिए खून की कमी नहीं होनी चाहिए। फ़ीडिंग ट्रैकर से आज का आयरन जाँचिए और कमी तुरंत पूरी कीजिए।', title_id = 'Cek cadangan zat besi 🥩', body_id = 'Otot yang aktif tidak boleh kekurangan darah. Cek asupan zat besi hari ini dengan alat Pemantau Nutrisi dan segera lengkapi kekurangannya.', title_ja = '鉄分チェック 🥩', body_ja = '活発に動く筋肉のためには、貧血を防ぐことが大切です。「栄養管理ツール」で今日の鉄分の摂取量を確認し、足りない分をすぐに補いましょう。', title_ko = '철분 확인 🥩', body_ko = '활발한 근육을 위해 빈혈은 막아야 해요. 수유 기록 도구로 오늘의 철분 섭취를 확인하고 부족한 만큼 바로 채워 주세요.', title_nl = 'IJzervoorraad checken 🥩', body_nl = 'Voor actieve spieren mag er geen bloedarmoede zijn. Controleer met de Voedingstracker het ijzer van vandaag en vul tekorten meteen aan.', title_pl = 'Kontrola zapasu żelaza 🥩', body_pl = 'Aktywne mięśnie nie mogą cierpieć na anemię. Sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza i od razu uzupełnij braki.', title_pt = 'Verificar as reservas de ferro 🥩', body_pt = 'Músculos ativos não combinam com anemia. Verifique com o Registo de Alimentação o ferro de hoje e complete já o que faltar.', title_sv = 'Kontroll av järnförrådet 🥩', body_sv = 'Aktiva muskler behöver ett barn utan blodbrist. Kontrollera dagens järnintag med Matningskoll och fyll direkt på det som fattas.', title_vi = 'Kiểm tra kho sắt 🥩', body_vi = 'Để cơ bắp hoạt động tốt, bé không được thiếu máu. Hãy kiểm tra lượng sắt hôm nay bằng Theo dõi cữ bú và bổ sung ngay phần thiếu.', title_zh = '铁储备检查 🥩', body_zh = '为了肌肉活力十足，不能贫血。用喂养记录工具查看今天的铁摄入量，马上补足不够的部分。' WHERE id = 'f36fcaba-998e-48e4-a1c2-d085b47ccd2f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tentempié sin azúcar 🍪', body_es = 'No hacen falta galletas del súper. Descubre en Recetas para bebé dulces sanos caseros de dátiles y manzana que se preparan en 10 minutos y ábrele el apetito.', title_fr = 'En-cas sans sucre 🍪', body_fr = 'Pas besoin de biscuits du commerce. Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à la pomme, prêtes en 10 minutes, et ouvrez-lui l''appétit.', title_hi = 'बिना चीनी का स्नैक 🍪', body_hi = 'बाज़ार के बिस्किट की ज़रूरत नहीं। बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और सेब की सेहतमंद मिठाइयाँ खोजिए और उसकी भूख खोलिए।', title_id = 'Camilan tanpa gula 🍪', body_id = 'Tak perlu biskuit dari toko. Temukan camilan manis sehat dari kurma dan apel yang siap dalam 10 menit di Resep Bayi dan buka nafsu makannya.', title_ja = '砂糖不使用のおやつ 🍪', body_ja = '市販のクッキーはいりません。「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとりんごのヘルシーなおやつを見つけて、食欲を引き出しましょう。', title_ko = '설탕 없는 간식 🍪', body_ko = '마트 쿠키는 필요 없어요. 아기 레시피에서 집에서 10분이면 만드는 대추야자 사과 건강 간식을 찾아 입맛을 살려 주세요.', title_nl = 'Suikervrij tussendoortje 🍪', body_nl = 'Koekjes uit de winkel zijn niet nodig. Ontdek in Babyrecepten gezonde lekkernijen met dadels en appel, thuis klaar in 10 minuten, en maak hem hongerig.', title_pl = 'Przekąska bez cukru 🍪', body_pl = 'Sklepowe ciastka nie są potrzebne. Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i jabłkiem, które zrobisz w domu w 10 minut, i pobudź jego apetyt.', title_pt = 'Lanche sem açúcar 🍪', body_pt = 'Não precisa de bolachas do supermercado. Descubra nas Receitas para bebés doces saudáveis de tâmaras e maçã, feitos em casa em 10 minutos, e abra-lhe o apetite.', title_sv = 'Sockerfritt mellanmål 🍪', body_sv = 'Ni behöver inga kex från affären. Upptäck nyttiga sötsaker med dadlar och äpple som är klara på 10 minuter hemma i Recept för bebisar och väck aptiten.', title_vi = 'Món ăn vặt không đường 🍪', body_vi = 'Không cần bánh quy mua sẵn. Hãy khám phá các món ngọt bổ dưỡng từ chà là và táo làm tại nhà trong 10 phút trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '无糖小零食 🍪', body_zh = '不需要超市的饼干。在宝宝食谱里发现10分钟就能在家做好的椰枣苹果健康甜点，让宝宝胃口大开。' WHERE id = '04a88ead-f1bb-44fb-a8ea-9c02adfcfb9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón! 📏', body_es = '¿Las mangas vuelven a quedarle cortas? Su desarrollo físico se acelera. Introduce sus medidas actuales en el Seguimiento del desarrollo y mira con orgullo su curva de crecimiento.', title_fr = 'Poussée de croissance ! 📏', body_fr = 'Ses manches sont encore trop courtes ? Sa croissance physique s''accélère. Entrez ses mesures actuelles dans le Suivi de croissance et regardez fièrement sa courbe.', title_hi = 'लंबाई में उछाल! 📏', body_hi = 'कमीज़ की आस्तीनें फिर छोटी हो गईं? शारीरिक विकास तेज़ हो रहा है। ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और गर्व से ग्रोथ चार्ट देखिए।', title_id = 'Lonjakan tinggi badan! 📏', body_id = 'Lengan bajunya kependekan lagi? Pertumbuhan fisiknya makin cepat. Masukkan ukuran terbarunya ke Pelacak Perkembangan dan lihat grafik pertumbuhannya dengan bangga.', title_ja = '背がぐんと伸びた！📏', body_ja = 'シャツの袖がまた短くなりましたか？体の成長が加速しています。「発達トラッカー」に今のサイズを入力して、成長グラフを誇らしく眺めましょう。', title_ko = '키가 쑥! 📏', body_ko = '셔츠 소매가 또 짧아졌나요? 신체 발달이 빨라지고 있어요. 성장 기록에 현재 치수를 입력하고 성장 그래프를 뿌듯하게 확인하세요.', title_nl = 'Groeispurt! 📏', body_nl = 'Zijn de mouwen weer te kort? Hij groeit snel. Voer de huidige maten in de Groeitracker in en kijk trots naar zijn groeicurve.', title_pl = 'Skok wzrostowy! 📏', body_pl = 'Rękawy koszulek znów za krótkie? Rozwój fizyczny przyspiesza. Wpisz aktualne pomiary w Śledzeniu rozwoju i z dumą spójrz na wykres wzrostu.', title_pt = 'Salto de crescimento! 📏', body_pt = 'As mangas das camisolas voltaram a ficar curtas? O crescimento físico está a acelerar. Introduza as medidas atuais no Registo de Desenvolvimento e veja com orgulho o gráfico de crescimento.', title_sv = 'Längdspurt! 📏', body_sv = 'Har tröjärmarna blivit korta igen? Den fysiska utvecklingen går fortare. Ange aktuella mått i Utvecklingsspåraren och titta stolt på tillväxtkurvan.', title_vi = 'Bé cao vọt! 📏', body_vi = 'Tay áo lại ngắn rồi? Bé đang phát triển thể chất nhanh. Hãy nhập số đo hiện tại vào Theo dõi phát triển và tự hào ngắm biểu đồ tăng trưởng.', title_zh = '长个子啦！📏', body_zh = '衣袖又变短了？身体发育在加速。在发育追踪里输入当前的尺寸，骄傲地看看成长曲线。' WHERE id = '7b343e4c-3369-4f05-b976-97c243e8ed13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Llegan palabras nuevas! 🗣️', body_es = '¿Hace muchos sonidos pero aún no dice palabras completas? Para activar su vocabulario pasivo, añade estos graciosos intentos de sílabas con sonido al Álbum del bebé y sigue su evolución.', title_fr = 'De nouveaux mots arrivent ! 🗣️', body_fr = 'Il fait plein de sons mais ne dit pas encore de vrais mots ? Pour activer son vocabulaire passif, ajoutez ces drôles d''essais de syllabes en audio à l''Album de bébé et suivez ses progrès.', title_hi = 'नए शब्द आ रहे हैं! 🗣️', body_hi = 'बहुत आवाज़ें निकालता है, पर पूरा शब्द नहीं बोलता? समझे हुए शब्दों को बोलने तक लाने के लिए अक्षरों की इन मज़ेदार कोशिशों को आवाज़ के साथ बेबी एल्बम में जोड़िए और नज़र रखिए।', title_id = 'Kata-kata baru segera hadir! 🗣️', body_id = 'Banyak bersuara tapi belum mengucapkan kata utuh? Rekam usaha mengucapkan suku kata yang lucu ini dalam bentuk suara di Album Bayi dan pantau kosakata pasifnya menjadi aktif.', title_ja = '新しい言葉がやってくる！🗣️', body_ja = 'たくさん声を出すけれど、まだはっきりした言葉にならない？わかる言葉を話せる言葉に変えていくために、このおもしろい音節の挑戦を音声付きで「ベビーアルバム」に追加して、見守りましょう。', title_ko = '새로운 단어가 와요! 🗣️', body_ko = '소리는 많이 내는데 온전한 단어는 아직인가요? 알아듣는 어휘가 말로 나오도록, 이 귀여운 옹알이 시도를 소리와 함께 아기 앨범에 올리고 지켜보세요.', title_nl = 'Nieuwe woorden komen eraan! 🗣️', body_nl = 'Maakt hij veel geluidjes, maar zegt hij nog geen hele woorden? Zet deze grappige lettergreeppogingen met geluid in het Babyalbum en volg hoe zijn passieve woordenschat actief wordt.', title_pl = 'Nadchodzą nowe słowa! 🗣️', body_pl = 'Wydaje mnóstwo dźwięków, ale nie mówi jeszcze całych słów? Dodaj te zabawne próby sylab jako nagrania z dźwiękiem do Albumu dziecka i obserwuj, jak bierny słownik staje się czynny.', title_pt = 'Aí vêm palavras novas! 🗣️', body_pt = 'Faz muitos sons, mas ainda não diz palavras completas? Para ativar o vocabulário passivo, adicione estas tentativas engraçadas de sílabas em áudio ao Álbum do Bebé e acompanhe-as.', title_sv = 'Nya ord på väg! 🗣️', body_sv = 'Låter barnet mycket men säger inte riktiga ord? Spara de roliga stavelseförsöken med ljud i Babyalbumet och följ hur det passiva ordförrådet blir aktivt.', title_vi = 'Từ mới đang đến! 🗣️', body_vi = 'Bé phát ra nhiều âm nhưng chưa nói được từ hoàn chỉnh? Hãy ghi lại những lần tập phát âm ngộ nghĩnh này bằng video có tiếng trong Album của bé để theo dõi vốn từ thụ động được kích hoạt.', title_zh = '新词要来了！🗣️', body_zh = '发出很多声音，但还说不出完整的词？为了激活被动词汇，把这些有趣的音节尝试录下声音加进宝宝相册，跟踪进展。' WHERE id = '7c55b3cc-0f0f-47b0-8148-d026b3b7590e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ayudante de limpieza 🧹', body_es = 'Ya quiere participar en las tareas de casa. Lee en el Blog cómo inculcar el sentido de la responsabilidad jugando a un niño de 22,5 meses y ponlo en práctica.', title_fr = 'Petit assistant ménage 🧹', body_fr = 'Il veut déjà participer aux tâches ménagères. Lisez dans la rubrique Blogs comment lui transmettre le sens des responsabilités par le jeu à 22,5 mois, et essayez.', title_hi = 'सफ़ाई का मददगार 🧹', body_hi = 'वह अब घर के कामों में हाथ बँटाना चाहता है। ब्लॉग सेक्शन में पढ़िए कि 22.5 महीने के बच्चे में खेल-खेल में ज़िम्मेदारी की भावना कैसे जगाएँ, और आज़माइए।', title_id = 'Asisten bersih-bersih 🧹', body_id = 'Ia sudah ingin ikut mengerjakan pekerjaan rumah. Baca dan praktikkan di bagian Blog cara menanamkan rasa tanggung jawab lewat permainan pada anak usia 22,5 bulan.', title_ja = 'お掃除のお手伝いさん 🧹', body_ja = 'もう家事に参加したがっています。1歳10か月半の子に、遊びを通して責任感を育てる方法をブログで読んで、試してみましょう。', title_ko = '청소 도우미 🧹', body_ko = '벌써 집안일을 돕고 싶어 해요. 22.5개월 아이에게 놀이로 책임감을 길러 주는 방법을 블로그에서 읽고 해 보세요.', title_nl = 'Hulpje bij het schoonmaken 🧹', body_nl = 'Hij wil al meehelpen in huis. Lees in Blogs hoe je een kind van 22,5 maand spelenderwijs verantwoordelijkheid leert, en probeer het uit.', title_pl = 'Mały pomocnik w sprzątaniu 🧹', body_pl = 'Już chce pomagać w domowych obowiązkach. Przeczytaj w sekcji Blog, jak poprzez zabawę zaszczepić 22,5-miesięcznemu dziecku poczucie odpowiedzialności, i wypróbuj to.', title_pt = 'Ajudante das limpezas 🧹', body_pt = 'Já quer participar nas tarefas da casa. Leia nos Blogues como incutir, a brincar, o sentido de responsabilidade numa criança de 22,5 meses e ponha-o em prática.', title_sv = 'Städhjälpen 🧹', body_sv = 'Barnet vill redan vara med i hushållssysslorna. Läs i Bloggar hur du med lek väcker ansvarskänsla hos ett barn på 22,5 månader och prova.', title_vi = 'Trợ thủ dọn dẹp 🧹', body_vi = 'Bé đã muốn tham gia việc nhà. Hãy đọc trong mục Blog cách nuôi dưỡng tinh thần trách nhiệm qua trò chơi cho trẻ 22,5 tháng và áp dụng nhé.', title_zh = '打扫小帮手 🧹', body_zh = '宝宝已经想参与家务了。去博客板块读读如何通过游戏培养22.5个月宝宝的责任感，一起试试吧。' WHERE id = '614145be-ebb6-498c-9b3f-26a829cb6b6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La imaginación no tiene límites 🧸', body_es = '¿Le da de comer a su osito o te cura a ti? Añade este desarrollo de la empatía en un vídeo corto al Álbum del bebé y crea un recuerdo para siempre.', title_fr = 'Une imagination sans limites 🧸', body_fr = 'Il donne à manger à son nounours ou vous soigne ? Ajoutez cette belle empathie naissante en courte vidéo à l''Album de bébé pour en faire un souvenir pour la vie.', title_hi = 'कल्पना की कोई सीमा नहीं 🧸', body_hi = 'अपने भालू को खाना खिलाता है या आपका इलाज करता है? हमदर्दी के इस विकास को छोटे वीडियो के रूप में बेबी एल्बम में जोड़िए और उम्रभर की याद बनाइए।', title_id = 'Imajinasi tanpa batas 🧸', body_id = 'Ia menyuapi boneka beruangnya, atau mengobati Anda? Simpan perkembangan empati ini sebagai video pendek di Album Bayi dan ciptakan kenangan seumur hidup.', title_ja = '想像力に限界はない 🧸', body_ja = 'くまさんにごはんを食べさせたり、あなたを手当てしてくれたり？この思いやりの発達を短い動画で「ベビーアルバム」に追加して、一生の思い出にしましょう。', title_ko = '상상력에는 끝이 없어요 🧸', body_ko = '곰 인형에게 밥을 먹이거나 엄마를 치료해 주나요? 이 공감 능력의 발달을 짧은 영상으로 아기 앨범에 올려 평생의 추억을 만드세요.', title_nl = 'Fantasie kent geen grenzen 🧸', body_nl = 'Geeft hij zijn beer te eten of verzorgt hij jou? Zet deze groeiende empathie als korte video in het Babyalbum en maak er een herinnering voor altijd van.', title_pl = 'Wyobraźnia nie zna granic 🧸', body_pl = 'Karmi misia albo cię „leczy”? Dodaj ten rozwój empatii jako krótki film do Albumu dziecka i stwórz pamiątkę na całe życie.', title_pt = 'A imaginação não tem limites 🧸', body_pt = 'Dá de comer ao ursinho ou faz de conta que a trata? Adicione este desenvolvimento da empatia num pequeno vídeo ao Álbum do Bebé e crie uma recordação para a vida.', title_sv = 'Fantasin har inga gränser 🧸', body_sv = 'Matar barnet nallen eller låtsas behandla dig? Lägg till denna empatiutveckling som en kort video i Babyalbumet och skapa ett minne för livet.', title_vi = 'Trí tưởng tượng không có giới hạn 🧸', body_vi = 'Bé đút cho gấu bông ăn hay "chữa bệnh" cho mẹ? Hãy quay video ngắn về sự phát triển lòng đồng cảm này và thêm vào Album của bé làm kỷ niệm trọn đời.', title_zh = '想象力没有边界 🧸', body_zh = '给小熊喂饭，或者给你“看病”？把这种共情能力的发展拍成短视频加进宝宝相册，留下一生的回忆。' WHERE id = '6d017679-be1f-4b11-b8fd-36574013a33a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exploraciones seguras ⚠️', body_es = 'Armarios, cajones... ¡Peligro para un pequeño explorador! Echa un vistazo sin falta en Productos recomendados a los protectores de muebles y cierres de seguridad.', title_fr = 'Explorer en sécurité ⚠️', body_fr = 'Placards, tiroirs... Dangereux pour un petit explorateur ! Jetez absolument un œil aux protections de meubles et aux verrous de sécurité dans les Produits recommandés.', title_hi = 'सुरक्षित खोज ⚠️', body_hi = 'अलमारियाँ, दराज़ें... नन्हे खोजी के लिए खतरनाक हैं! सुझाए गए प्रोडक्ट में फ़र्नीचर गार्ड और सेफ़्टी लॉक ज़रूर देखिए।', title_id = 'Penjelajahan yang aman ⚠️', body_id = 'Lemari, laci... Berbahaya bagi si penjelajah! Pastikan melihat pengaman furnitur dan kunci pengaman di Produk Rekomendasi.', title_ja = '安全な探検 ⚠️', body_ja = '戸棚、引き出し…小さな探検家には危険がいっぱい！「おすすめ商品」で家具の転倒防止グッズやチャイルドロックをぜひチェックしましょう。', title_ko = '안전한 탐험 ⚠️', body_ko = '옷장, 서랍... 꼬마 탐험가에게는 위험해요! 추천 제품에서 가구 전도 방지 장치와 안전 잠금장치를 꼭 살펴보세요.', title_nl = 'Veilig ontdekken ⚠️', body_nl = 'Kasten, laden... Gevaarlijk voor een ontdekkingsreiziger! Bekijk zeker meubelbeveiligingen en veiligheidssloten in Aanbevolen producten.', title_pl = 'Bezpieczne odkrywanie ⚠️', body_pl = 'Szafki, szuflady... Dla małego odkrywcy to niebezpieczne! Koniecznie zajrzyj w Polecanych produktach do zabezpieczeń mebli i blokad.', title_pt = 'Descobertas em segurança ⚠️', body_pt = 'Armários, gavetas... São perigosos para um explorador! Espreite sem falta nos Produtos Recomendados os protetores de móveis e as trancas de segurança.', title_sv = 'Säkra upptäckter ⚠️', body_sv = 'Skåp, lådor... Farligt för en upptäcktsresande! Glöm inte att titta på möbelskydd och säkerhetslås i Rekommenderade produkter.', title_vi = 'Khám phá an toàn ⚠️', body_vi = 'Tủ, ngăn kéo... Thật nguy hiểm với nhà thám hiểm nhí! Nhất định hãy xem các miếng bảo vệ góc đồ đạc và khóa an toàn trong Sản phẩm gợi ý.', title_zh = '安全地探索 ⚠️', body_zh = '柜子、抽屉……对小探险家来说很危险！一定要去推荐商品看看家具防护角和安全锁。' WHERE id = 'f542a783-2187-4790-b865-10366397c49d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Obra de arte en la pared 🎨', body_es = '¿Ha cogido un bolígrafo y ha pintado la pared? ¡No te enfades! Añade esta dulce travesura al álbum con los marcos divertidos de la Sesión de fotos del bebé y simplemente sonríe.', title_fr = 'Une œuvre d''art sur le mur 🎨', body_fr = 'Il a pris un stylo et dessiné sur le mur ? Ne vous énervez pas ! Ajoutez cette mignonne bêtise à l''album avec les cadres rigolos de la Séance photo bébé, et souriez simplement.', title_hi = 'दीवार पर कलाकृति 🎨', body_hi = 'पेन लेकर दीवार रंग दी? गुस्सा मत होइए! इस प्यारी शरारत को बेबी फ़ोटोशूट के मज़ेदार फ़्रेम के साथ एल्बम में जोड़िए और बस मुस्कुराइए।', title_id = 'Karya seni di dinding 🎨', body_id = 'Ia mengambil pulpen dan mencoret dinding? Jangan kesal! Tambahkan kenakalan manis ini ke album dengan bingkai lucu dari Sesi Foto Bayi, dan tersenyumlah.', title_ja = '壁の上の芸術作品 🎨', body_ja = 'ペンを手に取って壁に描いてしまいましたか？怒らないで！このかわいいいたずらを、「ベビーフォトセッション」のおもしろいフレームでアルバムに追加して、ただほほえみましょう。', title_ko = '벽 위의 예술 작품 🎨', body_ko = '펜을 들고 벽에 그림을 그렸나요? 화내지 마세요! 이 귀여운 장난을 아기 사진 촬영의 재미있는 프레임으로 앨범에 담고 그냥 웃어 주세요.', title_nl = 'Kunstwerk op de muur 🎨', body_nl = 'Heeft hij met een pen op de muur getekend? Word niet boos! Zet deze lieve ondeugd met grappige kaders uit Babyfotoshoot in het album en glimlach gewoon.', title_pl = 'Dzieło sztuki na ścianie 🎨', body_pl = 'Wziął długopis i pomalował ścianę? Nie denerwuj się! Dodaj tę słodką psotę do albumu z zabawnymi ramkami z Sesji zdjęciowej dziecka i po prostu się uśmiechnij.', title_pt = 'Uma obra de arte na parede 🎨', body_pt = 'Pegou numa caneta e pintou a parede? Não se enerve! Adicione esta traquinice tão doce ao álbum com as molduras engraçadas da Sessão Fotográfica do Bebé e limite-se a sorrir.', title_sv = 'Konstverk på väggen 🎨', body_sv = 'Tog barnet en penna och målade på väggen? Bli inte irriterad! Lägg till det söta busstreck i albumet med roliga ramar i Babyfotografering och le bara.', title_vi = 'Tác phẩm nghệ thuật trên tường 🎨', body_vi = 'Bé cầm bút vẽ lên tường? Đừng bực mình! Hãy thêm trò nghịch ngợm đáng yêu này vào album với khung ảnh ngộ nghĩnh trong Chụp ảnh cho bé và cứ mỉm cười thôi.', title_zh = '墙上的艺术作品 🎨', body_zh = '拿起笔就在墙上画画？别生气！用宝宝写真里的搞笑相框把这个可爱的淘气瞬间加进相册，笑一笑就好。' WHERE id = '1a8b991b-0214-44d5-b2fa-cca54722c709' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelven los despertares repentinos? ⏱️', body_es = '¿Se despierta llorando a medianoche? Mira el gráfico del temporizador de sueño. Si la siesta termina muy tarde, le cuesta más entrar en sueño profundo por la noche.', title_fr = 'Les réveils soudains sont de retour ? ⏱️', body_fr = 'Il se réveille en pleurant au milieu de la nuit ? Regardez le graphique du minuteur de sommeil. Si la sieste finit trop tard, il a plus de mal à plonger dans un sommeil profond le soir.', title_hi = 'अचानक जागना फिर शुरू? ⏱️', body_hi = 'आधी रात को रोते हुए जागता है? स्लीप टाइमर का चार्ट देखिए। अगर दिन की नींद बहुत देर से खत्म होती है, तो शाम को गहरी नींद में जाना मुश्किल हो जाता है।', title_id = 'Tiba-tiba sering terbangun lagi? ⏱️', body_id = 'Terbangun sambil menangis di tengah malam? Lihat grafik Timer Tidur. Jika tidur siangnya berakhir terlalu sore, ia akan sulit masuk ke tidur nyenyak di malam hari.', title_ja = '急に起きるのが復活？⏱️', body_ja = '夜中に泣いて起きますか？睡眠タイマーのグラフを見てみましょう。お昼寝の終わりが遅すぎると、夜に深い眠りへ入りにくくなります。', title_ko = '갑자기 다시 깨나요? ⏱️', body_ko = '한밤중에 울면서 깨나요? 수면 타이머 그래프를 살펴보세요. 낮잠이 너무 늦게 끝나면 밤에 깊은 잠으로 넘어가기 어려워요.', title_nl = 'Wordt hij weer plotseling wakker? ⏱️', body_nl = 'Wordt hij midden in de nacht huilend wakker? Bekijk de grafiek van de Slaaptimer. Eindigt het middagdutje te laat, dan valt hij ''s avonds moeilijker in een diepe slaap.', title_pl = 'Nagłe pobudki wróciły? ⏱️', body_pl = 'Budzi się z płaczem w środku nocy? Spójrz na wykres timera snu. Jeśli drzemka kończy się zbyt późno, wieczorem trudniej mu przejść w głęboki sen.', title_pt = 'Os despertares repentinos voltaram? ⏱️', body_pt = 'Acorda a chorar a meio da noite? Veja o gráfico do temporizador de sono. Se a sesta acaba muito tarde, à noite fica mais difícil entrar no sono profundo.', title_sv = 'Plötsliga uppvaknanden igen? ⏱️', body_sv = 'Vaknar barnet gråtande mitt i natten? Titta på grafen i sömntimern. Om dagsömnen slutar för sent blir det svårare att sjunka in i djup sömn på kvällen.', title_vi = 'Lại thức giấc đột ngột? ⏱️', body_vi = 'Bé khóc thức giấc lúc nửa đêm? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Nếu giấc ngủ ngày kết thúc quá muộn, buổi tối bé sẽ khó vào giấc ngủ sâu.', title_zh = '突然醒来又回来了？⏱️', body_zh = '半夜哭着醒来？看看睡眠计时器的图表。如果白天小睡结束得太晚，晚上就很难进入深度睡眠。' WHERE id = '5ded1b01-b65d-40da-8990-d4cd09688a69' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pausa del café de mamá ☕', body_es = '¡No te olvides de ti! Prepara en Recetas saludables para mujeres un tentempié de avena que te suba la energía y disfruta de tu café.', title_fr = 'La pause café de maman ☕', body_fr = 'Ne vous oubliez pas ! Préparez un en-cas à l''avoine énergisant avec les Recettes saines pour femmes et savourez votre café.', title_hi = 'माँ का कॉफ़ी ब्रेक ☕', body_hi = 'खुद को मत भूलिए! महिलाओं के लिए सेहतमंद रेसिपी से ऊर्जा बढ़ाने वाला ओट्स स्नैक बनाइए और अपनी कॉफ़ी का मज़ा लीजिए।', title_id = 'Rehat kopi Bunda ☕', body_id = 'Jangan lupakan diri Anda! Buat camilan oat penambah energi dari Resep Sehat untuk wanita dan nikmati kopi Anda.', title_ja = 'ママのコーヒーブレイク ☕', body_ja = '自分のことも忘れないで！「女性のためのヘルシーレシピ」から元気が出るオートミールのおやつをつくって、コーヒーを味わいましょう。', title_ko = '엄마의 커피 타임 ☕', body_ko = '엄마 자신을 잊지 마세요! 여성을 위한 건강한 레시피에서 기운을 북돋는 귀리 간식을 만들어 커피와 함께 즐기세요.', title_nl = 'Koffiepauze voor mama ☕', body_nl = 'Vergeet jezelf niet! Maak uit Gezonde recepten voor vrouwen een havertussendoortje dat je energie geeft, en geniet van je koffie.', title_pl = 'Kawowa przerwa mamy ☕', body_pl = 'Nie zapominaj o sobie! Przygotuj ze Zdrowych przepisów dla kobiet owsianą przekąskę, która doda ci energii, i delektuj się kawą.', title_pt = 'A pausa para o café da mãe ☕', body_pt = 'Não se esqueça de si! Prepare nas Receitas Saudáveis para Mulheres um lanche de aveia que lhe levante a energia e saboreie o seu café.', title_sv = 'Mammas kaffepaus ☕', body_sv = 'Glöm inte bort dig själv! Gör ett mellanmål med havre som höjer energin från Hälsosamma recept för kvinnor och njut av ditt kaffe.', title_vi = 'Giờ cà phê của mẹ ☕', body_vi = 'Đừng quên bản thân! Hãy làm món ăn nhẹ từ yến mạch giúp tăng năng lượng từ Công thức lành mạnh cho phụ nữ và thưởng thức ly cà phê của mình.', title_zh = '妈妈的咖啡时间 ☕', body_zh = '别忘了你自己！从女性健康食谱里做一份提升精力的燕麦小零食，好好享受你的咖啡吧。' WHERE id = '79c4c89f-ba17-4c97-96b0-f5dc444414e9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Elegir bien el orinal 🚽', body_es = '¡Que empiece la preparación visual para dejar el pañal! Echa un vistazo sin falta en Productos recomendados a los orinales más cómodos y atractivos probados por otras madres.', title_fr = 'Bien choisir son pot 🚽', body_fr = 'Place à la préparation visuelle pour la propreté ! Jetez absolument un œil aux pots les plus confortables et attrayants, testés par des mamans, dans les Produits recommandés.', title_hi = 'पॉटी के लिए सही चुनाव 🚽', body_hi = 'टॉयलेट ट्रेनिंग की देखकर सीखने वाली तैयारी शुरू हो! सुझाए गए प्रोडक्ट में माँओं की आज़माई सबसे आरामदायक और आकर्षक पॉटी ज़रूर देखिए।', title_id = 'Pilihan pispot yang tepat 🚽', body_id = 'Saatnya persiapan visual untuk latihan toilet! Lihat model pispot paling nyaman dan menarik yang sudah dicoba para ibu di Produk Rekomendasi.', title_ja = 'おまる選びは大切 🚽', body_ja = 'トイレトレーニングの目で見る準備を始めましょう！「おすすめ商品」で、ママたちが試した、いちばん使いやすくて魅力的なおまるをぜひチェックしましょう。', title_ko = '배변 훈련용 변기 고르기 🚽', body_ko = '배변 훈련을 위한 눈으로 익히기를 시작해요! 추천 제품에서 엄마들이 직접 써 본 가장 편하고 매력적인 유아 변기를 꼭 살펴보세요.', title_nl = 'Het juiste potje kiezen 🚽', body_nl = 'Laat de visuele voorbereiding op de zindelijkheid beginnen! Bekijk zeker in Aanbevolen producten de comfortabelste en leukste potjes die door moeders zijn getest.', title_pl = 'Właściwy wybór nocnika 🚽', body_pl = 'Czas na wizualne przygotowanie do nauki korzystania z toalety! Koniecznie zajrzyj w Polecanych produktach do najwygodniejszych i najbardziej zachęcających nocników sprawdzonych przez mamy.', title_pt = 'A escolha certa de bacio 🚽', body_pt = 'Comece a preparação visual para deixar a fralda! Espreite sem falta nos Produtos Recomendados os modelos de bacio mais confortáveis e apelativos, testados pelas mães.', title_sv = 'Rätt val av potta 🚽', body_sv = 'Låt den visuella förberedelsen för toaträning börja! Titta på de bekvämaste och mest lockande pottorna som mammor testat i Rekommenderade produkter.', title_vi = 'Chọn bô phù hợp 🚽', body_vi = 'Hãy bắt đầu chuẩn bị cho bé tập đi vệ sinh bằng hình ảnh! Nhất định hãy xem những mẫu bô thoải mái và hấp dẫn nhất đã được các mẹ dùng thử trong Sản phẩm gợi ý.', title_zh = '选对便盆 🚽', body_zh = '开始为如厕训练做视觉上的准备吧！一定要去推荐商品看看妈妈们试用过的最舒适、最吸引人的便盆款式。' WHERE id = '178de938-0734-4759-bd61-91671bd355ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal su reserva de omega-3? 🐟', body_es = '¡El pescado o las nueces son imprescindibles para un desarrollo cerebral tan rápido! Comprueba con el Seguimiento de tomas el omega-3 de esta semana y actualiza su menú enseguida.', title_fr = 'Où en sont ses oméga-3 ? 🐟', body_fr = 'Poisson ou noix sont indispensables au développement rapide du cerveau ! Vérifiez avec le Suivi des repas ses apports en oméga-3 de la semaine et mettez tout de suite son menu à jour.', title_hi = 'ओमेगा-3 का भंडार कैसा है? 🐟', body_hi = 'दिमाग के तेज़ विकास के लिए मछली या अखरोट ज़रूरी हैं! फ़ीडिंग ट्रैकर से इस हफ़्ते का ओमेगा-3 जाँचिए और मेन्यू तुरंत अपडेट कीजिए।', title_id = 'Bagaimana cadangan omega-3-nya? 🐟', body_id = 'Ikan atau kenari wajib untuk perkembangan otak yang pesat! Cek asupan omega-3 minggu ini dengan alat Pemantau Nutrisi dan segera perbarui menunya.', title_ja = 'オメガ3はとれている？🐟', body_ja = '急速な脳の発達には、お魚やくるみが欠かせません！「栄養管理ツール」で今週のオメガ3の摂取量を確認して、すぐにメニューを見直しましょう。', title_ko = '오메가3는 충분한가요? 🐟', body_ko = '빠른 두뇌 발달에는 생선이나 호두가 꼭 필요해요! 수유 기록 도구로 이번 주 오메가3 섭취를 확인하고 식단을 바로 업데이트하세요.', title_nl = 'Hoe staat het met omega-3? 🐟', body_nl = 'Vis of walnoten zijn onmisbaar voor een snelle hersenontwikkeling! Controleer met de Voedingstracker de omega-3 van deze week en pas het menu meteen aan.', title_pl = 'Jak tam zapas omega-3? 🐟', body_pl = 'Ryby lub orzechy są niezbędne dla szybkiego rozwoju mózgu! Sprawdź w narzędziu do śledzenia karmienia spożycie omega-3 w tym tygodniu i od razu odśwież menu.', title_pt = 'Como estão as reservas de ómega-3? 🐟', body_pt = 'Para um desenvolvimento rápido do cérebro, peixe ou nozes são indispensáveis! Verifique com o Registo de Alimentação o ómega-3 desta semana e atualize já a ementa.', title_sv = 'Hur är det med omega-3? 🐟', body_sv = 'Fisk eller nötter är ett måste för hjärnans snabba utveckling! Kontrollera veckans intag av omega-3 med Matningskoll och uppdatera menyn direkt.', title_vi = 'Lượng omega-3 thế nào rồi? 🐟', body_vi = 'Cá hoặc óc chó rất cần cho não bộ phát triển nhanh! Hãy kiểm tra lượng omega-3 tuần này bằng Theo dõi cữ bú và làm mới thực đơn ngay.', title_zh = '欧米伽-3储备怎么样？🐟', body_zh = '大脑快速发育离不开鱼或核桃！用喂养记录工具查看这周的欧米伽-3摄入量，马上更新菜单。' WHERE id = '2f6cc31a-8b1b-415e-861a-b476799ab26e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No tienes por qué ser perfecta 💖', body_es = '¿Hoy la casa está patas arriba y la comida se ha retrasado? ¡No pasa nada! Escribe tu voz interior en el Diario de ánimo y recuerda que tu peque te quiere tal como eres.', title_fr = 'Inutile d''être parfaite 💖', body_fr = 'La maison est en désordre et le repas est en retard aujourd''hui ? Ce n''est rien ! Confiez votre voix intérieure au Journal d''humeur et rappelez-vous que votre enfant vous aime telle que vous êtes.', title_hi = 'परफ़ेक्ट होना ज़रूरी नहीं 💖', body_hi = 'आज घर बिखर गया, खाना देर से बना? कोई बात नहीं! मूड डायरी में अपने मन की बात लिखिए और याद रखिए कि आपका बच्चा आपको हर हाल में प्यार करता है।', title_id = 'Tidak harus sempurna 💖', body_id = 'Hari ini rumah berantakan dan makanan terlambat? Tidak apa-apa! Tulis suara hati Anda di Buku Harian Suasana Hati dan ingatlah bahwa si kecil mencintai Anda apa adanya.', title_ja = '完璧でなくていいんです 💖', body_ja = '今日は家が散らかって、ごはんも遅れた？大丈夫！「気分日記」に心の声を書いて、お子さんはどんなあなたでも大好きだということを思い出しましょう。', title_ko = '완벽할 필요는 없어요 💖', body_ko = '오늘 집이 어질러지고 식사가 늦어졌나요? 괜찮아요! 기분 일기에 속마음을 적고, 아이는 어떤 모습의 엄마든 사랑한다는 걸 기억하세요.', title_nl = 'Je hoeft niet perfect te zijn 💖', body_nl = 'Was het huis vandaag een chaos en was het eten laat? Helemaal niet erg! Schrijf je innerlijke stem op in je Stemmingsdagboek en onthoud dat je kindje je hoe dan ook liefheeft.', title_pl = 'Nie musisz być idealna 💖', body_pl = 'Dziś w domu bałagan, a obiad się spóźnia? Nic się nie stanie! Zapisz swój wewnętrzny głos w Dzienniku nastroju i pamiętaj, że twoje dziecko kocha cię taką, jaka jesteś.', title_pt = 'Não tem de ser perfeita 💖', body_pt = 'Hoje a casa ficou desarrumada e a comida atrasou-se? Não faz mal! Escreva a sua voz interior no Diário de Humor e lembre-se de que o seu filho a ama tal como é.', title_sv = 'Du måste inte vara perfekt 💖', body_sv = 'Stökigt hemma och sen middag i dag? Det gör ingenting! Skriv ner dina tankar i Humördagboken och kom ihåg att barnet älskar dig precis som du är.', title_vi = 'Không cần phải hoàn hảo 💖', body_vi = 'Hôm nay nhà bừa bộn, bữa ăn bị trễ? Không sao cả! Hãy viết tiếng lòng vào Nhật ký tâm trạng và nhớ rằng bé yêu mẹ dù mẹ thế nào đi nữa.', title_zh = '不必非要完美 💖', body_zh = '今天家里乱了，饭也晚了？没关系！把内心的声音写进心情日记，记住孩子爱的是任何样子的你。' WHERE id = 'f1e65e7a-efb2-4ee4-9b90-639511a93965' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mucha agua, digestión fácil 💧', body_es = '¿Cómo funciona el intestino de tu peque tan activo? Haz las anotaciones al cambiar el pañal. Si hay riesgo de estreñimiento, mira en la app recomendaciones de alimentos con fibra natural.', title_fr = 'Beaucoup d''eau, digestion facile 💧', body_fr = 'Comment fonctionnent les intestins de votre petit actif ? Notez-le à chaque change. En cas de risque de constipation, consultez dans l''appli les conseils d''aliments riches en fibres naturelles.', title_hi = 'ज़्यादा पानी, आसान पाचन 💧', body_hi = 'चंचल नन्हे की आँतें कैसे काम कर रही हैं? डायपर बदलते समय एंट्री कीजिए। कब्ज़ का खतरा हो तो ऐप में कुदरती फ़ाइबर वाले खाने के सुझाव देखिए।', title_id = 'Banyak minum, pencernaan lancar 💧', body_id = 'Bagaimana kerja usus si kecil yang aktif? Masukkan catatan saat mengganti popok. Jika ada risiko sembelit, lihat rekomendasi makanan berserat alami di aplikasi.', title_ja = 'たっぷりの水分で、すっきり消化 💧', body_ja = '活発なお子さんのおなかの調子はどうですか？おむつ替えのときに記録しましょう。便秘のおそれがあれば、アプリで食物繊維の多い自然な食べ物のおすすめをチェックしましょう。', title_ko = '물을 많이, 소화는 편하게 💧', body_ko = '활발한 아이의 장은 잘 움직이고 있나요? 기저귀를 갈 때 기록을 남기세요. 변비가 걱정된다면 앱에서 자연 섬유질 음식 추천을 살펴보세요.', title_nl = 'Veel water, makkelijke spijsvertering 💧', body_nl = 'Hoe werken de darmen van je actieve kleintje? Noteer het bij het verschonen. Is er kans op verstopping, bekijk dan in de app tips voor natuurlijk vezelrijk eten.', title_pl = 'Dużo wody, łatwe trawienie 💧', body_pl = 'Jak pracują jelitka aktywnego malucha? Notuj przy zmianie pieluszki. Jeśli jest ryzyko zaparć, zajrzyj w aplikacji do wskazówek o naturalnych produktach bogatych w błonnik.', title_pt = 'Muita água, digestão fácil 💧', body_pt = 'Como está a funcionar o intestino do seu pequenino tão ativo? Faça os registos ao mudar a fralda. Se houver risco de prisão de ventre, veja na app as sugestões de alimentos com fibra natural.', title_sv = 'Mycket vatten, lätt matsmältning 💧', body_sv = 'Hur fungerar magen hos din aktiva lilla? Anteckna när du byter blöja. Finns risk för förstoppning, titta på tipsen om naturlig fiberrik mat i appen.', title_vi = 'Uống nhiều nước, tiêu hóa dễ dàng 💧', body_vi = 'Ruột của bé hiếu động hoạt động thế nào? Hãy ghi lại khi thay tã. Nếu có nguy cơ táo bón, hãy xem gợi ý thực phẩm giàu chất xơ tự nhiên trong ứng dụng.', title_zh = '多喝水，好消化 💧', body_zh = '好动的小家伙肠道怎么样？换尿布时记录下来。如果有便秘风险，去应用里看看天然高纤维食物的建议。' WHERE id = '0ec68466-1a64-4bc2-ab11-6f19a539925d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Conocer a otras madres 👯‍♀️', body_es = '¡Que tu peque juegue mientras tú charlas! Busca en el mapa de Lugares para mamás un centro con grupos de juego y sal de casa.', title_fr = 'Rencontrer d''autres mamans 👯‍♀️', body_fr = 'Qu''il joue pendant que vous discutez ! Trouvez sur la carte des Lieux adaptés aux mamans un centre avec groupes de jeu et sortez de la maison.', title_hi = 'दूसरी माँओं से मुलाकात 👯‍♀️', body_hi = 'बच्चा भी खेले और आप भी बातें करें! माँ के लिए अनुकूल जगहें के नक्शे से प्ले ग्रुप वाला सेंटर ढूँढिए और घर से निकलिए।', title_id = 'Berkenalan dengan ibu lain 👯‍♀️', body_id = 'Si kecil bermain, Anda pun bisa mengobrol! Temukan tempat dengan kelompok bermain di peta Tempat Ramah Ibu dan keluarlah dari rumah.', title_ja = 'ほかのママと知り合おう 👯‍♀️', body_ja = 'お子さんは遊んで、あなたはおしゃべり！「ママにやさしいスポット」のマップで遊びのグループがある施設を見つけて、お出かけしましょう。', title_ko = '다른 엄마들과 만나요 👯‍♀️', body_ko = '아이는 놀고 엄마는 수다를! 엄마 친화 장소 지도에서 놀이 모임이 있는 센터를 찾아 집 밖으로 나가 보세요.', title_nl = 'Andere moeders leren kennen 👯‍♀️', body_nl = 'Laat je kindje spelen terwijl jij kletst! Zoek op de kaart Mamavriendelijke plekken een centrum met speelgroepjes en ga de deur uit.', title_pl = 'Poznaj inne mamy 👯‍♀️', body_pl = 'Niech maluch się bawi, a ty porozmawiasz! Znajdź na mapie Miejsc przyjaznych mamom centrum z grupami zabaw i wyjdź z domu.', title_pt = 'Conhecer outras mães 👯‍♀️', body_pt = 'Ele brinca e a mãe conversa! Encontre no mapa dos Locais Amigos das Mães um centro com grupos de brincadeira e saiam de casa.', title_sv = 'Träffa andra mammor 👯‍♀️', body_sv = 'Låt barnet leka medan du pratar! Hitta ett center med lekgrupper på kartan i Mammavänliga platser och gå ut.', title_vi = 'Làm quen với các mẹ khác 👯‍♀️', body_vi = 'Vừa để bé chơi, vừa để mẹ trò chuyện! Hãy tìm một trung tâm có nhóm chơi trên bản đồ Địa điểm thân thiện với mẹ và ra ngoài nhé.', title_zh = '认识其他妈妈 👯‍♀️', body_zh = '让孩子玩，你也能聊聊天！在妈妈友好场所地图上找一个有游戏小组的中心，出门走走吧。' WHERE id = 'e1d32a6a-e4ea-4c4f-8731-157813de9284' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Nos lavamos los dientes? 🪥', body_es = '¿Cierra la boca en cuanto ve el cepillo? Pide a Anacan AI consejos prácticos para convertir esta rutina de higiene en un juego divertido.', title_fr = 'On se brosse les dents ? 🪥', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse ? Demandez à Anacan AI des conseils pratiques pour transformer ce rituel d''hygiène en jeu amusant.', title_hi = 'दाँत ब्रश हो रहे हैं? 🪥', body_hi = 'ब्रश देखते ही मुँह बंद कर लेता है? सफ़ाई के इस रूटीन को मज़ेदार खेल कैसे बनाएँ, यह जानने के लिए Anacan AI से काम की सलाह लीजिए।', title_id = 'Sudah sikat gigi? 🪥', body_id = 'Langsung mengatupkan mulut begitu melihat sikat gigi? Dapatkan saran praktis dari Anacan AI untuk menjadikan rutinitas kebersihan ini permainan seru.', title_ja = '歯みがきできた？🪥', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？この歯みがきの習慣を楽しい遊びに変える実践的なアドバイスを、Anacan AIからもらいましょう。', title_ko = '양치는 했나요? 🪥', body_ko = '칫솔만 보면 입을 꾹 다무나요? 이 위생 습관을 재미있는 놀이로 바꾸는 방법을 Anacan AI에게 실용적인 조언으로 받아 보세요.', title_nl = 'Tandenpoetsen? 🪥', body_nl = 'Klemt hij zijn mond dicht zodra hij de tandenborstel ziet? Vraag Anacan AI om praktische tips om van deze verzorging een leuk spel te maken.', title_pl = 'Ząbki umyte? 🪥', body_pl = 'Zaciska buzię na widok szczoteczki? Poproś Anacan AI o praktyczne rady, jak zamienić tę higieniczną rutynę w zabawę.', title_pt = 'Já lavou os dentes? 🪥', body_pt = 'Mal vê a escova, fecha a boca? Peça ao Anacan AI conselhos práticos para transformar esta rotina de higiene num jogo divertido.', title_sv = 'Borstar vi tänderna? 🪥', body_sv = 'Stänger barnet munnen så fort tandborsten syns? Få praktiska råd från Anacan AI om hur du gör hygienrutinen till en rolig lek.', title_vi = 'Đánh răng chưa nào? 🪥', body_vi = 'Vừa thấy bàn chải là bé mím chặt miệng? Hãy nhận lời khuyên thực tế từ Anacan AI để biến thói quen vệ sinh này thành trò chơi vui nhộn.', title_zh = '刷牙了吗？🪥', body_zh = '一看到牙刷就紧闭小嘴？向Anacan AI获取实用建议，学习如何把这项卫生习惯变成有趣的游戏。' WHERE id = '2e576d6b-3baa-4d91-b939-7173553eee26' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso? El temporizador se ha parado. Olvida las tareas de casa, prepárate una infusión de melisa de Recetas saludables y disfruta del silencio.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée très bruyante ? Le minuteur est arrêté. Oubliez les tâches ménagères, préparez une tisane de mélisse des Recettes saines et savourez simplement le silence.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत शोर भरा दिन था? टाइमर रुक गया। घर के काम भूल जाइए, सेहतमंद रेसिपी से लेमन बाम की चाय बनाइए और बस खामोशी का मज़ा लीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari yang sangat bising? Timer sudah berhenti. Lupakan pekerjaan rumah, seduh teh lemon balm dari Resep Sehat, dan nikmati keheningan.', title_ja = '自然のリラックス効果 🍃', body_ja = 'にぎやかな一日でしたか？タイマーは止まりました。家事は忘れて、「ヘルシーレシピ」からレモンバームティーをいれて、静けさだけを味わいましょう。', title_ko = '자연의 진정제 🍃', body_ko = '정말 시끄러운 하루였나요? 타이머가 멈췄어요. 집안일은 잊고, 건강한 레시피에서 레몬밤 차를 우려 오직 고요함만 즐기세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een lawaaierige dag? De timer is gestopt. Vergeet het huishouden, zet citroenmelissethee uit Gezonde recepten en geniet gewoon van de stilte.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był bardzo głośny dzień? Timer zatrzymany. Zapomnij o obowiązkach, zaparz melisę ze Zdrowych przepisów i po prostu delektuj się ciszą.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia muito barulhento? O temporizador parou. Esqueça as tarefas da casa, prepare um chá de erva-cidreira das Receitas Saudáveis e saboreie apenas o silêncio.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit väldigt bullrig? Timern har stannat. Glöm hushållssysslorna, brygg citronmelissate från Hälsosamma recept och njut bara av tystnaden.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Một ngày quá ồn ào? Hẹn giờ đã dừng. Quên việc nhà đi, hãy pha trà tía tô đất từ Công thức lành mạnh và tận hưởng sự yên tĩnh.', title_zh = '天然的镇静剂 🍃', body_zh = '今天特别吵闹？计时器停了。忘掉家务，从健康食谱里泡一杯香蜂草茶，好好享受这份安静。' WHERE id = '8e98b7fa-b3a5-48a4-896a-9431c201a988' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de dulces sanos 🍎', body_es = '¡Adiós a las galletas del súper! Descubre en Recetas para bebé galletas sanas caseras de dátiles y manzana que se preparan en 10 minutos y ábrele el apetito.', title_fr = 'À la recherche d''une douceur saine 🍎', body_fr = 'Fini les biscuits du commerce ! Découvrez dans les Recettes pour bébés des biscuits sains aux dattes et à la pomme, prêts en 10 minutes à la maison, et ouvrez-lui l''appétit.', title_hi = 'सेहतमंद मिठाई की तलाश 🍎', body_hi = 'बाज़ार के बिस्किट को अलविदा! बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और सेब की सेहतमंद कुकीज़ खोजिए और उसकी भूख खोलिए।', title_id = 'Mencari camilan manis sehat 🍎', body_id = 'Selamat tinggal biskuit dari toko! Temukan kue kering sehat dari kurma dan apel yang siap dalam 10 menit di Resep Bayi dan buka nafsu makannya.', title_ja = 'ヘルシーなおやつ探し 🍎', body_ja = '市販のクッキーとはお別れ！「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとりんごのヘルシーなクッキーを見つけて、食欲を引き出しましょう。', title_ko = '건강한 간식 찾기 🍎', body_ko = '마트 쿠키는 이제 그만! 아기 레시피에서 집에서 10분이면 만드는 대추야자 사과 쿠키를 찾아 입맛을 살려 주세요.', title_nl = 'Op zoek naar gezond lekkers 🍎', body_nl = 'Weg met koekjes uit de winkel! Ontdek in Babyrecepten gezonde koekjes met dadels en appel, thuis klaar in 10 minuten, en maak hem hongerig.', title_pl = 'W poszukiwaniu zdrowych słodkości 🍎', body_pl = 'Koniec ze sklepowymi ciastkami! Odkryj w Przepisach dla niemowląt zdrowe ciasteczka z daktylami i jabłkiem, które zrobisz w domu w 10 minut, i pobudź jego apetyt.', title_pt = 'À procura de doces saudáveis 🍎', body_pt = 'Adeus bolachas do supermercado! Descubra nas Receitas para bebés bolachas saudáveis de tâmaras e maçã, feitas em casa em 10 minutos, e abra-lhe o apetite.', title_sv = 'På jakt efter nyttigt godis 🍎', body_sv = 'Slut på kex från affären! Upptäck nyttiga kakor med dadlar och äpple som är klara på 10 minuter hemma i Recept för bebisar och väck aptiten.', title_vi = 'Tìm món ngọt lành mạnh 🍎', body_vi = 'Tạm biệt bánh quy mua sẵn! Hãy khám phá những chiếc bánh quy bổ dưỡng từ chà là và táo làm tại nhà trong 10 phút trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '寻找健康甜点 🍎', body_zh = '和超市饼干说再见！在宝宝食谱里发现10分钟就能在家做好的椰枣苹果健康饼干，让宝宝胃口大开。' WHERE id = 'e49913ea-33f5-4d6e-8204-24fdfbb6dfec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelve el miedo a la separación? 🌌', body_es = '¿Llora en cuanto sales de la habitación? Pon el sonido del latido del corazón de Ruido blanco, dale sensación de seguridad y prepárale para dormir.', title_fr = 'La peur de la séparation revient ? 🌌', body_fr = 'Il pleure dès que vous quittez la pièce ? Lancez les battements de cœur des Bruits blancs pour lui donner un sentiment de sécurité et l''aider à s''endormir.', title_hi = 'अलग होने का डर लौट आया? 🌌', body_hi = 'आप कमरे से निकलते ही वह रोने लगता है? व्हाइट नॉइज़ में दिल की धड़कन की आवाज़ चलाकर उसे सुरक्षा का एहसास दीजिए और नींद के लिए तैयार कीजिए।', title_id = 'Takut berpisah kembali muncul? 🌌', body_id = 'Menangis begitu Anda keluar kamar? Putar suara detak jantung dari Suara Putih, beri ia rasa aman, dan antar ia tidur.', title_ja = '離れるのがこわい気持ちが復活？🌌', body_ja = '部屋を出たとたん、あとを追って泣きますか？「ホワイトノイズ」の心臓の音を流して安心感を届け、眠りへ導きましょう。', title_ko = '분리 불안이 다시? 🌌', body_ko = '방을 나가자마자 울며 따라오나요? 백색소음에서 심장 박동 소리를 틀어 안정감을 주고 잠들 준비를 도와주세요.', title_nl = 'Komt de verlatingsangst terug? 🌌', body_nl = 'Huilt hij zodra je de kamer uit gaat? Zet het hartslaggeluid uit Witte ruis aan, geef hem een veilig gevoel en help hem in slaap.', title_pl = 'Lęk przed rozstaniem wraca? 🌌', body_pl = 'Płacze, gdy tylko wychodzisz z pokoju? Włącz bicie serca z Białego szumu, daj mu poczucie bezpieczeństwa i nastrój go do snu.', title_pt = 'O medo da separação voltou? 🌌', body_pt = 'Mal sai do quarto, chora atrás de si? Ligue no Ruído Branco o som do batimento cardíaco, dê-lhe uma sensação de segurança e prepare-o para dormir.', title_sv = 'Separationsångesten tillbaka? 🌌', body_sv = 'Gråter barnet så fort du lämnar rummet? Sätt på hjärtslag från Vitt brus, ge barnet en känsla av trygghet och stäm för sömn.', title_vi = 'Nỗi sợ xa mẹ quay lại? 🌌', body_vi = 'Mẹ vừa ra khỏi phòng là bé khóc theo? Hãy bật tiếng tim đập trong Tiếng ồn trắng để mang lại cảm giác an toàn và đưa bé vào giấc ngủ.', title_zh = '分离焦虑又回来了？🌌', body_zh = '你一离开房间就在后面哭？打开白噪音里的心跳声，给宝宝安全感，帮宝宝进入睡眠。' WHERE id = '8566be64-ecf0-4dc1-8d90-20c831db74ad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Los pantalones vuelven a quedarle cortos! 📏', body_es = '¿Las mangas se le quedan estrechas? Está dando un estirón. Introduce sus medidas actuales en el Registro de peso y mira con orgullo su curva de crecimiento.', title_fr = 'Le pantalon est encore trop court ! 📏', body_fr = 'Les manches deviennent trop étroites ? C''est un pic de croissance physique. Entrez ses mesures actuelles dans le Suivi du poids et regardez fièrement sa courbe de croissance.', title_hi = 'पैंट फिर छोटी हो गई! 📏', body_hi = 'कमीज़ की आस्तीनें तंग हो रही हैं? शारीरिक विकास में उछाल है। वेट ट्रैकर में मौजूदा माप दर्ज कीजिए और गर्व से ग्रोथ चार्ट देखिए।', title_id = 'Celananya kependekan lagi! 📏', body_id = 'Lengan bajunya mulai sempit? Ada lonjakan pertumbuhan fisik. Masukkan ukuran terbarunya ke Pelacak Berat Badan dan lihat grafik pertumbuhannya dengan bangga.', title_ja = 'ズボンがまた短くなった！📏', body_ja = 'シャツの袖がきつくなってきましたか？体がぐんと成長する時期です。「体重トラッカー」に今のサイズを入力して、成長グラフを誇らしく眺めましょう。', title_ko = '바지가 또 짧아졌어요! 📏', body_ko = '셔츠 소매가 끼나요? 신체 성장 급등기예요. 체중 기록에 현재 치수를 입력하고 성장 그래프를 뿌듯하게 확인하세요.', title_nl = 'De broek is weer te kort! 📏', body_nl = 'Worden de mouwen te krap? Er is een groeispurt. Voer de huidige maten in de Gewichtstracker in en kijk trots naar zijn groeicurve.', title_pl = 'Spodnie znów za krótkie! 📏', body_pl = 'Rękawy koszulek robią się ciasne? To skok w rozwoju fizycznym. Wpisz aktualne pomiary w Liczniku wagi i z dumą spójrz na wykres wzrostu.', title_pt = 'As calças voltaram a ficar curtas! 📏', body_pt = 'As mangas das camisolas estão a ficar apertadas? Há um salto no crescimento físico. Introduza as medidas atuais no Registo de Peso e veja com orgulho o gráfico de crescimento.', title_sv = 'Byxorna för korta igen! 📏', body_sv = 'Blir tröjärmarna för trånga? Det är en fysisk tillväxtspurt. Ange aktuella mått i Viktspåraren och titta stolt på tillväxtkurvan.', title_vi = 'Quần lại ngắn rồi! 📏', body_vi = 'Tay áo bị chật? Bé đang tăng trưởng vọt. Hãy nhập số đo hiện tại vào Theo dõi cân nặng và tự hào ngắm biểu đồ tăng trưởng.', title_zh = '裤子又变短了！📏', body_zh = '衣袖变紧了？身体发育正在突飞猛进。在体重记录里输入当前的尺寸，骄傲地看看成长曲线。' WHERE id = '942d7419-7926-47e6-b70e-db59dc58e301' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pronunciaciones graciosas 🗣️', body_es = '¡Hay palabras que dice tan dulcemente mal! No te pierdas estos momentos de oro. Súbelos en vídeo con sonido al Álbum del bebé y reíd juntos en el futuro.', title_fr = 'Prononciations rigolotes 🗣️', body_fr = 'Il prononce certains mots de travers, et c''est trop mignon ! Ne manquez pas ces moments en or. Ajoutez-les en vidéo avec le son à l''Album de bébé et riez-en ensemble plus tard.', title_hi = 'मज़ेदार उच्चारण 🗣️', body_hi = 'कुछ शब्द इतने प्यारे और गलत बोलता है! इन सुनहरे पलों को मत चूकिए। इन्हें आवाज़ वाले वीडियो के रूप में बेबी एल्बम में अपलोड कीजिए और आगे चलकर साथ में हँसिए।', title_id = 'Pelafalan yang lucu 🗣️', body_id = 'Ada kata-kata yang ia ucapkan dengan begitu manis meski salah! Jangan lewatkan momen emas ini. Unggah sebagai video bersuara ke Album Bayi dan tertawalah bersama di masa depan.', title_ja = 'おもしろい発音 🗣️', body_ja = 'いくつかの言葉を、とてもかわいく言いまちがえますね！この宝物のような瞬間を見逃さないで。音声付きの動画で「ベビーアルバム」にアップして、いつか一緒に笑いましょう。', title_ko = '귀여운 발음 🗣️', body_ko = '어떤 단어는 정말 귀엽게 틀리게 말해요! 이 소중한 순간을 놓치지 마세요. 소리가 담긴 영상으로 아기 앨범에 올려 나중에 함께 웃어요.', title_nl = 'Grappige uitspraak 🗣️', body_nl = 'Sommige woorden zegt hij zo schattig verkeerd! Mis deze gouden momenten niet. Zet ze als video met geluid in het Babyalbum en lach er later samen om.', title_pl = 'Zabawna wymowa 🗣️', body_pl = 'Niektóre słowa wymawia tak słodko i tak błędnie! Nie przegap tych złotych chwil. Dodaj je jako film z dźwiękiem do Albumu dziecka i pośmiejcie się z nich razem w przyszłości.', title_pt = 'Pronúncias engraçadas 🗣️', body_pt = 'Diz algumas palavras de forma tão doce e trocada! Não perca estes momentos de ouro. Carregue-os em vídeo com som no Álbum do Bebé e riam-se juntos no futuro.', title_sv = 'Roligt uttal 🗣️', body_sv = 'Vissa ord säger barnet så sött och fel! Missa inte dessa gyllene stunder. Ladda upp dem som video med ljud i Babyalbumet och skratta åt dem tillsammans i framtiden.', title_vi = 'Phát âm ngộ nghĩnh 🗣️', body_vi = 'Bé nói sai một số từ mà nghe đáng yêu vô cùng! Đừng bỏ lỡ những khoảnh khắc vàng này. Hãy tải video có tiếng lên Album của bé để sau này cùng nhau cười.', title_zh = '搞笑的发音 🗣️', body_zh = '有些词宝宝说得又可爱又不对！别错过这些黄金时刻。录成有声视频上传到宝宝相册，将来一起笑一笑。' WHERE id = '95ec49ae-492b-442d-be59-8db9c9f8c8e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Unos músculos tan activos necesitan proteínas. Mide con el Seguimiento de tomas el equilibrio de su alimentación diaria y enriquece su menú.', body_fr = 'Les protéines sont indispensables à des muscles actifs. Mesurez son équilibre alimentaire du jour avec le Suivi des repas et enrichissez son menu.', body_hi = 'चंचल मांसपेशियों के लिए प्रोटीन ज़रूरी है। फ़ीडिंग ट्रैकर से उसके रोज़ के खाने का संतुलन मापिए और मेन्यू को और पौष्टिक बनाइए।', body_id = 'Otot yang aktif butuh protein. Ukur keseimbangan nutrisi hariannya dengan alat Pemantau Nutrisi dan perkaya menunya.', body_ja = '活発に動く筋肉には、たんぱく質が欠かせません。「栄養管理ツール」で1日の栄養バランスを確認して、メニューを豊かにしましょう。', body_ko = '활발한 근육에는 단백질이 꼭 필요해요. 수유 기록 도구로 하루 영양 균형을 확인하고 식단을 더 풍성하게 만들어 주세요.', body_nl = 'Eiwit is onmisbaar voor actieve spieren. Meet met de Voedingstracker zijn dagelijkse voedingsbalans en maak zijn menu rijker.', body_pl = 'Białko jest niezbędne dla aktywnych mięśni. Sprawdź w narzędziu do śledzenia karmienia jego dzienny bilans żywieniowy i wzbogać menu.', body_pt = 'Músculos ativos precisam de proteína. Meça com o Registo de Alimentação o equilíbrio alimentar diário e enriqueça a ementa.', body_sv = 'Aktiva muskler behöver protein. Mät barnets dagliga näringsbalans med Matningskoll och gör menyn mer varierad.', body_vi = 'Cơ bắp hoạt động nhiều rất cần đạm. Hãy đo cân bằng dinh dưỡng hằng ngày của bé bằng Theo dõi cữ bú và làm thực đơn thêm phong phú.', body_zh = '活力满满的肌肉离不开蛋白质。用喂养记录工具衡量宝宝每天的饮食平衡，让菜单更丰富。' WHERE id = '25439bfb-873c-4735-bc03-f5aa2d6b8ff2' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Esto lo hago yo! 👕', body_es = '¿Vestirse por la mañana se convierte en una gran crisis? Aprende ya con Anacan AI los secretos para afrontar la tozudez y darle derecho a elegir.', title_fr = 'C''est moi qui le fais ! 👕', body_fr = 'L''habillage du matin tourne à la grosse crise ? Découvrez tout de suite avec Anacan AI les secrets pour gérer son obstination et lui laisser le droit de choisir.', title_hi = 'यह मैं करूँगा! 👕', body_hi = 'सुबह कपड़े पहनना बड़ा झगड़ा बन जाता है? ज़िद से निपटने और उसे चुनने का मौका देने के राज़ तुरंत Anacan AI से जानिए।', title_id = 'Biar aku sendiri! 👕', body_id = 'Berpakaian di pagi hari berubah jadi drama besar? Pelajari rahasia menghadapi sikap keras kepala dan memberinya hak memilih langsung dari Anacan AI.', title_ja = '自分でやる！👕', body_ja = '朝の着替えが大きなかんしゃくの時間になっていますか？こだわりへの対処法と、自分で選ぶ機会をあげるコツを、すぐにAnacan AIで学びましょう。', title_ko = '내가 할래! 👕', body_ko = '아침마다 옷 입기가 큰 전쟁이 되나요? 고집을 다루고 선택할 기회를 주는 비결을 Anacan AI에게 바로 배워 보세요.', title_nl = 'Dat doe ik zelf! 👕', body_nl = 'Wordt aankleden in de ochtend een grote strijd? Leer meteen bij Anacan AI hoe je met koppigheid omgaat en hem zelf laat kiezen.', title_pl = 'Ja to zrobię! 👕', body_pl = 'Poranne ubieranie zamienia się w wielki kryzys? Od razu poznaj z Anacan AI sekrety radzenia sobie z uporem i dawania mu prawa wyboru.', title_pt = 'Eu faço sozinho! 👕', body_pt = 'Vestir-se de manhã transforma-se numa grande crise? Aprenda já com o Anacan AI os segredos para lidar com a teimosia e dar-lhe o direito de escolher.', title_sv = 'Jag gör det själv! 👕', body_sv = 'Har påklädningen på morgonen blivit ett stort utbrott? Lär dig direkt av Anacan AI hur du hanterar envisheten och ger barnet rätt att välja.', title_vi = '"Con tự làm!" 👕', body_vi = 'Mặc quần áo buổi sáng đã thành cuộc khủng hoảng lớn? Hãy học ngay từ Anacan AI bí quyết đối phó với sự bướng bỉnh và cho bé quyền tự chọn.', title_zh = '这个我自己来！👕', body_zh = '早上穿衣服变成了大崩溃？马上向Anacan AI学习应对倔强、给宝宝选择权的秘诀。' WHERE id = 'a458d5c8-d74f-4a15-a4a9-53e24632f8f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libros para leer, no para romper 📖', body_es = '¿Arranca las páginas a la hora del cuento? Lee ya en el Blog cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'Lire les livres, pas les déchirer 📖', body_fr = 'Il déchire les pages à l''heure du conte du soir ? Lisez tout de suite dans la rubrique Blogs comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'किताब फाड़ना नहीं, पढ़ना 📖', body_hi = 'शाम को कहानी के समय पन्ने फाड़ देता है? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह तुरंत ब्लॉग सेक्शन में पढ़िए।', title_id = 'Membaca buku, bukan merobeknya 📖', body_id = 'Merobek halaman saat waktu dongeng malam? Segera baca di bagian Blog cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = '絵本は破らずに読もう 📖', body_ja = '夜の読み聞かせの時間にページを破ってしまいますか？読書の習慣を損なわずにこの問題に対応する方法を、すぐにブログで読んでみましょう。', title_ko = '찢지 말고 읽어요 📖', body_ko = '잠자리 동화 시간에 책장을 찢나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 블로그에서 바로 읽어 보세요.', title_nl = 'Boeken lezen, niet scheuren 📖', body_nl = 'Scheurt hij bij het avondverhaal de bladzijden kapot? Lees meteen in Blogs hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Nie drzemy książek, tylko czytamy 📖', body_pl = 'Podczas wieczornej bajki drze strony? Od razu przeczytaj w sekcji Blog, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'Ler, não rasgar 📖', body_pt = 'Na hora da história da noite, rasga as páginas? Leia já nos Blogues como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Läsa böcker, inte riva sönder dem 📖', body_sv = 'River barnet sönder sidorna vid kvällssagan? Läs direkt i Bloggar hur du löser problemet utan att skada läsvanan.', title_vi = 'Đọc sách, không xé sách 📖', body_vi = 'Đến giờ kể chuyện buổi tối là bé xé trang sách? Hãy đọc ngay trong mục Blog cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '不撕书，读书 📖', body_zh = '晚上讲故事时把书页撕碎？马上去博客板块读读，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = 'f5dd0c22-b8ec-461e-a5b4-9045aa3ae282' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena y barro 🏖️', body_es = '¡No tengas miedo a que se ensucie! Descubre ahora en Productos recomendados lo mejor en arena cinética y juegos sensoriales.', title_fr = 'Thérapie par le sable et la boue 🏖️', body_fr = 'N''ayez pas peur qu''il se salisse ! Découvrez tout de suite dans les Produits recommandés le meilleur matériel pour le sable cinétique et les jeux sensoriels.', title_hi = 'रेत और मिट्टी थेरेपी 🏖️', body_hi = 'गंदा होने से मत डरिए! काइनेटिक सैंड या सेंसरी खेलों के लिए सबसे अच्छी चीज़ें तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Terapi pasir dan lumpur 🏖️', body_id = 'Jangan takut kotor! Temukan perlengkapan terbaik untuk pasir kinetik dan permainan sensorik di bagian Produk Rekomendasi.', title_ja = '砂と泥んこセラピー 🏖️', body_ja = '汚れるのをこわがらないで！キネティックサンドや感覚遊びにぴったりのアイテムを、「おすすめ商品」ですぐに見つけましょう。', title_ko = '모래와 진흙 테라피 🏖️', body_ko = '더러워지는 걸 두려워하지 마세요! 키네틱 샌드와 감각 놀이에 좋은 도구를 추천 제품 섹션에서 바로 찾아보세요.', title_nl = 'Zand- en moddertherapie 🏖️', body_nl = 'Wees niet bang voor vieze handjes! Ontdek meteen in Aanbevolen producten de beste spullen voor kinetisch zand en zintuiglijke spelletjes.', title_pl = 'Terapia piaskiem i błotem 🏖️', body_pl = 'Nie bój się brudu! Od razu odkryj w sekcji Polecane produkty najlepsze akcesoria do piasku kinetycznego i zabaw sensorycznych.', title_pt = 'Terapia com areia e lama 🏖️', body_pt = 'Não tenha medo que se suje! Descubra já na secção Produtos Recomendados os melhores materiais de areia cinética e brincadeiras sensoriais.', title_sv = 'Sand- och leraterapi 🏖️', body_sv = 'Var inte rädd för smuts! Upptäck direkt de bästa produkterna för kinetisk sand och sinneslekar i Rekommenderade produkter.', title_vi = 'Liệu pháp cát và bùn 🏖️', body_vi = 'Đừng sợ bé bị bẩn! Hãy khám phá ngay những món đồ tốt nhất về cát động lực học hoặc trò chơi giác quan trong mục Sản phẩm gợi ý.', title_zh = '沙子和泥巴疗法 🏖️', body_zh = '别怕弄脏！马上去推荐商品板块，发现最好的动力沙和感官游戏用品。' WHERE id = '65db46df-45b6-4a1e-ae35-6797a38fafce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Es fruto de tu esfuerzo 🌟', body_es = 'Cada nueva habilidad que aprende y cada paso seguro que da son fruto de tu esfuerzo. ¡Abre el Diario de ánimo y escribe hoy una nota de la que sentirte orgullosa!', title_fr = 'C''est le fruit de vos efforts 🌟', body_fr = 'Chaque nouvelle compétence, chaque pas assuré, c''est grâce à vous. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note qui vous rendra fière de vous !', title_hi = 'यह आपकी मेहनत है 🌟', body_hi = 'हर दिन सीखी नई चीज़, हर भरोसे भरा कदम आपकी मेहनत है। मूड डायरी खोलिए और आज खुद पर गर्व करने वाली एक बात लिखिए!', title_id = 'Ini hasil kerja keras Anda 🌟', body_id = 'Setiap keterampilan baru dan setiap langkah percaya dirinya adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati dan tulis catatan yang membuat Anda bangga pada diri sendiri hari ini!', title_ja = 'あなたのがんばりのおかげです 🌟', body_ja = '毎日新しくできるようになること、自信に満ちた一歩一歩は、あなたのがんばりのおかげです。「気分日記」を開いて、今日の自分を誇りに思えるメモを書きましょう！', title_ko = '엄마의 노력 덕분이에요 🌟', body_ko = '매일 배우는 새로운 능력, 자신 있는 한 걸음 한 걸음이 모두 엄마의 노력이에요. 기분 일기를 열고 오늘 나를 자랑스러워할 기록을 남겨 보세요!', title_nl = 'Dat is jouw werk 🌟', body_nl = 'Elke nieuwe vaardigheid en elk zelfverzekerd stapje is dankzij jou. Open je Stemmingsdagboek en schrijf vandaag een notitie waar je trots op kunt zijn!', title_pl = 'To twoja zasługa 🌟', body_pl = 'Każda nowa umiejętność, każdy pewny krok to twoja zasługa. Otwórz Dziennik nastroju i napisz dziś notatkę, z której będziesz dumna!', title_pt = 'É fruto do seu esforço 🌟', body_pt = 'Cada nova competência que aprende e cada passo confiante são fruto do seu esforço. Abra o Diário de Humor e escreva hoje uma nota que a faça sentir orgulho em si!', title_sv = 'Det är ditt arbete 🌟', body_sv = 'Varje ny färdighet barnet lär sig och varje säkert steg är tack vare ditt arbete. Öppna Humördagboken och skriv en anteckning i dag som gör dig stolt över dig själv!', title_vi = 'Đó là công sức của mẹ 🌟', body_vi = 'Mỗi kỹ năng mới, mỗi bước đi tự tin của bé đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng khiến mẹ tự hào về bản thân hôm nay!', title_zh = '这是你的功劳 🌟', body_zh = '宝宝每天学会的新本领、迈出的每一个自信的脚步，都有你的功劳。打开心情日记，写下一句让你为自己骄傲的话吧！' WHERE id = 'dc3f8791-df91-4f2d-8dc5-44a0fff017da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cuántas veces has dicho «no» hoy? 💆‍♀️', body_es = 'Estás muy cansada, ¿verdad? Respira hondo. Vuelca todo lo que sientes en el Diario de ánimo, deja a un lado la culpa y simplemente descansa.', title_fr = 'Combien de « non » aujourd''hui ? 💆‍♀️', body_fr = 'Vous êtes très fatiguée, n''est-ce pas ? Respirez profondément. Confiez toutes vos émotions au Journal d''humeur, laissez la culpabilité de côté et reposez-vous simplement.', title_hi = 'आज कितनी बार ''नहीं'' कहा? 💆‍♀️', body_hi = 'बहुत थक गई हैं, है ना? गहरी साँस लीजिए। मूड डायरी में अपनी सारी भावनाएँ लिखिए और अपराध-बोध को किनारे रखकर बस आराम कीजिए।', title_id = 'Berapa kali hari ini Anda bilang Tidak? 💆‍♀️', body_id = 'Sangat lelah, ya? Tarik napas dalam-dalam. Curahkan semua perasaan Anda di Buku Harian Suasana Hati, singkirkan rasa bersalah, dan beristirahatlah.', title_ja = '今日は何回「ダメ」と言いましたか？💆‍♀️', body_ja = 'とても疲れましたよね？深呼吸をしましょう。「気分日記」に気持ちをすべて書き出して、罪悪感は横に置き、ただゆっくり休みましょう。', title_ko = '오늘 ''안 돼''를 몇 번 했나요? 💆‍♀️', body_ko = '많이 지쳤죠? 깊게 숨을 쉬세요. 기분 일기에 마음을 모두 털어놓고, 죄책감은 내려놓은 채 그냥 쉬세요.', title_nl = 'Hoe vaak zei je vandaag nee? 💆‍♀️', body_nl = 'Je bent erg moe, hè? Adem diep in. Schrijf al je gevoelens van je af in je Stemmingsdagboek, zet je schuldgevoel opzij en rust gewoon uit.', title_pl = 'Ile razy dziś powiedziałaś „nie”? 💆‍♀️', body_pl = 'Jesteś bardzo zmęczona, prawda? Weź głęboki oddech. Wylej wszystkie uczucia w Dzienniku nastroju, odłóż wyrzuty sumienia i po prostu odpocznij.', title_pt = 'Quantas vezes disse "não" hoje? 💆‍♀️', body_pt = 'Está muito cansada, não está? Respire fundo. Deixe sair todos os sentimentos no Diário de Humor, ponha a culpa de lado e simplesmente descanse.', title_sv = 'Hur många gånger sa du ”nej” i dag? 💆‍♀️', body_sv = 'Du är väldigt trött, eller hur? Andas djupt. Skriv av dig alla känslor i Humördagboken, lägg det dåliga samvetet åt sidan och vila bara.', title_vi = 'Hôm nay mẹ đã nói "Không" bao nhiêu lần? 💆‍♀️', body_vi = 'Mẹ mệt lắm phải không? Hãy hít thở sâu. Trút hết cảm xúc vào Nhật ký tâm trạng, gác lại cảm giác áy náy và chỉ cần nghỉ ngơi thôi.', title_zh = '今天你说了几次“不”？💆‍♀️', body_zh = '累坏了，是吧？深呼吸。把所有感受倒进心情日记，放下内疚，好好休息。' WHERE id = '2dafd9b8-26be-4b73-a1b1-cede334643cd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se ha despertado con el pañal seco? 🩲', body_es = '¿Al cambiar el pañal de la mañana has notado que estaba seco? Pregunta ya a Anacan AI cuál es el mejor momento y los métodos psicológicos para empezar a dejar el pañal.', title_fr = 'Réveillé avec une couche sèche ? 🩲', body_fr = 'Vous avez remarqué que la couche du matin était sèche ? Demandez tout de suite à Anacan AI le meilleur moment et les méthodes psychologiques pour lancer l''apprentissage du pot.', title_hi = 'सूखे डायपर के साथ जागा? 🩲', body_hi = 'सुबह डायपर बदलते समय देखा कि वह सूखा है? पॉटी ट्रेनिंग शुरू करने का सबसे सही समय और मनोवैज्ञानिक तरीके तुरंत Anacan AI से पूछिए।', title_id = 'Bangun dengan popok kering? 🩲', body_id = 'Saat mengganti popok pagi, Anda melihat popoknya kering? Segera tanyakan kepada Anacan AI waktu paling tepat dan metode psikologis untuk memulai latihan pispot.', title_ja = 'おむつが乾いたまま起きた？🩲', body_ja = '朝のおむつ替えで、乾いていることに気づきましたか？トイレトレーニングを始めるのにいちばんいいタイミングと心理的な方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '보송한 기저귀로 깼나요? 🩲', body_ko = '아침에 기저귀를 갈 때 말라 있는 걸 알아챘나요? 배변 훈련을 시작하기 가장 좋은 때와 심리적 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Droog wakker geworden? 🩲', body_nl = 'Was de luier vanochtend droog? Vraag Anacan AI meteen naar het beste moment en psychologische methoden om met zindelijkheidstraining te beginnen.', title_pl = 'Obudził się z suchą pieluszką? 🩲', body_pl = 'Przy porannej zmianie zauważyłaś, że pieluszka jest sucha? Od razu zapytaj Anacan AI o najlepszy moment i psychologiczne metody, by zacząć naukę korzystania z nocnika.', title_pt = 'Acordou com a fralda seca? 🩲', body_pt = 'Ao mudar a fralda da manhã, reparou que estava seca? Pergunte já ao Anacan AI qual o momento certo e os métodos psicológicos para começar o treino do bacio.', title_sv = 'Vaknade med torr blöja? 🩲', body_sv = 'Märkte du att blöjan var torr när du bytte på morgonen? Fråga Anacan AI direkt om rätt tid och psykologiska metoder för att börja med pottträning.', title_vi = 'Tã vẫn khô khi thức dậy? 🩲', body_vi = 'Mẹ để ý tã khô khi thay buổi sáng? Hãy hỏi ngay Anacan AI thời điểm phù hợp nhất và các phương pháp tâm lý để bắt đầu tập ngồi bô.', title_zh = '醒来时尿布是干的？🩲', body_zh = '早上换尿布时发现是干的？马上问问Anacan AI，开始如厕训练的最佳时机和心理方法。' WHERE id = '379a5991-8f1e-48b3-9f27-5e21468d8859' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por las magdalenas 🧁', body_es = '¿Quiere algo dulce? No corras al súper. Con una magdalena casera de plátano y avena sin azúcar de Recetas para bebé, lista en 10 minutos, mantén su buena puntuación en el Seguimiento de tomas.', title_fr = 'L''amour des muffins 🧁', body_fr = 'Il réclame du sucré ? Pas besoin de courir au supermarché. Avec le muffin maison sans sucre banane-avoine en 10 minutes des Recettes pour bébés, gardez un bon score santé dans le Suivi des repas.', title_hi = 'मफ़िन का शौक 🧁', body_hi = 'मीठा चाहिए? बाज़ार की ओर मत भागिए। बच्चों की रेसिपी में बिना चीनी, केले और ओट्स से 10 मिनट में बनने वाले घर के मफ़िन से फ़ीडिंग ट्रैकर में सेहत का स्कोर बनाए रखिए।', title_id = 'Cinta muffin 🧁', body_id = 'Ingin yang manis-manis? Tak perlu ke minimarket. Jaga skor sehat di alat Pemantau Nutrisi dengan muffin rumahan pisang dan oat tanpa gula, siap dalam 10 menit dari Resep Bayi.', title_ja = 'マフィンが大好き 🧁', body_ja = '甘いものがほしい？お店に走らないで。「離乳食を始める赤ちゃんのレシピ」の、砂糖不使用のバナナとオートミールの10分マフィンで、「栄養管理ツール」の健康スコアをキープしましょう。', title_ko = '머핀 사랑 🧁', body_ko = '단 게 먹고 싶대요? 마트로 달려가지 마세요. 아기 레시피의 설탕 없는 바나나 귀리 10분 머핀으로 수유 기록 도구의 건강 점수를 지켜 주세요.', title_nl = 'Dol op muffins 🧁', body_nl = 'Wil hij iets zoets? Ren niet naar de winkel. Houd met een suikervrije muffin met banaan en havermout uit Babyrecepten, klaar in 10 minuten, zijn gezonde score in de Voedingstracker op peil.', title_pl = 'Miłość do babeczek 🧁', body_pl = 'Ma ochotę na słodkie? Nie biegnij do sklepu. Domowa babeczka z bananem i płatkami owsianymi bez cukru z Przepisów dla niemowląt, gotowa w 10 minut, utrzyma zdrowy bilans w narzędziu do śledzenia karmienia.', title_pt = 'O gosto por queques 🧁', body_pt = 'Quer doces? Não corra para o supermercado. Com um queque caseiro de banana e aveia sem açúcar, feito em 10 minutos com as Receitas para bebés, mantenha o equilíbrio saudável no Registo de Alimentação.', title_sv = 'Kärlek till muffins 🧁', body_sv = 'Vill barnet ha något sött? Rusa inte till affären. Värna om hälsopoängen i Matningskoll med en sockerfri hemgjord muffins med banan och havre på 10 minuter från Recept för bebisar.', title_vi = 'Mê bánh muffin 🧁', body_vi = 'Bé đòi ăn đồ ngọt? Đừng vội ra siêu thị. Hãy làm bánh muffin chuối yến mạch không đường trong 10 phút từ Công thức cho bé để giữ điểm lành mạnh trong Theo dõi cữ bú.', title_zh = '爱吃玛芬 🧁', body_zh = '想吃甜的？别跑去超市。用宝宝食谱里10分钟就能做好的无糖香蕉燕麦家常玛芬，守住喂养记录工具里的健康分。' WHERE id = '9728ea76-627d-4390-8b60-df7f4a0dc917' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía en 5 minutos ⚡', body_es = 'No corras a las tareas de casa por la mañana. Prepara en Recetas saludables para mujeres una avena con frutos rojos cargada de antioxidantes y renueva tu cuerpo.', title_fr = '5 minutes d''énergie ⚡', body_fr = 'Ne vous ruez pas sur les tâches ménagères le matin. Préparez des flocons d''avoine aux baies, pleins d''antioxydants, avec les Recettes saines pour femmes et ressourcez votre corps.', title_hi = '5 मिनट की ऊर्जा ⚡', body_hi = 'सुबह घर के कामों की ओर मत भागिए। महिलाओं के लिए सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर बेरी वाले ओट्स बनाइए और अपने शरीर को तरोताज़ा कीजिए।', title_id = 'Energi 5 menit ⚡', body_id = 'Jangan buru-buru mengerjakan pekerjaan rumah di pagi hari. Buat oat beri kaya antioksidan dari Resep Sehat untuk wanita dan segarkan kembali tubuh Anda.', title_ja = '5分でエネルギー ⚡', body_ja = '朝から家事に走らないで。「女性のためのヘルシーレシピ」から抗酸化物質たっぷりのベリーのオートミールをつくって、体をリフレッシュさせましょう。', title_ko = '5분 에너지 ⚡', body_ko = '아침부터 집안일로 달려가지 마세요. 여성을 위한 건강한 레시피에서 항산화 성분 가득한 베리 오트밀을 만들어 몸에 활력을 채우세요.', title_nl = 'Energie in 5 minuten ⚡', body_nl = 'Ren ''s ochtends niet meteen naar het huishouden. Maak uit Gezonde recepten voor vrouwen havermout met bessen vol antioxidanten en geef je lichaam nieuwe energie.', title_pl = 'Energia w 5 minut ⚡', body_pl = 'Nie rzucaj się rano w wir obowiązków. Przygotuj ze Zdrowych przepisów dla kobiet owsiankę z owocami jagodowymi pełną antyoksydantów i odnów organizm.', title_pt = 'Energia em 5 minutos ⚡', body_pt = 'De manhã, não corra para as tarefas da casa. Prepare com as Receitas Saudáveis para Mulheres papas de aveia com frutos vermelhos, cheias de antioxidantes, e renove o seu corpo.', title_sv = 'Energi på 5 minuter ⚡', body_sv = 'Rusa inte till hushållssysslorna på morgonen. Gör havregrynsgröt med bär full av antioxidanter från Hälsosamma recept för kvinnor och ge kroppen ny kraft.', title_vi = 'Năng lượng trong 5 phút ⚡', body_vi = 'Buổi sáng đừng vội lao vào việc nhà. Hãy làm món yến mạch quả mọng giàu chất chống oxy hóa từ Công thức lành mạnh cho phụ nữ để cơ thể được tái tạo.', title_zh = '5分钟能量补给 ⚡', body_zh = '早上别急着做家务。从女性健康食谱里做一份富含抗氧化物的莓果燕麦，让身体焕然一新。' WHERE id = '685f831c-092e-4c6a-aaf1-8fc0973b0182' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se frota los ojos? 🥱', body_es = '¡Llegan las señales de sueño! Pon el temporizador de sueño, el susurro del bosque de Ruido blanco para llevarle con calma al sueño y sigue el gráfico.', title_fr = 'Il se frotte les yeux ? 🥱', body_fr = 'Les signaux du sommeil arrivent ! Lancez le minuteur de sommeil, mettez le bruissement de la forêt des Bruits blancs pour l''amener doucement vers le sommeil, et suivez le graphique.', title_hi = 'आँखें मल रहा है? 🥱', body_hi = 'नींद के संकेत आ रहे हैं! स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में जंगल की सरसराहट लगाकर उसे शांति से नींद के लिए तैयार कीजिए और चार्ट पर नज़र रखिए।', title_id = 'Mengucek mata? 🥱', body_id = 'Tanda-tanda mengantuk muncul! Nyalakan Timer Tidur, putar suara gemerisik hutan dari Suara Putih untuk mengantarnya tidur dengan tenang, dan pantau grafiknya.', title_ja = '目をこすっている？🥱', body_ja = '眠いサインが出ています！睡眠タイマーをオンにして、「ホワイトノイズ」の森のざわめきを流し、静かに眠りへ導きながら、グラフを見守りましょう。', title_ko = '눈을 비비나요? 🥱', body_ko = '졸음 신호가 왔어요! 수면 타이머를 켜고 백색소음의 숲 바스락 소리로 조용히 잠들 준비를 도와준 뒤 그래프를 확인하세요.', title_nl = 'Wrijft hij in zijn ogen? 🥱', body_nl = 'De slaapsignalen komen! Zet de Slaaptimer aan, laat hem met bosgeruis uit Witte ruis rustig in slaap vallen en volg de grafiek.', title_pl = 'Trze oczka? 🥱', body_pl = 'Pojawiają się sygnały senności! Włącz timer snu, puść szum lasu z Białego szumu, spokojnie nastrój go do snu i śledź wykres.', title_pt = 'Está a esfregar os olhos? 🥱', body_pt = 'Chegam os sinais de sono! Ligue o temporizador de sono, ponha o sussurro da floresta do Ruído Branco, prepare-o com calma para dormir e acompanhe o gráfico.', title_sv = 'Gnuggar ögonen? 🥱', body_sv = 'Sömnsignalerna kommer! Starta sömntimern, sätt på skogens sus från Vitt brus, stäm lugnt barnet för sömn och följ grafen.', title_vi = 'Bé dụi mắt? 🥱', body_vi = 'Dấu hiệu buồn ngủ đã đến! Hãy bật Bộ hẹn giờ ngủ, mở tiếng rừng xào xạc trong Tiếng ồn trắng để nhẹ nhàng đưa bé vào giấc ngủ và theo dõi biểu đồ.', title_zh = '在揉眼睛？🥱', body_zh = '困了的信号来了！打开睡眠计时器，播放白噪音里的森林沙沙声，让宝宝平静地进入睡眠，再看看图表。' WHERE id = '2ac666c9-f3bd-4794-a981-76652151d626' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del café de mamá ☕', body_es = 'Ahora toca pausa. Mientras tu peque juega a su aire, recarga energía con un té verde lleno de antioxidantes o un café suave de Recetas saludables para mujeres.', title_fr = 'L''heure du café de maman ☕', body_fr = 'C''est l''heure de la pause. Pendant qu''il joue tout seul, rechargez-vous avec un thé vert riche en antioxydants ou un café léger grâce aux Recettes saines pour femmes.', title_hi = 'माँ का कॉफ़ी टाइम ☕', body_hi = 'अब ब्रेक का समय है। जब बच्चा अपने आप खेल रहा हो, महिलाओं के लिए सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर ग्रीन टी या हल्की कॉफ़ी से अपनी ऊर्जा लौटाइए।', title_id = 'Jam kopi Bunda ☕', body_id = 'Sekarang waktunya rehat. Selagi si kecil asyik bermain sendiri, segarkan energi Anda dengan teh hijau kaya antioksidan atau kopi ringan dari Resep Sehat untuk wanita.', title_ja = 'ママのコーヒータイム ☕', body_ja = '今は休憩の時間です。お子さんがひとりで遊んでいる間に、「女性のためのヘルシーレシピ」から抗酸化物質たっぷりの緑茶か軽めのコーヒーで、エネルギーをチャージしましょう。', title_ko = '엄마의 커피 시간 ☕', body_ko = '이제 쉬는 시간이에요. 아이가 혼자 노는 동안 여성을 위한 건강한 레시피에서 항산화 성분 가득한 녹차나 연한 커피로 기운을 채우세요.', title_nl = 'Koffietijd voor mama ☕', body_nl = 'Tijd voor een pauze. Terwijl je kindje zelf speelt, laad je jezelf op met groene thee vol antioxidanten of lichte koffie uit Gezonde recepten voor vrouwen.', title_pl = 'Kawowa chwila mamy ☕', body_pl = 'Teraz czas na przerwę. Gdy maluch bawi się sam, odnów energię zieloną herbatą pełną antyoksydantów albo lekką kawą ze Zdrowych przepisów dla kobiet.', title_pt = 'A hora do café da mãe ☕', body_pt = 'Agora é hora de uma pausa. Enquanto ele brinca sozinho, renove a energia com um chá verde rico em antioxidantes ou um café leve das Receitas Saudáveis para Mulheres.', title_sv = 'Mammas kaffestund ☕', body_sv = 'Nu är det dags för en paus. Medan barnet leker för sig själv, ladda om energin med grönt te fullt av antioxidanter eller ett milt kaffe från Hälsosamma recept för kvinnor.', title_vi = 'Giờ cà phê của mẹ ☕', body_vi = 'Giờ là lúc nghỉ giải lao. Khi bé đang tự chơi, hãy nạp lại năng lượng bằng trà xanh giàu chất chống oxy hóa hoặc cà phê nhẹ từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的咖啡时间 ☕', body_zh = '现在是休息时间。孩子自己玩的时候，从女性健康食谱里来一杯富含抗氧化物的绿茶或淡咖啡，恢复精力吧。' WHERE id = '5ce76677-164d-4bc6-835d-9ba614b47d9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se sube por las paredes en casa? 🧗', body_es = '¡Necesita gastar energía! Abre el mapa de Lugares para mamás, descubre un parque nuevo con zona segura para correr y tobogán, y déjale jugar a su aire.', title_fr = 'Il grimpe aux murs à la maison ? 🧗', body_fr = 'Il doit absolument se dépenser ! Ouvrez la carte des Lieux adaptés aux mamans, découvrez un nouveau parc avec un toboggan et un espace sûr pour courir, et laissez-le libre.', title_hi = 'घर में दीवारों पर चढ़ता है? 🧗', body_hi = 'ऊर्जा निकालना ज़रूरी है! माँ के लिए अनुकूल जगहें का नक्शा खोलिए, दौड़ने की सुरक्षित जगह और स्लाइड वाला नया पार्क खोजिए और उसे खुलकर खेलने दीजिए।', title_id = 'Memanjat dinding di rumah? 🧗', body_id = 'Energinya harus tersalurkan! Buka peta Tempat Ramah Ibu, temukan taman baru dengan area lari dan perosotan yang aman, dan biarkan ia bebas bermain.', title_ja = '家の中で壁によじ登る？🧗', body_ja = 'エネルギーを発散させることが大切！「ママにやさしいスポット」のマップを開いて、安全に走れる場所やすべり台のある新しい公園を見つけ、思いきり遊ばせてあげましょう。', title_ko = '집에서 벽을 타고 오르나요? 🧗', body_ko = '에너지를 꼭 발산해야 해요! 엄마 친화 장소 지도를 열어 안전하게 뛸 공간과 미끄럼틀이 있는 새 공원을 찾아 마음껏 놀게 해 주세요.', title_nl = 'Klimt hij thuis tegen de muren op? 🧗', body_nl = 'Hij moet zijn energie kwijt! Open de kaart Mamavriendelijke plekken, ontdek een nieuw park met een veilige renplek en glijbaan en laat hem vrij spelen.', title_pl = 'W domu wspina się po ścianach? 🧗', body_pl = 'Musi rozładować energię! Otwórz mapę Miejsc przyjaznych mamom, odkryj nowy park z bezpiecznym miejscem do biegania i zjeżdżalnią i pozwól mu się wyszaleć.', title_pt = 'Em casa trepa pelas paredes? 🧗', body_pt = 'Gastar energia é indispensável! Abra o mapa dos Locais Amigos das Mães, descubra um parque novo com espaço seguro para correr e escorrega e deixe-o à vontade.', title_sv = 'Klättrar på väggarna hemma? 🧗', body_sv = 'Energin måste ut! Öppna kartan i Mammavänliga platser, upptäck en ny park med säker yta att springa på och rutschkana och låt barnet röra sig fritt.', title_vi = 'Bé leo cả lên tường trong nhà? 🧗', body_vi = 'Bé rất cần được xả năng lượng! Hãy mở bản đồ Địa điểm thân thiện với mẹ, khám phá một công viên mới có khu chạy nhảy an toàn và cầu trượt để bé tự do vui chơi.', title_zh = '在家里爬墙？🧗', body_zh = '一定要释放精力！打开妈妈友好场所地图，发现一个有安全跑步区和滑梯的新公园，让宝宝尽情撒欢。' WHERE id = '35dcaff3-d09c-4c5a-87b5-8fa048fa86b8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Huida de la mesa! 🏃‍♂️', body_es = '¿Deja la comida a medias y sale corriendo? Para el temporizador de tomas. En lugar de obligarle a comer, lee en el Blog los secretos para abrirle el apetito de forma natural.', title_fr = 'Évasion de table ! 🏃‍♂️', body_fr = 'Il abandonne son repas en plein milieu pour filer ? Arrêtez le minuteur des repas. Au lieu de le forcer, lisez dans la rubrique Blogs les secrets pour ouvrir l''appétit naturellement.', title_hi = 'मेज़ से भागना! 🏃‍♂️', body_hi = 'खाना बीच में छोड़कर भाग जाता है? फ़ीडिंग टाइमर रोकिए। ज़बरदस्ती खिलाने के बजाय ब्लॉग सेक्शन में भूख को कुदरती तरीके से खोलने के राज़ पढ़िए।', title_id = 'Kabur dari meja makan! 🏃‍♂️', body_id = 'Meninggalkan makanannya di tengah jalan lalu kabur? Hentikan Timer Makan. Daripada memaksanya makan, baca rahasia membuka nafsu makan secara alami di bagian Blog.', title_ja = '食卓から脱走！🏃‍♂️', body_ja = '食事を途中でやめて逃げていきますか？食事タイマーを止めましょう。無理に食べさせる代わりに、自然に食欲を引き出すコツをブログで読んでみましょう。', title_ko = '식탁 탈출! 🏃‍♂️', body_ko = '밥을 먹다 말고 도망가나요? 수유 타이머를 멈추세요. 억지로 먹이는 대신 블로그에서 자연스럽게 입맛을 살리는 비결을 읽어 보세요.', title_nl = 'Ontsnapping van tafel! 🏃‍♂️', body_nl = 'Laat hij zijn eten halverwege staan en rent hij weg? Stop de Voedingstimer. Dwing hem niet, maar lees in Blogs de geheimen om zijn eetlust op een natuurlijke manier op te wekken.', title_pl = 'Ucieczka od stołu! 🏃‍♂️', body_pl = 'Zostawia jedzenie w połowie i ucieka? Zatrzymaj timer karmienia. Zamiast karmić na siłę, przeczytaj w sekcji Blog sekrety naturalnego pobudzania apetytu.', title_pt = 'Fuga da mesa! 🏃‍♂️', body_pt = 'Deixa a comida a meio e foge? Pare o temporizador de alimentação. Em vez de o obrigar a comer, leia nos Blogues os segredos para abrir o apetite de forma natural.', title_sv = 'Flykt från bordet! 🏃‍♂️', body_sv = 'Lämnar barnet maten halvfärdig och springer iväg? Stoppa matningstimern. I stället för att tvångsmata, läs i Bloggar om hemligheterna bakom att väcka aptiten på ett naturligt sätt.', title_vi = 'Trốn khỏi bàn ăn! 🏃‍♂️', body_vi = 'Bé bỏ dở bữa ăn và chạy đi? Hãy dừng Hẹn giờ cho bú. Thay vì ép bé ăn, hãy đọc bí quyết giúp bé ăn ngon miệng một cách tự nhiên trong mục Blog.', title_zh = '从餐桌逃跑！🏃‍♂️', body_zh = '饭吃到一半就跑了？停下喂养计时器。与其强迫喂饭，不如去博客板块读读自然打开胃口的秘诀。' WHERE id = '3eefbe35-a241-4512-8320-0993efa296ef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué le aprietan los zapatos? 👟', body_es = '¿Tropieza a menudo al correr? ¡Puede que le haya crecido el pie! Introduce sus medidas actuales en el Seguimiento del desarrollo, comprueba si hay un estirón y analiza su crecimiento.', title_fr = 'Pourquoi les chaussures serrent ? 👟', body_fr = 'Il trébuche souvent en courant ? Son pied a peut-être grandi ! Entrez ses mesures actuelles dans le Suivi de croissance pour vérifier tout de suite s''il y a un pic de croissance.', title_hi = 'जूते तंग क्यों हैं? 👟', body_hi = 'दौड़ते समय अक्सर लड़खड़ाता है? शायद पैर बड़े हो गए हैं! ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और ग्रोथ स्पर्ट को तुरंत जाँचकर विकास का विश्लेषण कीजिए।', title_id = 'Kenapa sepatunya sesak? 👟', body_id = 'Sering tersandung saat berlari? Kakinya mungkin sudah bertambah besar! Masukkan ukuran terbarunya ke Pelacak Perkembangan, cek lonjakan pertumbuhannya, dan analisis perkembangannya.', title_ja = 'どうして靴がきついの？👟', body_ja = '走るとよくつまずきますか？足が大きくなったのかもしれません！「発達トラッカー」に今のサイズを入力して、成長期かどうかすぐに確認し、成長を分析しましょう。', title_ko = '신발이 왜 끼죠? 👟', body_ko = '뛰다가 자주 넘어지나요? 발이 자랐을 수도 있어요! 성장 기록에 현재 치수를 입력하고 성장 급등기인지 바로 확인해 보세요.', title_nl = 'Waarom knellen de schoenen? 👟', body_nl = 'Struikelt hij vaak bij het rennen? Zijn voetjes kunnen gegroeid zijn! Voer de huidige maten in de Groeitracker in, check meteen of er een groeispurt is en volg zijn groei.', title_pl = 'Dlaczego buty uciskają? 👟', body_pl = 'Często potyka się podczas biegania? Może urosła mu stopa! Wpisz aktualne wymiary w Śledzeniu rozwoju, od razu sprawdź skok wzrostowy i przeanalizuj, jak rośnie.', title_pt = 'Porque é que os sapatos apertam? 👟', body_pt = 'Tropeça muito quando corre? O pé pode ter crescido! Introduza as medidas atuais no Registo de Desenvolvimento, verifique já o salto de crescimento e analise a evolução.', title_sv = 'Varför klämmer skorna? 👟', body_sv = 'Snubblar barnet ofta när hen springer? Foten kan ha växt! Ange aktuella mått i Utvecklingsspåraren, kontrollera tillväxtspurten direkt och analysera tillväxten.', title_vi = 'Vì sao giày bị chật? 👟', body_vi = 'Bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập số đo hiện tại vào Theo dõi phát triển để kiểm tra ngay giai đoạn tăng trưởng vọt và phân tích sự phát triển.', title_zh = '鞋子为什么挤脚？👟', body_zh = '跑的时候经常绊倒？可能是脚长大了！在发育追踪里输入当前的尺寸，马上看看是否到了生长突增期，分析成长情况。' WHERE id = 'ecf28bb2-147f-47c5-8e81-503885a13db6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos ⏱️', body_es = '¡Pon el temporizador de sueño! Analiza con precisión en el gráfico de estadísticas si se trata de terrores nocturnos o de una regresión del sueño y ajusta la rutina.', title_fr = 'Réveils nocturnes ⏱️', body_fr = 'Lancez le minuteur de sommeil ! Analysez précisément sur son graphique statistique s''il s''agit de terreurs nocturnes ou d''une régression du sommeil, puis ajustez son rythme.', title_hi = 'रात में जागना ⏱️', body_hi = 'स्लीप टाइमर चालू कीजिए! टाइमर के आँकड़ों वाले चार्ट से सटीक समझिए कि कहीं यह नाइट टेरर या स्लीप रिग्रेशन तो नहीं, और रूटीन ठीक कीजिए।', title_id = 'Terbangun di malam hari ⏱️', body_id = 'Nyalakan Timer Tidur! Analisis grafik statistik timer dengan akurat untuk melihat apakah ini teror malam atau regresi tidur, lalu atur rutinitasnya.', title_ja = '夜中に起きる ⏱️', body_ja = '睡眠タイマーをオンにしましょう！夜驚症なのか睡眠退行なのか、タイマーの統計グラフでしっかり分析して、生活リズムを整えましょう。', title_ko = '밤에 깨요 ⏱️', body_ko = '수면 타이머를 켜세요! 야경증인지 수면 퇴행인지 타이머의 통계 그래프로 정확히 분석하고 일과를 조절하세요.', title_nl = 'Nachtelijk wakker worden ⏱️', body_nl = 'Zet de Slaaptimer aan! Analyseer in de statistiekgrafiek van de timer of het om nachtangst of een slaapregressie gaat, en pas het ritme aan.', title_pl = 'Nocne pobudki ⏱️', body_pl = 'Włącz timer snu! Na wykresie statystyk dokładnie sprawdzisz, czy to lęki nocne, czy regres snu, i dopasujesz rytm dnia.', title_pt = 'Despertares noturnos ⏱️', body_pt = 'Ligue o temporizador de sono! Analise com precisão no gráfico de estatísticas se se trata de terrores noturnos ou de uma regressão do sono e ajuste a rotina.', title_sv = 'Nattliga uppvaknanden ⏱️', body_sv = 'Starta sömntimern! Analysera noga med timerns statistikgraf om det kan vara nattskräck eller sömnregression och justera rytmen.', title_vi = 'Thức giấc ban đêm ⏱️', body_vi = 'Hãy bật Bộ hẹn giờ ngủ! Phân tích chính xác biểu đồ thống kê để xem bé có bị hoảng sợ ban đêm hay thoái lui giấc ngủ không và điều chỉnh nếp sinh hoạt.', title_zh = '夜间醒来 ⏱️', body_zh = '打开睡眠计时器！从计时器的统计图表中准确分析是夜惊还是睡眠倒退，调整作息。' WHERE id = 'a2d43041-fecf-4b9c-87c8-b48f899e1810' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Su inteligencia no para de crecer 🧠', body_es = '¡Le encanta clasificarlo todo! Descubre ya en Productos recomendados rompecabezas geométricos que estimulan el cerebro y mejoran la percepción de colores y formas.', title_fr = 'Son intelligence ne cesse de grandir 🧠', body_fr = 'Il adore tout trier ! Découvrez tout de suite dans les Produits recommandés des puzzles géométriques qui stimulent le cerveau et la perception des couleurs et des formes.', title_hi = 'बुद्धि का विकास रुकता नहीं 🧠', body_hi = 'उसे हर चीज़ छाँटना पसंद है! रंग और आकार की समझ बढ़ाने वाली, दिमाग को सक्रिय करने वाली ज्यामितीय पहेलियाँ (पज़ल) तुरंत सुझाए गए प्रोडक्ट में खोजिए।', title_id = 'Kecerdasannya terus berkembang 🧠', body_id = 'Ia suka memilah-milah segala hal! Segera temukan puzzle geometri yang menstimulasi otak dan meningkatkan pengenalan warna dan bentuk di Produk Rekomendasi.', title_ja = '知性の発達は止まらない 🧠', body_ja = 'なんでも分類するのが大好き！色や形の認識を育て、脳を刺激する図形パズルを、すぐに「おすすめ商品」で見つけましょう。', title_ko = '두뇌 발달은 멈추지 않아요 🧠', body_ko = '뭐든 분류하는 걸 좋아해요! 색과 모양 인지를 키우고 두뇌를 자극하는 도형 퍼즐을 추천 제품에서 바로 찾아보세요.', title_nl = 'De slimheid groeit door 🧠', body_nl = 'Hij sorteert graag alles! Ontdek meteen in Aanbevolen producten geometrische puzzels die kleur- en vormherkenning versterken en de hersenen prikkelen.', title_pl = 'Umysł nieustannie się rozwija 🧠', body_pl = 'Uwielbia wszystko sortować! Od razu odkryj w Polecanych produktach geometryczne układanki, które rozwijają postrzeganie kolorów i kształtów i stymulują mózg.', title_pt = 'A inteligência não para de crescer 🧠', body_pt = 'Adora separar tudo por grupos! Descubra já nos Produtos Recomendados puzzles geométricos que estimulam o cérebro e melhoram a perceção de cores e formas.', title_sv = 'Tänkandet utvecklas hela tiden 🧠', body_sv = 'Barnet älskar att sortera allt! Upptäck direkt geometriska pussel som stimulerar hjärnan och stärker uppfattningen av färger och former i Rekommenderade produkter.', title_vi = 'Trí tuệ không ngừng phát triển 🧠', body_vi = 'Bé thích phân loại mọi thứ! Hãy khám phá ngay trong Sản phẩm gợi ý các trò ghép hình học (puzzle) giúp kích thích não bộ, tăng khả năng nhận biết màu sắc và hình dạng.', title_zh = '智力发展从不停歇 🧠', body_zh = '宝宝什么都爱分类！马上去推荐商品发现能提升颜色和形状认知、刺激大脑的几何拼图。' WHERE id = 'ca7d5385-3628-4318-a29d-52e41611d6dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🌟', body_es = 'Cada nueva habilidad que aprende es fruto de tu esfuerzo. ¡Abre el Diario de ánimo y escribe hoy una nota para aplaudirte de pie!', title_fr = 'L''héroïne du jour, c''est vous 🌟', body_fr = 'Chaque nouvelle compétence qu''il apprend, c''est grâce à vous. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note qui mérite une ovation debout !', title_hi = 'आज की हीरो आप हैं 🌟', body_hi = 'हर दिन वह जो नई चीज़ सीखता है, वह आपकी मेहनत है। मूड डायरी खोलिए और आज खुद को शाबाशी देने वाली एक बात लिखिए!', title_id = 'Pahlawan hari ini adalah Anda 🌟', body_id = 'Setiap keterampilan baru yang ia pelajari adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati dan tulis catatan yang membuat Anda bertepuk tangan untuk diri sendiri hari ini!', title_ja = '今日のヒーローはあなたです 🌟', body_ja = '毎日新しくできるようになることは、あなたのがんばりのおかげです。「気分日記」を開いて、今日の自分にスタンディングオベーションを送るメモを書きましょう！', title_ko = '오늘의 주인공은 엄마예요 🌟', body_ko = '아이가 매일 배우는 새로운 능력은 엄마의 노력 덕분이에요. 기분 일기를 열고 오늘의 나에게 기립 박수를 보낼 기록을 남겨 보세요!', title_nl = 'Jij bent de held van vandaag 🌟', body_nl = 'Elke nieuwe vaardigheid die hij leert, is dankzij jou. Open je Stemmingsdagboek en schrijf vandaag een notitie waarmee je jezelf een staande ovatie geeft!', title_pl = 'Dzisiejszą bohaterką jesteś ty 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, to twoja zasługa. Otwórz Dziennik nastroju i napisz dziś notatkę, za którą nagrodzisz się owacją na stojąco!', title_pt = 'A heroína do dia é a mãe 🌟', body_pt = 'Cada nova competência que ele aprende é fruto do seu esforço. Abra o Diário de Humor e escreva hoje uma nota que a faça aplaudir-se de pé!', title_sv = 'Dagens hjälte är du 🌟', body_sv = 'Varje ny färdighet barnet lär sig är tack vare ditt arbete. Öppna Humördagboken och skriv en anteckning i dag som ger dig själv stående ovationer!', title_vi = 'Mẹ là người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng để tự vỗ tay cho mình hôm nay!', title_zh = '今天的英雄是你 🌟', body_zh = '宝宝每天学会的新本领都有你的功劳。打开心情日记，写下一句为自己热烈鼓掌的话吧！' WHERE id = '2c09d1ae-89ad-4429-b136-e47270b6a957' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Encuentra bien las figuras? 🧩', body_es = 'Para apoyar su desarrollo lógico, busca ya en Productos recomendados rompecabezas geométricos y juguetes educativos de madera adecuados a su edad.', title_fr = 'Il trouve les bonnes formes ? 🧩', body_fr = 'Pour soutenir son développement logique, cherchez tout de suite dans les Produits recommandés des puzzles géométriques et des jouets éducatifs en bois adaptés à son âge.', title_hi = 'आकृतियाँ सही ढूँढता है? 🧩', body_hi = 'तार्किक विकास में मदद के लिए उम्र के हिसाब से ज्यामितीय पहेलियाँ (पज़ल) और सिखाने वाले लकड़ी के खिलौने तुरंत सुझाए गए प्रोडक्ट में खोजिए।', title_id = 'Menemukan bentuk dengan tepat? 🧩', body_id = 'Untuk mendukung perkembangan logikanya, segera cari puzzle geometri dan mainan kayu edukatif sesuai usia di Produk Rekomendasi.', title_ja = '形をちゃんと見つけられる？🧩', body_ja = '論理的な思考の発達を応援するために、年齢に合った図形パズルや木の知育おもちゃを、すぐに「おすすめ商品」で探してみましょう。', title_ko = '모양을 척척 찾나요? 🧩', body_ko = '논리 발달을 돕고 싶다면 연령별 도형 퍼즐과 교육용 원목 장난감을 추천 제품에서 바로 찾아보세요.', title_nl = 'Vindt hij de juiste vormpjes? 🧩', body_nl = 'Zoek meteen in Aanbevolen producten geometrische puzzels en leerzaam houten speelgoed voor zijn leeftijd om zijn logische ontwikkeling te steunen.', title_pl = 'Dobrze dopasowuje figury? 🧩', body_pl = 'Aby wspierać rozwój logicznego myślenia, od razu poszukaj w Polecanych produktach geometrycznych układanek i edukacyjnych drewnianych zabawek dopasowanych do wieku.', title_pt = 'Encontra bem as formas? 🧩', body_pt = 'Para apoiar o desenvolvimento lógico, procure já nos Produtos Recomendados puzzles geométricos adequados à idade e brinquedos educativos de madeira.', title_sv = 'Hittar rätt figurer? 🧩', body_sv = 'Leta direkt efter åldersanpassade geometriska pussel och lärorika träleksaker i Rekommenderade produkter för att stötta den logiska utvecklingen.', title_vi = 'Bé tìm đúng các hình khối? 🧩', body_vi = 'Để hỗ trợ phát triển tư duy, hãy tìm ngay các trò ghép hình học (puzzle) và đồ chơi gỗ giáo dục phù hợp lứa tuổi trong Sản phẩm gợi ý.', title_zh = '能找对形状了？🧩', body_zh = '为了支持逻辑发展，马上去推荐商品找找适龄的几何拼图和木制益智玩具。' WHERE id = 'c795e5c9-7249-46e0-9227-8cae7b9774c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Qué tal su reserva de proteínas? 🥚', body_es = 'Unos músculos que crecen tan rápido necesitan proteínas. Calcula con el Seguimiento de tomas la ración de hoy y, si falta algo, ajusta el menú.', title_fr = 'Où en sont ses protéines ? 🥚', body_fr = 'Les protéines sont indispensables à des muscles qui grandissent vite. Calculez sa ration du jour avec le Suivi des repas et ajustez le menu s''il en manque.', title_hi = 'प्रोटीन का भंडार कैसा है? 🥚', body_hi = 'तेज़ी से बढ़ती मांसपेशियों के लिए प्रोटीन ज़रूरी है। फ़ीडिंग ट्रैकर से आज की मात्रा गिनिए और कमी हो तो मेन्यू ठीक कीजिए।', title_id = 'Bagaimana cadangan proteinnya? 🥚', body_id = 'Otot yang tumbuh pesat butuh protein. Hitung kebutuhan hari ini dengan alat Pemantau Nutrisi dan sesuaikan menunya jika ada kekurangan.', title_ja = 'たんぱく質は足りている？🥚', body_ja = 'ぐんぐん育つ筋肉には、たんぱく質が欠かせません。「栄養管理ツール」で今日の目安量を計算して、足りなければメニューを調整しましょう。', title_ko = '단백질은 충분한가요? 🥚', body_ko = '빠르게 자라는 근육에는 단백질이 꼭 필요해요. 수유 기록 도구로 오늘의 기준량을 계산하고 부족하다면 식단을 조절하세요.', title_nl = 'Hoe staat het met eiwit? 🥚', body_nl = 'Eiwit is onmisbaar voor snel groeiende spieren. Bereken met de Voedingstracker de norm van vandaag en pas bij een tekort het menu aan.', title_pl = 'Jak tam zapas białka? 🥚', body_pl = 'Białko jest niezbędne dla szybko rosnących mięśni. Oblicz w narzędziu do śledzenia karmienia dzisiejszą normę, a jeśli czegoś brakuje, dopasuj menu.', title_pt = 'Como estão as reservas de proteína? 🥚', body_pt = 'Músculos que crescem depressa precisam de proteína. Calcule com o Registo de Alimentação a dose de hoje e, se faltar, ajuste a ementa.', title_sv = 'Hur är det med proteinförrådet? 🥚', body_sv = 'Muskler som växer snabbt behöver protein. Räkna ut dagens norm med Matningskoll och justera menyn om något fattas.', title_vi = 'Lượng đạm thế nào rồi? 🥚', body_vi = 'Cơ bắp phát triển nhanh rất cần đạm. Hãy tính định mức hôm nay bằng Theo dõi cữ bú và điều chỉnh thực đơn nếu còn thiếu.', title_zh = '蛋白质储备怎么样？🥚', body_zh = '快速生长的肌肉离不开蛋白质。用喂养记录工具算一算今天的参考量，如有不足就调整菜单。' WHERE id = 'ce8c0e6d-8b04-4829-9134-54da2f1cc621' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las primeras conversaciones serias 🗣️', body_es = '¿Te cuenta largo y tendido cosas en su propio idioma? Guarda este momento tan gracioso y valioso en vídeo con sonido en el Álbum del bebé.', title_fr = 'Premières vraies conversations 🗣️', body_fr = 'Il vous raconte de longues histoires dans sa langue à lui ? Gardez ce moment drôle et précieux en vidéo avec le son dans l''Album de bébé.', title_hi = 'पहली गंभीर बातचीत 🗣️', body_hi = 'अपनी भाषा में आपसे लंबी-लंबी बातें करता है? इस मज़ेदार और अनमोल पल को आवाज़ वाले वीडियो के रूप में बेबी एल्बम में सहेजिए।', title_id = 'Obrolan serius pertama 🗣️', body_id = 'Ia membahas sesuatu panjang lebar dengan Anda dalam bahasanya sendiri? Simpan momen lucu dan berharga ini sebagai video bersuara di Album Bayi.', title_ja = 'はじめての本格的なおしゃべり 🗣️', body_ja = '自分の言葉で、あなたと長々と何かを話し合っていますか？このおもしろくて宝物のような瞬間を、音声付きの動画で「ベビーアルバム」に残しましょう。', title_ko = '첫 진지한 대화 🗣️', body_ko = '자기만의 말로 엄마와 한참 무언가를 이야기하나요? 이 재미있고 금쪽같은 순간을 소리가 담긴 영상으로 아기 앨범에 남기세요.', title_nl = 'De eerste serieuze gesprekken 🗣️', body_nl = 'Bespreekt hij uitgebreid iets met je in zijn eigen taal? Bewaar dit grappige, goudwaardige moment als video met geluid in het Babyalbum.', title_pl = 'Pierwsze poważne rozmowy 🗣️', body_pl = 'Długo coś z tobą omawia w swoim języku? Zapisz tę zabawną i bezcenną chwilę jako film z dźwiękiem w Albumie dziecka.', title_pt = 'As primeiras conversas a sério 🗣️', body_pt = 'Discute consigo longamente qualquer coisa na sua própria língua? Guarde este momento divertido e de ouro em vídeo com som no Álbum do Bebé.', title_sv = 'De första allvarliga samtalen 🗣️', body_sv = 'Diskuterar barnet något länge med dig på sitt eget språk? Spara detta roliga och guldvärda ögonblick som video med ljud i Babyalbumet.', title_vi = 'Những cuộc trò chuyện "nghiêm túc" đầu tiên 🗣️', body_vi = 'Bé bàn luận rất lâu với mẹ bằng ngôn ngữ riêng của mình? Hãy lưu khoảnh khắc ngộ nghĩnh, quý như vàng này bằng video có tiếng trong Album của bé.', title_zh = '第一次认真的对话 🗣️', body_zh = '用自己的语言和你长篇大论地讨论着什么？把这个有趣又珍贵如金的时刻录成有声视频，存进宝宝相册。' WHERE id = 'd5a7dad1-9dd5-40f2-bc6d-27d7e6052c76' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Gritos repentinos! 🛑', body_es = '¿Se tira al suelo cuando no consigue lo que quiere? Pregunta a nuestro asistente experto Anacan AI cómo convertir en juego estas crisis emocionales que aumentan hacia los 23 meses.', title_fr = 'Cris soudains ! 🛑', body_fr = 'Il se jette par terre quand il n''obtient pas ce qu''il veut ? Demandez à notre assistant expert Anacan AI comment transformer en jeu ces crises émotionnelles qui augmentent vers 23 mois.', title_hi = 'अचानक चीखें! 🛑', body_hi = 'मनचाहा न मिले तो ज़मीन पर लोट जाता है? 23वें महीने के करीब बढ़ते इन भावनात्मक तूफ़ानों को खेल में बदलने के तरीके हमारे Anacan AI एक्सपर्ट असिस्टेंट से पूछिए।', title_id = 'Tiba-tiba menjerit! 🛑', body_id = 'Menjatuhkan diri ke lantai saat keinginannya tak terpenuhi? Tanyakan kepada asisten ahli Anacan AI cara mengubah ledakan emosi yang makin sering menjelang usia 23 bulan ini menjadi permainan.', title_ja = '急に叫ぶ！🛑', body_ja = '思いどおりにならないと床にひっくり返りますか？1歳11か月に向けて増えていくこの気持ちの爆発を、遊びに変える方法をAnacan AIのエキスパートアシスタントに聞いてみましょう。', title_ko = '갑작스러운 비명! 🛑', body_ko = '원하는 대로 안 되면 바닥에 드러눕나요? 23개월을 앞두고 늘어나는 감정 폭발을 놀이로 바꾸는 방법을 Anacan AI 전문가 도우미에게 물어보세요.', title_nl = 'Plotselinge schreeuwbuien! 🛑', body_nl = 'Gooit hij zich op de grond als hij zijn zin niet krijgt? Vraag onze Anacan AI-expert hoe je van deze emotionele buien, die rond de 23e maand toenemen, een spelletje maakt.', title_pl = 'Nagłe krzyki! 🛑', body_pl = 'Rzuca się na podłogę, gdy nie dostaje tego, czego chce? Zapytaj naszego eksperta Anacan AI, jak zamienić w zabawę te nasilające się około 23. miesiąca kryzysy emocjonalne.', title_pt = 'Gritos repentinos! 🛑', body_pt = 'Atira-se para o chão quando não consegue o que quer? Pergunte ao nosso assistente especialista Anacan AI como transformar num jogo estas crises emocionais que aumentam perto dos 23 meses.', title_sv = 'Plötsliga skrik! 🛑', body_sv = 'Kastar sig barnet på golvet när hen inte får som hen vill? Fråga vår expertassistent Anacan AI hur du kan göra dessa känslomässiga kriser, som ökar mot 23:e månaden, till en lek.', title_vi = 'Những tiếng hét bất chợt! 🛑', body_vi = 'Bé lăn ra sàn khi không được như ý? Hãy hỏi trợ lý chuyên gia Anacan AI cách biến những cơn bùng nổ cảm xúc ngày càng nhiều khi gần 23 tháng này thành trò chơi.', title_zh = '突然尖叫！🛑', body_zh = '想要的得不到就躺地上打滚？向我们的Anacan AI专家助手问问，如何把临近23个月时越来越多的情绪危机变成游戏。' WHERE id = '6d0154ad-03f9-4392-b21e-d18f214374b2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que no se olvide de beber agua 💧', body_es = '¿Cómo funciona el intestino de un peque que corre tanto? Anota las deposiciones al cambiar el pañal. Si hay riesgo de estreñimiento, mira sin falta en la app recomendaciones de alimentos con fibra natural.', title_fr = 'Qu''il n''oublie pas de boire 💧', body_fr = 'Comment fonctionnent les intestins de votre petit qui court beaucoup ? Notez les selles à chaque change. En cas de risque de constipation, consultez absolument dans l''appli les conseils d''aliments riches en fibres naturelles.', title_hi = 'पानी पीना न भूले 💧', body_hi = 'खूब दौड़ने वाले नन्हे की आँतें कैसे काम कर रही हैं? डायपर बदलते समय पॉटी दर्ज कीजिए। कब्ज़ का खतरा हो तो ऐप में कुदरती फ़ाइबर वाले खाने के सुझाव ज़रूर देखिए।', title_id = 'Jangan sampai lupa minum 💧', body_id = 'Bagaimana kerja usus si kecil yang banyak berlari? Catat kotorannya saat mengganti popok. Jika ada risiko sembelit, pastikan melihat rekomendasi makanan berserat alami di aplikasi.', title_ja = 'お水を飲むのを忘れずに 💧', body_ja = 'よく走り回るお子さんのおなかの調子はどうですか？おむつ替えのときにうんちの様子を記録しましょう。便秘のおそれがあれば、アプリで食物繊維の多い自然な食べ物のおすすめを必ずチェックしましょう。', title_ko = '물 마시는 걸 잊지 않게 💧', body_ko = '많이 뛰는 아이의 장은 잘 움직이고 있나요? 기저귀를 갈 때 배변을 기록하세요. 변비가 걱정된다면 앱에서 자연 섬유질 음식 추천을 꼭 살펴보세요.', title_nl = 'Vergeet niet te drinken 💧', body_nl = 'Hoe werken de darmen van je rennende kleintje? Noteer de ontlasting bij het verschonen. Is er kans op verstopping, bekijk dan zeker in de app tips voor natuurlijk vezelrijk eten.', title_pl = 'Niech nie zapomina pić 💧', body_pl = 'Jak pracują jelitka malucha, który dużo biega? Notuj kupki przy zmianie pieluszki. Jeśli jest ryzyko zaparć, koniecznie zajrzyj w aplikacji do wskazówek o naturalnych produktach bogatych w błonnik.', title_pt = 'Que não se esqueça de beber água 💧', body_pt = 'Como funciona o intestino de um pequenino que corre tanto? Registe as fezes ao mudar a fralda. Se houver risco de prisão de ventre, veja sem falta na app as sugestões de alimentos com fibra natural.', title_sv = 'Glöm inte att dricka vatten 💧', body_sv = 'Hur fungerar magen hos din lilla som springer så mycket? Anteckna avföringen när du byter blöja. Finns risk för förstoppning, titta på tipsen om naturlig fiberrik mat i appen.', title_vi = 'Đừng để bé quên uống nước 💧', body_vi = 'Ruột của bé chạy nhảy nhiều hoạt động thế nào? Hãy ghi lại phân khi thay tã. Nếu có nguy cơ táo bón, nhất định hãy xem gợi ý thực phẩm giàu chất xơ tự nhiên trong ứng dụng.', title_zh = '别忘了喝水 💧', body_zh = '跑个不停的小家伙肠道怎么样？换尿布时记下排便情况。如果有便秘风险，一定去应用里看看天然高纤维食物的建议。' WHERE id = '9e25f59c-eab1-44ee-ae76-e1b1ae42dc4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Miedo a la oscuridad? 🌌', body_es = '¿Llora cuando apagas la luz de la habitación? Pon el sonido del vientre materno (latido del corazón) de Ruido blanco y devuélvele aquella sensación de seguridad perfecta.', title_fr = 'Peur du noir ? 🌌', body_fr = 'Il pleure quand vous éteignez la lumière ? Lancez le son du ventre maternel (battements de cœur) des Bruits blancs pour lui rendre ce sentiment de sécurité parfait d''autrefois.', title_hi = 'अँधेरे से डर? 🌌', body_hi = 'कमरे की बत्ती बुझाते ही रोता है? व्हाइट नॉइज़ में गर्भ की आवाज़ (दिल की धड़कन) चलाकर उसे वही पुराना, पूरा सुरक्षा का एहसास दीजिए।', title_id = 'Takut gelap? 🌌', body_id = 'Menangis saat lampu kamar dimatikan? Putar suara rahim (detak jantung) dari Suara Putih dan beri ia rasa aman yang akrab dan sempurna.', title_ja = '暗いのがこわい？🌌', body_ja = '部屋の電気を消すと泣きますか？「ホワイトノイズ」の胎内の音（心臓の音）を流して、なつかしい、完璧な安心感を届けましょう。', title_ko = '어둠이 무서워요? 🌌', body_ko = '불을 끄면 우나요? 백색소음에서 엄마 배 속 소리(심장 박동)를 틀어 익숙하고 완벽한 안정감을 선물하세요.', title_nl = 'Bang in het donker? 🌌', body_nl = 'Huilt hij als het licht uitgaat? Zet het baarmoedergeluid (hartslag) uit Witte ruis aan en geef hem dat oude, perfecte gevoel van veiligheid.', title_pl = 'Strach przed ciemnością? 🌌', body_pl = 'Płacze, gdy gasisz światło w pokoju? Włącz w Białym szumie odgłosy z brzucha mamy (bicie serca) i daj mu znajome, doskonałe poczucie bezpieczeństwa.', title_pt = 'Medo do escuro? 🌌', body_pt = 'Chora quando apaga a luz do quarto? Ligue no Ruído Branco o som do útero materno (batimento cardíaco) e dê-lhe aquela antiga e perfeita sensação de segurança.', title_sv = 'Mörkrädd? 🌌', body_sv = 'Gråter barnet när du släcker ljuset i rummet? Sätt på ljudet från livmodern (hjärtslag) i Vitt brus och ge barnet den gamla, perfekta känslan av trygghet.', title_vi = 'Bé sợ bóng tối? 🌌', body_vi = 'Bé khóc khi tắt đèn trong phòng? Hãy bật âm thanh trong bụng mẹ (tiếng tim đập) trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn trọn vẹn quen thuộc.', title_zh = '怕黑？🌌', body_zh = '关灯就哭？打开白噪音里的子宫声（心跳声），给宝宝熟悉而完美的安全感。' WHERE id = 'bc4d0552-0cde-4c7a-bca8-4b2551c95ad7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Suelta el cansancio del día 🛋️', body_es = 'Estás agotada de correr detrás de tu peque. Ya duerme: escribe todo el estrés en el Diario de ánimo y sírvete una taza de infusión.', title_fr = 'Évacuez la fatigue du jour 🛋️', body_fr = 'Vous êtes épuisée à force de lui courir après. Il dort : écrivez tout votre stress dans le Journal d''humeur et servez-vous une tasse de tisane.', title_hi = 'दिन की थकान उतारिए 🛋️', body_hi = 'उसके पीछे भागते-भागते आप थककर चूर हो गईं। बच्चा सो गया, अब मूड डायरी में सारा तनाव लिखिए और अपने लिए एक कप हर्बल चाय डालिए।', title_id = 'Lepaskan lelah hari ini 🛋️', body_id = 'Anda kehabisan tenaga karena terus mengejarnya. Si kecil sudah tidur, sekarang tuliskan semua stres di Buku Harian Suasana Hati dan tuang secangkir teh herbal untuk diri Anda.', title_ja = '一日の疲れを手放して 🛋️', body_ja = '追いかけ回して、くたくたですね。お子さんが眠ったら、「気分日記」にストレスを全部書き出して、ハーブティーを一杯いれましょう。', title_ko = '하루의 피로를 털어 내요 🛋️', body_ko = '아이를 쫓아다니느라 기운이 다 빠졌죠. 아이가 잠들었으니 이제 기분 일기에 스트레스를 모두 적고 허브차 한 잔을 따라 보세요.', title_nl = 'Laat de vermoeidheid van de dag los 🛋️', body_nl = 'Je bent uitgeput van het achter hem aan rennen. Hij slaapt: schrijf nu alle stress op in je Stemmingsdagboek en schenk jezelf een kop kruidenthee in.', title_pl = 'Zrzuć zmęczenie dnia 🛋️', body_pl = 'Bieganie za maluchem odebrało ci siły. Zasnął, więc teraz wypisz cały stres w Dzienniku nastroju i nalej sobie filiżankę herbatki ziołowej.', title_pt = 'Deixe o cansaço do dia 🛋️', body_pt = 'Ficou sem forças de tanto correr atrás dele. Ele adormeceu: agora escreva todo o stress no Diário de Humor e sirva-se de uma chávena de chá de ervas.', title_sv = 'Släpp dagens trötthet 🛋️', body_sv = 'Du är helt slut efter att ha sprungit efter barnet. Barnet sover, skriv nu av dig all stress i Humördagboken och häll upp en kopp örtte.', title_vi = 'Gạt bỏ mệt mỏi cả ngày 🛋️', body_vi = 'Chạy theo bé khiến mẹ kiệt sức. Bé đã ngủ, giờ hãy viết hết căng thẳng vào Nhật ký tâm trạng và rót cho mình một tách trà thảo mộc.', title_zh = '卸下一天的疲惫 🛋️', body_zh = '追着宝宝跑得筋疲力尽了。孩子睡着了，现在把所有压力写进心情日记，给自己倒一杯花草茶吧。' WHERE id = '8497fe17-ba82-4513-8de8-e30bada196eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🌟', body_es = 'Cada nueva habilidad que aprende y cada paso seguro que da son fruto de tu esfuerzo. ¡Abre el Diario de ánimo y escribe hoy una nota de la que sentirte orgullosa!', title_fr = 'L''héroïne du jour, c''est vous 🌟', body_fr = 'Chaque nouvelle compétence, chaque pas assuré, c''est grâce à vous. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note dont vous serez fière !', title_hi = 'आज की हीरो आप हैं 🌟', body_hi = 'हर दिन सीखी नई चीज़, हर भरोसे भरा कदम आपकी मेहनत है। मूड डायरी खोलिए और आज खुद पर गर्व करने वाली एक बात लिखिए!', title_id = 'Pahlawan hari ini adalah Anda 🌟', body_id = 'Setiap keterampilan baru dan setiap langkah percaya dirinya adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati dan tulis catatan membanggakan tentang diri Anda hari ini!', title_ja = '今日のヒーローはあなたです 🌟', body_ja = '毎日新しくできるようになること、自信に満ちた一歩一歩は、あなたのがんばりのおかげです。「気分日記」を開いて、今日の自分を誇りに思えるメモを書きましょう！', title_ko = '오늘의 주인공은 엄마예요 🌟', body_ko = '매일 배우는 새로운 능력, 자신 있는 한 걸음 한 걸음이 모두 엄마의 노력이에요. 기분 일기를 열고 오늘 나를 자랑스러워할 뿌듯한 기록을 남겨 보세요!', title_nl = 'Jij bent de held van vandaag 🌟', body_nl = 'Elke nieuwe vaardigheid en elk zelfverzekerd stapje is dankzij jou. Open je Stemmingsdagboek en schrijf vandaag een trotse notitie over jezelf!', title_pl = 'Dzisiejszą bohaterką jesteś ty 🌟', body_pl = 'Każda nowa umiejętność, każdy pewny krok to twoja zasługa. Otwórz Dziennik nastroju i napisz dziś notatkę, z której będziesz naprawdę dumna!', title_pt = 'A heroína do dia é a mãe 🌟', body_pt = 'Cada nova competência que aprende e cada passo confiante são fruto do seu esforço. Abra o Diário de Humor e escreva hoje uma nota que a encha de orgulho em si!', title_sv = 'Dagens hjälte är du 🌟', body_sv = 'Varje ny färdighet barnet lär sig och varje säkert steg är tack vare ditt arbete. Öppna Humördagboken och skriv en anteckning i dag som gör dig riktigt stolt över dig själv!', title_vi = 'Mẹ là người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới, mỗi bước đi tự tin của bé đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng đáng tự hào về bản thân hôm nay!', title_zh = '今天的英雄是你 🌟', body_zh = '宝宝每天学会的新本领、迈出的每一个自信的脚步，都有你的功劳。打开心情日记，写下一句让你为自己骄傲的话吧！' WHERE id = '0347ce08-669e-4477-9fbc-63c1580b9edb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Huye de las verduras? 🥦', body_es = '¿Ha empezado a elegir por colores? Descubre en Recetas para bebé cómo esconder con maña las espinacas y la zanahoria en unas tortitas deliciosas y ábrele el apetito.', title_fr = 'Il fuit dès qu''il voit du vert ? 🥦', body_fr = 'Il trie les aliments par couleur ? Découvrez dans les Recettes pour bébés comment cacher habilement épinards et carottes dans de délicieux pancakes et ouvrez-lui l''appétit.', title_hi = 'हरी सब्ज़ी देखते ही भागता है? 🥦', body_hi = 'रंग देखकर खाना चुनने लगा? बच्चों की रेसिपी में जानिए कि पालक और गाजर को स्वादिष्ट पैनकेक में चतुराई से कैसे छिपाएँ, और उसकी भूख खोलिए।', title_id = 'Kabur saat melihat sayuran hijau? 🥦', body_id = 'Mulai pilih-pilih warna? Temukan di Resep Bayi cara pintar menyembunyikan bayam dan wortel di dalam panekuk yang lezat, dan buka nafsu makannya.', title_ja = '青菜を見ると逃げる？🥦', body_ja = '色で好き嫌いが始まりましたか？「離乳食を始める赤ちゃんのレシピ」で、ほうれん草やにんじんをおいしいパンケーキに上手に隠す方法を見つけて、食欲を引き出しましょう。', title_ko = '채소만 보면 도망가나요? 🥦', body_ko = '색깔로 음식을 가리기 시작했나요? 아기 레시피에서 시금치와 당근을 맛있는 팬케이크 속에 감쪽같이 숨기는 법을 찾아 입맛을 살려 주세요.', title_nl = 'Rent hij weg van groente? 🥦', body_nl = 'Is hij kieskeurig op kleur geworden? Ontdek in Babyrecepten hoe je spinazie en wortel slim verstopt in lekkere pannenkoekjes en wek zijn eetlust op.', title_pl = 'Ucieka na widok zieleniny? 🥦', body_pl = 'Zaczęło się wybieranie po kolorach? Odkryj w Przepisach dla niemowląt, jak zręcznie ukryć szpinak i marchewkę w pysznych placuszkach, i pobudź jego apetyt.', title_pt = 'Foge quando vê verduras? 🥦', body_pt = 'Começou a escolher pelas cores? Descubra nas Receitas para bebés como esconder com mestria espinafres e cenoura em panquecas deliciosas e abra-lhe o apetite.', title_sv = 'Springer iväg vid åsynen av grönt? 🥦', body_sv = 'Har barnet börjat välja mat efter färg? Upptäck i Recept för bebisar hur du skickligt gömmer spenat och morötter i goda pannkakor och väck aptiten.', title_vi = 'Thấy rau xanh là chạy? 🥦', body_vi = 'Bé bắt đầu kén màu sắc? Hãy khám phá cách khéo léo giấu rau chân vịt và cà rốt vào bánh kếp thơm ngon trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '一看到绿叶菜就跑？🥦', body_zh = '开始挑颜色了？在宝宝食谱里发现如何把菠菜和胡萝卜巧妙地藏进美味的松饼里，让宝宝胃口大开。' WHERE id = '19e2869e-6998-4c65-b3a4-edbc6a06f435' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño artista en acción 🎨', body_es = '¡No te enfades aunque acabe lleno de pintura! Decora ya este momento creativo con las pegatinas alegres de la Sesión de fotos del bebé, añádelo al álbum y sonríe.', title_fr = 'Petit artiste au travail 🎨', body_fr = 'Même s''il est couvert de peinture, ne vous énervez pas ! Décorez tout de suite ce moment créatif avec les stickers joyeux de la Séance photo bébé, ajoutez-le à l''album et souriez.', title_hi = 'नन्हा चित्रकार काम पर 🎨', body_hi = 'कपड़ों पर रंग लग जाए तो भी गुस्सा मत होइए! इस रचनात्मक पल को तुरंत बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में जोड़िए और मुस्कुराइए।', title_id = 'Pelukis cilik sedang beraksi 🎨', body_id = 'Jangan kesal meski bajunya penuh cat! Segera hiasi momen kreatif ini dengan stiker ceria dari Sesi Foto Bayi, tambahkan ke album, dan tersenyumlah.', title_ja = '小さな画家が作業中 🎨', body_ja = '服が絵の具だらけでも怒らないで！この創造的な瞬間をすぐに「ベビーフォトセッション」の楽しいステッカーで飾ってアルバムに追加し、ほほえみましょう。', title_ko = '꼬마 화가 작업 중 🎨', body_ko = '온몸이 물감투성이여도 화내지 마세요! 이 창의적인 순간을 바로 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 올리고 웃어 보세요.', title_nl = 'Kleine kunstenaar aan het werk 🎨', body_nl = 'Word niet boos, ook al zit hij onder de verf! Versier dit creatieve moment meteen met vrolijke stickers in Babyfotoshoot, zet het in het album en glimlach.', title_pl = 'Mały artysta przy pracy 🎨', body_pl = 'Nie denerwuj się, nawet jeśli jest cały w farbie! Od razu ozdób tę twórczą chwilę wesołymi naklejkami z Sesji zdjęciowej dziecka, dodaj do albumu i uśmiechnij się.', title_pt = 'Pequeno artista em ação 🎨', body_pt = 'Mesmo que fique todo pintado, não se enerve! Decore já este momento criativo com os autocolantes alegres da Sessão Fotográfica do Bebé, adicione-o ao álbum e sorria.', title_sv = 'Den lilla konstnären i farten 🎨', body_sv = 'Bli inte irriterad även om kläderna är fulla av färg! Dekorera det kreativa ögonblicket direkt med glada klistermärken i Babyfotografering, lägg till det i albumet och le.', title_vi = 'Họa sĩ nhí đang làm việc 🎨', body_vi = 'Dù quần áo dính đầy màu cũng đừng bực mình! Hãy trang trí ngay khoảnh khắc sáng tạo này bằng sticker vui nhộn trong Chụp ảnh cho bé, thêm vào album và mỉm cười.', title_zh = '小画家上班啦 🎨', body_zh = '就算弄得满身颜料也别生气！马上用宝宝写真里欢乐的贴纸装饰这个充满创意的时刻，加进相册，笑一笑吧。' WHERE id = 'b793a816-4035-4e2c-8e9a-647949d5fa3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere comer carne? 🥩', body_es = '¿Necesita proteínas pero rechaza la carne? Completa su ración en el Seguimiento de tomas con unas albóndigas de pollo ricas y fáciles de masticar de Recetas para bebé.', title_fr = 'Il ne veut pas de viande ? 🥩', body_fr = 'Il a besoin de protéines mais fuit la viande ? Avec les boulettes de poulet savoureuses et faciles à mâcher des Recettes pour bébés, atteignez sa ration dans le Suivi des repas.', title_hi = 'मांस नहीं खाना चाहता? 🥩', body_hi = 'प्रोटीन की ज़रूरत है, पर मांस से भागता है? बच्चों की रेसिपी में आसानी से चबाए जाने वाले स्वादिष्ट चिकन कोफ़्तों से फ़ीडिंग ट्रैकर का मानक पूरा कीजिए।', title_id = 'Tidak mau makan daging? 🥩', body_id = 'Butuh protein, tapi menghindari daging? Penuhi kebutuhan di alat Pemantau Nutrisi dengan bola-bola ayam yang lezat dan mudah dikunyah dari Resep Bayi.', title_ja = 'お肉を食べたがらない？🥩', body_ja = 'たんぱく質が必要なのに、お肉を避けますか？「離乳食を始める赤ちゃんのレシピ」の、かみやすくておいしい鶏肉のミートボールで、「栄養管理ツール」の目安量を満たしましょう。', title_ko = '고기를 안 먹으려 하나요? 🥩', body_ko = '단백질이 필요한데 고기를 피하나요? 아기 레시피의 씹기 쉽고 맛있는 닭고기 완자로 수유 기록 도구의 기준량을 채워 주세요.', title_nl = 'Wil hij geen vlees eten? 🥩', body_nl = 'Heeft hij eiwit nodig, maar ontwijkt hij vlees? Haal met makkelijk te kauwen, lekkere kipballetjes uit Babyrecepten de norm in de Voedingstracker.', title_pl = 'Nie chce jeść mięsa? 🥩', body_pl = 'Potrzebuje białka, ale unika mięsa? Uzupełnij normę w narzędziu do śledzenia karmienia łatwymi do pogryzienia, smacznymi klopsikami z kurczaka z Przepisów dla niemowląt.', title_pt = 'Não quer comer carne? 🥩', body_pt = 'Precisa de proteína, mas foge da carne? Com almôndegas de frango saborosas e fáceis de mastigar das Receitas para bebés, complete a dose do Registo de Alimentação.', title_sv = 'Vill inte äta kött? 🥩', body_sv = 'Behöver barnet protein men undviker kött? Fyll normen i Matningskoll med goda kycklingköttbullar som är lätta att tugga från Recept för bebisar.', title_vi = 'Bé không muốn ăn thịt? 🥩', body_vi = 'Bé cần đạm nhưng lại né thịt? Hãy dùng món viên gà mềm, dễ nhai và thơm ngon trong Công thức cho bé để hoàn thành định mức trong Theo dõi cữ bú.', title_zh = '不想吃肉？🥩', body_zh = '需要蛋白质，却不肯吃肉？用宝宝食谱里好咀嚼又美味的鸡肉丸子，补足喂养记录工具里的参考量。' WHERE id = '924176de-d987-4381-ba5c-3bdf618f72f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga de la cama 🏃‍♂️', body_es = '¿Se escapa de la habitación cuando llega la hora de dormir? Pon el temporizador de sueño y el rumor del bosque de Ruido blanco, y convierte la habitación en una cueva tranquila.', title_fr = 'Plan d''évasion du lit 🏃‍♂️', body_fr = 'Il s''enfuit de la chambre à l''heure du coucher ? Lancez le minuteur de sommeil, mettez le murmure de la forêt des Bruits blancs et transformez la chambre en grotte paisible.', title_hi = 'बिस्तर से भागने का प्लान 🏃‍♂️', body_hi = 'सोने का समय आते ही कमरे से भाग जाता है? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में जंगल की सरसराहट लगाइए और कमरे को एक शांत गुफ़ा बना दीजिए।', title_id = 'Rencana kabur dari tempat tidur 🏃‍♂️', body_id = 'Kabur dari kamar saat jam tidur tiba? Nyalakan Timer Tidur, putar suara desau hutan dari Suara Putih, dan ubah kamar menjadi gua yang tenang.', title_ja = 'ベッドからの脱走計画 🏃‍♂️', body_ja = '寝る時間になると部屋から逃げ出しますか？睡眠タイマーをオンにして、「ホワイトノイズ」の森のざわめきを流し、部屋を静かな洞窟に変えましょう。', title_ko = '침대 탈출 작전 🏃‍♂️', body_ko = '잘 시간만 되면 방에서 도망가나요? 수면 타이머를 켜고 백색소음의 숲 소리를 틀어 방을 조용한 동굴로 바꿔 주세요.', title_nl = 'Ontsnappingsplan uit bed 🏃‍♂️', body_nl = 'Rent hij de kamer uit als het bedtijd is? Zet de Slaaptimer aan, kies het ruisen van het bos in Witte ruis en maak van de kamer een rustige grot.', title_pl = 'Plan ucieczki z łóżka 🏃‍♂️', body_pl = 'Gdy przychodzi pora snu, ucieka z pokoju? Włącz timer snu, puść szum lasu z Białego szumu i zamień pokój w cichą jaskinię.', title_pt = 'Plano de fuga da cama 🏃‍♂️', body_pt = 'Quando chega a hora de dormir, foge do quarto? Ligue o temporizador de sono, ponha o murmúrio da floresta do Ruído Branco e transforme o quarto numa gruta tranquila.', title_sv = 'Flyktplanen från sängen 🏃‍♂️', body_sv = 'Springer barnet ut ur rummet när det är dags att sova? Starta sömntimern, sätt på skogens sus från Vitt brus och gör rummet till en lugn grotta.', title_vi = 'Kế hoạch trốn khỏi giường 🏃‍♂️', body_vi = 'Đến giờ ngủ là bé chạy khỏi phòng? Hãy bật Bộ hẹn giờ ngủ, mở tiếng rừng rì rào trong Tiếng ồn trắng và biến căn phòng thành một hang động yên tĩnh.', title_zh = '逃离床铺计划 🏃‍♂️', body_zh = '一到睡觉时间就往房间外跑？打开睡眠计时器，播放白噪音里的森林呼啸声，把房间变成一个安静的小山洞。' WHERE id = '75bd2c8f-8af9-437f-ac84-6c69bc76ea8c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tozudez matutina 🛑', body_es = '¿Las crisis de «¡No me pongo esto, no me como eso!» te complican las mañanas? Escribe ya a Anacan AI y aprende a gestionar cómo pone a prueba los límites a esta edad.', title_fr = 'Obstination du matin 🛑', body_fr = 'Les crises « Je ne mets pas ça, je ne mange pas ça ! » compliquent vos matinées ? Écrivez tout de suite à Anacan AI pour apprendre à gérer les tests de limites de cet âge.', title_hi = 'सुबह की ज़िद 🛑', body_hi = '''यह नहीं पहनूँगा, वह नहीं खाऊँगा!'' वाले नखरे आपकी सुबह मुश्किल बना देते हैं? तुरंत Anacan AI को लिखिए और जानिए कि इस उम्र में सीमाएँ परखने को कैसे संभालें।', title_id = 'Keras kepala di pagi hari 🛑', body_id = 'Drama Aku tidak mau pakai ini, aku tidak mau makan itu! membuat pagi Anda berat? Segera tulis ke Anacan AI dan pelajari cara menghadapi uji batas khas usia ini.', title_ja = '朝のこだわり 🛑', body_ja = '「これは着ない、それは食べない！」というかんしゃくで、朝が大変になっていますか？すぐにAnacan AIに書き込んで、この年齢の境界線を試す行動への対応を学びましょう。', title_ko = '아침 고집 🛑', body_ko = '''이거 안 입어, 저거 안 먹어!'' 떼쓰기로 아침이 힘든가요? 바로 Anacan AI에게 물어 이 시기의 한계 시험을 다루는 법을 배워 보세요.', title_nl = 'Koppigheid in de ochtend 🛑', body_nl = 'Maken buien als dit trek ik niet aan, dat eet ik niet! je ochtenden zwaar? Schrijf meteen naar Anacan AI en leer hoe je omgaat met het grenzen testen op deze leeftijd.', title_pl = 'Poranny upór 🛑', body_pl = 'Kryzysy w stylu „Tego nie założę, tego nie zjem!” utrudniają ci poranki? Od razu napisz do Anacan AI i dowiedz się, jak radzić sobie z typowym dla tego wieku testowaniem granic.', title_pt = 'Teimosia da manhã 🛑', body_pt = 'As crises de "Não visto isto, não como aquilo!" complicam-lhe as manhãs? Escreva já ao Anacan AI e aprenda a gerir os testes de limites desta idade.', title_sv = 'Morgonenvishet 🛑', body_sv = 'Gör utbrott som ”Det här tar jag inte på mig, det där äter jag inte!” morgnarna svåra? Skriv direkt till Anacan AI och lär dig hantera den här ålderns gränstester.', title_vi = 'Bướng bỉnh buổi sáng 🛑', body_vi = 'Những cơn "Con không mặc cái này, con không ăn cái kia!" khiến buổi sáng thêm vất vả? Hãy nhắn ngay cho Anacan AI để biết cách xử lý những lần bé thử giới hạn ở tuổi này.', title_zh = '早上的倔强 🛑', body_zh = '“这个我不穿，那个我不吃！”的崩溃让早上变得很难？马上写信给Anacan AI，学习如何应对这个年龄试探边界的行为。' WHERE id = 'bd146fb2-5002-4d8c-824b-58bbd81c0c9b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Saltos de la pared al sofá! 🧗‍♂️', body_es = '¡Es todo un especialista en acrobacias! Para que gaste la energía que acumula en casa, busca en Lugares para mamás centros con amplias salas de juego y déjale jugar a su aire.', title_fr = 'Du mur au canapé, il saute ! 🧗‍♂️', body_fr = 'C''est un vrai cascadeur ! Pour qu''il se dépense, trouvez dans les Lieux adaptés aux mamans des centres avec de grandes salles de jeux et laissez-le s''en donner à cœur joie.', title_hi = 'दीवार से सोफ़े पर छलांग! 🧗‍♂️', body_hi = 'वह तो असली स्टंटमैन है! घर की ऊर्जा निकालने के लिए माँ के लिए अनुकूल जगहें में बड़े प्ले हॉल वाले सेंटर ढूँढिए और उसे खुलकर खेलने दीजिए।', title_id = 'Lompat dari dinding ke sofa! 🧗‍♂️', body_id = 'Ia benar-benar pemeran aksi cilik! Untuk menyalurkan energinya, temukan tempat dengan ruang bermain luas di Tempat Ramah Ibu dan biarkan ia bebas bermain.', title_ja = '壁からソファへジャンプ！🧗‍♂️', body_ja = 'まるで本物のスタントマン！家の中のエネルギーを発散させるために、「ママにやさしいスポット」で広いプレイルームのある施設を見つけて、思いきり遊ばせてあげましょう。', title_ko = '벽에서 소파로 점프! 🧗‍♂️', body_ko = '진정한 스턴트맨이에요! 집 안의 에너지를 발산하도록 엄마 친화 장소에서 넓은 놀이 공간이 있는 센터를 찾아 마음껏 뛰놀게 해 주세요.', title_nl = 'Van de muur op de bank! 🧗‍♂️', body_nl = 'Hij is een echte stuntman! Zoek in Mamavriendelijke plekken centra met ruime speelhallen en laat hem vrij om zijn energie kwijt te raken.', title_pl = 'Ze ściany na kanapę! 🧗‍♂️', body_pl = 'To prawdziwy kaskader! Aby rozładował energię, znajdź w Miejscach przyjaznych mamom centra z dużymi salami zabaw i pozwól mu się wyszaleć.', title_pt = 'Da parede para o sofá! 🧗‍♂️', body_pt = 'É um verdadeiro duplo! Para gastar a energia de casa, encontre nos Locais Amigos das Mães centros com salas de brincar amplas e deixe-o à vontade.', title_sv = 'Hopp från väggen till soffan! 🧗‍♂️', body_sv = 'Barnet är en riktig stuntman! Hitta center med stora lekhallar i Mammavänliga platser för att få ut energin och låt barnet röra sig fritt.', title_vi = 'Từ tường nhảy sang sofa! 🧗‍♂️', body_vi = 'Bé đúng là một diễn viên đóng thế! Để bé xả năng lượng, hãy tìm các trung tâm có phòng chơi rộng trong Địa điểm thân thiện với mẹ và để bé tự do vui chơi.', title_zh = '从墙边跳到沙发！🧗‍♂️', body_zh = '简直是个特技演员！为了释放在家里积攒的精力，在妈妈友好场所里找一个有宽敞游戏厅的中心，让宝宝尽情撒欢。' WHERE id = 'fdf24d1a-f6c7-451f-974c-c9a5a3bf1aa7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mordiscos de enfado 🦖', body_es = '¿Cuando se enfada te muerde a ti o a sus amigos? Pregunta ya a nuestro asistente experto Anacan AI cómo afrontar con cariño esta conducta difícil.', title_fr = 'Morsures de colère 🦖', body_fr = 'Il mord ses copains ou vous quand il se fâche ? Demandez tout de suite à notre assistant expert Anacan AI comment gérer ce comportement difficile avec amour.', title_hi = 'गुस्से में काटना 🦖', body_hi = 'गुस्से में दोस्तों को या आपको काटता है? इस मुश्किल व्यवहार को प्यार से कैसे सुलझाएँ, यह तुरंत हमारे Anacan AI एक्सपर्ट असिस्टेंट से पूछिए।', title_id = 'Gigitan saat marah 🦖', body_id = 'Menggigit temannya atau Anda saat marah? Segera tanyakan kepada asisten ahli Anacan AI cara mengatasi perilaku sulit ini dengan penuh kasih.', title_ja = '怒ってかみつく 🦖', body_ja = '怒るとお友だちやあなたにかみつきますか？この難しい行動に愛情をもってどう対応すればいいか、すぐにAnacan AIのエキスパートアシスタントに聞いてみましょう。', title_ko = '화가 나서 깨물어요 🦖', body_ko = '화가 나면 친구나 엄마를 깨무나요? 이 어려운 행동을 사랑으로 다루는 방법을 Anacan AI 전문가 도우미에게 바로 물어보세요.', title_nl = 'Boos bijten 🦖', body_nl = 'Bijt hij vriendjes of jou als hij boos is? Vraag onze Anacan AI-expert meteen hoe je dit lastige gedrag liefdevol aanpakt.', title_pl = 'Gryzienie ze złości 🦖', body_pl = 'Gdy się złości, gryzie kolegów albo ciebie? Od razu zapytaj naszego eksperta Anacan AI, jak z miłością poradzić sobie z tym trudnym zachowaniem.', title_pt = 'Mordidas de raiva 🦖', body_pt = 'Quando se zanga, morde os amigos ou a mãe? Pergunte já ao nosso assistente especialista Anacan AI como resolver com amor este comportamento difícil.', title_sv = 'Biter när hen är arg 🦖', body_sv = 'Biter barnet sina kompisar eller dig när hen blir arg? Fråga vår expertassistent Anacan AI direkt hur du med kärlek kan hantera detta svåra beteende.', title_vi = 'Cắn vì tức giận 🦖', body_vi = 'Bé cắn bạn hoặc cắn mẹ khi tức giận? Hãy hỏi ngay trợ lý chuyên gia Anacan AI cách xử lý hành vi khó khăn này bằng tình yêu thương.', title_zh = '生气就咬人 🦖', body_zh = '一生气就咬小朋友或咬你？马上问问我们的Anacan AI专家助手，如何用爱解决这种棘手的行为。' WHERE id = '0b69ffc4-e10f-4228-a354-3609a2cf48bb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Solo come pan? 🍞', body_es = '¿Aparta las proteínas y las verduras y solo quiere hidratos de carbono? Calcula con el Seguimiento de tomas cuántos alimentos saludables ha tomado hoy y ajusta su ración.', title_fr = 'Il ne mange que du pain ? 🍞', body_fr = 'Il repousse protéines et légumes et ne veut que des féculents ? Calculez avec le Suivi des repas ce qu''il a mangé de bon aujourd''hui et ajustez sa ration.', title_hi = 'सिर्फ़ रोटी खाता है? 🍞', body_hi = 'प्रोटीन और सब्ज़ियाँ हटाकर सिर्फ़ कार्बोहाइड्रेट चाहता है? फ़ीडिंग ट्रैकर से गिनिए कि आज उसे कितना पौष्टिक खाना मिला, और मात्रा ठीक कीजिए।', title_id = 'Hanya mau makan roti? 🍞', body_id = 'Menyingkirkan protein dan sayuran, hanya mau karbohidrat? Hitung berapa banyak makanan bergizi yang ia dapat hari ini dengan alat Pemantau Nutrisi dan sesuaikan porsinya.', title_ja = 'パンしか食べない？🍞', body_ja = 'たんぱく質や野菜を押しのけて、炭水化物ばかりほしがりますか？「栄養管理ツール」で、今日体にいい食べ物をどれだけとれたか計算して、目安量を調整しましょう。', title_ko = '빵만 먹나요? 🍞', body_ko = '단백질과 채소는 밀어내고 탄수화물만 찾나요? 수유 기록 도구로 오늘 몸에 좋은 음식을 얼마나 먹었는지 계산하고 기준량을 조절하세요.', title_nl = 'Eet hij alleen brood? 🍞', body_nl = 'Schuift hij eiwit en groente opzij en wil hij alleen koolhydraten? Bereken met de Voedingstracker hoeveel gezond eten hij vandaag heeft gehad en pas de norm aan.', title_pl = 'Je tylko chleb? 🍞', body_pl = 'Odsuwa białko i warzywa i chce tylko węglowodanów? Oblicz w narzędziu do śledzenia karmienia, ile zdrowego jedzenia dziś zjadł, i dopasuj normę.', title_pt = 'Só come pão? 🍞', body_pt = 'Afasta a proteína e os legumes e só quer hidratos de carbono? Calcule com o Registo de Alimentação quanta comida nutritiva recebeu hoje e ajuste a dose.', title_sv = 'Äter bara bröd? 🍞', body_sv = 'Skjuter barnet undan protein och grönsaker och vill bara ha kolhydrater? Räkna ut med Matningskoll hur mycket nyttig mat barnet fått i dag och justera normen.', title_vi = 'Bé chỉ ăn bánh mì? 🍞', body_vi = 'Bé gạt đạm và rau sang một bên, chỉ muốn ăn tinh bột? Hãy tính bằng Theo dõi cữ bú xem hôm nay bé đã ăn bao nhiêu thực phẩm bổ dưỡng và điều chỉnh định mức.', title_zh = '只吃面包？🍞', body_zh = '把蛋白质和蔬菜推到一边，只想吃碳水？用喂养记录工具算算今天吃了多少有营养的食物，调整一下参考量。' WHERE id = '0bd19a92-8f32-4626-9053-67019de34d6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de romper las páginas 📖', body_es = '¿Quiere arrancar las páginas del libro a la hora del cuento? Lee en el Blog cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'L''envie de déchirer les pages 📖', body_fr = 'Il veut déchirer les pages du livre pendant le conte du soir ? Lisez dans la rubrique Blogs comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'पन्ने फाड़ने का शौक 📖', body_hi = 'शाम की कहानी के समय किताब के पन्ने फाड़ना चाहता है? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह ब्लॉग सेक्शन में पढ़िए।', title_id = 'Hobi merobek halaman 📖', body_id = 'Ingin merobek halaman buku saat dongeng malam? Baca di bagian Blog cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = 'ページを破りたい気持ち 📖', body_ja = '夜の読み聞かせのときに、絵本のページを破りたがりますか？読書の習慣を損なわずにこの問題に対応する方法を、ブログで読んでみましょう。', title_ko = '책장을 찢고 싶어요 📖', body_ko = '잠자리 동화 시간에 책장을 찢으려 하나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 블로그에서 읽어 보세요.', title_nl = 'Zin om bladzijden te scheuren 📖', body_nl = 'Wil hij bij het avondverhaal de bladzijden uit het boek scheuren? Lees in Blogs hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Ochota na darcie stron 📖', body_pl = 'Podczas wieczornej bajki chce drzeć strony książki? Przeczytaj w sekcji Blog, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'A mania de rasgar páginas 📖', body_pt = 'Na história da noite, quer rasgar as páginas do livro? Leia nos Blogues como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Lust att riva sönder sidorna 📖', body_sv = 'Vill barnet riva sönder sidorna i boken vid kvällssagan? Läs i Bloggar hur du löser problemet utan att skada läsvanan.', title_vi = 'Mê xé trang sách 📖', body_vi = 'Đến giờ kể chuyện buổi tối là bé muốn xé trang sách? Hãy đọc trong mục Blog cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '爱撕书页 📖', body_zh = '晚上讲故事时想把书页撕碎？去博客板块读读，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = '3794ac2c-9f00-4406-8f93-da27c84ffed3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Obra de arte en la pared 🎨', body_es = '¿Ha cogido un bolígrafo y ha pintado la pared? ¡No te enfades! Añade esta dulce travesura al álbum con los marcos divertidos de la Sesión de fotos del bebé y simplemente sonríe.', title_fr = 'Une œuvre d''art sur le mur 🎨', body_fr = 'Il a pris un stylo et dessiné sur le mur ? Ne vous énervez pas ! Ajoutez cette mignonne bêtise à l''album avec les cadres rigolos de la Séance photo bébé, et souriez simplement.', title_hi = 'दीवार पर कलाकृति 🎨', body_hi = 'पेन लेकर दीवार रंग दी? गुस्सा मत होइए! इस प्यारी शरारत को बेबी फ़ोटोशूट के मज़ेदार फ़्रेम के साथ एल्बम में जोड़िए और बस मुस्कुराइए।', title_id = 'Karya seni di dinding 🎨', body_id = 'Ia mengambil pulpen dan mencoret dinding? Jangan kesal! Tambahkan kenakalan manis ini ke album dengan bingkai lucu dari Sesi Foto Bayi, dan tersenyumlah.', title_ja = '壁の上の芸術作品 🎨', body_ja = 'ペンを手に取って壁に描いてしまいましたか？怒らないで！このかわいいいたずらを、「ベビーフォトセッション」のおもしろいフレームでアルバムに追加して、ただほほえみましょう。', title_ko = '벽 위의 예술 작품 🎨', body_ko = '펜을 들고 벽에 그림을 그렸나요? 화내지 마세요! 이 귀여운 장난을 아기 사진 촬영의 재미있는 프레임으로 앨범에 담고 그냥 웃어 주세요.', title_nl = 'Kunstwerk op de muur 🎨', body_nl = 'Heeft hij met een pen op de muur getekend? Word niet boos! Zet deze lieve ondeugd met grappige kaders uit Babyfotoshoot in het album en glimlach gewoon.', title_pl = 'Dzieło sztuki na ścianie 🎨', body_pl = 'Wziął długopis i pomalował ścianę? Nie denerwuj się! Dodaj tę słodką psotę do albumu z zabawnymi ramkami z Sesji zdjęciowej dziecka i po prostu się uśmiechnij.', title_pt = 'Uma obra de arte na parede 🎨', body_pt = 'Pegou numa caneta e pintou a parede? Não se enerve! Adicione esta traquinice tão doce ao álbum com as molduras engraçadas da Sessão Fotográfica do Bebé e limite-se a sorrir.', title_sv = 'Konstverk på väggen 🎨', body_sv = 'Tog barnet en penna och målade på väggen? Bli inte irriterad! Lägg till det söta busstreck i albumet med roliga ramar i Babyfotografering och le bara.', title_vi = 'Tác phẩm nghệ thuật trên tường 🎨', body_vi = 'Bé cầm bút vẽ lên tường? Đừng bực mình! Hãy thêm trò nghịch ngợm đáng yêu này vào album với khung ảnh ngộ nghĩnh trong Chụp ảnh cho bé và cứ mỉm cười thôi.', title_zh = '墙上的艺术作品 🎨', body_zh = '拿起笔就在墙上画画？别生气！用宝宝写真里的搞笑相框把这个可爱的淘气瞬间加进相册，笑一笑就好。' WHERE id = '21c31221-548f-42a2-945f-424351b307be' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te duele la espalda? 🧘‍♀️', body_es = 'No es fácil coger en brazos sin parar a un peque de más de 12 kg. Prepárate un té de jengibre antiinflamatorio que relaja los músculos de Recetas saludables y descansa.', title_fr = 'Vous avez mal au dos ? 🧘‍♀️', body_fr = 'Porter sans cesse un petit de plus de 12 kg n''est pas facile. Préparez une tisane de gingembre anti-inflammatoire qui détend les muscles avec les Recettes saines, et reposez-vous.', title_hi = 'कमर दर्द है? 🧘‍♀️', body_hi = '12+ kg के नन्हे को बार-बार उठाना आसान नहीं। सेहतमंद रेसिपी से मांसपेशियों को आराम देने वाली, सूजन कम करने वाली अदरक की चाय बनाइए और आराम कीजिए।', title_id = 'Punggung Anda sakit? 🧘‍♀️', body_id = 'Terus-menerus menggendong si kecil yang beratnya 12+ kg tidaklah mudah. Seduh teh jahe antiradang yang merilekskan otot dari Resep Sehat, lalu beristirahatlah.', title_ja = '腰が痛い？🧘‍♀️', body_ja = '12kg以上のお子さんを何度も抱き上げるのは大変です。「ヘルシーレシピ」から、筋肉をほぐし炎症をおさえるしょうが茶をいれて、休みましょう。', title_ko = '허리가 아프나요? 🧘‍♀️', body_ko = '12kg이 넘는 아이를 계속 안아 올리기는 쉽지 않아요. 건강한 레시피에서 근육을 풀어 주고 염증을 줄이는 생강차를 우려 쉬세요.', title_nl = 'Pijn in je rug? 🧘‍♀️', body_nl = 'Steeds een kleintje van 12+ kg optillen is niet makkelijk. Zet ontstekingsremmende gemberthee uit Gezonde recepten die je spieren ontspant, en rust uit.', title_pl = 'Bolą cię plecy? 🧘‍♀️', body_pl = 'Ciągłe podnoszenie malucha ważącego ponad 12 kg to nie lada wyzwanie. Zaparz ze Zdrowych przepisów przeciwzapalną herbatę imbirową, która rozluźnia mięśnie, i odpocznij.', title_pt = 'Dores nas costas? 🧘‍♀️', body_pt = 'Pegar sem parar num pequenino de mais de 12 kg não é fácil. Prepare um chá de gengibre das Receitas Saudáveis, anti-inflamatório e que relaxa os músculos, e descanse.', title_sv = 'Ont i ryggen? 🧘‍♀️', body_sv = 'Det är inte lätt att ständigt lyfta en liten på över 12 kg. Brygg ett antiinflammatoriskt ingefärste som får musklerna att slappna av från Hälsosamma recept och vila.', title_vi = 'Mẹ bị đau lưng? 🧘‍♀️', body_vi = 'Liên tục bế một em bé hơn 12 kg không hề dễ dàng. Hãy pha trà gừng chống viêm, giúp thư giãn cơ từ Công thức lành mạnh và nghỉ ngơi.', title_zh = '腰疼吗？🧘‍♀️', body_zh = '不停地抱起12+ kg的小家伙可不容易。从健康食谱里泡一杯放松肌肉、抗炎的姜茶，休息一下吧。' WHERE id = 'cb6101a7-dbfd-4d36-944e-5acbfd6bc964' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga de la cama 🏃‍♂️', body_es = '¿A la hora de dormir trepa y se sale de la cuna? Pon el temporizador de sueño y el sonido monótono del tren de Ruido blanco para llevarle con calma al sueño.', title_fr = 'Plan d''évasion du lit 🏃‍♂️', body_fr = 'Il escalade son lit à barreaux à l''heure du coucher ? Lancez le minuteur de sommeil, mettez le bruit monotone du train des Bruits blancs et amenez-le doucement vers le sommeil.', title_hi = 'बिस्तर से भागने का प्लान 🏃‍♂️', body_hi = 'सोने का समय आते ही पालने से चढ़कर बाहर निकल आता है? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में ट्रेन की एक जैसी आवाज़ लगाइए और उसे शांति से नींद के लिए तैयार कीजिए।', title_id = 'Rencana kabur dari tempat tidur 🏃‍♂️', body_id = 'Memanjat keluar dari boks saat jam tidur tiba? Nyalakan Timer Tidur, putar suara kereta yang monoton dari Suara Putih, dan antar ia tidur dengan tenang.', title_ja = 'ベッドからの脱走計画 🏃‍♂️', body_ja = '寝る時間になると、ベビーベッドからよじ登って出てきますか？睡眠タイマーをオンにして、「ホワイトノイズ」の単調な電車の音を流し、静かに眠りへ導きましょう。', title_ko = '침대 탈출 작전 🏃‍♂️', body_ko = '잘 시간만 되면 아기 침대를 넘어 나오나요? 수면 타이머를 켜고 백색소음의 단조로운 기차 소리로 조용히 잠들 준비를 도와주세요.', title_nl = 'Ontsnappingsplan uit bed 🏃‍♂️', body_nl = 'Klimt hij uit zijn bedje als het bedtijd is? Zet de Slaaptimer aan, kies het monotone treingeluid in Witte ruis en laat hem rustig in slaap vallen.', title_pl = 'Plan ucieczki z łóżka 🏃‍♂️', body_pl = 'Gdy przychodzi pora snu, wychodzi z łóżeczka? Włącz timer snu, puść monotonny stukot pociągu z Białego szumu i spokojnie nastrój go do snu.', title_pt = 'Plano de fuga da cama 🏃‍♂️', body_pt = 'Na hora de dormir, trepa e sai do berço? Ligue o temporizador de sono, ponha o som monótono do comboio do Ruído Branco e prepare-o com calma para dormir.', title_sv = 'Flyktplanen från sängen 🏃‍♂️', body_sv = 'Klättrar barnet ur spjälsängen när det är dags att sova? Starta sömntimern, sätt på det monotona tågljudet från Vitt brus och stäm lugnt barnet för sömn.', title_vi = 'Kế hoạch trốn khỏi giường 🏃‍♂️', body_vi = 'Đến giờ ngủ là bé trèo ra khỏi cũi? Hãy bật Bộ hẹn giờ ngủ, mở tiếng tàu hỏa đều đều trong Tiếng ồn trắng để nhẹ nhàng đưa bé vào giấc ngủ.', title_zh = '逃离床铺计划 🏃‍♂️', body_zh = '一到睡觉时间就从小床里爬出来？打开睡眠计时器，播放白噪音里单调的火车声，让宝宝平静地进入睡眠。' WHERE id = 'e15645b0-86cf-412b-8fdc-f53e32110fb7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Solo come pan? 🍞', body_es = '¿Aparta las proteínas y las verduras y solo quiere hidratos de carbono? Calcula con el Seguimiento de tomas cuántos alimentos saludables ha tomado hoy y ajusta su ración.', title_fr = 'Il ne mange que du pain ? 🍞', body_fr = 'Il repousse protéines et légumes et ne veut que des féculents ? Calculez avec le Suivi des repas ce qu''il a mangé de bon aujourd''hui et ajustez sa ration.', title_hi = 'सिर्फ़ रोटी खाता है? 🍞', body_hi = 'प्रोटीन और सब्ज़ियाँ हटाकर सिर्फ़ कार्बोहाइड्रेट चाहता है? फ़ीडिंग ट्रैकर से गिनिए कि आज उसे कितना पौष्टिक खाना मिला, और मात्रा ठीक कीजिए।', title_id = 'Hanya mau makan roti? 🍞', body_id = 'Menyingkirkan protein dan sayuran, hanya mau karbohidrat? Hitung berapa banyak makanan bergizi yang ia dapat hari ini dengan alat Pemantau Nutrisi dan sesuaikan porsinya.', title_ja = 'パンしか食べない？🍞', body_ja = 'たんぱく質や野菜を押しのけて、炭水化物ばかりほしがりますか？「栄養管理ツール」で、今日体にいい食べ物をどれだけとれたか計算して、目安量を調整しましょう。', title_ko = '빵만 먹나요? 🍞', body_ko = '단백질과 채소는 밀어내고 탄수화물만 찾나요? 수유 기록 도구로 오늘 몸에 좋은 음식을 얼마나 먹었는지 계산하고 기준량을 조절하세요.', title_nl = 'Eet hij alleen brood? 🍞', body_nl = 'Schuift hij eiwit en groente opzij en wil hij alleen koolhydraten? Bereken met de Voedingstracker hoeveel gezond eten hij vandaag heeft gehad en pas de norm aan.', title_pl = 'Je tylko chleb? 🍞', body_pl = 'Odsuwa białko i warzywa i chce tylko węglowodanów? Oblicz w narzędziu do śledzenia karmienia, ile zdrowego jedzenia dziś zjadł, i dopasuj normę.', title_pt = 'Só come pão? 🍞', body_pt = 'Afasta a proteína e os legumes e só quer hidratos de carbono? Calcule com o Registo de Alimentação quanta comida nutritiva recebeu hoje e ajuste a dose.', title_sv = 'Äter bara bröd? 🍞', body_sv = 'Skjuter barnet undan protein och grönsaker och vill bara ha kolhydrater? Räkna ut med Matningskoll hur mycket nyttig mat barnet fått i dag och justera normen.', title_vi = 'Bé chỉ ăn bánh mì? 🍞', body_vi = 'Bé gạt đạm và rau sang một bên, chỉ muốn ăn tinh bột? Hãy tính bằng Theo dõi cữ bú xem hôm nay bé đã ăn bao nhiêu thực phẩm bổ dưỡng và điều chỉnh định mức.', title_zh = '只吃面包？🍞', body_zh = '把蛋白质和蔬菜推到一边，只想吃碳水？用喂养记录工具算算今天吃了多少有营养的食物，调整一下参考量。' WHERE id = '97ab1430-c17a-4645-93d1-2d0b7261c822' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de romper las páginas 📖', body_es = '¿Quiere arrancar las páginas del libro a la hora del cuento? Lee en el Blog cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'L''envie de déchirer les pages 📖', body_fr = 'Il veut déchirer les pages du livre pendant le conte du soir ? Lisez dans la rubrique Blogs comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'पन्ने फाड़ने का शौक 📖', body_hi = 'शाम की कहानी के समय किताब के पन्ने फाड़ना चाहता है? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह ब्लॉग सेक्शन में पढ़िए।', title_id = 'Hobi merobek halaman 📖', body_id = 'Ingin merobek halaman buku saat dongeng malam? Baca di bagian Blog cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = 'ページを破りたい気持ち 📖', body_ja = '夜の読み聞かせのときに、絵本のページを破りたがりますか？読書の習慣を損なわずにこの問題に対応する方法を、ブログで読んでみましょう。', title_ko = '책장을 찢고 싶어요 📖', body_ko = '잠자리 동화 시간에 책장을 찢으려 하나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 블로그에서 읽어 보세요.', title_nl = 'Zin om bladzijden te scheuren 📖', body_nl = 'Wil hij bij het avondverhaal de bladzijden uit het boek scheuren? Lees in Blogs hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Ochota na darcie stron 📖', body_pl = 'Podczas wieczornej bajki chce drzeć strony książki? Przeczytaj w sekcji Blog, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'A mania de rasgar páginas 📖', body_pt = 'Na história da noite, quer rasgar as páginas do livro? Leia nos Blogues como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Lust att riva sönder sidorna 📖', body_sv = 'Vill barnet riva sönder sidorna i boken vid kvällssagan? Läs i Bloggar hur du löser problemet utan att skada läsvanan.', title_vi = 'Mê xé trang sách 📖', body_vi = 'Đến giờ kể chuyện buổi tối là bé muốn xé trang sách? Hãy đọc trong mục Blog cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '爱撕书页 📖', body_zh = '晚上讲故事时想把书页撕碎？去博客板块读读，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = 'b991e93f-39a2-4eb7-afdb-453c13a1d55b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mordiscos de enfado 🦖', body_es = '¿Cuando se enfada te muerde a ti o a sus amigos? Pregunta ya a nuestro asistente experto Anacan AI cómo afrontar con cariño esta conducta difícil.', title_fr = 'Morsures de colère 🦖', body_fr = 'Il mord ses copains ou vous quand il se fâche ? Demandez tout de suite à notre assistant expert Anacan AI comment gérer ce comportement difficile avec amour.', title_hi = 'गुस्से में काटना 🦖', body_hi = 'गुस्से में दोस्तों को या आपको काटता है? इस मुश्किल व्यवहार को प्यार से कैसे सुलझाएँ, यह तुरंत हमारे Anacan AI एक्सपर्ट असिस्टेंट से पूछिए।', title_id = 'Gigitan saat marah 🦖', body_id = 'Menggigit temannya atau Anda saat marah? Segera tanyakan kepada asisten ahli Anacan AI cara mengatasi perilaku sulit ini dengan penuh kasih.', title_ja = '怒ってかみつく 🦖', body_ja = '怒るとお友だちやあなたにかみつきますか？この難しい行動に愛情をもってどう対応すればいいか、すぐにAnacan AIのエキスパートアシスタントに聞いてみましょう。', title_ko = '화가 나서 깨물어요 🦖', body_ko = '화가 나면 친구나 엄마를 깨무나요? 이 어려운 행동을 사랑으로 다루는 방법을 Anacan AI 전문가 도우미에게 바로 물어보세요.', title_nl = 'Boos bijten 🦖', body_nl = 'Bijt hij vriendjes of jou als hij boos is? Vraag onze Anacan AI-expert meteen hoe je dit lastige gedrag liefdevol aanpakt.', title_pl = 'Gryzienie ze złości 🦖', body_pl = 'Gdy się złości, gryzie kolegów albo ciebie? Od razu zapytaj naszego eksperta Anacan AI, jak z miłością poradzić sobie z tym trudnym zachowaniem.', title_pt = 'Mordidas de raiva 🦖', body_pt = 'Quando se zanga, morde os amigos ou a mãe? Pergunte já ao nosso assistente especialista Anacan AI como resolver com amor este comportamento difícil.', title_sv = 'Biter när hen är arg 🦖', body_sv = 'Biter barnet sina kompisar eller dig när hen blir arg? Fråga vår expertassistent Anacan AI direkt hur du med kärlek kan hantera detta svåra beteende.', title_vi = 'Cắn vì tức giận 🦖', body_vi = 'Bé cắn bạn hoặc cắn mẹ khi tức giận? Hãy hỏi ngay trợ lý chuyên gia Anacan AI cách xử lý hành vi khó khăn này bằng tình yêu thương.', title_zh = '生气就咬人 🦖', body_zh = '一生气就咬小朋友或咬你？马上问问我们的Anacan AI专家助手，如何用爱解决这种棘手的行为。' WHERE id = 'fa426bdb-bb7f-4a4f-9e93-d26f8fe4998a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te duele la espalda? 🧘‍♀️', body_es = 'No es fácil coger en brazos sin parar a un peque de más de 12 kg. Prepárate un té de jengibre antiinflamatorio que relaja los músculos de Recetas saludables para mujeres y descansa.', title_fr = 'Vous avez mal au dos ? 🧘‍♀️', body_fr = 'Porter sans cesse un petit de plus de 12 kg n''est pas facile. Préparez une tisane de gingembre anti-inflammatoire qui détend les muscles avec les Recettes saines pour femmes, et reposez-vous.', title_hi = 'कमर दर्द है? 🧘‍♀️', body_hi = '12+ kg के नन्हे को बार-बार उठाना आसान नहीं। महिलाओं के लिए सेहतमंद रेसिपी से मांसपेशियों को आराम देने वाली, सूजन कम करने वाली अदरक की चाय बनाइए और आराम कीजिए।', title_id = 'Punggung Anda sakit? 🧘‍♀️', body_id = 'Terus-menerus menggendong si kecil yang beratnya 12+ kg tidaklah mudah. Seduh teh jahe antiradang yang merilekskan otot dari Resep Sehat untuk wanita, lalu beristirahatlah.', title_ja = '腰が痛い？🧘‍♀️', body_ja = '12kg以上のお子さんを何度も抱き上げるのは大変です。「女性のためのヘルシーレシピ」から、筋肉をほぐし炎症をおさえるしょうが茶をいれて、休みましょう。', title_ko = '허리가 아프나요? 🧘‍♀️', body_ko = '12kg이 넘는 아이를 계속 안아 올리기는 쉽지 않아요. 여성을 위한 건강한 레시피에서 근육을 풀어 주고 염증을 줄이는 생강차를 우려 쉬세요.', title_nl = 'Pijn in je rug? 🧘‍♀️', body_nl = 'Steeds een kleintje van 12+ kg optillen is niet makkelijk. Zet ontstekingsremmende gemberthee uit Gezonde recepten voor vrouwen die je spieren ontspant, en rust uit.', title_pl = 'Bolą cię plecy? 🧘‍♀️', body_pl = 'Ciągłe podnoszenie malucha ważącego ponad 12 kg to nie lada wyzwanie. Zaparz ze Zdrowych przepisów dla kobiet przeciwzapalną herbatę imbirową, która rozluźnia mięśnie, i odpocznij.', title_pt = 'Dores nas costas? 🧘‍♀️', body_pt = 'Pegar sem parar num pequenino de mais de 12 kg não é fácil. Prepare um chá de gengibre das Receitas Saudáveis para Mulheres, anti-inflamatório e que relaxa os músculos, e descanse.', title_sv = 'Ont i ryggen? 🧘‍♀️', body_sv = 'Det är inte lätt att ständigt lyfta en liten på över 12 kg. Brygg ett antiinflammatoriskt ingefärste som får musklerna att slappna av från Hälsosamma recept för kvinnor och vila.', title_vi = 'Mẹ bị đau lưng? 🧘‍♀️', body_vi = 'Liên tục bế một em bé hơn 12 kg không hề dễ dàng. Hãy pha trà gừng chống viêm, giúp thư giãn cơ từ Công thức lành mạnh cho phụ nữ và nghỉ ngơi.', title_zh = '腰疼吗？🧘‍♀️', body_zh = '不停地抱起12+ kg的小家伙可不容易。从女性健康食谱里泡一杯放松肌肉、抗炎的姜茶，休息一下吧。' WHERE id = '1c3f0685-89ab-4827-a123-f84fa8b82551' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Obra de arte en la pared 🎨', body_es = '¿Ha cogido un bolígrafo y ha pintado la pared? ¡No te enfades! Añade esta dulce travesura al álbum con los marcos divertidos de la Sesión de fotos del bebé y simplemente sonríe.', title_fr = 'Une œuvre d''art sur le mur 🎨', body_fr = 'Il a pris un stylo et dessiné sur le mur ? Ne vous énervez pas ! Ajoutez cette mignonne bêtise à l''album avec les cadres rigolos de la Séance photo bébé, et souriez simplement.', title_hi = 'दीवार पर कलाकृति 🎨', body_hi = 'पेन लेकर दीवार रंग दी? गुस्सा मत होइए! इस प्यारी शरारत को बेबी फ़ोटोशूट के मज़ेदार फ़्रेम के साथ एल्बम में जोड़िए और बस मुस्कुराइए।', title_id = 'Karya seni di dinding 🎨', body_id = 'Ia mengambil pulpen dan mencoret dinding? Jangan kesal! Tambahkan kenakalan manis ini ke album dengan bingkai lucu dari Sesi Foto Bayi, dan tersenyumlah.', title_ja = '壁の上の芸術作品 🎨', body_ja = 'ペンを手に取って壁に描いてしまいましたか？怒らないで！このかわいいいたずらを、「ベビーフォトセッション」のおもしろいフレームでアルバムに追加して、ただほほえみましょう。', title_ko = '벽 위의 예술 작품 🎨', body_ko = '펜을 들고 벽에 그림을 그렸나요? 화내지 마세요! 이 귀여운 장난을 아기 사진 촬영의 재미있는 프레임으로 앨범에 담고 그냥 웃어 주세요.', title_nl = 'Kunstwerk op de muur 🎨', body_nl = 'Heeft hij met een pen op de muur getekend? Word niet boos! Zet deze lieve ondeugd met grappige kaders uit Babyfotoshoot in het album en glimlach gewoon.', title_pl = 'Dzieło sztuki na ścianie 🎨', body_pl = 'Wziął długopis i pomalował ścianę? Nie denerwuj się! Dodaj tę słodką psotę do albumu z zabawnymi ramkami z Sesji zdjęciowej dziecka i po prostu się uśmiechnij.', title_pt = 'Uma obra de arte na parede 🎨', body_pt = 'Pegou numa caneta e pintou a parede? Não se enerve! Adicione esta traquinice tão doce ao álbum com as molduras engraçadas da Sessão Fotográfica do Bebé e limite-se a sorrir.', title_sv = 'Konstverk på väggen 🎨', body_sv = 'Tog barnet en penna och målade på väggen? Bli inte irriterad! Lägg till det söta busstreck i albumet med roliga ramar i Babyfotografering och le bara.', title_vi = 'Tác phẩm nghệ thuật trên tường 🎨', body_vi = 'Bé cầm bút vẽ lên tường? Đừng bực mình! Hãy thêm trò nghịch ngợm đáng yêu này vào album với khung ảnh ngộ nghĩnh trong Chụp ảnh cho bé và cứ mỉm cười thôi.', title_zh = '墙上的艺术作品 🎨', body_zh = '拿起笔就在墙上画画？别生气！用宝宝写真里的搞笑相框把这个可爱的淘气瞬间加进相册，笑一笑就好。' WHERE id = '71912e32-5753-4990-97c7-dcf5458c45d1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga de la cama 🏃‍♂️', body_es = '¿A la hora de dormir trepa y se sale de la cuna? Pon el temporizador de sueño y el sonido monótono del tren de Ruido blanco para llevarle con calma al sueño.', title_fr = 'Plan d''évasion du lit 🏃‍♂️', body_fr = 'Il escalade son lit à barreaux à l''heure du coucher ? Lancez le minuteur de sommeil, mettez le bruit monotone du train des Bruits blancs et amenez-le doucement vers le sommeil.', title_hi = 'बिस्तर से भागने का प्लान 🏃‍♂️', body_hi = 'सोने का समय आते ही पालने से चढ़कर बाहर निकल आता है? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में ट्रेन की एक जैसी आवाज़ लगाइए और उसे शांति से नींद के लिए तैयार कीजिए।', title_id = 'Rencana kabur dari tempat tidur 🏃‍♂️', body_id = 'Memanjat keluar dari boks saat jam tidur tiba? Nyalakan Timer Tidur, putar suara kereta yang monoton dari Suara Putih, dan antar ia tidur dengan tenang.', title_ja = 'ベッドからの脱走計画 🏃‍♂️', body_ja = '寝る時間になると、ベビーベッドからよじ登って出てきますか？睡眠タイマーをオンにして、「ホワイトノイズ」の単調な電車の音を流し、静かに眠りへ導きましょう。', title_ko = '침대 탈출 작전 🏃‍♂️', body_ko = '잘 시간만 되면 아기 침대를 넘어 나오나요? 수면 타이머를 켜고 백색소음의 단조로운 기차 소리로 조용히 잠들 준비를 도와주세요.', title_nl = 'Ontsnappingsplan uit bed 🏃‍♂️', body_nl = 'Klimt hij uit zijn bedje als het bedtijd is? Zet de Slaaptimer aan, kies het monotone treingeluid in Witte ruis en laat hem rustig in slaap vallen.', title_pl = 'Plan ucieczki z łóżka 🏃‍♂️', body_pl = 'Gdy przychodzi pora snu, wychodzi z łóżeczka? Włącz timer snu, puść monotonny stukot pociągu z Białego szumu i spokojnie nastrój go do snu.', title_pt = 'Plano de fuga da cama 🏃‍♂️', body_pt = 'Na hora de dormir, trepa e sai do berço? Ligue o temporizador de sono, ponha o som monótono do comboio do Ruído Branco e prepare-o com calma para dormir.', title_sv = 'Flyktplanen från sängen 🏃‍♂️', body_sv = 'Klättrar barnet ur spjälsängen när det är dags att sova? Starta sömntimern, sätt på det monotona tågljudet från Vitt brus och stäm lugnt barnet för sömn.', title_vi = 'Kế hoạch trốn khỏi giường 🏃‍♂️', body_vi = 'Đến giờ ngủ là bé trèo ra khỏi cũi? Hãy bật Bộ hẹn giờ ngủ, mở tiếng tàu hỏa đều đều trong Tiếng ồn trắng để nhẹ nhàng đưa bé vào giấc ngủ.', title_zh = '逃离床铺计划 🏃‍♂️', body_zh = '一到睡觉时间就从小床里爬出来？打开睡眠计时器，播放白噪音里单调的火车声，让宝宝平静地进入睡眠。' WHERE id = 'aa4285be-2d37-4c2f-82d8-24587b052512' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Señales del orinal? 🚽', body_es = '¿El pañal de la mañana está totalmente seco? Puede ser el momento ideal para empezar a dejar el pañal. Anótalo en el Seguimiento de pañales y mira orinales ergonómicos en Productos recomendados.', title_fr = 'Des signes pour le pot ? 🚽', body_fr = 'La couche du matin est toute sèche ? C''est peut-être le moment idéal pour commencer l''apprentissage de la propreté. Notez-le dans le Suivi des couches et regardez les pots ergonomiques des Produits recommandés.', title_hi = 'पॉटी के संकेत? 🚽', body_hi = 'सुबह का डायपर बिल्कुल सूखा है? टॉयलेट ट्रेनिंग शुरू करने का यह सही समय हो सकता है। डायपर ट्रैकर में दर्ज कीजिए और सुझाए गए प्रोडक्ट में आरामदायक पॉटी देखिए।', title_id = 'Tanda siap pispot? 🚽', body_id = 'Popok paginya kering sama sekali? Ini bisa jadi waktu ideal untuk mulai latihan toilet. Catat di Pelacak Popok dan lihat pilihan pispot ergonomis di Produk Rekomendasi.', title_ja = 'トイレのサイン？🚽', body_ja = '朝のおむつがすっかり乾いていますか？トイレトレーニングを始めるのにぴったりの時期かもしれません。「おむつトラッカー」に記録して、「おすすめ商品」で人間工学に基づいたおまるをチェックしましょう。', title_ko = '배변 훈련 신호? 🚽', body_ko = '아침 기저귀가 보송보송한가요? 배변 훈련을 시작하기 좋은 때일 수 있어요. 기저귀 기록에 남기고 추천 제품에서 인체공학적 유아 변기를 살펴보세요.', title_nl = 'Signalen voor het potje? 🚽', body_nl = 'Is de ochtendluier kurkdroog? Dit kan het ideale moment zijn om met zindelijkheidstraining te beginnen. Noteer het in de Luiertracker en bekijk ergonomische potjes in Aanbevolen producten.', title_pl = 'Sygnały gotowości do nocnika? 🚽', body_pl = 'Poranna pieluszka zupełnie sucha? To może być idealny moment, by zacząć naukę korzystania z toalety. Zapisz to w narzędziu do śledzenia pieluszek i zajrzyj do Polecanych produktów po ergonomiczny nocnik.', title_pt = 'Sinais de bacio? 🚽', body_pt = 'A fralda da manhã está completamente seca? Pode ser a altura ideal para começar a deixar a fralda. Registe-o no Registo de Fraldas e veja nos Produtos Recomendados bacios ergonómicos.', title_sv = 'Signaler om pottan? 🚽', body_sv = 'Är morgonblöjan helt torr? Det kan vara perfekt tid att börja med toaträning. Anteckna i Blöjkollen och titta på ergonomiska pottor i Rekommenderade produkter.', title_vi = 'Tín hiệu sẵn sàng ngồi bô? 🚽', body_vi = 'Tã buổi sáng khô cong? Có thể đây là thời điểm lý tưởng để bắt đầu tập đi vệ sinh. Hãy ghi lại trong Theo dõi tã và xem các mẫu bô tiện dụng trong Sản phẩm gợi ý.', title_zh = '便盆信号？🚽', body_zh = '早上的尿布干干的？可能是开始如厕训练的理想时机。记在尿布记录里，再去推荐商品看看符合人体工学的便盆。' WHERE id = '406278a2-debe-4851-9b00-479abeb4b13e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Quiere jugar solo? 👶', body_es = '¿En el parque no se une a los demás niños y los observa desde fuera? Descubre en el Blog los datos más curiosos y científicos sobre este sano juego paralelo.', title_fr = 'Il veut jouer seul ? 👶', body_fr = 'Au parc, il ne rejoint pas les autres enfants et les observe de loin ? Découvrez dans la rubrique Blogs les faits scientifiques les plus intéressants sur ce jeu parallèle tout à fait sain.', title_hi = 'अकेले खेलना चाहता है? 👶', body_hi = 'पार्क में दूसरे बच्चों के साथ नहीं खेलता, दूर से देखता है? इस सेहतमंद पैरेलल प्ले के बारे में सबसे दिलचस्प और वैज्ञानिक तथ्य ब्लॉग सेक्शन में जानिए।', title_id = 'Ingin bermain sendiri? 👶', body_id = 'Di taman ia tidak ikut bermain dengan anak lain, hanya mengamati dari pinggir? Temukan fakta ilmiah paling menarik tentang bermain paralel yang sehat ini di bagian Blog.', title_ja = 'ひとりで遊びたい？👶', body_ja = '公園でほかの子の輪に入らず、そばで見ていますか？この健やかな「平行遊び」についての、いちばんおもしろくて科学的な豆知識を、ブログで見つけましょう。', title_ko = '혼자 놀고 싶어 하나요? 👶', body_ko = '공원에서 다른 아이들과 어울리지 않고 옆에서 지켜보나요? 이 건강한 평행 놀이에 관한 흥미롭고 과학적인 사실을 블로그에서 찾아보세요.', title_nl = 'Speelt hij liever alleen? 👶', body_nl = 'Doet hij in het park niet mee met andere kinderen, maar kijkt hij toe? Ontdek in Blogs de leukste wetenschappelijke feitjes over dit gezonde parallelle spel.', title_pl = 'Chce się bawić sam? 👶', body_pl = 'W parku nie dołącza do innych dzieci, tylko patrzy z boku? Odkryj w sekcji Blog najciekawsze naukowe fakty o tej zdrowej zabawie równoległej.', title_pt = 'Quer brincar sozinho? 👶', body_pt = 'No parque não se junta às outras crianças e observa de longe? Descubra nos Blogues os factos mais curiosos e científicos sobre esta saudável brincadeira paralela.', title_sv = 'Vill leka själv? 👶', body_sv = 'Ansluter sig barnet inte till de andra barnen i parken utan tittar bara på? Upptäck de mest intressanta och vetenskapliga fakta om denna sunda parallellek i Bloggar.', title_vi = 'Bé muốn chơi một mình? 👶', body_vi = 'Ở công viên bé không nhập hội mà chỉ đứng nhìn các bạn? Hãy khám phá những điều thú vị và khoa học nhất về kiểu chơi song song lành mạnh này trong mục Blog.', title_zh = '想一个人玩？👶', body_zh = '在公园不加入其他小朋友，只在旁边看？去博客板块发现关于这种健康的平行游戏最有趣、最科学的知识。' WHERE id = '67af77d4-bcc0-42c9-9d93-190208cee7c5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de la madre perfecta 💖', body_es = '¿Hoy has levantado un poco la voz? No te sientas culpable. Escribe cómo te sientes en el Diario de ánimo: ya eres la mejor para tu peque.', title_fr = 'À la recherche de la maman parfaite 💖', body_fr = 'Vous avez un peu haussé le ton aujourd''hui ? Ne culpabilisez pas. Écrivez vos émotions dans le Journal d''humeur : pour lui, vous êtes déjà la meilleure.', title_hi = 'परफ़ेक्ट माँ की तलाश 💖', body_hi = 'आज आपकी आवाज़ थोड़ी ऊँची हो गई? खुद को दोष मत दीजिए। मूड डायरी में अपनी भावनाएँ लिखिए, आप वैसे भी उसके लिए सबसे अच्छी हैं।', title_id = 'Mencari ibu yang sempurna 💖', body_id = 'Hari ini suara Anda sedikit meninggi? Jangan merasa bersalah. Tulis perasaan Anda di Buku Harian Suasana Hati, Anda tetap yang terbaik untuknya.', title_ja = '完璧なママを目指して 💖', body_ja = '今日は少し声を荒らげてしまいましたか？罪悪感を持たないで。「気分日記」に気持ちを書きましょう。あなたはお子さんにとって、すでに最高のママです。', title_ko = '완벽한 엄마를 찾아서 💖', body_ko = '오늘 목소리가 조금 커졌나요? 죄책감은 내려놓으세요. 기분 일기에 마음을 적어 보세요. 엄마는 이미 아이에게 최고예요.', title_nl = 'Op zoek naar de perfecte moeder 💖', body_nl = 'Verhief je vandaag je stem een beetje? Voel je niet schuldig. Schrijf je gevoelens op in je Stemmingsdagboek, je bent hoe dan ook de beste voor hem.', title_pl = 'W poszukiwaniu idealnej mamy 💖', body_pl = 'Podniosłaś dziś trochę głos? Nie miej wyrzutów sumienia. Zapisz swoje uczucia w Dzienniku nastroju, i tak jesteś dla niego najlepsza.', title_pt = 'À procura da mãe perfeita 💖', body_pt = 'Hoje levantou um pouco a voz? Não se sinta culpada. Escreva o que sente no Diário de Humor: para ele, já é a melhor.', title_sv = 'På jakt efter den perfekta mamman 💖', body_sv = 'Höjde du rösten lite i dag? Känn inget dåligt samvete. Skriv ner dina känslor i Humördagboken, du är redan den bästa för ditt barn.', title_vi = 'Đi tìm người mẹ hoàn hảo 💖', body_vi = 'Hôm nay mẹ lỡ to tiếng một chút? Đừng áy náy. Hãy viết cảm xúc vào Nhật ký tâm trạng, vì với bé, mẹ vẫn là tuyệt nhất.', title_zh = '寻找完美妈妈 💖', body_zh = '今天说话声音有点大了？别内疚。把感受写进心情日记，你本来就是宝宝最好的妈妈。' WHERE id = '789f31a5-225d-4210-8e89-eb69a6524d9d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño y sigue el gráfico. Quizá sea el momento de acortar la siesta 15 minutos.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil et suivez le graphique. C''est peut-être le bon moment pour raccourcir la sieste de 15 minutes.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 15 मिनट कम करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin inilah saatnya memangkas tidur siang 15 menit.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにして、グラフをチェックしましょう。お昼寝を15分短くするちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 15분 줄일 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan en volg de grafiek. Misschien is het precies tijd om het middagdutje met 15 minuten in te korten.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu i śledź wykres. Może to dobry moment, by skrócić drzemkę o 15 minut.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono e acompanhe o gráfico. Talvez seja a altura certa de encurtar a sesta 15 minutos.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern och följ grafen. Kanske är det precis rätt tid att korta dagsömnen med 15 minuter.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 15 phút.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器，看看图表。也许正是把白天小睡缩短15分钟的时候了。' WHERE id = '354016aa-fdff-494e-9db1-d11124a417c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena y barro 🏖️', body_es = '¡No tengas miedo a que se ensucie! Para su desarrollo sensorial, busca en Lugares para mamás un parque seguro con arenero y déjale a solas con la naturaleza.', title_fr = 'Thérapie par le sable et la boue 🏖️', body_fr = 'N''ayez pas peur qu''il se salisse ! Pour son développement sensoriel, trouvez dans les Lieux adaptés aux mamans un parc sûr avec bac à sable et laissez-le en tête-à-tête avec la nature.', title_hi = 'रेत और मिट्टी थेरेपी 🏖️', body_hi = 'गंदा होने से मत डरिए! सेंसरी विकास के लिए माँ के लिए अनुकूल जगहें में सैंडपिट वाला सुरक्षित पार्क ढूँढिए और उसे प्रकृति के साथ खुलकर खेलने दीजिए।', title_id = 'Terapi pasir dan lumpur 🏖️', body_id = 'Jangan takut kotor! Untuk perkembangan sensoriknya, temukan taman aman dengan bak pasir di Tempat Ramah Ibu dan biarkan ia menyatu dengan alam.', title_ja = '砂と泥んこセラピー 🏖️', body_ja = '汚れるのをこわがらないで！感覚の発達のために、「ママにやさしいスポット」で砂場のある安全な公園を見つけて、自然と思いきりふれあわせてあげましょう。', title_ko = '모래와 진흙 테라피 🏖️', body_ko = '더러워지는 걸 두려워하지 마세요! 감각 발달을 위해 엄마 친화 장소에서 모래 놀이터가 있는 안전한 공원을 찾아 자연과 마음껏 만나게 해 주세요.', title_nl = 'Zand- en moddertherapie 🏖️', body_nl = 'Wees niet bang voor vieze handjes! Zoek in Mamavriendelijke plekken een veilig park met een zandbak voor zijn zintuiglijke ontwikkeling en laat hem de natuur ontdekken.', title_pl = 'Terapia piaskiem i błotem 🏖️', body_pl = 'Nie bój się brudu! Dla rozwoju sensorycznego znajdź w Miejscach przyjaznych mamom bezpieczny park z piaskownicą i pozwól mu pobyć sam na sam z naturą.', title_pt = 'Terapia com areia e lama 🏖️', body_pt = 'Não tenha medo que se suje! Para o desenvolvimento sensorial, encontre nos Locais Amigos das Mães um parque seguro com caixa de areia e deixe-o a sós com a natureza.', title_sv = 'Sand- och leraterapi 🏖️', body_sv = 'Var inte rädd för smuts! Hitta en trygg park med sandlåda i Mammavänliga platser för sinnesutvecklingen och låt barnet vara ensam med naturen.', title_vi = 'Liệu pháp cát và bùn 🏖️', body_vi = 'Đừng sợ bé bị bẩn! Để phát triển giác quan, hãy tìm một công viên an toàn có hố cát trong Địa điểm thân thiện với mẹ và để bé hòa mình vào thiên nhiên.', title_zh = '沙子和泥巴疗法 🏖️', body_zh = '别怕弄脏！为了感官发展，在妈妈友好场所里找一个有沙池的安全公园，让宝宝和大自然亲密接触。' WHERE id = 'd03661d9-e587-4637-b9c4-cf2d9c6ce6c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El mejor amigo del hierro 🥩', body_es = '¡La vitamina C es imprescindible para que el cuerpo absorba el hierro! Revisa el menú de hoy con el Seguimiento de tomas y añade a la carne una ensalada con mucho limón.', title_fr = 'Le meilleur ami du fer 🥩', body_fr = 'La vitamine C est indispensable pour que le corps absorbe le fer ! Vérifiez le menu du jour avec le Suivi des repas et ajoutez une salade bien citronnée avec la viande.', title_hi = 'आयरन का सबसे अच्छा दोस्त 🥩', body_hi = 'शरीर में आयरन सोखने के लिए विटामिन C ज़रूरी है! फ़ीडिंग ट्रैकर से आज का मेन्यू जाँचिए और मांस के साथ नींबू वाला सलाद ज़रूर जोड़िए।', title_id = 'Sahabat terbaik zat besi 🥩', body_id = 'Vitamin C wajib agar zat besi terserap tubuh! Cek menu hari ini dengan alat Pemantau Nutrisi dan tambahkan salad dengan banyak perasan lemon di samping daging.', title_ja = '鉄分のいちばんの相棒 🥩', body_ja = '鉄分を体に吸収するにはビタミンCが欠かせません！「栄養管理ツール」で今日のメニューを確認して、お肉と一緒にレモンたっぷりのサラダを添えましょう。', title_ko = '철분의 단짝 🥩', body_ko = '철분이 몸에 흡수되려면 비타민 C가 꼭 필요해요! 수유 기록 도구로 오늘 식단을 확인하고 고기와 함께 레몬을 듬뿍 뿌린 샐러드를 곁들이세요.', title_nl = 'De beste vriend van ijzer 🥩', body_nl = 'Vitamine C is nodig om ijzer in het lichaam op te nemen! Controleer het menu van vandaag met de Voedingstracker en zet naast het vlees een salade met veel citroen.', title_pl = 'Najlepszy przyjaciel żelaza 🥩', body_pl = 'Witamina C jest niezbędna do wchłaniania żelaza! Sprawdź dzisiejsze menu w narzędziu do śledzenia karmienia i dodaj do mięsa sałatkę z dużą ilością cytryny.', title_pt = 'O melhor amigo do ferro 🥩', body_pt = 'A vitamina C é indispensável para o corpo absorver o ferro! Verifique a ementa de hoje com o Registo de Alimentação e junte à carne uma salada com bastante limão.', title_sv = 'Järnets bästa vän 🥩', body_sv = 'C-vitamin behövs för att kroppen ska ta upp järn! Kontrollera dagens meny med Matningskoll och servera en sallad med mycket citron till köttet.', title_vi = 'Người bạn thân nhất của sắt 🥩', body_vi = 'Cơ thể cần vitamin C để hấp thu sắt! Hãy kiểm tra thực đơn hôm nay bằng Theo dõi cữ bú và thêm món salad nhiều chanh ăn kèm thịt.', title_zh = '铁的好朋友 🥩', body_zh = '身体吸收铁离不开维生素C！用喂养记录工具检查今天的菜单，搭配肉类加一份多放柠檬汁的沙拉。' WHERE id = 'dd733e39-eed2-478b-9a6a-adcec13e6fc1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Saltos con los dos pies 🦘', body_es = '¿Intenta saltar con los dos pies a la vez sin moverse del sitio? Queda graciosísimo, ¿verdad? Inmortaliza este momento sin falta.', title_fr = 'Sauter à pieds joints 🦘', body_fr = 'Il essaie de sauter sur place à pieds joints ? C''est trop drôle, non ? Immortalisez absolument ce moment.', title_hi = 'दोनों पैरों से कूदना 🦘', body_hi = 'एक ही जगह खड़े होकर दोनों पैरों से एक साथ कूदने की कोशिश करता है? बहुत मज़ेदार लगता है, है ना? इस पल को ज़रूर हमेशा के लिए सहेजिए।', title_id = 'Melompat dengan dua kaki 🦘', body_id = 'Ia mencoba melompat dengan dua kaki sekaligus di tempat? Lucu sekali, bukan? Pastikan Anda mengabadikan momen ini.', title_ja = '両足ジャンプ 🦘', body_ja = 'その場で両足をそろえてジャンプしようとしていますか？とってもおもしろい姿ですよね？この瞬間をぜひ残しましょう。', title_ko = '두 발로 깡충 🦘', body_ko = '제자리에서 두 발로 동시에 뛰어 보려고 하나요? 정말 귀엽죠? 이 순간을 꼭 남겨 두세요.', title_nl = 'Springen met twee voeten 🦘', body_nl = 'Probeert hij op de plek met beide voeten tegelijk te springen? Wat ziet dat er grappig uit, toch? Leg dit moment zeker vast.', title_pl = 'Skoki obunóż 🦘', body_pl = 'Próbuje podskakiwać w miejscu obiema nogami naraz? Wygląda to przezabawnie, prawda? Koniecznie uwiecznij tę chwilę.', title_pt = 'Saltar a pés juntos 🦘', body_pt = 'Tenta saltar no mesmo sítio com os dois pés ao mesmo tempo? É muito engraçado, não é? Eternize sem falta este momento.', title_sv = 'Hopp med båda fötterna 🦘', body_sv = 'Försöker barnet hoppa med båda fötterna samtidigt på stället? Det ser så roligt ut, eller hur? Förevig ögonblicket.', title_vi = 'Bật nhảy bằng hai chân 🦘', body_vi = 'Bé đứng tại chỗ và cố nhảy bằng cả hai chân cùng lúc? Trông thật buồn cười phải không? Nhất định hãy lưu lại khoảnh khắc này.', title_zh = '双脚跳 🦘', body_zh = '宝宝站在原地，想用双脚同时起跳？看起来超搞笑吧？一定要把这一刻永远留下来。' WHERE id = '7057ef80-4efd-430a-a44f-a695f7bd7b53' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma musical 🎶', body_es = 'La forma más fácil de calmar el llanto de última hora de la tarde es poner su melodía favorita, abrazarle y bailar despacito juntos.', title_fr = 'Sérénité en musique 🎶', body_fr = 'Le plus simple pour apaiser les pleurnicheries de fin de journée : mettez une mélodie qu''il aime, prenez-le dans vos bras et dansez doucement.', title_hi = 'संगीत भरा सुकून 🎶', body_hi = 'शाम को होने वाली चिड़चिड़ाहट को संभालने का सबसे आसान तरीका है उसकी पसंदीदा धुन लगाकर उसे गले लगाकर धीरे-धीरे नाचना।', title_id = 'Damai bersama musik 🎶', body_id = 'Cara termudah meredakan rewel di sore hari adalah memutar melodi favoritnya, memeluknya, lalu berdansa pelan bersamanya.', title_ja = '音楽でほっとひと息 🎶', body_ja = '夕方のぐずりをいちばん簡単に落ち着かせる方法は、好きな曲をかけて、ぎゅっと抱っこしながらゆっくり踊ることです。', title_ko = '음악과 함께 평온하게 🎶', body_ko = '저녁 무렵의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안은 채 천천히 춤추는 거예요.', title_nl = 'Muzikale rust 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsmelodie op, knuffel hem en dans samen langzaam.', title_pl = 'Muzyczny spokój 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną melodię, przytulić go i powoli razem zatańczyć.', title_pt = 'Tranquilidade com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma melodia de que ele goste, abraçá-lo e dançar devagarinho.', title_sv = 'Lugn med musik 🎶', body_sv = 'Det enklaste sättet att lösa gnälligheten framåt kvällen är att sätta på en favoritmelodi, krama barnet och dansa långsamt tillsammans.', title_vi = 'Bình yên cùng âm nhạc 🎶', body_vi = 'Cách dễ nhất để xoa dịu cơn quấy khóc lúc chiều tối là bật giai điệu bé yêu thích, ôm bé vào lòng và nhẹ nhàng nhảy cùng bé.', title_zh = '音乐中的安宁 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝喜欢的曲子，抱着宝宝慢慢跳舞。' WHERE id = 'a5fa8450-6478-40eb-8c4a-42d08f636974' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere dormir? 🥱', body_es = '¿Se resiste a la siesta? Pide a Anacan AI información precisa sobre las ventanas de sueño cerca de los 2 años y un horario de rutina.', title_fr = 'Il refuse de dormir ? 🥱', body_fr = 'Il résiste à la sieste ? Demandez à Anacan AI des informations précises sur les fenêtres de sommeil à l''approche des 2 ans et un planning adapté.', title_hi = 'सोने से इनकार? 🥱', body_hi = 'दिन में सोना नहीं चाहता और विरोध करता है? Anacan AI से 2 साल के करीब की नींद की खिड़कियों के बारे में सटीक जानकारी और रूटीन चार्ट माँगिए।', title_id = 'Menolak tidur? 🥱', body_id = 'Ia menolak dan melawan saat waktu tidur siang? Minta informasi akurat tentang jendela tidur menjelang usia 2 tahun beserta jadwalnya dari Anacan AI.', title_ja = 'お昼寝いやいや？🥱', body_ja = 'お昼寝を嫌がって抵抗しますか？2歳に向けての活動時間（眠りのタイミング）と生活リズム表を、Anacan AIに聞いてみましょう。', title_ko = '낮잠 거부? 🥱', body_ko = '낮잠을 안 자려고 버티나요? Anacan AI에게 두 돌 무렵의 수면 간격에 대한 정확한 정보와 일과표를 물어보세요.', title_nl = 'Geen zin in slapen? 🥱', body_nl = 'Wil hij niet naar zijn middagdutje en verzet hij zich? Vraag Anacan AI om precieze info over slaapvensters rond 2 jaar en een dagschema.', title_pl = 'Odmawia spania? 🥱', body_pl = 'Nie chce iść na drzemkę i się opiera? Poproś Anacan AI o dokładne informacje o oknach snu w okolicach 2. urodzin i plan dnia.', title_pt = 'Recusa dormir? 🥱', body_pt = 'Não quer fazer a sesta e resiste? Peça ao Anacan AI informação precisa sobre as janelas de sono perto dos 2 anos e um horário de rotina.', title_sv = 'Vägrar sova? 🥱', body_sv = 'Vill barnet inte sova middag och gör motstånd? Be Anacan AI om exakt information om vakenfönster mot 2 års ålder och ett förslag på dagsrytm.', title_vi = 'Không chịu ngủ? 🥱', body_vi = 'Bé không muốn ngủ ngày và cứ cưỡng lại? Hãy hỏi Anacan AI thông tin chính xác về khung giờ ngủ và lịch sinh hoạt cho trẻ gần 2 tuổi.', title_zh = '不肯睡觉？🥱', body_zh = '不想睡午觉，一直抗拒？问问Anacan AI，了解快2岁宝宝的清醒时间窗口和作息表。' WHERE id = 'cea6f894-72c1-48a7-91fc-bc8637fa2cca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de dulces sanos 🍎', body_es = '¡Adiós a las galletas del súper! Descubre en Recetas para bebé dulces sanos caseros de dátiles y manzana que se preparan en 10 minutos y ábrele el apetito.', title_fr = 'À la recherche d''une douceur saine 🍎', body_fr = 'Fini les biscuits du commerce ! Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à la pomme, prêtes en 10 minutes à la maison, et ouvrez-lui l''appétit.', title_hi = 'सेहतमंद मिठाई की तलाश 🍎', body_hi = 'बाज़ार के बिस्किट को अलविदा! बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और सेब की सेहतमंद मिठाइयाँ खोजिए और उसकी भूख खोलिए।', title_id = 'Mencari camilan manis sehat 🍎', body_id = 'Selamat tinggal biskuit dari toko! Temukan camilan manis sehat dari kurma dan apel yang siap dalam 10 menit di Resep Bayi dan buka nafsu makannya.', title_ja = 'ヘルシーなおやつ探し 🍎', body_ja = '市販のクッキーとはお別れ！「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとりんごのヘルシーなおやつを見つけて、食欲を引き出しましょう。', title_ko = '건강한 간식 찾기 🍎', body_ko = '마트 쿠키는 이제 그만! 아기 레시피에서 집에서 10분이면 만드는 대추야자 사과 건강 간식을 찾아 입맛을 살려 주세요.', title_nl = 'Op zoek naar gezond lekkers 🍎', body_nl = 'Weg met koekjes uit de winkel! Ontdek in Babyrecepten gezonde lekkernijen met dadels en appel, thuis klaar in 10 minuten, en maak hem hongerig.', title_pl = 'W poszukiwaniu zdrowych słodkości 🍎', body_pl = 'Koniec ze sklepowymi ciastkami! Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i jabłkiem, które zrobisz w domu w 10 minut, i pobudź jego apetyt.', title_pt = 'À procura de doces saudáveis 🍎', body_pt = 'Adeus bolachas do supermercado! Descubra nas Receitas para bebés doces saudáveis de tâmaras e maçã, feitos em casa em 10 minutos, e abra-lhe o apetite.', title_sv = 'På jakt efter nyttigt godis 🍎', body_sv = 'Slut på kex från affären! Upptäck nyttiga sötsaker med dadlar och äpple som är klara på 10 minuter hemma i Recept för bebisar och väck aptiten.', title_vi = 'Tìm món ngọt lành mạnh 🍎', body_vi = 'Tạm biệt bánh quy mua sẵn! Hãy khám phá các món ngọt bổ dưỡng từ chà là và táo làm tại nhà trong 10 phút trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '寻找健康甜点 🍎', body_zh = '和超市饼干说再见！在宝宝食谱里发现10分钟就能在家做好的椰枣苹果健康甜点，让宝宝胃口大开。' WHERE id = 'b7bcd4fe-cc33-4ea9-a97e-59e15168cb31' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de lavarse los dientes 🪥', body_es = '¿Cierra la boca en cuanto ve el cepillo? Pide a Anacan AI consejos prácticos para convertir esta rutina de higiene tan importante en un juego divertido.', title_fr = 'La bataille du brossage de dents 🪥', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse ? Demandez à Anacan AI des conseils pratiques pour transformer ce rituel d''hygiène essentiel en jeu amusant.', title_hi = 'दाँत ब्रश करने की लड़ाई 🪥', body_hi = 'ब्रश देखते ही मुँह बंद कर लेता है? सफ़ाई के इस ज़रूरी रूटीन को मज़ेदार खेल कैसे बनाएँ, यह जानने के लिए Anacan AI से काम की सलाह लीजिए।', title_id = 'Drama sikat gigi 🪥', body_id = 'Langsung mengatupkan mulut begitu melihat sikat gigi? Dapatkan saran praktis dari Anacan AI untuk menjadikan rutinitas kebersihan penting ini permainan seru.', title_ja = '歯みがきバトル 🪥', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？この大切な歯みがきの習慣を楽しい遊びに変える実践的なアドバイスを、Anacan AIからもらいましょう。', title_ko = '양치 전쟁 🪥', body_ko = '칫솔만 보면 입을 꾹 다무나요? 이 중요한 위생 습관을 재미있는 놀이로 바꾸는 방법을 Anacan AI에게 실용적인 조언으로 받아 보세요.', title_nl = 'Gedoe met tandenpoetsen 🪥', body_nl = 'Klemt hij zijn mond dicht zodra hij de tandenborstel ziet? Vraag Anacan AI om praktische tips om van deze belangrijke verzorging een leuk spel te maken.', title_pl = 'Bitwa o mycie ząbków 🪥', body_pl = 'Zaciska buzię na widok szczoteczki? Poproś Anacan AI o praktyczne rady, jak zamienić tę ważną higieniczną rutynę w zabawę.', title_pt = 'A luta da escova de dentes 🪥', body_pt = 'Mal vê a escova, fecha a boca? Peça ao Anacan AI conselhos práticos para transformar esta rotina de higiene tão importante num jogo divertido.', title_sv = 'Kampen om tandborstningen 🪥', body_sv = 'Stänger barnet munnen så fort tandborsten syns? Få praktiska råd från Anacan AI om hur du gör den viktiga hygienrutinen till en rolig lek.', title_vi = 'Cuộc chiến đánh răng 🪥', body_vi = 'Vừa thấy bàn chải là bé mím chặt miệng? Hãy nhận lời khuyên thực tế từ Anacan AI để biến thói quen vệ sinh quan trọng này thành trò chơi vui nhộn.', title_zh = '刷牙大作战 🪥', body_zh = '一看到牙刷就紧闭小嘴？向Anacan AI获取实用建议，学习如何把这项重要的卫生习惯变成有趣的游戏。' WHERE id = 'ed519633-a8d9-4eaa-a80a-911f5bc80cd1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pronunciaciones graciosas 🗣️', body_es = '¡Hay palabras que dice tan dulcemente mal! No te pierdas estos momentos de oro. Súbelos en vídeo con sonido al Álbum del bebé y reíd juntos en el futuro.', title_fr = 'Prononciations rigolotes 🗣️', body_fr = 'Il prononce certains mots de travers, et c''est trop mignon ! Ne manquez pas ces moments en or. Ajoutez-les en vidéo avec le son à l''Album de bébé et riez-en ensemble plus tard.', title_hi = 'मज़ेदार उच्चारण 🗣️', body_hi = 'कुछ शब्द इतने प्यारे और गलत बोलता है! इन सुनहरे पलों को मत चूकिए। इन्हें आवाज़ वाले वीडियो के रूप में बेबी एल्बम में अपलोड कीजिए और आगे चलकर साथ में हँसिए।', title_id = 'Pelafalan yang lucu 🗣️', body_id = 'Ada kata-kata yang ia ucapkan dengan begitu manis meski salah! Jangan lewatkan momen emas ini. Unggah sebagai video bersuara ke Album Bayi dan tertawalah bersama di masa depan.', title_ja = 'おもしろい発音 🗣️', body_ja = 'いくつかの言葉を、とてもかわいく言いまちがえますね！この宝物のような瞬間を見逃さないで。音声付きの動画で「ベビーアルバム」にアップして、いつか一緒に笑いましょう。', title_ko = '귀여운 발음 🗣️', body_ko = '어떤 단어는 정말 귀엽게 틀리게 말해요! 이 소중한 순간을 놓치지 마세요. 소리가 담긴 영상으로 아기 앨범에 올려 나중에 함께 웃어요.', title_nl = 'Grappige uitspraak 🗣️', body_nl = 'Sommige woorden zegt hij zo schattig verkeerd! Mis deze gouden momenten niet. Zet ze als video met geluid in het Babyalbum en lach er later samen om.', title_pl = 'Zabawna wymowa 🗣️', body_pl = 'Niektóre słowa wymawia tak słodko i tak błędnie! Nie przegap tych złotych chwil. Dodaj je jako film z dźwiękiem do Albumu dziecka i pośmiejcie się z nich razem w przyszłości.', title_pt = 'Pronúncias engraçadas 🗣️', body_pt = 'Diz algumas palavras de forma tão doce e trocada! Não perca estes momentos de ouro. Carregue-os em vídeo com som no Álbum do Bebé e riam-se juntos no futuro.', title_sv = 'Roligt uttal 🗣️', body_sv = 'Vissa ord säger barnet så sött och fel! Missa inte dessa gyllene stunder. Ladda upp dem som video med ljud i Babyalbumet och skratta åt dem tillsammans i framtiden.', title_vi = 'Phát âm ngộ nghĩnh 🗣️', body_vi = 'Bé nói sai một số từ mà nghe đáng yêu vô cùng! Đừng bỏ lỡ những khoảnh khắc vàng này. Hãy tải video có tiếng lên Album của bé để sau này cùng nhau cười.', title_zh = '搞笑的发音 🗣️', body_zh = '有些词宝宝说得又可爱又不对！别错过这些黄金时刻。录成有声视频上传到宝宝相册，将来一起笑一笑。' WHERE id = 'fc53997b-db7d-4e51-803e-f6bd3797e9e3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Las últimas muelas? 🦷', body_es = '¿Lo muerde todo sin motivo y está más agresivo? Puede que vengan las muelas del fondo. Anota el proceso en el Seguimiento de dentición y ten listos los mordedores fríos.', title_fr = 'Les dernières molaires ? 🦷', body_fr = 'Il mâchouille tout sans raison et devient agressif ? Les molaires du fond arrivent peut-être. Notez l''évolution dans le Suivi des dents et préparez des anneaux de dentition froids.', title_hi = 'आखिरी दाढ़ें? 🦷', body_hi = 'बिना वजह सब कुछ चबाता है और चिड़चिड़ा हो गया है? सबसे पीछे की दाढ़ें आने वाली हो सकती हैं। दाँत निकलने के ट्रैकर में इसे दर्ज कीजिए और ठंडे टीदर तैयार रखिए।', title_id = 'Geraham terakhir? 🦷', body_id = 'Menggigit apa saja tanpa sebab dan jadi agresif? Geraham paling belakang mungkin sedang tumbuh. Catat prosesnya di Pelacak Tumbuh Gigi dan siapkan teether dingin.', title_ja = '最後の奥歯？🦷', body_ja = '理由もなくなんでもかじって、乱暴になっていますか？いちばん奥の奥歯が生えてきているのかもしれません。「歯の生え始めトラッカー」に記録して、冷やした歯がためを用意しましょう。', title_ko = '마지막 어금니? 🦷', body_ko = '이유 없이 뭐든 깨물고 공격적으로 변했나요? 가장 안쪽 어금니가 나오는 중일 수 있어요. 이앓이 기록에 과정을 남기고 차가운 치발기를 준비해 두세요.', title_nl = 'De laatste kiezen? 🦷', body_nl = 'Knaagt hij zonder reden op alles en is hij agressief? De achterste kiezen kunnen eraan komen. Noteer het in de Tandjestracker en leg koele bijtringen klaar.', title_pl = 'Ostatnie trzonowce? 🦷', body_pl = 'Gryzie wszystko bez powodu i zrobił się agresywny? Mogą wychodzić ostatnie trzonowce. Zapisz to w narzędziu do śledzenia ząbkowania i przygotuj schłodzone gryzaki.', title_pt = 'Os últimos molares? 🦷', body_pt = 'Rói tudo sem motivo e ficou agressivo? Os molares de trás podem estar a caminho. Registe o processo no Registo de Dentição e prepare mordedores frios.', title_sv = 'De sista kindtänderna? 🦷', body_sv = 'Tuggar barnet på allt och har blivit aggressivt utan anledning? De bakersta kindtänderna kan vara på väg. Anteckna det i Tandspåraren och ta fram kalla bitringar.', title_vi = 'Những chiếc răng hàm cuối cùng? 🦷', body_vi = 'Bé gặm mọi thứ và trở nên cáu kỉnh không rõ lý do? Có thể những chiếc răng hàm trong cùng đang mọc. Hãy ghi lại trong Theo dõi mọc răng và chuẩn bị vòng gặm nướu mát lạnh.', title_zh = '最后几颗磨牙？🦷', body_zh = '无缘无故什么都咬，还变得有攻击性？最里面的磨牙可能正在长。在出牙记录里记下过程，准备好冰凉的牙胶吧。' WHERE id = 'bcfad7da-e488-4ced-aa83-11c72d34ebec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe del cuento 🪄', body_es = 'Esta noche crea en Cuentos inteligentes una historia especial cuyo héroe sea tu peque: «El pequeño valiente al que le encanta lavarse los dientes».', title_fr = 'Le héros du conte 🪄', body_fr = 'Ce soir, créez dans les Contes intelligents une histoire spéciale dont votre enfant est le héros : « Le petit courageux qui adore se brosser les dents ».', title_hi = 'कहानी का हीरो 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: दाँत ब्रश करना पसंद करने वाला एक बहादुर नन्हा।', title_id = 'Tokoh utama dongeng 🪄', body_id = 'Malam ini, buat cerita istimewa di Dongeng Pintar dengan anak Anda sebagai tokoh utamanya: Si kecil pemberani yang suka menyikat gigi.', title_ja = 'お話の主人公 🪄', body_ja = '今夜は「スマートおはなし」で、お子さんが主人公の特別なお話をつくりましょう：「歯みがきが大好きな勇敢なおちびさん」。', title_ko = '동화 속 주인공 🪄', body_ko = '오늘 밤 스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: ''양치를 좋아하는 용감한 꼬마''.', title_nl = 'De held van het sprookje 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: de dappere kleine die graag zijn tanden poetst.', title_pl = 'Bohater bajki 🪄', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Dzielny maluch, który uwielbia myć ząbki”.', title_pt = 'O herói da história 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "O pequeno corajoso que adora escovar os dentes".', title_sv = 'Sagans hjälte 🪄', body_sv = 'Skapa i kväll en speciell berättelse i Smarta sagor där ditt eget barn är hjälten: den modiga lilla som älskar att borsta tänderna.', title_vi = 'Nhân vật chính của câu chuyện 🪄', body_vi = 'Tối nay, hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là bé: "Em bé dũng cảm thích đánh răng".', title_zh = '故事的主角 🪄', body_zh = '今晚在智能故事里创作一个以你的孩子为主角的特别故事：一个爱刷牙的勇敢小家伙。' WHERE id = 'c57b31e1-ab4c-412f-95b1-bcfc05812865' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Dedícate tiempo 🛋️', body_es = 'Estás agotada de correr detrás de tu peque. Ya duerme: escribe todo el estrés en el Diario de ánimo y sírvete una taza de infusión de melisa.', title_fr = 'Prenez du temps pour vous 🛋️', body_fr = 'Vous êtes épuisée à force de lui courir après. Il dort : écrivez tout votre stress dans le Journal d''humeur et servez-vous une tasse de tisane de mélisse.', title_hi = 'अपने लिए समय निकालिए 🛋️', body_hi = 'उसके पीछे भागते-भागते आप थककर चूर हो गईं। बच्चा सो गया, अब मूड डायरी में सारा तनाव लिखिए और अपने लिए एक कप लेमन बाम की चाय डालिए।', title_id = 'Luangkan waktu untuk diri Anda 🛋️', body_id = 'Anda kehabisan tenaga karena terus mengejarnya. Si kecil sudah tidur, sekarang tuliskan semua stres di Buku Harian Suasana Hati dan tuang secangkir teh lemon balm untuk diri Anda.', title_ja = '自分のための時間を 🛋️', body_ja = '追いかけ回して、くたくたですね。お子さんが眠ったら、「気分日記」にストレスを全部書き出して、レモンバームティーを一杯いれましょう。', title_ko = '나를 위한 시간을 내세요 🛋️', body_ko = '아이를 쫓아다니느라 기운이 다 빠졌죠. 아이가 잠들었으니 이제 기분 일기에 스트레스를 모두 적고 레몬밤 차 한 잔을 따라 보세요.', title_nl = 'Maak tijd voor jezelf 🛋️', body_nl = 'Je bent uitgeput van het achter hem aan rennen. Hij slaapt: schrijf nu alle stress op in je Stemmingsdagboek en schenk jezelf een kop citroenmelissethee in.', title_pl = 'Znajdź czas dla siebie 🛋️', body_pl = 'Bieganie za maluchem odebrało ci siły. Zasnął, więc teraz wypisz cały stres w Dzienniku nastroju i nalej sobie filiżankę melisy.', title_pt = 'Reserve tempo para si 🛋️', body_pt = 'Ficou sem forças de tanto correr atrás dele. Ele adormeceu: agora escreva todo o stress no Diário de Humor e sirva-se de uma chávena de chá de erva-cidreira.', title_sv = 'Ta tid för dig själv 🛋️', body_sv = 'Du är helt slut efter att ha sprungit efter barnet. Barnet sover, skriv nu av dig all stress i Humördagboken och häll upp en kopp citronmelissate.', title_vi = 'Dành thời gian cho bản thân 🛋️', body_vi = 'Chạy theo bé khiến mẹ kiệt sức. Bé đã ngủ, giờ hãy viết hết căng thẳng vào Nhật ký tâm trạng và rót cho mình một tách trà tía tô đất.', title_zh = '留点时间给自己 🛋️', body_zh = '追着宝宝跑得筋疲力尽了。孩子睡着了，现在把所有压力写进心情日记，给自己倒一杯香蜂草茶吧。' WHERE id = '3dd0cee4-66f4-4904-9285-5b0b7b0dfa7b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hambre o sed? 💧', body_es = 'A veces la sed se confunde con falta de apetito. Revisa las anotaciones del Seguimiento de pañales y asegúrate enseguida de que toma suficiente líquido.', title_fr = 'Faim ou soif ? 💧', body_fr = 'La soif se confond parfois avec un manque d''appétit. Vérifiez les selles et urines notées dans le Suivi des couches pour vous assurer tout de suite qu''il boit assez.', title_hi = 'भूखा है या प्यासा? 💧', body_hi = 'कभी-कभी प्यास को भूख न लगना समझ लिया जाता है। डायपर ट्रैकर की एंट्री देखकर तुरंत पक्का कीजिए कि उसे पर्याप्त तरल मिल रहा है।', title_id = 'Lapar, atau haus? 💧', body_id = 'Terkadang haus disangka tidak nafsu makan. Cek catatan BAK/BAB di Pelacak Popok dan segera pastikan asupan cairannya cukup.', title_ja = 'おなかがすいた？それとものどが渇いた？💧', body_ja = 'のどの渇きが食欲不振とまちがえられることがあります。「おむつトラッカー」のおしっこやうんちの記録を確認して、水分が足りているかすぐに確かめましょう。', title_ko = '배고픈 걸까, 목마른 걸까? 💧', body_ko = '목마름을 입맛이 없는 것으로 착각할 때가 있어요. 기저귀 기록의 배변 기록을 확인해 수분 섭취가 충분한지 바로 확인하세요.', title_nl = 'Honger of dorst? 💧', body_nl = 'Soms wordt dorst verward met geen trek. Controleer de gegevens in de Luiertracker en zorg er meteen voor dat hij genoeg drinkt.', title_pl = 'Głodny czy spragniony? 💧', body_pl = 'Pragnienie czasem myli się z brakiem apetytu. Sprawdź wpisy w narzędziu do śledzenia pieluszek i od razu upewnij się, że pije wystarczająco.', title_pt = 'Tem fome ou sede? 💧', body_pt = 'Às vezes a sede confunde-se com falta de apetite. Veja os registos no Registo de Fraldas e confirme já que está a beber líquidos suficientes.', title_sv = 'Hungrig eller törstig? 💧', body_sv = 'Ibland förväxlas törst med dålig aptit. Kontrollera anteckningarna om avföring i Blöjkollen och se direkt till att vätskeintaget räcker.', title_vi = 'Bé đói hay khát? 💧', body_vi = 'Đôi khi khát nước bị nhầm với biếng ăn. Hãy kiểm tra ghi chép bài tiết trong Theo dõi tã để chắc chắn bé uống đủ nước.', title_zh = '是饿了，还是渴了？💧', body_zh = '有时口渴会被误当成没胃口。查看尿布记录里的排泄记录，马上确认水分摄入是否充足。' WHERE id = '6721af60-2c7e-45f7-a60e-e27511cbb049' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño cantante 🎤', body_es = '¿Canta la misma canción sin parar? Esto refuerza su sentido del ritmo y el desarrollo del lenguaje.', title_fr = 'Petit chanteur 🎤', body_fr = 'Il chante la même chanson en boucle ? Cela soutient son sens du rythme et le développement de son langage.', title_hi = 'नन्हा गायक 🎤', body_hi = 'एक ही गाना बार-बार गाता है? यह लय की समझ और भाषा के विकास में मदद करता है।', title_id = 'Penyanyi cilik 🎤', body_id = 'Menyanyikan lagu yang sama tanpa henti? Ini mendukung rasa ritme dan perkembangan bahasanya.', title_ja = '小さな歌手 🎤', body_ja = '同じ歌を何度も何度も歌っていますか？これはリズム感と言葉の発達を育てます。', title_ko = '꼬마 가수 🎤', body_ko = '같은 노래를 쉬지 않고 부르나요? 리듬감과 언어 발달에 도움이 돼요.', title_nl = 'Kleine zanger 🎤', body_nl = 'Zingt hij steeds maar hetzelfde liedje? Dat steunt zijn gevoel voor ritme en zijn taalontwikkeling.', title_pl = 'Mały piosenkarz 🎤', body_pl = 'Śpiewa w kółko tę samą piosenkę? To wspiera jego poczucie rytmu i rozwój mowy.', title_pt = 'Pequeno cantor 🎤', body_pt = 'Canta a mesma canção sem parar? Isso apoia o sentido de ritmo e o desenvolvimento da linguagem.', title_sv = 'Liten sångare 🎤', body_sv = 'Sjunger barnet samma sång om och om igen? Det stöttar rytmkänslan och språkutvecklingen.', title_vi = 'Ca sĩ nhí 🎤', body_vi = 'Bé hát đi hát lại một bài không ngừng? Điều này giúp phát triển cảm nhận nhịp điệu và ngôn ngữ.', title_zh = '小小歌手 🎤', body_zh = '一直唱同一首歌？这能促进节奏感和语言发展。' WHERE id = 'be975b82-781b-4e9e-b454-14728754957f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por los libros 📖', body_es = '¿Te trae su libro de cuentos favorito y se sienta en tu regazo? Su capacidad de atención está creciendo. Leed juntos y nombra lo que aparece en los dibujos.', title_fr = 'L''amour des livres 📖', body_fr = 'Il apporte son livre de contes préféré et s''installe sur vos genoux ? Sa capacité d''attention s''allonge. Lisez ensemble et nommez ce qu''il y a sur les images.', title_hi = 'किताबों से प्यार 📖', body_hi = 'अपनी सबसे पसंदीदा कहानी की किताब लाकर आपकी गोद में बैठ जाता है? उसका ध्यान देर तक टिकने लगा है। उसके साथ पढ़िए और तस्वीरों में दिख रही चीज़ों के नाम बताइए।', title_id = 'Cinta pada buku 📖', body_id = 'Ia membawa buku dongeng favoritnya dan duduk di pangkuan Anda? Rentang perhatiannya makin panjang. Bacalah bersama dan sebutkan nama benda di gambarnya.', title_ja = '絵本が大好き 📖', body_ja = 'お気に入りの絵本を持ってきて、ひざに座りますか？集中できる時間が長くなっています。一緒に読んで、絵に描かれたものの名前を言ってあげましょう。', title_ko = '책을 사랑하는 마음 📖', body_ko = '가장 좋아하는 동화책을 들고 와 무릎에 앉나요? 집중하는 시간이 길어지고 있어요. 함께 읽으며 그림 속 사물의 이름을 말해 주세요.', title_nl = 'Liefde voor boeken 📖', body_nl = 'Haalt hij zijn lievelingsboek en kruipt hij bij je op schoot? Zijn concentratie wordt langer. Lees samen en benoem wat er op de plaatjes staat.', title_pl = 'Miłość do książek 📖', body_pl = 'Przynosi ulubioną książeczkę z bajkami i siada ci na kolanach? Jego uwaga staje się dłuższa. Czytajcie razem i nazywajcie to, co na obrazkach.', title_pt = 'O gosto pelos livros 📖', body_pt = 'Traz o seu livro de histórias preferido e senta-se ao seu colo? A capacidade de atenção está a aumentar. Leiam juntos e diga o nome do que aparece nas imagens.', title_sv = 'Kärlek till böcker 📖', body_sv = 'Hämtar barnet sin favoritsagobok och sätter sig i ditt knä? Koncentrationen blir längre. Läs tillsammans och benämn det som finns på bilderna.', title_vi = 'Yêu sách 📖', body_vi = 'Bé mang cuốn truyện yêu thích đến và ngồi vào lòng mẹ? Khả năng tập trung của bé đang dài hơn. Hãy cùng bé đọc và gọi tên những gì trong tranh.', title_zh = '爱上书本 📖', body_zh = '拿来最爱的故事书，坐到你怀里？专注的时间变长了。和宝宝一起读，说出图画里的东西叫什么。' WHERE id = '5266953d-d239-48ef-aac1-e6e5bcca5cbf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Empiezan los miedos? 👻', body_es = '¿Ahora le da miedo la aspiradora, que antes no le asustaba? A medida que se desarrolla la imaginación aparecen miedos sin motivo. Abrázale y dile que está a salvo.', title_fr = 'Les peurs commencent ? 👻', body_fr = 'Il a peur de l''aspirateur alors qu''avant non ? Avec l''imagination qui se développe, des peurs injustifiées apparaissent. Serrez-le dans vos bras et dites-lui qu''il est en sécurité.', title_hi = 'डर शुरू हो रहे हैं? 👻', body_hi = 'जिस वैक्यूम क्लीनर से पहले नहीं डरता था, अब उससे डरता है? कल्पना बढ़ने के साथ बेवजह के डर पैदा होते हैं। उसे गले लगाइए और बताइए कि वह सुरक्षित है।', title_id = 'Mulai muncul rasa takut? 👻', body_id = 'Sekarang takut pada penyedot debu yang dulu tidak ia takuti? Seiring berkembangnya imajinasi, muncul rasa takut yang tak beralasan. Peluk ia dan katakan bahwa ia aman.', title_ja = 'こわいものが出てきた？👻', body_ja = '前は平気だった掃除機を、今はこわがりますか？想像力が育つにつれて、理由のないこわさが生まれます。ぎゅっと抱きしめて、安全だよと伝えましょう。', title_ko = '무서움이 생겼나요? 👻', body_ko = '전에는 무서워하지 않던 청소기를 이제 무서워하나요? 상상력이 자라면서 이유 없는 두려움도 생겨요. 꼭 안아 주고 안전하다고 말해 주세요.', title_nl = 'Beginnen de angsten? 👻', body_nl = 'Is hij nu bang voor de stofzuiger, terwijl hij dat eerst niet was? Naarmate zijn fantasie groeit, ontstaan onterechte angsten. Knuffel hem en zeg dat hij veilig is.', title_pl = 'Zaczynają się lęki? 👻', body_pl = 'Teraz boi się odkurzacza, którego wcześniej się nie bał? Wraz z rozwojem wyobraźni pojawiają się nieuzasadnione lęki. Przytul go i powiedz, że jest bezpieczny.', title_pt = 'Começam os medos? 👻', body_pt = 'Agora tem medo do aspirador, de que antes não tinha? À medida que a imaginação se desenvolve, surgem medos sem razão. Abrace-o e diga-lhe que está seguro.', title_sv = 'Rädslor börjar? 👻', body_sv = 'Är barnet nu rädd för dammsugaren som det inte var rädd för tidigare? När fantasin utvecklas uppstår obefogade rädslor. Krama barnet och säg att hen är trygg.', title_vi = 'Nỗi sợ bắt đầu? 👻', body_vi = 'Trước đây không sợ, giờ bé lại sợ máy hút bụi? Khi trí tưởng tượng phát triển, những nỗi sợ vô cớ sẽ xuất hiện. Hãy ôm bé và nói rằng bé đang được an toàn.', title_zh = '开始害怕了？👻', body_zh = '以前不怕的吸尘器，现在却怕了？随着想象力发展，会出现一些莫名的恐惧。抱抱宝宝，告诉宝宝很安全。' WHERE id = 'b3334b05-05eb-4d1a-9a1b-b94086c6493b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Necesidad de aire fresco 🌳', body_es = '¿Está muy inquieto y no para en casa? Consulta Tiempo y ropa y salid enseguida al parque. La naturaleza es su calmante más rápido.', title_fr = 'Besoin de grand air 🌳', body_fr = 'Il est très agité et ne tient pas en place à la maison ? Vérifiez Météo et tenue et filez au parc. La nature est son calmant le plus rapide.', title_hi = 'ताज़ी हवा की ज़रूरत 🌳', body_hi = 'बच्चा बहुत बेचैन है और घर में टिकता नहीं? मौसम और कपड़े देखिए और तुरंत पार्क की ओर निकलिए। प्रकृति उसके लिए सबसे तेज़ सुकून देने वाली है।', title_id = 'Butuh udara segar 🌳', body_id = 'Si kecil sangat gelisah dan tidak betah di rumah? Cek cuaca dan pakaian, lalu langsung ke taman. Alam adalah penenang tercepat baginya.', title_ja = '新鮮な空気が必要 🌳', body_ja = '落ち着かなくて、家の中にじっとしていられない？「天気と服装」をチェックして、すぐに公園へ出かけましょう。自然はお子さんにとって、いちばん早く心を落ち着かせてくれるものです。', title_ko = '맑은 공기가 필요해요 🌳', body_ko = '아이가 너무 안절부절못하고 집에 있으려 하지 않나요? 날씨와 옷차림을 확인하고 바로 공원으로 가 보세요. 자연은 아이를 가장 빨리 진정시켜 줘요.', title_nl = 'Behoefte aan frisse lucht 🌳', body_nl = 'Is je kindje erg onrustig en wil hij niet binnen blijven? Check het weer en de kleding en ga meteen naar het park. De natuur kalmeert hem het snelst.', title_pl = 'Potrzeba świeżego powietrza 🌳', body_pl = 'Maluch jest bardzo niespokojny i nie może usiedzieć w domu? Sprawdź Pogodę i ubiór i od razu ruszajcie do parku. Natura to dla niego najszybszy sposób na wyciszenie.', title_pt = 'Precisa de ar puro 🌳', body_pt = 'Está muito inquieto e não para em casa? Veja o Tempo e Roupa e siga já para o parque. A natureza é para ele o calmante mais rápido.', title_sv = 'Behov av frisk luft 🌳', body_sv = 'Är barnet väldigt rastlöst och vill inte vara inne? Kolla Väder och kläder och gå direkt till parken. Naturen är det snabbaste sättet att lugna barnet.', title_vi = 'Cần không khí trong lành 🌳', body_vi = 'Bé bồn chồn và không chịu ở trong nhà? Hãy xem Thời tiết và trang phục rồi ra công viên ngay. Thiên nhiên là liều thuốc xoa dịu nhanh nhất cho bé.', title_zh = '需要新鲜空气 🌳', body_zh = '孩子很烦躁，在家待不住？看看天气与穿衣，马上去公园。大自然是让宝宝最快平静下来的良方。' WHERE id = 'c2a4b3f4-3db4-4b1d-a807-2effcd0ace08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas a tus amigas 👯‍♀️', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás centros con grupos de juego, socializa con otras madres y comparte experiencias.', title_fr = 'Vous aussi, vous avez besoin d''amies 👯‍♀️', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez des centres avec groupes de jeu dans les Lieux adaptés aux mamans, rencontrez d''autres mamans et partagez vos expériences.', title_hi = 'आपको भी दोस्तों की ज़रूरत है 👯‍♀️', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में प्ले ग्रुप वाले सेंटर ढूँढिए, दूसरी माँओं से मिलिए और अनुभव बाँटिए।', title_id = 'Anda juga butuh teman 👯‍♀️', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan tempat dengan kelompok bermain di Tempat Ramah Ibu, bersosialisasi dengan ibu lain, dan berbagi pengalaman.', title_ja = 'あなたにも友だちが必要です 👯‍♀️', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」で遊びのグループがある施設を見つけて、ほかのママと交流し、経験を分かち合いましょう。', title_ko = '엄마에게도 친구가 필요해요 👯‍♀️', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 놀이 모임이 있는 센터를 찾아 다른 엄마들과 어울리고 경험을 나눠 보세요.', title_nl = 'Jij hebt ook vriendinnen nodig 👯‍♀️', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken centra met speelgroepjes, maak contact met andere moeders en deel ervaringen.', title_pl = 'Ty też potrzebujesz przyjaciółek 👯‍♀️', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom centra z grupami zabaw, poznaj inne mamy i wymieniajcie się doświadczeniami.', title_pt = 'Também precisa de amigas 👯‍♀️', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães centros com grupos de brincadeira, conviva com outras mães e partilhe experiências.', title_sv = 'Du behöver också vänner 👯‍♀️', body_sv = 'Trött på att bara prata med barnet? Hitta center med lekgrupper i Mammavänliga platser, umgås med andra mammor och dela erfarenheter.', title_vi = 'Mẹ cũng cần bạn bè 👯‍♀️', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm các trung tâm có nhóm chơi trong Địa điểm thân thiện với mẹ để giao lưu và chia sẻ kinh nghiệm với các mẹ khác.', title_zh = '你也需要朋友 👯‍♀️', body_zh = '只和孩子说话说累了？在妈妈友好场所里找到有游戏小组的中心，和其他妈妈交流、分享经验吧。' WHERE id = '387df56f-151e-4857-83aa-f757db180cee' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ayudante de limpieza 🧹', body_es = 'Ya quiere participar en las tareas de casa. Lee en el Blog cómo inculcar el sentido de la responsabilidad jugando a un niño de casi 2 años y ponlo en práctica.', title_fr = 'Petit assistant ménage 🧹', body_fr = 'Il veut déjà participer aux tâches ménagères. Lisez dans la rubrique Blogs comment transmettre le sens des responsabilités par le jeu à un enfant de presque 2 ans, et essayez.', title_hi = 'सफ़ाई का मददगार 🧹', body_hi = 'वह अब घर के कामों में हाथ बँटाना चाहता है। ब्लॉग सेक्शन में पढ़िए कि लगभग 2 साल के बच्चे में खेल-खेल में ज़िम्मेदारी की भावना कैसे जगाएँ, और आज़माइए।', title_id = 'Asisten bersih-bersih 🧹', body_id = 'Ia sudah ingin ikut mengerjakan pekerjaan rumah. Baca dan praktikkan di bagian Blog cara menanamkan rasa tanggung jawab lewat permainan pada anak yang hampir berusia 2 tahun.', title_ja = 'お掃除のお手伝いさん 🧹', body_ja = 'もう家事に参加したがっています。2歳ごろの子に、遊びを通して責任感を育てる方法をブログで読んで、試してみましょう。', title_ko = '청소 도우미 🧹', body_ko = '벌써 집안일을 돕고 싶어 해요. 두 돌 무렵 아이에게 놀이로 책임감을 길러 주는 방법을 블로그에서 읽고 해 보세요.', title_nl = 'Hulpje bij het schoonmaken 🧹', body_nl = 'Hij wil al meehelpen in huis. Lees in Blogs hoe je een kind van bijna 2 jaar spelenderwijs verantwoordelijkheid leert, en probeer het uit.', title_pl = 'Mały pomocnik w sprzątaniu 🧹', body_pl = 'Już chce pomagać w domowych obowiązkach. Przeczytaj w sekcji Blog, jak poprzez zabawę zaszczepić prawie 2-letniemu dziecku poczucie odpowiedzialności, i wypróbuj to.', title_pt = 'Ajudante das limpezas 🧹', body_pt = 'Já quer participar nas tarefas da casa. Leia nos Blogues como incutir, a brincar, o sentido de responsabilidade numa criança de quase 2 anos e ponha-o em prática.', title_sv = 'Städhjälpen 🧹', body_sv = 'Barnet vill redan vara med i hushållssysslorna. Läs i Bloggar hur du med lek väcker ansvarskänsla hos ett barn på ungefär 2 år och prova.', title_vi = 'Trợ thủ dọn dẹp 🧹', body_vi = 'Bé đã muốn tham gia việc nhà. Hãy đọc trong mục Blog cách nuôi dưỡng tinh thần trách nhiệm qua trò chơi cho trẻ khoảng 2 tuổi và áp dụng nhé.', title_zh = '打扫小帮手 🧹', body_zh = '宝宝已经想参与家务了。去博客板块读读如何通过游戏培养2岁左右宝宝的责任感，一起试试吧。' WHERE id = 'c13703f6-090d-418f-ba78-30e2aa25d678' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Siéntete orgullosa de ti! 🌟', body_es = 'Cada nueva habilidad que aprende y cada paso seguro que da son fruto de tu esfuerzo. ¡Abre el Diario de ánimo y escribe hoy una nota de la que sentirte orgullosa!', title_fr = 'Soyez fière de vous ! 🌟', body_fr = 'Chaque nouvelle compétence, chaque pas assuré, c''est grâce à vous. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note dont vous serez fière !', title_hi = 'खुद पर गर्व कीजिए! 🌟', body_hi = 'हर दिन सीखी नई चीज़, हर भरोसे भरा कदम आपकी मेहनत है। मूड डायरी खोलिए और आज खुद पर गर्व करने वाली एक बात लिखिए!', title_id = 'Banggalah pada diri sendiri! 🌟', body_id = 'Setiap keterampilan baru dan setiap langkah percaya dirinya adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati dan tulis catatan membanggakan tentang diri Anda hari ini!', title_ja = '自分を誇りに思って！🌟', body_ja = '毎日新しくできるようになること、自信に満ちた一歩一歩は、あなたのがんばりのおかげです。「気分日記」を開いて、今日の自分を誇りに思えるメモを書きましょう！', title_ko = '스스로를 자랑스러워하세요! 🌟', body_ko = '매일 배우는 새로운 능력, 자신 있는 한 걸음 한 걸음이 모두 엄마의 노력이에요. 기분 일기를 열고 오늘 나를 자랑스러워할 뿌듯한 기록을 남겨 보세요!', title_nl = 'Wees trots op jezelf! 🌟', body_nl = 'Elke nieuwe vaardigheid en elk zelfverzekerd stapje is dankzij jou. Open je Stemmingsdagboek en schrijf vandaag een trotse notitie over jezelf!', title_pl = 'Bądź z siebie dumna! 🌟', body_pl = 'Każda nowa umiejętność, każdy pewny krok to twoja zasługa. Otwórz Dziennik nastroju i napisz dziś notatkę, z której będziesz naprawdę dumna!', title_pt = 'Orgulhe-se de si! 🌟', body_pt = 'Cada nova competência que aprende e cada passo confiante são fruto do seu esforço. Abra o Diário de Humor e escreva hoje uma nota que a encha de orgulho em si!', title_sv = 'Var stolt över dig själv! 🌟', body_sv = 'Varje ny färdighet barnet lär sig och varje säkert steg är tack vare ditt arbete. Öppna Humördagboken och skriv en anteckning i dag som gör dig riktigt stolt över dig själv!', title_vi = 'Hãy tự hào về bản thân! 🌟', body_vi = 'Mỗi kỹ năng mới, mỗi bước đi tự tin của bé đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng đáng tự hào về bản thân hôm nay!', title_zh = '为自己骄傲吧！🌟', body_zh = '宝宝每天学会的新本领、迈出的每一个自信的脚步，都有你的功劳。打开心情日记，写下一句让你为自己骄傲的话吧！' WHERE id = 'c6d0e6b3-90f7-4c66-9fd0-1f47e6d714c9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pegar o empujar 🦖', body_es = '¿Levanta la mano o empuja a sus amigos de repente cuando se enfada? Aprende con Anacan AI a cambiar con suavidad las emociones agresivas propias de esta edad.', title_fr = 'Taper ou pousser 🦖', body_fr = 'Quand il se fâche, il lève soudain la main ou pousse ses copains ? Découvrez avec Anacan AI comment faire évoluer en douceur les émotions agressives de cet âge.', title_hi = 'मारना या धक्का देना 🦖', body_hi = 'गुस्से में अचानक हाथ उठाता है या दोस्तों को धक्का देता है? इस उम्र की तेज़ होती भावनाओं को नरमी से कैसे बदलें, यह Anacan AI से जानिए।', title_id = 'Memukul atau mendorong 🦖', body_id = 'Tiba-tiba mengangkat tangan atau mendorong temannya saat marah? Pelajari dari Anacan AI cara mengubah emosi agresif khas usia ini dengan lembut.', title_ja = 'たたく、押す 🦖', body_ja = '怒ると急に手が出たり、お友だちを押したりしますか？この年齢の激しくなる気持ちを、やさしく変えていく方法をAnacan AIで学びましょう。', title_ko = '때리거나 밀 때 🦖', body_ko = '화가 나면 갑자기 손을 들거나 친구를 미나요? 이 나이의 거칠어지는 감정을 부드럽게 바꿔 주는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Slaan of duwen 🦖', body_nl = 'Haalt hij ineens uit of duwt hij vriendjes als hij boos is? Leer bij Anacan AI hoe je de heftige emoties van deze leeftijd zacht verandert.', title_pl = 'Bicie albo popychanie 🦖', body_pl = 'Gdy się złości, nagle podnosi rękę albo popycha kolegów? Dowiedz się od Anacan AI, jak łagodnie zmienić agresywne emocje typowe dla tego wieku.', title_pt = 'Bater ou empurrar 🦖', body_pt = 'Quando se zanga, levanta a mão de repente ou empurra os amigos? Aprenda com o Anacan AI a mudar com suavidade estas emoções agressivas típicas da idade.', title_sv = 'Slår eller knuffar 🦖', body_sv = 'Lyfter barnet plötsligt handen eller knuffar sina kompisar när hen blir arg? Lär dig av Anacan AI hur du varsamt kan förändra den här ålderns allt starkare känslor.', title_vi = 'Đánh hoặc xô đẩy 🦖', body_vi = 'Bé bất ngờ vung tay hoặc xô bạn khi tức giận? Hãy học từ Anacan AI cách nhẹ nhàng thay đổi những cảm xúc ngày càng mạnh mẽ của lứa tuổi này.', title_zh = '打人或推人 🦖', body_zh = '一生气就突然动手或推小朋友？向Anacan AI了解如何温和地改变这个年龄越来越激烈的情绪。' WHERE id = 'addb392c-deee-4dda-99c7-ed94d64cd987' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los huesos se fortalecen 🦴', body_es = 'Un desarrollo tan rápido necesita calcio. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de queso y yogur y completa lo que falte.', title_fr = 'Des os plus solides 🦴', body_fr = 'Une croissance rapide demande du calcium. Vérifiez avec le Suivi des repas qu''il a eu sa ration de fromage et de yaourt aujourd''hui et comblez les manques.', title_hi = 'हड्डियाँ मज़बूत हो रही हैं 🦴', body_hi = 'तेज़ विकास के लिए कैल्शियम चाहिए। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज पनीर और दही की मात्रा पूरी हुई, और कमी पूरी कीजिए।', title_id = 'Tulang makin kuat 🦴', body_id = 'Pertumbuhan yang pesat butuh kalsium. Pastikan dengan alat Pemantau Nutrisi bahwa porsi keju dan yogurt hari ini terpenuhi, dan lengkapi kekurangannya.', title_ja = '骨が強くなる 🦴', body_ja = '急速な成長にはカルシウムが必要です。「栄養管理ツール」で今日のチーズやヨーグルトの目安量をとれたか確認して、足りない分を補いましょう。', title_ko = '뼈가 튼튼해져요 🦴', body_ko = '빠른 성장에는 칼슘이 필요해요. 수유 기록 도구로 오늘 치즈와 요거트 기준량을 채웠는지 확인하고 부족한 만큼 채워 주세요.', title_nl = 'Sterkere botten 🦴', body_nl = 'Snelle groei vraagt om calcium. Check met de Voedingstracker of hij vandaag genoeg kaas en yoghurt heeft gehad en vul tekorten aan.', title_pl = 'Kości stają się mocniejsze 🦴', body_pl = 'Szybki rozwój wymaga wapnia. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja sera i jogurtu została osiągnięta, i uzupełnij braki.', title_pt = 'Os ossos ficam mais fortes 🦴', body_pt = 'Um desenvolvimento rápido exige cálcio. Confirme com o Registo de Alimentação que hoje cumpriu a dose de queijo e iogurte e complete o que faltar.', title_sv = 'Skelettet blir starkare 🦴', body_sv = 'Snabb utveckling kräver kalcium. Kontrollera med Matningskoll att barnet fått dagens norm av ost och yoghurt och fyll på det som fattas.', title_vi = 'Xương chắc khỏe hơn 🦴', body_vi = 'Phát triển nhanh cần nhiều canxi. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức phô mai, sữa chua chưa và bổ sung phần thiếu.', title_zh = '骨骼越来越强壮 🦴', body_zh = '快速发育需要钙。用喂养记录工具确认今天奶酪、酸奶的参考量是否达到，补上不足的部分。' WHERE id = 'ebc52a7e-1091-4bf2-89de-cc6e528ddbe1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso? El temporizador se ha parado. Olvida las tareas de casa, pon el murmullo del río de Ruido blanco y túmbate en el sofá a descansar.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée très bruyante ? Le minuteur est arrêté. Oubliez les tâches ménagères, lancez le murmure de la rivière des Bruits blancs et allongez-vous sur le canapé pour vous reposer.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत शोर भरा दिन था? टाइमर रुक गया। घर के काम भूल जाइए, व्हाइट नॉइज़ में नदी की कलकल चलाइए और आराम के लिए सोफ़े पर लेट जाइए।', title_id = 'Penenang alami 🍃', body_id = 'Hari yang sangat bising? Timer sudah berhenti. Lupakan pekerjaan rumah, putar suara gemericik sungai dari Suara Putih, dan berbaringlah di sofa untuk beristirahat.', title_ja = '自然のリラックス効果 🍃', body_ja = 'にぎやかな一日でしたか？タイマーは止まりました。家事は忘れて、「ホワイトノイズ」の小川のせせらぎを流し、ソファに横になって休みましょう。', title_ko = '자연의 진정제 🍃', body_ko = '정말 시끄러운 하루였나요? 타이머가 멈췄어요. 집안일은 잊고, 백색소음에서 시냇물 소리를 틀어 소파에 누워 쉬세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een lawaaierige dag? De timer is gestopt. Vergeet het huishouden, zet het kabbelen van een beekje uit Witte ruis aan en ga op de bank liggen om uit te rusten.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był bardzo głośny dzień? Timer zatrzymany. Zapomnij o obowiązkach, włącz szum strumienia z Białego szumu i połóż się na kanapie, by odpocząć.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia muito barulhento? O temporizador parou. Esqueça as tarefas da casa, ligue o murmúrio do rio do Ruído Branco e deite-se no sofá a descansar.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit väldigt bullrig? Timern har stannat. Glöm hushållssysslorna, sätt på bäckens porlande från Vitt brus och lägg dig på soffan och vila.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Một ngày quá ồn ào? Hẹn giờ đã dừng. Quên việc nhà đi, hãy bật tiếng suối chảy trong Tiếng ồn trắng và nằm dài trên sofa nghỉ ngơi.', title_zh = '天然的镇静剂 🍃', body_zh = '今天特别吵闹？计时器停了。忘掉家务，打开白噪音里的溪流声，躺到沙发上休息吧。' WHERE id = 'ee59618a-2d83-4249-b1e6-0323265cd134' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libros para leer, no para romper 📖', body_es = '¿Arranca las páginas a la hora del cuento? Lee ya en el Blog cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'Lire les livres, pas les déchirer 📖', body_fr = 'Il déchire les pages à l''heure du conte du soir ? Lisez tout de suite dans la rubrique Blogs comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'किताब फाड़ना नहीं, पढ़ना 📖', body_hi = 'शाम को कहानी के समय पन्ने फाड़ देता है? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह तुरंत ब्लॉग सेक्शन में पढ़िए।', title_id = 'Membaca buku, bukan merobeknya 📖', body_id = 'Merobek halaman saat waktu dongeng malam? Segera baca di bagian Blog cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = '絵本は破らずに読もう 📖', body_ja = '夜の読み聞かせの時間にページを破ってしまいますか？読書の習慣を損なわずにこの問題に対応する方法を、すぐにブログで読んでみましょう。', title_ko = '찢지 말고 읽어요 📖', body_ko = '잠자리 동화 시간에 책장을 찢나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 블로그에서 바로 읽어 보세요.', title_nl = 'Boeken lezen, niet scheuren 📖', body_nl = 'Scheurt hij bij het avondverhaal de bladzijden kapot? Lees meteen in Blogs hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Nie drzemy książek, tylko czytamy 📖', body_pl = 'Podczas wieczornej bajki drze strony? Od razu przeczytaj w sekcji Blog, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'Ler, não rasgar 📖', body_pt = 'Na hora da história da noite, rasga as páginas? Leia já nos Blogues como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Läsa böcker, inte riva sönder dem 📖', body_sv = 'River barnet sönder sidorna vid kvällssagan? Läs direkt i Bloggar hur du löser problemet utan att skada läsvanan.', title_vi = 'Đọc sách, không xé sách 📖', body_vi = 'Đến giờ kể chuyện buổi tối là bé xé trang sách? Hãy đọc ngay trong mục Blog cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '不撕书，读书 📖', body_zh = '晚上讲故事时把书页撕碎？马上去博客板块读读，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = '5557465c-fb11-48b9-90c2-fc336972f19c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El espectáculo sin fin en la cama 🛌', body_es = '¿En lugar de dormir, salta en la cama? Pon el temporizador de sueño y sigue el gráfico. Analiza si no ha gastado toda su energía o si está demasiado cansado.', title_fr = 'Le show sans fin au lit 🛌', body_fr = 'Il saute sur le lit au lieu de dormir ? Lancez le minuteur de sommeil et suivez le graphique. Analysez s''il ne s''est pas assez dépensé ou s''il est trop fatigué.', title_hi = 'बिस्तर पर कभी न खत्म होने वाला शो 🛌', body_hi = 'सोने के बजाय बिस्तर पर कूदता है? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। समझिए कि उसकी ऊर्जा पूरी नहीं निकली या वह ज़रूरत से ज़्यादा थक गया है।', title_id = 'Pertunjukan tanpa akhir di tempat tidur 🛌', body_id = 'Bukannya tidur, malah melompat-lompat di kasur? Nyalakan Timer Tidur dan pantau grafiknya. Analisis apakah energinya belum tersalurkan atau ia justru terlalu lelah.', title_ja = 'ベッドの上のエンドレスショー 🛌', body_ja = '寝る代わりにベッドの上でジャンプしていますか？睡眠タイマーをオンにして、グラフを見守りましょう。エネルギーを発散しきれていないのか、疲れすぎているのか分析しましょう。', title_ko = '침대 위 끝없는 공연 🛌', body_ko = '자는 대신 침대에서 뛰나요? 수면 타이머를 켜고 그래프를 살펴보세요. 에너지를 다 쓰지 못한 건지, 너무 피곤한 건지 분석해 보세요.', title_nl = 'De eindeloze show in bed 🛌', body_nl = 'Springt hij op bed in plaats van te slapen? Zet de Slaaptimer aan en volg de grafiek. Analyseer of hij zijn energie nog niet kwijt is of juist oververmoeid is.', title_pl = 'Niekończący się show w łóżku 🛌', body_pl = 'Zamiast spać, skacze po łóżku? Włącz timer snu i śledź wykres. Sprawdź, czy nie rozładował całej energii, czy raczej jest przemęczony.', title_pt = 'O espetáculo sem fim na cama 🛌', body_pt = 'Em vez de dormir, salta na cama? Ligue o temporizador de sono e acompanhe o gráfico. Analise se ainda não gastou toda a energia ou se está cansado demais.', title_sv = 'Showen i sängen som aldrig tar slut 🛌', body_sv = 'Hoppar barnet i sängen i stället för att sova? Starta sömntimern och följ grafen. Analysera om barnet inte fått ut all energi eller är övertrött.', title_vi = 'Màn trình diễn bất tận trên giường 🛌', body_vi = 'Bé nhảy trên giường thay vì ngủ? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Phân tích xem bé chưa xả hết năng lượng hay đã quá mệt.', title_zh = '床上停不下来的表演 🛌', body_zh = '不睡觉，在床上蹦来蹦去？打开睡眠计时器，看看图表。分析一下是精力没释放完，还是太累了。' WHERE id = '5b487ba9-a209-4653-a8fe-4315e87398df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de lavarse los dientes 🪥', body_es = '¿Cierra la boca en cuanto ve el cepillo? Mira en Productos recomendados cepillos musicales o de dedo y descubre cómo convertir esta rutina tan importante en un juego divertido.', title_fr = 'La bataille du brossage de dents 🪥', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse ? Regardez dans les Produits recommandés les brosses musicales ou à doigt et transformez ce rituel essentiel en jeu amusant.', title_hi = 'दाँत ब्रश करने की लड़ाई 🪥', body_hi = 'ब्रश देखते ही मुँह बंद कर लेता है? सुझाए गए प्रोडक्ट में म्यूज़िकल या फ़िंगर ब्रश देखिए और इस ज़रूरी रूटीन को मज़ेदार खेल बनाने का तरीका जानिए।', title_id = 'Drama sikat gigi 🪥', body_id = 'Langsung mengatupkan mulut begitu melihat sikat gigi? Lihat sikat gigi bermusik atau sikat jari di Produk Rekomendasi dan jadikan rutinitas penting ini permainan seru.', title_ja = '歯みがきバトル 🪥', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？「おすすめ商品」で音楽付きや指にはめるタイプの歯ブラシをチェックして、この大切な習慣を楽しい遊びに変えましょう。', title_ko = '양치 전쟁 🪥', body_ko = '칫솔만 보면 입을 꾹 다무나요? 추천 제품에서 음악이 나오는 칫솔이나 손가락 칫솔을 살펴보고 이 중요한 습관을 재미있는 놀이로 바꿔 보세요.', title_nl = 'Gedoe met tandenpoetsen 🪥', body_nl = 'Klemt hij zijn mond dicht zodra hij de tandenborstel ziet? Ontdek in Aanbevolen producten muzikale of vingertandenborstels en maak van deze belangrijke routine een leuk spel.', title_pl = 'Bitwa o mycie ząbków 🪥', body_pl = 'Zaciska buzię na widok szczoteczki? Zajrzyj w Polecanych produktach do grających szczoteczek lub szczoteczek na palec i odkryj, jak zamienić tę ważną rutynę w zabawę.', title_pt = 'A luta da escova de dentes 🪥', body_pt = 'Mal vê a escova, fecha a boca? Veja nos Produtos Recomendados escovas musicais ou de dedo e descubra como transformar esta rotina tão importante num jogo divertido.', title_sv = 'Kampen om tandborstningen 🪥', body_sv = 'Stänger barnet munnen så fort tandborsten syns? Upptäck tandborstar med musik eller fingertandborstar i Rekommenderade produkter och gör den viktiga rutinen till en rolig lek.', title_vi = 'Cuộc chiến đánh răng 🪥', body_vi = 'Vừa thấy bàn chải là bé mím chặt miệng? Hãy xem các loại bàn chải có nhạc hoặc bàn chải xỏ ngón trong Sản phẩm gợi ý để biến thói quen quan trọng này thành trò chơi vui nhộn.', title_zh = '刷牙大作战 🪥', body_zh = '一看到牙刷就紧闭小嘴？去推荐商品看看音乐牙刷或指套牙刷，发现如何把这项重要的日常习惯变成有趣的游戏。' WHERE id = '9fb4af87-300a-4df0-8f02-48703cd4da3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La imaginación no tiene límites 🧸', body_es = '¿Le da de comer a su osito o te cura a ti? Mira en Productos recomendados juegos de médico o de cocinita que apoyan este maravilloso desarrollo de la empatía.', title_fr = 'Une imagination sans limites 🧸', body_fr = 'Il donne à manger à son nounours ou vous soigne ? Regardez dans les Produits recommandés les kits de docteur ou de cuisine qui soutiennent cette belle empathie naissante.', title_hi = 'कल्पना की कोई सीमा नहीं 🧸', body_hi = 'अपने भालू को खाना खिलाता है या आपका इलाज करता है? हमदर्दी के इस शानदार विकास में मदद करने वाले डॉक्टर या किचन सेट के लिए सुझाए गए प्रोडक्ट देखिए।', title_id = 'Imajinasi tanpa batas 🧸', body_id = 'Ia menyuapi boneka beruangnya, atau mengobati Anda? Lihat set mainan dokter atau dapur yang mendukung perkembangan empati yang luar biasa ini di Produk Rekomendasi.', title_ja = '想像力に限界はない 🧸', body_ja = 'くまさんにごはんを食べさせたり、あなたを手当てしてくれたり？このすばらしい思いやりの発達を応援する、お医者さんセットやキッチンセットを「おすすめ商品」でチェックしましょう。', title_ko = '상상력에는 끝이 없어요 🧸', body_ko = '곰 인형에게 밥을 먹이거나 엄마를 치료해 주나요? 이 멋진 공감 능력의 발달을 돕는 병원 놀이나 주방 놀이 세트를 추천 제품에서 살펴보세요.', title_nl = 'Fantasie kent geen grenzen 🧸', body_nl = 'Geeft hij zijn beer te eten of verzorgt hij jou? Bekijk in Aanbevolen producten dokters- of keukensets die deze geweldige empathie steunen.', title_pl = 'Wyobraźnia nie zna granic 🧸', body_pl = 'Karmi misia albo cię „leczy”? Zajrzyj do Polecanych produktów po zestawy lekarza lub kuchenki, które wspierają ten wspaniały rozwój empatii.', title_pt = 'A imaginação não tem limites 🧸', body_pt = 'Dá de comer ao ursinho ou faz de conta que a trata? Veja nos Produtos Recomendados kits de médico ou de cozinha que apoiam este desenvolvimento fantástico da empatia.', title_sv = 'Fantasin har inga gränser 🧸', body_sv = 'Matar barnet nallen eller låtsas behandla dig? Titta på doktors- eller köksset som stöttar denna fantastiska empatiutveckling i Rekommenderade produkter.', title_vi = 'Trí tưởng tượng không có giới hạn 🧸', body_vi = 'Bé đút cho gấu bông ăn hay "chữa bệnh" cho mẹ? Hãy xem bộ đồ chơi bác sĩ hoặc nhà bếp trong Sản phẩm gợi ý để hỗ trợ sự phát triển lòng đồng cảm tuyệt vời này.', title_zh = '想象力没有边界 🧸', body_zh = '给小熊喂饭，或者给你“看病”？去推荐商品看看能支持这种了不起的共情发展的医生或厨房玩具套装。' WHERE id = '12f1dbe9-33ce-4aad-aead-7be2d360eb1e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelve el miedo a la separación? 🌌', body_es = '¿Llora en cuanto sales de la habitación? Pon el sonido del latido del corazón de Ruido blanco, dale sensación de seguridad y prepárale para dormir.', title_fr = 'La peur de la séparation revient ? 🌌', body_fr = 'Il pleure dès que vous quittez la pièce ? Lancez les battements de cœur des Bruits blancs pour lui donner un sentiment de sécurité et l''aider à s''endormir.', title_hi = 'अलग होने का डर लौट आया? 🌌', body_hi = 'आप कमरे से निकलते ही वह रोने लगता है? व्हाइट नॉइज़ में दिल की धड़कन की आवाज़ चलाकर उसे सुरक्षा का एहसास दीजिए और नींद के लिए तैयार कीजिए।', title_id = 'Takut berpisah kembali muncul? 🌌', body_id = 'Menangis begitu Anda keluar kamar? Putar suara detak jantung dari Suara Putih, beri ia rasa aman, dan antar ia tidur.', title_ja = '離れるのがこわい気持ちが復活？🌌', body_ja = '部屋を出たとたん、あとを追って泣きますか？「ホワイトノイズ」の心臓の音を流して安心感を届け、眠りへ導きましょう。', title_ko = '분리 불안이 다시? 🌌', body_ko = '방을 나가자마자 울며 따라오나요? 백색소음에서 심장 박동 소리를 틀어 안정감을 주고 잠들 준비를 도와주세요.', title_nl = 'Komt de verlatingsangst terug? 🌌', body_nl = 'Huilt hij zodra je de kamer uit gaat? Zet het hartslaggeluid uit Witte ruis aan, geef hem een veilig gevoel en help hem in slaap.', title_pl = 'Lęk przed rozstaniem wraca? 🌌', body_pl = 'Płacze, gdy tylko wychodzisz z pokoju? Włącz bicie serca z Białego szumu, daj mu poczucie bezpieczeństwa i nastrój go do snu.', title_pt = 'O medo da separação voltou? 🌌', body_pt = 'Mal sai do quarto, chora atrás de si? Ligue no Ruído Branco o som do batimento cardíaco, dê-lhe uma sensação de segurança e prepare-o para dormir.', title_sv = 'Separationsångesten tillbaka? 🌌', body_sv = 'Gråter barnet så fort du lämnar rummet? Sätt på hjärtslag från Vitt brus, ge barnet en känsla av trygghet och stäm för sömn.', title_vi = 'Nỗi sợ xa mẹ quay lại? 🌌', body_vi = 'Mẹ vừa ra khỏi phòng là bé khóc theo? Hãy bật tiếng tim đập trong Tiếng ồn trắng để mang lại cảm giác an toàn và đưa bé vào giấc ngủ.', title_zh = '分离焦虑又回来了？🌌', body_zh = '你一离开房间就在后面哭？打开白噪音里的心跳声，给宝宝安全感，帮宝宝进入睡眠。' WHERE id = '813a036f-96ee-4802-8c36-c3d573f602c0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Los pantalones vuelven a quedarle cortos! 📏', body_es = '¿Las mangas se le quedan estrechas? Está dando un estirón. Introduce sus medidas actuales en el Seguimiento del desarrollo y mira con orgullo su curva de crecimiento.', title_fr = 'Le pantalon est encore trop court ! 📏', body_fr = 'Les manches deviennent trop étroites ? C''est un pic de croissance physique. Entrez ses mesures actuelles dans le Suivi de croissance et regardez fièrement sa courbe de croissance.', title_hi = 'पैंट फिर छोटी हो गई! 📏', body_hi = 'कमीज़ की आस्तीनें तंग हो रही हैं? शारीरिक विकास में उछाल है। ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और गर्व से ग्रोथ चार्ट देखिए।', title_id = 'Celananya kependekan lagi! 📏', body_id = 'Lengan bajunya mulai sempit? Ada lonjakan pertumbuhan fisik. Masukkan ukuran terbarunya ke Pelacak Perkembangan dan lihat grafik pertumbuhannya dengan bangga.', title_ja = 'ズボンがまた短くなった！📏', body_ja = 'シャツの袖がきつくなってきましたか？体がぐんと成長する時期です。「発達トラッカー」に今のサイズを入力して、成長グラフを誇らしく眺めましょう。', title_ko = '바지가 또 짧아졌어요! 📏', body_ko = '셔츠 소매가 끼나요? 신체 성장 급등기예요. 성장 기록에 현재 치수를 입력하고 성장 그래프를 뿌듯하게 확인하세요.', title_nl = 'De broek is weer te kort! 📏', body_nl = 'Worden de mouwen te krap? Er is een groeispurt. Voer de huidige maten in de Groeitracker in en kijk trots naar zijn groeicurve.', title_pl = 'Spodnie znów za krótkie! 📏', body_pl = 'Rękawy koszulek robią się ciasne? To skok w rozwoju fizycznym. Wpisz aktualne pomiary w Śledzeniu rozwoju i z dumą spójrz na wykres wzrostu.', title_pt = 'As calças voltaram a ficar curtas! 📏', body_pt = 'As mangas das camisolas estão a ficar apertadas? Há um salto no crescimento físico. Introduza as medidas atuais no Registo de Desenvolvimento e veja com orgulho o gráfico de crescimento.', title_sv = 'Byxorna för korta igen! 📏', body_sv = 'Blir tröjärmarna för trånga? Det är en fysisk tillväxtspurt. Ange aktuella mått i Utvecklingsspåraren och titta stolt på tillväxtkurvan.', title_vi = 'Quần lại ngắn rồi! 📏', body_vi = 'Tay áo bị chật? Bé đang tăng trưởng vọt. Hãy nhập số đo hiện tại vào Theo dõi phát triển và tự hào ngắm biểu đồ tăng trưởng.', title_zh = '裤子又变短了！📏', body_zh = '衣袖变紧了？身体发育正在突飞猛进。在发育追踪里输入当前的尺寸，骄傲地看看成长曲线。' WHERE id = '8c8e48b0-6f8d-4855-bb6b-3ff2edd9fbb3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La reserva de proteínas de mamá ⚡', body_es = 'No es fácil correr detrás de un peque tan activo. Prepara en Recetas saludables para mujeres un batido energético rico en proteínas y fruta, y recarga tu batería.', title_fr = 'La réserve de protéines de maman ⚡', body_fr = 'Courir après un petit plein d''énergie n''est pas facile. Rechargez vos batteries avec un smoothie énergie riche en protéines et en fruits des Recettes saines pour femmes.', title_hi = 'माँ का प्रोटीन भंडार ⚡', body_hi = 'चंचल नन्हे के पीछे भागना आसान नहीं। महिलाओं के लिए सेहतमंद रेसिपी से प्रोटीन और फलों से भरपूर एनर्जी स्मूदी बनाइए और अपनी बैटरी चार्ज कीजिए।', title_id = 'Gudang protein Bunda ⚡', body_id = 'Mengejar si kecil yang aktif tidaklah mudah. Isi ulang baterai Anda dengan smoothie energi kaya protein dan buah dari Resep Sehat untuk wanita.', title_ja = 'ママのたんぱく質チャージ ⚡', body_ja = '活発なお子さんを追いかけるのは大変です。「女性のためのヘルシーレシピ」から、たんぱく質とフルーツたっぷりのエナジースムージーをつくって、バッテリーを充電しましょう。', title_ko = '엄마의 단백질 충전소 ⚡', body_ko = '활발한 아이를 쫓아다니기는 쉽지 않아요. 여성을 위한 건강한 레시피에서 단백질과 과일이 풍부한 에너지 스무디를 만들어 배터리를 충전하세요.', title_nl = 'Eiwitvoorraad van mama ⚡', body_nl = 'Achter een beweeglijk kleintje aan rennen is niet makkelijk. Laad je batterij op met een energiesmoothie vol eiwit en fruit uit Gezonde recepten voor vrouwen.', title_pl = 'Białkowy zapas mamy ⚡', body_pl = 'Bieganie za ruchliwym maluchem to nie lada wyzwanie. Przygotuj ze Zdrowych przepisów dla kobiet energetyczne smoothie bogate w białko i owoce i naładuj baterie.', title_pt = 'A reserva de proteína da mãe ⚡', body_pt = 'Correr atrás de um pequenino tão ativo não é fácil. Prepare nas Receitas Saudáveis para Mulheres um batido energético rico em proteína e fruta e recarregue as baterias.', title_sv = 'Mammas proteinförråd ⚡', body_sv = 'Det är inte lätt att springa efter en aktiv liten. Gör en energismoothie rik på protein och frukt från Hälsosamma recept för kvinnor och ladda dina batterier.', title_vi = 'Kho đạm của mẹ ⚡', body_vi = 'Chạy theo bé hiếu động không hề dễ. Hãy làm ly sinh tố năng lượng giàu đạm và trái cây từ Công thức lành mạnh cho phụ nữ để sạc đầy pin cho mình.', title_zh = '妈妈的蛋白质储备 ⚡', body_zh = '追着好动的小家伙跑可不容易。从女性健康食谱里做一杯富含蛋白质和水果的能量奶昔，给自己充满电。' WHERE id = '24f24fa2-f109-4ee8-b9c0-2fe64e74bf4d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Esto lo hago yo! 👕', body_es = '¿Vestirse por la mañana se convierte en una gran crisis? Aprende ya con Anacan AI los secretos para afrontar la tozudez y darle derecho a elegir.', title_fr = 'C''est moi qui le fais ! 👕', body_fr = 'L''habillage du matin tourne à la grosse crise ? Découvrez tout de suite avec Anacan AI les secrets pour gérer son obstination et lui laisser le droit de choisir.', title_hi = 'यह मैं करूँगा! 👕', body_hi = 'सुबह कपड़े पहनना बड़ा झगड़ा बन जाता है? ज़िद से निपटने और उसे चुनने का मौका देने के राज़ तुरंत Anacan AI से जानिए।', title_id = 'Biar aku sendiri! 👕', body_id = 'Berpakaian di pagi hari berubah jadi drama besar? Pelajari rahasia menghadapi sikap keras kepala dan memberinya hak memilih langsung dari Anacan AI.', title_ja = '自分でやる！👕', body_ja = '朝の着替えが大きなかんしゃくの時間になっていますか？こだわりへの対処法と、自分で選ぶ機会をあげるコツを、すぐにAnacan AIで学びましょう。', title_ko = '내가 할래! 👕', body_ko = '아침마다 옷 입기가 큰 전쟁이 되나요? 고집을 다루고 선택할 기회를 주는 비결을 Anacan AI에게 바로 배워 보세요.', title_nl = 'Dat doe ik zelf! 👕', body_nl = 'Wordt aankleden in de ochtend een grote strijd? Leer meteen bij Anacan AI hoe je met koppigheid omgaat en hem zelf laat kiezen.', title_pl = 'Ja to zrobię! 👕', body_pl = 'Poranne ubieranie zamienia się w wielki kryzys? Od razu poznaj z Anacan AI sekrety radzenia sobie z uporem i dawania mu prawa wyboru.', title_pt = 'Eu faço sozinho! 👕', body_pt = 'Vestir-se de manhã transforma-se numa grande crise? Aprenda já com o Anacan AI os segredos para lidar com a teimosia e dar-lhe o direito de escolher.', title_sv = 'Jag gör det själv! 👕', body_sv = 'Har påklädningen på morgonen blivit ett stort utbrott? Lär dig direkt av Anacan AI hur du hanterar envisheten och ger barnet rätt att välja.', title_vi = '"Con tự làm!" 👕', body_vi = 'Mặc quần áo buổi sáng đã thành cuộc khủng hoảng lớn? Hãy học ngay từ Anacan AI bí quyết đối phó với sự bướng bỉnh và cho bé quyền tự chọn.', title_zh = '这个我自己来！👕', body_zh = '早上穿衣服变成了大崩溃？马上向Anacan AI学习应对倔强、给宝宝选择权的秘诀。' WHERE id = '5e6168f7-641f-4f35-ba96-328826769e77' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Operación verdura secreta 🥦', body_es = '¿Aparta el plato en cuanto ve el brócoli? Descubre en Recetas para bebé cómo esconder con maña estas vitaminas en unas tortitas deliciosas y ábrele el apetito.', title_fr = 'Opération légumes cachés 🥦', body_fr = 'Il repousse l''assiette dès qu''il voit du brocoli ? Découvrez dans les Recettes pour bébés comment cacher habilement ces vitamines dans de délicieuses crêpes et ouvrez-lui l''appétit.', title_hi = 'छिपी सब्ज़ी का मिशन 🥦', body_hi = 'ब्रोकली देखते ही प्लेट दूर कर देता है? बच्चों की रेसिपी में जानिए कि इन विटामिनों को स्वादिष्ट पैनकेक में चतुराई से कैसे छिपाएँ, और उसकी भूख खोलिए।', title_id = 'Misi sayuran rahasia 🥦', body_id = 'Langsung mendorong piring begitu melihat brokoli? Temukan di Resep Bayi cara pintar menyembunyikan vitamin-vitamin ini di dalam panekuk yang lezat, dan buka nafsu makannya.', title_ja = 'こっそり野菜作戦 🥦', body_ja = 'ブロッコリーを見たとたん、お皿を押しのけますか？「離乳食を始める赤ちゃんのレシピ」で、これらのビタミンをおいしいパンケーキに上手に隠す方法を見つけて、食欲を引き出しましょう。', title_ko = '채소 몰래 작전 🥦', body_ko = '브로콜리만 보면 접시를 밀어내나요? 아기 레시피에서 이 비타민들을 맛있는 팬케이크 속에 감쪽같이 숨기는 법을 찾아 입맛을 살려 주세요.', title_nl = 'Geheime groente-operatie 🥦', body_nl = 'Schuift hij zijn bord weg zodra hij broccoli ziet? Ontdek in Babyrecepten hoe je deze vitamines slim verstopt in lekkere pannenkoekjes en wek zijn eetlust op.', title_pl = 'Tajna misja warzywna 🥦', body_pl = 'Odsuwa talerz na widok brokułów? Odkryj w Przepisach dla niemowląt, jak zręcznie ukryć te witaminy w pysznych placuszkach, i pobudź jego apetyt.', title_pt = 'Operação legumes escondidos 🥦', body_pt = 'Mal vê brócolos, afasta o prato? Descubra nas Receitas para bebés como esconder com mestria estas vitaminas dentro de panquecas deliciosas e abra-lhe o apetite.', title_sv = 'Hemlig grönsaksoperation 🥦', body_sv = 'Skjuter barnet bort tallriken så fort broccolin syns? Upptäck i Recept för bebisar hur du skickligt gömmer dessa vitaminer i goda pannkakor och väck aptiten.', title_vi = 'Chiến dịch giấu rau củ 🥦', body_vi = 'Thấy bông cải xanh là bé đẩy đĩa ra? Hãy khám phá cách khéo léo giấu những vitamin này vào bánh kếp thơm ngon trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '秘密蔬菜行动 🥦', body_zh = '一看到西兰花就推开盘子？在宝宝食谱里发现如何把这些维生素巧妙地藏进美味的小煎饼里，让宝宝胃口大开。' WHERE id = '85abdfc2-20eb-4a57-a2bc-cb822114eada' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego no se acaba nunca ⏱️', body_es = '¿En lugar de irse a la cama, sale corriendo a esconderse? Pon el temporizador de sueño y las olas del mar de Ruido blanco, y convierte la habitación en una tranquila cueva del sueño.', title_fr = 'Le jeu n''en finit pas ⏱️', body_fr = 'Au lieu d''aller au lit, il court se cacher ? Lancez le minuteur de sommeil, mettez les vagues de l''océan des Bruits blancs et transformez la chambre en douce grotte du sommeil.', title_hi = 'खेल खत्म ही नहीं होता ⏱️', body_hi = 'सोने जाने के बजाय भागकर छिप जाता है? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में समुद्र की लहरें लगाइए और कमरे को नींद की शांत गुफ़ा बना दीजिए।', title_id = 'Waktu bermain tak kunjung usai ⏱️', body_id = 'Bukannya ke tempat tidur, malah lari bersembunyi? Nyalakan Timer Tidur, putar suara ombak dari Suara Putih, dan ubah kamar menjadi gua tidur yang tenang.', title_ja = '遊びが終わらない ⏱️', body_ja = 'ベッドに行く代わりに走って隠れますか？睡眠タイマーをオンにして、「ホワイトノイズ」の波の音を流し、部屋を静かな眠りの洞窟に変えましょう。', title_ko = '놀이가 끝나지 않아요 ⏱️', body_ko = '잠자리에 드는 대신 도망가서 숨나요? 수면 타이머를 켜고 백색소음의 파도 소리를 틀어 방을 조용한 잠의 동굴로 바꿔 주세요.', title_nl = 'Het spelen houdt maar niet op ⏱️', body_nl = 'Rent hij weg en verstopt hij zich in plaats van naar bed te gaan? Zet de Slaaptimer aan, kies oceaangolven in Witte ruis en maak van de kamer een rustige slaapgrot.', title_pl = 'Zabawa nie ma końca ⏱️', body_pl = 'Zamiast iść do łóżka, ucieka i się chowa? Włącz timer snu, puść fale oceanu z Białego szumu i zamień pokój w cichą jaskinię snu.', title_pt = 'A brincadeira nunca acaba ⏱️', body_pt = 'Em vez de ir para a cama, foge e esconde-se? Ligue o temporizador de sono, ponha as ondas do mar do Ruído Branco e transforme o quarto numa gruta tranquila para dormir.', title_sv = 'Leken tar aldrig slut ⏱️', body_sv = 'Springer barnet och gömmer sig i stället för att gå och lägga sig? Starta sömntimern, sätt på havsvågor från Vitt brus och gör rummet till en lugn sömngrotta.', title_vi = 'Trò chơi chưa muốn kết thúc ⏱️', body_vi = 'Bé chạy đi trốn thay vì lên giường? Hãy bật Bộ hẹn giờ ngủ, mở tiếng sóng biển trong Tiếng ồn trắng để biến căn phòng thành một hang ngủ yên tĩnh.', title_zh = '游戏停不下来 ⏱️', body_zh = '不上床，反而跑去躲起来？打开睡眠计时器，播放白噪音里的海浪声，把房间变成一个安静的睡眠小山洞。' WHERE id = '8a4be0f9-7229-4996-baf5-618ca78de14d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Si empieza a tirar o escupir la comida, te está diciendo que ya está lleno. Para el temporizador de tomas, anota que ha completado su ración y analiza su apetito.', body_fr = 'S''il commence à jeter ou à recracher la nourriture, il vous dit qu''il n''a plus faim. Arrêtez le minuteur des repas, notez que sa ration est atteinte et analysez son appétit.', body_hi = 'अगर खाना फेंकने या थूकने लगा है, तो वह कह रहा है ''मेरा पेट भर गया''। फ़ीडिंग टाइमर रोकिए, मात्रा पूरी होने को दर्ज कीजिए और भूख का विश्लेषण कीजिए।', body_id = 'Jika ia mulai melempar atau meludahkan makanan, artinya ia bilang sudah kenyang. Hentikan Timer Makan, catat bahwa porsinya terpenuhi, dan analisis nafsu makannya.', body_ja = '食べ物を投げたり吐き出したりし始めたら、「おなかいっぱい」のサインです。食事タイマーを止めて、目安量をとれたことを記録し、食欲を分析しましょう。', body_ko = '음식을 던지거나 뱉기 시작했다면 ''배불러요''라는 뜻이에요. 수유 타이머를 멈추고 충분히 먹었다고 기록한 뒤 식욕을 분석해 보세요.', body_nl = 'Begint hij eten te gooien of uit te spugen? Dan zegt hij: ik zit vol. Stop de Voedingstimer, noteer dat hij genoeg heeft gehad en analyseer zijn eetlust.', body_pl = 'Jeśli zaczyna rzucać jedzeniem albo je wypluwać, mówi „jestem syty”. Zatrzymaj timer karmienia, zanotuj, że norma została osiągnięta, i przeanalizuj apetyt.', body_pt = 'Se começou a atirar ou a cuspir a comida, está a dizer que está satisfeito. Pare o temporizador de alimentação, registe que a dose foi cumprida e analise o apetite.', body_sv = 'Har barnet börjat kasta eller spotta ut maten betyder det ”jag är mätt”. Stoppa matningstimern, anteckna att normen är nådd och analysera aptiten.', body_vi = 'Nếu bé bắt đầu ném hoặc nhổ thức ăn, tức là bé đang nói "Con no rồi". Hãy dừng Hẹn giờ cho bú, ghi nhận đã đủ định mức và phân tích khẩu vị của bé.', body_zh = '如果开始扔食物或吐出来，那就是在说“我吃饱了”。停下喂养计时器，记下已达到参考量，分析一下食欲。' WHERE id = 'a40e092a-696e-4da1-98b1-5b56a4f49122' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se despierta muy temprano? 🌅', body_es = '¿Se despierta antes de que salga el sol y lleno de energía? Pide ya a nuestro asistente experto Anacan AI los secretos para llevar su horario de sueño a horas más razonables.', title_fr = 'Des réveils trop matinaux ? 🌅', body_fr = 'Il se réveille avant le lever du soleil, plein d''énergie ? Demandez tout de suite à notre assistant expert Anacan AI ses secrets pour décaler son rythme vers des horaires plus raisonnables.', title_hi = 'सुबह बहुत जल्दी जागता है? 🌅', body_hi = 'सूरज निकलने से पहले ही जागकर ऊर्जा से भरा है? उसकी नींद के समय को ज़्यादा आरामदायक घंटों तक कैसे खिसकाएँ, यह जानने के लिए तुरंत हमारे Anacan AI एक्सपर्ट असिस्टेंट से राज़ जानिए।', title_id = 'Bangun terlalu pagi? 🌅', body_id = 'Bangun sebelum matahari terbit dan penuh energi? Segera dapatkan rahasia dari asisten ahli Anacan AI untuk menggeser jadwal tidurnya ke jam yang lebih manusiawi.', title_ja = '朝起きるのが早すぎる？🌅', body_ja = '日が昇る前から元気いっぱいに起きていますか？この睡眠リズムを、もう少し人間らしい時間にずらすコツを、すぐにAnacan AIのエキスパートアシスタントから教えてもらいましょう。', title_ko = '아침에 너무 일찍 깨나요? 🌅', body_ko = '해가 뜨기도 전에 쌩쌩하게 일어나나요? 수면 시간을 좀 더 여유로운 시간대로 옮기는 비결을 Anacan AI 전문가 도우미에게 바로 물어보세요.', title_nl = 'Wordt hij erg vroeg wakker? 🌅', body_nl = 'Is hij al wakker en vol energie voor de zon op is? Haal meteen tips bij onze Anacan AI-expert om zijn slaapritme naar wat menselijker tijden te verschuiven.', title_pl = 'Zbyt wczesne poranne pobudki? 🌅', body_pl = 'Budzi się pełen energii, zanim wzejdzie słońce? Od razu poznaj sekrety od naszego eksperta Anacan AI, jak przesunąć ten rytm snu na bardziej ludzkie godziny.', title_pt = 'Acorda muito cedo? 🌅', body_pt = 'Acorda antes de o sol nascer e cheio de energia? Peça já ao nosso assistente especialista Anacan AI os segredos para passar esta rotina de sono para horas mais humanas.', title_sv = 'Vaknar för tidigt på morgonen? 🌅', body_sv = 'Vaknar barnet pigg innan solen gått upp? Få hemligheterna från vår expertassistent Anacan AI direkt om hur du flyttar sömnrytmen till mer mänskliga tider.', title_vi = 'Bé dậy quá sớm? 🌅', body_vi = 'Mặt trời chưa lên mà bé đã thức dậy đầy năng lượng? Hãy hỏi ngay trợ lý chuyên gia Anacan AI bí quyết để dời giờ dậy của bé sang khung giờ dễ chịu hơn.', title_zh = '早上醒得太早？🌅', body_zh = '太阳还没出来就醒了，还精力充沛？马上向我们的Anacan AI专家助手讨教秘诀，把作息调到更人性化的时间。' WHERE id = 'b333371b-bfc0-429c-bd23-a3e9996c1c00' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Mete los juguetes en una caja y luego la vacía entera? Se está formando la lógica de «dentro» y «fuera». Anota esta habilidad cognitiva en el Seguimiento del desarrollo.', body_fr = 'Il met ses jouets dans une boîte puis la vide entièrement ? Les notions de dedans et dehors se construisent. Notez cette compétence cognitive dans le Suivi de développement.', body_hi = 'डिब्बे में खिलौने डालता है, फिर सब खाली कर देता है? ''अंदर'' और ''बाहर'' की समझ बन रही है। ग्रोथ ट्रैकर में इस समझ वाले हुनर को दर्ज कीजिए।', body_id = 'Memasukkan mainan ke kotak, lalu mengeluarkan semuanya lagi? Logika di dalam dan di luar sedang terbentuk. Catat keterampilan kognitif ini di Pelacak Perkembangan.', body_ja = '箱におもちゃを入れては、全部出していますか？「中」と「外」の論理が育っています。この認知の力を「発達トラッカー」に記録しましょう。', body_ko = '상자에 장난감을 넣었다가 다시 다 쏟아 내나요? ''안과 밖''의 논리가 자라고 있어요. 성장 기록에 이 인지 능력을 남겨 두세요.', body_nl = 'Gooit hij speelgoed in een doos en haalt hij alles er weer uit? Zo ontwikkelt hij het begrip van erin en eruit. Noteer deze cognitieve vaardigheid in de Groeitracker.', body_pl = 'Wrzuca zabawki do pudełka, a potem wszystko wysypuje? Kształtuje się logika pojęć „w środku” i „na zewnątrz”. Zapisz tę umiejętność poznawczą w Śledzeniu rozwoju.', body_pt = 'Mete os brinquedos na caixa e depois esvazia-a toda? Está a formar-se a lógica de "dentro" e "fora". Registe esta competência cognitiva no Registo de Desenvolvimento.', body_sv = 'Lägger barnet leksakerna i lådan och tömmer den sedan igen? Logiken för ”i” och ”utanför” formas. Anteckna denna kognitiva färdighet i Utvecklingsspåraren.', body_vi = 'Bé bỏ đồ chơi vào hộp rồi lại đổ hết ra? Khái niệm trong và ngoài đang hình thành. Hãy ghi lại kỹ năng nhận thức này vào Theo dõi phát triển.', body_zh = '把玩具扔进盒子，再全部倒出来？“里面”和“外面”的逻辑正在形成。把这项认知能力记在发育追踪里吧。' WHERE id = '3c7a1c30-6e81-411e-a8e2-8748214141cf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de los zapatos 👟', body_es = '¿Al salir quiere ponerse sí o sí las botas de invierno en pleno verano? Deja que a veces elija él, eso refuerza su voluntad.', title_fr = 'L''obstination des chaussures 👟', body_fr = 'Il tient absolument à porter ses chaussures d''hiver en plein été pour sortir ? Laissez-le choisir de temps en temps, cela renforce sa volonté.', title_hi = 'जूतों की ज़िद 👟', body_hi = 'बाहर जाते समय गर्मी में भी वही सर्दियों वाले जूते पहनने की ज़िद करता है? कभी-कभी उसकी पसंद को मान लीजिए, इससे उसकी इच्छाशक्ति मज़बूत होती है।', title_id = 'Ngotot soal sepatu 👟', body_id = 'Ia bersikeras memakai sepatu musim dingin di musim panas saat keluar rumah? Sesekali biarkan ia memilih sendiri, ini memperkuat kemauannya.', title_ja = '靴へのこだわり 👟', body_ja = 'お出かけのとき、夏なのにどうしても冬の靴をはきたがりますか？ときにはその選択を認めてあげましょう。意志の力が育ちます。', title_ko = '신발 고집 👟', body_ko = '외출할 때 여름인데도 꼭 겨울 신발을 신겠다고 하나요? 가끔은 아이의 선택을 허락해 주세요. 의지가 더 단단해져요.', title_nl = 'Schoenenstrijd 👟', body_nl = 'Wil hij per se zijn winterschoenen aan in de zomer? Laat hem soms zelf kiezen, dat versterkt zijn wilskracht.', title_pl = 'Butowy upór 👟', body_pl = 'Przy każdym wyjściu koniecznie chce założyć latem zimowe buty? Czasem pozwól mu wybrać, to wzmacnia jego siłę woli.', title_pt = 'A teimosia dos sapatos 👟', body_pt = 'Para sair, quer mesmo calçar as botas de inverno em pleno verão? Deixe-o às vezes escolher: isso fortalece a vontade dele.', title_sv = 'Envis med skorna 👟', body_sv = 'Vill barnet absolut ha vinterskorna på sig ute mitt i sommaren? Låt barnet välja ibland, det stärker viljan.', title_vi = 'Cuộc chiến giày dép 👟', body_vi = 'Ra ngoài là bé nhất định đòi đi đôi giày mùa đông giữa mùa hè? Thỉnh thoảng hãy để bé tự chọn, điều này giúp bé rèn ý chí.', title_zh = '鞋子之争 👟', body_zh = '出门非要在夏天穿那双冬鞋？有时候允许宝宝自己选择，这会增强宝宝的意志力。' WHERE id = 'b06ec056-54a0-4363-b389-839031267542' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Te asusta lo que lees sobre la crisis de los 2 años? No te pierdas en internet: escribe directamente a Anacan AI y aprende a superar esta etapa con facilidad.', body_fr = 'Ce que vous lisez sur la crise des 2 ans vous fait peur ? Ne vous perdez pas sur Internet, écrivez directement à Anacan AI et découvrez comment traverser cette période sereinement.', body_hi = '2 साल के नखरों के बारे में पढ़कर डर लग रहा है? इंटरनेट में मत उलझिए, सीधे Anacan AI को लिखिए और जानिए कि यह दौर आसानी से कैसे पार करें।', body_id = 'Takut dengan apa yang Anda baca tentang krisis usia 2 tahun? Jangan tersesat di internet, langsung tulis ke Anacan AI dan pelajari cara melewati masa ini dengan mudah.', body_ja = '2歳のイヤイヤ期について読んで不安になっていますか？ネットで迷わず、Anacan AIに直接書き込んで、この時期を楽に乗りこえる方法を学びましょう。', body_ko = '두 돌 떼쓰기에 관한 글을 읽고 겁이 났나요? 인터넷에서 헤매지 말고 Anacan AI에게 바로 물어 이 시기를 수월하게 넘기는 법을 배워 보세요.', body_nl = 'Maakt wat je leest over de peuterpuberteit je bang? Verdwaal niet op internet, maar schrijf direct naar Anacan AI en leer hoe je deze fase makkelijk doorkomt.', body_pl = 'Przeraża cię to, co czytasz o buncie dwulatka? Nie gub się w internecie, napisz od razu do Anacan AI i dowiedz się, jak łagodnie przejść przez ten okres.', body_pt = 'O que lê sobre as crises dos 2 anos assusta-a? Não se perca na internet: escreva diretamente ao Anacan AI e aprenda a passar esta fase com facilidade.', body_sv = 'Skrämmer det du läst om 2-årstrots dig? Gå inte vilse på internet, skriv direkt till Anacan AI och lär dig hur ni lätt tar er igenom den här perioden.', body_vi = 'Những gì mẹ đọc về khủng hoảng tuổi lên 2 khiến mẹ lo lắng? Đừng lạc giữa internet, hãy nhắn thẳng cho Anacan AI để biết cách vượt qua giai đoạn này dễ dàng.', body_zh = '读到的“2岁危机”让你害怕？别在网上迷失，直接写信给Anacan AI，学习如何轻松度过这个阶段。' WHERE id = 'ff08789a-eee1-4756-9d40-5ac5e65f75a9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'De las palabras a las frases 🗣️', body_es = '¿Ya empieza a formar frases graciosas de 3 palabras? Graba en vídeo con sonido este gran salto del lenguaje y su dulce pronunciación, y guárdalo para el futuro.', title_fr = 'Des mots aux phrases 🗣️', body_fr = 'Il commence déjà à faire de drôles de phrases de 3 mots ? Gardez ce formidable bond du langage et ses prononciations adorables en vidéo avec le son pour plus tard.', title_hi = 'शब्दों से वाक्यों तक 🗣️', body_hi = 'अब 3 शब्दों वाले मज़ेदार वाक्य बनाने लगा है? भाषा की इस शानदार छलांग और प्यारे उच्चारण को आवाज़ वाले वीडियो के रूप में रिकॉर्ड करके भविष्य के लिए सहेजिए।', title_id = 'Dari kata ke kalimat 🗣️', body_id = 'Ia sudah mulai menyusun kalimat lucu 3 kata? Rekam lompatan bahasa yang luar biasa ini dan pelafalannya yang menggemaskan dalam video bersuara untuk dikenang nanti.', title_ja = '言葉から文へ 🗣️', body_ja = 'もう3語のおもしろい文をつくり始めましたか？このすばらしい言葉の飛躍とかわいい発音を、音声付きの動画で記録して、未来に残しましょう。', title_ko = '단어에서 문장으로 🗣️', body_ko = '벌써 세 단어로 된 재미있는 문장을 만들기 시작했나요? 이 멋진 언어 도약과 귀여운 발음을 소리가 담긴 영상으로 남겨 간직하세요.', title_nl = 'Van woorden naar zinnen 🗣️', body_nl = 'Maakt hij al grappige zinnetjes van 3 woorden? Leg deze geweldige taalsprong en zijn schattige uitspraak vast op video met geluid en bewaar het voor later.', title_pl = 'Od słów do zdań 🗣️', body_pl = 'Zaczyna już składać zabawne zdania z 3 słów? Nagraj ten wspaniały skok językowy i słodką wymowę jako film z dźwiękiem i zachowaj na przyszłość.', title_pt = 'Das palavras às frases 🗣️', body_pt = 'Já começa a formar frases engraçadas de 3 palavras? Grave em vídeo com som este salto fantástico na linguagem e as pronúncias tão doces, e guarde-os para o futuro.', title_sv = 'Från ord till meningar 🗣️', body_sv = 'Har barnet börjat bilda roliga meningar med 3 ord? Spela in detta fantastiska språksprång och det söta uttalet som video med ljud och spara det för framtiden.', title_vi = 'Từ từ ngữ đến câu 🗣️', body_vi = 'Bé đã bắt đầu nói những câu 3 từ ngộ nghĩnh? Hãy quay video có tiếng bước nhảy vọt ngôn ngữ tuyệt vời này cùng cách phát âm đáng yêu của bé để lưu giữ cho mai sau.', title_zh = '从词语到句子 🗣️', body_zh = '已经开始说3个词的搞笑句子了？把这次了不起的语言飞跃和可爱的发音录成有声视频，留给未来。' WHERE id = '17e385d1-c634-49cd-9d0d-e1c98c9b0fd8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las páginas cobran vida 📖', body_es = '¿Imita los sonidos de los animales del libro mientras leéis el cuento? Lee sin falta en el Blog técnicas de lectura interactiva que apoyan este desarrollo de la imaginación.', title_fr = 'Les pages prennent vie 📖', body_fr = 'Il imite les cris des animaux du livre pendant le conte ? Lisez absolument dans la rubrique Blogs les techniques de lecture interactive qui soutiennent ce développement de l''imagination.', title_hi = 'पन्ने जीवंत हो उठते हैं 📖', body_hi = 'कहानी पढ़ते समय किताब के जानवरों की आवाज़ निकालता है? ब्लॉग सेक्शन में कल्पना के इस विकास में मदद करने वाली इंटरैक्टिव पढ़ने की तकनीकें ज़रूर पढ़िए।', title_id = 'Halaman-halaman jadi hidup 📖', body_id = 'Menirukan suara hewan di buku saat Anda membacakan dongeng? Baca teknik membaca interaktif yang mendukung perkembangan imajinasi ini di bagian Blog.', title_ja = 'ページがいきいきと動き出す 📖', body_ja = '絵本を読んでいると、出てくる動物の鳴き声をまねしますか？この想像力の発達を応援する、参加型の読み聞かせのコツを、ブログでぜひ読んでみましょう。', title_ko = '책장이 살아나요 📖', body_ko = '동화를 읽을 때 책 속 동물 소리를 따라 하나요? 이 상상력 발달을 돕는 상호작용 책 읽기 방법을 블로그에서 꼭 읽어 보세요.', title_nl = 'Bladzijden komen tot leven 📖', body_nl = 'Doet hij bij het voorlezen de dieren in het boek na? Lees zeker in Blogs over interactieve leestechnieken die deze fantasie-ontwikkeling steunen.', title_pl = 'Strony ożywają 📖', body_pl = 'Podczas czytania bajki naśladuje odgłosy zwierząt z książki? Koniecznie przeczytaj w sekcji Blog o technikach interaktywnego czytania, które wspierają rozwój wyobraźni.', title_pt = 'As páginas ganham vida 📖', body_pt = 'Enquanto lê a história, imita os sons dos animais do livro? Leia sem falta nos Blogues técnicas de leitura interativa que apoiam este desenvolvimento da imaginação.', title_sv = 'Sidorna får liv 📖', body_sv = 'Härmar barnet djurens läten i boken när ni läser sagor? Läs om interaktiva lästekniker som stöttar fantasins utveckling i Bloggar.', title_vi = 'Những trang sách sống động 📖', body_vi = 'Khi đọc truyện, bé bắt chước tiếng các con vật trong sách? Nhất định hãy đọc trong mục Blog về các kỹ thuật đọc tương tác giúp hỗ trợ trí tưởng tượng phát triển.', title_zh = '书页活起来了 📖', body_zh = '读故事时模仿书里动物的叫声？一定要读读博客板块里支持这种想象力发展的互动阅读技巧。' WHERE id = '3fe4d415-9d24-4577-93ed-654921e52b2c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explosión de energía 💥', body_es = 'Las cuatro paredes de casa no aguantan tanta carrera. Abre el mapa de Lugares para mamás, busca un parque seguro con suelo blando y un tobogán grande, y déjale jugar a su aire.', title_fr = 'Explosion d''énergie 💥', body_fr = 'Les quatre murs de la maison ne résistent plus à ces courses. Ouvrez la carte des Lieux adaptés aux mamans, trouvez un parc sûr avec un sol souple et un grand toboggan, et laissez-le libre.', title_hi = 'ऊर्जा का धमाका 💥', body_hi = 'घर की चार दीवारें यह भाग-दौड़ नहीं झेल पातीं। माँ के लिए अनुकूल जगहें का नक्शा खोलिए, नरम ज़मीन और बड़ी स्लाइड वाला सुरक्षित पार्क ढूँढिए और उसे खुलकर खेलने दीजिए।', title_id = 'Ledakan energi 💥', body_id = 'Empat dinding rumah tak sanggup menampung larinya. Buka peta Tempat Ramah Ibu, temukan taman aman dengan alas lembut dan perosotan besar, dan biarkan ia bebas bermain.', title_ja = 'エネルギーが爆発 💥', body_ja = '家の4つの壁では、この走り回りに耐えられません。「ママにやさしいスポット」のマップを開いて、やわらかい地面と大きなすべり台がある安全な公園を見つけ、思いきり遊ばせてあげましょう。', title_ko = '에너지 폭발 💥', body_ko = '집 안의 네 벽으로는 이 뜀박질을 감당할 수 없어요. 엄마 친화 장소 지도를 열어 바닥이 푹신하고 큰 미끄럼틀이 있는 안전한 공원을 찾아 마음껏 뛰놀게 해 주세요.', title_nl = 'Energie-explosie 💥', body_nl = 'De vier muren van het huis houden dit gerren niet uit. Open de kaart Mamavriendelijke plekken, zoek een veilig park met een zachte ondergrond en grote glijbaan en laat hem vrij.', title_pl = 'Wybuch energii 💥', body_pl = 'Cztery ściany nie wytrzymują tej bieganiny. Otwórz mapę Miejsc przyjaznych mamom, znajdź bezpieczny park z miękką nawierzchnią i dużą zjeżdżalnią i pozwól mu się wyszaleć.', title_pt = 'Explosão de energia 💥', body_pt = 'As quatro paredes de casa não aguentam tanta correria. Abra o mapa dos Locais Amigos das Mães, encontre um parque seguro com piso macio e um escorrega grande e deixe-o à vontade.', title_sv = 'Energiexplosion 💥', body_sv = 'Hemmets fyra väggar klarar inte allt springande. Öppna kartan i Mammavänliga platser, hitta en trygg park med mjukt underlag och stor rutschkana och låt barnet röra sig fritt.', title_vi = 'Bùng nổ năng lượng 💥', body_vi = 'Bốn bức tường trong nhà không chịu nổi những màn chạy nhảy này. Hãy mở bản đồ Địa điểm thân thiện với mẹ, tìm một công viên an toàn có nền mềm và cầu trượt lớn để bé tự do vui chơi.', title_zh = '能量大爆发 💥', body_zh = '家里的四面墙承受不住这样的奔跑了。打开妈妈友好场所地图，找一个有软地面和大滑梯的安全公园，让宝宝尽情撒欢。' WHERE id = 'bad958b0-7da3-4a62-ae7d-c35289ff6f57' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Me los lavo yo! 🪥', body_es = '¿Te quita el cepillo para hacerlo solo, pero en realidad no se cepilla? Busca ya en Productos recomendados modelos musicales y ergonómicos que te faciliten esta tarea.', title_fr = 'Je me brosse tout seul ! 🪥', body_fr = 'Il vous prend la brosse à dents pour le faire lui-même, sans vraiment se brosser ? Cherchez tout de suite dans les Produits recommandés des modèles musicaux et ergonomiques qui faciliteront ce moment.', title_hi = 'मैं खुद ब्रश करूँगा! 🪥', body_hi = 'टूथब्रश आपसे लेकर खुद करना चाहता है, पर असल में ब्रश नहीं करता? इसे आसान बनाने वाले म्यूज़िकल और आरामदायक ब्रश तुरंत सुझाए गए प्रोडक्ट में खोजिए।', title_id = 'Aku sikat gigi sendiri! 🪥', body_id = 'Ia merebut sikat gigi dari Anda untuk menyikat sendiri, padahal sebenarnya tidak menyikat? Segera cari model bermusik dan ergonomis yang memudahkan proses ini di Produk Rekomendasi.', title_ja = '自分でみがく！🪥', body_ja = 'あなたから歯ブラシを取って自分でやりたがるけれど、実際はみがけていない？この習慣を楽にする、音楽付きで持ちやすい歯ブラシを、すぐに「おすすめ商品」で探してみましょう。', title_ko = '내가 닦을래! 🪥', body_ko = '칫솔을 빼앗아 혼자 하겠다면서 실제로는 닦지 않나요? 양치를 쉽게 해 줄 음악이 나오는 인체공학적 칫솔을 추천 제품에서 바로 찾아보세요.', title_nl = 'Ik poets zelf! 🪥', body_nl = 'Pakt hij de tandenborstel af om het zelf te doen, maar poetst hij niet echt? Zoek meteen in Aanbevolen producten muzikale en ergonomische borstels die het makkelijker maken.', title_pl = 'Sam umyję! 🪥', body_pl = 'Zabiera ci szczoteczkę, bo chce sam, ale tak naprawdę nie myje zębów? Od razu poszukaj w Polecanych produktach grających i ergonomicznych modeli, które to ułatwią.', title_pt = 'Eu escovo sozinho! 🪥', body_pt = 'Tira-lhe a escova para o fazer sozinho, mas na verdade não escova? Procure já nos Produtos Recomendados modelos musicais e ergonómicos que facilitam esta tarefa.', title_sv = 'Jag borstar själv! 🪥', body_sv = 'Tar barnet tandborsten från dig för att göra det själv, men borstar egentligen inte? Leta direkt efter tandborstar med musik och ergonomiska modeller som gör det enklare i Rekommenderade produkter.', title_vi = '"Con tự đánh!" 🪥', body_vi = 'Bé giành bàn chải để tự làm nhưng thật ra không chải? Hãy tìm ngay những mẫu bàn chải có nhạc, thiết kế tiện dụng giúp việc này dễ hơn trong Sản phẩm gợi ý.', title_zh = '我要自己刷！🪥', body_zh = '从你手里拿走牙刷想自己刷，其实根本没刷？马上去推荐商品找找能让刷牙更轻松的音乐款和人体工学款。' WHERE id = '6dabe6f9-b86b-4347-9d8c-8d189d8a1224' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Líquidos y estreñimiento 💧', body_es = '¿Corre mucho y bebe poca agua? Fíjate en las deposiciones al cambiar el pañal. Si hay riesgo de estreñimiento, anótalo en la app y añade enseguida alimentos con fibra con el Seguimiento de tomas.', title_fr = 'Hydratation et constipation 💧', body_fr = 'Il court beaucoup et boit peu ? Observez les selles à chaque change. En cas de risque de constipation, notez-le dans l''appli et ajoutez tout de suite des aliments riches en fibres avec le Suivi des repas.', title_hi = 'तरल और कब्ज़ 💧', body_hi = 'खूब दौड़ता है, पर पानी कम पीता है? डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ का खतरा हो तो ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से फ़ाइबर वाली चीज़ें जोड़िए।', title_id = 'Asupan cairan dan sembelit 💧', body_id = 'Banyak berlari, sedikit minum? Perhatikan kotorannya saat mengganti popok. Jika ada risiko sembelit, catat di aplikasi dan segera tambahkan makanan berserat dengan alat Pemantau Nutrisi.', title_ja = '水分補給と便秘 💧', body_ja = 'たくさん走り回るのに、あまりお水を飲まない？おむつ替えのときにうんちの様子をチェックしましょう。便秘のおそれがあればアプリに記録して、すぐに「栄養管理ツール」で食物繊維の多い食べ物を加えましょう。', title_ko = '수분 섭취와 변비 💧', body_ko = '많이 뛰는데 물은 적게 마시나요? 기저귀를 갈 때 배변을 살펴보세요. 변비가 걱정된다면 앱에 기록하고 수유 기록 도구로 섬유질 음식을 바로 추가하세요.', title_nl = 'Drinken en verstopping 💧', body_nl = 'Rent hij veel en drinkt hij weinig? Let bij het verschonen op de ontlasting. Is er kans op verstopping, noteer het in de app en voeg meteen met de Voedingstracker vezelrijk eten toe.', title_pl = 'Picie a zaparcia 💧', body_pl = 'Dużo biega, a mało pije? Obserwuj kupki przy zmianie pieluszki. Jeśli jest ryzyko zaparć, zapisz to w aplikacji i od razu dodaj produkty bogate w błonnik w narzędziu do śledzenia karmienia.', title_pt = 'Líquidos e prisão de ventre 💧', body_pt = 'Corre muito e bebe pouca água? Observe as fezes ao mudar a fralda. Se houver risco de prisão de ventre, registe-o na app e acrescente já alimentos ricos em fibra com o Registo de Alimentação.', title_sv = 'Vätskeintag och förstoppning 💧', body_sv = 'Springer barnet mycket men dricker lite? Håll koll på avföringen när du byter blöja. Finns risk för förstoppning, anteckna det i appen och lägg direkt till fiberrik mat med Matningskoll.', title_vi = 'Uống nước và táo bón 💧', body_vi = 'Bé chạy nhiều mà uống ít nước? Hãy để ý phân khi thay tã. Nếu có nguy cơ táo bón, hãy ghi vào ứng dụng và thêm ngay thực phẩm giàu chất xơ bằng Theo dõi cữ bú.', title_zh = '饮水与便秘 💧', body_zh = '跑得多，喝得少？换尿布时留意一下排便。如果有便秘风险，记到应用里，马上用喂养记录工具加入富含纤维的食物。' WHERE id = 'a9e849fb-b58a-4614-9ca7-0396de5c5865' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rituales de la noche 🧸', body_es = '¿Cada noche se duerme abrazado al mismo juguete? Haz inolvidable este dulce momento de seguridad describiéndolo, sin foto, en la sección de notas del Álbum del bebé.', title_fr = 'Rituels du soir 🧸', body_fr = 'Il s''endort chaque soir en serrant le même jouet ? Rendez ce doux moment de confiance inoubliable en le décrivant simplement, sans photo, dans les notes de l''Album de bébé.', title_hi = 'रात की रस्में 🧸', body_hi = 'हर शाम एक ही खिलौने को गले लगाकर सोता है? भरोसे के इस प्यारे पल को बिना तस्वीर, बस शब्दों में बेबी एल्बम के नोट सेक्शन में लिखकर यादगार बनाइए।', title_id = 'Ritual malam 🧸', body_id = 'Setiap malam tidur sambil memeluk mainan yang sama? Abadikan momen rasa aman yang manis ini dengan menuliskannya, tanpa foto, di bagian catatan Album Bayi.', title_ja = '夜の習慣 🧸', body_ja = '毎晩同じおもちゃを抱きしめて眠りますか？このかわいい安心の瞬間を、写真なしで言葉だけで「ベビーアルバム」のメモ欄に書いて、忘れられない思い出にしましょう。', title_ko = '잠자리 의식 🧸', body_ko = '매일 밤 같은 인형을 안고 자나요? 이 사랑스러운 안정감의 순간을 사진 없이 글로 아기 앨범의 메모란에 적어 잊지 못할 추억으로 만드세요.', title_nl = 'Rituelen voor de nacht 🧸', body_nl = 'Slaapt hij elke avond met hetzelfde knuffeltje in zijn armen? Maak dit lieve moment van vertrouwen onvergetelijk door het zonder foto te beschrijven in de notities van het Babyalbum.', title_pl = 'Wieczorne rytuały 🧸', body_pl = 'Każdego wieczoru zasypia, tuląc tę samą zabawkę? Uczyń tę słodką chwilę poczucia bezpieczeństwa niezapomnianą, opisując ją bez zdjęcia w notatkach Albumu dziecka.', title_pt = 'Rituais da noite 🧸', body_pt = 'Todas as noites adormece abraçado ao mesmo brinquedo? Torne inesquecível este doce momento de confiança, escrevendo-o sem foto, só como descrição, na secção de notas do Álbum do Bebé.', title_sv = 'Kvällsritualer 🧸', body_sv = 'Somnar barnet varje kväll med samma leksak i famnen? Gör den söta trygghetsstunden oförglömlig genom att skriva ner den, utan bild, bara som en beskrivning i anteckningsdelen av Babyalbumet.', title_vi = 'Nghi thức buổi tối 🧸', body_vi = 'Tối nào bé cũng ôm cùng một món đồ chơi khi ngủ? Hãy ghi lại khoảnh khắc an tâm đáng yêu này bằng lời trong phần ghi chú của Album của bé để không bao giờ quên.', title_zh = '睡前仪式 🧸', body_zh = '每晚都抱着同一个玩具睡觉？不用照片，只用文字把这个充满安全感的可爱时刻写进宝宝相册的笔记里，让它难以忘怀。' WHERE id = '3112ae5c-eae2-4dc5-ae42-0bb7f83e1fdb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Primeros intentos de amistad 👶', body_es = '¿En el parque le interesa el juguete de otro niño y le hace sonidos? Descubre cómo apoyar esta etapa de socialización charlando con otras madres en Lugares para mamás.', title_fr = 'Premiers essais d''amitié 👶', body_fr = 'Au parc, il s''intéresse au jouet d''un autre enfant et fait des sons ? Découvrez comment soutenir cette étape de socialisation en discutant avec d''autres mamans dans les Lieux adaptés aux mamans.', title_hi = 'दोस्ती की पहली कोशिशें 👶', body_hi = 'पार्क में दूसरे बच्चे के खिलौने में दिलचस्पी दिखाता है, आवाज़ें निकालता है? मेल-जोल के इस दौर में उसका साथ कैसे दें, यह माँ के लिए अनुकूल जगहें में दूसरी माँओं से बात करके जानिए।', title_id = 'Mencoba berteman 👶', body_id = 'Di taman ia tertarik pada mainan anak lain dan mengeluarkan suara? Temukan cara mendukung tahap sosialisasi ini dengan mengobrol bersama ibu-ibu lain di Tempat Ramah Ibu.', title_ja = 'はじめてのお友だち 👶', body_ja = '公園でほかの子のおもちゃに興味を示して、声を出していますか？この社会性の段階をどう応援すればいいか、「ママにやさしいスポット」でほかのママとおしゃべりして見つけましょう。', title_ko = '첫 친구 사귀기 👶', body_ko = '공원에서 다른 아이의 장난감에 관심을 보이며 소리를 내나요? 엄마 친화 장소에서 다른 엄마들과 이야기하며 이 사회성 발달 단계를 돕는 법을 알아보세요.', title_nl = 'Eerste pogingen tot vriendschap 👶', body_nl = 'Toont hij in het park interesse in het speelgoed van een ander kind en maakt hij geluidjes? Ontdek hoe je deze fase van socialisatie steunt door met andere moeders te kletsen in Mamavriendelijke plekken.', title_pl = 'Pierwsze próby przyjaźni 👶', body_pl = 'W parku interesuje się zabawką innego dziecka i wydaje dźwięki? Dowiedz się, jak wspierać ten etap uspołecznienia, rozmawiając z innymi mamami w Miejscach przyjaznych mamom.', title_pt = 'As primeiras tentativas de amizade 👶', body_pt = 'No parque mostra interesse pelo brinquedo de outra criança e faz sons? Descubra como apoiar esta fase da socialização conversando com outras mães nos Locais Amigos das Mães.', title_sv = 'Första försöken till vänskap 👶', body_sv = 'Visar barnet intresse för ett annat barns leksak i parken och låter? Upptäck hur du kan stötta detta sociala stadium genom att prata med andra mammor i Mammavänliga platser.', title_vi = 'Những lần đầu kết bạn 👶', body_vi = 'Ở công viên bé tò mò về đồ chơi của bạn khác và líu lo? Hãy trò chuyện với các mẹ khác ở Địa điểm thân thiện với mẹ để khám phá cách hỗ trợ giai đoạn hòa nhập xã hội này.', title_zh = '第一次尝试交朋友 👶', body_zh = '在公园对别的小朋友的玩具感兴趣，还发出声音？在妈妈友好场所里和其他妈妈聊聊，了解如何支持这个社交阶段。' WHERE id = '363e202f-bc22-4752-9313-7e506d91cf84' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño médico en acción 🩺', body_es = '¿Le pone una inyección a su osito o le escucha la barriga? ¡Los juegos de imaginación están en su mejor momento! Lee en el Blog el increíble efecto de los juegos de rol en el desarrollo de la inteligencia.', title_fr = 'Petit docteur au travail 🩺', body_fr = 'Il fait une piqûre à son nounours ou écoute son ventre ? Les jeux d''imagination sont à leur sommet ! Lisez dans la rubrique Blogs l''effet incroyable des jeux de rôle sur le développement de l''intelligence.', title_hi = 'नन्हा डॉक्टर काम पर 🩺', body_hi = 'अपने भालू को इंजेक्शन लगाता है या उसका पेट सुनता है? कल्पना वाले खेल चरम पर हैं! ब्लॉग सेक्शन में पढ़िए कि रोल प्ले बुद्धि के विकास पर कितना कमाल का असर डालते हैं।', title_id = 'Dokter cilik sedang bertugas 🩺', body_id = 'Menyuntik boneka beruangnya, atau mendengarkan perutnya? Permainan imajinasi sedang di puncaknya! Baca di bagian Blog pengaruh luar biasa permainan peran pada kecerdasan.', title_ja = '小さなお医者さんが診察中 🩺', body_ja = 'くまさんに注射をしたり、おなかの音を聞いたりしていますか？ごっこ遊びが真っ盛りです！ごっこ遊びが知性の発達に与えるすごい効果について、ブログで読んでみましょう。', title_ko = '꼬마 의사 진료 중 🩺', body_ko = '곰 인형에게 주사를 놓거나 배에 귀를 대 보나요? 상상 놀이가 한창이에요! 역할 놀이가 두뇌 발달에 주는 놀라운 효과를 블로그에서 읽어 보세요.', title_nl = 'Kleine dokter aan het werk 🩺', body_nl = 'Geeft hij zijn beer een prik of luistert hij naar zijn buik? Het fantasiespel is op zijn hoogtepunt! Lees in Blogs over de ongelofelijke invloed van rollenspel op de ontwikkeling van zijn verstand.', title_pl = 'Mały lekarz przy pracy 🩺', body_pl = 'Robi misiowi zastrzyk albo osłuchuje mu brzuszek? Zabawy w udawanie są w pełnym rozkwicie! Przeczytaj w sekcji Blog o niesamowitym wpływie zabaw w role na rozwój umysłu.', title_pt = 'Pequeno médico em ação 🩺', body_pt = 'Dá uma injeção ao ursinho ou ouve-lhe a barriga? As brincadeiras de imaginação estão no auge! Leia nos Blogues o efeito incrível dos jogos de papéis no desenvolvimento da inteligência.', title_sv = 'Den lilla doktorn i farten 🩺', body_sv = 'Ger barnet nallen en spruta eller lyssnar på magen? Låtsaslekarna är på topp! Läs i Bloggar om rollekarnas otroliga inverkan på tankeutvecklingen.', title_vi = 'Bác sĩ nhí đang làm việc 🩺', body_vi = 'Bé tiêm cho gấu bông hay nghe bụng gấu? Trò chơi tưởng tượng đang ở đỉnh cao! Hãy đọc trong mục Blog về tác động đáng kinh ngạc của trò chơi nhập vai đối với sự phát triển trí tuệ.', title_zh = '小医生上班啦 🩺', body_zh = '给小熊打针，或者听听它的肚子？想象游戏正处于巅峰！去博客板块读读角色扮演游戏对智力发展的惊人影响。' WHERE id = 'a11c68a5-ec27-4659-9acb-bdcc422f80f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se ha despertado con el pañal totalmente seco? 🩲', body_es = '¿Al cambiar el pañal de la mañana has notado que estaba seco? ¡Es la señal principal de que físicamente está preparado para el orinal! Anótalo en el Seguimiento de pañales y sigue las estadísticas con atención.', title_fr = 'Réveillé avec une couche toute sèche ? 🩲', body_fr = 'Vous avez remarqué que la couche du matin était sèche ? C''est le signe principal qu''il est physiquement prêt pour le pot ! Notez-le dans le Suivi des couches et suivez attentivement les statistiques.', title_hi = 'बिल्कुल सूखे डायपर के साथ जागा? 🩲', body_hi = 'सुबह डायपर बदलते समय देखा कि वह सूखा है? यह शारीरिक रूप से पॉटी के लिए तैयार होने का मुख्य संकेत है! डायपर ट्रैकर में दर्ज कीजिए और आँकड़ों पर ध्यान से नज़र रखिए।', title_id = 'Bangun dengan popok kering? 🩲', body_id = 'Saat mengganti popok pagi, Anda melihat popoknya kering? Ini tanda utama bahwa secara fisik ia siap untuk pispot! Catat di Pelacak Popok dan pantau statistiknya dengan cermat.', title_ja = 'おむつがすっかり乾いたまま起きた？🩲', body_ja = '朝のおむつ替えで、乾いていることに気づきましたか？これは体がトイレトレーニングの準備ができている大切なサインです！「おむつトラッカー」に記録して、統計をよく見守りましょう。', title_ko = '기저귀가 완전히 보송한 채로 깼나요? 🩲', body_ko = '아침에 기저귀를 갈 때 말라 있는 걸 알아챘나요? 몸이 배변 훈련 준비가 되었다는 중요한 신호예요! 기저귀 기록에 남기고 통계를 꼼꼼히 살펴보세요.', title_nl = 'Helemaal droog wakker geworden? 🩲', body_nl = 'Was de luier vanochtend droog? Dat is het belangrijkste teken dat hij lichamelijk klaar is voor het potje! Noteer het in de Luiertracker en volg de statistieken goed.', title_pl = 'Obudził się z zupełnie suchą pieluszką? 🩲', body_pl = 'Przy porannej zmianie zauważyłaś, że pieluszka jest sucha? To główny znak, że fizycznie jest gotowy na nocnik! Zapisz to w narzędziu do śledzenia pieluszek i uważnie obserwuj statystyki.', title_pt = 'Acordou com a fralda completamente seca? 🩲', body_pt = 'Ao mudar a fralda da manhã, reparou que estava seca? É o principal sinal de que está fisicamente pronto para o bacio! Registe-o no Registo de Fraldas e acompanhe as estatísticas com atenção.', title_sv = 'Vaknade med helt torr blöja? 🩲', body_sv = 'Märkte du att blöjan var torr när du bytte på morgonen? Det är det viktigaste tecknet på att barnet fysiskt är redo för pottan! Anteckna i Blöjkollen och följ statistiken noga.', title_vi = 'Tã khô hoàn toàn khi thức dậy? 🩲', body_vi = 'Mẹ để ý tã khô khi thay buổi sáng? Đây là dấu hiệu chính cho thấy cơ thể bé đã sẵn sàng ngồi bô! Hãy ghi lại trong Theo dõi tã và theo dõi kỹ thống kê.', title_zh = '醒来时尿布完全是干的？🩲', body_zh = '早上换尿布时发现是干的？这是身体上已准备好用便盆的主要信号！记在尿布记录里，仔细留意统计数据。' WHERE id = '053139e2-7d9f-4a00-9462-2ddb17d7e133' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin azúcar, pero dulce 🍪', body_es = '¿Quiere merendar? No hacen falta galletas del súper. Descubre en Recetas para bebé dulces sanos de dátiles y avena que se preparan en 10 minutos.', title_fr = 'Sans sucre, mais sucré 🍪', body_fr = 'Il réclame un goûter ? Pas besoin de biscuits du commerce. Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à l''avoine, prêtes en 10 minutes.', title_hi = 'बिना चीनी, फिर भी मीठा 🍪', body_hi = 'दोपहर का स्नैक चाहिए? बाज़ार के बिस्किट की ज़रूरत नहीं। बच्चों की रेसिपी में 10 मिनट में बनने वाली खजूर और ओट्स की सेहतमंद मिठाइयाँ खोजिए।', title_id = 'Tanpa gula, tapi manis 🍪', body_id = 'Ingin camilan siang? Tak perlu biskuit dari toko. Temukan camilan manis sehat dari kurma dan oat yang siap dalam 10 menit di Resep Bayi.', title_ja = '砂糖なしでも甘い 🍪', body_ja = 'お昼のおやつがほしい？市販のクッキーはいりません。「離乳食を始める赤ちゃんのレシピ」で、10分でつくれるデーツとオートミールのヘルシーなおやつを見つけましょう。', title_ko = '설탕 없이도 달콤하게 🍪', body_ko = '오후 간식을 찾나요? 마트 쿠키는 필요 없어요. 아기 레시피에서 10분이면 만드는 대추야자 귀리 건강 간식을 찾아보세요.', title_nl = 'Zonder suiker, maar zoet 🍪', body_nl = 'Wil hij ''s middags een tussendoortje? Koekjes uit de winkel zijn niet nodig. Ontdek in Babyrecepten gezonde lekkernijen met dadels en havermout, klaar in 10 minuten.', title_pl = 'Bez cukru, ale słodko 🍪', body_pl = 'Chce popołudniowej przekąski? Sklepowe ciastka nie są potrzebne. Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i płatkami owsianymi gotowe w 10 minut.', title_pt = 'Sem açúcar, mas doce 🍪', body_pt = 'Quer um lanche à tarde? Não precisa de bolachas do supermercado. Descubra nas Receitas para bebés doces saudáveis de tâmaras e aveia, prontos em 10 minutos.', title_sv = 'Sockerfritt, men sött 🍪', body_sv = 'Vill barnet ha ett mellanmål på eftermiddagen? Ni behöver inga kex från affären. Upptäck nyttiga sötsaker med dadlar och havre som är klara på 10 minuter i Recept för bebisar.', title_vi = 'Không đường mà vẫn ngọt 🍪', body_vi = 'Bé đòi ăn vặt buổi chiều? Không cần bánh quy mua sẵn. Hãy khám phá các món ngọt bổ dưỡng từ chà là và yến mạch làm trong 10 phút trong Công thức cho bé.', title_zh = '无糖，却很甜 🍪', body_zh = '下午想吃点心？不需要超市的饼干。在宝宝食谱里发现10分钟就能做好的椰枣燕麦健康甜点。' WHERE id = 'd7110781-b463-4661-96ac-270a072de535' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos bien la rutina ⏱️', body_es = '¿Por la noche tardó 40 minutos en dormirse? Mira el gráfico del temporizador de sueño. Quizá sea el momento de acortar la siesta 20 minutos y adelantar la hora de dormir.', title_fr = 'Analysons son rythme en détail ⏱️', body_fr = 'Il a mis 40 minutes à s''endormir ce soir ? Regardez le graphique du minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 20 minutes et avancer le coucher.', title_hi = 'रूटीन का पूरा विश्लेषण करें ⏱️', body_hi = 'शाम को सोने में 40 मिनट लग गए? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद 20 मिनट कम करने और शाम की नींद जल्दी करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Butuh 40 menit untuk tertidur malam ini? Lihat grafik Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 20 menit dan memajukan jam tidur malam.', title_ja = '生活リズムをしっかり分析しよう ⏱️', body_ja = '夜、寝つくまで40分かかりましたか？睡眠タイマーのグラフを見てみましょう。お昼寝を20分短くして、夜の寝る時間を早めるちょうどいいタイミングかもしれません。', title_ko = '일과를 제대로 분석해 봐요 ⏱️', body_ko = '저녁에 잠드는 데 40분이 걸렸나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 20분 줄이고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme goed analyseren ⏱️', body_nl = 'Duurde het inslapen vanavond 40 minuten? Bekijk de grafiek van de Slaaptimer. Misschien is het precies tijd om het middagdutje met 20 minuten in te korten en de bedtijd te vervroegen.', title_pl = 'Dokładnie przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorne zasypianie trwało 40 minut? Spójrz na wykres timera snu. Może to dobry moment, by skrócić drzemkę o 20 minut i przesunąć wieczorne spanie wcześniej.', title_pt = 'Vamos analisar a rotina a fundo ⏱️', body_pt = 'À noite demorou 40 minutos a adormecer? Veja o gráfico do temporizador de sono. Talvez seja a altura certa de encurtar a sesta 20 minutos e antecipar a hora de deitar.', title_sv = 'Vi analyserar rytmen ordentligt ⏱️', body_sv = 'Tog det 40 minuter att somna i kväll? Titta på grafen i sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 20 minuter och tidigarelägga kvällen.', title_vi = 'Cùng phân tích toàn bộ nếp sinh hoạt ⏱️', body_vi = 'Tối qua bé mất 40 phút mới ngủ? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 20 phút và cho bé ngủ tối sớm hơn.', title_zh = '来全面分析一下作息 ⏱️', body_zh = '晚上入睡花了40分钟？看看睡眠计时器的图表。也许正是把白天小睡缩短20分钟、把晚上就寝时间提前的时候了。' WHERE id = 'f9924ca2-641b-4911-b60a-55193623479d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de tirarlo todo al suelo 🛑', body_es = '¿Cuando se enfada o se agobia, tira lo que tiene en la mano? Pregunta a Anacan AI cómo reconducir con suavidad estas reacciones emocionales.', title_fr = 'L''envie de tout jeter par terre 🛑', body_fr = 'Il lance ce qu''il a dans les mains quand il se fâche ou se sent frustré ? Demandez à Anacan AI comment orienter en douceur ces réactions émotionnelles.', title_hi = 'सब कुछ नीचे फेंकने का शौक 🛑', body_hi = 'गुस्से या ऊब में हाथ की चीज़ घुमाकर फेंक देता है? इन भावनात्मक प्रतिक्रियाओं को नरमी से सही दिशा कैसे दें, यह Anacan AI से पूछिए।', title_id = 'Hobi melempar segalanya 🛑', body_id = 'Mengayunkan dan melempar barang di tangannya saat marah atau kesal? Tanyakan kepada Anacan AI cara mengarahkan reaksi emosional ini dengan lembut.', title_ja = 'なんでも床に投げたい 🛑', body_ja = '怒ったり、イライラしたりすると、手に持ったものを振り回して投げますか？こうした気持ちの反応をやさしく導く方法を、Anacan AIに聞いてみましょう。', title_ko = '뭐든 바닥에 던지고 싶어요 🛑', body_ko = '화가 나거나 답답하면 손에 든 걸 휘둘러 던지나요? 이런 감정 반응을 부드럽게 이끌어 주는 방법을 Anacan AI에게 물어보세요.', title_nl = 'Zin om alles op de grond te gooien 🛑', body_nl = 'Smijt hij weg wat hij vasthoudt als hij boos of gefrustreerd is? Vraag Anacan AI hoe je deze emotionele reacties zacht bijstuurt.', title_pl = 'Ochota na rzucanie wszystkim 🛑', body_pl = 'Gdy się złości lub denerwuje, rzuca tym, co ma w rękach? Zapytaj Anacan AI, jak łagodnie kierować tymi reakcjami emocjonalnymi.', title_pt = 'A mania de atirar tudo ao chão 🛑', body_pt = 'Quando se zanga ou se aborrece, atira o que tem na mão? Pergunte ao Anacan AI como orientar com suavidade estas reações emocionais.', title_sv = 'Lust att kasta allt på golvet 🛑', body_sv = 'Slänger barnet iväg det hen håller i när hen är arg eller frustrerad? Fråga Anacan AI hur du varsamt kan styra dessa känslomässiga reaktioner.', title_vi = 'Mê ném mọi thứ xuống sàn 🛑', body_vi = 'Khi tức giận hoặc bức bối, bé vung tay ném đồ đang cầm? Hãy hỏi Anacan AI cách nhẹ nhàng định hướng những phản ứng cảm xúc này.', title_zh = '什么都想往地上扔 🛑', body_zh = '生气或烦躁时就把手里的东西甩出去？问问Anacan AI，如何温和地引导这些情绪反应。' WHERE id = '5f435409-af45-4f28-ad39-0362ac580462' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Las camisetas se le quedan cortas! 📏', body_es = '¿Al vestirle has notado que las mangas le aprietan? ¡Cerca de los 2 años hay un estirón! Introduce su talla actual en el Seguimiento del desarrollo y mira con orgullo su curva de crecimiento.', title_fr = 'Les t-shirts raccourcissent ! 📏', body_fr = 'En l''habillant, vous avez senti que les manches serraient ? C''est un pic de croissance à l''approche des 2 ans ! Entrez sa taille actuelle dans le Suivi de croissance et regardez fièrement sa courbe.', title_hi = 'कमीज़ें छोटी हो रही हैं! 📏', body_hi = 'कपड़े पहनाते समय लगा कि आस्तीनें तंग हो गई हैं? 2 साल के करीब शारीरिक विकास में उछाल है! ग्रोथ ट्रैकर में मौजूदा लंबाई दर्ज कीजिए और गर्व से ग्रोथ कर्व देखिए।', title_id = 'Bajunya kekecilan! 📏', body_id = 'Merasa lengan bajunya sempit saat memakaikannya? Ada lonjakan pertumbuhan fisik menjelang usia 2 tahun! Masukkan tinggi badannya saat ini ke Pelacak Perkembangan dan lihat kurva pertumbuhannya dengan bangga.', title_ja = 'シャツが短くなってきた！📏', body_ja = '着替えさせるときに、袖がきつくなっていると感じましたか？2歳に向けて体がぐんと成長しています！「発達トラッカー」に今の身長を入力して、成長曲線を誇らしく眺めましょう。', title_ko = '셔츠가 짧아져요! 📏', body_ko = '옷을 입힐 때 소매가 끼는 걸 느꼈나요? 두 돌을 앞두고 신체 성장 급등기예요! 성장 기록에 현재 키를 입력하고 성장 곡선을 뿌듯하게 확인하세요.', title_nl = 'De shirtjes worden te kort! 📏', body_nl = 'Merkte je bij het aankleden dat de mouwen krap zitten? Rond 2 jaar is er een groeispurt! Voer zijn huidige lengte in de Groeitracker in en kijk trots naar zijn groeicurve.', title_pl = 'Koszulki za krótkie! 📏', body_pl = 'Przy ubieraniu zauważyłaś, że rękawy są ciasne? W okolicach 2. urodzin następuje skok fizyczny! Wpisz aktualny wzrost w Śledzeniu rozwoju i z dumą spójrz na krzywą rozwoju.', title_pt = 'As camisolas estão a ficar curtas! 📏', body_pt = 'Ao vesti-lo, sentiu que as mangas estavam apertadas? Perto dos 2 anos há um salto físico! Introduza a altura atual no Registo de Desenvolvimento e veja com orgulho a curva de crescimento.', title_sv = 'Tröjorna blir för korta! 📏', body_sv = 'Märkte du att ärmarna blivit trånga när du klädde på barnet? Det är en fysisk spurt mot 2 års ålder! Ange aktuell längd i Utvecklingsspåraren och titta stolt på tillväxtkurvan.', title_vi = 'Áo bị ngắn rồi! 📏', body_vi = 'Khi mặc đồ cho bé, mẹ thấy tay áo chật hơn? Gần 2 tuổi, bé đang tăng trưởng vọt! Hãy nhập chiều cao hiện tại vào Theo dõi phát triển và tự hào ngắm đường cong phát triển.', title_zh = '衣服变短了！📏', body_zh = '穿衣服时发现袖子变紧了？快2岁了，身体正在飞速发育！在发育追踪里输入当前的身高，骄傲地看看成长曲线。' WHERE id = 'cf7b282d-cfc2-4ce1-9f7c-e71f0a8529ba' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y silencio 🍵', body_es = 'El temporizador se ha parado y tu peque duerme. ¡No corras a las tareas de casa! Prepárate una infusión de melisa de Recetas saludables para mujeres y anota los pequeños logros de hoy en el Diario de ánimo.', title_fr = 'Thé chaud et silence 🍵', body_fr = 'Le minuteur est arrêté, il dort. Ne vous ruez pas sur les tâches ménagères ! Préparez une tisane de mélisse des Recettes saines pour femmes et notez vos petites victoires du jour dans le Journal d''humeur.', title_hi = 'गर्म चाय और खामोशी 🍵', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के कामों की ओर मत भागिए! महिलाओं के लिए सेहतमंद रेसिपी से लेमन बाम की चाय बनाइए और मूड डायरी में आज की छोटी-छोटी सफलताएँ लिखिए।', title_id = 'Teh hangat dan keheningan 🍵', body_id = 'Timer berhenti, si kecil sudah tidur. Jangan buru-buru mengerjakan pekerjaan rumah! Seduh teh lemon balm dari Resep Sehat untuk wanita dan catat keberhasilan kecil Anda hari ini di Buku Harian Suasana Hati.', title_ja = '温かいお茶と静けさ 🍵', body_ja = 'タイマーは止まり、お子さんは眠りました。家事に走らないで！「女性のためのヘルシーレシピ」からレモンバームティーをいれて、「気分日記」に今日の小さな成功を記録しましょう。', title_ko = '따뜻한 차와 고요함 🍵', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일로 달려가지 마세요! 여성을 위한 건강한 레시피에서 레몬밤 차를 우리고 기분 일기에 오늘의 작은 성공을 적어 보세요.', title_nl = 'Warme thee en stilte 🍵', body_nl = 'De timer is gestopt, je kindje slaapt. Ren niet naar het huishouden! Zet citroenmelissethee uit Gezonde recepten voor vrouwen en noteer je kleine successen van vandaag in je Stemmingsdagboek.', title_pl = 'Ciepła herbata i cisza 🍵', body_pl = 'Timer zatrzymany, maluch śpi. Nie rzucaj się w wir obowiązków! Zaparz melisę ze Zdrowych przepisów dla kobiet i zapisz w Dzienniku nastroju swoje dzisiejsze małe sukcesy.', title_pt = 'Chá quente e silêncio 🍵', body_pt = 'O temporizador parou, ele adormeceu. Não corra para as tarefas da casa! Prepare um chá de erva-cidreira das Receitas Saudáveis para Mulheres e registe no Diário de Humor as pequenas vitórias de hoje.', title_sv = 'Varmt te och tystnad 🍵', body_sv = 'Timern har stannat, barnet sover. Rusa inte till hushållssysslorna! Brygg citronmelissate från Hälsosamma recept för kvinnor och anteckna dagens små framgångar i Humördagboken.', title_vi = 'Trà nóng và sự yên tĩnh 🍵', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Đừng vội lao vào việc nhà! Hãy pha trà tía tô đất từ Công thức lành mạnh cho phụ nữ và ghi lại những thành công nhỏ hôm nay trong Nhật ký tâm trạng.', title_zh = '热茶与安静 🍵', body_zh = '计时器停了，孩子睡着了。别急着去做家务！从女性健康食谱里泡一杯香蜂草茶，在心情日记里记下今天的小成就。' WHERE id = 'd1b0bfba-8ace-4234-8eb6-40647f25ce47' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza del hierro 🥩', body_es = 'Para que tu peque tan activo no tenga anemia y siga lleno de energía, comprueba en el Seguimiento de tomas el hierro de hoy y, si falta, ajusta su menú.', title_fr = 'La force du fer 🥩', body_fr = 'Pour que votre petit actif ne manque pas de fer et garde son énergie, vérifiez ses apports en fer du jour dans le Suivi des repas et ajustez son menu si besoin.', title_hi = 'आयरन की ताकत 🥩', body_hi = 'चंचल नन्हे को खून की कमी न हो और वह ऊर्जा से भरा रहे, इसके लिए फ़ीडिंग ट्रैकर में आज का आयरन जाँचिए और कमी हो तो मेन्यू ठीक कीजिए।', title_id = 'Kekuatan zat besi 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia dan tetap berenergi, cek asupan zat besi hari ini di alat Pemantau Nutrisi dan sesuaikan menunya jika ada kekurangan.', title_ja = '鉄分の力 🥩', body_ja = '活発なお子さんが貧血にならず元気でいられるよう、「栄養管理ツール」で今日の鉄分の摂取量を確認し、足りなければメニューを調整しましょう。', title_ko = '철분의 힘 🥩', body_ko = '활발한 아이가 빈혈 없이 활기차게 지내도록 수유 기록 도구로 오늘의 철분 섭취를 확인하고, 부족하다면 식단을 조절하세요.', title_nl = 'De kracht van ijzer 🥩', body_nl = 'Controleer in de Voedingstracker het ijzer van vandaag en pas bij een tekort het menu aan, zodat je actieve kleintje geen bloedarmoede krijgt en energiek blijft.', title_pl = 'Siła żelaza 🥩', body_pl = 'Aby aktywny maluch nie miał anemii i był pełen energii, sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza, a jeśli czegoś brakuje, dopasuj menu.', title_pt = 'A força do ferro 🥩', body_pt = 'Para que o seu pequenino tão ativo não tenha anemia e continue cheio de energia, verifique no Registo de Alimentação o ferro de hoje e, se faltar, ajuste a ementa.', title_sv = 'Järnets kraft 🥩', body_sv = 'Kontrollera dagens järnintag i Matningskoll så att din aktiva lilla inte får blodbrist och håller energin uppe, och justera menyn om något fattas.', title_vi = 'Sức mạnh của sắt 🥩', body_vi = 'Để bé hiếu động không bị thiếu máu và luôn tràn đầy năng lượng, hãy kiểm tra lượng sắt hôm nay trong Theo dõi cữ bú và điều chỉnh thực đơn nếu còn thiếu.', title_zh = '铁的力量 🥩', body_zh = '为了让活泼的小家伙不贫血、精力充沛，在喂养记录工具里查看今天的铁摄入量，如有不足就调整菜单。' WHERE id = '1c764980-a64f-44cc-b47e-9bb7c39ae099' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La magia de la monotonía 🌬️', body_es = 'Al apagar la tele, el silencio repentino le inquieta. Pon en la habitación el sonido del ventilador o del secador de Ruido blanco y verás qué sensación de seguridad crea para dormir.', title_fr = 'La magie de la monotonie 🌬️', body_fr = 'Après la télé éteinte, le silence soudain l''inquiète. Lancez dans la chambre le bruit de ventilateur ou de sèche-cheveux des Bruits blancs et voyez comme il crée un sentiment de sécurité pour dormir.', title_hi = 'एक जैसी आवाज़ का जादू 🌬️', body_hi = 'टीवी बंद होने के बाद अचानक की खामोशी उसे बेचैन करती है। कमरे में व्हाइट नॉइज़ से पंखे या हेयर ड्रायर की आवाज़ चलाइए और देखिए कि यह नींद के माहौल में कैसे सुरक्षा का एहसास देती है।', title_id = 'Keajaiban suara monoton 🌬️', body_id = 'Setelah TV dimatikan, hening yang tiba-tiba membuatnya gelisah. Putar suara kipas angin atau pengering rambut dari Suara Putih di kamar dan lihat bagaimana suara itu menciptakan rasa aman saat tidur.', title_ja = '単調な音の魔法 🌬️', body_ja = 'テレビを消したあとの急な静けさが、お子さんを不安にさせます。部屋で「ホワイトノイズ」の扇風機やドライヤーの音を流して、眠りの環境にどれほど安心感が生まれるか確かめてみましょう。', title_ko = '단조로운 소리의 마법 🌬️', body_ko = 'TV를 끈 뒤의 갑작스러운 정적이 아이를 불안하게 하나요? 백색소음에서 선풍기나 헤어드라이어 소리를 틀어 수면 환경에 어떻게 안정감을 주는지 확인해 보세요.', title_nl = 'De magie van eentonigheid 🌬️', body_nl = 'Na het uitzetten van de tv kan plotselinge stilte hem onrustig maken. Zet in de kamer het geluid van een ventilator of föhn uit Witte ruis aan en zie hoe het zijn slaapomgeving een veilig gevoel geeft.', title_pl = 'Magia monotonii 🌬️', body_pl = 'Nagła cisza po wyłączeniu telewizora go niepokoi. Włącz w pokoju odgłos wentylatora lub suszarki z Białego szumu i zobacz, jak daje mu poczucie bezpieczeństwa podczas snu.', title_pt = 'A magia da monotonia 🌬️', body_pt = 'Depois de desligar a televisão, o silêncio repentino deixa-o inquieto. Ligue no quarto o som da ventoinha ou do secador de cabelo do Ruído Branco e veja como cria uma sensação de segurança no ambiente de sono.', title_sv = 'Magin i monotona ljud 🌬️', body_sv = 'Plötslig tystnad efter att tv:n stängts av kan oroa barnet. Sätt på fläkt- eller hårtorksljud från Vitt brus i rummet och se hur det skapar en känsla av trygghet i sömnmiljön.', title_vi = 'Phép màu của âm thanh đều đều 🌬️', body_vi = 'Sau khi tắt TV, sự im lặng đột ngột khiến bé bất an. Hãy bật tiếng quạt hoặc máy sấy tóc trong Tiếng ồn trắng và xem âm thanh này tạo cảm giác an toàn cho giấc ngủ thế nào.', title_zh = '单调声音的魔力 🌬️', body_zh = '关掉电视后，突然的安静会让宝宝不安。在房间里打开白噪音里的风扇或吹风机声，看看它如何在睡眠环境中带来安全感。' WHERE id = '2754ee28-07df-42f6-ba7d-9d86b1edf758' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de las manos pintadas 🎨', body_es = '¿Jugando con colores se ha pintado toda la cara? En lugar de enfadarte, fotografía ya este momento creativo y divertido y añádelo al álbum como el recuerdo más colorido.', title_fr = 'L''art des mains peintes 🎨', body_fr = 'En jouant avec les couleurs, il s''en est mis plein le visage ? Au lieu de vous énerver, photographiez tout de suite ce moment drôle et créatif et ajoutez-le à l''album comme le souvenir le plus coloré.', title_hi = 'रंगे हाथों की कला 🎨', body_hi = 'रंगों से खेलते हुए पूरा चेहरा रंग लिया? गुस्सा होने के बजाय इस मज़ेदार, रचनात्मक पल की तुरंत तस्वीर लीजिए और एल्बम में सबसे रंगीन याद के रूप में जोड़िए।', title_id = 'Seni tangan penuh cat 🎨', body_id = 'Wajahnya penuh cat saat bermain warna? Daripada kesal, segera abadikan momen lucu dan kreatif ini dan tambahkan ke album sebagai kenangan paling berwarna.', title_ja = '絵の具の手でアート 🎨', body_ja = '色で遊んでいて、顔じゅう絵の具だらけに？怒る代わりに、このおもしろくて創造的な瞬間をすぐに撮影して、いちばんカラフルな思い出としてアルバムに追加しましょう。', title_ko = '물감 묻은 손의 예술 🎨', body_ko = '물감 놀이를 하다 얼굴이 온통 물감투성이가 되었나요? 화내는 대신 이 재미있고 창의적인 순간을 바로 찍어 앨범의 가장 알록달록한 추억으로 남기세요.', title_nl = 'Kunst met verfhandjes 🎨', body_nl = 'Zit zijn hele gezicht onder de verf na het spelen met kleuren? Word niet boos, maar leg dit grappige, creatieve moment meteen vast en zet het als kleurrijkste herinnering in het album.', title_pl = 'Sztuka umazanych rączek 🎨', body_pl = 'Bawiąc się farbami, umazał całą buzię? Zamiast się złościć, od razu uwiecznij tę zabawną, twórczą chwilę i dodaj do albumu jako najbardziej kolorową pamiątkę.', title_pt = 'A arte das mãos pintadas 🎨', body_pt = 'A brincar com as cores, sujou a cara toda? Em vez de se enervar, fotografe já este momento divertido e criativo e adicione-o ao álbum como a recordação mais colorida.', title_sv = 'Konsten med färgglada händer 🎨', body_sv = 'Har barnet kladdat ner hela ansiktet när hen lekte med färger? I stället för att bli irriterad, fotografera direkt detta roliga och kreativa ögonblick och lägg till det i albumet som det mest färgglada minnet.', title_vi = 'Nghệ thuật bàn tay đầy màu 🎨', body_vi = 'Chơi màu mà lem luốc cả mặt mũi? Thay vì bực mình, hãy chụp ngay khoảnh khắc sáng tạo vui nhộn này và thêm vào album như kỷ niệm rực rỡ nhất.', title_zh = '彩色小手的艺术 🎨', body_zh = '玩颜料时把脸都涂花了？与其生气，不如马上拍下这个有趣又有创意的瞬间，作为最多彩的回忆加进相册。' WHERE id = '301a1109-2563-49a6-a096-aa057de78fa7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Que cuente él el cuento 📖', body_es = '¿Mira los dibujos del libro y cuenta cosas en su propio idioma? Añade ya este momento de imaginación en vídeo con sonido al Álbum del bebé y guárdalo para el futuro.', title_fr = 'Laissez-le raconter l''histoire 📖', body_fr = 'Il regarde les images du livre et raconte des choses dans sa langue à lui ? Ajoutez tout de suite ce beau moment d''imagination en vidéo avec le son à l''Album de bébé pour le garder.', title_hi = 'कहानी उसे सुनाने दीजिए 📖', body_hi = 'किताब की तस्वीरें देखकर अपनी भाषा में कुछ बोलता है? कल्पना के इस शानदार पल को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़कर भविष्य के लिए सहेजिए।', title_id = 'Biarkan ia yang bercerita 📖', body_id = 'Ia melihat gambar di buku dan bercerita dengan bahasanya sendiri? Segera simpan momen imajinasi yang luar biasa ini sebagai video bersuara di Album Bayi untuk masa depan.', title_ja = 'お話はお子さんにおまかせ 📖', body_ja = '絵本の絵を見ながら、自分の言葉で何かお話ししていますか？このすばらしい想像力の瞬間を、すぐに音声付きの動画で「ベビーアルバム」に追加して、未来に残しましょう。', title_ko = '이야기는 아이가 들려줘요 📖', body_ko = '책 속 그림을 보며 자기만의 말로 무언가를 이야기하나요? 이 멋진 상상의 순간을 바로 소리가 담긴 영상으로 아기 앨범에 올려 간직하세요.', title_nl = 'Laat hem het verhaal vertellen 📖', body_nl = 'Kijkt hij naar de plaatjes in een boek en vertelt hij iets in zijn eigen taal? Zet dit prachtige fantasiemoment meteen als video met geluid in het Babyalbum en bewaar het voor later.', title_pl = 'Niech on opowie bajkę 📖', body_pl = 'Ogląda obrazki w książce i coś opowiada po swojemu? Od razu dodaj tę wspaniałą chwilę wyobraźni jako film z dźwiękiem do Albumu dziecka i zachowaj na przyszłość.', title_pt = 'Deixe-o contar a história 📖', body_pt = 'Olha para as imagens do livro e conta qualquer coisa na sua língua? Adicione já este momento maravilhoso de imaginação em vídeo com som ao Álbum do Bebé e guarde-o para o futuro.', title_sv = 'Låt barnet berätta sagan 📖', body_sv = 'Tittar barnet på bilderna i boken och berättar något på sitt eget språk? Spela in detta fantastiska fantasiögonblick som video med ljud, lägg det i Babyalbumet och spara det för framtiden.', title_vi = 'Để bé kể chuyện 📖', body_vi = 'Bé nhìn tranh trong sách và líu lo kể bằng ngôn ngữ của riêng mình? Hãy quay ngay video có tiếng khoảnh khắc tưởng tượng tuyệt vời này và lưu vào Album của bé.', title_zh = '让宝宝来讲故事 📖', body_zh = '看着书里的图画，用自己的语言说着什么？马上把这个了不起的想象时刻录成有声视频加进宝宝相册，留给未来。' WHERE id = '194c05a1-f79c-496c-b1f4-f1316b804846' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Zona segura para correr 🏃‍♀️', body_es = '¿En casa no consigue gastar energía y lo desordena todo? Abre el mapa de Lugares para mamás, busca un parque con una zona segura para correr y salid a tomar aire fresco.', title_fr = 'Un espace sûr pour courir 🏃‍♀️', body_fr = 'Il ne peut pas se dépenser à la maison et met tout sens dessus dessous ? Ouvrez la carte des Lieux adaptés aux mamans, trouvez un parc avec un espace sûr pour courir et sortez prendre l''air.', title_hi = 'दौड़ने की सुरक्षित जगह 🏃‍♀️', body_hi = 'घर के अंदर ऊर्जा नहीं निकाल पाता और सब कुछ बिखेर देता है? माँ के लिए अनुकूल जगहें का नक्शा खोलिए, दौड़ने की सुरक्षित जगह वाला पार्क ढूँढिए और ताज़ी हवा में निकलिए।', title_id = 'Area lari yang aman 🏃‍♀️', body_id = 'Tak bisa menyalurkan energi di dalam rumah dan mengacak-acak segalanya? Buka peta Tempat Ramah Ibu, temukan taman dengan area lari yang aman, dan hirup udara segar.', title_ja = '安全に走れる場所 🏃‍♀️', body_ja = '家の中でエネルギーを発散できず、なんでも散らかしていますか？「ママにやさしいスポット」のマップを開いて、安全に走れる公園を見つけ、新鮮な空気を吸いに出かけましょう。', title_ko = '안전하게 뛰어놀 공간 🏃‍♀️', body_ko = '집 안에서 에너지를 다 쓰지 못해 다 어지르나요? 엄마 친화 장소 지도를 열어 안전하게 뛸 수 있는 공원을 찾아 맑은 공기를 마시러 나가세요.', title_nl = 'Veilige renplek 🏃‍♀️', body_nl = 'Kan hij binnen zijn energie niet kwijt en haalt hij alles overhoop? Open de kaart Mamavriendelijke plekken, zoek een park met een veilige renplek en ga naar buiten.', title_pl = 'Bezpieczne miejsce do biegania 🏃‍♀️', body_pl = 'Nie może rozładować energii w domu i wszystko rozrzuca? Otwórz mapę Miejsc przyjaznych mamom, znajdź park z bezpiecznym miejscem do biegania i wyjdźcie na świeże powietrze.', title_pt = 'Um espaço seguro para correr 🏃‍♀️', body_pt = 'Não consegue gastar energia em casa e desarruma tudo? Abra o mapa dos Locais Amigos das Mães, encontre um parque com espaço seguro para correr e vão apanhar ar puro.', title_sv = 'Säker yta att springa på 🏃‍♀️', body_sv = 'Kan barnet inte få ut energin inomhus och river ner allt? Öppna kartan i Mammavänliga platser, hitta en park med säker yta att springa på och gå ut i friska luften.', title_vi = 'Khu chạy nhảy an toàn 🏃‍♀️', body_vi = 'Bé không thể xả năng lượng trong nhà và bày bừa mọi thứ? Hãy mở bản đồ Địa điểm thân thiện với mẹ, tìm một công viên có khu chạy nhảy an toàn và ra ngoài hít thở không khí trong lành.', title_zh = '安全的奔跑场地 🏃‍♀️', body_zh = '在家里释放不了精力，什么都弄得乱七八糟？打开妈妈友好场所地图，找一个有安全跑步区域的公园，出去呼吸新鲜空气。' WHERE id = '81278832-aa98-446b-b9de-87731d74c2b6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Pelea por el vaso equivocado? 🥤', body_es = '¿Se ha montado un drama porque le diste el agua en el vaso azul y no en el rojo? Aprende con Anacan AI a gestionar con calma estas crisis que parecen absurdas.', title_fr = 'La crise du mauvais gobelet ? 🥤', body_fr = 'Tout a explosé parce que vous avez servi l''eau dans le gobelet bleu et pas le rouge ? Découvrez avec Anacan AI comment gérer avec calme ces crises qui semblent absurdes.', title_hi = 'गलत गिलास पर झगड़ा? 🥤', body_hi = 'पानी लाल की जगह नीले गिलास में दिया तो तूफ़ान आ गया? ऐसे बेतुके लगने वाले नखरों को शांति से कैसे संभालें, यह Anacan AI से जानिए।', title_id = 'Drama gelas yang salah? 🥤', body_id = 'Kiamat kecil terjadi karena Anda memberi air di gelas biru, bukan merah? Pelajari dari Anacan AI cara menghadapi tantrum yang tampak absurd ini dengan tenang.', title_ja = '「コップがちがう！」の大騒ぎ？🥤', body_ja = 'お水を赤ではなく青いコップで出したら大騒ぎに？一見ばかげたようなこうしたかんしゃくに落ち着いて対応する方法を、Anacan AIで学びましょう。', title_ko = '''잘못된 컵'' 소동? 🥤', body_ko = '빨간 컵이 아니라 파란 컵에 물을 줬다고 난리가 났나요? 이렇게 엉뚱해 보이는 떼쓰기를 침착하게 다루는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Strijd om de verkeerde beker? 🥤', body_nl = 'Brak de hel los omdat je water in de blauwe beker gaf in plaats van de rode? Leer bij Anacan AI hoe je zulke absurd lijkende buien kalm aanpakt.', title_pl = 'Wojna o zły kubek? 🥤', body_pl = 'Rozpętała się burza, bo dałaś wodę w niebieskim kubku, a nie w czerwonym? Dowiedz się od Anacan AI, jak spokojnie radzić sobie z takimi pozornie absurdalnymi kryzysami.', title_pt = 'A guerra do copo errado? 🥤', body_pt = 'Foi o fim do mundo porque lhe deu água no copo azul e não no vermelho? Aprenda com o Anacan AI a gerir com calma estas crises que parecem absurdas.', title_sv = 'Bråk om fel mugg? 🥤', body_sv = 'Brakade allt loss för att du gav vattnet i den blå muggen i stället för den röda? Lär dig av Anacan AI hur du lugnt kan hantera sådana utbrott som verkar absurda.', title_vi = 'Cuộc chiến vì "nhầm cốc"? 🥤', body_vi = 'Mẹ đưa nước trong cốc xanh thay vì cốc đỏ và bé ăn vạ ầm ĩ? Hãy học từ Anacan AI cách bình tĩnh xử lý những cơn khủng hoảng tưởng như vô lý này.', title_zh = '杯子拿错了引发的战争？🥤', body_zh = '因为用蓝杯子而不是红杯子装水，就天塌了？向Anacan AI学习如何冷静应对这类看似荒唐的崩溃。' WHERE id = 'fe937f54-e4d9-4674-821c-ae81d7c0c2cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares nocturnos ⏱️', body_es = '¡Pon el temporizador de sueño! Analiza con precisión en el gráfico de estadísticas si se trata de terrores nocturnos o de una regresión del sueño y ajusta la rutina.', title_fr = 'Réveils nocturnes ⏱️', body_fr = 'Lancez le minuteur de sommeil ! Analysez précisément sur son graphique statistique s''il s''agit de terreurs nocturnes ou d''une régression du sommeil, puis ajustez son rythme.', title_hi = 'रात में जागना ⏱️', body_hi = 'स्लीप टाइमर चालू कीजिए! टाइमर के आँकड़ों वाले चार्ट से सटीक समझिए कि कहीं यह नाइट टेरर या स्लीप रिग्रेशन तो नहीं, और रूटीन ठीक कीजिए।', title_id = 'Terbangun di malam hari ⏱️', body_id = 'Nyalakan Timer Tidur! Analisis grafik statistik timer dengan akurat untuk melihat apakah ini teror malam atau regresi tidur, lalu atur rutinitasnya.', title_ja = '夜中に起きる ⏱️', body_ja = '睡眠タイマーをオンにしましょう！夜驚症なのか睡眠退行なのか、タイマーの統計グラフでしっかり分析して、生活リズムを整えましょう。', title_ko = '밤에 깨요 ⏱️', body_ko = '수면 타이머를 켜세요! 야경증인지 수면 퇴행인지 타이머의 통계 그래프로 정확히 분석하고 일과를 조절하세요.', title_nl = 'Nachtelijk wakker worden ⏱️', body_nl = 'Zet de Slaaptimer aan! Analyseer in de statistiekgrafiek van de timer of het om nachtangst of een slaapregressie gaat, en pas het ritme aan.', title_pl = 'Nocne pobudki ⏱️', body_pl = 'Włącz timer snu! Na wykresie statystyk dokładnie sprawdzisz, czy to lęki nocne, czy regres snu, i dopasujesz rytm dnia.', title_pt = 'Despertares noturnos ⏱️', body_pt = 'Ligue o temporizador de sono! Analise com precisão no gráfico de estatísticas se se trata de terrores noturnos ou de uma regressão do sono e ajuste a rotina.', title_sv = 'Nattliga uppvaknanden ⏱️', body_sv = 'Starta sömntimern! Analysera noga med timerns statistikgraf om det kan vara nattskräck eller sömnregression och justera rytmen.', title_vi = 'Thức giấc ban đêm ⏱️', body_vi = 'Hãy bật Bộ hẹn giờ ngủ! Phân tích chính xác biểu đồ thống kê để xem bé có bị hoảng sợ ban đêm hay thoái lui giấc ngủ không và điều chỉnh nếp sinh hoạt.', title_zh = '夜间醒来 ⏱️', body_zh = '打开睡眠计时器！从计时器的统计图表中准确分析是夜惊还是睡眠倒退，调整作息。' WHERE id = '4582098e-0228-4efe-b173-11bb966a75f4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas una pausa ☕', body_es = '¡Sal de casa y respira un poco! Busca en Lugares para mamás una cafetería cercana con rincón infantil y disfruta de tu café caliente.', title_fr = 'Vous aussi, vous avez besoin d''une pause ☕', body_fr = 'Sortez prendre un peu l''air ! Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants près de chez vous et savourez votre café chaud.', title_hi = 'आपको भी ब्रेक चाहिए ☕', body_hi = 'घर से निकलकर थोड़ी साँस लीजिए! माँ के लिए अनुकूल जगहें में पास का बच्चों के कोने वाला कैफ़े ढूँढिए और अपनी गर्म कॉफ़ी का मज़ा लीजिए।', title_id = 'Anda juga butuh rehat ☕', body_id = 'Keluar rumah dan hirup udara sebentar! Temukan kafe terdekat dengan sudut bermain anak di Tempat Ramah Ibu dan nikmati kopi hangat Anda.', title_ja = 'あなたにも休憩が必要です ☕', body_ja = '家を出て、ひと息つきましょう！「ママにやさしいスポット」で近くのキッズコーナーのあるカフェを見つけて、温かいコーヒーをゆっくり味わいましょう。', title_ko = '엄마에게도 휴식이 필요해요 ☕', body_ko = '집을 나서서 잠시 숨을 돌리세요! 엄마 친화 장소에서 가까운 키즈 코너 카페를 찾아 따뜻한 커피를 즐겨 보세요.', title_nl = 'Jij hebt ook een pauze nodig ☕', body_nl = 'Ga de deur uit en haal even adem! Zoek in Mamavriendelijke plekken een café met kinderhoek in de buurt en geniet van je warme koffie.', title_pl = 'Ty też potrzebujesz przerwy ☕', body_pl = 'Wyjdź z domu i odetchnij! Znajdź w Miejscach przyjaznych mamom pobliską kawiarnię z kącikiem dla dzieci i delektuj się gorącą kawą.', title_pt = 'Também precisa de uma pausa ☕', body_pt = 'Saia de casa e respire um pouco! Encontre nos Locais Amigos das Mães um café perto com cantinho para crianças e saboreie o seu café quente.', title_sv = 'Du behöver också en paus ☕', body_sv = 'Gå ut och andas lite! Hitta ett kafé med barnhörna i närheten i Mammavänliga platser och lyssna på ljudet av ditt varma kaffe.', title_vi = 'Mẹ cũng cần nghỉ ngơi ☕', body_vi = 'Hãy ra ngoài hít thở một chút! Tìm quán cà phê có góc trẻ em gần nhà trong Địa điểm thân thiện với mẹ và tận hưởng ly cà phê nóng của mình.', title_zh = '你也需要歇一歇 ☕', body_zh = '出门透透气吧！在妈妈友好场所里找一家附近带儿童角的咖啡馆，听听热咖啡的声音。' WHERE id = '91af8067-4bf1-4cab-af7f-58a96c7e04b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tiene estreñimiento? 🚽', body_es = 'Al cambiar el pañal de la mañana, fíjate en las cacas. Si hay estreñimiento, anótalo en la app, añade enseguida alimentos con fibra con el Seguimiento de tomas y mantén el equilibrio.', title_fr = 'Un souci de constipation ? 🚽', body_fr = 'En changeant la couche du matin, observez les selles. En cas de constipation, notez-le dans l''appli et ajoutez tout de suite des aliments riches en fibres avec le Suivi des repas pour garder l''équilibre.', title_hi = 'कब्ज़ की परेशानी? 🚽', body_hi = 'सुबह डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ हो तो ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से फ़ाइबर वाली चीज़ें जोड़कर संतुलन बनाए रखिए।', title_id = 'Ada masalah sembelit? 🚽', body_id = 'Perhatikan kotorannya saat mengganti popok pagi. Jika ia sembelit, catat di aplikasi, lalu segera tambahkan makanan berserat dengan alat Pemantau Nutrisi untuk menjaga keseimbangannya.', title_ja = '便秘ぎみ？🚽', body_ja = '朝のおむつ替えのときに、うんちの様子をチェックしましょう。便秘ならアプリに記録して、すぐに「栄養管理ツール」で食物繊維の多い食べ物を加え、バランスを保ちましょう。', title_ko = '변비가 있나요? 🚽', body_ko = '아침에 기저귀를 갈 때 배변을 살펴보세요. 변비가 있다면 앱에 기록하고 수유 기록 도구로 섬유질 음식을 바로 추가해 균형을 지켜 주세요.', title_nl = 'Last van verstopping? 🚽', body_nl = 'Let bij het verschonen van de ochtendluier op de ontlasting. Bij verstopping: noteer het in de app en voeg meteen met de Voedingstracker vezelrijk eten toe om de balans te bewaren.', title_pl = 'Problem z zaparciami? 🚽', body_pl = 'Przy porannej zmianie pieluszki obserwuj kupkę. Jeśli są zaparcia, zapisz to w aplikacji i od razu dodaj produkty bogate w błonnik w narzędziu do śledzenia karmienia, by zachować równowagę.', title_pt = 'Prisão de ventre? 🚽', body_pt = 'Ao mudar a fralda da manhã, observe as fezes. Se houver prisão de ventre, registe-o na app e acrescente já alimentos ricos em fibra com o Registo de Alimentação para manter o equilíbrio.', title_sv = 'Förstoppning? 🚽', body_sv = 'Håll koll på avföringen när du byter morgonblöjan. Vid förstoppning, anteckna det i appen, lägg direkt till fiberrik mat med Matningskoll och håll balansen.', title_vi = 'Bé bị táo bón? 🚽', body_vi = 'Hãy để ý phân khi thay tã buổi sáng. Nếu bé bị táo bón, hãy ghi vào ứng dụng và thêm ngay thực phẩm giàu chất xơ bằng Theo dõi cữ bú để giữ cân bằng.', title_zh = '便秘了？🚽', body_zh = '早上换尿布时留意一下排便。如果便秘，记到应用里，马上用喂养记录工具加入富含纤维的食物，保持平衡。' WHERE id = 'e6513be5-cd7d-41ca-afb7-bc1d9cfbc0d8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis matutinas 👗', body_es = '¿La tozudez del «¡No quiero estos zapatos!» te complica las mañanas? Aprende con Anacan AI las formas psicológicas más eficaces de ofrecerle alternativas y libertad para elegir.', title_fr = 'Crises du matin 👗', body_fr = 'La période « Je ne veux pas ces chaussures ! » complique vos matinées ? Découvrez avec Anacan AI les approches psychologiques les plus efficaces pour lui proposer des alternatives et le laisser choisir.', title_hi = 'सुबह के नखरे 👗', body_hi = '''ये जूते नहीं चाहिए!'' वाली ज़िद आपकी सुबह मुश्किल बना देती है? उसे विकल्प देकर चुनने की आज़ादी देने के सबसे असरदार मनोवैज्ञानिक तरीके Anacan AI से जानिए।', title_id = 'Drama pagi hari 👗', body_id = 'Sikap keras kepala Aku tidak mau sepatu ini! membuat pagi Anda berat? Pelajari dari Anacan AI cara psikologis paling efektif untuk menawarkan alternatif dan memberinya kebebasan memilih.', title_ja = '朝のかんしゃく 👗', body_ja = '「この靴はいや！」というこだわりで、朝が大変になっていますか？選択肢を出して選ぶ自由をあげる、いちばん効果的な心理的アプローチをAnacan AIで学びましょう。', title_ko = '아침 떼쓰기 👗', body_ko = '''이 신발 싫어!'' 고집으로 아침이 힘든가요? 다른 선택지를 보여 주며 고를 자유를 주는 가장 효과적인 심리적 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Ochtendbuien 👗', body_nl = 'Maakt ik wil deze schoenen niet!-koppigheid je ochtenden zwaar? Leer bij Anacan AI de beste psychologische manieren om hem alternatieven en keuzevrijheid te geven.', title_pl = 'Poranne kryzysy 👗', body_pl = 'Upór w stylu „Nie chcę tych butów!” utrudnia ci poranki? Poznaj z Anacan AI najskuteczniejsze psychologiczne sposoby, by proponować alternatywy i dać mu swobodę wyboru.', title_pt = 'Crises da manhã 👗', body_pt = 'A teimosia do "Não quero estes sapatos!" complica-lhe as manhãs? Aprenda com o Anacan AI as formas psicológicas mais eficazes de lhe oferecer alternativas e dar liberdade de escolha.', title_sv = 'Morgonutbrott 👗', body_sv = 'Gör envisheten ”Jag vill inte ha de här skorna!” morgnarna svåra? Lär dig av Anacan AI de mest effektiva psykologiska sätten att ge barnet valfrihet genom att erbjuda alternativ.', title_vi = 'Khủng hoảng buổi sáng 👗', body_vi = 'Cơn bướng "Con không thích đôi giày này!" khiến buổi sáng thêm vất vả? Hãy học từ Anacan AI những cách tâm lý hiệu quả nhất để đưa ra lựa chọn thay thế và cho bé tự do chọn lựa.', title_zh = '早上的崩溃 👗', body_zh = '“我不要这双鞋！”的倔强让早上变得很难？向Anacan AI学习最有效的心理方法：提供备选，给宝宝选择的自由。' WHERE id = '94201b9a-86d5-4505-89c9-5202248a32f0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La reserva de proteínas de mamá ⚡', body_es = 'No es fácil correr detrás de un peque tan activo. ¡No te agotes! Prepara en Recetas saludables un batido energético rico en proteínas y fruta, y recupera fuerzas.', title_fr = 'La réserve de protéines de maman ⚡', body_fr = 'Courir après un petit plein d''énergie n''est pas facile. Ne vous épuisez pas ! Retrouvez votre énergie avec un smoothie énergie riche en protéines et en fruits des Recettes saines.', title_hi = 'माँ का प्रोटीन भंडार ⚡', body_hi = 'चंचल नन्हे के पीछे भागना आसान नहीं। खुद को थकाकर चूर मत कीजिए! सेहतमंद रेसिपी से प्रोटीन और फलों से भरपूर एनर्जी स्मूदी बनाइए और अपनी ऊर्जा लौटाइए।', title_id = 'Gudang protein Bunda ⚡', body_id = 'Mengejar si kecil yang aktif tidaklah mudah. Jangan sampai kehabisan tenaga! Pulihkan energi Anda dengan smoothie energi kaya protein dan buah dari Resep Sehat.', title_ja = 'ママのたんぱく質チャージ ⚡', body_ja = '活発なお子さんを追いかけるのは大変です。無理をしすぎないで！「ヘルシーレシピ」から、たんぱく質とフルーツたっぷりのエナジースムージーをつくって、エネルギーを取り戻しましょう。', title_ko = '엄마의 단백질 충전소 ⚡', body_ko = '활발한 아이를 쫓아다니기는 쉽지 않아요. 기운을 다 쓰지 마세요! 건강한 레시피에서 단백질과 과일이 풍부한 에너지 스무디를 만들어 기운을 되찾으세요.', title_nl = 'Eiwitvoorraad van mama ⚡', body_nl = 'Achter een beweeglijk kleintje aan rennen is niet makkelijk. Put jezelf niet uit! Herstel je energie met een energiesmoothie vol eiwit en fruit uit Gezonde recepten.', title_pl = 'Białkowy zapas mamy ⚡', body_pl = 'Bieganie za ruchliwym maluchem to nie lada wyzwanie. Nie wyczerpuj się! Przygotuj ze Zdrowych przepisów energetyczne smoothie bogate w białko i owoce i odzyskaj siły.', title_pt = 'A reserva de proteína da mãe ⚡', body_pt = 'Correr atrás de um pequenino tão ativo não é fácil. Não se esgote! Prepare nas Receitas Saudáveis um batido energético rico em proteína e fruta e recupere a energia.', title_sv = 'Mammas proteinförråd ⚡', body_sv = 'Det är inte lätt att springa efter en aktiv liten. Kör inte slut på dig själv! Gör en energismoothie rik på protein och frukt från Hälsosamma recept och återfå energin.', title_vi = 'Kho đạm của mẹ ⚡', body_vi = 'Chạy theo bé hiếu động không hề dễ. Đừng vắt kiệt bản thân! Hãy làm ly sinh tố năng lượng giàu đạm và trái cây từ Công thức lành mạnh để phục hồi sức lực.', title_zh = '妈妈的蛋白质储备 ⚡', body_zh = '追着好动的小家伙跑可不容易。别把自己累垮了！从健康食谱里做一杯富含蛋白质和水果的能量奶昔，恢复精力吧。' WHERE id = 'c7ffac8f-2df5-4b9d-8171-edd5730bbcb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de carreras? El temporizador se ha parado. Oscurece la habitación, pon el murmullo del río de Ruido blanco y regala un masaje a su mente y a la tuya.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée bruyante et pleine de courses ? Le minuteur est arrêté. Faites l''obscurité, lancez le murmure de la rivière des Bruits blancs et massez son cerveau comme le vôtre.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत शोर और भाग-दौड़ भरा दिन था? टाइमर रुक गया। कमरे में अँधेरा कीजिए, व्हाइट नॉइज़ में नदी की कलकल लगाइए और उसके और अपने, दोनों के दिमाग को आराम दीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari yang bising dan penuh kejar-kejaran? Timer sudah berhenti. Gelapkan kamar, putar suara gemericik sungai dari Suara Putih, dan tenangkan pikiran ia dan Anda.', title_ja = '自然のリラックス効果 🍃', body_ja = 'にぎやかで走り回った一日でしたか？タイマーは止まりました。部屋を暗くして、「ホワイトノイズ」の小川のせせらぎを流し、お子さんとあなたの頭をやさしくほぐしましょう。', title_ko = '자연의 진정제 🍃', body_ko = '시끄럽고 정신없는 하루였나요? 타이머가 멈췄어요. 방을 어둡게 하고 백색소음에서 시냇물 소리를 틀어 아이와 엄마의 머리를 함께 쉬게 해 주세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een lawaaierige, drukke dag? De timer is gestopt. Verduister de kamer, zet het kabbelen van een beekje uit Witte ruis aan en geef zijn hoofdje en dat van jezelf een massage.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był bardzo głośny dzień pełen bieganiny? Timer zatrzymany. Zaciemnij pokój, włącz szum strumienia z Białego szumu i ukój umysł jego i swój.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia muito barulhento e cheio de correria? O temporizador parou. Escureça o quarto, ligue o murmúrio do rio do Ruído Branco e faça uma massagem ao cérebro dele e ao seu.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit full av buller och springande? Timern har stannat. Mörklägg rummet, sätt på bäckens porlande från Vitt brus och ge både barnets och din egen hjärna en massage.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Một ngày quá ồn ào và chạy nhảy? Hẹn giờ đã dừng. Hãy làm tối phòng, bật tiếng suối chảy trong Tiếng ồn trắng để thư giãn đầu óc cho cả bé lẫn mẹ.', title_zh = '天然的镇静剂 🍃', body_zh = '今天又吵又跑，闹腾了一整天？计时器停了。把房间调暗，打开白噪音里的溪流声，给宝宝和你自己的大脑都做个按摩。' WHERE id = 'fdd42343-56c5-47a1-8eaa-9e8b57c16e15' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La batalla de la independencia! 👕', body_es = '¿Quiere vestirse solo y rechaza tu ayuda? Pregunta ya a nuestro asistente experto Anacan AI cómo convertir esta tozudez en un desarrollo sano.', title_fr = 'La bataille de l''autonomie ! 👕', body_fr = 'Il veut s''habiller seul et refuse votre aide ? Demandez tout de suite à notre assistant expert Anacan AI comment transformer cette obstination en développement sain.', title_hi = 'आत्मनिर्भरता की जंग! 👕', body_hi = 'खुद कपड़े पहनना चाहता है और आपकी मदद ठुकराता है? इस ज़िद को सेहतमंद विकास में कैसे बदलें, यह तुरंत हमारे Anacan AI एक्सपर्ट असिस्टेंट से पूछिए।', title_id = 'Perang kemandirian! 👕', body_id = 'Ingin berpakaian sendiri dan menolak bantuan Anda? Segera tanyakan kepada asisten ahli Anacan AI cara mengubah sikap keras kepala ini menjadi perkembangan yang sehat.', title_ja = '自立をめぐる攻防！👕', body_ja = '自分で着たがって、あなたの手助けを断りますか？このこだわりを健やかな発達につなげる方法を、すぐにAnacan AIのエキスパートアシスタントに聞いてみましょう。', title_ko = '독립 전쟁! 👕', body_ko = '혼자 옷을 입겠다며 도움을 거절하나요? 이 고집을 건강한 성장으로 바꾸는 방법을 Anacan AI 전문가 도우미에게 바로 물어보세요.', title_nl = 'Strijd om zelfstandigheid! 👕', body_nl = 'Wil hij zichzelf aankleden en weigert hij je hulp? Vraag onze Anacan AI-expert meteen hoe je deze koppigheid omzet in een gezonde ontwikkeling.', title_pl = 'Walka o samodzielność! 👕', body_pl = 'Chce ubierać się sam i odrzuca twoją pomoc? Od razu zapytaj naszego eksperta Anacan AI, jak zamienić ten upór w zdrowy rozwój.', title_pt = 'A guerra da independência! 👕', body_pt = 'Quer vestir-se sozinho e recusa a sua ajuda? Pergunte já ao nosso assistente especialista Anacan AI como transformar esta teimosia num desenvolvimento saudável.', title_sv = 'Kampen om självständighet! 👕', body_sv = 'Vill barnet klä på sig själv och vägrar ta emot hjälp? Fråga vår expertassistent Anacan AI direkt hur du gör envisheten till sund utveckling.', title_vi = 'Cuộc chiến tự lập! 👕', body_vi = 'Bé muốn tự mặc đồ và từ chối sự giúp đỡ của mẹ? Hãy hỏi ngay trợ lý chuyên gia Anacan AI cách biến sự bướng bỉnh này thành sự phát triển lành mạnh.', title_zh = '独立之战！👕', body_zh = '想自己穿衣服，拒绝你的帮忙？马上问问我们的Anacan AI专家助手，如何把这种倔强转化为健康的成长。' WHERE id = '06ba8468-2412-484c-9b4b-12b5ce2a132b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de las reservas de hierro 🥩', body_es = 'Para que tu peque tan activo no tenga anemia, comprueba en el Seguimiento de tomas el hierro de hoy (carne, legumbres) y actualiza su menú.', title_fr = 'Contrôle des réserves de fer 🥩', body_fr = 'Pour que votre petit plein d''énergie ne manque pas de fer, vérifiez dans le Suivi des repas ses apports en fer du jour (viande, légumineuses) et mettez son menu à jour.', title_hi = 'आयरन के भंडार की जाँच 🥩', body_hi = 'चंचल नन्हे को खून की कमी न हो, इसके लिए फ़ीडिंग ट्रैकर में आज का आयरन (मांस, दालें) जाँचिए और मेन्यू अपडेट कीजिए।', title_id = 'Cek cadangan zat besi 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia, cek asupan zat besi hari ini (daging, kacang-kacangan) di alat Pemantau Nutrisi dan perbarui menunya.', title_ja = '鉄分チェック 🥩', body_ja = '活発なお子さんが貧血にならないよう、「栄養管理ツール」で今日の鉄分（お肉、豆類）の摂取量を確認して、メニューを見直しましょう。', title_ko = '철분 확인 🥩', body_ko = '활발한 아이가 빈혈을 겪지 않도록 수유 기록 도구로 오늘의 철분 섭취(고기, 콩류)를 확인하고 식단을 업데이트하세요.', title_nl = 'IJzervoorraad checken 🥩', body_nl = 'Controleer in de Voedingstracker het ijzer van vandaag (vlees, peulvruchten) en pas het menu aan, zodat je actieve kleintje geen bloedarmoede krijgt.', title_pl = 'Kontrola zapasu żelaza 🥩', body_pl = 'Aby ruchliwy maluch nie miał anemii, sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza (mięso, rośliny strączkowe) i odśwież menu.', title_pt = 'Verificar as reservas de ferro 🥩', body_pt = 'Para que o seu pequenino tão ativo não tenha anemia, verifique no Registo de Alimentação o ferro de hoje (carne, leguminosas) e atualize a ementa.', title_sv = 'Kontroll av järnförrådet 🥩', body_sv = 'För att din aktiva lilla inte ska få blodbrist, kontrollera dagens järnintag (kött, baljväxter) i Matningskoll och uppdatera menyn.', title_vi = 'Kiểm tra kho sắt 🥩', body_vi = 'Để bé hiếu động không bị thiếu máu, hãy kiểm tra lượng sắt (thịt, các loại đậu) hôm nay trong Theo dõi cữ bú và làm mới thực đơn.', title_zh = '铁储备检查 🥩', body_zh = '为了让好动的小家伙不贫血，在喂养记录工具里查看今天的铁（肉类、豆类）摄入量，更新一下菜单。' WHERE id = '10c5438d-d27e-4125-a092-12fa2afc9118' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bajar el ritmo por la noche 🎶', body_es = '¿No se cansa de correr y no quiere irse a la cama? Pon el temporizador de sueño y las olas del mar de Ruido blanco para crear en la habitación un ambiente tranquilo y de sueño.', title_fr = 'Ralentir avant la nuit 🎶', body_fr = 'Jamais fatigué de courir et il refuse d''aller au lit ? Lancez le minuteur de sommeil et mettez les vagues de l''océan des Bruits blancs pour créer dans la chambre une ambiance calme, propice au sommeil.', title_hi = 'रात को धीमा होना 🎶', body_hi = 'भागते-भागते थकता नहीं और सोने नहीं जाता? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में समुद्र की लहरों की आवाज़ लगाइए और कमरे में शांति और नींद का माहौल बनाइए।', title_id = 'Mengerem di malam hari 🎶', body_id = 'Tak lelah berlari dan tak mau ke tempat tidur? Nyalakan Timer Tidur, putar suara ombak dari Suara Putih, dan ciptakan suasana hening yang mengundang kantuk di kamar.', title_ja = '夜のクールダウン 🎶', body_ja = '走り回っても疲れ知らずで、ベッドに行かない？睡眠タイマーをオンにして、「ホワイトノイズ」の波の音を流し、部屋に静けさと眠りの雰囲気をつくりましょう。', title_ko = '밤에 속도 늦추기 🎶', body_ko = '뛰어도 지치지 않고 잠자리에 가지 않나요? 수면 타이머를 켜고 백색소음의 파도 소리를 틀어 방에 고요하고 잠이 오는 분위기를 만들어 주세요.', title_nl = 'Afremmen voor de nacht 🎶', body_nl = 'Wordt hij niet moe van het rennen en wil hij niet naar bed? Zet de Slaaptimer aan en zet oceaangolven uit Witte ruis aan voor een stille slaapsfeer in de kamer.', title_pl = 'Wieczorne wyciszenie 🎶', body_pl = 'Nie męczy się bieganiem i nie chce iść do łóżka? Włącz timer snu i puść fale oceanu z Białego szumu, by stworzyć w pokoju ciszę i senny nastrój.', title_pt = 'Abrandar à noite 🎶', body_pt = 'Não se cansa de correr e não vai para a cama? Ligue o temporizador de sono, ponha as ondas do mar do Ruído Branco e crie no quarto um ambiente de silêncio e de sono.', title_sv = 'Nattlig inbromsning 🎶', body_sv = 'Blir barnet aldrig trött på att springa och vill inte gå och lägga sig? Starta sömntimern, sätt på havsvågor från Vitt brus och skapa lugn och sömnmiljö i rummet.', title_vi = 'Chậm lại cho đêm về 🎶', body_vi = 'Bé chạy mãi không mệt và không chịu lên giường? Hãy bật Bộ hẹn giờ ngủ, mở tiếng sóng biển trong Tiếng ồn trắng để tạo không gian yên tĩnh, dễ ngủ trong phòng.', title_zh = '夜晚踩刹车 🎶', body_zh = '跑个不停也不累，就是不上床？打开睡眠计时器，播放白噪音里的海浪声，在房间里营造安静的睡眠环境。' WHERE id = 'f5441f5e-36e8-4685-812e-3b947ba2fe54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Crisis delante de la pantalla 📱', body_es = '¿Se tira al suelo cuando le quitas el móvil? Aprende con Anacan AI a limitar el tiempo de pantalla sin estrés y a poner límites sanos.', title_fr = 'Crise devant l''écran 📱', body_fr = 'Il se jette par terre quand vous lui reprenez le téléphone ? Découvrez avec Anacan AI comment limiter le temps d''écran sans stress et poser des limites saines.', title_hi = 'स्क्रीन के सामने नखरे 📱', body_hi = 'फ़ोन हाथ से लेते ही ज़मीन पर लोट जाता है? स्क्रीन टाइम को बिना तनाव कैसे सीमित करें और सेहतमंद सीमाएँ कैसे तय करें, यह Anacan AI से जानिए।', title_id = 'Tantrum di depan layar 📱', body_id = 'Menjatuhkan diri ke lantai saat ponsel diambil dari tangannya? Pelajari dari Anacan AI cara membatasi waktu layar tanpa stres dan menetapkan batasan yang sehat.', title_ja = '画面の前でかんしゃく 📱', body_ja = 'スマホを取り上げると床にひっくり返りますか？ストレスなく画面時間を制限し、健やかなルールをつくる方法を、Anacan AIで学びましょう。', title_ko = '화면 앞 떼쓰기 📱', body_ko = '휴대폰을 빼앗으면 바닥에 드러눕나요? 스트레스 없이 화면 시간을 줄이고 건강한 규칙을 세우는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Drama voor het scherm 📱', body_nl = 'Gooit hij zich op de grond als je de telefoon afpakt? Leer bij Anacan AI hoe je de schermtijd zonder stress beperkt en gezonde grenzen stelt.', title_pl = 'Kryzys przed ekranem 📱', body_pl = 'Rzuca się na podłogę, gdy zabierasz mu telefon? Dowiedz się od Anacan AI, jak bez stresu ograniczać czas przed ekranem i stawiać zdrowe granice.', title_pt = 'Crise em frente ao ecrã 📱', body_pt = 'Quando lhe tira o telemóvel, atira-se para o chão? Aprenda com o Anacan AI a limitar o tempo de ecrã sem stress e a pôr limites saudáveis.', title_sv = 'Utbrott framför skärmen 📱', body_sv = 'Kastar sig barnet på golvet när du tar telefonen? Lär dig av Anacan AI hur du begränsar skärmtiden utan stress och sätter sunda gränser.', title_vi = 'Ăn vạ trước màn hình 📱', body_vi = 'Bé lăn ra sàn khi mẹ lấy điện thoại? Hãy học từ Anacan AI cách giới hạn thời gian dùng màn hình mà không căng thẳng và đặt ra ranh giới lành mạnh.', title_zh = '屏幕前的崩溃 📱', body_zh = '一拿走手机就躺地上打滚？向Anacan AI学习如何不带压力地限制屏幕时间，设立健康的边界。' WHERE id = '442e022d-5a7b-4ad3-bb7f-6aecb9da6631' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🌟', body_es = 'Cada nueva habilidad que aprende es fruto de tu esfuerzo. ¡Abre el Diario de ánimo y escribe hoy una nota para aplaudirte de pie!', title_fr = 'L''héroïne du jour, c''est vous 🌟', body_fr = 'Chaque nouvelle compétence qu''il apprend, c''est grâce à vous. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note qui mérite une ovation debout !', title_hi = 'आज की हीरो आप हैं 🌟', body_hi = 'हर दिन वह जो नई चीज़ सीखता है, वह आपकी मेहनत है। मूड डायरी खोलिए और आज खुद को शाबाशी देने वाली एक बात लिखिए!', title_id = 'Pahlawan hari ini adalah Anda 🌟', body_id = 'Setiap keterampilan baru yang ia pelajari adalah hasil kerja keras Anda. Buka Buku Harian Suasana Hati dan tulis catatan yang membuat Anda bertepuk tangan untuk diri sendiri hari ini!', title_ja = '今日のヒーローはあなたです 🌟', body_ja = '毎日新しくできるようになることは、あなたのがんばりのおかげです。「気分日記」を開いて、今日の自分にスタンディングオベーションを送るメモを書きましょう！', title_ko = '오늘의 주인공은 엄마예요 🌟', body_ko = '아이가 매일 배우는 새로운 능력은 엄마의 노력 덕분이에요. 기분 일기를 열고 오늘의 나에게 기립 박수를 보낼 기록을 남겨 보세요!', title_nl = 'Jij bent de held van vandaag 🌟', body_nl = 'Elke nieuwe vaardigheid die hij leert, is dankzij jou. Open je Stemmingsdagboek en schrijf vandaag een notitie waarmee je jezelf een staande ovatie geeft!', title_pl = 'Dzisiejszą bohaterką jesteś ty 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, to twoja zasługa. Otwórz Dziennik nastroju i napisz dziś notatkę, za którą nagrodzisz się owacją na stojąco!', title_pt = 'A heroína do dia é a mãe 🌟', body_pt = 'Cada nova competência que ele aprende é fruto do seu esforço. Abra o Diário de Humor e escreva hoje uma nota que a faça aplaudir-se de pé!', title_sv = 'Dagens hjälte är du 🌟', body_sv = 'Varje ny färdighet barnet lär sig är tack vare ditt arbete. Öppna Humördagboken och skriv en anteckning i dag som ger dig själv stående ovationer!', title_vi = 'Mẹ là người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới bé học được hằng ngày đều là công sức của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng để tự vỗ tay cho mình hôm nay!', title_zh = '今天的英雄是你 🌟', body_zh = '宝宝每天学会的新本领都有你的功劳。打开心情日记，写下一句为自己热烈鼓掌的话吧！' WHERE id = '70c5aa02-8fdb-44ad-8a7f-cb5e6e2076a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pelea de lavarse los dientes 🪥', body_es = '¿Sale corriendo en cuanto ve el cepillo? Mira en Productos recomendados cepillos infantiles musicales o giratorios y convierte esta higiene tan importante en un juego divertido.', title_fr = 'La bataille du brossage de dents 🪥', body_fr = 'Il s''enfuit dès qu''il voit la brosse ? Regardez dans les Produits recommandés les brosses musicales ou rotatives pour enfants et transformez ce geste d''hygiène essentiel en jeu amusant.', title_hi = 'दाँत ब्रश करने की लड़ाई 🪥', body_hi = 'ब्रश देखते ही भाग जाता है? सुझाए गए प्रोडक्ट में म्यूज़िकल या घूमने वाले बच्चों के ब्रश देखिए और सफ़ाई की इस ज़रूरी आदत को मज़ेदार खेल बना दीजिए।', title_id = 'Drama sikat gigi 🪥', body_id = 'Langsung kabur begitu melihat sikat gigi? Lihat sikat gigi anak bermusik atau berputar di Produk Rekomendasi dan jadikan rutinitas kebersihan penting ini permainan seru.', title_ja = '歯みがきバトル 🪥', body_ja = '歯ブラシを見たとたんに逃げますか？「おすすめ商品」で音楽付きや回転する子ども用歯ブラシをチェックして、この大切な歯みがきの習慣を楽しい遊びに変えましょう。', title_ko = '양치 전쟁 🪥', body_ko = '칫솔만 보면 도망가나요? 추천 제품에서 음악이 나오거나 회전하는 유아 칫솔을 살펴보고 중요한 위생 습관을 재미있는 놀이로 바꿔 보세요.', title_nl = 'Gedoe met tandenpoetsen 🪥', body_nl = 'Rent hij weg zodra hij de tandenborstel ziet? Bekijk in Aanbevolen producten muzikale of draaiende kindertandenborstels en maak van deze belangrijke verzorging een leuk spel.', title_pl = 'Bitwa o mycie ząbków 🪥', body_pl = 'Ucieka na widok szczoteczki? Zajrzyj w Polecanych produktach do grających lub obrotowych szczoteczek dla dzieci i zamień tę ważną higienę w zabawę.', title_pt = 'A luta da escova de dentes 🪥', body_pt = 'Foge mal vê a escova? Veja nos Produtos Recomendados escovas musicais ou rotativas para crianças e transforme esta rotina de higiene tão importante num jogo divertido.', title_sv = 'Kampen om tandborstningen 🪥', body_sv = 'Springer barnet iväg så fort tandborsten syns? Titta på tandborstar med musik eller roterande barntandborstar i Rekommenderade produkter och gör den viktiga hygienrutinen till en rolig lek.', title_vi = 'Cuộc chiến đánh răng 🪥', body_vi = 'Vừa thấy bàn chải là bé chạy mất? Hãy xem các loại bàn chải có nhạc hoặc bàn chải xoay cho trẻ em trong Sản phẩm gợi ý để biến việc vệ sinh quan trọng này thành trò chơi vui nhộn.', title_zh = '刷牙大作战 🪥', body_zh = '一看到牙刷就跑？去推荐商品看看音乐牙刷或旋转儿童牙刷，把这项重要的卫生习惯变成有趣的游戏。' WHERE id = 'd0802019-8ab1-4450-b744-1d4846aeaf76' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de carreras? El temporizador se ha parado. Oscurece la habitación, pon el murmullo del río de Ruido blanco y regala un masaje a su mente y a la tuya.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée bruyante et pleine de courses ? Le minuteur est arrêté. Faites l''obscurité, lancez le murmure de la rivière des Bruits blancs et massez son cerveau comme le vôtre.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत शोर और भाग-दौड़ भरा दिन था? टाइमर रुक गया। कमरे में अँधेरा कीजिए, व्हाइट नॉइज़ में नदी की कलकल लगाइए और उसके और अपने, दोनों के दिमाग को आराम दीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari yang bising dan penuh kejar-kejaran? Timer sudah berhenti. Gelapkan kamar, putar suara gemericik sungai dari Suara Putih, dan tenangkan pikiran ia dan Anda.', title_ja = '自然のリラックス効果 🍃', body_ja = 'にぎやかで走り回った一日でしたか？タイマーは止まりました。部屋を暗くして、「ホワイトノイズ」の小川のせせらぎを流し、お子さんとあなたの頭をやさしくほぐしましょう。', title_ko = '자연의 진정제 🍃', body_ko = '시끄럽고 정신없는 하루였나요? 타이머가 멈췄어요. 방을 어둡게 하고 백색소음에서 시냇물 소리를 틀어 아이와 엄마의 머리를 함께 쉬게 해 주세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een lawaaierige, drukke dag? De timer is gestopt. Verduister de kamer, zet het kabbelen van een beekje uit Witte ruis aan en geef zijn hoofdje en dat van jezelf een massage.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był bardzo głośny dzień pełen bieganiny? Timer zatrzymany. Zaciemnij pokój, włącz szum strumienia z Białego szumu i ukój umysł jego i swój.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia muito barulhento e cheio de correria? O temporizador parou. Escureça o quarto, ligue o murmúrio do rio do Ruído Branco e faça uma massagem ao cérebro dele e ao seu.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit full av buller och springande? Timern har stannat. Mörklägg rummet, sätt på bäckens porlande från Vitt brus och ge både barnets och din egen hjärna en massage.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Một ngày quá ồn ào và chạy nhảy? Hẹn giờ đã dừng. Hãy làm tối phòng, bật tiếng suối chảy trong Tiếng ồn trắng để thư giãn đầu óc cho cả bé lẫn mẹ.', title_zh = '天然的镇静剂 🍃', body_zh = '今天又吵又跑，闹腾了一整天？计时器停了。把房间调暗，打开白噪音里的溪流声，给宝宝和你自己的大脑都做个按摩。' WHERE id = '134f77a6-22c5-4894-83a4-bbdf2a3551b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Salto en la lógica 🧩', body_es = 'Ha empezado a entender la relación causa-efecto. Lee en el Blog los mejores juegos caseros para acelerar el desarrollo cognitivo de los niños de unos 2 años y ponlos en práctica.', title_fr = 'Un bond dans la logique 🧩', body_fr = 'Il commence à comprendre les liens de cause à effet. Lisez dans la rubrique Blogs les meilleurs jeux à la maison qui accélèrent le développement cognitif vers 2 ans, et essayez-les.', title_hi = 'तर्क में छलांग 🧩', body_hi = 'वह कारण और नतीजे का रिश्ता समझने लगा है। ब्लॉग सेक्शन में लगभग 2 साल के बच्चों की समझ का विकास तेज़ करने वाले सबसे अच्छे घरेलू खेल पढ़िए और आज़माइए।', title_id = 'Lompatan logika 🧩', body_id = 'Ia mulai memahami sebab-akibat. Baca dan praktikkan permainan rumahan terbaik yang mempercepat perkembangan kognitif anak usia sekitar 2 tahun di bagian Blog.', title_ja = '論理的な思考の飛躍 🧩', body_ja = '原因と結果のつながりを理解し始めています。2歳ごろの子の認知の発達を促す、いちばんいいおうち遊びをブログで読んで、試してみましょう。', title_ko = '논리의 도약 🧩', body_ko = '원인과 결과를 이해하기 시작했어요. 블로그에서 두 돌 무렵 아이의 인지 발달을 앞당기는 최고의 집 놀이를 읽고 해 보세요.', title_nl = 'Logische sprong 🧩', body_nl = 'Hij begint oorzaak en gevolg te begrijpen. Lees in Blogs de beste spelletjes voor thuis die de cognitieve ontwikkeling van kinderen rond 2 jaar versnellen, en probeer ze uit.', title_pl = 'Skok w logice 🧩', body_pl = 'Zaczyna rozumieć związek przyczyny i skutku. Przeczytaj w sekcji Blog o najlepszych domowych zabawach przyspieszających rozwój poznawczy prawie 2-letnich dzieci i wypróbuj je.', title_pt = 'Salto na lógica 🧩', body_pt = 'Começa a perceber a relação de causa e efeito. Leia nos Blogues e experimente os melhores jogos caseiros que aceleram o desenvolvimento cognitivo das crianças de cerca de 2 anos.', title_sv = 'Logiskt språng 🧩', body_sv = 'Barnet har börjat förstå orsak och verkan. Läs om de bästa lekarna hemma som snabbar på den kognitiva utvecklingen hos barn på ungefär 2 år i Bloggar och prova dem.', title_vi = 'Bước nhảy vọt về tư duy 🧩', body_vi = 'Bé bắt đầu hiểu mối quan hệ nguyên nhân và kết quả. Hãy đọc trong mục Blog và thử những trò chơi tại nhà tốt nhất giúp thúc đẩy nhận thức của trẻ khoảng 2 tuổi.', title_zh = '逻辑飞跃 🧩', body_zh = '宝宝开始理解因果关系了。去博客板块读读能促进2岁左右宝宝认知发展的最佳居家游戏，一起玩起来。' WHERE id = 'c38c019f-d84f-4e70-a98d-688ae4d3f657' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de calcio 🦴', body_es = 'El calcio es imprescindible para dientes y huesos. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de yogur y queso.', title_fr = 'Bouclier calcium 🦴', body_fr = 'Le calcium est indispensable aux dents et aux os. Vérifiez avec le Suivi des repas qu''il a bien eu sa ration de yaourt et de fromage aujourd''hui.', title_hi = 'कैल्शियम की ढाल 🦴', body_hi = 'दाँतों और हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज दही और पनीर की मात्रा पूरी हुई।', title_id = 'Perisai kalsium 🦴', body_id = 'Kalsium wajib untuk gigi dan tulang. Pastikan dengan alat Pemantau Nutrisi bahwa porsi yogurt dan keju hari ini sudah terpenuhi.', title_ja = 'カルシウムのシールド 🦴', body_ja = '歯と骨にはカルシウムが欠かせません。「栄養管理ツール」で、今日のヨーグルトやチーズの目安量をとれたか確認しましょう。', title_ko = '칼슘 방패 🦴', body_ko = '치아와 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 요거트와 치즈 기준량을 채웠는지 확인하세요.', title_nl = 'Calciumschild 🦴', body_nl = 'Calcium is onmisbaar voor tanden en botten. Check met de Voedingstracker of hij vandaag genoeg yoghurt en kaas heeft gehad.', title_pl = 'Tarcza z wapnia 🦴', body_pl = 'Wapń jest niezbędny dla zębów i kości. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja jogurtu i sera została osiągnięta.', title_pt = 'Escudo de cálcio 🦴', body_pt = 'O cálcio é indispensável para os dentes e os ossos. Confirme com o Registo de Alimentação que hoje cumpriu a dose de iogurte e queijo.', title_sv = 'Kalciumskölden 🦴', body_sv = 'Kalcium är ett måste för tänder och skelett. Kontrollera med Matningskoll att barnet fått dagens norm av yoghurt och ost.', title_vi = 'Lá chắn canxi 🦴', body_vi = 'Canxi rất cần cho răng và xương. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sữa chua, phô mai chưa.', title_zh = '钙的护盾 🦴', body_zh = '钙对牙齿和骨骼必不可少。用喂养记录工具确认今天酸奶、奶酪的参考量是否达到了。' WHERE id = 'e1d2d8e1-5d2b-4afe-b927-cf13cedf3cda' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Alpinista del sofá! 🧗', body_es = '¿Su mayor afición es andar por encima de los muebles? Decora este espectáculo motor tan valiente y gracioso con las pegatinas alegres de la Sesión de fotos del bebé y súbelo al álbum.', title_fr = 'Alpiniste du canapé ! 🧗', body_fr = 'Marcher sur les meubles est son passe-temps préféré ? Décorez ce show moteur courageux et rigolo avec les stickers joyeux de la Séance photo bébé et ajoutez-le à l''album.', title_hi = 'सोफ़े का पर्वतारोही! 🧗', body_hi = 'फ़र्नीचर पर चलना उसका सबसे बड़ा शौक है? उसके इस बहादुर और मज़ेदार मोटर स्किल्स शो को बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में अपलोड कीजिए।', title_id = 'Pendaki sofa! 🧗', body_id = 'Berjalan di atas perabot adalah hobi terbesarnya? Hiasi pertunjukan motorik yang berani dan lucu ini dengan stiker ceria dari Sesi Foto Bayi dan unggah ke album.', title_ja = 'ソファの登山家！🧗', body_ja = '家具の上を歩くのがいちばんの趣味？この勇敢でおもしろい運動ショーを、「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムにアップしましょう。', title_ko = '소파 등반가! 🧗', body_ko = '가구 위를 걸어 다니는 게 가장 좋아하는 취미인가요? 이 용감하고 웃긴 운동 쇼를 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 올려 보세요.', title_nl = 'Bankklimmer! 🧗', body_nl = 'Is over de meubels lopen zijn grootste hobby? Versier deze dappere, grappige motoriekshow met vrolijke stickers in Babyfotoshoot en zet het in het album.', title_pl = 'Kanapowy alpinista! 🧗', body_pl = 'Chodzenie po meblach to jego największe hobby? Ozdób to odważne i zabawne motoryczne show wesołymi naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'Alpinista do sofá! 🧗', body_pt = 'Andar por cima dos móveis é o seu maior passatempo? Decore este espetáculo motor corajoso e divertido com os autocolantes alegres da Sessão Fotográfica do Bebé e carregue-o no álbum.', title_sv = 'Soffklättraren! 🧗', body_sv = 'Är det barnets största hobby att gå på möblerna? Dekorera den modiga och roliga motoriska showen med glada klistermärken i Babyfotografering och ladda upp den i albumet.', title_vi = 'Nhà leo núi sofa! 🧗', body_vi = 'Đi trên đồ đạc là sở thích lớn nhất của bé? Hãy trang trí màn trình diễn vận động gan dạ và hài hước này bằng sticker vui nhộn trong Chụp ảnh cho bé rồi tải lên album.', title_zh = '沙发登山家！🧗', body_zh = '在家具上走来走去是最大的爱好？用宝宝写真里欢乐的贴纸装饰这场勇敢又搞笑的运动表演，上传到相册。' WHERE id = '4ee32e6d-768e-4628-8838-47e0599752e7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El monstruo de las tortitas 🥞', body_es = '¿Rechaza el desayuno? Prueba en Recetas para bebé las tortitas de plátano sin azúcar. Podrá cogerlas y comerlas solo, y se le abrirá el apetito.', title_fr = 'Le monstre des pancakes 🥞', body_fr = 'Il refuse le petit-déjeuner ? Essayez la recette de pancakes à la banane sans sucre des Recettes pour bébés. Il les mangera tout seul avec les mains, et l''appétit reviendra.', title_hi = 'पैनकेक मॉन्स्टर 🥞', body_hi = 'नाश्ते से मना करता है? बच्चों की रेसिपी में बिना चीनी वाला केले का पैनकेक देखिए। वह उसे हाथ में लेकर खुद खाएगा और उसकी भूख भी खुलेगी।', title_id = 'Monster panekuk 🥞', body_id = 'Menolak sarapan? Coba resep panekuk pisang tanpa gula di Resep Bayi. Ia bisa memegang dan memakannya sendiri, dan nafsu makannya pun terbuka.', title_ja = 'パンケーキモンスター 🥞', body_ja = '朝ごはんを嫌がりますか？「離乳食を始める赤ちゃんのレシピ」で、砂糖不使用のバナナパンケーキのレシピをチェックしましょう。自分で持って食べられて、食欲もわいてきます。', title_ko = '팬케이크 괴물 🥞', body_ko = '아침밥을 거부하나요? 아기 레시피에서 설탕 없는 바나나 팬케이크를 확인해 보세요. 손에 들고 혼자 먹으면서 입맛도 살아날 거예요.', title_nl = 'Pannenkoekenmonster 🥞', body_nl = 'Wil hij niet ontbijten? Probeer in Babyrecepten de suikervrije bananenpannenkoekjes. Hij kan ze zelf vastpakken en eten, en krijgt er trek van.', title_pl = 'Naleśnikowy potwór 🥞', body_pl = 'Nie chce jeść śniadania? Sprawdź w Przepisach dla niemowląt przepis na bananowe placuszki bez cukru. Sam weźmie je do rączki i zje, a apetyt wróci.', title_pt = 'O monstro das panquecas 🥞', body_pt = 'Recusa o pequeno-almoço? Experimente nas Receitas para bebés a receita de panquecas de banana sem açúcar. Vai pegar nelas e comer sozinho, e o apetite vai abrir.', title_sv = 'Pannkaksmonstret 🥞', body_sv = 'Vägrar barnet frukost? Prova receptet på sockerfria bananpannkakor i Recept för bebisar. Barnet kan hålla dem och äta själv, och aptiten väcks.', title_vi = 'Quái vật bánh kếp 🥞', body_vi = 'Bé không chịu ăn sáng? Hãy thử công thức bánh kếp chuối không đường trong Công thức cho bé. Bé vừa tự cầm ăn được, vừa ăn ngon miệng hơn.', title_zh = '松饼小怪兽 🥞', body_zh = '不肯吃早餐？看看宝宝食谱里的无糖香蕉松饼。宝宝既能自己拿着吃，胃口也会变好。' WHERE id = '20e07ee8-1ee8-4d24-9dc9-8aeafced1a45' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de paciencia en la mesa 🥣', body_es = '¿Juega con la comida y lo mancha todo? Pon el temporizador de tomas, analiza la evolución de su apetito con el gráfico y controla con precisión cuánto dura la comida.', title_fr = 'Patience à table 🥣', body_fr = 'Il joue avec la nourriture et en met partout ? Lancez le minuteur des repas, analysez son appétit sur le graphique et suivez précisément la durée du repas.', title_hi = 'मेज़ पर सब्र की परीक्षा 🥣', body_hi = 'खाने से खेलता है और सब जगह गंदा कर देता है? फ़ीडिंग टाइमर चालू कीजिए, चार्ट से भूख का रुझान देखिए और सटीक जानिए कि खाने में कितना समय लगता है।', title_id = 'Ujian kesabaran di meja makan 🥣', body_id = 'Bermain dengan makanan dan membuat semuanya berantakan? Nyalakan Timer Makan, analisis nafsu makannya lewat grafik, dan pantau dengan tepat berapa lama waktu makannya.', title_ja = '食卓で試される忍耐 🥣', body_ja = '食べ物で遊んで、あちこち汚していますか？食事タイマーをオンにして、グラフで食欲の変化を分析し、食事にどれくらい時間がかかっているかしっかり記録しましょう。', title_ko = '식탁에서의 인내심 시험 🥣', body_ko = '음식으로 장난치며 온 사방을 어지르나요? 수유 타이머를 켜고 그래프로 식욕의 변화를 분석해 식사 시간이 얼마나 걸리는지 정확히 확인하세요.', title_nl = 'Geduldproef aan tafel 🥣', body_nl = 'Speelt hij met eten en maakt hij alles vies? Zet de Voedingstimer aan, analyseer zijn eetlust met de grafiek en volg precies hoe lang het duurt.', title_pl = 'Test cierpliwości przy stole 🥣', body_pl = 'Bawi się jedzeniem i wszystko brudzi? Włącz timer karmienia, przeanalizuj apetyt na wykresie i dokładnie śledź, ile trwa posiłek.', title_pt = 'Teste de paciência à mesa 🥣', body_pt = 'Brinca com a comida e suja tudo? Ligue o temporizador de alimentação, analise no gráfico a evolução do apetite e acompanhe com precisão quanto tempo demora.', title_sv = 'Tålamodsprov vid bordet 🥣', body_sv = 'Leker barnet med maten och kladdar ner allt? Starta matningstimern, analysera aptitens utveckling med grafen och följ noga hur lång tid måltiden tar.', title_vi = 'Thử thách kiên nhẫn trên bàn ăn 🥣', body_vi = 'Bé nghịch thức ăn và bôi bẩn khắp nơi? Hãy bật Hẹn giờ cho bú, phân tích khẩu vị qua biểu đồ và theo dõi chính xác bữa ăn kéo dài bao lâu.', title_zh = '餐桌上的耐心考验 🥣', body_zh = '玩食物，弄得到处都是？打开喂养计时器，用图表分析食欲变化，准确跟踪这一餐花了多长时间。' WHERE id = '98f28b6b-3cea-495d-a58b-704216aa3a0d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Terapia de arena y barro 🏖️', body_es = '¡No tengas miedo a que se ensucie! Descubre ahora en Productos recomendados lo mejor en arena cinética y juegos sensoriales.', title_fr = 'Thérapie par le sable et la boue 🏖️', body_fr = 'N''ayez pas peur qu''il se salisse ! Découvrez tout de suite dans les Produits recommandés le meilleur matériel pour le sable cinétique et les jeux sensoriels.', title_hi = 'रेत और मिट्टी थेरेपी 🏖️', body_hi = 'गंदा होने से मत डरिए! काइनेटिक सैंड या सेंसरी खेलों के लिए सबसे अच्छी चीज़ें तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Terapi pasir dan lumpur 🏖️', body_id = 'Jangan takut kotor! Temukan perlengkapan terbaik untuk pasir kinetik dan permainan sensorik di bagian Produk Rekomendasi.', title_ja = '砂と泥んこセラピー 🏖️', body_ja = '汚れるのをこわがらないで！キネティックサンドや感覚遊びにぴったりのアイテムを、「おすすめ商品」ですぐに見つけましょう。', title_ko = '모래와 진흙 테라피 🏖️', body_ko = '더러워지는 걸 두려워하지 마세요! 키네틱 샌드와 감각 놀이에 좋은 도구를 추천 제품 섹션에서 바로 찾아보세요.', title_nl = 'Zand- en moddertherapie 🏖️', body_nl = 'Wees niet bang voor vieze handjes! Ontdek meteen in Aanbevolen producten de beste spullen voor kinetisch zand en zintuiglijke spelletjes.', title_pl = 'Terapia piaskiem i błotem 🏖️', body_pl = 'Nie bój się brudu! Od razu odkryj w sekcji Polecane produkty najlepsze akcesoria do piasku kinetycznego i zabaw sensorycznych.', title_pt = 'Terapia com areia e lama 🏖️', body_pt = 'Não tenha medo que se suje! Descubra já na secção Produtos Recomendados os melhores materiais de areia cinética e brincadeiras sensoriais.', title_sv = 'Sand- och leraterapi 🏖️', body_sv = 'Var inte rädd för smuts! Upptäck direkt de bästa produkterna för kinetisk sand och sinneslekar i Rekommenderade produkter.', title_vi = 'Liệu pháp cát và bùn 🏖️', body_vi = 'Đừng sợ bé bị bẩn! Hãy khám phá ngay những món đồ tốt nhất về cát động lực học hoặc trò chơi giác quan trong mục Sản phẩm gợi ý.', title_zh = '沙子和泥巴疗法 🏖️', body_zh = '别怕弄脏！马上去推荐商品板块，发现最好的动力沙和感官游戏用品。' WHERE id = 'a8ac0c29-0fa0-4dec-a0ed-2411236fabc2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de gastar energía 🧗', body_es = 'Las paredes de casa se le quedan cortas. Abre el mapa de Lugares para mamás y busca un sitio con una zona de juegos segura y de suelo blando donde pueda saltar y correr.', title_fr = 'L''art de se dépenser 🧗', body_fr = 'Les murs de la maison ne lui suffisent plus. Ouvrez la carte des Lieux adaptés aux mamans et trouvez un lieu avec une aire de jeux sûre au sol souple, où il pourra sauter et courir.', title_hi = 'ऊर्जा निकालने की कला 🧗', body_hi = 'घर की दीवारें उसके लिए काफ़ी नहीं। माँ के लिए अनुकूल जगहें का नक्शा खोलिए और ऐसी जगह ढूँढिए जहाँ नरम ज़मीन वाला सुरक्षित प्ले ज़ोन हो और वह कूद-दौड़ सके।', title_id = 'Seni menyalurkan energi 🧗', body_id = 'Dinding rumah tak cukup untuknya. Buka peta Tempat Ramah Ibu dan temukan tempat dengan zona bermain beralas lembut yang aman untuk melompat dan berlari.', title_ja = 'エネルギーを発散するコツ 🧗', body_ja = '家の中だけでは足りません。「ママにやさしいスポット」のマップを開いて、跳んだり走ったりできる、やわらかい地面の安全な遊び場を見つけましょう。', title_ko = '에너지 발산의 기술 🧗', body_ko = '집 안으로는 부족해요. 엄마 친화 장소 지도를 열어 마음껏 뛰고 달릴 수 있는 바닥이 푹신한 안전한 놀이 공간을 찾아보세요.', title_nl = 'De kunst van energie kwijtraken 🧗', body_nl = 'De muren van het huis zijn niet genoeg voor hem. Open de kaart Mamavriendelijke plekken en zoek een plek met een veilige speelzone met zachte ondergrond waar hij kan springen en rennen.', title_pl = 'Sztuka rozładowania energii 🧗', body_pl = 'W domu jest mu za ciasno. Otwórz mapę Miejsc przyjaznych mamom i znajdź miejsce z bezpieczną strefą zabaw o miękkiej nawierzchni, gdzie wyskacze się i wybiega.', title_pt = 'A arte de gastar energia 🧗', body_pt = 'As paredes de casa não lhe chegam. Abra o mapa dos Locais Amigos das Mães e encontre um sítio com uma zona de brincar segura e piso macio, onde possa saltar e correr.', title_sv = 'Konsten att få ut energi 🧗', body_sv = 'Väggarna hemma räcker inte till. Öppna kartan i Mammavänliga platser och hitta ett ställe med en säker lekyta med mjukt underlag där barnet kan hoppa och springa.', title_vi = 'Nghệ thuật xả năng lượng 🧗', body_vi = 'Nhà không đủ chỗ cho bé. Hãy mở bản đồ Địa điểm thân thiện với mẹ, tìm một nơi có khu vui chơi an toàn, nền mềm để bé thỏa sức chạy nhảy.', title_zh = '释放精力的艺术 🧗', body_zh = '家里的墙已经不够宝宝折腾了。打开妈妈友好场所地图，找一个有软地面、能蹦能跑的安全游乐区。' WHERE id = '5c1b9d9c-ddd2-4dad-b93e-0902ebeb2417' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Apetito selectivo 🥦', body_es = '¿Solo quiere pasta o pan? Analiza su menú con el Seguimiento de tomas y completa las vitaminas que falten con raciones divertidas de Recetas para bebé.', title_fr = 'Un appétit difficile 🥦', body_fr = 'Il ne veut que des pâtes ou du pain ? Analysez son menu avec le Suivi des repas et complétez les vitamines manquantes avec les portions amusantes des Recettes pour bébés.', title_hi = 'चुनिंदा भूख 🥦', body_hi = 'सिर्फ़ पास्ता या रोटी चाहता है? फ़ीडिंग ट्रैकर से मेन्यू का विश्लेषण कीजिए और कम पड़ रहे विटामिन बच्चों की रेसिपी के दिलचस्प हिस्सों से पूरे कीजिए।', title_id = 'Pilih-pilih makanan 🥦', body_id = 'Hanya mau pasta atau roti? Analisis menunya dengan alat Pemantau Nutrisi dan lengkapi vitamin yang kurang dengan porsi menarik dari Resep Bayi.', title_ja = '好き嫌いのある食欲 🥦', body_ja = 'パスタやパンばかりほしがりますか？「栄養管理ツール」でメニューを分析して、足りないビタミンは「離乳食を始める赤ちゃんのレシピ」の楽しい一皿で補いましょう。', title_ko = '까다로운 입맛 🥦', body_ko = '파스타나 빵만 찾나요? 수유 기록 도구로 식단을 분석하고, 부족한 비타민은 아기 레시피의 재미있는 메뉴로 채워 주세요.', title_nl = 'Kieskeurige eter 🥦', body_nl = 'Wil hij alleen pasta of brood? Analyseer het menu met de Voedingstracker en vul ontbrekende vitamines aan met leuke porties uit Babyrecepten.', title_pl = 'Wybredny apetyt 🥦', body_pl = 'Chce tylko makaronu albo chleba? Przeanalizuj menu w narzędziu do śledzenia karmienia i uzupełnij brakujące witaminy ciekawymi porcjami z Przepisów dla niemowląt.', title_pt = 'Apetite seletivo 🥦', body_pt = 'Só quer massa ou pão? Analise a ementa com o Registo de Alimentação e complete as vitaminas em falta com porções apelativas das Receitas para bebés.', title_sv = 'Kräsen aptit 🥦', body_sv = 'Vill barnet bara ha pasta eller bröd? Analysera menyn med Matningskoll och fyll på vitaminerna som fattas med roliga portioner från Recept för bebisar.', title_vi = 'Kén ăn 🥦', body_vi = 'Bé chỉ muốn ăn mì ống hoặc bánh mì? Hãy phân tích thực đơn bằng Theo dõi cữ bú và bổ sung vitamin còn thiếu bằng những phần ăn thú vị trong Công thức cho bé.', title_zh = '挑食 🥦', body_zh = '只想吃意面或面包？用喂养记录工具分析一下菜单，再用宝宝食谱里有趣的小份餐补上缺少的维生素。' WHERE id = '7c5f1c11-9db4-4f7a-913f-8ca7bf583cb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se le acaba la energía a mamá? 🔋', body_es = '¿Te entra sueño de pie a mediodía? Prepara en Recetas saludables para mujeres un batido de crema de cacahuete con proteínas que te da fuerza al instante sin necesidad de cafeína.', title_fr = 'Maman est à court d''énergie ? 🔋', body_fr = 'Vous somnolez debout à midi ? Préparez avec les Recettes saines pour femmes un smoothie protéiné au beurre de cacahuète qui vous redonne de l''énergie sans caféine.', title_hi = 'माँ की ऊर्जा खत्म हो रही है? 🔋', body_hi = 'दोपहर में खड़े-खड़े ऊँघ रही हैं? महिलाओं के लिए सेहतमंद रेसिपी से कैफ़ीन के बिना तुरंत ताकत देने वाली, प्रोटीन से भरपूर पीनट बटर स्मूदी बनाइए।', title_id = 'Energi Bunda mulai habis? 🔋', body_id = 'Terkantuk-kantuk sambil berdiri di siang hari? Buat smoothie selai kacang kaya protein dari Resep Sehat untuk wanita yang langsung memberi tenaga tanpa perlu kafein.', title_ja = 'ママのエネルギーが切れそう？🔋', body_ja = 'お昼に立ったままうとうとしていませんか？「女性のためのヘルシーレシピ」から、カフェインに頼らずすぐに元気が出る、たんぱく質たっぷりのピーナッツバタースムージーをつくりましょう。', title_ko = '엄마의 에너지가 바닥났나요? 🔋', body_ko = '오후에 선 채로 꾸벅꾸벅 조나요? 여성을 위한 건강한 레시피에서 카페인 없이도 바로 힘이 나는 단백질 땅콩버터 스무디를 만들어 보세요.', title_nl = 'Is mama''s energie op? 🔋', body_nl = 'Dut je ''s middags staand bijna in? Maak uit Gezonde recepten voor vrouwen een eiwitrijke smoothie met pindakaas die je zonder cafeïne meteen kracht geeft.', title_pl = 'Mamie kończy się energia? 🔋', body_pl = 'Przysypiasz w południe na stojąco? Przygotuj ze Zdrowych przepisów dla kobiet białkowe smoothie z masłem orzechowym, które od razu doda ci sił bez kofeiny.', title_pt = 'A energia da mãe está a acabar? 🔋', body_pt = 'Ao meio-dia está a dormitar de pé? Prepare nas Receitas Saudáveis para Mulheres um batido de manteiga de amendoim rico em proteína, que dá força na hora sem precisar de cafeína.', title_sv = 'Tar mammas energi slut? 🔋', body_sv = 'Nickar du till stående mitt på dagen? Gör en proteinrik smoothie med jordnötssmör som ger kraft direkt utan koffein från Hälsosamma recept för kvinnor.', title_vi = 'Mẹ cạn năng lượng? 🔋', body_vi = 'Buổi trưa mẹ đứng cũng ngủ gật? Hãy làm ly sinh tố bơ đậu phộng giàu đạm, tiếp sức tức thì mà không cần caffeine từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的电量快没了？🔋', body_zh = '中午站着都要打瞌睡？从女性健康食谱里做一杯不靠咖啡因、马上补充能量的高蛋白花生酱奶昔。' WHERE id = '74a21e11-19bb-4326-af8e-197831260dd5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Todas las cazuelas de la cocina están por el suelo?', body_es = 'Jugar con objetos inofensivos desarrolla su pensamiento lógico. Deja que explore su tesoro a sus anchas.', title_fr = 'Toutes les casseroles sont par terre ?', body_fr = 'Jouer avec des objets sans danger développe sa pensée logique. Laissez-le explorer librement son trésor.', title_hi = 'रसोई के सारे बर्तन ज़मीन पर हैं?', body_hi = 'सुरक्षित चीज़ों से खेलना उसकी तार्किक सोच को बढ़ाता है। उसे अपने खज़ाने को खुलकर खोजने दीजिए।', title_id = 'Semua panci di dapur ada di lantai?', body_id = 'Bermain dengan benda yang aman mengembangkan pemikiran logisnya. Biarkan ia bebas menjelajahi harta karunnya.', title_ja = 'キッチンのお鍋が全部床に？', body_ja = '安全なもので遊ぶことは、論理的な思考を育てます。自分の宝物を自由に探検させてあげましょう。', title_ko = '주방의 냄비가 모두 바닥에 나와 있나요?', body_ko = '안전한 물건으로 노는 건 논리적 사고를 키워 줘요. 자기만의 보물을 마음껏 탐험하게 해 주세요.', title_nl = 'Liggen alle pannen uit de keuken op de grond?', body_nl = 'Spelen met onschadelijke spullen ontwikkelt zijn logisch denken. Laat hem vrij zijn schatten ontdekken.', title_pl = 'Wszystkie garnki z kuchni na podłodze?', body_pl = 'Zabawa bezpiecznymi przedmiotami rozwija jego logiczne myślenie. Pozwól mu swobodnie odkrywać swoje skarby.', title_pt = 'Os tachos da cozinha estão todos no chão?', body_pt = 'Brincar com objetos inofensivos desenvolve o pensamento lógico dele. Deixe-o descobrir à vontade o seu tesouro.', title_sv = 'Ligger alla kastruller från köket på golvet?', body_sv = 'Att leka med ofarliga föremål utvecklar det logiska tänkandet. Låt barnet fritt utforska sin skatt.', title_vi = 'Tất cả nồi niêu trong bếp đều nằm dưới sàn?', body_vi = 'Chơi với những đồ vật vô hại giúp phát triển tư duy logic của bé. Hãy để bé tự do khám phá kho báu của mình.', title_zh = '厨房里的锅全在地上？', body_zh = '玩安全的物品能促进宝宝的逻辑思维。让宝宝自由地探索自己的宝藏吧。' WHERE id = '25dc715a-32c8-4d74-92d1-69586eb52b13' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juguetes inteligentes 🧩', body_es = 'Una mente de 2 años necesita juguetes que enseñen, no solo que hagan ruido. Descubre en Productos recomendados puzles de madera que desarrollan la lógica.', title_fr = 'Jouets malins 🧩', body_fr = 'À 2 ans, il lui faut des jouets qui apprennent des choses, pas seulement qui font du bruit. Découvrez dans les Produits recommandés des puzzles en bois qui développent la logique.', title_hi = 'स्मार्ट खिलौने 🧩', body_hi = '2 साल के दिमाग के लिए सिर्फ़ आवाज़ करने वाले नहीं, सिखाने वाले खिलौने चाहिए। सुझाए गए प्रोडक्ट में तर्क बढ़ाने वाली लकड़ी की पज़ल खोजिए।', title_id = 'Mainan cerdas 🧩', body_id = 'Kecerdasan anak 2 tahun butuh mainan yang mengajarkan sesuatu, bukan sekadar berbunyi. Temukan puzzle kayu yang mengembangkan logika di Produk Rekomendasi.', title_ja = 'かしこいおもちゃ 🧩', body_ja = '2歳の知性には、音が出るだけでなく、学びのあるおもちゃが必要です。「おすすめ商品」で、論理的な思考を育てる木のパズルを見つけましょう。', title_ko = '똑똑한 장난감 🧩', body_ko = '두 살 아이의 두뇌에는 소리만 나는 장난감이 아니라 배우게 하는 장난감이 필요해요. 추천 제품에서 논리력을 키우는 원목 퍼즐을 찾아보세요.', title_nl = 'Slim speelgoed 🧩', body_nl = 'Een slim kind van 2 heeft speelgoed nodig dat iets leert, niet alleen geluid maakt. Ontdek in Aanbevolen producten houten puzzels die de logica ontwikkelen.', title_pl = 'Mądre zabawki 🧩', body_pl = 'Umysł 2-latka potrzebuje zabawek, które nie tylko hałasują, ale też uczą. Odkryj w Polecanych produktach drewniane układanki rozwijające logikę.', title_pt = 'Brinquedos inteligentes 🧩', body_pt = 'Uma inteligência de 2 anos precisa de brinquedos que ensinem, não só que façam barulho. Descubra nos Produtos Recomendados puzzles de madeira que desenvolvem a lógica.', title_sv = 'Smarta leksaker 🧩', body_sv = 'En 2-årings tänkande behöver leksaker som lär, inte bara låter. Upptäck träpussel som utvecklar logiken i Rekommenderade produkter.', title_vi = 'Đồ chơi thông minh 🧩', body_vi = 'Trí tuệ của bé 2 tuổi cần những món đồ chơi dạy được điều gì đó, không chỉ phát ra âm thanh. Hãy khám phá các bộ ghép hình gỗ phát triển tư duy trong Sản phẩm gợi ý.', title_zh = '聪明玩具 🧩', body_zh = '2岁的小脑瓜需要的不只是会发声的玩具，而是能教东西的玩具。在推荐商品里发现促进逻辑发展的木制拼图。' WHERE id = '247c6eba-b9c7-406d-95d9-27a9c74871bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La central de energía de mamá 🥗', body_es = '¡No olvides recargar tu propia batería! Prepara en Recetas saludables un batido de crema de cacahuete con proteínas que da energía al instante.', title_fr = 'La centrale d''énergie de maman 🥗', body_fr = 'N''oubliez pas de recharger vos propres batteries ! Préparez avec les Recettes saines un smoothie protéiné au beurre de cacahuète, énergisant en un instant.', title_hi = 'माँ का पावर सेंटर 🥗', body_hi = 'अपनी बैटरी चार्ज करना मत भूलिए! सेहतमंद रेसिपी से तुरंत ऊर्जा देने वाली, प्रोटीन से भरपूर पीनट बटर स्मूदी बनाइए।', title_id = 'Pusat tenaga Bunda 🥗', body_id = 'Jangan lupa mengisi baterai Anda sendiri! Buat smoothie selai kacang kaya protein yang langsung memberi energi dari Resep Sehat.', title_ja = 'ママのパワーの源 🥗', body_ja = '自分のバッテリーを充電するのも忘れないで！「ヘルシーレシピ」から、すぐに元気が出るたんぱく質たっぷりのピーナッツバタースムージーをつくりましょう。', title_ko = '엄마의 에너지 충전소 🥗', body_ko = '엄마의 배터리 충전도 잊지 마세요! 건강한 레시피에서 바로 힘이 나는 땅콩버터 단백질 스무디를 만들어 보세요.', title_nl = 'Krachtcentrale van mama 🥗', body_nl = 'Vergeet niet je eigen batterij op te laden! Maak uit Gezonde recepten een eiwitrijke smoothie met pindakaas die je meteen energie geeft.', title_pl = 'Źródło siły mamy 🥗', body_pl = 'Nie zapominaj naładować własnych baterii! Przygotuj ze Zdrowych przepisów białkowe smoothie z masłem orzechowym, które od razu doda ci energii.', title_pt = 'A central de energia da mãe 🥗', body_pt = 'Não se esqueça de carregar a sua própria bateria! Prepare com as Receitas Saudáveis um batido de manteiga de amendoim rico em proteína, que dá energia na hora.', title_sv = 'Mammas kraftcenter 🥗', body_sv = 'Glöm inte att ladda dina egna batterier! Gör en proteinrik smoothie med jordnötssmör som ger energi direkt från Hälsosamma recept.', title_vi = 'Trạm năng lượng của mẹ 🥗', body_vi = 'Đừng quên sạc pin cho chính mình! Hãy làm ly sinh tố bơ đậu phộng giàu đạm, tiếp năng lượng tức thì từ Công thức lành mạnh.', title_zh = '妈妈的能量中心 🥗', body_zh = '别忘了给自己充电！从健康食谱里做一杯马上补充能量、富含蛋白质的花生酱奶昔。' WHERE id = '9c2176f9-4583-459e-b4a3-631c624068de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'La primera media hora tras dormirse es el momento más delicado. Comprueba los decibelios del ambiente con el Medidor de sonido y evita los ruidos repentinos.', body_fr = 'La première demi-heure après l''endormissement est la plus fragile. Vérifiez le niveau de décibels de la pièce avec le Sonomètre et évitez tout bruit soudain.', body_hi = 'सोने के बाद का पहला आधा घंटा सबसे नाज़ुक होता है। साउंड मीटर से माहौल का डेसिबल जाँचिए और अचानक के शोर से बचिए।', body_id = 'Setengah jam pertama setelah ia tertidur adalah waktu paling rawan. Cek desibel ruangan dengan Pengukur Suara dan hindari suara bising yang tiba-tiba.', body_ja = '眠りについてから最初の30分は、いちばん眠りが浅い時間です。「サウンドメーター」で周りのデシベルを確認し、急な物音を避けましょう。', body_ko = '잠든 뒤 첫 30분이 가장 예민한 시간이에요. 소음 측정기로 방의 데시벨을 확인하고 갑작스러운 소음을 피하세요.', body_nl = 'Het eerste halfuur na het inslapen is het gevoeligst. Controleer met de Geluidsmeter het aantal decibel in de kamer en vermijd plotseling lawaai.', body_pl = 'Pierwsze pół godziny po zaśnięciu to najbardziej wrażliwy czas. Sprawdź Miernikiem dźwięku poziom decybeli i unikaj nagłego hałasu.', body_pt = 'A primeira meia hora depois de adormecer é o momento mais sensível. Verifique os decibéis do ambiente com o Medidor de Som e evite barulhos repentinos.', body_sv = 'Den första halvtimmen efter insomnandet är den känsligaste. Kontrollera decibelnivån med Ljudmätaren och undvik plötsligt buller.', body_vi = 'Nửa giờ đầu sau khi bé ngủ là lúc nhạy cảm nhất. Hãy kiểm tra decibel bằng Đo âm thanh và tránh tiếng ồn đột ngột.', body_zh = '入睡后的头半小时最敏感。用分贝仪检查环境分贝，远离突然的噪音。' WHERE id = '43609cdd-bc75-4be9-80ac-98506e0aba38' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No quiere sentarse a la mesa 🥣', body_es = '¿Se cansa enseguida de comer y sale corriendo? Pon el temporizador de tomas, anota cuánto dura la comida y evita por completo obligarle a comer.', title_fr = 'Il ne veut pas rester à table 🥣', body_fr = 'Il se lasse vite du repas et s''enfuit ? Lancez le minuteur des repas, notez la durée du repas et évitez complètement de le forcer à manger.', title_hi = 'मेज़ पर बैठना नहीं चाहता 🥣', body_hi = 'खाने से जल्दी ऊबकर भाग जाता है? फ़ीडिंग टाइमर चालू कीजिए, समय दर्ज कीजिए और ज़बरदस्ती खिलाने से पूरी तरह बचिए।', title_id = 'Tidak mau duduk di meja makan 🥣', body_id = 'Cepat bosan makan lalu kabur? Nyalakan Timer Makan, catat durasinya, dan hindari sepenuhnya memaksanya makan.', title_ja = '食卓に座りたがらない 🥣', body_ja = '食事にすぐ飽きて逃げていきますか？食事タイマーをオンにして食事の時間を記録し、無理に食べさせるのは完全に避けましょう。', title_ko = '식탁에 앉기 싫어해요 🥣', body_ko = '금방 싫증 내고 식탁을 떠나나요? 수유 타이머를 켜서 식사 시간을 기록하고 억지로 먹이는 건 완전히 피하세요.', title_nl = 'Wil niet aan tafel zitten 🥣', body_nl = 'Is hij snel klaar met eten en rent hij weg? Zet de Voedingstimer aan, noteer hoe lang de maaltijd duurt en dwing hem nooit te eten.', title_pl = 'Nie chce siedzieć przy stole 🥣', body_pl = 'Szybko nudzi się jedzeniem i ucieka? Włącz timer karmienia, zanotuj czas posiłku i całkowicie unikaj karmienia na siłę.', title_pt = 'Não quer ficar sentado à mesa 🥣', body_pt = 'Cansa-se depressa da comida e foge? Ligue o temporizador de alimentação, registe a duração e evite por completo obrigá-lo a comer.', title_sv = 'Vill inte sitta vid bordet 🥣', body_sv = 'Tröttnar barnet snabbt på maten och springer iväg? Starta matningstimern, anteckna hur lång tid måltiden tar och undvik helt att tvångsmata.', title_vi = 'Bé không muốn ngồi vào bàn 🥣', body_vi = 'Bé nhanh chán và bỏ chạy khỏi bữa ăn? Hãy bật Hẹn giờ cho bú, ghi lại thời gian và tuyệt đối tránh ép bé ăn.', title_zh = '不肯坐在餐桌前 🥣', body_zh = '很快就吃腻了，起身就跑？打开喂养计时器，记下用餐时长，完全避免强迫喂饭。' WHERE id = '17c8a3a6-67b0-49ab-a185-9e25f788bb11' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Después del ruido de ayer, protege la calma de la habitación con el Medidor de sonido. Un sueño interrumpido por la noche estropea su humor y el tuyo.', body_fr = 'Après le bruit d''hier, préservez le calme de la chambre avec le Sonomètre. Un sommeil interrompu la nuit gâche son humeur comme la vôtre.', body_hi = 'कल के शोर के बाद साउंड मीटर से कमरे की शांति बनाए रखिए। रात में टूटी नींद उसका और आपका, दोनों का मूड बिगाड़ती है।', body_id = 'Setelah keramaian kemarin, jaga ketenangan kamar dengan Pengukur Suara. Tidur malam yang terputus merusak suasana hati ia dan Anda.', body_ja = '昨日のにぎやかさのあとは、「サウンドメーター」で部屋の静けさを守りましょう。夜に途切れる眠りは、お子さんとあなたの両方の気分を乱します。', body_ko = '어제의 소란 뒤에는 소음 측정기로 방의 고요함을 지켜 주세요. 밤에 깨는 잠은 아이와 엄마의 기분을 모두 망쳐요.', body_nl = 'Bewaak na het lawaai van gisteren de rust in de kamer met de Geluidsmeter. Een onderbroken nachtrust verpest zijn humeur en dat van jou.', body_pl = 'Po wczorajszym hałasie chroń ciszę w pokoju z Miernikiem dźwięku. Przerywany nocny sen psuje nastrój i jemu, i tobie.', body_pt = 'Depois do barulho de ontem, proteja o silêncio do quarto com o Medidor de Som. Um sono interrompido à noite estraga o humor dele e o seu.', body_sv = 'Efter gårdagens oväsen, skydda lugnet i rummet med Ljudmätaren. Avbruten nattsömn förstör både barnets och ditt humör.', body_vi = 'Sau những ồn ào hôm qua, hãy giữ sự yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ bị gián đoạn ban đêm làm ảnh hưởng tâm trạng của cả bé lẫn mẹ.', body_zh = '昨天热闹过后，用分贝仪守护房间的安静吧。夜里睡眠被打断，会影响宝宝和你的心情。' WHERE id = '32abe85c-b2ef-4ebb-aa71-2ad4fbb4e416' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Después de la fiesta de ayer la casa está patas arriba? No corras a limpiar. Dedica el día de hoy a descansar con tu peque que acaba de cumplir 2 años.', body_fr = 'La maison est sens dessus dessous après la fête d''hier ? Ne vous ruez pas sur le ménage. Consacrez simplement cette journée au repos avec votre nouveau grand de 2 ans.', body_hi = 'कल की पार्टी के बाद घर बिखरा पड़ा है? सफ़ाई की ओर मत भागिए। अपने नए-नए 2 साल के नन्हे के साथ आज का दिन बस आराम में बिताइए।', body_id = 'Rumah berantakan setelah pesta kemarin? Jangan buru-buru bersih-bersih. Khususkan hari ini untuk bersantai bersama si kecil yang kini berusia 2 tahun.', body_ja = '昨日のパーティーのあと、家がめちゃくちゃ？掃除に走らないで。新しく2歳になったお子さんと、今日はただゆっくり過ごしましょう。', body_ko = '어제 파티 뒤로 집이 엉망인가요? 청소로 달려가지 마세요. 오늘은 새로 두 살이 된 아이와 그냥 쉬는 날로 보내세요.', body_nl = 'Is het huis een chaos na het feest van gisteren? Ren niet meteen naar de schoonmaak. Wijd deze dag gewoon aan uitrusten met je kersverse tweejarige.', body_pl = 'Po wczorajszej imprezie w domu pobojowisko? Nie rzucaj się do sprzątania. Poświęć dzisiejszy dzień na odpoczynek ze swoim świeżo upieczonym 2-latkiem.', body_pt = 'Depois da festa de ontem, a casa está virada do avesso? Não corra para as limpezas. Dedique o dia de hoje só a descansar com o seu novo menino de 2 anos.', body_sv = 'Är huset kaos efter gårdagens kalas? Rusa inte till städningen. Ägna bara dagen åt vila med din nyblivna 2-åring.', body_vi = 'Sau bữa tiệc hôm qua nhà cửa tan hoang? Đừng vội dọn dẹp. Hãy dành trọn hôm nay để nghỉ ngơi cùng "cô cậu 2 tuổi" của mẹ.', body_zh = '昨天派对过后家里一片狼藉？别急着打扫。今天就和你刚满2岁的小家伙一起好好休息吧。' WHERE id = '8796a078-f4e3-4ea5-9258-919333a4b718' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Artista de la naturaleza 🍂', body_es = '¡Salid de casa! Las hojas y piedras del parque son el mejor material sensorial. Busca en Lugares para mamás un sitio con mucho verde.', title_fr = 'Petit artiste de la nature 🍂', body_fr = 'Sortez de la maison ! Les feuilles et les cailloux du parc sont le meilleur matériel sensoriel. Trouvez un lieu plein de verdure dans les Lieux adaptés aux mamans.', title_hi = 'प्रकृति का नन्हा कलाकार 🍂', body_hi = 'घर से निकलिए! पार्क के पत्ते और पत्थर सबसे अच्छी सेंसरी चीज़ें हैं। माँ के लिए अनुकूल जगहें में खूब हरियाली वाली जगह ढूँढिए।', title_id = 'Seniman alam 🍂', body_id = 'Keluarlah dari rumah! Daun dan batu di taman adalah bahan sensorik terbaik. Temukan tempat yang hijau dan luas di Tempat Ramah Ibu.', title_ja = '自然のアーティスト 🍂', body_ja = 'お出かけしましょう！公園の葉っぱや石は、最高の感覚あそびの素材です。「ママにやさしいスポット」で緑の多い場所を見つけましょう。', title_ko = '자연 속 예술가 🍂', body_ko = '집 밖으로 나가세요! 공원의 나뭇잎과 돌멩이는 최고의 감각 놀이 재료예요. 엄마 친화 장소에서 푸른 녹지가 넓은 곳을 찾아보세요.', title_nl = 'Natuurkunstenaar 🍂', body_nl = 'Ga naar buiten! Bladeren en steentjes in het park zijn het beste zintuiglijke materiaal. Zoek in Mamavriendelijke plekken een plek met veel groen.', title_pl = 'Artysta natury 🍂', body_pl = 'Wyjdźcie z domu! Liście i kamienie w parku to najlepszy materiał sensoryczny. Znajdź w Miejscach przyjaznych mamom miejsce z dużą ilością zieleni.', title_pt = 'Artista da natureza 🍂', body_pt = 'Saiam de casa! As folhas e as pedras do parque são o melhor material sensorial. Encontre nos Locais Amigos das Mães um sítio com muito verde.', title_sv = 'Naturens konstnär 🍂', body_sv = 'Gå ut! Löven och stenarna i parken är det bästa sinnesmaterialet. Hitta ett ställe med mycket grönska i Mammavänliga platser.', title_vi = 'Nghệ sĩ thiên nhiên 🍂', body_vi = 'Ra ngoài thôi! Lá và đá trong công viên là chất liệu giác quan tuyệt nhất. Hãy tìm một nơi có nhiều cây xanh rộng rãi trong Địa điểm thân thiện với mẹ.', title_zh = '大自然的小艺术家 🍂', body_zh = '出门吧！公园里的树叶和石头是最好的感官材料。在妈妈友好场所里找一个绿地宽阔的地方。' WHERE id = '07c79611-988f-4228-b928-f34af1a7425a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mucha agua, digestión fácil 💧', body_es = '¿De tanto correr se olvida de beber agua? Haz la anotación de la mañana en el Seguimiento de pañales y analiza enseguida el equilibrio de líquidos y fibra para prevenir el estreñimiento.', title_fr = 'Beaucoup d''eau, digestion facile 💧', body_fr = 'Il oublie de boire à force de courir ? Notez la couche du matin dans le Suivi des couches et analysez tout de suite l''équilibre liquides/fibres pour éviter la constipation.', title_hi = 'खूब पानी, आसान पाचन 💧', body_hi = 'दौड़ने में पानी पीना भूल जाता है? डायपर ट्रैकर में सुबह की एंट्री कीजिए और कब्ज़ से बचने के लिए तरल/फ़ाइबर का संतुलन तुरंत जाँचिए।', title_id = 'Banyak minum, pencernaan lancar 💧', body_id = 'Lupa minum karena asyik berlari? Buat catatan pagi di Pelacak Popok dan segera analisis keseimbangan cairan/serat untuk mencegah sembelit.', title_ja = 'たっぷりの水分で、すっきり消化 💧', body_ja = '走り回ってお水を飲むのを忘れていますか？「おむつトラッカー」に朝の記録をつけて、便秘を防ぐために水分と食物繊維のバランスをすぐに分析しましょう。', title_ko = '물을 많이, 소화는 편하게 💧', body_ko = '뛰어노느라 물 마시는 걸 잊나요? 기저귀 기록에 아침 기록을 남기고 변비 예방을 위해 수분과 섬유질 균형을 바로 분석하세요.', title_nl = 'Veel water, makkelijke spijsvertering 💧', body_nl = 'Vergeet hij door het rennen te drinken? Noteer de ochtendluier in de Luiertracker en analyseer meteen de balans van vocht en vezels tegen verstopping.', title_pl = 'Dużo wody, łatwe trawienie 💧', body_pl = 'Przez bieganie zapomina pić? Zrób poranny wpis w narzędziu do śledzenia pieluszek i od razu przeanalizuj bilans płynów i błonnika, by zapobiec zaparciom.', title_pt = 'Muita água, digestão fácil 💧', body_pt = 'De tanto correr, esquece-se de beber água? Faça o registo da manhã no Registo de Fraldas e analise já o equilíbrio de líquidos e fibra para prevenir a prisão de ventre.', title_sv = 'Mycket vatten, lätt matsmältning 💧', body_sv = 'Glömmer barnet att dricka för att hen springer? Gör morgonanteckningen i Blöjkollen och analysera direkt balansen mellan vätska och fibrer mot risken för förstoppning.', title_vi = 'Uống nhiều nước, tiêu hóa dễ dàng 💧', body_vi = 'Mải chạy nhảy mà bé quên uống nước? Hãy ghi lại lần thay tã buổi sáng trong Theo dõi tã và phân tích ngay cân bằng nước/chất xơ để phòng táo bón.', title_zh = '多喝水，好消化 💧', body_zh = '跑得忘了喝水？在尿布记录里做好早上的记录，马上分析水分和纤维的平衡，预防便秘。' WHERE id = '14d525a3-b7d6-43c1-9919-132c8691cf60' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El hábito del cuento de la noche 📖', body_es = '¿Repite a su manera el cuento que le has leído? Añade ya este gran salto del lenguaje en vídeo con sonido al Álbum del bebé y guárdalo para el futuro.', title_fr = 'L''habitude du conte du soir 📖', body_fr = 'Il répète dans sa langue le conte que vous avez lu ? Ajoutez tout de suite ce formidable bond du langage en vidéo avec le son à l''Album de bébé pour le garder.', title_hi = 'शाम की कहानी की आदत 📖', body_hi = 'आपकी सुनाई कहानी अपनी भाषा में दोहराता है? भाषा की इस शानदार छलांग को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़कर भविष्य के लिए सहेजिए।', title_id = 'Kebiasaan dongeng malam 📖', body_id = 'Ia mengulang dongeng yang Anda bacakan dengan bahasanya sendiri? Segera simpan lompatan bahasa yang luar biasa ini sebagai video bersuara di Album Bayi untuk masa depan.', title_ja = '夜の読み聞かせの習慣 📖', body_ja = '読んであげたお話を、自分の言葉で繰り返していますか？このすばらしい言葉の飛躍を、すぐに音声付きの動画で「ベビーアルバム」に追加して、未来に残しましょう。', title_ko = '잠자리 동화 습관 📖', body_ko = '읽어 준 동화를 자기만의 말로 따라 하나요? 이 멋진 언어 도약을 바로 소리가 담긴 영상으로 아기 앨범에 올려 간직하세요.', title_nl = 'Gewoonte van het avondverhaal 📖', body_nl = 'Vertelt hij het verhaal dat je voorlas na in zijn eigen taal? Zet deze geweldige taalsprong meteen als video met geluid in het Babyalbum en bewaar het voor later.', title_pl = 'Nawyk wieczornej bajki 📖', body_pl = 'Powtarza po swojemu bajkę, którą przeczytałaś? Od razu dodaj ten wspaniały skok językowy jako film z dźwiękiem do Albumu dziecka i zachowaj na przyszłość.', title_pt = 'O hábito da história da noite 📖', body_pt = 'Repete à sua maneira a história que lhe leu? Adicione já este salto fantástico na linguagem em vídeo com som ao Álbum do Bebé e guarde-o para o futuro.', title_sv = 'Vanan med kvällssaga 📖', body_sv = 'Upprepar barnet sagan du läst på sitt eget språk? Spela in detta fantastiska språksprång direkt som video med ljud i Babyalbumet och spara det för framtiden.', title_vi = 'Thói quen nghe truyện buổi tối 📖', body_vi = 'Bé kể lại câu chuyện mẹ đọc bằng ngôn ngữ của riêng mình? Hãy quay ngay video có tiếng bước nhảy vọt ngôn ngữ tuyệt vời này và lưu vào Album của bé.', title_zh = '睡前故事的习惯 📖', body_zh = '用自己的语言复述你读过的故事？马上把这次了不起的语言飞跃录成有声视频加进宝宝相册，留给未来。' WHERE id = '8a2ef907-aa42-42a0-b57d-125e83745fe9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ilusión de la perfección 🛋️', body_es = 'No te juzgues comparándote con las madres siempre sonrientes de las redes sociales. Tu cansancio y tu habitación desordenada son la realidad más natural.', title_fr = 'L''illusion de la perfection 🛋️', body_fr = 'Ne vous jugez pas en regardant les mamans toujours souriantes des réseaux sociaux. Votre fatigue, comme votre chambre en désordre, c''est la réalité la plus naturelle.', title_hi = 'परफ़ेक्ट होने का भ्रम 🛋️', body_hi = 'सोशल मीडिया पर हमेशा खुश दिखने वाली माँओं को देखकर खुद को मत कोसिए। आपकी थकान और बिखरा कमरा, दोनों सबसे स्वाभाविक सच्चाई हैं।', title_id = 'Ilusi kesempurnaan 🛋️', body_id = 'Jangan menyalahkan diri sendiri karena melihat ibu-ibu yang selalu ceria di media sosial. Rasa lelah dan kamar Anda yang berantakan adalah kenyataan yang paling wajar.', title_ja = '完璧という幻想 🛋️', body_ja = 'SNSでいつも楽しそうなママたちを見て、自分を責めないで。あなたの疲れも、散らかった部屋も、ごく自然な現実です。', title_ko = '완벽함이라는 착각 🛋️', body_ko = 'SNS 속 늘 밝은 엄마들과 비교하며 자신을 탓하지 마세요. 엄마의 피로도, 어질러진 방도 가장 자연스러운 현실이에요.', title_nl = 'De illusie van perfectie 🛋️', body_nl = 'Veroordeel jezelf niet als je naar altijd vrolijke moeders op sociale media kijkt. Jouw vermoeidheid en je rommelige kamer zijn de meest natuurlijke werkelijkheid.', title_pl = 'Iluzja perfekcji 🛋️', body_pl = 'Nie obwiniaj się, patrząc na zawsze uśmiechnięte mamy z mediów społecznościowych. Twoje zmęczenie i bałagan w pokoju to najbardziej naturalna rzeczywistość.', title_pt = 'A ilusão da perfeição 🛋️', body_pt = 'Não se culpe ao olhar para as mães sempre alegres das redes sociais. O seu cansaço e o seu quarto desarrumado são a realidade mais natural.', title_sv = 'Illusionen om perfektion 🛋️', body_sv = 'Döm inte dig själv när du ser de alltid glada mammorna på sociala medier. Din trötthet och ditt stökiga rum är den mest naturliga verkligheten.', title_vi = 'Ảo tưởng về sự hoàn hảo 🛋️', body_vi = 'Đừng nhìn những bà mẹ lúc nào cũng vui vẻ trên mạng xã hội mà tự trách mình. Sự mệt mỏi và căn phòng bừa bộn của mẹ là hiện thực tự nhiên nhất.', title_zh = '完美的幻觉 🛋️', body_zh = '别看着社交网络上总是开开心心的妈妈们责怪自己。你的疲惫和乱糟糟的房间，才是最自然的现实。' WHERE id = '8b59959d-35b3-4803-a8d5-668ef810ded0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Es mío!» 🧸', body_es = '¿En el parque no comparte sus juguetes y grita? Aprende con Anacan AI a gestionar de forma sana el egocentrismo de los 2 años antes de que se convierta en agresividad.', title_fr = 'La période « C''est à moi ! » 🧸', body_fr = 'Au parc, il ne partage pas son jouet et crie ? Découvrez avec Anacan AI comment gérer sainement l''égocentrisme des 2 ans avant qu''il ne tourne à l''agressivité.', title_hi = '''मेरा है!'' वाला दौर 🧸', body_hi = 'पार्क में अपना खिलौना नहीं बाँटता और चिल्लाता है? 2 साल के ''सब मेरा'' वाले भाव को आक्रामकता बनने दिए बिना सेहतमंद तरीके से कैसे संभालें, यह Anacan AI से जानिए।', title_id = 'Masa Punyaku! 🧸', body_id = 'Tidak mau berbagi mainan di taman dan berteriak? Pelajari dari Anacan AI cara mengelola egosentrisme usia 2 tahun dengan sehat sebelum berubah menjadi agresi.', title_ja = '「ぼくの！」「わたしの！」の時期 🧸', body_ja = '公園でおもちゃを貸さずに叫びますか？2歳の自己中心的な気持ちを、攻撃的にならないよう健やかに導く方法を、Anacan AIで学びましょう。', title_ko = '''내 거야!'' 시기 🧸', body_ko = '공원에서 장난감을 나누지 않고 소리 지르나요? 두 살의 자기중심성이 공격성으로 번지지 않게 건강하게 다루는 법을 Anacan AI에게 배워 보세요.', title_nl = 'De van mij!-fase 🧸', body_nl = 'Deelt hij in het park zijn speelgoed niet en schreeuwt hij? Leer bij Anacan AI hoe je het egocentrisme van een tweejarige gezond aanpakt voordat het agressie wordt.', title_pl = 'Etap „Moje!” 🧸', body_pl = 'W parku nie dzieli się zabawkami i krzyczy? Dowiedz się od Anacan AI, jak zdrowo radzić sobie z egocentryzmem 2-latka, zanim zamieni się w agresję.', title_pt = 'A fase do "É meu!" 🧸', body_pt = 'No parque não partilha o brinquedo e grita? Aprenda com o Anacan AI a gerir de forma saudável o egocentrismo dos 2 anos, sem que se transforme em agressividade.', title_sv = '”Min!”-perioden 🧸', body_sv = 'Delar barnet inte med sig av leksakerna i parken och skriker? Lär dig av Anacan AI hur du på ett sunt sätt hanterar 2-åringens egocentrism utan att den blir aggressivitet.', title_vi = 'Giai đoạn "Của con!" 🧸', body_vi = 'Ở công viên bé không chia sẻ đồ chơi và la hét? Hãy học từ Anacan AI cách xử lý lành mạnh tính vị kỷ tuổi lên 2 để nó không biến thành hung hăng.', title_zh = '“是我的！”阶段 🧸', body_zh = '在公园不肯分享玩具，还大喊大叫？向Anacan AI学习如何健康地应对2岁的自我中心，不让它变成攻击行为。' WHERE id = '031b0761-047d-4d63-84ce-fd41ce83245b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Poder antiinflamatorio 🍵', body_es = '¿Te duelen la espalda y los brazos de coger a tu peque? Prepárate un té de jengibre y limón de Recetas saludables para mujeres y ayuda a tu cuerpo a recuperarse.', title_fr = 'Force anti-inflammatoire 🍵', body_fr = 'Vous avez mal au dos et aux bras à force de le porter ? Préparez un thé au gingembre et au citron avec les Recettes saines pour femmes pour aider votre corps à récupérer.', title_hi = 'सूजन से लड़ने की ताकत 🍵', body_hi = 'बच्चे को उठाते-उठाते कमर और बाँहें दर्द करती हैं? महिलाओं के लिए सेहतमंद रेसिपी से अदरक और नींबू की चाय बनाइए और शरीर को फिर से ताकत दीजिए।', title_id = 'Kekuatan antiradang 🍵', body_id = 'Punggung dan lengan pegal karena menggendong si kecil? Pulihkan tubuh Anda dengan menyeduh teh jahe lemon dari Resep Sehat untuk wanita.', title_ja = '炎症をおさえるパワー 🍵', body_ja = '抱っこのしすぎで腰や腕が痛いですか？「女性のためのヘルシーレシピ」から、しょうがとレモンのお茶をいれて、体を回復させましょう。', title_ko = '염증을 다스리는 힘 🍵', body_ko = '아이를 안아 올리느라 허리와 팔이 아프나요? 여성을 위한 건강한 레시피에서 생강 레몬차를 우려 몸을 회복하세요.', title_nl = 'Ontstekingsremmende kracht 🍵', body_nl = 'Doen je rug en armen pijn van het tillen? Zet thee met gember en citroen uit Gezonde recepten voor vrouwen en help je lichaam herstellen.', title_pl = 'Moc przeciwzapalna 🍵', body_pl = 'Bolą cię plecy i ręce od noszenia malucha? Zaparz ze Zdrowych przepisów dla kobiet herbatę z imbirem i cytryną i zregeneruj organizm.', title_pt = 'Força anti-inflamatória 🍵', body_pt = 'As costas e os braços doem-lhe de tanto o pegar ao colo? Prepare um chá de gengibre e limão das Receitas Saudáveis para Mulheres e recupere o seu corpo.', title_sv = 'Antiinflammatorisk kraft 🍵', body_sv = 'Gör ryggen och armarna ont av att lyfta barnet? Brygg te med ingefära och citron från Hälsosamma recept för kvinnor och låt kroppen återhämta sig.', title_vi = 'Sức mạnh chống viêm 🍵', body_vi = 'Bế bé nhiều khiến lưng và tay mẹ đau nhức? Hãy pha trà gừng chanh từ Công thức lành mạnh cho phụ nữ để cơ thể phục hồi.', title_zh = '抗炎的力量 🍵', body_zh = '抱孩子抱得腰酸手疼？从女性健康食谱里泡一杯姜柠檬茶，帮助身体恢复。' WHERE id = '16c2ca9a-7971-49b0-9210-b9dd3baea775' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Pasa demasiado tiempo despierto por la tarde? Pon el temporizador de sueño y sigue el gráfico. ¡Quizá sea el momento de acortar la siesta 20 minutos!', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il reste éveillé trop longtemps le soir ? Lancez le minuteur de sommeil et suivez le graphique. Il est peut-être temps de raccourcir la sieste de 20 minutes !', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को जागने का समय बहुत लंबा हो गया? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। शायद दिन की नींद 20 मिनट कम करने का समय आ गया है!', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Waktu terjaga di sore hari terlalu panjang? Nyalakan Timer Tidur dan pantau grafiknya. Mungkin sudah waktunya memangkas tidur siang 20 menit!', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夕方に起きている時間が長くなりすぎていますか？睡眠タイマーをオンにして、グラフを見守りましょう。お昼寝を20分短くするときが来たのかもしれません！', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 깨어 있는 시간이 너무 길어졌나요? 수면 타이머를 켜고 그래프를 살펴보세요. 낮잠을 20분 줄일 때가 되었을지도 몰라요!', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Is hij ''s avonds veel te lang wakker? Zet de Slaaptimer aan en volg de grafiek. Misschien is het tijd om het middagdutje met 20 minuten in te korten!', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorny czas czuwania bardzo się wydłużył? Włącz timer snu i śledź wykres. Może przyszedł czas, by skrócić drzemkę o 20 minut!', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'O tempo acordado ao fim do dia ficou muito longo? Ligue o temporizador de sono e acompanhe o gráfico. Talvez esteja na altura de encurtar a sesta 20 minutos!', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Har vakentiden på kvällen blivit för lång? Starta sömntimern och följ grafen. Kanske är det dags att korta dagsömnen med 20 minuter!', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Thời gian thức buổi tối kéo dài quá lâu? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Có lẽ đã đến lúc giảm giấc ngủ ngày 20 phút!', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上清醒的时间拉得太长了？打开睡眠计时器，看看图表。也许是时候把白天小睡减少20分钟了！' WHERE id = '4645899a-65b7-4ec6-9619-57e71d7569de' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sigue imitando 🦜', body_es = '¿Cuando hablas por teléfono, coge el mando y se lo pone en la oreja? ¡Te copia al 100 %! Intenta ser un buen ejemplo.', title_fr = 'Il continue de vous imiter 🦜', body_fr = 'Quand vous êtes au téléphone, il prend la télécommande et la colle à son oreille ? Il vous copie à 100 % ! Essayez de lui montrer le bon exemple.', title_hi = 'नकल जारी है 🦜', body_hi = 'आप फ़ोन पर बात करती हैं तो वह भी रिमोट उठाकर कान से लगाता है? वह आपकी 100% नकल करता है! उसके लिए अच्छी मिसाल बनने की कोशिश कीजिए।', title_id = 'Masih terus meniru 🦜', body_id = 'Saat Anda menelepon, ia ikut mengambil remote dan menempelkannya ke telinga? Ia meniru Anda 100%! Berusahalah menjadi contoh yang baik untuknya.', title_ja = 'まねっこは続く 🦜', body_ja = 'あなたが電話で話していると、リモコンを耳に当てていますか？あなたを100%まねしています！よいお手本になれるよう心がけましょう。', title_ko = '따라쟁이는 계속돼요 🦜', body_ko = '엄마가 통화할 때 아이도 리모컨을 귀에 대나요? 엄마를 100% 따라 하고 있어요! 좋은 본보기가 되어 주세요.', title_nl = 'Het nadoen gaat door 🦜', body_nl = 'Pakt hij de afstandsbediening en houdt hij die tegen zijn oor als jij belt? Hij kopieert je voor 100%! Probeer een goed voorbeeld te zijn.', title_pl = 'Naśladowanie trwa 🦜', body_pl = 'Gdy rozmawiasz przez telefon, on bierze pilota i przykłada go do ucha? Kopiuje cię w 100%! Staraj się być dla niego dobrym przykładem.', title_pt = 'Continua a imitar 🦜', body_pt = 'Quando fala ao telefone, ele pega no comando e encosta-o à orelha? Está a copiá-la a 100%! Procure ser um bom exemplo para ele.', title_sv = 'Härmandet fortsätter 🦜', body_sv = 'Tar barnet fjärrkontrollen och håller den mot örat när du pratar i telefon? Barnet kopierar dig till 100%! Försök vara ett gott exempel.', title_vi = 'Bé tiếp tục bắt chước 🦜', body_vi = 'Mẹ nghe điện thoại thì bé cũng cầm điều khiển áp lên tai? Bé sao chép mẹ đến 100%! Hãy cố gắng làm tấm gương tốt cho bé nhé.', title_zh = '继续模仿中 🦜', body_zh = '你打电话时，宝宝也拿起遥控器放到耳边？宝宝在100%复制你！努力给宝宝做个好榜样吧。' WHERE id = '5bc99c8b-11ed-40cb-90ff-db30ccb7cbdb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¡Cuando le propones algo, dice que no con la cabeza! No es tozudez, es expresar su opinión. Ofrécele opciones para calmarle.', body_fr = 'Quand vous lui proposez quelque chose, il secoue la tête pour dire non ! Ce n''est pas de l''entêtement, il exprime son avis. Apaisez-le en lui proposant des choix.', body_hi = 'कुछ देने पर सिर हिलाकर ''नहीं'' कहता है! यह ज़िद नहीं, अपनी राय ज़ाहिर करना है। उसे विकल्प देकर शांत कीजिए।', body_id = 'Saat ditawari sesuatu, ia menggeleng dan bilang tidak! Ini bukan keras kepala, melainkan cara mengungkapkan pendapatnya. Tenangkan ia dengan memberi pilihan.', body_ja = '何かをすすめると、首を振って「いや」と言います！これはわがままではなく、自分の考えを伝えているのです。選択肢をあげて落ち着かせてあげましょう。', body_ko = '무언가를 권하면 고개를 저으며 싫다고 하나요? 고집이 아니라 자기 생각을 표현하는 거예요. 선택지를 주며 마음을 달래 주세요.', body_nl = 'Schudt hij nee als je iets aanbiedt? Dat is geen koppigheid, maar zijn eigen mening geven. Kalmeer hem door hem keuzes te geven.', body_pl = 'Gdy coś mu proponujesz, kręci głową i mówi „nie”! To nie upór, tylko wyrażanie własnego zdania. Uspokój go, dając mu wybór.', body_pt = 'Quando lhe oferece algo, abana a cabeça a dizer que não! Não é teimosia, é expressar a sua opinião. Acalme-o dando-lhe opções.', body_sv = 'Skakar barnet på huvudet och säger nej när du föreslår något? Det är inte envishet, utan ett sätt att uttrycka sin åsikt. Lugna barnet genom att ge val.', body_vi = 'Mẹ mời gì bé cũng lắc đầu nói không! Đây không phải bướng bỉnh mà là bé đang bày tỏ ý kiến. Hãy đưa ra lựa chọn để bé dịu lại.', body_zh = '你提议什么，宝宝都摇头说不！这不是倔强，而是在表达自己的想法。给宝宝一些选择，让宝宝平静下来。' WHERE id = 'bfbd5b7b-bf9b-48f6-a1a2-f194c1a573f8' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los momentos divertidos de papá 🤡', title_fr = 'Les moments rigolos de papa 🤡', title_hi = 'पापा के मज़ेदार पल 🤡', title_id = 'Tingkah lucu Ayah 🤡', title_ja = 'パパのおもしろタイム 🤡', title_ko = '아빠의 재미있는 순간 🤡', title_nl = 'Papa''s grappige kant 🤡', title_pl = 'Zabawne chwile z tatą 🤡', title_pt = 'As brincadeiras divertidas do pai 🤡', title_sv = 'Pappas roliga stunder 🤡', title_vi = 'Những trò vui của bố 🤡', title_zh = '爸爸的搞笑时刻 🤡' WHERE id = 'e590043b-d98d-4bab-915d-caf59d5351e3' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Plan de fuga de la cama 🏃‍♂️', body_es = '¿Se escapa a esconderse cuando llega la hora de dormir? Pon el temporizador de sueño y el rumor del bosque de Ruido blanco, y convierte la habitación en una cueva tranquila.', title_fr = 'Plan d''évasion du lit 🏃‍♂️', body_fr = 'Il court se cacher à l''heure du coucher ? Lancez le minuteur de sommeil, mettez le murmure de la forêt des Bruits blancs et transformez la chambre en grotte paisible.', title_hi = 'बिस्तर से भागने का प्लान 🏃‍♂️', body_hi = 'सोने का समय आते ही भागकर छिप जाता है? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में जंगल की सरसराहट लगाइए और कमरे को एक शांत गुफ़ा बना दीजिए।', title_id = 'Rencana kabur dari tempat tidur 🏃‍♂️', body_id = 'Lari bersembunyi saat jam tidur tiba? Nyalakan Timer Tidur, putar suara desau hutan dari Suara Putih, dan ubah kamar menjadi gua yang tenang.', title_ja = 'ベッドからの脱走計画 🏃‍♂️', body_ja = '寝る時間になると、走って隠れますか？睡眠タイマーをオンにして、「ホワイトノイズ」の森のざわめきを流し、部屋を静かな洞窟に変えましょう。', title_ko = '침대 탈출 작전 🏃‍♂️', body_ko = '잘 시간만 되면 도망가서 숨나요? 수면 타이머를 켜고 백색소음의 숲 소리를 틀어 방을 조용한 동굴로 바꿔 주세요.', title_nl = 'Ontsnappingsplan uit bed 🏃‍♂️', body_nl = 'Rent hij weg en verstopt hij zich als het bedtijd is? Zet de Slaaptimer aan, kies het ruisen van het bos in Witte ruis en maak van de kamer een rustige grot.', title_pl = 'Plan ucieczki z łóżka 🏃‍♂️', body_pl = 'Gdy przychodzi pora snu, ucieka i się chowa? Włącz timer snu, puść szum lasu z Białego szumu i zamień pokój w cichą jaskinię.', title_pt = 'Plano de fuga da cama 🏃‍♂️', body_pt = 'Quando chega a hora de dormir, foge e esconde-se? Ligue o temporizador de sono, ponha o murmúrio da floresta do Ruído Branco e transforme o quarto numa gruta tranquila.', title_sv = 'Flyktplanen från sängen 🏃‍♂️', body_sv = 'Springer barnet och gömmer sig när det är dags att sova? Starta sömntimern, sätt på skogens sus från Vitt brus och gör rummet till en lugn grotta.', title_vi = 'Kế hoạch trốn khỏi giường 🏃‍♂️', body_vi = 'Đến giờ ngủ là bé chạy đi trốn? Hãy bật Bộ hẹn giờ ngủ, mở tiếng rừng rì rào trong Tiếng ồn trắng và biến căn phòng thành một hang động yên tĩnh.', title_zh = '逃离床铺计划 🏃‍♂️', body_zh = '一到睡觉时间就跑去躲起来？打开睡眠计时器，播放白噪音里的森林呼啸声，把房间变成一个安静的小山洞。' WHERE id = '10e42611-20e5-4efa-b449-859dcdf79439' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Del juego paralelo al juego compartido 👶', body_es = 'Cada vez le interesa más jugar en el mismo espacio que otros niños. Descubre en el Blog los secretos de la socialización a los 2 años y la psicología del parque infantil.', title_fr = 'Du jeu parallèle au jeu ensemble 👶', body_fr = 'Il a de plus en plus envie de jouer au même endroit que les autres enfants. Découvrez dans la rubrique Blogs les secrets de la socialisation à 2 ans et la psychologie de l''aire de jeux.', title_hi = 'पैरेलल प्ले से साथ खेलने तक 👶', body_hi = 'दूसरे बच्चों के साथ एक ही जगह खेलने में उसकी दिलचस्पी बढ़ रही है। ब्लॉग सेक्शन में 2 साल के बच्चों के मेल-जोल के राज़ और प्लेग्राउंड की मनोविज्ञान जानिए।', title_id = 'Dari bermain paralel ke bermain bersama 👶', body_id = 'Minatnya bermain di tempat yang sama dengan anak lain makin besar. Temukan rahasia sosialisasi anak usia 2 tahun dan psikologi taman bermain di bagian Blog.', title_ja = '平行遊びから一緒に遊ぶへ 👶', body_ja = 'ほかの子と同じ場所で遊ぶことへの興味が高まっています。2歳の子の社会性のひみつと、公園での心理について、ブログで見つけましょう。', title_ko = '평행 놀이에서 함께 놀이로 👶', body_ko = '다른 아이들과 같은 공간에서 노는 데 관심이 커지고 있어요. 블로그에서 두 살 아이의 사회성 비결과 놀이터 심리를 알아보세요.', title_nl = 'Van parallel spel naar samen spelen 👶', body_nl = 'Hij wil steeds meer in dezelfde ruimte spelen als andere kinderen. Ontdek in Blogs de geheimen van socialisatie bij tweejarigen en de psychologie van de speeltuin.', title_pl = 'Od zabawy równoległej do wspólnej 👶', body_pl = 'Coraz chętniej bawi się w tym samym miejscu co inne dzieci. Odkryj w sekcji Blog sekrety uspołecznienia 2-latków i psychologię placu zabaw.', title_pt = 'Da brincadeira paralela à brincadeira em conjunto 👶', body_pt = 'Tem cada vez mais vontade de brincar no mesmo espaço que as outras crianças. Descubra nos Blogues os segredos da socialização aos 2 anos e a psicologia do parque infantil.', title_sv = 'Från parallellek till lek tillsammans 👶', body_sv = 'Intresset för att leka i samma miljö som andra barn ökar. Upptäck 2-åringarnas sociala hemligheter och lekplatsens psykologi i Bloggar.', title_vi = 'Từ chơi song song đến chơi cùng nhau 👶', body_vi = 'Bé ngày càng thích chơi cùng chỗ với các bạn khác. Hãy khám phá bí quyết hòa nhập xã hội của trẻ 2 tuổi và tâm lý ở sân chơi trong mục Blog.', title_zh = '从平行游戏到一起玩 👶', body_zh = '越来越想和其他小朋友在同一个环境里玩了。去博客板块发现2岁宝宝的社交秘诀和游乐场心理学。' WHERE id = 'a00ab8a1-2a6c-4ace-a218-64e35136c179' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez al vestirse 👗', body_es = '¿Llora diciendo «¡No quiero estos pantalones!»? Aprende con Anacan AI cómo reducir las batallas de ropa por la mañana y darle libertad para elegir.', title_fr = 'L''habillage obstiné 👗', body_fr = 'Il pleure en disant « Je ne veux pas ce pantalon ! » ? Découvrez avec Anacan AI comment réduire les crises d''habillage du matin et lui laisser le libre choix.', title_hi = 'कपड़े पहनने की ज़िद 👗', body_hi = '''यह पैंट नहीं चाहिए!'' कहकर रोता है? सुबह कपड़ों के झगड़े कम करने और उसे अपनी पसंद चुनने का मौका देने के तरीके Anacan AI से जानिए।', title_id = 'Keras kepala soal baju 👗', body_id = 'Menangis sambil bilang Aku tidak mau celana ini!? Pelajari dari Anacan AI cara mengurangi drama berpakaian di pagi hari dan memberinya hak memilih.', title_ja = '着替えのこだわり 👗', body_ja = '「このズボンはいや！」と泣きますか？朝の着替えのかんしゃくを減らし、自分で選ぶ機会をあげる方法を、Anacan AIで学びましょう。', title_ko = '옷 입기 고집 👗', body_ko = '''이 바지 싫어!'' 하며 우나요? 아침 옷 입기 전쟁을 줄이고 스스로 고를 기회를 주는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Koppig bij het aankleden 👗', body_nl = 'Huilt hij ik wil deze broek niet!? Leer bij Anacan AI hoe je de ochtendstrijd om kleding vermindert en hem vrij laat kiezen.', title_pl = 'Uparte ubieranie 👗', body_pl = 'Płacze: „Nie chcę tych spodni!”? Dowiedz się od Anacan AI, jak ograniczyć poranne kryzysy przy ubieraniu i dać mu prawo do samodzielnego wyboru.', title_pt = 'Teimosia na hora de vestir 👗', body_pt = 'Chora a dizer "Não quero estas calças!"? Aprenda com o Anacan AI como reduzir as crises da roupa de manhã e dar-lhe liberdade de escolha.', title_sv = 'Envis påklädning 👗', body_sv = 'Gråter barnet och säger ”Jag vill inte ha de här byxorna!”? Lär dig av Anacan AI hur du kan minska morgonens klädbråk och ge barnet frihet att välja.', title_vi = 'Bướng bỉnh khi mặc đồ 👗', body_vi = 'Bé khóc "Con không thích cái quần này!"? Hãy học từ Anacan AI cách giảm những cuộc chiến quần áo buổi sáng và cho bé quyền tự chọn.', title_zh = '穿衣倔强 👗', body_zh = '哭着说“我不要这条裤子！”？向Anacan AI了解如何减少早上穿衣时的冲突，并给宝宝自由选择的权利。' WHERE id = 'ab2766ea-1937-4401-b3fe-78b7aa14f747' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño cocinero en acción 👨‍🍳', body_es = '¿Te ayuda en la cocina amasando? Graba en vídeo con sonido este momento tan gracioso, lleno de harina, y crea un recuerdo para siempre.', title_fr = 'Petit chef au travail 👨‍🍳', body_fr = 'Il vous aide en cuisine et pétrit la pâte ? Filmez avec le son ce moment rigolo, couvert de farine, pour en faire un souvenir pour la vie.', title_hi = 'नन्हा शेफ़ काम पर 👨‍🍳', body_hi = 'रसोई में आपकी मदद करता है, आटा गूँधता है? आटे से सने इस मज़ेदार पल को आवाज़ वाले वीडियो के रूप में रिकॉर्ड कीजिए और उम्रभर की याद बनाइए।', title_id = 'Koki cilik sedang beraksi 👨‍🍳', body_id = 'Ia membantu Anda di dapur dan menguleni adonan? Rekam momen lucu saat ia berlumur tepung ini sebagai video bersuara dan ciptakan kenangan seumur hidup.', title_ja = '小さなシェフが料理中 👨‍🍳', body_ja = 'キッチンでお手伝いして、生地をこねていますか？粉まみれのこのおもしろい瞬間を音声付きの動画で記録して、一生の思い出にしましょう。', title_ko = '꼬마 요리사 작업 중 👨‍🍳', body_ko = '주방에서 엄마를 도와 반죽을 주무르나요? 밀가루투성이가 된 이 재미있는 순간을 소리가 담긴 영상으로 남겨 평생의 추억을 만드세요.', title_nl = 'Kleine kok aan het werk 👨‍🍳', body_nl = 'Helpt hij je in de keuken en kneedt hij deeg? Leg dit grappige moment onder de bloem vast als video met geluid en maak er een herinnering voor altijd van.', title_pl = 'Mały kucharz przy pracy 👨‍🍳', body_pl = 'Pomaga ci w kuchni i ugniata ciasto? Nagraj tę zabawną chwilę, gdy jest cały w mące, jako film z dźwiękiem i stwórz pamiątkę na całe życie.', title_pt = 'Pequeno cozinheiro em ação 👨‍🍳', body_pt = 'Ajuda-a na cozinha e amassa a massa? Grave em vídeo com som este momento divertido, todo coberto de farinha, e crie uma recordação para a vida.', title_sv = 'Den lilla kocken i farten 👨‍🍳', body_sv = 'Hjälper barnet dig i köket och knådar deg? Spela in det roliga ögonblicket med mjöl överallt som video med ljud och skapa ett minne för livet.', title_vi = 'Đầu bếp nhí đang làm việc 👨‍🍳', body_vi = 'Bé phụ mẹ trong bếp, nhào bột? Hãy quay video có tiếng khoảnh khắc lấm lem bột ngộ nghĩnh này để làm kỷ niệm trọn đời.', title_zh = '小厨师上班啦 👨‍🍳', body_zh = '在厨房帮你忙，揉面团？把这个满身面粉的有趣瞬间录成有声视频，留下一生的回忆。' WHERE id = '3743e0d0-daf8-4b16-9966-a5c865827254' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gritos en el súper 🛒', body_es = '¿Se ha tirado al suelo en público porque no le compraste lo que quería? Olvida las miradas y desahógate con Anacan AI para gestionar con calma las crisis de los 2 años.', title_fr = 'Cris au supermarché 🛒', body_fr = 'Il s''est jeté par terre en public parce qu''il n''a pas eu ce qu''il voulait ? Oubliez les regards et confiez-vous à Anacan AI pour gérer ces crises des 2 ans avec sang-froid.', title_hi = 'बाज़ार में चीखें 🛒', body_hi = 'सबके सामने मनचाही चीज़ न मिलने पर ज़मीन पर लोट गया? आसपास की नज़रों को भूल जाइए और 2 साल के इन नखरों को शांति से संभालने के लिए Anacan AI से बात कीजिए।', title_id = 'Menjerit di supermarket 🛒', body_id = 'Menjatuhkan diri ke lantai di tempat umum karena keinginannya tak dituruti? Lupakan tatapan orang lain dan curhatlah kepada Anacan AI untuk menghadapi tantrum usia 2 tahun ini dengan tenang.', title_ja = 'お店で大泣き 🛒', body_ja = '人前で、ほしいものを買ってもらえず床にひっくり返りましたか？周りの視線は忘れて、2歳のかんしゃくに落ち着いて対応するために、Anacan AIに相談しましょう。', title_ko = '마트에서 울고불고 🛒', body_ko = '사람들 앞에서 원하는 걸 못 가졌다고 바닥에 드러누웠나요? 주변 시선은 잊고, 두 돌 떼쓰기를 침착하게 다루도록 Anacan AI에게 고민을 털어놓으세요.', title_nl = 'Geschreeuw in de supermarkt 🛒', body_nl = 'Gooide hij zich in het openbaar op de grond omdat hij zijn zin niet kreeg? Vergeet de blikken van anderen en praat met Anacan AI om deze buien van de peuterpuberteit kalm aan te pakken.', title_pl = 'Krzyk w sklepie 🛒', body_pl = 'Rzucił się na ziemię w miejscu publicznym, bo nie dostał tego, czego chciał? Zapomnij o spojrzeniach innych i porozmawiaj z Anacan AI, by spokojnie radzić sobie z kryzysami dwulatka.', title_pt = 'Gritos no supermercado 🛒', body_pt = 'Atirou-se para o chão num local público porque não lhe compraram o que queria? Esqueça os olhares à volta e desabafe com o Anacan AI para gerir com calma estas crises dos 2 anos.', title_sv = 'Skrik i affären 🛒', body_sv = 'Kastade sig barnet på golvet på en offentlig plats för att hen inte fick det hen ville ha? Glöm omgivningens blickar och prata med Anacan AI om hur du lugnt hanterar 2-årstrotsets utbrott.', title_vi = 'La hét ở siêu thị 🛒', body_vi = 'Bé lăn ra sàn nơi công cộng vì không được mua món mình muốn? Hãy quên ánh nhìn xung quanh và trò chuyện với Anacan AI để bình tĩnh xử lý những cơn khủng hoảng tuổi lên 2 này.', title_zh = '超市里的尖叫 🛒', body_zh = '在公共场合因为没买到想要的东西就躺地上打滚？忘掉周围的目光，和Anacan AI聊聊，学习冷静应对2岁的崩溃。' WHERE id = '8b9210f4-74fc-4c2d-b35a-90728df0c189' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Has pasado la noche sin dormir? ☕', body_es = '¿Los despertares nocturnos han acabado con tu energía? Revive con un batido de crema de cacahuete con proteínas de Recetas saludables para mujeres que da fuerza al instante sin cafeína.', title_fr = 'Une nuit sans sommeil ? ☕', body_fr = 'Les réveils nocturnes ont épuisé votre énergie ? Requinquez-vous avec un smoothie protéiné au beurre de cacahuète des Recettes saines pour femmes, énergisant en un instant et sans caféine.', title_hi = 'रात भर नींद नहीं हुई? ☕', body_hi = 'रात में बार-बार जागने से ऊर्जा खत्म हो गई? महिलाओं के लिए सेहतमंद रेसिपी से कैफ़ीन के बिना तुरंत ताकत देने वाली, प्रोटीन से भरपूर पीनट बटर स्मूदी बनाइए और तरोताज़ा हो जाइए।', title_id = 'Semalam kurang tidur? ☕', body_id = 'Sering terbangun malam menguras energi Anda? Segarkan diri dengan smoothie selai kacang kaya protein dari Resep Sehat untuk wanita yang langsung memberi tenaga tanpa perlu kafein.', title_ja = '夜、眠れなかった？☕', body_ja = '夜中に起こされて、エネルギーが切れましたか？「女性のためのヘルシーレシピ」から、カフェインに頼らずすぐに元気が出る、たんぱく質たっぷりのピーナッツバタースムージーで元気を取り戻しましょう。', title_ko = '밤잠을 설쳤나요? ☕', body_ko = '밤에 깨느라 기운이 다 빠졌나요? 여성을 위한 건강한 레시피에서 카페인 없이도 바로 힘이 나는 단백질 땅콩버터 스무디로 기운을 되찾으세요.', title_nl = 'Een slapeloze nacht gehad? ☕', body_nl = 'Hebben de nachtelijke wakkere momenten je energie opgebruikt? Maak uit Gezonde recepten voor vrouwen een eiwitrijke smoothie met pindakaas die je zonder cafeïne meteen kracht geeft.', title_pl = 'Nieprzespana noc? ☕', body_pl = 'Nocne pobudki odebrały ci energię? Przygotuj ze Zdrowych przepisów dla kobiet białkowe smoothie z masłem orzechowym, które od razu doda ci sił bez kofeiny, i odżyj.', title_pt = 'Ficou sem dormir à noite? ☕', body_pt = 'Os despertares noturnos esgotaram-lhe a energia? Prepare nas Receitas Saudáveis para Mulheres um batido de manteiga de amendoim rico em proteína, que dá força na hora sem precisar de cafeína, e revigore-se.', title_sv = 'Sömnlös natt? ☕', body_sv = 'Har de nattliga uppvaknandena tömt din energi? Gör en proteinrik smoothie med jordnötssmör som ger kraft direkt utan koffein från Hälsosamma recept för kvinnor och pigga upp dig.', title_vi = 'Đêm qua mẹ mất ngủ? ☕', body_vi = 'Thức giấc ban đêm khiến mẹ cạn năng lượng? Hãy làm ly sinh tố bơ đậu phộng giàu đạm, tiếp sức tức thì mà không cần caffeine từ Công thức lành mạnh cho phụ nữ để tỉnh táo lại.', title_zh = '昨晚没睡好？☕', body_zh = '夜里频繁醒来耗光了你的精力？从女性健康食谱里做一杯不靠咖啡因、马上补充能量的高蛋白花生酱奶昔，重新振作起来。' WHERE id = 'd5d9b1e2-d062-4d67-8535-5d3b9126d7d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin azúcar, pero rico 🥞', body_es = '¿Busca algo dulce? No vayas al súper. Prueba en Recetas para bebé las tortitas de plátano y manzana que se preparan en solo 10 minutos y ábrele el apetito.', title_fr = 'Sans sucre, mais délicieux 🥞', body_fr = 'Il réclame du sucré ? Pas besoin d''aller au supermarché. Essayez les pancakes banane-pomme des Recettes pour bébés, prêts en 10 minutes, et ouvrez-lui l''appétit.', title_hi = 'बिना चीनी, फिर भी स्वादिष्ट 🥞', body_hi = 'मीठा ढूँढ रहा है? बाज़ार मत जाइए। बच्चों की रेसिपी में सिर्फ़ 10 मिनट में बनने वाले केले और सेब के पैनकेक आज़माइए और उसकी भूख खोलिए।', title_id = 'Tanpa gula, tapi lezat 🥞', body_id = 'Mencari yang manis-manis? Tak perlu ke minimarket. Coba panekuk pisang dan apel yang siap hanya dalam 10 menit di Resep Bayi dan buka nafsu makannya.', title_ja = '砂糖なしでもおいしい 🥞', body_ja = '甘いものがほしい？お店に行かなくても大丈夫。「離乳食を始める赤ちゃんのレシピ」で、たった10分でできるバナナとりんごのパンケーキをチェックして、食欲を引き出しましょう。', title_ko = '설탕 없이도 맛있게 🥞', body_ko = '단 걸 찾나요? 마트에 가지 마세요. 아기 레시피에서 10분이면 만드는 바나나 사과 팬케이크를 확인하고 입맛을 살려 주세요.', title_nl = 'Zonder suiker, maar lekker 🥞', body_nl = 'Wil hij iets zoets? Ga niet naar de winkel. Probeer in Babyrecepten de pannenkoekjes met banaan en appel, klaar in maar 10 minuten, en wek zijn eetlust op.', title_pl = 'Bez cukru, ale pysznie 🥞', body_pl = 'Szuka słodyczy? Nie idź do sklepu. Wypróbuj w Przepisach dla niemowląt placuszki z bananem i jabłkiem gotowe w zaledwie 10 minut i pobudź jego apetyt.', title_pt = 'Sem açúcar, mas saboroso 🥞', body_pt = 'Quer doces? Não vá ao supermercado. Experimente nas Receitas para bebés as panquecas de banana e maçã, prontas em apenas 10 minutos, e abra-lhe o apetite.', title_sv = 'Sockerfritt, men gott 🥞', body_sv = 'Söker barnet efter något sött? Gå inte till affären. Prova bananpannkakor med äpple som är klara på bara 10 minuter i Recept för bebisar och väck aptiten.', title_vi = 'Không đường mà vẫn ngon 🥞', body_vi = 'Bé đòi đồ ngọt? Đừng ra siêu thị. Hãy thử món bánh kếp chuối táo làm trong 10 phút trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '无糖，却很好吃 🥞', body_zh = '在找甜食？别去超市了。看看宝宝食谱里只需10分钟的香蕉苹果松饼，让宝宝胃口大开。' WHERE id = '72f63b03-217f-4966-9286-177869cd7d59' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla del cepillo 🪥', body_es = '¿Lavarse los dientes es una gran batalla? Mira en Productos recomendados cepillos musicales o con sus personajes de dibujos favoritos y conviértelo ya en un juego.', title_fr = 'La bataille de la brosse 🪥', body_fr = 'Se brosser les dents est une vraie bataille ? Regardez dans les Produits recommandés les brosses musicales ou à l''effigie de son héros de dessin animé préféré et transformez-la tout de suite en jeu.', title_hi = 'ब्रश की जंग 🪥', body_hi = 'दाँत ब्रश करना बड़ी लड़ाई है? सुझाए गए प्रोडक्ट में म्यूज़िकल या पसंदीदा कार्टून कैरेक्टर वाले ब्रश देखिए और इसे तुरंत खेल बना दीजिए।', title_id = 'Perang sikat gigi 🪥', body_id = 'Menyikat gigi jadi pertempuran besar? Lihat sikat gigi bermusik atau bergambar tokoh kartun favorit di Produk Rekomendasi dan segera jadikan permainan.', title_ja = '歯ブラシバトル 🪥', body_ja = '歯みがきが大きなバトルになっていますか？「おすすめ商品」で音楽付きや人気のアニメキャラクターの歯ブラシをチェックして、すぐに遊びに変えましょう。', title_ko = '칫솔 전쟁 🪥', body_ko = '양치가 큰 전쟁인가요? 추천 제품에서 음악이 나오거나 좋아하는 만화 캐릭터 칫솔을 살펴보고 바로 놀이로 바꿔 보세요.', title_nl = 'Tandenborstelstrijd 🪥', body_nl = 'Is tandenpoetsen een groot gevecht? Bekijk in Aanbevolen producten muzikale borstels of borstels met zijn favoriete tekenfilmheld en maak er meteen een spel van.', title_pl = 'Wojna o szczoteczkę 🪥', body_pl = 'Mycie zębów to wielka bitwa? Zajrzyj w Polecanych produktach do grających szczoteczek lub szczoteczek z ulubionymi bohaterami bajek i od razu zamień to w zabawę.', title_pt = 'A guerra da escova 🪥', body_pt = 'Lavar os dentes é uma grande batalha? Veja nos Produtos Recomendados escovas musicais ou com o seu herói de desenhos animados preferido e transforme isto já num jogo.', title_sv = 'Kampen om tandborsten 🪥', body_sv = 'Är tandborstningen en stor strid? Titta på tandborstar med musik eller favoritfigurer i Rekommenderade produkter och gör det direkt till en lek.', title_vi = 'Cuộc chiến bàn chải 🪥', body_vi = 'Đánh răng là cả một trận chiến? Hãy xem các loại bàn chải có nhạc hoặc in hình nhân vật hoạt hình yêu thích trong Sản phẩm gợi ý để biến việc này thành trò chơi ngay.', title_zh = '牙刷之战 🪥', body_zh = '刷牙是一场大战？去推荐商品看看音乐牙刷或带可爱卡通形象的牙刷，马上把它变成游戏。' WHERE id = 'c2a3a287-3762-4751-aa0e-2e7d2c1d038c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de carreras? El temporizador se ha parado. Oscurece la habitación, pon el murmullo del río de Ruido blanco y regala también un masaje a tu mente.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée bruyante et pleine de courses ? Le minuteur est arrêté. Faites l''obscurité, lancez le murmure de la rivière des Bruits blancs et massez aussi votre propre cerveau.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत शोर और भाग-दौड़ भरा दिन था? टाइमर रुक गया। कमरे में अँधेरा कीजिए, व्हाइट नॉइज़ में नदी की कलकल लगाइए और अपने दिमाग को भी आराम दीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari yang bising dan penuh kejar-kejaran? Timer sudah berhenti. Gelapkan kamar, putar suara gemericik sungai dari Suara Putih, dan tenangkan juga pikiran Anda.', title_ja = '自然のリラックス効果 🍃', body_ja = 'にぎやかで走り回った一日でしたか？タイマーは止まりました。部屋を暗くして、「ホワイトノイズ」の小川のせせらぎを流し、あなたの頭もやさしくほぐしましょう。', title_ko = '자연의 진정제 🍃', body_ko = '시끄럽고 정신없는 하루였나요? 타이머가 멈췄어요. 방을 어둡게 하고 백색소음에서 시냇물 소리를 틀어 엄마의 머리도 쉬게 해 주세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een lawaaierige, drukke dag? De timer is gestopt. Verduister de kamer, zet het kabbelen van een beekje uit Witte ruis aan en geef ook je eigen hoofd een massage.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był bardzo głośny dzień pełen bieganiny? Timer zatrzymany. Zaciemnij pokój, włącz szum strumienia z Białego szumu i ukój także swój umysł.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia muito barulhento e cheio de correria? O temporizador parou. Escureça o quarto, ligue o murmúrio do rio do Ruído Branco e faça também uma massagem ao seu cérebro.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit full av buller och springande? Timern har stannat. Mörklägg rummet, sätt på bäckens porlande från Vitt brus och ge även din egen hjärna en massage.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Một ngày quá ồn ào và chạy nhảy? Hẹn giờ đã dừng. Hãy làm tối phòng, bật tiếng suối chảy trong Tiếng ồn trắng để đầu óc mẹ cũng được thư giãn.', title_zh = '天然的镇静剂 🍃', body_zh = '今天又吵又跑，闹腾了一整天？计时器停了。把房间调暗，打开白噪音里的溪流声，也给自己的大脑做个按摩。' WHERE id = 'd3ffa760-4dfc-4872-9709-1f13cf644f4a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de hierro 🥩', body_es = '¿Le falta energía o solo está cansado? Comprueba con el Seguimiento de tomas el hierro de hoy (carne, legumbres) y completa enseguida lo que falte.', title_fr = 'Bouclier de fer 🥩', body_fr = 'Il manque d''énergie ou il est simplement fatigué ? Vérifiez avec le Suivi des repas ses apports en fer du jour (viande, légumineuses) et comblez tout de suite les manques.', title_hi = 'आयरन की ढाल 🥩', body_hi = 'ऊर्जा कम है या बस थक गया है? फ़ीडिंग ट्रैकर से आज का आयरन (मांस, दालें) जाँचिए और कमी तुरंत पूरी कीजिए।', title_id = 'Perisai zat besi 🥩', body_id = 'Energinya menurun, atau hanya lelah? Cek asupan zat besi hari ini (daging, kacang-kacangan) dengan alat Pemantau Nutrisi dan segera lengkapi kekurangannya.', title_ja = '鉄分のシールド 🥩', body_ja = '元気がないのか、ただ疲れているだけ？「栄養管理ツール」で今日の鉄分（お肉、豆類）の摂取量を確認して、足りない分をすぐに補いましょう。', title_ko = '철분 방패 🥩', body_ko = '기운이 떨어진 걸까요, 그냥 피곤한 걸까요? 수유 기록 도구로 오늘의 철분 섭취(고기, 콩류)를 확인하고 부족한 만큼 바로 채워 주세요.', title_nl = 'IJzerschild 🥩', body_nl = 'Heeft hij weinig energie of is hij gewoon moe? Controleer met de Voedingstracker het ijzer van vandaag (vlees, peulvruchten) en vul tekorten meteen aan.', title_pl = 'Tarcza z żelaza 🥩', body_pl = 'Brakuje mu energii, czy jest po prostu zmęczony? Sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza (mięso, rośliny strączkowe) i od razu uzupełnij braki.', title_pt = 'Escudo de ferro 🥩', body_pt = 'Está com pouca energia ou só cansado? Verifique com o Registo de Alimentação o ferro de hoje (carne, leguminosas) e complete já o que faltar.', title_sv = 'Järnskölden 🥩', body_sv = 'Har energin sjunkit, eller är barnet bara trött? Kontrollera dagens järnintag (kött, baljväxter) med Matningskoll och fyll direkt på det som fattas.', title_vi = 'Lá chắn sắt 🥩', body_vi = 'Bé thiếu năng lượng hay chỉ mệt thôi? Hãy kiểm tra lượng sắt (thịt, các loại đậu) hôm nay bằng Theo dõi cữ bú và bổ sung ngay phần thiếu.', title_zh = '铁的护盾 🥩', body_zh = '是精力下降了，还是只是累了？用喂养记录工具查看今天的铁（肉类、豆类）摄入量，马上补足不够的部分。' WHERE id = '3b32f5ba-4db0-47e2-ab4a-893183710c64' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Empieza el juego de médicos! 🩺', body_es = '¿Le pone una inyección a su osito? Los juegos de imaginación están en su mejor momento. Captura este dulce momento con la Sesión de fotos del bebé y guárdalo como un recuerdo inolvidable.', title_fr = 'Le jeu du docteur a commencé 🩺', body_fr = 'Il fait une piqûre à son nounours ? Les jeux d''imagination sont à leur sommet. Photographiez ce mignon moment avec la Séance photo bébé et gardez-le comme un souvenir inoubliable.', title_hi = 'डॉक्टर-डॉक्टर का खेल शुरू 🩺', body_hi = 'अपने भालू को इंजेक्शन लगाता है? कल्पना वाले खेल चरम पर हैं। इस प्यारे पल को बेबी फ़ोटोशूट से कैद कीजिए और सबसे यादगार याद के रूप में सहेजिए।', title_id = 'Main dokter-dokteran dimulai 🩺', body_id = 'Menyuntik boneka beruangnya? Permainan imajinasi sedang di puncaknya. Abadikan momen manis ini dengan Sesi Foto Bayi dan simpan sebagai kenangan paling berkesan.', title_ja = 'お医者さんごっこが始まった 🩺', body_ja = 'くまさんに注射をしていますか？ごっこ遊びが真っ盛りです。このかわいい瞬間を「ベビーフォトセッション」で撮って、いちばん心に残る思い出として保存しましょう。', title_ko = '병원 놀이 시작 🩺', body_ko = '곰 인형에게 주사를 놓나요? 상상 놀이가 한창이에요. 이 사랑스러운 순간을 아기 사진 촬영으로 찍어 가장 기억에 남는 추억으로 간직하세요.', title_nl = 'Het doktersspel is begonnen 🩺', body_nl = 'Geeft hij zijn beer een prik? Het fantasiespel is op zijn hoogtepunt. Leg dit lieve moment vast met Babyfotoshoot en bewaar het als onvergetelijke herinnering.', title_pl = 'Zaczęła się zabawa w lekarza 🩺', body_pl = 'Robi misiowi zastrzyk? Zabawy w udawanie są w pełnym rozkwicie. Uwiecznij tę słodką chwilę w Sesji zdjęciowej dziecka i zachowaj jako niezapomnianą pamiątkę.', title_pt = 'Começou o jogo do médico 🩺', body_pt = 'Dá uma injeção ao ursinho? As brincadeiras de imaginação estão no auge. Fotografe este momento doce com a Sessão Fotográfica do Bebé e guarde-o como uma recordação inesquecível.', title_sv = 'Doktorsleken har börjat 🩺', body_sv = 'Ger barnet nallen en spruta? Låtsaslekarna är på topp. Fotografera det söta ögonblicket med Babyfotografering och spara det som ett av de mest minnesvärda minnena.', title_vi = 'Trò chơi bác sĩ đã bắt đầu 🩺', body_vi = 'Bé tiêm cho gấu bông? Trò chơi tưởng tượng đang ở đỉnh cao. Hãy chụp khoảnh khắc đáng yêu này bằng Chụp ảnh cho bé và lưu lại thành kỷ niệm khó quên nhất.', title_zh = '医生游戏开始了 🩺', body_zh = '给小熊打针？想象游戏正处于巅峰。用宝宝写真拍下这个可爱的瞬间，留作最难忘的回忆。' WHERE id = 'a743db36-b967-433a-8695-0780f7195e63' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas una pausa ☕', body_es = '¡Sepárate un momento de tu peque y respira! Busca en Lugares para mamás una cafetería con rincón infantil y disfruta de tu café caliente.', title_fr = 'Vous aussi, vous avez besoin d''une pause ☕', body_fr = 'Éloignez-vous un instant de votre enfant et respirez ! Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants et savourez votre café chaud.', title_hi = 'आपको भी ब्रेक चाहिए ☕', body_hi = 'बच्चे से एक पल दूर होकर साँस लीजिए! माँ के लिए अनुकूल जगहें में बच्चों के कोने वाला कैफ़े ढूँढिए और अपनी गर्म कॉफ़ी का मज़ा लीजिए।', title_id = 'Anda juga butuh rehat ☕', body_id = 'Berpisah sejenak dari si kecil dan tarik napas! Temukan kafe dengan sudut bermain anak di Tempat Ramah Ibu dan nikmati kopi hangat Anda.', title_ja = 'あなたにも休憩が必要です ☕', body_ja = '少しの間お子さんから離れて、ひと息つきましょう！「ママにやさしいスポット」でキッズコーナーのあるカフェを見つけて、温かいコーヒーをゆっくり味わいましょう。', title_ko = '엄마에게도 휴식이 필요해요 ☕', body_ko = '잠시 아이와 떨어져 숨을 돌리세요! 엄마 친화 장소에서 키즈 코너가 있는 카페를 찾아 따뜻한 커피를 즐겨 보세요.', title_nl = 'Jij hebt ook een pauze nodig ☕', body_nl = 'Neem even afstand van je kindje en haal adem! Zoek in Mamavriendelijke plekken een café met kinderhoek en geniet van je warme koffie.', title_pl = 'Ty też potrzebujesz przerwy ☕', body_pl = 'Odejdź na chwilę od dziecka i odetchnij! Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci i delektuj się gorącą kawą.', title_pt = 'Também precisa de uma pausa ☕', body_pt = 'Afaste-se um instante da criança e respire! Encontre nos Locais Amigos das Mães um café com cantinho para crianças e saboreie o seu café quente.', title_sv = 'Du behöver också en paus ☕', body_sv = 'Ta en stund ifrån barnet och andas! Hitta ett kafé med barnhörna i Mammavänliga platser och lyssna på ljudet av ditt varma kaffe.', title_vi = 'Mẹ cũng cần nghỉ ngơi ☕', body_vi = 'Hãy tạm rời bé một chút để hít thở! Tìm một quán cà phê có góc trẻ em trong Địa điểm thân thiện với mẹ và tận hưởng ly cà phê nóng của mình.', title_zh = '你也需要歇一歇 ☕', body_zh = '离开孩子一小会儿，喘口气吧！在妈妈友好场所里找一家带儿童角的咖啡馆，听听热咖啡的声音。' WHERE id = 'd6af2d07-9e24-449e-843c-4a4fbcab142b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Conducir un coche imaginario 🚗', body_es = '¿Coge una caja vacía o un juguete, lo gira como un volante y hace ruidos? ¡El juego simbólico se está desarrollando plenamente!', title_fr = 'Conduire une voiture imaginaire 🚗', body_fr = 'Il prend une boîte vide ou un jouet, le tourne comme un volant et fait « vroum » ? Le jeu symbolique (faire semblant) est en plein développement !', title_hi = 'काल्पनिक गाड़ी चलाना 🚗', body_hi = 'खाली डिब्बा या खिलौना लेकर स्टीयरिंग की तरह घुमाता है और आवाज़ निकालता है? दिखावटी खेल (प्रिटेंड प्ले) पूरी तरह विकसित हो रहे हैं!', title_id = 'Menyetir mobil khayalan 🚗', body_id = 'Mengambil kotak kosong atau mainan, memutarnya seperti setir, sambil bersuara? Permainan simbolik (pretend play) sedang berkembang pesat!', title_ja = '想像のドライブ 🚗', body_ja = '空き箱やおもちゃをハンドルのように回して、音を出していますか？見立て遊び（ごっこ遊び）がしっかり育っています！', title_ko = '상상 속 운전 🚗', body_ko = '빈 상자나 장난감을 운전대처럼 돌리며 소리를 내나요? 상징 놀이(역할 놀이)가 활짝 자라고 있어요!', title_nl = 'Autorijden in zijn fantasie 🚗', body_nl = 'Pakt hij een lege doos of speeltje, draait hij het rond als een stuur en maakt hij geluiden? Zijn fantasiespel ontwikkelt zich volop!', title_pl = 'Wyimaginowana jazda autem 🚗', body_pl = 'Bierze puste pudełko albo zabawkę, kręci nią jak kierownicą i wydaje dźwięki? Zabawy symboliczne (w udawanie) w pełni się rozwijają!', title_pt = 'A conduzir um carro imaginário 🚗', body_pt = 'Pega numa caixa vazia ou num brinquedo, roda-o como um volante e faz barulhos? Os jogos simbólicos (faz de conta) estão em pleno desenvolvimento!', title_sv = 'Kör en låtsasbil 🚗', body_sv = 'Tar barnet en tom låda eller leksak, vrider den som en ratt och låter? Symbolisk lek (låtsaslek) är i full utveckling!', title_vi = 'Lái xe tưởng tượng 🚗', body_vi = 'Bé cầm chiếc hộp rỗng hay món đồ chơi xoay như vô lăng và giả tiếng xe? Trò chơi biểu tượng (pretend play) đang phát triển trọn vẹn!', title_zh = '假装开车 🚗', body_zh = '拿起空盒子或玩具当方向盘转，还发出声音？象征性游戏（假装游戏）正在全面发展！' WHERE id = '3708efde-5f63-47e0-b30e-19b8bf533ad8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿No te quitas de la cabeza el «¿Por qué hace esto mi peque?»? Entra en la Comunidad Anacan y lee historias parecidas de otras madres.', body_fr = 'La question « Pourquoi mon enfant fait-il ça ? » vous obsède ? Rejoignez la Communauté Anacan et lisez les histoires semblables d''autres mamans.', body_hi = '''मेरा बच्चा ऐसा क्यों करता है?'' वाला सवाल दिमाग से नहीं जाता? Anacan कम्युनिटी में शामिल होइए और दूसरी माँओं की मिलती-जुलती कहानियाँ पढ़िए।', body_id = 'Pikiran Kenapa anakku begini? terus menghantui Anda? Bergabunglah dengan Komunitas Anacan dan baca kisah serupa dari ibu-ibu lain.', body_ja = '「どうしてうちの子はこうなの？」と頭がいっぱいですか？Anacanコミュニティに参加して、ほかのママたちの似た体験を読んでみましょう。', body_ko = '''우리 아이는 왜 이럴까?''라는 생각이 머리를 떠나지 않나요? Anacan 커뮤니티에 들어와 다른 엄마들의 비슷한 이야기를 읽어 보세요.', body_nl = 'Blijf je maar denken: waarom doet mijn kind zo? Word lid van de Anacan Community en lees vergelijkbare verhalen van andere moeders.', body_pl = 'Myśl „Dlaczego moje dziecko tak się zachowuje?” nie daje ci spokoju? Dołącz do Społeczności Anacan i przeczytaj podobne historie innych mam.', body_pt = 'O pensamento "Porque é que o meu filho faz isto?" não lhe sai da cabeça? Entre na Comunidade Anacan e leia histórias parecidas de outras mães.', body_sv = 'Äter tanken ”Varför gör mitt barn så här?” upp dig? Gå med i Anacans Community och läs andra mammors liknande berättelser.', body_vi = 'Câu hỏi "Sao con mình lại thế này?" cứ lởn vởn trong đầu? Hãy tham gia Cộng đồng Anacan và đọc những câu chuyện tương tự của các mẹ khác.', body_zh = '“我的孩子为什么会这样？”的念头一直萦绕心头？加入Anacan社区，读读其他妈妈相似的故事吧。' WHERE id = 'c1efd894-6c8f-4d33-9cdd-4d863998e9be' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de calcio 🦴', body_es = 'El calcio es imprescindible para dientes y huesos. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de yogur y queso y completa lo que falte.', title_fr = 'Réserve de calcium 🦴', body_fr = 'Le calcium est indispensable aux dents et aux os. Vérifiez avec le Suivi des repas qu''il a eu sa ration de yaourt et de fromage aujourd''hui et comblez les manques.', title_hi = 'कैल्शियम का भंडार 🦴', body_hi = 'दाँतों और हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज दही और पनीर की मात्रा पूरी हुई, और कमी पूरी कीजिए।', title_id = 'Gudang kalsium 🦴', body_id = 'Kalsium wajib untuk gigi dan tulang. Pastikan dengan alat Pemantau Nutrisi bahwa porsi yogurt dan keju hari ini terpenuhi, dan lengkapi kekurangannya.', title_ja = 'カルシウムの宝庫 🦴', body_ja = '歯と骨にはカルシウムが欠かせません。「栄養管理ツール」で今日のヨーグルトやチーズの目安量をとれたか確認して、足りない分を補いましょう。', title_ko = '칼슘 창고 🦴', body_ko = '치아와 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 요거트와 치즈 기준량을 채웠는지 확인하고 부족한 만큼 채워 주세요.', title_nl = 'Calciumvoorraad 🦴', body_nl = 'Calcium is onmisbaar voor tanden en botten. Check met de Voedingstracker of hij vandaag genoeg yoghurt en kaas heeft gehad en vul tekorten aan.', title_pl = 'Zapas wapnia 🦴', body_pl = 'Wapń jest niezbędny dla zębów i kości. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja jogurtu i sera została osiągnięta, i uzupełnij braki.', title_pt = 'Reserva de cálcio 🦴', body_pt = 'O cálcio é indispensável para os dentes e os ossos. Confirme com o Registo de Alimentação que hoje cumpriu a dose de iogurte e queijo e complete o que faltar.', title_sv = 'Kalciumförråd 🦴', body_sv = 'Kalcium är ett måste för tänder och skelett. Kontrollera med Matningskoll att barnet fått dagens norm av yoghurt och ost och fyll på det som fattas.', title_vi = 'Kho canxi 🦴', body_vi = 'Canxi rất cần cho răng và xương. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sữa chua, phô mai chưa và bổ sung phần thiếu.', title_zh = '钙储备 🦴', body_zh = '钙对牙齿和骨骼必不可少。用喂养记录工具确认今天酸奶、奶酪的参考量是否达到，补上不足的部分。' WHERE id = '71d54817-9c7d-4b6a-a083-cfc9af5ca532' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La heroína del día eres tú 🌟', body_es = 'Cada nueva habilidad que aprende y cada paso que da por sí solo son fruto de tu esfuerzo.', title_fr = 'L''héroïne du jour, c''est vous 🌟', body_fr = 'Chaque nouvelle compétence, chaque pas en autonomie, c''est grâce à vous.', title_hi = 'आज की हीरो आप हैं 🌟', body_hi = 'हर दिन सीखी नई चीज़, हर आज़ाद कदम आपकी मेहनत है।', title_id = 'Pahlawan hari ini adalah Anda 🌟', body_id = 'Setiap keterampilan baru dan setiap langkah mandirinya adalah hasil kerja keras Anda.', title_ja = '今日のヒーローはあなたです 🌟', body_ja = '毎日新しくできるようになること、自分で踏み出す一歩一歩は、あなたのがんばりのおかげです。', title_ko = '오늘의 주인공은 엄마예요 🌟', body_ko = '아이가 매일 배우는 새로운 능력, 혼자 내딛는 한 걸음 한 걸음이 모두 엄마의 노력이에요.', title_nl = 'Jij bent de held van vandaag 🌟', body_nl = 'Elke nieuwe vaardigheid en elk zelfstandig stapje is dankzij jou.', title_pl = 'Dzisiejszą bohaterką jesteś ty 🌟', body_pl = 'Każda nowa umiejętność, której się uczy, każdy samodzielny krok to twoja zasługa.', title_pt = 'A heroína do dia é a mãe 🌟', body_pt = 'Cada nova competência que aprende e cada passo independente são fruto do seu esforço.', title_sv = 'Dagens hjälte är du 🌟', body_sv = 'Varje ny färdighet barnet lär sig och varje självständigt steg är tack vare ditt arbete.', title_vi = 'Mẹ là người hùng của ngày hôm nay 🌟', body_vi = 'Mỗi kỹ năng mới, mỗi bước đi tự lập của bé đều là công sức của mẹ.', title_zh = '今天的英雄是你 🌟', body_zh = '宝宝每天学会的新本领、迈出的每一个独立的脚步，都有你的功劳。' WHERE id = 'b6c449a4-eac7-47b9-9e9b-4c3b2deebe5b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juguetes inteligentes 🧩', body_es = 'Una mente de 2 años necesita juguetes que enseñen, no solo que hagan ruido. Descubre en Productos recomendados puzles de madera y figuras que desarrollan la lógica.', title_fr = 'Jouets malins 🧩', body_fr = 'À 2 ans, il lui faut des jouets qui apprennent des choses, pas seulement qui font du bruit. Découvrez dans les Produits recommandés des puzzles et formes en bois qui développent la logique.', title_hi = 'स्मार्ट खिलौने 🧩', body_hi = '2 साल के दिमाग के लिए सिर्फ़ आवाज़ करने वाले नहीं, सिखाने वाले खिलौने चाहिए। सुझाए गए प्रोडक्ट में तर्क बढ़ाने वाली लकड़ी की पज़ल और आकृतियाँ खोजिए।', title_id = 'Mainan cerdas 🧩', body_id = 'Kecerdasan anak 2 tahun butuh mainan yang mengajarkan sesuatu, bukan sekadar berbunyi. Temukan puzzle kayu dan mainan bentuk yang mengembangkan logika di Produk Rekomendasi.', title_ja = 'かしこいおもちゃ 🧩', body_ja = '2歳の知性には、音が出るだけでなく、学びのあるおもちゃが必要です。「おすすめ商品」で、論理的な思考を育てる木のパズルや型はめを見つけましょう。', title_ko = '똑똑한 장난감 🧩', body_ko = '두 살 아이의 두뇌에는 소리만 나는 장난감이 아니라 배우게 하는 장난감이 필요해요. 추천 제품에서 논리력을 키우는 원목 퍼즐과 모양 맞추기를 찾아보세요.', title_nl = 'Slim speelgoed 🧩', body_nl = 'Een slim kind van 2 heeft speelgoed nodig dat iets leert, niet alleen geluid maakt. Ontdek in Aanbevolen producten houten puzzels en vormen die de logica ontwikkelen.', title_pl = 'Mądre zabawki 🧩', body_pl = 'Umysł 2-latka potrzebuje zabawek, które nie tylko hałasują, ale też uczą. Odkryj w Polecanych produktach drewniane układanki i kształty rozwijające logikę.', title_pt = 'Brinquedos inteligentes 🧩', body_pt = 'Uma inteligência de 2 anos precisa de brinquedos que ensinem, não só que façam barulho. Descubra nos Produtos Recomendados puzzles e formas de madeira que desenvolvem a lógica.', title_sv = 'Smarta leksaker 🧩', body_sv = 'En 2-årings tänkande behöver leksaker som lär, inte bara låter. Upptäck träpussel och former som utvecklar logiken i Rekommenderade produkter.', title_vi = 'Đồ chơi thông minh 🧩', body_vi = 'Trí tuệ của bé 2 tuổi cần những món đồ chơi dạy được điều gì đó, không chỉ phát ra âm thanh. Hãy khám phá các bộ ghép hình gỗ và hình khối phát triển tư duy trong Sản phẩm gợi ý.', title_zh = '聪明玩具 🧩', body_zh = '2岁的小脑瓜需要的不只是会发声的玩具，而是能教东西的玩具。在推荐商品里发现促进逻辑发展的木制拼图和形状玩具。' WHERE id = '2a9eaf13-aaf9-41fd-baa3-5fdcb48e56ca' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tiene estreñimiento? 🚽', body_es = '¿De tanto correr se olvida de beber agua? Fíjate en las deposiciones al cambiar el pañal. Si hay riesgo de estreñimiento, anótalo en la app y añade enseguida alimentos con fibra con el Seguimiento de tomas.', title_fr = 'Un souci de constipation ? 🚽', body_fr = 'Il oublie de boire à force de courir ? Observez les selles à chaque change. En cas de risque de constipation, notez-le dans l''appli et ajoutez tout de suite des aliments riches en fibres avec le Suivi des repas.', title_hi = 'कब्ज़ की परेशानी? 🚽', body_hi = 'दौड़ने में पानी पीना भूल जाता है? डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ का खतरा हो तो ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से फ़ाइबर वाली चीज़ें जोड़िए।', title_id = 'Ada masalah sembelit? 🚽', body_id = 'Lupa minum karena asyik berlari? Perhatikan kotorannya saat mengganti popok. Jika ada risiko sembelit, catat di aplikasi dan segera tambahkan makanan berserat dengan alat Pemantau Nutrisi.', title_ja = '便秘ぎみ？🚽', body_ja = '走り回ってお水を飲むのを忘れていますか？おむつ替えのときにうんちの様子をチェックしましょう。便秘のおそれがあればアプリに記録して、すぐに「栄養管理ツール」で食物繊維の多い食べ物を加えましょう。', title_ko = '변비가 있나요? 🚽', body_ko = '뛰어노느라 물 마시는 걸 잊나요? 기저귀를 갈 때 배변을 살펴보세요. 변비가 걱정된다면 앱에 기록하고 수유 기록 도구로 섬유질 음식을 바로 추가하세요.', title_nl = 'Last van verstopping? 🚽', body_nl = 'Vergeet hij door het rennen te drinken? Let bij het verschonen op de ontlasting. Is er kans op verstopping, noteer het in de app en voeg meteen met de Voedingstracker vezelrijk eten toe.', title_pl = 'Problem z zaparciami? 🚽', body_pl = 'Przez bieganie zapomina pić? Obserwuj kupki przy zmianie pieluszki. Jeśli jest ryzyko zaparć, zapisz to w aplikacji i od razu dodaj produkty bogate w błonnik w narzędziu do śledzenia karmienia.', title_pt = 'Prisão de ventre? 🚽', body_pt = 'De tanto correr, esquece-se de beber água? Observe as fezes ao mudar a fralda. Se houver risco de prisão de ventre, registe-o na app e acrescente já alimentos ricos em fibra com o Registo de Alimentação.', title_sv = 'Förstoppning? 🚽', body_sv = 'Glömmer barnet att dricka för att hen springer? Håll koll på avföringen när du byter blöja. Finns risk för förstoppning, anteckna det i appen och lägg direkt till fiberrik mat med Matningskoll.', title_vi = 'Bé bị táo bón? 🚽', body_vi = 'Mải chạy nhảy mà bé quên uống nước? Hãy để ý phân khi thay tã. Nếu có nguy cơ táo bón, hãy ghi vào ứng dụng và thêm ngay thực phẩm giàu chất xơ bằng Theo dõi cữ bú.', title_zh = '便秘了？🚽', body_zh = '跑得忘了喝水？换尿布时留意一下排便。如果有便秘风险，记到应用里，马上用喂养记录工具加入富含纤维的食物。' WHERE id = '5592a39d-90a2-449d-9f20-3a71ba9dddad' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Por la noche tardó 40 minutos en dormirse? Mira el gráfico del temporizador de sueño. Quizá sea el momento de acortar la siesta 20 minutos y adelantar la hora de dormir.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il a mis 40 minutes à s''endormir ce soir ? Regardez le graphique du minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 20 minutes et avancer le coucher.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को सोने में 40 मिनट लग गए? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद 20 मिनट कम करने और शाम की नींद जल्दी करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Butuh 40 menit untuk tertidur malam ini? Lihat grafik Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 20 menit dan memajukan jam tidur malam.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夜、寝つくまで40分かかりましたか？睡眠タイマーのグラフを見てみましょう。お昼寝を20分短くして、夜の寝る時間を早めるちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 잠드는 데 40분이 걸렸나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 20분 줄이고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Duurde het inslapen vanavond 40 minuten? Bekijk de grafiek van de Slaaptimer. Misschien is het precies tijd om het middagdutje met 20 minuten in te korten en de bedtijd te vervroegen.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorne zasypianie trwało 40 minut? Spójrz na wykres timera snu. Może to dobry moment, by skrócić drzemkę o 20 minut i przesunąć wieczorne spanie wcześniej.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'À noite demorou 40 minutos a adormecer? Veja o gráfico do temporizador de sono. Talvez seja a altura certa de encurtar a sesta 20 minutos e antecipar a hora de deitar.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Tog det 40 minuter att somna i kväll? Titta på grafen i sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 20 minuter och tidigarelägga kvällen.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Tối qua bé mất 40 phút mới ngủ? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 20 phút và cho bé ngủ tối sớm hơn.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上入睡花了40分钟？看看睡眠计时器的图表。也许正是把白天小睡缩短20分钟、把晚上就寝时间提前的时候了。' WHERE id = 'a589907e-1ec5-4668-9a51-f72995d314f0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin azúcar, pero dulce 🍪', body_es = '¿Quiere merendar? No hacen falta galletas del súper. Prepara con Recetas para bebé dulces sanos de dátiles y avena en 10 minutos.', title_fr = 'Sans sucre, mais sucré 🍪', body_fr = 'Il réclame un goûter ? Pas besoin de biscuits du commerce. Préparez les douceurs saines aux dattes et à l''avoine des Recettes pour bébés, prêtes en 10 minutes.', title_hi = 'बिना चीनी, फिर भी मीठा 🍪', body_hi = 'दोपहर का स्नैक चाहिए? बाज़ार के बिस्किट की ज़रूरत नहीं। बच्चों की रेसिपी से 10 मिनट में बनने वाली खजूर और ओट्स की सेहतमंद मिठाइयाँ बनाइए।', title_id = 'Tanpa gula, tapi manis 🍪', body_id = 'Ingin camilan siang? Tak perlu biskuit dari toko. Buat camilan manis sehat dari kurma dan oat yang siap dalam 10 menit dari Resep Bayi.', title_ja = '砂糖なしでも甘い 🍪', body_ja = 'お昼のおやつがほしい？市販のクッキーはいりません。「離乳食を始める赤ちゃんのレシピ」で、10分でつくれるデーツとオートミールのヘルシーなおやつを焼きましょう。', title_ko = '설탕 없이도 달콤하게 🍪', body_ko = '오후 간식을 찾나요? 마트 쿠키는 필요 없어요. 아기 레시피에서 10분이면 만드는 대추야자 귀리 건강 간식을 구워 보세요.', title_nl = 'Zonder suiker, maar zoet 🍪', body_nl = 'Wil hij ''s middags een tussendoortje? Koekjes uit de winkel zijn niet nodig. Bak uit Babyrecepten gezonde lekkernijen met dadels en havermout, klaar in 10 minuten.', title_pl = 'Bez cukru, ale słodko 🍪', body_pl = 'Chce popołudniowej przekąski? Sklepowe ciastka nie są potrzebne. Upiecz z Przepisów dla niemowląt zdrowe słodkości z daktylami i płatkami owsianymi gotowe w 10 minut.', title_pt = 'Sem açúcar, mas doce 🍪', body_pt = 'Quer um lanche à tarde? Não precisa de bolachas do supermercado. Faça com as Receitas para bebés doces saudáveis de tâmaras e aveia, prontos em 10 minutos.', title_sv = 'Sockerfritt, men sött 🍪', body_sv = 'Vill barnet ha ett mellanmål på eftermiddagen? Ni behöver inga kex från affären. Baka nyttiga sötsaker med dadlar och havre som är klara på 10 minuter från Recept för bebisar.', title_vi = 'Không đường mà vẫn ngọt 🍪', body_vi = 'Bé đòi ăn vặt buổi chiều? Không cần bánh quy mua sẵn. Hãy làm các món ngọt bổ dưỡng từ chà là và yến mạch trong 10 phút theo Công thức cho bé.', title_zh = '无糖，却很甜 🍪', body_zh = '下午想吃点心？不需要超市的饼干。用宝宝食谱做些10分钟就能完成的椰枣燕麦健康甜点吧。' WHERE id = '1966178b-773a-4205-ab76-e8693f0abf72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Caras graciosas 🤪', body_es = '¿Hace muecas delante del espejo? ¡No te pierdas este momento tan divertido! Decóralo ya con los marcos graciosos de la Sesión de fotos del bebé y añádelo al álbum.', title_fr = 'Grimaces rigolotes 🤪', body_fr = 'Il fait des grimaces devant le miroir ? Ne manquez pas ce moment amusant ! Décorez-le tout de suite avec les cadres rigolos de la Séance photo bébé et ajoutez-le à l''album.', title_hi = 'मज़ेदार चेहरे 🤪', body_hi = 'आईने के सामने मुँह बनाता है? यह मज़ेदार पल मत चूकिए! तुरंत बेबी फ़ोटोशूट के मज़ेदार फ़्रेम से सजाकर एल्बम में जोड़िए।', title_id = 'Ekspresi wajah lucu 🤪', body_id = 'Ia memasang wajah lucu di depan cermin? Jangan lewatkan momen seru ini! Segera hiasi dengan bingkai lucu dari Sesi Foto Bayi dan tambahkan ke album.', title_ja = 'おもしろい顔 🤪', body_ja = '鏡の前で変な顔をしていますか？この楽しい瞬間を見逃さないで！すぐに「ベビーフォトセッション」のおもしろいフレームで飾って、アルバムに追加しましょう。', title_ko = '웃긴 표정 🤪', body_ko = '거울 앞에서 얼굴을 찡그리고 있나요? 이 재미있는 순간을 놓치지 마세요! 바로 아기 사진 촬영의 재미있는 프레임으로 꾸며 앨범에 올려 보세요.', title_nl = 'Grappige gezichtjes 🤪', body_nl = 'Trekt hij gekke bekken voor de spiegel? Mis dit leuke moment niet! Versier het meteen met grappige kaders in Babyfotoshoot en zet het in het album.', title_pl = 'Śmieszne miny 🤪', body_pl = 'Robi miny przed lustrem? Nie przegap tej zabawnej chwili! Od razu ozdób zdjęcie śmiesznymi ramkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'Caretas engraçadas 🤪', body_pt = 'Faz caretas em frente ao espelho? Não perca este momento divertido! Decore-o já com as molduras engraçadas da Sessão Fotográfica do Bebé e adicione-o ao álbum.', title_sv = 'Roliga miner 🤪', body_sv = 'Gör barnet grimaser framför spegeln? Missa inte det roliga ögonblicket! Dekorera det direkt med roliga ramar i Babyfotografering och lägg till det i albumet.', title_vi = 'Biểu cảm khuôn mặt hài hước 🤪', body_vi = 'Bé nhăn mặt làm trò trước gương? Đừng bỏ lỡ khoảnh khắc vui nhộn này! Hãy trang trí ngay bằng khung ảnh ngộ nghĩnh trong Chụp ảnh cho bé và thêm vào album.', title_zh = '搞笑表情 🤪', body_zh = '在镜子前挤眉弄眼？别错过这个有趣的时刻！马上用宝宝写真里的搞笑相框装饰一下，加进相册。' WHERE id = '6f0ae293-593e-4249-828e-c2ec4c4fce2b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas una pausa ☕', body_es = '¡Sal de casa y respira un poco! Busca en Lugares para mamás una cafetería cercana con rincón infantil, disfruta de tu café caliente y conoce a otras madres.', title_fr = 'Vous aussi, vous avez besoin d''une pause ☕', body_fr = 'Sortez prendre un peu l''air ! Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants près de chez vous, savourez votre café chaud et rencontrez d''autres mamans.', title_hi = 'आपको भी ब्रेक चाहिए ☕', body_hi = 'घर से निकलकर थोड़ी साँस लीजिए! माँ के लिए अनुकूल जगहें में पास का बच्चों के कोने वाला कैफ़े ढूँढिए, अपनी गर्म कॉफ़ी का मज़ा लीजिए और दूसरी माँओं से मिलिए।', title_id = 'Anda juga butuh rehat ☕', body_id = 'Keluar rumah dan hirup udara sebentar! Temukan kafe terdekat dengan sudut bermain anak di Tempat Ramah Ibu, nikmati kopi hangat Anda, dan berkenalan dengan ibu-ibu lain.', title_ja = 'あなたにも休憩が必要です ☕', body_ja = '家を出て、ひと息つきましょう！「ママにやさしいスポット」で近くのキッズコーナーのあるカフェを見つけて、温かいコーヒーを味わい、ほかのママと知り合いましょう。', title_ko = '엄마에게도 휴식이 필요해요 ☕', body_ko = '집을 나서서 잠시 숨을 돌리세요! 엄마 친화 장소에서 가까운 키즈 코너 카페를 찾아 따뜻한 커피를 즐기고 다른 엄마들과도 만나 보세요.', title_nl = 'Jij hebt ook een pauze nodig ☕', body_nl = 'Ga de deur uit en haal even adem! Zoek in Mamavriendelijke plekken een café met kinderhoek in de buurt, geniet van je warme koffie en leer andere moeders kennen.', title_pl = 'Ty też potrzebujesz przerwy ☕', body_pl = 'Wyjdź z domu i odetchnij! Znajdź w Miejscach przyjaznych mamom pobliską kawiarnię z kącikiem dla dzieci, delektuj się gorącą kawą i poznaj inne mamy.', title_pt = 'Também precisa de uma pausa ☕', body_pt = 'Saia de casa e respire um pouco! Encontre nos Locais Amigos das Mães um café perto com cantinho para crianças, saboreie o seu café quente e conheça outras mães.', title_sv = 'Du behöver också en paus ☕', body_sv = 'Gå ut och andas lite! Hitta ett kafé med barnhörna i närheten i Mammavänliga platser, lyssna på ljudet av ditt varma kaffe och lär känna andra mammor.', title_vi = 'Mẹ cũng cần nghỉ ngơi ☕', body_vi = 'Hãy ra ngoài hít thở một chút! Tìm quán cà phê có góc trẻ em gần nhà trong Địa điểm thân thiện với mẹ, tận hưởng ly cà phê nóng và làm quen với các mẹ khác.', title_zh = '你也需要歇一歇 ☕', body_zh = '出门透透气吧！在妈妈友好场所里找一家附近带儿童角的咖啡馆，听听热咖啡的声音，认识其他妈妈。' WHERE id = '853c16b5-ec48-42df-a039-bc81b5a0ae1e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El plato del color equivocado! 🎨', body_es = '¿Se ha montado una crisis porque le diste la comida en el plato rojo y no en el verde? Lee los consejos del Blog para gestionar la tozudez sin lógica de esta edad.', title_fr = 'L''assiette de la mauvaise couleur ! 🎨', body_fr = 'Une crise parce que vous avez servi le repas dans l''assiette rouge et pas la verte ? Lisez les conseils de la rubrique Blogs pour gérer les entêtements illogiques de cet âge.', title_hi = 'गलत रंग की प्लेट! 🎨', body_hi = 'खाना हरी की जगह लाल प्लेट में दिया तो तूफ़ान आ गया? इस उम्र की बेतुकी ज़िदों को संभालने के लिए ब्लॉग सेक्शन की सलाह पढ़िए।', title_id = 'Piringnya salah warna! 🎨', body_id = 'Tantrum karena makanannya disajikan di piring merah, bukan hijau? Baca tips di bagian Blog untuk menghadapi sikap keras kepala yang tak masuk akal di usia ini.', title_ja = 'お皿の色がちがう！🎨', body_ja = 'ごはんを緑ではなく赤いお皿で出したら、かんしゃくに？この年齢の理屈に合わないこだわりに対応するためのアドバイスを、ブログで読んでみましょう。', title_ko = '접시 색깔이 틀렸어요! 🎨', body_ko = '초록 접시가 아니라 빨간 접시에 줬다고 떼를 썼나요? 이 시기의 엉뚱한 고집을 다루는 조언을 블로그에서 읽어 보세요.', title_nl = 'Bord in de verkeerde kleur! 🎨', body_nl = 'Een bui omdat je het eten op een rood bord gaf in plaats van een groen? Lees de tips in Blogs om met de onlogische koppigheid van deze leeftijd om te gaan.', title_pl = 'Talerz w złym kolorze! 🎨', body_pl = 'Wybuchł kryzys, bo dałaś jedzenie na czerwonym talerzu, a nie na zielonym? Przeczytaj w sekcji Blog wskazówki, jak radzić sobie z nielogicznym uporem w tym wieku.', title_pt = 'O prato da cor errada! 🎨', body_pt = 'Houve uma crise porque lhe deu a comida no prato vermelho e não no verde? Leia as sugestões dos Blogues para gerir as teimosias sem lógica desta idade.', title_sv = 'Tallrik i fel färg! 🎨', body_sv = 'Blev det ett utbrott för att du serverade maten på den röda tallriken i stället för den gröna? Läs råden i Bloggar för att hantera den här ålderns ologiska envishet.', title_vi = 'Nhầm màu đĩa! 🎨', body_vi = 'Mẹ đưa thức ăn trong đĩa đỏ thay vì đĩa xanh lá và bé ăn vạ? Hãy đọc lời khuyên trong mục Blog để xử lý những kiểu bướng bỉnh khó hiểu của lứa tuổi này.', title_zh = '盘子颜色不对！🎨', body_zh = '因为用红盘子而不是绿盘子装饭，就闹起来了？去博客板块读读应对这个年龄没道理的倔强的建议。' WHERE id = '7f7e8cbd-f54d-475a-9880-5e509bceab0e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dolor de espalda de mamá 🧘‍♀️', body_es = '¿Te duele la espalda de coger a un peque de más de 13 kg? Cuídate preparando un té de jengibre que relaja los músculos de Recetas saludables para mujeres.', title_fr = 'Le mal de dos de maman 🧘‍♀️', body_fr = 'Votre dos souffre à force de porter un petit de plus de 13 kg ? Prenez soin de vous avec une tisane de gingembre qui détend les muscles, des Recettes saines pour femmes.', title_hi = 'माँ की कमर का दर्द 🧘‍♀️', body_hi = '13+ kg के नन्हे को उठाते-उठाते कमर दुखती है? महिलाओं के लिए सेहतमंद रेसिपी से मांसपेशियों को आराम देने वाली अदरक की चाय बनाइए और अपना ख्याल रखिए।', title_id = 'Sakit punggung Bunda 🧘‍♀️', body_id = 'Punggung nyeri karena menggendong si kecil yang beratnya 13+ kg? Rawat diri Anda dengan menyeduh teh jahe yang merilekskan otot dari Resep Sehat untuk wanita.', title_ja = 'ママの腰痛 🧘‍♀️', body_ja = '13kg以上のお子さんを抱き上げて、腰が痛みますか？「女性のためのヘルシーレシピ」から、筋肉をほぐすしょうが茶をいれて、自分をいたわりましょう。', title_ko = '엄마의 허리 통증 🧘‍♀️', body_ko = '13kg이 넘는 아이를 안아 올리느라 허리가 쑤시나요? 여성을 위한 건강한 레시피에서 근육을 풀어 주는 생강차를 우려 나를 돌보세요.', title_nl = 'Rugpijn van mama 🧘‍♀️', body_nl = 'Zeurt je rug van het tillen van een kleintje van 13+ kg? Zet gemberthee uit Gezonde recepten voor vrouwen die je spieren ontspant, en zorg voor jezelf.', title_pl = 'Ból pleców mamy 🧘‍♀️', body_pl = 'Plecy bolą cię od podnoszenia malucha ważącego ponad 13 kg? Zadbaj o siebie i zaparz ze Zdrowych przepisów dla kobiet herbatę imbirową, która rozluźnia mięśnie.', title_pt = 'As dores de costas da mãe 🧘‍♀️', body_pt = 'As costas doem-lhe de tanto pegar num pequenino de mais de 13 kg? Cuide de si com um chá de gengibre das Receitas Saudáveis para Mulheres, que relaxa os músculos.', title_sv = 'Mammas ryggont 🧘‍♀️', body_sv = 'Värker ryggen av att lyfta en liten på över 13 kg? Brygg ett ingefärste som får musklerna att slappna av från Hälsosamma recept för kvinnor och ta hand om dig själv.', title_vi = 'Mẹ bị đau lưng 🧘‍♀️', body_vi = 'Bế bé hơn 13 kg khiến lưng mẹ ê ẩm? Hãy pha trà gừng giúp thư giãn cơ từ Công thức lành mạnh cho phụ nữ và chăm sóc bản thân nhé.', title_zh = '妈妈的腰痛 🧘‍♀️', body_zh = '抱13+ kg的小家伙抱得腰酸？从女性健康食谱里泡一杯放松肌肉的姜茶，照顾好自己。' WHERE id = '967e4cff-99ce-432e-991e-40e75469ba59' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El imitador secreto 📸', body_es = '¿Habla por teléfono como tú o hace tus mismos gestos? Decora este momento tan gracioso con las pegatinas alegres de la Sesión de fotos del bebé y añádelo al álbum.', title_fr = 'Petit imitateur 📸', body_fr = 'Il parle au téléphone comme vous ou reproduit vos gestes ? Décorez ce moment rigolo avec les stickers joyeux de la Séance photo bébé et ajoutez-le à l''album.', title_hi = 'छुपा नकलची 📸', body_hi = 'आपकी तरह फ़ोन पर बात करता है या वही हरकतें करता है? इस मज़ेदार पल को बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में जोड़िए।', title_id = 'Peniru diam-diam 📸', body_id = 'Bicara di telepon seperti Anda atau meniru gerakan yang sama? Hiasi momen lucu ini dengan stiker ceria dari Sesi Foto Bayi dan tambahkan ke album.', title_ja = 'こっそりまねっこ 📸', body_ja = 'あなたのように電話で話したり、同じ動きをしたりしていますか？このおもしろい瞬間を「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムに追加しましょう。', title_ko = '꼬마 따라쟁이 📸', body_ko = '엄마처럼 전화 통화를 하거나 똑같이 행동하나요? 이 웃긴 순간을 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 올려 보세요.', title_nl = 'Stiekeme na-aper 📸', body_nl = 'Praat hij net als jij aan de telefoon of doet hij dezelfde dingen? Versier dit grappige moment met vrolijke stickers in Babyfotoshoot en zet het in het album.', title_pl = 'Mały naśladowca 📸', body_pl = 'Rozmawia przez telefon jak ty albo powtarza twoje ruchy? Ozdób tę zabawną chwilę wesołymi naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'O imitador secreto 📸', body_pt = 'Fala ao telefone como a mãe ou faz os mesmos gestos? Decore este momento divertido com os autocolantes alegres da Sessão Fotográfica do Bebé e adicione-o ao álbum.', title_sv = 'Hemlig härmare 📸', body_sv = 'Pratar barnet i telefon som du eller gör samma rörelser? Dekorera det roliga ögonblicket med glada klistermärken i Babyfotografering och lägg till det i albumet.', title_vi = 'Bé bắt chước kín đáo 📸', body_vi = 'Bé nói chuyện điện thoại hay làm động tác y hệt mẹ? Hãy trang trí khoảnh khắc hài hước này bằng sticker vui nhộn trong Chụp ảnh cho bé và thêm vào album.', title_zh = '悄悄模仿 📸', body_zh = '像你一样打电话，或者做同样的动作？用宝宝写真里欢乐的贴纸装饰这个有趣的瞬间，加进相册。' WHERE id = 'a1d9ccbc-d633-4cf7-8231-4a3a870b0696' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de tirarlo todo al suelo 🛑', body_es = '¿Cuando se enfada o se agobia, tira lo que tiene en la mano? Lee en los artículos del Blog cómo reconducir con suavidad estas reacciones emocionales.', title_fr = 'L''envie de tout jeter par terre 🛑', body_fr = 'Il lance ce qu''il a dans les mains quand il se fâche ou se sent frustré ? Lisez dans les articles de la rubrique Blogs comment orienter en douceur ces réactions émotionnelles.', title_hi = 'सब कुछ नीचे फेंकने का शौक 🛑', body_hi = 'गुस्से या ऊब में हाथ की चीज़ घुमाकर फेंक देता है? इन भावनात्मक प्रतिक्रियाओं को नरमी से सही दिशा कैसे दें, यह ब्लॉग सेक्शन के लेखों में पढ़िए।', title_id = 'Hobi melempar segalanya 🛑', body_id = 'Mengayunkan dan melempar barang di tangannya saat marah atau kesal? Baca di artikel bagian Blog cara mengarahkan reaksi emosional ini dengan lembut.', title_ja = 'なんでも床に投げたい 🛑', body_ja = '怒ったり、イライラしたりすると、手に持ったものを振り回して投げますか？こうした気持ちの反応をやさしく導く方法を、ブログの記事で読んでみましょう。', title_ko = '뭐든 바닥에 던지고 싶어요 🛑', body_ko = '화가 나거나 답답하면 손에 든 걸 휘둘러 던지나요? 이런 감정 반응을 부드럽게 이끌어 주는 방법을 블로그의 글에서 읽어 보세요.', title_nl = 'Zin om alles op de grond te gooien 🛑', body_nl = 'Smijt hij weg wat hij vasthoudt als hij boos of gefrustreerd is? Lees in de artikelen in Blogs hoe je deze emotionele reacties zacht bijstuurt.', title_pl = 'Ochota na rzucanie wszystkim 🛑', body_pl = 'Gdy się złości lub denerwuje, rzuca tym, co ma w rękach? Przeczytaj w artykułach w sekcji Blog, jak łagodnie kierować tymi reakcjami emocjonalnymi.', title_pt = 'A mania de atirar tudo ao chão 🛑', body_pt = 'Quando se zanga ou se aborrece, atira o que tem na mão? Leia nos artigos dos Blogues como orientar com suavidade estas reações emocionais.', title_sv = 'Lust att kasta allt på golvet 🛑', body_sv = 'Slänger barnet iväg det hen håller i när hen är arg eller frustrerad? Läs artiklarna i Bloggar om hur du varsamt kan styra dessa känslomässiga reaktioner.', title_vi = 'Mê ném mọi thứ xuống sàn 🛑', body_vi = 'Khi tức giận hoặc bức bối, bé vung tay ném đồ đang cầm? Hãy đọc các bài viết trong mục Blog về cách nhẹ nhàng định hướng những phản ứng cảm xúc này.', title_zh = '什么都想往地上扔 🛑', body_zh = '生气或烦躁时就把手里的东西甩出去？去博客板块的文章里读读，如何温和地引导这些情绪反应。' WHERE id = '43a58d7e-e492-4b05-8142-e4389027f185' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de las manos pintadas 🎨', body_es = '¿Jugando con colores se ha pintado toda la cara? En lugar de enfadarte, fotografía ya este momento creativo y divertido y añádelo al Álbum del bebé como el recuerdo más colorido.', title_fr = 'L''art des mains peintes 🎨', body_fr = 'En jouant avec les couleurs, il s''en est mis plein le visage ? Au lieu de vous énerver, photographiez tout de suite ce moment drôle et créatif et ajoutez-le à l''Album de bébé comme le souvenir le plus coloré.', title_hi = 'रंगे हाथों की कला 🎨', body_hi = 'रंगों से खेलते हुए पूरा चेहरा रंग लिया? गुस्सा होने के बजाय इस मज़ेदार, रचनात्मक पल की तुरंत तस्वीर लीजिए और बेबी एल्बम में सबसे रंगीन याद के रूप में जोड़िए।', title_id = 'Seni tangan penuh cat 🎨', body_id = 'Wajahnya penuh cat saat bermain warna? Daripada kesal, segera abadikan momen lucu dan kreatif ini dan tambahkan ke Album Bayi sebagai kenangan paling berwarna.', title_ja = '絵の具の手でアート 🎨', body_ja = '色で遊んでいて、顔じゅう絵の具だらけに？怒る代わりに、このおもしろくて創造的な瞬間をすぐに撮影して、いちばんカラフルな思い出として「ベビーアルバム」に追加しましょう。', title_ko = '물감 묻은 손의 예술 🎨', body_ko = '물감 놀이를 하다 얼굴이 온통 물감투성이가 되었나요? 화내는 대신 이 재미있고 창의적인 순간을 바로 찍어 아기 앨범의 가장 알록달록한 추억으로 남기세요.', title_nl = 'Kunst met verfhandjes 🎨', body_nl = 'Zit zijn hele gezicht onder de verf na het spelen met kleuren? Word niet boos, maar leg dit grappige, creatieve moment meteen vast en zet het als kleurrijkste herinnering in het Babyalbum.', title_pl = 'Sztuka umazanych rączek 🎨', body_pl = 'Bawiąc się farbami, umazał całą buzię? Zamiast się złościć, od razu uwiecznij tę zabawną, twórczą chwilę i dodaj do Albumu dziecka jako najbardziej kolorową pamiątkę.', title_pt = 'A arte das mãos pintadas 🎨', body_pt = 'A brincar com as cores, sujou a cara toda? Em vez de se enervar, fotografe já este momento divertido e criativo e adicione-o ao Álbum do Bebé como a recordação mais colorida.', title_sv = 'Konsten med färgglada händer 🎨', body_sv = 'Har barnet kladdat ner hela ansiktet när hen lekte med färger? I stället för att bli irriterad, fotografera direkt detta roliga och kreativa ögonblick och lägg till det i Babyalbumet som det mest färgglada minnet.', title_vi = 'Nghệ thuật bàn tay đầy màu 🎨', body_vi = 'Chơi màu mà lem luốc cả mặt mũi? Thay vì bực mình, hãy chụp ngay khoảnh khắc sáng tạo vui nhộn này và thêm vào Album của bé như kỷ niệm rực rỡ nhất.', title_zh = '彩色小手的艺术 🎨', body_zh = '玩颜料时把脸都涂花了？与其生气，不如马上拍下这个有趣又有创意的瞬间，作为最多彩的回忆加进宝宝相册。' WHERE id = 'cec4b4c4-52ab-4e49-adea-d05ca6bfff30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = 'El temporizador se ha parado. Tu peque duerme. ¡Date tu valor! Prepárate una infusión de melisa de Recetas saludables para mujeres, túmbate en el sofá y sumérgete en el silencio tras este día agotador.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Le minuteur est arrêté. Il dort. Pensez à vous ! Préparez une tisane de mélisse des Recettes saines pour femmes, allongez-vous sur le canapé et plongez dans le silence après cette journée épuisante.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'टाइमर रुक गया। बच्चा सो गया। अब अपनी कद्र कीजिए! महिलाओं के लिए सेहतमंद रेसिपी से लेमन बाम की चाय बनाइए, सोफ़े पर लेटिए और इस थकाऊ दिन के बाद खामोशी में डूब जाइए।', title_id = 'Penenang alami 🍃', body_id = 'Timer berhenti. Si kecil sudah tidur. Hargai diri Anda! Seduh teh lemon balm dari Resep Sehat untuk wanita, berbaring di sofa, dan tenggelamlah dalam keheningan setelah hari yang melelahkan ini.', title_ja = '自然のリラックス効果 🍃', body_ja = 'タイマーは止まりました。お子さんは眠りました。自分をいたわって！「女性のためのヘルシーレシピ」からレモンバームティーをいれて、ソファに横になり、疲れた一日のあとの静けさに身をゆだねましょう。', title_ko = '자연의 진정제 🍃', body_ko = '타이머가 멈추고 아이가 잠들었어요. 나를 아껴 주세요! 여성을 위한 건강한 레시피에서 레몬밤 차를 우려 소파에 누워, 고단한 하루 끝의 고요함에 잠겨 보세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'De timer is gestopt. Je kindje slaapt. Waardeer jezelf! Zet citroenmelissethee uit Gezonde recepten voor vrouwen, ga op de bank liggen en geniet na deze vermoeiende dag van de stilte.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'Timer zatrzymany. Maluch śpi. Doceń siebie! Zaparz melisę ze Zdrowych przepisów dla kobiet, połóż się na kanapie i po tym męczącym dniu zanurz się w ciszy.', title_pt = 'Calmante natural 🍃', body_pt = 'O temporizador parou. Ele adormeceu. Valorize-se! Prepare um chá de erva-cidreira das Receitas Saudáveis para Mulheres, deite-se no sofá e mergulhe no silêncio depois deste dia cansativo.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Timern har stannat. Barnet sover. Uppskatta dig själv! Brygg citronmelissate från Hälsosamma recept för kvinnor, lägg dig på soffan och sjunk in i tystnaden efter den tröttsamma dagen.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Hẹn giờ đã dừng. Bé đã ngủ. Hãy trân trọng bản thân! Pha trà tía tô đất từ Công thức lành mạnh cho phụ nữ, nằm dài trên sofa và chìm vào yên tĩnh sau một ngày mệt nhoài.', title_zh = '天然的镇静剂 🍃', body_zh = '计时器停了。孩子睡着了。好好犒劳自己！从女性健康食谱里泡一杯香蜂草茶，躺在沙发上，在累人的一天之后沉浸在安静里。' WHERE id = 'deb2e459-e0cf-41a4-8379-c85e410b286a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Me lavo yo solo! 🧽', body_es = '¿En la bañera te quita la esponja o la toallita? Busca en Productos recomendados accesorios de baño pensados para niños que apoyen este deseo de independencia.', title_fr = 'Je me lave tout seul ! 🧽', body_fr = 'Dans le bain, il vous prend la brosse ou le gant ? Cherchez dans les Produits recommandés des accessoires de bain adaptés aux enfants qui soutiennent cette quête d''autonomie.', title_hi = 'मैं खुद नहाऊँगा! 🧽', body_hi = 'नहाते समय ब्रश या कपड़ा आपके हाथ से ले लेता है? आत्मनिर्भरता की इस चाह में मदद करने वाला बच्चों के लिए सही नहाने का सामान सुझाए गए प्रोडक्ट में ढूँढिए।', title_id = 'Aku mandi sendiri! 🧽', body_id = 'Merebut sikat atau waslap dari tangan Anda saat mandi? Cari perlengkapan mandi ramah anak yang mendukung semangat mandirinya di Produk Rekomendasi.', title_ja = '自分で洗う！🧽', body_ja = 'お風呂でブラシやタオルを取り上げますか？この自立したい気持ちを応援する、子どもにやさしいお風呂グッズを「おすすめ商品」で探してみましょう。', title_ko = '내가 씻을래! 🧽', body_ko = '목욕할 때 엄마 손에서 솔이나 수건을 가져가나요? 이 자립심을 응원하는 아이 친화적인 목욕용품을 추천 제품에서 찾아보세요.', title_nl = 'Ik was zelf! 🧽', body_nl = 'Pakt hij in bad de borstel of het washandje van je af? Zoek in Aanbevolen producten kindvriendelijke badspullen die deze zelfstandigheid steunen.', title_pl = 'Sam umyję! 🧽', body_pl = 'W wannie zabiera ci szczoteczkę albo myjkę? Poszukaj w Polecanych produktach przyjaznych dzieciom akcesoriów kąpielowych, które wspierają tę potrzebę samodzielności.', title_pt = 'Eu lavo sozinho! 🧽', body_pt = 'No banho, tira-lhe a escova ou a esponja da mão? Procure nos Produtos Recomendados artigos de banho para crianças que apoiem esta vontade de independência.', title_sv = 'Jag tvättar själv! 🧽', body_sv = 'Tar barnet borsten eller tvättlappen från dig i badet? Leta efter barnvänliga badtillbehör som stöttar längtan efter självständighet i Rekommenderade produkter.', title_vi = '"Con tự tắm!" 🧽', body_vi = 'Trong bồn tắm bé giành bàn chải hay khăn từ tay mẹ? Hãy tìm những đồ dùng nhà tắm thân thiện với trẻ giúp hỗ trợ mong muốn tự lập này trong Sản phẩm gợi ý.', title_zh = '我要自己洗！🧽', body_zh = '在浴缸里从你手中拿走刷子或毛巾？去推荐商品找找支持这种独立探索、适合孩子的洗浴用品。' WHERE id = '6653e097-de4e-4ae0-8162-9b9f5ea59388' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía en 5 minutos ⚡', body_es = '¿Estás agotada de tanto correr? Renuévate con un batido de crema de cacahuete con proteínas de Recetas saludables para mujeres que da fuerza al instante.', title_fr = '5 minutes d''énergie ⚡', body_fr = 'Épuisée à force de courir ? Préparez avec les Recettes saines pour femmes un smoothie protéiné au beurre de cacahuète, énergisant en un instant, et retrouvez votre énergie.', title_hi = '5 मिनट की ऊर्जा ⚡', body_hi = 'भागदौड़ से थककर चूर हैं? महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाली, प्रोटीन से भरपूर पीनट बटर स्मूदी बनाइए और तरोताज़ा हो जाइए।', title_id = 'Energi 5 menit ⚡', body_id = 'Kehabisan tenaga karena terus berlari? Segarkan diri dengan smoothie selai kacang kaya protein yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = '5分でエネルギー ⚡', body_ja = '走り回って、くたくたですか？「女性のためのヘルシーレシピ」から、すぐに元気が出るたんぱく質たっぷりのピーナッツバタースムージーをつくって、リフレッシュしましょう。', title_ko = '5분 에너지 ⚡', body_ko = '뛰어다니느라 기운이 다 빠졌나요? 여성을 위한 건강한 레시피에서 바로 힘이 나는 단백질 땅콩버터 스무디로 기운을 되찾으세요.', title_nl = 'Energie in 5 minuten ⚡', body_nl = 'Ben je uitgeput van het rennen? Maak uit Gezonde recepten voor vrouwen een eiwitrijke smoothie met pindakaas die je meteen kracht geeft en voel je weer fris.', title_pl = 'Energia w 5 minut ⚡', body_pl = 'Opadasz z sił od bieganiny? Przygotuj ze Zdrowych przepisów dla kobiet białkowe smoothie z masłem orzechowym, które od razu doda ci sił, i odżyj.', title_pt = 'Energia em 5 minutos ⚡', body_pt = 'Está sem forças de tanto correr? Prepare nas Receitas Saudáveis para Mulheres um batido de manteiga de amendoim rico em proteína, que dá força na hora, e renove-se.', title_sv = 'Energi på 5 minuter ⚡', body_sv = 'Helt slut efter allt springande? Gör en proteinrik smoothie med jordnötssmör som ger kraft direkt från Hälsosamma recept för kvinnor och känn dig piggare.', title_vi = 'Năng lượng trong 5 phút ⚡', body_vi = 'Chạy theo bé đến kiệt sức? Hãy làm ly sinh tố bơ đậu phộng giàu đạm, tiếp sức tức thì từ Công thức lành mạnh cho phụ nữ để tràn đầy sức sống.', title_zh = '5分钟能量补给 ⚡', body_zh = '跑得筋疲力尽了？从女性健康食谱里做一杯马上补充能量、富含蛋白质的花生酱奶昔，焕然一新吧。' WHERE id = '74cf7a22-e38a-436b-abf9-30e1ae8f9815' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis del horario de sueño ⏱️', body_es = '¿Por la noche da muchas vueltas en la cama? Mira el gráfico del temporizador de sueño. Quizá sea el momento de acortar la siesta 20 minutos y adelantar la hora de dormir.', title_fr = 'Analyse du rythme de sommeil ⏱️', body_fr = 'Il se tourne et se retourne longtemps dans son lit le soir ? Regardez le graphique du minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 20 minutes et avancer le coucher.', title_hi = 'नींद के रूटीन का विश्लेषण ⏱️', body_hi = 'शाम को बिस्तर पर बहुत करवटें बदलता है? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद 20 मिनट कम करने और शाम की नींद जल्दी करने का सही समय आ गया है।', title_id = 'Analisis jadwal tidur ⏱️', body_id = 'Banyak berguling di tempat tidur malam hari? Lihat grafik Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 20 menit dan memajukan jam tidur malam.', title_ja = '睡眠リズムの分析 ⏱️', body_ja = '夜、ベッドでごろごろ寝返りばかり？睡眠タイマーのグラフを見てみましょう。お昼寝を20分短くして、夜の寝る時間を早めるちょうどいいタイミングかもしれません。', title_ko = '수면 일과 분석 ⏱️', body_ko = '저녁에 침대에서 계속 뒤척이나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 20분 줄이고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Analyse van het slaapritme ⏱️', body_nl = 'Draait hij ''s avonds veel rond in bed? Bekijk de grafiek van de Slaaptimer. Misschien is het precies tijd om het middagdutje met 20 minuten in te korten en de bedtijd te vervroegen.', title_pl = 'Analiza rytmu snu ⏱️', body_pl = 'Wieczorem długo wierci się w łóżku? Spójrz na wykres timera snu. Może to dobry moment, by skrócić drzemkę o 20 minut i przesunąć wieczorne spanie wcześniej.', title_pt = 'Análise da rotina de sono ⏱️', body_pt = 'À noite dá muitas voltas na cama? Veja o gráfico do temporizador de sono. Talvez seja a altura certa de encurtar a sesta 20 minutos e antecipar a hora de deitar.', title_sv = 'Analys av sömnrytmen ⏱️', body_sv = 'Vrider sig barnet mycket i sängen på kvällen? Titta på grafen i sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 20 minuter och tidigarelägga kvällen.', title_vi = 'Phân tích nếp ngủ ⏱️', body_vi = 'Buổi tối bé trằn trọc mãi trên giường? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 20 phút và cho bé ngủ tối sớm hơn.', title_zh = '睡眠作息分析 ⏱️', body_zh = '晚上在床上翻来覆去？看看睡眠计时器的图表。也许正是把白天小睡缩短20分钟、把晚上就寝时间提前的时候了。' WHERE id = '86c19953-fc54-4688-b5d9-b4feaed16fa5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El fondo mágico del silencio 🌊', body_es = '¿Ha sido un día muy ruidoso y lleno de rabietas? Pon las olas del mar de Ruido blanco y calma el sistema nervioso de los dos.', title_fr = 'Un fond magique de calme 🌊', body_fr = 'Une journée pleine de crises et de bruit ? Lancez les vagues de l''océan des Bruits blancs pour apaiser son système nerveux comme le vôtre.', title_hi = 'खामोशी का जादुई बैकग्राउंड 🌊', body_hi = 'बहुत नखरों और शोर भरा दिन था? व्हाइट नॉइज़ में समुद्र की लहरें चलाइए और उसके और अपने, दोनों के तंत्रिका तंत्र को शांत कीजिए।', title_id = 'Latar hening yang ajaib 🌊', body_id = 'Hari ini penuh tantrum dan bising? Putar suara ombak dari Suara Putih untuk menenangkan saraf ia dan Anda.', title_ja = '静けさの魔法のBGM 🌊', body_ja = 'かんしゃくが多く、にぎやかな一日でしたか？「ホワイトノイズ」の波の音を流して、お子さんとあなたの神経を落ち着かせましょう。', title_ko = '고요함을 만드는 마법의 소리 🌊', body_ko = '떼쓰기 많고 시끄러운 하루였나요? 백색소음의 파도 소리를 틀어 아이와 엄마의 신경을 함께 진정시켜 주세요.', title_nl = 'Magische achtergrond van stilte 🌊', body_nl = 'Was het een dag vol driftbuien en lawaai? Zet oceaangolven uit Witte ruis aan en kalmeer zijn zenuwstelsel en dat van jezelf.', title_pl = 'Magiczne tło ciszy 🌊', body_pl = 'To był dzień pełen kryzysów i hałasu? Włącz fale oceanu z Białego szumu i uspokój układ nerwowy jego i swój.', title_pt = 'O fundo mágico do silêncio 🌊', body_pt = 'Foi um dia cheio de crises e barulho? Ligue as ondas do mar do Ruído Branco e acalme o sistema nervoso dele e o seu.', title_sv = 'Tystnadens magiska bakgrund 🌊', body_sv = 'Har dagen varit full av utbrott och buller? Sätt på havsvågor från Vitt brus och lugna både barnets och ditt eget nervsystem.', title_vi = 'Nền âm thanh kỳ diệu của tĩnh lặng 🌊', body_vi = 'Hôm nay quá nhiều cơn ăn vạ và ồn ào? Hãy bật tiếng sóng biển trong Tiếng ồn trắng để làm dịu hệ thần kinh của cả bé lẫn mẹ.', title_zh = '安静的神奇背景音 🌊', body_zh = '今天又闹又吵，崩溃不断？打开白噪音里的海浪声，让宝宝和你自己的神经系统都平静下来。' WHERE id = '69468bd3-2ce5-4731-b30e-3685775a4a1a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Jugando con verduras 🥦', body_es = '¿Rechaza las espinacas? Descubre en Recetas para bebé cómo esconder con maña estas vitaminas en unas tortitas deliciosas y ábrele el apetito.', title_fr = 'Jouer avec les légumes 🥦', body_fr = 'Il refuse les épinards ? Découvrez dans les Recettes pour bébés comment cacher habilement ces vitamines dans de délicieuses crêpes et ouvrez-lui l''appétit.', title_hi = 'सब्ज़ियों के साथ खेल 🥦', body_hi = 'पालक नहीं खाता? बच्चों की रेसिपी में जानिए कि इन विटामिनों को स्वादिष्ट पैनकेक में चतुराई से कैसे छिपाएँ, और उसकी भूख खोलिए।', title_id = 'Bermain dengan sayuran 🥦', body_id = 'Menolak bayam? Temukan di Resep Bayi cara pintar menyembunyikan vitamin-vitamin ini di dalam panekuk yang lezat, dan buka nafsu makannya.', title_ja = '野菜であそぼう 🥦', body_ja = 'ほうれん草を嫌がりますか？「離乳食を始める赤ちゃんのレシピ」で、これらのビタミンをおいしいパンケーキに上手に隠す方法を見つけて、食欲を引き出しましょう。', title_ko = '채소와 함께 놀아요 🥦', body_ko = '시금치를 거부하나요? 아기 레시피에서 이 비타민들을 맛있는 팬케이크 속에 감쪽같이 숨기는 법을 찾아 입맛을 살려 주세요.', title_nl = 'Spelen met groente 🥦', body_nl = 'Weigert hij spinazie? Ontdek in Babyrecepten hoe je deze vitamines slim verstopt in lekkere pannenkoekjes en wek zijn eetlust op.', title_pl = 'Zabawa z warzywami 🥦', body_pl = 'Odrzuca szpinak? Odkryj w Przepisach dla niemowląt, jak zręcznie ukryć te witaminy w pysznych placuszkach, i pobudź jego apetyt.', title_pt = 'A brincar com os legumes 🥦', body_pt = 'Rejeita os espinafres? Descubra nas Receitas para bebés como esconder com mestria estas vitaminas em panquecas deliciosas e abra-lhe o apetite.', title_sv = 'Lek med grönsaker 🥦', body_sv = 'Vägrar barnet spenat? Upptäck i Recept för bebisar hur du skickligt gömmer dessa vitaminer i goda pannkakor och väck aptiten.', title_vi = 'Chơi cùng rau củ 🥦', body_vi = 'Bé từ chối rau chân vịt? Hãy khám phá cách khéo léo giấu những vitamin này vào bánh kếp thơm ngon trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '和蔬菜玩游戏 🥦', body_zh = '不吃菠菜？在宝宝食谱里发现如何把这些维生素巧妙地藏进美味的小煎饼里，让宝宝胃口大开。' WHERE id = '86704e7d-f300-4ac8-a2e1-2a5068e8a7e2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón! 📏', body_es = '¿Los pantalones vuelven a quedarle cortos? Hacia el mes 25 el desarrollo físico se acelera. Introduce sus medidas actuales en el Seguimiento del desarrollo y mira con orgullo su curva de crecimiento.', title_fr = 'Poussée de croissance ! 📏', body_fr = 'Le pantalon est encore trop court ? Vers le 25e mois, la croissance physique s''accélère. Entrez ses mesures actuelles dans le Suivi de croissance et regardez fièrement sa courbe.', title_hi = 'लंबाई में उछाल! 📏', body_hi = 'पैंट फिर छोटी हो गई? 25वें महीने के करीब शारीरिक विकास तेज़ हो रहा है। ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और गर्व से विकास चार्ट देखिए।', title_id = 'Lonjakan tinggi badan! 📏', body_id = 'Celananya kependekan lagi? Pertumbuhan fisik makin cepat menjelang usia 25 bulan. Masukkan ukuran terbarunya ke Pelacak Perkembangan dan lihat grafik pertumbuhannya dengan bangga.', title_ja = '背がぐんと伸びた！📏', body_ja = 'ズボンがまた短くなった？2歳1か月に向けて、体の成長が加速しています。「発達トラッカー」に今のサイズを入力して、成長グラフを誇らしく眺めましょう。', title_ko = '키가 쑥! 📏', body_ko = '바지가 또 짧아졌나요? 25개월을 앞두고 신체 발달이 빨라져요. 성장 기록에 현재 치수를 입력하고 성장 그래프를 뿌듯하게 확인하세요.', title_nl = 'Groeispurt! 📏', body_nl = 'Is de broek weer te kort? Rond de 25e maand gaat de lichamelijke groei sneller. Voer de huidige maten in de Groeitracker in en kijk trots naar zijn groeicurve.', title_pl = 'Skok wzrostowy! 📏', body_pl = 'Spodnie znów za krótkie? Około 25. miesiąca rozwój fizyczny przyspiesza. Wpisz aktualne pomiary w Śledzeniu rozwoju i z dumą spójrz na wykres rozwoju.', title_pt = 'Salto de crescimento! 📏', body_pt = 'As calças voltaram a ficar curtas? Perto dos 25 meses, o crescimento físico acelera. Introduza as medidas atuais no Registo de Desenvolvimento e veja com orgulho o gráfico de crescimento.', title_sv = 'Längdspurt! 📏', body_sv = 'Byxorna för korta igen? Mot 25:e månaden går den fysiska utvecklingen fortare. Ange aktuella mått i Utvecklingsspåraren och titta stolt på tillväxtkurvan.', title_vi = 'Bé cao vọt! 📏', body_vi = 'Quần lại ngắn rồi? Gần tháng thứ 25, bé phát triển thể chất nhanh hơn. Hãy nhập số đo hiện tại vào Theo dõi phát triển và tự hào ngắm biểu đồ phát triển.', title_zh = '长个子啦！📏', body_zh = '裤子又变短了？快到25个月了，身体发育在加速。在发育追踪里输入当前的尺寸，骄傲地看看成长曲线。' WHERE id = 'c422d14a-eccf-4f6a-bcbb-1ec2a5bdfc3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Se le queda pequeña la casa. Busca en Lugares para mamás un parque amplio y seguro, y deja que corra a sus anchas y gaste toda su energía.', body_fr = 'Il se sent à l''étroit à la maison. Trouvez un parc grand et sûr dans les Lieux adaptés aux mamans et laissez-le courir librement pour dépenser toute son énergie.', body_hi = 'घर की दीवारें उसके लिए छोटी पड़ रही हैं। माँ के लिए अनुकूल जगहें में बड़ा और सुरक्षित पार्क ढूँढिए और उसे खुलकर दौड़ने दीजिए ताकि उसकी सारी ऊर्जा निकल जाए।', body_id = 'Rumah terasa sempit baginya. Temukan taman yang luas dan aman di Tempat Ramah Ibu, dan biarkan ia bebas berlari menyalurkan seluruh energinya.', body_ja = '家の中では狭すぎる。「ママにやさしいスポット」で広くて安全な公園を見つけて、自由に走り回ってエネルギーを全部発散させてあげましょう。', body_ko = '집이 답답하게 느껴져요. 엄마 친화 장소에서 넓고 안전한 공원을 찾아 마음껏 뛰며 에너지를 모두 발산하게 해 주세요.', body_nl = 'Het huis wordt te klein voor hem. Zoek in Mamavriendelijke plekken een ruim en veilig park en laat hem vrij rennen om al zijn energie kwijt te raken.', body_pl = 'W domu robi mu się za ciasno. Znajdź w Miejscach przyjaznych mamom duży i bezpieczny park i pozwól mu swobodnie biegać, aż rozładuje całą energię.', body_pt = 'As paredes de casa ficam-lhe apertadas. Encontre nos Locais Amigos das Mães um parque amplo e seguro e deixe-o correr à vontade e gastar toda a energia.', body_sv = 'Väggarna hemma känns för trånga. Hitta en stor och trygg park i Mammavänliga platser och låt barnet springa fritt och få ut all energi.', body_vi = 'Nhà trở nên chật chội với bé. Hãy tìm một công viên rộng rãi và an toàn trong Địa điểm thân thiện với mẹ, để bé tự do chạy nhảy và xả hết năng lượng.', body_zh = '家里的墙关不住宝宝了。在妈妈友好场所里找一个宽敞安全的公园，让宝宝自由奔跑，释放所有精力。' WHERE id = '2f36e03e-8050-4c96-a7d2-3231c5e8bf3f' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de paciencia en la mesa ⏱️', body_es = '¿Juega con la comida pero no come? Pon el temporizador de tomas, controla cuánto dura y analiza la evolución de su apetito con el gráfico de la app.', title_fr = 'Patience à table ⏱️', body_fr = 'Il joue avec la nourriture mais ne mange pas ? Lancez le minuteur des repas, suivez la durée du repas et analysez l''évolution de son appétit grâce au graphique de l''appli.', title_hi = 'मेज़ पर सब्र की परीक्षा ⏱️', body_hi = 'खाने से खेलता है, पर खाता नहीं? फ़ीडिंग टाइमर चालू कीजिए, समय पर नज़र रखिए और ऐप के चार्ट से भूख के रुझान को समझिए।', title_id = 'Ujian kesabaran di meja makan ⏱️', body_id = 'Bermain dengan makanan, tapi tidak makan? Nyalakan Timer Makan, pantau durasinya, dan analisis perkembangan nafsu makannya lewat grafik di aplikasi.', title_ja = '食卓で試される忍耐 ⏱️', body_ja = '食べ物で遊ぶけれど、食べない？食事タイマーをオンにして食事の時間を記録し、アプリのグラフで食欲の変化を分析しましょう。', title_ko = '식탁에서의 인내심 시험 ⏱️', body_ko = '음식으로 장난만 치고 먹지는 않나요? 수유 타이머를 켜서 시간을 재고 앱의 그래프로 식욕의 변화를 분석해 보세요.', title_nl = 'Geduldproef aan tafel ⏱️', body_nl = 'Speelt hij met eten, maar eet hij niet? Zet de Voedingstimer aan, volg hoe lang het duurt en analyseer zijn eetlust met de grafiek in de app.', title_pl = 'Test cierpliwości przy stole ⏱️', body_pl = 'Bawi się jedzeniem, ale nie je? Włącz timer karmienia, śledź czas posiłku i przeanalizuj apetyt dzięki wykresowi w aplikacji.', title_pt = 'Teste de paciência à mesa ⏱️', body_pt = 'Brinca com a comida, mas não come? Ligue o temporizador de alimentação, acompanhe a duração e analise a evolução do apetite no gráfico da app.', title_sv = 'Tålamodsprov vid bordet ⏱️', body_sv = 'Leker barnet med maten men äter inte? Starta matningstimern, följ hur lång tid det tar och analysera aptitens utveckling med grafen i appen.', title_vi = 'Thử thách kiên nhẫn trên bàn ăn ⏱️', body_vi = 'Bé nghịch thức ăn mà không ăn? Hãy bật Hẹn giờ cho bú, theo dõi thời gian và phân tích khẩu vị qua biểu đồ trong ứng dụng.', title_zh = '餐桌上的耐心考验 ⏱️', body_zh = '玩食物，就是不吃？打开喂养计时器，记录用餐时长，用应用里的图表分析食欲的变化。' WHERE id = '484ef066-dacc-4b23-98a9-ef3409b6f055' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Por qué pega de repente? 🛑', body_es = '¿Levanta la mano cuando se enfada? Aprende con el experto Anacan AI a cambiar con suavidad las emociones agresivas de esta edad convirtiéndolas en un juego.', title_fr = 'Pourquoi tape-t-il soudain ? 🛑', body_fr = 'Il lève la main quand il se fâche ? Découvrez avec l''expert Anacan AI comment transformer en jeu les émotions agressives de cet âge et les faire évoluer en douceur.', title_hi = 'अचानक क्यों मारता है? 🛑', body_hi = 'गुस्से में हाथ उठाता है? इस उम्र की आक्रामक भावनाओं को खेल बनाकर नरमी से कैसे बदलें, यह Anacan AI एक्सपर्ट से जानिए।', title_id = 'Kenapa tiba-tiba memukul? 🛑', body_id = 'Mengangkat tangan saat marah? Pelajari dari ahli Anacan AI cara mengubah emosi agresif khas usia ini dengan lembut lewat permainan.', title_ja = 'どうして急にたたくの？🛑', body_ja = '怒ると手が出ますか？この年齢の激しい気持ちを遊びに変えて、やさしく変えていく方法を、Anacan AIのエキスパートから学びましょう。', title_ko = '왜 갑자기 때릴까요? 🛑', body_ko = '화가 나면 손을 드나요? 이 나이의 공격적인 감정을 놀이로 바꿔 부드럽게 다루는 방법을 Anacan AI 전문가에게 배워 보세요.', title_nl = 'Waarom slaat hij ineens? 🛑', body_nl = 'Haalt hij uit als hij boos is? Leer bij de Anacan AI-expert hoe je de heftige emoties van deze leeftijd zacht verandert door er een spelletje van te maken.', title_pl = 'Dlaczego nagle bije? 🛑', body_pl = 'Gdy się złości, podnosi rękę? Dowiedz się od eksperta Anacan AI, jak łagodnie zmienić agresywne emocje typowe dla tego wieku, zamieniając je w zabawę.', title_pt = 'Porque bate de repente? 🛑', body_pt = 'Quando se zanga, levanta a mão? Aprenda com o especialista Anacan AI a mudar com suavidade as emoções agressivas desta idade, transformando-as num jogo.', title_sv = 'Varför slår barnet plötsligt? 🛑', body_sv = 'Lyfter barnet handen när hen blir arg? Lär dig av experten Anacan AI hur du varsamt kan förändra den här ålderns aggressiva känslor genom att göra det till en lek.', title_vi = 'Vì sao bé bỗng dưng đánh? 🛑', body_vi = 'Bé vung tay khi tức giận? Hãy học từ chuyên gia Anacan AI cách nhẹ nhàng thay đổi những cảm xúc hung hăng của lứa tuổi này bằng cách biến chúng thành trò chơi.', title_zh = '为什么突然打人？🛑', body_zh = '一生气就动手？向Anacan AI专家学习如何把这个年龄激烈的情绪变成游戏，温和地加以改变。' WHERE id = 'd99bde2e-2ab1-43d0-b2d0-95122a7f44ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Tareas de casa y cuidado del peque... ¡Ahora toca una pausa! Busca en Lugares para mamás una cafetería con rincón infantil y disfruta de tu café caliente.', body_fr = 'Tâches ménagères et soins de l''enfant... C''est l''heure de la pause ! Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants et savourez votre café chaud.', body_hi = 'घर के काम और बच्चे की देखभाल... अब ब्रेक का समय है! माँ के लिए अनुकूल जगहें में बच्चों के कोने वाला कैफ़े ढूँढिए और अपनी गर्म कॉफ़ी का मज़ा लीजिए।', body_id = 'Pekerjaan rumah dan mengasuh anak... Sekarang waktunya rehat! Temukan kafe dengan sudut bermain anak di Tempat Ramah Ibu dan nikmati kopi hangat Anda.', body_ja = '家事に育児…今は休憩の時間です！「ママにやさしいスポット」でキッズコーナーのあるカフェを見つけて、温かいコーヒーをゆっくり味わいましょう。', body_ko = '집안일과 육아... 이제 쉬는 시간이에요! 엄마 친화 장소에서 키즈 코너가 있는 카페를 찾아 따뜻한 커피를 즐겨 보세요.', body_nl = 'Huishouden en de zorg voor je kindje... Nu is het tijd voor een pauze! Zoek in Mamavriendelijke plekken een café met kinderhoek en geniet van je warme koffie.', body_pl = 'Obowiązki domowe i opieka nad dzieckiem... Teraz czas na przerwę! Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem dla dzieci i delektuj się gorącą kawą.', body_pt = 'Tarefas da casa e cuidar da criança... Agora é hora de uma pausa! Encontre nos Locais Amigos das Mães um café com cantinho para crianças e saboreie o seu café quente.', body_sv = 'Hushållssysslor och barnomsorg... Nu är det dags för en paus! Hitta ett kafé med barnhörna i Mammavänliga platser och lyssna på ljudet av ditt varma kaffe.', body_vi = 'Việc nhà và chăm con... Giờ là lúc nghỉ ngơi! Hãy tìm một quán cà phê có góc trẻ em trong Địa điểm thân thiện với mẹ và tận hưởng ly cà phê nóng của mình.', body_zh = '家务加带娃……现在是休息时间！在妈妈友好场所里找一家带儿童角的咖啡馆，听听热咖啡的声音。' WHERE id = '1a858fa5-276f-440e-972b-2b83e93db467' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Equilibrio de vitamina C 🍊', body_es = 'Sus defensas tienen que estar fuertes. Calcula con el Seguimiento de tomas si hoy ha tomado suficiente vitamina C y actualiza su menú.', title_fr = 'L''équilibre en vitamine C 🍊', body_fr = 'Son immunité doit être solide. Calculez avec le Suivi des repas s''il a eu assez de vitamine C aujourd''hui et mettez son menu à jour.', title_hi = 'विटामिन C का संतुलन 🍊', body_hi = 'इम्युनिटी मज़बूत होनी चाहिए। फ़ीडिंग ट्रैकर से गिनिए कि आज उसे पर्याप्त विटामिन C मिला या नहीं, और मेन्यू अपडेट कीजिए।', title_id = 'Keseimbangan vitamin C 🍊', body_id = 'Daya tahan tubuh harus kuat. Hitung dengan alat Pemantau Nutrisi apakah hari ini ia sudah cukup mendapat vitamin C, lalu perbarui menunya.', title_ja = 'ビタミンCのバランス 🍊', body_ja = '免疫を強くしておくことが大切です。「栄養管理ツール」で、今日ビタミンCを十分とれたか計算して、メニューを見直しましょう。', title_ko = '비타민 C 균형 🍊', body_ko = '면역력은 튼튼해야 해요. 수유 기록 도구로 오늘 비타민 C를 충분히 섭취했는지 계산하고 식단을 업데이트하세요.', title_nl = 'Vitamine C-balans 🍊', body_nl = 'Zijn afweer moet sterk zijn. Bereken met de Voedingstracker of hij vandaag genoeg vitamine C heeft gehad en pas het menu aan.', title_pl = 'Bilans witaminy C 🍊', body_pl = 'Odporność musi być silna. Oblicz w narzędziu do śledzenia karmienia, czy dostał dziś wystarczająco witaminy C, i odśwież menu.', title_pt = 'Equilíbrio de vitamina C 🍊', body_pt = 'A imunidade tem de ser forte. Calcule com o Registo de Alimentação se hoje recebeu vitamina C suficiente e atualize a ementa.', title_sv = 'C-vitaminbalans 🍊', body_sv = 'Immunförsvaret behöver vara starkt. Räkna ut med Matningskoll om barnet fått tillräckligt med C-vitamin i dag och uppdatera menyn.', title_vi = 'Cân bằng vitamin C 🍊', body_vi = 'Hệ miễn dịch cần khỏe mạnh. Hãy tính bằng Theo dõi cữ bú xem hôm nay bé đã nhận đủ vitamin C chưa và làm mới thực đơn.', title_zh = '维生素C的平衡 🍊', body_zh = '免疫力要强。用喂养记录工具算一算宝宝今天是否摄入了足够的维生素C，更新一下菜单。' WHERE id = '9fcf0a97-e2c0-4a40-994a-17bcfcd07b1b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿por qué?» sin fin 🤔', body_es = '«¿Qué es eso?», «¿Por qué es así?»... ¡Ya cuestiona el mundo! Responde con paciencia, porque son momentos en los que las neuronas de su cerebro están de fiesta.', title_fr = 'La période des « pourquoi ? » sans fin 🤔', body_fr = '« C''est quoi ? », « Pourquoi c''est comme ça ? »... Il interroge déjà le monde ! Répondez avec patience : ce sont des moments où les neurones de son cerveau font la fête.', title_hi = 'कभी न खत्म होने वाले ''क्यों?'' का दौर 🤔', body_hi = '''यह क्या है?'', ''ऐसा क्यों है?''... वह अब दुनिया पर सवाल करने लगा है! धैर्य से जवाब दीजिए, क्योंकि ये वे पल हैं जब उसके दिमाग के न्यूरॉन जश्न मना रहे होते हैं।', title_id = 'Masa kenapa? yang tak ada habisnya 🤔', body_id = 'Itu apa?, Kenapa begitu?... Ia sudah mulai mempertanyakan dunia! Jawablah dengan sabar, karena inilah saat-saat neuron di otaknya sedang berpesta.', title_ja = '終わらない「なんで？」の時期 🤔', body_ja = '「あれなに？」「なんでこうなの？」…もう世界に疑問を持ち始めています！気長に答えてあげましょう。今まさに、脳の神経細胞がお祭りをしている瞬間です。', title_ko = '끝없는 ''왜?'' 시기 🤔', body_ko = '''저게 뭐야?'', ''왜 그래?''... 벌써 세상에 질문을 던지고 있어요! 인내심을 갖고 대답해 주세요. 지금이 바로 아이 뇌의 신경세포들이 축제를 여는 순간이에요.', title_nl = 'De eindeloze waarom?-fase 🤔', body_nl = 'Wat is dat? Waarom is dat zo?... Hij stelt de wereld al vragen! Antwoord geduldig, want dit zijn de momenten waarop de neuronen in zijn hersenen feestvieren.', title_pl = 'Niekończący się etap „dlaczego?” 🤔', body_pl = '„Co to jest?”, „Dlaczego tak jest?”... On już zadaje pytania o świat! Odpowiadaj cierpliwie, bo to chwile, w których neurony w jego mózgu świętują.', title_pt = 'A fase interminável do "Porquê?" 🤔', body_pt = '"O que é aquilo?", "Porque é assim?"... Já questiona o mundo! Responda com paciência, porque são momentos em que os neurónios do cérebro dele estão em festa.', title_sv = '”Varför?”-perioden som aldrig tar slut 🤔', body_sv = '”Vad är det?”, ”Varför är det så?”... Barnet ifrågasätter redan världen! Svara med tålamod, för det är stunder då nervcellerna i hjärnan firar.', title_vi = 'Giai đoạn "Tại sao?" bất tận 🤔', body_vi = '"Cái gì đây?", "Sao lại thế?"... Bé đã bắt đầu đặt câu hỏi về thế giới! Hãy kiên nhẫn trả lời, vì đây là lúc các nơ-ron trong não bé đang "mở hội".', title_zh = '没完没了的“为什么？”阶段 🤔', body_zh = '“那是什么？”“为什么会这样？”……宝宝已经开始追问这个世界了！耐心回答吧，因为这正是宝宝脑中神经元在狂欢的时刻。' WHERE id = '0ef06d2c-90d7-4377-9290-8bde591b5f45' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rompe la cadena de la perfección 🛑', body_es = '¿Hoy no ha dormido la siesta y la casa está patas arriba? ¡No pasa nada! Respira hondo, no puedes con todo a la vez. Suéltalo.', title_fr = 'Brisez la chaîne de la perfection 🛑', body_fr = 'Il n''a pas fait la sieste aujourd''hui et la maison est sens dessus dessous ? Ce n''est pas grave ! Respirez profondément, vous ne pouvez pas tout gérer en même temps. Lâchez prise.', title_hi = 'परफ़ेक्शन की ज़ंजीर तोड़िए 🛑', body_hi = 'बच्चा आज दोपहर में नहीं सोया और घर बिखरा पड़ा है? कोई बात नहीं! गहरी साँस लीजिए, आप एक साथ सब कुछ नहीं संभाल सकतीं। जाने दीजिए।', title_id = 'Putuskan rantai kesempurnaan 🛑', body_id = 'Hari ini si kecil tidak tidur siang dan rumah porak-poranda? Tidak apa-apa! Tarik napas dalam-dalam, Anda tidak bisa mengurus semuanya sekaligus. Biarkan saja.', title_ja = '完璧の鎖を断ち切ろう 🛑', body_ja = '今日はお昼寝をしなくて、家もめちゃくちゃ？大丈夫！深呼吸をしましょう。すべてを同時にこなすことはできません。肩の力を抜いて。', title_ko = '완벽함의 사슬을 끊어요 🛑', body_ko = '오늘 아이가 낮잠을 안 자서 집이 엉망인가요? 괜찮아요! 깊게 숨을 쉬세요. 모든 걸 한꺼번에 해낼 수는 없어요. 그냥 내려놓으세요.', title_nl = 'Breek de keten van perfectie 🛑', body_nl = 'Sloeg hij vandaag zijn middagdutje over en is het huis een chaos? Geeft niks! Adem diep in, je kunt niet alles tegelijk regelen. Laat het los.', title_pl = 'Zerwij łańcuch perfekcji 🛑', body_pl = 'Maluch nie poszedł dziś na drzemkę, a w domu pobojowisko? Nic nie szkodzi! Weź głęboki oddech, nie dasz rady ogarnąć wszystkiego naraz. Odpuść.', title_pt = 'Quebre a corrente da perfeição 🛑', body_pt = 'Hoje não fez a sesta e a casa está virada do avesso? Não faz mal! Respire fundo: não consegue controlar tudo ao mesmo tempo. Deixe estar.', title_sv = 'Bryt perfektionens kedja 🛑', body_sv = 'Sov barnet ingen middag i dag och huset är kaos? Det gör inget! Andas djupt, du kan inte hantera allt på en gång. Släpp taget.', title_vi = 'Phá bỏ xiềng xích hoàn hảo 🛑', body_vi = 'Hôm nay bé không ngủ trưa và nhà cửa tan hoang? Không sao cả! Hãy hít thở sâu, mẹ không thể cùng lúc lo hết mọi thứ. Cứ thả lỏng thôi.', title_zh = '打破完美的枷锁 🛑', body_zh = '孩子今天没睡午觉，家里乱成一团？没关系！深呼吸，你不可能同时搞定所有事情。放手吧。' WHERE id = '23204200-aac5-4b32-bb1b-c194a2fa62c8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te agota la paciencia?', body_es = 'Cierra la puerta de la habitación y deja a tu peque a solas con papá. Que esta noche él sea el jefe del parque de juegos de casa.', title_fr = 'Vous êtes à bout de patience ?', body_fr = 'Fermez la porte de la chambre et laissez-le seul avec son papa. Ce soir, c''est lui le chef de l''aire de jeux de la maison.', title_hi = 'सब्र खत्म हो रहा है?', body_hi = 'कमरे का दरवाज़ा बंद कीजिए और बच्चे को उसके पापा के साथ अकेला छोड़ दीजिए। आज शाम घर के प्लेग्राउंड के बॉस वे ही रहें।', title_id = 'Kesabaran mulai menipis?', body_id = 'Tutup pintu kamar dan biarkan si kecil berdua dengan ayahnya. Malam ini, biarkan ia jadi bos taman bermain di rumah.', title_ja = 'もう我慢の限界？', body_ja = '部屋のドアを閉めて、お子さんとパパを2人きりにしましょう。今夜は、おうちの遊び場のリーダーをパパに任せて。', title_ko = '인내심이 바닥났나요?', body_ko = '방문을 닫고 아이를 아빠와 단둘이 있게 해 주세요. 오늘 저녁은 집 안 놀이터의 대장을 아빠에게 맡기세요.', title_nl = 'Raakt je geduld op?', body_nl = 'Doe de deur dicht en laat je kindje alleen met papa. Laat hem vanavond de baas zijn van de speeltuin in huis.', title_pl = 'Kończy ci się cierpliwość?', body_pl = 'Zamknij drzwi do pokoju i zostaw malucha sam na sam z tatą. Niech dziś wieczorem to on rządzi domowym placem zabaw.', title_pt = 'A paciência está a esgotar-se?', body_pt = 'Feche a porta do quarto e deixe-o sozinho com o pai. Esta noite, ele que seja o chefe do parque infantil lá de casa.', title_sv = 'Har tålamodet tagit slut?', body_sv = 'Stäng dörren och lämna barnet ensam med pappa. Låt honom vara chef över hemmets lekpark i kväll.', title_vi = 'Mẹ sắp hết kiên nhẫn?', body_vi = 'Hãy đóng cửa phòng và để bé ở riêng với bố. Tối nay để bố làm "quản lý khu vui chơi" trong nhà nhé.', title_zh = '快没耐心了？', body_zh = '关上房门，让孩子和爸爸单独待一会儿。今晚就让爸爸来当家里游乐场的负责人吧。' WHERE id = 'c615cbe9-985e-4212-bc61-219d1808967f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sientes que las paredes de casa se te echan encima?', body_es = 'Descubre en Lugares para mamás una cafetería con rincón de juegos infantil. Que tu peque juegue y tú disfruta de tu café.', title_fr = 'Les murs de la maison se referment sur vous ?', body_fr = 'Découvrez un café avec coin jeux pour enfants dans les Lieux adaptés aux mamans. Il joue, vous savourez votre café.', title_hi = 'घर की दीवारें आप पर हावी हो रही हैं?', body_hi = 'माँ के लिए अनुकूल जगहें में बच्चों के खेलने के कोने वाला कैफ़े खोजिए। वह खेले, आप कॉफ़ी का मज़ा लीजिए।', title_id = 'Dinding rumah terasa menghimpit?', body_id = 'Temukan kafe dengan sudut bermain anak di Tempat Ramah Ibu. Biarkan ia bermain, Anda nikmati kopi Anda.', title_ja = '家の壁に押しつぶされそう？', body_ja = '「ママにやさしいスポット」でキッズスペースのあるカフェを見つけましょう。お子さんは遊び、あなたはコーヒーを楽しんで。', title_ko = '집 안의 벽이 답답하게 느껴지나요?', body_ko = '엄마 친화 장소에서 키즈 놀이 공간이 있는 카페를 찾아보세요. 아이는 놀고, 엄마는 커피를 즐기세요.', title_nl = 'Komen de muren op je af?', body_nl = 'Ontdek in Mamavriendelijke plekken een café met speelhoek. Laat hem spelen, dan geniet jij van je koffie.', title_pl = 'Ściany w domu cię przytłaczają?', body_pl = 'Odkryj w Miejscach przyjaznych mamom kawiarnię z kącikiem zabaw dla dzieci. Niech on się bawi, a ty delektuj się kawą.', title_pt = 'As paredes de casa caem-lhe em cima?', body_pt = 'Descubra nos Locais Amigos das Mães um café com cantinho de brincar para crianças. Ele brinca e a mãe saboreia o café.', title_sv = 'Känns det som att väggarna hemma kryper inpå dig?', body_sv = 'Upptäck ett kafé med lekhörna i Mammavänliga platser. Låt barnet leka medan du njuter av kaffet.', title_vi = 'Bốn bức tường như đang đè nặng lên mẹ?', body_vi = 'Hãy khám phá một quán cà phê có góc vui chơi trẻ em trong Địa điểm thân thiện với mẹ. Bé chơi, còn mẹ thưởng thức cà phê.', title_zh = '家里的墙让你喘不过气？', body_zh = '在妈妈友好场所里发现一家带儿童游乐角的咖啡馆。宝宝玩，你享受咖啡。' WHERE id = '5d64edd3-2a7c-4881-81d2-2b0ca3685e08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Me visto yo solo 👕', body_es = 'Aunque intente ponerse los pantalones en la cabeza, no frenes sus intentos de vestirse. ¡Sus ganas de independencia están en su mejor momento! Anota esta pequeña victoria en el Seguimiento del desarrollo.', title_fr = 'Je m''habille tout seul 👕', body_fr = 'Même s''il essaie d''enfiler son pantalon sur la tête, ne freinez pas ses essais pour s''habiller. Son envie d''autonomie est au sommet ! Notez cette petite victoire dans le Suivi de développement.', title_hi = 'मैं खुद पहनूँगा 👕', body_hi = 'भले ही वह पैंट सिर पर डालने की कोशिश करे, कपड़े पहनने की उसकी कोशिशों में रुकावट मत डालिए। आत्मनिर्भरता की चाह चरम पर है! ग्रोथ ट्रैकर में इस छोटी सी जीत को दर्ज कीजिए।', title_id = 'Aku pakai baju sendiri 👕', body_id = 'Meski ia mencoba memakai celana di kepalanya, jangan halangi usahanya berpakaian. Keinginannya untuk mandiri sedang di puncak! Catat kemenangan kecil ini di Pelacak Perkembangan.', title_ja = '自分で着る 👕', body_ja = 'ズボンを頭にかぶろうとしても、着替えの挑戦をじゃましないで。自立したい気持ちが最高潮です！この小さな勝利を「発達トラッカー」に記録しましょう。', title_ko = '혼자 입을래요 👕', body_ko = '바지를 머리에 쓰려고 해도 옷 입기 시도를 막지 마세요. 자립하고 싶은 마음이 최고조예요! 성장 기록에 이 작은 승리를 남겨 두세요.', title_nl = 'Ik kleed me zelf aan 👕', body_nl = 'Ook al probeert hij zijn broek over zijn hoofd te trekken, houd zijn aankleedpogingen niet tegen. Zijn drang naar zelfstandigheid is op zijn hoogtepunt! Noteer deze kleine overwinning in de Groeitracker.', title_pl = 'Sam się ubiorę 👕', body_pl = 'Nawet jeśli próbuje włożyć spodnie na głowę, nie przeszkadzaj mu w próbach ubierania się. Potrzeba samodzielności jest u szczytu! Zapisz to małe zwycięstwo w Śledzeniu rozwoju.', title_pt = 'Eu visto-me sozinho 👕', body_pt = 'Mesmo que tente enfiar as calças pela cabeça, não impeça as tentativas de se vestir. A vontade de independência está no auge! Registe esta pequena vitória no Registo de Desenvolvimento.', title_sv = 'Jag klär på mig själv 👕', body_sv = 'Även om barnet försöker dra byxorna över huvudet, hindra inte försöken att klä på sig. Längtan efter självständighet är på topp! Anteckna denna lilla seger i Utvecklingsspåraren.', title_vi = '"Con tự mặc!" 👕', body_vi = 'Dù bé cố chui đầu vào ống quần, đừng ngăn những lần tự mặc đồ của bé. Mong muốn tự lập đang ở đỉnh cao! Hãy ghi chiến thắng nhỏ này vào Theo dõi phát triển.', title_zh = '我要自己穿 👕', body_zh = '哪怕想把裤子套到头上，也别阻止宝宝尝试穿衣服。独立的愿望正处于高峰！把这个小小的胜利记在发育追踪里吧。' WHERE id = '752be34d-ef64-4eb5-9d4c-e6d82cd2a840' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma musical 🎶', body_es = 'La forma más fácil de calmar el llanto de última hora de la tarde es poner su melodía favorita, abrazarle y bailar despacito juntos.', title_fr = 'Sérénité en musique 🎶', body_fr = 'Le plus simple pour apaiser les pleurnicheries de fin de journée : mettez une mélodie qu''il aime, prenez-le dans vos bras et dansez doucement.', title_hi = 'संगीत भरा सुकून 🎶', body_hi = 'शाम को होने वाली चिड़चिड़ाहट को संभालने का सबसे आसान तरीका है उसकी पसंदीदा धुन लगाकर उसे गले लगाकर धीरे-धीरे नाचना।', title_id = 'Damai bersama musik 🎶', body_id = 'Cara termudah meredakan rewel di sore hari adalah memutar melodi favoritnya, memeluknya, lalu berdansa pelan bersamanya.', title_ja = '音楽でほっとひと息 🎶', body_ja = '夕方のぐずりをいちばん簡単に落ち着かせる方法は、好きな曲をかけて、ぎゅっと抱っこしながらゆっくり踊ることです。', title_ko = '음악과 함께 평온하게 🎶', body_ko = '저녁 무렵의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안은 채 천천히 춤추는 거예요.', title_nl = 'Muzikale rust 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsmelodie op, knuffel hem en dans samen langzaam.', title_pl = 'Muzyczny spokój 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną melodię, przytulić go i powoli razem zatańczyć.', title_pt = 'Tranquilidade com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma melodia de que ele goste, abraçá-lo e dançar devagarinho.', title_sv = 'Lugn med musik 🎶', body_sv = 'Det enklaste sättet att lösa gnälligheten framåt kvällen är att sätta på en favoritmelodi, krama barnet och dansa långsamt tillsammans.', title_vi = 'Bình yên cùng âm nhạc 🎶', body_vi = 'Cách dễ nhất để xoa dịu cơn quấy khóc lúc chiều tối là bật giai điệu bé yêu thích, ôm bé vào lòng và nhẹ nhàng nhảy cùng bé.', title_zh = '音乐中的安宁 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝喜欢的曲子，抱着宝宝慢慢跳舞。' WHERE id = '84770b0a-8d36-4d8c-9fce-09146969d787' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La calma de la cueva 🌌', body_es = '¿No se cansa de correr y no quiere irse a la cama? Pon el temporizador de sueño y el rumor del bosque de Ruido blanco, y convierte la habitación en una tranquila cueva del sueño.', title_fr = 'Le calme d''une grotte 🌌', body_fr = 'Jamais fatigué de courir et il refuse d''aller au lit ? Lancez le minuteur de sommeil et mettez le murmure de la forêt des Bruits blancs pour transformer la chambre en douce grotte du sommeil.', title_hi = 'गुफ़ा जैसी शांति 🌌', body_hi = 'भागते-भागते थकता नहीं और सोने नहीं जाता? स्लीप टाइमर चालू कीजिए, व्हाइट नॉइज़ में जंगल की सरसराहट लगाइए और कमरे को नींद की शांत गुफ़ा बना दीजिए।', title_id = 'Hening seperti di gua 🌌', body_id = 'Tak lelah berlari dan tak mau ke tempat tidur? Nyalakan Timer Tidur, putar suara desau hutan dari Suara Putih, dan ubah kamar menjadi gua tidur yang tenang.', title_ja = '洞窟のような静けさ 🌌', body_ja = '走り回っても疲れ知らずで、ベッドに行かない？睡眠タイマーをオンにして、「ホワイトノイズ」の森のざわめきを流し、部屋を静かな眠りの洞窟に変えましょう。', title_ko = '동굴 같은 고요함 🌌', body_ko = '뛰어도 지치지 않고 잠자리에 가지 않나요? 수면 타이머를 켜고 백색소음의 숲 소리를 틀어 방을 조용한 잠의 동굴로 바꿔 주세요.', title_nl = 'De rust van een grot 🌌', body_nl = 'Wordt hij niet moe van het rennen en wil hij niet naar bed? Zet de Slaaptimer aan, kies het ruisen van het bos in Witte ruis en maak van de kamer een rustige slaapgrot.', title_pl = 'Cisza jaskini 🌌', body_pl = 'Nie męczy się bieganiem i nie chce iść do łóżka? Włącz timer snu, puść szum lasu z Białego szumu i zamień pokój w cichą jaskinię snu.', title_pt = 'O silêncio da gruta 🌌', body_pt = 'Não se cansa de correr e não vai para a cama? Ligue o temporizador de sono, ponha o murmúrio da floresta do Ruído Branco e transforme o quarto numa gruta tranquila para dormir.', title_sv = 'Grottans lugn 🌌', body_sv = 'Blir barnet aldrig trött på att springa och vill inte gå och lägga sig? Starta sömntimern, sätt på skogens sus från Vitt brus och gör rummet till en lugn sömngrotta.', title_vi = 'Hang động yên tĩnh 🌌', body_vi = 'Bé chạy mãi không mệt và không chịu lên giường? Hãy bật Bộ hẹn giờ ngủ, mở tiếng rừng rì rào trong Tiếng ồn trắng để biến căn phòng thành một hang ngủ yên tĩnh.', title_zh = '山洞般的宁静 🌌', body_zh = '跑个不停也不累，就是不上床？打开睡眠计时器，播放白噪音里的森林呼啸声，把房间变成一个安静的睡眠小山洞。' WHERE id = '07a0b7ef-0c8f-405e-aede-5d8c497ab1df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de saltar 🦘', body_es = '¿En casa salta encima de los sofás? Busca en Lugares para mamás un centro de ocio con camas elásticas y suelo blando para que gaste su energía con seguridad.', title_fr = 'L''heure de sauter 🦘', body_fr = 'Il saute sur les canapés à la maison ? Trouvez dans les Lieux adaptés aux mamans un centre de loisirs avec trampolines et sol souple pour qu''il se dépense en toute sécurité.', title_hi = 'कूदने का समय 🦘', body_hi = 'घर में सोफ़ों पर कूदता है? माँ के लिए अनुकूल जगहें में ट्रैम्पोलिन और नरम ज़मीन वाला फ़न सेंटर ढूँढिए ताकि वह अपनी ऊर्जा सुरक्षित तरीके से निकाल सके।', title_id = 'Waktunya melompat 🦘', body_id = 'Melompat-lompat di atas sofa di rumah? Temukan pusat hiburan dengan trampolin dan alas lembut di Tempat Ramah Ibu agar ia bisa menyalurkan energinya dengan aman.', title_ja = 'ジャンプの時間 🦘', body_ja = '家でソファの上をぴょんぴょん跳ねていますか？「ママにやさしいスポット」でトランポリンとやわらかい床のある遊び場を見つけて、安全にエネルギーを発散させてあげましょう。', title_ko = '점프할 시간 🦘', body_ko = '집에서 소파 위를 뛰어다니나요? 엄마 친화 장소에서 트램펄린과 푹신한 바닥이 있는 놀이 센터를 찾아 안전하게 에너지를 발산하게 해 주세요.', title_nl = 'Tijd om te springen 🦘', body_nl = 'Springt hij thuis op de banken? Zoek in Mamavriendelijke plekken een speelcentrum met trampolines en een zachte ondergrond, zodat hij zijn energie veilig kwijt kan.', title_pl = 'Czas na skakanie 🦘', body_pl = 'Skacze w domu po kanapach? Znajdź w Miejscach przyjaznych mamom centrum rozrywki z trampolinami i miękką nawierzchnią, gdzie bezpiecznie rozładuje energię.', title_pt = 'Hora de saltar 🦘', body_pt = 'Em casa salta em cima dos sofás? Encontre nos Locais Amigos das Mães um centro de diversões com trampolins e piso macio, para gastar energia em segurança.', title_sv = 'Dags att hoppa 🦘', body_sv = 'Hoppar barnet i soffan hemma? Hitta en lekplats med studsmatta och mjukt underlag i Mammavänliga platser så att energin kommer ut säkert.', title_vi = 'Giờ nhảy nhót 🦘', body_vi = 'Bé nhảy trên sofa trong nhà? Hãy tìm một trung tâm vui chơi có bạt nhún và nền mềm trong Địa điểm thân thiện với mẹ để bé xả năng lượng an toàn.', title_zh = '蹦跳时间 🦘', body_zh = '在家里的沙发上蹦来蹦去？在妈妈友好场所里找一个有蹦床和软地面的游乐中心，让宝宝安全地释放精力。' WHERE id = '9849f311-0e6e-4965-b1a2-164cf002508c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Despertares muy tempranos! 🌅', body_es = '¿Está de pie antes de que salga el sol? Pide ya a nuestro asistente experto Anacan AI secretos prácticos para ajustar su ritmo de sueño.', title_fr = 'Des réveils trop matinaux ! 🌅', body_fr = 'Il est debout avant le lever du soleil ? Demandez tout de suite à notre assistant expert Anacan AI ses secrets pratiques pour régler son rythme de sommeil.', title_hi = 'बहुत जल्दी जागना! 🌅', body_hi = 'सूरज निकलने से पहले ही उठ जाता है? इस नींद की लय को कैसे ठीक करें, यह जानने के लिए तुरंत हमारे Anacan AI एक्सपर्ट असिस्टेंट से काम के राज़ जानिए।', title_id = 'Bangun terlalu pagi! 🌅', body_id = 'Sudah bangun sebelum matahari terbit? Segera dapatkan rahasia praktis dari asisten ahli Anacan AI untuk mengatur ritme tidurnya.', title_ja = '朝起きるのが早すぎる！🌅', body_ja = '日が昇る前から起きていますか？この睡眠リズムを整える方法を学ぶために、すぐにAnacan AIのエキスパートアシスタントから実践的なコツを教えてもらいましょう。', title_ko = '너무 이른 기상! 🌅', body_ko = '해가 뜨기도 전에 일어나나요? 수면 리듬을 조절하는 실용적인 비결을 Anacan AI 전문가 도우미에게 바로 물어보세요.', title_nl = 'Heel vroeg wakker! 🌅', body_nl = 'Is hij al op voor de zon op is? Haal meteen praktische tips bij onze Anacan AI-expert om zijn slaapritme bij te stellen.', title_pl = 'Zbyt wczesne pobudki! 🌅', body_pl = 'Jest na nogach, zanim wzejdzie słońce? Od razu poznaj praktyczne sekrety od naszego eksperta Anacan AI, jak uregulować ten rytm snu.', title_pt = 'Acorda cedo demais! 🌅', body_pt = 'Já está de pé antes de o sol nascer? Peça já ao nosso assistente especialista Anacan AI segredos práticos para ajustar este ritmo de sono.', title_sv = 'Vaknar för tidigt! 🌅', body_sv = 'Är barnet uppe innan solen gått upp? Få praktiska hemligheter från vår expertassistent Anacan AI direkt om hur du justerar sömnrytmen.', title_vi = 'Bé dậy quá sớm! 🌅', body_vi = 'Mặt trời chưa lên mà bé đã dậy? Hãy nhận ngay bí quyết thực tế từ trợ lý chuyên gia Anacan AI để điều chỉnh nhịp ngủ này.', title_zh = '醒得太早了！🌅', body_zh = '太阳还没出来就起床了？马上向我们的Anacan AI专家助手讨教实用秘诀，学习如何调整这种睡眠节律。' WHERE id = 'e6b6723c-fd0e-4884-94df-d412f5e903e7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo palabras nuevas 🗣️', body_es = '¿Qué palabra graciosa se ha inventado hoy? Guarda este gran desarrollo del lenguaje en vídeo con sonido en el Álbum del bebé: dentro de unos años os reiréis muchísimo al verlo.', title_fr = 'Nouveaux mots découverts 🗣️', body_fr = 'Quel mot rigolo a-t-il inventé aujourd''hui ? Gardez ce formidable développement du langage en vidéo avec le son dans l''Album de bébé : dans quelques années, vous en rirez beaucoup.', title_hi = 'नए शब्दों की खोज 🗣️', body_hi = 'आज उसने कौन-सा मज़ेदार शब्द गढ़ा? भाषा के इस शानदार विकास को आवाज़ वाले वीडियो के रूप में बेबी एल्बम में सहेजिए, सालों बाद देखकर आप खूब हँसेंगी।', title_id = 'Menemukan kata baru 🗣️', body_id = 'Kata lucu apa yang ia ciptakan hari ini? Simpan perkembangan bahasa yang luar biasa ini sebagai video bersuara di Album Bayi, bertahun-tahun lagi Anda akan tertawa saat menontonnya.', title_ja = '新しい言葉の発見 🗣️', body_ja = '今日はどんなおもしろい言葉をつくりましたか？このすばらしい言葉の発達を音声付きの動画で「ベビーアルバム」に残しましょう。何年かあとに見返して、きっと大笑いしますよ。', title_ko = '새로운 단어 발견 🗣️', body_ko = '오늘은 어떤 웃긴 단어를 지어냈나요? 이 멋진 언어 발달을 소리가 담긴 영상으로 아기 앨범에 남겨 두세요. 몇 년 뒤에 보면 한참 웃을 거예요.', title_nl = 'Nieuwe woorden ontdekt 🗣️', body_nl = 'Welk grappig woord verzon hij vandaag? Bewaar deze geweldige taalontwikkeling als video met geluid in het Babyalbum, over een paar jaar lach je er hard om.', title_pl = 'Odkrywanie nowych słów 🗣️', body_pl = 'Jakie zabawne słowo wymyślił dziś? Zapisz ten wspaniały rozwój mowy jako film z dźwiękiem w Albumie dziecka, a za kilka lat będziecie się z tego śmiać.', title_pt = 'Descoberta de palavras novas 🗣️', body_pt = 'Que palavra engraçada inventou hoje? Guarde este desenvolvimento fantástico da linguagem em vídeo com som no Álbum do Bebé: daqui a uns anos vão rir-se muito a vê-lo.', title_sv = 'Nya ord upptäckta 🗣️', body_sv = 'Vilket roligt ord hittade barnet på i dag? Spara den fantastiska språkutvecklingen som video med ljud i Babyalbumet, om flera år kommer ni att skratta gott åt den.', title_vi = 'Khám phá từ mới 🗣️', body_vi = 'Hôm nay bé "sáng tác" ra từ ngộ nghĩnh nào? Hãy lưu sự phát triển ngôn ngữ tuyệt vời này bằng video có tiếng trong Album của bé, nhiều năm sau xem lại cả nhà sẽ cười thật nhiều.', title_zh = '发现新词 🗣️', body_zh = '宝宝今天编出了什么搞笑的词？把这次了不起的语言发展录成有声视频存进宝宝相册，多年后再看一定会笑个不停。' WHERE id = '498eede0-22c9-4d0a-b512-067c46777cb9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te entra sueño de pie a mediodía?', body_es = 'Prepara en Recetas saludables un batido de crema de cacahuete que te da fuerza al instante sin necesidad de cafeína.', title_fr = 'Vous somnolez debout à midi ?', body_fr = 'Préparez avec les Recettes saines un smoothie au beurre de cacahuète qui vous redonne de l''énergie en un instant, sans caféine.', title_hi = 'दोपहर में खड़े-खड़े ऊँघ रही हैं?', body_hi = 'सेहतमंद रेसिपी से कैफ़ीन के बिना तुरंत ताकत देने वाली पीनट बटर स्मूदी बनाइए।', title_id = 'Terkantuk-kantuk sambil berdiri di siang hari?', body_id = 'Buat smoothie selai kacang dari Resep Sehat yang langsung memberi tenaga tanpa perlu kafein.', title_ja = 'お昼に立ったままうとうと？', body_ja = '「ヘルシーレシピ」から、カフェインに頼らずすぐに元気が出るピーナッツバタースムージーをつくりましょう。', title_ko = '오후에 선 채로 꾸벅꾸벅 조나요?', body_ko = '건강한 레시피에서 카페인 없이도 바로 힘이 나는 땅콩버터 스무디를 만들어 보세요.', title_nl = 'Dut je ''s middags staand bijna in?', body_nl = 'Maak uit Gezonde recepten een smoothie met pindakaas die je zonder cafeïne meteen kracht geeft.', title_pl = 'Przysypiasz w południe na stojąco?', body_pl = 'Przygotuj ze Zdrowych przepisów smoothie z masłem orzechowym, które od razu doda ci sił bez kofeiny.', title_pt = 'Ao meio-dia está a dormitar de pé?', body_pt = 'Prepare com as Receitas Saudáveis um batido de manteiga de amendoim que dá força na hora, sem precisar de cafeína.', title_sv = 'Nickar du till stående mitt på dagen?', body_sv = 'Gör en smoothie med jordnötssmör som ger kraft direkt utan koffein från Hälsosamma recept.', title_vi = 'Buổi trưa mẹ đứng cũng ngủ gật?', body_vi = 'Hãy làm ly sinh tố bơ đậu phộng tiếp sức tức thì mà không cần caffeine từ Công thức lành mạnh.', title_zh = '中午站着都要打瞌睡？', body_zh = '从健康食谱里做一杯不靠咖啡因、马上补充能量的花生酱奶昔吧。' WHERE id = '710fba45-03e1-4e84-9d81-f9c99d7d2c40' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El espectáculo sin fin en la cama 🛌', body_es = '¿En lugar de dormir, salta en la cama? Sigue el gráfico del temporizador de sueño. Analiza enseguida si no ha gastado toda su energía o si está demasiado cansado.', title_fr = 'Le show sans fin au lit 🛌', body_fr = 'Il saute sur le lit au lieu de dormir ? Suivez le graphique du minuteur de sommeil. Analysez tout de suite s''il ne s''est pas assez dépensé ou s''il est trop fatigué.', title_hi = 'बिस्तर पर कभी न खत्म होने वाला शो 🛌', body_hi = 'सोने के बजाय बिस्तर पर कूदता है? स्लीप टाइमर के चार्ट पर नज़र रखिए। तुरंत समझिए कि उसकी ऊर्जा पूरी नहीं निकली या वह ज़रूरत से ज़्यादा थक गया है।', title_id = 'Pertunjukan tanpa akhir di tempat tidur 🛌', body_id = 'Bukannya tidur, malah melompat-lompat di kasur? Pantau grafik Timer Tidur. Segera analisis apakah energinya belum tersalurkan atau ia justru terlalu lelah.', title_ja = 'ベッドの上のエンドレスショー 🛌', body_ja = '寝る代わりにベッドの上でジャンプしていますか？睡眠タイマーのグラフを見守りましょう。エネルギーを発散しきれていないのか、疲れすぎているのか、すぐに分析しましょう。', title_ko = '침대 위 끝없는 공연 🛌', body_ko = '자는 대신 침대에서 뛰나요? 수면 타이머 그래프를 살펴보세요. 에너지를 다 쓰지 못한 건지, 너무 피곤한 건지 바로 분석해 보세요.', title_nl = 'De eindeloze show in bed 🛌', body_nl = 'Springt hij op bed in plaats van te slapen? Volg de grafiek van de Slaaptimer. Analyseer meteen of hij zijn energie nog niet kwijt is of juist oververmoeid is.', title_pl = 'Niekończący się show w łóżku 🛌', body_pl = 'Zamiast spać, skacze po łóżku? Śledź wykres timera snu. Od razu sprawdź, czy nie rozładował całej energii, czy raczej jest przemęczony.', title_pt = 'O espetáculo sem fim na cama 🛌', body_pt = 'Em vez de dormir, salta na cama? Acompanhe o gráfico do temporizador de sono. Analise já se ainda não gastou toda a energia ou se está cansado demais.', title_sv = 'Showen i sängen som aldrig tar slut 🛌', body_sv = 'Hoppar barnet i sängen i stället för att sova? Följ grafen i sömntimern. Analysera direkt om barnet inte fått ut all energi eller är övertrött.', title_vi = 'Màn trình diễn bất tận trên giường 🛌', body_vi = 'Bé nhảy trên giường thay vì ngủ? Hãy theo dõi biểu đồ của Bộ hẹn giờ ngủ. Phân tích ngay xem bé chưa xả hết năng lượng hay đã quá mệt.', title_zh = '床上停不下来的表演 🛌', body_zh = '不睡觉，在床上蹦来蹦去？看看睡眠计时器的图表。马上分析一下是精力没释放完，还是太累了。' WHERE id = '78d6a4b5-d4db-4754-8341-cf2bcc10342a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y silencio 🍵', body_es = 'El temporizador se ha parado y tu peque duerme. ¡No corras a las tareas de casa! Prepárate una infusión de melisa y disfruta del silencio.', title_fr = 'Thé chaud et silence 🍵', body_fr = 'Le minuteur est arrêté, il dort. Ne vous ruez pas sur les tâches ménagères ! Préparez une tisane de mélisse et savourez simplement le silence.', title_hi = 'गर्म चाय और खामोशी 🍵', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के कामों की ओर मत भागिए! लेमन बाम की चाय बनाइए और बस खामोशी का मज़ा लीजिए।', title_id = 'Teh hangat dan keheningan 🍵', body_id = 'Timer berhenti, si kecil sudah tidur. Jangan buru-buru mengerjakan pekerjaan rumah! Seduh teh lemon balm dan nikmati keheningan.', title_ja = '温かいお茶と静けさ 🍵', body_ja = 'タイマーは止まり、お子さんは眠りました。家事に走らないで！レモンバームティーをいれて、静けさだけを味わいましょう。', title_ko = '따뜻한 차와 고요함 🍵', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일로 달려가지 마세요! 레몬밤 차를 우려 오직 고요함만 즐기세요.', title_nl = 'Warme thee en stilte 🍵', body_nl = 'De timer is gestopt, je kindje slaapt. Ren niet naar het huishouden! Zet citroenmelissethee en geniet gewoon van de stilte.', title_pl = 'Ciepła herbata i cisza 🍵', body_pl = 'Timer zatrzymany, maluch śpi. Nie rzucaj się w wir obowiązków! Zaparz melisę i po prostu delektuj się ciszą.', title_pt = 'Chá quente e silêncio 🍵', body_pt = 'O temporizador parou, ele adormeceu. Não corra para as tarefas da casa! Prepare um chá de erva-cidreira e saboreie apenas o silêncio.', title_sv = 'Varmt te och tystnad 🍵', body_sv = 'Timern har stannat, barnet sover. Rusa inte till hushållssysslorna! Brygg citronmelissate och njut bara av tystnaden.', title_vi = 'Trà nóng và sự yên tĩnh 🍵', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Đừng vội lao vào việc nhà! Hãy pha trà tía tô đất và tận hưởng sự yên tĩnh.', title_zh = '热茶与安静 🍵', body_zh = '计时器停了，孩子睡着了。别急着去做家务！泡一杯香蜂草茶，好好享受这份安静。' WHERE id = '4622294e-c362-48ed-b4bf-63c35923b3ce' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de calcio 🦴', body_es = 'El calcio es imprescindible para dientes y huesos. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de yogur y queso y completa lo que falte.', title_fr = 'Bouclier calcium 🦴', body_fr = 'Le calcium est indispensable aux dents et aux os. Vérifiez avec le Suivi des repas qu''il a eu sa ration de yaourt et de fromage aujourd''hui et comblez les manques.', title_hi = 'कैल्शियम की ढाल 🦴', body_hi = 'दाँतों और हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज दही और पनीर की मात्रा पूरी हुई, और कमी पूरी कीजिए।', title_id = 'Perisai kalsium 🦴', body_id = 'Kalsium wajib untuk gigi dan tulang. Pastikan dengan alat Pemantau Nutrisi bahwa porsi yogurt dan keju hari ini terpenuhi, dan lengkapi kekurangannya.', title_ja = 'カルシウムのシールド 🦴', body_ja = '歯と骨にはカルシウムが欠かせません。「栄養管理ツール」で今日のヨーグルトやチーズの目安量をとれたか確認して、足りない分を補いましょう。', title_ko = '칼슘 방패 🦴', body_ko = '치아와 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 요거트와 치즈 기준량을 채웠는지 확인하고 부족한 만큼 채워 주세요.', title_nl = 'Calciumschild 🦴', body_nl = 'Calcium is onmisbaar voor tanden en botten. Check met de Voedingstracker of hij vandaag genoeg yoghurt en kaas heeft gehad en vul tekorten aan.', title_pl = 'Tarcza z wapnia 🦴', body_pl = 'Wapń jest niezbędny dla zębów i kości. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja jogurtu i sera została osiągnięta, i uzupełnij braki.', title_pt = 'Escudo de cálcio 🦴', body_pt = 'O cálcio é indispensável para os dentes e os ossos. Confirme com o Registo de Alimentação que hoje cumpriu a dose de iogurte e queijo e complete o que faltar.', title_sv = 'Kalciumskölden 🦴', body_sv = 'Kalcium är ett måste för tänder och skelett. Kontrollera med Matningskoll att barnet fått dagens norm av yoghurt och ost och fyll på det som fattas.', title_vi = 'Lá chắn canxi 🦴', body_vi = 'Canxi rất cần cho răng và xương. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức sữa chua, phô mai chưa và bổ sung phần thiếu.', title_zh = '钙的护盾 🦴', body_zh = '钙对牙齿和骨骼必不可少。用喂养记录工具确认今天酸奶、奶酪的参考量是否达到，补上不足的部分。' WHERE id = '53c02e98-c468-40ac-9f02-6cb3c5e5158c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño médico en acción 🩺', body_es = '¿Le pone una inyección a su osito o le escucha la barriga? ¡Los juegos de imaginación están en su mejor momento! Captura ya este dulce momento con la Sesión de fotos del bebé y conviértelo en un recuerdo inolvidable.', title_fr = 'Petit docteur au travail 🩺', body_fr = 'Il fait une piqûre à son nounours ou écoute son ventre ? Les jeux d''imagination sont à leur sommet ! Photographiez tout de suite ce mignon moment avec la Séance photo bébé pour en faire un souvenir inoubliable.', title_hi = 'नन्हा डॉक्टर काम पर 🩺', body_hi = 'अपने भालू को इंजेक्शन लगाता है या उसका पेट सुनता है? कल्पना वाले खेल चरम पर हैं! इस प्यारे पल को तुरंत बेबी फ़ोटोशूट से कैद कीजिए और सबसे यादगार याद बनाइए।', title_id = 'Dokter cilik sedang bertugas 🩺', body_id = 'Menyuntik boneka beruangnya, atau mendengarkan perutnya? Permainan imajinasi sedang di puncaknya! Segera abadikan momen manis ini dengan Sesi Foto Bayi dan jadikan kenangan paling berkesan.', title_ja = '小さなお医者さんが診察中 🩺', body_ja = 'くまさんに注射をしたり、おなかの音を聞いたりしていますか？ごっこ遊びが真っ盛りです！このかわいい瞬間をすぐに「ベビーフォトセッション」で撮って、いちばん心に残る思い出にしましょう。', title_ko = '꼬마 의사 진료 중 🩺', body_ko = '곰 인형에게 주사를 놓거나 배에 귀를 대 보나요? 상상 놀이가 한창이에요! 이 사랑스러운 순간을 바로 아기 사진 촬영으로 찍어 가장 기억에 남는 추억으로 만드세요.', title_nl = 'Kleine dokter aan het werk 🩺', body_nl = 'Geeft hij zijn beer een prik of luistert hij naar zijn buik? Het fantasiespel is op zijn hoogtepunt! Leg dit lieve moment meteen vast met Babyfotoshoot en maak er een onvergetelijke herinnering van.', title_pl = 'Mały lekarz przy pracy 🩺', body_pl = 'Robi misiowi zastrzyk albo osłuchuje mu brzuszek? Zabawy w udawanie są w pełnym rozkwicie! Od razu uwiecznij tę słodką chwilę w Sesji zdjęciowej dziecka jako niezapomnianą pamiątkę.', title_pt = 'Pequeno médico em ação 🩺', body_pt = 'Dá uma injeção ao ursinho ou ouve-lhe a barriga? As brincadeiras de imaginação estão no auge! Fotografe já este momento doce com a Sessão Fotográfica do Bebé e torne-o uma recordação inesquecível.', title_sv = 'Den lilla doktorn i farten 🩺', body_sv = 'Ger barnet nallen en spruta eller lyssnar på magen? Låtsaslekarna är på topp! Fotografera det söta ögonblicket direkt med Babyfotografering och gör det till det mest minnesvärda minnet.', title_vi = 'Bác sĩ nhí đang làm việc 🩺', body_vi = 'Bé tiêm cho gấu bông hay nghe bụng gấu? Trò chơi tưởng tượng đang ở đỉnh cao! Hãy chụp ngay khoảnh khắc đáng yêu này bằng Chụp ảnh cho bé để có kỷ niệm khó quên nhất.', title_zh = '小医生上班啦 🩺', body_zh = '给小熊打针，或者听听它的肚子？想象游戏正处于巅峰！马上用宝宝写真拍下这个可爱的瞬间，留作最难忘的回忆。' WHERE id = 'f10247de-df8b-47ef-a539-e87f8db55ae2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Protege la calma de la habitación con el Medidor de sonido. Un sueño interrumpido por la noche perjudica su desarrollo y tu humor por la mañana.', body_fr = 'Préservez le calme de la chambre avec le Sonomètre. Un sommeil interrompu la nuit nuit à son développement comme à votre humeur du matin.', body_hi = 'साउंड मीटर से कमरे की शांति बनाए रखिए। रात में टूटी नींद उसके विकास और आपके सुबह के मूड, दोनों को बिगाड़ती है।', body_id = 'Jaga ketenangan kamar dengan Pengukur Suara. Tidur malam yang terputus merusak perkembangannya dan suasana hati Anda di pagi hari.', body_ja = '「サウンドメーター」で部屋の静けさを守りましょう。夜に途切れる眠りは、お子さんの発達にも、あなたの朝の気分にも影響します。', body_ko = '소음 측정기로 방의 고요함을 지켜 주세요. 밤에 깨는 잠은 아이의 발달도, 엄마의 아침 기분도 망쳐요.', body_nl = 'Bewaak de rust in de kamer met de Geluidsmeter. Een onderbroken nachtrust is slecht voor zijn ontwikkeling en voor jouw ochtendhumeur.', body_pl = 'Chroń ciszę w pokoju z Miernikiem dźwięku. Przerywany nocny sen szkodzi i jego rozwojowi, i twojemu porannemu nastrojowi.', body_pt = 'Proteja o silêncio do quarto com o Medidor de Som. Um sono interrompido à noite prejudica o desenvolvimento dele e o seu humor de manhã.', body_sv = 'Skydda lugnet i rummet med Ljudmätaren. Avbruten nattsömn förstör både barnets utveckling och ditt morgonhumör.', body_vi = 'Hãy giữ sự yên tĩnh cho căn phòng bằng Đo âm thanh. Giấc ngủ bị gián đoạn ban đêm ảnh hưởng cả sự phát triển của bé lẫn tâm trạng buổi sáng của mẹ.', body_zh = '用分贝仪守护房间的安静吧。夜里睡眠被打断，既影响宝宝的发育，也会破坏你早上的心情。' WHERE id = '1a31af42-99cc-4ebb-8d30-72e007760f62' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Las últimas muelas? 🦷', body_es = '¿Lo muerde todo sin motivo y tiene las manos en la boca? Puede que vengan las muelas del fondo (segundos molares). Revisa sin falta el Seguimiento de dentición.', title_fr = 'Les dernières molaires ? 🦷', body_fr = 'Il mâchouille tout sans raison et a toujours les mains dans la bouche ? Les molaires du fond (deuxièmes molaires) arrivent peut-être. Consultez absolument le Suivi des dents.', title_hi = 'आखिरी दाढ़ें? 🦷', body_hi = 'बिना वजह सब कुछ चबाता है और हाथ मुँह में रहते हैं? सबसे पीछे की दाढ़ें (दूसरी दाढ़ें) आने वाली हो सकती हैं। दाँत निकलने का ट्रैकर ज़रूर देखिए।', title_id = 'Geraham terakhir? 🦷', body_id = 'Menggigit apa saja tanpa sebab dan tangannya selalu di mulut? Geraham paling belakang (geraham kedua) mungkin sedang tumbuh. Pastikan untuk cek Pelacak Tumbuh Gigi.', title_ja = '最後の奥歯？🦷', body_ja = '理由もなくなんでもかじって、手を口に入れていますか？いちばん奥の奥歯（第二乳臼歯）が生えてきているのかもしれません。「歯の生え始めトラッカー」をぜひチェックしましょう。', title_ko = '마지막 어금니? 🦷', body_ko = '이유 없이 뭐든 깨물고 손을 입에 넣나요? 가장 안쪽 어금니(두 번째 어금니)가 나오는 중일 수 있어요. 이앓이 기록을 꼭 확인해 보세요.', title_nl = 'De laatste kiezen? 🦷', body_nl = 'Knaagt hij zonder reden op alles en zitten zijn handjes in zijn mond? De achterste kiezen (tweede kiezen) kunnen eraan komen. Kijk zeker in de Tandjestracker.', title_pl = 'Ostatnie trzonowce? 🦷', body_pl = 'Gryzie wszystko bez powodu i ciągle ma rączki w buzi? Mogą wychodzić ostatnie trzonowce (drugie trzonowce). Koniecznie sprawdź narzędzie do śledzenia ząbkowania.', title_pt = 'Os últimos molares? 🦷', body_pt = 'Rói tudo sem motivo e tem sempre as mãos na boca? Os molares mais de trás (segundos molares) podem estar a caminho. Veja sem falta o Registo de Dentição.', title_sv = 'De sista kindtänderna? 🦷', body_sv = 'Tuggar barnet på allt utan anledning och har händerna i munnen? De bakersta kindtänderna (andra molarerna) kan vara på väg. Titta i Tandspåraren.', title_vi = 'Những chiếc răng hàm cuối cùng? 🦷', body_vi = 'Bé gặm mọi thứ không rõ lý do và cứ đưa tay vào miệng? Có thể những chiếc răng hàm trong cùng (răng hàm thứ hai) đang mọc. Nhất định hãy kiểm tra Theo dõi mọc răng.', title_zh = '最后几颗磨牙？🦷', body_zh = '无缘无故什么都咬，手总放在嘴里？最里面的磨牙（第二乳磨牙）可能正在长。一定要看看出牙记录。' WHERE id = 'bcb1a85f-15a5-4fe9-bbeb-6c1ae564f15a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy tira al suelo la fruta que ayer le encantaba? Ser selectivo con la comida es un clásico de esta edad. Mira en Recetas saludables presentaciones divertidas y diferentes.', body_fr = 'Il jette par terre aujourd''hui le fruit qu''il adorait hier ? La sélectivité alimentaire est un grand classique à cet âge. Découvrez des présentations amusantes et différentes dans les Recettes saines.', body_hi = 'कल जो फल पसंद था, आज ज़मीन पर फेंकता है? खाने में नखरे इस उम्र की आम समस्या है। सेहतमंद रेसिपी में मज़ेदार और अलग तरह से परोसने के तरीके देखिए।', body_id = 'Buah yang kemarin ia sukai hari ini dilempar ke lantai? Pilih-pilih makanan adalah masalah klasik di usia ini. Lihat cara penyajian yang seru dan berbeda di Resep Sehat.', body_ja = '昨日大好きだった果物を、今日は床に投げますか？好き嫌いはこの年齢によくある悩みです。「ヘルシーレシピ」で、楽しくていつもとちがう盛り付けを見てみましょう。', body_ko = '어제 좋아하던 과일을 오늘은 바닥에 던지나요? 편식은 이 시기의 대표적인 고민이에요. 건강한 레시피에서 재미있고 색다른 담음새를 살펴보세요.', body_nl = 'Gooit hij vandaag het fruit op de grond waar hij gisteren dol op was? Kieskeurig eten is een klassiek probleem op deze leeftijd. Bekijk in Gezonde recepten leuke en andere manieren van opdienen.', body_pl = 'Ulubiony wczoraj owoc dziś rzuca na podłogę? Wybredność to klasyczny problem tego wieku. Zajrzyj do Zdrowych przepisów po zabawne i różnorodne sposoby podania.', body_pt = 'Hoje atira ao chão a fruta de que gostava ontem? Ser esquisito com a comida é um clássico desta idade. Veja nas Receitas Saudáveis formas divertidas e diferentes de apresentar a comida.', body_sv = 'Kastar barnet i dag frukten hen älskade i går på golvet? Kräsenhet är ett klassiskt problem i den här åldern. Titta på roliga och annorlunda sätt att servera i Hälsosamma recept.', body_vi = 'Món trái cây hôm qua bé thích, hôm nay lại ném xuống sàn? Kén ăn là chuyện kinh điển ở lứa tuổi này. Hãy xem những cách bày biện vui nhộn, mới lạ trong Công thức lành mạnh.', body_zh = '昨天还爱吃的水果，今天就扔到地上？挑食是这个年龄的经典问题。去健康食谱里看看有趣又不一样的摆盘方式吧。' WHERE id = '753bfaff-7926-4516-b6b5-e78d2b60a270' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los juegos de imaginación se hacen más profundos 🧸', body_es = '¿Da de comer a sus juguetes y los acuesta? ¡Es el punto álgido del desarrollo de la imaginación! Anota estos intentos de empatía en el Seguimiento del desarrollo.', title_fr = 'Les jeux d''imagination s''approfondissent 🧸', body_fr = 'Il fait manger ses jouets et les met au lit ? C''est le sommet du développement de l''imagination ! Notez ces élans d''empathie dans le Suivi de développement.', title_hi = 'कल्पना वाले खेल गहरे हो रहे हैं 🧸', body_hi = 'अपने खिलौनों को खाना खिलाता है, उन्हें सुलाता है? कल्पना का विकास चरम पर है! ग्रोथ ट्रैकर में हमदर्दी की इन कोशिशों को दर्ज कीजिए।', title_id = 'Permainan khayalan makin mendalam 🧸', body_id = 'Ia menyuapi mainannya dan menidurkannya? Ini puncak perkembangan imajinasi! Catat usaha berempatinya di Pelacak Perkembangan.', title_ja = 'ごっこ遊びが深まる 🧸', body_ja = 'おもちゃにごはんを食べさせたり、寝かしつけたりしていますか？想像力の発達がピークを迎えています！この思いやりの挑戦を「発達トラッカー」に記録しましょう。', title_ko = '상상 놀이가 깊어져요 🧸', body_ko = '장난감에게 밥을 먹이고 재우나요? 상상력 발달이 최고조예요! 성장 기록에 이 공감의 시도를 남겨 두세요.', title_nl = 'Fantasiespel wordt dieper 🧸', body_nl = 'Geeft hij zijn knuffels eten en legt hij ze te slapen? Zijn fantasie is op zijn hoogtepunt! Noteer deze pogingen tot empathie in de Groeitracker.', title_pl = 'Zabawy w udawanie się pogłębiają 🧸', body_pl = 'Karmi zabawki i kładzie je spać? To szczyt rozwoju wyobraźni! Zapisz te próby empatii w Śledzeniu rozwoju.', title_pt = 'As brincadeiras de imaginação ficam mais ricas 🧸', body_pt = 'Dá de comer aos brinquedos e põe-nos a dormir? É o auge do desenvolvimento da imaginação! Registe estas tentativas de empatia no Registo de Desenvolvimento.', title_sv = 'Låtsaslekarna fördjupas 🧸', body_sv = 'Matar barnet sina leksaker och lägger dem att sova? Fantasins utveckling är på topp! Anteckna dessa försök till empati i Utvecklingsspåraren.', title_vi = 'Trò chơi tưởng tượng phong phú hơn 🧸', body_vi = 'Bé đút đồ chơi ăn, ru chúng ngủ? Đây là đỉnh cao của sự phát triển trí tưởng tượng! Hãy ghi lại những biểu hiện đồng cảm này vào Theo dõi phát triển.', title_zh = '想象游戏越来越深入 🧸', body_zh = '给玩具喂饭、哄它们睡觉？这是想象力发展的巅峰！把这些共情的尝试记在发育追踪里吧。' WHERE id = '8b287134-38e5-4f28-8d41-3ba7f9bcd5b7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza está en la unión 🥂', body_es = 'Cuando tu peque se duerma, sírvete un té con tu pareja para soltar el estrés del día y reconoceos mutuamente diciendo: «Somos un gran equipo».', title_fr = 'Plus forts ensemble 🥂', body_fr = 'Une fois qu''il dort, évacuez le stress du jour en partageant un thé avec votre conjoint et félicitez-vous en disant « on forme une super équipe ».', title_hi = 'ताकत साथ में है🥂', body_hi = 'बच्चे के सो जाने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ चाय पीजिए और ''हम बढ़िया टीम हैं'' कहकर एक-दूसरे की तारीफ़ कीजिए।', title_id = 'Kekuatan ada pada kebersamaan🥂', body_id = 'Setelah si kecil tidur, lepaskan stres hari ini dengan menuang teh bersama pasangan dan saling menghargai sambil berkata: kita tim yang hebat.', title_ja = '力を合わせて🥂', body_ja = 'お子さんが眠ったら、一日のストレスを手放すために、パートナーとお茶をいれて「わたしたち、最高のチームだね」とお互いをねぎらいましょう。', title_ko = '함께할 때 강해져요 🥂', body_ko = '아이가 잠든 뒤 하루의 스트레스를 풀도록 배우자와 차 한 잔을 나누며 ''우리 정말 좋은 팀이야'' 하고 서로를 칭찬해 주세요.', title_nl = 'Samen sterk 🥂', body_nl = 'Schenk, als je kindje slaapt, een kop thee in met je partner om de stress van de dag los te laten, en waardeer elkaar: we zijn een top team.', title_pl = 'Siła w jedności🥂', body_pl = 'Gdy maluch zaśnie, zrzućcie stres dnia: nalejcie sobie z partnerem herbaty i doceńcie się nawzajem, mówiąc „jesteśmy świetną drużyną”.', title_pt = 'A força está na união 🥂', body_pt = 'Depois de ele adormecer, para largar o stress do dia, sirvam-se de um chá com o seu companheiro e valorizem-se um ao outro dizendo: "Somos uma ótima equipa".', title_sv = 'Styrkan finns i att vara tillsammans🥂', body_sv = 'När barnet somnat, häll upp en kopp te med din partner för att släppa dagens stress och uppskatta varandra med orden ”vi är ett fantastiskt team”.', title_vi = 'Đoàn kết là sức mạnh 🥂', body_vi = 'Sau khi bé ngủ, để xua tan căng thẳng cả ngày, hãy cùng bạn đời rót một tách trà và khen ngợi nhau: "Chúng mình là một đội tuyệt vời".', title_zh = '团结就是力量🥂', body_zh = '孩子睡着后，为了卸下一天的压力，和另一半倒杯茶，说一句“我们是很棒的团队”，互相肯定一下吧。' WHERE id = 'b884ea59-629f-4f5c-a2db-ce8f7aee5def' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos la rutina ⏱️', body_es = '¿Por la noche tardó 40 minutos en dormirse? Mira el gráfico del temporizador de sueño. Quizá sea el momento de acortar la siesta 20 minutos y adelantar la hora de dormir.', title_fr = 'Analysons le rythme ⏱️', body_fr = 'Il a mis 40 minutes à s''endormir ce soir ? Regardez le graphique du minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 20 minutes et avancer le coucher.', title_hi = 'रूटीन का विश्लेषण करें ⏱️', body_hi = 'शाम को सोने में 40 मिनट लग गए? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद 20 मिनट कम करने और शाम की नींद जल्दी करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Butuh 40 menit untuk tertidur malam ini? Lihat grafik Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 20 menit dan memajukan jam tidur malam.', title_ja = '生活リズムを分析しよう ⏱️', body_ja = '夜、寝つくまで40分かかりましたか？睡眠タイマーのグラフを見てみましょう。お昼寝を20分短くして、夜の寝る時間を早めるちょうどいいタイミングかもしれません。', title_ko = '일과를 분석해 봐요 ⏱️', body_ko = '저녁에 잠드는 데 40분이 걸렸나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 20분 줄이고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme analyseren ⏱️', body_nl = 'Duurde het inslapen vanavond 40 minuten? Bekijk de grafiek van de Slaaptimer. Misschien is het precies tijd om het middagdutje met 20 minuten in te korten en de bedtijd te vervroegen.', title_pl = 'Przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorne zasypianie trwało 40 minut? Spójrz na wykres timera snu. Może to dobry moment, by skrócić drzemkę o 20 minut i przesunąć wieczorne spanie wcześniej.', title_pt = 'Vamos analisar a rotina ⏱️', body_pt = 'À noite demorou 40 minutos a adormecer? Veja o gráfico do temporizador de sono. Talvez seja a altura certa de encurtar a sesta 20 minutos e antecipar a hora de deitar.', title_sv = 'Vi analyserar rytmen ⏱️', body_sv = 'Tog det 40 minuter att somna i kväll? Titta på grafen i sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 20 minuter och tidigarelägga kvällen.', title_vi = 'Cùng phân tích nếp sinh hoạt ⏱️', body_vi = 'Tối qua bé mất 40 phút mới ngủ? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 20 phút và cho bé ngủ tối sớm hơn.', title_zh = '来分析一下作息 ⏱️', body_zh = '晚上入睡花了40分钟？看看睡眠计时器的图表。也许正是把白天小睡缩短20分钟、把晚上就寝时间提前的时候了。' WHERE id = '26ecdf90-afa5-4aeb-a939-0e9c19c4397d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Gritos en público 🛒', body_es = '¿Se ha tirado al suelo en el súper porque no le compraste lo que quería? Olvida las miradas y desahógate con Anacan AI para gestionar estas crisis con calma.', title_fr = 'Cris en public 🛒', body_fr = 'Il s''est jeté par terre au supermarché parce qu''il n''a pas eu ce qu''il voulait ? Oubliez les regards et confiez-vous à Anacan AI pour gérer ces crises avec sang-froid.', title_hi = 'सबके सामने चीखें 🛒', body_hi = 'बाज़ार में मनचाही चीज़ न मिलने पर ज़मीन पर लोट गया? आसपास की नज़रों को भूल जाइए और इन नखरों को शांति से संभालने के लिए Anacan AI से बात कीजिए।', title_id = 'Menjerit di tempat umum 🛒', body_id = 'Menjatuhkan diri ke lantai di supermarket karena keinginannya tak dituruti? Lupakan tatapan orang lain dan curhatlah kepada Anacan AI untuk menghadapi tantrum ini dengan tenang.', title_ja = '人前での大泣き 🛒', body_ja = 'お店でほしいものを買ってもらえず、床にひっくり返りましたか？周りの視線は忘れて、こうしたかんしゃくに落ち着いて対応するために、Anacan AIに相談しましょう。', title_ko = '사람들 앞에서 떼쓰기 🛒', body_ko = '마트에서 원하는 걸 못 가졌다고 바닥에 드러누웠나요? 주변 시선은 잊고, 이런 떼쓰기를 침착하게 다루도록 Anacan AI에게 고민을 털어놓으세요.', title_nl = 'Geschreeuw in het openbaar 🛒', body_nl = 'Gooide hij zich in de supermarkt op de grond omdat hij zijn zin niet kreeg? Vergeet de blikken van anderen en praat met Anacan AI om zulke buien kalm aan te pakken.', title_pl = 'Krzyk w miejscu publicznym 🛒', body_pl = 'Rzucił się na podłogę w sklepie, bo nie dostał tego, czego chciał? Zapomnij o spojrzeniach innych i porozmawiaj z Anacan AI, by spokojnie radzić sobie z takimi kryzysami.', title_pt = 'Gritos em público 🛒', body_pt = 'Atirou-se para o chão no supermercado porque não lhe compraram o que queria? Esqueça os olhares à volta e desabafe com o Anacan AI para gerir estas crises com calma.', title_sv = 'Skrik på en offentlig plats 🛒', body_sv = 'Kastade sig barnet på golvet i affären för att hen inte fick det hen ville ha? Glöm omgivningens blickar och prata med Anacan AI om hur du lugnt hanterar sådana utbrott.', title_vi = 'La hét nơi công cộng 🛒', body_vi = 'Bé lăn ra sàn ở siêu thị vì không được mua món mình muốn? Hãy quên ánh nhìn xung quanh và trò chuyện với Anacan AI để bình tĩnh xử lý những cơn khủng hoảng này.', title_zh = '公共场合的尖叫 🛒', body_zh = '在超市因为没买到想要的东西就躺地上打滚？忘掉周围的目光，和Anacan AI聊聊，学习冷静应对这些崩溃。' WHERE id = '4efacff1-8d44-47f9-9c4b-52dbb8de0f37' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No tengas miedo a que se ensucie!', body_es = 'Descubre ya en Productos recomendados lo mejor en arena cinética y juegos sensoriales y pídelo a casa.', title_fr = 'N''ayez pas peur qu''il se salisse !', body_fr = 'Découvrez tout de suite dans les Produits recommandés le meilleur matériel pour le sable cinétique et les jeux sensoriels, et faites-vous livrer à la maison.', title_hi = 'गंदा होने से मत डरिए!', body_hi = 'काइनेटिक सैंड या सेंसरी खेलों के लिए सबसे अच्छी चीज़ें तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए और घर मँगवाइए।', title_id = 'Jangan takut kotor!', body_id = 'Temukan perlengkapan terbaik untuk pasir kinetik dan permainan sensorik di bagian Produk Rekomendasi dan pesan langsung ke rumah.', title_ja = '汚れるのをこわがらないで！', body_ja = 'キネティックサンドや感覚遊びにぴったりのアイテムを、すぐに「おすすめ商品」で見つけて、おうちに届けてもらいましょう。', title_ko = '더러워지는 걸 두려워하지 마세요!', body_ko = '키네틱 샌드와 감각 놀이에 좋은 도구를 추천 제품 섹션에서 바로 찾아 집으로 주문해 보세요.', title_nl = 'Wees niet bang voor vieze handjes!', body_nl = 'Ontdek meteen in Aanbevolen producten de beste spullen voor kinetisch zand of zintuiglijke spelletjes en bestel ze naar huis.', title_pl = 'Nie bój się brudu!', body_pl = 'Od razu odkryj w sekcji Polecane produkty najlepsze akcesoria do piasku kinetycznego i zabaw sensorycznych i zamów je do domu.', title_pt = 'Não tenha medo que se suje!', body_pt = 'Descubra já na secção Produtos Recomendados os melhores materiais de areia cinética e brincadeiras sensoriais e encomende-os para casa.', title_sv = 'Var inte rädd för smuts!', body_sv = 'Upptäck direkt de bästa produkterna för kinetisk sand och sinneslekar i Rekommenderade produkter och beställ hem.', title_vi = 'Đừng sợ bé bị bẩn!', body_vi = 'Hãy khám phá ngay những món đồ tốt nhất về cát động lực học hoặc trò chơi giác quan trong mục Sản phẩm gợi ý và đặt mua về nhà.', title_zh = '别怕弄脏！', body_zh = '马上去推荐商品板块，发现最好的动力沙和感官游戏用品，直接下单送到家。' WHERE id = '6e38a4cd-2c0a-4585-9a87-c6dd4f83a0a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despertares repentinos 🌌', body_es = '¿Se despierta llorando a medianoche y no se calma? Escribe al experto Anacan AI para entender la diferencia entre terror nocturno y pesadilla y saber cómo actuar.', title_fr = 'Réveils soudains 🌌', body_fr = 'Il se réveille en pleurant au milieu de la nuit et ne se calme pas ? Écrivez à l''expert Anacan AI pour comprendre la différence entre terreur nocturne et cauchemar et savoir comment réagir.', title_hi = 'अचानक जागना 🌌', body_hi = 'आधी रात को रोते हुए जागता है और शांत नहीं होता? नाइट टेरर और बुरे सपने का फ़र्क समझने और सही तरीके से संभालने के लिए Anacan AI एक्सपर्ट को लिखिए।', title_id = 'Tiba-tiba terbangun 🌌', body_id = 'Terbangun sambil menangis di tengah malam dan tak bisa ditenangkan? Tulis kepada ahli Anacan AI untuk memahami beda teror malam dan mimpi buruk serta cara menanganinya dengan benar.', title_ja = '急に夜中に起きる 🌌', body_ja = '夜中に泣いて起きて、泣き止まない？夜驚症と悪夢のちがいを知って正しく対応するために、Anacan AIのエキスパートに書き込んでみましょう。', title_ko = '갑자기 깨요 🌌', body_ko = '한밤중에 울며 깨서 진정이 안 되나요? 야경증과 악몽의 차이를 알고 올바르게 대처하도록 Anacan AI 전문가에게 물어보세요.', title_nl = 'Plotseling wakker 🌌', body_nl = 'Wordt hij midden in de nacht huilend wakker en is hij niet te troosten? Schrijf naar de Anacan AI-expert om het verschil tussen nachtangst en een nachtmerrie te begrijpen en goed te reageren.', title_pl = 'Nagłe pobudki 🌌', body_pl = 'Budzi się z płaczem w środku nocy i nie daje się uspokoić? Napisz do eksperta Anacan AI, by zrozumieć różnicę między lękiem nocnym a koszmarem i właściwie zareagować.', title_pt = 'Despertares repentinos 🌌', body_pt = 'Acorda a chorar a meio da noite e não se acalma? Escreva ao especialista Anacan AI para perceber a diferença entre terror noturno e pesadelo e saber como intervir.', title_sv = 'Plötsliga uppvaknanden 🌌', body_sv = 'Vaknar barnet gråtande mitt i natten och går inte att lugna? Skriv till experten Anacan AI för att förstå skillnaden mellan nattskräck och mardrömmar och agera rätt.', title_vi = 'Thức giấc đột ngột 🌌', body_vi = 'Bé khóc thức giấc lúc nửa đêm và không chịu dịu lại? Hãy nhắn cho chuyên gia Anacan AI để hiểu sự khác nhau giữa hoảng sợ ban đêm và ác mộng, từ đó xử lý đúng cách.', title_zh = '突然醒来 🌌', body_zh = '半夜哭着醒来，怎么也安抚不下来？写信给Anacan AI专家，弄清夜惊和噩梦的区别，学会正确应对。' WHERE id = '02f4d85d-ea15-4227-a58f-b7dba39b78d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Se acaba la pelea del cepillo 🪥', body_es = '¿Cierra la boca en cuanto ve el cepillo de dientes? Busca ya en Productos recomendados modelos musicales y ergonómicos que te faciliten la tarea y convierte la rutina en un juego.', title_fr = 'Fin de la bataille de la brosse 🪥', body_fr = 'Il verrouille sa bouche dès qu''il voit la brosse à dents ? Cherchez tout de suite dans les Produits recommandés des modèles musicaux et ergonomiques et transformez ce rituel en jeu.', title_hi = 'ब्रश की लड़ाई खत्म 🪥', body_hi = 'टूथब्रश देखते ही मुँह बंद कर लेता है? इसे आसान बनाने वाले म्यूज़िकल और आरामदायक ब्रश तुरंत सुझाए गए प्रोडक्ट में खोजिए और रूटीन को खेल बना दीजिए।', title_id = 'Perang sikat gigi berakhir 🪥', body_id = 'Langsung mengatupkan mulut begitu melihat sikat gigi? Segera cari model bermusik dan ergonomis yang memudahkan proses ini di Produk Rekomendasi, dan jadikan rutinitas ini permainan.', title_ja = '歯ブラシバトルはおしまい 🪥', body_ja = '歯ブラシを見たとたん、口をぎゅっと閉じますか？この習慣を楽にする、音楽付きで持ちやすい歯ブラシをすぐに「おすすめ商品」で探して、歯みがきを遊びに変えましょう。', title_ko = '양치 전쟁은 이제 끝 🪥', body_ko = '칫솔만 보면 입을 꾹 다무나요? 양치를 쉽게 해 줄 음악이 나오는 인체공학적 칫솔을 추천 제품에서 바로 찾아 습관을 놀이로 바꿔 보세요.', title_nl = 'Einde van de tandenborstelstrijd 🪥', body_nl = 'Klemt hij zijn mond dicht zodra hij de tandenborstel ziet? Zoek meteen in Aanbevolen producten muzikale en ergonomische borstels en maak van de routine een spel.', title_pl = 'Koniec wojny o szczoteczkę 🪥', body_pl = 'Zaciska buzię na widok szczoteczki? Od razu poszukaj w Polecanych produktach grających i ergonomicznych modeli, które to ułatwią, i zamień rutynę w zabawę.', title_pt = 'Acaba a guerra da escova 🪥', body_pt = 'Mal vê a escova de dentes, fecha a boca? Procure já nos Produtos Recomendados modelos musicais e ergonómicos que facilitam a tarefa e transforme a rotina num jogo.', title_sv = 'Kampen om tandborsten tar slut 🪥', body_sv = 'Stänger barnet munnen så fort tandborsten syns? Leta direkt efter tandborstar med musik och ergonomiska modeller som gör det enklare i Rekommenderade produkter och gör rutinen till en lek.', title_vi = 'Kết thúc cuộc chiến bàn chải 🪥', body_vi = 'Vừa thấy bàn chải là bé mím chặt miệng? Hãy tìm ngay những mẫu bàn chải có nhạc, thiết kế tiện dụng trong Sản phẩm gợi ý để biến thói quen này thành trò chơi.', title_zh = '牙刷之战结束啦 🪥', body_zh = '一看到牙刷就紧闭小嘴？马上去推荐商品找找能让刷牙更轻松的音乐款和人体工学款，把日常变成游戏。' WHERE id = '3a940a2c-0062-4cd0-9553-c25d5aadd4ea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Escudo de hierro 🥩', body_es = 'Para que tu peque tan activo no tenga anemia y siga lleno de energía, descubre en Recetas para bebé albóndigas de carne con verduras, ricas y fáciles de masticar, y ábrele el apetito.', title_fr = 'Bouclier de fer 🥩', body_fr = 'Pour que votre petit actif ne manque pas de fer et garde son énergie, découvrez dans les Recettes pour bébés de délicieuses boulettes de viande aux légumes, faciles à mâcher, et ouvrez-lui l''appétit.', title_hi = 'आयरन की ढाल 🥩', body_hi = 'चंचल नन्हे को खून की कमी न हो और वह ऊर्जा से भरा रहे, इसके लिए बच्चों की रेसिपी में आसानी से चबाए जाने वाले, सब्ज़ियों वाले स्वादिष्ट मीट कोफ़्ते खोजिए और उसकी भूख खोलिए।', title_id = 'Perisai zat besi 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia dan tetap berenergi, temukan bola-bola daging sayur yang lezat dan mudah dikunyah di Resep Bayi, dan buka nafsu makannya.', title_ja = '鉄分のシールド 🥩', body_ja = '活発なお子さんが貧血にならず元気でいられるよう、「離乳食を始める赤ちゃんのレシピ」で、かみやすくておいしい野菜入りミートボールを見つけて、食欲を引き出しましょう。', title_ko = '철분 방패 🥩', body_ko = '활발한 아이가 빈혈 없이 활기차게 지내도록 아기 레시피에서 씹기 쉽고 맛있는 채소 고기 완자를 찾아 입맛을 살려 주세요.', title_nl = 'IJzerschild 🥩', body_nl = 'Ontdek in Babyrecepten makkelijk te kauwen, lekkere gehaktballetjes met groenten, zodat je actieve kleintje geen bloedarmoede krijgt, energiek blijft en trek krijgt.', title_pl = 'Tarcza z żelaza 🥩', body_pl = 'Aby aktywny maluch nie miał anemii i był pełen energii, odkryj w Przepisach dla niemowląt łatwe do pogryzienia, pyszne klopsiki mięsne z warzywami i pobudź jego apetyt.', title_pt = 'Escudo de ferro 🥩', body_pt = 'Para que o seu pequenino tão ativo não tenha anemia e continue cheio de energia, descubra nas Receitas para bebés almôndegas de carne com legumes, saborosas e fáceis de mastigar, e abra-lhe o apetite.', title_sv = 'Järnskölden 🥩', body_sv = 'Upptäck goda köttbullar med grönsaker som är lätta att tugga i Recept för bebisar så att din aktiva lilla inte får blodbrist och håller energin uppe, och väck aptiten.', title_vi = 'Lá chắn sắt 🥩', body_vi = 'Để bé hiếu động không bị thiếu máu và luôn tràn đầy năng lượng, hãy khám phá món thịt viên rau củ mềm, dễ nhai và thơm ngon trong Công thức cho bé để bé ăn ngon miệng hơn.', title_zh = '铁的护盾 🥩', body_zh = '为了让活泼的小家伙不贫血、精力充沛，在宝宝食谱里发现好咀嚼又美味的蔬菜肉丸，让宝宝胃口大开。' WHERE id = '78846b79-c47d-4a00-947e-59f644b0393d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ganas de romper las páginas 📖', body_es = '¿En lugar de leer, arranca las páginas del libro? Pregunta ya a Anacan AI cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'L''envie de déchirer les pages 📖', body_fr = 'Il déchire les pages du livre au lieu de lire ? Demandez tout de suite à Anacan AI comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'पन्ने फाड़ने का शौक 📖', body_hi = 'पढ़ने के बजाय किताब के पन्ने फाड़ता है? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह तुरंत Anacan AI से पूछिए।', title_id = 'Hobi merobek halaman 📖', body_id = 'Bukannya membaca, ia malah merobek halaman buku? Segera tanyakan kepada Anacan AI cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = 'ページを破りたい気持ち 📖', body_ja = '読む代わりに絵本のページを破ってしまいますか？読書の習慣を損なわずにこの問題に対応する方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '책장을 찢고 싶어요 📖', body_ko = '읽는 대신 책장을 찢나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Zin om bladzijden te scheuren 📖', body_nl = 'Scheurt hij de bladzijden in plaats van te lezen? Vraag Anacan AI meteen hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Ochota na darcie stron 📖', body_pl = 'Zamiast czytać, drze strony książki? Od razu zapytaj Anacan AI, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'A mania de rasgar páginas 📖', body_pt = 'Em vez de ler, rasga as páginas do livro? Pergunte já ao Anacan AI como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Lust att riva sönder sidorna 📖', body_sv = 'River barnet sönder sidorna i stället för att läsa? Fråga Anacan AI direkt hur du löser problemet utan att skada läsvanan.', title_vi = 'Mê xé trang sách 📖', body_vi = 'Bé xé trang sách thay vì đọc? Hãy hỏi ngay Anacan AI cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '爱撕书页 📖', body_zh = '不是读书，而是把书页撕碎？马上问问Anacan AI，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = '14cb8a25-67e3-4a93-92e7-813bc9ea34c1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La bomba de energía de mamá ⚡', body_es = '¿Se te cierran los ojos de tanto correr? ¡Apuesta por las proteínas, no por los dulces! Recarga tu batería con un batido de crema de cacahuete de Recetas saludables para mujeres que se prepara en 5 minutos.', title_fr = 'La bombe d''énergie de maman ⚡', body_fr = 'Vos yeux se ferment à force de courir ? Misez sur les protéines plutôt que sur le sucre ! Rechargez vos batteries avec un smoothie au beurre de cacahuète prêt en 5 minutes, des Recettes saines pour femmes.', title_hi = 'माँ का एनर्जी बम ⚡', body_hi = 'भागदौड़ से आँखें बंद हो रही हैं? मिठाई नहीं, प्रोटीन चुनिए! महिलाओं के लिए सेहतमंद रेसिपी से 5 मिनट में बनने वाली पीनट बटर स्मूदी से अपनी बैटरी चार्ज कीजिए।', title_id = 'Bom energi Bunda ⚡', body_id = 'Mata terasa berat karena terus berlari? Pilih protein, bukan manisan! Isi ulang baterai Anda dengan smoothie selai kacang yang siap dalam 5 menit dari Resep Sehat untuk wanita.', title_ja = 'ママのエネルギー爆弾 ⚡', body_ja = '走り回って、まぶたが重くなっていますか？甘いものではなく、たんぱく質を！「女性のためのヘルシーレシピ」から、5分でできるピーナッツバタースムージーでバッテリーを充電しましょう。', title_ko = '엄마의 에너지 폭탄 ⚡', body_ko = '뛰어다니느라 눈이 감기나요? 단 음식 말고 단백질을 챙기세요! 여성을 위한 건강한 레시피에서 5분이면 만드는 땅콩버터 스무디로 배터리를 충전하세요.', title_nl = 'Energiebom voor mama ⚡', body_nl = 'Vallen je ogen dicht van het rennen? Kies niet voor snoep, maar voor eiwit! Laad je batterij op met een smoothie met pindakaas uit Gezonde recepten voor vrouwen, klaar in 5 minuten.', title_pl = 'Energetyczna bomba mamy ⚡', body_pl = 'Oczy same ci się zamykają od bieganiny? Zamiast słodyczy postaw na białko! Naładuj baterie smoothie z masłem orzechowym ze Zdrowych przepisów dla kobiet, gotowym w 5 minut.', title_pt = 'A bomba de energia da mãe ⚡', body_pt = 'Os olhos fecham-se de tanto correr? Aposte na proteína, não nos doces! Recarregue as baterias com um batido de manteiga de amendoim das Receitas Saudáveis para Mulheres, pronto em 5 minutos.', title_sv = 'Mammas energibomb ⚡', body_sv = 'Faller ögonen ihop efter allt springande? Satsa på protein, inte godis! Ladda batterierna med en smoothie med jordnötssmör som är klar på 5 minuter från Hälsosamma recept för kvinnor.', title_vi = 'Quả bom năng lượng của mẹ ⚡', body_vi = 'Chạy theo bé đến díp cả mắt? Đừng tìm đến đồ ngọt mà hãy chọn đạm! Hãy sạc pin bằng ly sinh tố bơ đậu phộng làm trong 5 phút từ Công thức lành mạnh cho phụ nữ.', title_zh = '妈妈的能量炸弹 ⚡', body_zh = '跑得眼睛都睁不开了？别找甜食，多补充蛋白质！用女性健康食谱里5分钟就能做好的花生酱奶昔给自己充满电。' WHERE id = '3c1dc66a-c7fe-45c2-99c5-908555ae99a9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le dan miedo las sombras? 🌌', body_es = '¿Al oscurecer la habitación le inquietan las sombras de la pared? La imaginación en desarrollo puede crear miedos. Pon el sonido del vientre materno de Ruido blanco y llena la habitación de seguridad.', title_fr = 'Il a peur des ombres ? 🌌', body_fr = 'Les ombres sur le mur l''inquiètent quand vous faites le noir ? L''imagination qui se développe peut créer des peurs. Lancez le son du ventre maternel des Bruits blancs pour apporter un sentiment de sécurité dans la chambre.', title_hi = 'परछाइयों से डर? 🌌', body_hi = 'कमरे में अँधेरा करते ही दीवार की परछाइयाँ उसे बेचैन करती हैं? कल्पना बढ़ने से डर पैदा हो सकते हैं। व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर कमरे में सुरक्षा का एहसास लाइए।', title_id = 'Takut bayangan? 🌌', body_id = 'Bayangan di dinding membuatnya gelisah saat kamar digelapkan? Imajinasi yang berkembang bisa menimbulkan rasa takut. Putar suara rahim dari Suara Putih dan hadirkan rasa aman di kamar.', title_ja = '影がこわい？🌌', body_ja = '部屋を暗くすると、壁の影が気になりますか？想像力の発達が、こわさを生むことがあります。「ホワイトノイズ」の胎内の音を流して、部屋に安心感を届けましょう。', title_ko = '그림자가 무서워요? 🌌', body_ko = '방을 어둡게 하면 벽의 그림자가 아이를 불안하게 하나요? 상상력이 자라면 두려움도 생길 수 있어요. 백색소음에서 엄마 배 속 소리를 틀어 방에 안정감을 채워 주세요.', title_nl = 'Bang voor schaduwen? 🌌', body_nl = 'Maken de schaduwen op de muur hem onrustig als de kamer donker is? Een groeiende fantasie kan angsten oproepen. Zet het baarmoedergeluid uit Witte ruis aan en breng een veilig gevoel in de kamer.', title_pl = 'Boi się cieni? 🌌', body_pl = 'Gdy zaciemniasz pokój, niepokoją go cienie na ścianie? Rozwój wyobraźni może rodzić lęki. Włącz w Białym szumie odgłosy z brzucha mamy i daj mu poczucie bezpieczeństwa.', title_pt = 'Tem medo das sombras? 🌌', body_pt = 'Quando escurece o quarto, as sombras na parede deixam-no inquieto? O desenvolvimento da imaginação pode criar medos. Ligue no Ruído Branco o som do útero materno e traga segurança ao quarto.', title_sv = 'Rädd för skuggor? 🌌', body_sv = 'Oroas barnet av skuggorna på väggen när du mörklägger rummet? Fantasins utveckling kan skapa rädslor. Sätt på ljudet från livmodern i Vitt brus och skapa en känsla av trygghet i rummet.', title_vi = 'Bé sợ những cái bóng? 🌌', body_vi = 'Khi phòng tối, những cái bóng trên tường khiến bé bất an? Trí tưởng tượng phát triển có thể sinh ra nỗi sợ. Hãy bật âm thanh trong bụng mẹ trong Tiếng ồn trắng để căn phòng thêm an toàn.', title_zh = '怕影子？🌌', body_zh = '关灯后墙上的影子让宝宝不安？想象力发展可能会带来恐惧。打开白噪音里的子宫声，给房间带来安全感。' WHERE id = '83cfece3-b100-41d8-bb8e-0c02263c9e3e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Primer paso hacia el baño? 🧻', body_es = '¿El pañal de la mañana sigue totalmente seco y se siente incómodo? Es una señal estupenda. Anótalo en el Seguimiento de pañales y empieza a leer en el Blog las etapas de preparación para dejar el pañal.', title_fr = 'Premier pas vers les toilettes ? 🧻', body_fr = 'La couche du matin reste toute sèche et elle le gêne ? C''est un super signal. Notez-le dans le Suivi des couches et commencez à lire dans la rubrique Blogs les étapes pour se préparer au pot.', title_hi = 'टॉयलेट की ओर पहला कदम? 🧻', body_hi = 'सुबह का डायपर पूरी तरह सूखा रहता है और वह बेचैन होता है? यह शानदार संकेत है। डायपर ट्रैकर में दर्ज कीजिए और ब्लॉग सेक्शन में पॉटी ट्रेनिंग की तैयारी के चरण पढ़ना शुरू कीजिए।', title_id = 'Langkah pertama ke toilet? 🧻', body_id = 'Popok paginya tetap kering sama sekali dan ia merasa tidak nyaman? Ini sinyal yang luar biasa. Catat di Pelacak Popok dan mulailah membaca tahap persiapan latihan pispot di bagian Blog.', title_ja = 'トイレへの第一歩？🧻', body_ja = '朝のおむつがすっかり乾いていて、おむつを気にしていますか？これはすばらしいサインです。「おむつトラッカー」に記録して、トイレトレーニングの準備の段階について、ブログで読み始めましょう。', title_ko = '배변 훈련의 첫걸음? 🧻', body_ko = '아침 기저귀가 완전히 보송하고 아이가 불편해하나요? 아주 좋은 신호예요. 기저귀 기록에 남기고 블로그에서 배변 훈련 준비 단계를 읽어 보세요.', title_nl = 'Eerste stap naar de wc? 🧻', body_nl = 'Blijft de ochtendluier helemaal droog en voelt hij zich ongemakkelijk? Dat is een geweldig signaal. Noteer het in de Luiertracker en begin in Blogs te lezen over de stappen naar zindelijkheidstraining.', title_pl = 'Pierwszy krok do toalety? 🧻', body_pl = 'Poranna pieluszka jest zupełnie sucha, a on się niepokoi? To wspaniały sygnał. Zapisz to w narzędziu do śledzenia pieluszek i zacznij czytać w sekcji Blog o etapach przygotowania do nauki korzystania z nocnika.', title_pt = 'O primeiro passo para a casa de banho? 🧻', body_pt = 'A fralda da manhã fica completamente seca e ele fica incomodado? É um sinal fantástico. Registe-o no Registo de Fraldas e comece a ler nos Blogues as etapas de preparação para o bacio.', title_sv = 'Första steget mot toaletten? 🧻', body_sv = 'Håller sig morgonblöjan helt torr och barnet är oroligt? Det är en fantastisk signal. Anteckna i Blöjkollen och börja läsa om stegen inför pottträning i Bloggar.', title_vi = 'Bước đầu tiên đến nhà vệ sinh? 🧻', body_vi = 'Tã buổi sáng hoàn toàn khô và bé thấy khó chịu? Đây là một tín hiệu tuyệt vời. Hãy ghi lại trong Theo dõi tã và bắt đầu đọc về các bước chuẩn bị tập ngồi bô trong mục Blog.', title_zh = '迈向厕所的第一步？🧻', body_zh = '早上尿布完全是干的，宝宝还觉得不舒服？这是个很棒的信号。记在尿布记录里，开始去博客板块读读如厕训练的准备阶段吧。' WHERE id = 'a23bc347-ea83-491e-af00-0e80deaecf0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tormenta del «¡No!» 🛑', body_es = '¿Protesta a gritos ante cada propuesta? Pide ya a nuestro experto Anacan AI secretos para mantener la calma en estos momentos difíciles de la crisis de los 2 años y convertir las rabietas en juego.', title_fr = 'Tempête de « Non ! » 🛑', body_fr = 'Il s''oppose en criant à chacune de vos propositions ? Demandez tout de suite à notre expert Anacan AI ses secrets pour garder votre calme et transformer en jeu les crises de ce terrible two.', title_hi = '''नहीं!'' का तूफ़ान 🛑', body_hi = 'आपकी हर बात का चीखकर विरोध करता है? 2 साल के दौर के इन मुश्किल पलों में शांत रहने और नखरों को खेल में बदलने के लिए तुरंत हमारे Anacan AI एक्सपर्ट से राज़ जानिए।', title_id = 'Badai Tidak! 🛑', body_id = 'Menolak setiap tawaran Anda sambil berteriak? Segera dapatkan rahasia dari ahli Anacan AI untuk tetap tenang di masa sulit sindrom usia 2 tahun dan mengubah tantrum menjadi permainan.', title_ja = '「いや！」の嵐 🛑', body_ja = 'あなたの提案すべてに叫んで反対しますか？2歳のイヤイヤ期のこの大変な時期に、落ち着いて対応し、かんしゃくを遊びに変えるコツを、すぐにAnacan AIのエキスパートから教えてもらいましょう。', title_ko = '''싫어!'' 폭풍 🛑', body_ko = '모든 제안에 소리 지르며 반대하나요? 미운 두 살의 힘든 순간에 침착함을 지키고 떼쓰기를 놀이로 바꾸는 비결을 Anacan AI 전문가에게 바로 받아 보세요.', title_nl = 'Een storm van nee! 🛑', body_nl = 'Protesteert hij schreeuwend tegen elk voorstel? Haal meteen tips bij onze Anacan AI-expert om kalm te blijven in deze lastige momenten van de peuterpuberteit en van buien een spel te maken.', title_pl = 'Burza „Nie!” 🛑', body_pl = 'Na każdą twoją propozycję odpowiada krzykiem i sprzeciwem? Od razu poznaj sekrety od naszego eksperta Anacan AI, jak w tych trudnych chwilach buntu dwulatka zachować spokój i zamieniać kryzysy w zabawę.', title_pt = 'Tempestade de "Não!" 🛑', body_pt = 'Contesta aos gritos todas as suas propostas? Peça já ao nosso especialista Anacan AI segredos para manter a calma nestes momentos difíceis da crise dos 2 anos e transformar as crises num jogo.', title_sv = '”Nej!”-storm 🛑', body_sv = 'Protesterar barnet skrikande mot varje förslag? Få hemligheterna från vår expert Anacan AI direkt för att hålla dig lugn i 2-årstrotsets svåra stunder och göra utbrotten till en lek.', title_vi = 'Cơn bão "Không!" 🛑', body_vi = 'Bé la hét phản đối mọi đề nghị của mẹ? Hãy nhận ngay bí quyết từ chuyên gia Anacan AI để giữ bình tĩnh và biến khủng hoảng thành trò chơi trong những lúc khó khăn của tuổi lên 2.', title_zh = '“不！”的风暴 🛑', body_zh = '对你的每个提议都尖叫反对？马上向我们的Anacan AI专家讨教秘诀，在2岁综合征的艰难时刻保持冷静，把崩溃变成游戏。' WHERE id = '46824a50-cc48-4a9c-ad3e-91d5073cd55e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de lógica 🧩', body_es = 'Ya se aburre enseguida de los juguetes sencillos. Descubre en Productos recomendados puzles de madera y juegos geométricos que afinarán su inteligencia y su concentración.', title_fr = 'En quête de logique 🧩', body_fr = 'Il se lasse vite des jouets simples. Découvrez dans les Produits recommandés des puzzles en bois et des jeux géométriques qui affûteront son intelligence et sa concentration.', title_hi = 'तर्क की तलाश 🧩', body_hi = 'वह अब आसान खिलौनों से जल्दी ऊब जाता है। उसकी बुद्धि तेज़ करने वाली और ध्यान बढ़ाने वाली लकड़ी की पज़ल और ज्यामितीय खेल सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Mencari tantangan logika 🧩', body_id = 'Ia sudah cepat bosan dengan mainan sederhana. Temukan puzzle kayu dan permainan geometri yang mengasah kecerdasan dan melatih fokusnya di bagian Produk Rekomendasi.', title_ja = '論理的な思考を育てよう 🧩', body_ja = '簡単なおもちゃには、もうすぐ飽きてしまいます。知性を磨き、集中力を高める木のパズルや図形遊びを、「おすすめ商品」で見つけましょう。', title_ko = '논리를 찾아서 🧩', body_ko = '이제 단순한 장난감에는 금방 싫증을 내요. 두뇌를 키우고 집중력을 높여 줄 원목 퍼즐과 도형 놀이를 추천 제품 섹션에서 찾아보세요.', title_nl = 'Op zoek naar logica 🧩', body_nl = 'Hij verveelt zich al snel met simpel speelgoed. Ontdek in Aanbevolen producten houten puzzels en geometrische spelletjes die zijn verstand scherpen en zijn concentratie versterken.', title_pl = 'W poszukiwaniu logiki 🧩', body_pl = 'Proste zabawki szybko go nudzą. Odkryj w sekcji Polecane produkty drewniane układanki i gry geometryczne, które wyostrzą jego umysł i skupią uwagę.', title_pt = 'Em busca da lógica 🧩', body_pt = 'Já se cansa depressa dos brinquedos simples. Descubra na secção Produtos Recomendados puzzles de madeira e jogos geométricos que aguçam a inteligência e a concentração.', title_sv = 'På jakt efter logik 🧩', body_sv = 'Barnet tröttnar redan snabbt på enkla leksaker. Upptäck träpussel och geometriska lekar som skärper tänkandet och koncentrationen i Rekommenderade produkter.', title_vi = 'Tìm kiếm tư duy 🧩', body_vi = 'Bé đã nhanh chán những món đồ chơi đơn giản. Hãy khám phá các bộ ghép hình gỗ và trò chơi hình học giúp bé thêm nhanh trí và tập trung hơn trong mục Sản phẩm gợi ý.', title_zh = '寻找逻辑游戏 🧩', body_zh = '宝宝很快就玩腻简单的玩具了。在推荐商品板块发现能让宝宝更聪明、更专注的木制拼图和几何游戏。' WHERE id = '51c7f01a-f92a-4f7e-97c1-5893c5304d42' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Carreras sin fin 🏃‍♂️', body_es = '¿En lugar de irse a la cama, salta encima de los sofás? Pon el temporizador de sueño, anota cuánto dura y, según el gráfico, quizá debas adelantar la rutina de la noche.', title_fr = 'La course-poursuite sans fin 🏃‍♂️', body_fr = 'Il saute sur les canapés au lieu d''aller au lit ? Lancez le minuteur de sommeil, notez la durée et, selon le graphique, avancez peut-être le rituel du soir.', title_hi = 'कभी न खत्म होने वाली भागदौड़ 🏃‍♂️', body_hi = 'सोने जाने के बजाय सोफ़ों पर कूदता है? स्लीप टाइमर चालू कीजिए, समय दर्ज कीजिए और चार्ट के आधार पर शायद शाम का रूटीन थोड़ा जल्दी कीजिए।', title_id = 'Kejar-kejaran tanpa akhir 🏃‍♂️', body_id = 'Bukannya ke tempat tidur, malah melompat-lompat di sofa? Nyalakan Timer Tidur, catat durasinya, dan berdasarkan grafiknya mungkin majukan rutinitas malamnya.', title_ja = '終わらない追いかけっこ 🏃‍♂️', body_ja = 'ベッドに行く代わりに、ソファの上でジャンプしていますか？睡眠タイマーをオンにして時間を記録し、グラフをもとに夜の生活リズムを少し早めましょう。', title_ko = '끝없는 술래잡기 🏃‍♂️', body_ko = '잠자리에 드는 대신 소파 위를 뛰어다니나요? 수면 타이머를 켜고 시간을 기록한 뒤, 그래프를 보고 저녁 일과를 앞당겨 보세요.', title_nl = 'Het rennen houdt maar niet op 🏃‍♂️', body_nl = 'Springt hij op de banken in plaats van naar bed te gaan? Zet de Slaaptimer aan, noteer hoe lang het duurt en vervroeg op basis van de grafiek misschien het avondritme.', title_pl = 'Niekończąca się gonitwa 🏃‍♂️', body_pl = 'Zamiast iść do łóżka, skacze po kanapach? Włącz timer snu, zanotuj, ile to trwa, i na podstawie wykresu może przesuń wieczorny rytm wcześniej.', title_pt = 'A correria sem fim 🏃‍♂️', body_pt = 'Em vez de ir para a cama, salta em cima dos sofás? Ligue o temporizador de sono, registe a duração e, com base no gráfico, talvez antecipe a rotina da noite.', title_sv = 'Springet som aldrig tar slut 🏃‍♂️', body_sv = 'Hoppar barnet i soffan i stället för att gå och lägga sig? Starta sömntimern, anteckna hur lång tid det tar och tidigarelägg kanske kvällsrutinen utifrån grafen.', title_vi = 'Chạy nhảy không ngừng 🏃‍♂️', body_vi = 'Bé nhảy trên sofa thay vì lên giường? Hãy bật Bộ hẹn giờ ngủ, ghi lại thời gian và dựa vào biểu đồ, có lẽ nên cho bé đi ngủ sớm hơn.', title_zh = '没完没了的追逐 🏃‍♂️', body_zh = '不上床，却在沙发上蹦来蹦去？打开睡眠计时器，记下过程时长，根据图表也许可以把晚上的作息提前。' WHERE id = 'a1d0bf30-60c8-4128-8527-423ff92dd8f8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Energía en 5 minutos ⚡', body_es = '¿Te entra sueño de pie a mediodía? Prepara en Recetas saludables para mujeres una avena con frutos rojos cargada de antioxidantes que te da fuerza al instante y renueva tu cuerpo.', title_fr = '5 minutes d''énergie ⚡', body_fr = 'Vous somnolez debout à midi ? Préparez avec les Recettes saines pour femmes des flocons d''avoine aux baies, pleins d''antioxydants et énergisants, et ressourcez votre corps.', title_hi = '5 मिनट की ऊर्जा ⚡', body_hi = 'दोपहर में खड़े-खड़े ऊँघ रही हैं? महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाले, एंटीऑक्सीडेंट से भरपूर बेरी वाले ओट्स बनाइए और शरीर को तरोताज़ा कीजिए।', title_id = 'Energi 5 menit ⚡', body_id = 'Terkantuk-kantuk sambil berdiri di siang hari? Segarkan kembali tubuh Anda dengan oat beri kaya antioksidan yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = '5分でエネルギー ⚡', body_ja = 'お昼に立ったままうとうとしていませんか？「女性のためのヘルシーレシピ」から、すぐに元気が出る抗酸化物質たっぷりのベリーのオートミールをつくって、体をリフレッシュさせましょう。', title_ko = '5분 에너지 ⚡', body_ko = '오후에 선 채로 꾸벅꾸벅 조나요? 여성을 위한 건강한 레시피에서 바로 힘이 나는 항산화 가득 베리 오트밀을 만들어 몸에 활력을 채우세요.', title_nl = 'Energie in 5 minuten ⚡', body_nl = 'Dut je ''s middags staand bijna in? Maak uit Gezonde recepten voor vrouwen havermout met bessen vol antioxidanten die je meteen kracht geeft.', title_pl = 'Energia w 5 minut ⚡', body_pl = 'Przysypiasz w południe na stojąco? Przygotuj ze Zdrowych przepisów dla kobiet owsiankę z owocami jagodowymi pełną antyoksydantów, która od razu doda sił, i odnów organizm.', title_pt = 'Energia em 5 minutos ⚡', body_pt = 'Ao meio-dia está a dormitar de pé? Prepare nas Receitas Saudáveis para Mulheres papas de aveia com frutos vermelhos, cheias de antioxidantes, que dão força na hora, e renove o seu corpo.', title_sv = 'Energi på 5 minuter ⚡', body_sv = 'Nickar du till stående mitt på dagen? Gör havregrynsgröt med bär full av antioxidanter som ger kraft direkt från Hälsosamma recept för kvinnor och ge kroppen ny kraft.', title_vi = 'Năng lượng trong 5 phút ⚡', body_vi = 'Buổi trưa mẹ đứng cũng ngủ gật? Hãy làm món yến mạch quả mọng giàu chất chống oxy hóa, tiếp sức tức thì từ Công thức lành mạnh cho phụ nữ để cơ thể được tái tạo.', title_zh = '5分钟能量补给 ⚡', body_zh = '中午站着都要打瞌睡？从女性健康食谱里做一份马上补充能量、富含抗氧化物的莓果燕麦，让身体焕然一新。' WHERE id = 'ce2cdb1e-e1d2-4e44-a336-1708ff489505' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'De las palabras a las frases 🗣️', body_es = '¿Ya empieza a formar frases graciosas de 3-4 palabras? Lee en el Blog los mejores juegos caseros y ejercicios de sílabas para apoyar este gran salto del lenguaje.', title_fr = 'Des mots aux phrases 🗣️', body_fr = 'Il commence à faire de drôles de phrases de 3-4 mots ? Lisez dans la rubrique Blogs les meilleurs jeux à la maison et exercices de syllabes pour soutenir ce formidable bond du langage.', title_hi = 'शब्दों से वाक्यों तक 🗣️', body_hi = 'अब 3-4 शब्दों वाले मज़ेदार वाक्य बनाने लगा है? भाषा की इस शानदार छलांग में मदद करने वाले सबसे अच्छे घरेलू खेल और अक्षरों के अभ्यास ब्लॉग सेक्शन में पढ़िए।', title_id = 'Dari kata ke kalimat 🗣️', body_id = 'Ia sudah mulai menyusun kalimat lucu 3-4 kata? Baca permainan rumahan dan latihan suku kata terbaik yang mendukung lompatan bahasa yang luar biasa ini di bagian Blog.', title_ja = '言葉から文へ 🗣️', body_ja = 'もう3-4語のおもしろい文をつくり始めましたか？このすばらしい言葉の飛躍を応援する、いちばんいいおうち遊びや音節の練習を、ブログで読んでみましょう。', title_ko = '단어에서 문장으로 🗣️', body_ko = '벌써 서너 단어로 된 재미있는 문장을 만들기 시작했나요? 이 멋진 언어 도약을 돕는 최고의 집 놀이와 음절 연습을 블로그에서 읽어 보세요.', title_nl = 'Van woorden naar zinnen 🗣️', body_nl = 'Maakt hij al grappige zinnetjes van 3-4 woorden? Lees in Blogs de beste spelletjes en lettergreepoefeningen die deze geweldige taalsprong steunen.', title_pl = 'Od słów do zdań 🗣️', body_pl = 'Zaczyna już składać zabawne zdania z 3-4 słów? Przeczytaj w sekcji Blog o najlepszych domowych zabawach i ćwiczeniach sylab, które wspierają ten wspaniały skok językowy.', title_pt = 'Das palavras às frases 🗣️', body_pt = 'Já começa a formar frases engraçadas de 3-4 palavras? Leia nos Blogues os melhores jogos caseiros e exercícios de sílabas para apoiar este salto fantástico na linguagem.', title_sv = 'Från ord till meningar 🗣️', body_sv = 'Har barnet börjat bilda roliga meningar med 3-4 ord? Läs om de bästa lekarna hemma och stavelseövningarna som stöttar detta fantastiska språksprång i Bloggar.', title_vi = 'Từ từ ngữ đến câu 🗣️', body_vi = 'Bé đã bắt đầu nói những câu 3-4 từ ngộ nghĩnh? Hãy đọc trong mục Blog những trò chơi tại nhà và bài tập âm tiết tốt nhất để hỗ trợ bước nhảy vọt ngôn ngữ tuyệt vời này.', title_zh = '从词语到句子 🗣️', body_zh = '已经开始说3-4个词的搞笑句子了？去博客板块读读能支持这次了不起的语言飞跃的最佳居家游戏和音节练习。' WHERE id = 'd83ebff1-21e6-4964-94da-2347551c7e01' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Frases graciosas 🗣️', body_es = '¡Esas frases de 3-4 palabras con errores tan dulces valen oro! No te pierdas este gran avance: añádelo ya en vídeo con sonido al Álbum del bebé y guárdalo en la memoria.', title_fr = 'Phrases rigolotes 🗣️', body_fr = 'Ses phrases de 3-4 mots pleines d''adorables erreurs valent de l''or ! Ne manquez pas ce formidable progrès : ajoutez-le tout de suite en vidéo avec le son à l''Album de bébé pour le garder en mémoire.', title_hi = 'मज़ेदार वाक्य 🗣️', body_hi = 'प्यारी गलतियों वाले उसके 3-4 शब्दों के वाक्य अनमोल हैं! इस शानदार विकास को मत चूकिए, तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़कर यादों में सहेजिए।', title_id = 'Kalimat-kalimat lucu 🗣️', body_id = 'Kalimat 3-4 kata yang ia susun dengan kesalahan manis itu sangat berharga! Jangan lewatkan perkembangan luar biasa ini, segera simpan sebagai video bersuara di Album Bayi dan jadikan kenangan.', title_ja = 'おもしろい文 🗣️', body_ja = 'かわいい言いまちがいがいっぱいの3-4語の文は、宝物のように貴重です！このすばらしい成長を見逃さず、すぐに音声付きの動画で「ベビーアルバム」に追加して、記憶に刻みましょう。', title_ko = '웃긴 문장 🗣️', body_ko = '귀여운 실수가 섞인 서너 단어 문장은 정말 소중해요! 이 멋진 발달을 놓치지 말고 바로 소리가 담긴 영상으로 아기 앨범에 올려 추억으로 새기세요.', title_nl = 'Grappige zinnetjes 🗣️', body_nl = 'Die zinnetjes van 3-4 woorden met schattige foutjes zijn goud waard! Mis deze geweldige ontwikkeling niet en zet ze meteen als video met geluid in het Babyalbum.', title_pl = 'Zabawne zdania 🗣️', body_pl = 'Te zdania z 3-4 słów ze słodkimi błędami są na wagę złota! Nie przegap tego wspaniałego rozwoju, od razu dodaj go jako film z dźwiękiem do Albumu dziecka i zachowaj w pamięci.', title_pt = 'Frases engraçadas 🗣️', body_pt = 'Aquelas frases de 3-4 palavras com erros tão doces valem ouro! Não perca este desenvolvimento fantástico: adicione-o já em vídeo com som ao Álbum do Bebé e guarde-o na memória.', title_sv = 'Roliga meningar 🗣️', body_sv = 'De där meningarna med 3-4 ord och söta fel är guld värda! Missa inte denna fantastiska utveckling, lägg direkt till den som video med ljud i Babyalbumet och spara den i minnet.', title_vi = 'Những câu nói ngộ nghĩnh 🗣️', body_vi = 'Những câu 3-4 từ bé nói với lỗi sai đáng yêu quý như vàng! Đừng bỏ lỡ sự phát triển tuyệt vời này, hãy thêm ngay video có tiếng vào Album của bé để lưu giữ mãi.', title_zh = '搞笑的句子 🗣️', body_zh = '那些带着可爱错误的3-4个词的句子珍贵如金！别错过这了不起的成长，马上录成有声视频加进宝宝相册，永远留在回忆里。' WHERE id = '1e0042aa-0b2b-4948-aaf5-3b9cec37c61f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No consigue gastar su energía y lo desordena todo?', body_es = 'Abre el mapa de Lugares para mamás, busca un parque seguro con suelo blando y toboganes, y déjale jugar a su aire.', title_fr = 'Il n''arrive pas à se dépenser et met tout sens dessus dessous ?', body_fr = 'Ouvrez la carte des Lieux adaptés aux mamans, trouvez un parc sûr avec sol souple et toboggan, et laissez-le libre.', title_hi = 'ऊर्जा नहीं निकल पाई और सब कुछ बिखेर रहा है?', body_hi = 'माँ के लिए अनुकूल जगहें का नक्शा खोलिए, नरम ज़मीन और स्लाइड वाला सुरक्षित पार्क ढूँढिए और उसे खुलकर खेलने दीजिए।', title_id = 'Energinya tak tersalurkan sampai mengacak-acak segalanya?', body_id = 'Buka peta Tempat Ramah Ibu, temukan taman aman dengan alas lembut dan perosotan, dan biarkan ia bebas bermain.', title_ja = 'エネルギーを発散しきれず、なんでも散らかしていますか？', body_ja = '「ママにやさしいスポット」のマップを開いて、やわらかい地面とすべり台のある安全な公園を見つけ、思いきり遊ばせてあげましょう。', title_ko = '에너지를 다 쓰지 못해 모든 걸 어지르나요?', body_ko = '엄마 친화 장소 지도를 열어 바닥이 푹신하고 미끄럼틀이 있는 안전한 공원을 찾아 마음껏 뛰놀게 해 주세요.', title_nl = 'Kan hij zijn energie niet kwijt en haalt hij alles overhoop?', body_nl = 'Open de kaart Mamavriendelijke plekken, zoek een veilig park met een zachte ondergrond en glijbaan en laat hem vrij.', title_pl = 'Nie może rozładować energii i wszystko rozrzuca?', body_pl = 'Otwórz mapę Miejsc przyjaznych mamom, znajdź bezpieczny park z miękką nawierzchnią i zjeżdżalnią i pozwól mu się wyszaleć.', title_pt = 'Não consegue gastar energia e desarruma tudo?', body_pt = 'Abra o mapa dos Locais Amigos das Mães, encontre um parque seguro com piso macio e escorrega e deixe-o à vontade.', title_sv = 'Har barnet inte fått ut energin och river ner allt?', body_sv = 'Öppna kartan i Mammavänliga platser, hitta en trygg park med mjukt underlag och rutschkana och låt barnet röra sig fritt.', title_vi = 'Bé không xả được năng lượng nên bày bừa mọi thứ?', body_vi = 'Hãy mở bản đồ Địa điểm thân thiện với mẹ, tìm một công viên an toàn có nền mềm và cầu trượt để bé tự do vui chơi.', title_zh = '精力释放不出来，什么都弄得乱七八糟？', body_zh = '打开妈妈友好场所地图，找一个有软地面和滑梯的安全公园，让宝宝尽情撒欢。' WHERE id = '4d28b1d1-1b59-430b-a6d9-3d3ad8b1e671' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de la reserva de proteínas 🥚', body_es = 'Unos músculos que crecen tan rápido necesitan proteínas. Calcula con el Seguimiento de tomas la ración de hoy (huevo, carne, legumbres) y, si falta algo, ajusta el menú.', title_fr = 'Contrôle des réserves de protéines 🥚', body_fr = 'Les protéines sont indispensables à des muscles qui grandissent vite. Calculez sa ration du jour (œufs, viande, légumineuses) avec le Suivi des repas et ajustez le menu s''il en manque.', title_hi = 'प्रोटीन के भंडार की जाँच 🥚', body_hi = 'तेज़ी से बढ़ती मांसपेशियों के लिए प्रोटीन ज़रूरी है। फ़ीडिंग ट्रैकर से आज की मात्रा (अंडा, मांस, दालें) गिनिए और कमी हो तो मेन्यू ठीक कीजिए।', title_id = 'Cek cadangan protein 🥚', body_id = 'Otot yang tumbuh pesat butuh protein. Hitung kebutuhan hari ini (telur, daging, kacang-kacangan) dengan alat Pemantau Nutrisi dan sesuaikan menunya jika ada kekurangan.', title_ja = 'たんぱく質チェック 🥚', body_ja = 'ぐんぐん育つ筋肉には、たんぱく質が欠かせません。「栄養管理ツール」で今日の目安量（卵、お肉、豆類）を計算して、足りなければメニューを調整しましょう。', title_ko = '단백질 확인 🥚', body_ko = '빠르게 자라는 근육에는 단백질이 꼭 필요해요. 수유 기록 도구로 오늘의 기준량(달걀, 고기, 콩류)을 계산하고 부족하다면 식단을 조절하세요.', title_nl = 'Eiwitvoorraad checken 🥚', body_nl = 'Eiwit is onmisbaar voor snel groeiende spieren. Bereken met de Voedingstracker de norm van vandaag (ei, vlees, peulvruchten) en pas bij een tekort het menu aan.', title_pl = 'Kontrola zapasu białka 🥚', body_pl = 'Białko jest niezbędne dla szybko rosnących mięśni. Oblicz w narzędziu do śledzenia karmienia dzisiejszą normę (jajka, mięso, rośliny strączkowe), a jeśli czegoś brakuje, dopasuj menu.', title_pt = 'Verificar as reservas de proteína 🥚', body_pt = 'Músculos que crescem depressa precisam de proteína. Calcule com o Registo de Alimentação a dose de hoje (ovos, carne, leguminosas) e, se faltar, ajuste a ementa.', title_sv = 'Kontroll av proteinförrådet 🥚', body_sv = 'Muskler som växer snabbt behöver protein. Räkna ut dagens norm (ägg, kött, baljväxter) med Matningskoll och justera menyn om något fattas.', title_vi = 'Kiểm tra kho đạm 🥚', body_vi = 'Cơ bắp phát triển nhanh rất cần đạm. Hãy tính định mức hôm nay (trứng, thịt, các loại đậu) bằng Theo dõi cữ bú và điều chỉnh thực đơn nếu còn thiếu.', title_zh = '蛋白质储备检查 🥚', body_zh = '快速生长的肌肉离不开蛋白质。用喂养记录工具算一算今天的参考量（鸡蛋、肉类、豆类），如有不足就调整菜单。' WHERE id = '031a9c48-32b8-49a9-a9d1-55eb165785a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡El arte de pintar con los dedos! 🎨', body_es = '¿Jugando con colores se ha pintado toda la cara? En lugar de enfadarte, decora ya este momento creativo y divertido con las pegatinas alegres de la Sesión de fotos del bebé y súbelo al álbum.', title_fr = 'L''art de la peinture au doigt ! 🎨', body_fr = 'En jouant avec les couleurs, il s''en est mis plein le visage ? Au lieu de vous énerver, décorez tout de suite ce moment drôle et créatif avec les stickers joyeux de la Séance photo bébé et ajoutez-le à l''album.', title_hi = 'फ़िंगर पेंटिंग की कला! 🎨', body_hi = 'रंगों से खेलते हुए पूरा चेहरा रंग लिया? गुस्सा होने के बजाय इस मज़ेदार, रचनात्मक पल को तुरंत बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में अपलोड कीजिए।', title_id = 'Seni melukis dengan jari! 🎨', body_id = 'Wajahnya penuh cat saat bermain warna? Daripada kesal, segera hiasi momen lucu dan kreatif ini dengan stiker ceria dari Sesi Foto Bayi dan unggah ke album.', title_ja = 'フィンガーペインティング！🎨', body_ja = '色で遊んでいて、顔じゅう絵の具だらけに？怒る代わりに、このおもしろくて創造的な瞬間をすぐに「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムにアップしましょう。', title_ko = '손가락 물감 예술! 🎨', body_ko = '물감 놀이를 하다 얼굴이 온통 물감투성이가 되었나요? 화내는 대신 이 재미있고 창의적인 순간을 바로 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 올려 보세요.', title_nl = 'Kunst met vingerverf! 🎨', body_nl = 'Zit zijn hele gezicht onder de verf na het spelen met kleuren? Word niet boos, maar versier dit grappige, creatieve moment meteen met vrolijke stickers in Babyfotoshoot en zet het in het album.', title_pl = 'Sztuka malowania palcami! 🎨', body_pl = 'Bawiąc się farbami, umazał całą buzię? Zamiast się złościć, od razu ozdób tę zabawną, twórczą chwilę wesołymi naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'A arte da pintura com os dedos! 🎨', body_pt = 'A brincar com as cores, sujou a cara toda? Em vez de se enervar, decore já este momento divertido e criativo com os autocolantes alegres da Sessão Fotográfica do Bebé e carregue-o no álbum.', title_sv = 'Fingermålningskonst! 🎨', body_sv = 'Har barnet kladdat ner hela ansiktet när hen lekte med färger? I stället för att bli irriterad, dekorera det roliga och kreativa ögonblicket direkt med glada klistermärken i Babyfotografering och ladda upp det i albumet.', title_vi = 'Nghệ thuật vẽ bằng ngón tay! 🎨', body_vi = 'Chơi màu mà lem luốc cả mặt mũi? Thay vì bực mình, hãy trang trí ngay khoảnh khắc sáng tạo vui nhộn này bằng sticker trong Chụp ảnh cho bé và tải lên album.', title_zh = '手指画的艺术！🎨', body_zh = '玩颜料时把脸都涂花了？与其生气，不如马上用宝宝写真里欢乐的贴纸装饰这个有趣又有创意的瞬间，上传到相册。' WHERE id = '9a014c54-2569-48f1-8b59-1e18b3b2e5b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelven los despertares nocturnos? ⏱️', body_es = '¿Se despierta llorando a medianoche y le cuesta volver a dormirse? Analiza las estadísticas del temporizador de sueño. ¿Quizá la siesta se alarga demasiado y le estropea la noche?', title_fr = 'Les réveils nocturnes sont de retour ? ⏱️', body_fr = 'Il se réveille en pleurant au milieu de la nuit et a du mal à se rendormir ? Analysez les statistiques du minuteur de sommeil. Sa sieste trop longue perturbe peut-être ses soirées ?', title_hi = 'रात में जागना फिर शुरू? ⏱️', body_hi = 'आधी रात को रोते हुए जागता है और मुश्किल से सोता है? स्लीप टाइमर के आँकड़ों का विश्लेषण कीजिए। कहीं दिन की नींद बहुत लंबी होकर शाम तो नहीं बिगाड़ रही?', title_id = 'Sering terbangun malam lagi? ⏱️', body_id = 'Terbangun sambil menangis di tengah malam dan sulit tidur lagi? Analisis statistik Timer Tidur. Mungkin tidur siangnya terlalu panjang dan mengganggu malamnya?', title_ja = '夜中に起きるのが復活？⏱️', body_ja = '夜中に泣いて起きて、なかなか寝つけない？睡眠タイマーの統計を分析しましょう。お昼寝が長すぎて、夜の眠りを乱しているのかもしれません。', title_ko = '밤에 다시 깨나요? ⏱️', body_ko = '한밤중에 울며 깨서 다시 잠들기 힘들어하나요? 수면 타이머 통계를 분석해 보세요. 낮잠이 너무 길어져 밤잠을 방해하는 건 아닐까요?', title_nl = 'Wordt hij weer ''s nachts wakker? ⏱️', body_nl = 'Wordt hij midden in de nacht huilend wakker en valt hij moeilijk weer in slaap? Analyseer de statistieken van de Slaaptimer. Duurt het middagdutje misschien te lang en verstoort het de avond?', title_pl = 'Nocne pobudki wróciły? ⏱️', body_pl = 'Budzi się z płaczem w środku nocy i trudno mu znów zasnąć? Przeanalizuj statystyki timera snu. Może drzemka jest za długa i psuje wieczór?', title_pt = 'Os despertares noturnos voltaram? ⏱️', body_pt = 'Acorda a chorar a meio da noite e custa-lhe voltar a adormecer? Analise as estatísticas do temporizador de sono. Talvez a sesta esteja demasiado longa e estrague a noite?', title_sv = 'Nattliga uppvaknanden igen? ⏱️', body_sv = 'Vaknar barnet gråtande mitt i natten och har svårt att somna om? Analysera statistiken i sömntimern. Kanske har dagsömnen blivit för lång och stör kvällen?', title_vi = 'Bé lại thức giấc ban đêm? ⏱️', body_vi = 'Bé khóc thức giấc lúc nửa đêm và khó ngủ lại? Hãy phân tích thống kê của Bộ hẹn giờ ngủ. Có lẽ giấc ngủ ngày quá dài làm xáo trộn giấc ngủ tối?', title_zh = '夜醒又回来了？⏱️', body_zh = '半夜哭着醒来，很难再睡着？分析一下睡眠计时器的统计。也许是白天小睡太长，影响了晚上？' WHERE id = '9b9b6d7f-8fb9-448e-ba10-0598457b94a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No solo leer, también contar 📖', body_es = '¿A la hora del cuento te cuenta él lo que ve en los dibujos? Graba con sonido este momento de imaginación tan asombroso.', title_fr = 'Pas lire, raconter 📖', body_fr = 'Pendant le conte du soir, c''est lui qui vous raconte les images ? Enregistrez avec le son ce moment d''imagination étonnant.', title_hi = 'पढ़ना नहीं, बताना 📖', body_hi = 'शाम की कहानी के समय वह आपको तस्वीरों के बारे में बताता है? कल्पना के इस कमाल के पल को आवाज़ के साथ रिकॉर्ड कीजिए।', title_id = 'Bukan membaca, tapi bercerita 📖', body_id = 'Saat dongeng malam, ia yang menceritakan gambar-gambarnya kepada Anda? Rekam suara momen imajinasi yang menakjubkan ini.', title_ja = '読むより、お話しよう 📖', body_ja = '夜の読み聞かせのとき、お子さんが絵について話してくれますか？このすばらしい想像力の瞬間を音声で記録しましょう。', title_ko = '읽기보다 이야기하기 📖', body_ko = '잠자리 동화 시간에 아이가 그림을 설명해 주나요? 이 놀라운 상상의 순간을 소리로 기록해 두세요.', title_nl = 'Niet lezen, maar vertellen 📖', body_nl = 'Vertelt hij jou bij het avondverhaal wat er op de plaatjes staat? Neem dit prachtige fantasiemoment op met geluid.', title_pl = 'Nie czytamy, tylko opowiadamy 📖', body_pl = 'Podczas wieczornej bajki to on opowiada ci o obrazkach? Nagraj tę niesamowitą chwilę wyobraźni z dźwiękiem.', title_pt = 'Não ler, mas conversar 📖', body_pt = 'Na história da noite, é ele que lhe conta o que está nas imagens? Grave em áudio este momento incrível de imaginação.', title_sv = 'Berätta, inte läsa 📖', body_sv = 'Berättar barnet om bilderna för dig vid kvällssagan? Spela in detta fantastiska fantasiögonblick med ljud.', title_vi = 'Không phải đọc, mà là kể 📖', body_vi = 'Giờ kể chuyện buổi tối, bé lại kể cho mẹ nghe về những bức tranh? Hãy ghi âm khoảnh khắc tưởng tượng tuyệt vời này.', title_zh = '不是读，而是讲 📖', body_zh = '晚上讲故事时，宝宝给你讲图画里的内容？把这个令人惊叹的想象时刻录下声音吧。' WHERE id = '87f68482-c94a-42ff-b3af-66083c5353fb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los huesos se fortalecen 🦴', body_es = 'Un desarrollo tan rápido necesita calcio. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de queso y yogur y completa lo que falte.', title_fr = 'Des os plus solides 🦴', body_fr = 'Une croissance rapide demande du calcium. Vérifiez avec le Suivi des repas qu''il a eu sa ration de fromage et de yaourt aujourd''hui et comblez les manques.', title_hi = 'हड्डियाँ मज़बूत हो रही हैं 🦴', body_hi = 'तेज़ विकास के लिए कैल्शियम चाहिए। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज पनीर और दही की मात्रा पूरी हुई, और कमी पूरी कीजिए।', title_id = 'Tulang makin kuat 🦴', body_id = 'Pertumbuhan yang pesat butuh kalsium. Pastikan dengan alat Pemantau Nutrisi bahwa porsi keju dan yogurt hari ini terpenuhi, dan lengkapi kekurangannya.', title_ja = '骨が強くなる 🦴', body_ja = '急速な成長にはカルシウムが必要です。「栄養管理ツール」で今日のチーズやヨーグルトの目安量をとれたか確認して、足りない分を補いましょう。', title_ko = '뼈가 튼튼해져요 🦴', body_ko = '빠른 성장에는 칼슘이 필요해요. 수유 기록 도구로 오늘 치즈와 요거트 기준량을 채웠는지 확인하고 부족한 만큼 채워 주세요.', title_nl = 'Sterkere botten 🦴', body_nl = 'Snelle groei vraagt om calcium. Check met de Voedingstracker of hij vandaag genoeg kaas en yoghurt heeft gehad en vul tekorten aan.', title_pl = 'Kości stają się mocniejsze 🦴', body_pl = 'Szybki rozwój wymaga wapnia. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja sera i jogurtu została osiągnięta, i uzupełnij braki.', title_pt = 'Os ossos ficam mais fortes 🦴', body_pt = 'Um desenvolvimento rápido exige cálcio. Confirme com o Registo de Alimentação que hoje cumpriu a dose de queijo e iogurte e complete o que faltar.', title_sv = 'Skelettet blir starkare 🦴', body_sv = 'Snabb utveckling kräver kalcium. Kontrollera med Matningskoll att barnet fått dagens norm av ost och yoghurt och fyll på det som fattas.', title_vi = 'Xương chắc khỏe hơn 🦴', body_vi = 'Phát triển nhanh cần nhiều canxi. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức phô mai, sữa chua chưa và bổ sung phần thiếu.', title_zh = '骨骼越来越强壮 🦴', body_zh = '快速发育需要钙。用喂养记录工具确认今天奶酪、酸奶的参考量是否达到，补上不足的部分。' WHERE id = '9bde240a-b972-41fa-8294-7b553545ae04' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿No quiere compartir? 🧸', body_es = '¿En el parque corre a por los juguetes de otros niños, pero no deja los suyos? Aprende en el Blog a enseñar a los niños de 2 años a respetar turnos.', title_fr = 'Il ne veut pas partager ? 🧸', body_fr = 'Au parc, il court vers les jouets des autres mais ne prête pas les siens ? Découvrez dans la rubrique Blogs comment apprendre à jouer chacun son tour à 2 ans.', title_hi = 'बाँटना नहीं चाहता? 🧸', body_hi = 'पार्क में दूसरे बच्चों के खिलौनों की ओर भागता है, पर अपना नहीं देता? ब्लॉग सेक्शन में जानिए कि 2 साल के बच्चों को बारी-बारी से खेलना कैसे सिखाएँ।', title_id = 'Tidak mau berbagi? 🧸', body_id = 'Di taman ia berlari ke mainan anak lain, tapi tidak mau meminjamkan miliknya? Pelajari di bagian Blog cara menanamkan konsep bergiliran pada anak usia 2 tahun.', title_ja = '貸したくない？🧸', body_ja = '公園でほかの子のおもちゃに走っていくのに、自分のは貸さない？2歳の子に「順番」を教える方法を、ブログで学びましょう。', title_ko = '나누기 싫어요? 🧸', body_ko = '공원에서 다른 아이의 장난감으로 달려가면서 자기 것은 안 주나요? 블로그에서 두 살 아이에게 차례 지키기를 가르치는 법을 배워 보세요.', title_nl = 'Wil hij niet delen? 🧸', body_nl = 'Rent hij in het park naar het speelgoed van anderen, maar geeft hij het zijne niet? Lees in Blogs hoe je tweejarigen leert om om de beurt te spelen.', title_pl = 'Nie chce się dzielić? 🧸', body_pl = 'W parku biegnie do zabawek innych dzieci, ale swoich nie oddaje? Dowiedz się w sekcji Blog, jak nauczyć 2-latka zabawy po kolei.', title_pt = 'Não quer partilhar? 🧸', body_pt = 'No parque corre para os brinquedos das outras crianças, mas não empresta os seus? Aprenda nos Blogues a ensinar às crianças de 2 anos a ideia de brincar à vez.', title_sv = 'Vill inte dela? 🧸', body_sv = 'Springer barnet fram till andra barns leksaker i parken men ger inte bort sina egna? Lär dig i Bloggar hur du lär 2-åringar att turas om.', title_vi = 'Bé không muốn chia sẻ? 🧸', body_vi = 'Ở công viên bé chạy đến chỗ đồ chơi của bạn nhưng không cho ai đồ của mình? Hãy học trong mục Blog cách dạy trẻ 2 tuổi biết chơi lần lượt.', title_zh = '不愿意分享？🧸', body_zh = '在公园跑去拿别的小朋友的玩具，却不肯给出自己的？去博客板块学习如何教2岁宝宝学会轮流玩。' WHERE id = 'ffa8de8b-2edf-4c8a-82b0-fb8a5415ce7b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos bien la rutina ⏱️', body_es = '¿Por la noche tardó 40 minutos en dormirse? Mira el gráfico del temporizador de sueño. Quizá sea el momento de acortar la siesta 20 minutos y adelantar la hora de dormir.', title_fr = 'Analysons son rythme en détail ⏱️', body_fr = 'Il a mis 40 minutes à s''endormir ce soir ? Regardez le graphique du minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 20 minutes et avancer le coucher.', title_hi = 'रूटीन का पूरा विश्लेषण करें ⏱️', body_hi = 'शाम को सोने में 40 मिनट लग गए? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद 20 मिनट कम करने और शाम की नींद जल्दी करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Butuh 40 menit untuk tertidur malam ini? Lihat grafik Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 20 menit dan memajukan jam tidur malam.', title_ja = '生活リズムをしっかり分析しよう ⏱️', body_ja = '夜、寝つくまで40分かかりましたか？睡眠タイマーのグラフを見てみましょう。お昼寝を20分短くして、夜の寝る時間を早めるちょうどいいタイミングかもしれません。', title_ko = '일과를 제대로 분석해 봐요 ⏱️', body_ko = '저녁에 잠드는 데 40분이 걸렸나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 20분 줄이고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme goed analyseren ⏱️', body_nl = 'Duurde het inslapen vanavond 40 minuten? Bekijk de grafiek van de Slaaptimer. Misschien is het precies tijd om het middagdutje met 20 minuten in te korten en de bedtijd te vervroegen.', title_pl = 'Dokładnie przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorne zasypianie trwało 40 minut? Spójrz na wykres timera snu. Może to dobry moment, by skrócić drzemkę o 20 minut i przesunąć wieczorne spanie wcześniej.', title_pt = 'Vamos analisar a rotina a fundo ⏱️', body_pt = 'À noite demorou 40 minutos a adormecer? Veja o gráfico do temporizador de sono. Talvez seja a altura certa de encurtar a sesta 20 minutos e antecipar a hora de deitar.', title_sv = 'Vi analyserar rytmen ordentligt ⏱️', body_sv = 'Tog det 40 minuter att somna i kväll? Titta på grafen i sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 20 minuter och tidigarelägga kvällen.', title_vi = 'Cùng phân tích toàn bộ nếp sinh hoạt ⏱️', body_vi = 'Tối qua bé mất 40 phút mới ngủ? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 20 phút và cho bé ngủ tối sớm hơn.', title_zh = '来全面分析一下作息 ⏱️', body_zh = '晚上入睡花了40分钟？看看睡眠计时器的图表。也许正是把白天小睡缩短20分钟、把晚上就寝时间提前的时候了。' WHERE id = '0fca32b2-cafe-4f95-9933-261c2771f460' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tu pequeña copia 📸', body_es = '¿Cuando barres, él limpia con un trapo o camina como tú? ¡La imitación está en su mejor momento!', title_fr = 'Votre petite copie 📸', body_fr = 'Quand vous balayez, il essuie avec un chiffon ou marche comme vous ? L''imitation est à son sommet !', title_hi = 'आपकी नन्ही कॉपी 📸', body_hi = 'आप कमरे में झाड़ू लगाती हैं तो वह कपड़े से पोंछता है, या आपकी तरह चलता है? नकल चरम पर है!', title_id = 'Fotokopi kecil Anda 📸', body_id = 'Saat Anda menyapu kamar, ia ikut mengelap dengan kain atau berjalan persis seperti Anda? Masa meniru sedang di puncaknya!', title_ja = 'あなたの小さなコピー 📸', body_ja = 'あなたが部屋を掃くと、お子さんも布で拭いたり、あなたのように歩いたりしていますか？まねっこが最高潮です！', title_ko = '엄마의 작은 복사판 📸', body_ko = '엄마가 방을 쓸 때 아이도 걸레로 닦거나 엄마처럼 걸어 다니나요? 따라 하기가 최고조예요!', title_nl = 'Je kleine kopie 📸', body_nl = 'Veegt hij met een doekje als jij de kamer veegt, of loopt hij net als jij? Het nadoen is op zijn hoogtepunt!', title_pl = 'Twoja mała kopia 📸', body_pl = 'Gdy zamiatasz, on wyciera ściereczką albo chodzi tak jak ty? Naśladowanie jest u szczytu!', title_pt = 'A sua pequena cópia 📸', body_pt = 'Quando varre o quarto, ele limpa com um pano ou anda como a mãe? A imitação está no auge!', title_sv = 'Din lilla kopia 📸', body_sv = 'Torkar barnet med en trasa när du sopar, eller går precis som du? Härmandet är på topp!', title_vi = 'Bản sao nhỏ của mẹ 📸', body_vi = 'Mẹ quét nhà thì bé cầm khăn lau, hay bé đi lại y như mẹ? Khả năng bắt chước đang ở đỉnh cao!', title_zh = '你的小小翻版 📸', body_zh = '你扫地时，宝宝也拿抹布擦，或者学你走路的样子？模仿正处于巅峰！' WHERE id = '63d48088-e9cb-43c1-afc1-9e4bb32ff340' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin azúcar, pero dulce 🍪', body_es = '¡Adiós a las galletas del súper! Descubre en Recetas para bebé dulces sanos caseros de dátiles y manzana que se preparan en 10 minutos y dale una alegría.', title_fr = 'Sans sucre, mais sucré 🍪', body_fr = 'Fini les biscuits du commerce ! Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à la pomme, prêtes en 10 minutes à la maison, et faites-lui plaisir.', title_hi = 'बिना चीनी, फिर भी मीठा 🍪', body_hi = 'बाज़ार के बिस्किट को अलविदा! बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और सेब की सेहतमंद मिठाइयाँ खोजिए और उसे खुश कीजिए।', title_id = 'Tanpa gula, tapi manis 🍪', body_id = 'Selamat tinggal biskuit dari toko! Temukan camilan manis sehat dari kurma dan apel yang siap dalam 10 menit di Resep Bayi dan buat ia senang.', title_ja = '砂糖なしでも甘い 🍪', body_ja = '市販のクッキーとはお別れ！「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとりんごのヘルシーなおやつを見つけて、お子さんを喜ばせましょう。', title_ko = '설탕 없이도 달콤하게 🍪', body_ko = '마트 쿠키는 이제 그만! 아기 레시피에서 집에서 10분이면 만드는 대추야자 사과 건강 간식을 찾아 아이를 기쁘게 해 주세요.', title_nl = 'Zonder suiker, maar zoet 🍪', body_nl = 'Weg met koekjes uit de winkel! Ontdek in Babyrecepten gezonde lekkernijen met dadels en appel, thuis klaar in 10 minuten, en maak hem blij.', title_pl = 'Bez cukru, ale słodko 🍪', body_pl = 'Koniec ze sklepowymi ciastkami! Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i jabłkiem, które zrobisz w domu w 10 minut, i spraw mu radość.', title_pt = 'Sem açúcar, mas doce 🍪', body_pt = 'Adeus bolachas do supermercado! Descubra nas Receitas para bebés doces saudáveis de tâmaras e maçã, feitos em casa em 10 minutos, e faça-o feliz.', title_sv = 'Sockerfritt, men sött 🍪', body_sv = 'Slut på kex från affären! Upptäck nyttiga sötsaker med dadlar och äpple som är klara på 10 minuter hemma i Recept för bebisar och gör barnet glad.', title_vi = 'Không đường mà vẫn ngọt 🍪', body_vi = 'Tạm biệt bánh quy mua sẵn! Hãy khám phá các món ngọt bổ dưỡng từ chà là và táo làm tại nhà trong 10 phút trong Công thức cho bé để bé thêm vui.', title_zh = '无糖，却很甜 🍪', body_zh = '和超市饼干说再见！在宝宝食谱里发现10分钟就能在家做好的椰枣苹果健康甜点，让宝宝开心一下。' WHERE id = '669259fd-a22a-4d24-b932-9eedd58dff3f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Agresividad repentina 🛑', body_es = '¿Cuando se enfada empuja a sus amigos o te levanta la mano? Pregunta ya a Anacan AI cómo reconducir con suavidad las emociones agresivas propias de esta edad.', title_fr = 'Agressivité soudaine 🛑', body_fr = 'Quand il se fâche, il pousse ses copains ou lève la main sur vous ? Demandez tout de suite à Anacan AI comment orienter en douceur les émotions agressives de cet âge.', title_hi = 'अचानक आक्रामकता 🛑', body_hi = 'गुस्से में दोस्तों को धक्का देता है या आप पर हाथ उठाता है? इस उम्र की तेज़ होती भावनाओं को नरमी से सही दिशा कैसे दें, यह तुरंत Anacan AI से पूछिए।', title_id = 'Tiba-tiba agresif 🛑', body_id = 'Mendorong temannya atau mengangkat tangan kepada Anda saat marah? Segera tanyakan kepada Anacan AI cara mengarahkan emosi agresif khas usia ini dengan lembut.', title_ja = '急に乱暴になる 🛑', body_ja = '怒るとお友だちを押したり、あなたに手を上げたりしますか？この年齢の激しくなる気持ちをやさしく導く方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '갑작스러운 공격성 🛑', body_ko = '화가 나면 친구를 밀거나 엄마에게 손을 드나요? 이 나이의 거칠어지는 감정을 부드럽게 이끄는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Plotselinge agressie 🛑', body_nl = 'Duwt hij vriendjes of haalt hij naar jou uit als hij boos is? Vraag Anacan AI meteen hoe je de heftige emoties van deze leeftijd zacht bijstuurt.', title_pl = 'Nagła agresja 🛑', body_pl = 'Gdy się złości, popycha kolegów albo podnosi na ciebie rękę? Od razu zapytaj Anacan AI, jak łagodnie kierować agresywnymi emocjami typowymi dla tego wieku.', title_pt = 'Agressividade repentina 🛑', body_pt = 'Quando se zanga, empurra os amigos ou levanta-lhe a mão? Pergunte já ao Anacan AI como orientar com suavidade estas emoções agressivas típicas da idade.', title_sv = 'Plötslig aggressivitet 🛑', body_sv = 'Knuffar barnet sina kompisar eller lyfter handen mot dig när hen blir arg? Fråga Anacan AI direkt hur du varsamt kan styra den här ålderns allt starkare känslor.', title_vi = 'Hung hăng bất chợt 🛑', body_vi = 'Bé xô bạn hoặc vung tay với mẹ khi tức giận? Hãy hỏi ngay Anacan AI cách nhẹ nhàng định hướng những cảm xúc ngày càng mạnh mẽ của lứa tuổi này.', title_zh = '突然的攻击行为 🛑', body_zh = '一生气就推小朋友或对你动手？马上问问Anacan AI，如何温和地引导这个年龄越来越激烈的情绪。' WHERE id = '14d92f0a-2caa-441a-b66e-e4531b0f2c30' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te duele la espalda? 🧘‍♀️', body_es = '¿Te duele la espalda de coger a un peque de más de 13 kg? Cuídate preparando un té de jengibre antiinflamatorio que relaja los músculos de Recetas saludables.', title_fr = 'Vous avez mal au dos ? 🧘‍♀️', body_fr = 'Votre dos souffre à force de porter un petit de plus de 13 kg ? Prenez soin de vous avec une tisane de gingembre anti-inflammatoire qui détend les muscles, des Recettes saines.', title_hi = 'कमर दर्द है? 🧘‍♀️', body_hi = '13+ kg के नन्हे को उठाते-उठाते कमर दुखती है? सेहतमंद रेसिपी से मांसपेशियों को आराम देने वाली, सूजन कम करने वाली अदरक की चाय बनाइए और अपना ख्याल रखिए।', title_id = 'Punggung Anda sakit? 🧘‍♀️', body_id = 'Punggung nyeri karena menggendong si kecil yang beratnya 13+ kg? Rawat diri Anda dengan menyeduh teh jahe antiradang yang merilekskan otot dari Resep Sehat.', title_ja = '腰が痛い？🧘‍♀️', body_ja = '13kg以上のお子さんを抱き上げて、腰が痛みますか？「ヘルシーレシピ」から、筋肉をほぐし炎症をおさえるしょうが茶をいれて、自分をいたわりましょう。', title_ko = '허리가 아프나요? 🧘‍♀️', body_ko = '13kg이 넘는 아이를 안아 올리느라 허리가 쑤시나요? 건강한 레시피에서 근육을 풀어 주고 염증을 줄이는 생강차를 우려 나를 돌보세요.', title_nl = 'Pijn in je rug? 🧘‍♀️', body_nl = 'Zeurt je rug van het tillen van een kleintje van 13+ kg? Zet ontstekingsremmende gemberthee uit Gezonde recepten die je spieren ontspant, en zorg voor jezelf.', title_pl = 'Bolą cię plecy? 🧘‍♀️', body_pl = 'Plecy bolą cię od podnoszenia malucha ważącego ponad 13 kg? Zadbaj o siebie i zaparz ze Zdrowych przepisów przeciwzapalną herbatę imbirową, która rozluźnia mięśnie.', title_pt = 'Dores nas costas? 🧘‍♀️', body_pt = 'As costas doem-lhe de tanto pegar num pequenino de mais de 13 kg? Cuide de si com um chá de gengibre das Receitas Saudáveis, anti-inflamatório e que relaxa os músculos.', title_sv = 'Ont i ryggen? 🧘‍♀️', body_sv = 'Värker ryggen av att lyfta en liten på över 13 kg? Brygg ett antiinflammatoriskt ingefärste som får musklerna att slappna av från Hälsosamma recept och ta hand om dig själv.', title_vi = 'Mẹ bị đau lưng? 🧘‍♀️', body_vi = 'Bế bé hơn 13 kg khiến lưng mẹ ê ẩm? Hãy pha trà gừng chống viêm, giúp thư giãn cơ từ Công thức lành mạnh và chăm sóc bản thân nhé.', title_zh = '腰疼吗？🧘‍♀️', body_zh = '抱13+ kg的小家伙抱得腰酸？从健康食谱里泡一杯放松肌肉、抗炎的姜茶，照顾好自己。' WHERE id = 'a1ab1785-3fde-4782-bfe0-d24e5fc6ec72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿El silencio le asusta?', body_es = 'Pon en la habitación el sonido del ventilador o del secador de Ruido blanco y verás qué sensación de seguridad tan perfecta crea para dormir.', title_fr = 'Le silence lui fait peur ?', body_fr = 'Lancez dans la chambre le bruit de ventilateur ou de sèche-cheveux des Bruits blancs et voyez comme il crée un sentiment de sécurité parfait pour dormir.', title_hi = 'खामोशी उसे डराती है?', body_hi = 'कमरे में व्हाइट नॉइज़ से पंखे या हेयर ड्रायर की आवाज़ चलाइए और देखिए कि यह नींद के माहौल में कितना पूरा सुरक्षा का एहसास देती है।', title_id = 'Keheningan membuatnya takut?', body_id = 'Putar suara kipas angin atau pengering rambut dari Suara Putih di kamar dan lihat bagaimana suara itu menciptakan rasa aman yang sempurna saat tidur.', title_ja = '静けさがこわい？', body_ja = '部屋で「ホワイトノイズ」の扇風機やドライヤーの音を流して、眠りの環境にどれほど完璧な安心感が生まれるか確かめてみましょう。', title_ko = '조용하면 무서워하나요?', body_ko = '백색소음에서 선풍기나 헤어드라이어 소리를 틀어 수면 환경에 얼마나 완벽한 안정감을 주는지 확인해 보세요.', title_nl = 'Maakt stilte hem bang?', body_nl = 'Zet in de kamer het geluid van een ventilator of föhn uit Witte ruis aan en zie hoe het in zijn slaapomgeving een perfect veilig gevoel geeft.', title_pl = 'Cisza go przeraża?', body_pl = 'Włącz w pokoju odgłos wentylatora lub suszarki z Białego szumu i zobacz, jak daje mu doskonałe poczucie bezpieczeństwa podczas snu.', title_pt = 'O silêncio assusta-o?', body_pt = 'Ligue no quarto o som da ventoinha ou do secador de cabelo do Ruído Branco e veja como cria uma sensação perfeita de segurança no ambiente de sono.', title_sv = 'Skrämmer tystnaden barnet?', body_sv = 'Sätt på fläkt- eller hårtorksljud från Vitt brus i rummet och se hur det skapar en perfekt känsla av trygghet i sömnmiljön.', title_vi = 'Sự im lặng khiến bé sợ?', body_vi = 'Hãy bật tiếng quạt hoặc máy sấy tóc trong Tiếng ồn trắng và xem âm thanh này tạo cảm giác an toàn hoàn hảo cho giấc ngủ thế nào.', title_zh = '安静会让宝宝害怕？', body_zh = '在房间里打开白噪音里的风扇或吹风机声，看看它如何在睡眠环境中带来完美的安全感。' WHERE id = 'e3fde63e-bd7b-46c0-8b54-9e79a9f6fb65' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Niebla mental 🌫️', body_es = '¿Estás muy cansada y se te olvida todo? Prepara en Recetas saludables para mujeres un tentempié de nueces rico en omega-3 y vacía tu mente en el Diario de ánimo.', title_fr = 'Brouillard mental 🌫️', body_fr = 'Très fatiguée et vous oubliez tout ? Préparez un en-cas aux noix riche en oméga-3 avec les Recettes saines pour femmes, puis videz-vous la tête dans le Journal d''humeur.', title_hi = 'दिमागी धुंध 🌫️', body_hi = 'बहुत थक गई हैं और सब कुछ भूल जाती हैं? महिलाओं के लिए सेहतमंद रेसिपी से ओमेगा-3 से भरपूर अखरोट वाला स्नैक बनाइए और मूड डायरी में मन खाली कीजिए।', title_id = 'Kabut otak 🌫️', body_id = 'Sangat lelah dan sering lupa? Buat camilan kenari kaya omega-3 dari Resep Sehat untuk wanita, lalu kosongkan pikiran Anda di Buku Harian Suasana Hati.', title_ja = '頭がぼんやり 🌫️', body_ja = 'とても疲れて、なんでも忘れてしまいますか？「女性のためのヘルシーレシピ」から、オメガ3たっぷりのくるみのおやつをつくって、「気分日記」に頭の中を書き出しましょう。', title_ko = '머릿속이 뿌예요 🌫️', body_ko = '너무 지쳐서 자꾸 잊어버리나요? 여성을 위한 건강한 레시피에서 오메가3가 풍부한 호두 간식을 만들고, 기분 일기에 생각을 털어놓으세요.', title_nl = 'Hersenmist 🌫️', body_nl = 'Ben je erg moe en vergeet je alles? Maak uit Gezonde recepten voor vrouwen een tussendoortje met walnoten, rijk aan omega-3, en maak je hoofd leeg in je Stemmingsdagboek.', title_pl = 'Mgła mózgowa 🌫️', body_pl = 'Jesteś bardzo zmęczona i wszystko zapominasz? Przygotuj ze Zdrowych przepisów dla kobiet przekąskę z orzechami włoskimi bogatą w omega-3 i oczyść głowę w Dzienniku nastroju.', title_pt = 'Nevoeiro mental 🌫️', body_pt = 'Está muito cansada e esquece-se de tudo? Prepare nas Receitas Saudáveis para Mulheres um lanche de nozes rico em ómega-3 e esvazie a cabeça no Diário de Humor.', title_sv = 'Hjärndimma 🌫️', body_sv = 'Är du väldigt trött och glömmer allt? Gör ett mellanmål med valnötter rikt på omega-3 från Hälsosamma recept för kvinnor och rensa tankarna i Humördagboken.', title_vi = 'Đầu óc mơ hồ 🌫️', body_vi = 'Mẹ quá mệt và hay quên? Hãy làm món ăn vặt từ óc chó giàu omega-3 trong Công thức lành mạnh cho phụ nữ và trút bỏ mọi suy nghĩ vào Nhật ký tâm trạng.', title_zh = '脑袋一团雾 🌫️', body_zh = '累坏了，什么都忘？从女性健康食谱里做一份富含欧米伽-3的核桃小零食，再在心情日记里清空大脑。' WHERE id = '7ac3c96c-42b7-4566-aa71-c52f9eb0b4eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Rechaza el orinal? 🚽', body_es = '¿No quiere ir al baño y llora? Pregunta ya a nuestro asistente experto Anacan AI si conviene hacer una pausa o probar otro método.', title_fr = 'Il refuse le pot ? 🚽', body_fr = 'Il ne veut pas aller aux toilettes et pleure ? Demandez tout de suite à notre assistant expert Anacan AI s''il faut faire une pause dans l''apprentissage ou essayer une autre méthode.', title_hi = 'पॉटी से इनकार? 🚽', body_hi = 'टॉयलेट जाना नहीं चाहता और रोता है? ट्रेनिंग में ब्रेक लेना है या कोई दूसरा तरीका आज़माना है, यह तुरंत हमारे Anacan AI एक्सपर्ट असिस्टेंट से पूछिए।', title_id = 'Menolak pispot? 🚽', body_id = 'Tidak mau ke toilet dan menangis? Segera tanyakan kepada asisten ahli Anacan AI apakah latihan perlu dijeda atau dicoba dengan metode lain.', title_ja = 'おまるを嫌がる？🚽', body_ja = 'トイレに行きたがらず、泣きますか？トレーニングをお休みするべきか、ちがう方法を試すべきか、すぐにAnacan AIのエキスパートアシスタントに聞いてみましょう。', title_ko = '변기를 거부하나요? 🚽', body_ko = '화장실에 가기 싫다며 우나요? 훈련을 잠시 쉬어야 할지, 다른 방법을 시도해야 할지 Anacan AI 전문가 도우미에게 바로 물어보세요.', title_nl = 'Verzet tegen het potje? 🚽', body_nl = 'Wil hij niet naar de wc en huilt hij? Vraag onze Anacan AI-expert meteen of je de training even moet pauzeren of een andere methode moet proberen.', title_pl = 'Sprzeciw wobec nocnika? 🚽', body_pl = 'Nie chce iść do toalety i płacze? Od razu zapytaj naszego eksperta Anacan AI, czy zrobić przerwę w nauce, czy spróbować innej metody.', title_pt = 'Recusa o bacio? 🚽', body_pt = 'Não quer ir à casa de banho e chora? Pergunte já ao nosso assistente especialista Anacan AI se deve fazer uma pausa no treino ou experimentar outro método.', title_sv = 'Protesterar mot pottan? 🚽', body_sv = 'Vill barnet inte gå på toaletten och gråter? Fråga vår expertassistent Anacan AI direkt om ni behöver pausa träningen eller prova en annan metod.', title_vi = 'Bé phản đối ngồi bô? 🚽', body_vi = 'Bé không muốn đi vệ sinh và khóc? Hãy hỏi ngay trợ lý chuyên gia Anacan AI xem nên tạm dừng việc tập hay thử một phương pháp khác.', title_zh = '抗拒便盆？🚽', body_zh = '不想上厕所，还哭？马上问问我们的Anacan AI专家助手，是该暂停训练，还是换一种方法试试。' WHERE id = '8144388a-1733-475c-83c3-62e4fa74eb05' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Solo come fruta? 🍎', body_es = '¿Rechaza las proteínas o las verduras? Calcula con el Seguimiento de tomas cuántos alimentos saludables ha tomado hoy y crea combinaciones ricas, como yogur con fruta.', title_fr = 'Il ne mange que des fruits ? 🍎', body_fr = 'Il refuse les protéines ou les légumes ? Calculez avec le Suivi des repas ce qu''il a mangé de bon aujourd''hui et créez de délicieuses associations, comme un yaourt aux fruits.', title_hi = 'सिर्फ़ फल खाता है? 🍎', body_hi = 'प्रोटीन या सब्ज़ी नहीं खाता? फ़ीडिंग ट्रैकर से गिनिए कि आज उसे कितना पौष्टिक खाना मिला, और फ्रूट योगर्ट जैसे स्वादिष्ट मेल बनाइए।', title_id = 'Hanya mau makan buah? 🍎', body_id = 'Menolak protein atau sayuran? Hitung berapa banyak makanan bergizi yang ia dapat hari ini dengan alat Pemantau Nutrisi dan buat kombinasi lezat seperti yogurt buah.', title_ja = '果物しか食べない？🍎', body_ja = 'たんぱく質や野菜を嫌がりますか？「栄養管理ツール」で今日体にいい食べ物をどれだけとれたか計算して、フルーツヨーグルトのようなおいしい組み合わせをつくりましょう。', title_ko = '과일만 먹나요? 🍎', body_ko = '단백질이나 채소를 거부하나요? 수유 기록 도구로 오늘 몸에 좋은 음식을 얼마나 먹었는지 계산하고, 과일 요거트처럼 맛있는 조합을 만들어 보세요.', title_nl = 'Eet hij alleen fruit? 🍎', body_nl = 'Weigert hij eiwit of groente? Bereken met de Voedingstracker hoeveel gezond eten hij vandaag heeft gehad en maak lekkere combinaties zoals yoghurt met fruit.', title_pl = 'Je tylko owoce? 🍎', body_pl = 'Odrzuca białko lub warzywa? Oblicz w narzędziu do śledzenia karmienia, ile zdrowego jedzenia dziś zjadł, i twórz pyszne połączenia, np. jogurt z owocami.', title_pt = 'Só come fruta? 🍎', body_pt = 'Rejeita a proteína ou os legumes? Calcule com o Registo de Alimentação quanta comida nutritiva recebeu hoje e crie combinações saborosas, como iogurte com fruta.', title_sv = 'Äter bara frukt? 🍎', body_sv = 'Vägrar barnet protein eller grönsaker? Räkna ut med Matningskoll hur mycket nyttig mat barnet fått i dag och skapa goda kombinationer som yoghurt med frukt.', title_vi = 'Bé chỉ ăn trái cây? 🍎', body_vi = 'Bé từ chối đạm hoặc rau? Hãy tính bằng Theo dõi cữ bú xem hôm nay bé đã ăn bao nhiêu thực phẩm bổ dưỡng và tạo những kết hợp ngon miệng như sữa chua trái cây.', title_zh = '只吃水果？🍎', body_zh = '拒绝蛋白质或蔬菜？用喂养记录工具算算今天吃了多少有营养的食物，再搭配出像水果酸奶这样美味的组合。' WHERE id = 'aff8f3ff-854b-4c58-ae45-b01d9a3d3fdb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Corriendo detrás de tu peque te has olvidado de beber agua? Esa es la causa del dolor de cabeza. Revive con un agua detox de menta y limón de Recetas saludables para mujeres.', body_fr = 'Vous avez oublié de boire en lui courant après ? Voilà la cause de votre mal de tête. Requinquez-vous avec une eau détox menthe-citron des Recettes saines pour femmes.', body_hi = 'बच्चे के पीछे भागते हुए पानी पीना भूल गईं? सिर दर्द की वजह यही है। महिलाओं के लिए सेहतमंद रेसिपी से पुदीने और नींबू का डिटॉक्स वॉटर बनाइए और तरोताज़ा हो जाइए।', body_id = 'Lupa minum karena terus mengejar si kecil? Itulah penyebab sakit kepala Anda. Segarkan diri dengan infused water detoks mint dan lemon dari Resep Sehat untuk wanita.', body_ja = 'お子さんを追いかけて、お水を飲むのを忘れていませんか？それが頭痛の原因かもしれません。「女性のためのヘルシーレシピ」から、ミントとレモンのデトックスウォーターをつくって、元気を取り戻しましょう。', body_ko = '아이를 쫓아다니느라 물 마시는 걸 잊었나요? 두통의 원인이 바로 그거예요. 여성을 위한 건강한 레시피에서 민트 레몬 디톡스 워터를 만들어 기운을 되찾으세요.', body_nl = 'Vergat je te drinken terwijl je achter hem aan rende? Daar komt je hoofdpijn vandaan. Maak detoxwater met munt en citroen uit Gezonde recepten voor vrouwen en voel je weer fris.', body_pl = 'Biegając za maluchem, zapomniałaś pić? To dlatego boli cię głowa. Przygotuj ze Zdrowych przepisów dla kobiet wodę detoks z miętą i cytryną i odżyj.', body_pt = 'Esqueceu-se de beber água a correr atrás dele? É essa a causa das dores de cabeça. Prepare uma água detox de hortelã e limão das Receitas Saudáveis para Mulheres e revigore-se.', body_sv = 'Glömde du att dricka medan du sprang efter barnet? Det är därför du har huvudvärk. Gör detoxvatten med mynta och citron från Hälsosamma recept för kvinnor och pigga upp dig.', body_vi = 'Mải chạy theo bé mà mẹ quên uống nước? Đó là lý do mẹ đau đầu. Hãy làm nước detox bạc hà chanh từ Công thức lành mạnh cho phụ nữ để tỉnh táo lại.', body_zh = '追着孩子跑忘了喝水？头疼的原因就在这里。从女性健康食谱里做一杯薄荷柠檬排毒水，重新振作起来。' WHERE id = '0e790195-f407-4908-a021-252afa265e2e' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de la digestión por la mañana 💩', body_es = 'Fíjate en las deposiciones al cambiar el pañal. Al aumentar los alimentos sólidos aumenta el riesgo de estreñimiento: anótalo en la app y añade enseguida alimentos con fibra (pera, avena) con el Seguimiento de tomas.', title_fr = 'Contrôle digestif du matin 💩', body_fr = 'Observez les selles à chaque change. Plus il mange solide, plus le risque de constipation augmente : notez-le dans l''appli et ajoutez tout de suite des aliments riches en fibres (poire, avoine) avec le Suivi des repas.', title_hi = 'सुबह पाचन की जाँच 💩', body_hi = 'डायपर बदलते समय पॉटी पर ध्यान दीजिए। ठोस खाना बढ़ने के साथ कब्ज़ का खतरा बढ़ता है, ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से फ़ाइबर वाली चीज़ें (नाशपाती, ओट्स) जोड़िए।', title_id = 'Cek pencernaan pagi 💩', body_id = 'Perhatikan kotorannya saat mengganti popok. Makin banyak makanan padat, makin besar risiko sembelit. Catat di aplikasi dan segera tambahkan makanan berserat (pir, oat) dengan alat Pemantau Nutrisi.', title_ja = '朝の消化チェック 💩', body_ja = 'おむつ替えのときに、うんちの様子をチェックしましょう。固形食が増えると便秘のおそれも高まります。アプリに記録して、すぐに「栄養管理ツール」で食物繊維の多い食べ物（洋なし、オートミール）を加えましょう。', title_ko = '아침 소화 확인 💩', body_ko = '기저귀를 갈 때 배변을 살펴보세요. 고형식이 늘수록 변비 위험도 커져요. 앱에 기록하고 수유 기록 도구로 섬유질 음식(배, 귀리)을 바로 추가하세요.', title_nl = 'Spijsvertering checken in de ochtend 💩', body_nl = 'Let bij het verschonen op de ontlasting. Hoe meer vast eten, hoe groter de kans op verstopping: noteer het in de app en voeg meteen met de Voedingstracker vezelrijk eten (peer, havermout) toe.', title_pl = 'Poranna kontrola trawienia 💩', body_pl = 'Obserwuj kupki przy zmianie pieluszki. Im więcej stałych pokarmów, tym większe ryzyko zaparć: zapisz to w aplikacji i od razu dodaj w narzędziu do śledzenia karmienia produkty bogate w błonnik (gruszka, płatki owsiane).', title_pt = 'Verificar a digestão de manhã 💩', body_pt = 'Observe as fezes ao mudar a fralda. Com mais alimentos sólidos, o risco de prisão de ventre aumenta: registe-o na app e acrescente já alimentos ricos em fibra (pera, aveia) com o Registo de Alimentação.', title_sv = 'Morgonkoll av matsmältningen 💩', body_sv = 'Håll koll på avföringen när du byter blöja. Ju mer fast föda, desto större risk för förstoppning. Anteckna det i appen och lägg direkt till fiberrik mat (päron, havre) med Matningskoll.', title_vi = 'Kiểm tra tiêu hóa buổi sáng 💩', body_vi = 'Hãy để ý phân khi thay tã. Ăn càng nhiều thức ăn đặc thì nguy cơ táo bón càng cao, hãy ghi vào ứng dụng và thêm ngay thực phẩm giàu chất xơ (lê, yến mạch) bằng Theo dõi cữ bú.', title_zh = '早晨消化检查 💩', body_zh = '换尿布时留意一下排便。固体食物越多，便秘风险越高，记到应用里，马上用喂养记录工具加入富含纤维的食物（梨、燕麦）。' WHERE id = '704cb940-aadd-424e-94f9-6bfecacafa6d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo a los ruidos repentinos 🌪️', body_es = '¿Le asusta el ruido de la aspiradora o de la batidora? Pon en la habitación el sonido del secador de Ruido blanco para reducir su miedo y prepararle poco a poco para dormir.', title_fr = 'Peur des bruits soudains 🌪️', body_fr = 'Il a peur de l''aspirateur ou du mixeur ? Lancez dans la chambre le bruit de sèche-cheveux des Bruits blancs pour apaiser sa peur et le préparer doucement au sommeil.', title_hi = 'अचानक की आवाज़ों से डर 🌪️', body_hi = 'वैक्यूम क्लीनर या ब्लेंडर की आवाज़ से डरता है? कमरे में व्हाइट नॉइज़ से हेयर ड्रायर की आवाज़ चलाइए, इससे डर भी कम होगा और वह धीरे-धीरे नींद के लिए तैयार भी होगा।', title_id = 'Takut suara mendadak 🌪️', body_id = 'Takut suara penyedot debu atau blender? Putar suara pengering rambut dari Suara Putih di kamar untuk mengurangi rasa takutnya sekaligus menyiapkannya tidur pelan-pelan.', title_ja = '急な音がこわい 🌪️', body_ja = '掃除機やミキサーの音をこわがりますか？部屋で「ホワイトノイズ」のドライヤーの音を流して、こわさをやわらげながら、ゆっくり眠りへの準備をしましょう。', title_ko = '갑작스러운 소리가 무서워요 🌪️', body_ko = '청소기나 믹서기 소리를 무서워하나요? 백색소음에서 헤어드라이어 소리를 틀어 두려움을 줄이고 천천히 잠들 준비를 도와주세요.', title_nl = 'Bang voor plotselinge geluiden 🌪️', body_nl = 'Is hij bang voor de stofzuiger of de blender? Zet in de kamer het föhngeluid uit Witte ruis aan om zijn angst te verminderen en hem rustig op de slaap voor te bereiden.', title_pl = 'Strach przed nagłymi dźwiękami 🌪️', body_pl = 'Boi się odkurzacza albo blendera? Włącz w pokoju odgłos suszarki z Białego szumu, by zmniejszyć jego lęk i powoli przygotować go do snu.', title_pt = 'Medo de sons repentinos 🌪️', body_pt = 'Tem medo do barulho do aspirador ou da varinha mágica? Ligue no quarto o som do secador de cabelo do Ruído Branco, reduza-lhe o medo e prepare-o aos poucos para dormir.', title_sv = 'Rädd för plötsliga ljud 🌪️', body_sv = 'Är barnet rädd för ljudet från dammsugaren eller mixern? Sätt på hårtorksljud från Vitt brus i rummet, minska rädslan och förbered sakta barnet för sömn.', title_vi = 'Sợ những âm thanh bất ngờ 🌪️', body_vi = 'Bé sợ tiếng máy hút bụi hay máy xay sinh tố? Hãy bật tiếng máy sấy tóc trong Tiếng ồn trắng để vừa giảm nỗi sợ, vừa từ từ chuẩn bị cho bé đi ngủ.', title_zh = '害怕突然的声音 🌪️', body_zh = '害怕吸尘器或搅拌机的声音？在房间里打开白噪音里的吹风机声，既能减少恐惧，又能慢慢帮宝宝准备入睡。' WHERE id = '94804bde-ee95-44e1-87c0-8fe6a051dfb6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Clasificar colores 🔴🔵', body_es = 'Para apoyar su desarrollo lógico, busca ya en Productos recomendados rompecabezas geométricos y juguetes de madera de colores adecuados a su edad, y afina su inteligencia.', title_fr = 'Trier les couleurs 🔴🔵', body_fr = 'Pour soutenir son développement logique, cherchez tout de suite dans les Produits recommandés des puzzles géométriques et des jouets en bois colorés adaptés à son âge, et affûtez son intelligence.', title_hi = 'रंग छाँटना 🔴🔵', body_hi = 'तार्किक विकास में मदद के लिए उम्र के हिसाब से ज्यामितीय पहेलियाँ (पज़ल) और रंगीन लकड़ी के खिलौने तुरंत सुझाए गए प्रोडक्ट में खोजिए और उसकी बुद्धि तेज़ कीजिए।', title_id = 'Memilah warna 🔴🔵', body_id = 'Untuk mendukung perkembangan logikanya, segera cari puzzle geometri dan mainan kayu warna-warni sesuai usia di Produk Rekomendasi dan asah kecerdasannya.', title_ja = '色を分けよう 🔴🔵', body_ja = '論理的な思考の発達を応援するために、年齢に合った図形パズルやカラフルな木のおもちゃを、すぐに「おすすめ商品」で探して、知性を磨きましょう。', title_ko = '색깔 분류하기 🔴🔵', body_ko = '논리 발달을 돕도록 연령별 도형 퍼즐과 알록달록한 원목 장난감을 추천 제품에서 바로 찾아 두뇌를 키워 주세요.', title_nl = 'Kleuren sorteren 🔴🔵', body_nl = 'Zoek meteen in Aanbevolen producten geometrische puzzels en kleurrijk houten speelgoed voor zijn leeftijd om zijn logische ontwikkeling te steunen en zijn verstand te scherpen.', title_pl = 'Sortowanie kolorów 🔴🔵', body_pl = 'Aby wspierać rozwój logicznego myślenia, od razu poszukaj w Polecanych produktach geometrycznych układanek i kolorowych drewnianych zabawek dopasowanych do wieku i wyostrz jego umysł.', title_pt = 'Separar as cores 🔴🔵', body_pt = 'Para apoiar o desenvolvimento lógico, procure já nos Produtos Recomendados puzzles geométricos adequados à idade e brinquedos de madeira coloridos, e aguce a inteligência dele.', title_sv = 'Sortera färger 🔴🔵', body_sv = 'Leta direkt efter åldersanpassade geometriska pussel och färgglada träleksaker i Rekommenderade produkter för att stötta den logiska utvecklingen och skärpa tänkandet.', title_vi = 'Phân loại màu sắc 🔴🔵', body_vi = 'Để hỗ trợ phát triển tư duy, hãy tìm ngay các trò ghép hình học (puzzle) và đồ chơi gỗ nhiều màu sắc phù hợp lứa tuổi trong Sản phẩm gợi ý để bé thêm nhanh trí.', title_zh = '颜色分类 🔴🔵', body_zh = '为了支持逻辑发展，马上去推荐商品找找适龄的几何拼图和彩色木制玩具，让宝宝更聪明。' WHERE id = '0c2ed459-b6ef-4583-9c57-19766bfe4257' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Morder y pegar 🦖', body_es = '¿Levanta la mano o muerde de repente cuando se enfada? Lee en los artículos de psicología del Blog cómo cambiar con suavidad las emociones agresivas de esta edad.', title_fr = 'Mordre et taper 🦖', body_fr = 'Il lève soudain la main ou mord quand il se fâche ? Lisez dans les articles de psychologie de la rubrique Blogs comment faire évoluer en douceur les émotions agressives de cet âge.', title_hi = 'काटना और मारना 🦖', body_hi = 'गुस्से में अचानक हाथ उठाता है या काटता है? इस उम्र की तेज़ होती भावनाओं को नरमी से कैसे बदलें, यह ब्लॉग सेक्शन के मनोविज्ञान वाले लेखों में पढ़िए।', title_id = 'Menggigit dan memukul 🦖', body_id = 'Tiba-tiba mengangkat tangan atau menggigit saat marah? Baca artikel psikologi di bagian Blog tentang cara mengubah emosi agresif khas usia ini dengan lembut.', title_ja = 'かみつく、たたく 🦖', body_ja = '怒ると急に手が出たり、かみついたりしますか？この年齢の激しくなる気持ちをやさしく変えていく方法を、ブログの心理学の記事で読んでみましょう。', title_ko = '깨물기와 때리기 🦖', body_ko = '화가 나면 갑자기 손을 들거나 깨무나요? 이 나이의 거칠어지는 감정을 부드럽게 바꿔 주는 방법을 블로그의 심리 관련 글에서 읽어 보세요.', title_nl = 'Bijten en slaan 🦖', body_nl = 'Haalt hij ineens uit of bijt hij als hij boos is? Lees in de psychologische artikelen in Blogs hoe je de heftige emoties van deze leeftijd zacht verandert.', title_pl = 'Gryzienie i bicie 🦖', body_pl = 'Gdy się złości, nagle podnosi rękę albo gryzie? Przeczytaj w psychologicznych artykułach w sekcji Blog, jak łagodnie zmienić agresywne emocje typowe dla tego wieku.', title_pt = 'Morder e bater 🦖', body_pt = 'Quando se zanga, levanta a mão de repente ou morde? Leia nos artigos de psicologia dos Blogues como mudar com suavidade estas emoções agressivas da idade.', title_sv = 'Biter och slår 🦖', body_sv = 'Lyfter barnet plötsligt handen eller biter när hen blir arg? Läs de psykologiska artiklarna i Bloggar om hur du varsamt kan förändra den här ålderns allt starkare känslor.', title_vi = 'Cắn và đánh 🦖', body_vi = 'Bé bất ngờ vung tay hoặc cắn khi tức giận? Hãy đọc các bài viết tâm lý trong mục Blog về cách nhẹ nhàng thay đổi những cảm xúc ngày càng mạnh mẽ của lứa tuổi này.', title_zh = '咬人和打人 🦖', body_zh = '一生气就突然动手或咬人？去博客板块读读心理学文章，了解如何温和地改变这个年龄越来越激烈的情绪。' WHERE id = '1d490bb4-d589-47e3-911a-0660496e1c17' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿De repente le aprietan los zapatos? 👟', body_es = '¿Tropieza a menudo al correr? ¡Puede que le haya crecido el pie! Introduce su talla y número de pie actuales en el Registro de peso y sigue su crecimiento físico.', title_fr = 'Les chaussures serrent d''un coup ? 👟', body_fr = 'Il trébuche souvent en courant ? Son pied a peut-être grandi ! Entrez sa taille et sa pointure actuelles dans le Suivi du poids et suivez son développement physique.', title_hi = 'जूते अचानक तंग हो गए? 👟', body_hi = 'दौड़ते समय अक्सर लड़खड़ाता है? शायद पैर बड़े हो गए हैं! वेट ट्रैकर में मौजूदा लंबाई और जूतों का साइज़ दर्ज कीजिए और शारीरिक विकास पर नज़र रखिए।', title_id = 'Sepatunya tiba-tiba sesak? 👟', body_id = 'Sering tersandung saat berlari? Kakinya mungkin sudah bertambah besar! Masukkan tinggi dan ukuran sepatunya saat ini ke Pelacak Berat Badan dan pantau pertumbuhan fisiknya.', title_ja = '急に靴がきつくなった？👟', body_ja = '走るとよくつまずきますか？足が大きくなったのかもしれません！「体重トラッカー」に今の身長と靴のサイズを入力して、体の成長を記録しましょう。', title_ko = '신발이 갑자기 끼나요? 👟', body_ko = '뛰다가 자주 넘어지나요? 발이 자랐을 수도 있어요! 체중 기록에 현재 키와 신발 치수를 입력하고 신체 발달을 지켜보세요.', title_nl = 'Knellen de schoenen ineens? 👟', body_nl = 'Struikelt hij vaak bij het rennen? Zijn voetjes kunnen gegroeid zijn! Voer zijn huidige lengte en schoenmaat in de Gewichtstracker in en volg zijn lichamelijke ontwikkeling.', title_pl = 'Buty nagle uciskają? 👟', body_pl = 'Często potyka się podczas biegania? Może urosła mu stopa! Wpisz aktualny wzrost i rozmiar butów w Liczniku wagi i śledź jego rozwój fizyczny.', title_pt = 'Os sapatos ficaram apertados de repente? 👟', body_pt = 'Tropeça muito quando corre? O pé pode ter crescido! Introduza a altura e o tamanho do sapato atuais no Registo de Peso e acompanhe o crescimento físico.', title_sv = 'Klämmer skorna plötsligt? 👟', body_sv = 'Snubblar barnet ofta när hen springer? Foten kan ha växt! Ange aktuell längd och skostorlek i Viktspåraren och följ den fysiska utvecklingen.', title_vi = 'Giày bỗng dưng chật? 👟', body_vi = 'Bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập chiều cao và cỡ giày hiện tại vào Theo dõi cân nặng để theo sát sự phát triển thể chất.', title_zh = '鞋子突然挤脚了？👟', body_zh = '跑的时候经常绊倒？可能是脚长大了！在体重记录里输入当前的身高和鞋码，跟进身体发育情况。' WHERE id = 'f82f821d-7bd9-4cb7-9d17-c92628dde594' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Señales de la digestión 💩', body_es = 'Haz las anotaciones al cambiar el pañal. Si hay riesgo de estreñimiento, mira sin falta en la app recomendaciones de alimentos con fibra natural y recetas de agua con fruta.', title_fr = 'Les signaux de la digestion 💩', body_fr = 'Notez-le à chaque change. En cas de risque de constipation, consultez absolument dans l''appli les conseils d''aliments riches en fibres naturelles et les recettes d''eau aux fruits.', title_hi = 'पेट और आँतों के संकेत 💩', body_hi = 'डायपर बदलते समय एंट्री कीजिए। कब्ज़ का खतरा हो तो ऐप में कुदरती फ़ाइबर वाले खाने के सुझाव और फ्रूट वॉटर की रेसिपी ज़रूर देखिए।', title_id = 'Sinyal dari perut 💩', body_id = 'Masukkan catatan saat mengganti popok. Jika ada risiko sembelit, pastikan melihat rekomendasi makanan berserat alami dan resep air buah di aplikasi.', title_ja = 'おなかからのサイン 💩', body_ja = 'おむつ替えのときに記録しましょう。便秘のおそれがあれば、アプリで食物繊維の多い自然な食べ物のおすすめや、フルーツウォーターのレシピを必ずチェックしましょう。', title_ko = '장이 보내는 신호 💩', body_ko = '기저귀를 갈 때 기록을 남기세요. 변비가 걱정된다면 앱에서 자연 섬유질 음식 추천과 과일 물 레시피를 꼭 살펴보세요.', title_nl = 'Signalen van de darmen 💩', body_nl = 'Noteer het bij het verschonen. Is er kans op verstopping, bekijk dan zeker in de app tips voor natuurlijk vezelrijk eten en recepten voor fruitwater.', title_pl = 'Sygnały z brzuszka 💩', body_pl = 'Notuj przy zmianie pieluszki. Jeśli jest ryzyko zaparć, koniecznie zajrzyj w aplikacji do wskazówek o naturalnych produktach bogatych w błonnik i przepisów na wodę z owocami.', title_pt = 'Sinais do intestino 💩', body_pt = 'Faça os registos ao mudar a fralda. Se houver risco de prisão de ventre, veja sem falta na app as sugestões de alimentos com fibra natural e as receitas de água com fruta.', title_sv = 'Signaler från magen 💩', body_sv = 'Anteckna när du byter blöja. Finns risk för förstoppning, titta på tipsen om naturlig fiberrik mat och recepten på fruktvatten i appen.', title_vi = 'Tín hiệu từ đường ruột 💩', body_vi = 'Hãy ghi lại khi thay tã. Nếu có nguy cơ táo bón, nhất định hãy xem gợi ý thực phẩm giàu chất xơ tự nhiên và công thức nước trái cây trong ứng dụng.', title_zh = '肠胃发出的信号 💩', body_zh = '换尿布时记录下来。如果有便秘风险，一定去应用里看看天然高纤维食物的建议和果味水食谱。' WHERE id = '04f27cd2-d5c6-4a88-a758-f59dfedfac03' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Miedo a la separación? 🌌', body_es = '¿Llora en cuanto sales de la habitación? Pon el sonido del vientre materno de Ruido blanco, devuélvele aquella cálida sensación de seguridad y prepárale para dormir.', title_fr = 'Peur de la séparation ? 🌌', body_fr = 'Il pleure dès que vous quittez la pièce ? Lancez le son du ventre maternel des Bruits blancs pour lui rendre ce doux sentiment de sécurité d''autrefois et l''aider à s''endormir.', title_hi = 'अलग होने का डर? 🌌', body_hi = 'आप कमरे से निकलते ही वह रोने लगता है? व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर उसे वही पुरानी गर्माहट और सुरक्षा का एहसास दीजिए और नींद के लिए तैयार कीजिए।', title_id = 'Takut berpisah? 🌌', body_id = 'Menangis begitu Anda keluar kamar? Putar suara rahim dari Suara Putih, beri ia rasa aman yang hangat dan akrab, lalu antar ia tidur.', title_ja = '離れるのがこわい？🌌', body_ja = '部屋を出たとたん、あとを追って泣きますか？「ホワイトノイズ」の胎内の音を流して、なつかしい温かな安心感を届け、眠りへ導きましょう。', title_ko = '분리 불안? 🌌', body_ko = '방을 나가자마자 울며 따라오나요? 백색소음에서 엄마 배 속 소리를 틀어 익숙하고 따뜻한 안정감을 주고 잠들 준비를 도와주세요.', title_nl = 'Verlatingsangst? 🌌', body_nl = 'Huilt hij zodra je de kamer uit gaat? Zet het baarmoedergeluid uit Witte ruis aan, geef hem dat oude, warme gevoel van veiligheid en help hem in slaap.', title_pl = 'Lęk przed rozstaniem? 🌌', body_pl = 'Płacze, gdy tylko wychodzisz z pokoju? Włącz w Białym szumie odgłosy z brzucha mamy, daj mu znajome, ciepłe poczucie bezpieczeństwa i nastrój go do snu.', title_pt = 'Medo da separação? 🌌', body_pt = 'Mal sai do quarto, chora atrás de si? Ligue no Ruído Branco o som do útero materno, dê-lhe aquela antiga sensação quente de segurança e prepare-o para dormir.', title_sv = 'Separationsångest? 🌌', body_sv = 'Gråter barnet så fort du lämnar rummet? Sätt på ljudet från livmodern i Vitt brus, ge barnet den gamla varma känslan av trygghet och stäm för sömn.', title_vi = 'Sợ phải xa mẹ? 🌌', body_vi = 'Mẹ vừa ra khỏi phòng là bé khóc theo? Hãy bật âm thanh trong bụng mẹ trong Tiếng ồn trắng để mang lại cảm giác an toàn ấm áp quen thuộc và đưa bé vào giấc ngủ.', title_zh = '分离焦虑？🌌', body_zh = '你一离开房间就在后面哭？打开白噪音里的子宫声，给宝宝熟悉而温暖的安全感，帮宝宝进入睡眠。' WHERE id = '2312b09a-1559-4ed0-aada-ff2063057e72' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los huesos se fortalecen 🦴', body_es = 'Un desarrollo tan rápido necesita calcio. Comprueba con el Seguimiento de tomas si hoy ha tomado su ración de queso y yogur y completa enseguida lo que falte.', title_fr = 'Des os plus solides 🦴', body_fr = 'Une croissance rapide demande du calcium. Vérifiez avec le Suivi des repas qu''il a eu sa ration de fromage et de yaourt aujourd''hui et comblez tout de suite les manques.', title_hi = 'हड्डियाँ मज़बूत हो रही हैं 🦴', body_hi = 'तेज़ विकास के लिए कैल्शियम चाहिए। फ़ीडिंग ट्रैकर से पक्का कीजिए कि आज पनीर और दही की मात्रा पूरी हुई, और कमी तुरंत पूरी कीजिए।', title_id = 'Tulang makin kuat 🦴', body_id = 'Pertumbuhan yang pesat butuh kalsium. Pastikan dengan alat Pemantau Nutrisi bahwa porsi keju dan yogurt hari ini terpenuhi, dan segera lengkapi kekurangannya.', title_ja = '骨が強くなる 🦴', body_ja = '急速な成長にはカルシウムが必要です。「栄養管理ツール」で今日のチーズやヨーグルトの目安量をとれたか確認して、足りない分をすぐに補いましょう。', title_ko = '뼈가 튼튼해져요 🦴', body_ko = '빠른 성장에는 칼슘이 필요해요. 수유 기록 도구로 오늘 치즈와 요거트 기준량을 채웠는지 확인하고 부족한 만큼 바로 채워 주세요.', title_nl = 'Sterkere botten 🦴', body_nl = 'Snelle groei vraagt om calcium. Check met de Voedingstracker of hij vandaag genoeg kaas en yoghurt heeft gehad en vul tekorten meteen aan.', title_pl = 'Kości stają się mocniejsze 🦴', body_pl = 'Szybki rozwój wymaga wapnia. Sprawdź w narzędziu do śledzenia karmienia, czy dzisiejsza porcja sera i jogurtu została osiągnięta, i od razu uzupełnij braki.', title_pt = 'Os ossos ficam mais fortes 🦴', body_pt = 'Um desenvolvimento rápido exige cálcio. Confirme com o Registo de Alimentação que hoje cumpriu a dose de queijo e iogurte e complete já o que faltar.', title_sv = 'Skelettet blir starkare 🦴', body_sv = 'Snabb utveckling kräver kalcium. Kontrollera med Matningskoll att barnet fått dagens norm av ost och yoghurt och fyll direkt på det som fattas.', title_vi = 'Xương chắc khỏe hơn 🦴', body_vi = 'Phát triển nhanh cần nhiều canxi. Hãy kiểm tra bằng Theo dõi cữ bú xem hôm nay bé đã ăn đủ định mức phô mai, sữa chua chưa và bổ sung ngay phần thiếu.', title_zh = '骨骼越来越强壮 🦴', body_zh = '快速发育需要钙。用喂养记录工具确认今天奶酪、酸奶的参考量是否达到，马上补上不足的部分。' WHERE id = 'ca3c13b4-94b6-44d7-a1be-1829a1d0e718' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ya eres genial 🌟', body_es = 'Hoy no has parado de correr detrás de tu peque y estás cansada. ¡Abre el Diario de ánimo, escribe hasta lo más pequeño que has hecho hoy por tu peque y aplaúdete de pie!', title_fr = 'Vous êtes déjà formidable 🌟', body_fr = 'Vous lui avez couru après toute la journée et vous êtes épuisée. Ouvrez le Journal d''humeur, notez même la plus petite attention que vous lui avez offerte aujourd''hui et applaudissez-vous debout !', title_hi = 'आप वैसे भी कमाल की हैं 🌟', body_hi = 'आज आप लगातार उसके पीछे भागीं और थक गईं। मूड डायरी खोलिए, आज उसके लिए की गई छोटी से छोटी अच्छाई भी लिखिए और खुद को शाबाशी दीजिए!', title_id = 'Anda sudah luar biasa 🌟', body_id = 'Hari ini Anda terus mengejarnya tanpa henti dan kelelahan. Buka Buku Harian Suasana Hati, tulis kebaikan sekecil apa pun yang Anda lakukan untuknya hari ini, dan beri tepuk tangan untuk diri sendiri!', title_ja = 'あなたはすでに最高です 🌟', body_ja = '今日は一日中お子さんを追いかけて、くたくたですね。「気分日記」を開いて、今日お子さんのためにしたどんな小さなことも書き、自分にスタンディングオベーションを送りましょう！', title_ko = '엄마는 이미 충분히 멋져요 🌟', body_ko = '오늘 쉬지 않고 아이를 쫓아다니느라 지쳤죠. 기분 일기를 열고 오늘 아이를 위해 한 아주 작은 일이라도 적으며 나에게 기립 박수를 보내 주세요!', title_nl = 'Je bent al geweldig 🌟', body_nl = 'Je rende vandaag de hele dag achter hem aan en bent moe. Open je Stemmingsdagboek, schrijf zelfs het kleinste liefs op dat je vandaag voor hem deed, en geef jezelf een staande ovatie!', title_pl = 'I tak jesteś wspaniała 🌟', body_pl = 'Cały dzień biegałaś za nim i jesteś zmęczona. Otwórz Dziennik nastroju, zapisz nawet najmniejszą dobrą rzecz, którą dziś dla niego zrobiłaś, i nagródź się owacją na stojąco!', title_pt = 'Já é fantástica 🌟', body_pt = 'Hoje correu atrás dele sem parar e ficou cansada. Abra o Diário de Humor, escreva até o gesto mais pequeno que fez hoje por ele e aplauda-se de pé!', title_sv = 'Du är redan fantastisk 🌟', body_sv = 'Du har sprungit efter barnet hela dagen och är trött. Öppna Humördagboken, skriv ner även det minsta du gjort för barnet i dag och ge dig själv stående ovationer!', title_vi = 'Mẹ vốn đã tuyệt vời rồi 🌟', body_vi = 'Hôm nay mẹ đã chạy theo bé không ngừng và mệt nhoài. Hãy mở Nhật ký tâm trạng, ghi lại cả việc tốt nhỏ nhất mẹ đã làm cho bé hôm nay và tự vỗ tay cho mình!', title_zh = '你本来就很棒 🌟', body_zh = '今天你一直追着宝宝跑，累坏了。打开心情日记，哪怕是今天为宝宝做的最小的一件好事也写下来，为自己热烈鼓掌吧！' WHERE id = 'cbda41ad-a761-4c07-b60f-6e77f3dd54cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La tozudez de comer solo 🥄', body_es = '¿Te quita la cuchara y lo mancha todo? Pon el temporizador de tomas y analiza cuánto dura esta prueba de independencia. A la comida derramada, solo sonríele.', title_fr = 'Il tient à manger seul 🥄', body_fr = 'Il vous prend la cuillère et en met partout ? Lancez le minuteur des repas et analysez combien de temps dure ce test d''autonomie. Et devant la nourriture renversée, souriez simplement.', title_hi = 'खुद खाने की ज़िद 🥄', body_hi = 'चम्मच आपसे ले लेता है और सब जगह गंदा कर देता है? फ़ीडिंग टाइमर चालू कीजिए और देखिए कि आज़ादी की यह कोशिश कितना समय लेती है। बिखरे खाने पर बस मुस्कुरा दीजिए।', title_id = 'Ngotot makan sendiri 🥄', body_id = 'Merebut sendok dari Anda dan membuat semuanya berantakan? Nyalakan Timer Makan dan lihat berapa lama ujian kemandirian ini berlangsung. Untuk makanan yang berceceran, cukup tersenyum saja.', title_ja = '自分で食べるとゆずらない 🥄', body_ja = 'あなたからスプーンを取って、あちこち汚していますか？食事タイマーをオンにして、この自立の挑戦にどれくらい時間がかかるか分析しましょう。こぼれた食べ物には、ただほほえんで。', title_ko = '혼자 먹겠다는 고집 🥄', body_ko = '엄마 손에서 숟가락을 가져가 온 사방을 어지르나요? 수유 타이머를 켜고 이 자립 도전이 얼마나 걸리는지 살펴보세요. 흘린 음식에는 그냥 웃어 주세요.', title_nl = 'Per se zelf eten 🥄', body_nl = 'Pakt hij de lepel van je af en maakt hij alles vies? Zet de Voedingstimer aan en kijk hoe lang deze zelfstandigheidstest duurt. Om het gemorste eten kun je gewoon glimlachen.', title_pl = 'Upiera się, że zje sam 🥄', body_pl = 'Zabiera ci łyżkę i wszystko brudzi? Włącz timer karmienia i sprawdź, ile trwa ta próba samodzielności. Do rozsypanego jedzenia po prostu się uśmiechnij.', title_pt = 'A teimosia de comer sozinho 🥄', body_pt = 'Tira-lhe a colher e suja tudo? Ligue o temporizador de alimentação e analise quanto tempo demora este teste de independência. À comida entornada, responda só com um sorriso.', title_sv = 'Envis med att äta själv 🥄', body_sv = 'Tar barnet skeden från dig och kladdar ner allt? Starta matningstimern och analysera hur lång tid självständighetsförsöket tar. Le bara åt maten som spills.', title_vi = 'Nhất quyết tự ăn 🥄', body_vi = 'Bé giành thìa từ tay mẹ và làm bẩn khắp nơi? Hãy bật Hẹn giờ cho bú để xem thử thách tự lập này mất bao lâu. Thức ăn vương vãi thì cứ mỉm cười thôi.', title_zh = '坚持自己吃饭 🥄', body_zh = '从你手里拿走勺子，弄得到处都是？打开喂养计时器，分析这场自主挑战花了多长时间。撒了一地的饭，笑一笑就好。' WHERE id = 'dc8f916f-27ea-45e1-9c5f-84435b0902fd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡No quiero estos pantalones! 👗', body_es = '¿Ha empezado la tozudez del «¡Me visto yo!»? Aprende con Anacan AI cómo reducir las batallas de ropa por la mañana y darle libertad para elegir.', title_fr = '« Je ne veux pas ce pantalon ! » 👗', body_fr = 'La période « Je m''habille tout seul ! » a commencé ? Découvrez avec Anacan AI comment réduire les crises d''habillage du matin et lui laisser le libre choix.', title_hi = '''यह पैंट नहीं चाहिए!'' 👗', body_hi = '''मैं खुद पहनूँगा!'' वाली ज़िद शुरू हो गई? सुबह कपड़ों के झगड़े कम करने और उसे अपनी पसंद चुनने का मौका देने के तरीके Anacan AI से जानिए।', title_id = 'Aku tidak mau celana ini! 👗', body_id = 'Masa keras kepala Aku pakai sendiri! sudah dimulai? Pelajari dari Anacan AI cara mengurangi drama berpakaian di pagi hari dan memberinya hak memilih.', title_ja = 'このズボンはいや！👗', body_ja = '「自分で着る！」というこだわりが始まりましたか？朝の着替えのかんしゃくを減らし、自分で選ぶ機会をあげる方法を、Anacan AIで学びましょう。', title_ko = '이 바지 싫어! 👗', body_ko = '''내가 입을 거야!'' 고집이 시작됐나요? 아침 옷 입기 전쟁을 줄이고 스스로 고를 기회를 주는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Ik wil deze broek niet! 👗', body_nl = 'Begint het ik kleed me zelf aan!-gedoe? Leer bij Anacan AI hoe je de ochtendstrijd om kleding vermindert en hem vrij laat kiezen.', title_pl = 'Nie chcę tych spodni! 👗', body_pl = 'Zaczął się upór w stylu „Sam się ubiorę!”? Dowiedz się od Anacan AI, jak ograniczyć poranne kryzysy przy ubieraniu i dać mu prawo do samodzielnego wyboru.', title_pt = 'Não quero estas calças! 👗', body_pt = 'Começou a teimosia do "Eu visto-me sozinho!"? Aprenda com o Anacan AI como reduzir as crises da roupa de manhã e dar-lhe liberdade de escolha.', title_sv = 'Jag vill inte ha de här byxorna! 👗', body_sv = 'Har envisheten ”Jag klär på mig själv!” börjat? Lär dig av Anacan AI hur du kan minska morgonens klädbråk och ge barnet frihet att välja.', title_vi = '"Con không thích cái quần này!" 👗', body_vi = 'Bé bắt đầu bướng bỉnh "Con tự mặc!"? Hãy học từ Anacan AI cách giảm những cuộc chiến quần áo buổi sáng và cho bé quyền tự chọn.', title_zh = '我不要这条裤子！👗', body_zh = '开始“我要自己穿！”的倔强了？向Anacan AI了解如何减少早上穿衣时的冲突，并给宝宝自由选择的权利。' WHERE id = '1d9a17fb-3ed7-4382-9eaf-1517914b5b98' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas a tus amigas 👯‍♀️', body_es = '¿Cansada de hablar solo con tu peque? Busca en Lugares para mamás centros con grupos de juego, socializa con otras madres y comparte experiencias.', title_fr = 'Vous aussi, vous avez besoin d''amies 👯‍♀️', body_fr = 'Fatiguée de ne parler qu''avec votre enfant ? Trouvez des centres avec groupes de jeu dans les Lieux adaptés aux mamans, rencontrez d''autres mamans et partagez vos expériences.', title_hi = 'आपको भी दोस्तों की ज़रूरत है 👯‍♀️', body_hi = 'सिर्फ़ बच्चे से बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में प्ले ग्रुप वाले सेंटर ढूँढिए, दूसरी माँओं से मिलिए और अनुभव बाँटिए।', title_id = 'Anda juga butuh teman 👯‍♀️', body_id = 'Lelah hanya mengobrol dengan si kecil? Temukan tempat dengan kelompok bermain di Tempat Ramah Ibu, bersosialisasi dengan ibu lain, dan berbagi pengalaman.', title_ja = 'あなたにも友だちが必要です 👯‍♀️', body_ja = '子どもとだけ話すのに疲れましたか？「ママにやさしいスポット」で遊びのグループがある施設を見つけて、ほかのママと交流し、経験を分かち合いましょう。', title_ko = '엄마에게도 친구가 필요해요 👯‍♀️', body_ko = '아이하고만 이야기하는 게 지쳤나요? 엄마 친화 장소에서 놀이 모임이 있는 센터를 찾아 다른 엄마들과 어울리고 경험을 나눠 보세요.', title_nl = 'Jij hebt ook vriendinnen nodig 👯‍♀️', body_nl = 'Moe van alleen maar praten met je kindje? Zoek in Mamavriendelijke plekken centra met speelgroepjes, maak contact met andere moeders en deel ervaringen.', title_pl = 'Ty też potrzebujesz przyjaciółek 👯‍♀️', body_pl = 'Masz dość rozmów wyłącznie z dzieckiem? Znajdź w Miejscach przyjaznych mamom centra z grupami zabaw, poznaj inne mamy i wymieniajcie się doświadczeniami.', title_pt = 'Também precisa de amigas 👯‍♀️', body_pt = 'Cansada de falar só com a criança? Encontre nos Locais Amigos das Mães centros com grupos de brincadeira, conviva com outras mães e partilhe experiências.', title_sv = 'Du behöver också vänner 👯‍♀️', body_sv = 'Trött på att bara prata med barnet? Hitta center med lekgrupper i Mammavänliga platser, umgås med andra mammor och dela erfarenheter.', title_vi = 'Mẹ cũng cần bạn bè 👯‍♀️', body_vi = 'Mẹ mệt vì cả ngày chỉ nói chuyện với bé? Hãy tìm các trung tâm có nhóm chơi trong Địa điểm thân thiện với mẹ để giao lưu và chia sẻ kinh nghiệm với các mẹ khác.', title_zh = '你也需要朋友 👯‍♀️', body_zh = '只和孩子说话说累了？在妈妈友好场所里找到有游戏小组的中心，和其他妈妈交流、分享经验吧。' WHERE id = '98d988ed-7e7f-4eb3-8b84-734112bb1929' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libros para leer, no para romper 📖', body_es = '¿A la hora del cuento arranca las páginas o no te deja leer? Pregunta ya a Anacan AI cómo resolverlo sin dañar el hábito de la lectura.', title_fr = 'Lire les livres, pas les déchirer 📖', body_fr = 'Il déchire les pages ou vous empêche de lire le conte du soir ? Demandez tout de suite à Anacan AI comment régler ce problème sans abîmer son goût pour la lecture.', title_hi = 'किताब फाड़ना नहीं, पढ़ना 📖', body_hi = 'शाम की कहानी के समय पन्ने फाड़ता है या पढ़ने नहीं देता? पढ़ने की आदत बिगाड़े बिना इस समस्या को कैसे सुलझाएँ, यह तुरंत Anacan AI से पूछिए।', title_id = 'Membaca buku, bukan merobeknya 📖', body_id = 'Merobek halaman atau tidak membiarkan Anda membaca saat dongeng malam? Segera tanyakan kepada Anacan AI cara mengatasinya tanpa merusak kebiasaan membacanya.', title_ja = '絵本は破らずに読もう 📖', body_ja = '夜の読み聞かせの時間に、ページを破ったり、読ませてくれなかったりしますか？読書の習慣を損なわずにこの問題に対応する方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '찢지 말고 읽어요 📖', body_ko = '잠자리 동화 시간에 책장을 찢거나 읽지 못하게 하나요? 책 읽는 습관을 해치지 않고 이 문제를 해결하는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Boeken lezen, niet scheuren 📖', body_nl = 'Scheurt hij bij het avondverhaal de bladzijden of laat hij je niet voorlezen? Vraag Anacan AI meteen hoe je dit oplost zonder zijn leesplezier te beschadigen.', title_pl = 'Nie drzemy książek, tylko czytamy 📖', body_pl = 'Podczas wieczornej bajki drze strony albo nie pozwala czytać? Od razu zapytaj Anacan AI, jak rozwiązać ten problem, nie zniechęcając go do czytania.', title_pt = 'Ler, não rasgar 📖', body_pt = 'Na hora da história da noite, rasga as páginas ou não a deixa ler? Pergunte já ao Anacan AI como resolver isto sem prejudicar o hábito da leitura.', title_sv = 'Läsa böcker, inte riva sönder dem 📖', body_sv = 'River barnet sönder sidorna vid kvällssagan eller låter dig inte läsa? Fråga Anacan AI direkt hur du löser problemet utan att skada läsvanan.', title_vi = 'Đọc sách, không xé sách 📖', body_vi = 'Giờ kể chuyện buổi tối bé xé trang sách hoặc không cho mẹ đọc? Hãy hỏi ngay Anacan AI cách giải quyết chuyện này mà không làm mất thói quen đọc sách của bé.', title_zh = '不撕书，读书 📖', body_zh = '晚上讲故事时撕书页，或者不让你读？马上问问Anacan AI，如何在不破坏阅读习惯的前提下解决这个问题。' WHERE id = 'f6ae40aa-d27d-4aed-a0d9-bd51bad467d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin azúcar, pero dulce 🍪', body_es = '¡Adiós a las galletas del súper! Descubre en Recetas para bebé dulces sanos caseros de dátiles y avena que se preparan en 10 minutos.', title_fr = 'Sans sucre, mais sucré 🍪', body_fr = 'Fini les biscuits du commerce ! Découvrez dans les Recettes pour bébés des douceurs saines aux dattes et à l''avoine, prêtes en 10 minutes à la maison.', title_hi = 'बिना चीनी, फिर भी मीठा 🍪', body_hi = 'बाज़ार के बिस्किट को अलविदा! बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली खजूर और ओट्स की सेहतमंद मिठाइयाँ खोजिए।', title_id = 'Tanpa gula, tapi manis 🍪', body_id = 'Selamat tinggal biskuit dari toko! Temukan camilan manis sehat dari kurma dan oat yang siap dalam 10 menit di Resep Bayi.', title_ja = '砂糖なしでも甘い 🍪', body_ja = '市販のクッキーとはお別れ！「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれる、デーツとオートミールのヘルシーなおやつを見つけましょう。', title_ko = '설탕 없이도 달콤하게 🍪', body_ko = '마트 쿠키는 이제 그만! 아기 레시피에서 집에서 10분이면 만드는 대추야자 귀리 건강 간식을 찾아보세요.', title_nl = 'Zonder suiker, maar zoet 🍪', body_nl = 'Weg met koekjes uit de winkel! Ontdek in Babyrecepten gezonde lekkernijen met dadels en havermout, thuis klaar in 10 minuten.', title_pl = 'Bez cukru, ale słodko 🍪', body_pl = 'Koniec ze sklepowymi ciastkami! Odkryj w Przepisach dla niemowląt zdrowe słodkości z daktylami i płatkami owsianymi, które zrobisz w domu w 10 minut.', title_pt = 'Sem açúcar, mas doce 🍪', body_pt = 'Adeus bolachas do supermercado! Descubra nas Receitas para bebés doces saudáveis de tâmaras e aveia, feitos em casa em 10 minutos.', title_sv = 'Sockerfritt, men sött 🍪', body_sv = 'Slut på kex från affären! Upptäck nyttiga sötsaker med dadlar och havre som är klara på 10 minuter hemma i Recept för bebisar.', title_vi = 'Không đường mà vẫn ngọt 🍪', body_vi = 'Tạm biệt bánh quy mua sẵn! Hãy khám phá các món ngọt bổ dưỡng từ chà là và yến mạch làm tại nhà trong 10 phút trong Công thức cho bé.', title_zh = '无糖，却很甜 🍪', body_zh = '和超市饼干说再见！在宝宝食谱里发现10分钟就能在家做好的椰枣燕麦健康甜点。' WHERE id = 'a2bb6939-4631-4be2-a871-cb519c3fdacb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos bien la rutina ⏱️', body_es = '¿Por la noche tardó 40 minutos en dormirse? Mira el gráfico del temporizador de sueño. Quizá sea el momento de acortar la siesta 20 minutos y adelantar la hora de dormir.', title_fr = 'Analysons son rythme en détail ⏱️', body_fr = 'Il a mis 40 minutes à s''endormir ce soir ? Regardez le graphique du minuteur de sommeil. C''est peut-être le bon moment pour raccourcir la sieste de 20 minutes et avancer le coucher.', title_hi = 'रूटीन का पूरा विश्लेषण करें ⏱️', body_hi = 'शाम को सोने में 40 मिनट लग गए? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद 20 मिनट कम करने और शाम की नींद जल्दी करने का सही समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Butuh 40 menit untuk tertidur malam ini? Lihat grafik Timer Tidur. Mungkin inilah saatnya memangkas tidur siang 20 menit dan memajukan jam tidur malam.', title_ja = '生活リズムをしっかり分析しよう ⏱️', body_ja = '夜、寝つくまで40分かかりましたか？睡眠タイマーのグラフを見てみましょう。お昼寝を20分短くして、夜の寝る時間を早めるちょうどいいタイミングかもしれません。', title_ko = '일과를 제대로 분석해 봐요 ⏱️', body_ko = '저녁에 잠드는 데 40분이 걸렸나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 20분 줄이고 잠자리 시간을 앞당길 때가 되었을지도 몰라요.', title_nl = 'Laten we het ritme goed analyseren ⏱️', body_nl = 'Duurde het inslapen vanavond 40 minuten? Bekijk de grafiek van de Slaaptimer. Misschien is het precies tijd om het middagdutje met 20 minuten in te korten en de bedtijd te vervroegen.', title_pl = 'Dokładnie przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorne zasypianie trwało 40 minut? Spójrz na wykres timera snu. Może to dobry moment, by skrócić drzemkę o 20 minut i przesunąć wieczorne spanie wcześniej.', title_pt = 'Vamos analisar a rotina a fundo ⏱️', body_pt = 'À noite demorou 40 minutos a adormecer? Veja o gráfico do temporizador de sono. Talvez seja a altura certa de encurtar a sesta 20 minutos e antecipar a hora de deitar.', title_sv = 'Vi analyserar rytmen ordentligt ⏱️', body_sv = 'Tog det 40 minuter att somna i kväll? Titta på grafen i sömntimern. Kanske är det precis rätt tid att korta dagsömnen med 20 minuter och tidigarelägga kvällen.', title_vi = 'Cùng phân tích toàn bộ nếp sinh hoạt ⏱️', body_vi = 'Tối qua bé mất 40 phút mới ngủ? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đây đúng là lúc rút ngắn giấc ngủ ngày 20 phút và cho bé ngủ tối sớm hơn.', title_zh = '来全面分析一下作息 ⏱️', body_zh = '晚上入睡花了40分钟？看看睡眠计时器的图表。也许正是把白天小睡缩短20分钟、把晚上就寝时间提前的时候了。' WHERE id = '27d6b395-9576-4f2d-9566-57d41e7c6f41' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los «¿por qué?» sin fin 🤔', body_es = '¿No se cansa de preguntar? ¡La etapa del «¿Qué es esto? ¿Por qué?» ha empezado oficialmente! Aprende en el Blog a responder con paciencia a su curiosidad por descubrir.', title_fr = 'Les « Pourquoi ? » sans fin 🤔', body_fr = 'Il ne se lasse pas de poser des questions ? La période du « C''est quoi ? Pourquoi ? » a officiellement commencé ! Découvrez dans la rubrique Blogs comment répondre avec patience à sa curiosité.', title_hi = 'कभी न खत्म होने वाले ''क्यों?'' 🤔', body_hi = 'पूछते-पूछते थकता नहीं? ''यह क्या है? क्यों?'' वाला दौर आधिकारिक तौर पर शुरू हो गया है! उसकी इस खोज भरी जिज्ञासा का धैर्य से जवाब कैसे दें, यह ब्लॉग में जानिए।', title_id = 'Pertanyaan Kenapa? tanpa akhir 🤔', body_id = 'Tak pernah lelah bertanya? Masa Ini apa? Kenapa? resmi dimulai! Pelajari di Blog cara menjawab rasa ingin tahunya dengan sabar.', title_ja = '終わらない「なんで？」の質問 🤔', body_ja = '質問が止まらない？「これなあに？なんで？」の時期が正式に始まりました！この探究心に気長に答える方法を、ブログで学びましょう。', title_ko = '끝없는 ''왜?'' 질문 🤔', body_ko = '질문을 멈추지 않나요? ''이게 뭐야? 왜?'' 시기가 공식적으로 시작됐어요! 아이의 탐구심에 인내심 있게 대답하는 법을 블로그에서 배워 보세요.', title_nl = 'De eindeloze waarom?-vragen 🤔', body_nl = 'Wordt hij nooit moe van vragen? De fase van wat is dat? waarom? is officieel begonnen! Lees in Blogs hoe je geduldig antwoord geeft op zijn nieuwsgierigheid.', title_pl = 'Niekończące się pytania „Dlaczego?” 🤔', body_pl = 'Nie męczy się pytaniem? Etap „Co to? Dlaczego?” oficjalnie się zaczął! Dowiedz się z Bloga, jak cierpliwie odpowiadać na tę ciekawość świata.', title_pt = 'As perguntas sem fim do "Porquê?" 🤔', body_pt = 'Não se cansa de perguntar? A fase do "O que é isto? Porquê?" começou oficialmente! Aprenda nos Blogues a responder com paciência a esta curiosidade de descobrir.', title_sv = 'De ändlösa ”Varför?”-frågorna 🤔', body_sv = 'Blir barnet aldrig trött på att fråga? ”Vad är det? Varför?”-perioden har officiellt börjat! Lär dig i Bloggar hur du med tålamod svarar på barnets upptäckarlust.', title_vi = 'Những câu hỏi "Tại sao?" bất tận 🤔', body_vi = 'Bé hỏi mãi không biết mệt? Giai đoạn "Cái gì đây? Tại sao?" đã chính thức bắt đầu! Hãy học trong mục Blog cách kiên nhẫn trả lời sự tò mò khám phá này của bé.', title_zh = '没完没了的“为什么？”🤔', body_zh = '问个不停也不累？“这是什么？为什么？”阶段正式开始了！去博客学习如何耐心回应孩子的探索欲。' WHERE id = 'dec1d9f5-52bc-4c79-9c9c-281f44046beb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin azúcar, pero dulce 🍪', body_es = '¡Adiós a las galletas del súper! Descubre en Recetas para bebé dulces sanos caseros que se preparan en 10 minutos y dale una alegría.', title_fr = 'Sans sucre, mais sucré 🍪', body_fr = 'Fini les biscuits du commerce ! Découvrez dans les Recettes pour bébés des douceurs saines, prêtes en 10 minutes à la maison, et faites-lui plaisir.', title_hi = 'बिना चीनी, फिर भी मीठा 🍪', body_hi = 'बाज़ार के बिस्किट को अलविदा! बच्चों की रेसिपी में घर पर 10 मिनट में बनने वाली सेहतमंद मिठाइयाँ खोजिए और उसे खुश कीजिए।', title_id = 'Tanpa gula, tapi manis 🍪', body_id = 'Selamat tinggal biskuit dari toko! Temukan camilan manis sehat yang siap dalam 10 menit di Resep Bayi dan buat ia senang.', title_ja = '砂糖なしでも甘い 🍪', body_ja = '市販のクッキーとはお別れ！「離乳食を始める赤ちゃんのレシピ」で、家で10分でつくれるヘルシーなおやつを見つけて、お子さんを喜ばせましょう。', title_ko = '설탕 없이도 달콤하게 🍪', body_ko = '마트 쿠키는 이제 그만! 아기 레시피에서 집에서 10분이면 만드는 건강 간식을 찾아 아이를 기쁘게 해 주세요.', title_nl = 'Zonder suiker, maar zoet 🍪', body_nl = 'Weg met koekjes uit de winkel! Ontdek in Babyrecepten gezonde lekkernijen, thuis klaar in 10 minuten, en maak hem blij.', title_pl = 'Bez cukru, ale słodko 🍪', body_pl = 'Koniec ze sklepowymi ciastkami! Odkryj w Przepisach dla niemowląt zdrowe słodkości, które zrobisz w domu w 10 minut, i spraw mu radość.', title_pt = 'Sem açúcar, mas doce 🍪', body_pt = 'Adeus bolachas do supermercado! Descubra nas Receitas para bebés doces saudáveis feitos em casa em 10 minutos e faça-o feliz.', title_sv = 'Sockerfritt, men sött 🍪', body_sv = 'Slut på kex från affären! Upptäck nyttiga sötsaker som är klara på 10 minuter hemma i Recept för bebisar och gör barnet glad.', title_vi = 'Không đường mà vẫn ngọt 🍪', body_vi = 'Tạm biệt bánh quy mua sẵn! Hãy khám phá các món ngọt bổ dưỡng làm tại nhà trong 10 phút trong Công thức cho bé để bé thêm vui.', title_zh = '无糖，却很甜 🍪', body_zh = '和超市饼干说再见！在宝宝食谱里发现10分钟就能在家做好的健康甜点，让宝宝开心一下。' WHERE id = 'e68bbf03-3f37-41e8-a1d9-32feba8b86d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y silencio 🍵', body_es = 'El temporizador se ha parado y tu peque duerme. ¡No corras a las tareas de casa! Prepárate un café especial de Recetas saludables, túmbate en el sofá y disfruta del silencio.', title_fr = 'Thé chaud et silence 🍵', body_fr = 'Le minuteur est arrêté, il dort. Ne vous ruez pas sur les tâches ménagères ! Préparez un café spécial des Recettes saines, allongez-vous sur le canapé et savourez simplement le silence.', title_hi = 'गर्म चाय और खामोशी 🍵', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के कामों की ओर मत भागिए! सेहतमंद रेसिपी से एक खास कॉफ़ी बनाइए, सोफ़े पर लेटिए और बस खामोशी का मज़ा लीजिए।', title_id = 'Teh hangat dan keheningan 🍵', body_id = 'Timer berhenti, si kecil sudah tidur. Jangan buru-buru mengerjakan pekerjaan rumah! Buat kopi spesial dari Resep Sehat, berbaring di sofa, dan nikmati keheningan.', title_ja = '温かいお茶と静けさ 🍵', body_ja = 'タイマーは止まり、お子さんは眠りました。家事に走らないで！「ヘルシーレシピ」から特別なコーヒーをいれて、ソファに横になり、静けさだけを味わいましょう。', title_ko = '따뜻한 차와 고요함 🍵', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일로 달려가지 마세요! 건강한 레시피에서 특별한 커피를 만들어 소파에 누워 오직 고요함만 즐기세요.', title_nl = 'Warme thee en stilte 🍵', body_nl = 'De timer is gestopt, je kindje slaapt. Ren niet naar het huishouden! Maak een speciale koffie uit Gezonde recepten, ga op de bank liggen en geniet gewoon van de stilte.', title_pl = 'Ciepła herbata i cisza 🍵', body_pl = 'Timer zatrzymany, maluch śpi. Nie rzucaj się w wir obowiązków! Przygotuj wyjątkową kawę ze Zdrowych przepisów, połóż się na kanapie i po prostu delektuj się ciszą.', title_pt = 'Chá quente e silêncio 🍵', body_pt = 'O temporizador parou, ele adormeceu. Não corra para as tarefas da casa! Prepare um café especial das Receitas Saudáveis, deite-se no sofá e saboreie apenas o silêncio.', title_sv = 'Varmt te och tystnad 🍵', body_sv = 'Timern har stannat, barnet sover. Rusa inte till hushållssysslorna! Gör ett speciellt kaffe från Hälsosamma recept, lägg dig på soffan och njut bara av tystnaden.', title_vi = 'Trà nóng và sự yên tĩnh 🍵', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Đừng vội lao vào việc nhà! Hãy pha một ly cà phê đặc biệt từ Công thức lành mạnh, nằm dài trên sofa và tận hưởng sự yên tĩnh.', title_zh = '热茶与安静 🍵', body_zh = '计时器停了，孩子睡着了。别急着去做家务！从健康食谱里做一杯特别的咖啡，躺在沙发上，好好享受这份安静。' WHERE id = '32443a45-bb1d-40cd-8cbf-77a3eda300d7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ayudante de limpieza 🧹', body_es = '¿Cuando barres, él limpia con un trapo o ataca la aspiradora? Decora ya esta imitación tan graciosa con las pegatinas de la Sesión de fotos del bebé y súbela al álbum.', title_fr = 'Petit assistant ménage 🧹', body_fr = 'Quand vous balayez, il essuie avec un chiffon ou attaque l''aspirateur ? Décorez tout de suite cette imitation rigolote avec les stickers de la Séance photo bébé et ajoutez-la à l''album.', title_hi = 'सफ़ाई का मददगार 🧹', body_hi = 'आप कमरे में झाड़ू लगाती हैं तो वह कपड़े से पोंछता है या वैक्यूम क्लीनर पर हमला करता है? इस मज़ेदार नकल को तुरंत बेबी फ़ोटोशूट के स्टिकर से सजाकर एल्बम में अपलोड कीजिए।', title_id = 'Asisten bersih-bersih 🧹', body_id = 'Saat Anda menyapu kamar, ia ikut mengelap dengan kain atau menyerang penyedot debu? Segera hiasi tingkah meniru yang lucu ini dengan stiker dari Sesi Foto Bayi dan unggah ke album.', title_ja = 'お掃除のお手伝いさん 🧹', body_ja = 'あなたが部屋を掃くと、お子さんも布で拭いたり、掃除機にとびかかったりしていますか？このおもしろいまねっこを、すぐに「ベビーフォトセッション」のステッカーで飾って、アルバムにアップしましょう。', title_ko = '청소 도우미 🧹', body_ko = '엄마가 방을 쓸 때 아이도 걸레로 닦거나 청소기에 덤벼드나요? 이 웃긴 따라 하기를 바로 아기 사진 촬영의 스티커로 꾸며 앨범에 올려 보세요.', title_nl = 'Hulpje bij het schoonmaken 🧹', body_nl = 'Veegt hij met een doekje als jij de kamer veegt, of valt hij de stofzuiger aan? Versier dit grappige nadoen meteen met stickers in Babyfotoshoot en zet het in het album.', title_pl = 'Mały pomocnik w sprzątaniu 🧹', body_pl = 'Gdy zamiatasz, on wyciera ściereczką albo atakuje odkurzacz? Od razu ozdób to zabawne naśladowanie naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'Ajudante das limpezas 🧹', body_pt = 'Enquanto varre o quarto, ele limpa com um pano ou ataca o aspirador? Decore já esta imitação divertida com os autocolantes da Sessão Fotográfica do Bebé e carregue-a no álbum.', title_sv = 'Städhjälpen 🧹', body_sv = 'Torkar barnet med en trasa när du sopar, eller attackerar dammsugaren? Dekorera det roliga härmandet direkt med klistermärken i Babyfotografering och ladda upp det i albumet.', title_vi = 'Trợ thủ dọn dẹp 🧹', body_vi = 'Mẹ quét nhà thì bé cầm khăn lau, hay "tấn công" máy hút bụi? Hãy trang trí ngay màn bắt chước hài hước này bằng sticker trong Chụp ảnh cho bé và tải lên album.', title_zh = '打扫小帮手 🧹', body_zh = '你扫地时，宝宝也拿抹布擦，或者去“攻击”吸尘器？马上用宝宝写真里的贴纸装饰这个搞笑的模仿，上传到相册。' WHERE id = '53d8ad5e-ba3b-4f31-a266-650eb5f83382' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisión de las reservas de hierro 🥩', body_es = 'Para que tu peque tan activo no tenga anemia, comprueba en el Seguimiento de tomas el hierro de hoy (carne, legumbres) y actualiza su menú.', title_fr = 'Contrôle des réserves de fer 🥩', body_fr = 'Pour que votre petit plein d''énergie ne manque pas de fer, vérifiez dans le Suivi des repas ses apports en fer du jour (viande, légumineuses) et mettez son menu à jour.', title_hi = 'आयरन के भंडार की जाँच 🥩', body_hi = 'चंचल नन्हे को खून की कमी न हो, इसके लिए फ़ीडिंग ट्रैकर में आज का आयरन (मांस, दालें) जाँचिए और मेन्यू अपडेट कीजिए।', title_id = 'Cek cadangan zat besi 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia, cek asupan zat besi hari ini (daging, kacang-kacangan) di alat Pemantau Nutrisi dan perbarui menunya.', title_ja = '鉄分チェック 🥩', body_ja = '活発なお子さんが貧血にならないよう、「栄養管理ツール」で今日の鉄分（お肉、豆類）の摂取量を確認して、メニューを見直しましょう。', title_ko = '철분 확인 🥩', body_ko = '활발한 아이가 빈혈을 겪지 않도록 수유 기록 도구로 오늘의 철분 섭취(고기, 콩류)를 확인하고 식단을 업데이트하세요.', title_nl = 'IJzervoorraad checken 🥩', body_nl = 'Controleer in de Voedingstracker het ijzer van vandaag (vlees, peulvruchten) en pas het menu aan, zodat je actieve kleintje geen bloedarmoede krijgt.', title_pl = 'Kontrola zapasu żelaza 🥩', body_pl = 'Aby ruchliwy maluch nie miał anemii, sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza (mięso, rośliny strączkowe) i odśwież menu.', title_pt = 'Verificar as reservas de ferro 🥩', body_pt = 'Para que o seu pequenino tão ativo não tenha anemia, verifique no Registo de Alimentação o ferro de hoje (carne, leguminosas) e atualize a ementa.', title_sv = 'Kontroll av järnförrådet 🥩', body_sv = 'För att din aktiva lilla inte ska få blodbrist, kontrollera dagens järnintag (kött, baljväxter) i Matningskoll och uppdatera menyn.', title_vi = 'Kiểm tra kho sắt 🥩', body_vi = 'Để bé hiếu động không bị thiếu máu, hãy kiểm tra lượng sắt (thịt, các loại đậu) hôm nay trong Theo dõi cữ bú và làm mới thực đơn.', title_zh = '铁储备检查 🥩', body_zh = '为了让好动的小家伙不贫血，在喂养记录工具里查看今天的铁（肉类、豆类）摄入量，更新一下菜单。' WHERE id = '9d0ac1c5-216f-4fa0-95d2-f983474b4839' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de decir «¡No!» 🛑', body_es = '¿Dice «no» a todo? No es ir contra ti, es descubrir su propia personalidad. Rompe su tozudez ofreciéndole elegir entre dos opciones en lugar de preguntas cerradas.', title_fr = 'L''art de dire « Non ! » 🛑', body_fr = 'Il dit non à tout ? Ce n''est pas contre vous, il découvre sa propre personnalité. Désamorcez son entêtement en lui proposant deux options plutôt que des questions fermées.', title_hi = '''नहीं!'' कहने की कला 🛑', body_hi = 'हर बात पर ''नहीं'' कहता है? यह आपका विरोध नहीं, अपनी पहचान की खोज है। उससे हाँ-ना वाले सवाल नहीं, दो विकल्पों वाले चुनाव देकर उसकी ज़िद तोड़िए।', title_id = 'Seni berkata Tidak! 🛑', body_id = 'Selalu bilang tidak? Ini bukan melawan Anda, melainkan menemukan jati dirinya. Luluhkan sikap keras kepalanya dengan memberi dua pilihan, bukan pertanyaan ya/tidak.', title_ja = '「いや！」と言う力 🛑', body_ja = 'なんにでも「いや」と言いますか？これはあなたへの反抗ではなく、自分らしさの発見です。「はい・いいえ」で答える質問ではなく、2択の選択肢をあげて、こだわりをほぐしましょう。', title_ko = '''싫어!''라고 말하는 기술 🛑', body_ko = '뭐든 ''싫어''라고 하나요? 엄마에게 맞서는 게 아니라 자기 개성을 발견하는 중이에요. 예/아니요 질문 대신 두 가지 중 고르게 해서 고집을 풀어 주세요.', title_nl = 'De kunst van nee! zeggen 🛑', body_nl = 'Zegt hij overal nee tegen? Dat is niet tegen jou ingaan, maar zijn eigen persoonlijkheid ontdekken. Breek zijn koppigheid door hem geen gesloten vragen te stellen, maar te laten kiezen uit twee opties.', title_pl = 'Sztuka mówienia „Nie!” 🛑', body_pl = 'Na wszystko mówi „nie”? To nie sprzeciw wobec ciebie, tylko odkrywanie własnej osobowości. Przełam jego upór, dając mu wybór z dwóch opcji zamiast pytań zamkniętych.', title_pt = 'A arte de dizer "Não!" 🛑', body_pt = 'Diz que não a tudo? Não é estar contra si, é descobrir a sua própria individualidade. Em vez de perguntas fechadas, dê-lhe escolhas com duas opções e quebre a teimosia.', title_sv = 'Konsten att säga ”Nej!” 🛑', body_sv = 'Säger barnet nej till allt? Det handlar inte om att gå emot dig, utan om att upptäcka sin egen personlighet. Bryt envisheten genom att ge två alternativ i stället för slutna frågor.', title_vi = 'Nghệ thuật nói "Không!" 🛑', body_vi = 'Bé nói không với mọi thứ? Đó không phải chống đối mẹ mà là bé đang khám phá cá tính riêng. Hãy đưa ra hai lựa chọn thay vì câu hỏi đóng để hóa giải sự bướng bỉnh.', title_zh = '说“不！”的艺术 🛑', body_zh = '什么都说不？这不是在跟你作对，而是在发现自己的个性。别问是非题，给两个选项让宝宝挑，化解倔强。' WHERE id = '5e9c412f-bcfb-4d5e-a447-66eebbf03e51' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se te ha vuelto a olvidar?', body_es = 'No guardes en la cabeza cada cosita que se acaba en casa: añádela al momento a la Lista de la compra y que tu pareja se encargue.', title_fr = 'Votre mémoire vous a encore lâchée ?', body_fr = 'Ne gardez pas en tête chaque petite chose qui manque à la maison : ajoutez-la tout de suite à la Liste de courses et laissez votre conjoint s''en charger.', title_hi = 'याददाश्त ने फिर धोखा दिया?', body_hi = 'घर में खत्म होने वाली हर छोटी चीज़ दिमाग में मत रखिए, तुरंत शॉपिंग लिस्ट में डालिए, आपके जीवनसाथी संभाल लेंगे।', title_id = 'Lupa lagi?', body_id = 'Tak perlu mengingat setiap barang kecil yang habis di rumah, langsung masukkan ke Daftar Belanja dan biarkan pasangan Anda yang mengurusnya.', title_ja = 'またもの忘れ？', body_ja = '家で切れた細かいものを頭で覚えておかないで、すぐに「買い物リスト」に入れて、パートナーに任せましょう。', title_ko = '또 깜빡하셨나요?', body_ko = '집에 떨어진 자잘한 물건까지 머릿속에 담아 두지 말고 바로 쇼핑 목록에 넣어 배우자에게 맡기세요.', title_nl = 'Laat je geheugen je weer in de steek?', body_nl = 'Onthoud niet elk klein ding dat thuis op is, maar zet het meteen op het Boodschappenlijstje en laat je partner het regelen.', title_pl = 'Pamięć znów zawiodła?', body_pl = 'Nie trzymaj w głowie każdej drobnostki, która skończyła się w domu. Od razu dodaj ją do Listy zakupów, a partner się tym zajmie.', title_pt = 'A memória voltou a falhar?', body_pt = 'Não guarde na cabeça cada coisinha que acaba em casa: ponha-a logo na Lista de Compras e o seu companheiro trata disso.', title_sv = 'Svek minnet dig igen?', body_sv = 'Håll inte varje liten sak som tagit slut hemma i huvudet, lägg den direkt i Inköpslistan och låt din partner ta hand om det.', title_vi = 'Mẹ lại quên mất rồi?', body_vi = 'Đừng cố nhớ từng món lặt vặt sắp hết trong nhà, hãy thêm ngay vào Danh sách mua sắm để bố lo.', title_zh = '记性又忘事了？', body_zh = '家里用完的小东西别都记在脑子里，马上丢进购物清单，让另一半去搞定。' WHERE id = '64707418-d2a0-43f8-b7ef-86936fa426fe' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de saltar 🦘', body_es = '¡Los sofás ya se le quedan pequeños! Busca un centro de ocio cubierto y seguro con cama elástica y ayúdale a gastar energía.', title_fr = 'L''art de sauter 🦘', body_fr = 'Les canapés ne lui suffisent plus ! Trouvez un centre de loisirs couvert et sûr avec trampoline et aidez-le à se dépenser.', title_hi = 'कूदने की कला 🦘', body_hi = 'अब सोफ़े उसके लिए काफ़ी नहीं! ट्रैम्पोलिन वाला सुरक्षित इनडोर फ़न सेंटर ढूँढिए और उसकी ऊर्जा निकालने में मदद कीजिए।', title_id = 'Seni melompat 🦘', body_id = 'Sofa sudah tak cukup lagi untuknya! Temukan pusat hiburan dalam ruangan yang aman dengan trampolin dan bantu ia menyalurkan energinya.', title_ja = 'ジャンプの達人 🦘', body_ja = 'もうソファでは物足りない！トランポリンのある安全な屋内の遊び場を見つけて、エネルギーを発散させてあげましょう。', title_ko = '점프의 기술 🦘', body_ko = '이제 소파로는 부족해요! 트램펄린이 있는 안전한 실내 놀이 센터를 찾아 에너지를 발산하도록 도와주세요.', title_nl = 'De kunst van springen 🦘', body_nl = 'De banken zijn niet meer genoeg voor hem! Zoek een veilig overdekt speelcentrum met een trampoline en help hem zijn energie kwijt te raken.', title_pl = 'Sztuka skakania 🦘', body_pl = 'Kanapy już mu nie wystarczają! Znajdź bezpieczne kryte centrum rozrywki z trampoliną i pomóż mu rozładować energię.', title_pt = 'A arte de saltar 🦘', body_pt = 'Os sofás já não lhe chegam! Encontre um centro de diversões interior e seguro, com trampolim, e ajude-o a gastar energia.', title_sv = 'Konsten att hoppa 🦘', body_sv = 'Soffan räcker inte längre! Hitta en säker inomhuslekplats med studsmatta och hjälp barnet att få ut energin.', title_vi = 'Nghệ thuật nhảy nhót 🦘', body_vi = 'Sofa đã không đủ cho bé! Hãy tìm một trung tâm vui chơi trong nhà an toàn có bạt nhún để giúp bé xả năng lượng.', title_zh = '蹦跳的艺术 🦘', body_zh = '沙发已经不够宝宝蹦了！找一个有蹦床的安全室内游乐中心，帮宝宝释放精力吧。' WHERE id = '8f01b040-4aa3-4a5f-a127-4287f88b0ef1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño artista en acción 🎨', body_es = '¿Jugando con colores se ha pintado toda la cara? En lugar de enfadarte, disfruta de este momento creativo y divertido.', title_fr = 'Petit artiste au travail 🎨', body_fr = 'En jouant avec les couleurs, il s''en est mis plein le visage ? Au lieu de vous énerver, savourez ce moment drôle et créatif.', title_hi = 'नन्हा चित्रकार काम पर 🎨', body_hi = 'रंगों से खेलते हुए पूरा चेहरा रंग लिया? गुस्सा होने के बजाय इस मज़ेदार, रचनात्मक पल का मज़ा लीजिए।', title_id = 'Pelukis cilik sedang beraksi 🎨', body_id = 'Wajahnya penuh cat saat bermain warna? Daripada kesal, nikmati momen lucu dan kreatif ini.', title_ja = '小さな画家が作業中 🎨', body_ja = '色で遊んでいて、顔じゅう絵の具だらけに？怒る代わりに、このおもしろくて創造的な瞬間を楽しみましょう。', title_ko = '꼬마 화가 작업 중 🎨', body_ko = '물감 놀이를 하다 얼굴이 온통 물감투성이가 되었나요? 화내는 대신 이 재미있고 창의적인 순간을 즐겨 보세요.', title_nl = 'Kleine kunstenaar aan het werk 🎨', body_nl = 'Zit zijn hele gezicht onder de verf na het spelen met kleuren? Word niet boos, maar geniet van dit grappige, creatieve moment.', title_pl = 'Mały artysta przy pracy 🎨', body_pl = 'Bawiąc się farbami, umazał całą buzię? Zamiast się złościć, ciesz się tą zabawną, twórczą chwilą.', title_pt = 'Pequeno artista em ação 🎨', body_pt = 'A brincar com as cores, sujou a cara toda? Em vez de se enervar, aproveite este momento divertido e criativo.', title_sv = 'Den lilla konstnären i farten 🎨', body_sv = 'Har barnet kladdat ner hela ansiktet när hen lekte med färger? I stället för att bli irriterad, njut av det roliga och kreativa ögonblicket.', title_vi = 'Họa sĩ nhí đang làm việc 🎨', body_vi = 'Chơi màu mà lem luốc cả mặt mũi? Thay vì bực mình, hãy tận hưởng khoảnh khắc sáng tạo vui nhộn này.', title_zh = '小画家上班啦 🎨', body_zh = '玩颜料时把脸都涂花了？与其生气，不如好好享受这个有趣又有创意的时刻。' WHERE id = 'cf348bab-0260-4da9-bc53-4069f0a6ddf3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelven los despertares nocturnos? ⏱️', body_es = '¿Se despierta llorando a medianoche y le cuesta volver a dormirse? Analiza las estadísticas del temporizador de sueño. Puede ser la regresión del sueño de los 2 años o los dientes.', title_fr = 'Les réveils nocturnes sont de retour ? ⏱️', body_fr = 'Il se réveille en pleurant au milieu de la nuit et a du mal à se rendormir ? Analysez les statistiques du minuteur de sommeil. La régression du sommeil des 2 ans ou les dents peuvent en être la cause.', title_hi = 'रात में जागना फिर शुरू? ⏱️', body_hi = 'आधी रात को रोते हुए जागता है और मुश्किल से सोता है? स्लीप टाइमर के आँकड़ों का विश्लेषण कीजिए। वजह 2 साल का स्लीप रिग्रेशन या दाँत हो सकते हैं।', title_id = 'Sering terbangun malam lagi? ⏱️', body_id = 'Terbangun sambil menangis di tengah malam dan sulit tidur lagi? Analisis statistik Timer Tidur. Penyebabnya bisa regresi tidur usia 2 tahun atau gigi yang tumbuh.', title_ja = '夜中に起きるのが復活？⏱️', body_ja = '夜中に泣いて起きて、なかなか寝つけない？睡眠タイマーの統計を分析しましょう。2歳の睡眠退行や歯が原因かもしれません。', title_ko = '밤에 다시 깨나요? ⏱️', body_ko = '한밤중에 울며 깨서 다시 잠들기 힘들어하나요? 수면 타이머 통계를 분석해 보세요. 두 돌 수면 퇴행이나 이앓이가 원인일 수 있어요.', title_nl = 'Wordt hij weer ''s nachts wakker? ⏱️', body_nl = 'Wordt hij midden in de nacht huilend wakker en valt hij moeilijk weer in slaap? Analyseer de statistieken van de Slaaptimer. De slaapregressie van 2 jaar of tandjes kunnen de oorzaak zijn.', title_pl = 'Nocne pobudki wróciły? ⏱️', body_pl = 'Budzi się z płaczem w środku nocy i trudno mu znów zasnąć? Przeanalizuj statystyki timera snu. Przyczyną może być regres snu 2-latka albo ząbki.', title_pt = 'Os despertares noturnos voltaram? ⏱️', body_pt = 'Acorda a chorar a meio da noite e custa-lhe voltar a adormecer? Analise as estatísticas do temporizador de sono. A causa pode ser a regressão do sono dos 2 anos ou os dentes.', title_sv = 'Nattliga uppvaknanden igen? ⏱️', body_sv = 'Vaknar barnet gråtande mitt i natten och har svårt att somna om? Analysera statistiken i sömntimern. Sömnregressionen vid 2 år eller tänderna kan vara orsaken.', title_vi = 'Bé lại thức giấc ban đêm? ⏱️', body_vi = 'Bé khóc thức giấc lúc nửa đêm và khó ngủ lại? Hãy phân tích thống kê của Bộ hẹn giờ ngủ. Nguyên nhân có thể là thoái lui giấc ngủ tuổi lên 2 hoặc mọc răng.', title_zh = '夜醒又回来了？⏱️', body_zh = '半夜哭着醒来，很难再睡着？分析一下睡眠计时器的统计。可能是2岁睡眠倒退或者出牙引起的。' WHERE id = 'd6dd1818-c4fb-46af-be6f-20980791db71' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calmante natural 🍃', body_es = '¿Ha sido un día muy ruidoso y lleno de carreras? Oscurece la habitación, pon el murmullo del río de Ruido blanco y regala un masaje a su mente y a la tuya.', title_fr = 'Un apaisant naturel 🍃', body_fr = 'Une journée bruyante et pleine de courses ? Faites l''obscurité, lancez le murmure de la rivière des Bruits blancs et massez son cerveau comme le vôtre.', title_hi = 'कुदरती सुकून 🍃', body_hi = 'बहुत शोर और भाग-दौड़ भरा दिन था? कमरे में अँधेरा कीजिए, व्हाइट नॉइज़ में नदी की कलकल लगाइए और उसके और अपने, दोनों के दिमाग को आराम दीजिए।', title_id = 'Penenang alami 🍃', body_id = 'Hari yang bising dan penuh kejar-kejaran? Gelapkan kamar, putar suara gemericik sungai dari Suara Putih, dan tenangkan pikiran ia dan Anda.', title_ja = '自然のリラックス効果 🍃', body_ja = 'にぎやかで走り回った一日でしたか？部屋を暗くして、「ホワイトノイズ」の小川のせせらぎを流し、お子さんとあなたの頭をやさしくほぐしましょう。', title_ko = '자연의 진정제 🍃', body_ko = '시끄럽고 정신없는 하루였나요? 방을 어둡게 하고 백색소음에서 시냇물 소리를 틀어 아이와 엄마의 머리를 함께 쉬게 해 주세요.', title_nl = 'Natuurlijke rustgever 🍃', body_nl = 'Was het een lawaaierige, drukke dag? Verduister de kamer, zet het kabbelen van een beekje uit Witte ruis aan en geef zijn hoofdje en dat van jezelf een massage.', title_pl = 'Naturalne ukojenie 🍃', body_pl = 'To był bardzo głośny dzień pełen bieganiny? Zaciemnij pokój, włącz szum strumienia z Białego szumu i ukój umysł jego i swój.', title_pt = 'Calmante natural 🍃', body_pt = 'Foi um dia muito barulhento e cheio de correria? Escureça o quarto, ligue o murmúrio do rio do Ruído Branco e faça uma massagem ao cérebro dele e ao seu.', title_sv = 'Naturligt lugnande 🍃', body_sv = 'Har dagen varit full av buller och springande? Mörklägg rummet, sätt på bäckens porlande från Vitt brus och ge både barnets och din egen hjärna en massage.', title_vi = 'Liều thuốc an thần tự nhiên 🍃', body_vi = 'Một ngày quá ồn ào và chạy nhảy? Hãy làm tối phòng, bật tiếng suối chảy trong Tiếng ồn trắng để thư giãn đầu óc cho cả bé lẫn mẹ.', title_zh = '天然的镇静剂 🍃', body_zh = '今天又吵又跑，闹腾了一整天？把房间调暗，打开白噪音里的溪流声，给宝宝和你自己的大脑都做个按摩。' WHERE id = '1d5cbb75-8a18-4083-a6e5-10d5b00dd31c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Unos músculos tan activos necesitan proteínas. Mide con el Seguimiento de tomas el equilibrio de su alimentación diaria y enriquece su menú.', body_fr = 'Les protéines sont indispensables à des muscles actifs. Mesurez son équilibre alimentaire du jour avec le Suivi des repas et enrichissez son menu.', body_hi = 'चंचल मांसपेशियों के लिए प्रोटीन ज़रूरी है। फ़ीडिंग ट्रैकर से उसके रोज़ के खाने का संतुलन मापिए और मेन्यू को और पौष्टिक बनाइए।', body_id = 'Otot yang aktif butuh protein. Ukur keseimbangan nutrisi hariannya dengan alat Pemantau Nutrisi dan perkaya menunya.', body_ja = '活発に動く筋肉には、たんぱく質が欠かせません。「栄養管理ツール」で1日の栄養バランスを確認して、メニューを豊かにしましょう。', body_ko = '활발한 근육에는 단백질이 꼭 필요해요. 수유 기록 도구로 하루 영양 균형을 확인하고 식단을 더 풍성하게 만들어 주세요.', body_nl = 'Eiwit is onmisbaar voor actieve spieren. Meet met de Voedingstracker zijn dagelijkse voedingsbalans en maak zijn menu rijker.', body_pl = 'Białko jest niezbędne dla aktywnych mięśni. Sprawdź w narzędziu do śledzenia karmienia jego dzienny bilans żywieniowy i wzbogać menu.', body_pt = 'Músculos ativos precisam de proteína. Meça com o Registo de Alimentação o equilíbrio alimentar diário e enriqueça a ementa.', body_sv = 'Aktiva muskler behöver protein. Mät barnets dagliga näringsbalans med Matningskoll och gör menyn mer varierad.', body_vi = 'Cơ bắp hoạt động nhiều rất cần đạm. Hãy đo cân bằng dinh dưỡng hằng ngày của bé bằng Theo dõi cữ bú và làm thực đơn thêm phong phú.', body_zh = '活力满满的肌肉离不开蛋白质。用喂养记录工具衡量宝宝每天的饮食平衡，让菜单更丰富。' WHERE id = '947b2874-60ed-46dc-82cb-4ddf972a50b1' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Canciones favoritas 🎤', body_es = '¿Canta o tararea la misma canción sin parar? Guarda este sentido del ritmo y su desarrollo del lenguaje añadiéndolo al álbum con las pegatinas musicales de la Sesión de fotos del bebé.', title_fr = 'Chansons préférées 🎤', body_fr = 'Il chante ou fredonne la même chanson en boucle ? Célébrez son sens du rythme et son langage en ajoutant ce moment à l''album avec les stickers musicaux de la Séance photo bébé.', title_hi = 'पसंदीदा गाने 🎤', body_hi = 'एक ही गाना बार-बार गाता या गुनगुनाता है? लय की इस समझ और भाषा के विकास को बेबी फ़ोटोशूट के म्यूज़िक स्टिकर के साथ एल्बम में जोड़कर याद बनाइए।', title_id = 'Lagu-lagu favorit 🎤', body_id = 'Menyanyikan atau menggumamkan lagu yang sama tanpa henti? Abadikan rasa ritme dan perkembangan bahasanya dengan menambahkan ke album memakai stiker musik dari Sesi Foto Bayi.', title_ja = 'お気に入りの歌 🎤', body_ja = '同じ歌を何度も歌ったり、口ずさんだりしていますか？このリズム感と言葉の発達を、「ベビーフォトセッション」の音楽ステッカーで飾ってアルバムに追加し、記録しましょう。', title_ko = '좋아하는 노래 🎤', body_ko = '같은 노래를 쉬지 않고 부르거나 흥얼거리나요? 이 리듬감과 언어 발달을 아기 사진 촬영의 음악 스티커로 꾸며 앨범에 기록해 두세요.', title_nl = 'Lievelingsliedjes 🎤', body_nl = 'Zingt of neuriet hij steeds maar hetzelfde liedje? Leg dit gevoel voor ritme en zijn taalontwikkeling vast in het album met muziekstickers uit Babyfotoshoot.', title_pl = 'Ulubione piosenki 🎤', body_pl = 'Śpiewa albo nuci w kółko tę samą piosenkę? Uwiecznij to poczucie rytmu i rozwój mowy, dodając zdjęcie do albumu z muzycznymi naklejkami z Sesji zdjęciowej dziecka.', title_pt = 'Canções preferidas 🎤', body_pt = 'Canta ou trauteia a mesma canção sem parar? Registe este sentido de ritmo e desenvolvimento da linguagem, adicionando-o ao álbum com os autocolantes de música da Sessão Fotográfica do Bebé.', title_sv = 'Favoritsånger 🎤', body_sv = 'Sjunger eller nynnar barnet samma sång om och om igen? Spara rytmkänslan och språkutvecklingen i albumet med musikklistermärken i Babyfotografering.', title_vi = 'Những bài hát yêu thích 🎤', body_vi = 'Bé hát hay ngân nga mãi một bài? Hãy lưu lại cảm nhận nhịp điệu và sự phát triển ngôn ngữ này vào album cùng sticker âm nhạc trong Chụp ảnh cho bé.', title_zh = '最爱的歌 🎤', body_zh = '一直唱同一首歌，或者哼个不停？用宝宝写真里的音乐贴纸，把这份节奏感和语言发展记录到相册里。' WHERE id = 'f56b8fb7-fe66-42a7-afb0-9342dd02a543' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Rebelión contra la siesta! 🛌', body_es = '¿No quiere dormir la siesta y sale corriendo? Pregunta a Anacan AI por las necesidades de sueño a los 2 años y los secretos para crear un rato de calma.', title_fr = 'Révolte contre la sieste ! 🛌', body_fr = 'Il ne veut pas faire la sieste et s''enfuit ? Demandez à Anacan AI quels sont les besoins de sommeil à 2 ans et ses secrets pour instaurer un temps calme.', title_hi = 'दिन की नींद से बगावत! 🛌', body_hi = 'दोपहर में सोना नहीं चाहता और भाग जाता है? Anacan AI से 2 साल के बच्चों की नींद की ज़रूरतों और शांत समय (क्वाइट टाइम) बनाने के राज़ पूछिए।', title_id = 'Memberontak saat tidur siang! 🛌', body_id = 'Tidak mau tidur siang dan malah kabur? Tanyakan kepada Anacan AI tentang kebutuhan tidur anak usia 2 tahun dan rahasia menciptakan waktu tenang (quiet time).', title_ja = 'お昼寝への反乱！🛌', body_ja = 'お昼に寝たがらず、逃げ回りますか？2歳の子に必要な睡眠と、静かに過ごす時間（クワイエットタイム）をつくるコツを、Anacan AIに聞いてみましょう。', title_ko = '낮잠 반란! 🛌', body_ko = '낮잠을 안 자려고 도망가나요? Anacan AI에게 두 살 아이의 수면 필요량과 조용한 시간(quiet time)을 만드는 비결을 물어보세요.', title_nl = 'Opstand tegen het middagdutje! 🛌', body_nl = 'Wil hij ''s middags niet slapen en rent hij weg? Vraag Anacan AI naar de slaapbehoefte van tweejarigen en de geheimen van een rustmoment (quiet time).', title_pl = 'Bunt przeciw drzemce! 🛌', body_pl = 'W południe nie chce spać i ucieka? Zapytaj Anacan AI o potrzeby snu 2-latków i sekrety wprowadzania czasu wyciszenia.', title_pt = 'Revolta contra a sesta! 🛌', body_pt = 'Não quer dormir à tarde e foge? Pergunte ao Anacan AI quais são as necessidades de sono aos 2 anos e os segredos para criar um tempo calmo (quiet time).', title_sv = 'Uppror mot dagsömnen! 🛌', body_sv = 'Vill barnet inte sova middag och springer iväg? Fråga Anacan AI om 2-åringars sömnbehov och hemligheterna med att skapa en lugn stund (quiet time).', title_vi = 'Nổi loạn với giấc ngủ ngày! 🛌', body_vi = 'Buổi trưa bé không muốn ngủ và chạy đi? Hãy hỏi Anacan AI về nhu cầu ngủ của trẻ 2 tuổi và bí quyết tạo "giờ yên tĩnh" (quiet time).', title_zh = '反抗午睡！🛌', body_zh = '中午不想睡，还到处跑？问问Anacan AI，了解2岁宝宝的睡眠需求，以及营造安静时间（quiet time）的秘诀。' WHERE id = '0963259b-f909-4657-ae5e-475b63d595ec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Experto en desvestirse! 🧦', body_es = '¿Intenta quitarse él solo los calcetines o los pantalones? Es un gran avance de su motricidad.', title_fr = 'Expert du déshabillage ! 🧦', body_fr = 'Il essaie d''enlever tout seul ses chaussettes ou son pantalon ? C''est un très beau progrès de motricité.', title_hi = 'कपड़े उतारने का एक्सपर्ट! 🧦', body_hi = 'खुद से मोज़े या पैंट उतारने की कोशिश करता है? यह मोटर स्किल्स का शानदार विकास है।', title_id = 'Ahli melepas baju! 🧦', body_id = 'Mencoba melepas kaus kaki atau celananya sendiri? Ini perkembangan motorik yang hebat.', title_ja = 'お着替え脱ぎの名人！🧦', body_ja = '自分で靴下やズボンを脱ごうとしていますか？これはすばらしい運動能力の発達です。', title_ko = '옷 벗기 전문가! 🧦', body_ko = '혼자 양말이나 바지를 벗으려고 하나요? 소근육이 멋지게 발달하고 있다는 신호예요.', title_nl = 'Expert in uitkleden! 🧦', body_nl = 'Probeert hij zelf zijn sokken of broek uit te trekken? Dat is een geweldige motorische ontwikkeling.', title_pl = 'Ekspert od rozbierania! 🧦', body_pl = 'Próbuje sam zdjąć skarpetki albo spodnie? To świetny rozwój motoryki.', title_pt = 'Especialista em despir-se! 🧦', body_pt = 'Tenta tirar sozinho as meias ou as calças? É um ótimo desenvolvimento motor.', title_sv = 'Expert på att klä av sig! 🧦', body_sv = 'Försöker barnet själv ta av sig strumporna eller byxorna? Det är fin motorisk utveckling.', title_vi = 'Chuyên gia cởi đồ! 🧦', body_vi = 'Bé tự cố gắng cởi tất hoặc quần? Đây là sự phát triển vận động tuyệt vời.', title_zh = '脱衣服小专家！🧦', body_zh = '想自己脱袜子或裤子？这是很棒的动作发展。' WHERE id = '0bba2ea7-ff2c-40db-9921-cae50208c766' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El poder del jengibre 🫖', body_es = '¿Te duelen la espalda y las piernas de correr todo el día? Prepárate en Recetas saludables una infusión que relaja los músculos y descansa.', title_fr = 'La force du gingembre 🫖', body_fr = 'Vous avez mal au dos et aux jambes après avoir couru toute la journée ? Préparez une tisane qui détend les muscles avec les Recettes saines, et reposez-vous.', title_hi = 'अदरक की ताकत 🫖', body_hi = 'दिनभर भागते-भागते कमर और पैर दर्द करते हैं? सेहतमंद रेसिपी से मांसपेशियों को आराम देने वाली चाय बनाइए और आराम कीजिए।', title_id = 'Kekuatan jahe 🫖', body_id = 'Punggung dan kaki pegal karena berlari seharian? Seduh teh yang merilekskan otot dari Resep Sehat, lalu beristirahatlah.', title_ja = 'しょうがのパワー 🫖', body_ja = '一日中走り回って、腰や足が痛いですか？「ヘルシーレシピ」から、筋肉をほぐすお茶をいれて、休みましょう。', title_ko = '생강의 힘 🫖', body_ko = '하루 종일 뛰어다니느라 허리와 다리가 아프나요? 건강한 레시피에서 근육을 풀어 주는 차를 우려 쉬세요.', title_nl = 'De kracht van gember 🫖', body_nl = 'Doen je rug en benen pijn van de hele dag rennen? Zet een thee uit Gezonde recepten die je spieren ontspant, en rust uit.', title_pl = 'Moc imbiru 🫖', body_pl = 'Plecy i nogi bolą cię od całodziennej bieganiny? Zaparz ze Zdrowych przepisów herbatę rozluźniającą mięśnie i odpocznij.', title_pt = 'A força do gengibre 🫖', body_pt = 'As costas e as pernas doem-lhe de correr o dia todo? Prepare um chá das Receitas Saudáveis que relaxa os músculos e descanse.', title_sv = 'Ingefärans kraft 🫖', body_sv = 'Gör ryggen och benen ont efter en hel dag av springande? Brygg ett te som får musklerna att slappna av från Hälsosamma recept och vila.', title_vi = 'Sức mạnh của gừng 🫖', body_vi = 'Chạy nhảy cả ngày khiến lưng và chân mẹ đau nhức? Hãy pha một tách trà giúp thư giãn cơ từ Công thức lành mạnh và nghỉ ngơi.', title_zh = '生姜的力量 🫖', body_zh = '跑了一整天，腰和腿都疼？从健康食谱里泡一杯放松肌肉的茶，休息一下吧。' WHERE id = '160a2dee-dfe4-4a75-b257-c4a10c478741' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Observamos los pájaros 🕊️', body_es = '¿Se ha agobiado mucho en casa? Busca un parque con mucho verde y refuerza su empatía con la naturaleza dando de comer a los pájaros.', title_fr = 'On observe les oiseaux 🕊️', body_fr = 'Il s''ennuie à la maison ? Trouvez un parc verdoyant et renforcez son empathie pour la nature en donnant des graines aux oiseaux.', title_hi = 'चिड़ियों को देखें 🕊️', body_hi = 'घर में बहुत ऊब गया? हरियाली वाला पार्क ढूँढिए और चिड़ियों को दाना डालकर प्रकृति के प्रति उसकी हमदर्दी बढ़ाइए।', title_id = 'Mengamati burung 🕊️', body_id = 'Sangat bosan di rumah? Temukan taman yang hijau dan perkuat empatinya pada alam dengan memberi makan burung.', title_ja = '鳥を観察しよう 🕊️', body_ja = '家の中で退屈してしまった？緑の多い公園を見つけて、鳥にえさをあげながら、自然への思いやりの心を育てましょう。', title_ko = '새를 관찰해요 🕊️', body_ko = '집에서 너무 답답했나요? 푸른 공원을 찾아 새에게 모이를 주며 자연을 향한 공감을 키워 주세요.', title_nl = 'Vogels kijken 🕊️', body_nl = 'Verveelt hij zich thuis? Zoek een groen park en versterk zijn band met de natuur door samen de vogels te voeren.', title_pl = 'Obserwujemy ptaki 🕊️', body_pl = 'Znudził się w domu? Znajdź zielony park i karmiąc ptaki ziarnem, wzmacniaj jego empatię wobec przyrody.', title_pt = 'A observar os pássaros 🕊️', body_pt = 'Aborreceu-se muito em casa? Encontre um parque verde e reforcem a empatia pela natureza dando de comer aos pássaros.', title_sv = 'Vi tittar på fåglar 🕊️', body_sv = 'Har barnet tråkigt hemma? Hitta en grön park och mata fåglarna för att stärka barnets empati med naturen.', title_vi = 'Cùng ngắm chim 🕊️', body_vi = 'Bé chán ở nhà? Hãy tìm một công viên nhiều cây xanh và cho chim ăn để nuôi dưỡng tình yêu thiên nhiên của bé.', title_zh = '一起看小鸟 🕊️', body_zh = '在家闷坏了？找一个绿意盎然的公园，喂喂小鸟，增强宝宝对大自然的共情。' WHERE id = '20369d8a-500f-4d0c-8f13-a85f623e07d2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de inventar un cuento 📖', body_es = '¿Cansada de leer libros? Apaga las luces, pon el sonido de la lluvia de Ruido blanco e inventad juntos cuentos imaginarios en la oscuridad hasta quedaros dormidos.', title_fr = 'L''heure d''inventer une histoire 📖', body_fr = 'Lassée de lire des livres ? Éteignez la lumière, lancez le bruit de la pluie des Bruits blancs et inventez ensemble des contes imaginaires dans le noir jusqu''à vous endormir.', title_hi = 'कहानी गढ़ने का समय 📖', body_hi = 'किताब पढ़ते-पढ़ते ऊब गईं? बत्तियाँ बुझाइए, व्हाइट नॉइज़ में बारिश की आवाज़ लगाइए और अँधेरे में साथ मिलकर काल्पनिक कहानियाँ गढ़ते हुए सो जाइए।', title_id = 'Waktunya mengarang cerita 📖', body_id = 'Bosan membaca buku? Matikan lampu, putar suara hujan dari Suara Putih, dan karang dongeng khayalan bersama dalam gelap hingga tertidur.', title_ja = 'お話をつくる時間 📖', body_ja = '絵本を読むのに飽きましたか？電気を消して、「ホワイトノイズ」の雨の音を流し、暗い中で一緒に空想のお話をつくりながら眠りにつきましょう。', title_ko = '이야기를 지어낼 시간 📖', body_ko = '책 읽기가 지겨워졌나요? 불을 끄고 백색소음의 빗소리를 틀어 어둠 속에서 함께 상상 속 이야기를 지어내며 잠들어 보세요.', title_nl = 'Tijd om een verhaal te verzinnen 📖', body_nl = 'Ben je het voorlezen zat? Doe het licht uit, zet regengeluid uit Witte ruis aan en verzin samen in het donker fantasieverhalen tot jullie in slaap vallen.', title_pl = 'Czas wymyślać historie 📖', body_pl = 'Macie dość czytania książek? Zgaś światło, włącz odgłos deszczu z Białego szumu i wymyślajcie razem w ciemności bajki, aż zaśniecie.', title_pt = 'Hora de inventar histórias 📖', body_pt = 'Cansada de ler livros? Apague as luzes, ligue o som da chuva do Ruído Branco e inventem juntos histórias imaginárias no escuro até adormecerem.', title_sv = 'Dags att hitta på sagor 📖', body_sv = 'Trött på att läsa böcker? Släck ljuset, sätt på regnljud från Vitt brus och hitta på fantasisagor tillsammans i mörkret tills ni somnar.', title_vi = 'Giờ sáng tác truyện 📖', body_vi = 'Mẹ chán đọc sách rồi? Hãy tắt đèn, bật tiếng mưa trong Tiếng ồn trắng và cùng bé nghĩ ra những câu chuyện tưởng tượng trong bóng tối cho đến khi chìm vào giấc ngủ.', title_zh = '编故事时间 📖', body_zh = '读书读累了？关上灯，打开白噪音里的雨声，在黑暗中一起编些想象的故事，慢慢入睡。' WHERE id = '69fc5add-e558-46f8-bee8-37acee27a9c1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Vuelta al puré? 🥣', body_es = '¿Le da pereza masticar sólidos y vuelve a pedir puré? Echa un vistazo en Recetas para bebé a recetas originales de filetes rusos fáciles de masticar, pero que no son puré.', title_fr = 'Retour aux purées ? 🥣', body_fr = 'Il a la flemme de mâcher et réclame de nouveau de la purée ? Jetez un œil dans les Recettes pour bébés aux recettes de galettes faciles à mâcher, sans être des purées.', title_hi = 'फिर से प्यूरी? 🥣', body_hi = 'ठोस खाना चबाने में आलस करके फिर से प्यूरी माँगता है? बच्चों की रेसिपी में आसानी से चबाए जाने वाले, पर प्यूरी नहीं, ऐसे दिलचस्प कटलेट देखिए।', title_id = 'Kembali ke bubur? 🥣', body_id = 'Malas mengunyah makanan padat dan minta bubur lagi? Lihat resep perkedel menarik yang mudah dikunyah tapi bukan bubur di Resep Bayi.', title_ja = 'ピューレに逆戻り？🥣', body_ja = '固形食をかむのを面倒がって、またピューレをほしがりますか？「離乳食を始める赤ちゃんのレシピ」で、かみやすいけれどピューレではない、楽しいハンバーグのレシピをチェックしましょう。', title_ko = '다시 퓌레로? 🥣', body_ko = '고형식 씹기를 귀찮아하며 다시 퓌레를 찾나요? 아기 레시피에서 퓌레는 아니지만 씹기 쉬운 재미있는 커틀릿 레시피를 살펴보세요.', title_nl = 'Terug naar puree? 🥣', body_nl = 'Is hij te lui om vast eten te kauwen en wil hij weer puree? Bekijk in Babyrecepten leuke, makkelijk te kauwen gehaktschijfjes die geen puree zijn.', title_pl = 'Powrót do papek? 🥣', body_pl = 'Nie chce mu się gryźć stałych pokarmów i znów prosi o papkę? Zajrzyj w Przepisach dla niemowląt do ciekawych przepisów na kotleciki, które łatwo pogryźć, ale nie są papką.', title_pt = 'De volta ao puré? 🥣', body_pt = 'Tem preguiça de mastigar alimentos sólidos e volta a pedir puré? Espreite nas Receitas para bebés receitas interessantes de croquetes fáceis de mastigar, mas que não são puré.', title_sv = 'Tillbaka till puré? 🥣', body_sv = 'Orkar barnet inte tugga fast föda och vill ha puré igen? Titta på spännande recept på biffar som är lätta att tugga men inte puré i Recept för bebisar.', title_vi = 'Quay lại ăn cháo nghiền? 🥣', body_vi = 'Bé lười nhai thức ăn đặc và lại đòi ăn đồ nghiền? Hãy xem những công thức chả viên thú vị, dễ nhai nhưng không phải đồ nghiền trong Công thức cho bé.', title_zh = '又想吃泥糊了？🥣', body_zh = '懒得咀嚼固体食物，又想吃泥糊？看看宝宝食谱里好咀嚼又不是泥糊的有趣肉饼食谱。' WHERE id = 'd25adde2-a568-4bad-bacf-b25822698f2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se despierta gritando a medianoche y no se calma?', body_es = 'Las crisis de los 2 años también afectan al sueño. Deja que Análisis del llanto escuche su llanto y averigua con precisión cuál es el problema.', title_fr = 'Il se réveille en hurlant en pleine nuit et ne se calme pas ?', body_fr = 'Les crises des 2 ans perturbent aussi le sommeil. Faites écouter ses pleurs à l''Analyse des pleurs pour savoir précisément ce qui ne va pas.', title_hi = 'आधी रात को चीखकर जागता है और चुप नहीं होता?', body_hi = '2 साल के नखरे नींद पर भी असर डालते हैं। आवाज़ को क्राइंग एनालिसिस में सुनाइए और ठीक-ठीक जानिए कि परेशानी क्या है।', title_id = 'Terbangun menjerit tengah malam dan tak kunjung diam?', body_id = 'Krisis usia 2 tahun juga memengaruhi tidurnya. Perdengarkan suaranya ke Analisis Tangisan dan pastikan apa masalahnya.', title_ja = '夜中に叫んで起きて、泣き止まない？', body_ja = '2歳のかんしゃくは眠りにも影響します。「泣き声分析」で泣き声を聞かせて、何が問題なのかを確かめましょう。', title_ko = '한밤중에 비명을 지르며 깨서 그치지 않나요?', body_ko = '두 돌 떼쓰기는 잠에도 영향을 줘요. 울음 분석으로 소리를 들려주고 무엇이 문제인지 정확히 알아보세요.', title_nl = 'Wordt hij midden in de nacht gillend wakker en houdt hij niet op?', body_nl = 'De buien van de peuterpuberteit hebben ook invloed op de slaap. Laat Huilanalyse naar zijn geluid luisteren en ontdek precies wat er aan de hand is.', title_pl = 'Budzi się w środku nocy z krzykiem i nie przestaje?', body_pl = 'Kryzysy dwulatka wpływają też na sen. Pozwól Analizie płaczu posłuchać dźwięku i ustal, w czym problem.', title_pt = 'Acorda aos gritos a meio da noite e não se cala?', body_pt = 'As crises dos 2 anos também afetam o sono. Deixe a Análise do Choro ouvir o som e descubra qual é o problema.', title_sv = 'Vaknar barnet skrikande mitt i natten och slutar inte?', body_sv = '2-årstrotset påverkar även sömnen. Låt Gråtanalys lyssna på ljudet och ta reda på vad problemet är.', title_vi = 'Nửa đêm bé thét lên thức giấc và không chịu nín?', body_vi = 'Khủng hoảng tuổi lên 2 cũng ảnh hưởng đến giấc ngủ. Hãy cho Phân tích tiếng khóc nghe để xác định chính xác vấn đề.', title_zh = '半夜尖叫着醒来，怎么也停不下来？', body_zh = '2岁的崩溃也会影响睡眠。让哭声分析听一听哭声，弄清问题到底是什么。' WHERE id = 'd3a41958-709d-460d-ae40-910c3a69b580' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Me lo sirvo yo! 🥛', body_es = '¿Quiere servirse el agua él solo y lo moja todo? Para estas habilidades prácticas, mira en Productos recomendados vasos inteligentes antiderrames.', title_fr = 'Je me sers tout seul ! 🥛', body_fr = 'Il veut verser l''eau lui-même dans son verre et mouille tout ? Pour ces gestes pratiques du quotidien, regardez les gobelets anti-renversement des Produits recommandés.', title_hi = 'मैं खुद डालूँगा! 🥛', body_hi = 'गिलास में पानी खुद डालना चाहता है और सब गीला कर देता है? रोज़मर्रा के इन हुनर के लिए सुझाए गए प्रोडक्ट में न छलकने वाले स्मार्ट कप देखिए।', title_id = 'Aku tuang sendiri! 🥛', body_id = 'Ingin menuang air ke gelas sendiri dan membasahi semuanya? Untuk keterampilan hidup praktis ini, lihat gelas pintar anti tumpah di Produk Rekomendasi.', title_ja = '自分でつぐ！🥛', body_ja = '自分でコップにお水をつぎたがって、あちこちびしょびしょに？この生活の力を育てるために、「おすすめ商品」でこぼれにくいコップをチェックしましょう。', title_ko = '내가 따를래! 🥛', body_ko = '컵에 물을 직접 따르겠다며 온 사방을 적시나요? 이런 생활 기술을 위해 추천 제품에서 흘리지 않는 스마트 컵을 살펴보세요.', title_nl = 'Ik schenk zelf in! 🥛', body_nl = 'Wil hij zelf water in zijn beker schenken en wordt alles nat? Bekijk voor deze praktische levensvaardigheid slimme, lekvrije bekers in Aanbevolen producten.', title_pl = 'Sam naleję! 🥛', body_pl = 'Chce sam nalewać wodę do kubka i wszystko zalewa? Zajrzyj w Polecanych produktach do sprytnych kubków niekapków, które wspierają te praktyczne umiejętności.', title_pt = 'Eu sirvo sozinho! 🥛', body_pt = 'Quer servir sozinho a água no copo e molha tudo? Para estas competências práticas da vida, veja nos Produtos Recomendados copos inteligentes antientornar.', title_sv = 'Jag häller själv! 🥛', body_sv = 'Vill barnet själv hälla vatten i muggen och blöter ner allt? Titta på smarta muggar som inte spiller i Rekommenderade produkter för dessa praktiska livsfärdigheter.', title_vi = '"Con tự rót!" 🥛', body_vi = 'Bé muốn tự rót nước vào cốc và làm ướt khắp nơi? Hãy xem những chiếc cốc thông minh chống đổ trong Sản phẩm gợi ý để hỗ trợ kỹ năng sống thực tế này.', title_zh = '我要自己倒！🥛', body_zh = '想自己往杯子里倒水，弄得到处湿漉漉？为了培养这些生活技能，去推荐商品看看防洒的智能水杯。' WHERE id = '181e78e0-6fdf-4595-ab68-0d67492cb40c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Da portazos? 🚪', body_es = '¿Cuando se enfada da portazos y llora? Contacta ya con nuestro experto Anacan AI y aprende estrategias para gestionar estas explosiones emocionales tan intensas.', title_fr = 'Il claque les portes ? 🚪', body_fr = 'Il claque les portes et pleure quand il se fâche ? Pour gérer ces violentes explosions émotionnelles, contactez tout de suite notre expert Anacan AI et découvrez des stratégies.', title_hi = 'दरवाज़े पटकता है? 🚪', body_hi = 'गुस्से में दरवाज़े पटककर रोता है? इन तेज़ भावनात्मक विस्फोटों को संभालने के लिए तुरंत हमारे Anacan AI एक्सपर्ट से जुड़िए और तरीका सीखिए।', title_id = 'Membanting pintu? 🚪', body_id = 'Membanting pintu dan menangis saat marah? Untuk menghadapi ledakan emosi yang hebat ini, segera hubungi ahli Anacan AI dan pelajari strateginya.', title_ja = 'ドアをバタンと閉める？🚪', body_ja = '怒るとドアをバタンと閉めて泣きますか？この激しい気持ちの爆発に対応するために、すぐにAnacan AIのエキスパートに相談して、対応のコツを学びましょう。', title_ko = '문을 쾅 닫나요? 🚪', body_ko = '화가 나면 문을 쾅 닫고 우나요? 이런 격한 감정 폭발을 다루는 전략을 Anacan AI 전문가에게 바로 물어보세요.', title_nl = 'Slaat hij met deuren? 🚪', body_nl = 'Slaat hij met deuren en huilt hij als hij boos is? Neem meteen contact op met onze Anacan AI-expert en leer een strategie om deze heftige uitbarstingen aan te pakken.', title_pl = 'Trzaska drzwiami? 🚪', body_pl = 'Gdy się złości, trzaska drzwiami i płacze? Od razu skontaktuj się z naszym ekspertem Anacan AI i poznaj strategie radzenia sobie z tymi gwałtownymi wybuchami emocji.', title_pt = 'Bate com as portas? 🚪', body_pt = 'Quando se zanga, bate com as portas e chora? Para gerir estas explosões emocionais intensas, fale já com o nosso especialista Anacan AI e aprenda estratégias.', title_sv = 'Smäller i dörrarna? 🚪', body_sv = 'Smäller barnet i dörrarna och gråter när hen blir arg? Kontakta vår expert Anacan AI direkt och lär dig strategier för att hantera dessa häftiga känsloutbrott.', title_vi = 'Bé đóng sầm cửa? 🚪', body_vi = 'Bé đóng sầm cửa và khóc khi tức giận? Hãy liên hệ ngay chuyên gia Anacan AI để học chiến lược xử lý những cơn bùng nổ cảm xúc dữ dội này.', title_zh = '摔门？🚪', body_zh = '一生气就摔门哭闹？马上联系我们的Anacan AI专家，学习应对这种激烈情绪爆发的策略。' WHERE id = '68364d15-562a-4922-a1dc-902274f2d63c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No piques de pie 🍎', body_es = '¡Date tu valor! Prepara en Recetas saludables una ensalada de frutos rojos cargada de antioxidantes.', title_fr = 'Ne grignotez pas debout 🍎', body_fr = 'Prenez soin de vous ! Préparez une salade de baies pleine d''antioxydants avec les Recettes saines.', title_hi = 'खड़े-खड़े कुछ भी मत खाइए 🍎', body_hi = 'अपनी कद्र कीजिए! सेहतमंद रेसिपी से एंटीऑक्सीडेंट से भरपूर बेरी सलाद बनाइए।', title_id = 'Jangan makan sambil berdiri 🍎', body_id = 'Hargai diri Anda! Buat salad beri kaya antioksidan dari Resep Sehat.', title_ja = '立ったままつままないで 🍎', body_ja = '自分を大切にしましょう！「ヘルシーレシピ」から、抗酸化物質たっぷりのベリーサラダをつくりましょう。', title_ko = '서서 대충 먹지 마세요 🍎', body_ko = '나를 소중히 여기세요! 건강한 레시피에서 항산화 성분 가득한 베리 샐러드를 만들어 보세요.', title_nl = 'Niet staand snacken 🍎', body_nl = 'Geef om jezelf! Maak uit Gezonde recepten een bessensalade vol antioxidanten.', title_pl = 'Nie jedz w biegu 🍎', body_pl = 'Doceń siebie! Przygotuj ze Zdrowych przepisów sałatkę z owoców jagodowych pełną antyoksydantów.', title_pt = 'Não coma de pé 🍎', body_pt = 'Dê-se valor! Prepare com as Receitas Saudáveis uma salada de frutos vermelhos, cheia de antioxidantes.', title_sv = 'Ät inte stående 🍎', body_sv = 'Ge dig själv värde! Gör en bärsallad full av antioxidanter från Hälsosamma recept.', title_vi = 'Đừng ăn vội vàng 🍎', body_vi = 'Hãy trân trọng bản thân! Làm món salad quả mọng giàu chất chống oxy hóa từ Công thức lành mạnh nhé.', title_zh = '别站着随便吃两口 🍎', body_zh = '好好珍惜自己！从健康食谱里做一份富含抗氧化物的莓果沙拉吧。' WHERE id = 'de0f5d4f-9f96-42d7-a940-e7558af5d045' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasión por el papel higiénico 🧻', body_es = '¿En el baño desenrolla el papel higiénico y juega con él? Convierte este interés en una oportunidad: empieza ya a leer en el Blog el artículo sobre cómo dejar el pañal jugando.', title_fr = 'L''amour du papier toilette 🧻', body_fr = 'Dans la salle de bain, il déroule le papier toilette pour jouer ? Faites de cette curiosité une occasion : lisez tout de suite dans la rubrique Blogs l''article sur l''apprentissage du pot par le jeu.', title_hi = 'टॉयलेट पेपर से प्यार 🧻', body_hi = 'बाथरूम में टॉयलेट पेपर का रोल खोलकर खेलता है? इस दिलचस्पी को मौके में बदलिए, तुरंत ब्लॉग में खेल-खेल में पॉटी ट्रेनिंग शुरू करने वाला लेख पढ़िए।', title_id = 'Cinta tisu toilet 🧻', body_id = 'Membuka gulungan tisu toilet di kamar mandi untuk bermain? Jadikan rasa ingin tahu ini peluang, segera mulai baca artikel di Blog tentang beralih ke latihan pispot lewat permainan.', title_ja = 'トイレットペーパーが大好き 🧻', body_ja = 'トイレでトイレットペーパーをくるくる引き出して遊んでいますか？この興味をチャンスに変えましょう。遊びを通してトイレトレーニングへ進む方法について、すぐにブログの記事を読み始めましょう。', title_ko = '휴지 사랑 🧻', body_ko = '화장실에서 두루마리 휴지를 풀며 노나요? 이 호기심을 기회로 바꿔 보세요. 블로그에서 놀이로 배변 훈련을 시작하는 글을 바로 읽어 보세요.', title_nl = 'Dol op wc-papier 🧻', body_nl = 'Rolt hij in de badkamer het wc-papier af om ermee te spelen? Maak van die interesse een kans en lees meteen in Blogs het artikel over spelenderwijs overstappen naar het potje.', title_pl = 'Miłość do papieru toaletowego 🧻', body_pl = 'W łazience rozwija papier toaletowy z rolki i się nim bawi? Zamień tę ciekawość w okazję i od razu przeczytaj na Blogu artykuł o przejściu do nauki korzystania z nocnika przez zabawę.', title_pt = 'O gosto pelo papel higiénico 🧻', body_pt = 'Na casa de banho desenrola o papel higiénico e brinca com ele? Transforme esta curiosidade numa oportunidade e comece já a ler nos Blogues o artigo sobre a passagem para o bacio a brincar.', title_sv = 'Kärlek till toalettpapper 🧻', body_sv = 'Rullar barnet ut toalettpappret och leker med det i badrummet? Gör intresset till en möjlighet och börja direkt läsa artikeln i Bloggar om att gå över till pottträning med lek.', title_vi = 'Mê giấy vệ sinh 🧻', body_vi = 'Bé tháo cuộn giấy vệ sinh trong phòng tắm ra chơi? Hãy biến sự tò mò này thành cơ hội, đọc ngay bài viết về cách bắt đầu tập ngồi bô qua trò chơi trong mục Blog.', title_zh = '爱玩卫生纸 🧻', body_zh = '在卫生间把卫生纸从卷上拉开来玩？把这份好奇变成机会，马上去博客读读通过游戏过渡到如厕训练的文章。' WHERE id = '7a5b3c40-a866-426b-8ed4-dd68302d6513' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Uno, dos, tres... 🔢', body_es = '¿Intenta contar cosas mientras sube las escaleras? Son las primeras chispas del desarrollo matemático.', title_fr = 'Un, deux, trois... 🔢', body_fr = 'Il essaie de compter en montant les marches ? Ce sont les premières étincelles du développement mathématique.', title_hi = 'एक, दो, तीन... 🔢', body_hi = 'सीढ़ियाँ चढ़ते हुए कुछ गिनने की कोशिश करता है? यह गणित की समझ की पहली चिंगारी है।', title_id = 'Satu, dua, tiga... 🔢', body_id = 'Mencoba menghitung sesuatu saat menaiki tangga? Inilah percikan pertama perkembangan kemampuan matematikanya.', title_ja = 'いち、に、さん… 🔢', body_ja = '階段をのぼりながら、何かを数えようとしていますか？これは算数の力が育つ最初の火花です。', title_ko = '하나, 둘, 셋... 🔢', body_ko = '계단을 오르며 무언가를 세려고 하나요? 수학적 발달의 첫 불씨예요.', title_nl = 'Een, twee, drie... 🔢', body_nl = 'Probeert hij te tellen als hij de trap op loopt? Dat zijn de eerste vonkjes van zijn rekenkundige ontwikkeling.', title_pl = 'Raz, dwa, trzy... 🔢', body_pl = 'Wchodząc po schodach, próbuje coś liczyć? To pierwsze iskierki rozwoju matematycznego.', title_pt = 'Um, dois, três... 🔢', body_pt = 'Ao subir as escadas, tenta contar? São as primeiras faíscas do desenvolvimento matemático.', title_sv = 'Ett, två, tre... 🔢', body_sv = 'Försöker barnet räkna något när hen går uppför trappan? Det är de första gnistorna av matematisk utveckling.', title_vi = 'Một, hai, ba... 🔢', body_vi = 'Bé cố đếm gì đó khi leo cầu thang? Đây là những tia sáng đầu tiên của tư duy toán học.', title_zh = '一、二、三…… 🔢', body_zh = '爬楼梯时想数点什么？这是数学能力发展的第一缕火花。' WHERE id = 'd2a5512c-c089-47a6-aba1-367f406306e5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ya tiene todos los dientes? 🦷', body_es = '¿Le están saliendo las últimas muelas? Para cubrir la mayor necesidad de calcio, comprueba sin falta con el Seguimiento de tomas el yogur y el queso de hoy.', title_fr = 'Toutes les dents sont là ? 🦷', body_fr = 'Les dernières molaires arrivent ? Pour couvrir ses besoins accrus en calcium, vérifiez absolument avec le Suivi des repas sa ration de yaourt et de fromage du jour.', title_hi = 'सारे दाँत आ गए? 🦷', body_hi = 'आखिरी दाढ़ें निकल रही हैं? कैल्शियम की बढ़ी ज़रूरत के लिए फ़ीडिंग ट्रैकर से आज का दही और पनीर ज़रूर जाँचिए।', title_id = 'Giginya sudah lengkap? 🦷', body_id = 'Geraham terakhir sedang tumbuh? Untuk menambah asupan kalsium, pastikan cek asupan yogurt dan keju hari ini dengan alat Pemantau Nutrisi.', title_ja = '歯は全部そろった？🦷', body_ja = '最後の奥歯が生えてきていますか？カルシウムを多めにとれるよう、「栄養管理ツール」で今日のヨーグルトやチーズの量を必ず確認しましょう。', title_ko = '이가 다 났나요? 🦷', body_ko = '마지막 어금니가 나오고 있나요? 칼슘을 충분히 챙기도록 수유 기록 도구로 오늘 요거트와 치즈 섭취를 꼭 확인하세요.', title_nl = 'Zijn alle tandjes er? 🦷', body_nl = 'Komen de laatste kiezen door? Controleer zeker de yoghurt en kaas van vandaag met de Voedingstracker om genoeg calcium binnen te krijgen.', title_pl = 'Wszystkie ząbki już są? 🦷', body_pl = 'Wychodzą ostatnie trzonowce? Aby zwiększyć ilość wapnia, koniecznie sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie jogurtu i sera.', title_pt = 'Os dentes estão todos? 🦷', body_pt = 'Estão a nascer os últimos molares? Para aumentar o cálcio, verifique sem falta com o Registo de Alimentação o iogurte e o queijo de hoje.', title_sv = 'Har alla tänder kommit? 🦷', body_sv = 'Kommer de sista kindtänderna? Kontrollera dagens intag av yoghurt och ost med Matningskoll för att öka kalciumet.', title_vi = 'Răng đã mọc đủ chưa? 🦷', body_vi = 'Những chiếc răng hàm cuối đang mọc? Để tăng lượng canxi, nhất định hãy kiểm tra lượng sữa chua và phô mai hôm nay bằng Theo dõi cữ bú.', title_zh = '牙齿长齐了吗？🦷', body_zh = '最后几颗磨牙在长？为了满足更多的钙需求，一定要用喂养记录工具查看今天的酸奶和奶酪摄入量。' WHERE id = 'f4ef4af2-bbdc-456f-a980-4eeb315c77b8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Hace demasiado calor en el dormitorio? 🌡️', body_es = '¿Da muchas vueltas en la cama y suda? Comprueba la temperatura de la habitación, pon el temporizador de sueño y refresca el ambiente psicológicamente con el sonido del ventilador de Ruido blanco.', title_fr = 'Il fait trop chaud dans la chambre ? 🌡️', body_fr = 'Il se tourne et se retourne dans son lit en transpirant ? Vérifiez la température de la chambre, lancez le minuteur de sommeil et rafraîchissez la pièce psychologiquement avec le bruit de ventilateur des Bruits blancs.', title_hi = 'बेडरूम बहुत गर्म तो नहीं? 🌡️', body_hi = 'बिस्तर पर बहुत करवटें बदलता है और पसीना आता है? कमरे का तापमान जाँचिए, स्लीप टाइमर चालू कीजिए और व्हाइट नॉइज़ में पंखे की आवाज़ से कमरे को मन से ठंडक का एहसास दीजिए।', title_id = 'Kamar tidurnya terlalu panas? 🌡️', body_id = 'Banyak berguling dan berkeringat di tempat tidur? Cek suhu kamar, nyalakan Timer Tidur, dan sejukkan kamar secara psikologis dengan suara kipas angin dari Suara Putih.', title_ja = '寝室が暑すぎる？🌡️', body_ja = 'ベッドでごろごろ寝返りばかりで、汗をかいていますか？部屋の温度を確認し、睡眠タイマーをオンにして、「ホワイトノイズ」の扇風機の音で部屋を気分的に涼しくしましょう。', title_ko = '침실이 너무 덥나요? 🌡️', body_ko = '침대에서 계속 뒤척이며 땀을 흘리나요? 방 온도를 확인하고, 수면 타이머를 켠 뒤 백색소음의 선풍기 소리로 방을 심리적으로 시원하게 해 주세요.', title_nl = 'Is het te warm in de slaapkamer? 🌡️', body_nl = 'Draait hij veel rond in bed en zweet hij? Controleer de temperatuur in de kamer, zet de Slaaptimer aan en laat de kamer met het ventilatorgeluid uit Witte ruis koeler aanvoelen.', title_pl = 'W sypialni jest za ciepło? 🌡️', body_pl = 'Dużo wierci się w łóżku i się poci? Sprawdź temperaturę w pokoju, włącz timer snu i odgłosem wentylatora z Białego szumu psychologicznie ochłódź pokój.', title_pt = 'O quarto está quente demais? 🌡️', body_pt = 'Dá muitas voltas na cama e transpira? Verifique a temperatura do quarto, ligue o temporizador de sono e refresque psicologicamente o quarto com o som da ventoinha do Ruído Branco.', title_sv = 'För varmt i sovrummet? 🌡️', body_sv = 'Vrider sig barnet mycket i sängen och svettas? Kontrollera temperaturen i rummet, starta sömntimern och svalka rummet psykologiskt med fläktljud från Vitt brus.', title_vi = 'Phòng ngủ có quá nóng? 🌡️', body_vi = 'Bé trằn trọc và đổ mồ hôi trên giường? Hãy kiểm tra nhiệt độ phòng, bật Bộ hẹn giờ ngủ và dùng tiếng quạt trong Tiếng ồn trắng để căn phòng "mát" hơn về mặt tâm lý.', title_zh = '卧室太热了？🌡️', body_zh = '在床上翻来覆去还出汗？检查一下房间温度，打开睡眠计时器，用白噪音里的风扇声让房间在心理上凉快下来。' WHERE id = '0480de3f-fc2e-475f-9c9a-7f062b43912d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Llora cuando te vas? 🚪', body_es = '¿Te llama a gritos incluso cuando sales de la habitación? Pregunta a Anacan AI trucos para afrontar con suavidad esta nueva ola de ansiedad por separación.', title_fr = 'Il pleure quand vous partez ? 🚪', body_fr = 'Il crie après vous même quand vous quittez la pièce ? Demandez à Anacan AI des astuces pour gérer en douceur cette nouvelle vague d''angoisse de séparation.', title_hi = 'आपके पीछे रोता है? 🚪', body_hi = 'आप कमरे से निकलें तो भी पीछे से चिल्लाता है? अलग होने की बेचैनी की इस नई लहर को नरमी से सुलझाने की तरकीबें Anacan AI से पूछिए।', title_id = 'Menangis saat Anda pergi? 🚪', body_id = 'Menjerit memanggil Anda bahkan saat Anda hanya keluar kamar? Tanyakan kepada Anacan AI trik mengatasi gelombang baru kecemasan berpisah ini dengan lembut.', title_ja = 'あとを追って泣く？🚪', body_ja = '部屋を出ただけで、あなたを呼んで叫びますか？この新しい分離不安の波にやさしく対応するコツを、Anacan AIに聞いてみましょう。', title_ko = '엄마를 찾으며 우나요? 🚪', body_ko = '방만 나가도 엄마를 부르며 소리 지르나요? 새롭게 찾아온 분리 불안을 부드럽게 넘기는 요령을 Anacan AI에게 물어보세요.', title_nl = 'Huilt hij je achterna? 🚪', body_nl = 'Roept hij je zelfs als je even de kamer uit gaat? Vraag Anacan AI om tips om deze nieuwe golf van verlatingsangst zacht aan te pakken.', title_pl = 'Płacze, gdy wychodzisz? 🚪', body_pl = 'Krzyczy za tobą, nawet gdy tylko wychodzisz z pokoju? Zapytaj Anacan AI o sposoby, jak łagodnie przejść przez tę nową falę lęku separacyjnego.', title_pt = 'Chora atrás de si? 🚪', body_pt = 'Mesmo quando só sai do quarto, grita atrás de si? Pergunte ao Anacan AI truques para resolver com suavidade esta nova vaga de ansiedade de separação.', title_sv = 'Gråter efter dig? 🚪', body_sv = 'Skriker barnet efter dig även när du bara lämnar rummet? Fråga Anacan AI om knep för att varsamt hantera den nya vågen av separationsångest.', title_vi = 'Bé khóc theo mẹ? 🚪', body_vi = 'Mẹ vừa ra khỏi phòng là bé đã gào lên? Hãy hỏi Anacan AI mẹo nhẹ nhàng vượt qua đợt lo âu chia ly mới này.', title_zh = '在你身后哭？🚪', body_zh = '你一离开房间就在后面尖叫？问问Anacan AI，温和化解这波新的分离焦虑的小技巧。' WHERE id = '2b885719-7eb3-49f2-a501-3fdceb08a1dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lógica en acción 🧩', body_es = '¿Cada vez se le da mejor encajar figuras geométricas? Descubre en Productos recomendados juegos más complejos que pongan a prueba su inteligencia.', title_fr = 'La logique en action 🧩', body_fr = 'Il devient expert pour assortir les formes géométriques ? Découvrez dans les Produits recommandés des jeux plus complexes qui stimuleront encore son intelligence.', title_hi = 'तर्क काम पर 🧩', body_hi = 'ज्यामितीय आकृतियाँ मिलाने में माहिर हो रहा है? उसकी बुद्धि को और चुनौती देने वाले मुश्किल खेलों के लिए सुझाए गए प्रोडक्ट सेक्शन देखिए।', title_id = 'Logika sedang bekerja 🧩', body_id = 'Makin mahir mencocokkan bentuk geometri? Temukan permainan yang lebih rumit untuk lebih menantang kecerdasannya di bagian Produk Rekomendasi.', title_ja = '論理的な思考が活躍中 🧩', body_ja = '図形合わせが上手になってきましたか？知性をさらに刺激する、もっと難しい遊びを「おすすめ商品」で見つけましょう。', title_ko = '논리가 일하는 중 🧩', body_ko = '도형 맞추기에 능숙해지고 있나요? 두뇌를 더 자극할 한층 복잡한 놀이를 추천 제품 섹션에서 찾아보세요.', title_nl = 'Logica aan het werk 🧩', body_nl = 'Wordt hij steeds beter in geometrische vormen passen? Ontdek in Aanbevolen producten moeilijkere spelletjes die zijn verstand nog meer uitdagen.', title_pl = 'Logika w akcji 🧩', body_pl = 'Coraz lepiej dopasowuje figury geometryczne? Odkryj w sekcji Polecane produkty bardziej złożone gry, które jeszcze mocniej pobudzą jego umysł.', title_pt = 'A lógica em ação 🧩', body_pt = 'Está a ficar mestre a encaixar formas geométricas? Descubra na secção Produtos Recomendados jogos mais complexos que vão desafiar ainda mais a inteligência dele.', title_sv = 'Logiken i farten 🧩', body_sv = 'Blir barnet allt bättre på att matcha geometriska figurer? Upptäck Rekommenderade produkter för svårare lekar som utmanar tänkandet ännu mer.', title_vi = 'Tư duy đang vận hành 🧩', body_vi = 'Bé đã thành thạo ghép các hình khối? Hãy khám phá những trò chơi phức tạp hơn giúp bé động não nhiều hơn trong mục Sản phẩm gợi ý.', title_zh = '逻辑上线 🧩', body_zh = '越来越会配对几何形状了？去推荐商品板块发现更复杂的游戏，给宝宝的小脑瓜更多挑战。' WHERE id = '4ef212ee-e501-41a3-bd1b-0f62028addbd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Elegir la pasta de dientes 🪥', body_es = '¿Ya empieza a aprender a escupir el agua? Lee sin falta en el Blog nuestro artículo científico sobre si elegir pasta con flúor o sin flúor.', title_fr = 'Choisir son dentifrice 🪥', body_fr = 'Il commence à apprendre à recracher l''eau ? Lisez absolument notre article scientifique de la rubrique Blogs sur le choix d''un dentifrice avec ou sans fluor.', title_hi = 'टूथपेस्ट का चुनाव 🪥', body_hi = 'पानी थूकना सीखने लगा है? फ़्लोराइड वाला या बिना फ़्लोराइड वाला पेस्ट चुनने पर ब्लॉग सेक्शन का हमारा वैज्ञानिक लेख ज़रूर पढ़िए।', title_id = 'Memilih pasta gigi 🪥', body_id = 'Ia mulai belajar meludahkan air? Baca artikel ilmiah kami di bagian Blog tentang memilih pasta gigi berfluoride atau tanpa fluoride.', title_ja = '歯みがき粉の選び方 🪥', body_ja = 'お水をペッと吐き出すのを覚え始めましたか？フッ素入りかフッ素なしか、歯みがき粉の選び方についての科学的な記事を、ブログでぜひ読んでみましょう。', title_ko = '치약 고르기 🪥', body_ko = '물을 뱉는 법을 배우기 시작했나요? 불소 치약과 무불소 치약 선택에 관한 블로그의 과학적인 글을 꼭 읽어 보세요.', title_nl = 'Tandpasta kiezen 🪥', body_nl = 'Leert hij al water uitspugen? Lees zeker ons wetenschappelijke artikel in Blogs over de keuze tussen tandpasta met of zonder fluoride.', title_pl = 'Wybór pasty do zębów 🪥', body_pl = 'Zaczyna już uczyć się wypluwać wodę? Koniecznie przeczytaj w sekcji Blog nasz naukowy artykuł o wyborze pasty z fluorem lub bez fluoru.', title_pt = 'A escolha da pasta de dentes 🪥', body_pt = 'Já começa a aprender a cuspir a água? Leia sem falta nos Blogues o nosso artigo científico sobre a escolha entre pasta com ou sem flúor.', title_sv = 'Val av tandkräm 🪥', body_sv = 'Har barnet börjat lära sig att spotta ut vatten? Läs vår vetenskapliga artikel i Bloggar om att välja tandkräm med eller utan fluor.', title_vi = 'Chọn kem đánh răng 🪥', body_vi = 'Bé đã bắt đầu tập nhổ nước? Nhất định hãy đọc bài viết khoa học trong mục Blog về việc chọn kem đánh răng có fluor hay không fluor.', title_zh = '选牙膏 🪥', body_zh = '已经开始学吐水了？一定要读读博客板块里我们那篇关于选含氟还是无氟牙膏的科学文章。' WHERE id = '132f97c4-bee0-471c-ad8b-a7fc3585b9d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Pasteles de barro! 🧁', body_es = '¿Quiere jugar con la tierra en el patio? ¡Deja que se ensucie! Inmortaliza estos momentos maravillosos que apoyan su desarrollo sensorial con la Sesión de fotos del bebé.', title_fr = 'Gâteaux de boue ! 🧁', body_fr = 'Il veut jouer avec la terre dans la cour ? Laissez-le se salir ! Immortalisez ces superbes moments qui soutiennent son développement sensoriel avec la Séance photo bébé.', title_hi = 'मिट्टी के केक! 🧁', body_hi = 'आँगन में मिट्टी से खेलना चाहता है? उसे गंदा होने दीजिए! सेंसरी विकास में मदद करने वाले इन शानदार पलों को बेबी फ़ोटोशूट से हमेशा के लिए सहेजिए।', title_id = 'Kue lumpur! 🧁', body_id = 'Ingin bermain tanah di halaman? Biarkan ia kotor! Abadikan momen luar biasa yang mendukung perkembangan sensorik ini dengan Sesi Foto Bayi.', title_ja = '泥んこケーキ！🧁', body_ja = '庭で土遊びをしたがりますか？汚れてもいいんです！感覚の発達を育てるこのすばらしい瞬間を、「ベビーフォトセッション」で残しましょう。', title_ko = '진흙 케이크! 🧁', body_ko = '마당에서 흙장난을 하고 싶어 하나요? 마음껏 더러워지게 해 주세요! 감각 발달을 돕는 이 멋진 순간을 아기 사진 촬영으로 영원히 남기세요.', title_nl = 'Moddertaartjes! 🧁', body_nl = 'Wil hij in de tuin met aarde spelen? Laat hem vies worden! Leg deze geweldige momenten die zijn zintuiglijke ontwikkeling steunen vast met Babyfotoshoot.', title_pl = 'Babki z błota! 🧁', body_pl = 'Chce bawić się ziemią na podwórku? Pozwól mu się ubrudzić! Uwiecznij te wspaniałe chwile wspierające rozwój sensoryczny w Sesji zdjęciowej dziecka.', title_pt = 'Bolos de lama! 🧁', body_pt = 'Quer brincar com terra no quintal? Deixe-o sujar-se! Eternize com a Sessão Fotográfica do Bebé estes momentos fantásticos que apoiam o desenvolvimento sensorial.', title_sv = 'Lerkakor! 🧁', body_sv = 'Vill barnet leka med jord på gården? Låt barnet bli smutsigt! Förevig dessa fantastiska stunder som stöttar sinnesutvecklingen med Babyfotografering.', title_vi = 'Bánh bùn đất! 🧁', body_vi = 'Bé muốn chơi đất ngoài sân? Cứ để bé lấm bẩn! Hãy lưu giữ những khoảnh khắc tuyệt vời giúp phát triển giác quan này bằng Chụp ảnh cho bé.', title_zh = '泥巴蛋糕！🧁', body_zh = '想在院子里玩泥土？就让宝宝弄脏吧！用宝宝写真把这些促进感官发展的精彩时刻永远留下来。' WHERE id = 'c85cd72a-3a99-42a3-86ab-1fa1d9a4f422' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reinicia tu mente 🧘‍♀️', body_es = '¿Todo se te echa encima? Abre el Diario de ánimo y escribe sin parar durante 3 minutos lo que sientes. Escribir reduce el estrés al instante.', title_fr = 'Redémarrez votre cerveau 🧘‍♀️', body_fr = 'Tout vous tombe dessus ? Ouvrez le Journal d''humeur et écrivez sans vous arrêter ce que vous ressentez pendant 3 minutes. Écrire réduit tout de suite le stress.', title_hi = 'अपने दिमाग को रीस्टार्ट कीजिए 🧘‍♀️', body_hi = 'सब कुछ भारी लग रहा है? मूड डायरी खोलिए, 3 मिनट तक बिना रुके लिखिए कि आप क्या महसूस कर रही हैं। लिखने से तनाव तुरंत कम होता है।', title_id = 'Restart pikiran Anda 🧘‍♀️', body_id = 'Semua terasa menumpuk? Buka Buku Harian Suasana Hati dan tulis apa yang Anda rasakan selama 3 menit tanpa berhenti. Menulis langsung mengurangi stres.', title_ja = '頭をリセットしよう 🧘‍♀️', body_ja = '何もかもが押し寄せてくる？「気分日記」を開いて、3分間、手を止めずに今の気持ちを書きましょう。書くことで、ストレスはすぐに軽くなります。', title_ko = '머리를 재시작해요 🧘‍♀️', body_ko = '모든 게 한꺼번에 몰려오나요? 기분 일기를 열고 3분 동안 멈추지 말고 느끼는 대로 적어 보세요. 글쓰기는 스트레스를 바로 줄여 줘요.', title_nl = 'Herstart je hoofd 🧘‍♀️', body_nl = 'Komt alles op je af? Open je Stemmingsdagboek en schrijf 3 minuten lang zonder te stoppen op wat je voelt. Schrijven vermindert stress meteen.', title_pl = 'Zrestartuj umysł 🧘‍♀️', body_pl = 'Wszystko cię przytłacza? Otwórz Dziennik nastroju i przez 3 minuty pisz bez przerwy, co czujesz. Pisanie od razu zmniejsza stres.', title_pt = 'Reinicie o cérebro 🧘‍♀️', body_pt = 'Tudo lhe cai em cima? Abra o Diário de Humor e escreva sem parar, durante 3 minutos, o que sente. Escrever reduz o stress na hora.', title_sv = 'Starta om hjärnan 🧘‍♀️', body_sv = 'Känns allt övermäktigt? Öppna Humördagboken och skriv utan uppehåll i 3 minuter om vad du känner. Att skriva minskar stressen direkt.', title_vi = 'Khởi động lại đầu óc 🧘‍♀️', body_vi = 'Mọi thứ đổ dồn lên mẹ? Hãy mở Nhật ký tâm trạng và viết liền tay mọi cảm xúc trong 3 phút. Viết ra giúp giảm căng thẳng ngay lập tức.', title_zh = '给大脑重启一下 🧘‍♀️', body_zh = '一切都压得你喘不过气？打开心情日记，用3分钟不停地写下你的感受。书写能马上减轻压力。' WHERE id = 'da905da7-70f6-46f4-b372-c620f421daf8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Prueba de gravedad! 🍎', body_es = '¿Le encanta tirar la comida o los juguetes desde arriba? En lugar de frenar estos descubrimientos físicos, aprende con Anacan AI a reconducirlos hacia otra dirección.', title_fr = 'Test de gravité ! 🍎', body_fr = 'Il adore jeter la nourriture ou les jouets depuis une hauteur ? Au lieu d''arrêter ces découvertes de physique, découvrez avec Anacan AI comment les orienter autrement.', title_hi = 'गुरुत्वाकर्षण टेस्ट! 🍎', body_hi = 'खाना या खिलौने ऊपर से नीचे गिराना बहुत पसंद है? भौतिकी की इन खोजों को रोकने के बजाय उन्हें दूसरी दिशा देना Anacan AI से सीखिए।', title_id = 'Uji gravitasi! 🍎', body_id = 'Senang menjatuhkan makanan atau mainan dari atas? Daripada menghentikan penemuan fisika ini, pelajari dari Anacan AI cara mengalihkannya ke arah lain.', title_ja = '重力の実験！🍎', body_ja = '食べ物やおもちゃを高いところから落とすのが大好き？この物理の発見を止める代わりに、ちがう方向へ導く方法をAnacan AIで学びましょう。', title_ko = '중력 실험! 🍎', body_ko = '높은 곳에서 음식이나 장난감을 떨어뜨리는 걸 좋아하나요? 이런 물리 탐구를 막는 대신 다른 방향으로 이끄는 방법을 Anacan AI에게 배워 보세요.', title_nl = 'Zwaartekrachttest! 🍎', body_nl = 'Is hij dol op eten of speelgoed van een hoogte laten vallen? Leer bij Anacan AI hoe je deze natuurkundige ontdekkingen een andere kant op stuurt in plaats van ze te stoppen.', title_pl = 'Test grawitacji! 🍎', body_pl = 'Uwielbia zrzucać jedzenie i zabawki z góry? Zamiast przerywać te odkrycia fizyczne, dowiedz się od Anacan AI, jak skierować je w inną stronę.', title_pt = 'Teste da gravidade! 🍎', body_pt = 'Adora atirar comida ou brinquedos de cima para baixo? Em vez de travar estas descobertas de física, aprenda com o Anacan AI a orientá-las para outra direção.', title_sv = 'Gravitationstest! 🍎', body_sv = 'Älskar barnet att släppa mat eller leksaker från höjden? Lär dig av Anacan AI hur du styr om dessa fysikaliska upptäckter i stället för att stoppa dem.', title_vi = 'Thử nghiệm trọng lực! 🍎', body_vi = 'Bé mê ném thức ăn hay đồ chơi từ trên cao xuống? Thay vì ngăn những khám phá vật lý này, hãy học từ Anacan AI cách định hướng sang hướng khác.', title_zh = '重力测试！🍎', body_zh = '特别爱把食物或玩具从高处往下扔？向Anacan AI学习如何不是阻止，而是把这些物理探索引向别的方向。' WHERE id = '929b30f1-695d-4f66-a22b-9182b15561c4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Falta de fibra? 💩', body_es = '¿Las cacas se han endurecido y te preocupa el estreñimiento? Anótalo en el Seguimiento de pañales y añade enseguida ciruelas pasas o avena a su menú con el Seguimiento de tomas.', title_fr = 'Manque de fibres ? 💩', body_fr = 'Ses selles sont dures et la constipation vous inquiète ? Notez-le dans le Suivi des couches et ajoutez tout de suite des pruneaux ou de l''avoine à son menu avec le Suivi des repas.', title_hi = 'फ़ाइबर की कमी? 💩', body_hi = 'पॉटी सख्त हो गई है और कब्ज़ परेशान कर रहा है? डायपर ट्रैकर में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से मेन्यू में आलूबुखारा (प्रून) या ओट्स जोड़िए।', title_id = 'Kurang serat? 💩', body_id = 'Kotorannya mengeras dan sembelit mengganggu? Catat di Pelacak Popok dan segera tambahkan plum kering (prune) atau oat ke menunya dengan alat Pemantau Nutrisi.', title_ja = '食物繊維が足りない？💩', body_ja = 'うんちがかたくなって、便秘が気になりますか？「おむつトラッカー」に記録して、すぐに「栄養管理ツール」でプルーンやオートミールをメニューに加えましょう。', title_ko = '섬유질이 부족한가요? 💩', body_ko = '변이 딱딱해지고 변비가 걱정되나요? 기저귀 기록에 남기고 수유 기록 도구로 식단에 말린 자두나 귀리를 바로 추가하세요.', title_nl = 'Te weinig vezels? 💩', body_nl = 'Is de ontlasting hard en maak je je zorgen over verstopping? Noteer het in de Luiertracker en voeg meteen met de Voedingstracker gedroogde pruimen of havermout toe aan het menu.', title_pl = 'Brak błonnika? 💩', body_pl = 'Kupki stały się twarde i martwią cię zaparcia? Zapisz to w narzędziu do śledzenia pieluszek i od razu dodaj do menu suszone śliwki lub płatki owsiane w narzędziu do śledzenia karmienia.', title_pt = 'Falta de fibra? 💩', body_pt = 'As fezes ficaram duras e a prisão de ventre preocupa-a? Registe-o no Registo de Fraldas e acrescente já à ementa ameixas secas ou aveia com o Registo de Alimentação.', title_sv = 'Brist på fibrer? 💩', body_sv = 'Har avföringen blivit hård och oroar förstoppningen? Anteckna det i Blöjkollen och lägg direkt till katrinplommon eller havre i menyn med Matningskoll.', title_vi = 'Thiếu chất xơ? 💩', body_vi = 'Phân cứng lại và táo bón khiến bé khó chịu? Hãy ghi lại trong Theo dõi tã và thêm ngay mận khô hoặc yến mạch vào thực đơn bằng Theo dõi cữ bú.', title_zh = '纤维不足？💩', body_zh = '大便变硬，便秘让宝宝难受？记在尿布记录里，马上用喂养记录工具在菜单里加入西梅或燕麦。' WHERE id = 'a100b8dd-35f6-4549-ae5f-d60352e46cb5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El primer amigo de juegos 👯‍♂️', body_es = '¿En el parque intenta jugar todo el rato con otro niño? Mira en Lugares para mamás cafeterías infantiles que apoyen esta nueva etapa de socialización.', title_fr = 'Premier copain de jeu 👯‍♂️', body_fr = 'Au parc, il essaie de jouer longtemps avec un autre enfant ? Regardez dans les Lieux adaptés aux mamans les cafés pour enfants qui soutiennent cette nouvelle étape de socialisation.', title_hi = 'पहला खेल का साथी 👯‍♂️', body_hi = 'पार्क में किसी दूसरे बच्चे के साथ लगातार खेलने की कोशिश करता है? मेल-जोल के इस नए दौर में मदद करने वाले किड्स कैफ़े माँ के लिए अनुकूल जगहें में देखिए।', title_id = 'Teman bermain pertama 👯‍♂️', body_id = 'Di taman ia terus mencoba bermain dengan satu anak lain? Lihat kafe anak di Tempat Ramah Ibu yang mendukung tahap sosialisasi baru ini.', title_ja = 'はじめての遊び友だち 👯‍♂️', body_ja = '公園でほかの子とずっと遊ぼうとしていますか？「ママにやさしいスポット」で、この新しい社会性の段階を応援するキッズカフェをチェックしましょう。', title_ko = '첫 놀이 친구 👯‍♂️', body_ko = '공원에서 다른 아이와 계속 놀려고 하나요? 엄마 친화 장소에서 이 새로운 사회성 단계를 돕는 키즈 카페를 찾아보세요.', title_nl = 'Het eerste speelmaatje 👯‍♂️', body_nl = 'Probeert hij in het park steeds met een ander kind te spelen? Bekijk in Mamavriendelijke plekken kindercafés die deze nieuwe fase van socialisatie steunen.', title_pl = 'Pierwszy kolega do zabawy 👯‍♂️', body_pl = 'W parku stale próbuje bawić się z innym dzieckiem? Sprawdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, które wspierają ten nowy etap uspołecznienia.', title_pt = 'O primeiro amigo de brincadeira 👯‍♂️', body_pt = 'No parque tenta brincar sempre com outra criança? Veja nos Locais Amigos das Mães cafés para crianças que apoiam esta nova fase da socialização.', title_sv = 'Första lekkamraten 👯‍♂️', body_sv = 'Försöker barnet leka länge med ett annat barn i parken? Kolla barncaféer i Mammavänliga platser som stöttar detta nya sociala stadium.', title_vi = 'Người bạn chơi đầu tiên 👯‍♂️', body_vi = 'Ở công viên bé cố chơi lâu với một bạn nhỏ? Hãy xem các quán cà phê trẻ em trong Địa điểm thân thiện với mẹ giúp hỗ trợ giai đoạn hòa nhập xã hội mới này.', title_zh = '第一个玩伴 👯‍♂️', body_zh = '在公园想和另一个小朋友一直玩下去？在妈妈友好场所里看看能支持这个新社交阶段的亲子咖啡馆。' WHERE id = 'f0258928-f8cb-46a1-adb3-9d7138af115d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis del temporizador de sueño ⏱️', body_es = '¿Se acuesta muy tarde por la noche? Mira el gráfico del temporizador de sueño. Se acerca el momento de acortar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Analyse du minuteur de sommeil ⏱️', body_fr = 'Il se couche très tard le soir ? Regardez le graphique du minuteur de sommeil. Le moment approche de raccourcir nettement la sieste et d''avancer le coucher.', title_hi = 'स्लीप टाइमर का विश्लेषण ⏱️', body_hi = 'शाम को बहुत देर से सोता है? स्लीप टाइमर का चार्ट देखिए। दिन की नींद पूरी तरह कम करने और शाम की नींद जल्दी करने का समय करीब आ रहा है।', title_id = 'Analisis Timer Tidur ⏱️', body_id = 'Tidur terlalu larut di malam hari? Lihat grafik Timer Tidur. Saatnya hampir tiba untuk memangkas tidur siang sepenuhnya dan memajukan jam tidur malam.', title_ja = '睡眠タイマーで分析 ⏱️', body_ja = '夜、寝るのがとても遅いですか？睡眠タイマーのグラフを見てみましょう。お昼寝をぐっと短くして、夜の寝る時間を早めるときが近づいています。', title_ko = '수면 타이머 분석 ⏱️', body_ko = '저녁에 너무 늦게 자나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 확 줄이고 잠자리 시간을 앞당길 때가 다가오고 있어요.', title_nl = 'Analyse van de Slaaptimer ⏱️', body_nl = 'Gaat hij ''s avonds erg laat slapen? Bekijk de grafiek van de Slaaptimer. De tijd komt eraan om het middagdutje flink in te korten en de bedtijd te vervroegen.', title_pl = 'Analiza timera snu ⏱️', body_pl = 'Wieczorami zasypia bardzo późno? Spójrz na wykres timera snu. Zbliża się czas, by całkiem skrócić drzemkę i przesunąć wieczorne spanie wcześniej.', title_pt = 'Análise do temporizador de sono ⏱️', body_pt = 'À noite deita-se muito tarde? Veja o gráfico do temporizador de sono. Está a aproximar-se a altura de encurtar a sesta de vez e antecipar a hora de deitar.', title_sv = 'Analys med sömntimern ⏱️', body_sv = 'Somnar barnet väldigt sent på kvällarna? Titta på grafen i sömntimern. Det närmar sig dags att korta dagsömnen ordentligt och tidigarelägga kvällen.', title_vi = 'Phân tích Bộ hẹn giờ ngủ ⏱️', body_vi = 'Buổi tối bé đi ngủ quá muộn? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Sắp đến lúc rút ngắn hẳn giấc ngủ ngày và cho bé ngủ tối sớm hơn.', title_zh = '睡眠计时器分析 ⏱️', body_zh = '晚上睡得很晚？看看睡眠计时器的图表。快到该大幅缩短白天小睡、把晚上就寝时间提前的时候了。' WHERE id = '0b94a795-dee1-49c6-a4fb-e07d6174147f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿De repente le aprietan los zapatos? 👟', body_es = '¿Tropieza a menudo al correr? ¡Puede que le haya crecido el pie! Introduce su talla y número de pie actuales en el Seguimiento del desarrollo y sigue su crecimiento físico.', title_fr = 'Les chaussures serrent d''un coup ? 👟', body_fr = 'Il trébuche souvent en courant ? Son pied a peut-être grandi ! Entrez sa taille et sa pointure actuelles dans le Suivi de croissance et suivez son développement physique.', title_hi = 'जूते अचानक तंग हो गए? 👟', body_hi = 'दौड़ते समय अक्सर लड़खड़ाता है? शायद पैर बड़े हो गए हैं! ग्रोथ ट्रैकर में मौजूदा लंबाई और जूतों का साइज़ दर्ज कीजिए और शारीरिक विकास पर नज़र रखिए।', title_id = 'Sepatunya tiba-tiba sesak? 👟', body_id = 'Sering tersandung saat berlari? Kakinya mungkin sudah bertambah besar! Masukkan tinggi dan ukuran sepatunya saat ini ke Pelacak Perkembangan dan pantau pertumbuhan fisiknya.', title_ja = '急に靴がきつくなった？👟', body_ja = '走るとよくつまずきますか？足が大きくなったのかもしれません！「発達トラッカー」に今の身長と靴のサイズを入力して、体の成長を記録しましょう。', title_ko = '신발이 갑자기 끼나요? 👟', body_ko = '뛰다가 자주 넘어지나요? 발이 자랐을 수도 있어요! 성장 기록에 현재 키와 신발 치수를 입력하고 신체 발달을 지켜보세요.', title_nl = 'Knellen de schoenen ineens? 👟', body_nl = 'Struikelt hij vaak bij het rennen? Zijn voetjes kunnen gegroeid zijn! Voer zijn huidige lengte en schoenmaat in de Groeitracker in en volg zijn lichamelijke ontwikkeling.', title_pl = 'Buty nagle uciskają? 👟', body_pl = 'Często potyka się podczas biegania? Może urosła mu stopa! Wpisz aktualny wzrost i rozmiar butów w Śledzeniu rozwoju i śledź jego rozwój fizyczny.', title_pt = 'Os sapatos ficaram apertados de repente? 👟', body_pt = 'Tropeça muito quando corre? O pé pode ter crescido! Introduza a altura e o tamanho do sapato atuais no Registo de Desenvolvimento e acompanhe o crescimento físico.', title_sv = 'Klämmer skorna plötsligt? 👟', body_sv = 'Snubblar barnet ofta när hen springer? Foten kan ha växt! Ange aktuell längd och skostorlek i Utvecklingsspåraren och följ den fysiska utvecklingen.', title_vi = 'Giày bỗng dưng chật? 👟', body_vi = 'Bé hay vấp khi chạy? Có thể chân bé đã lớn! Hãy nhập chiều cao và cỡ giày hiện tại vào Theo dõi phát triển để theo sát sự phát triển thể chất.', title_zh = '鞋子突然挤脚了？👟', body_zh = '跑的时候经常绊倒？可能是脚长大了！在发育追踪里输入当前的身高和鞋码，跟进身体发育情况。' WHERE id = '225bd8fb-b294-42ab-8941-6c8eee154c5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Café o agua? 💧', body_es = '¡No intentes tapar el cansancio con cafeína! Descubre en Recetas saludables para mujeres bebidas detox con proteínas y fruta que dan energía.', title_fr = 'Café ou eau ? 💧', body_fr = 'N''essayez pas d''étouffer la fatigue avec de la caféine ! Découvrez dans les Recettes saines pour femmes des boissons détox énergisantes aux protéines et aux fruits.', title_hi = 'कॉफ़ी या पानी? 💧', body_hi = 'थकान को कैफ़ीन से दबाने की कोशिश मत कीजिए! महिलाओं के लिए सेहतमंद रेसिपी में ऊर्जा देने वाले प्रोटीन और फलों वाले डिटॉक्स ड्रिंक खोजिए।', title_id = 'Kopi, atau air? 💧', body_id = 'Jangan coba menutupi rasa lelah dengan kafein! Temukan minuman detoks buah kaya protein yang memberi energi di Resep Sehat untuk wanita.', title_ja = 'コーヒー？それともお水？💧', body_ja = '疲れをカフェインでごまかさないで！「女性のためのヘルシーレシピ」から、元気が出るたんぱく質とフルーツのデトックスドリンクを見つけましょう。', title_ko = '커피, 아니면 물? 💧', body_ko = '피로를 카페인으로 누르려 하지 마세요! 여성을 위한 건강한 레시피에서 힘이 나는 단백질 음료와 과일 디톡스 음료를 찾아보세요.', title_nl = 'Koffie of water? 💧', body_nl = 'Probeer je vermoeidheid niet weg te drukken met cafeïne! Ontdek in Gezonde recepten voor vrouwen energierijke detoxdrankjes met eiwit en fruit.', title_pl = 'Kawa czy woda? 💧', body_pl = 'Nie próbuj zagłuszać zmęczenia kofeiną! Odkryj w Zdrowych przepisach dla kobiet energetyczne napoje detoks z białkiem i owocami.', title_pt = 'Café ou água? 💧', body_pt = 'Não tente abafar o cansaço com cafeína! Descubra nas Receitas Saudáveis para Mulheres bebidas detox com proteína e fruta que dão energia.', title_sv = 'Kaffe eller vatten? 💧', body_sv = 'Försök inte dränka tröttheten i koffein! Upptäck energigivande detoxdrycker med protein och frukt i Hälsosamma recept för kvinnor.', title_vi = 'Cà phê hay nước lọc? 💧', body_vi = 'Đừng cố át mệt mỏi bằng caffeine! Hãy khám phá các thức uống detox giàu đạm và trái cây tiếp năng lượng trong Công thức lành mạnh cho phụ nữ.', title_zh = '咖啡，还是水？💧', body_zh = '别想用咖啡因压住疲惫！在女性健康食谱里发现能补充能量、富含蛋白质和水果的排毒饮品。' WHERE id = 'f7cd700a-6bea-4a3e-a6b4-0018529f2ea2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Chef en la cocina 👩‍🍳', body_es = 'Amasad juntos la masa de galletas sin azúcar de Recetas para bebé. Así desarrollará su motricidad y se comerá con ganas lo que ha hecho él mismo.', title_fr = 'Un chef en cuisine 👩‍🍳', body_fr = 'Pétrissez ensemble une pâte à biscuits sans sucre des Recettes pour bébés. Il développe sa motricité et mange avec appétit le fruit de son travail.', title_hi = 'रसोई में शेफ़ 👩‍🍳', body_hi = 'बच्चों की रेसिपी से बिना चीनी वाली कुकी का आटा साथ मिलकर गूँधिए। इससे उसकी मोटर स्किल्स भी बढ़ेंगी और वह अपनी मेहनत भी मज़े से खाएगा।', title_id = 'Koki di dapur 👩‍🍳', body_id = 'Uleni adonan kue kering tanpa gula dari Resep Bayi bersama-sama. Biarkan motoriknya berkembang dan ia lahap menyantap hasil karyanya sendiri.', title_ja = 'キッチンのシェフ 👩‍🍳', body_ja = '「離乳食を始める赤ちゃんのレシピ」から、砂糖不使用のクッキー生地を一緒にこねましょう。手先の力が育ち、自分でつくったものをおいしく食べられます。', title_ko = '주방의 요리사 👩‍🍳', body_ko = '아기 레시피의 설탕 없는 쿠키 반죽을 함께 주물러 보세요. 소근육도 키우고, 직접 만든 걸 맛있게 먹을 거예요.', title_nl = 'Kok in de keuken 👩‍🍳', body_nl = 'Kneed samen suikervrij koekjesdeeg uit Babyrecepten. Zo ontwikkelt hij zijn motoriek en eet hij met smaak wat hij zelf heeft gemaakt.', title_pl = 'Kucharz w kuchni 👩‍🍳', body_pl = 'Zagniećcie razem ciasto na ciasteczka bez cukru z Przepisów dla niemowląt. Niech rozwija motorykę i z apetytem zje owoc swojej pracy.', title_pt = 'Chef na cozinha 👩‍🍳', body_pt = 'Amassem juntos uma massa de bolachas sem açúcar das Receitas para bebés. Ele desenvolve a motricidade e come com apetite o fruto do seu trabalho.', title_sv = 'Kocken i köket 👩‍🍳', body_sv = 'Knåda deg till sockerfria kakor tillsammans från Recept för bebisar. Låt barnet både utveckla motoriken och äta sitt eget arbete med god aptit.', title_vi = 'Đầu bếp vào bếp 👩‍🍳', body_vi = 'Hãy cùng bé nhào bột bánh quy không đường từ Công thức cho bé. Vừa giúp bé phát triển vận động, vừa để bé ngon miệng thưởng thức thành quả của mình.', title_zh = '小厨师进厨房 👩‍🍳', body_zh = '用宝宝食谱一起揉无糖饼干面团吧。既锻炼动作能力，又能让宝宝津津有味地吃上自己的劳动成果。' WHERE id = '250e2ef0-defa-4388-a9c2-8574f1be0fed' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño alpinista 🧗', body_es = '¿Subirse a los muebles se ha convertido en su afición? Para que la casa sea lo más segura posible, echa un vistazo en Productos recomendados a los protectores especiales.', title_fr = 'Petit alpiniste 🧗', body_fr = 'Grimper sur les meubles est devenu son passe-temps ? Pour une sécurité maximale à la maison, jetez un œil aux protections spéciales des Produits recommandés.', title_hi = 'नन्हा पर्वतारोही 🧗', body_hi = 'फ़र्नीचर पर चढ़ना अब शौक बन गया है? घर को ज़्यादा से ज़्यादा सुरक्षित बनाने के लिए सुझाए गए प्रोडक्ट में खास गार्ड देखिए।', title_id = 'Pendaki Cilik 🧗', body_id = 'Memanjat perabot sudah jadi hobinya? Untuk memaksimalkan keamanan rumah, lihat pengaman khusus di Produk Rekomendasi.', title_ja = '小さな登山家 🧗', body_ja = '家具によじ登るのが趣味になっていますか？家の安全を最大限に高めるために、「おすすめ商品」で専用の安全グッズをチェックしましょう。', title_ko = '꼬마 등반가 🧗', body_ko = '가구 위에 오르는 게 취미가 되었나요? 집 안 안전을 최대로 높이도록 추천 제품에서 전용 안전 보호대를 살펴보세요.', title_nl = 'Kleine bergbeklimmer 🧗', body_nl = 'Is op meubels klimmen een hobby geworden? Bekijk in Aanbevolen producten speciale beveiligingen om je huis zo veilig mogelijk te maken.', title_pl = 'Mały alpinista 🧗', body_pl = 'Wspinanie się na meble stało się hobby? Aby maksymalnie zabezpieczyć dom, zajrzyj w Polecanych produktach do specjalnych zabezpieczeń.', title_pt = 'Pequeno alpinista 🧗', body_pt = 'Subir para cima dos móveis já é um passatempo? Para levar a segurança da casa ao máximo, espreite nos Produtos Recomendados os protetores especiais.', title_sv = 'Liten bergsklättrare 🧗', body_sv = 'Har klättring på möblerna blivit en hobby? Titta på speciella skydd i Rekommenderade produkter för att göra hemmet så säkert som möjligt.', title_vi = 'Nhà leo núi nhí 🧗', body_vi = 'Trèo lên đồ đạc đã thành sở thích của bé? Hãy xem các thiết bị bảo vệ chuyên dụng trong Sản phẩm gợi ý để ngôi nhà an toàn tối đa.', title_zh = '小小登山家 🧗', body_zh = '爬家具已经变成爱好了？为了把家里的安全做到最好，去推荐商品看看专用防护用品。' WHERE id = '2ee3ac65-4c9f-4558-a181-e43a5be6a221' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El murmullo del agua 🌊', body_es = '¿Ha sido un día muy intenso y lleno de carreras? Baja las luces, pon el murmullo del río de Ruido blanco y sumergíos los dos en la calma.', title_fr = 'L''eau qui ruisselle 🌊', body_fr = 'Une journée agitée et pleine de courses ? Baissez les lumières, lancez le murmure de la rivière des Bruits blancs et plongez tous les deux dans le calme.', title_hi = 'कलकल बहता पानी 🌊', body_hi = 'बहुत गुस्से और भाग-दौड़ भरा दिन था? बत्तियाँ धीमी कीजिए, व्हाइट नॉइज़ में नदी की कलकल लगाइए और दोनों बस शांति में डूब जाइए।', title_id = 'Gemericik air 🌊', body_id = 'Hari yang penuh amukan dan kejar-kejaran? Redupkan lampu, putar suara gemericik sungai dari Suara Putih, dan tenggelamlah berdua dalam ketenangan.', title_ja = 'さらさら流れる水の音 🌊', body_ja = 'とても激しく走り回った一日でしたか？照明を落として、「ホワイトノイズ」の小川のせせらぎを流し、ふたりで静けさに身をゆだねましょう。', title_ko = '졸졸 흐르는 물 🌊', body_ko = '거칠고 정신없는 하루였나요? 불을 낮추고 백색소음에서 시냇물 소리를 틀어 두 사람 모두 고요함에 잠겨 보세요.', title_nl = 'Kabbelend water 🌊', body_nl = 'Was het een heftige, drukke dag? Dim het licht, zet het kabbelen van een beekje uit Witte ruis aan en laat jullie allebei wegzakken in de rust.', title_pl = 'Szemrzące wody 🌊', body_pl = 'To był bardzo burzliwy dzień pełen bieganiny? Przygaś światło, włącz szum strumienia z Białego szumu i po prostu zanurzcie się oboje w ciszy.', title_pt = 'Água a correr 🌊', body_pt = 'Foi um dia muito agressivo e cheio de correria? Baixe as luzes, ligue o murmúrio do rio do Ruído Branco e mergulhem os dois no silêncio.', title_sv = 'Porlande vatten 🌊', body_sv = 'Har dagen varit väldigt aggressiv och full av springande? Dämpa ljuset, sätt på bäckens porlande från Vitt brus och sjunk båda bara in i lugnet.', title_vi = 'Róc rách suối chảy 🌊', body_vi = 'Một ngày quá nhiều căng thẳng và chạy nhảy? Hãy giảm ánh sáng, bật tiếng suối chảy trong Tiếng ồn trắng và để cả hai mẹ con chìm vào yên tĩnh.', title_zh = '哗哗的流水 🌊', body_zh = '今天又闹又跑，特别激烈？把灯光调暗，打开白噪音里的溪流声，你们俩一起沉浸在安静里吧。' WHERE id = 'e1c7d8a6-1882-42b5-8d1e-5420a73cc054' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Aplaúdete 🌟', body_es = '¿Has conseguido terminar el día sin rabietas? Sin ti, este desarrollo no sería posible. ¡Abre el Diario de ánimo y escríbete un enorme agradecimiento por tu entrega!', title_fr = 'Applaudissez-vous 🌟', body_fr = 'Vous avez réussi à finir la journée sans crise ? Sans vous, il n''y aurait pas de tels progrès. Ouvrez le Journal d''humeur et écrivez-vous un grand merci pour votre dévouement !', title_hi = 'खुद को शाबाशी दीजिए 🌟', body_hi = 'दिन बिना नखरों के बीत गया? आपके बिना यह विकास नहीं होता। मूड डायरी खोलिए और अपने त्याग के लिए खुद को एक बड़ा सा धन्यवाद लिखिए!', title_id = 'Beri tepuk tangan untuk diri Anda 🌟', body_id = 'Berhasil melewati hari tanpa tantrum? Tanpa Anda, perkembangan seperti ini tidak akan terjadi. Buka Buku Harian Suasana Hati dan tulis ucapan terima kasih yang besar untuk pengorbanan Anda!', title_ja = '自分に拍手を 🌟', body_ja = 'かんしゃくなしで一日を終えられましたか？あなたがいなければ、こんな成長はありません。「気分日記」を開いて、あなたの献身に大きな「ありがとう」を書きましょう！', title_ko = '나에게 박수를 🌟', body_ko = '오늘 떼쓰기 없이 하루를 마쳤나요? 엄마가 없었다면 이런 성장도 없었을 거예요. 기분 일기를 열고 나의 헌신에 큰 고마움을 적어 보세요!', title_nl = 'Applaus voor jezelf 🌟', body_nl = 'Kwam je de dag door zonder buien? Zonder jou zou deze ontwikkeling er niet zijn. Open je Stemmingsdagboek en schrijf jezelf een groot bedankje voor je toewijding!', title_pl = 'Nagródź się brawami 🌟', body_pl = 'Udało ci się przejść przez dzień bez kryzysów? Bez ciebie nie byłoby takiego rozwoju. Otwórz Dziennik nastroju i napisz sobie wielkie podziękowanie za twoje poświęcenie!', title_pt = 'Aplauda-se 🌟', body_pt = 'Conseguiu acabar o dia sem crises? Sem si, este desenvolvimento não existiria. Abra o Diário de Humor e escreva a si própria um grande obrigado pela sua dedicação!', title_sv = 'Applådera dig själv 🌟', body_sv = 'Klarade ni dagen utan utbrott? Utan dig skulle den här utvecklingen inte finnas. Öppna Humördagboken och skriv ett stort tack till dig själv för dina uppoffringar!', title_vi = 'Hãy tự vỗ tay cho mình 🌟', body_vi = 'Mẹ đã qua một ngày không có cơn ăn vạ nào? Không có mẹ, bé đã không phát triển được như vậy. Hãy mở Nhật ký tâm trạng và viết một lời cảm ơn thật lớn cho sự hy sinh của mình!', title_zh = '为自己鼓掌 🌟', body_zh = '今天顺利度过，没有崩溃？没有你，就没有这样的成长。打开心情日记，为你的付出给自己写一句大大的感谢吧！' WHERE id = '09840996-6ece-429b-8105-2969a0ec7d4b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ternura con los juguetes 🧸', body_es = '¿Le canta una nana a su osito o lo tapa con la manta? Es un gran desarrollo de la empatía. Añádelo en vídeo con sonido al Álbum del bebé y guarda su ternura.', title_fr = 'Tendresse pour les jouets 🧸', body_fr = 'Il chante une berceuse à son nounours ou le couvre ? C''est une belle empathie qui se développe. Ajoutez-le en vidéo avec le son à l''Album de bébé pour garder une trace de sa tendresse.', title_hi = 'खिलौनों के लिए ममता 🧸', body_hi = 'अपने भालू को लोरी सुनाता है या उसे चादर ओढ़ाता है? यह हमदर्दी का मज़बूत विकास है। इसे आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़िए और उसकी ममता को याद बनाइए।', title_id = 'Kasih sayang pada mainan 🧸', body_id = 'Menyanyikan lagu nina bobo untuk boneka beruangnya atau menyelimutinya? Ini perkembangan empati yang kuat. Simpan sebagai video bersuara di Album Bayi dan abadikan kasih sayangnya.', title_ja = 'おもちゃへのやさしさ 🧸', body_ja = 'くまさんに子守歌を歌ったり、毛布をかけてあげたりしていますか？これは思いやりがしっかり育っている証拠です。音声付きの動画で「ベビーアルバム」に追加して、そのやさしさを記録しましょう。', title_ko = '인형을 향한 다정함 🧸', body_ko = '곰 인형에게 자장가를 불러 주거나 이불을 덮어 주나요? 공감 능력이 쑥쑥 자라고 있어요. 소리가 담긴 영상으로 아기 앨범에 올려 이 다정함을 남겨 두세요.', title_nl = 'Liefde voor knuffels 🧸', body_nl = 'Zingt hij een slaapliedje voor zijn beer of stopt hij hem in? Dat is een sterke ontwikkeling van empathie. Leg zijn zorgzaamheid vast als video met geluid in het Babyalbum.', title_pl = 'Czułość dla zabawek 🧸', body_pl = 'Śpiewa misiowi kołysankę albo go przykrywa? To silny rozwój empatii. Dodaj to jako film z dźwiękiem do Albumu dziecka i uwiecznij jego czułość.', title_pt = 'Carinho pelos brinquedos 🧸', body_pt = 'Canta uma canção de embalar ao ursinho ou tapa-o? É um forte desenvolvimento da empatia. Adicione-o em vídeo com som ao Álbum do Bebé e registe este carinho.', title_sv = 'Omtanke om leksakerna 🧸', body_sv = 'Sjunger barnet vaggvisor för nallen eller bäddar ner den? Det är en stark empatiutveckling. Lägg till den som video med ljud i Babyalbumet och spara omtanken.', title_vi = 'Yêu thương đồ chơi 🧸', body_vi = 'Bé hát ru gấu bông hay đắp chăn cho gấu? Đây là sự phát triển mạnh mẽ của lòng đồng cảm. Hãy thêm video có tiếng vào Album của bé để ghi lại sự dịu dàng này.', title_zh = '对玩具的温柔 🧸', body_zh = '给小熊唱摇篮曲，或者给它盖被子？这是很强的共情发展。录成有声视频加进宝宝相册，记下这份温柔。' WHERE id = '152dc6e1-3207-4818-a59d-35cf71d6d914' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explosión de vocabulario 🗣️', body_es = '¿Cómo va su vocabulario? Descubre en el Blog los estándares del desarrollo del habla de este mes y juegos caseros que lo apoyan.', title_fr = 'Explosion de vocabulaire 🗣️', body_fr = 'Où en est son vocabulaire ? Découvrez dans la rubrique Blogs les repères de langage de ce mois et des jeux à la maison pour soutenir son développement.', title_hi = 'शब्दों का धमाका 🗣️', body_hi = 'शब्द भंडार कैसा है? ब्लॉग सेक्शन में इस महीने के बोली के विकास के मानक और विकास में मदद करने वाले घरेलू खेल जानिए।', title_id = 'Ledakan kosakata 🗣️', body_id = 'Bagaimana kosakatanya? Temukan standar perkembangan bicara bulan ini dan permainan rumahan pendukungnya di bagian Blog.', title_ja = '語彙の爆発 🗣️', body_ja = '語彙はどれくらい増えましたか？この月齢の言葉の発達の目安と、成長を応援するおうち遊びを、ブログで見つけましょう。', title_ko = '어휘 폭발 🗣️', body_ko = '어휘는 얼마나 늘었나요? 블로그에서 이번 달 언어 발달 기준과 발달을 돕는 집 놀이를 알아보세요.', title_nl = 'Woordenexplosie 🗣️', body_nl = 'Hoe staat het met zijn woordenschat? Ontdek in Blogs de normen voor taalontwikkeling van deze maand en spelletjes voor thuis die de ontwikkeling steunen.', title_pl = 'Eksplozja słownictwa 🗣️', body_pl = 'Jak tam zasób słów? Odkryj w sekcji Blog normy rozwoju mowy w tym miesiącu i domowe zabawy, które go wspierają.', title_pt = 'Explosão de vocabulário 🗣️', body_pt = 'Como está o vocabulário? Descubra nos Blogues os padrões de desenvolvimento da fala deste mês e jogos caseiros que o apoiam.', title_sv = 'Ordexplosion 🗣️', body_sv = 'Hur är det med ordförrådet? Upptäck månadens normer för talutveckling och lekar hemma som stöttar utvecklingen i Bloggar.', title_vi = 'Bùng nổ vốn từ 🗣️', body_vi = 'Vốn từ của bé thế nào rồi? Hãy khám phá chuẩn phát triển ngôn ngữ của tháng này và các trò chơi tại nhà hỗ trợ phát triển trong mục Blog.', title_zh = '词汇大爆发 🗣️', body_zh = '词汇量怎么样？去博客板块发现这个月的语言发展标准，以及支持发展的居家游戏。' WHERE id = 'cb411136-f146-4918-b034-820fe50cfd21' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La comida toma forma ⭐️', body_es = '¿No se come la fruta cortada sin más? Mira en Recetas para bebé presentaciones divertidas con forma de estrella o de animales y convierte la comida en un juego visual.', title_fr = 'Les repas prennent forme ⭐️', body_fr = 'Il ne mange pas les fruits simplement coupés ? Regardez dans les Recettes pour bébés des présentations amusantes en forme d''étoile ou d''animal et transformez le repas en jeu visuel.', title_hi = 'खाने को आकार मिल रहे हैं ⭐️', body_hi = 'साधारण कटे फल नहीं खाता? बच्चों की रेसिपी में तारे या जानवरों के आकार में मज़ेदार तरीके से परोसने के आइडिया देखिए और खाने को देखने वाला खेल बना दीजिए।', title_id = 'Makanan berbentuk lucu ⭐️', body_id = 'Tidak mau makan buah yang dipotong biasa? Lihat penyajian piring seru berbentuk bintang atau hewan di Resep Bayi dan jadikan waktu makan permainan visual.', title_ja = '食べ物がいろんな形に ⭐️', body_ja = 'ふつうに切った果物は食べない？「離乳食を始める赤ちゃんのレシピ」で、星や動物の形の楽しい盛り付けをチェックして、食事を目で楽しむ遊びに変えましょう。', title_ko = '음식이 모양을 갖춰요 ⭐️', body_ko = '그냥 썬 과일은 안 먹나요? 아기 레시피에서 별이나 동물 모양의 재미있는 담음새를 살펴보고 식사를 눈으로 즐기는 놀이로 바꿔 보세요.', title_nl = 'Eten in vormpjes ⭐️', body_nl = 'Eet hij gewoon gesneden fruit niet? Bekijk in Babyrecepten leuke borden met ster- of dierenvormen en maak van eten een visueel spel.', title_pl = 'Jedzenie nabiera kształtów ⭐️', body_pl = 'Nie je zwykłych pokrojonych owoców? Zajrzyj w Przepisach dla niemowląt do zabawnych sposobów podania w kształcie gwiazdek lub zwierzątek i zamień jedzenie w wizualną zabawę.', title_pt = 'A comida ganha formas ⭐️', body_pt = 'Não come a fruta cortada às fatias? Veja nas Receitas para bebés apresentações divertidas em forma de estrela ou de animais e transforme a refeição num jogo visual.', title_sv = 'Maten får former ⭐️', body_sv = 'Äter barnet inte vanlig skuren frukt? Titta på roliga tallriksupplägg i stjärn- eller djurform i Recept för bebisar och gör maten till en visuell lek.', title_vi = 'Thức ăn có hình thù ⭐️', body_vi = 'Bé không chịu ăn trái cây cắt bình thường? Hãy xem những cách bày đĩa vui nhộn hình ngôi sao hay con vật trong Công thức cho bé để biến bữa ăn thành trò chơi thị giác.', title_zh = '食物变成了图案 ⭐️', body_zh = '普通切好的水果不肯吃？看看宝宝食谱里星星或动物造型的趣味摆盘，把吃饭变成视觉游戏。' WHERE id = '047ed43c-bb7c-4206-afa0-67d1dc0f765d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se esconde para hacer caca? 🙈', body_es = '¿Se va detrás de la cortina o a un rincón para hacer caca? ¡Es la mayor señal psicológica de que está preparado para el orinal! Anótalo en el Seguimiento de pañales y lee en el Blog los artículos para dejar el pañal.', title_fr = 'Il se cache pour faire caca ? 🙈', body_fr = 'Il se retire derrière le rideau ou dans un coin pour faire ses besoins ? C''est le plus grand signal psychologique qu''il est prêt pour le pot ! Notez-le dans le Suivi des couches et lisez les articles d''apprentissage dans la rubrique Blogs.', title_hi = 'छिपकर पॉटी करता है? 🙈', body_hi = 'पर्दे के पीछे या कोने में जाकर पॉटी करता है? यह पॉटी के लिए तैयार होने का सबसे बड़ा मनोवैज्ञानिक संकेत है! डायपर ट्रैकर में दर्ज कीजिए और ब्लॉग में ट्रेनिंग के लेख पढ़िए।', title_id = 'Bersembunyi saat BAB? 🙈', body_id = 'Menyendiri di balik gorden atau di sudut saat BAB? Ini sinyal psikologis terbesar kesiapan pispot! Catat di Pelacak Popok dan baca artikel latihannya di Blog.', title_ja = '隠れてうんちをする？🙈', body_ja = 'カーテンの裏や部屋のすみに行ってうんちをしますか？これはトイレの準備ができている、いちばん大きな心理的サインです！「おむつトラッカー」に記録して、ブログでトレーニングの記事を読みましょう。', title_ko = '숨어서 응가하나요? 🙈', body_ko = '커튼 뒤나 구석에 숨어서 응가하나요? 배변 훈련 준비가 되었다는 가장 큰 심리적 신호예요! 기저귀 기록에 남기고 블로그에서 훈련 관련 글을 읽어 보세요.', title_nl = 'Verstopt hij zich om te poepen? 🙈', body_nl = 'Trekt hij zich terug achter het gordijn of in een hoekje om te poepen? Dat is het grootste psychologische signaal dat hij klaar is voor het potje! Noteer het in de Luiertracker en lees de artikelen over zindelijkheid in Blogs.', title_pl = 'Chowa się, żeby zrobić kupkę? 🙈', body_pl = 'Robi kupkę za zasłoną albo w kącie? To najważniejszy psychologiczny sygnał gotowości do nocnika! Zapisz to w narzędziu do śledzenia pieluszek i przeczytaj artykuły o nauce na Blogu.', title_pt = 'Esconde-se para fazer cocó? 🙈', body_pt = 'Esconde-se atrás da cortina ou num canto para fazer cocó? É o maior sinal psicológico de que está pronto para o bacio! Registe-o no Registo de Fraldas e leia nos Blogues os artigos sobre o treino.', title_sv = 'Gömmer sig för att bajsa? 🙈', body_sv = 'Drar sig barnet undan bakom gardinen eller i ett hörn för att bajsa? Det är den största psykologiska signalen på att barnet är redo för pottan! Anteckna i Blöjkollen och läs artiklarna om träning i Bloggar.', title_vi = 'Trốn đi để "ị"? 🙈', body_vi = 'Bé nấp sau rèm hoặc vào góc để đi ngoài? Đây là tín hiệu tâm lý lớn nhất cho thấy bé sẵn sàng ngồi bô! Hãy ghi lại trong Theo dõi tã và đọc bài viết về tập luyện trong mục Blog.', title_zh = '躲起来拉臭臭？🙈', body_zh = '躲到窗帘后面或角落里拉便便？这是准备好用便盆的最大心理信号！记在尿布记录里，再去博客读读训练文章。' WHERE id = '5f17b1b2-9554-4ba7-b535-5f0af1522385' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Te duele la espalda? 🧘‍♀️', body_es = 'Tus músculos están tensos de coger a tu peque, que cada vez pesa más. Prepárate un té de jengibre antiinflamatorio de Recetas saludables para mujeres, túmbate y dedícate un rato.', title_fr = 'Votre dos souffre ? 🧘‍♀️', body_fr = 'Vos muscles sont tendus à force de porter votre petit qui s''alourdit. Préparez une tisane de gingembre anti-inflammatoire avec les Recettes saines pour femmes, allongez-vous et prenez du temps pour vous.', title_hi = 'कमर दुख रही है? 🧘‍♀️', body_hi = 'भारी होते नन्हे को उठाते-उठाते आपकी मांसपेशियाँ तन गई हैं। महिलाओं के लिए सेहतमंद रेसिपी से सूजन कम करने वाली अदरक की चाय बनाइए, लेटिए और अपने लिए समय निकालिए।', title_id = 'Punggung Anda nyeri? 🧘‍♀️', body_id = 'Otot Anda tegang karena menggendong si kecil yang makin berat. Seduh teh jahe antiradang dari Resep Sehat untuk wanita, berbaringlah, dan luangkan waktu untuk diri sendiri.', title_ja = '腰が痛む？🧘‍♀️', body_ja = '重くなってきたお子さんを抱き上げて、筋肉がこわばっていますか？「女性のためのヘルシーレシピ」から炎症をおさえるしょうが茶をいれて、横になり、自分のための時間をとりましょう。', title_ko = '허리가 쑤시나요? 🧘‍♀️', body_ko = '점점 무거워지는 아이를 안아 올리느라 근육이 뭉쳤나요? 여성을 위한 건강한 레시피에서 염증을 줄이는 생강차를 우려 누워서 나를 위한 시간을 가지세요.', title_nl = 'Zeurt je rug? 🧘‍♀️', body_nl = 'Je spieren zijn gespannen van het tillen van je zwaarder wordende kleintje. Zet ontstekingsremmende gemberthee uit Gezonde recepten voor vrouwen, ga liggen en neem tijd voor jezelf.', title_pl = 'Bolą cię plecy? 🧘‍♀️', body_pl = 'Mięśnie masz napięte od podnoszenia coraz cięższego malucha. Zaparz ze Zdrowych przepisów dla kobiet przeciwzapalną herbatę imbirową, połóż się i znajdź czas dla siebie.', title_pt = 'As costas doem-lhe? 🧘‍♀️', body_pt = 'Os músculos ficaram tensos de tanto pegar num pequenino cada vez mais pesado. Prepare um chá de gengibre anti-inflamatório das Receitas Saudáveis para Mulheres, deite-se e reserve tempo para si.', title_sv = 'Värker ryggen? 🧘‍♀️', body_sv = 'Musklerna är spända av att lyfta en allt tyngre liten. Brygg ett antiinflammatoriskt ingefärste från Hälsosamma recept för kvinnor, lägg dig ner och ta tid för dig själv.', title_vi = 'Lưng mẹ ê ẩm? 🧘‍♀️', body_vi = 'Bế bé ngày càng nặng khiến cơ của mẹ căng cứng. Hãy pha trà gừng chống viêm từ Công thức lành mạnh cho phụ nữ, nằm nghỉ và dành thời gian cho mình.', title_zh = '腰酸背痛？🧘‍♀️', body_zh = '抱越来越重的小家伙，让你的肌肉紧绷。从女性健康食谱里泡一杯抗炎的姜茶，躺下来给自己一点时间。' WHERE id = 'c569bc01-3134-4ece-a6d6-d600fb0bf88b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de «Me visto yo» 👕', body_es = '¿Intenta ponerse los pantalones en la cabeza y la camiseta en los pies? ¡No te pierdas este divertido intento de independencia! Decóralo ya con las pegatinas alegres de la Sesión de fotos del bebé y súbelo al álbum.', title_fr = 'L''art du « Je m''habille tout seul » 👕', body_fr = 'Il essaie d''enfiler son pantalon sur la tête et son t-shirt aux pieds ? Ne manquez surtout pas cet essai d''autonomie rigolo ! Décorez-le tout de suite avec les stickers joyeux de la Séance photo bébé et ajoutez-le à l''album.', title_hi = '''मैं खुद पहनूँगा'' की कला 👕', body_hi = 'पैंट सिर पर और कमीज़ पैरों में पहनने की कोशिश करता है? आत्मनिर्भरता की इस मज़ेदार कोशिश को बिल्कुल मत चूकिए! तुरंत बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम में अपलोड कीजिए।', title_id = 'Seni berpakaian sendiri 👕', body_id = 'Mencoba memakai celana di kepala dan baju di kaki? Jangan lewatkan usaha mandiri yang lucu ini! Segera hiasi dengan stiker ceria dari Sesi Foto Bayi dan unggah ke album.', title_ja = '「自分で着る」の芸術 👕', body_ja = 'ズボンを頭に、シャツを足に着ようとしていますか？このおもしろい自立の挑戦を見逃さないで！すぐに「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムにアップしましょう。', title_ko = '혼자 입기의 기술 👕', body_ko = '바지를 머리에, 셔츠를 다리에 입으려고 하나요? 이 웃긴 자립 시도를 절대 놓치지 마세요! 바로 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에 올려 보세요.', title_nl = 'De kunst van zelf aankleden 👕', body_nl = 'Probeert hij zijn broek over zijn hoofd en zijn shirt om zijn voeten te doen? Mis deze grappige poging tot zelfstandigheid niet! Versier het meteen met vrolijke stickers in Babyfotoshoot en zet het in het album.', title_pl = 'Sztuka „Sam się ubiorę” 👕', body_pl = 'Próbuje włożyć spodnie na głowę, a koszulkę na nogi? Nie przegap tej zabawnej próby samodzielności! Od razu ozdób zdjęcie wesołymi naklejkami z Sesji zdjęciowej dziecka i dodaj do albumu.', title_pt = 'A arte do "Eu visto-me sozinho" 👕', body_pt = 'Tenta enfiar as calças pela cabeça e a camisola pelos pés? Não perca esta tentativa divertida de independência! Decore-a já com os autocolantes alegres da Sessão Fotográfica do Bebé e carregue-a no álbum.', title_sv = 'Konsten att klä på sig själv 👕', body_sv = 'Försöker barnet ta byxorna över huvudet och tröjan på benen? Missa inte detta roliga försök till självständighet! Dekorera det direkt med glada klistermärken i Babyfotografering och ladda upp det i albumet.', title_vi = 'Nghệ thuật "Con tự mặc" 👕', body_vi = 'Bé cố mặc quần lên đầu, áo xuống chân? Đừng bỏ lỡ nỗ lực tự lập hài hước này! Hãy trang trí ngay bằng sticker vui nhộn trong Chụp ảnh cho bé và tải lên album.', title_zh = '“我要自己穿”的艺术 👕', body_zh = '想把裤子套到头上，把上衣穿到脚上？千万别错过这个搞笑的独立尝试！马上用宝宝写真里欢乐的贴纸装饰一下，上传到相册。' WHERE id = '504aaa66-e4f6-4eca-bd17-eead2d69deec' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando charcos 🌧️', body_es = '¡Después de la lluvia no hay que quedarse en casa! Busca en Lugares para mamás un parque cercano, ponle las botas de agua y déjale saltar en el barro.', title_fr = 'Exploration des flaques 🌧️', body_fr = 'Après la pluie, pas question de rester à la maison ! Trouvez un parc près de chez vous dans les Lieux adaptés aux mamans, mettez-lui ses bottes en caoutchouc et laissez-le sauter dans la boue.', title_hi = 'पानी के गड्ढों की खोज 🌧️', body_hi = 'बारिश के बाद घर में बैठना मना है! माँ के लिए अनुकूल जगहें में पास का पार्क ढूँढिए, उसे रबर के जूते पहनाइए और कीचड़ में कूदने दीजिए।', title_id = 'Menjelajahi genangan 🌧️', body_id = 'Setelah hujan, jangan diam di rumah! Temukan taman terdekat di Tempat Ramah Ibu, pakaikan sepatu bot karetnya, dan biarkan ia melompat di genangan lumpur.', title_ja = '水たまり探検 🌧️', body_ja = '雨上がりに家にいるなんてもったいない！「ママにやさしいスポット」で近くの公園を見つけ、長ぐつをはかせて、泥んこの中でジャンプさせてあげましょう。', title_ko = '물웅덩이 탐험 🌧️', body_ko = '비 온 뒤에는 집에만 있을 수 없죠! 엄마 친화 장소에서 가까운 공원을 찾아 장화를 신기고 진흙탕에서 첨벙첨벙 뛰게 해 주세요.', title_nl = 'Plassen ontdekken 🌧️', body_nl = 'Na de regen blijf je niet binnen! Zoek in Mamavriendelijke plekken een park in de buurt, trek hem zijn regenlaarzen aan en laat hem in de modder springen.', title_pl = 'Wyprawa po kałużach 🌧️', body_pl = 'Po deszczu nie można siedzieć w domu! Znajdź w Miejscach przyjaznych mamom pobliski park, załóż mu kalosze i pozwól skakać po błocie.', title_pt = 'Exploração das poças 🌧️', body_pt = 'Depois da chuva, nada de ficar em casa! Encontre nos Locais Amigos das Mães um parque perto, calce-lhe as galochas e deixe-o saltar na lama.', title_sv = 'Vattenpölsäventyr 🌧️', body_sv = 'Efter regnet kan man inte sitta inne! Hitta en park i närheten i Mammavänliga platser, ta på gummistövlarna och låt barnet hoppa i leran.', title_vi = 'Khám phá vũng nước 🌧️', body_vi = 'Sau cơn mưa thì không thể ngồi trong nhà! Hãy tìm công viên gần nhà trong Địa điểm thân thiện với mẹ, cho bé đi ủng cao su và để bé nhảy trong bùn.', title_zh = '探索水坑 🌧️', body_zh = '雨后可不能待在家里！在妈妈友好场所里找到附近的公园，给宝宝穿上雨靴，让宝宝在泥地里蹦跳吧。' WHERE id = 'c0ee7f2f-8895-4772-8368-647fe5fed56e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La ventana de sueño se desplaza ⏱️', body_es = '¿Hoy no ha querido dormir la siesta? Para que no llegue agotado a la noche y tenga una rabieta, pon el temporizador de sueño y adelanta la rutina de la noche 30 minutos.', title_fr = 'La fenêtre de sommeil se décale ⏱️', body_fr = 'Il a refusé la sieste ? Pour éviter qu''il soit trop fatigué et fasse une crise le soir, lancez le minuteur de sommeil et avancez le rituel du soir de 30 minutes.', title_hi = 'नींद की खिड़की खिसक रही है ⏱️', body_hi = 'दिन में सोने से मना कर दिया? शाम को बहुत थककर नखरे न करे, इसके लिए स्लीप टाइमर चालू कीजिए और शाम का रूटीन 30 मिनट जल्दी कीजिए।', title_id = 'Jendela tidurnya bergeser ⏱️', body_id = 'Menolak tidur siang? Agar ia tidak terlalu lelah dan tantrum di sore hari, nyalakan Timer Tidur dan majukan rutinitas malamnya 30 menit.', title_ja = '眠りのタイミングがずれてきた ⏱️', body_ja = 'お昼寝を嫌がりましたか？夕方に疲れすぎてかんしゃくを起こさないよう、睡眠タイマーをオンにして、夜の生活リズムを30分早めましょう。', title_ko = '수면 간격이 바뀌고 있어요 ⏱️', body_ko = '낮잠을 거부했나요? 저녁에 너무 피곤해서 떼쓰지 않도록 수면 타이머를 켜고 저녁 일과를 30분 앞당겨 주세요.', title_nl = 'Het slaapvenster verschuift ⏱️', body_nl = 'Sloeg hij zijn middagdutje over? Zet de Slaaptimer aan en vervroeg het avondritme met 30 minuten, zodat hij ''s avonds niet oververmoeid raakt en een bui krijgt.', title_pl = 'Okno snu się przesuwa ⏱️', body_pl = 'Odmówił drzemki? Aby wieczorem nie był przemęczony i nie miał kryzysu, włącz timer snu i przesuń wieczorny rytm o 30 minut wcześniej.', title_pt = 'A janela de sono está a mudar ⏱️', body_pt = 'Recusou a sesta? Para não chegar à noite cansado demais e ter uma crise, ligue o temporizador de sono e antecipe 30 minutos a rotina da noite.', title_sv = 'Sömnfönstret glider ⏱️', body_sv = 'Vägrade barnet dagsömnen? Starta sömntimern och tidigarelägg kvällsrutinen med 30 minuter så att barnet inte blir övertrött och får ett utbrott på kvällen.', title_vi = 'Khung giờ ngủ bị lệch ⏱️', body_vi = 'Bé bỏ giấc ngủ ngày? Để buổi tối bé không quá mệt mà ăn vạ, hãy bật Bộ hẹn giờ ngủ và cho bé đi ngủ tối sớm hơn 30 phút.', title_zh = '睡眠窗口推迟了 ⏱️', body_zh = '不肯睡午觉？为了不让宝宝晚上累到崩溃，打开睡眠计时器，把晚上的作息提前30分钟。' WHERE id = 'e70f443c-46d9-4882-ab14-fad93c425a0f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La motricidad de los dedos avanza 🧩', body_es = 'Ya se sabe de memoria los puzles sencillos. Descubre en Productos recomendados rompecabezas de madera más complejos y de muchas piezas que pongan a prueba su inteligencia.', title_fr = 'La motricité fine se développe 🧩', body_fr = 'Il connaît déjà par cœur les puzzles simples. Découvrez dans les Produits recommandés des puzzles en bois plus complexes, à plusieurs pièces, qui mettront son intelligence au défi.', title_hi = 'उँगलियों की मोटर स्किल्स बढ़ रही हैं 🧩', body_hi = 'उसे आसान पज़ल अब याद हो गई हैं। उसकी बुद्धि को और चुनौती देने वाली, कई टुकड़ों वाली मुश्किल लकड़ी की पहेलियाँ सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Motorik jari sedang berkembang 🧩', body_id = 'Ia sudah hafal puzzle sederhana. Temukan puzzle kayu yang lebih rumit dengan banyak keping untuk lebih menantang kecerdasannya di bagian Produk Rekomendasi.', title_ja = '指先の力が育っている 🧩', body_ja = '簡単なパズルはもう覚えてしまいました。知性をさらに刺激する、もっと難しいピースの多い木のパズルを「おすすめ商品」で見つけましょう。', title_ko = '손가락 소근육이 자라요 🧩', body_ko = '이제 간단한 퍼즐은 다 외웠어요. 두뇌를 더 자극할 조각이 많은 원목 퍼즐을 추천 제품 섹션에서 찾아보세요.', title_nl = 'De fijne motoriek ontwikkelt zich 🧩', body_nl = 'Simpele puzzels kent hij al uit zijn hoofd. Ontdek in Aanbevolen producten moeilijkere houten puzzels met meer stukjes die zijn verstand nog meer uitdagen.', title_pl = 'Motoryka paluszków się rozwija 🧩', body_pl = 'Proste układanki zna już na pamięć. Odkryj w sekcji Polecane produkty bardziej złożone, wieloelementowe drewniane układanki, które jeszcze mocniej pobudzą jego umysł.', title_pt = 'A motricidade dos dedos está a desenvolver-se 🧩', body_pt = 'Já sabe de cor os puzzles simples. Descubra na secção Produtos Recomendados puzzles de madeira mais complexos, com muitas peças, que vão desafiar ainda mais a inteligência dele.', title_sv = 'Fingermotoriken utvecklas 🧩', body_sv = 'Barnet kan redan de enkla pusslen utantill. Upptäck svårare träpussel med många bitar som utmanar tänkandet ännu mer i Rekommenderade produkter.', title_vi = 'Vận động tinh của ngón tay đang phát triển 🧩', body_vi = 'Bé đã thuộc lòng các bộ ghép hình đơn giản. Hãy khám phá các bộ ghép hình gỗ phức tạp hơn, nhiều mảnh hơn giúp bé động não nhiều hơn trong mục Sản phẩm gợi ý.', title_zh = '手指精细动作在发展 🧩', body_zh = '简单的拼图宝宝已经背熟了。在推荐商品板块发现更复杂、多块的木制拼图，给宝宝的小脑瓜更多挑战。' WHERE id = '65eaf451-e5ab-4c54-9b0f-1a6331bd0312' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabieta en el suelo 🛑', body_es = '¿Se tira al suelo gritando en un lugar público? ¡Olvida las miradas! Desahógate con Anacan AI y aprende estrategias para gestionar con calma estas explosiones emocionales tan intensas.', title_fr = 'Crise de larmes par terre 🛑', body_fr = 'Il se jette par terre en hurlant en public ? Ignorez les regards ! Discutez avec Anacan AI pour apprendre des techniques et gérer ces violentes explosions émotionnelles avec sang-froid.', title_hi = 'फ़र्श पर रोने का तूफ़ान 🛑', body_hi = 'सबके सामने ज़मीन पर लोटकर चिल्लाता है? आसपास की नज़रों की परवाह छोड़िए! इन तेज़ भावनात्मक विस्फोटों को शांति से संभालने के तरीके Anacan AI से बात करके सीखिए।', title_id = 'Tantrum menangis di lantai 🛑', body_id = 'Menjatuhkan diri dan menjerit di tempat umum? Abaikan tatapan orang lain! Curhatlah kepada Anacan AI dan pelajari taktik menghadapi ledakan emosi yang hebat ini dengan tenang.', title_ja = '床でのかんしゃく 🛑', body_ja = '人前で床にひっくり返って叫びますか？周りの視線は気にしないで！この激しい気持ちの爆発に落ち着いて対応するために、Anacan AIに相談して、対応のコツを学びましょう。', title_ko = '바닥에 드러누워 울어요 🛑', body_ko = '사람들 앞에서 바닥에 드러누워 소리 지르나요? 주변 시선은 신경 쓰지 마세요! 이런 격한 감정 폭발을 침착하게 다루도록 Anacan AI와 이야기하며 요령을 배워 보세요.', title_nl = 'Huilbui op de vloer 🛑', body_nl = 'Gooit hij zich in het openbaar schreeuwend op de grond? Trek je niets aan van de blikken! Praat met Anacan AI en leer tactieken om deze heftige uitbarstingen kalm aan te pakken.', title_pl = 'Kryzys z płaczem na podłodze 🛑', body_pl = 'W miejscu publicznym rzuca się na ziemię i krzyczy? Nie przejmuj się spojrzeniami innych! Porozmawiaj z Anacan AI i poznaj sposoby, by spokojnie radzić sobie z tymi gwałtownymi wybuchami emocji.', title_pt = 'Crise de choro no chão 🛑', body_pt = 'Atira-se para o chão e grita num local público? Não ligue aos olhares à volta! Desabafe com o Anacan AI e aprenda táticas para gerir com calma estas explosões emocionais intensas.', title_sv = 'Gråtutbrott på golvet 🛑', body_sv = 'Kastar sig barnet på golvet och skriker på en offentlig plats? Strunta i omgivningens blickar! Prata med Anacan AI och lär dig taktiker för att lugnt hantera dessa häftiga känsloutbrott.', title_vi = 'Khóc lăn lộn trên sàn 🛑', body_vi = 'Bé lăn ra sàn la hét nơi công cộng? Mặc kệ ánh nhìn xung quanh! Hãy trò chuyện với Anacan AI để học chiến thuật bình tĩnh xử lý những cơn bùng nổ cảm xúc dữ dội này.', title_zh = '在地板上哭闹崩溃 🛑', body_zh = '在公共场合躺地上尖叫？别管周围的目光！和Anacan AI聊聊，学习冷静应对这种激烈情绪爆发的策略。' WHERE id = 'c2a5ae09-9d8c-4ef8-afa7-4f35fb948c6f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Libros para leer, no para romper 📖', body_es = '¿Arranca las páginas a la hora del cuento? Lee en el Blog cómo captar su atención con el cuento sin dañar el hábito de la lectura.', title_fr = 'Lire les livres, pas les déchirer 📖', body_fr = 'Il déchire les pages à l''heure du conte du soir ? Lisez dans la rubrique Blogs comment capter son attention sur l''histoire sans abîmer son goût pour la lecture.', title_hi = 'किताब फाड़ना नहीं, पढ़ना 📖', body_hi = 'शाम की कहानी के समय पन्ने फाड़ता है? पढ़ने की आदत बिगाड़े बिना उसका ध्यान कहानी की ओर कैसे लाएँ, यह ब्लॉग सेक्शन में पढ़िए।', title_id = 'Membaca buku, bukan merobeknya 📖', body_id = 'Merobek halaman saat dongeng malam? Baca di bagian Blog cara menarik perhatiannya ke cerita tanpa merusak kebiasaan membacanya.', title_ja = '絵本は破らずに読もう 📖', body_ja = '夜の読み聞かせの時間にページを破りますか？読書の習慣を損なわずに、お話に集中させる方法をブログで読んでみましょう。', title_ko = '찢지 말고 읽어요 📖', body_ko = '잠자리 동화 시간에 책장을 찢나요? 책 읽는 습관을 해치지 않고 동화에 집중하게 하는 방법을 블로그에서 읽어 보세요.', title_nl = 'Boeken lezen, niet scheuren 📖', body_nl = 'Scheurt hij bij het avondverhaal de bladzijden kapot? Lees in Blogs hoe je zijn aandacht bij het verhaal houdt zonder zijn leesplezier te beschadigen.', title_pl = 'Nie drzemy książek, tylko czytamy 📖', body_pl = 'Podczas wieczornej bajki drze strony? Przeczytaj w sekcji Blog, jak przyciągnąć jego uwagę do bajki, nie zniechęcając go do czytania.', title_pt = 'Ler, não rasgar 📖', body_pt = 'Na hora da história da noite, rasga as páginas? Leia nos Blogues como captar a atenção dele para a história sem prejudicar o hábito da leitura.', title_sv = 'Läsa böcker, inte riva sönder dem 📖', body_sv = 'River barnet sönder sidorna vid kvällssagan? Läs i Bloggar hur du fångar barnets uppmärksamhet för sagan utan att skada läsvanan.', title_vi = 'Đọc sách, không xé sách 📖', body_vi = 'Giờ kể chuyện buổi tối bé xé trang sách? Hãy đọc trong mục Blog cách thu hút sự chú ý của bé vào câu chuyện mà không làm mất thói quen đọc sách.', title_zh = '不撕书，读书 📖', body_zh = '晚上讲故事时把书页撕碎？去博客板块读读，如何在不破坏阅读习惯的前提下把宝宝的注意力吸引到故事上。' WHERE id = 'f9afcff7-9182-4728-9ed2-135f5b97e440' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El calcio no es solo leche 🧀', body_es = '¿No quiere beber leche? El calcio es imprescindible para los huesos. Calcula con el Seguimiento de tomas el queso, el yogur o el brócoli de hoy y completa lo que falte.', title_fr = 'Le calcium, ce n''est pas que le lait 🧀', body_fr = 'Il refuse de boire du lait ? Le calcium est indispensable aux os. Calculez avec le Suivi des repas ce qu''il a mangé de fromage, de yaourt ou de brocoli aujourd''hui et comblez les manques.', title_hi = 'कैल्शियम सिर्फ़ दूध में नहीं 🧀', body_hi = 'दूध पीने से मना करता है? हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से आज का पनीर, दही या ब्रोकली गिनिए और कमी पूरी कीजिए।', title_id = 'Kalsium bukan hanya dari susu 🧀', body_id = 'Menolak minum susu? Kalsium wajib untuk tulang. Hitung asupan keju, yogurt, atau brokoli hari ini dengan alat Pemantau Nutrisi dan lengkapi kekurangannya.', title_ja = 'カルシウムは牛乳だけじゃない 🧀', body_ja = '牛乳を飲みたがらない？骨にはカルシウムが欠かせません。「栄養管理ツール」で今日のチーズ、ヨーグルト、ブロッコリーの量を計算して、足りない分を補いましょう。', title_ko = '칼슘은 우유만이 아니에요 🧀', body_ko = '우유를 안 마시려 하나요? 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 치즈, 요거트, 브로콜리 섭취를 계산하고 부족한 만큼 채워 주세요.', title_nl = 'Calcium is niet alleen melk 🧀', body_nl = 'Wil hij geen melk drinken? Calcium is onmisbaar voor de botten. Bereken met de Voedingstracker de kaas, yoghurt of broccoli van vandaag en vul tekorten aan.', title_pl = 'Wapń to nie tylko mleko 🧀', body_pl = 'Nie chce pić mleka? Wapń jest niezbędny dla kości. Oblicz w narzędziu do śledzenia karmienia dzisiejsze spożycie sera, jogurtu lub brokułów i uzupełnij braki.', title_pt = 'Cálcio não é só leite 🧀', body_pt = 'Recusa beber leite? O cálcio é indispensável para os ossos. Calcule com o Registo de Alimentação o queijo, o iogurte ou os brócolos de hoje e complete o que faltar.', title_sv = 'Kalcium är inte bara mjölk 🧀', body_sv = 'Vägrar barnet dricka mjölk? Kalcium är ett måste för skelettet. Räkna ut dagens intag av ost, yoghurt eller broccoli med Matningskoll och fyll på det som fattas.', title_vi = 'Canxi không chỉ có trong sữa 🧀', body_vi = 'Bé không chịu uống sữa? Canxi rất cần cho xương. Hãy tính lượng phô mai, sữa chua hoặc bông cải xanh hôm nay bằng Theo dõi cữ bú và bổ sung phần thiếu.', title_zh = '钙不只来自牛奶 🧀', body_zh = '不肯喝奶？骨骼离不开钙。用喂养记录工具算一算今天奶酪、酸奶或西兰花的摄入量，补上不足的部分。' WHERE id = '11eb0bc9-4158-4fbc-8d65-97be316f8b92' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juego de doblar la ropa 🧺', body_es = '¿Quiere ayudarte mientras recoges la ropa? ¡Encárgale emparejar los calcetines! Lee en el Blog los secretos para inculcar el sentido de la responsabilidad jugando.', title_fr = 'Le jeu du pliage de linge 🧺', body_fr = 'Il veut vous aider quand vous rangez le linge ? Confiez-lui les paires de chaussettes ! Lisez dans la rubrique Blogs les secrets pour lui transmettre le sens des responsabilités par le jeu.', title_hi = 'कपड़े तह करने का खेल 🧺', body_hi = 'आप कपड़े समेटती हैं तो वह भी मदद करना चाहता है? मोज़ों के जोड़े मिलाने का काम उसे दीजिए! ब्लॉग में खेल-खेल में ज़िम्मेदारी सिखाने के राज़ पढ़िए।', title_id = 'Permainan melipat baju 🧺', body_id = 'Ingin membantu saat Anda membereskan baju? Serahkan tugas memasangkan kaus kaki kepadanya! Baca di Blog rahasia menanamkan rasa tanggung jawab lewat permainan.', title_ja = '洗濯物たたみ遊び 🧺', body_ja = 'あなたが洗濯物を片付けていると、お手伝いしたがりますか？靴下のペア合わせを任せてみましょう！遊びを通して責任感を育てるコツを、ブログで読んでみましょう。', title_ko = '빨래 개기 놀이 🧺', body_ko = '엄마가 빨래를 갤 때 아이도 돕고 싶어 하나요? 양말 짝 맞추기를 맡겨 보세요! 놀이로 책임감을 길러 주는 비결을 블로그에서 읽어 보세요.', title_nl = 'Spelletje kleren vouwen 🧺', body_nl = 'Wil hij helpen als jij de was opruimt? Laat hem de sokken bij elkaar zoeken! Lees in Blogs de geheimen om spelenderwijs verantwoordelijkheid mee te geven.', title_pl = 'Zabawa w składanie ubrań 🧺', body_pl = 'Gdy składasz pranie, też chce pomagać? Powierz mu łączenie skarpetek w pary! Przeczytaj na Blogu sekrety zaszczepiania poczucia odpowiedzialności przez zabawę.', title_pt = 'O jogo de dobrar a roupa 🧺', body_pt = 'Enquanto arruma a roupa, ele também quer ajudar? Deixe-o juntar as meias aos pares! Leia nos Blogues os segredos para incutir o sentido de responsabilidade a brincar.', title_sv = 'Lek med tvätthögen 🧺', body_sv = 'Vill barnet hjälpa till när du viker tvätt? Låt barnet para ihop strumporna! Läs hemligheterna med att väcka ansvarskänsla genom lek i Bloggar.', title_vi = 'Trò chơi gấp quần áo 🧺', body_vi = 'Mẹ gấp quần áo thì bé cũng muốn phụ? Hãy giao cho bé việc ghép đôi tất! Đọc bí quyết nuôi dưỡng tinh thần trách nhiệm qua trò chơi trong mục Blog.', title_zh = '叠衣服游戏 🧺', body_zh = '你收衣服时，宝宝也想帮忙？把配袜子的任务交给宝宝吧！去博客读读通过游戏培养责任感的秘诀。' WHERE id = '51803c0a-8b62-474c-8ecd-e45188efdf2a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo a la habitación oscura 🌌', body_es = '¿Llora cuando apagas la luz? Al desarrollarse su imaginación, aumentan los miedos. Pon el sonido del vientre materno de Ruido blanco y devuélvele aquella sensación de seguridad.', title_fr = 'Peur de la chambre dans le noir 🌌', body_fr = 'Il pleure quand vous éteignez la lumière ? Son imagination grandit, et ses peurs aussi. Lancez le son du ventre maternel des Bruits blancs pour lui rendre ce sentiment de sécurité d''autrefois.', title_hi = 'अँधेरे कमरे का डर 🌌', body_hi = 'बत्ती बुझाते ही रोता है? कल्पना बढ़ने से डर भी बढ़ते हैं। व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर उसे वही पुराना सुरक्षा का एहसास दीजिए।', title_id = 'Takut kamar gelap 🌌', body_id = 'Menangis saat lampu dimatikan? Rasa takut bertambah karena imajinasinya berkembang. Putar suara rahim dari Suara Putih dan beri ia rasa aman yang akrab.', title_ja = '暗い部屋がこわい 🌌', body_ja = '電気を消すと泣きますか？想像力が育つにつれて、こわさも増えていきます。「ホワイトノイズ」の胎内の音を流して、なつかしい安心感を届けましょう。', title_ko = '어두운 방이 무서워요 🌌', body_ko = '불을 끄면 우나요? 상상력이 자라면서 두려움도 커져요. 백색소음에서 엄마 배 속 소리를 틀어 익숙한 안정감을 선물하세요.', title_nl = 'Bang voor een donkere kamer 🌌', body_nl = 'Huilt hij als het licht uitgaat? Doordat zijn fantasie groeit, worden de angsten groter. Zet het baarmoedergeluid uit Witte ruis aan en geef hem dat oude gevoel van veiligheid.', title_pl = 'Strach przed ciemnym pokojem 🌌', body_pl = 'Płacze, gdy gasisz światło? Wraz z rozwojem wyobraźni rosną lęki. Włącz w Białym szumie odgłosy z brzucha mamy i daj mu znajome poczucie bezpieczeństwa.', title_pt = 'Medo do quarto escuro 🌌', body_pt = 'Chora quando apaga a luz? Como a imaginação se está a desenvolver, os medos aumentam. Ligue no Ruído Branco o som do útero materno e dê-lhe aquela antiga sensação de segurança.', title_sv = 'Rädsla för mörka rum 🌌', body_sv = 'Gråter barnet när du släcker ljuset? Rädslorna ökar när fantasin utvecklas. Sätt på ljudet från livmodern i Vitt brus och ge barnet den gamla känslan av trygghet.', title_vi = 'Sợ phòng tối 🌌', body_vi = 'Bé khóc khi tắt đèn? Trí tưởng tượng phát triển nên nỗi sợ cũng tăng lên. Hãy bật âm thanh trong bụng mẹ trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn quen thuộc.', title_zh = '害怕黑暗的房间 🌌', body_zh = '关灯就哭？随着想象力发展，恐惧也会变多。打开白噪音里的子宫声，给宝宝熟悉的安全感。' WHERE id = 'ede1e4a9-4d71-4eca-bacd-697cb6454edc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo nace el interés por los libros? 📖', body_es = '¿En lugar de leer, quiere arrancar las páginas? Pregunta a Anacan AI formas prácticas de captar su atención con el cuento sin dañar el hábito de la lectura.', title_fr = 'Comment naît l''amour des livres ? 📖', body_fr = 'Il veut déchirer les pages au lieu de lire ? Demandez à Anacan AI des moyens pratiques pour capter son attention sur l''histoire sans abîmer son goût pour la lecture.', title_hi = 'किताबों में दिलचस्पी कैसे जगे? 📖', body_hi = 'पढ़ने के बजाय पन्ने फाड़ना चाहता है? पढ़ने की आदत बिगाड़े बिना उसका ध्यान कहानी की ओर कैसे लाएँ, इसके काम के तरीके Anacan AI से पूछिए।', title_id = 'Bagaimana menumbuhkan minat pada buku? 📖', body_id = 'Ingin merobek halaman, bukannya membaca? Tanyakan kepada Anacan AI cara praktis menarik perhatiannya ke dongeng tanpa merusak kebiasaan membacanya.', title_ja = '本への興味はどう育つ？📖', body_ja = '読む代わりにページを破りたがりますか？読書の習慣を損なわずにお話に集中させる実践的な方法を、Anacan AIに聞いてみましょう。', title_ko = '책에 대한 관심은 어떻게 생길까요? 📖', body_ko = '읽는 대신 책장을 찢고 싶어 하나요? 책 읽는 습관을 해치지 않고 동화에 집중하게 하는 실용적인 방법을 Anacan AI에게 물어보세요.', title_nl = 'Hoe ontstaat interesse in boeken? 📖', body_nl = 'Wil hij de bladzijden scheuren in plaats van lezen? Vraag Anacan AI om praktische manieren om zijn aandacht bij het verhaal te houden zonder zijn leesplezier te beschadigen.', title_pl = 'Jak rodzi się miłość do książek? 📖', body_pl = 'Zamiast czytać, chce drzeć strony? Zapytaj Anacan AI o praktyczne sposoby, jak przyciągnąć jego uwagę do bajki, nie zniechęcając go do czytania.', title_pt = 'Como nasce o gosto pelos livros? 📖', body_pt = 'Em vez de ler, quer rasgar as páginas? Pergunte ao Anacan AI formas práticas de captar a atenção dele para a história sem prejudicar o hábito da leitura.', title_sv = 'Hur väcks intresset för böcker? 📖', body_sv = 'Vill barnet riva sönder sidorna i stället för att läsa? Fråga Anacan AI om praktiska sätt att fånga barnets uppmärksamhet för sagan utan att skada läsvanan.', title_vi = 'Làm sao để bé yêu sách? 📖', body_vi = 'Bé muốn xé trang sách thay vì đọc? Hãy hỏi Anacan AI những cách thực tế để thu hút bé vào câu chuyện mà không làm mất thói quen đọc sách.', title_zh = '怎样培养对书的兴趣？📖', body_zh = '不想读书，而是想撕书页？向Anacan AI问问实用的方法，在不破坏阅读习惯的前提下把宝宝的注意力吸引到故事上。' WHERE id = '13aac5b4-c714-41fb-8e2e-16c1c92d8390' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El secreto del hierro: la vitamina C 🍋', body_es = 'Para que el cuerpo absorba bien el hierro, revisa el menú de hoy en el Seguimiento de tomas. Acompaña siempre la carne con una ensalada con mucho limón o tomate.', title_fr = 'Le secret du fer : la vitamine C 🍋', body_fr = 'Pour que le fer soit bien absorbé, regardez le menu du jour dans le Suivi des repas. Ajoutez absolument à la viande une salade bien citronnée ou à la tomate.', title_hi = 'आयरन का राज़: विटामिन C 🍋', body_hi = 'शरीर में आयरन अच्छी तरह सोखने के लिए फ़ीडिंग ट्रैकर में आज का मेन्यू देखिए। मांस वाली डिश के साथ नींबू या टमाटर वाला सलाद ज़रूर जोड़िए।', title_id = 'Rahasia zat besi: vitamin C 🍋', body_id = 'Agar zat besi terserap baik oleh tubuh, lihat menu hari ini di alat Pemantau Nutrisi. Pastikan menambahkan salad dengan banyak perasan lemon atau tomat di samping hidangan daging.', title_ja = '鉄分のひみつ：ビタミンC 🍋', body_ja = '鉄分をしっかり吸収できるよう、「栄養管理ツール」で今日のメニューを確認しましょう。お肉料理には、レモンやトマトたっぷりのサラダを必ず添えて。', title_ko = '철분의 비밀: 비타민 C 🍋', body_ko = '철분이 몸에 잘 흡수되도록 수유 기록 도구로 오늘 식단을 확인하세요. 고기 요리에는 레몬이나 토마토를 듬뿍 넣은 샐러드를 꼭 곁들이세요.', title_nl = 'Het geheim van ijzer: vitamine C 🍋', body_nl = 'Bekijk voor een goede opname van ijzer het menu van vandaag in de Voedingstracker. Zet naast een vleesgerecht zeker een salade met veel citroen of tomaat.', title_pl = 'Sekret żelaza: witamina C 🍋', body_pl = 'Aby żelazo dobrze się wchłaniało, spójrz na dzisiejsze menu w narzędziu do śledzenia karmienia. Do dania mięsnego koniecznie dodaj sałatkę z dużą ilością cytryny lub pomidorów.', title_pt = 'O segredo do ferro: vitamina C 🍋', body_pt = 'Para o corpo absorver bem o ferro, veja a ementa de hoje no Registo de Alimentação. Junte sem falta ao prato de carne uma salada com bastante limão ou tomate.', title_sv = 'Järnets hemlighet: C-vitamin 🍋', body_sv = 'Titta på dagens meny i Matningskoll för att kroppen ska ta upp järnet väl. Servera alltid en sallad med mycket citron eller tomat till köttet.', title_vi = 'Bí mật của sắt: Vitamin C 🍋', body_vi = 'Để cơ thể hấp thu sắt tốt, hãy xem thực đơn hôm nay trong Theo dõi cữ bú. Nhất định thêm salad nhiều chanh hoặc cà chua ăn kèm món thịt.', title_zh = '铁的秘密：维生素C 🍋', body_zh = '为了让身体更好地吸收铁，看看喂养记录工具里今天的菜单。肉类菜肴旁一定要加一份多放柠檬汁或番茄的沙拉。' WHERE id = '542e3a59-e25b-4803-a553-c3183744d2dc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora del café de mamá ☕', body_es = '¡Deja las tareas de casa a un lado y respira! Busca en Lugares para mamás una cafetería con rincón de juegos infantil, disfruta de tu café caliente y conoce a otras madres.', title_fr = 'L''heure du café de maman ☕', body_fr = 'Laissez les tâches ménagères de côté et respirez ! Trouvez dans les Lieux adaptés aux mamans un café avec coin jeux pour enfants, savourez votre café chaud et rencontrez d''autres mamans.', title_hi = 'माँ का कॉफ़ी टाइम ☕', body_hi = 'घर के काम एक तरफ़ रखकर साँस लीजिए! माँ के लिए अनुकूल जगहें में बच्चों के खेलने के कोने वाला कैफ़े ढूँढिए, अपनी गर्म कॉफ़ी का मज़ा लीजिए और दूसरी माँओं से मिलिए।', title_id = 'Jam kopi Bunda ☕', body_id = 'Sisihkan pekerjaan rumah dan tarik napas! Temukan kafe dengan sudut bermain anak di Tempat Ramah Ibu, nikmati kopi hangat Anda, dan berkenalan dengan ibu-ibu lain.', title_ja = 'ママのコーヒータイム ☕', body_ja = '家事はいったん横に置いて、ひと息つきましょう！「ママにやさしいスポット」でキッズスペースのあるカフェを見つけて、温かいコーヒーを味わい、ほかのママと知り合いましょう。', title_ko = '엄마의 커피 시간 ☕', body_ko = '집안일은 잠시 내려놓고 숨을 돌리세요! 엄마 친화 장소에서 키즈 놀이 공간이 있는 카페를 찾아 따뜻한 커피를 즐기고 다른 엄마들과도 만나 보세요.', title_nl = 'Koffietijd voor mama ☕', body_nl = 'Leg het huishouden opzij en haal adem! Zoek in Mamavriendelijke plekken een café met speelhoek, geniet van je warme koffie en leer andere moeders kennen.', title_pl = 'Kawowa chwila mamy ☕', body_pl = 'Odłóż obowiązki i odetchnij! Znajdź w Miejscach przyjaznych mamom kawiarnię z kącikiem zabaw dla dzieci, delektuj się gorącą kawą i poznaj inne mamy.', title_pt = 'A hora do café da mãe ☕', body_pt = 'Ponha as tarefas da casa de lado e respire! Encontre nos Locais Amigos das Mães um café com cantinho de brincar para crianças, saboreie o seu café quente e conheça outras mães.', title_sv = 'Mammas kaffestund ☕', body_sv = 'Lägg hushållssysslorna åt sidan och andas! Hitta ett kafé med lekhörna i Mammavänliga platser, lyssna på ljudet av ditt varma kaffe och lär känna andra mammor.', title_vi = 'Giờ cà phê của mẹ ☕', body_vi = 'Gác việc nhà sang một bên và hít thở! Hãy tìm quán cà phê có góc vui chơi trẻ em trong Địa điểm thân thiện với mẹ, tận hưởng ly cà phê nóng và làm quen với các mẹ khác.', title_zh = '妈妈的咖啡时间 ☕', body_zh = '把家务放一边，喘口气吧！在妈妈友好场所里找一家带儿童游乐角的咖啡馆，听听热咖啡的声音，认识其他妈妈。' WHERE id = 'bb3d49d9-8e03-48af-9a82-d11c505ca32b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sonido de la noche: el tren 🚂', body_es = '¿Después del ruido del día, el silencio repentino le inquieta? Para tapar los demás sonidos de casa, pon el sonido monótono del tren de Ruido blanco y prepárale para dormir.', title_fr = 'Le son de la nuit : le train 🚂', body_fr = 'Après le bruit de la journée, le silence soudain l''inquiète ? Pour couvrir les autres bruits de la maison, lancez le bruit monotone du train des Bruits blancs et amenez-le vers le sommeil.', title_hi = 'रात की आवाज़: ट्रेन 🚂', body_hi = 'दिन के शोर के बाद अचानक की खामोशी उसे बेचैन करती है? घर की दूसरी आवाज़ों को दबाने के लिए व्हाइट नॉइज़ में ट्रेन की एक जैसी आवाज़ लगाइए और उसे नींद के लिए तैयार कीजिए।', title_id = 'Suara malam: kereta 🚂', body_id = 'Setelah hari yang bising, hening yang tiba-tiba membuatnya gelisah? Untuk meredam suara lain di rumah, putar suara kereta yang monoton dari Suara Putih dan antar ia tidur.', title_ja = '夜の音：電車 🚂', body_ja = '一日のにぎやかさのあとの急な静けさが、お子さんを不安にさせますか？家の中のほかの音をさえぎるために、「ホワイトノイズ」の単調な電車の音を流して、眠りへ導きましょう。', title_ko = '밤의 소리: 기차 🚂', body_ko = '시끄러운 하루 뒤의 갑작스러운 정적이 아이를 불안하게 하나요? 집 안의 다른 소리를 가리도록 백색소음의 단조로운 기차 소리를 틀어 잠들 준비를 도와주세요.', title_nl = 'Geluid van de nacht: trein 🚂', body_nl = 'Maakt de plotselinge stilte na een lawaaierige dag hem onrustig? Zet het monotone treingeluid uit Witte ruis aan om andere geluiden in huis te blokkeren en hem in slaap te laten vallen.', title_pl = 'Odgłos nocy: pociąg 🚂', body_pl = 'Nagła cisza po hałaśliwym dniu go niepokoi? Aby zagłuszyć inne domowe dźwięki, włącz monotonny stukot pociągu z Białego szumu i nastrój go do snu.', title_pt = 'O som da noite: o comboio 🚂', body_pt = 'Depois do barulho do dia, o silêncio repentino deixa-o inquieto? Para abafar os outros sons da casa, ligue o som monótono do comboio do Ruído Branco e prepare-o para dormir.', title_sv = 'Nattens ljud: Tåg 🚂', body_sv = 'Oroas barnet av den plötsliga tystnaden efter dagens oväsen? Sätt på det monotona tågljudet från Vitt brus för att stänga ute andra ljud hemma och stäm för sömn.', title_vi = 'Âm thanh của đêm: Tàu hỏa 🚂', body_vi = 'Sau một ngày ồn ào, sự im lặng đột ngột khiến bé bất an? Hãy bật tiếng tàu hỏa đều đều trong Tiếng ồn trắng để át các âm thanh khác trong nhà và đưa bé vào giấc ngủ.', title_zh = '夜晚的声音：火车 🚂', body_zh = '白天热闹过后，突然的安静让宝宝不安？为了盖过家里的其他声音，打开白噪音里单调的火车声，帮宝宝进入睡眠。' WHERE id = '0d828df8-79e8-40c6-a759-0255d981435d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿De repente le aprietan los zapatos? 👟', body_es = '¿Tropieza al correr o quiere quitarse los zapatos? ¡Puede que le haya crecido el pie! Introduce ya sus medidas actuales en el Seguimiento del desarrollo y sigue su crecimiento físico.', title_fr = 'Les chaussures serrent d''un coup ? 👟', body_fr = 'Il trébuche en courant ou veut enlever ses chaussures ? Son pied a peut-être grandi ! Entrez ses mesures actuelles dans le Suivi de croissance et suivez tout de suite son développement physique.', title_hi = 'जूते अचानक तंग हो गए? 👟', body_hi = 'दौड़ते समय लड़खड़ाता है या जूते उतारना चाहता है? शायद पैर बड़े हो गए हैं! ग्रोथ ट्रैकर में मौजूदा माप दर्ज कीजिए और तुरंत शारीरिक विकास पर नज़र रखिए।', title_id = 'Sepatunya tiba-tiba sesak? 👟', body_id = 'Tersandung saat berlari atau ingin melepas sepatunya? Kakinya mungkin sudah bertambah besar! Masukkan ukuran terbarunya ke Pelacak Perkembangan dan segera pantau pertumbuhan fisiknya.', title_ja = '急に靴がきつくなった？👟', body_ja = '走るとつまずいたり、靴を脱ぎたがったりしますか？足が大きくなったのかもしれません！「発達トラッカー」に今のサイズを入力して、すぐに体の成長を記録しましょう。', title_ko = '신발이 갑자기 끼나요? 👟', body_ko = '뛰다가 넘어지거나 신발을 벗으려 하나요? 발이 자랐을 수도 있어요! 성장 기록에 현재 치수를 입력하고 신체 발달을 바로 확인하세요.', title_nl = 'Knellen de schoenen ineens? 👟', body_nl = 'Struikelt hij bij het rennen of wil hij zijn schoenen uittrekken? Zijn voetjes kunnen gegroeid zijn! Voer de huidige maten in de Groeitracker in en volg meteen zijn lichamelijke ontwikkeling.', title_pl = 'Buty nagle uciskają? 👟', body_pl = 'Potyka się podczas biegania albo chce zdjąć buty? Może urosła mu stopa! Wpisz aktualne wymiary w Śledzeniu rozwoju i od razu śledź jego rozwój fizyczny.', title_pt = 'Os sapatos ficaram apertados de repente? 👟', body_pt = 'Tropeça quando corre ou quer tirar os sapatos? O pé pode ter crescido! Introduza já as medidas atuais no Registo de Desenvolvimento e acompanhe o crescimento físico.', title_sv = 'Klämmer skorna plötsligt? 👟', body_sv = 'Snubblar barnet när hen springer eller vill ta av sig skorna? Foten kan ha växt! Ange aktuella mått i Utvecklingsspåraren och följ den fysiska utvecklingen direkt.', title_vi = 'Giày bỗng dưng chật? 👟', body_vi = 'Bé vấp khi chạy hoặc muốn cởi giày? Có thể chân bé đã lớn! Hãy nhập ngay số đo hiện tại vào Theo dõi phát triển để theo sát sự phát triển thể chất.', title_zh = '鞋子突然挤脚了？👟', body_zh = '跑的时候绊倒，或者总想脱鞋？可能是脚长大了！马上在发育追踪里输入当前的尺寸，跟进身体发育情况。' WHERE id = '8776b932-7a29-4e58-81cd-88646f84a4c7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Bolitas energéticas sin azúcar 🍪', body_es = '¡Adiós a los dulces del súper! Descubre en Recetas para bebé tentempiés sanos y deliciosos de dátiles y avena que se preparan en solo 10 minutos y dale una alegría.', title_fr = 'Boules d''énergie sans sucre 🍪', body_fr = 'Fini les sucreries du commerce ! Découvrez dans les Recettes pour bébés des en-cas sains et savoureux aux dattes et à l''avoine, prêts en 10 minutes, et faites-lui plaisir.', title_hi = 'बिना चीनी के एनर्जी बॉल्स 🍪', body_hi = 'बाज़ार की मिठाइयों को अलविदा! बच्चों की रेसिपी में सिर्फ़ 10 मिनट में बनने वाले खजूर और ओट्स के सेहतमंद, स्वादिष्ट स्नैक खोजिए और उसे खुश कीजिए।', title_id = 'Energy ball tanpa gula 🍪', body_id = 'Selamat tinggal manisan dari toko! Temukan camilan lezat dan sehat dari kurma dan oat yang siap hanya dalam 10 menit di Resep Bayi dan buat ia senang.', title_ja = '砂糖不使用のエナジーボール 🍪', body_ja = '市販のお菓子とはお別れ！「離乳食を始める赤ちゃんのレシピ」で、たった10分でつくれる、デーツとオートミールのヘルシーでおいしいおやつを見つけて、お子さんを喜ばせましょう。', title_ko = '설탕 없는 에너지 볼 🍪', body_ko = '마트 과자는 이제 그만! 아기 레시피에서 10분이면 만드는 맛있고 건강한 대추야자 귀리 간식을 찾아 아이를 기쁘게 해 주세요.', title_nl = 'Energieballetjes zonder suiker 🍪', body_nl = 'Weg met snoep uit de winkel! Ontdek in Babyrecepten gezonde, lekkere tussendoortjes met dadels en havermout, klaar in maar 10 minuten, en maak hem blij.', title_pl = 'Kulki mocy bez cukru 🍪', body_pl = 'Koniec ze sklepowymi słodyczami! Odkryj w Przepisach dla niemowląt zdrowe i pyszne przekąski z daktylami i płatkami owsianymi gotowe w zaledwie 10 minut i spraw mu radość.', title_pt = 'Bolinhas energéticas sem açúcar 🍪', body_pt = 'Adeus doces do supermercado! Descubra nas Receitas para bebés lanches saudáveis e saborosos de tâmaras e aveia, prontos em apenas 10 minutos, e faça-o feliz.', title_sv = 'Sockerfria energibollar 🍪', body_sv = 'Slut på godis från affären! Upptäck nyttiga och goda mellanmål med dadlar och havre som är klara på bara 10 minuter i Recept för bebisar och gör barnet glad.', title_vi = 'Viên năng lượng không đường 🍪', body_vi = 'Tạm biệt đồ ngọt mua sẵn! Hãy khám phá các món ăn vặt bổ dưỡng, thơm ngon từ chà là và yến mạch làm chỉ trong 10 phút trong Công thức cho bé để bé thêm vui.', title_zh = '无糖能量球 🍪', body_zh = '和超市甜食说再见！在宝宝食谱里发现只需10分钟就能做好的椰枣燕麦健康美味小零食，让宝宝开心一下。' WHERE id = 'e742c56f-494a-46b7-82c7-113a5d4f0287' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Agresividad repentina 🦖', body_es = '¿Cuando se enfada empuja a sus amigos o te levanta la mano? Pregunta ya a Anacan AI cómo reconducir con suavidad las emociones agresivas propias de esta edad.', title_fr = 'Agressivité soudaine 🦖', body_fr = 'Quand il se fâche, il pousse ses copains ou lève la main sur vous ? Demandez tout de suite à Anacan AI comment orienter en douceur les émotions agressives de cet âge.', title_hi = 'अचानक आक्रामकता 🦖', body_hi = 'गुस्से में दोस्तों को धक्का देता है या आप पर हाथ उठाता है? इस उम्र की तेज़ होती भावनाओं को नरमी से सही दिशा कैसे दें, यह तुरंत Anacan AI से पूछिए।', title_id = 'Tiba-tiba agresif 🦖', body_id = 'Mendorong temannya atau mengangkat tangan kepada Anda saat marah? Segera tanyakan kepada Anacan AI cara mengarahkan emosi agresif khas usia ini dengan lembut.', title_ja = '急に乱暴になる 🦖', body_ja = '怒るとお友だちを押したり、あなたに手を上げたりしますか？この年齢の激しくなる気持ちをやさしく導く方法を、すぐにAnacan AIに聞いてみましょう。', title_ko = '갑작스러운 공격성 🦖', body_ko = '화가 나면 친구를 밀거나 엄마에게 손을 드나요? 이 나이의 거칠어지는 감정을 부드럽게 이끄는 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Plotselinge agressie 🦖', body_nl = 'Duwt hij vriendjes of haalt hij naar jou uit als hij boos is? Vraag Anacan AI meteen hoe je de heftige emoties van deze leeftijd zacht bijstuurt.', title_pl = 'Nagła agresja 🦖', body_pl = 'Gdy się złości, popycha kolegów albo podnosi na ciebie rękę? Od razu zapytaj Anacan AI, jak łagodnie kierować agresywnymi emocjami typowymi dla tego wieku.', title_pt = 'Agressividade repentina 🦖', body_pt = 'Quando se zanga, empurra os amigos ou levanta-lhe a mão? Pergunte já ao Anacan AI como orientar com suavidade estas emoções agressivas típicas da idade.', title_sv = 'Plötslig aggressivitet 🦖', body_sv = 'Knuffar barnet sina kompisar eller lyfter handen mot dig när hen blir arg? Fråga Anacan AI direkt hur du varsamt kan styra den här ålderns allt starkare känslor.', title_vi = 'Hung hăng bất chợt 🦖', body_vi = 'Bé xô bạn hoặc vung tay với mẹ khi tức giận? Hãy hỏi ngay Anacan AI cách nhẹ nhàng định hướng những cảm xúc ngày càng mạnh mẽ của lứa tuổi này.', title_zh = '突然的攻击行为 🦖', body_zh = '一生气就推小朋友或对你动手？马上问问Anacan AI，如何温和地引导这个年龄越来越激烈的情绪。' WHERE id = '81b85e80-d265-4f32-8c47-4b14aa23d8e1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No te olvides de ti ⚡', body_es = '¿A mediodía te quedas sin fuerzas? ¡No corras a por dulces! Recarga tu batería con un batido de crema de cacahuete con proteínas de Recetas saludables para mujeres que da fuerza al instante.', title_fr = 'Ne vous oubliez pas ⚡', body_fr = 'Coup de fatigue l''après-midi ? Ne vous jetez pas sur le sucre ! Rechargez vos batteries avec un smoothie protéiné au beurre de cacahuète des Recettes saines pour femmes, énergisant en un instant.', title_hi = 'खुद को मत भूलिए ⚡', body_hi = 'दोपहर में थककर चूर हो जाती हैं? मिठाई की ओर मत भागिए! महिलाओं के लिए सेहतमंद रेसिपी से तुरंत ताकत देने वाली, प्रोटीन से भरपूर पीनट बटर स्मूदी बनाइए और अपनी बैटरी चार्ज कीजिए।', title_id = 'Jangan lupakan diri Anda ⚡', body_id = 'Kehabisan tenaga di siang hari? Jangan lari ke manisan! Isi ulang baterai Anda dengan smoothie selai kacang kaya protein yang langsung memberi tenaga dari Resep Sehat untuk wanita.', title_ja = '自分のことも忘れないで ⚡', body_ja = 'お昼にエネルギー切れ？甘いものに頼らないで！「女性のためのヘルシーレシピ」から、すぐに元気が出るたんぱく質たっぷりのピーナッツバタースムージーをつくって、バッテリーを充電しましょう。', title_ko = '엄마 자신을 잊지 마세요 ⚡', body_ko = '오후만 되면 기운이 빠지나요? 단 음식으로 달려가지 마세요! 여성을 위한 건강한 레시피에서 바로 힘이 나는 단백질 땅콩버터 스무디로 배터리를 충전하세요.', title_nl = 'Vergeet jezelf niet ⚡', body_nl = 'Ben je ''s middags uitgeput? Grijp niet naar snoep! Laad je batterij op met een eiwitrijke smoothie met pindakaas uit Gezonde recepten voor vrouwen die je meteen kracht geeft.', title_pl = 'Nie zapominaj o sobie ⚡', body_pl = 'W południe opadasz z sił? Nie sięgaj po słodycze! Przygotuj ze Zdrowych przepisów dla kobiet białkowe smoothie z masłem orzechowym, które od razu doda ci sił, i naładuj baterie.', title_pt = 'Não se esqueça de si ⚡', body_pt = 'À tarde fica sem forças? Não corra para os doces! Prepare nas Receitas Saudáveis para Mulheres um batido de manteiga de amendoim rico em proteína, que dá força na hora, e recarregue as baterias.', title_sv = 'Glöm inte bort dig själv ⚡', body_sv = 'Helt slut mitt på dagen? Rusa inte efter godis! Gör en proteinrik smoothie med jordnötssmör som ger kraft direkt från Hälsosamma recept för kvinnor och ladda batterierna.', title_vi = 'Đừng quên bản thân ⚡', body_vi = 'Buổi trưa mẹ kiệt sức? Đừng tìm đến đồ ngọt! Hãy làm ly sinh tố bơ đậu phộng giàu đạm, tiếp sức tức thì từ Công thức lành mạnh cho phụ nữ để sạc đầy pin.', title_zh = '别忘了你自己 ⚡', body_zh = '一到中午就没力气？别急着吃甜食！从女性健康食谱里做一杯马上补充能量、富含蛋白质的花生酱奶昔，给自己充满电。' WHERE id = 'bf03a99b-eae8-47d0-a5c6-eb2e17e62b7d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Por la noche tardó mucho en dormirse? Pon el temporizador de sueño y sigue el gráfico. Analiza si no ha gastado toda su energía o si está demasiado cansado.', body_fr = 'Il a mis très longtemps à s''endormir ce soir ? Lancez le minuteur de sommeil et suivez le graphique. Analysez s''il ne s''est pas assez dépensé ou s''il est trop fatigué.', body_hi = 'शाम को सोने में बहुत समय लगा? स्लीप टाइमर चालू कीजिए और चार्ट पर नज़र रखिए। समझिए कि उसकी ऊर्जा पूरी नहीं निकली या वह ज़रूरत से ज़्यादा थक गया है।', body_id = 'Butuh waktu sangat lama untuk tertidur malam ini? Nyalakan Timer Tidur dan pantau grafiknya. Analisis apakah energinya belum tersalurkan atau ia justru terlalu lelah.', body_ja = '夜、寝つくまでにとても時間がかかりましたか？睡眠タイマーをオンにして、グラフを見守りましょう。エネルギーを発散しきれていないのか、疲れすぎているのか分析しましょう。', body_ko = '저녁에 잠드는 데 너무 오래 걸렸나요? 수면 타이머를 켜고 그래프를 살펴보세요. 에너지를 다 쓰지 못한 건지, 너무 피곤한 건지 분석해 보세요.', body_nl = 'Duurde het inslapen vanavond erg lang? Zet de Slaaptimer aan en volg de grafiek. Analyseer of hij zijn energie nog niet kwijt is of juist oververmoeid is.', body_pl = 'Wieczorne zasypianie trwało bardzo długo? Włącz timer snu i śledź wykres. Sprawdź, czy nie rozładował całej energii, czy raczej jest przemęczony.', body_pt = 'À noite demorou muito a adormecer? Ligue o temporizador de sono e acompanhe o gráfico. Analise se ainda não gastou toda a energia ou se está cansado demais.', body_sv = 'Tog det väldigt lång tid att somna i kväll? Starta sömntimern och följ grafen. Analysera om barnet inte fått ut all energi eller är övertrött.', body_vi = 'Tối qua bé mất quá lâu để ngủ? Hãy bật Bộ hẹn giờ ngủ và theo dõi biểu đồ. Phân tích xem bé chưa xả hết năng lượng hay đã quá mệt.', body_zh = '晚上入睡花了太长时间？打开睡眠计时器，看看图表。分析一下是精力没释放完，还是太累了。' WHERE id = 'fdde906c-a398-4012-a073-4015f9852301' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y silencio 🍵', body_es = 'El temporizador se ha parado y tu peque duerme. ¡Ahora ni toques las tareas de casa! Prepárate una infusión de melisa de Recetas saludables para mujeres y deja que el vapor caliente se lleve el cansancio del día.', title_fr = 'Thé chaud et silence 🍵', body_fr = 'Le minuteur est arrêté, il dort. Maintenant, ne touchez pas aux tâches ménagères ! Préparez une tisane de mélisse des Recettes saines pour femmes et laissez la fatigue du jour s''envoler avec la vapeur.', title_hi = 'गर्म चाय और खामोशी 🍵', body_hi = 'टाइमर रुक गया, बच्चा सो गया। अब घर के कामों को हाथ मत लगाइए! महिलाओं के लिए सेहतमंद रेसिपी से लेमन बाम की चाय बनाइए और दिन की थकान को गर्म भाप के साथ उड़ा दीजिए।', title_id = 'Teh hangat dan keheningan 🍵', body_id = 'Timer berhenti, si kecil sudah tidur. Sekarang jangan sentuh pekerjaan rumah! Seduh teh lemon balm dari Resep Sehat untuk wanita dan biarkan lelah hari ini menguap bersama uap hangatnya.', title_ja = '温かいお茶と静けさ 🍵', body_ja = 'タイマーは止まり、お子さんは眠りました。今は家事に手をつけないで！「女性のためのヘルシーレシピ」からレモンバームティーをいれて、一日の疲れを温かい湯気に溶かしましょう。', title_ko = '따뜻한 차와 고요함 🍵', body_ko = '타이머가 멈추고 아이가 잠들었어요. 이제 집안일은 손대지 마세요! 여성을 위한 건강한 레시피에서 레몬밤 차를 우려 따뜻한 김에 하루의 피로를 날려 보내세요.', title_nl = 'Warme thee en stilte 🍵', body_nl = 'De timer is gestopt, je kindje slaapt. Raak het huishouden nu niet aan! Zet citroenmelissethee uit Gezonde recepten voor vrouwen en laat de vermoeidheid van de dag wegdampen.', title_pl = 'Ciepła herbata i cisza 🍵', body_pl = 'Timer zatrzymany, maluch śpi. Teraz nie ruszaj obowiązków! Zaparz melisę ze Zdrowych przepisów dla kobiet i pozwól, by ciepła para zabrała zmęczenie całego dnia.', title_pt = 'Chá quente e silêncio 🍵', body_pt = 'O temporizador parou, ele adormeceu. Agora não toque nas tarefas da casa! Prepare um chá de erva-cidreira das Receitas Saudáveis para Mulheres e deixe o cansaço do dia ir-se com o vapor quente.', title_sv = 'Varmt te och tystnad 🍵', body_sv = 'Timern har stannat, barnet sover. Rör inte hushållssysslorna nu! Brygg citronmelissate från Hälsosamma recept för kvinnor och låt dagens trötthet försvinna med den varma ångan.', title_vi = 'Trà nóng và sự yên tĩnh 🍵', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Giờ đừng động vào việc nhà nhé! Hãy pha trà tía tô đất từ Công thức lành mạnh cho phụ nữ và để hơi ấm cuốn trôi mệt mỏi cả ngày.', title_zh = '热茶与安静 🍵', body_zh = '计时器停了，孩子睡着了。现在别碰家务！从女性健康食谱里泡一杯香蜂草茶，让一天的疲惫随热气散去。' WHERE id = '63af320f-f496-491d-b573-f5b6663a91e4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Unos músculos que no paran de correr y saltar necesitan proteínas. Mide con el Seguimiento de tomas el equilibrio de su alimentación diaria y enriquece su menú.', body_fr = 'Les protéines sont indispensables à des muscles qui courent et sautent sans arrêt. Mesurez son équilibre alimentaire du jour avec le Suivi des repas et enrichissez son menu.', body_hi = 'बिना रुके दौड़ने-कूदने वाली मांसपेशियों के लिए प्रोटीन ज़रूरी है। फ़ीडिंग ट्रैकर से उसके रोज़ के खाने का संतुलन मापिए और मेन्यू को और पौष्टिक बनाइए।', body_id = 'Otot yang terus berlari dan melompat butuh protein. Ukur keseimbangan nutrisi hariannya dengan alat Pemantau Nutrisi dan perkaya menunya.', body_ja = '休みなく走ってジャンプする筋肉には、たんぱく質が欠かせません。「栄養管理ツール」で1日の栄養バランスを確認して、メニューを豊かにしましょう。', body_ko = '쉬지 않고 뛰고 점프하는 근육에는 단백질이 꼭 필요해요. 수유 기록 도구로 하루 영양 균형을 확인하고 식단을 더 풍성하게 만들어 주세요.', body_nl = 'Eiwit is onmisbaar voor spieren die de hele dag rennen en springen. Meet met de Voedingstracker zijn dagelijkse voedingsbalans en maak zijn menu rijker.', body_pl = 'Mięśnie, które bez przerwy biegają i skaczą, potrzebują białka. Sprawdź w narzędziu do śledzenia karmienia jego dzienny bilans żywieniowy i wzbogać menu.', body_pt = 'Músculos que correm e saltam sem parar precisam de proteína. Meça com o Registo de Alimentação o equilíbrio alimentar diário e enriqueça a ementa.', body_sv = 'Muskler som springer och hoppar utan uppehåll behöver protein. Mät barnets dagliga näringsbalans med Matningskoll och gör menyn mer varierad.', body_vi = 'Cơ bắp chạy nhảy không ngừng rất cần đạm. Hãy đo cân bằng dinh dưỡng hằng ngày của bé bằng Theo dõi cữ bú và làm thực đơn thêm phong phú.', body_zh = '不停奔跑、蹦跳的肌肉离不开蛋白质。用喂养记录工具衡量宝宝每天的饮食平衡，让菜单更丰富。' WHERE id = '86e064b7-8da1-4aa9-b551-ca85b1a25e7c' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Los «¿por qué?» sin fin 🤔', body_es = '¡La etapa del «¿Qué es esto? ¿Por qué es así?» ha empezado oficialmente! Aprende en el Blog a responder con paciencia y de forma estimulante a su curiosidad sin fin.', title_fr = 'Les « Pourquoi ? » sans fin 🤔', body_fr = 'La période du « C''est quoi ? Pourquoi c''est comme ça ? » a officiellement commencé ! Découvrez dans la rubrique Blogs comment répondre avec patience et de façon stimulante à sa curiosité sans fin.', title_hi = 'कभी न खत्म होने वाले ''क्यों?'' 🤔', body_hi = '''यह क्या है? ऐसा क्यों है?'' वाला दौर आधिकारिक तौर पर शुरू हो गया है! उसकी इस अनंत जिज्ञासा का धैर्य से और विकास में मदद करने वाला जवाब कैसे दें, यह ब्लॉग में जानिए।', title_id = 'Pertanyaan Kenapa? tanpa akhir 🤔', body_id = 'Masa Ini apa? Kenapa begitu? resmi dimulai! Pelajari di Blog cara menjawab rasa ingin tahunya yang tak ada habisnya dengan sabar dan mendidik.', title_ja = '終わらない「なんで？」の質問 🤔', body_ja = '「これなあに？なんでこうなの？」の時期が正式に始まりました！この終わりのない探究心に、気長に、そして成長を促すように答える方法を、ブログで学びましょう。', title_ko = '끝없는 ''왜?'' 질문 🤔', body_ko = '''이게 뭐야? 왜 그래?'' 시기가 공식적으로 시작됐어요! 아이의 끝없는 탐구심에 인내심 있게, 발달을 돕는 방식으로 대답하는 법을 블로그에서 배워 보세요.', title_nl = 'De eindeloze waarom?-vragen 🤔', body_nl = 'De fase van wat is dat? waarom is dat zo? is officieel begonnen! Lees in Blogs hoe je geduldig en leerzaam antwoord geeft op zijn eindeloze nieuwsgierigheid.', title_pl = 'Niekończące się pytania „Dlaczego?” 🤔', body_pl = 'Etap „Co to jest? Dlaczego tak jest?” oficjalnie się zaczął! Dowiedz się z Bloga, jak cierpliwie i rozwijająco odpowiadać na jego bezgraniczną ciekawość świata.', title_pt = 'As perguntas sem fim do "Porquê?" 🤔', body_pt = 'A fase do "O que é isto? Porque é assim?" começou oficialmente! Aprenda nos Blogues a responder com paciência e de forma estimulante a esta curiosidade sem fim.', title_sv = 'De ändlösa ”Varför?”-frågorna 🤔', body_sv = '”Vad är det? Varför är det så?”-perioden har officiellt börjat! Lär dig i Bloggar hur du med tålamod och på ett utvecklande sätt svarar på barnets ändlösa upptäckarlust.', title_vi = 'Những câu hỏi "Tại sao?" bất tận 🤔', body_vi = 'Giai đoạn "Cái gì đây? Tại sao?" đã chính thức bắt đầu! Hãy học trong mục Blog cách trả lời sự tò mò bất tận của bé một cách kiên nhẫn và giúp bé phát triển.', title_zh = '没完没了的“为什么？”🤔', body_zh = '“这是什么？为什么会这样？”阶段正式开始了！去博客学习如何耐心又有启发性地回应孩子无穷无尽的探索欲。' WHERE id = '947ec858-749d-4a0f-bf72-73a1503e2c5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Grabaciones de voz antiguas 🎤', body_es = 'Cuando tu peque se duerma, abre el Álbum del bebé y escucha aquellos sonidos tan dulces que hacía hace meses. ¡Mira lo rápido que ha crecido y siéntete orgullosa!', title_fr = 'Anciens enregistrements 🎤', body_fr = 'Une fois qu''il dort, ouvrez l''Album de bébé et réécoutez les petits sons adorables qu''il faisait il y a quelques mois. Voyez comme il a grandi vite et soyez fière !', title_hi = 'पुरानी आवाज़ की रिकॉर्डिंग 🎤', body_hi = 'बच्चे के सोने के बाद बेबी एल्बम खोलिए और महीनों पहले की उसकी वे प्यारी आवाज़ें सुनिए। देखिए वह कितनी तेज़ी से बड़ा हुआ है, और गर्व कीजिए!', title_id = 'Rekaman suara lama 🎤', body_id = 'Setelah si kecil tidur, buka Album Bayi dan dengarkan suara-suara manis yang ia keluarkan berbulan-bulan lalu. Lihat betapa cepatnya ia tumbuh, dan banggalah!', title_ja = 'なつかしい声の記録 🎤', body_ja = 'お子さんが眠ったら「ベビーアルバム」を開いて、何か月も前のかわいい声を聞いてみましょう。こんなに早く大きくなったんだと、誇らしい気持ちになりますよ！', title_ko = '예전 목소리 기록 🎤', body_ko = '아이가 잠든 뒤 아기 앨범을 열고 몇 달 전에 냈던 그 귀여운 소리들을 들어 보세요. 얼마나 빨리 자랐는지 보며 뿌듯해질 거예요!', title_nl = 'Oude geluidsopnames 🎤', body_nl = 'Open als je kindje slaapt het Babyalbum en luister naar de lieve geluidjes van maanden geleden. Wees trots als je ziet hoe snel hij groeit!', title_pl = 'Stare nagrania głosu 🎤', body_pl = 'Gdy maluch zaśnie, otwórz Album dziecka i posłuchaj tych słodkich dźwięków sprzed kilku miesięcy. Zobacz, jak szybko rośnie, i bądź dumna!', title_pt = 'Gravações de voz antigas 🎤', body_pt = 'Depois de ele adormecer, abra o Álbum do Bebé e ouça aqueles sons tão doces que fazia há meses. Veja como cresceu depressa e encha-se de orgulho!', title_sv = 'Gamla ljudinspelningar 🎤', body_sv = 'När barnet somnat, öppna Babyalbumet och lyssna på de söta ljuden barnet gjorde för några månader sedan. Se hur snabbt barnet växt och känn dig stolt!', title_vi = 'Những bản ghi âm cũ 🎤', body_vi = 'Khi bé đã ngủ, hãy mở Album của bé và nghe lại những âm thanh đáng yêu bé phát ra từ nhiều tháng trước. Thấy bé lớn nhanh thế nào mà tự hào!', title_zh = '以前的录音 🎤', body_zh = '孩子睡着后，打开宝宝相册，听听几个月前宝宝发出的那些可爱声音。看看宝宝长得多快，为宝宝骄傲吧！' WHERE id = '5d69eb5c-8ed9-4c1d-9b48-d1c46bb4e1fb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¡Es mío!» 🧸', body_es = '¿En el parque no le deja sus juguetes a nadie? Pregunta a Anacan AI cómo enseñar a respetar turnos a un niño que se acerca a los 2,5 años.', title_fr = 'La période « C''est à moi ! » 🧸', body_fr = 'Au parc, il ne prête ses jouets à personne ? Demandez à Anacan AI comment apprendre à jouer chacun son tour à un enfant qui approche des 2 ans et demi.', title_hi = '''मेरा है!'' वाला दौर 🧸', body_hi = 'पार्क में किसी को खिलौना नहीं देता? 2.5 साल के करीब पहुँच रहे बच्चों को बारी-बारी से खेलना कैसे सिखाएँ, यह Anacan AI से पूछकर जानिए।', title_id = 'Masa Punyaku! 🧸', body_id = 'Di taman ia tidak mau meminjamkan mainan ke siapa pun? Tanyakan kepada Anacan AI cara menanamkan konsep bergiliran pada anak yang menuju usia 2,5 tahun.', title_ja = '「ぼくの！」「わたしの！」の時期 🧸', body_ja = '公園で誰にもおもちゃを貸さない？2歳半に向かう子に「順番」を教える方法を、Anacan AIに聞いて学びましょう。', title_ko = '''내 거야!'' 시기 🧸', body_ko = '공원에서 아무에게도 장난감을 안 주나요? 두 돌 반을 앞둔 아이에게 차례 지키기를 가르치는 방법을 Anacan AI에게 물어보세요.', title_nl = 'De van mij!-fase 🧸', body_nl = 'Geeft hij in het park niemand zijn speelgoed? Vraag Anacan AI hoe je kinderen die bijna 2,5 jaar zijn leert om om de beurt te spelen.', title_pl = 'Etap „Moje!” 🧸', body_pl = 'W parku nikomu nie daje swoich zabawek? Zapytaj Anacan AI, jak nauczyć dziecko zbliżające się do 2,5 roku zabawy po kolei.', title_pt = 'A fase do "É meu!" 🧸', body_pt = 'No parque não empresta os brinquedos a ninguém? Pergunte ao Anacan AI como ensinar a ideia de brincar à vez a crianças a caminho dos 2,5 anos.', title_sv = '”Min!”-perioden 🧸', body_sv = 'Ger barnet inte sina leksaker till någon i parken? Fråga Anacan AI hur du lär barn som närmar sig 2,5 år att turas om.', title_vi = 'Giai đoạn "Của con!" 🧸', body_vi = 'Ở công viên bé không đưa đồ chơi cho ai? Hãy hỏi Anacan AI cách dạy trẻ gần 2,5 tuổi biết chơi lần lượt.', title_zh = '“是我的！”阶段 🧸', body_zh = '在公园谁都不给玩具？问问Anacan AI，如何教快2.5岁的宝宝学会轮流玩。' WHERE id = 'c3ea09ec-b61b-40ca-8245-a6b47232b78f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Espectáculo delante del espejo 🤪', body_es = '¿Hace muecas mirándose y se ríe a carcajadas? Añade ya en vídeo al Álbum del bebé este momento tan gracioso de autodescubrimiento y suelta el estrés del día.', title_fr = 'Show devant le miroir 🤪', body_fr = 'Il fait des grimaces et éclate de rire en se regardant ? Ajoutez tout de suite ce moment rigolo de découverte de soi en vidéo à l''Album de bébé et évacuez le stress du jour.', title_hi = 'आईने के सामने शो 🤪', body_hi = 'मुँह बनाकर खुद को देखता है और ठहाके लगाता है? खुद को खोजने के इस मज़ेदार पल को तुरंत वीडियो के रूप में बेबी एल्बम में जोड़िए और दिन का तनाव उतारिए।', title_id = 'Pertunjukan di depan cermin 🤪', body_id = 'Memasang wajah lucu sambil menatap dirinya dan tertawa terbahak-bahak? Segera simpan momen lucu saat ia mengenali dirinya ini sebagai video di Album Bayi dan lepaskan stres hari ini.', title_ja = '鏡の前でショー 🤪', body_ja = '変な顔をして鏡の自分を見て大笑いしていますか？このおもしろい自分発見の瞬間を、すぐに動画で「ベビーアルバム」に追加して、一日のストレスを吹き飛ばしましょう。', title_ko = '거울 앞 공연 🤪', body_ko = '얼굴을 찡그리며 거울 속 자기를 보고 깔깔 웃나요? 이 재미있는 자기 발견의 순간을 바로 영상으로 아기 앨범에 올리고 하루의 스트레스를 날려 보세요.', title_nl = 'Show voor de spiegel 🤪', body_nl = 'Trekt hij gekke bekken naar zichzelf en schatert hij het uit? Zet dit grappige moment van zelfontdekking meteen als video in het Babyalbum en laat de stress van de dag los.', title_pl = 'Show przed lustrem 🤪', body_pl = 'Robi miny i śmieje się do siebie w lustrze? Od razu dodaj tę zabawną chwilę odkrywania siebie jako film do Albumu dziecka i zrzuć stres dnia.', title_pt = 'Espetáculo em frente ao espelho 🤪', body_pt = 'Faz caretas e ri-se às gargalhadas a olhar para si próprio? Adicione já em vídeo ao Álbum do Bebé este momento divertido de autodescoberta e liberte o stress do dia.', title_sv = 'Show framför spegeln 🤪', body_sv = 'Gör barnet grimaser och skrattar högt åt sig själv? Lägg direkt till detta roliga ögonblick av självupptäckt som video i Babyalbumet och släpp dagens stress.', title_vi = 'Màn trình diễn trước gương 🤪', body_vi = 'Bé nhăn mặt nhìn mình rồi cười khanh khách? Hãy quay ngay video khoảnh khắc tự khám phá hài hước này, thêm vào Album của bé và xua tan căng thẳng cả ngày.', title_zh = '镜子前的表演 🤪', body_zh = '挤眉弄眼，看着自己哈哈大笑？马上把这个搞笑的自我发现时刻拍成视频加进宝宝相册，卸下一天的压力。' WHERE id = 'd4efd00f-6d87-4868-a912-9b76b79425d0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas una pausa ☕', body_es = '¡Sal de casa y respira un poco! Busca en Lugares para mamás una cafetería cercana con rincón infantil, disfruta de tu café caliente y conoce a otras madres.', title_fr = 'Vous aussi, vous avez besoin d''une pause ☕', body_fr = 'Sortez prendre un peu l''air ! Trouvez dans les Lieux adaptés aux mamans un café avec coin enfants près de chez vous, savourez votre café chaud et rencontrez d''autres mamans.', title_hi = 'आपको भी ब्रेक चाहिए ☕', body_hi = 'घर से निकलकर थोड़ी साँस लीजिए! माँ के लिए अनुकूल जगहें में पास का बच्चों के कोने वाला कैफ़े ढूँढिए, अपनी गर्म कॉफ़ी का मज़ा लीजिए और दूसरी माँओं से मिलिए।', title_id = 'Anda juga butuh rehat ☕', body_id = 'Keluar rumah dan hirup udara sebentar! Temukan kafe terdekat dengan sudut bermain anak di Tempat Ramah Ibu, nikmati kopi hangat Anda, dan berkenalan dengan ibu-ibu lain.', title_ja = 'あなたにも休憩が必要です ☕', body_ja = '家を出て、ひと息つきましょう！「ママにやさしいスポット」で近くのキッズコーナーのあるカフェを見つけて、温かいコーヒーを味わい、ほかのママと知り合いましょう。', title_ko = '엄마에게도 휴식이 필요해요 ☕', body_ko = '집을 나서서 잠시 숨을 돌리세요! 엄마 친화 장소에서 가까운 키즈 코너 카페를 찾아 따뜻한 커피를 즐기고 다른 엄마들과도 만나 보세요.', title_nl = 'Jij hebt ook een pauze nodig ☕', body_nl = 'Ga de deur uit en haal even adem! Zoek in Mamavriendelijke plekken een café met kinderhoek in de buurt, geniet van je warme koffie en leer andere moeders kennen.', title_pl = 'Ty też potrzebujesz przerwy ☕', body_pl = 'Wyjdź z domu i odetchnij! Znajdź w Miejscach przyjaznych mamom pobliską kawiarnię z kącikiem dla dzieci, delektuj się gorącą kawą i poznaj inne mamy.', title_pt = 'Também precisa de uma pausa ☕', body_pt = 'Saia de casa e respire um pouco! Encontre nos Locais Amigos das Mães um café perto com cantinho para crianças, saboreie o seu café quente e conheça outras mães.', title_sv = 'Du behöver också en paus ☕', body_sv = 'Gå ut och andas lite! Hitta ett kafé med barnhörna i närheten i Mammavänliga platser, lyssna på ljudet av ditt varma kaffe och lär känna andra mammor.', title_vi = 'Mẹ cũng cần nghỉ ngơi ☕', body_vi = 'Hãy ra ngoài hít thở một chút! Tìm quán cà phê có góc trẻ em gần nhà trong Địa điểm thân thiện với mẹ, tận hưởng ly cà phê nóng và làm quen với các mẹ khác.', title_zh = '你也需要歇一歇 ☕', body_zh = '出门透透气吧！在妈妈友好场所里找一家附近带儿童角的咖啡馆，听听热咖啡的声音，认识其他妈妈。' WHERE id = '3f2f1108-7831-4796-88a8-5de7f4f81912' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Siéntete orgullosa de ti 🌟', body_es = 'Cada nueva habilidad que aprende y cada paso seguro que da son fruto de tu entrega. ¡Abre el Diario de ánimo y escribe hoy una nota para aplaudirte de pie!', title_fr = 'Soyez fière de vous 🌟', body_fr = 'Chaque nouvelle compétence, chaque pas assuré, c''est grâce à votre dévouement. Ouvrez le Journal d''humeur et écrivez aujourd''hui une note qui mérite une ovation debout !', title_hi = 'खुद पर गर्व कीजिए 🌟', body_hi = 'हर दिन सीखी नई चीज़, हर भरोसे भरा कदम आपका त्याग है। मूड डायरी खोलिए और आज खुद को शाबाशी देने वाली एक बात लिखिए!', title_id = 'Banggalah pada diri sendiri 🌟', body_id = 'Setiap keterampilan baru dan setiap langkah percaya dirinya adalah buah pengorbanan Anda. Buka Buku Harian Suasana Hati dan tulis catatan yang membuat Anda bertepuk tangan untuk diri sendiri hari ini!', title_ja = '自分を誇りに思って 🌟', body_ja = '毎日新しくできるようになること、自信に満ちた一歩一歩は、あなたの献身のおかげです。「気分日記」を開いて、今日の自分にスタンディングオベーションを送るメモを書きましょう！', title_ko = '스스로를 자랑스러워하세요 🌟', body_ko = '매일 배우는 새로운 능력, 자신 있는 한 걸음 한 걸음이 모두 엄마의 헌신이에요. 기분 일기를 열고 오늘의 나에게 기립 박수를 보낼 기록을 남겨 보세요!', title_nl = 'Wees trots op jezelf 🌟', body_nl = 'Elke nieuwe vaardigheid en elk zelfverzekerd stapje is dankzij jouw toewijding. Open je Stemmingsdagboek en schrijf vandaag een notitie waarmee je jezelf een staande ovatie geeft!', title_pl = 'Bądź z siebie dumna 🌟', body_pl = 'Każda nowa umiejętność, każdy pewny krok to owoc twojego poświęcenia. Otwórz Dziennik nastroju i napisz dziś notatkę, za którą nagrodzisz się owacją na stojąco!', title_pt = 'Orgulhe-se de si 🌟', body_pt = 'Cada nova competência que aprende e cada passo confiante são fruto da sua dedicação. Abra o Diário de Humor e escreva hoje uma nota que a faça aplaudir-se de pé!', title_sv = 'Var stolt över dig själv 🌟', body_sv = 'Varje ny färdighet barnet lär sig och varje säkert steg är tack vare dina uppoffringar. Öppna Humördagboken och skriv en anteckning i dag som ger dig själv stående ovationer!', title_vi = 'Hãy tự hào về bản thân 🌟', body_vi = 'Mỗi kỹ năng mới, mỗi bước đi tự tin của bé đều là sự hy sinh của mẹ. Hãy mở Nhật ký tâm trạng và viết một dòng để tự vỗ tay cho mình hôm nay!', title_zh = '为自己骄傲吧 🌟', body_zh = '宝宝每天学会的新本领、迈出的每一个自信的脚步，都是你的付出。打开心情日记，写下一句为自己热烈鼓掌的话吧！' WHERE id = '875b72c1-d353-4eb2-8649-bca828613387' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Tira la comida? 🥣', body_es = '¿Se cansa de estar sentado en la mesa y tira la cuchara? Pon el temporizador de tomas, analiza con el gráfico cuánto dura la comida y evita por completo obligarle a comer.', title_fr = 'Il jette la nourriture ? 🥣', body_fr = 'Lassé d''être à table, il jette la cuillère ? Lancez le minuteur des repas, analysez la durée du repas sur le graphique et évitez complètement de le forcer à manger.', title_hi = 'खाना घुमाकर फेंकता है? 🥣', body_hi = 'मेज़ पर बैठे-बैठे ऊबकर चम्मच फेंक देता है? फ़ीडिंग टाइमर चालू कीजिए, चार्ट से समय का विश्लेषण कीजिए और ज़बरदस्ती खिलाने से पूरी तरह बचिए।', title_id = 'Mengayunkan dan melempar makanan? 🥣', body_id = 'Bosan duduk di meja makan dan melempar sendok? Nyalakan Timer Makan, analisis durasinya lewat grafik, dan hindari sepenuhnya memaksanya makan.', title_ja = '食べ物を振り回して投げる？🥣', body_ja = '食卓に座るのに飽きて、スプーンを投げますか？食事タイマーをオンにして、食事の時間をグラフで分析し、無理に食べさせるのは完全に避けましょう。', title_ko = '음식을 휘둘러 던지나요? 🥣', body_ko = '식탁에 앉아 있기 지루해서 숟가락을 던지나요? 수유 타이머를 켜서 식사 시간을 그래프로 분석하고 억지로 먹이는 건 완전히 피하세요.', title_nl = 'Smijt hij met eten? 🥣', body_nl = 'Heeft hij geen zin meer om aan tafel te zitten en gooit hij de lepel? Zet de Voedingstimer aan, analyseer de duur met de grafiek en dwing hem nooit te eten.', title_pl = 'Rzuca jedzeniem? 🥣', body_pl = 'Nudzi się przy stole i rzuca łyżką? Włącz timer karmienia, przeanalizuj czas posiłku na wykresie i całkowicie unikaj karmienia na siłę.', title_pt = 'Atira a comida? 🥣', body_pt = 'Cansou-se de estar sentado à mesa e atira a colher? Ligue o temporizador de alimentação, analise a duração no gráfico e evite por completo obrigá-lo a comer.', title_sv = 'Slänger maten? 🥣', body_sv = 'Tröttnar barnet på att sitta vid bordet och kastar skeden? Starta matningstimern, analysera hur lång tid måltiden tar med grafen och undvik helt att tvångsmata.', title_vi = 'Bé ném thức ăn đi? 🥣', body_vi = 'Bé chán ngồi bàn và ném thìa? Hãy bật Hẹn giờ cho bú, phân tích thời gian qua biểu đồ và tuyệt đối tránh ép bé ăn.', title_zh = '把饭甩出去？🥣', body_zh = '坐腻了，把勺子扔掉？打开喂养计时器，用图表分析用餐时长，完全避免强迫喂饭。' WHERE id = '9ccd2cce-af67-4d8c-b8c4-0ddfa25c77b1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Come de un solo color? 🟡', body_es = '¿Solo quiere comida amarilla (patata, pasta, plátano)? Analiza su menú con el Seguimiento de tomas y descubre en Recetas para bebé alternativas coloridas con verduras escondidas.', title_fr = 'Des repas d''une seule couleur ? 🟡', body_fr = 'Il ne veut que des aliments jaunes (pomme de terre, pâtes, banane) ? Analysez son menu avec le Suivi des repas et découvrez dans les Recettes pour bébés des alternatives colorées aux légumes cachés.', title_hi = 'एक ही रंग का खाना? 🟡', body_hi = 'सिर्फ़ पीले रंग का खाना (आलू, पास्ता, केला) चाहता है? फ़ीडिंग ट्रैकर से उसके मेन्यू का विश्लेषण कीजिए और बच्चों की रेसिपी में रंग-बिरंगे, छिपी सब्ज़ियों वाले विकल्प खोजिए।', title_id = 'Hanya mau makanan satu warna? 🟡', body_id = 'Hanya mau makanan berwarna kuning (kentang, pasta, pisang)? Analisis menunya dengan alat Pemantau Nutrisi dan temukan alternatif warna-warni dengan sayuran tersembunyi di Resep Bayi.', title_ja = '1色だけの食事？🟡', body_ja = '黄色い食べ物（じゃがいも、パスタ、バナナ）ばかりほしがりますか？「栄養管理ツール」でメニューを分析して、「離乳食を始める赤ちゃんのレシピ」でカラフルで野菜をこっそり入れた代わりのメニューを見つけましょう。', title_ko = '한 가지 색만 먹나요? 🟡', body_ko = '노란색 음식(감자, 파스타, 바나나)만 찾나요? 수유 기록 도구로 식단을 분석하고, 아기 레시피에서 알록달록하고 채소를 숨긴 메뉴를 찾아보세요.', title_nl = 'Eten in één kleur? 🟡', body_nl = 'Wil hij alleen geel eten (aardappel, pasta, banaan)? Analyseer zijn menu met de Voedingstracker en ontdek in Babyrecepten kleurrijke alternatieven met verstopte groenten.', title_pl = 'Jedzenie w jednym kolorze? 🟡', body_pl = 'Chce tylko żółtego jedzenia (ziemniaki, makaron, banan)? Przeanalizuj menu w narzędziu do śledzenia karmienia i odkryj w Przepisach dla niemowląt kolorowe alternatywy z ukrytymi warzywami.', title_pt = 'Só come de uma cor? 🟡', body_pt = 'Só quer alimentos amarelos (batata, massa, banana)? Analise a ementa com o Registo de Alimentação e descubra nas Receitas para bebés alternativas coloridas e com legumes escondidos.', title_sv = 'Mat i bara en färg? 🟡', body_sv = 'Vill barnet bara ha gul mat (potatis, pasta, banan)? Analysera menyn med Matningskoll och upptäck färgglada alternativ med gömda grönsaker i Recept för bebisar.', title_vi = 'Chỉ ăn một màu? 🟡', body_vi = 'Bé chỉ muốn ăn đồ màu vàng (khoai tây, mì ống, chuối)? Hãy phân tích thực đơn bằng Theo dõi cữ bú và khám phá các lựa chọn nhiều màu sắc có giấu rau trong Công thức cho bé.', title_zh = '只吃一种颜色？🟡', body_zh = '只想吃黄色的食物（土豆、意面、香蕉）？用喂养记录工具分析菜单，在宝宝食谱里发现色彩丰富、藏着蔬菜的替代选择。' WHERE id = '4bafd57a-0f5f-4a7d-8215-cfd63b08cad2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La diferencia entre «yo» y «tú» 🗣️', body_es = '¿Ya no habla de sí mismo en tercera persona, sino que dice «yo»? Para apoyar este gran salto cognitivo, pregunta ya a Anacan AI los secretos para conversar bien con tu peque.', title_fr = 'La différence entre « moi » et « toi » 🗣️', body_fr = 'Il ne parle plus de lui à la 3e personne et dit « moi » ? Pour soutenir ce grand bond cognitif, demandez tout de suite à Anacan AI les secrets d''un bon dialogue.', title_hi = '''मैं'' और ''तुम'' का फ़र्क 🗣️', body_hi = 'अब खुद के बारे में अपना नाम लेकर नहीं, ''मैं'' कहकर बात करता है? समझ की इस बड़ी छलांग में मदद के लिए तुरंत Anacan AI से सही बातचीत के राज़ पूछिए।', title_id = 'Beda Aku dan Kamu 🗣️', body_id = 'Ia sudah menyebut dirinya Aku, bukan dengan namanya sendiri? Untuk mendukung lompatan kognitif besar ini, segera tanyakan kepada Anacan AI rahasia membangun dialog yang tepat.', title_ja = '「わたし」と「あなた」のちがい 🗣️', body_ja = '自分のことを名前で呼ぶのではなく、「ぼく」「わたし」と言うようになりましたか？この大きな認知の飛躍を応援するために、上手な会話のコツをすぐにAnacan AIに聞いてみましょう。', title_ko = '''나''와 ''너''의 차이 🗣️', body_ko = '이제 자기를 이름 대신 ''나''라고 부르나요? 이 큰 인지 도약을 돕도록 대화를 잘 이어 가는 비결을 Anacan AI에게 바로 물어보세요.', title_nl = 'Het verschil tussen ik en jij 🗣️', body_nl = 'Praat hij over zichzelf niet meer als een derde persoon, maar zegt hij ik? Vraag Anacan AI meteen hoe je goede gesprekjes voert om deze grote cognitieve sprong te steunen.', title_pl = 'Różnica między „ja” i „ty” 🗣️', body_pl = 'Mówi już o sobie „ja”, a nie w trzeciej osobie? Aby wspierać ten wielki skok poznawczy, od razu zapytaj Anacan AI o sekrety dobrego prowadzenia rozmowy.', title_pt = 'A diferença entre "eu" e "tu" 🗣️', body_pt = 'Já fala de si próprio como "eu" e não na 3.ª pessoa? Para apoiar este grande salto cognitivo, pergunte já ao Anacan AI os segredos para conversar com ele da forma certa.', title_sv = 'Skillnaden mellan Jag och Du 🗣️', body_sv = 'Pratar barnet om sig själv som ”jag” i stället för i tredje person? Fråga Anacan AI direkt om hemligheterna bakom rätt samtal för att stötta detta stora kognitiva språng.', title_vi = 'Phân biệt "Con" và "Mẹ" 🗣️', body_vi = 'Bé đã tự xưng "con" thay vì gọi tên mình như ngôi thứ ba? Để hỗ trợ bước nhảy vọt nhận thức lớn này, hãy hỏi ngay Anacan AI bí quyết trò chuyện đúng cách với bé.', title_zh = '“我”和“你”的区别 🗣️', body_zh = '已经不再用第三人称，而是用“我”来称呼自己了？为了支持这次重大的认知飞跃，马上问问Anacan AI正确对话的秘诀。' WHERE id = 'accea8e1-cb5f-4833-9081-056b6237ac04' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Un cuento más! 📚', body_es = '¿Se inventa excusas nuevas sin parar para no irse a la cama? Pon el temporizador de sueño, mantén los límites y pon las olas del mar de Ruido blanco para llevar la habitación al modo calma.', title_fr = 'Encore un conte ! 📚', body_fr = 'Il invente sans cesse de nouvelles excuses pour ne pas aller au lit ? Lancez le minuteur de sommeil, tenez les limites et passez la chambre en mode calme avec les vagues de l''océan des Bruits blancs.', title_hi = 'बस एक कहानी और! 📚', body_hi = 'सोने न जाने के लिए लगातार नए बहाने बनाता है? स्लीप टाइमर चालू कीजिए, सीमाएँ बनाए रखिए और व्हाइट नॉइज़ में समुद्र की लहरें लगाकर कमरे को शांत मोड में लाइए।', title_id = 'Satu dongeng lagi! 📚', body_id = 'Terus mengarang alasan baru agar tidak perlu tidur? Nyalakan Timer Tidur, jaga batasannya, dan putar suara ombak dari Suara Putih untuk membawa kamar ke mode tenang.', title_ja = 'もう1冊だけ！📚', body_ja = '寝ないために、次々と新しい言い訳を考え出しますか？睡眠タイマーをオンにして、ルールを守りながら、「ホワイトノイズ」の波の音を流して部屋を静けさモードに切りかえましょう。', title_ko = '동화 하나만 더! 📚', body_ko = '잠자리에 들지 않으려고 계속 새로운 핑계를 만들어 내나요? 수면 타이머를 켜고 규칙을 지키며, 백색소음의 파도 소리로 방을 고요한 분위기로 바꿔 주세요.', title_nl = 'Nog één verhaaltje! 📚', body_nl = 'Verzint hij steeds nieuwe smoesjes om niet naar bed te hoeven? Zet de Slaaptimer aan, bewaak de grenzen en zet de kamer met oceaangolven uit Witte ruis in de rustmodus.', title_pl = 'Jeszcze jedna bajka! 📚', body_pl = 'Bez przerwy wymyśla nowe wymówki, żeby nie iść spać? Włącz timer snu, pilnuj granic i puść fale oceanu z Białego szumu, by wprowadzić pokój w tryb ciszy.', title_pt = 'Só mais uma história! 📚', body_pt = 'Inventa sem parar novas desculpas para não ir para a cama? Ligue o temporizador de sono, mantenha os limites e ponha as ondas do mar do Ruído Branco para passar o quarto para o modo tranquilo.', title_sv = 'En saga till! 📚', body_sv = 'Hittar barnet hela tiden på nya ursäkter för att slippa gå och lägga sig? Starta sömntimern, håll gränserna och sätt på havsvågor från Vitt brus för att få rummet i lugnt läge.', title_vi = 'Thêm một chuyện nữa thôi! 📚', body_vi = 'Bé liên tục nghĩ ra cớ mới để không đi ngủ? Hãy bật Bộ hẹn giờ ngủ, giữ vững ranh giới và mở tiếng sóng biển trong Tiếng ồn trắng để căn phòng chuyển sang chế độ yên tĩnh.', title_zh = '再讲一个故事！📚', body_zh = '为了不上床，不停地编新借口？打开睡眠计时器，守住边界，播放白噪音里的海浪声，把房间切换到安静模式。' WHERE id = 'f9e8a36b-3135-4421-adad-49b6ce187cf2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El arte de saltar 🦘', body_es = '¿Intenta saltar desde las escaleras o el sofá? Su motricidad necesita un lugar seguro. Busca en Lugares para mamás un centro de ocio cubierto con camas elásticas y canaliza su energía.', title_fr = 'L''art de sauter 🦘', body_fr = 'Il essaie de sauter des escaliers ou du canapé ? Il lui faut un endroit sûr pour sa motricité. Trouvez dans les Lieux adaptés aux mamans un centre de loisirs couvert avec trampoline et canalisez son énergie.', title_hi = 'कूदने की कला 🦘', body_hi = 'सीढ़ियों या सोफ़े से कूदने की कोशिश करता है? मोटर स्किल्स के विकास के लिए सुरक्षित जगह चाहिए। माँ के लिए अनुकूल जगहें में ट्रैम्पोलिन वाला इनडोर फ़न सेंटर ढूँढिए और उसकी ऊर्जा को सही दिशा दीजिए।', title_id = 'Seni melompat 🦘', body_id = 'Mencoba melompat dari tangga atau sofa? Perkembangan motoriknya butuh tempat yang aman. Temukan pusat hiburan dalam ruangan dengan trampolin di Tempat Ramah Ibu dan salurkan energinya ke arah yang tepat.', title_ja = 'ジャンプの達人 🦘', body_ja = '階段やソファから飛び降りようとしていますか？運動能力の発達には、安全な場所が必要です。「ママにやさしいスポット」でトランポリンのある屋内の遊び場を見つけて、エネルギーを上手に発散させましょう。', title_ko = '점프의 기술 🦘', body_ko = '계단이나 소파에서 뛰어내리려 하나요? 운동 발달에는 안전한 공간이 필요해요. 엄마 친화 장소에서 트램펄린이 있는 실내 놀이 센터를 찾아 에너지를 즐겁게 쓰게 해 주세요.', title_nl = 'De kunst van springen 🦘', body_nl = 'Probeert hij van de trap of de bank te springen? Voor zijn motoriek heeft hij een veilige plek nodig. Zoek in Mamavriendelijke plekken een overdekt speelcentrum met trampolines en geef zijn energie een doel.', title_pl = 'Sztuka skakania 🦘', body_pl = 'Próbuje skakać ze schodów albo z kanapy? Do rozwoju motoryki potrzebuje bezpiecznego miejsca. Znajdź w Miejscach przyjaznych mamom kryte centrum rozrywki z trampolinami i skieruj jego energię we właściwą stronę.', title_pt = 'A arte de saltar 🦘', body_pt = 'Tenta saltar das escadas ou do sofá? Para a motricidade, precisa de um sítio seguro. Encontre nos Locais Amigos das Mães um centro de diversões interior com trampolins e canalize a energia dele.', title_sv = 'Konsten att hoppa 🦘', body_sv = 'Försöker barnet hoppa från trappan eller soffan? Den motoriska utvecklingen behöver en säker plats. Hitta en inomhuslekplats med studsmatta i Mammavänliga platser och styr energin rätt.', title_vi = 'Nghệ thuật nhảy nhót 🦘', body_vi = 'Bé cố nhảy từ cầu thang hay sofa xuống? Bé cần nơi an toàn để phát triển vận động. Hãy tìm trung tâm vui chơi trong nhà có bạt nhún trong Địa điểm thân thiện với mẹ để bé xả năng lượng đúng chỗ.', title_zh = '蹦跳的艺术 🦘', body_zh = '想从楼梯或沙发上往下跳？动作发展需要安全的场地。在妈妈友好场所里找一个有蹦床的室内游乐中心，把精力引到正确的地方。' WHERE id = '52ee49fe-425d-44ef-9429-5ef1f4410d82' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también tienes batería 🔋', body_es = '¿Cansada de decir «no» y de correr todo el día? Vuelca tus agobios en el Diario de ánimo. Recuerda: dedicarte tiempo no es un lujo, es una necesidad.', title_fr = 'Vous aussi, vous avez une batterie 🔋', body_fr = 'Fatiguée d''avoir dit « non » et couru toute la journée ? Confiez vos tensions au Journal d''humeur. N''oubliez pas : prendre du temps pour vous n''est pas un luxe, c''est un besoin.', title_hi = 'आपकी भी बैटरी है 🔋', body_hi = 'दिनभर ''नहीं'' कहते और भागते-भागते थक गईं? मूड डायरी में मन की घुटन लिखिए। याद रखिए, अपने लिए समय निकालना शौक नहीं, ज़रूरत है।', title_id = 'Anda juga punya baterai 🔋', body_id = 'Lelah seharian berkata Tidak dan terus berlari? Curahkan beban hati di Buku Harian Suasana Hati. Ingat, meluangkan waktu untuk diri sendiri bukan kemewahan, melainkan kebutuhan.', title_ja = 'あなたにもバッテリーがあります 🔋', body_ja = '一日中「ダメ」と言って走り回って、疲れましたか？「気分日記」に心のもやもやを書き出しましょう。自分のための時間は、ぜいたくではなく必要なものです。', title_ko = '엄마에게도 배터리가 있어요 🔋', body_ko = '하루 종일 ''안 돼''를 외치고 뛰어다니느라 지쳤나요? 기분 일기에 속상한 마음을 털어놓으세요. 나를 위한 시간은 사치가 아니라 꼭 필요한 거예요.', title_nl = 'Jij hebt ook een batterij 🔋', body_nl = 'Moe van de hele dag nee zeggen en rennen? Schrijf je zorgen van je af in je Stemmingsdagboek. Vergeet niet: tijd voor jezelf is geen luxe, maar een behoefte.', title_pl = 'Ty też masz baterię 🔋', body_pl = 'Masz dość całodziennego mówienia „nie” i bieganiny? Wylej swoje troski w Dzienniku nastroju. Pamiętaj, czas dla siebie to nie luksus, tylko potrzeba.', title_pt = 'A mãe também tem bateria 🔋', body_pt = 'Ficou cansada de dizer "não" e de correr o dia todo? Deixe sair as suas angústias no Diário de Humor. Lembre-se: reservar tempo para si não é um luxo, é uma necessidade.', title_sv = 'Du har också ett batteri 🔋', body_sv = 'Trött på att säga ”nej” och springa hela dagen? Skriv av dig det som tynger dig i Humördagboken. Kom ihåg att tid för dig själv inte är lyx, utan ett behov.', title_vi = 'Mẹ cũng có pin năng lượng 🔋', body_vi = 'Mẹ mệt vì cả ngày nói "Không" và chạy theo bé? Hãy trút nỗi niềm vào Nhật ký tâm trạng. Đừng quên, dành thời gian cho bản thân không phải là xa xỉ mà là nhu cầu.', title_zh = '你也有电池 🔋', body_zh = '一整天说“不”、跑来跑去，累坏了？把心里的烦闷倒进心情日记。记住，留时间给自己不是奢侈，而是需要。' WHERE id = 'f8fbff5d-2a79-4ebc-90f5-c58d315a80ab' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Los zapatos al revés! 👟', body_es = '¿Se ha puesto el zapato derecho en el pie izquierdo y viceversa, y no se los quiere quitar? Decora este divertido intento de independencia con las pegatinas alegres de la Sesión de fotos del bebé y conviértelo en la foto más graciosa del álbum.', title_fr = 'Les chaussures à l''envers ! 👟', body_fr = 'Il a mis la chaussure droite au pied gauche et refuse de les enlever ? Décorez cet essai d''autonomie rigolo avec les stickers joyeux de la Séance photo bébé pour en faire la photo la plus drôle de l''album.', title_hi = 'जूते उल्टे हैं! 👟', body_hi = 'दायाँ जूता बाएँ पैर में और बायाँ दाएँ में पहन लिया और उतारना नहीं चाहता? आत्मनिर्भरता की इस मज़ेदार कोशिश को बेबी फ़ोटोशूट के खुशनुमा स्टिकर से सजाकर एल्बम की सबसे मज़ेदार तस्वीर बनाइए।', title_id = 'Sepatunya terbalik! 👟', body_id = 'Memakai sepatu kanan di kaki kiri dan sebaliknya, lalu tak mau melepasnya? Hiasi usaha mandiri yang lucu ini dengan stiker ceria dari Sesi Foto Bayi dan jadikan foto paling kocak di album.', title_ja = '靴が左右逆！👟', body_ja = '右の靴を左に、左の靴を右にはいて、脱ぎたがらない？このおもしろい自立の挑戦を、「ベビーフォトセッション」の楽しいステッカーで飾って、アルバムでいちばん笑える一枚にしましょう。', title_ko = '신발을 거꾸로 신었어요! 👟', body_ko = '신발을 좌우 바꿔 신고는 벗지 않겠다고 하나요? 이 웃긴 자립 시도를 아기 사진 촬영의 유쾌한 스티커로 꾸며 앨범에서 가장 재미있는 사진으로 만들어 보세요.', title_nl = 'De schoenen zitten verkeerd om! 👟', body_nl = 'Heeft hij de rechterschoen links en de linker rechts aan en wil hij ze niet uitdoen? Versier deze grappige poging tot zelfstandigheid met vrolijke stickers in Babyfotoshoot en maak er de leukste foto van het album van.', title_pl = 'Buty na odwrót! 👟', body_pl = 'Założył prawy but na lewą nogę, a lewy na prawą i nie chce ich zdjąć? Ozdób tę zabawną próbę samodzielności wesołymi naklejkami z Sesji zdjęciowej dziecka i zrób z niej najzabawniejszy kadr w albumie.', title_pt = 'Os sapatos estão trocados! 👟', body_pt = 'Calçou o sapato direito no pé esquerdo e o esquerdo no direito e não os quer tirar? Decore esta tentativa divertida de independência com os autocolantes alegres da Sessão Fotográfica do Bebé e transforme-a na foto mais engraçada do álbum.', title_sv = 'Skorna på fel fot! 👟', body_sv = 'Har barnet satt höger sko på vänster fot och tvärtom och vill inte ta av dem? Dekorera detta roliga försök till självständighet med glada klistermärken i Babyfotografering och gör det till albumets roligaste bild.', title_vi = 'Giày đi ngược rồi! 👟', body_vi = 'Bé đi giày phải vào chân trái, giày trái vào chân phải và không chịu cởi ra? Hãy trang trí nỗ lực tự lập hài hước này bằng sticker trong Chụp ảnh cho bé để có khung hình vui nhất album.', title_zh = '鞋子穿反了！👟', body_zh = '右脚的鞋穿到左脚，左脚的穿到右脚，还不肯脱？用宝宝写真里欢乐的贴纸装饰这个搞笑的独立尝试，变成相册里最逗的一张。' WHERE id = 'fb79060e-f7c1-4e3e-983a-bf84e747b66e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Amor por la pasta 🍝', body_es = '¿Lleva días pidiendo la misma comida? Ser selectivo con la comida está en pleno auge. Busca en Recetas saludables salsas divertidas en las que esconder verduras.', title_fr = 'L''amour des pâtes 🍝', body_fr = 'Il réclame le même plat depuis des jours ? La sélectivité alimentaire est à son sommet. Cherchez dans les Recettes saines des sauces amusantes où cacher les légumes.', title_hi = 'पास्ता से प्यार 🍝', body_hi = 'बच्चा कई दिनों से एक ही खाना माँग रहा है? खाने में नखरे चरम पर हैं। सेहतमंद रेसिपी में ऐसे मज़ेदार सॉस ढूँढिए जिनमें सब्ज़ियाँ छिपाई जा सकें।', title_id = 'Cinta pasta 🍝', body_id = 'Sudah berhari-hari ia minta makanan yang sama? Pilih-pilih makanan sedang di puncaknya. Cari saus seru di Resep Sehat yang bisa menyembunyikan sayuran.', title_ja = 'パスタが大好き 🍝', body_ja = '何日も同じ料理ばかりほしがりますか？好き嫌いが最高潮です。「ヘルシーレシピ」で、野菜をこっそり隠せる楽しいソースを探してみましょう。', title_ko = '파스타 사랑 🍝', body_ko = '며칠째 같은 음식만 찾나요? 편식이 최고조예요. 건강한 레시피에서 채소를 숨길 수 있는 재미있는 소스를 찾아보세요.', title_nl = 'Dol op pasta 🍝', body_nl = 'Wil je kindje al dagen hetzelfde eten? Kieskeurig eten is op zijn hoogtepunt. Zoek in Gezonde recepten leuke sauzen waarin je groenten kunt verstoppen.', title_pl = 'Miłość do makaronu 🍝', body_pl = 'Od kilku dni chce tego samego jedzenia? Wybredność jest u szczytu. Poszukaj w Zdrowych przepisach zabawnych sosów, w których ukryjesz warzywa.', title_pt = 'O gosto pela massa 🍝', body_pt = 'Há dias que quer sempre a mesma comida? Ser esquisito com a comida está no auge. Procure nas Receitas Saudáveis molhos divertidos onde possa esconder os legumes.', title_sv = 'Kärlek till pasta 🍝', body_sv = 'Vill barnet ha samma mat i flera dagar? Kräsenheten är på topp. Leta efter roliga såser där du kan gömma grönsaker i Hälsosamma recept.', title_vi = 'Mê mì ống 🍝', body_vi = 'Nhiều ngày liền bé chỉ đòi một món? Kén ăn đang ở đỉnh điểm. Hãy tìm những loại nước sốt vui nhộn có thể giấu rau củ trong Công thức lành mạnh.', title_zh = '爱吃意面 🍝', body_zh = '孩子好几天都只想吃同一种食物？挑食正处于高峰。去健康食谱里找找能把蔬菜藏进去的趣味酱汁吧。' WHERE id = '0ba368ce-9746-48c2-a3e5-a973ee982121' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El sabor del silencio 🤫', body_es = 'Por fin reina la calma en la habitación. Olvida las tareas, siéntate a oscuras. Activa el Medidor de sonido, mide este silencio y deja descansar tu mente.', title_fr = 'Le goût du silence 🤫', body_fr = 'Le calme est enfin tombé dans la chambre. Laissez tomber les tâches, asseyez-vous dans le noir. Activez le Sonomètre, mesurez ce silence et reposez votre cerveau.', title_hi = 'खामोशी का स्वाद 🤫', body_hi = 'कमरे में आखिरकार शांति छा गई। काम छोड़िए, अँधेरे में बैठ जाइए। साउंड मीटर चालू करके इस खामोशी का स्तर मापिए और अपने दिमाग को आराम दीजिए।', title_id = 'Nikmatnya keheningan 🤫', body_id = 'Kamar akhirnya hening. Lupakan pekerjaan, duduklah dalam gelap. Aktifkan Pengukur Suara, ukur tingkat keheningan ini, dan istirahatkan pikiran Anda.', title_ja = '静けさを味わう 🤫', body_ja = 'やっと部屋に静けさが訪れました。家事はそのままで、暗い中で座りましょう。「サウンドメーター」をオンにしてこの静けさを測り、頭を休ませましょう。', title_ko = '고요함의 맛 🤫', body_ko = '드디어 방이 조용해졌어요. 할 일은 내려놓고 어둠 속에 앉아 보세요. 소음 측정기를 켜서 이 고요함을 재 보며 머리를 쉬게 해 주세요.', title_nl = 'De smaak van stilte 🤫', body_nl = 'Eindelijk is het stil in de kamer. Laat het werk liggen en ga in het donker zitten. Zet de Geluidsmeter aan, meet hoe stil het is en laat je hoofd tot rust komen.', title_pl = 'Smak ciszy 🤫', body_pl = 'W pokoju wreszcie zapadła cisza. Zostaw obowiązki i usiądź w ciemności. Włącz Miernik dźwięku, zmierz poziom tej ciszy i daj odpocząć głowie.', title_pt = 'O sabor do silêncio 🤫', body_pt = 'Finalmente, o quarto ficou em silêncio. Deixe as tarefas, sente-se no escuro. Ative o Medidor de Som, meça o nível deste silêncio e descanse a cabeça.', title_sv = 'Tystnadens smak 🤫', body_sv = 'Äntligen har det blivit lugnt i rummet. Släpp allt och sätt dig i mörkret. Aktivera Ljudmätaren, mät hur tyst det är och låt hjärnan vila.', title_vi = 'Hương vị của tĩnh lặng 🤫', body_vi = 'Căn phòng cuối cùng cũng yên tĩnh. Gác lại mọi việc, ngồi xuống trong bóng tối. Hãy bật Đo âm thanh để đo độ yên tĩnh này và cho đầu óc được nghỉ ngơi.', title_zh = '安静的味道 🤫', body_zh = '房间里终于安静下来了。放下手头的事，在黑暗中坐一会儿。打开分贝仪测一测这份安静的程度，让大脑休息一下。' WHERE id = '92abce30-d667-4f40-9371-ee7642e09a28' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Hemos llegado a 800!🚀', body_es = 'Ahora es tiempo de más preguntas, más movimiento y más personalidad. Empieza esta nueva y emocionante etapa respirando hondo.', title_fr = '800 jours, c''est fait ! 🚀', body_fr = 'Place à plus de questions, plus de mouvement et plus de personnalité. Commencez cette nouvelle étape passionnante en respirant profondément.', title_hi = '800 दिन पूरे!🚀', body_hi = 'अब और ज़्यादा सवालों, और ज़्यादा भाग-दौड़ और और ज़्यादा अपनी पहचान का समय है। इस नए और रोमांचक दौर की शुरुआत एक गहरी साँस के साथ कीजिए।', title_id = '800 hari terlewati!🚀', body_id = 'Sekarang saatnya lebih banyak pertanyaan, lebih banyak gerakan, dan lebih banyak kepribadian. Mulailah fase baru yang seru ini dengan tarikan napas dalam.', title_ja = '800日達成！🚀', body_ja = 'これからは、もっとたくさんの質問、もっとたくさんの動き、そしてもっと豊かな個性の時期です。深呼吸をして、このわくわくする新しい段階を始めましょう。', title_ko = '800일 달성! 🚀', body_ko = '이제는 더 많은 질문, 더 많은 움직임, 더 뚜렷한 개성의 시간이에요. 이 새롭고 설레는 시기를 깊은 숨과 함께 시작해 보세요.', title_nl = '800 dagen bereikt! 🚀', body_nl = 'Nu is het tijd voor meer vragen, meer beweging en meer eigenheid. Begin aan deze nieuwe, spannende fase met een diepe ademhaling.', title_pl = 'Mamy już 800!🚀', body_pl = 'Teraz czas na więcej pytań, więcej ruchu i więcej indywidualności. Zacznij ten nowy, ekscytujący etap od głębokiego oddechu.', title_pt = 'Chegámos aos 800! 🚀', body_pt = 'Agora é tempo de mais perguntas, mais movimento e mais personalidade. Comece esta fase nova e emocionante com uma respiração profunda.', title_sv = '800 avklarade!🚀', body_sv = 'Nu är det dags för fler frågor, mer rörelse och mer personlighet. Börja denna nya och spännande period med ett djupt andetag.', title_vi = 'Đã tròn 800 ngày! 🚀', body_vi = 'Giờ là lúc của nhiều câu hỏi hơn, nhiều vận động hơn và nhiều cá tính hơn. Hãy hít một hơi thật sâu và bắt đầu giai đoạn mới đầy háo hức này.', title_zh = '800天达成！🚀', body_zh = '现在是更多问题、更多活动、更多个性的时候了。深吸一口气，开始这个崭新又激动人心的阶段吧。' WHERE id = 'e50a9ce1-a01a-4462-9bc9-e410e94685ff' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Mitos de la madre perfecta 🛑', body_es = '¿Te juzgas porque hoy ha habido mucha pantalla? Olvida a las madres ideales de internet. Eres perfecta con tu propia realidad.', title_fr = 'Les mythes de la maman parfaite 🛑', body_fr = 'Vous vous reprochez d''avoir laissé trop d''écran aujourd''hui ? Oubliez les mamans idéales d''Internet. Vous êtes parfaite dans votre propre réalité.', title_hi = 'परफ़ेक्ट माँ के मिथक 🛑', body_hi = 'आज स्क्रीन टाइम ज़्यादा हो गया, इसलिए खुद को कोस रही हैं? इंटरनेट की आदर्श माँओं को भूल जाइए। आप अपनी असलियत के साथ परफ़ेक्ट हैं।', title_id = 'Mitos ibu sempurna 🛑', body_id = 'Menyalahkan diri karena hari ini waktu layarnya terlalu lama? Lupakan ibu-ibu ideal di internet. Anda sempurna dengan kenyataan Anda sendiri.', title_ja = '完璧なママの神話 🛑', body_ja = '今日は画面時間が長くなったと自分を責めていますか？ネットの理想のママたちのことは忘れましょう。あなたは、ありのままのあなたで完璧です。', title_ko = '완벽한 엄마라는 신화 🛑', body_ko = '오늘 화면 시간이 길었다고 자책하나요? 인터넷 속 이상적인 엄마들은 잊으세요. 엄마는 엄마의 현실 그대로 완벽해요.', title_nl = 'Mythes over de perfecte moeder 🛑', body_nl = 'Veroordeel je jezelf omdat er vandaag veel schermtijd was? Vergeet de ideale moeders op internet. Jij bent perfect in je eigen werkelijkheid.', title_pl = 'Mity o idealnej mamie 🛑', body_pl = 'Obwiniasz się, bo dziś było dużo czasu przed ekranem? Zapomnij o idealnych mamach z internetu. Jesteś doskonała w swojej własnej rzeczywistości.', title_pt = 'Os mitos da mãe perfeita 🛑', body_pt = 'Culpa-se porque hoje houve muito tempo de ecrã? Esqueça as mães ideais da internet. É perfeita com a sua realidade.', title_sv = 'Myter om den perfekta mamman 🛑', body_sv = 'Dömer du dig själv för att det blev mycket skärmtid i dag? Glöm de idealiska mammorna på internet. Du är perfekt i din egen verklighet.', title_vi = 'Những huyền thoại về người mẹ hoàn hảo 🛑', body_vi = 'Mẹ tự trách vì hôm nay bé xem màn hình quá nhiều? Hãy quên những bà mẹ lý tưởng trên mạng. Mẹ hoàn hảo theo cách thật của chính mình.', title_zh = '完美妈妈的神话 🛑', body_zh = '因为今天屏幕时间太多而责怪自己？忘掉网上那些理想的妈妈吧。真实的你就已经很完美了。' WHERE id = '0ea063ed-fd41-47e6-9ae7-1268a3f1138f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Se te agota la paciencia? Cierra la puerta de la habitación y deja a tu peque a solas con papá. Que esta noche él sea el jefe de los juegos de casa.', body_fr = 'Vous êtes à bout de patience ? Fermez la porte de la chambre et laissez-le seul avec son papa. Ce soir, c''est lui le chef des jeux à la maison.', body_hi = 'सब्र खत्म हो रहा है? कमरे का दरवाज़ा बंद कीजिए और बच्चे को उसके पापा के साथ अकेला छोड़ दीजिए। आज शाम घर के खेलों के बॉस वे ही रहें।', body_id = 'Kesabaran mulai menipis? Tutup pintu kamar dan biarkan si kecil berdua dengan ayahnya. Malam ini, biarkan ia jadi pemimpin permainan di rumah.', body_ja = 'もう我慢の限界？部屋のドアを閉めて、お子さんとパパを2人きりにしましょう。今夜は、おうちの遊びのリーダーをパパに任せて。', body_ko = '인내심이 바닥났나요? 방문을 닫고 아이를 아빠와 단둘이 있게 해 주세요. 오늘 저녁 집 안 놀이의 대장은 아빠에게 맡기세요.', body_nl = 'Raakt je geduld op? Doe de deur dicht en laat je kindje alleen met papa. Laat hem vanavond de baas zijn van de spelletjes in huis.', body_pl = 'Kończy ci się cierpliwość? Zamknij drzwi do pokoju i zostaw malucha sam na sam z tatą. Niech dziś wieczorem to on rządzi domowymi zabawami.', body_pt = 'A paciência está a esgotar-se? Feche a porta do quarto e deixe-o sozinho com o pai. Esta noite, ele que seja o chefe das brincadeiras lá de casa.', body_sv = 'Har tålamodet tagit slut? Stäng dörren och lämna barnet ensam med pappa. Låt honom vara chef över lekarna hemma i kväll.', body_vi = 'Mẹ sắp hết kiên nhẫn? Hãy đóng cửa phòng và để bé ở riêng với bố. Tối nay để bố làm "người chỉ huy" các trò chơi trong nhà nhé.', body_zh = '快没耐心了？关上房门，让孩子和爸爸单独待一会儿。今晚就让爸爸来主持家里的游戏吧。' WHERE id = '6e5882b6-b1b9-4876-8253-b97551d73f12' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La etapa del «¿por qué?» 🤔', body_es = '¿Pregunta «¿Por qué es así?» por todo? Su cerebro absorbe información como una esponja. Arma tu paciencia y dale respuestas cortas y lógicas.', title_fr = 'La période des « pourquoi ? » 🤔', body_fr = 'Il demande « Pourquoi c''est comme ça ? » à propos de tout ? Son cerveau absorbe les informations comme une éponge. Armez-vous de patience et donnez-lui des réponses courtes et logiques.', title_hi = '''क्यों?'' का दौर 🤔', body_hi = 'हर चीज़ पर पूछता है ''यह ऐसा क्यों है?'' उसका दिमाग स्पंज की तरह जानकारी सोख रहा है। सब्र रखिए और उसे छोटे, तर्कसंगत जवाब दीजिए।', title_id = 'Masa Kenapa? 🤔', body_id = 'Selalu bertanya Kenapa begini? tentang segala hal? Otaknya menyerap informasi seperti spons. Kumpulkan kesabaran dan beri ia jawaban singkat yang logis.', title_ja = '「なんで？」の時期 🤔', body_ja = 'なんにでも「どうしてこうなの？」と聞いてきますか？脳がスポンジのように情報を吸収しています。気持ちを落ち着けて、短く筋の通った答えをあげましょう。', title_ko = '''왜?'' 시기 🤔', body_ko = '무엇이든 ''이건 왜 그래?'' 하고 묻나요? 뇌가 스펀지처럼 정보를 빨아들이고 있어요. 인내심을 갖고 짧고 논리적으로 대답해 주세요.', title_nl = 'De waarom?-fase 🤔', body_nl = 'Vraagt hij bij alles: waarom is dat zo? Zijn hersenen zuigen informatie op als een spons. Verzamel je geduld en geef hem korte, logische antwoorden.', title_pl = 'Etap „Dlaczego?” 🤔', body_pl = 'O wszystko pyta „Dlaczego tak jest?”? Jego mózg chłonie informacje jak gąbka. Uzbrój się w cierpliwość i dawaj mu krótkie, logiczne odpowiedzi.', title_pt = 'A fase do "Porquê?" 🤔', body_pt = 'Pergunta "Porque é assim?" sobre tudo? O cérebro dele absorve informação como uma esponja. Arme-se de paciência e dê-lhe respostas curtas e lógicas.', title_sv = '”Varför?”-perioden 🤔', body_sv = 'Frågar barnet ”Varför är det så?” om allt? Hjärnan suger upp information som en svamp. Samla tålamod och ge korta, logiska svar.', title_vi = 'Giai đoạn "Tại sao?" 🤔', body_vi = 'Bé hỏi "Sao lại thế này?" về mọi thứ? Não bộ của bé hút thông tin như miếng bọt biển. Hãy kiên nhẫn và trả lời bé ngắn gọn, logic.', title_zh = '“为什么？”阶段 🤔', body_zh = '什么都要问“为什么会这样？”宝宝的大脑像海绵一样吸收信息。拿出耐心，给宝宝简短又有逻辑的回答吧。' WHERE id = 'c72b4558-e629-4a4b-bb39-ef072b6603b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Plátano o teléfono? 🍌', body_es = '¿Se pone el plátano o el mando en la oreja y mantiene conversaciones imaginarias? ¡El juego de imaginación en su máximo esplendor! Añade ya este momento de oro en vídeo con sonido al Álbum del bebé y guárdalo en la memoria.', title_fr = 'Banane ou téléphone ? 🍌', body_fr = 'Il colle une banane ou la télécommande à son oreille et fait semblant de téléphoner ? C''est le sommet des jeux d''imagination ! Ajoutez tout de suite ce moment en or en vidéo avec le son à l''Album de bébé pour le garder en mémoire.', title_hi = 'केला या फ़ोन? 🍌', body_hi = 'केला या रिमोट कान से लगाकर काल्पनिक बातें करता है? कल्पना वाले खेलों का चरम! इस अनमोल पल को तुरंत आवाज़ वाले वीडियो के रूप में बेबी एल्बम में जोड़कर यादों में सहेजिए।', title_id = 'Pisang, atau telepon? 🍌', body_id = 'Menempelkan pisang atau remote ke telinga dan mengobrol dengan teman khayalan? Puncak permainan imajinasi! Segera simpan momen emas ini sebagai video bersuara di Album Bayi dan jadikan kenangan.', title_ja = 'バナナ？それとも電話？🍌', body_ja = 'バナナやリモコンを耳に当てて、想像のおしゃべりをしていますか？ごっこ遊びが最高潮です！この宝物のような瞬間を、すぐに音声付きの動画で「ベビーアルバム」に追加して、記憶に刻みましょう。', title_ko = '바나나일까, 전화기일까? 🍌', body_ko = '바나나나 리모컨을 귀에 대고 상상 속 통화를 하나요? 상상 놀이가 최고조예요! 이 금쪽같은 순간을 바로 소리가 담긴 영상으로 아기 앨범에 올려 추억으로 새기세요.', title_nl = 'Banaan of telefoon? 🍌', body_nl = 'Houdt hij een banaan of de afstandsbediening tegen zijn oor en voert hij denkbeeldige gesprekken? Het fantasiespel is op zijn hoogtepunt! Zet dit gouden moment meteen als video met geluid in het Babyalbum.', title_pl = 'Banan czy telefon? 🍌', body_pl = 'Przykłada banana albo pilota do ucha i prowadzi wyimaginowane rozmowy? To szczyt zabaw w udawanie! Od razu dodaj tę złotą chwilę jako film z dźwiękiem do Albumu dziecka i zachowaj w pamięci.', title_pt = 'Banana ou telefone? 🍌', body_pt = 'Encosta uma banana ou o comando à orelha e tem conversas imaginárias? É o auge das brincadeiras de imaginação! Adicione já este momento de ouro em vídeo com som ao Álbum do Bebé e guarde-o na memória.', title_sv = 'Banan eller telefon? 🍌', body_sv = 'Håller barnet en banan eller fjärrkontrollen mot örat och pratar på låtsas? Låtsaslekarna är på topp! Lägg direkt till detta gyllene ögonblick som video med ljud i Babyalbumet och spara det i minnet.', title_vi = 'Chuối hay điện thoại? 🍌', body_vi = 'Bé áp quả chuối hoặc điều khiển lên tai và "nói chuyện" tưởng tượng? Đỉnh cao của trò chơi tưởng tượng! Hãy thêm ngay video có tiếng khoảnh khắc quý như vàng này vào Album của bé.', title_zh = '香蕉，还是电话？🍌', body_zh = '把香蕉或遥控器放到耳边，假装打电话？想象游戏的巅峰！马上把这个黄金时刻录成有声视频加进宝宝相册，永远留在回忆里。' WHERE id = '10f0ddfb-06ae-4780-9b39-ba433d0edc10' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Miedo a la habitación oscura 🌌', body_es = '¿Cuando apagas la luz, los objetos de la habitación le parecen monstruos? Al crecer la imaginación aparecen los miedos. Pon el sonido del vientre materno de Ruido blanco y devuélvele aquella sensación de seguridad perfecta.', title_fr = 'Peur de la chambre dans le noir 🌌', body_fr = 'Quand vous éteignez la lumière, les objets de la chambre deviennent des monstres ? L''imagination grandit, et les peurs aussi. Lancez le son du ventre maternel des Bruits blancs pour lui rendre ce sentiment de sécurité parfait d''autrefois.', title_hi = 'अँधेरे कमरे का डर 🌌', body_hi = 'बत्ती बुझाते ही कमरे की चीज़ें उसे राक्षस जैसी लगती हैं? कल्पना बढ़ने के साथ डर भी आते हैं। व्हाइट नॉइज़ में गर्भ की आवाज़ चलाकर उसे वही पुराना, पूरा सुरक्षा का एहसास दीजिए।', title_id = 'Takut kamar gelap 🌌', body_id = 'Saat lampu dimatikan, benda-benda di kamar tampak seperti monster baginya? Makin berkembang imajinasinya, makin muncul rasa takut. Putar suara rahim dari Suara Putih dan beri ia rasa aman yang akrab dan sempurna.', title_ja = '暗い部屋がこわい 🌌', body_ja = '電気を消すと、部屋の中のものがおばけに見えますか？想像力が育つにつれて、こわさも生まれます。「ホワイトノイズ」の胎内の音を流して、なつかしい、完璧な安心感を届けましょう。', title_ko = '어두운 방이 무서워요 🌌', body_ko = '불을 끄면 방 안의 물건이 괴물처럼 보이나요? 상상력이 자라면 두려움도 생겨요. 백색소음에서 엄마 배 속 소리를 틀어 익숙하고 완벽한 안정감을 선물하세요.', title_nl = 'Bang voor een donkere kamer 🌌', body_nl = 'Lijken de spullen in de kamer op monsters als het licht uit is? Met de fantasie groeien ook de angsten. Zet het baarmoedergeluid uit Witte ruis aan en geef hem dat oude, perfecte gevoel van veiligheid.', title_pl = 'Strach przed ciemnym pokojem 🌌', body_pl = 'Gdy gasisz światło, przedmioty w pokoju wydają mu się potworami? Wraz z wyobraźnią rosną lęki. Włącz w Białym szumie odgłosy z brzucha mamy i daj mu znajome, doskonałe poczucie bezpieczeństwa.', title_pt = 'Medo do quarto escuro 🌌', body_pt = 'Quando apaga a luz, os objetos do quarto parecem-lhe monstros? Com mais imaginação, surgem também medos. Ligue no Ruído Branco o som do útero materno e dê-lhe aquela antiga e perfeita sensação de segurança.', title_sv = 'Rädsla för mörka rum 🌌', body_sv = 'Liknar barnet sakerna i rummet vid monster när du släcker ljuset? När fantasin växer uppstår också rädslor. Sätt på ljudet från livmodern i Vitt brus och ge barnet den gamla, perfekta känslan av trygghet.', title_vi = 'Sợ phòng tối 🌌', body_vi = 'Khi tắt đèn, bé tưởng đồ vật trong phòng là quái vật? Trí tưởng tượng càng phát triển thì nỗi sợ cũng xuất hiện. Hãy bật âm thanh trong bụng mẹ trong Tiếng ồn trắng để mang lại cho bé cảm giác an toàn trọn vẹn quen thuộc.', title_zh = '害怕黑暗的房间 🌌', body_zh = '关灯后把房间里的东西想象成怪兽？想象力越丰富，恐惧也会随之出现。打开白噪音里的子宫声，给宝宝熟悉而完美的安全感。' WHERE id = '24cc9d6f-2286-4f7a-a81a-633ab5dd91df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El secreto del hierro y la energía 🥩', body_es = 'Para que tu peque tan activo no tenga anemia, comprueba en el Seguimiento de tomas el hierro de hoy (carne, lentejas, espinacas) y enriquece su menú junto con vitamina C.', title_fr = 'Le secret du fer et de l''énergie 🥩', body_fr = 'Pour que votre petit actif ne manque pas de fer, vérifiez dans le Suivi des repas ses apports en fer du jour (viande, lentilles, épinards) et enrichissez son menu avec de la vitamine C.', title_hi = 'आयरन और ऊर्जा का राज़ 🥩', body_hi = 'चंचल नन्हे को खून की कमी न हो, इसके लिए फ़ीडिंग ट्रैकर में आज का आयरन (मांस, मसूर, पालक) जाँचिए और विटामिन C के साथ मेन्यू को और पौष्टिक बनाइए।', title_id = 'Rahasia zat besi dan energi 🥩', body_id = 'Agar si kecil yang aktif tidak mengalami anemia, cek asupan zat besi hari ini (daging, lentil, bayam) di alat Pemantau Nutrisi dan perkaya menunya bersama vitamin C.', title_ja = '鉄分と元気のひみつ 🥩', body_ja = '活発なお子さんが貧血にならないよう、「栄養管理ツール」で今日の鉄分（お肉、レンズ豆、ほうれん草）の摂取量を確認して、ビタミンCと一緒にメニューを豊かにしましょう。', title_ko = '철분과 에너지의 비밀 🥩', body_ko = '활발한 아이가 빈혈을 겪지 않도록 수유 기록 도구로 오늘의 철분 섭취(고기, 렌틸콩, 시금치)를 확인하고 비타민 C와 함께 식단을 풍성하게 해 주세요.', title_nl = 'Het geheim van ijzer en energie 🥩', body_nl = 'Controleer in de Voedingstracker het ijzer van vandaag (vlees, linzen, spinazie) en maak het menu rijker met vitamine C, zodat je actieve kleintje geen bloedarmoede krijgt.', title_pl = 'Sekret żelaza i energii 🥩', body_pl = 'Aby aktywny maluch nie miał anemii, sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza (mięso, soczewica, szpinak) i wzbogać menu o witaminę C.', title_pt = 'O segredo do ferro e da energia 🥩', body_pt = 'Para que o seu pequenino tão ativo não tenha anemia, verifique no Registo de Alimentação o ferro de hoje (carne, lentilhas, espinafres) e enriqueça a ementa juntando vitamina C.', title_sv = 'Hemligheten bakom järn och energi 🥩', body_sv = 'För att din aktiva lilla inte ska få blodbrist, kontrollera dagens järnintag (kött, linser, spenat) i Matningskoll och berika menyn tillsammans med C-vitamin.', title_vi = 'Bí mật của sắt và năng lượng 🥩', body_vi = 'Để bé hiếu động không bị thiếu máu, hãy kiểm tra lượng sắt (thịt, đậu lăng, rau chân vịt) hôm nay trong Theo dõi cữ bú và làm thực đơn phong phú hơn cùng vitamin C.', title_zh = '铁与能量的秘密 🥩', body_zh = '为了让好动的小家伙不贫血，在喂养记录工具里查看今天的铁（肉类、扁豆、菠菜）摄入量，再搭配维生素C让菜单更丰富。' WHERE id = '3c29abba-6cf4-47d2-a227-99611ccf0101' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Líquidos y estreñimiento 💧', body_es = '¿Corre mucho y bebe poca agua? Fíjate en las deposiciones al cambiar el pañal. Si hay riesgo de estreñimiento, anótalo en la app y añade enseguida alimentos con fibra (pera, avena) con el Seguimiento de tomas.', title_fr = 'Hydratation et constipation 💧', body_fr = 'Il court beaucoup et boit peu ? Observez les selles à chaque change. En cas de risque de constipation, notez-le dans l''appli et ajoutez tout de suite des aliments riches en fibres (poire, avoine) avec le Suivi des repas.', title_hi = 'तरल और कब्ज़ 💧', body_hi = 'खूब दौड़ता है, पर पानी कम पीता है? डायपर बदलते समय पॉटी पर ध्यान दीजिए। कब्ज़ का खतरा हो तो ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से फ़ाइबर वाली चीज़ें (नाशपाती, ओट्स) जोड़िए।', title_id = 'Asupan cairan dan sembelit 💧', body_id = 'Banyak berlari, tapi sedikit minum? Perhatikan kotorannya saat mengganti popok. Jika ada risiko sembelit, catat di aplikasi dan segera tambahkan makanan berserat (pir, oat) dengan alat Pemantau Nutrisi.', title_ja = '水分補給と便秘 💧', body_ja = 'たくさん走り回るのに、あまりお水を飲まない？おむつ替えのときにうんちの様子をチェックしましょう。便秘のおそれがあればアプリに記録して、すぐに「栄養管理ツール」で食物繊維の多い食べ物（洋なし、オートミール）を加えましょう。', title_ko = '수분 섭취와 변비 💧', body_ko = '많이 뛰는데 물은 적게 마시나요? 기저귀를 갈 때 배변을 살펴보세요. 변비가 걱정된다면 앱에 기록하고 수유 기록 도구로 섬유질 음식(배, 귀리)을 바로 추가하세요.', title_nl = 'Drinken en verstopping 💧', body_nl = 'Rent hij veel en drinkt hij weinig? Let bij het verschonen op de ontlasting. Is er kans op verstopping, noteer het in de app en voeg meteen met de Voedingstracker vezelrijk eten (peer, havermout) toe.', title_pl = 'Picie a zaparcia 💧', body_pl = 'Dużo biega, a mało pije? Obserwuj kupki przy zmianie pieluszki. Jeśli jest ryzyko zaparć, zapisz to w aplikacji i od razu dodaj w narzędziu do śledzenia karmienia produkty bogate w błonnik (gruszka, płatki owsiane).', title_pt = 'Líquidos e prisão de ventre 💧', body_pt = 'Corre muito e bebe pouca água? Observe as fezes ao mudar a fralda. Se houver risco de prisão de ventre, registe-o na app e acrescente já alimentos ricos em fibra (pera, aveia) com o Registo de Alimentação.', title_sv = 'Vätskeintag och förstoppning 💧', body_sv = 'Springer barnet mycket men dricker lite? Håll koll på avföringen när du byter blöja. Finns risk för förstoppning, anteckna det i appen och lägg direkt till fiberrik mat (päron, havre) med Matningskoll.', title_vi = 'Uống nước và táo bón 💧', body_vi = 'Bé chạy nhiều mà uống ít nước? Hãy để ý phân khi thay tã. Nếu có nguy cơ táo bón, hãy ghi vào ứng dụng và thêm ngay thực phẩm giàu chất xơ (lê, yến mạch) bằng Theo dõi cữ bú.', title_zh = '饮水与便秘 💧', body_zh = '跑得多，喝得少？换尿布时留意一下排便。如果有便秘风险，记到应用里，马上用喂养记录工具加入富含纤维的食物（梨、燕麦）。' WHERE id = '074c97a3-66b5-4499-b8dd-c6ca41189da1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maestro de colores y formas 🔴🟩', body_es = '¿Agrupa bloques, botones o juguetes por colores? Descubre ya en Productos recomendados puzles de madera que desarrollan la lógica y pondrán a prueba su inteligencia.', title_fr = 'Maître des couleurs et des formes 🔴🟩', body_fr = 'Il range les cubes, les boutons ou les jouets par couleur ? Découvrez tout de suite dans les Produits recommandés des puzzles en bois qui développent la logique et stimuleront encore son intelligence.', title_hi = 'रंग और आकार का मास्टर 🔴🟩', body_hi = 'ढक्कनों, बटनों या खिलौनों को रंग के हिसाब से अलग करता है? उसकी बुद्धि को और चुनौती देने वाली, तर्क बढ़ाने वाली लकड़ी की पज़ल तुरंत सुझाए गए प्रोडक्ट सेक्शन में खोजिए।', title_id = 'Jago warna dan bentuk 🔴🟩', body_id = 'Mengelompokkan balok, kancing, atau mainan berdasarkan warnanya? Segera temukan puzzle kayu yang mengembangkan logika dan lebih menantang kecerdasannya di bagian Produk Rekomendasi.', title_ja = '色と形の名人 🔴🟩', body_ja = '積み木やボタン、おもちゃを色ごとに分けていますか？知性をさらに刺激し、論理的な思考を育てる木のパズルを、すぐに「おすすめ商品」で見つけましょう。', title_ko = '색과 모양의 달인 🔴🟩', body_ko = '블록이나 단추, 장난감을 색깔별로 나누나요? 두뇌를 더 자극하고 논리력을 키워 줄 원목 퍼즐을 추천 제품 섹션에서 바로 찾아보세요.', title_nl = 'Meester in kleuren en vormen 🔴🟩', body_nl = 'Sorteert hij blokken, knopen of speelgoed op kleur? Ontdek meteen in Aanbevolen producten houten puzzels die zijn verstand nog meer uitdagen en zijn logica ontwikkelen.', title_pl = 'Mistrz kolorów i kształtów 🔴🟩', body_pl = 'Grupuje klocki, guziki albo zabawki według kolorów? Od razu odkryj w sekcji Polecane produkty drewniane układanki rozwijające logikę, które jeszcze mocniej pobudzą jego umysł.', title_pt = 'Mestre das cores e das formas 🔴🟩', body_pt = 'Agrupa cubos, botões ou brinquedos por cores? Descubra já na secção Produtos Recomendados puzzles de madeira que desenvolvem a lógica e desafiam ainda mais a inteligência dele.', title_sv = 'Mästare på färger och former 🔴🟩', body_sv = 'Grupperar barnet kapsyler, knappar eller leksaker efter färg? Upptäck direkt träpussel som utvecklar logiken och utmanar tänkandet ännu mer i Rekommenderade produkter.', title_vi = 'Bậc thầy màu sắc và hình dạng 🔴🟩', body_vi = 'Bé xếp nhóm nắp chai, cúc áo hay đồ chơi theo màu? Hãy khám phá ngay các bộ ghép hình gỗ phát triển tư duy giúp bé động não nhiều hơn trong mục Sản phẩm gợi ý.', title_zh = '颜色和形状小达人 🔴🟩', body_zh = '按颜色给瓶盖、纽扣或玩具分组？马上去推荐商品板块发现能给宝宝更多挑战、促进逻辑发展的木制拼图。' WHERE id = '33f7b16f-fd6e-4686-be50-8b9aabfa4a20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Terror nocturno o pesadilla? 🤖', body_es = '¿Se despierta llorando a medianoche y no se calma? Para entender la diferencia entre ambos y actuar bien desde el punto de vista psicológico, echa un vistazo a nuestros artículos científicos del Blog.', title_fr = 'Terreur nocturne ou cauchemar ? 🤖', body_fr = 'Il se réveille en pleurant au milieu de la nuit et ne se calme pas ? Pour comprendre la différence entre les deux et réagir correctement, consultez nos articles scientifiques de la rubrique Blogs.', title_hi = 'नाइट टेरर या बुरा सपना? 🤖', body_hi = 'आधी रात को रोते हुए जागता है और शांत नहीं होता? इन दोनों का फ़र्क समझने और सही मनोवैज्ञानिक तरीके से संभालने के लिए ब्लॉग सेक्शन में हमारे वैज्ञानिक लेख देखिए।', title_id = 'Teror malam, atau mimpi buruk? 🤖', body_id = 'Terbangun sambil menangis di tengah malam dan tak bisa ditenangkan? Untuk memahami beda keduanya dan menanganinya secara psikologis dengan benar, baca artikel ilmiah kami di bagian Blog.', title_ja = '夜驚症？それとも悪夢？🤖', body_ja = '夜中に泣いて起きて、泣き止まない？このふたつのちがいを知り、心理的に正しく対応するために、ブログの科学的な記事をのぞいてみましょう。', title_ko = '야경증일까, 악몽일까? 🤖', body_ko = '한밤중에 울며 깨서 진정이 안 되나요? 둘의 차이를 알고 올바르게 심리적으로 대처하도록 블로그의 과학적인 글을 살펴보세요.', title_nl = 'Nachtangst of nachtmerrie? 🤖', body_nl = 'Wordt hij midden in de nacht huilend wakker en is hij niet te troosten? Lees de wetenschappelijke artikelen in Blogs om het verschil tussen die twee te begrijpen en psychologisch goed te reageren.', title_pl = 'Lęk nocny czy koszmar? 🤖', body_pl = 'Budzi się z płaczem w środku nocy i nie daje się uspokoić? Zajrzyj do naszych naukowych artykułów w sekcji Blog, by zrozumieć różnicę między nimi i właściwie zareagować.', title_pt = 'Terror noturno ou pesadelo? 🤖', body_pt = 'Acorda a chorar a meio da noite e não se acalma? Para perceber a diferença entre os dois e intervir da forma psicológica certa, espreite os nossos artigos científicos nos Blogues.', title_sv = 'Nattskräck eller mardröm? 🤖', body_sv = 'Vaknar barnet gråtande mitt i natten och går inte att lugna? Läs våra vetenskapliga artiklar i Bloggar för att förstå skillnaden mellan de två och agera rätt psykologiskt.', title_vi = 'Hoảng sợ ban đêm hay ác mộng? 🤖', body_vi = 'Bé khóc thức giấc lúc nửa đêm và không chịu dịu lại? Hãy xem các bài viết khoa học trong mục Blog để hiểu sự khác nhau giữa hai hiện tượng này và can thiệp tâm lý đúng cách.', title_zh = '夜惊，还是噩梦？🤖', body_zh = '半夜哭着醒来，怎么也安抚不下来？为了弄清两者的区别并正确地进行心理干预，去看看博客板块里我们的科学文章吧。' WHERE id = '912d3d15-f8b0-4ade-8219-5e9c81b99f0a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Ha sido un día difícil? 📝', body_es = 'Desahógate escribiendo el estrés de hoy en el Diario de ánimo. Todas las madres pasan por estas crisis, no estás sola.', title_fr = 'Journée difficile ? 📝', body_fr = 'Videz votre cœur en écrivant le stress du jour dans le Journal d''humeur. Toutes les mamans vivent ces crises, vous n''êtes pas seule.', title_hi = 'मुश्किल दिन था? 📝', body_hi = 'आज का तनाव मूड डायरी में लिखकर दिल हल्का कीजिए। हर माँ इन मुश्किलों से गुज़रती है, आप अकेली नहीं हैं।', title_id = 'Hari yang berat? 📝', body_id = 'Lepaskan beban hati dengan menuliskan stres hari ini di Buku Harian Suasana Hati. Semua ibu pernah mengalami masa seperti ini, Anda tidak sendirian.', title_ja = '大変な一日でしたか？📝', body_ja = '「気分日記」に今日のストレスを書いて、心を軽くしましょう。どのママもこうしたかんしゃくを経験しています。あなたはひとりではありません。', title_ko = '힘든 하루였나요? 📝', body_ko = '기분 일기에 오늘의 스트레스를 적으며 마음을 비워 보세요. 모든 엄마가 이런 순간을 겪어요. 혼자가 아니에요.', title_nl = 'Was het een zware dag? 📝', body_nl = 'Schrijf de stress van vandaag van je af in je Stemmingsdagboek. Alle moeders maken zulke buien mee, je staat er niet alleen voor.', title_pl = 'To był trudny dzień? 📝', body_pl = 'Wypisz dzisiejszy stres w Dzienniku nastroju i ulżyj sercu. Każda mama przeżywa takie kryzysy, nie jesteś sama.', title_pt = 'Foi um dia difícil? 📝', body_pt = 'Desabafe escrevendo o stress de hoje no Diário de Humor. Todas as mães passam por estas crises, não está sozinha.', title_sv = 'Har det varit en tuff dag? 📝', body_sv = 'Skriv av dig dagens stress i Humördagboken och lätta ditt hjärta. Alla mammor går igenom sådana utbrott, du är inte ensam.', title_vi = 'Hôm nay vất vả quá? 📝', body_vi = 'Hãy viết những căng thẳng hôm nay vào Nhật ký tâm trạng cho nhẹ lòng. Mẹ nào cũng trải qua những cơn khủng hoảng này, mẹ không đơn độc đâu.', title_zh = '今天很难熬？📝', body_zh = '把今天的压力写进心情日记，让心里轻松一些。每个妈妈都经历过这些崩溃，你并不孤单。' WHERE id = '015a0c8f-c960-422b-8198-6bdb85909e68' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos de imaginación 🧸', body_es = '¿Hace hablar a los coches o le da de comer a su osito? Su imaginación vuela. Anota este salto cognitivo en el Seguimiento del desarrollo y únete al juego.', title_fr = 'Jeux d''imagination 🧸', body_fr = 'Il fait parler ses voitures et donne à manger à son nounours ? Son imagination s''envole. Notez ce bond cognitif dans le Suivi de développement et joignez-vous au jeu.', title_hi = 'कल्पना वाले खेल 🧸', body_hi = 'गाड़ियों से बातें करवाता है, टेडी बियर को खाना खिलाता है? उसकी कल्पना ऊँची उड़ान भर रही है। ग्रोथ ट्रैकर में समझ की इस छलांग को दर्ज कीजिए और खेल में शामिल हो जाइए।', title_id = 'Permainan khayalan 🧸', body_id = 'Membuat mobil-mobilannya berbicara, menyuapi boneka beruangnya? Imajinasinya melambung tinggi. Catat lompatan kognitif ini di Pelacak Perkembangan dan ikutlah bermain.', title_ja = 'ごっこ遊び 🧸', body_ja = '車にお話しさせたり、くまさんにごはんをあげたりしていますか？想像力が羽ばたいています。この認知の飛躍を「発達トラッカー」に記録して、遊びに加わりましょう。', title_ko = '상상 놀이 🧸', body_ko = '자동차끼리 대화시키고 곰 인형에게 밥을 주나요? 상상력이 하늘을 찌르고 있어요. 성장 기록에 이 인지 도약을 남기고 놀이에 함께해 보세요.', title_nl = 'Fantasiespel 🧸', body_nl = 'Laat hij auto''s praten en geeft hij zijn beer eten? Zijn fantasie vliegt omhoog. Noteer deze cognitieve sprong in de Groeitracker en speel mee.', title_pl = 'Zabawy w udawanie 🧸', body_pl = 'Każe autkom rozmawiać, karmi misia? Jego wyobraźnia szybuje. Zapisz ten skok poznawczy w Śledzeniu rozwoju i dołącz do zabawy.', title_pt = 'Brincadeiras de imaginação 🧸', body_pt = 'Põe os carros a falar e dá de comer ao ursinho? A imaginação está a voar alto. Registe este salto cognitivo no Registo de Desenvolvimento e entre na brincadeira.', title_sv = 'Låtsaslekar 🧸', body_sv = 'Låter barnet bilarna prata eller matar nallen? Fantasin flödar. Anteckna detta kognitiva språng i Utvecklingsspåraren och var med i leken.', title_vi = 'Trò chơi tưởng tượng 🧸', body_vi = 'Bé cho ô tô nói chuyện, đút gấu bông ăn? Trí tưởng tượng đang bay cao. Hãy ghi bước nhảy vọt nhận thức này vào Theo dõi phát triển và cùng chơi với bé.', title_zh = '想象游戏 🧸', body_zh = '让小汽车说话，给小熊喂饭？想象力正在腾飞。把这次认知飞跃记在发育追踪里，也加入游戏吧。' WHERE id = '5229a519-68a8-4340-8bba-d14464123530' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Agobiada en casa?', body_es = 'Descubre en Lugares para mamás una cafetería con rincón de juegos infantil. Que tu peque juegue y tú tómate el café caliente.', title_fr = 'Vous vous ennuyez à la maison ?', body_fr = 'Découvrez un café avec coin jeux pour enfants dans les Lieux adaptés aux mamans. Il joue, vous buvez votre café chaud.', title_hi = 'घर में ऊब गईं?', body_hi = 'माँ के लिए अनुकूल जगहें में बच्चों के खेलने के कोने वाला कैफ़े खोजिए। वह खेले, आप गर्म-गर्म कॉफ़ी पीजिए।', title_id = 'Bosan di rumah?', body_id = 'Temukan kafe dengan sudut bermain anak di Tempat Ramah Ibu. Biarkan ia bermain, Anda nikmati kopi selagi hangat.', title_ja = '家の中で退屈？', body_ja = '「ママにやさしいスポット」でキッズスペースのあるカフェを見つけましょう。お子さんは遊び、あなたは温かいうちにコーヒーを。', title_ko = '집에서 답답했나요?', body_ko = '엄마 친화 장소에서 키즈 놀이 공간이 있는 카페를 찾아보세요. 아이는 놀고, 엄마는 커피를 따뜻할 때 마셔요.', title_nl = 'Verveel je je thuis?', body_nl = 'Ontdek in Mamavriendelijke plekken een café met speelhoek. Laat hem spelen, dan drink jij je koffie warm op.', title_pl = 'Nudzisz się w domu?', body_pl = 'Odkryj w Miejscach przyjaznych mamom kawiarnię z kącikiem zabaw dla dzieci. Niech on się bawi, a ty wypij kawę, póki gorąca.', title_pt = 'Aborreceu-se em casa?', body_pt = 'Descubra nos Locais Amigos das Mães um café com cantinho de brincar para crianças. Ele brinca e a mãe bebe o café ainda quente.', title_sv = 'Tråkigt hemma?', body_sv = 'Upptäck ett kafé med lekhörna i Mammavänliga platser. Låt barnet leka medan du dricker kaffet varmt.', title_vi = 'Mẹ thấy bí bách ở nhà?', body_vi = 'Hãy khám phá một quán cà phê có góc vui chơi trẻ em trong Địa điểm thân thiện với mẹ. Bé chơi, còn mẹ uống cà phê khi còn nóng.', title_zh = '在家闷坏了？', body_zh = '在妈妈友好场所里发现一家带儿童游乐角的咖啡馆。宝宝玩，你趁热喝咖啡。' WHERE id = 'f0d11fbf-f594-485d-b316-f567d5c6731d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma musical 🎶', body_es = 'La forma más fácil de calmar el llanto de última hora de la tarde es poner su melodía favorita, abrazarle y bailar despacito juntos.', title_fr = 'Sérénité en musique 🎶', body_fr = 'Le plus simple pour apaiser les pleurnicheries de fin de journée : mettez une mélodie qu''il aime, prenez-le dans vos bras et dansez doucement.', title_hi = 'संगीत भरा सुकून 🎶', body_hi = 'शाम को होने वाली चिड़चिड़ाहट को संभालने का सबसे आसान तरीका है उसकी पसंदीदा धुन लगाकर उसे गले लगाकर धीरे-धीरे नाचना।', title_id = 'Damai bersama musik 🎶', body_id = 'Cara termudah meredakan rewel di sore hari adalah memutar melodi favoritnya, memeluknya, lalu berdansa pelan bersamanya.', title_ja = '音楽でほっとひと息 🎶', body_ja = '夕方のぐずりをいちばん簡単に落ち着かせる方法は、好きな曲をかけて、ぎゅっと抱っこしながらゆっくり踊ることです。', title_ko = '음악과 함께 평온하게 🎶', body_ko = '저녁 무렵의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안은 채 천천히 춤추는 거예요.', title_nl = 'Muzikale rust 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsmelodie op, knuffel hem en dans samen langzaam.', title_pl = 'Muzyczny spokój 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną melodię, przytulić go i powoli razem zatańczyć.', title_pt = 'Tranquilidade com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma melodia de que ele goste, abraçá-lo e dançar devagarinho.', title_sv = 'Lugn med musik 🎶', body_sv = 'Det enklaste sättet att lösa gnälligheten framåt kvällen är att sätta på en favoritmelodi, krama barnet och dansa långsamt tillsammans.', title_vi = 'Bình yên cùng âm nhạc 🎶', body_vi = 'Cách dễ nhất để xoa dịu cơn quấy khóc lúc chiều tối là bật giai điệu bé yêu thích, ôm bé vào lòng và nhẹ nhàng nhảy cùng bé.', title_zh = '音乐中的安宁 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝喜欢的曲子，抱着宝宝慢慢跳舞。' WHERE id = 'b9ab0ee4-3e32-4c6f-9669-cbb581181150' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Os habéis quedado en casa porque el tiempo está raro?', body_es = 'Deja que Tiempo y ropa te diga al momento la temperatura que no se ve desde la ventana, y sal al parque.', title_fr = 'Vous restez à la maison parce que le temps est bizarre ?', body_fr = 'Laissez l''outil Météo et tenue vous indiquer tout de suite la température, invisible depuis la fenêtre, et filez au parc.', title_hi = 'मौसम अजीब है, इसलिए घर पर रुकी हैं?', body_hi = 'मौसम और कपड़े टूल आपको खिड़की से न दिखने वाला तापमान तुरंत बताएगा, पार्क जाइए।', title_id = 'Tetap di rumah karena cuacanya aneh?', body_id = 'Biarkan alat Cuaca dan Pakaian langsung memberi tahu suhu yang tak terlihat dari jendela, lalu pergilah ke taman.', title_ja = 'なんだか変な天気だから家にいますか？', body_ja = '窓からはわからない気温も、「天気と服装」がすぐに教えてくれます。公園へ出かけましょう。', title_ko = '날씨가 애매해서 집에만 있었나요?', body_ko = '날씨와 옷차림 도구로 창밖으로는 알 수 없는 기온을 바로 확인하고 공원으로 나가 보세요.', title_nl = 'Thuisgebleven omdat het weer raar is?', body_nl = 'Laat Weer en kleding je meteen de temperatuur vertellen die je door het raam niet ziet, en ga naar het park.', title_pl = 'Zostałyście w domu, bo pogoda jest dziwna?', body_pl = 'Niech narzędzie Pogoda i ubiór od razu powie ci, jaka jest temperatura, której nie widać przez okno. Ruszajcie do parku.', title_pt = 'Ficou em casa porque o tempo está estranho?', body_pt = 'Deixe que o Tempo e Roupa lhe diga na hora a temperatura que não se vê da janela, e vão ao parque.', title_sv = 'Har ni stannat inne för att vädret är konstigt?', body_sv = 'Låt Väder och kläder direkt berätta temperaturen du inte ser genom fönstret, och gå till parken.', title_vi = 'Thời tiết thất thường nên cả nhà ở trong nhà?', body_vi = 'Hãy để công cụ Thời tiết và trang phục cho mẹ biết ngay nhiệt độ mà nhìn qua cửa sổ không thấy được, rồi ra công viên nhé.', title_zh = '天气怪怪的，就待在家里了？', body_zh = '让天气与穿衣工具立刻告诉你窗外看不出的温度，去公园吧。' WHERE id = 'c4cbfe42-b7f8-4e4c-ad6a-198774caa2d6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Me visto yo solo 👕', body_es = 'Aunque intente ponerse los pantalones en la cabeza, no frenes sus intentos de vestirse. ¡Sus ganas de independencia están en su mejor momento! Dale tiempo y deja que pruebe.', title_fr = 'Je m''habille tout seul 👕', body_fr = 'Même s''il enfile son pantalon sur la tête, ne freinez pas ses essais pour s''habiller. Son envie d''autonomie est au sommet ! Laissez-lui du temps et laissez-le essayer.', title_hi = 'मैं खुद पहनूँगा 👕', body_hi = 'भले ही वह पैंट सिर पर डाल ले, कपड़े पहनने की उसकी कोशिशों में रुकावट मत डालिए। आत्मनिर्भरता की चाह चरम पर है! उसे समय दीजिए, आज़माने दीजिए।', title_id = 'Aku pakai baju sendiri 👕', body_id = 'Meski ia memakai celana di kepalanya, jangan halangi usahanya berpakaian. Keinginannya untuk mandiri sedang di puncak! Beri ia waktu dan biarkan ia mencoba.', title_ja = '自分で着る 👕', body_ja = 'ズボンを頭にかぶっても、着替えの挑戦をじゃましないで。自立したい気持ちが最高潮です！時間をあげて、試させてあげましょう。', title_ko = '혼자 입을래요 👕', body_ko = '바지를 머리에 쓰려고 해도 옷 입기 시도를 막지 마세요. 자립하고 싶은 마음이 최고조예요! 시간을 주고 마음껏 시도하게 해 주세요.', title_nl = 'Ik kleed me zelf aan 👕', body_nl = 'Ook al trekt hij zijn broek over zijn hoofd, houd zijn aankleedpogingen niet tegen. Zijn drang naar zelfstandigheid is op zijn hoogtepunt! Geef hem de tijd en laat hem het uitproberen.', title_pl = 'Sam się ubiorę 👕', body_pl = 'Nawet jeśli wkłada spodnie na głowę, nie przeszkadzaj mu w próbach ubierania się. Potrzeba samodzielności jest u szczytu! Daj mu czas i pozwól próbować.', title_pt = 'Eu visto-me sozinho 👕', body_pt = 'Mesmo que enfie as calças pela cabeça, não impeça as tentativas de se vestir. A vontade de independência está no auge! Dê-lhe tempo e deixe-o experimentar.', title_sv = 'Jag klär på mig själv 👕', body_sv = 'Även om barnet drar byxorna över huvudet, hindra inte försöken att klä på sig. Längtan efter självständighet är på topp! Ge barnet tid och låt hen prova.', title_vi = '"Con tự mặc!" 👕', body_vi = 'Dù bé chui đầu vào ống quần, đừng ngăn những lần tự mặc đồ của bé. Mong muốn tự lập đang ở đỉnh cao! Hãy cho bé thời gian để tự thử.', title_zh = '我要自己穿 👕', body_zh = '哪怕把裤子套到头上，也别阻止宝宝尝试穿衣服。独立的愿望正处于高峰！给宝宝时间，让宝宝去试。' WHERE id = 'ce87972f-2f28-45fe-80b3-aa0ec4116930' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Me lo sirvo yo! 🥛', body_es = '¿Quiere servirse el agua él solo y lo moja todo? Busca en Productos recomendados vasos infantiles inteligentes antiderrames que desarrollan habilidades prácticas y te facilitan la vida.', title_fr = 'Je me sers tout seul ! 🥛', body_fr = 'Il veut verser l''eau lui-même dans son verre et mouille tout ? Cherchez dans les Produits recommandés des gobelets malins anti-renversement qui développent les gestes du quotidien, et simplifiez-vous la vie.', title_hi = 'मैं खुद डालूँगा! 🥛', body_hi = 'गिलास में पानी खुद डालना चाहता है और सब गीला कर देता है? रोज़मर्रा के हुनर सिखाने वाले, पर न छलकने वाले बच्चों के स्मार्ट कप सुझाए गए प्रोडक्ट में ढूँढिए और अपना काम आसान कीजिए।', title_id = 'Aku tuang sendiri! 🥛', body_id = 'Ingin menuang air ke gelas sendiri dan membasahi semuanya? Mudahkan urusan Anda dengan mencari gelas pintar anak anti tumpah yang melatih keterampilan hidup praktis di Produk Rekomendasi.', title_ja = '自分でつぐ！🥛', body_ja = '自分でコップにお水をつぎたがって、あちこちびしょびしょに？生活の力を育てながらもこぼれにくい、子ども用のコップを「おすすめ商品」で探して、手間を減らしましょう。', title_ko = '내가 따를래! 🥛', body_ko = '컵에 물을 직접 따르겠다며 온 사방을 적시나요? 생활 기술은 키워 주면서 흘리지 않는 스마트 유아 컵을 추천 제품에서 찾아 일을 덜어 보세요.', title_nl = 'Ik schenk zelf in! 🥛', body_nl = 'Wil hij zelf water in zijn beker schenken en wordt alles nat? Zoek in Aanbevolen producten slimme, lekvrije kinderbekers die zijn praktische vaardigheden ontwikkelen en jou het werk besparen.', title_pl = 'Sam naleję! 🥛', body_pl = 'Chce sam nalewać wodę do kubka i wszystko zalewa? Poszukaj w Polecanych produktach sprytnych kubków niekapków dla dzieci, które rozwijają praktyczne umiejętności, i ułatw sobie życie.', title_pt = 'Eu sirvo sozinho! 🥛', body_pt = 'Quer servir sozinho a água no copo e molha tudo? Procure nos Produtos Recomendados copos inteligentes antientornar para crianças, que desenvolvem competências práticas da vida, e facilite a sua tarefa.', title_sv = 'Jag häller själv! 🥛', body_sv = 'Vill barnet själv hälla vatten i muggen och blöter ner allt? Leta efter smarta barnmuggar som inte spiller men utvecklar praktiska livsfärdigheter i Rekommenderade produkter och gör det enklare för dig.', title_vi = '"Con tự rót!" 🥛', body_vi = 'Bé muốn tự rót nước vào cốc và làm ướt khắp nơi? Hãy tìm những chiếc cốc thông minh chống đổ cho trẻ giúp phát triển kỹ năng sống trong Sản phẩm gợi ý để mẹ đỡ vất vả.', title_zh = '我要自己倒！🥛', body_zh = '想自己往杯子里倒水，弄得到处湿漉漉？去推荐商品找找既能培养生活技能、又不会洒的儿童智能水杯，让你轻松一点。' WHERE id = '43a750e7-aff2-4c1a-baec-6890bc56e642' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Chef en la cocina 👩‍🍳', body_es = 'Amasad juntos la masa de galletas de plátano sin azúcar de Recetas para bebé. Así desarrollará su motricidad y, divirtiéndose, se comerá con ganas lo que ha hecho él mismo.', title_fr = 'Un chef en cuisine 👩‍🍳', body_fr = 'Pétrissez ensemble une pâte à biscuits à la banane sans sucre des Recettes pour bébés. Il développe sa motricité, s''amuse et mange avec appétit le fruit de son travail.', title_hi = 'रसोई में शेफ़ 👩‍🍳', body_hi = 'बच्चों की रेसिपी से बिना चीनी वाली केले की कुकी का आटा साथ मिलकर गूँधिए। इससे उसकी मोटर स्किल्स भी बढ़ेंगी और वह मज़े-मज़े में अपनी मेहनत भी चाव से खाएगा।', title_id = 'Koki di dapur 👩‍🍳', body_id = 'Uleni adonan kue kering pisang tanpa gula dari Resep Bayi bersama-sama. Biarkan motoriknya berkembang dan ia lahap menyantap hasil karyanya sambil bersenang-senang.', title_ja = 'キッチンのシェフ 👩‍🍳', body_ja = '「離乳食を始める赤ちゃんのレシピ」から、砂糖不使用のバナナクッキーの生地を一緒にこねましょう。手先の力が育ち、楽しみながら自分でつくったものをおいしく食べられます。', title_ko = '주방의 요리사 👩‍🍳', body_ko = '아기 레시피의 설탕 없는 바나나 쿠키 반죽을 함께 주물러 보세요. 소근육도 키우고, 즐겁게 직접 만든 걸 맛있게 먹을 거예요.', title_nl = 'Kok in de keuken 👩‍🍳', body_nl = 'Kneed samen suikervrij koekjesdeeg met banaan uit Babyrecepten. Zo ontwikkelt hij zijn motoriek en eet hij met plezier en smaak wat hij zelf heeft gemaakt.', title_pl = 'Kucharz w kuchni 👩‍🍳', body_pl = 'Zagniećcie razem ciasto na bananowe ciasteczka bez cukru z Przepisów dla niemowląt. Niech rozwija motorykę, bawi się i z apetytem zje owoc swojej pracy.', title_pt = 'Chef na cozinha 👩‍🍳', body_pt = 'Amassem juntos uma massa de bolachas de banana sem açúcar das Receitas para bebés. Ele desenvolve a motricidade e, a divertir-se, come com apetite o fruto do seu trabalho.', title_sv = 'Kocken i köket 👩‍🍳', body_sv = 'Knåda sockerfri kakdeg med banan tillsammans från Recept för bebisar. Låt barnet både utveckla motoriken och ha roligt och äta sitt eget arbete med god aptit.', title_vi = 'Đầu bếp vào bếp 👩‍🍳', body_vi = 'Hãy cùng bé nhào bột bánh quy chuối không đường từ Công thức cho bé. Vừa giúp bé phát triển vận động, vừa để bé vui vẻ thưởng thức thành quả của mình.', title_zh = '小厨师进厨房 👩‍🍳', body_zh = '用宝宝食谱一起揉无糖香蕉饼干面团吧。既锻炼动作能力，又能让宝宝玩得开心、津津有味地吃上自己的劳动成果。' WHERE id = '8d131ccb-5e19-4d42-b8a6-86bf255b1f23' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y silencio 🍵', body_es = 'El temporizador se ha parado y tu peque duerme. ¡No corras a las tareas de casa! Prepárate una infusión de melisa o manzanilla de Recetas saludables, túmbate en el sofá y disfruta del silencio.', title_fr = 'Thé chaud et silence 🍵', body_fr = 'Le minuteur est arrêté, il dort. Ne vous ruez pas sur les tâches ménagères ! Préparez une tisane de mélisse ou de camomille des Recettes saines, allongez-vous sur le canapé et savourez simplement le silence.', title_hi = 'गर्म चाय और खामोशी 🍵', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के कामों की ओर मत भागिए! सेहतमंद रेसिपी से लेमन बाम या कैमोमाइल की चाय बनाइए, सोफ़े पर लेटिए और बस खामोशी का मज़ा लीजिए।', title_id = 'Teh hangat dan keheningan 🍵', body_id = 'Timer berhenti, si kecil sudah tidur. Jangan buru-buru mengerjakan pekerjaan rumah! Seduh teh lemon balm atau chamomile dari Resep Sehat, berbaring di sofa, dan nikmati keheningan.', title_ja = '温かいお茶と静けさ 🍵', body_ja = 'タイマーは止まり、お子さんは眠りました。家事に走らないで！「ヘルシーレシピ」からレモンバームかカモミールのお茶をいれて、ソファに横になり、静けさだけを味わいましょう。', title_ko = '따뜻한 차와 고요함 🍵', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일로 달려가지 마세요! 건강한 레시피에서 레몬밤이나 캐모마일 차를 우려 소파에 누워 오직 고요함만 즐기세요.', title_nl = 'Warme thee en stilte 🍵', body_nl = 'De timer is gestopt, je kindje slaapt. Ren niet naar het huishouden! Zet citroenmelisse- of kamillethee uit Gezonde recepten, ga op de bank liggen en geniet gewoon van de stilte.', title_pl = 'Ciepła herbata i cisza 🍵', body_pl = 'Timer zatrzymany, maluch śpi. Nie rzucaj się w wir obowiązków! Zaparz melisę lub rumianek ze Zdrowych przepisów, połóż się na kanapie i po prostu delektuj się ciszą.', title_pt = 'Chá quente e silêncio 🍵', body_pt = 'O temporizador parou, ele adormeceu. Não corra para as tarefas da casa! Prepare um chá de erva-cidreira ou de camomila das Receitas Saudáveis, deite-se no sofá e saboreie apenas o silêncio.', title_sv = 'Varmt te och tystnad 🍵', body_sv = 'Timern har stannat, barnet sover. Rusa inte till hushållssysslorna! Brygg citronmelisse- eller kamomillte från Hälsosamma recept, lägg dig på soffan och njut bara av tystnaden.', title_vi = 'Trà nóng và sự yên tĩnh 🍵', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Đừng vội lao vào việc nhà! Hãy pha trà tía tô đất hoặc hoa cúc từ Công thức lành mạnh, nằm dài trên sofa và tận hưởng sự yên tĩnh.', title_zh = '热茶与安静 🍵', body_zh = '计时器停了，孩子睡着了。别急着去做家务！从健康食谱里泡一杯香蜂草或洋甘菊茶，躺在沙发上，好好享受这份安静。' WHERE id = 'bd7400ff-b3f7-4318-9c68-166242aa98f9' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Lo tuyo es mío! 🧸', body_es = '¿En el parque no quiere devolver el juguete de otro niño? Es la etapa del egocentrismo. Enséñale a compartir con turnos, no a la fuerza.', title_fr = 'Ce qui est à toi est à moi ! 🧸', body_fr = 'Au parc, il ne veut pas rendre le jouet d''un autre enfant ? C''est la période égocentrique. Apprenez-lui à partager non pas de force, mais chacun son tour.', title_hi = 'तुम्हारा भी मेरा है! 🧸', body_hi = 'पार्क में किसी दूसरे का खिलौना वापस नहीं देना चाहता? यह ''मैं ही सब कुछ'' वाला दौर है। बाँटना ज़बरदस्ती से नहीं, बारी लगाकर सिखाइए।', title_id = 'Punyamu juga punyaku! 🧸', body_id = 'Tidak mau memberikan mainan anak lain di taman? Ini masa egosentris. Ajarkan berbagi dengan bergiliran, bukan dengan paksaan.', title_ja = 'あなたのは、ぼくの！🧸', body_ja = '公園でほかの子のおもちゃを返したがらない？自己中心的な時期です。無理に貸させるのではなく、順番にすることで分け合うことを教えましょう。', title_ko = '네 것도 내 거야! 🧸', body_ko = '공원에서 장난감을 내주지 않으려 하나요? 자기중심적인 시기예요. 억지로 나누게 하기보다 차례를 정해 나누는 법을 가르쳐 주세요.', title_nl = 'Geef het hier, het is van mij! 🧸', body_nl = 'Wil hij het speelgoed van een ander kind in het park niet teruggeven? Het is de fase van egocentrisme. Leer hem delen door om de beurt te spelen, niet door te dwingen.', title_pl = 'Twoje jest moje! 🧸', body_pl = 'W parku nie chce oddać cudzej zabawki? To okres egocentryzmu. Ucz dzielenia się nie na siłę, tylko wprowadzając kolejkę.', title_pt = 'O que é teu é meu! 🧸', body_pt = 'No parque não quer devolver o brinquedo de outra criança? É a fase do egocentrismo. Ensine a partilhar não à força, mas brincando à vez.', title_sv = 'Ge hit, den är min! 🧸', body_sv = 'Vill barnet inte ge tillbaka ett annat barns leksak i parken? Det är egocentrismens period. Lär barnet att dela genom att turas om, inte med tvång.', title_vi = '"Của bạn cũng là của con!" 🧸', body_vi = 'Ở công viên bé không muốn trả đồ chơi cho bạn? Đây là giai đoạn vị kỷ. Hãy dạy bé chia sẻ bằng cách chơi lần lượt chứ đừng ép buộc.', title_zh = '你的给我，我的还是我的！🧸', body_zh = '在公园不肯把别人的玩具还回去？这是自我中心阶段。别强迫分享，用排队轮流的方式来教吧。' WHERE id = '65e69d4e-9f8b-4e23-8934-10178d918f6b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ratón de biblioteca 📖', body_es = '¿Te trae su libro de cuentos favorito y te hace leer la misma página una y otra vez? La repetición es su forma de aprender. Vuelve a leerla con paciencia.', title_fr = 'Petit rat de bibliothèque 📖', body_fr = 'Il apporte son livre préféré et vous fait relire la même page encore et encore ? La répétition, c''est sa façon d''apprendre. Relisez avec patience.', title_hi = 'किताबी कीड़ा 📖', body_hi = 'अपनी सबसे पसंदीदा कहानी की किताब लाकर बार-बार वही पन्ना पढ़वाता है? दोहराना ही उसके सीखने का तरीका है। धैर्य से फिर पढ़िए।', title_id = 'Kutu Buku 📖', body_id = 'Membawa buku dongeng favoritnya dan minta halaman yang sama dibacakan berulang kali? Pengulangan adalah cara ia belajar. Bacakan lagi dengan sabar.', title_ja = '本の虫 📖', body_ja = 'お気に入りの絵本を持ってきて、同じページを何度も読ませますか？繰り返しは、お子さんの学び方です。気長にもう一度読んであげましょう。', title_ko = '꼬마 책벌레 📖', body_ko = '가장 좋아하는 동화책을 가져와 같은 페이지를 몇 번이고 읽어 달라고 하나요? 반복은 아이가 배우는 방법이에요. 인내심을 갖고 다시 읽어 주세요.', title_nl = 'Boekenwurm 📖', body_nl = 'Haalt hij zijn lievelingsboek en laat hij je steeds dezelfde bladzijde voorlezen? Herhaling is zijn manier van leren. Lees het geduldig nog een keer.', title_pl = 'Mól książkowy 📖', body_pl = 'Przynosi ulubioną książeczkę i każe ci czytać w kółko tę samą stronę? Powtarzanie to jego sposób nauki. Cierpliwie przeczytaj jeszcze raz.', title_pt = 'Rato de biblioteca 📖', body_pt = 'Traz o seu livro de histórias preferido e pede-lhe para ler a mesma página vezes sem conta? Repetir é a forma dele de aprender. Volte a ler com paciência.', title_sv = 'Bokmal 📖', body_sv = 'Hämtar barnet sin favoritsagobok och låter dig läsa samma sida om och om igen? Upprepning är barnets sätt att lära sig. Läs igen med tålamod.', title_vi = 'Mọt sách nhí 📖', body_vi = 'Bé mang cuốn truyện yêu thích đến và bắt mẹ đọc đi đọc lại một trang? Lặp lại là cách học của bé. Hãy kiên nhẫn đọc lại nhé.', title_zh = '小书虫 📖', body_zh = '拿来最爱的故事书，让你一遍遍读同一页？重复就是宝宝的学习方式。耐心地再读一遍吧。' WHERE id = '71700719-be0c-45bf-8d93-6cb51d48ed2d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿El suelo está sin fregar? Que espere. Una casa sucia se arregla, pero una madre agotada tarda mucho en recuperarse. Túmbate en el sofá y escucha la calma.', body_fr = 'Le sol n''est pas lavé ? Tant pis. Une maison sale se range, mais une maman épuisée met longtemps à se remettre. Allongez-vous sur le canapé et savourez le calme.', body_hi = 'फ़र्श पोंछा नहीं गया? रहने दीजिए। गंदा घर ठीक हो जाता है, पर थकी हुई माँ को सँभलने में लंबा समय लगता है। सोफ़े पर लेटिए और सुकून को सुनिए।', body_id = 'Lantai belum dipel? Biarkan saja. Rumah yang kotor bisa dibereskan, tapi ibu yang kelelahan butuh waktu lama untuk pulih. Berbaringlah di sofa dan nikmati ketenangan.', body_ja = '床の拭き掃除がまだ？そのままでいいんです。散らかった家はいつでも片付きますが、燃え尽きたママの回復には時間がかかります。ソファに横になって、穏やかな時間に耳を傾けましょう。', body_ko = '바닥을 못 닦았나요? 그냥 두세요. 지저분한 집은 금방 치울 수 있지만, 지친 엄마가 회복하는 데는 오래 걸려요. 소파에 누워 평온함을 느껴 보세요.', body_nl = 'Is de vloer niet gedweild? Laat maar zitten. Een vies huis wordt weer schoon, maar een uitgeputte moeder heeft lang nodig om te herstellen. Ga op de bank liggen en luister naar de rust.', body_pl = 'Podłoga nieumyta? Niech zostanie. Brudny dom da się posprzątać, ale wyczerpana mama długo dochodzi do siebie. Połóż się na kanapie i wsłuchaj w spokój.', body_pt = 'O chão ficou por limpar? Deixe estar. Uma casa suja arruma-se, mas uma mãe esgotada demora muito a recuperar. Deite-se no sofá e escute a tranquilidade.', body_sv = 'Är golvet inte torkat? Låt det vara. Ett smutsigt hem blir rent igen, men en utmattad mamma tar lång tid att återhämta sig. Lägg dig på soffan och lyssna på lugnet.', body_vi = 'Sàn nhà chưa lau? Cứ để đó. Nhà bẩn thì dọn được, nhưng người mẹ kiệt sức thì cần rất lâu để hồi phục. Hãy nằm trên sofa và lắng nghe sự bình yên.', body_zh = '地板还没拖？那就先放着吧。脏了的家可以收拾，但累垮的妈妈需要很久才能恢复。躺到沙发上，听听这份宁静。' WHERE id = 'd6aaa644-5d8a-47cd-b998-227fc0b6f04b' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té imaginario 🫖', body_es = '¿Os obliga a ti y a sus juguetes a tomar té en tazas imaginarias? ¡Los juegos de rol son el punto álgido del desarrollo de la inteligencia!', title_fr = 'Dînette imaginaire 🫖', body_fr = 'Il vous oblige, vous et ses jouets, à boire du thé dans des tasses imaginaires ? Les jeux de rôle sont le sommet du développement de l''intelligence !', title_hi = 'काल्पनिक चाय पार्टी 🫖', body_hi = 'आपको या अपने खिलौनों को काल्पनिक कप से चाय पीने पर मजबूर करता है? रोल प्ले बुद्धि के विकास का चरम है!', title_id = 'Pesta teh khayalan 🫖', body_id = 'Memaksa Anda atau mainannya minum teh dari cangkir khayalan? Permainan peran adalah puncak perkembangan kecerdasan!', title_ja = '想像のティーパーティー 🫖', body_ja = 'あなたやおもちゃに、想像のカップでお茶を飲ませますか？ごっこ遊びは知性の発達のピークです！', title_ko = '상상 속 티타임 🫖', body_ko = '엄마나 인형에게 상상 속 컵으로 차를 마시라고 하나요? 역할 놀이는 두뇌 발달이 최고조라는 신호예요!', title_nl = 'Denkbeeldige theepartij 🫖', body_nl = 'Laat hij jou of zijn knuffels thee drinken uit denkbeeldige kopjes? Rollenspel is het hoogtepunt van zijn verstandelijke ontwikkeling!', title_pl = 'Wyimaginowane przyjęcie herbaciane 🫖', body_pl = 'Każe tobie albo zabawkom pić herbatę z wyimaginowanych filiżanek? Zabawy w role to szczyt rozwoju umysłu!', title_pt = 'Um chá imaginário 🫖', body_pt = 'Obriga-a a si ou aos brinquedos a beber chá em chávenas imaginárias? Os jogos de papéis são o auge do desenvolvimento da inteligência!', title_sv = 'Låtsaste 🫖', body_sv = 'Låter barnet dig eller leksakerna dricka te ur låtsaskoppar? Rollekar är tankeutvecklingens höjdpunkt!', title_vi = 'Tiệc trà tưởng tượng 🫖', body_vi = 'Bé bắt mẹ hoặc đồ chơi uống trà bằng những chiếc tách tưởng tượng? Trò chơi nhập vai là đỉnh cao của sự phát triển trí tuệ!', title_zh = '假装的茶会 🫖', body_zh = '让你或玩具们用想象的杯子喝茶？角色扮演游戏是智力发展的巅峰！' WHERE id = '04312503-34be-494a-8896-38312d406a86' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dolor de cuello de mamá 🧘‍♀️', body_es = '¿Tienes el cuello y la espalda agarrotados de jugar en el suelo y coger a tu peque? Prepárate un té verde con jengibre antiinflamatorio que relaja los músculos de Recetas saludables y descansa.', title_fr = 'Les douleurs de nuque de maman 🧘‍♀️', body_fr = 'Votre nuque et votre dos sont raides à force de jouer par terre et de le porter ? Reposez-vous avec un thé vert au gingembre anti-inflammatoire qui détend les muscles, des Recettes saines.', title_hi = 'माँ की गर्दन का दर्द 🧘‍♀️', body_hi = 'ज़मीन पर खेलने और बच्चे को उठाने से गर्दन और कमर अकड़ गई है? सेहतमंद रेसिपी से मांसपेशियों को आराम देने वाली, सूजन कम करने वाली अदरक वाली ग्रीन टी बनाइए और आराम कीजिए।', title_id = 'Leher pegal Bunda 🧘‍♀️', body_id = 'Leher dan punggung kaku karena bermain di lantai dan menggendong si kecil? Seduh teh hijau jahe antiradang yang merilekskan otot dari Resep Sehat, lalu beristirahatlah.', title_ja = 'ママの首の痛み 🧘‍♀️', body_ja = '床で遊んだり、お子さんを抱き上げたりして、首や腰がこわばっていますか？「ヘルシーレシピ」から、筋肉をほぐし炎症をおさえるしょうが入り緑茶をいれて、休みましょう。', title_ko = '엄마의 목 통증 🧘‍♀️', body_ko = '바닥에서 놀아 주고 아이를 안아 올리느라 목과 허리가 뻣뻣해졌나요? 건강한 레시피에서 근육을 풀어 주고 염증을 줄이는 생강 녹차를 우려 쉬세요.', title_nl = 'Nekpijn van mama 🧘‍♀️', body_nl = 'Zitten je nek en rug vast van het spelen op de grond en het tillen? Zet ontstekingsremmende groene thee met gember uit Gezonde recepten die je spieren ontspant, en rust uit.', title_pl = 'Ból karku mamy 🧘‍♀️', body_pl = 'Kark i plecy zesztywniały ci od zabawy na podłodze i podnoszenia malucha? Zaparz ze Zdrowych przepisów przeciwzapalną, rozluźniającą mięśnie zieloną herbatę z imbirem i odpocznij.', title_pt = 'As dores no pescoço da mãe 🧘‍♀️', body_pt = 'O pescoço e as costas ficaram presos de brincar no chão e de pegar nele ao colo? Prepare um chá verde com gengibre das Receitas Saudáveis, anti-inflamatório e que relaxa os músculos, e descanse.', title_sv = 'Mammas nackvärk 🧘‍♀️', body_sv = 'Har nacken och ryggen låst sig av att leka på golvet och lyfta barnet? Brygg ett antiinflammatoriskt grönt te med ingefära som får musklerna att slappna av från Hälsosamma recept och vila.', title_vi = 'Mẹ bị đau cổ 🧘‍♀️', body_vi = 'Chơi dưới sàn và bế bé khiến cổ, lưng mẹ cứng đờ? Hãy pha trà xanh gừng chống viêm, giúp thư giãn cơ từ Công thức lành mạnh và nghỉ ngơi.', title_zh = '妈妈的脖子疼 🧘‍♀️', body_zh = '在地上陪玩、抱孩子，弄得脖子和腰都僵了？从健康食谱里泡一杯放松肌肉、抗炎的姜味绿茶，休息一下吧。' WHERE id = '149beadc-5c37-404b-8b3e-f6ce437629da' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿El monstruo debajo de la cama? 👾', body_es = 'A medida que se desarrolla la imaginación, los miedos se vuelven reales. Si le asustan las sombras, baja las luces y pon el sonido del vientre materno (latido del corazón) de Ruido blanco para devolverle aquella sensación de seguridad perfecta.', title_fr = 'Un monstre sous le lit ? 👾', body_fr = 'Quand l''imagination grandit, les peurs deviennent bien réelles. S''il a peur des ombres, baissez les lumières et lancez le son du ventre maternel (battements de cœur) des Bruits blancs pour lui rendre ce sentiment de sécurité parfait d''autrefois.', title_hi = 'बिस्तर के नीचे राक्षस? 👾', body_hi = 'कल्पना बढ़ने के साथ डर भी असली लगने लगते हैं। अगर परछाइयों से डरता है, तो बत्तियाँ धीमी कीजिए और व्हाइट नॉइज़ में गर्भ की आवाज़ (दिल की धड़कन) चलाकर उसे वही पुराना, पूरा सुरक्षा का एहसास दीजिए।', title_id = 'Monster di bawah tempat tidur? 👾', body_id = 'Seiring berkembangnya imajinasi, rasa takut pun terasa nyata. Jika ia takut bayangan, redupkan lampu dan putar suara rahim (detak jantung) dari Suara Putih untuk memberinya rasa aman yang akrab dan sempurna.', title_ja = 'ベッドの下におばけ？👾', body_ja = '想像力が育つにつれて、こわさも本物のように感じられます。影をこわがるなら、照明を落として、「ホワイトノイズ」の胎内の音（心臓の音）を流し、なつかしい完璧な安心感を届けましょう。', title_ko = '침대 밑 괴물? 👾', body_ko = '상상력이 자라면 두려움도 진짜처럼 느껴져요. 그림자를 무서워한다면 불을 낮추고 백색소음에서 엄마 배 속 소리(심장 박동)를 틀어 익숙하고 완벽한 안정감을 선물하세요.', title_nl = 'Een monster onder het bed? 👾', body_nl = 'Naarmate de fantasie groeit, worden angsten echt. Is hij bang voor schaduwen, dim dan het licht en zet het baarmoedergeluid (hartslag) uit Witte ruis aan om hem dat oude, perfecte gevoel van veiligheid te geven.', title_pl = 'Potwór pod łóżkiem? 👾', body_pl = 'Wraz z rozwojem wyobraźni lęki stają się prawdziwe. Jeśli boi się cieni, przygaś światło i włącz w Białym szumie odgłosy z brzucha mamy (bicie serca), by dać mu znajome, doskonałe poczucie bezpieczeństwa.', title_pt = 'O monstro debaixo da cama? 👾', body_pt = 'À medida que a imaginação se desenvolve, os medos tornam-se reais. Se tem medo das sombras, baixe as luzes e ligue no Ruído Branco o som do útero materno (batimento cardíaco) para lhe dar aquela antiga e perfeita sensação de segurança.', title_sv = 'Monstret under sängen? 👾', body_sv = 'När fantasin utvecklas blir rädslorna verkliga. Är barnet rädd för skuggor, dämpa ljuset och sätt på ljudet från livmodern (hjärtslag) i Vitt brus för att ge den gamla, perfekta känslan av trygghet.', title_vi = 'Quái vật dưới gầm giường? 👾', body_vi = 'Trí tưởng tượng càng phát triển, nỗi sợ càng trở nên chân thực. Nếu bé sợ những cái bóng, hãy giảm ánh sáng và bật âm thanh trong bụng mẹ (tiếng tim đập) trong Tiếng ồn trắng để mang lại cảm giác an toàn trọn vẹn quen thuộc.', title_zh = '床底下的怪兽？👾', body_zh = '随着想象力发展，恐惧也变得真实起来。如果宝宝怕影子，就把灯光调暗，打开白噪音里的子宫声（心跳声），给宝宝熟悉而完美的安全感。' WHERE id = '2daba5bf-3da2-43ab-bc87-fdc726c1aabb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pelea por el turno en el tobogán 🛑', body_es = '¿En el parque no quiere esperar a los demás niños? Lee sin falta en los artículos sobre socialización del Blog cómo inculcar el sentido del turno y la paciencia hacia los 2,5 años.', title_fr = 'Dispute pour le toboggan 🛑', body_fr = 'Au parc, il ne veut pas attendre les autres enfants ? Lisez absolument les articles sur la socialisation de la rubrique Blogs pour lui apprendre à attendre son tour et à patienter vers 2 ans et demi.', title_hi = 'स्लाइड पर बारी का झगड़ा 🛑', body_hi = 'पार्क में दूसरे बच्चों का इंतज़ार नहीं करना चाहता? 2.5 साल के करीब बारी और सब्र की समझ कैसे सिखाएँ, यह ब्लॉग सेक्शन के मेल-जोल वाले लेखों में ज़रूर पढ़िए।', title_id = 'Rebutan giliran di perosotan 🛑', body_id = 'Tidak mau menunggu anak lain di taman? Pastikan membaca artikel sosialisasi di bagian Blog tentang cara menanamkan konsep bergiliran dan sabar menjelang usia 2,5 tahun.', title_ja = 'すべり台の順番争い 🛑', body_ja = '公園でほかの子を待ちたがらない？2歳半に向けて「順番」と「がまん」をどう教えるか、ブログの社会性に関する記事をぜひ読んでみましょう。', title_ko = '미끄럼틀 차례 싸움 🛑', body_ko = '공원에서 다른 아이들을 기다리기 싫어하나요? 두 돌 반 무렵 차례와 기다림을 가르치는 방법을 블로그의 사회성 관련 글에서 꼭 읽어 보세요.', title_nl = 'Ruzie om de beurt op de glijbaan 🛑', body_nl = 'Wil hij in het park niet op andere kinderen wachten? Lees zeker de artikelen over socialisatie in Blogs over hoe je rond 2,5 jaar om de beurt gaan en geduld aanleert.', title_pl = 'Kłótnia o kolejkę na zjeżdżalni 🛑', body_pl = 'W parku nie chce czekać na inne dzieci? Koniecznie przeczytaj w artykułach o uspołecznieniu w sekcji Blog, jak w okolicach 2,5 roku uczyć czekania na swoją kolej i cierpliwości.', title_pt = 'A guerra da vez no escorrega 🛑', body_pt = 'No parque não quer esperar pelas outras crianças? Leia sem falta nos artigos de socialização dos Blogues como incutir, perto dos 2,5 anos, as noções de vez e paciência.', title_sv = 'Bråk om turen i rutschkanan 🛑', body_sv = 'Vill barnet inte vänta på de andra barnen i parken? Läs artiklarna om socialt samspel i Bloggar om hur du lär ut begreppen tur och tålamod mot 2,5 års ålder.', title_vi = 'Tranh nhau cầu trượt 🛑', body_vi = 'Ở công viên bé không muốn chờ các bạn? Nhất định hãy đọc các bài viết về hòa nhập xã hội trong mục Blog về cách dạy trẻ gần 2,5 tuổi biết chờ lượt và kiên nhẫn.', title_zh = '滑梯前的排队之争 🛑', body_zh = '在公园不愿意等其他小朋友？一定要读读博客板块里的社交文章，了解如何教快2.5岁的宝宝学会轮流和耐心。' WHERE id = 'd0a47f18-7e98-462c-be4f-167fcf918411' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Hoy la tozudez te ha hecho perder los nervios y has levantado la voz? Vuelca tus agobios en el Diario de ánimo. ¡No eres un robot, no tienes por qué ser perfecta!', body_fr = 'Son entêtement vous a fait perdre patience et hausser le ton aujourd''hui ? Confiez vos tensions au Journal d''humeur. Vous n''êtes pas un robot, vous n''êtes pas obligée d''être parfaite !', body_hi = 'आज ज़िदों ने आपका सब्र तोड़ दिया और आवाज़ ऊँची हो गई? मूड डायरी में मन की घुटन लिखिए। आप रोबोट नहीं हैं, परफ़ेक्ट होना आपकी मजबूरी नहीं है!', body_id = 'Hari ini sikap keras kepalanya membuat Anda hilang sabar dan suara Anda meninggi? Curahkan beban hati di Buku Harian Suasana Hati. Anda bukan robot, Anda tidak harus sempurna!', body_ja = '今日はこだわりに手を焼いて、つい声を荒らげてしまいましたか？「気分日記」に心のもやもやを書き出しましょう。あなたはロボットではありません。完璧でなくていいんです！', body_ko = '오늘 고집 때문에 인내심이 바닥나 목소리가 커졌나요? 기분 일기에 속상한 마음을 털어놓으세요. 엄마는 로봇이 아니에요. 완벽할 필요는 없어요!', body_nl = 'Werd je vandaag zo moe van zijn koppigheid dat je je stem verhief? Schrijf je zorgen van je af in je Stemmingsdagboek. Je bent geen robot, je hoeft niet perfect te zijn!', body_pl = 'Dziś upór wyprowadził cię z równowagi i podniosłaś głos? Wylej swoje troski w Dzienniku nastroju. Nie jesteś robotem i nie musisz być idealna!', body_pt = 'Hoje as teimosias tiraram-na do sério e levantou a voz? Deixe sair as suas angústias no Diário de Humor. Não é um robô, não tem de ser perfeita!', body_sv = 'Fick envisheten dig att tappa tålamodet i dag och höja rösten? Skriv av dig det som tynger dig i Humördagboken. Du är ingen robot, du måste inte vara perfekt!', body_vi = 'Hôm nay sự bướng bỉnh khiến mẹ mất kiên nhẫn và lỡ to tiếng? Hãy trút nỗi niềm vào Nhật ký tâm trạng. Mẹ không phải là robot, mẹ không cần phải hoàn hảo!', body_zh = '今天的倔强让你失去耐心，提高了嗓门？把心里的烦闷倒进心情日记。你不是机器人，没有必要做到完美！' WHERE id = 'dc66703c-31b3-4677-a6cd-dc09bb5b60cf' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡La moda del revés! 👕', body_es = '¿Se ha puesto los pantalones del revés y los zapatos cambiados, y no se los quiere quitar? ¡No interfieras en este divertido intento de independencia!', title_fr = 'La mode à l''envers ! 👕', body_fr = 'Pantalon à l''envers, chaussures au mauvais pied, et il refuse de les enlever ? N''intervenez pas dans cet essai d''autonomie rigolo !', title_hi = 'उल्टा पहनने का फ़ैशन! 👕', body_hi = 'पैंट उल्टी और जूते गलत पैरों में पहन लिए और उतारना नहीं चाहता? आत्मनिर्भरता की इस मज़ेदार कोशिश में दखल मत दीजिए!', title_id = 'Mode pakaian terbalik! 👕', body_id = 'Memakai celana terbalik, sepatu di kaki yang salah, dan tak mau melepasnya? Jangan ikut campur dalam usaha mandiri yang lucu ini!', title_ja = '裏返しファッション！👕', body_ja = 'ズボンを前後逆に、靴を左右逆にはいて、脱ぎたがらない？このおもしろい自立の挑戦には口を出さないで！', title_ko = '거꾸로 입기 패션! 👕', body_ko = '바지를 거꾸로, 신발을 좌우 바꿔 신고는 벗지 않겠다고 하나요? 이 웃긴 자립 시도에 끼어들지 마세요!', title_nl = 'Binnenstebuiten is mode! 👕', body_nl = 'Heeft hij zijn broek achterstevoren en zijn schoenen aan de verkeerde voet en wil hij ze niet uitdoen? Bemoei je niet met deze grappige poging tot zelfstandigheid!', title_pl = 'Moda na odwrót! 👕', body_pl = 'Założył spodnie na lewą stronę, a buty na złe nogi i nie chce ich zdjąć? Nie przeszkadzaj w tej zabawnej próbie samodzielności!', title_pt = 'A moda de vestir ao contrário! 👕', body_pt = 'Vestiu as calças ao contrário, calçou os sapatos trocados e não os quer tirar? Não interfira nesta tentativa divertida de independência!', title_sv = 'Bak och fram är på modet! 👕', body_sv = 'Har barnet tagit på sig byxorna bak och fram och skorna på fel fot och vill inte ta av dem? Lägg dig inte i detta roliga försök till självständighet!', title_vi = 'Mốt mặc đồ ngược! 👕', body_vi = 'Bé mặc quần ngược, đi giày nhầm chân và không chịu cởi ra? Đừng can thiệp vào nỗ lực tự lập hài hước này nhé!', title_zh = '反穿时尚！👕', body_zh = '裤子穿反了，鞋子也穿错了脚，还不肯脱？别干涉这个搞笑的独立尝试！' WHERE id = 'f9ec5212-0b50-47f7-b50f-84f41a8701a2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Rebelión contra la siesta! ⏱️', body_es = '¿Hoy no ha querido dormir la siesta y ahora está agotado? Mira el gráfico del temporizador de sueño y adelanta la rutina de la noche al menos 40 minutos para prevenir los terrores nocturnos.', title_fr = 'Révolte contre la sieste ! ⏱️', body_fr = 'Il a refusé la sieste et il est maintenant trop fatigué ? Regardez le graphique du minuteur de sommeil et avancez le rituel du soir d''au moins 40 minutes pour prévenir les terreurs nocturnes.', title_hi = 'दिन की नींद से बगावत! ⏱️', body_hi = 'दोपहर में सोने से मना कर दिया और अब ज़रूरत से ज़्यादा थका है? स्लीप टाइमर का चार्ट देखिए और शाम का रूटीन कम से कम 40 मिनट जल्दी करके नाइट टेरर से बचिए।', title_id = 'Memberontak saat tidur siang! ⏱️', body_id = 'Menolak tidur siang dan sekarang terlalu lelah? Lihat grafik Timer Tidur dan majukan rutinitas malamnya minimal 40 menit untuk mencegah teror malam.', title_ja = 'お昼寝への反乱！⏱️', body_ja = 'お昼寝を嫌がって、今は疲れすぎていますか？睡眠タイマーのグラフを見て、夜の生活リズムを少なくとも40分早めて、夜驚症を防ぎましょう。', title_ko = '낮잠 반란! ⏱️', body_ko = '낮잠을 거부해서 지금 너무 피곤해하나요? 수면 타이머 그래프를 보고 저녁 일과를 최소 40분 앞당겨 야경증을 예방하세요.', title_nl = 'Opstand tegen het middagdutje! ⏱️', body_nl = 'Weigerde hij zijn middagdutje en is hij nu oververmoeid? Bekijk de grafiek van de Slaaptimer en vervroeg het avondritme met minstens 40 minuten om nachtangst te voorkomen.', title_pl = 'Bunt przeciw drzemce! ⏱️', body_pl = 'Odmówił popołudniowej drzemki i teraz jest przemęczony? Spójrz na wykres timera snu i przesuń wieczorny rytm co najmniej o 40 minut wcześniej, by zapobiec lękom nocnym.', title_pt = 'Revolta contra a sesta! ⏱️', body_pt = 'Recusou a sesta e agora está cansado demais? Veja o gráfico do temporizador de sono e antecipe a rotina da noite pelo menos 40 minutos para prevenir os terrores noturnos.', title_sv = 'Uppror mot dagsömnen! ⏱️', body_sv = 'Vägrade barnet sova middag och är nu övertrött? Titta på grafen i sömntimern och tidigarelägg kvällsrutinen med minst 40 minuter för att förebygga nattskräck.', title_vi = 'Nổi loạn với giấc ngủ ngày! ⏱️', body_vi = 'Bé không chịu ngủ trưa và giờ thì quá mệt? Hãy xem biểu đồ của Bộ hẹn giờ ngủ và cho bé đi ngủ tối sớm hơn ít nhất 40 phút để phòng ngừa hoảng sợ ban đêm.', title_zh = '反抗午睡！⏱️', body_zh = '不肯睡午觉，现在累过头了？看看睡眠计时器的图表，把晚上的作息至少提前40分钟，预防夜惊。' WHERE id = '36818534-e1f7-451b-9f88-51bf852bc139' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se aguanta la caca? 💩', body_es = '¿Justo antes de dejar el pañal se aguanta la caca de pie? Esto puede provocar estreñimiento psicológico. Anótalo en el Seguimiento de pañales y añade enseguida albaricoques o avena al menú.', title_fr = 'Il se retient ? 💩', body_fr = 'À l''approche de l''apprentissage du pot, il se retient debout de faire caca ? Cela peut provoquer une constipation psychologique. Notez-le dans le Suivi des couches et ajoutez tout de suite des abricots ou de l''avoine à son menu.', title_hi = 'पॉटी रोकता है? 💩', body_hi = 'पॉटी ट्रेनिंग के आसपास खड़े होकर पॉटी रोक लेता है? इससे मनोवैज्ञानिक कब्ज़ हो सकता है। डायपर ट्रैकर में इसे दर्ज कीजिए और तुरंत मेन्यू में खुबानी या ओट्स जोड़िए।', title_id = 'Menahan BAB? 💩', body_id = 'Menjelang latihan pispot, ia berdiri dan menahan BAB? Ini bisa menyebabkan sembelit psikologis. Catat di Pelacak Popok dan segera tambahkan aprikot atau oat ke menunya.', title_ja = 'うんちをがまんする？💩', body_ja = 'トイレトレーニングを始めるころ、立ったままうんちをがまんしますか？これは心理的な便秘につながることがあります。「おむつトラッカー」に記録して、すぐにメニューにあんずやオートミールを加えましょう。', title_ko = '응가를 참나요? 💩', body_ko = '배변 훈련을 앞두고 선 채로 응가를 참나요? 심리적인 변비로 이어질 수 있어요. 기저귀 기록에 남기고 식단에 살구나 귀리를 바로 추가하세요.', title_nl = 'Houdt hij zijn ontlasting op? 💩', body_nl = 'Houdt hij vlak voor de zindelijkheidstraining staand zijn poep op? Dat kan psychologische verstopping veroorzaken. Noteer het in de Luiertracker en voeg meteen abrikozen of havermout toe aan het menu.', title_pl = 'Wstrzymuje kupkę? 💩', body_pl = 'Tuż przed nauką korzystania z nocnika wstrzymuje kupkę na stojąco? To może wywołać zaparcia na tle psychologicznym. Zapisz to w narzędziu do śledzenia pieluszek i od razu dodaj do menu morele lub płatki owsiane.', title_pt = 'Está a reter as fezes? 💩', body_pt = 'Antes de começar o treino do bacio, fica de pé e retém o cocó? Isto pode causar prisão de ventre psicológica. Registe-o no Registo de Fraldas e acrescente já alperce ou aveia à ementa.', title_sv = 'Håller in bajset? 💩', body_sv = 'Håller barnet in bajset stående inför pottträningen? Det kan leda till psykologisk förstoppning. Anteckna det i Blöjkollen och lägg direkt till aprikoser eller havre i menyn.', title_vi = 'Bé nhịn đi ngoài? 💩', body_vi = 'Sắp tập ngồi bô mà bé đứng nhịn không đi ngoài? Điều này có thể gây táo bón do tâm lý. Hãy ghi lại trong Theo dõi tã và thêm ngay mơ hoặc yến mạch vào thực đơn.', title_zh = '憋着不拉？💩', body_zh = '快开始如厕训练了，却站着憋住不拉？这可能导致心理性便秘。记在尿布记录里，马上在菜单里加入杏干或燕麦。' WHERE id = '54668cb8-852a-467f-9492-c88f3b1ba329' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las cuatro paredes le agobian 🌳', body_es = '¿En casa no consigue gastar energía y lo tira todo? Abre el mapa de Lugares para mamás, busca un parque seguro con suelo blando y toboganes, y déjale jugar a su aire al aire libre.', title_fr = 'Il étouffe entre quatre murs 🌳', body_fr = 'Il ne peut pas se dépenser à la maison et lance tout ? Ouvrez la carte des Lieux adaptés aux mamans, trouvez un parc sûr avec sol souple et toboggan, et laissez-le libre au grand air.', title_hi = 'चार दीवारें उसे घुटन देती हैं 🌳', body_hi = 'घर के अंदर ऊर्जा नहीं निकाल पाता और सब कुछ घुमाकर फेंकता है? माँ के लिए अनुकूल जगहें का नक्शा खोलिए, नरम ज़मीन और स्लाइड वाला सुरक्षित पार्क ढूँढिए और उसे खुली हवा में खुलकर खेलने दीजिए।', title_id = 'Empat dinding terasa sesak 🌳', body_id = 'Tak bisa menyalurkan energi di dalam rumah dan melempar segala sesuatu? Buka peta Tempat Ramah Ibu, temukan taman aman dengan alas lembut dan perosotan, dan biarkan ia bebas di udara terbuka.', title_ja = '4つの壁では窮屈 🌳', body_ja = '家の中でエネルギーを発散できず、なんでも投げていますか？「ママにやさしいスポット」のマップを開いて、やわらかい地面とすべり台のある安全な公園を見つけ、外で思いきり遊ばせてあげましょう。', title_ko = '네 벽이 답답해요 🌳', body_ko = '집 안에서 에너지를 다 쓰지 못해 뭐든 휘둘러 던지나요? 엄마 친화 장소 지도를 열어 바닥이 푹신하고 미끄럼틀이 있는 안전한 공원을 찾아 바깥에서 마음껏 뛰놀게 해 주세요.', title_nl = 'De vier muren worden te benauwd 🌳', body_nl = 'Kan hij binnen zijn energie niet kwijt en smijt hij met alles? Open de kaart Mamavriendelijke plekken, zoek een veilig park met een zachte ondergrond en glijbaan en laat hem vrij in de buitenlucht.', title_pl = 'Cztery ściany go przytłaczają 🌳', body_pl = 'Nie może rozładować energii w domu i wszystkim rzuca? Otwórz mapę Miejsc przyjaznych mamom, znajdź bezpieczny park z miękką nawierzchnią i zjeżdżalnią i pozwól mu wyszaleć się na świeżym powietrzu.', title_pt = 'As quatro paredes sufocam-no 🌳', body_pt = 'Não consegue gastar energia em casa e atira tudo ao ar? Abra o mapa dos Locais Amigos das Mães, encontre um parque seguro com piso macio e escorrega e deixe-o à vontade ao ar livre.', title_sv = 'De fyra väggarna känns trånga 🌳', body_sv = 'Kan barnet inte få ut energin inomhus och kastar allt omkring sig? Öppna kartan i Mammavänliga platser, hitta en trygg park med mjukt underlag och rutschkana och låt barnet röra sig fritt utomhus.', title_vi = 'Bốn bức tường làm bé bức bối 🌳', body_vi = 'Bé không xả được năng lượng trong nhà và ném tung mọi thứ? Hãy mở bản đồ Địa điểm thân thiện với mẹ, tìm một công viên an toàn có nền mềm và cầu trượt để bé tự do vui chơi ngoài trời.', title_zh = '四面墙让宝宝憋闷 🌳', body_zh = '在家里释放不了精力，什么都乱扔？打开妈妈友好场所地图，找一个有软地面和滑梯的安全公园，让宝宝在户外尽情撒欢。' WHERE id = 'd3a86832-34ed-43f4-90d5-a80f77b22f80' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón de talla y peso! 📏', body_es = '¿Al vestirle has notado que las camisetas le quedan estrechas o le aprietan los zapatos? Introduce su talla y medidas actuales en el Registro de peso y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Pic de taille et de poids ! 📏', body_fr = 'En l''habillant, vous avez remarqué que les t-shirts serraient ou que les chaussures étaient étroites ? Entrez sa taille et ses mesures actuelles dans le Suivi du poids et regardez fièrement sa courbe grimper.', title_hi = 'लंबाई और वज़न में उछाल! 📏', body_hi = 'कपड़े पहनाते समय लगा कि कमीज़ें तंग हो गईं या जूते काट रहे हैं? वेट ट्रैकर में मौजूदा लंबाई और माप दर्ज कीजिए और गर्व से देखिए कि ग्रोथ कर्व कैसे ऊपर जा रहा है।', title_id = 'Lonjakan tinggi dan berat badan! 📏', body_id = 'Saat memakaikan baju, Anda melihat kausnya mulai sempit atau sepatunya sesak? Masukkan tinggi dan ukuran terbarunya ke Pelacak Berat Badan dan lihat dengan bangga kurva pertumbuhannya naik.', title_ja = '身長と体重がぐんと伸びた！📏', body_ja = '着替えのときに、シャツがきつくなったり、靴が小さくなったりしたことに気づきましたか？「体重トラッカー」に今の身長とサイズを入力して、成長曲線が伸びていく様子を誇らしく眺めましょう。', title_ko = '키와 몸무게가 쑥! 📏', body_ko = '옷을 입힐 때 셔츠가 끼거나 신발이 작아진 걸 느꼈나요? 체중 기록에 현재 키와 치수를 입력하고 성장 곡선이 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Groeispurt in lengte en gewicht! 📏', body_nl = 'Merk je bij het aankleden dat shirtjes krap zitten of schoenen knellen? Voer zijn huidige lengte en maten in de Gewichtstracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Skok wzrostu i wagi! 📏', body_pl = 'Przy ubieraniu zauważyłaś, że koszulki są ciasne, a buty uciskają? Wpisz aktualny wzrost i wymiary w Liczniku wagi i z dumą patrz, jak pnie się krzywa rozwoju.', title_pt = 'Salto na altura e no peso! 📏', body_pt = 'Ao vesti-lo, reparou que as camisolas estão apertadas ou que os sapatos apertam? Introduza a altura e as medidas atuais no Registo de Peso e veja com orgulho a curva de crescimento a subir.', title_sv = 'Längd- och viktspurt! 📏', body_sv = 'Märkte du att tröjorna blivit trånga eller att skorna klämmer när du klädde på barnet? Ange aktuell längd och mått i Viktspåraren och titta stolt på hur tillväxtkurvan stiger.', title_vi = 'Tăng vọt chiều cao và cân nặng! 📏', body_vi = 'Khi mặc đồ cho bé, mẹ thấy áo chật hơn hay giày bị bó? Hãy nhập chiều cao và số đo hiện tại vào Theo dõi cân nặng và tự hào ngắm đường cong phát triển đi lên.', title_zh = '身高体重猛长！📏', body_zh = '穿衣服时发现上衣变紧，或者鞋子挤脚？在体重记录里输入当前的身高和尺寸，骄傲地看看成长曲线是怎么往上走的。' WHERE id = '24023d7c-2bc9-4102-89e5-fd869c13910d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Revisa la reserva de hierro 🥩', body_es = '¿Está pálido o se cansa enseguida? Comprueba en el Seguimiento de tomas el hierro de hoy y acompaña siempre la carne con vitamina C (limón, tomate) para mejorar la absorción.', title_fr = 'Vérifiez ses réserves de fer 🥩', body_fr = 'Il a le teint pâle ou se fatigue vite ? Vérifiez ses apports en fer du jour dans le Suivi des repas et donnez absolument de la vitamine C (citron, tomate) avec la viande pour mieux l''absorber.', title_hi = 'आयरन का भंडार जाँचिए 🥩', body_hi = 'रंग फीका है या जल्दी थक जाता है? फ़ीडिंग ट्रैकर में आज का आयरन जाँचिए और मांस के साथ ज़रूर विटामिन C (नींबू, टमाटर) दीजिए ताकि आयरन अच्छे से सोखा जाए।', title_id = 'Cek cadangan zat besi 🥩', body_id = 'Wajahnya pucat atau cepat lelah? Cek asupan zat besi hari ini di alat Pemantau Nutrisi, dan pastikan memberi vitamin C (lemon, tomat) bersama daging untuk meningkatkan penyerapannya.', title_ja = '鉄分をチェックしよう 🥩', body_ja = '顔色が悪かったり、すぐに疲れたりしますか？「栄養管理ツール」で今日の鉄分の摂取量を確認し、お肉と一緒に必ずビタミンC（レモン、トマト）をとって吸収を高めましょう。', title_ko = '철분을 확인하세요 🥩', body_ko = '얼굴이 창백하거나 쉽게 지치나요? 수유 기록 도구로 오늘의 철분 섭취를 확인하고, 고기와 함께 비타민 C(레몬, 토마토)를 꼭 곁들여 흡수를 높이세요.', title_nl = 'Check de ijzervoorraad 🥩', body_nl = 'Ziet hij bleek of is hij snel moe? Controleer in de Voedingstracker het ijzer van vandaag en geef naast vlees zeker vitamine C (citroen, tomaat) voor een betere opname.', title_pl = 'Sprawdź zapas żelaza 🥩', body_pl = 'Jest blady albo szybko się męczy? Sprawdź w narzędziu do śledzenia karmienia dzisiejsze spożycie żelaza i do mięsa koniecznie podawaj witaminę C (cytryna, pomidor), by poprawić wchłanianie.', title_pt = 'Verifique as reservas de ferro 🥩', body_pt = 'Está pálido ou cansa-se depressa? Verifique no Registo de Alimentação o ferro de hoje e, com a carne, dê-lhe sempre vitamina C (limão, tomate) para aumentar a absorção.', title_sv = 'Kontrollera järnförrådet 🥩', body_sv = 'Är barnet blekt eller blir snabbt trött? Kontrollera dagens järnintag i Matningskoll och ge alltid C-vitamin (citron, tomat) till köttet för bättre upptag.', title_vi = 'Kiểm tra kho sắt 🥩', body_vi = 'Bé xanh xao hay nhanh mệt? Hãy kiểm tra lượng sắt hôm nay trong Theo dõi cữ bú và nhất định cho bé ăn kèm vitamin C (chanh, cà chua) với thịt để tăng hấp thu.', title_zh = '检查铁储备 🥩', body_zh = '脸色苍白，还很容易累？在喂养记录工具里查看今天的铁摄入量，吃肉的同时一定搭配维生素C（柠檬、番茄），提高吸收率。' WHERE id = 'af6b0980-8f3e-49f7-8539-9fc05967e656' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tú también necesitas amigas 👯‍♀️', body_es = '¿Cansada de hablar todo el día solo en idioma bebé? Busca en Lugares para mamás cafeterías infantiles donde se reúnen muchas madres y créate un ambiente para socializar.', title_fr = 'Vous aussi, vous avez besoin d''amies 👯‍♀️', body_fr = 'Fatiguée de ne parler que le langage bébé toute la journée ? Trouvez dans les Lieux adaptés aux mamans des cafés pour enfants où les mamans se retrouvent, et offrez-vous un cadre pour voir du monde.', title_hi = 'आपको भी दोस्त चाहिए 👯‍♀️', body_hi = 'दिनभर सिर्फ़ तोतली भाषा में बात करते-करते थक गईं? माँ के लिए अनुकूल जगहें में वे किड्स कैफ़े ढूँढिए जहाँ बहुत सी माँएँ आती हैं, और अपने लिए भी मेल-जोल का माहौल बनाइए।', title_id = 'Anda juga butuh teman 👯‍♀️', body_id = 'Lelah seharian hanya berbicara dengan bahasa anak-anak? Temukan kafe anak tempat banyak ibu berkumpul di Tempat Ramah Ibu dan ciptakan suasana untuk bersosialisasi.', title_ja = 'あなたにも友だちが必要です 👯‍♀️', body_ja = '一日中、子ども向けの言葉だけで話すのに疲れましたか？「ママにやさしいスポット」でママたちが集まるキッズカフェを見つけて、自分にも交流できる場所をつくりましょう。', title_ko = '엄마에게도 친구가 필요해요 👯‍♀️', body_ko = '하루 종일 아기 말만 하느라 지쳤나요? 엄마 친화 장소에서 엄마들이 많이 모이는 키즈 카페를 찾아 나에게도 어울릴 기회를 만들어 주세요.', title_nl = 'Jij hebt ook vriendinnen nodig 👯‍♀️', body_nl = 'Moe van de hele dag alleen maar kindertaal praten? Zoek in Mamavriendelijke plekken kindercafés waar veel moeders komen en zorg dat jij ook sociaal contact hebt.', title_pl = 'Ty też potrzebujesz przyjaciółek 👯‍♀️', body_pl = 'Masz dość całodziennego mówienia wyłącznie dziecięcym językiem? Znajdź w Miejscach przyjaznych mamom kawiarnie dla dzieci, w których spotyka się wiele mam, i stwórz sobie okazję do spotkań.', title_pt = 'Também precisa de amigas 👯‍♀️', body_pt = 'Cansada de falar o dia todo só a linguagem das crianças? Encontre nos Locais Amigos das Mães cafés para crianças onde se juntam muitas mães e crie também um ambiente para conviver.', title_sv = 'Du behöver också vänner 👯‍♀️', body_sv = 'Trött på att bara prata barnspråk hela dagen? Hitta barncaféer där många mammor samlas i Mammavänliga platser och skapa en miljö för att umgås.', title_vi = 'Mẹ cũng cần bạn bè 👯‍♀️', body_vi = 'Mẹ mệt vì cả ngày chỉ nói "ngôn ngữ trẻ con"? Hãy tìm những quán cà phê trẻ em nơi các mẹ hay gặp nhau trong Địa điểm thân thiện với mẹ để có không gian giao lưu cho mình.', title_zh = '你也需要朋友 👯‍♀️', body_zh = '一整天都用“宝宝语”说话，说累了？在妈妈友好场所里找找妈妈们常聚的亲子咖啡馆，也给自己创造一个社交的环境。' WHERE id = 'f5e0ef2c-4838-48df-b45d-d158a473879a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Exigencias urgentes 🛒', title_fr = 'Exigences pressantes 🛒', title_hi = 'झटपट ज़िदें 🛒', title_id = 'Tuntutan mendadak 🛒', title_ja = '「今すぐ！」の要求 🛒', title_ko = '급한 요구 🛒', title_nl = 'Dringende eisen 🛒', title_pl = 'Pilne żądania 🛒', title_pt = 'Exigências urgentes 🛒', title_sv = 'Snabba krav 🛒', title_vi = 'Đòi hỏi tức thì 🛒', title_zh = '急切的要求 🛒' WHERE id = '3046868d-cc9d-4ca4-8350-b813468ec4dd' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Se tira al suelo y grita cuando no consigue lo que quiere?', body_es = 'Las rabietas siguen. Quédate tranquila a un lado y, cuando se calme, abrázale.', title_fr = 'Il se jette par terre en hurlant quand il n''obtient pas ce qu''il veut ?', body_fr = 'Les crises du tout-petit continuent. Restez calmement à côté et prenez-le dans vos bras quand il s''apaise.', title_hi = 'मनचाहा न मिले तो ज़मीन पर लोटकर चिल्लाता है?', body_hi = 'छोटे बच्चों के नखरे जारी हैं। पास में शांति से खड़ी रहिए, और जब वह शांत हो जाए तो उसे गले लगाइए।', title_id = 'Menjatuhkan diri ke lantai dan menjerit saat keinginannya tak terpenuhi?', body_id = 'Tantrum balita masih berlanjut. Berdirilah dengan tenang di dekatnya, dan peluk ia saat sudah tenang.', title_ja = '思いどおりにならないと、床にひっくり返って叫びますか？', body_ja = '幼児期のかんしゃくは続きます。そばで静かに待って、落ち着いたら抱きしめてあげましょう。', title_ko = '원하는 대로 안 되면 바닥에 드러누워 소리 지르나요?', body_ko = '두 살 아이의 떼쓰기는 계속돼요. 곁에서 조용히 기다렸다가 진정되면 꼭 안아 주세요.', title_nl = 'Gooit hij zich schreeuwend op de grond als hij zijn zin niet krijgt?', body_nl = 'De driftbuien van een peuter gaan door. Blijf rustig in de buurt staan en knuffel hem als hij gekalmeerd is.', title_pl = 'Rzuca się na podłogę i krzyczy, gdy nie dostaje tego, czego chce?', body_pl = 'Napady złości malucha trwają. Stań spokojnie obok, a gdy się uspokoi, przytul go.', title_pt = 'Atira-se para o chão aos gritos quando não consegue o que quer?', body_pt = 'As birras da fase de criança pequena continuam. Fique calmamente ao lado e, quando ele se acalmar, abrace-o.', title_sv = 'Kastar sig barnet på golvet och skriker när hen inte får som hen vill?', body_sv = 'Småbarnsutbrotten fortsätter. Stå lugnt bredvid och krama barnet när hen har lugnat sig.', title_vi = 'Bé lăn ra sàn la hét khi không được như ý?', body_vi = 'Những cơn ăn vạ tuổi chập chững vẫn tiếp diễn. Hãy bình tĩnh đứng bên cạnh, khi bé dịu lại thì ôm bé vào lòng.', title_zh = '想要的得不到就躺地上尖叫？', body_zh = '幼儿的发脾气还在继续。在旁边安静地待着，等宝宝平静下来再抱抱宝宝。' WHERE id = '437a3027-38a4-47b2-a62c-a24094b2e7eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe del cuento 🪄', body_es = 'Esta noche crea en Cuentos inteligentes una historia especial cuyo héroe sea tu peque: «El pequeño valiente al que le encanta la noche».', title_fr = 'Le héros du conte 🪄', body_fr = 'Ce soir, créez dans les Contes intelligents une histoire spéciale dont votre enfant est le héros : « Le petit courageux qui aimait la nuit ».', title_hi = 'कहानी का हीरो 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: रात को पसंद करने वाला एक बहादुर नन्हा।', title_id = 'Tokoh utama dongeng 🪄', body_id = 'Malam ini, buat cerita istimewa di Dongeng Pintar dengan anak Anda sebagai tokoh utamanya: Si kecil pemberani yang menyukai malam.', title_ja = 'お話の主人公 🪄', body_ja = '今夜は「スマートおはなし」で、お子さんが主人公の特別なお話をつくりましょう：「夜が大好きな勇敢なおちびさん」。', title_ko = '동화 속 주인공 🪄', body_ko = '오늘 밤 스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: ''밤을 좋아하는 용감한 꼬마''.', title_nl = 'De held van het sprookje 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: de dappere kleine die van de nacht houdt.', title_pl = 'Bohater bajki 🪄', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Dzielny maluch, który kocha noc”.', title_pt = 'O herói da história 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "O pequeno corajoso que adora a noite".', title_sv = 'Sagans hjälte 🪄', body_sv = 'Skapa i kväll en speciell berättelse i Smarta sagor där ditt eget barn är hjälten: den modiga lilla som älskar natten.', title_vi = 'Nhân vật chính của câu chuyện 🪄', body_vi = 'Tối nay, hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là bé: "Em bé dũng cảm yêu màn đêm".', title_zh = '故事的主角 🪄', body_zh = '今晚在智能故事里创作一个以你的孩子为主角的特别故事：一个喜欢夜晚的勇敢小家伙。' WHERE id = '46ca17b0-646f-46ee-9f74-a67a0f778d4f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Guardar las cosas en su sitio 🧸', body_es = '¿Mete el juguete en la caja y lo vuelve a sacar? Se está formando la lógica de «dentro» y «fuera». Anota sin falta esta habilidad cognitiva en el Seguimiento del desarrollo.', title_fr = 'Ranger les affaires 🧸', body_fr = 'Il met un jouet dans une boîte et le ressort encore et encore ? Les notions de dedans et dehors se construisent. Notez absolument cette compétence cognitive dans le Suivi de développement.', title_hi = 'चीज़ों को जगह पर रखना 🧸', body_hi = 'खिलौना डिब्बे में डालता है और फिर निकालता है? ''अंदर'' और ''बाहर'' की समझ बन रही है। ग्रोथ ट्रैकर में इस समझ वाले हुनर को ज़रूर दर्ज कीजिए।', title_id = 'Menaruh barang di tempatnya 🧸', body_id = 'Memasukkan mainan ke kotak lalu mengeluarkannya lagi berulang kali? Logika di dalam dan di luar sedang terbentuk. Pastikan mencatat keterampilan kognitif ini di Pelacak Perkembangan.', title_ja = 'お片付け 🧸', body_ja = 'おもちゃを箱に入れては、また出していますか？「中」と「外」の論理が育っています。この認知の力をぜひ「発達トラッカー」に記録しましょう。', title_ko = '물건을 제자리에 넣어요 🧸', body_ko = '장난감을 상자에 넣었다가 다시 꺼내기를 반복하나요? ''안과 밖''의 논리가 자라고 있어요. 성장 기록에 이 인지 능력을 꼭 남겨 두세요.', title_nl = 'Spullen opruimen 🧸', body_nl = 'Gooit hij een speeltje in een doos en haalt hij het er steeds weer uit? Zo ontwikkelt hij het begrip van erin en eruit. Noteer deze cognitieve vaardigheid zeker in de Groeitracker.', title_pl = 'Odkładanie rzeczy na miejsce 🧸', body_pl = 'Wrzuca zabawkę do pudełka i znów ją wyjmuje? Kształtuje się logika pojęć „w środku” i „na zewnątrz”. Koniecznie zapisz tę umiejętność poznawczą w Śledzeniu rozwoju.', title_pt = 'Pôr as coisas no lugar 🧸', body_pt = 'Mete o brinquedo na caixa e volta a tirá-lo? Está a formar-se a lógica de "dentro" e "fora". Registe sem falta esta competência cognitiva no Registo de Desenvolvimento.', title_sv = 'Lägga saker på plats 🧸', body_sv = 'Lägger barnet leksaken i lådan och tar fram den igen? Logiken för ”i” och ”utanför” formas. Glöm inte att anteckna denna kognitiva färdighet i Utvecklingsspåraren.', title_vi = 'Cất đồ về chỗ cũ 🧸', body_vi = 'Bé bỏ đồ chơi vào hộp rồi lại lấy ra? Khái niệm trong và ngoài đang hình thành. Nhất định hãy ghi lại kỹ năng nhận thức này vào Theo dõi phát triển.', title_zh = '把东西放回原处 🧸', body_zh = '把玩具扔进盒子，又再拿出来？“里面”和“外面”的逻辑正在形成。一定要把这项认知能力记在发育追踪里。' WHERE id = '764398f1-2f82-4a41-a767-bcf8004dd068' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = '¿Cómo debería ser el habla de un niño después de los 2 años? No te pierdas en internet: escribe directamente a Anacan AI y recibe una respuesta con base científica.', body_fr = 'Comment devrait être le langage de l''enfant après 2 ans ? Ne vous perdez pas sur Internet, écrivez directement à Anacan AI et obtenez une réponse fondée sur la science.', body_hi = '2 साल के बाद बच्चे की बोली कैसी होनी चाहिए? इंटरनेट में मत उलझिए, सीधे Anacan AI को लिखिए और विज्ञान पर आधारित जवाब पाइए।', body_id = 'Bagaimana seharusnya kemampuan bicara anak setelah usia 2 tahun? Jangan tersesat di internet, langsung tulis ke Anacan AI dan dapatkan jawaban berbasis ilmiah.', body_ja = '2歳を過ぎた子の言葉の発達はどうあるべき？ネットで迷わず、Anacan AIに直接書き込んで、科学的な根拠のある答えをもらいましょう。', body_ko = '두 돌 이후 아이의 말은 어느 정도여야 할까요? 인터넷에서 헤매지 말고 Anacan AI에게 바로 물어 과학적인 답을 받아 보세요.', body_nl = 'Hoe hoort de spraak van een kind na 2 jaar te zijn? Verdwaal niet op internet, maar schrijf direct naar Anacan AI en krijg een wetenschappelijk onderbouwd antwoord.', body_pl = 'Jak powinna wyglądać mowa dziecka po 2. urodzinach? Nie gub się w internecie, napisz od razu do Anacan AI i dostań odpowiedź opartą na nauce.', body_pt = 'Como deve ser a fala de uma criança depois dos 2 anos? Não se perca na internet: escreva diretamente ao Anacan AI e receba uma resposta com base científica.', body_sv = 'Hur ska barnets tal vara efter 2 år? Gå inte vilse på internet, skriv direkt till Anacan AI och få ett vetenskapligt grundat svar.', body_vi = 'Sau 2 tuổi trẻ nên nói được như thế nào? Đừng lạc giữa internet, hãy nhắn thẳng cho Anacan AI để nhận câu trả lời có cơ sở khoa học.', body_zh = '2岁以后孩子的语言应该是什么样的？别在网上迷失，直接写信给Anacan AI，获得有科学依据的回答。' WHERE id = '850a613f-ecbc-4d9b-ab63-9701c3f268f9' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Llegan las frases largas! 🗣️', body_es = '¿Ya junta 4-5 palabras para contar una historia graciosa? ¡Está viviendo una explosión de vocabulario! No te pierdas este momento de oro: guárdalo ya con sonido en el Álbum del bebé y anota su avance.', title_fr = 'Les longues phrases arrivent ! 🗣️', body_fr = 'Il assemble déjà 4-5 mots pour raconter une histoire rigolote ? C''est l''explosion du vocabulaire ! Ne manquez pas ce moment en or : enregistrez-le tout de suite avec le son dans l''Album de bébé pour garder une trace de ses progrès.', title_hi = 'लंबे वाक्य आ रहे हैं! 🗣️', body_hi = 'अब 4-5 शब्द जोड़कर मज़ेदार कहानी सुनाता है? शब्दों का धमाका हो रहा है! इस अनमोल पल को मत चूकिए, तुरंत आवाज़ के साथ बेबी एल्बम में सहेजिए और विकास दर्ज कीजिए।', title_id = 'Kalimat panjang mulai muncul! 🗣️', body_id = 'Ia sudah merangkai 4-5 kata untuk menceritakan kisah lucu? Ledakan kosakata sedang terjadi! Jangan lewatkan momen emas ini, segera simpan rekaman suaranya di Album Bayi dan abadikan perkembangannya.', title_ja = '長い文がやってくる！🗣️', body_ja = 'もう4-5語をつなげて、おもしろいお話をしていますか？語彙の爆発が起きています！この宝物のような瞬間を見逃さず、すぐに音声付きで「ベビーアルバム」に残して、成長を記録しましょう。', title_ko = '긴 문장이 와요! 🗣️', body_ko = '벌써 네다섯 단어를 이어 재미있는 이야기를 하나요? 어휘 폭발이 일어나고 있어요! 이 금쪽같은 순간을 놓치지 말고 바로 소리로 아기 앨범에 남겨 성장을 기록하세요.', title_nl = 'Lange zinnen komen eraan! 🗣️', body_nl = 'Vertelt hij al een grappig verhaal door 4-5 woorden te combineren? Er is een woordenexplosie! Mis dit gouden moment niet en bewaar het meteen met geluid in het Babyalbum.', title_pl = 'Nadchodzą długie zdania! 🗣️', body_pl = 'Już łączy 4-5 słów i opowiada zabawną historię? To eksplozja słownictwa! Nie przegap tej złotej chwili, od razu nagraj ją z dźwiękiem w Albumie dziecka i uwiecznij ten rozwój.', title_pt = 'Aí vêm as frases longas! 🗣️', body_pt = 'Já junta 4-5 palavras e conta uma história engraçada? Está a viver uma explosão de vocabulário! Não perca este momento de ouro: guarde-o já em áudio no Álbum do Bebé e registe o desenvolvimento.', title_sv = 'Långa meningar på väg! 🗣️', body_sv = 'Sätter barnet redan ihop 4-5 ord och berättar en rolig historia? Det är en ordexplosion! Missa inte detta gyllene ögonblick, spara det direkt med ljud i Babyalbumet och följ utvecklingen.', title_vi = 'Những câu dài đã đến! 🗣️', body_vi = 'Bé đã ghép 4-5 từ để kể một câu chuyện ngộ nghĩnh? Bé đang bùng nổ vốn từ! Đừng bỏ lỡ khoảnh khắc vàng này, hãy ghi âm ngay vào Album của bé để đánh dấu sự phát triển.', title_zh = '长句子来了！🗣️', body_zh = '已经能把4-5个词连起来，讲一个搞笑的故事了？词汇正在大爆发！别错过这个黄金时刻，马上录下声音存进宝宝相册，记录成长。' WHERE id = '4fcc8b4e-e106-490a-a901-8c89be671af5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'En busca de lógica 🧩', body_es = 'Ya se sabe de memoria los puzles sencillos de dos o tres piezas. Busca en Productos recomendados juguetes de madera más complejos de causa-efecto que pongan a prueba su inteligencia.', title_fr = 'En quête de logique 🧩', body_fr = 'Il connaît déjà par cœur les puzzles simples de deux ou trois pièces. Trouvez dans les Produits recommandés des jouets en bois plus complexes sur la cause et l''effet, qui mettront son intelligence au défi.', title_hi = 'तर्क की तलाश 🧩', body_hi = 'उसे दो-तीन टुकड़ों वाली आसान पज़ल अब याद हो गई हैं। उसकी बुद्धि को और चुनौती देने वाले, कारण और नतीजा समझाने वाले मुश्किल लकड़ी के खिलौने सुझाए गए प्रोडक्ट सेक्शन में ढूँढिए।', title_id = 'Mencari tantangan logika 🧩', body_id = 'Ia sudah hafal puzzle sederhana dua-tiga keping. Temukan mainan kayu yang lebih rumit untuk melatih sebab-akibat dan lebih menantang kecerdasannya di bagian Produk Rekomendasi.', title_ja = '論理的な思考を育てよう 🧩', body_ja = '2-3ピースの簡単なパズルは、もう覚えてしまいました。知性をさらに刺激し、原因と結果のつながりを学べる複雑な木のおもちゃを、「おすすめ商品」で見つけましょう。', title_ko = '논리를 찾아서 🧩', body_ko = '이제 두세 조각짜리 간단한 퍼즐은 다 외웠어요. 두뇌를 더 자극할 원인과 결과를 익히는 복잡한 원목 장난감을 추천 제품 섹션에서 찾아보세요.', title_nl = 'Op zoek naar logica 🧩', body_nl = 'Simpele puzzels van twee of drie stukjes kent hij al uit zijn hoofd. Zoek in Aanbevolen producten moeilijker houten speelgoed met oorzaak en gevolg dat zijn verstand nog meer uitdaagt.', title_pl = 'W poszukiwaniu logiki 🧩', body_pl = 'Proste układanki z dwóch-trzech części zna już na pamięć. Znajdź w sekcji Polecane produkty bardziej złożone drewniane zabawki uczące związku przyczyny i skutku, które jeszcze mocniej pobudzą jego umysł.', title_pt = 'Em busca da lógica 🧩', body_pt = 'Já sabe de cor os puzzles simples de duas ou três peças. Encontre na secção Produtos Recomendados brinquedos de madeira mais complexos, de causa e efeito, que vão desafiar ainda mais a inteligência dele.', title_sv = 'På jakt efter logik 🧩', body_sv = 'Barnet kan redan de enkla pusslen med två eller tre bitar utantill. Hitta svårare träleksaker som visar orsak och verkan och utmanar tänkandet ännu mer i Rekommenderade produkter.', title_vi = 'Tìm kiếm tư duy 🧩', body_vi = 'Bé đã thuộc lòng các bộ ghép hình đơn giản hai, ba mảnh. Hãy tìm những đồ chơi gỗ phức tạp hơn, giúp bé hiểu quan hệ nhân quả và động não nhiều hơn trong mục Sản phẩm gợi ý.', title_zh = '寻找逻辑游戏 🧩', body_zh = '简单的两三块拼图宝宝已经背熟了。在推荐商品板块找找更复杂、能建立因果关系、给宝宝更多挑战的木制玩具。' WHERE id = '569d530d-d6b9-4460-be46-292c62f656dd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tormenta en la bañera 🛁', body_es = '¿No quiere salir del agua y llora? Pregunta ya a Anacan AI por juguetes para distraerle y formas prácticas de terminar el baño sin estrés.', title_fr = 'Tempête dans le bain 🛁', body_fr = 'Il ne veut pas sortir de l''eau et pleure ? Demandez tout de suite à Anacan AI des jouets pour détourner son attention et des transitions pratiques pour finir le bain sans stress.', title_hi = 'नहाने में तूफ़ान 🛁', body_hi = 'पानी से निकलना नहीं चाहता और रोता है? नहाने का रूटीन बिना तनाव खत्म करने के लिए ध्यान बँटाने वाले खिलौने और काम के तरीके तुरंत Anacan AI से पूछिए।', title_id = 'Badai di kamar mandi 🛁', body_id = 'Tidak mau keluar dari air dan menangis? Segera tanyakan kepada Anacan AI mainan pengalih perhatian dan cara praktis mengakhiri waktu mandi tanpa stres.', title_ja = 'お風呂で大嵐 🛁', body_ja = 'お風呂から出たがらずに泣きますか？お風呂の時間をストレスなく終えるための、気をそらすおもちゃや実践的な切りかえ方を、すぐにAnacan AIに聞いてみましょう。', title_ko = '욕조 속 폭풍 🛁', body_ko = '물에서 나오기 싫다며 우나요? 목욕 시간을 스트레스 없이 끝내도록 주의를 돌릴 장난감과 실용적인 전환 방법을 Anacan AI에게 바로 물어보세요.', title_nl = 'Storm in het bad 🛁', body_nl = 'Wil hij niet uit het water en huilt hij? Vraag Anacan AI meteen naar afleidend speelgoed en praktische manieren om het badritueel zonder stress af te sluiten.', title_pl = 'Burza w wannie 🛁', body_pl = 'Nie chce wyjść z wody i płacze? Od razu zapytaj Anacan AI o zabawki odwracające uwagę i praktyczne sposoby, by bez stresu kończyć kąpiel.', title_pt = 'Tempestade no banho 🛁', body_pt = 'Não quer sair da água e chora? Pergunte já ao Anacan AI que brinquedos o podem distrair e formas práticas de terminar a rotina do banho sem stress.', title_sv = 'Storm i badet 🛁', body_sv = 'Vill barnet inte gå upp ur vattnet och gråter? Fråga Anacan AI direkt om leksaker som avleder och praktiska övergångar för att avsluta badet utan stress.', title_vi = 'Cơn bão trong nhà tắm 🛁', body_vi = 'Bé không chịu ra khỏi nước và khóc? Hãy hỏi ngay Anacan AI về đồ chơi đánh lạc hướng và cách chuyển tiếp thực tế để kết thúc giờ tắm mà không căng thẳng.', title_zh = '浴室里的风暴 🛁', body_zh = '不肯从水里出来，还哭？马上问问Anacan AI，用转移注意力的玩具和实用的过渡方法，轻松结束洗澡时间。' WHERE id = 'ce1a09c7-d2c5-485b-a920-bc02df41fb58' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pelea por el turno en el tobogán 🛑', body_es = '¿En el parque no quiere esperar a los demás niños? Lee sin falta en los artículos sobre socialización del Blog cómo inculcar el sentido del turno y de compartir hacia los 2,5 años.', title_fr = 'Dispute pour le toboggan 🛑', body_fr = 'Au parc, il ne veut pas attendre les autres enfants ? Lisez absolument les articles sur la socialisation de la rubrique Blogs pour lui apprendre à attendre son tour et à partager vers 2 ans et demi.', title_hi = 'स्लाइड पर बारी का झगड़ा 🛑', body_hi = 'पार्क में दूसरे बच्चों का इंतज़ार नहीं करना चाहता? 2.5 साल के करीब बारी और बाँटने की समझ कैसे सिखाएँ, यह ब्लॉग सेक्शन के मेल-जोल वाले लेखों में ज़रूर पढ़िए।', title_id = 'Rebutan giliran di perosotan 🛑', body_id = 'Tidak mau menunggu anak lain di taman? Pastikan membaca artikel sosialisasi di bagian Blog tentang cara menanamkan konsep bergiliran dan berbagi menjelang usia 2,5 tahun.', title_ja = 'すべり台の順番争い 🛑', body_ja = '公園でほかの子を待ちたがらない？2歳半に向けて「順番」と「分け合うこと」をどう教えるか、ブログの社会性に関する記事をぜひ読んでみましょう。', title_ko = '미끄럼틀 차례 싸움 🛑', body_ko = '공원에서 다른 아이들을 기다리기 싫어하나요? 두 돌 반 무렵 차례와 나누기를 가르치는 방법을 블로그의 사회성 관련 글에서 꼭 읽어 보세요.', title_nl = 'Ruzie om de beurt op de glijbaan 🛑', body_nl = 'Wil hij in het park niet op andere kinderen wachten? Lees zeker de artikelen over socialisatie in Blogs over hoe je rond 2,5 jaar om de beurt gaan en delen aanleert.', title_pl = 'Kłótnia o kolejkę na zjeżdżalni 🛑', body_pl = 'W parku nie chce czekać na inne dzieci? Koniecznie przeczytaj w artykułach o uspołecznieniu w sekcji Blog, jak w okolicach 2,5 roku uczyć czekania na swoją kolej i dzielenia się.', title_pt = 'A guerra da vez no escorrega 🛑', body_pt = 'No parque não quer esperar pelas outras crianças? Leia sem falta nos artigos de socialização dos Blogues como incutir, perto dos 2,5 anos, as noções de vez e de partilha.', title_sv = 'Bråk om turen i rutschkanan 🛑', body_sv = 'Vill barnet inte vänta på de andra barnen i parken? Läs artiklarna om socialt samspel i Bloggar om hur du lär ut begreppen tur och att dela mot 2,5 års ålder.', title_vi = 'Tranh nhau cầu trượt 🛑', body_vi = 'Ở công viên bé không muốn chờ các bạn? Nhất định hãy đọc các bài viết về hòa nhập xã hội trong mục Blog về cách dạy trẻ gần 2,5 tuổi biết chờ lượt và chia sẻ.', title_zh = '滑梯前的排队之争 🛑', body_zh = '在公园不愿意等其他小朋友？一定要读读博客板块里的社交文章，了解如何教快2.5岁的宝宝学会轮流和分享。' WHERE id = '32be8503-ee3d-483e-baae-9b3b130b80cc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las páginas cobran vida 📖', body_es = '¿Mientras le lees un cuento, se inventa él el final? Descubre con Anacan AI técnicas de lectura interactiva que apoyan este maravilloso momento de imaginación.', title_fr = 'Les pages prennent vie 📖', body_fr = 'Pendant le conte, c''est lui qui invente la fin de l''histoire ? Découvrez avec Anacan AI des techniques de lecture interactive qui soutiennent ce formidable moment d''imagination.', title_hi = 'पन्ने जीवंत हो उठते हैं 📖', body_hi = 'कहानी पढ़ते समय कहानी का अंत वह खुद गढ़ता है? कल्पना के इस शानदार पल में मदद करने वाली इंटरैक्टिव पढ़ने की तकनीकें Anacan AI के ज़रिए जानिए।', title_id = 'Halaman-halaman jadi hidup 📖', body_id = 'Saat Anda membacakan dongeng, ia yang mengarang akhir ceritanya? Temukan teknik membaca interaktif yang mendukung momen imajinasi luar biasa ini lewat Anacan AI.', title_ja = 'ページがいきいきと動き出す 📖', body_ja = 'お話を読んでいると、結末を自分でつくり出しますか？このすばらしい想像力の瞬間を応援する参加型の読み聞かせのコツを、Anacan AIで見つけましょう。', title_ko = '책장이 살아나요 📖', body_ko = '동화를 읽어 줄 때 이야기의 끝을 아이가 지어내나요? 이 멋진 상상의 순간을 돕는 상호작용 책 읽기 방법을 Anacan AI와 함께 알아보세요.', title_nl = 'Bladzijden komen tot leven 📖', body_nl = 'Verzint hij zelf het einde van het verhaal als je voorleest? Ontdek met Anacan AI interactieve leestechnieken die dit prachtige fantasiemoment steunen.', title_pl = 'Strony ożywają 📖', body_pl = 'Podczas czytania bajki sam wymyśla zakończenie? Odkryj z Anacan AI techniki interaktywnego czytania, które wspierają tę wspaniałą wyobraźnię.', title_pt = 'As páginas ganham vida 📖', body_pt = 'Enquanto lê a história, é ele que inventa o final? Descubra com o Anacan AI técnicas de leitura interativa que apoiam este momento fantástico de imaginação.', title_sv = 'Sidorna får liv 📖', body_sv = 'Hittar barnet på slutet på sagan när ni läser? Upptäck interaktiva lästekniker som stöttar detta fantastiska fantasiögonblick med Anacan AI.', title_vi = 'Những trang sách sống động 📖', body_vi = 'Khi đọc truyện, bé tự nghĩ ra cái kết? Hãy khám phá cùng Anacan AI các kỹ thuật đọc tương tác giúp hỗ trợ khoảnh khắc tưởng tượng tuyệt vời này.', title_zh = '书页活起来了 📖', body_zh = '读故事时，结尾由宝宝来编？借助Anacan AI，发现支持这种了不起的想象力的互动阅读技巧。' WHERE id = 'bbf3c14f-5832-4554-88a9-fc0b10c25324' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Líquidos y estreñimiento 💩', body_es = '¿Corre mucho y bebe poca agua? Fíjate en las deposiciones al cambiar el pañal (o en el orinal). Si hay riesgo de estreñimiento, anótalo en la app y añade enseguida ciruelas pasas o avena al menú con el Seguimiento de tomas.', title_fr = 'Hydratation et constipation 💩', body_fr = 'Il court beaucoup et boit peu ? Observez les selles au change (ou sur le pot). En cas de risque de constipation, notez-le dans l''appli et ajoutez tout de suite des pruneaux ou de l''avoine à son menu avec le Suivi des repas.', title_hi = 'तरल और कब्ज़ 💩', body_hi = 'खूब दौड़ता है, पर पानी कम पीता है? डायपर बदलते समय (या पॉटी में) पॉटी पर ध्यान दीजिए। कब्ज़ का खतरा हो तो ऐप में दर्ज कीजिए और तुरंत फ़ीडिंग ट्रैकर से मेन्यू में आलूबुखारा (प्रून) या ओट्स जोड़िए।', title_id = 'Asupan cairan dan sembelit 💩', body_id = 'Banyak berlari, sedikit minum? Perhatikan kotorannya saat mengganti popok (atau di pispot). Jika ada risiko sembelit, catat di aplikasi dan segera tambahkan plum kering (prune) atau oat ke menunya dengan alat Pemantau Nutrisi.', title_ja = '水分補給と便秘 💩', body_ja = 'たくさん走り回るのに、あまりお水を飲まない？おむつ替えのとき（またはおまるで）うんちの様子をチェックしましょう。便秘のおそれがあればアプリに記録して、すぐに「栄養管理ツール」でプルーンやオートミールをメニューに加えましょう。', title_ko = '수분 섭취와 변비 💩', body_ko = '많이 뛰는데 물은 적게 마시나요? 기저귀를 갈 때(또는 변기에서) 배변을 살펴보세요. 변비가 걱정된다면 앱에 기록하고 수유 기록 도구로 식단에 말린 자두나 귀리를 바로 추가하세요.', title_nl = 'Drinken en verstopping 💩', body_nl = 'Rent hij veel en drinkt hij weinig? Let bij het verschonen (of op het potje) op de ontlasting. Is er kans op verstopping, noteer het in de app en voeg meteen met de Voedingstracker gedroogde pruimen of havermout toe aan het menu.', title_pl = 'Picie a zaparcia 💩', body_pl = 'Dużo biega, a mało pije? Obserwuj kupki przy zmianie pieluszki (lub na nocniku). Jeśli jest ryzyko zaparć, zapisz to w aplikacji i od razu dodaj do menu suszone śliwki lub płatki owsiane w narzędziu do śledzenia karmienia.', title_pt = 'Líquidos e prisão de ventre 💩', body_pt = 'Corre muito e bebe pouca água? Observe as fezes ao mudar a fralda (ou no bacio). Se houver risco de prisão de ventre, registe-o na app e acrescente já ameixas secas ou aveia à ementa com o Registo de Alimentação.', title_sv = 'Vätskeintag och förstoppning 💩', body_sv = 'Springer barnet mycket men dricker lite? Håll koll på avföringen när du byter blöja (eller på pottan). Finns risk för förstoppning, anteckna det i appen och lägg direkt till katrinplommon eller havre i menyn med Matningskoll.', title_vi = 'Uống nước và táo bón 💩', body_vi = 'Bé chạy nhiều mà uống ít nước? Hãy để ý phân khi thay tã (hoặc khi bé ngồi bô). Nếu có nguy cơ táo bón, hãy ghi vào ứng dụng và thêm ngay mận khô hoặc yến mạch vào thực đơn bằng Theo dõi cữ bú.', title_zh = '饮水与便秘 💩', body_zh = '跑得多，喝得少？换尿布时（或在便盆上）留意一下排便。如果有便秘风险，记到应用里，马上用喂养记录工具在菜单里加入西梅或燕麦。' WHERE id = 'c3d03381-340f-4ce1-b075-de3e6584aed7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juega con la comida 🥦', body_es = '¿En lugar de comerse la pasta, la aplasta y la esparce por todas partes? A esta edad la comida también es un juguete. Anota en el Plan de alimentación si ha comido mucho o poco y sigue el equilibrio semanal.', title_fr = 'Il joue avec la nourriture 🥦', body_fr = 'Il écrase les pâtes et les éparpille au lieu de les manger ? À cet âge, la nourriture est aussi un jouet. Notez dans le plan alimentaire s''il a bien mangé et suivez l''équilibre de la semaine.', title_hi = 'खाने से खेलता है 🥦', body_hi = 'पास्ता खाने के बजाय मसलकर चारों ओर फैला देता है? इस उम्र में खाना एक खिलौना भी है। उसने ज़्यादा खाया या नहीं, यह फ़ीडिंग प्लान में दर्ज करके हफ़्ते का संतुलन देखिए।', title_id = 'Bermain dengan makanan 🥦', body_id = 'Bukannya memakan pasta, malah meremas dan menyebarkannya ke mana-mana? Di usia ini makanan juga mainan. Catat seberapa banyak ia makan di Rencana Nutrisi dan pantau keseimbangan mingguannya.', title_ja = '食べ物で遊ぶ 🥦', body_ja = 'パスタを食べる代わりに、つぶしてまき散らしていますか？この年齢では、食べ物はおもちゃでもあります。どれくらい食べたかを「栄養管理ツール」に記録して、1週間のバランスを見守りましょう。', title_ko = '음식으로 놀아요 🥦', body_ko = '파스타를 먹는 대신 으깨서 사방에 뿌리나요? 이 나이에는 음식도 장난감이에요. 식단 계획에 얼마나 먹었는지 기록하며 한 주의 균형을 살펴보세요.', title_nl = 'Hij speelt met zijn eten 🥦', body_nl = 'Prakt hij de pasta en strooit hij hem rond in plaats van te eten? Op deze leeftijd is eten ook speelgoed. Noteer in het Voedingsplan of hij veel eet en volg de balans per week.', title_pl = 'Bawi się jedzeniem 🥦', body_pl = 'Zamiast jeść makaron, rozgniata go i rozrzuca dookoła? W tym wieku jedzenie to też zabawka. Zapisuj w planie karmienia, ile je, i śledź tygodniowy bilans.', title_pt = 'Brinca com a comida 🥦', body_pt = 'Em vez de comer a massa, esmaga-a e espalha-a à volta? Nesta idade, a comida também é um brinquedo. Registe no Registo de Alimentação se come muito ou pouco e acompanhe o equilíbrio semanal.', title_sv = 'Leker med maten 🥦', body_sv = 'Mosar barnet pastan och sprider den omkring sig i stället för att äta? I den här åldern är maten också en leksak. Anteckna i matplanen om barnet åt mycket eller lite och följ veckobalansen.', title_vi = 'Bé nghịch thức ăn 🥦', body_vi = 'Bé bóp nát mì ống và vung vãi khắp nơi thay vì ăn? Ở tuổi này thức ăn cũng là đồ chơi. Hãy ghi lại bé ăn nhiều hay ít trong Kế hoạch dinh dưỡng để theo dõi cân bằng hằng tuần.', title_zh = '玩食物 🥦', body_zh = '不吃意面，反而把它捏碎撒得到处都是？这个年龄的食物也是一种玩具。在喂养计划里记下吃了多少，跟进每周的平衡。' WHERE id = '275e7b7b-377b-40f0-9e43-ab5886fc93b4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La flota de la mañana 🧦', body_es = '¿Esta mañana ha querido ponerse el calcetín en la mano? No te enfades con estos momentos de descubrimiento acompañados de tozudez. Deja que ande un rato así: es su prueba de libertad.', title_fr = 'Le show du matin 🧦', body_fr = 'Ce matin, il a voulu mettre sa chaussette à la main ? Ne vous énervez pas devant ces découvertes obstinées. Laissez-le marcher un peu comme ça, c''est son test de liberté.', title_hi = 'सुबह का फ़िलॉसफ़र 🧦', body_hi = 'आज सुबह मोज़ा हाथ में पहनना चाहा? ज़िद के साथ आने वाले इन खोज के पलों पर गुस्सा मत कीजिए। उसे थोड़ी देर ऐसे ही घूमने दीजिए, यह उसकी आज़ादी का प्रयोग है।', title_id = 'Filsuf cilik di pagi hari 🧦', body_id = 'Pagi ini ia ingin memakai kaus kaki di tangannya? Jangan kesal pada momen penemuan yang disertai sikap keras kepala ini. Biarkan ia berjalan seperti itu sebentar, ini ujian kebebasannya.', title_ja = '朝の靴下さわぎ 🧦', body_ja = '今朝、靴下を手にはこうとしましたか？こだわりと一緒にやってくるこの発見の瞬間に、イライラしないで。少しそのまま歩かせてあげましょう。これは自由への挑戦です。', title_ko = '아침 양말 소동 🧦', body_ko = '오늘 아침 양말을 손에 끼겠다고 했나요? 고집이 섞인 이런 발견의 순간에 화내지 마세요. 잠시 그렇게 다니게 두세요. 자유를 시험해 보는 중이에요.', title_nl = 'Sokkengedoe in de ochtend 🧦', body_nl = 'Wilde hij vanochtend zijn sok om zijn hand doen? Erger je niet aan deze koppige ontdekkingsmomenten. Laat hem zo even rondlopen, het is zijn test van vrijheid.', title_pl = 'Poranny pokaz mody 🧦', body_pl = 'Dziś rano chciał założyć skarpetkę na rękę? Nie denerwuj się tymi chwilami odkryć połączonych z uporem. Niech tak trochę pochodzi, to jego test wolności.', title_pt = 'Filosofia da manhã 🧦', body_pt = 'Esta manhã quis calçar a meia na mão? Não se enerve com estes momentos de descoberta acompanhados de teimosia. Deixe-o andar assim um bocadinho: é o seu teste de liberdade.', title_sv = 'Morgonens filosof 🧦', body_sv = 'Ville barnet ha strumpan på handen i morse? Bli inte irriterad över dessa upptäckter som kommer med envishet. Låt barnet gå så en stund, det är ett test av friheten.', title_vi = 'Triết gia buổi sáng 🧦', body_vi = 'Sáng nay bé muốn đeo tất vào tay? Đừng bực mình với những khoảnh khắc khám phá đi kèm bướng bỉnh này. Cứ để bé đi như vậy một lúc, đó là bài thử nghiệm tự do của bé.', title_zh = '早晨的哲学家 🧦', body_zh = '今天早上想把袜子穿到手上？别为这些伴随着倔强的探索时刻生气。让宝宝就这样走一会儿吧，这是宝宝对自由的尝试。' WHERE id = '7af19435-be8e-48dc-a066-aab689899f04' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La fuerza mágica del agua 🛀', body_es = 'Después de correr todo el día, los dos estáis agotados. Un baño templado no es solo limpieza: es la mejor terapia para calmar su sistema nervioso.', title_fr = 'Le pouvoir magique de l''eau 🛀', body_fr = 'Après une journée à courir, vous êtes épuisés tous les deux. Un bain tiède, ce n''est pas que pour se laver : c''est la meilleure thérapie pour apaiser son système nerveux.', title_hi = 'पानी की जादुई ताकत 🛀', body_hi = 'दिनभर भागते-भागते वह भी और आप भी थक गए। गुनगुना स्नान सिर्फ़ सफ़ाई नहीं, उसके तंत्रिका तंत्र को शांत करने वाली सबसे अच्छी थेरेपी है।', title_id = 'Kekuatan ajaib air 🛀', body_id = 'Seharian berlari membuat ia dan Anda sama-sama kehabisan tenaga. Mandi air hangat bukan sekadar membersihkan badan, melainkan terapi terbaik untuk menenangkan sarafnya.', title_ja = '水の魔法の力 🛀', body_ja = '一日中走り回って、お子さんもあなたもくたくたですね。ぬるめのお風呂は体をきれいにするだけでなく、神経を落ち着かせてくれる最高のセラピーです。', title_ko = '물의 마법 같은 힘 🛀', body_ko = '하루 종일 뛰어다니느라 아이도 엄마도 지쳤어요. 따뜻한 목욕은 씻기만 하는 게 아니라 아이의 신경을 진정시키는 최고의 테라피예요.', title_nl = 'De magische kracht van water 🛀', body_nl = 'Jullie zijn allebei uitgeput van de hele dag rennen. Een lauw bad is niet alleen om schoon te worden, het is de beste therapie om zijn zenuwstelsel te kalmeren.', title_pl = 'Magiczna moc wody 🛀', body_pl = 'Po całym dniu bieganiny oboje jesteście wyczerpani. Ciepła kąpiel to nie tylko higiena, ale najlepsza terapia, która uspokaja jego układ nerwowy.', title_pt = 'A força mágica da água 🛀', body_pt = 'De tanto correr o dia todo, ficaram os dois esgotados. Um banho morno não é só higiene: é a melhor terapia para acalmar o sistema nervoso dele.', title_sv = 'Vattnets magiska kraft 🛀', body_sv = 'Både du och barnet är slut efter en hel dag av springande. Ett ljummet bad är inte bara för renlighetens skull, det är den bästa terapin för att lugna barnets nervsystem.', title_vi = 'Sức mạnh kỳ diệu của nước 🛀', body_vi = 'Chạy nhảy cả ngày khiến cả bé lẫn mẹ kiệt sức. Tắm nước ấm không chỉ để sạch sẽ mà còn là liệu pháp tốt nhất giúp làm dịu hệ thần kinh của bé.', title_zh = '水的神奇力量 🛀', body_zh = '跑了一整天，宝宝和你都累坏了。温水澡不只是为了清洁，也是让宝宝神经系统平静下来的最好疗法。' WHERE id = 'f13502d3-76f4-47c6-bfef-ed2cb1d9fcf7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Egoísmo en el parque 🧸', body_es = '¿Jugando en la arena no le deja su cubo a nadie? Hacia los 27 meses, la idea de compartir aún es muy débil. No le acuses de egoísta, simplemente explícale la regla de los turnos.', title_fr = 'Égoïsme au parc 🧸', body_fr = 'Dans le bac à sable, il ne prête son seau à personne ? Vers 27 mois, la notion de partage est encore très fragile. Ne l''accusez pas d''égoïsme, expliquez-lui simplement la règle du chacun son tour.', title_hi = 'पार्क में ''सब मेरा'' 🧸', body_hi = 'रेत में खेलते समय अपना बर्तन किसी को नहीं देता? 27 महीने के करीब बाँटने की समझ अभी बहुत कमज़ोर होती है। उस पर स्वार्थी होने का इल्ज़ाम मत लगाइए, बस बारी का नियम समझाइए।', title_id = 'Egois di taman 🧸', body_id = 'Tidak mau meminjamkan embernya kepada siapa pun saat bermain pasir? Konsep berbagi masih sangat lemah menjelang usia 27 bulan. Jangan menuduhnya egois, cukup jelaskan aturan bergiliran.', title_ja = '公園での「ひとりじめ」 🧸', body_ja = '砂場で遊んでいて、自分のバケツを誰にも貸さない？2歳3か月ごろは、分け合うという考えがまだとても未熟です。わがままだと責めずに、順番のルールを教えてあげましょう。', title_ko = '공원에서의 이기심 🧸', body_ko = '모래 놀이를 할 때 그릇을 아무에게도 안 주나요? 27개월 무렵에는 나누기 개념이 아직 약해요. 이기적이라고 탓하지 말고 차례 규칙을 알려 주세요.', title_nl = 'Egoïsme in het park 🧸', body_nl = 'Geeft hij bij het spelen in het zand zijn emmertje aan niemand? Het begrip delen is rond 27 maanden nog heel zwak. Noem hem niet egoïstisch, leg gewoon uit hoe om de beurt werkt.', title_pl = 'Egoizm w parku 🧸', body_pl = 'Bawiąc się w piaskownicy, nikomu nie daje swojego wiaderka? W okolicach 27. miesiąca pojęcie dzielenia się jest jeszcze bardzo słabe. Nie zarzucaj mu egoizmu, po prostu wytłumacz zasadę kolejki.', title_pt = 'Egoísmo no parque 🧸', body_pt = 'A brincar na areia, não empresta o balde a ninguém? Perto dos 27 meses, a noção de partilha ainda é muito fraca. Não o acuse de egoísmo, explique-lhe simplesmente a regra da vez.', title_sv = 'Egoism i parken 🧸', body_sv = 'Delar barnet inte med sig av sin hink till någon när hen leker i sanden? Förståelsen för att dela är fortfarande mycket svag mot 27 månader. Anklaga inte barnet för egoism, förklara bara turordningen.', title_vi = 'Ích kỷ ở công viên 🧸', body_vi = 'Chơi cát mà bé không đưa xô cho ai? Gần 27 tháng, khái niệm chia sẻ vẫn còn rất mờ nhạt. Đừng trách bé ích kỷ, hãy giải thích cho bé quy tắc chờ lượt.', title_zh = '公园里的“自私” 🧸', body_zh = '玩沙子时谁都不给自己的小桶？快到27个月时，分享的概念还很弱。别指责宝宝自私，只要解释一下轮流的规则就好。' WHERE id = '1b2a22e9-6d73-4469-8535-2d773936acd1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El tono de voz de papá 📖', body_es = 'Esta noche creemos otro ambiente en la habitación. Encarga a la voz grave y tranquilizadora de papá leer un libro o contar un cuento, y tú descansa a un lado.', title_fr = 'La voix de papa 📖', body_fr = 'Ce soir, créons une ambiance différente dans la chambre. Confiez la lecture ou le conte à la voix grave et rassurante de papa, et reposez-vous dans un coin.', title_hi = 'पापा की आवाज़ 📖', body_hi = 'आज शाम कमरे में कुछ अलग माहौल बनाइए। किताब पढ़ने या कहानी सुनाने का काम पापा की भारी, भरोसा देने वाली आवाज़ को सौंपिए और आप एक तरफ़ आराम कीजिए।', title_id = 'Nada suara Ayah 📖', body_id = 'Malam ini, ciptakan suasana yang berbeda di kamar. Serahkan tugas membaca buku atau bercerita kepada suara Ayah yang berat dan menenangkan, sementara Anda beristirahat di samping.', title_ja = 'パパの声のトーン 📖', body_ja = '今夜は部屋にいつもとちがう雰囲気をつくりましょう。絵本の読み聞かせやお話は、パパの低くて安心できる声にお任せして、あなたは少し離れて休みましょう。', title_ko = '아빠의 목소리 📖', body_ko = '오늘 저녁은 방에 색다른 분위기를 만들어 봐요. 책 읽기나 이야기 들려주기를 아빠의 굵고 든든한 목소리에 맡기고 엄마는 옆에서 쉬세요.', title_nl = 'Papa''s stem 📖', body_nl = 'Laten we vanavond een andere sfeer in de kamer maken. Laat het voorlezen of vertellen over aan de lage, geruststellende stem van papa en rust zelf even uit.', title_pl = 'Głos taty 📖', body_pl = 'Stwórzmy dziś wieczorem w pokoju inną atmosferę. Powierz czytanie książki lub opowiadanie bajki niskiemu, kojącemu głosowi taty, a sama odpocznij z boku.', title_pt = 'O tom de voz do pai 📖', body_pt = 'Esta noite, vamos criar um ambiente diferente no quarto. Deixe a tarefa de ler um livro ou contar uma história à voz grave e tranquilizadora do pai e descanse a um canto.', title_sv = 'Pappas röst 📖', body_sv = 'I kväll skapar vi en annan stämning i rummet. Låt pappas djupa, trygga röst sköta läsningen eller sagoberättandet medan du vilar en stund.', title_vi = 'Giọng nói của bố 📖', body_vi = 'Tối nay hãy tạo không khí khác trong phòng. Giao việc đọc sách hay kể chuyện cho giọng trầm ấm, đáng tin cậy của bố, còn mẹ thì nghỉ ngơi một bên.', title_zh = '爸爸的声音 📖', body_zh = '今晚给房间换一种氛围吧。把读书或讲故事的任务交给爸爸低沉又让人安心的声音，你在一旁休息。' WHERE id = '57e50587-fc65-4605-a4e9-bbde134adfea' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Una memoria perfecta 🧠', body_es = '¿Esta mañana ha encontrado justo donde estaba el juguete que escondiste ayer? Su memoria a largo plazo se ha desarrollado de forma increíble.', title_fr = 'Une mémoire parfaite 🧠', body_fr = 'Il a retrouvé ce matin, sans hésiter, le jouet que vous aviez caché hier ? Sa mémoire à long terme s''est incroyablement développée.', title_hi = 'कमाल की याददाश्त 🧠', body_hi = 'कल आपने जो खिलौना छिपाया था, आज सुबह उसकी जगह ठीक-ठीक ढूँढ ली? उसकी लंबे समय की याददाश्त कमाल की बन गई है।', title_id = 'Ingatan yang luar biasa 🧠', body_id = 'Pagi ini ia menemukan dengan tepat mainan yang Anda sembunyikan kemarin? Memori jangka panjangnya sudah terbentuk dengan luar biasa.', title_ja = 'すばらしい記憶力 🧠', body_ja = '昨日隠したおもちゃの場所を、今朝ぴたりと見つけましたか？長期記憶が驚くほど育っています。', title_ko = '놀라운 기억력 🧠', body_ko = '어제 숨겨 둔 장난감을 오늘 아침 정확히 찾아냈나요? 장기 기억력이 놀랍도록 자랐어요.', title_nl = 'Perfect geheugen 🧠', body_nl = 'Vond hij vanochtend precies het speeltje terug dat je gisteren had verstopt? Zijn langetermijngeheugen ontwikkelt zich ongelofelijk goed.', title_pl = 'Doskonała pamięć 🧠', body_pl = 'Dziś rano bezbłędnie znalazł zabawkę, którą wczoraj schowałaś? Jego pamięć długotrwała niesamowicie się rozwinęła.', title_pt = 'Memória perfeita 🧠', body_pt = 'Esta manhã encontrou com precisão o brinquedo que escondeu ontem? A memória de longo prazo está a formar-se de forma incrível.', title_sv = 'Perfekt minne 🧠', body_sv = 'Hittade barnet i morse exakt var du gömde leksaken i går? Långtidsminnet har utvecklats otroligt mycket.', title_vi = 'Trí nhớ tuyệt vời 🧠', body_vi = 'Sáng nay bé tìm chính xác chỗ món đồ chơi mẹ giấu hôm qua? Trí nhớ dài hạn của bé đã hình thành đáng kinh ngạc.', title_zh = '超强的记忆力 🧠', body_zh = '昨天你藏起来的玩具，今天早上一下就找到了？宝宝的长期记忆已经发展得惊人了。' WHERE id = '64f0ac54-c21f-4a4c-bcce-53662284a4f5' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Maratón de carreras 🏃‍♂️', body_es = 'Andar ya le aburre, ¡ahora solo corre! Quita los pequeños obstáculos del centro de la habitación y disfruta con una sonrisa de esta energía sin fin.', title_fr = 'Marathon de course 🏃‍♂️', body_fr = 'Marcher l''ennuie, maintenant il ne fait que courir ! Retirez les petits obstacles au milieu de la pièce et regardez en souriant cette énergie sans fin.', title_hi = 'दौड़ का मैराथन 🏃‍♂️', body_hi = 'चलना अब उसके लिए उबाऊ है, वह बस दौड़ता है! कमरे के बीच की छोटी-मोटी रुकावटें हटा दीजिए और इस कभी न खत्म होने वाली ऊर्जा को मुस्कुराकर देखिए।', title_id = 'Maraton lari 🏃‍♂️', body_id = 'Berjalan sudah membosankan baginya, ia hanya mau berlari! Singkirkan rintangan kecil di tengah ruangan dan nikmati energinya yang tak ada habisnya sambil tersenyum.', title_ja = 'マラソンランナー 🏃‍♂️', body_ja = '歩くのはもう退屈、走ってばかり！部屋の真ん中の小さな障害物を片付けて、この尽きないエネルギーを笑顔で見守りましょう。', title_ko = '달리기 마라톤 🏃‍♂️', body_ko = '이제 걷기는 지루해서 뛰기만 해요! 방 한가운데 자잘한 장애물을 치우고 이 끝없는 에너지를 미소로 지켜봐 주세요.', title_nl = 'Hardloopmarathon 🏃‍♂️', body_nl = 'Lopen vindt hij saai, hij rent alleen nog maar! Ruim kleine obstakels midden in de kamer op en kijk met een glimlach naar deze eindeloze energie.', title_pl = 'Maraton biegowy 🏃‍♂️', body_pl = 'Chodzenie już go nudzi, teraz tylko biega! Uprzątnij drobne przeszkody ze środka pokoju i z uśmiechem obserwuj tę niekończącą się energię.', title_pt = 'Maratona de corrida 🏃‍♂️', body_pt = 'Andar já é aborrecido para ele, agora só corre! Tire os pequenos obstáculos do meio do quarto e observe com um sorriso esta energia sem fim.', title_sv = 'Springmaraton 🏃‍♂️', body_sv = 'Att gå är redan tråkigt, barnet bara springer! Plocka undan små hinder mitt i rummet och följ den aldrig sinande energin med ett leende.', title_vi = 'Cuộc chạy marathon 🏃‍♂️', body_vi = 'Đi bộ giờ đã quá nhàm chán với bé, bé chỉ chạy thôi! Hãy dọn những vật cản nhỏ giữa phòng và mỉm cười ngắm nguồn năng lượng bất tận này.', title_zh = '奔跑马拉松 🏃‍♂️', body_zh = '走路对宝宝来说已经太无聊了，只想跑！把房间中间的小障碍物收拾好，微笑着看这股用不完的精力吧。' WHERE id = '1fe350a6-fb9b-4b57-8832-dec2f74e4b97' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juegos en la oscuridad 🐰', body_es = '¿No quiere dormirse y le da miedo la oscuridad? Oscurece del todo la habitación y haz sombras chinescas con las manos en la pared. Convierte el miedo en diversión.', title_fr = 'Jeux dans le noir 🐰', body_fr = 'Il ne veut pas dormir et a peur du noir ? Faites l''obscurité complète et créez un théâtre d''ombres avec vos mains sur le mur. Transformez la peur en jeu.', title_hi = 'अँधेरे के खेल 🐰', body_hi = 'सोना नहीं चाहता और अँधेरे से कतराता है? कमरे में पूरा अँधेरा कीजिए और दीवार पर हाथों से परछाइयों का खेल दिखाइए। डर को मज़े में बदल दीजिए।', title_id = 'Permainan dalam gelap 🐰', body_id = 'Tidak mau tidur dan takut gelap? Gelapkan kamar sepenuhnya dan buat teater bayangan dengan tangan Anda di dinding. Ubah rasa takut menjadi keseruan.', title_ja = '暗やみ遊び 🐰', body_ja = '眠りたがらず、暗いのをこわがりますか？部屋を真っ暗にして、手で壁に影絵をつくりましょう。こわさを楽しさに変えて。', title_ko = '어둠 속 놀이 🐰', body_ko = '잠들기 싫어하고 어둠을 무서워하나요? 방을 완전히 어둡게 하고 손으로 벽에 그림자 놀이를 해 보세요. 두려움을 재미로 바꿔 주세요.', title_nl = 'Spelletjes in het donker 🐰', body_nl = 'Wil hij niet slapen en is hij bang in het donker? Maak de kamer helemaal donker en speel met je handen schaduwtheater op de muur. Maak van angst een spelletje.', title_pl = 'Zabawy w ciemności 🐰', body_pl = 'Nie chce zasnąć i boi się ciemności? Całkiem zaciemnij pokój i zrób dłońmi teatr cieni na ścianie. Zamień strach w zabawę.', title_pt = 'Jogos no escuro 🐰', body_pt = 'Não quer adormecer e tem receio do escuro? Escureça o quarto por completo e faça com as mãos um teatro de sombras na parede. Transforme o medo em diversão.', title_sv = 'Lekar i mörkret 🐰', body_sv = 'Vill barnet inte somna och är rädd för mörkret? Mörklägg rummet helt och gör skuggteater med händerna på väggen. Gör rädslan till nöje.', title_vi = 'Trò chơi trong bóng tối 🐰', body_vi = 'Bé không muốn ngủ và ngại bóng tối? Hãy tắt hết đèn và dùng tay làm kịch bóng trên tường. Biến nỗi sợ thành niềm vui.', title_zh = '黑暗中的游戏 🐰', body_zh = '不想睡觉，还怕黑？把房间完全调暗，用双手在墙上玩手影戏。把恐惧变成乐趣。' WHERE id = 'a661f7cf-1a9f-46de-b66d-252b9874aa1c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La hora offline de mamá ☕', body_es = 'Mientras está en su mundo hablando con sus muñecos, no corras al lavavajillas. Sírvete un café, deja el móvil a un lado 15 minutos y desconecta del todo.', title_fr = 'L''heure hors ligne de maman ☕', body_fr = 'Quand il est plongé dans son monde à parler à ses poupées, ne courez pas tout de suite au lave-vaisselle. Servez-vous un café, posez aussi votre téléphone 15 minutes et déconnectez complètement.', title_hi = 'माँ का ऑफ़लाइन समय ☕', body_hi = 'जब बच्चा अपनी दुनिया में खोकर गुड़ियों से बातें कर रहा हो, तुरंत बर्तन धोने मत भागिए। अपने लिए एक कॉफ़ी डालिए और 15 मिनट फ़ोन भी अलग रखकर पूरी तरह ऑफ़लाइन हो जाइए।', title_id = 'Jam offline Bunda ☕', body_id = 'Saat si kecil asyik di dunianya sendiri sambil mengobrol dengan bonekanya, jangan langsung lari ke cucian piring. Tuang secangkir kopi, singkirkan ponsel selama 15 menit, dan benar-benar offline.', title_ja = 'ママのオフラインタイム ☕', body_ja = 'お子さんが自分の世界に入りこんで人形とおしゃべりしている間、すぐに食器洗いに走らないで。コーヒーをいれて、15分間スマホも置いて、完全にオフラインになりましょう。', title_ko = '엄마의 오프라인 시간 ☕', body_ko = '아이가 자기 세상에 빠져 인형과 이야기할 때 바로 설거지하러 달려가지 마세요. 커피 한 잔을 따르고 15분 동안 휴대폰도 내려놓고 완전히 오프라인이 되어 보세요.', title_nl = 'Offline uurtje van mama ☕', body_nl = 'Is hij in zijn eigen wereld aan het praten met zijn poppen? Ren niet meteen naar de vaatwasser. Schenk een kop koffie in, leg je telefoon 15 minuten weg en ga helemaal offline.', title_pl = 'Godzina offline mamy ☕', body_pl = 'Gdy maluch zatopi się w swoim świecie i rozmawia z lalkami, nie biegnij od razu do zmywarki. Nalej sobie kawy, odłóż telefon na 15 minut i bądź całkowicie offline.', title_pt = 'A hora offline da mãe ☕', body_pt = 'Enquanto ele está mergulhado no seu mundo a falar com os bonecos, não corra logo para a máquina da loiça. Sirva-se de um café, ponha o telemóvel de lado 15 minutos e fique totalmente offline.', title_sv = 'Mammas offlinetimme ☕', body_sv = 'Rusa inte direkt till diskmaskinen när barnet är försjunket i sin egen värld och pratar med dockorna. Häll upp en kopp kaffe, lägg undan telefonen i 15 minuter och var helt offline.', title_vi = 'Giờ "offline" của mẹ ☕', body_vi = 'Khi bé đang mải trò chuyện với búp bê trong thế giới riêng, đừng vội lao vào rửa bát. Hãy rót cho mình một ly cà phê, cất cả điện thoại đi và hoàn toàn "offline" trong 15 phút.', title_zh = '妈妈的离线时间 ☕', body_zh = '孩子沉浸在自己的世界里和娃娃说话时，别马上冲去洗碗。给自己倒杯咖啡，把手机也放到一边15分钟，彻底离线吧。' WHERE id = 'a8a8e76c-4244-41ff-a34c-127f03070b5f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Las primeras frases largas 🗣️', body_es = '«¡Mamá, el coche se ha ido allí!» Ya encadena palabras para formar frases con sentido. Escucha estos momentos históricos y guárdalos sin falta como recuerdo en el Seguimiento del desarrollo.', title_fr = 'Premières longues phrases 🗣️', body_fr = '« Maman, la voiture est partie là-bas ! » Il enchaîne maintenant les mots pour faire de vraies phrases. Écoutez ces moments historiques et notez-les absolument en souvenir dans le Suivi de développement.', title_hi = 'पहले लंबे वाक्य 🗣️', body_hi = '''माँ, गाड़ी वहाँ गई!'' अब वह शब्दों को एक के बाद एक जोड़कर मतलब वाले वाक्य बनाता है। इन ऐतिहासिक पलों को सुनिए और ग्रोथ ट्रैकर में याद के रूप में ज़रूर लिखिए।', title_id = 'Kalimat panjang pertama 🗣️', body_id = 'Ma, mobilnya pergi ke sana! Ia sudah merangkai kata menjadi kalimat yang bermakna. Dengarkan momen bersejarah ini dan pastikan mencatatnya sebagai kenangan di Pelacak Perkembangan.', title_ja = 'はじめての長い文 🗣️', body_ja = '「ママ、くるま、あっちいった！」言葉を順番に並べて、意味のある文をつくっています。この歴史的な瞬間に耳を傾けて、ぜひ思い出として「発達トラッカー」に書きましょう。', title_ko = '첫 긴 문장 🗣️', body_ko = '''엄마, 차가 저기 갔어!'' 이제 단어를 이어 뜻이 통하는 문장을 만들어요. 이 역사적인 순간을 귀 기울여 듣고 성장 기록에 꼭 추억으로 남기세요.', title_nl = 'De eerste lange zinnen 🗣️', body_nl = 'Mama, auto daar heen! Hij zet woorden al achter elkaar tot zinnen met betekenis. Luister naar deze historische momenten en schrijf ze zeker als herinnering in de Groeitracker.', title_pl = 'Pierwsze długie zdania 🗣️', body_pl = '„Mama, auto pojechało tam!” Już układa słowa jedno po drugim w sensowne zdania. Wsłuchaj się w te historyczne chwile i koniecznie zapisz je na pamiątkę w Śledzeniu rozwoju.', title_pt = 'As primeiras frases longas 🗣️', body_pt = '"Mamã, o carro foi para ali!" Já junta palavras umas atrás das outras e forma frases com sentido. Ouça estes momentos históricos e registe-os sem falta no Registo de Desenvolvimento como recordação.', title_sv = 'De första långa meningarna 🗣️', body_sv = '”Mamma, bilen åkte dit!” Barnet sätter redan ihop ord efter varandra till meningsfulla meningar. Lyssna på dessa historiska stunder och skriv ner dem som minnen i Utvecklingsspåraren.', title_vi = 'Những câu dài đầu tiên 🗣️', body_vi = '"Mẹ ơi, xe đi đằng kia!" Bé đã xếp các từ nối tiếp nhau thành câu có nghĩa. Hãy lắng nghe những khoảnh khắc lịch sử này và nhất định ghi vào Theo dõi phát triển làm kỷ niệm.', title_zh = '第一批长句子 🗣️', body_zh = '“妈妈，车车开到那里了！”宝宝已经能把词一个接一个排起来，说出有意义的句子了。听听这些历史性的时刻，一定要作为纪念写进发育追踪。' WHERE id = '41bea9aa-47ca-48e8-8cd4-15b1a0a181a6' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pausa de blog 📱', body_es = '¿Es el momento adecuado para empezar a dejar el pañal? Si tienes dudas, entra en el Blog de la app Anacan y lee artículos escritos por especialistas y aprobados por pediatras.', title_fr = 'Pause blog 📱', body_fr = 'Est-ce le bon moment pour commencer l''apprentissage du pot ? Si vous hésitez, ouvrez la rubrique Blogs de l''appli Anacan et lisez les articles d''experts validés par des pédiatres.', title_hi = 'ब्लॉग ब्रेक 📱', body_hi = 'क्या पॉटी ट्रेनिंग शुरू करने का यह सही समय है? अगर दुविधा है, तो Anacan ऐप के ब्लॉग सेक्शन में जाइए और एक्सपर्ट्स के लिखे, बाल रोग विशेषज्ञ द्वारा जाँचे गए लेख पढ़िए।', title_id = 'Rehat sejenak dengan Blog 📱', body_id = 'Apakah ini waktu yang tepat untuk memulai latihan pispot? Jika ragu, buka bagian Blog di aplikasi Anacan dan baca artikel yang ditulis para ahli dan disetujui dokter anak.', title_ja = 'ブログでひと休み 📱', body_ja = 'トイレトレーニングを始めるのにいいタイミング？迷っているなら、Anacanアプリのブログを開いて、専門家が書いた小児科医も認める記事を読んでみましょう。', title_ko = '블로그 타임 📱', body_ko = '지금이 배변 훈련을 시작할 때일까요? 망설여진다면 Anacan 앱의 블로그에서 전문가가 쓰고 소아과 의사가 검토한 글을 읽어 보세요.', title_nl = 'Even naar Blogs 📱', body_nl = 'Is het het juiste moment om met zindelijkheidstraining te beginnen? Twijfel je, ga dan naar Blogs in de Anacan-app en lees artikelen van experts, goedgekeurd door kinderartsen.', title_pl = 'Przerwa na Blog 📱', body_pl = 'Czy to dobry moment, by zacząć naukę korzystania z nocnika? Jeśli masz wątpliwości, zajrzyj do sekcji Blog w aplikacji Anacan i przeczytaj zatwierdzone przez pediatrów artykuły ekspertów.', title_pt = 'Uma pausa nos Blogues 📱', body_pt = 'Será a altura certa para começar o treino do bacio? Se tem dúvidas, entre na secção Blogues da app Anacan e leia artigos escritos por especialistas e validados por pediatras.', title_sv = 'Bloggpaus 📱', body_sv = 'Är det rätt tid att börja med pottträning? Är du osäker, gå till Bloggar i Anacan-appen och läs artiklar skrivna av experter och godkända av barnläkare.', title_vi = 'Giờ đọc blog 📱', body_vi = 'Đã đúng lúc bắt đầu tập ngồi bô chưa? Nếu còn phân vân, hãy vào mục Blog của ứng dụng Anacan và đọc các bài viết do chuyên gia viết, được bác sĩ nhi khoa thẩm định.', title_zh = '博客时间 📱', body_zh = '现在是开始如厕训练的合适时机吗？如果拿不准，就去Anacan应用的博客板块，读读专家撰写、儿科医生认可的文章。' WHERE id = '69b61ce4-2f0a-419f-8ea0-47c763ae7f20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Análisis del día 📝', body_es = '¿Ha sido un día difícil? Desahógate escribiendo todo el estrés de hoy en el Diario de ánimo. Todas las madres pasan por estas crisis tan duras, no estás sola.', title_fr = 'Le bilan du jour 📝', body_fr = 'Journée difficile ? Videz-vous la tête en écrivant tout le stress du jour dans le Journal d''humeur. Toutes les mamans vivent ces grosses crises, vous n''êtes pas seule.', title_hi = 'आज का विश्लेषण 📝', body_hi = 'मुश्किल दिन था? आज का सारा तनाव मूड डायरी में लिखकर मन हल्का कीजिए। हर माँ इन भारी पलों से गुज़रती है, आप अकेली नहीं हैं।', title_id = 'Analisis hari ini 📝', body_id = 'Hari yang berat? Lepaskan beban dengan menuliskan semua stres hari ini di Buku Harian Suasana Hati. Semua ibu pernah mengalami masa sulit seperti ini, Anda tidak sendirian.', title_ja = '一日のふり返り 📝', body_ja = '大変な一日でしたか？「気分日記」に今日のストレスを全部書いて、気持ちを軽くしましょう。どのママもこうした大変なかんしゃくを経験しています。あなたはひとりではありません。', title_ko = '오늘 돌아보기 📝', body_ko = '힘든 하루였나요? 기분 일기에 오늘의 스트레스를 모두 적으며 마음을 비워 보세요. 모든 엄마가 이런 힘든 순간을 겪어요. 혼자가 아니에요.', title_nl = 'Analyse van de dag 📝', body_nl = 'Was het een zware dag? Schrijf alle stress van vandaag van je af in je Stemmingsdagboek. Alle moeders maken zulke zware buien mee, je staat er niet alleen voor.', title_pl = 'Analiza dnia 📝', body_pl = 'To był trudny dzień? Wypisz cały dzisiejszy stres w Dzienniku nastroju i ulżyj sobie. Każda mama przeżywa takie ciężkie kryzysy, nie jesteś sama.', title_pt = 'Análise do dia 📝', body_pt = 'Foi um dia difícil? Desabafe escrevendo todo o stress de hoje no Diário de Humor. Todas as mães passam por estas crises duras, não está sozinha.', title_sv = 'Dagens analys 📝', body_sv = 'Har det varit en tuff dag? Skriv av dig all dagens stress i Humördagboken. Alla mammor går igenom sådana tunga utbrott, du är inte ensam.', title_vi = 'Nhìn lại một ngày 📝', body_vi = 'Hôm nay vất vả quá? Hãy viết hết căng thẳng hôm nay vào Nhật ký tâm trạng cho nhẹ lòng. Mẹ nào cũng trải qua những cơn khủng hoảng nặng nề này, mẹ không đơn độc đâu.', title_zh = '今日回顾 📝', body_zh = '今天很难熬？把今天所有的压力写进心情日记，让心里轻松一些。每个妈妈都经历过这些艰难的崩溃，你并不孤单。' WHERE id = '8ba7811e-fc92-4ddc-b1e8-28de83aa7843' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rechaza el agua 💧', body_es = '¿En lugar de agua, siempre pide zumos dulces? Calcula cuánta agua necesita al día y ofrécesela en vasos de colores y divertidos.', title_fr = 'Il refuse l''eau 💧', body_fr = 'Il réclame sans cesse des jus sucrés au lieu de l''eau ? Calculez ses besoins en eau de la journée et proposez-lui l''eau dans des gobelets colorés et amusants.', title_hi = 'पानी से इनकार 💧', body_hi = 'पानी की जगह हमेशा मीठा जूस चाहता है? उसकी रोज़ की पानी की ज़रूरत गिनिए और पानी रंग-बिरंगे, दिलचस्प गिलासों में दीजिए।', title_id = 'Menolak minum air 💧', body_id = 'Terus minta jus manis, bukan air? Hitung kebutuhan air hariannya dan tawarkan air dalam gelas yang berwarna-warni dan menarik.', title_ja = 'お水を嫌がる 💧', body_ja = 'お水の代わりに甘いジュースばかりほしがりますか？1日に必要な水分量を計算して、カラフルでおもしろいコップでお水をすすめてみましょう。', title_ko = '물을 거부해요 💧', body_ko = '물 대신 계속 단 주스만 찾나요? 하루 물 필요량을 계산하고, 알록달록하고 재미있는 컵에 물을 담아 주세요.', title_nl = 'Weigert hij water? 💧', body_nl = 'Wil hij steeds zoete sapjes in plaats van water? Bereken hoeveel water hij per dag nodig heeft en bied water aan in kleurrijke, leuke bekers.', title_pl = 'Odmawia wody 💧', body_pl = 'Zamiast wody ciągle chce słodkich soków? Oblicz jego dzienne zapotrzebowanie na wodę i podawaj ją w kolorowych, ciekawych kubkach.', title_pt = 'Recusa beber água 💧', body_pt = 'Em vez de água, quer sempre sumos doces? Calcule as necessidades diárias de água dele e ofereça-lhe a água em copos coloridos e apelativos.', title_sv = 'Vägrar vatten 💧', body_sv = 'Vill barnet hela tiden ha söt juice i stället för vatten? Räkna ut barnets dagliga vattenbehov och servera vattnet i färgglada, roliga muggar.', title_vi = 'Không chịu uống nước 💧', body_vi = 'Bé cứ đòi nước ép ngọt thay vì nước lọc? Hãy tính nhu cầu nước hằng ngày của bé và mời bé uống nước trong những chiếc cốc nhiều màu sắc, thú vị.', title_zh = '不肯喝水 💧', body_zh = '总想喝甜果汁，不想喝水？算一算宝宝每天需要多少水，用色彩鲜艳、有趣的杯子来装水吧。' WHERE id = '3932254a-4956-424d-86dc-117f82815e3f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Historias inventadas 🎭', body_es = '¿Hace hablar a su osito y le cuenta historias inventadas? ¡Su imaginación vuela! Obsérvale desde fuera y no intervengas.', title_fr = 'Histoires inventées 🎭', body_fr = 'Il fait parler son nounours et lui raconte des histoires inventées ? Son imagination s''envole ! Observez-le de loin et n''intervenez pas.', title_hi = 'गढ़ी हुई कहानियाँ 🎭', body_hi = 'हाथ के टेडी बियर से बातें करवाता है और उसे गढ़ी हुई कहानियाँ सुनाता है? कल्पना ऊँची उड़ान भर रही है! दूर से देखिए और बिल्कुल दखल मत दीजिए।', title_id = 'Cerita karangan 🎭', body_id = 'Membuat boneka beruangnya berbicara dan menceritakan kisah karangannya? Imajinasinya melambung tinggi! Amati dari jauh dan jangan ikut campur.', title_ja = 'つくり話 🎭', body_ja = '手に持ったくまさんにお話しさせたり、つくり話を聞かせたりしていますか？想像力が羽ばたいています！少し離れて見守り、口をはさまないでおきましょう。', title_ko = '지어낸 이야기 🎭', body_ko = '곰 인형에게 말을 시키며 지어낸 이야기를 들려주나요? 상상력이 하늘을 찌르고 있어요! 멀리서 지켜보며 끼어들지 마세요.', title_nl = 'Verzonnen verhalen 🎭', body_nl = 'Laat hij zijn beer praten en vertelt hij hem verzonnen verhalen? Zijn fantasie vliegt omhoog! Kijk van een afstand toe en bemoei je er niet mee.', title_pl = 'Wymyślone historie 🎭', body_pl = 'Każe misiowi mówić i opowiada mu wymyślone historie? Wyobraźnia szybuje! Obserwuj go z boku i w nic się nie wtrącaj.', title_pt = 'Histórias inventadas 🎭', body_pt = 'Põe o ursinho a falar e conta-lhe histórias inventadas? A imaginação está a voar alto! Observe-o de longe e não interfira.', title_sv = 'Påhittade berättelser 🎭', body_sv = 'Låter barnet nallen prata och berättar påhittade historier för den? Fantasin flödar! Titta på från sidan och lägg dig inte i alls.', title_vi = 'Những câu chuyện bịa 🎭', body_vi = 'Bé cho gấu bông nói chuyện và kể những câu chuyện do mình nghĩ ra? Trí tưởng tượng đang bay cao! Hãy quan sát từ xa và đừng can thiệp gì nhé.', title_zh = '编出来的故事 🎭', body_zh = '让手里的小熊说话，给它讲编出来的故事？想象力正在腾飞！在一旁看着就好，不要打扰。' WHERE id = '7f344552-48d5-4a0e-95d3-b9aa7199f33a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Sin cuento no se duerme 🪄', body_es = '¿Los cuentos clásicos ya no le llaman la atención? Crea en Cuentos inteligentes un cuento especial en el que el héroe sea tu peque.', title_fr = 'Pas de dodo sans conte 🪄', body_fr = 'Les contes classiques ne captent plus son attention ? Créez dans les Contes intelligents une histoire spéciale dont il est le héros.', title_hi = 'बिना कहानी के नींद नहीं 🪄', body_hi = 'पुरानी कहानियाँ अब उसका ध्यान नहीं खींचतीं? स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो वह खुद हो।', title_id = 'Tak bisa tidur tanpa dongeng 🪄', body_id = 'Dongeng klasik tak lagi menarik perhatiannya? Buat dongeng istimewa di Dongeng Pintar dengan dirinya sebagai tokoh utama.', title_ja = 'お話がないと眠れない 🪄', body_ja = '昔話にはもう興味を示さない？「スマートおはなし」で、お子さんが主人公の特別なお話をつくりましょう。', title_ko = '동화 없이는 못 자요 🪄', body_ko = '고전 동화에는 더 이상 관심이 없나요? 스마트 동화에서 아이가 주인공인 특별한 이야기를 만들어 보세요.', title_nl = 'Niet slapen zonder sprookje 🪄', body_nl = 'Trekken klassieke sprookjes zijn aandacht niet meer? Maak in Slimme sprookjes een speciaal sprookje met hemzelf als held.', title_pl = 'Bez bajki nie zasypiamy 🪄', body_pl = 'Klasyczne bajki już go nie wciągają? Stwórz w Mądrych bajkach wyjątkową bajkę, w której to on jest bohaterem.', title_pt = 'Sem história não se dorme 🪄', body_pt = 'As histórias clássicas já não lhe prendem a atenção? Crie nas Histórias Inteligentes uma história especial em que o herói é ele próprio.', title_sv = 'Ingen sömn utan saga 🪄', body_sv = 'Fångar klassiska sagor inte längre barnets uppmärksamhet? Skapa en speciell saga i Smarta sagor där barnet själv är hjälten.', title_vi = 'Không có truyện thì không ngủ 🪄', body_vi = 'Truyện cổ tích kinh điển không còn thu hút bé? Hãy tạo một câu chuyện đặc biệt với nhân vật chính là bé trong Truyện cổ tích thông minh.', title_zh = '没有故事不睡觉 🪄', body_zh = '经典童话已经吸引不了宝宝了？在智能故事里创作一个以宝宝自己为主角的特别故事吧。' WHERE id = 'eda9b33e-46f7-44ed-b1db-b9ad146b53a3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El desorden es bonito 🌪️', body_es = '¿Cansada de recoger cada día los mismos juguetes en la caja? ¡Hoy no los recojas! Una casa desordenada no es el fin del mundo: tu bienestar psicológico es más importante.', title_fr = 'Le désordre, c''est beau 🌪️', body_fr = 'Fatiguée de ranger chaque jour les mêmes jouets dans le coffre ? Aujourd''hui, ne rangez pas ! Une maison en désordre n''est pas la fin du monde, votre bien-être psychologique compte davantage.', title_hi = 'बिखराव भी खूबसूरत है 🌪️', body_hi = 'रोज़ एक ही खिलौने डिब्बे में समेटते-समेटते थक गईं? आज मत समेटिए! बिखरा घर दुनिया का अंत नहीं है, आपका मानसिक सुकून ज़्यादा ज़रूरी है।', title_id = 'Berantakan itu indah 🌪️', body_id = 'Lelah membereskan mainan yang sama ke dalam kotak setiap hari? Hari ini tidak usah! Rumah berantakan bukan akhir dunia, ketenangan pikiran Anda jauh lebih penting.', title_ja = '散らかっていてもすてき 🌪️', body_ja = '毎日同じおもちゃを箱に片付けるのに疲れましたか？今日は片付けないで！家が散らかっていても世界の終わりではありません。あなたの心のゆとりのほうが大切です。', title_ko = '어질러진 집도 괜찮아요 🌪️', body_ko = '매일 같은 장난감을 상자에 담느라 지쳤나요? 오늘은 치우지 마세요! 어질러진 집이 세상의 끝은 아니에요. 엄마의 마음 편안함이 더 중요해요.', title_nl = 'Rommel is mooi 🌪️', body_nl = 'Ben je het zat om elke dag hetzelfde speelgoed in de doos te doen? Ruim vandaag niet op! Een rommelig huis is niet het einde van de wereld, jouw rust is belangrijker.', title_pl = 'Bałagan jest piękny 🌪️', body_pl = 'Masz dość codziennego wkładania tych samych zabawek do pudełka? Dziś ich nie zbieraj! Bałagan w domu to nie koniec świata, twój spokój psychiczny jest ważniejszy.', title_pt = 'A desarrumação é bonita 🌪️', body_pt = 'Cansada de arrumar todos os dias os mesmos brinquedos na caixa? Hoje não arrume! Uma casa desarrumada não é o fim do mundo, o seu bem-estar psicológico é mais importante.', title_sv = 'Röran är vacker 🌪️', body_sv = 'Trött på att plocka in samma leksaker i lådan varje dag? Plocka inte undan i dag! Ett stökigt hem är inte världens undergång, ditt psykiska välbefinnande är viktigare.', title_vi = 'Bừa bộn cũng đẹp 🌪️', body_vi = 'Mẹ mệt vì ngày nào cũng dọn đồ chơi vào hộp? Hôm nay đừng dọn! Nhà bừa bộn không phải ngày tận thế, sự thoải mái tinh thần của mẹ quan trọng hơn.', title_zh = '乱也是一种美 🌪️', body_zh = '每天把同样的玩具收进盒子，收累了？今天就别收了！家里乱一点不是世界末日，你的心理舒适更重要。' WHERE id = '67860791-a8d9-49e2-af36-c3429ea56929' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '10 minutos a solas 🛀', body_es = 'La calma reina en la habitación. Pide a tu pareja que se encargue de todo en casa. Tú date una ducha caliente y quédate 10 minutos a solas contigo misma.', title_fr = '10 minutes rien que pour vous 🛀', body_fr = 'Le silence est tombé dans la chambre. Demandez à votre conjoint de tout gérer à la maison. Vous, prenez une douche chaude et passez 10 minutes en tête-à-tête avec vous-même.', title_hi = 'अकेले में 10 मिनट 🛀', body_hi = 'कमरे में खामोशी छा गई। अपने जीवनसाथी से कहिए कि घर की हर चीज़ वे संभालें। और आप गर्म पानी से नहाकर 10 मिनट बस खुद के साथ बिताइए।', title_id = '10 menit sendirian 🛀', body_id = 'Kamar sudah hening. Minta pasangan Anda mengurus semua hal di rumah. Anda mandi air hangat dan nikmati 10 menit hanya untuk diri sendiri.', title_ja = 'ひとりで10分 🛀', body_ja = '部屋に静けさが訪れました。パートナーに家のことを全部お願いしましょう。あなたは温かいシャワーを浴びて、10分間、自分だけの時間を過ごしましょう。', title_ko = '나만의 10분 🛀', body_ko = '방이 조용해졌어요. 배우자에게 집안일을 모두 맡겨 달라고 부탁하고, 따뜻한 샤워를 하며 10분 동안 오롯이 나와 함께하세요.', title_nl = '10 minuten voor jezelf 🛀', body_nl = 'Het is stil in de kamer. Vraag je partner om alles in huis te regelen. Neem jij een warme douche en wees 10 minuten helemaal alleen met jezelf.', title_pl = '10 minut tylko dla siebie 🛀', body_pl = 'W pokoju zapadła cisza. Poproś partnera, by zajął się wszystkim w domu. A ty weź ciepły prysznic i przez 10 minut pobądź sam na sam ze sobą.', title_pt = '10 minutos sozinha 🛀', body_pt = 'O silêncio chegou ao quarto. Peça ao seu companheiro que trate de tudo em casa. Tome um duche quente e fique 10 minutos só consigo própria.', title_sv = '10 minuter för dig själv 🛀', body_sv = 'Det har blivit tyst i rummet. Be din partner ta hand om allt hemma. Ta en varm dusch och var ensam med dig själv i 10 minuter.', title_vi = '10 phút một mình 🛀', body_vi = 'Căn phòng đã yên tĩnh. Hãy nhờ bố lo mọi việc trong nhà. Còn mẹ thì tắm nước ấm và dành 10 phút ở riêng với chính mình.', title_zh = '独处10分钟 🛀', body_zh = '房间里安静下来了。请另一半来照看家里的一切，你去洗个热水澡，和自己独处10分钟。' WHERE id = 'a0432486-9631-45f3-ac61-64c5dc937b54' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El calcio no es solo leche 🧀', body_es = '¿No quiere beber leche? El calcio es imprescindible para los huesos. Calcula con el Seguimiento de tomas el queso, el yogur o el brócoli de hoy y completa lo que falte.', title_fr = 'Le calcium, ce n''est pas que le lait 🧀', body_fr = 'Il refuse de boire du lait ? Le calcium est indispensable aux os. Calculez avec le Suivi des repas ce qu''il a mangé de fromage, de yaourt ou de brocoli aujourd''hui et comblez les manques.', title_hi = 'कैल्शियम सिर्फ़ दूध में नहीं 🧀', body_hi = 'दूध पीने से मना करता है? हड्डियों के लिए कैल्शियम ज़रूरी है। फ़ीडिंग ट्रैकर से आज का पनीर, दही या ब्रोकली गिनिए और कमी पूरी कीजिए।', title_id = 'Kalsium bukan hanya dari susu 🧀', body_id = 'Menolak minum susu? Kalsium wajib untuk tulang. Hitung asupan keju, yogurt, atau brokoli hari ini dengan alat Pemantau Nutrisi dan lengkapi kekurangannya.', title_ja = 'カルシウムは牛乳だけじゃない 🧀', body_ja = '牛乳を飲みたがらない？骨にはカルシウムが欠かせません。「栄養管理ツール」で今日のチーズ、ヨーグルト、ブロッコリーの量を計算して、足りない分を補いましょう。', title_ko = '칼슘은 우유만이 아니에요 🧀', body_ko = '우유를 안 마시려 하나요? 뼈에는 칼슘이 꼭 필요해요. 수유 기록 도구로 오늘 치즈, 요거트, 브로콜리 섭취를 계산하고 부족한 만큼 채워 주세요.', title_nl = 'Calcium is niet alleen melk 🧀', body_nl = 'Wil hij geen melk drinken? Calcium is onmisbaar voor de botten. Bereken met de Voedingstracker de kaas, yoghurt of broccoli van vandaag en vul tekorten aan.', title_pl = 'Wapń to nie tylko mleko 🧀', body_pl = 'Nie chce pić mleka? Wapń jest niezbędny dla kości. Oblicz w narzędziu do śledzenia karmienia dzisiejsze spożycie sera, jogurtu lub brokułów i uzupełnij braki.', title_pt = 'Cálcio não é só leite 🧀', body_pt = 'Recusa beber leite? O cálcio é indispensável para os ossos. Calcule com o Registo de Alimentação o queijo, o iogurte ou os brócolos de hoje e complete o que faltar.', title_sv = 'Kalcium är inte bara mjölk 🧀', body_sv = 'Vägrar barnet dricka mjölk? Kalcium är ett måste för skelettet. Räkna ut dagens intag av ost, yoghurt eller broccoli med Matningskoll och fyll på det som fattas.', title_vi = 'Canxi không chỉ có trong sữa 🧀', body_vi = 'Bé không chịu uống sữa? Canxi rất cần cho xương. Hãy tính lượng phô mai, sữa chua hoặc bông cải xanh hôm nay bằng Theo dõi cữ bú và bổ sung phần thiếu.', title_zh = '钙不只来自牛奶 🧀', body_zh = '不肯喝奶？骨骼离不开钙。用喂养记录工具算一算今天奶酪、酸奶或西兰花的摄入量，补上不足的部分。' WHERE id = 'fc396394-677d-4b99-a945-20af7aec5056' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Club de apoyo 💬', body_es = '¿Estás muy cansada y sientes que nadie te entiende? Escribe ya en la Comunidad Anacan. Allí, miles de madres que pasan las mismas noches sin dormir te apoyarán.', title_fr = 'Le club de la solidarité 💬', body_fr = 'Vous êtes épuisée et vous avez l''impression que personne ne vous comprend ? Écrivez tout de suite dans la Communauté Anacan. Des milliers de mamans qui manquent de sommeil comme vous vous soutiendront.', title_hi = 'साथ देने वालों का क्लब 💬', body_hi = 'बहुत थक गई हैं और लगता है कि कोई आपको समझता नहीं? तुरंत Anacan कम्युनिटी में लिखिए। वहाँ आप जैसी ही नींद की कमी झेलने वाली हज़ारों माँएँ आपका साथ देंगी।', title_id = 'Klub saling mendukung 💬', body_id = 'Sangat lelah dan merasa tak ada yang memahami? Segera tulis ke Komunitas Anacan. Di sana ribuan ibu yang juga kurang tidur akan mendukung Anda.', title_ja = '支え合いのクラブ 💬', body_ja = 'とても疲れて、誰にもわかってもらえないと感じますか？すぐにAnacanコミュニティに書き込みましょう。同じように眠れない夜を過ごしている何千人ものママが、あなたを支えてくれます。', title_ko = '서로를 응원하는 모임 💬', body_ko = '너무 지치고 아무도 나를 이해하지 못하는 것 같나요? 바로 Anacan 커뮤니티에 글을 남기세요. 똑같이 잠 못 드는 수많은 엄마들이 응원해 줄 거예요.', title_nl = 'Club van steun 💬', body_nl = 'Ben je erg moe en heb je het gevoel dat niemand je begrijpt? Schrijf meteen in de Anacan Community. Daar steunen duizenden moeders die net zo weinig slapen jou.', title_pl = 'Klub wsparcia 💬', body_pl = 'Jesteś bardzo zmęczona i czujesz, że nikt cię nie rozumie? Od razu napisz w Społeczności Anacan. Tysiące mam, które tak samo nie dosypiają, cię wesprą.', title_pt = 'Clube de solidariedade 💬', body_pt = 'Está muito cansada e sente que ninguém a compreende? Escreva já na Comunidade Anacan. Lá, milhares de mães que passam pelas mesmas noites sem dormir vão apoiá-la.', title_sv = 'Gemenskapsklubben 💬', body_sv = 'Är du väldigt trött och känner dig oförstådd? Skriv direkt i Anacans Community. Där finns tusentals mammor med samma sömnbrist som stöttar dig.', title_vi = 'Câu lạc bộ đồng cảm 💬', body_vi = 'Mẹ quá mệt và nghĩ rằng không ai hiểu mình? Hãy viết ngay vào Cộng đồng Anacan. Ở đó hàng nghìn bà mẹ cũng đang mất ngủ như mẹ sẽ ủng hộ mẹ.', title_zh = '互助俱乐部 💬', body_zh = '累坏了，觉得没人理解你？马上在Anacan社区发帖。那里有成千上万同样睡不好的妈妈会支持你。' WHERE id = '40c67b1f-86cb-4258-ae34-ac9f630e9bcd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Tozudez sin lógica 🛑', body_es = '¿Esta mañana se montó un drama porque le diste el agua en el vaso rojo y no en el azul? No es un capricho: solo está comprobando si puede controlar el mundo. Ten paciencia.', title_fr = 'Entêtements illogiques 🛑', body_fr = 'Tout a explosé ce matin parce que vous avez servi l''eau dans le gobelet rouge et pas le bleu ? Ce n''est pas un caprice, il vérifie simplement qu''il peut contrôler le monde. Soyez patiente.', title_hi = 'बेतुकी ज़िदें 🛑', body_hi = 'आज सुबह पानी नीले की जगह लाल गिलास में दिया तो तूफ़ान आ गया? यह नखरा नहीं, वह बस परख रहा है कि क्या वह दुनिया को चला सकता है। धैर्य रखिए।', title_id = 'Keras kepala tanpa alasan 🛑', body_id = 'Pagi ini kiamat kecil terjadi karena Anda memberi air di gelas merah, bukan biru? Ini bukan manja, ia hanya menguji apakah ia bisa mengendalikan dunianya. Bersabarlah.', title_ja = '理屈に合わないこだわり 🛑', body_ja = '今朝、お水を青ではなく赤いコップで出したら大騒ぎに？これはわがままではなく、世界を自分で動かせるか確かめているだけです。気長に見守りましょう。', title_ko = '이해할 수 없는 고집 🛑', body_ko = '오늘 아침 파란 컵이 아니라 빨간 컵에 물을 줬다고 난리가 났나요? 투정이 아니라 자기가 세상을 움직일 수 있는지 시험하는 중이에요. 인내심을 가져 주세요.', title_nl = 'Onlogische koppigheid 🛑', body_nl = 'Brak vanochtend de hel los omdat je water in de rode beker gaf in plaats van de blauwe? Dat is geen stoutheid, hij test gewoon of hij de wereld kan sturen. Wees geduldig.', title_pl = 'Nielogiczny upór 🛑', body_pl = 'Dziś rano rozpętała się burza, bo dałaś wodę w czerwonym kubku, a nie w niebieskim? To nie kaprys, on po prostu sprawdza, czy może kierować światem. Bądź cierpliwa.', title_pt = 'Teimosias sem lógica 🛑', body_pt = 'Esta manhã foi o fim do mundo porque lhe deu água no copo vermelho e não no azul? Não é birra, está só a testar se consegue controlar o mundo. Tenha paciência.', title_sv = 'Ologisk envishet 🛑', body_sv = 'Brakade allt loss i morse för att du gav vattnet i den röda muggen i stället för den blå? Det är inte trots, barnet testar bara om hen kan styra världen. Ha tålamod.', title_vi = 'Bướng bỉnh vô lý 🛑', body_vi = 'Sáng nay mẹ đưa nước trong cốc đỏ thay vì cốc xanh và bé ăn vạ ầm ĩ? Đây không phải nhõng nhẽo, bé chỉ đang thử xem mình có kiểm soát được thế giới không. Hãy kiên nhẫn nhé.', title_zh = '没道理的倔强 🛑', body_zh = '今天早上因为用红杯子而不是蓝杯子装水，就天塌了？这不是任性，宝宝只是在测试自己能不能掌控世界。耐心一点吧。' WHERE id = '5fa2d1b1-040b-4c74-81f7-5aaa581e81fc' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reserva de vitaminas 🥗', body_es = 'Haces de todo para que coma. ¿Y tú? Elige en Recetas saludables una comida rica en hierro y calcio que se prepara en 10 minutos y recupera energía.', title_fr = 'Plein de vitamines 🥗', body_fr = 'Vous faites tout pour qu''il mange bien. Et vous ? Choisissez dans les Recettes saines un déjeuner riche en fer et en calcium, prêt en 10 minutes, et reprenez des forces.', title_hi = 'विटामिन का भंडार 🥗', body_hi = 'उसका पेट भरने के लिए आप सब कुछ करती हैं। और आप खुद? सेहतमंद रेसिपी से 10 मिनट में बनने वाला, आयरन और कैल्शियम से भरपूर लंच चुनिए और अपनी ऊर्जा लौटाइए।', title_id = 'Gudang vitamin 🥗', body_id = 'Anda melakukan segalanya agar ia kenyang. Lalu bagaimana dengan Anda? Pilih makan siang kaya zat besi dan kalsium yang siap dalam 10 menit dari Resep Sehat, dan pulihkan energi Anda.', title_ja = 'ビタミンの宝庫 🥗', body_ja = 'お子さんにたっぷり食べさせようとがんばっていますね。では、あなたは？「ヘルシーレシピ」から10分でできる、鉄分とカルシウムたっぷりのランチを選んで、エネルギーを取り戻しましょう。', title_ko = '비타민 창고 🥗', body_ko = '아이를 배불리 먹이려고 뭐든 하죠. 그럼 엄마는요? 건강한 레시피에서 10분이면 만드는 철분과 칼슘이 풍부한 점심을 골라 기운을 되찾으세요.', title_nl = 'Vitaminevoorraad 🥗', body_nl = 'Je doet alles om hem te laten eten. En jij? Kies uit Gezonde recepten een lunch vol ijzer en calcium, klaar in 10 minuten, en krijg je energie terug.', title_pl = 'Skarbnica witamin 🥗', body_pl = 'Robisz wszystko, żeby był najedzony. A ty? Wybierz w Zdrowych przepisach obiad bogaty w żelazo i wapń gotowy w 10 minut i odzyskaj energię.', title_pt = 'Reserva de vitaminas 🥗', body_pt = 'Faz tudo para que ele coma bem. E a mãe? Escolha nas Receitas Saudáveis um almoço rico em ferro e cálcio, pronto em 10 minutos, e recupere a energia.', title_sv = 'Vitaminförråd 🥗', body_sv = 'Du gör allt för att barnet ska bli mätt. Men du själv? Välj en lunch rik på järn och kalcium som är klar på 10 minuter från Hälsosamma recept och återfå energin.', title_vi = 'Kho vitamin 🥗', body_vi = 'Mẹ làm mọi thứ để bé được no. Còn mẹ thì sao? Hãy chọn một bữa trưa giàu sắt và canxi làm trong 10 phút từ Công thức lành mạnh để lấy lại năng lượng.', title_zh = '维生素储备 🥗', body_zh = '你想尽办法喂饱宝宝，那你自己呢？从健康食谱里选一份10分钟就能做好、富含铁和钙的午餐，恢复精力吧。' WHERE id = '6555b02b-e564-49b7-b5ae-a0b3594560b0' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Delante del espejo 👀', body_es = '¿Se pone delante del espejo, hace muecas distintas y se ríe solo? Su conciencia de sí mismo va de maravilla. Obsérvale a escondidas y disfruta de estos momentos tan graciosos.', title_fr = 'Devant le miroir 👀', body_fr = 'Il se met devant le miroir, fait des mimiques et rit tout seul ? Sa conscience de soi se développe à merveille. Observez-le en cachette et savourez ces moments rigolos.', title_hi = 'आईने के सामने 👀', body_hi = 'आईने के सामने खड़े होकर तरह-तरह के चेहरे बनाता है और खुद पर हँसता है? खुद की पहचान की समझ कमाल की है। चुपके से उसे देखिए और इन मज़ेदार पलों का आनंद लीजिए।', title_id = 'Di depan cermin 👀', body_id = 'Berdiri di depan cermin, membuat berbagai ekspresi, dan tertawa sendiri? Kesadaran dirinya berkembang dengan sempurna. Amati diam-diam dan nikmati momen lucu ini.', title_ja = '鏡の前で 👀', body_ja = '鏡の前に立って、いろいろな表情をして、ひとりで笑っていますか？自分という意識がしっかり育っています。こっそり見守って、このおもしろい瞬間を楽しみましょう。', title_ko = '거울 앞에서 👀', body_ko = '거울 앞에 서서 이런저런 표정을 지으며 혼자 웃나요? 자아 인식이 멋지게 자라고 있어요. 몰래 지켜보며 이 웃긴 순간을 즐겨 보세요.', title_nl = 'Voor de spiegel 👀', body_nl = 'Staat hij voor de spiegel gekke gezichten te trekken en om zichzelf te lachen? Zijn zelfbewustzijn ontwikkelt zich prachtig. Kijk stiekem toe en geniet van deze grappige momenten.', title_pl = 'Przed lustrem 👀', body_pl = 'Staje przed lustrem, robi różne miny i śmieje się sam do siebie? Świadomość siebie rozwija się wspaniale. Obserwuj go ukradkiem i ciesz się tymi zabawnymi chwilami.', title_pt = 'Em frente ao espelho 👀', body_pt = 'Fica em frente ao espelho a fazer caras diferentes e ri-se sozinho? A consciência de si próprio está a desenvolver-se na perfeição. Observe-o às escondidas e aproveite estes momentos divertidos.', title_sv = 'Framför spegeln 👀', body_sv = 'Står barnet framför spegeln, gör olika miner och skrattar för sig själv? Självmedvetenheten är fantastisk. Titta i smyg och njut av de roliga stunderna.', title_vi = 'Trước gương 👀', body_vi = 'Bé đứng trước gương làm đủ kiểu biểu cảm và tự cười một mình? Nhận thức về bản thân đang phát triển tuyệt vời. Hãy lén quan sát và tận hưởng những khoảnh khắc hài hước này.', title_zh = '在镜子前 👀', body_zh = '站在镜子前做各种表情，自己笑个不停？自我意识发展得非常好。悄悄看着宝宝，好好享受这些搞笑的时刻吧。' WHERE id = '74e20827-e129-489b-a3ba-b3145efc42b3' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Protesta contra el sueño 🥱', body_es = '¿No quiere dormir la siesta y se resiste? Algunos niños dejan la siesta a esta edad. En lugar de discutir, declara la «hora de calma» y hojead libros en la cama.', title_fr = 'Il résiste au sommeil 🥱', body_fr = 'Il refuse la sieste et se débat ? Certains enfants arrêtent la sieste à cet âge. Au lieu de vous disputer, annoncez un « temps calme » et feuilletez un livre au lit.', title_hi = 'नींद का विरोध 🥱', body_hi = 'दोपहर में सोना नहीं चाहता और लड़ता है? इस उम्र में कुछ बच्चे दिन की नींद छोड़ देते हैं। बहस करने के बजाय ''शांत समय'' की घोषणा कीजिए और बिस्तर पर किताब पलटिए।', title_id = 'Melawan kantuk 🥱', body_id = 'Tidak mau tidur siang dan melawan? Sebagian anak berhenti tidur siang di usia ini. Daripada berdebat, umumkan Waktu tenang dan baca-baca buku bersama di tempat tidur.', title_ja = '眠りに抵抗 🥱', body_ja = 'お昼寝を嫌がって、抵抗しますか？この年齢でお昼寝をしなくなる子もいます。言い争う代わりに、「静かな時間」を宣言して、ベッドで一緒に絵本をめくりましょう。', title_ko = '잠 거부 🥱', body_ko = '낮잠을 안 자려고 씨름하나요? 이 나이에 낮잠을 끊는 아이도 있어요. 다투는 대신 ''조용한 시간''을 선언하고 침대에서 함께 책장을 넘겨 보세요.', title_nl = 'Verzet tegen slapen 🥱', body_nl = 'Wil hij niet naar zijn middagdutje en vecht hij ertegen? Sommige kinderen laten op deze leeftijd het dutje vallen. Maak geen ruzie, maar kondig een rustuurtje aan en blader samen in bed door een boek.', title_pl = 'Sprzeciw wobec snu 🥱', body_pl = 'Nie chce iść na popołudniową drzemkę i walczy? Niektóre dzieci w tym wieku rezygnują z drzemki. Zamiast się kłócić, ogłoś „czas wyciszenia” i przeglądajcie książki w łóżku.', title_pt = 'Resiste ao sono 🥱', body_pt = 'Não quer fazer a sesta e luta contra ela? Algumas crianças deixam a sesta nesta idade. Em vez de discutir, anuncie a "hora calma" e folheiem um livro na cama.', title_sv = 'Protest mot sömnen 🥱', body_sv = 'Vill barnet inte sova middag och kämpar emot? Vissa barn slutar sova på dagen i den här åldern. I stället för att bråka, utlys en ”lugn stund” och bläddra i böcker i sängen.', title_vi = 'Phản đối giấc ngủ 🥱', body_vi = 'Bé không muốn ngủ trưa và chống cự? Một số trẻ bỏ giấc ngủ ngày ở tuổi này. Thay vì tranh cãi, hãy tuyên bố "giờ yên tĩnh" và cùng bé lật sách trên giường.', title_zh = '抗拒睡觉 🥱', body_zh = '不想睡午觉，一直抗拒？有些孩子在这个年龄会不再午睡。与其争执，不如宣布“安静时间”，在床上一起翻翻书。' WHERE id = '99e86be1-9932-47a0-b9a8-f6b98dc7dfcf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La acústica de la habitación 🤫', title_fr = 'L''acoustique de la chambre 🤫', title_hi = 'कमरे की ध्वनि 🤫', title_id = 'Akustik kamar 🤫', title_ja = '部屋の音環境 🤫', title_ko = '방 안의 소리 환경 🤫', title_nl = 'De akoestiek van de kamer 🤫', title_pl = 'Akustyka pokoju 🤫', title_pt = 'A acústica do quarto 🤫', title_sv = 'Rummets akustik 🤫', title_vi = 'Âm thanh trong phòng 🤫', title_zh = '房间的声学环境 🤫' WHERE id = 'f80a3604-81aa-4362-9508-4aa4c845b4bc' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabietas tozudas 🛑', body_es = '¿Te dan vergüenza las rabietas en la tienda o en el parque? Recuerda: no importa lo que piensen los demás, sino lo que siente tu peque en ese momento. Mírale a los ojos y cálmale.', title_fr = 'Crises obstinées 🛑', body_fr = 'Les crises au magasin ou au parc vous mettent mal à l''aise ? N''oubliez pas : ce qui compte, ce n''est pas ce que pensent les autres, mais l''émotion de votre enfant à ce moment-là. Regardez-le dans les yeux et apaisez-le.', title_hi = 'ज़िद्दी नखरे 🛑', body_hi = 'दुकान या पार्क में होने वाले नखरे आपको शर्मिंदा करते हैं? याद रखिए, आसपास के लोग क्या सोचते हैं यह नहीं, उस पल बच्चे की भावना ज़रूरी है। आँखों में आँखें डालकर उसे शांत कीजिए।', title_id = 'Tantrum keras kepala 🛑', body_id = 'Tantrum di toko atau taman membuat Anda malu? Ingat, yang penting bukan pikiran orang lain, melainkan emosi anak Anda saat itu. Tatap matanya dan tenangkan ia.', title_ja = 'こだわりのかんしゃく 🛑', body_ja = 'お店や公園でのかんしゃくが恥ずかしいですか？大切なのは周りの人がどう思うかではなく、そのときのお子さんの気持ちです。目を合わせて、落ち着かせてあげましょう。', title_ko = '고집스러운 떼쓰기 🛑', body_ko = '마트나 공원에서의 떼쓰기가 창피한가요? 주변 사람들의 생각이 아니라 그 순간 아이의 감정이 중요하다는 걸 기억하세요. 눈을 맞추고 진정시켜 주세요.', title_nl = 'Koppige buien 🛑', body_nl = 'Schaam je je voor de driftbuien in de winkel of het park? Onthoud: niet wat anderen denken, maar de emotie van je kind op dat moment is belangrijk. Maak oogcontact en kalmeer hem.', title_pl = 'Uparte kryzysy 🛑', body_pl = 'Napady złości w sklepie i w parku wprawiają cię w zakłopotanie? Pamiętaj, liczy się nie to, co pomyślą inni, ale to, co twoje dziecko czuje w tej chwili. Nawiąż kontakt wzrokowy i uspokój je.', title_pt = 'Crises de teimosia 🛑', body_pt = 'As birras na loja ou no parque deixam-na envergonhada? Lembre-se: o que importa não é o que os outros pensam, mas a emoção do seu filho naquele momento. Olhe-o nos olhos e acalme-o.', title_sv = 'Envisa utbrott 🛑', body_sv = 'Skäms du över utbrotten i affären eller parken? Kom ihåg att det viktiga inte är vad andra tycker, utan barnets känslor i stunden. Få ögonkontakt och lugna barnet.', title_vi = 'Những cơn khủng hoảng bướng bỉnh 🛑', body_vi = 'Những cơn ăn vạ ở cửa hàng, công viên khiến mẹ ngượng ngùng? Đừng quên, điều quan trọng không phải người xung quanh nghĩ gì mà là cảm xúc của bé lúc đó. Hãy nhìn vào mắt bé và giúp bé bình tĩnh lại.', title_zh = '倔强的崩溃 🛑', body_zh = '在商店、公园突然发脾气，让你很尴尬？记住，重要的不是别人怎么想，而是孩子那一刻的情绪。和宝宝对视，让宝宝平静下来。' WHERE id = '3e22553e-b182-4faa-9fc2-459fc9a92590' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Intentos de saltar 🤸‍♂️', body_es = '¿Intenta saltar del sofá al suelo o saltar en el sitio? ¡Su motricidad gruesa está mejorando! Anímale.', title_fr = 'Essais de sauts 🤸‍♂️', body_fr = 'Il essaie de sauter du canapé ou de sauter sur place ? Sa motricité globale se perfectionne ! Encouragez-le.', title_hi = 'कूदने की कोशिशें 🤸‍♂️', body_hi = 'सोफ़े से ज़मीन पर या एक जगह खड़े होकर हवा में कूदने की कोशिश करता है? बड़ी मोटर स्किल्स बेहतर हो रही हैं! उसका हौसला बढ़ाइए।', title_id = 'Mencoba melompat 🤸‍♂️', body_id = 'Mencoba melompat dari sofa ke lantai atau melompat ke udara di tempat? Keterampilan motorik kasarnya makin sempurna! Beri ia semangat.', title_ja = 'ジャンプへの挑戦 🤸‍♂️', body_ja = 'ソファから床へ、またはその場でジャンプしようとしていますか？体を大きく動かす力が完成に近づいています！勇気づけてあげましょう。', title_ko = '점프 도전 🤸‍♂️', body_ko = '소파에서 바닥으로, 또는 제자리에서 위로 뛰어 보려 하나요? 대근육 운동 능력이 완성되어 가고 있어요! 용기를 북돋아 주세요.', title_nl = 'Pogingen tot springen 🤸‍♂️', body_nl = 'Probeert hij van de bank op de grond te springen of op de plek omhoog te springen? Zijn grove motoriek wordt steeds beter! Moedig hem aan.', title_pl = 'Próby skakania 🤸‍♂️', body_pl = 'Próbuje zeskoczyć z kanapy na podłogę albo podskoczyć w miejscu? Motoryka duża coraz lepsza! Dodawaj mu odwagi.', title_pt = 'Tentativas de saltar 🤸‍♂️', body_pt = 'Tenta saltar do sofá para o chão ou saltar no mesmo sítio? A motricidade grossa está a aperfeiçoar-se! Encoraje-o.', title_sv = 'Försöker hoppa 🤸‍♂️', body_sv = 'Försöker barnet hoppa från soffan ner på golvet eller upp i luften på stället? Grovmotoriken blir allt bättre! Uppmuntra barnet.', title_vi = 'Tập bật nhảy 🤸‍♂️', body_vi = 'Bé cố nhảy từ sofa xuống sàn hay nhảy lên tại chỗ? Kỹ năng vận động thô đang hoàn thiện! Hãy khích lệ bé.', title_zh = '尝试跳跃 🤸‍♂️', body_zh = '想从沙发跳到地上，或者在原地往上跳？大动作技能越来越好了！多鼓励宝宝吧。' WHERE id = 'e37f9999-21b9-4b48-be42-d9cbbc3d9c55' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Analicemos bien la rutina ⏱️', body_es = '¿Por la noche tardó 40 minutos en dormirse? Mira el gráfico del temporizador de sueño. Quizá ya sea el momento de acortar del todo la siesta y adelantar la hora de dormir.', title_fr = 'Analysons son rythme en détail ⏱️', body_fr = 'Il a mis 40 minutes à s''endormir ce soir ? Regardez le graphique du minuteur de sommeil. Il est peut-être déjà temps de raccourcir nettement la sieste et d''avancer le coucher.', title_hi = 'रूटीन का पूरा विश्लेषण करें ⏱️', body_hi = 'शाम को सोने में 40 मिनट लग गए? स्लीप टाइमर का चार्ट देखिए। शायद दिन की नींद पूरी तरह कम करने और शाम की नींद जल्दी करने का समय आ गया है।', title_id = 'Ayo analisis rutinitasnya ⏱️', body_id = 'Butuh 40 menit untuk tertidur malam ini? Lihat grafik Timer Tidur. Mungkin sudah tiba waktunya memangkas tidur siang sepenuhnya dan memajukan jam tidur malam.', title_ja = '生活リズムをしっかり分析しよう ⏱️', body_ja = '夜、寝つくまで40分かかりましたか？睡眠タイマーのグラフを見てみましょう。お昼寝をぐっと短くして、夜の寝る時間を早めるときが、もう来ているのかもしれません。', title_ko = '일과를 제대로 분석해 봐요 ⏱️', body_ko = '저녁에 잠드는 데 40분이 걸렸나요? 수면 타이머 그래프를 살펴보세요. 낮잠을 아예 줄이고 잠자리 시간을 앞당길 때가 이미 되었을지도 몰라요.', title_nl = 'Laten we het ritme goed analyseren ⏱️', body_nl = 'Duurde het inslapen vanavond 40 minuten? Bekijk de grafiek van de Slaaptimer. Misschien is het tijd om het middagdutje helemaal te schrappen en de bedtijd te vervroegen.', title_pl = 'Dokładnie przeanalizujmy rytm dnia ⏱️', body_pl = 'Wieczorne zasypianie trwało 40 minut? Spójrz na wykres timera snu. Może już czas całkiem skrócić drzemkę i przesunąć wieczorne spanie wcześniej.', title_pt = 'Vamos analisar a rotina a fundo ⏱️', body_pt = 'À noite demorou 40 minutos a adormecer? Veja o gráfico do temporizador de sono. Talvez já esteja na altura de encurtar a sesta de vez e antecipar a hora de deitar.', title_sv = 'Vi analyserar rytmen ordentligt ⏱️', body_sv = 'Tog det 40 minuter att somna i kväll? Titta på grafen i sömntimern. Kanske är det redan dags att korta dagsömnen ordentligt och tidigarelägga kvällen.', title_vi = 'Cùng phân tích toàn bộ nếp sinh hoạt ⏱️', body_vi = 'Tối qua bé mất 40 phút mới ngủ? Hãy xem biểu đồ của Bộ hẹn giờ ngủ. Có lẽ đã đến lúc rút ngắn hẳn giấc ngủ ngày và cho bé ngủ tối sớm hơn.', title_zh = '来全面分析一下作息 ⏱️', body_zh = '晚上入睡花了40分钟？看看睡眠计时器的图表。也许已经到了大幅缩短白天小睡、把晚上就寝时间提前的时候了。' WHERE id = 'ebbeae36-6d1a-428b-bb72-2ef8bd324080' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explorando la naturaleza ⛅', body_es = 'Las cuatro paredes te ahogan. Abre Tiempo y ropa, vístele según el tiempo y salid enseguida al parque. Que descubra hojas y piedras.', title_fr = 'Exploration de la nature ⛅', body_fr = 'Vous étouffez entre quatre murs ? Ouvrez l''outil Météo et tenue, habillez-le selon le temps et emmenez-le tout de suite au parc. Qu''il découvre les feuilles et les cailloux.', title_hi = 'प्रकृति की खोज ⛅', body_hi = 'चार दीवारें आपका दम घोंट रही हैं। मौसम और कपड़े टूल खोलिए, मौसम के हिसाब से कपड़े पहनाइए और उसे तुरंत पार्क ले जाइए। उसे पत्ते और पत्थर खोजने दीजिए।', title_id = 'Menjelajahi alam ⛅', body_id = 'Empat dinding terasa menyesakkan. Buka alat Cuaca dan Pakaian, pakaikan baju sesuai cuaca, dan segera ajak ia ke taman. Biarkan ia menjelajahi daun dan batu.', title_ja = '自然の探検 ⛅', body_ja = '4つの壁に息がつまりそう？「天気と服装」を開いて、天気に合った服を着せ、すぐに公園へ出かけましょう。葉っぱや石を探検させてあげて。', title_ko = '자연 탐험 ⛅', body_ko = '네 벽에 갇힌 것 같나요? 날씨와 옷차림 도구를 열어 날씨에 맞게 입히고 바로 공원으로 나가세요. 나뭇잎과 돌멩이를 마음껏 탐험하게 해 주세요.', title_nl = 'De natuur ontdekken ⛅', body_nl = 'Word je gek van de vier muren? Open Weer en kleding, kleed hem passend aan en ga meteen naar het park. Laat hem bladeren en steentjes ontdekken.', title_pl = 'Odkrywanie przyrody ⛅', body_pl = 'Cztery ściany cię duszą. Otwórz narzędzie Pogoda i ubiór, ubierz go odpowiednio do pogody i od razu idźcie do parku. Niech odkrywa liście i kamienie.', title_pt = 'Exploração da natureza ⛅', body_pt = 'As quatro paredes sufocam-na. Abra o Tempo e Roupa, vista-o de acordo com o tempo e leve-o já ao parque. Deixe-o descobrir as folhas e as pedras.', title_sv = 'Naturutforskning ⛅', body_sv = 'Känns de fyra väggarna kvävande? Öppna Väder och kläder, klä barnet efter vädret och gå direkt till parken. Låt barnet upptäcka löv och stenar.', title_vi = 'Khám phá thiên nhiên ⛅', body_vi = 'Bốn bức tường làm mẹ ngột ngạt. Hãy mở công cụ Thời tiết và trang phục, mặc đồ phù hợp với thời tiết cho bé và ra công viên ngay. Để bé khám phá lá cây, đá sỏi.', title_zh = '探索大自然 ⛅', body_zh = '四面墙让你透不过气。打开天气与穿衣工具，按天气给宝宝穿好衣服，马上带宝宝去公园。让宝宝去探索树叶和石头吧。' WHERE id = '1240eee6-bdc5-4609-ba23-b9d212dcb809' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Disfruta de la calma 🤫', body_es = 'Por fin se ha dormido. Ahora hasta el ruido más pequeño de casa te pone nerviosa. Ponte los auriculares y, sin escuchar nada, simplemente valora el silencio.', title_fr = 'Savourez le calme 🤫', body_fr = 'Il s''est enfin endormi. Maintenant, le moindre bruit de la maison vous agace. Mettez vos écouteurs sans rien écouter et profitez simplement du silence.', title_hi = 'शांति का आनंद लीजिए 🤫', body_hi = 'वह आखिरकार सो गया। अब घर की छोटी से छोटी आवाज़ भी आपको चिढ़ा रही है। हेडफ़ोन लगाइए, कुछ भी सुने बिना बस खामोशी की कद्र कीजिए।', title_id = 'Nikmati ketenangan 🤫', body_id = 'Akhirnya ia tertidur. Kini suara sekecil apa pun di rumah membuat Anda kesal. Pasang headphone, tak perlu mendengarkan apa-apa, cukup hargai keheningan ini.', title_ja = '静けさを楽しんで 🤫', body_ja = 'やっと眠りました。今は家の中のほんの小さな音にもイライラしてしまいますね。イヤホンをつけて、何も聞かずに、ただ静けさのありがたさを味わいましょう。', title_ko = '고요함을 즐기세요 🤫', body_ko = '드디어 아이가 잠들었어요. 이제는 집 안의 아주 작은 소리마저 신경 쓰이죠. 헤드폰을 끼고 아무것도 듣지 않은 채 고요함을 누려 보세요.', title_nl = 'Geniet van de rust 🤫', body_nl = 'Hij slaapt eindelijk. Nu irriteert zelfs het kleinste geluid in huis je. Zet een koptelefoon op, luister naar niets en geniet gewoon van de stilte.', title_pl = 'Ciesz się ciszą 🤫', body_pl = 'Wreszcie zasnął. Teraz nawet najmniejszy dźwięk w domu cię drażni. Załóż słuchawki i niczego nie słuchając, po prostu doceń ciszę.', title_pt = 'Aproveite o silêncio 🤫', body_pt = 'Finalmente adormeceu. Agora até o som mais pequeno da casa a irrita. Ponha os auscultadores e, sem ouvir nada, simplesmente valorize o silêncio.', title_sv = 'Njut av lugnet 🤫', body_sv = 'Barnet har äntligen somnat. Nu irriterar även det minsta ljud hemma dig. Sätt på hörlurarna, lyssna inte på någonting och uppskatta bara tystnaden.', title_vi = 'Tận hưởng sự yên tĩnh 🤫', body_vi = 'Cuối cùng bé cũng ngủ. Giờ tiếng động nhỏ nhất trong nhà cũng khiến mẹ khó chịu. Hãy đeo tai nghe, không nghe gì cả, chỉ trân trọng sự yên tĩnh.', title_zh = '享受安静 🤫', body_zh = '宝宝终于睡着了。现在家里再小的声音都会让你心烦。戴上耳机，什么都不听，只是好好珍惜这份安静。' WHERE id = '1e908b82-2f19-4ebe-b79e-40246a88bab7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubriendo los colores 🎨', body_es = '¿Cuando le pides la pelota roja, señala justo la roja? Ya empieza a distinguir los colores. Anota esta nueva etapa de comprensión en el Seguimiento del desarrollo.', title_fr = 'La découverte des couleurs 🎨', body_fr = 'Quand vous demandez le ballon rouge, il montre bien le rouge ? Il commence déjà à distinguer les couleurs. Notez cette nouvelle étape de compréhension dans le Suivi de développement.', title_hi = 'रंगों की खोज 🎨', body_hi = 'लाल गेंद माँगने पर ठीक लाल ही दिखाता है? वह अब रंग पहचानने लगा है। ग्रोथ ट्रैकर में समझ के इस नए दौर को लिखिए।', title_id = 'Mengenal warna 🎨', body_id = 'Saat diminta bola merah, ia menunjuk tepat yang merah? Ia sudah mulai membedakan warna. Tulis tahap pemahaman baru ini di Pelacak Perkembangan.', title_ja = '色の発見 🎨', body_ja = '「赤いボールちょうだい」と言うと、ちゃんと赤を指さしますか？もう色を見分け始めています。この新しい認識の段階を「発達トラッカー」に書きましょう。', title_ko = '색깔 발견 🎨', body_ko = '빨간 공을 달라고 하면 정확히 빨간 공을 가리키나요? 이제 색을 구별하기 시작했어요. 성장 기록에 이 새로운 인지 단계를 남겨 두세요.', title_nl = 'Kleuren ontdekken 🎨', body_nl = 'Wijst hij precies de rode bal aan als je erom vraagt? Hij begint kleuren te herkennen. Noteer deze nieuwe stap in zijn begrip in de Groeitracker.', title_pl = 'Odkrywanie kolorów 🎨', body_pl = 'Gdy prosisz o czerwoną piłkę, pokazuje właśnie czerwoną? Zaczyna już rozróżniać kolory. Zapisz ten nowy etap postrzegania w Śledzeniu rozwoju.', title_pt = 'A descoberta das cores 🎨', body_pt = 'Quando lhe pede a bola vermelha, mostra mesmo a vermelha? Já começa a distinguir as cores. Registe esta nova fase de perceção no Registo de Desenvolvimento.', title_sv = 'Färgerna upptäcks 🎨', body_sv = 'Pekar barnet just på den röda bollen när du ber om den röda? Barnet har redan börjat skilja på färger. Skriv ner detta nya stadium av uppfattning i Utvecklingsspåraren.', title_vi = 'Khám phá màu sắc 🎨', body_vi = 'Mẹ bảo lấy quả bóng đỏ, bé chỉ đúng quả màu đỏ? Bé đã bắt đầu phân biệt màu sắc. Hãy ghi giai đoạn nhận thức mới này vào Theo dõi phát triển.', title_zh = '发现颜色 🎨', body_zh = '你要红色的球时，宝宝就能准确指出红色？宝宝已经开始分辨颜色了。把这个新的认知阶段写进发育追踪吧。' WHERE id = '488aec04-c9ee-4eb7-9fb1-11c9a4093d08' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La excusa del «estoy lleno» 🥣', body_es = '¿Come dos cucharadas, dice que está lleno y sale corriendo? No le obligues. Prueba a darle raciones pequeñas pero más a menudo.', title_fr = 'L''excuse « J''ai plus faim » 🥣', body_fr = 'Il dit « j''ai plus faim » après deux cuillerées et s''enfuit ? Ne le forcez pas. Essayez de lui donner de petites portions, mais plus souvent.', title_hi = '''मेरा पेट भर गया'' वाला बहाना 🥣', body_hi = 'दो चम्मच खाकर ''पेट भर गया'' कहता है और भाग जाता है? उस पर ज़ोर मत डालिए। छोटे हिस्से, पर थोड़े-थोड़े अंतराल पर बार-बार देकर देखिए।', title_id = 'Alasan Aku sudah kenyang 🥣', body_id = 'Baru makan dua suap lalu bilang sudah kenyang dan kabur? Jangan memaksanya. Coba berikan porsi kecil dengan jeda yang lebih sering.', title_ja = '「おなかいっぱい」の言いわけ 🥣', body_ja = '2口食べただけで「おなかいっぱい」と言って逃げますか？無理強いしないで。量を少なくして、こまめに間隔をあけて出してみましょう。', title_ko = '''배불러'' 핑계 🥣', body_ko = '두 숟가락 먹고 ''배불러'' 하며 도망가나요? 억지로 먹이지 마세요. 양은 적게, 대신 자주 나눠 주는 방법을 시도해 보세요.', title_nl = 'Het smoesje ik zit vol 🥣', body_nl = 'Zegt hij na twee hapjes ik zit vol en rent hij weg? Dwing hem niet. Probeer kleine porties, maar vaker op de dag.', title_pl = 'Wymówka „Jestem syty” 🥣', body_pl = 'Zjada dwie łyżki, mówi „jestem syty” i ucieka? Nie zmuszaj go. Spróbuj podawać mniejsze porcje, ale częściej.', title_pt = 'A desculpa do "Estou cheio" 🥣', body_pt = 'Come duas colheres, diz que está cheio e foge? Não o obrigue. Experimente dar porções pequenas, mas com mais frequência.', title_sv = 'Ursäkten ”Jag är mätt” 🥣', body_sv = 'Äter barnet två skedar, säger ”jag är mätt” och springer iväg? Tvinga inte barnet. Prova att servera små portioner men oftare.', title_vi = 'Cái cớ "Con no rồi" 🥣', body_vi = 'Bé ăn hai thìa rồi bảo "no rồi" và chạy đi? Đừng ép bé. Hãy thử chia thành những phần nhỏ và cho ăn thường xuyên hơn.', title_zh = '“我吃饱了”的借口 🥣', body_zh = '吃两勺就说饱了，起身就跑？别强迫宝宝。试试少量多次地给宝宝吃。' WHERE id = '3be3de73-5fca-4eff-b43e-5882d476d692' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Reconocer las partes del cuerpo 👀', body_es = '¿Cuando le preguntas «¿Dónde están tus hombros?», se los toca con el dedo? ¡Su comprensión está en su mejor momento! Sigue el juego con partes del cuerpo más difíciles.', title_fr = 'Reconnaître les parties du corps 👀', body_fr = 'Quand vous demandez « Où sont tes épaules ? », il les montre du doigt ? Sa compréhension est au top ! Continuez le jeu avec des parties du corps plus difficiles.', title_hi = 'शरीर के अंगों की पहचान 👀', body_hi = '''तुम्हारे कंधे कहाँ हैं?'' पूछने पर उँगली से छूकर दिखाता है? उसकी समझ चरम पर है! खेल को शरीर के और मुश्किल अंगों के साथ आगे बढ़ाइए।', title_id = 'Mengenal bagian tubuh 👀', body_id = 'Saat ditanya Bahumu di mana?, ia menyentuh dan menunjukkannya dengan jari? Pemahamannya sedang di puncak! Lanjutkan permainan dengan bagian tubuh yang lebih sulit.', title_ja = '体の部分がわかる 👀', body_ja = '「肩はどこ？」と聞くと、指でさわって教えてくれますか？理解する力が最高潮です！もっと難しい体の部分で遊びを続けましょう。', title_ko = '몸의 부위 알기 👀', body_ko = '''어깨 어디 있어?'' 하고 물으면 손가락으로 짚어 보여 주나요? 이해력이 최고조예요! 더 어려운 몸의 부위로 놀이를 이어 가 보세요.', title_nl = 'Lichaamsdelen leren 👀', body_nl = 'Wijst hij zijn schouders aan als je vraagt waar ze zijn? Zijn begrip is op zijn hoogtepunt! Speel het spelletje verder met moeilijkere lichaamsdelen.', title_pl = 'Poznawanie części ciała 👀', body_pl = 'Na pytanie „Gdzie masz ramiona?” dotyka ich palcem? Postrzeganie jest u szczytu! Kontynuujcie zabawę z trudniejszymi częściami ciała.', title_pt = 'Reconhecer as partes do corpo 👀', body_pt = 'Quando lhe pergunta "Onde estão os teus ombros?", toca-lhes com o dedo? A compreensão está no auge! Continue o jogo com partes do corpo mais difíceis.', title_sv = 'Känner igen kroppsdelar 👀', body_sv = 'Pekar barnet och rör vid axlarna när du frågar ”Var är dina axlar?” Den mentala förståelsen är på topp! Fortsätt leken med svårare kroppsdelar.', title_vi = 'Nhận biết các bộ phận cơ thể 👀', body_vi = 'Khi hỏi "Vai con đâu?", bé dùng ngón tay chạm vào chỉ? Khả năng nhận thức đang ở đỉnh cao! Hãy tiếp tục trò chơi với các bộ phận cơ thể khó hơn.', title_zh = '认识身体部位 👀', body_zh = '问“你的肩膀在哪里？”时，宝宝会用手指点给你看？认知能力正处于高峰！用更复杂的身体部位继续这个游戏吧。' WHERE id = '9e9231eb-622b-4591-8fb2-b2c0bedcc252' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La lucha del pijama 👕', body_es = '¿Vestirse por la noche se convierte en una gran guerra? Deja que elija: «¿Quieres el pijama blanco o el azul?». Este truco suele funcionar.', title_fr = 'La lutte du pyjama 👕', body_fr = 'S''habiller le soir tourne à la guerre ? Laissez-le choisir : « Tu veux le pyjama blanc ou le bleu ? » Cette astuce marche très souvent.', title_hi = 'पायजामे की कुश्ती 👕', body_hi = 'शाम को कपड़े बदलना बड़ी जंग बन जाता है? चुनाव उस पर छोड़िए: ''सफ़ेद पायजामा चाहिए या नीला?'' यह तरकीब अक्सर काम कर जाती है।', title_id = 'Gulat piyama 👕', body_id = 'Berpakaian di malam hari berubah jadi perang besar? Biarkan ia memilih: Mau piyama putih atau yang biru? Trik ini sering kali berhasil.', title_ja = 'パジャマのバトル 👕', body_ja = '夜の着替えが大きなバトルになっていますか？「白いパジャマがいい？それとも青？」と選ばせてあげましょう。このコツはたいていうまくいきます。', title_ko = '잠옷 씨름 👕', body_ko = '저녁마다 옷 입기가 큰 전쟁이 되나요? 선택을 맡겨 보세요: ''하얀 잠옷 입을래, 파란 잠옷 입을래?'' 이 방법은 대부분 효과가 있어요.', title_nl = 'Pyjamagevecht 👕', body_nl = 'Wordt aankleden ''s avonds een grote oorlog? Laat hem kiezen: wil je de witte pyjama of de blauwe? Dit trucje werkt vaak.', title_pl = 'Piżamowe zapasy 👕', body_pl = 'Wieczorne przebieranie zamienia się w wielką wojnę? Zostaw mu wybór: „Chcesz białą piżamę czy niebieską?”. Ta sztuczka często działa.', title_pt = 'A luta do pijama 👕', body_pt = 'À noite, vestir-se transforma-se numa grande guerra? Deixe-o escolher: "Queres o pijama branco ou o azul?" Este truque costuma resultar.', title_sv = 'Pyjamasbrottning 👕', body_sv = 'Blir påklädningen på kvällen ett stort krig? Låt barnet välja: ”Vill du ha den vita pyjamasen eller den blå?” Knepet fungerar oftast.', title_vi = 'Đấu vật với pyjama 👕', body_vi = 'Buổi tối mặc đồ thành cả một cuộc chiến? Hãy để bé chọn: "Con muốn mặc pyjama trắng hay xanh?" Mẹo này thường rất hiệu quả.', title_zh = '睡衣摔跤赛 👕', body_zh = '晚上换衣服变成了一场大战？把选择权交给宝宝：“你想穿白色睡衣，还是蓝色的？”这个小技巧往往很管用。' WHERE id = 'dfbc5f7d-d4f2-4480-8272-664e257700f7' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El juguete de otro 🧸', body_es = '¿No le deja sus juguetes al niño que viene de visita? No es egoísmo, está protegiendo sus límites personales. Enséñale a compartir con el ejemplo, no obligándole.', title_fr = 'Le jouet de l''autre 🧸', body_fr = 'Il ne prête pas ses jouets à l''enfant venu en visite ? Ce n''est pas de l''égoïsme, il protège ses limites personnelles. Apprenez-lui à partager par l''exemple, pas en le forçant.', title_hi = 'दूसरे का खिलौना 🧸', body_hi = 'घर आए मेहमान बच्चे को अपना खिलौना नहीं देता? यह स्वार्थ नहीं, अपनी निजी सीमाओं की रक्षा है। बाँटना ज़बरदस्ती से नहीं, उदाहरण से सिखाइए।', title_id = 'Mainan milik orang lain 🧸', body_id = 'Tidak mau meminjamkan mainannya kepada anak tamu? Ini bukan egois, ia sedang menjaga batasan pribadinya. Ajarkan berbagi lewat contoh, bukan paksaan.', title_ja = 'ほかの子のおもちゃ 🧸', body_ja = '遊びに来たお友だちに、自分のおもちゃを貸さない？これはわがままではなく、自分の境界線を守っているのです。無理に貸させるのではなく、お手本を見せて教えましょう。', title_ko = '다른 사람의 장난감 🧸', body_ko = '놀러 온 친구에게 자기 장난감을 안 주나요? 이기심이 아니라 자기 경계를 지키는 거예요. 억지로 나누게 하지 말고 본보기로 가르쳐 주세요.', title_nl = 'Het speelgoed van een ander 🧸', body_nl = 'Geeft hij zijn speelgoed niet aan een kind dat op bezoek komt? Dat is geen egoïsme, hij beschermt zijn eigen grenzen. Leer hem delen met je eigen voorbeeld, niet door te dwingen.', title_pl = 'Cudza zabawka 🧸', body_pl = 'Nie daje swoich zabawek dziecku, które przyszło w gości? To nie egoizm, tylko ochrona osobistych granic. Ucz dzielenia się własnym przykładem, a nie przymusem.', title_pt = 'O brinquedo dos outros 🧸', body_pt = 'Não empresta os brinquedos à criança que vem de visita? Não é egoísmo, é proteger os seus limites pessoais. Ensine a partilhar com o exemplo, não à força.', title_sv = 'Någon annans leksak 🧸', body_sv = 'Ger barnet inte sin leksak till ett barn som är på besök? Det är inte egoism, utan att skydda sina personliga gränser. Lär ut att dela genom att vara ett exempel, inte genom tvång.', title_vi = 'Đồ chơi của người khác 🧸', body_vi = 'Bé không đưa đồ chơi cho bạn nhỏ đến chơi nhà? Đây không phải ích kỷ mà là bé đang bảo vệ ranh giới cá nhân. Hãy dạy bé chia sẻ bằng cách làm gương chứ đừng ép buộc.', title_zh = '别人的玩具 🧸', body_zh = '不肯把自己的玩具给来家里做客的小朋友？这不是自私，而是在守护自己的边界。别强迫分享，用榜样去教吧。' WHERE id = '437d195c-2ce7-46eb-a38c-e5ab8476f991' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pronunciación de las palabras 🗣️', body_es = '¿Pronuncia algunas palabras a medias o de forma muy graciosa? No te rías: repítele la forma correcta con la entonación adecuada para que su cerebro la grabe bien.', title_fr = 'La prononciation des mots 🗣️', body_fr = 'Il prononce certains mots à moitié ou de façon très drôle ? Ne riez pas, mais répétez-lui la bonne prononciation avec la bonne intonation pour que son cerveau enregistre la bonne version.', title_hi = 'शब्दों का उच्चारण 🗣️', body_hi = 'कुछ शब्द अधूरे या बहुत मज़ेदार ढंग से बोलता है? हँसिए मत, बल्कि सही शब्द सही लहजे में उसके सामने दोहराइए ताकि उसका दिमाग सही रूप याद रखे।', title_id = 'Pelafalan kata 🗣️', body_id = 'Mengucapkan beberapa kata secara terpotong atau sangat lucu? Jangan ditertawakan, cukup ulangi kata yang benar dengan tekanan yang tepat agar otaknya merekam pelafalan yang benar.', title_ja = '言葉の発音 🗣️', body_ja = '言葉を途中までしか言えなかったり、とてもおもしろく発音したりしますか？笑わずに、正しい言い方をはっきりと繰り返してあげましょう。脳が正しい形を覚えていきます。', title_ko = '단어 발음 🗣️', body_ko = '어떤 단어를 반만 말하거나 아주 웃기게 발음하나요? 웃지 말고, 뇌가 바르게 기억하도록 정확한 발음과 강세로 다시 말해 주세요.', title_nl = 'Woorden uitspreken 🗣️', body_nl = 'Spreekt hij sommige woorden half of heel grappig uit? Lach niet, maar herhaal het goede woord met de juiste klemtoon, zodat zijn hersenen het goed opslaan.', title_pl = 'Wymowa słów 🗣️', body_pl = 'Niektóre słowa wymawia niedokończone albo bardzo zabawnie? Nie śmiej się, tylko powtórz mu je poprawnie, z właściwym akcentem, żeby jego mózg zapamiętał prawidłową wersję.', title_pt = 'A pronúncia das palavras 🗣️', body_pt = 'Pronuncia algumas palavras a meio ou de forma muito engraçada? Não se ria, mas repita-lhe a forma certa com a acentuação correta, para o cérebro dele a memorizar.', title_sv = 'Uttalet av ord 🗣️', body_sv = 'Uttalar barnet vissa ord halvt eller väldigt roligt? Skratta inte, men upprepa det rätta ordet med rätt betoning så att hjärnan lär sig det rätta.', title_vi = 'Cách phát âm 🗣️', body_vi = 'Bé phát âm một số từ chưa trọn hoặc rất ngộ nghĩnh? Đừng cười, hãy nhắc lại từ đúng với ngữ điệu chuẩn để não bé ghi nhớ cách nói đúng.', title_zh = '词语发音 🗣️', body_zh = '有些词说得不完整，或者特别搞笑？别笑，用正确的重音给宝宝重复一遍正确的说法，让宝宝的大脑记住对的发音。' WHERE id = '49a7a4ab-0bbe-4e7b-ab8f-16aac2b2f875' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Sospecha de terror nocturno? 😭', body_es = '¿Llora a medianoche con los ojos cerrados y no se calma? Deja que Análisis del llanto escuche su llanto enseguida. A veces no son gases, sino terror nocturno.', title_fr = 'Soupçon de terreur nocturne 😭', body_fr = 'Au milieu de la nuit, il pleure les yeux fermés et ne se calme pas ? Faites tout de suite écouter ses pleurs à l''Analyse des pleurs. Parfois, ce ne sont pas des gaz mais une terreur nocturne.', title_hi = 'नाइट टेरर का शक 😭', body_hi = 'आधी रात को आँखें बंद किए रोता है और शांत नहीं होता? आवाज़ तुरंत क्राइंग एनालिसिस को सुनाइए। कभी-कभी यह बस गैस नहीं, नाइट टेरर होता है।', title_id = 'Curiga teror malam 😭', body_id = 'Menangis di tengah malam dengan mata tertutup dan tak bisa ditenangkan? Segera perdengarkan suaranya ke Analisis Tangisan. Terkadang ini bukan sekadar kembung, melainkan teror tidur.', title_ja = '夜驚症かも？😭', body_ja = '夜中に目を閉じたまま泣いて、泣き止まない？すぐに「泣き声分析」で泣き声を聞かせましょう。ただのおなかのガスではなく、夜驚症のこともあります。', title_ko = '야경증이 의심될 때 😭', body_ko = '한밤중에 눈을 감은 채 울고 진정이 안 되나요? 바로 울음 분석으로 소리를 들려주세요. 가스 때문이 아니라 야경증일 때도 있어요.', title_nl = 'Vermoeden van nachtangst 😭', body_nl = 'Huilt hij midden in de nacht met zijn ogen dicht en is hij niet te troosten? Laat Huilanalyse meteen naar het geluid luisteren. Soms zijn het geen krampjes, maar nachtangst.', title_pl = 'Podejrzenie lęku nocnego 😭', body_pl = 'W środku nocy płacze z zamkniętymi oczami i nie daje się uspokoić? Od razu pozwól Analizie płaczu posłuchać dźwięku. Czasem to nie gazy, tylko lęk nocny.', title_pt = 'Suspeita de terror noturno 😭', body_pt = 'A meio da noite chora de olhos fechados e não se acalma? Deixe já a Análise do Choro ouvir o som. Às vezes não são só gases, é um terror noturno.', title_sv = 'Misstanke om nattskräck 😭', body_sv = 'Gråter barnet mitt i natten med slutna ögon och går inte att lugna? Låt Gråtanalys lyssna på ljudet direkt. Ibland är det inte bara gaser, utan nattskräck.', title_vi = 'Nghi ngờ hoảng sợ ban đêm 😭', body_vi = 'Nửa đêm bé nhắm mắt khóc mà không chịu dịu lại? Hãy cho Phân tích tiếng khóc nghe ngay. Đôi khi đó không chỉ là đầy hơi mà là hoảng sợ khi ngủ.', title_zh = '疑似夜惊 😭', body_zh = '半夜闭着眼睛哭，怎么也安抚不下来？马上让哭声分析听一听。有时这不只是胀气，而是夜惊。' WHERE id = 'd03e0dcf-56bb-436b-bb3e-19d3231b91eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Caprichos de la mañana ☁️', title_fr = 'Caprices du matin ☁️', title_hi = 'सुबह के नखरे ☁️', title_id = 'Rewel di pagi hari ☁️', title_ja = '朝の不機嫌 ☁️', title_ko = '아침 투정 ☁️', title_nl = 'Ochtendhumeur ☁️', title_pl = 'Poranne kaprysy ☁️', title_pt = 'Rabugice da manhã ☁️', title_sv = 'Morgongnäll ☁️', title_vi = 'Nhõng nhẽo buổi sáng ☁️', title_zh = '早上的小脾气 ☁️' WHERE id = '42301ed7-ed5e-4c5a-a79b-59b5256decae' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Deja que se ensucie 🏖️', body_es = '¿Quiere jugar con barro o arena en el parque? ¡Deja que se ensucie! Busca en la app los mejores Lugares para mamás para esta actividad que apoya su desarrollo sensorial.', title_fr = 'Laissez-le se salir 🏖️', body_fr = 'Il veut jouer avec la boue ou le sable au parc ? Laissez-le se salir ! Trouvez dans l''appli les meilleurs Lieux adaptés aux mamans pour cette activité qui soutient son développement sensoriel.', title_hi = 'गंदा होने दीजिए 🏖️', body_hi = 'पार्क में कीचड़ या रेत से खेलना चाहता है? उसे गंदा होने दीजिए! सेंसरी विकास में मदद करने वाली इस गतिविधि के लिए ऐप में सबसे अच्छी माँ के लिए अनुकूल जगहें ढूँढिए।', title_id = 'Biarkan ia kotor 🏖️', body_id = 'Ingin bermain lumpur atau pasir di taman? Biarkan ia kotor! Temukan Tempat Ramah Ibu terbaik untuk kegiatan yang mendukung perkembangan sensorik ini di aplikasi.', title_ja = '汚れても大丈夫 🏖️', body_ja = '公園で泥や砂で遊びたがりますか？汚れてもいいんです！感覚の発達を育てるこの遊びにぴったりの「ママにやさしいスポット」を、アプリで見つけましょう。', title_ko = '마음껏 더러워지게 해 주세요 🏖️', body_ko = '공원에서 진흙이나 모래로 놀고 싶어 하나요? 마음껏 더러워지게 해 주세요! 감각 발달을 돕는 이 놀이에 딱 맞는 엄마 친화 장소를 앱에서 찾아보세요.', title_nl = 'Laat hem vies worden 🏖️', body_nl = 'Wil hij in het park met modder of zand spelen? Laat hem vies worden! Vind in de app de beste Mamavriendelijke plekken voor deze activiteit die zijn zintuiglijke ontwikkeling steunt.', title_pl = 'Pozwól mu się ubrudzić 🏖️', body_pl = 'W parku chce bawić się błotem albo piaskiem? Pozwól mu się ubrudzić! Znajdź w aplikacji najlepsze Miejsca przyjazne mamom na tę zabawę wspierającą rozwój sensoryczny.', title_pt = 'Deixe-o sujar-se 🏖️', body_pt = 'No parque quer brincar com lama ou areia? Deixe-o sujar-se! Encontre na app os melhores Locais Amigos das Mães para esta atividade que apoia o desenvolvimento sensorial.', title_sv = 'Låt barnet bli smutsigt 🏖️', body_sv = 'Vill barnet leka med lera eller sand i parken? Låt barnet bli smutsigt! Hitta de bästa Mammavänliga platserna i appen för denna aktivitet som stöttar sinnesutvecklingen.', title_vi = 'Cứ để bé lấm bẩn 🏖️', body_vi = 'Ở công viên bé muốn nghịch bùn hay cát? Cứ để bé lấm bẩn! Hãy tìm trong ứng dụng những Địa điểm thân thiện với mẹ tốt nhất cho hoạt động phát triển giác quan này.', title_zh = '允许宝宝弄脏 🏖️', body_zh = '想在公园玩泥巴或沙子？就让宝宝弄脏吧！在应用里找到最适合这种促进感官发展活动的妈妈友好场所。' WHERE id = '4611486b-3235-40ef-8f07-a9ac44bd4de8' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Espíritu de equipo 🥂', body_es = 'Habéis dejado atrás un día difícil. Cuando tu peque se duerma, sírvete un té con tu pareja y reconoceos mutuamente diciendo: «De verdad que lo estamos consiguiendo».', title_fr = 'Esprit d''équipe 🥂', body_fr = 'Vous avez laissé derrière vous une journée difficile. Une fois qu''il dort, partagez un thé avec votre conjoint et félicitez-vous en disant « on s''en sort vraiment bien ».', title_hi = 'टीम स्पिरिट 🥂', body_hi = 'आपने एक मुश्किल दिन पार कर लिया। बच्चे के सोने के बाद अपने साथी के साथ चाय पीजिए और ''हम सच में यह कर दिखा रहे हैं'' कहकर एक-दूसरे की तारीफ़ कीजिए।', title_id = 'Semangat tim 🥂', body_id = 'Anda sudah melewati hari yang berat. Setelah si kecil tidur, tuang teh bersama pasangan dan saling menghargai sambil berkata: kita benar-benar bisa melewati semua ini.', title_ja = 'チームの力 🥂', body_ja = '大変な一日を乗りこえましたね。お子さんが眠ったら、パートナーとお茶をいれて「わたしたち、ちゃんとやれてるね」とお互いをねぎらいましょう。', title_ko = '팀워크 🥂', body_ko = '힘든 하루를 또 이겨 냈어요. 아이가 잠든 뒤 배우자와 차 한 잔을 나누며 ''우리 정말 잘 해내고 있어'' 하고 서로를 칭찬해 주세요.', title_nl = 'Teamgeest 🥂', body_nl = 'Weer een zware dag achter de rug. Schenk, als je kindje slaapt, samen met je partner een kop thee in en waardeer elkaar: we kunnen dit echt.', title_pl = 'Duch drużyny 🥂', body_pl = 'Kolejny trudny dzień za wami. Gdy maluch zaśnie, nalejcie sobie z partnerem herbaty i doceńcie się nawzajem, mówiąc „naprawdę dajemy radę”.', title_pt = 'Espírito de equipa 🥂', body_pt = 'Deixaram para trás um dia difícil. Depois de ele adormecer, sirvam-se de um chá com o seu companheiro e valorizem-se um ao outro dizendo: "Estamos mesmo a conseguir".', title_sv = 'Lagandan 🥂', body_sv = 'Ni har en tuff dag bakom er. När barnet somnat, häll upp en kopp te med din partner och uppskatta varandra med orden ”vi klarar verkligen det här”.', title_vi = 'Tinh thần đồng đội 🥂', body_vi = 'Mẹ vừa đi qua một ngày vất vả. Sau khi bé ngủ, hãy cùng bạn đời rót một tách trà và khen ngợi nhau: "Chúng mình thật sự làm được".', title_zh = '团队精神 🥂', body_zh = '你们又熬过了艰难的一天。孩子睡着后，和另一半倒杯茶，说一句“我们真的搞定了”，互相肯定一下吧。' WHERE id = 'b8751eb5-8b11-4040-9350-f54539cfefa1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Cómo te sientes? 🩸', body_es = '¿Te ha bajado la energía de repente o tienes cambios de humor? Echa un vistazo al Calendario menstrual de la app. Siguiendo tu ciclo, entenderás mejor lo que necesita tu cuerpo.', title_fr = 'Comment vous sentez-vous ? 🩸', body_fr = 'Votre énergie a chuté d''un coup ou votre humeur change souvent ? Jetez un œil au Suivi des règles dans l''appli. En suivant votre cycle, vous serez plus à l''écoute des besoins de votre corps.', title_hi = 'आप कैसा महसूस कर रही हैं? 🩸', body_hi = 'ऊर्जा अचानक कम हो गई या मूड बदलता रहता है? ऐप में पीरियड ट्रैकर देखिए। अपने चक्र पर नज़र रखकर शरीर की ज़रूरतों को बेहतर समझिए।', title_id = 'Bagaimana perasaan Anda? 🩸', body_id = 'Energi tiba-tiba menurun, atau suasana hati naik turun? Lihat Pelacak Menstruasi di aplikasi. Dengan memantau siklus, Anda bisa lebih memahami kebutuhan tubuh Anda.', title_ja = '体調はいかがですか？🩸', body_ja = '急にエネルギーが落ちたり、気分が変わりやすかったりしますか？アプリの「生理トラッカー」をのぞいてみましょう。周期を記録して、体が必要としていることにもっとやさしく寄り添いましょう。', title_ko = '요즘 어떠세요? 🩸', body_ko = '갑자기 기운이 떨어지거나 기분이 오락가락하나요? 앱의 생리 주기 기록을 살펴보세요. 주기를 기록하면 몸이 필요로 하는 것을 더 잘 이해할 수 있어요.', title_nl = 'Hoe voel je je? 🩸', body_nl = 'Is je energie ineens weg of wisselt je stemming? Kijk eens in de Cyclustracker in de app. Door je cyclus te volgen, begrijp je beter wat je lichaam nodig heeft.', title_pl = 'Jak się czujesz? 🩸', body_pl = 'Nagle spadła ci energia albo masz zmienny nastrój? Zajrzyj do Kalendarza miesiączkowego w aplikacji. Śledząc swój cykl, lepiej zrozumiesz potrzeby swojego ciała.', title_pt = 'Como se sente? 🩸', body_pt = 'A energia caiu de repente ou o humor anda instável? Espreite o Registo do Período na app. Acompanhe o seu ciclo e seja mais compreensiva com as necessidades do seu corpo.', title_sv = 'Hur mår du? 🩸', body_sv = 'Har energin plötsligt sjunkit, eller svänger humöret? Titta i Mensspåraren i appen. Följ din cykel och var mer förstående för kroppens behov.', title_vi = 'Mẹ cảm thấy thế nào? 🩸', body_vi = 'Năng lượng của mẹ bỗng tụt xuống hay tâm trạng thất thường? Hãy xem Theo dõi kỳ kinh trong ứng dụng. Theo dõi chu kỳ giúp mẹ thấu hiểu hơn những nhu cầu của cơ thể.', title_zh = '你感觉怎么样？🩸', body_zh = '精力突然下降，还是情绪起伏不定？看看应用里的经期记录。跟踪你的周期，更体贴地对待身体的需要。' WHERE id = 'dc029c20-8f5d-4aa9-a173-be7d3be13a69' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuentos imaginarios 📖', body_es = '¿Cansada de leer libros? Apaga las luces, pon el sonido de la lluvia de Ruido blanco e inventad juntos cuentos imaginarios en la oscuridad hasta quedaros dormidos.', title_fr = 'Contes imaginaires 📖', body_fr = 'Lassée de lire des livres ? Éteignez la lumière, lancez le bruit de la pluie des Bruits blancs et inventez ensemble des contes imaginaires dans le noir jusqu''à vous endormir.', title_hi = 'काल्पनिक कहानियाँ 📖', body_hi = 'किताब पढ़ते-पढ़ते ऊब गईं? बत्तियाँ बुझाइए, व्हाइट नॉइज़ में बारिश की आवाज़ लगाइए और अँधेरे में साथ मिलकर काल्पनिक कहानियाँ गढ़ते हुए सो जाइए।', title_id = 'Dongeng khayalan 📖', body_id = 'Bosan membaca buku? Matikan lampu, putar suara hujan dari Suara Putih, dan karang dongeng khayalan bersama dalam gelap hingga tertidur.', title_ja = '想像のお話 📖', body_ja = '絵本を読むのに飽きましたか？電気を消して、「ホワイトノイズ」の雨の音を流し、暗い中で一緒に空想のお話をつくりながら眠りにつきましょう。', title_ko = '상상 속 동화 📖', body_ko = '책 읽기가 지겨워졌나요? 불을 끄고 백색소음의 빗소리를 틀어 어둠 속에서 함께 상상 속 이야기를 지어내며 잠들어 보세요.', title_nl = 'Fantasiesprookjes 📖', body_nl = 'Ben je het voorlezen zat? Doe het licht uit, zet regengeluid uit Witte ruis aan en verzin samen in het donker fantasieverhalen tot jullie in slaap vallen.', title_pl = 'Wymyślone bajki 📖', body_pl = 'Macie dość czytania książek? Zgaś światło, włącz odgłos deszczu z Białego szumu i wymyślajcie razem w ciemności bajki, aż zaśniecie.', title_pt = 'Histórias imaginárias 📖', body_pt = 'Cansada de ler livros? Apague as luzes, ligue o som da chuva do Ruído Branco e inventem juntos histórias imaginárias no escuro até adormecerem.', title_sv = 'Fantasisagor 📖', body_sv = 'Trött på att läsa böcker? Släck ljuset, sätt på regnljud från Vitt brus och hitta på fantasisagor tillsammans i mörkret tills ni somnar.', title_vi = 'Truyện cổ tích tưởng tượng 📖', body_vi = 'Mẹ chán đọc sách rồi? Hãy tắt đèn, bật tiếng mưa trong Tiếng ồn trắng và cùng bé nghĩ ra những câu chuyện tưởng tượng trong bóng tối cho đến khi chìm vào giấc ngủ.', title_zh = '想象出来的故事 📖', body_zh = '读书读累了？关上灯，打开白噪音里的雨声，在黑暗中一起编些想象的故事，慢慢入睡。' WHERE id = 'df6798e4-19ad-45ba-b5f8-d0bab8fc0951' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Descubrimientos con fruta 🍏', body_es = '¿Rechaza las proteínas o las verduras? Calcula con el Seguimiento de tomas la ración de hoy y crea en Recetas para bebé combinaciones ricas, como yogur con fruta.', title_fr = 'Découvertes fruitées 🍏', body_fr = 'Il refuse les protéines ou les légumes ? Calculez sa ration du jour avec le Suivi des repas et créez de délicieuses associations, comme un yaourt aux fruits, avec les Recettes pour bébés.', title_hi = 'फलों वाली खोज 🍏', body_hi = 'प्रोटीन या सब्ज़ी नहीं खाता? फ़ीडिंग ट्रैकर से आज की मात्रा गिनिए और बच्चों की रेसिपी में फ्रूट योगर्ट जैसे स्वादिष्ट मेल बनाइए।', title_id = 'Penjelajahan buah 🍏', body_id = 'Menolak protein atau sayuran? Hitung kebutuhan hari ini dengan alat Pemantau Nutrisi dan buat kombinasi lezat seperti yogurt buah dari Resep Bayi.', title_ja = 'フルーツの発見 🍏', body_ja = 'たんぱく質や野菜を嫌がりますか？「栄養管理ツール」で今日の目安量を計算して、「離乳食を始める赤ちゃんのレシピ」でフルーツヨーグルトのようなおいしい組み合わせをつくりましょう。', title_ko = '과일로 떠나는 탐험 🍏', body_ko = '단백질이나 채소를 거부하나요? 수유 기록 도구로 오늘의 기준량을 계산하고, 아기 레시피에서 과일 요거트처럼 맛있는 조합을 만들어 보세요.', title_nl = 'Ontdekkingen met fruit 🍏', body_nl = 'Weigert hij eiwit of groente? Bereken met de Voedingstracker de norm van vandaag en maak met Babyrecepten lekkere combinaties zoals yoghurt met fruit.', title_pl = 'Owocowe odkrycia 🍏', body_pl = 'Odrzuca białko lub warzywa? Oblicz w narzędziu do śledzenia karmienia dzisiejszą normę i twórz z Przepisów dla niemowląt pyszne połączenia, np. jogurt z owocami.', title_pt = 'Descobertas com fruta 🍏', body_pt = 'Rejeita a proteína ou os legumes? Calcule com o Registo de Alimentação a dose de hoje e crie com as Receitas para bebés combinações saborosas, como iogurte com fruta.', title_sv = 'Fruktiga upptäckter 🍏', body_sv = 'Vägrar barnet protein eller grönsaker? Räkna ut dagens norm med Matningskoll och skapa goda kombinationer som yoghurt med frukt med Recept för bebisar.', title_vi = 'Khám phá trái cây 🍏', body_vi = 'Bé từ chối đạm hoặc rau? Hãy tính định mức hôm nay bằng Theo dõi cữ bú và tạo những kết hợp ngon miệng như sữa chua trái cây theo Công thức cho bé.', title_zh = '水果大发现 🍏', body_zh = '拒绝蛋白质或蔬菜？用喂养记录工具算一算今天的参考量，用宝宝食谱搭配出像水果酸奶这样美味的组合。' WHERE id = 'ebf1eb36-04dc-42ad-9b92-cfc852cf267d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Contar con los dedos 🔢', body_es = '¿Intenta decir «uno, dos, tres» al subir las escaleras o al poner en fila sus coches? Se están sentando las bases del pensamiento matemático. Contadlo todo juntos en voz alta.', title_fr = 'Compter sur ses doigts 🔢', body_fr = 'Il essaie de dire « un, deux, trois » en montant les marches ou en alignant ses voitures ? Les bases de la pensée mathématique se posent. Comptez tout à voix haute avec lui.', title_hi = 'उँगलियों पर गिनती 🔢', body_hi = 'सीढ़ियाँ चढ़ते या गाड़ियाँ लाइन में लगाते हुए ''एक, दो, तीन'' कहने की कोशिश करता है? गणित वाली सोच की नींव पड़ रही है। उसके साथ हर चीज़ ज़ोर से गिनिए।', title_id = 'Berhitung dengan jari 🔢', body_id = 'Mencoba mengucapkan satu, dua, tiga saat menaiki tangga atau menjajarkan mobil-mobilannya? Fondasi berpikir matematis sedang dibangun. Hitung semuanya bersama dengan suara lantang.', title_ja = '指で数えよう 🔢', body_ja = '階段をのぼったり、車を並べたりしながら、「いち、に、さん」と言おうとしていますか？算数の考え方の土台ができつつあります。一緒になんでも声に出して数えましょう。', title_ko = '손가락으로 세어요 🔢', body_ko = '계단을 오르거나 자동차를 줄 세우며 ''하나, 둘, 셋'' 하려고 하나요? 수학적 사고의 기초가 다져지고 있어요. 함께 큰 소리로 모든 걸 세어 보세요.', title_nl = 'Tellen op de vingers 🔢', body_nl = 'Probeert hij een, twee, drie te zeggen als hij de trap op loopt of zijn autootjes op een rij zet? De basis voor rekenkundig denken wordt gelegd. Tel samen alles hardop.', title_pl = 'Liczenie na palcach 🔢', body_pl = 'Wchodząc po schodach albo ustawiając autka, próbuje mówić „raz, dwa, trzy”? Kładzie fundamenty myślenia matematycznego. Liczcie razem wszystko na głos.', title_pt = 'Contar pelos dedos 🔢', body_pt = 'Ao subir as escadas ou alinhar os carrinhos, tenta dizer "um, dois, três"? Estão a ser lançadas as bases do pensamento matemático. Contem tudo juntos em voz alta.', title_sv = 'Räkna på fingrarna 🔢', body_sv = 'Försöker barnet säga ett, två, tre när hen går uppför trappan eller ställer upp bilarna? Grunden för matematiskt tänkande läggs. Räkna allt högt tillsammans.', title_vi = 'Đếm trên đầu ngón tay 🔢', body_vi = 'Bé cố nói "một, hai, ba" khi leo cầu thang hay xếp ô tô? Nền móng của tư duy toán học đang được đặt. Hãy cùng bé đếm to mọi thứ.', title_zh = '掰手指数数 🔢', body_zh = '爬楼梯或排小汽车时，想说“一、二、三”？数学思维的基础正在打下。和宝宝一起大声数一数身边的一切吧。' WHERE id = '14a13bdc-ca07-4dfa-9231-806da316a5bd' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respira hondo 🧘‍♀️', body_es = 'Se te ha secado la garganta de responder preguntas todo el día. En cuanto llegue el silencio a la habitación, sin mirar ninguna pantalla, simplemente respira hondo y descansa.', title_fr = 'Respirez profondément 🧘‍♀️', body_fr = 'Vous avez la gorge sèche à force de répondre à ses questions toute la journée. Dès que le silence tombe dans la chambre, reposez-vous en respirant profondément, sans regarder aucun écran.', title_hi = 'गहरी साँस 🧘‍♀️', body_hi = 'दिनभर सवालों के जवाब देते-देते गला सूख गया है। कमरे में खामोशी होते ही किसी स्क्रीन को देखे बिना बस गहरी साँस लीजिए-छोड़िए और आराम कीजिए।', title_id = 'Tarik napas dalam-dalam 🧘‍♀️', body_id = 'Tenggorokan Anda kering karena menjawab pertanyaan seharian. Begitu kamar hening, jangan lihat layar apa pun, cukup tarik dan embuskan napas dalam-dalam dan beristirahatlah.', title_ja = '深呼吸 🧘‍♀️', body_ja = '一日中質問に答えて、のどがからからですね。部屋が静かになったら、画面は見ずに、ただ深く息を吸って吐いて、休みましょう。', title_ko = '깊은 숨 🧘‍♀️', body_ko = '하루 종일 질문에 대답하느라 목이 다 말랐죠. 방이 조용해지면 화면은 보지 말고 그냥 깊게 숨을 들이쉬고 내쉬며 쉬세요.', title_nl = 'Diep ademhalen 🧘‍♀️', body_nl = 'Je keel is droog van de hele dag vragen beantwoorden. Zodra het stil is in de kamer: kijk naar geen enkel scherm, adem gewoon diep in en uit en rust uit.', title_pl = 'Głęboki oddech 🧘‍♀️', body_pl = 'Od całodziennego odpowiadania na pytania zaschło ci w gardle. Gdy tylko w pokoju zapadnie cisza, nie patrz na żaden ekran, po prostu oddychaj głęboko i odpocznij.', title_pt = 'Respire fundo 🧘‍♀️', body_pt = 'Ficou com a garganta seca de responder a perguntas o dia todo. Assim que o quarto ficar em silêncio, sem olhar para nenhum ecrã, simplesmente respire fundo e descanse.', title_sv = 'Djupt andetag 🧘‍♀️', body_sv = 'Halsen är torr efter att ha svarat på frågor hela dagen. Så fort det blir tyst i rummet, titta inte på någon skärm, andas bara djupt in och ut och vila.', title_vi = 'Hít thở sâu 🧘‍♀️', body_vi = 'Trả lời câu hỏi cả ngày khiến cổ họng mẹ khô khốc. Ngay khi phòng yên tĩnh, đừng nhìn vào màn hình nào cả, chỉ cần hít thở sâu và nghỉ ngơi.', title_zh = '深呼吸 🧘‍♀️', body_zh = '回答了一整天的问题，嗓子都干了。房间一安静下来，就别看任何屏幕，只是深深地呼吸，好好休息。' WHERE id = '8bf6a243-dbba-488e-976d-ab76ac22fdef' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té caliente y silencio 🍵', body_es = 'El temporizador se ha parado y tu peque duerme. ¡No corras a las tareas de casa! Prepárate una infusión de melisa o manzanilla de Recetas saludables, túmbate en el sofá y disfruta del silencio.', title_fr = 'Thé chaud et silence 🍵', body_fr = 'Le minuteur est arrêté, il dort. Ne vous ruez pas sur les tâches ménagères ! Préparez une tisane de mélisse ou de camomille des Recettes saines, allongez-vous sur le canapé et savourez simplement le silence.', title_hi = 'गर्म चाय और खामोशी 🍵', body_hi = 'टाइमर रुक गया, बच्चा सो गया। घर के कामों की ओर मत भागिए! सेहतमंद रेसिपी से लेमन बाम या कैमोमाइल की चाय बनाइए, सोफ़े पर लेटिए और बस खामोशी का मज़ा लीजिए।', title_id = 'Teh hangat dan keheningan 🍵', body_id = 'Timer berhenti, si kecil sudah tidur. Jangan buru-buru mengerjakan pekerjaan rumah! Seduh teh lemon balm atau chamomile dari Resep Sehat, berbaring di sofa, dan nikmati keheningan.', title_ja = '温かいお茶と静けさ 🍵', body_ja = 'タイマーは止まり、お子さんは眠りました。家事に走らないで！「ヘルシーレシピ」からレモンバームかカモミールのお茶をいれて、ソファに横になり、静けさだけを味わいましょう。', title_ko = '따뜻한 차와 고요함 🍵', body_ko = '타이머가 멈추고 아이가 잠들었어요. 집안일로 달려가지 마세요! 건강한 레시피에서 레몬밤이나 캐모마일 차를 우려 소파에 누워 오직 고요함만 즐기세요.', title_nl = 'Warme thee en stilte 🍵', body_nl = 'De timer is gestopt, je kindje slaapt. Ren niet naar het huishouden! Zet citroenmelisse- of kamillethee uit Gezonde recepten, ga op de bank liggen en geniet gewoon van de stilte.', title_pl = 'Ciepła herbata i cisza 🍵', body_pl = 'Timer zatrzymany, maluch śpi. Nie rzucaj się w wir obowiązków! Zaparz melisę lub rumianek ze Zdrowych przepisów, połóż się na kanapie i po prostu delektuj się ciszą.', title_pt = 'Chá quente e silêncio 🍵', body_pt = 'O temporizador parou, ele adormeceu. Não corra para as tarefas da casa! Prepare um chá de erva-cidreira ou de camomila das Receitas Saudáveis, deite-se no sofá e saboreie apenas o silêncio.', title_sv = 'Varmt te och tystnad 🍵', body_sv = 'Timern har stannat, barnet sover. Rusa inte till hushållssysslorna! Brygg citronmelisse- eller kamomillte från Hälsosamma recept, lägg dig på soffan och njut bara av tystnaden.', title_vi = 'Trà nóng và sự yên tĩnh 🍵', body_vi = 'Hẹn giờ đã dừng, bé đã ngủ. Đừng vội lao vào việc nhà! Hãy pha trà tía tô đất hoặc hoa cúc từ Công thức lành mạnh, nằm dài trên sofa và tận hưởng sự yên tĩnh.', title_zh = '热茶与安静 🍵', body_zh = '计时器停了，孩子睡着了。别急着去做家务！从健康食谱里泡一杯香蜂草或洋甘菊茶，躺在沙发上，好好享受这份安静。' WHERE id = 'c86b2cf3-2c86-4802-abd7-eac1fbe8e326' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Té imaginario 🍵', body_es = '¿Te incluye en sus juegos imaginarios y te pide que bebas té de una taza vacía? Forma parte de su imaginación. Estos juegos forman su inteligencia social.', title_fr = 'Dînette imaginaire 🍵', body_fr = 'Il vous embarque dans ses jeux imaginaires et vous demande de boire le thé d''une tasse vide ? Entrez dans son imaginaire. Ces jeux construisent son intelligence sociale.', title_hi = 'काल्पनिक चाय की महफ़िल 🍵', body_hi = 'आपको भी अपने काल्पनिक खेलों में शामिल करता है और खाली कप से चाय पीने को कहता है? उसकी कल्पना का हिस्सा बनिए। ये खेल उसकी सामाजिक समझ गढ़ते हैं।', title_id = 'Jamuan teh khayalan 🍵', body_id = 'Mengajak Anda ikut permainan khayalannya dan meminta Anda minum teh dari cangkir kosong? Jadilah bagian dari imajinasinya. Permainan ini membentuk kecerdasan sosialnya.', title_ja = '想像のお茶会 🍵', body_ja = 'あなたもごっこ遊びに誘って、からっぽのカップでお茶を飲むようにお願いしますか？想像の世界に参加しましょう。こうした遊びが社会的な知性を育てます。', title_ko = '상상 속 찻상 🍵', body_ko = '엄마도 상상 놀이에 끌어들여 빈 찻잔으로 차를 마시라고 하나요? 아이의 상상 속으로 들어가 보세요. 이런 놀이가 사회성 지능을 키워 줘요.', title_nl = 'Denkbeeldige theetafel 🍵', body_nl = 'Betrekt hij jou bij zijn fantasiespel en moet je thee drinken uit een leeg kopje? Word deel van zijn fantasie. Deze spelletjes vormen zijn sociale intelligentie.', title_pl = 'Wyimaginowane przyjęcie herbaciane 🍵', body_pl = 'Wciąga cię w swoje zabawy w udawanie i każe pić herbatę z pustej filiżanki? Stań się częścią jego wyobraźni. Te zabawy kształtują jego inteligencję społeczną.', title_pt = 'Lanche imaginário com chá 🍵', body_pt = 'Também a mete nas brincadeiras de faz de conta e pede-lhe para beber chá de uma chávena vazia? Faça parte da imaginação dele. Estas brincadeiras formam a inteligência social.', title_sv = 'Låtsaskalas med te 🍵', body_sv = 'Drar barnet med dig i sina låtsaslekar och vill att du dricker te ur en tom kopp? Var en del av fantasin. Dessa lekar formar barnets sociala intelligens.', title_vi = 'Tiệc trà tưởng tượng 🍵', body_vi = 'Bé rủ mẹ tham gia trò chơi tưởng tượng và mời mẹ uống trà từ tách rỗng? Hãy trở thành một phần trong trí tưởng tượng của bé. Những trò chơi này hình thành trí tuệ xã hội của bé.', title_zh = '假装的茶会 🍵', body_zh = '把你也拉进想象游戏，让你用空杯子喝茶？成为宝宝想象世界的一部分吧。这些游戏会塑造宝宝的社交智力。' WHERE id = '966fb5ae-0b22-47d8-b524-7d0d8e3e8e61' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá 📖', body_es = 'Esta noche deja descansar tus cuerdas vocales. Que papá se encargue de leer los libros favoritos de tu peque con voces distintas y de forma divertida.', title_fr = 'L''histoire de papa 📖', body_fr = 'Ce soir, reposez vos cordes vocales. Laissez papa lire ses livres préférés en changeant de voix, de façon rigolote.', title_hi = 'पापा की कहानी 📖', body_hi = 'आज शाम अपनी आवाज़ को आराम दीजिए। बच्चे की सबसे पसंदीदा किताबें अलग-अलग आवाज़ों में, मज़ेदार ढंग से पढ़ने का काम पापा को करने दीजिए।', title_id = 'Cerita dari Ayah 📖', body_id = 'Istirahatkan pita suara Anda malam ini. Biarkan Ayah yang bertugas membacakan buku favorit si kecil dengan berbagai nada suara yang lucu.', title_ja = 'パパのお話 📖', body_ja = '今夜はあなたののどを休ませましょう。お子さんの大好きな絵本を、いろいろな声色でおもしろく読む役目は、パパにお任せして。', title_ko = '아빠의 이야기 시간 📖', body_ko = '오늘 밤엔 목을 쉬게 해 주세요. 아이가 가장 좋아하는 책을 다양한 목소리로 재미있게 읽어 주는 일은 아빠에게 맡기세요.', title_nl = 'Papa''s verhaal 📖', body_nl = 'Laat je stembanden vanavond rusten. Laat papa de lievelingsboeken van je kindje grappig voorlezen met verschillende stemmetjes.', title_pl = 'Bajka od taty 📖', body_pl = 'Daj dziś wieczorem odpocząć strunom głosowym. Niech to tata czyta ulubione książeczki malucha zabawnie, różnymi głosami.', title_pt = 'A história do pai 📖', body_pt = 'Esta noite, descanse as cordas vocais. Deixe o pai ler os livros preferidos dele com vozes diferentes e de forma divertida.', title_sv = 'Pappas berättelse 📖', body_sv = 'Vila stämbanden i kväll. Låt pappa läsa barnets favoritböcker med olika röster och på ett roligt sätt.', title_vi = 'Câu chuyện của bố 📖', body_vi = 'Tối nay hãy để dây thanh quản của mẹ được nghỉ. Để bố đảm nhận việc đọc những cuốn sách bé yêu thích bằng nhiều giọng khác nhau thật hài hước.', title_zh = '爸爸讲故事 📖', body_zh = '今晚让你的嗓子休息一下。让爸爸用不同的声音、搞笑地读宝宝最爱的书吧。' WHERE id = 'cab52685-d8da-4cce-a78e-b76068863ea1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No llorar al caerse 🧗‍♂️', body_es = '¿Cuando se cae un poco no llora enseguida, sino que mira tu reacción y luego decide? No te alarmes: sonríe y dile «No pasa nada, eres fuerte».', title_fr = 'Ne pas pleurer en tombant 🧗‍♂️', body_fr = 'Quand il tombe légèrement, il ne pleure pas tout de suite mais regarde votre réaction avant de décider ? Pas de panique : souriez et dites « Ce n''est rien, tu es fort ».', title_hi = 'गिरने पर न रोना 🧗‍♂️', body_hi = 'हल्का सा गिरने पर तुरंत नहीं रोता, पहले आपकी प्रतिक्रिया देखता है फिर तय करता है? घबराइए मत, मुस्कुराकर कहिए ''कुछ नहीं हुआ, तुम बहादुर हो''।', title_id = 'Tidak menangis saat jatuh 🧗‍♂️', body_id = 'Saat jatuh ringan, ia tidak langsung menangis, tapi melihat reaksi Anda dulu? Jangan panik, tersenyumlah dan katakan: tidak apa-apa, kamu kuat.', title_ja = '転んでも泣かない 🧗‍♂️', body_ja = '軽く転んだとき、すぐには泣かず、あなたの反応を見てから決めていますか？慌てないで、ほほえみながら「大丈夫、あなたは強いね」と声をかけましょう。', title_ko = '넘어져도 울지 않기 🧗‍♂️', body_ko = '살짝 넘어졌을 때 바로 울지 않고 엄마의 반응을 본 뒤 결정하나요? 당황하지 말고 웃으며 ''괜찮아, 넌 씩씩해'' 하고 말해 주세요.', title_nl = 'Niet huilen bij vallen 🧗‍♂️', body_nl = 'Huilt hij niet meteen als hij zachtjes valt, maar kijkt hij eerst naar jouw reactie? Raak niet in paniek, glimlach en zeg: er is niks aan de hand, je bent sterk.', title_pl = 'Upadek bez płaczu 🧗‍♂️', body_pl = 'Gdy lekko się przewróci, nie płacze od razu, tylko patrzy na twoją reakcję i wtedy decyduje? Nie panikuj, z uśmiechem powiedz: „Nic się nie stało, jesteś silny”.', title_pt = 'Não chorar quando cai 🧗‍♂️', body_pt = 'Quando cai de leve, não chora logo e olha primeiro para a sua reação antes de decidir? Não entre em pânico, sorria e diga: "Não foi nada, és forte".', title_sv = 'Gråter inte när hen ramlar 🧗‍♂️', body_sv = 'Gråter barnet inte direkt när hen ramlar lite, utan tittar på din reaktion och bestämmer sig sedan? Få inte panik, le och säg ”det är ingen fara, du är stark”.', title_vi = 'Ngã mà không khóc 🧗‍♂️', body_vi = 'Khi ngã nhẹ, bé không khóc ngay mà nhìn phản ứng của mẹ rồi mới quyết định? Đừng hốt hoảng, hãy mỉm cười và nói "Không sao đâu, con mạnh mẽ lắm".', title_zh = '摔倒了不哭 🧗‍♂️', body_zh = '轻轻摔一下不马上哭，而是先看你的反应再决定？别慌，微笑着说“没事的，你很坚强”。' WHERE id = '380a71ea-f755-4ca8-a25d-c156eefcd118' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿Le da miedo la oscuridad?  🌙', body_es = 'Pon una lucecita de noche pequeña y de tono cálido junto a su cama. Deja el resto de la habitación totalmente a oscuras para favorecer la producción de melatonina.', title_fr = 'Il a peur du noir ?  🌙', body_fr = 'Placez une petite veilleuse à la lumière chaude près de son lit. Gardez le reste de la chambre dans l''obscurité complète pour favoriser la production de mélatonine.', title_hi = 'अँधेरे से डरता है? 🌙', body_hi = 'उसके बिस्तर के पास एक छोटा, गर्म रंग का नाइट लैंप रखिए। बाकी पूरे कमरे में मेलाटोनिन बनने के लिए पूरा अँधेरा रखिए।', title_id = 'Takut gelap?  🌙', body_id = 'Letakkan lampu tidur kecil berwarna hangat di samping tempat tidurnya. Biarkan bagian kamar lainnya benar-benar gelap untuk mendukung produksi melatonin.', title_ja = '暗いのがこわい？  🌙', body_ja = 'ベッドのそばに、小さな暖色系のナイトライトを置きましょう。メラトニンがしっかり分泌されるよう、ほかの部分は真っ暗にしておきましょう。', title_ko = '어둠이 무서워요? 🌙', body_ko = '침대 옆에 작고 따뜻한 색의 수면등을 두세요. 나머지 방은 멜라토닌 분비를 위해 완전히 어둡게 해 주세요.', title_nl = 'Bang in het donker? 🌙', body_nl = 'Zet een klein nachtlampje met warm licht naast zijn bed. Houd de rest van de kamer helemaal donker voor de aanmaak van melatonine.', title_pl = 'Boi się ciemności?  🌙', body_pl = 'Postaw przy jego łóżku małą lampkę nocną o ciepłej barwie. Resztę pokoju zostaw całkowicie ciemną, żeby wydzielała się melatonina.', title_pt = 'Tem medo do escuro? 🌙', body_pt = 'Ponha junto à cama uma pequena luz de presença de cor quente. Mantenha o resto do quarto totalmente escuro para a libertação de melatonina.', title_sv = 'Rädd för mörkret?  🌙', body_sv = 'Ställ en liten nattlampa med varmt ljus vid sängen. Håll resten av rummet helt mörkt för melatoninets skull.', title_vi = 'Bé sợ bóng tối? 🌙', body_vi = 'Hãy đặt một chiếc đèn ngủ nhỏ, ánh sáng ấm cạnh giường bé. Phần còn lại của phòng thì giữ tối hoàn toàn để cơ thể tiết melatonin.', title_zh = '怕黑吗？ 🌙', body_zh = '在床边放一盏暖色的小夜灯。房间其余的地方保持全黑，有助于分泌褪黑素。' WHERE id = '77a38e1b-ddf2-4519-806e-48198f93ac3a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Enemistad con las verduras 🥦', body_es = '¿Aparta todas las verduras de la sopa? Busca otras alternativas en el Plan de alimentación. Esconder las verduras dentro de las albóndigas es el truco de madre más antiguo.', title_fr = 'La guerre aux légumes 🥦', body_fr = 'Il met de côté tous les légumes de sa soupe ? Cherchez d''autres alternatives dans son plan alimentaire. Cacher les légumes dans des boulettes, c''est la plus vieille astuce de maman.', title_hi = 'सब्ज़ियों से दुश्मनी 🥦', body_hi = 'सूप की सारी सब्ज़ियाँ एक तरफ़ कर देता है? फ़ीडिंग प्लान में उसके लिए दूसरे विकल्प ढूँढिए। सब्ज़ियों को कटलेट में छिपाना माँओं की सबसे पुरानी तरकीब है।', title_id = 'Musuhan dengan sayuran 🥦', body_id = 'Menyisihkan semua sayuran di supnya? Cari alternatif lain di Rencana Nutrisinya. Menyembunyikan sayuran di dalam perkedel adalah trik ibu yang paling klasik.', title_ja = '野菜との戦い 🥦', body_ja = 'スープの野菜を全部よけていますか？「栄養管理ツール」でいろいろな代わりのメニューを探してみましょう。野菜をハンバーグの中に隠すのは、いちばん昔からあるママの技です。', title_ko = '채소와의 전쟁 🥦', body_ko = '수프 속 채소를 모두 골라내나요? 식단 계획에서 다른 대안을 찾아보세요. 채소를 커틀릿 속에 숨기는 건 가장 오래된 엄마의 비법이에요.', title_nl = 'Vijandschap met groente 🥦', body_nl = 'Haalt hij alle groenten uit zijn soep? Zoek in het Voedingsplan andere alternatieven. Groenten in gehaktballetjes verstoppen is de oudste moedertruc.', title_pl = 'Wrogość wobec warzyw 🥦', body_pl = 'Odkłada na bok wszystkie warzywa z zupy? Poszukaj w planie karmienia innych alternatyw. Ukrywanie warzyw w kotlecikach to najstarsza sztuczka mam.', title_pt = 'Inimizade com os legumes 🥦', body_pt = 'Separa todos os legumes da sopa? Procure alternativas no Registo de Alimentação. Esconder os legumes dentro de croquetes é o truque de mãe mais antigo.', title_sv = 'Grönsaksfientlighet 🥦', body_sv = 'Lägger barnet alla grönsaker i soppan åt sidan? Leta efter andra alternativ i matplanen. Att gömma grönsaker i biffar är det äldsta mammaknepet.', title_vi = 'Kẻ thù của rau củ 🥦', body_vi = 'Bé gạt hết rau trong bát canh ra một bên? Hãy tìm những lựa chọn khác cho bé trong Kế hoạch dinh dưỡng. Giấu rau trong chả viên là mẹo lâu đời nhất của các mẹ.', title_zh = '和蔬菜作对 🥦', body_zh = '把汤里的蔬菜全挑到一边？在喂养计划里给宝宝找些不同的替代选择。把蔬菜藏进肉饼里，是妈妈们最古老的妙招。' WHERE id = 'b3b925ae-8f35-4c41-918e-ce24c80daa1b' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'No existe la madre perfecta 💬', body_es = '¿Te sientes mal porque no puedes hacerlo todo a la vez? Entra ya en la Comunidad Anacan. Las confesiones sinceras de otras madres te darán fuerza.', title_fr = 'La maman parfaite n''existe pas 💬', body_fr = 'Vous vous sentez mal de ne pas pouvoir tout faire en même temps ? Rejoignez tout de suite la Communauté Anacan. Les confidences sincères des mamans vous donneront de la force.', title_hi = 'परफ़ेक्ट माँ कोई नहीं होती 💬', body_hi = 'एक साथ सब कुछ नहीं कर पातीं, इसलिए बुरा लगता है? तुरंत Anacan कम्युनिटी में जाइए। वहाँ की माँओं की सच्ची बातें आपको ताकत देंगी।', title_id = 'Tidak ada ibu yang sempurna 💬', body_id = 'Merasa buruk karena tidak bisa melakukan semuanya sekaligus? Segera bergabung dengan Komunitas Anacan. Pengakuan jujur ibu-ibu di sana akan memberi Anda kekuatan.', title_ja = '完璧なママなんていない 💬', body_ja = 'すべてを同時にこなせなくて、落ちこんでいますか？すぐにAnacanコミュニティに参加しましょう。ママたちの率直な打ち明け話が、あなたに力をくれます。', title_ko = '완벽한 엄마는 없어요 💬', body_ko = '모든 걸 한꺼번에 해내지 못해 속상한가요? 바로 Anacan 커뮤니티에 들어가 보세요. 엄마들의 솔직한 고백이 힘이 되어 줄 거예요.', title_nl = 'De perfecte moeder bestaat niet 💬', body_nl = 'Voel je je slecht omdat je niet alles tegelijk kunt doen? Word meteen lid van de Anacan Community. De eerlijke verhalen van de moeders daar geven je kracht.', title_pl = 'Nie ma idealnych mam 💬', body_pl = 'Czujesz się źle, bo nie dajesz rady robić wszystkiego naraz? Od razu dołącz do Społeczności Anacan. Szczere wyznania innych mam dodadzą ci sił.', title_pt = 'Não há mães perfeitas 💬', body_pt = 'Sente-se mal por não conseguir fazer tudo ao mesmo tempo? Entre já na Comunidade Anacan. Os desabafos sinceros das mães de lá vão dar-lhe força.', title_sv = 'Det finns ingen perfekt mamma 💬', body_sv = 'Mår du dåligt för att du inte kan göra allt på en gång? Gå direkt till Anacans Community. Mammornas uppriktiga bekännelser där ger dig kraft.', title_vi = 'Không có người mẹ hoàn hảo 💬', body_vi = 'Mẹ thấy tệ vì không thể làm mọi thứ cùng lúc? Hãy vào ngay Cộng đồng Anacan. Những lời tâm sự chân thành của các mẹ ở đó sẽ tiếp thêm sức mạnh cho mẹ.', title_zh = '没有完美的妈妈 💬', body_zh = '因为没法同时做好所有事而难过？马上进入Anacan社区。那里妈妈们真诚的分享会给你力量。' WHERE id = '16c277b4-79fe-460a-b9a5-72a7e8683280' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pasión por garabatear 🖍️', body_es = 'La forma de coger el lápiz está cambiando y hace trazos con intención en el papel. Marca sin falta este gran avance de su motricidad fina en el Seguimiento del desarrollo.', title_fr = 'L''envie de gribouiller 🖍️', body_fr = 'Sa façon de tenir le crayon change et il trace des traits volontaires sur le papier. Notez absolument ce formidable progrès de motricité fine dans le Suivi de développement.', title_hi = 'आड़ी-तिरछी लकीरों का शौक 🖍️', body_hi = 'पेन पकड़ने का तरीका बदल रहा है और वह कागज़ पर सोच-समझकर लकीरें बनाता है। ग्रोथ ट्रैकर में बारीक मोटर स्किल्स की इस शानदार प्रगति को ज़रूर दर्ज कीजिए।', title_id = 'Hobi mencoret-coret 🖍️', body_id = 'Cara memegang pensilnya berubah dan ia membuat garis yang terarah di kertas. Pastikan menandai kemajuan motorik halus yang luar biasa ini di Pelacak Perkembangan.', title_ja = 'お絵かきが大好き 🖍️', body_ja = 'ペンの持ち方が変わって、紙に目的を持った線を描いていますか？この手先の運動のすばらしい進歩を、「発達トラッカー」にぜひ記録しましょう。', title_ko = '끄적끄적 낙서 사랑 🖍️', body_ko = '연필 쥐는 모양이 달라지고 종이에 의도를 담은 선을 그리나요? 성장 기록에 소근육의 멋진 발전을 꼭 표시해 두세요.', title_nl = 'Zin om te krabbelen 🖍️', body_nl = 'Hij houdt zijn potlood anders vast en zet doelgerichte lijnen op papier. Noteer deze prachtige vooruitgang in de fijne motoriek zeker in de Groeitracker.', title_pl = 'Zapał do bazgrania 🖍️', body_pl = 'Zmienia się sposób trzymania kredki, a na kartce pojawiają się celowe kreski. Koniecznie zaznacz ten wspaniały postęp motoryki małej w Śledzeniu rozwoju.', title_pt = 'O gosto de rabiscar 🖍️', body_pt = 'A forma de pegar no lápis está a mudar e faz traços intencionais no papel. Assinale sem falta no Registo de Desenvolvimento este progresso fantástico da motricidade fina.', title_sv = 'Lust att klottra 🖍️', body_sv = 'Sättet att hålla pennan ändras och barnet gör avsiktliga streck på papperet. Glöm inte att markera detta fantastiska framsteg i finmotoriken i Utvecklingsspåraren.', title_vi = 'Mê vẽ nguệch ngoạc 🖍️', body_vi = 'Cách bé cầm bút đã thay đổi và bé vẽ những nét có chủ đích trên giấy. Nhất định hãy đánh dấu bước tiến tuyệt vời về vận động tinh này trong Theo dõi phát triển.', title_zh = '爱上涂鸦 🖍️', body_zh = '握笔的姿势在变化，能在纸上画出有目的的线条了？一定要在发育追踪里标记这次精细动作的了不起的进步。' WHERE id = '2e1e3e82-a2d5-4c25-a5ab-d3b0a7f4df86' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Recarga de café ☕', body_es = 'El ajetreo del día te ha dejado sin fuerzas. Déjale 15 minutos con una actividad segura (por ejemplo, colorear) y no te saltes tu recarga de café.', title_fr = 'Recharge au café ☕', body_fr = 'Les courses de la journée vous ont épuisée. Laissez-le 15 minutes avec une activité sans danger (comme le coloriage) et faites absolument votre recharge de café.', title_hi = 'कॉफ़ी से चार्ज ☕', body_hi = 'दिन की भागदौड़ ने आपको थका दिया है। उसे 15 मिनट किसी सुरक्षित गतिविधि (जैसे रंग भरना) में लगा दीजिए और खुद को कॉफ़ी से ज़रूर चार्ज कीजिए।', title_id = 'Isi ulang kopi ☕', body_id = 'Kesibukan siang hari menguras tenaga Anda. Biarkan ia asyik dengan kegiatan aman selama 15 menit (misalnya mewarnai), dan pastikan Anda mengisi ulang tenaga dengan kopi.', title_ja = 'コーヒーで充電 ☕', body_ja = '日中のばたばたで、くたくたですね。お子さんに15分間、安全な遊び（たとえばぬり絵）をさせて、あなたはコーヒーで必ず充電しましょう。', title_ko = '커피로 충전 ☕', body_ko = '낮의 정신없는 시간에 기운이 다 빠졌죠. 아이에게 15분 동안 안전한 놀이(색칠하기 등)를 맡기고 꼭 커피로 충전하세요.', title_nl = 'Opladen met koffie ☕', body_nl = 'Het gerren overdag heeft je uitgeput. Laat hem 15 minuten iets veiligs doen (bijvoorbeeld kleuren) en laad jezelf zeker op met een koffie.', title_pl = 'Kawowe ładowanie ☕', body_pl = 'Dzienna bieganina odebrała ci siły. Zostaw go na 15 minut z bezpiecznym zajęciem (np. kolorowanką) i koniecznie naładuj się kawą.', title_pt = 'Recarga de café ☕', body_pt = 'A correria do dia deixou-a sem forças. Deixe-o 15 minutos com uma atividade segura (por exemplo, pintar) e faça sem falta a sua recarga de café.', title_sv = 'Kaffeladdning ☕', body_sv = 'Dagens springande har tagit all din kraft. Låt barnet ägna sig åt en säker aktivitet i 15 minuter (till exempel färgläggning) och ladda dig själv med kaffe.', title_vi = 'Sạc năng lượng bằng cà phê ☕', body_vi = 'Chạy ngược chạy xuôi cả ngày khiến mẹ kiệt sức. Hãy để bé với một hoạt động an toàn 15 phút (ví dụ tô màu) và nhất định nạp năng lượng bằng ly cà phê của mình.', title_zh = '咖啡充电 ☕', body_zh = '白天的忙乱让你筋疲力尽。给宝宝安排一个15分钟的安全活动（比如涂色），你一定要给自己充个咖啡电。' WHERE id = '72b641f0-637f-48cd-8a37-fcd8fc3414bf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lanzamientos precisos ⚾', body_es = '¿Ya intenta atrapar con los brazos la pelota grande que le lanzas e incluso devolverla? Su coordinación ojo-mano se desarrolla rápido. Jugad juntos a la pelota en el pasillo.', title_fr = 'Lancers précis ⚾', body_fr = 'Il essaie déjà d''attraper avec ses bras le gros ballon que vous lui lancez, et même de le renvoyer ? Sa coordination œil-main progresse vite. Jouez au ballon ensemble dans le couloir.', title_hi = 'सटीक थ्रो ⚾', body_hi = 'आपकी फेंकी बड़ी गेंद को अब बाँहों से पकड़ने और वापस फेंकने की भी कोशिश करता है? आँख और हाथ का तालमेल तेज़ी से बढ़ रहा है। गलियारे में साथ मिलकर गेंद खेलिए।', title_id = 'Lemparan yang tepat ⚾', body_id = 'Ia sudah mencoba menangkap bola besar yang Anda lempar dengan kedua lengannya, bahkan melemparnya kembali? Koordinasi mata-tangannya berkembang pesat. Bermainlah bola bersama di lorong.', title_ja = '上手に投げる ⚾', body_ja = 'あなたが投げた大きなボールを、腕でキャッチしたり、投げ返したりしようとしていますか？目と手の協調がぐんぐん発達しています。廊下で一緒にボール遊びをしましょう。', title_ko = '정확한 던지기 ⚾', body_ko = '던져 준 큰 공을 두 팔로 받거나 다시 던지려고 하나요? 눈과 손의 협응력이 빠르게 자라고 있어요. 복도에서 함께 공놀이를 해 보세요.', title_nl = 'Gerichte worpen ⚾', body_nl = 'Probeert hij de grote bal die je gooit al met zijn armen te vangen en zelfs terug te gooien? Zijn oog-handcoördinatie ontwikkelt zich snel. Speel samen bal in de gang.', title_pl = 'Celne rzuty ⚾', body_pl = 'Próbuje już łapać rękami dużą piłkę, którą do niego rzucasz, a nawet odrzucać? Koordynacja oko-ręka szybko się rozwija. Pograjcie razem w piłkę w korytarzu.', title_pt = 'Lançamentos certeiros ⚾', body_pt = 'Já tenta apanhar com os braços a bola grande que lhe atira e até devolvê-la? A coordenação olho-mão está a desenvolver-se depressa. Joguem à bola juntos no corredor.', title_sv = 'Träffsäkra kast ⚾', body_sv = 'Försöker barnet redan fånga den stora bollen du kastar med armarna och till och med kasta tillbaka den? Öga-hand-koordinationen utvecklas snabbt. Spela boll tillsammans i hallen.', title_vi = 'Những cú ném chính xác ⚾', body_vi = 'Bé đã cố dùng hai tay bắt quả bóng lớn mẹ ném, thậm chí ném trả lại? Phối hợp tay mắt đang phát triển nhanh. Hãy cùng bé chơi bóng ngoài hành lang.', title_zh = '精准投掷 ⚾', body_zh = '你扔过去的大球，宝宝已经想用胳膊接住，甚至扔回来了？手眼协调发展得很快。在走廊里一起玩球吧。' WHERE id = '35817a20-39d6-4243-8610-08e856df9e52' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Transición musical 🛀', body_es = '¿La rutina de la noche se ha complicado? Mientras se da un baño templado, pon de fondo música clásica relajante. La armonía del agua y la música ablanda hasta al niño más tozudo.', title_fr = 'Une transition en musique 🛀', body_fr = 'Le rituel du soir devient difficile ? Pendant le bain tiède, mettez une musique classique apaisante en fond. L''harmonie de l''eau et de la musique adoucit même l''enfant le plus obstiné.', title_hi = 'संगीत के साथ बदलाव 🛀', body_hi = 'शाम का रूटीन मुश्किल हो गया है? गुनगुने पानी से नहलाते समय पीछे सुकून देने वाला क्लासिकल संगीत लगाइए। पानी और संगीत का मेल सबसे ज़िद्दी बच्चे को भी नरम कर देता है।', title_id = 'Peralihan dengan musik 🛀', body_id = 'Rutinitas malam makin sulit? Putar musik klasik yang menenangkan saat ia berendam air hangat. Harmoni air dan musik bisa meluluhkan anak yang paling keras kepala sekalipun.', title_ja = '音楽で切りかえ 🛀', body_ja = '夜の習慣が大変になってきましたか？ぬるめのお風呂に入るときに、BGMに落ち着いたクラシック音楽を流しましょう。水と音楽のハーモニーは、どんながんこな子の心もほぐしてくれます。', title_ko = '음악으로 넘어가기 🛀', body_ko = '저녁 일과가 힘들어졌나요? 따뜻한 물에 목욕할 때 잔잔한 클래식 음악을 틀어 주세요. 물과 음악의 조화는 가장 고집 센 아이도 부드럽게 만들어요.', title_nl = 'Muzikale overgang 🛀', body_nl = 'Is het avondritueel lastiger geworden? Zet in een lauw bad rustige klassieke muziek op de achtergrond aan. De harmonie van water en muziek maakt zelfs het koppigste kind zacht.', title_pl = 'Muzyczne przejście 🛀', body_pl = 'Wieczorny rytuał stał się trudny? Podczas ciepłej kąpieli włącz w tle kojącą muzykę klasyczną. Harmonia wody i muzyki zmiękcza nawet najbardziej upartego malucha.', title_pt = 'Transição com música 🛀', body_pt = 'A rotina da noite ficou difícil? Durante o banho morno, ponha música clássica calmante de fundo. A harmonia da água e da música amolece até a criança mais teimosa.', title_sv = 'Övergång med musik 🛀', body_sv = 'Har kvällsrutinen blivit svår? Sätt på lugnande klassisk musik i bakgrunden under det ljumma badet. Harmonin mellan vatten och musik mjukar upp även det envisaste barnet.', title_vi = 'Chuyển tiếp bằng âm nhạc 🛀', body_vi = 'Nếp sinh hoạt buổi tối trở nên khó khăn? Khi tắm nước ấm, hãy bật nhạc cổ điển êm dịu làm nền. Sự hòa quyện của nước và âm nhạc làm mềm cả đứa trẻ bướng bỉnh nhất.', title_zh = '音乐过渡 🛀', body_zh = '晚上的流程越来越难？洗温水澡时放一些舒缓的古典音乐作为背景。水和音乐的和谐，连最倔强的孩子也会变温柔。' WHERE id = '801c2145-44f5-4f5c-b680-cdaa0cf58a86' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rechazo de la siesta 🥱', body_es = '¿Otra vez no se ha dormido? No luches ni os agotéis los dos. Hojear un libro en silencio en la habitación también es una forma de descanso para el cerebro.', title_fr = 'Refus de la sieste 🥱', body_fr = 'Il ne s''est encore pas endormi ? Ne vous battez pas, vous vous épuiseriez tous les deux. Feuilleter un livre en silence dans la chambre, c''est aussi un repos pour le cerveau.', title_hi = 'दिन की नींद से इनकार 🥱', body_hi = 'फिर से नहीं सोया? ज़बरदस्ती करके उसे और खुद को मत थकाइए। कमरे में चुपचाप किताब पलटना भी दिमाग के लिए एक तरह का आराम है।', title_id = 'Menolak tidur siang 🥱', body_id = 'Lagi-lagi tidak tidur? Jangan melawannya sampai ia dan Anda sama-sama lelah. Membuka-buka buku dengan tenang di kamar juga merupakan cara otak beristirahat.', title_ja = 'お昼寝を嫌がる 🥱', body_ja = 'また眠らなかった？戦ってお子さんもあなたも疲れさせないで。部屋で静かに絵本をめくるのも、脳にとってはひとつの休息です。', title_ko = '낮잠 거부 🥱', body_ko = '또 잠들지 않았나요? 씨름하며 아이와 엄마 모두 지치지 마세요. 방에서 조용히 책장을 넘기는 것도 뇌에게는 휴식이에요.', title_nl = 'Geen middagdutje 🥱', body_nl = 'Weer niet in slaap gevallen? Ga de strijd niet aan en put jullie allebei niet uit. Rustig in de kamer door een boek bladeren is ook een vorm van rust voor de hersenen.', title_pl = 'Odmowa drzemki 🥱', body_pl = 'Znów nie zasnął? Nie walcz, żeby nie zmęczyć ani jego, ani siebie. Ciche przeglądanie książki w pokoju to też rodzaj odpoczynku dla mózgu.', title_pt = 'Recusa a sesta 🥱', body_pt = 'Voltou a não adormecer? Não lute e não se cansem os dois. Folhear um livro em silêncio no quarto também é uma forma de descanso para o cérebro.', title_sv = 'Vägrar dagsömn 🥱', body_sv = 'Somnade barnet inte igen? Kämpa inte och trötta ut både barnet och dig själv. Att tyst bläddra i böcker i rummet är också ett slags vila för hjärnan.', title_vi = 'Từ chối giấc ngủ ngày 🥱', body_vi = 'Bé lại không ngủ? Đừng giằng co khiến cả hai mệt mỏi. Lặng lẽ lật sách trong phòng cũng là một cách nghỉ ngơi cho não bộ.', title_zh = '拒绝午睡 🥱', body_zh = '又没睡着？别和宝宝较劲，把宝宝和你自己都累坏。在房间里安静地翻翻书，对大脑也是一种休息。' WHERE id = 'e1b2a066-88e9-4a4f-9df5-3af6a5d26b79' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Expresar los sentimientos 📝', body_es = '¿Hoy estás agotadísima o te ha dicho una palabra muy dulce? En ambos casos, abre el Diario de ánimo y guarda este momento para el futuro.', title_fr = 'Exprimer ses émotions 📝', body_fr = 'Vous êtes épuisée aujourd''hui ou il a dit un mot adorable ? Dans les deux cas, ouvrez le Journal d''humeur et notez ce moment pour plus tard.', title_hi = 'भावनाओं को शब्द दें 📝', body_hi = 'आज बेहद थक गईं या उसने कोई बहुत प्यारी बात कही? दोनों ही सूरत में मूड डायरी खोलिए और इस पल को भविष्य के लिए तारीख के साथ लिख लीजिए।', title_id = 'Mengungkapkan perasaan 📝', body_id = 'Hari ini Anda luar biasa lelah, atau ia mengucapkan kata yang sangat manis? Apa pun itu, buka Buku Harian Suasana Hati dan catat momen ini untuk masa depan.', title_ja = '気持ちを言葉に 📝', body_ja = '今日はへとへとに疲れましたか？それとも、お子さんがとてもかわいい言葉を言いましたか？どちらにしても「気分日記」を開いて、この瞬間を未来のために記録しましょう。', title_ko = '감정 표현하기 📝', body_ko = '오늘 미칠 듯이 지쳤나요, 아니면 아이가 아주 귀여운 말을 했나요? 어느 쪽이든 기분 일기를 열어 이 순간을 미래를 위해 기록해 두세요.', title_nl = 'Gevoelens uiten 📝', body_nl = 'Was je vandaag doodmoe of zei hij iets heel liefs? Open in beide gevallen je Stemmingsdagboek en leg dit moment vast voor later.', title_pl = 'Wyrażanie uczuć 📝', body_pl = 'Dziś jesteś potwornie zmęczona albo on powiedział coś bardzo słodkiego? W obu przypadkach otwórz Dziennik nastroju i zapisz tę chwilę na przyszłość.', title_pt = 'Expressar os sentimentos 📝', body_pt = 'Hoje ficou exausta ou ele disse uma palavra muito doce? Em qualquer dos casos, abra o Diário de Humor e registe este momento para o futuro.', title_sv = 'Uttryck känslorna 📝', body_sv = 'Var du galet trött i dag, eller sa barnet ett väldigt sött ord? Oavsett vilket, öppna Humördagboken och spara ögonblicket för framtiden.', title_vi = 'Bày tỏ cảm xúc 📝', body_vi = 'Hôm nay mẹ mệt rã rời hay bé vừa nói một câu thật đáng yêu? Dù là gì, hãy mở Nhật ký tâm trạng và ghi lại khoảnh khắc này cho tương lai.', title_zh = '表达感受 📝', body_zh = '今天累到发疯，还是宝宝说了一句特别可爱的话？无论哪种，都打开心情日记，把这一刻记下来留给未来。' WHERE id = '17487e3f-403d-4b65-ab45-c514d335d8cb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La batalla de lavarse los dientes 🦷', body_es = '¿No te deja acercarle el cepillo a la boca? No lo conviertas en una obligación, sino en un juego. Deja que te lave los dientes a ti y luego le toca a él.', title_fr = 'La bataille du brossage de dents 🦷', body_fr = 'Il ne laisse pas la brosse s''approcher de sa bouche ? N''en faites pas une obligation mais un jeu. Laissez-le vous brosser les dents, puis ce sera votre tour.', title_hi = 'दाँत ब्रश करने की जंग 🦷', body_hi = 'ब्रश मुँह के पास नहीं आने देता? इसे मजबूरी नहीं, खेल बनाइए। उसे आपके दाँत ब्रश करने दीजिए, फिर अगली बारी आपकी।', title_id = 'Perang sikat gigi 🦷', body_id = 'Tidak mau sikat gigi didekatkan ke mulutnya? Jadikan permainan, bukan paksaan. Biarkan ia menyikat gigi Anda dulu, lalu giliran Anda.', title_ja = '歯みがきバトル 🦷', body_ja = '歯ブラシを口に近づけさせてくれない？無理やりではなく、遊びに変えましょう。まずお子さんにあなたの歯をみがかせて、次はあなたの番です。', title_ko = '양치 전쟁 🦷', body_ko = '칫솔을 입 가까이 대지도 못하게 하나요? 억지로 하지 말고 놀이로 바꿔 보세요. 먼저 아이가 엄마 이를 닦게 하고, 다음은 아이 차례예요.', title_nl = 'Strijd om het tandenpoetsen 🦷', body_nl = 'Laat hij de borstel niet in de buurt van zijn mond komen? Maak er geen verplichting, maar een spel van. Laat hem jouw tanden poetsen, en daarna ben jij aan de beurt.', title_pl = 'Bitwa o mycie ząbków 🦷', body_pl = 'Nie pozwala zbliżyć szczoteczki do buzi? Zamień to nie w przymus, tylko w zabawę. Pozwól mu umyć twoje zęby, a potem twoja kolej.', title_pt = 'A guerra da escova de dentes 🦷', body_pt = 'Não deixa aproximar a escova da boca? Transforme isto num jogo, não numa obrigação. Deixe-o escovar-lhe os dentes a si e depois é a sua vez.', title_sv = 'Kampen om tandborstningen 🦷', body_sv = 'Låter barnet dig inte föra tandborsten mot munnen? Gör det till en lek, inte ett tvång. Låt barnet borsta dina tänder först, och sedan är det din tur.', title_vi = 'Cuộc chiến đánh răng 🦷', body_vi = 'Bé không cho đưa bàn chải lại gần miệng? Hãy biến việc này thành trò chơi chứ đừng ép buộc. Để bé đánh răng cho mẹ trước, rồi sau đó đến lượt mẹ.', title_zh = '刷牙大战 🦷', body_zh = '不让牙刷靠近嘴巴？别强迫，把它变成游戏。先让宝宝给你刷牙，然后轮到你。' WHERE id = '343623a3-2f2a-4afd-99aa-b377f0610f4c' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juego libre 🧸', body_es = 'No tienes que entretenerle cada minuto. Aburrirse es el principio de la creatividad en los niños. Deja que descubra algo él solo en la habitación.', title_fr = 'Jeu libre 🧸', body_fr = 'Vous n''êtes pas obligée de l''amuser à chaque minute. S''ennuyer, c''est le début de la créativité chez l''enfant. Laissez-le découvrir quelque chose tout seul dans la pièce.', title_hi = 'खुला खेल 🧸', body_hi = 'आपको हर पल उसका मनोरंजन करना ज़रूरी नहीं। ऊबना बच्चों के लिए रचनात्मकता की शुरुआत है। उसे कमरे में अकेले कुछ खोजने दीजिए।', title_id = 'Bermain bebas 🧸', body_id = 'Anda tidak harus menghiburnya setiap menit. Rasa bosan adalah awal kreativitas bagi anak. Biarkan ia menemukan sesuatu sendiri di kamar.', title_ja = '自由に遊ぶ 🧸', body_ja = 'いつもお子さんを楽しませなくても大丈夫。退屈は、子どもにとって創造力のはじまりです。部屋でひとりで何かを探検させてあげましょう。', title_ko = '자유 놀이 🧸', body_ko = '매 순간 아이를 즐겁게 해 줄 필요는 없어요. 심심함은 아이에게 창의력의 시작이에요. 방에서 혼자 무언가를 발견하게 두세요.', title_nl = 'Vrij spel 🧸', body_nl = 'Je hoeft hem niet elke minuut te vermaken. Verveling is voor kinderen het begin van creativiteit. Laat hem zelf iets ontdekken in de kamer.', title_pl = 'Swobodna zabawa 🧸', body_pl = 'Nie musisz zabawiać go w każdej minucie. Nuda to dla dzieci początek kreatywności. Pozwól mu samodzielnie coś odkryć w pokoju.', title_pt = 'Brincadeira livre 🧸', body_pt = 'Não tem de o entreter a cada minuto. Aborrecer-se é, para as crianças, o início da criatividade. Deixe-o descobrir alguma coisa sozinho no quarto.', title_sv = 'Fri lek 🧸', body_sv = 'Du måste inte underhålla barnet varje minut. Uttråkning är början på kreativitet för barn. Låt barnet upptäcka något på egen hand i rummet.', title_vi = 'Chơi tự do 🧸', body_vi = 'Mẹ không cần lúc nào cũng phải giải trí cho bé. Cảm giác buồn chán chính là khởi đầu của sự sáng tạo ở trẻ. Hãy để bé tự khám phá điều gì đó trong phòng.', title_zh = '自由玩耍 🧸', body_zh = '你不必每分钟都陪宝宝玩。无聊是孩子创造力的起点。让宝宝在房间里自己去探索吧。' WHERE id = '7022b1d9-81c4-428f-be96-d38885bd2971' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '«Noes» serios 🛑', body_es = '¿Se aparta y dice «no» cuando alguien quiere besarle? Respeta los límites de su cuerpo y haz que los demás también los respeten. Así empieza la autoestima.', title_fr = 'Des « non » sérieux 🛑', body_fr = 'Il s''éloigne et dit non quand quelqu''un veut l''embrasser ? Respectez les limites de son corps et faites-les respecter aux autres. La confiance en soi commence là.', title_hi = 'पक्की ''नहीं'' 🛑', body_hi = 'कोई उसे चूमना चाहे तो दूर हटकर ''नहीं'' कहता है? उसके शरीर की सीमाओं का सम्मान कीजिए और दूसरों से भी करवाइए। आत्मविश्वास यहीं से शुरू होता है।', title_id = 'Tidak yang serius 🛑', body_id = 'Menjauh dan bilang tidak saat seseorang ingin menciumnya? Hormati batasan tubuhnya dan minta orang lain juga menghormatinya. Rasa percaya diri dimulai dari sini.', title_ja = '本気の「いや」🛑', body_ja = '誰かにキスされそうになると、離れて「いや」と言いますか？お子さんの体の境界線を尊重し、ほかの人にもそうしてもらいましょう。自己肯定感はここから始まります。', title_ko = '단호한 ''싫어'' 🛑', body_ko = '누가 뽀뽀하려 하면 피하며 싫다고 하나요? 아이의 몸의 경계를 존중하고 다른 사람들도 그렇게 하도록 해 주세요. 자존감은 여기서 시작돼요.', title_nl = 'Serieuze nee''s 🛑', body_nl = 'Trekt hij zich terug en zegt hij nee als iemand hem wil kussen? Respecteer zijn lichamelijke grenzen en zorg dat anderen dat ook doen. Hier begint zelfvertrouwen.', title_pl = 'Stanowcze „nie” 🛑', body_pl = 'Odsuwa się i mówi „nie”, gdy ktoś chce go pocałować? Szanuj jego granice cielesne i wymagaj tego od innych. Tu zaczyna się pewność siebie.', title_pt = '"Nãos" a sério 🛑', body_pt = 'Quando alguém o quer beijar, afasta-se e diz que não? Respeite os limites do corpo dele e peça aos outros que também os respeitem. É aqui que começa a autoconfiança.', title_sv = 'Bestämda ”nej” 🛑', body_sv = 'Drar sig barnet undan och säger nej när någon vill pussa hen? Respektera barnets kroppsliga gränser och se till att andra också gör det. Självkänslan börjar här.', title_vi = 'Những tiếng "Không" nghiêm túc 🛑', body_vi = 'Bé né tránh và nói không khi có người muốn hôn? Hãy tôn trọng ranh giới cơ thể của bé và yêu cầu người khác cũng tôn trọng. Sự tự tin bắt đầu từ đây.', title_zh = '认真的“不” 🛑', body_zh = '有人想亲宝宝时，宝宝会躲开说“不”？尊重宝宝的身体边界，也要求别人尊重。自信就是从这里开始的。' WHERE id = '927b3990-20b2-4f48-94c1-3ea0663bfcd4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Echa un vistazo al Blog 📱', body_es = '¿No sabes cómo afrontar las rabietas de los 2 años? Lee los artículos de psicología del Blog de la app Anacan. Entender qué pasa en su cerebro en plena crisis te lo pondrá más fácil.', title_fr = 'Jetez un œil aux blogs 📱', body_fr = 'Vous n''arrivez pas à gérer les crises des 2 ans ? Lisez les blogs de psychologie de l''appli Anacan. Comprendre ce qui se passe dans son cerveau pendant la crise vous facilitera la tâche.', title_hi = 'ब्लॉग देखिए 📱', body_hi = '2 साल के नखरों से निपट नहीं पा रहीं? Anacan ऐप में मनोविज्ञान वाले ब्लॉग पढ़िए। नखरे के उस पल में बच्चे के दिमाग में क्या चल रहा होता है, यह समझने से आपका काम आसान होगा।', title_id = 'Intip Blog 📱', body_id = 'Kewalahan menghadapi tantrum usia 2 tahun? Baca blog psikologi di aplikasi Anacan. Memahami apa yang terjadi di otak anak saat tantrum akan memudahkan Anda.', title_ja = 'ブログをのぞいてみよう 📱', body_ja = '2歳のかんしゃくに手を焼いていますか？Anacanアプリの心理学のブログを読んでみましょう。かんしゃくのときにお子さんの脳で何が起きているかがわかると、ずっと楽になります。', title_ko = '블로그를 둘러보세요 📱', body_ko = '두 돌 떼쓰기를 감당하기 어렵나요? Anacan 앱의 심리 블로그를 읽어 보세요. 떼쓰는 순간 아이의 뇌에서 무슨 일이 일어나는지 알면 훨씬 수월해져요.', title_nl = 'Neem een kijkje in Blogs 📱', body_nl = 'Kom je niet uit de driftbuien van een tweejarige? Lees de psychologische blogs in de Anacan-app. Begrijpen wat er in zijn hoofd gebeurt tijdens zo''n bui maakt het je makkelijker.', title_pl = 'Zajrzyj na Blog 📱', body_pl = 'Nie radzisz sobie z napadami złości dwulatka? Przeczytaj psychologiczne artykuły na Blogu w aplikacji Anacan. Zrozumienie, co dzieje się w mózgu dziecka w chwili kryzysu, ułatwi ci sprawę.', title_pt = 'Espreite os Blogues 📱', body_pt = 'Não consegue lidar com as birras dos 2 anos? Leia os artigos de psicologia dos Blogues da app Anacan. Perceber o que se passa no cérebro dele no momento da crise vai facilitar-lhe a tarefa.', title_sv = 'Titta i Bloggar 📱', body_sv = 'Klarar du inte av 2-årstrotsets utbrott? Läs de psykologiska bloggarna i Anacan-appen. Att förstå vad som händer i barnets hjärna under ett utbrott gör det lättare för dig.', title_vi = 'Xem blog nhé 📱', body_vi = 'Mẹ chưa xoay xở được với cơn ăn vạ tuổi lên 2? Hãy đọc các blog tâm lý trong ứng dụng Anacan. Hiểu điều gì xảy ra trong não bé lúc khủng hoảng sẽ giúp mẹ nhẹ nhàng hơn.', title_zh = '看看博客 📱', body_zh = '搞不定2岁的发脾气？读读Anacan应用里的心理学博客。了解崩溃时孩子大脑里发生了什么，会让你轻松很多。' WHERE id = 'f73f1d7d-92d7-412b-a0e4-c0f949786729' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Hora de Cuentos inteligentes 🪄', body_es = 'Esta noche crea en Cuentos inteligentes una aventura especial: la historia del conejo valiente que tenía miedo. Cura los miedos con cuentos.', title_fr = 'L''heure des Contes intelligents 🪄', body_fr = 'Ce soir, créez-lui une aventure spéciale dans les Contes intelligents : « L''histoire du lapin courageux qui n''avait peur de rien ». Soignez les peurs avec des contes.', title_hi = 'स्मार्ट कहानी का समय 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में उसके लिए एक खास रोमांच बनाइए: न डरने वाले बहादुर खरगोश की कहानी। डर का इलाज कहानियों से कीजिए।', title_id = 'Waktunya Dongeng Pintar 🪄', body_id = 'Malam ini, buat petualangan istimewa untuknya di Dongeng Pintar: Kisah kelinci pemberani yang tak kenal takut. Atasi rasa takut dengan dongeng.', title_ja = 'スマートおはなしの時間 🪄', body_ja = '今夜は「スマートおはなし」で、特別な冒険をつくりましょう：「こわいもの知らずの勇敢なうさぎのお話」。こわさをお話でいやしてあげましょう。', title_ko = '스마트 동화 시간 🪄', body_ko = '오늘 밤 스마트 동화에서 특별한 모험을 만들어 주세요: 무서움을 이겨 낸 용감한 토끼 이야기. 두려움은 동화로 달래 주세요.', title_nl = 'Tijd voor een slim sprookje 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een speciaal avontuur voor hem: het verhaal van het dappere konijntje dat bang was. Help angsten met sprookjes.', title_pl = 'Czas na Mądrą bajkę 🪄', body_pl = 'Stwórz dziś wieczorem w Mądrych bajkach wyjątkową przygodę: historię dzielnego zajączka, który się bał. Lecz lęki bajkami.', title_pt = 'Hora das Histórias Inteligentes 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma aventura especial: "A história do coelho corajoso que tinha medo". Trate os medos com histórias.', title_sv = 'Dags för en smart saga 🪄', body_sv = 'Skapa ett speciellt äventyr i Smarta sagor i kväll: berättelsen om den modiga kaninen som inte var rädd. Bota rädslor med sagor.', title_vi = 'Giờ Truyện cổ tích thông minh 🪄', body_vi = 'Tối nay hãy tạo cho bé một cuộc phiêu lưu đặc biệt trong Truyện cổ tích thông minh: "Câu chuyện về chú thỏ dũng cảm không biết sợ". Hãy chữa lành nỗi sợ bằng truyện cổ tích.', title_zh = '智能故事时间 🪄', body_zh = '今晚在智能故事里为宝宝创作一场特别的冒险：一只什么都不怕的勇敢小兔子的故事。用故事治愈恐惧吧。' WHERE id = '7281bfed-2cc1-421c-942f-77684085a8cf' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El caos de casa 🌪️', body_es = '¿La habitación que ordenas cada día vuelve a estar desordenada en 5 minutos? ¡Déjalo estar! Tu casa no es un museo, es un lugar lleno de vida. Céntrate en la alegría de tu peque, no en el desorden.', title_fr = 'Le chaos à la maison 🌪️', body_fr = 'La pièce que vous rangez chaque jour est de nouveau en désordre en 5 minutes ? Laissez tomber ! Une maison n''est pas un musée, c''est un lieu plein de vie. Concentrez-vous sur la joie de votre enfant, pas sur le désordre.', title_hi = 'घर में अफ़रा-तफ़री 🌪️', body_hi = 'रोज़ जो कमरा आप साफ़ करती हैं, वह 5 मिनट में फिर बिखर जाता है? जाने दीजिए! घर कोई म्यूज़ियम नहीं, ज़िंदगी से भरी जगह है। बिखराव पर नहीं, बच्चे की खुशी पर ध्यान दीजिए।', title_id = 'Kekacauan di rumah 🌪️', body_id = 'Kamar yang Anda bereskan setiap hari berantakan lagi dalam 5 menit? Biarkan saja! Rumah bukan museum, melainkan tempat yang penuh kehidupan. Fokuslah pada kebahagiaan anak Anda, bukan pada kekacauannya.', title_ja = '家の中のカオス 🌪️', body_ja = '毎日掃除する部屋が、5分でまた散らかりますか？気にしないで！家は博物館ではなく、命がいきいきと息づく場所です。散らかりではなく、お子さんの喜びに目を向けましょう。', title_ko = '집 안의 혼돈 🌪️', body_ko = '매일 치우는 방이 5분 만에 다시 어질러지나요? 그냥 두세요! 집은 박물관이 아니라 삶이 살아 숨 쉬는 곳이에요. 어질러진 것보다 아이의 기쁨에 집중하세요.', title_nl = 'Chaos in huis 🌪️', body_nl = 'Is de kamer die je elke dag opruimt binnen 5 minuten weer een rommel? Laat maar! Een huis is geen museum, maar een plek vol leven. Focus niet op de rommel, maar op de vreugde van je kind.', title_pl = 'Chaos w domu 🌪️', body_pl = 'Pokój, który codziennie sprzątasz, po 5 minutach znów jest w nieładzie? Odpuść! Dom to nie muzeum, tylko miejsce tętniące życiem. Skup się nie na bałaganie, ale na radości dziecka.', title_pt = 'O caos da casa 🌪️', body_pt = 'O quarto que arruma todos os dias volta a ficar desarrumado em 5 minutos? Deixe estar! A casa não é um museu, é um lugar cheio de vida. Concentre-se na alegria do seu filho, não na desarrumação.', title_sv = 'Kaos hemma 🌪️', body_sv = 'Blir rummet du städar varje dag stökigt igen på 5 minuter? Strunta i det! Ett hem är inget museum, utan en plats full av liv. Fokusera på barnets glädje, inte på röran.', title_vi = 'Hỗn loạn trong nhà 🌪️', body_vi = 'Căn phòng ngày nào mẹ cũng dọn lại bừa bộn sau 5 phút? Kệ đi! Nhà không phải viện bảo tàng mà là nơi tràn đầy sức sống. Hãy tập trung vào niềm vui của bé thay vì sự bừa bộn.', title_zh = '家里的混乱 🌪️', body_zh = '每天打扫的房间5分钟又乱了？算了吧！家不是博物馆，而是充满生活气息的地方。别盯着乱，专注于孩子的快乐吧。' WHERE id = 'e96ff0af-1a62-4cbe-8543-0ed5c9498c20' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Despiertan los miedos 👻', body_es = '¿Ahora le da miedo la ruidosa aspiradora, que antes no le asustaba, y se esconde detrás de ti? A medida que se desarrolla la imaginación aparecen miedos sin motivo. Acaríciale y dale seguridad.', title_fr = 'Le réveil des peurs 👻', body_fr = 'Il a maintenant peur de l''aspirateur bruyant qui ne l''effrayait pas avant et se cache derrière vous ? Avec l''imagination qui se développe, des peurs injustifiées apparaissent. Caressez-le et rassurez-le.', title_hi = 'डर जाग रहे हैं 👻', body_hi = 'जिस शोर करने वाले वैक्यूम क्लीनर से पहले कभी नहीं डरा, अब उससे डरकर आपके पीछे छिप जाता है? कल्पना बढ़ने के साथ बेवजह के डर पैदा होते हैं। उसे सहलाइए और भरोसा दीजिए।', title_id = 'Rasa takut mulai muncul 👻', body_id = 'Sekarang takut pada penyedot debu yang dulu sama sekali tidak ia takuti dan bersembunyi di belakang Anda? Seiring berkembangnya imajinasi, muncul rasa takut yang tak beralasan. Belai ia dan beri rasa aman.', title_ja = 'こわさのめざめ 👻', body_ja = '前はまったく平気だった、うるさい掃除機をこわがって、あなたの後ろに隠れますか？想像力が育つにつれて、理由のないこわさが生まれます。なでて、安心させてあげましょう。', title_ko = '두려움이 깨어나요 👻', body_ko = '전에는 전혀 무서워하지 않던 시끄러운 청소기를 이제 무서워하며 엄마 뒤에 숨나요? 상상력이 자라면서 이유 없는 두려움도 생겨요. 쓰다듬어 주며 안심시켜 주세요.', title_nl = 'Angsten worden wakker 👻', body_nl = 'Is hij nu bang voor de lawaaierige stofzuiger, terwijl hij dat eerst nooit was, en verstopt hij zich achter je? Naarmate zijn fantasie groeit, ontstaan onterechte angsten. Aai hem en geef hem vertrouwen.', title_pl = 'Przebudzenie lęków 👻', body_pl = 'Teraz boi się głośnego odkurzacza, którego wcześniej w ogóle się nie bał, i chowa się za tobą? Wraz z rozwojem wyobraźni pojawiają się nieuzasadnione lęki. Pogłaszcz go i daj mu poczucie bezpieczeństwa.', title_pt = 'Os medos despertam 👻', body_pt = 'Agora tem medo do aspirador barulhento, de que antes não tinha, e esconde-se atrás de si? À medida que a imaginação se desenvolve, surgem medos sem razão. Faça-lhe uma festinha e dê-lhe segurança.', title_sv = 'Rädslorna vaknar 👻', body_sv = 'Är barnet nu rädd för den bullriga dammsugaren som det aldrig var rädd för tidigare och gömmer sig bakom dig? När fantasin utvecklas uppstår obefogade rädslor. Smek barnet och ge trygghet.', title_vi = 'Nỗi sợ thức giấc 👻', body_vi = 'Trước đây không sợ, giờ bé lại sợ máy hút bụi ồn ào và nấp sau lưng mẹ? Khi trí tưởng tượng phát triển, những nỗi sợ vô cớ sẽ xuất hiện. Hãy vuốt ve và trấn an bé.', title_zh = '恐惧觉醒 👻', body_zh = '以前一点都不怕的吵闹吸尘器，现在却怕得躲到你身后？随着想象力发展，会出现一些莫名的恐惧。摸摸宝宝，给宝宝安全感。' WHERE id = 'fa5b66d9-39b4-43f8-b655-5b6b176b299f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Ojos con sueño 🥱', body_es = 'Aunque tiene sueño, no quiere irse a la cama de ninguna manera. Esta noche cambia un poco la rutina. En lugar de leer un libro, túmbate con él en la cama y recuérdale las cosas bonitas de hoy.', title_fr = 'Le sommeil dans les yeux 🥱', body_fr = 'Il a sommeil mais refuse catégoriquement d''aller au lit. Ce soir, changez un peu le rituel. Au lieu de lire un livre, allongez-vous près de lui et rappelez-lui les beaux moments de la journée.', title_hi = 'आँखों में नींद 🥱', body_hi = 'नींद आ रही है, फिर भी बिस्तर पर बिल्कुल नहीं जाना चाहता। आज शाम का रूटीन थोड़ा अलग कीजिए। किताब पढ़ने के बजाय बिस्तर पर लेटकर उसे आज की अच्छी बातें याद दिलाइए।', title_id = 'Mata yang mengantuk 🥱', body_id = 'Meski mengantuk, ia sama sekali tidak mau ke tempat tidur. Buat rutinitas malam ini sedikit berbeda. Bukannya membaca buku, berbaringlah bersamanya dan ingatkan kejadian indah hari ini.', title_ja = '目に眠気 🥱', body_ja = '眠いのに、どうしてもベッドに行きたがらない。今夜はいつもの習慣を少し変えてみましょう。絵本の代わりに、ベッドに横になって今日あったすてきなことを思い出させてあげて。', title_ko = '졸린 눈 🥱', body_ko = '졸린데도 절대 잠자리에 가지 않으려 해요. 오늘 저녁은 일과를 조금 바꿔 보세요. 책 대신 침대에 함께 누워 오늘 있었던 좋은 일들을 이야기해 주세요.', title_nl = 'Slaap in de oogjes 🥱', body_nl = 'Hij heeft slaap, maar wil echt niet naar bed. Maak het ritueel vanavond eens anders. Lees geen boek, maar ga naast hem liggen en vertel hem over de mooie dingen van vandaag.', title_pl = 'Senne oczka 🥱', body_pl = 'Choć chce mu się spać, za nic nie chce iść do łóżka. Zmień dziś trochę wieczorny rytuał. Zamiast czytać książkę, połóż się obok i przypomnij mu dzisiejsze piękne chwile.', title_pt = 'Sono nos olhos 🥱', body_pt = 'Tem sono, mas não quer mesmo nada ir para a cama. Esta noite, mude um pouco a rotina. Em vez de ler um livro, deite-se com ele na cama e recorde-lhe as coisas bonitas de hoje.', title_sv = 'Sömn i ögonen 🥱', body_sv = 'Barnet är sömnigt men vill absolut inte gå och lägga sig. Gör kvällsrutinen lite annorlunda i kväll. I stället för att läsa, ligg i sängen och påminn barnet om dagens fina händelser.', title_vi = 'Mắt díp lại rồi 🥱', body_vi = 'Dù buồn ngủ, bé vẫn nhất quyết không lên giường. Tối nay hãy thay đổi nếp sinh hoạt một chút. Thay vì đọc sách, hãy nằm trên giường và nhắc lại cho bé những điều tốt đẹp hôm nay.', title_zh = '眼里的睡意 🥱', body_zh = '明明困了，却死活不肯上床。今晚把流程换个花样吧。不读书了，躺在床上和宝宝一起回想今天发生的美好事情。' WHERE id = '7b50e55a-c023-4d17-aacb-ffa1852fdee2' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Explosión de energía ⛅', body_es = '¿En casa se sube por las paredes? Necesita gastar energía. Entra en Tiempo y ropa, vístele bien y llévale al parque para que corra hasta cansarse.', title_fr = 'Explosion d''énergie ⛅', body_fr = 'Il grimpe aux murs à la maison ? Il doit absolument se dépenser. Ouvrez Météo et tenue, habillez-le comme il faut et emmenez-le au parc courir jusqu''à ce qu''il soit fatigué.', title_hi = 'ऊर्जा का धमाका ⛅', body_hi = 'बच्चा घर में दीवारों पर चढ़ रहा है? उसकी ऊर्जा निकालना ज़रूरी है। मौसम और कपड़े खोलिए, सही कपड़े पहनाइए और पार्क ले जाकर उसे थकने तक दौड़ने दीजिए।', title_id = 'Ledakan energi ⛅', body_id = 'Si kecil memanjat dinding di rumah? Energinya harus tersalurkan. Buka Cuaca dan Pakaian, pakaikan baju yang tepat, lalu ajak ia ke taman dan biarkan berlari sampai lelah.', title_ja = 'エネルギーが爆発 ⛅', body_ja = '家の中で壁によじ登っていますか？エネルギーの発散が欠かせません。「天気と服装」を開いてぴったりの服を着せ、公園へ連れ出して、疲れるまで走らせてあげましょう。', title_ko = '에너지 폭발 ⛅', body_ko = '아이가 집에서 벽을 타고 오르나요? 에너지를 꼭 발산해야 해요. 날씨와 옷차림 도구를 열어 알맞게 입히고 공원에 데려가 지칠 때까지 뛰게 해 주세요.', title_nl = 'Energie-explosie ⛅', body_nl = 'Klimt hij thuis tegen de muren op? Hij moet zijn energie kwijt. Open Weer en kleding, kleed hem goed aan, ga naar het park en laat hem rennen tot hij moe is.', title_pl = 'Wybuch energii ⛅', body_pl = 'Maluch w domu wspina się po ścianach? Musi rozładować energię. Sprawdź Pogodę i ubiór, ubierz go odpowiednio i idźcie do parku, niech biega, aż się zmęczy.', title_pt = 'Explosão de energia ⛅', body_pt = 'Em casa trepa pelas paredes? Gastar energia é indispensável. Abra o Tempo e Roupa, vista-o como deve ser, leve-o ao parque e deixe-o correr até se cansar.', title_sv = 'Energiexplosion ⛅', body_sv = 'Klättrar barnet på väggarna hemma? Energin måste ut. Gå in i Väder och kläder, klä barnet rätt, gå till parken och låt barnet springa tills hen blir trött.', title_vi = 'Bùng nổ năng lượng ⛅', body_vi = 'Bé leo cả lên tường trong nhà? Bé rất cần được xả năng lượng. Hãy vào Thời tiết và trang phục, mặc đồ phù hợp cho bé và ra công viên để bé chạy đến khi mệt.', title_zh = '能量大爆发 ⛅', body_zh = '孩子在家里爬墙？一定要释放精力。打开天气与穿衣，给宝宝穿对衣服，带去公园让宝宝跑到累为止。' WHERE id = 'a4e24e0d-5f22-40d2-b64c-109e7cec356e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Copia tu voz 🗣️', body_es = '¿Les da consejos a sus juguetes con tu mismo tono de voz y tus mismas frases? Es tu mejor espejo. Verte desde fuera te resultará muy gracioso.', title_fr = 'Il copie votre voix 🗣️', body_fr = 'Il fait la leçon à ses jouets avec exactement votre ton et vos phrases ? C''est votre meilleur miroir. Vous observer de l''extérieur sera bien drôle.', title_hi = 'आपकी आवाज़ की नकल करता है 🗣️', body_hi = 'अपने खिलौनों को बिल्कुल आपके लहजे और आपके ही वाक्यों में समझाता है? वह आपका सबसे अच्छा आईना है। बाहर से खुद को देखना मज़ेदार होगा।', title_id = 'Meniru suara Anda 🗣️', body_id = 'Menasihati mainannya persis dengan nada suara dan kalimat Anda? Ia adalah cermin terbaik Anda. Melihat diri Anda dari luar pasti lucu.', title_ja = 'あなたの声をまねっこ 🗣️', body_ja = 'あなたとそっくりの声のトーンと言い回しで、おもちゃにお説教していますか？お子さんはあなたのいちばんの鏡です。外から自分を見ているようで、おもしろいですね。', title_ko = '엄마 목소리를 따라 해요 🗣️', body_ko = '장난감에게 엄마와 똑같은 말투, 똑같은 문장으로 잔소리하나요? 아이는 엄마의 가장 좋은 거울이에요. 밖에서 나를 보는 것 같아 웃음이 날 거예요.', title_nl = 'Hij doet je stem na 🗣️', body_nl = 'Geeft hij zijn knuffels advies met precies jouw toon en jouw zinnen? Hij is je beste spiegel. Jezelf zo van een afstand bekijken is best grappig.', title_pl = 'Kopiuje twój głos 🗣️', body_pl = 'Udziela rad zabawkom dokładnie twoim tonem i twoimi zdaniami? To twoje najlepsze lustro. Obserwowanie siebie z boku będzie zabawne.', title_pt = 'Copia a sua voz 🗣️', body_pt = 'Dá conselhos aos brinquedos com o seu tom de voz e as suas frases? É o seu melhor espelho. Ver-se a si própria de fora vai ser divertido.', title_sv = 'Härmar din röst 🗣️', body_sv = 'Ger barnet leksakerna råd med exakt din röst och dina meningar? Barnet är din bästa spegel. Det blir roligt att se dig själv utifrån.', title_vi = 'Bé bắt chước giọng mẹ 🗣️', body_vi = 'Bé dạy dỗ đồ chơi bằng đúng giọng điệu và câu nói của mẹ? Bé là tấm gương tốt nhất của mẹ. Nhìn thấy chính mình từ bên ngoài sẽ rất buồn cười đấy.', title_zh = '模仿你的声音 🗣️', body_zh = '用和你一模一样的语气、你的句子教训玩具？宝宝就是你最好的镜子。从旁边看看自己，一定很好笑。' WHERE id = 'a628c2a6-552d-4e1a-a37b-9ed947ed297d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón de talla y peso! 📏', body_es = '¿Al vestirle has notado que las camisetas le quedan estrechas o le aprietan los zapatos? Introduce su talla y medidas actuales en el Seguimiento del desarrollo y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Pic de taille et de poids ! 📏', body_fr = 'En l''habillant, vous avez remarqué que les t-shirts serraient ou que les chaussures étaient étroites ? Entrez sa taille et ses mesures actuelles dans le Suivi de croissance et regardez fièrement sa courbe grimper.', title_hi = 'लंबाई और वज़न में उछाल! 📏', body_hi = 'कपड़े पहनाते समय लगा कि कमीज़ें तंग हो गईं या जूते काट रहे हैं? ग्रोथ ट्रैकर में मौजूदा लंबाई और माप दर्ज कीजिए और गर्व से देखिए कि ग्रोथ कर्व कैसे ऊपर जा रहा है।', title_id = 'Lonjakan tinggi dan berat badan! 📏', body_id = 'Saat memakaikan baju, Anda melihat kausnya mulai sempit atau sepatunya sesak? Masukkan tinggi dan ukuran terbarunya ke Pelacak Perkembangan dan lihat dengan bangga kurva pertumbuhannya naik.', title_ja = '身長と体重がぐんと伸びた！📏', body_ja = '着替えのときに、シャツがきつくなったり、靴が小さくなったりしたことに気づきましたか？「発達トラッカー」に今の身長とサイズを入力して、成長曲線が伸びていく様子を誇らしく眺めましょう。', title_ko = '키와 몸무게가 쑥! 📏', body_ko = '옷을 입힐 때 셔츠가 끼거나 신발이 작아진 걸 느꼈나요? 성장 기록에 현재 키와 치수를 입력하고 성장 곡선이 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Groeispurt in lengte en gewicht! 📏', body_nl = 'Merk je bij het aankleden dat shirtjes krap zitten of schoenen knellen? Voer zijn huidige lengte en maten in de Groeitracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Skok wzrostu i wagi! 📏', body_pl = 'Przy ubieraniu zauważyłaś, że koszulki są ciasne, a buty uciskają? Wpisz aktualny wzrost i wymiary w Śledzeniu rozwoju i z dumą patrz, jak pnie się krzywa rozwoju.', title_pt = 'Salto na altura e no peso! 📏', body_pt = 'Ao vesti-lo, reparou que as camisolas estão apertadas ou que os sapatos apertam? Introduza a altura e as medidas atuais no Registo de Desenvolvimento e veja com orgulho a curva de crescimento a subir.', title_sv = 'Längd- och viktspurt! 📏', body_sv = 'Märkte du att tröjorna blivit trånga eller att skorna klämmer när du klädde på barnet? Ange aktuell längd och mått i Utvecklingsspåraren och titta stolt på hur tillväxtkurvan stiger.', title_vi = 'Tăng vọt chiều cao và cân nặng! 📏', body_vi = 'Khi mặc đồ cho bé, mẹ thấy áo chật hơn hay giày bị bó? Hãy nhập chiều cao và số đo hiện tại vào Theo dõi phát triển và tự hào ngắm đường cong phát triển đi lên.', title_zh = '身高体重猛长！📏', body_zh = '穿衣服时发现上衣变紧，或者鞋子挤脚？在发育追踪里输入当前的身高和尺寸，骄傲地看看成长曲线是怎么往上走的。' WHERE id = 'a5f509e7-b242-4ca9-b7c5-aa083ba7699a' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando mamá está cansada 🛑', body_es = 'No eres un robot. Si hoy no tienes fuerzas para cocinar, pide comida a domicilio. Ser una madre perfecta no significa hacerlo todo sola.', title_fr = 'Quand maman est fatiguée 🛑', body_fr = 'Vous n''êtes pas un robot. Si vous n''avez pas la force de cuisiner aujourd''hui, commandez à manger. Être une maman parfaite ne veut pas dire tout faire seule.', title_hi = 'जब माँ थक जाए 🛑', body_hi = 'आप रोबोट नहीं हैं। अगर आज खाना बनाने की ताकत नहीं है, तो बाहर से मँगवा लीजिए। परफ़ेक्ट माँ होने का मतलब सब कुछ अकेले करना नहीं है।', title_id = 'Saat ibu lelah 🛑', body_id = 'Anda bukan robot. Jika hari ini tidak punya tenaga untuk memasak, pesan saja dari luar. Menjadi ibu yang sempurna bukan berarti melakukan semuanya sendirian.', title_ja = 'ママが疲れたとき 🛑', body_ja = 'あなたはロボットではありません。今日料理をする元気がないなら、出前をとりましょう。完璧なママとは、すべてをひとりでこなすことではありません。', title_ko = '엄마가 지칠 때 🛑', body_ko = '엄마는 로봇이 아니에요. 오늘 요리할 힘이 없다면 배달을 시키세요. 완벽한 엄마라고 모든 걸 혼자 해야 하는 건 아니에요.', title_nl = 'Als mama moe is 🛑', body_nl = 'Je bent geen robot. Heb je vandaag geen energie om te koken, bestel dan eten. Een perfecte moeder zijn betekent niet alles alleen doen.', title_pl = 'Gdy mama jest zmęczona 🛑', body_pl = 'Nie jesteś robotem. Jeśli dziś nie masz siły gotować, zamów jedzenie. Bycie idealną mamą nie oznacza robienia wszystkiego samej.', title_pt = 'Quando a mãe se cansa 🛑', body_pt = 'Não é um robô. Se hoje não tem forças para cozinhar, encomende comida. Ser uma mãe perfeita não significa fazer tudo sozinha.', title_sv = 'När mamma är trött 🛑', body_sv = 'Du är ingen robot. Om du inte orkar laga mat i dag, beställ hem. Att vara en perfekt mamma betyder inte att göra allt på egen hand.', title_vi = 'Khi mẹ mệt mỏi 🛑', body_vi = 'Mẹ không phải là robot. Nếu hôm nay không còn sức nấu ăn, hãy gọi đồ ăn bên ngoài. Làm mẹ hoàn hảo không có nghĩa là tự mình làm tất cả.', title_zh = '当妈妈累了 🛑', body_zh = '你不是机器人。如果今天没力气做饭，就点外卖吧。做完美妈妈，不等于什么都要自己做。' WHERE id = 'a9ef3c95-4b55-4dd2-abe5-e4a54e6509df' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Brindis por la victoria 🥂', body_es = 'Habéis terminado sanos y salvos un día difícil y lleno de tozudez. Sentaos frente a frente con tu pareja y brindad con vuestras tazas de té. Estáis a la altura de esta gran responsabilidad.', title_fr = 'Un toast à la victoire 🥂', body_fr = 'Vous avez traversé saine et sauve une journée difficile, pleine d''entêtement. Asseyez-vous face à votre conjoint et trinquez avec vos tasses de thé. Vous êtes à la hauteur de cette grande responsabilité.', title_hi = 'जीत का जश्न 🥂', body_hi = 'ज़िदों से भरा एक मुश्किल दिन आपने सही-सलामत पूरा कर लिया। अपने जीवनसाथी के साथ आमने-सामने बैठिए और चाय के कप टकराइए। आप इस बड़ी ज़िम्मेदारी को बखूबी निभा रहे हैं।', title_id = 'Bersulang untuk kemenangan 🥂', body_id = 'Anda berhasil melewati hari yang berat dan penuh sikap keras kepala. Duduklah berhadapan dengan pasangan dan dentingkan cangkir teh Anda. Anda berdua mampu memikul tanggung jawab besar ini.', title_ja = '勝利の乾杯 🥂', body_ja = 'こだわりいっぱいの大変な一日を、無事に乗りこえましたね。パートナーと向かい合って座り、お茶のカップで乾杯しましょう。おふたりはこの大きな責任をしっかり果たしています。', title_ko = '승리의 건배 🥂', body_ko = '고집으로 가득했던 힘든 하루를 무사히 마쳤어요. 배우자와 마주 앉아 찻잔을 부딪쳐 보세요. 두 사람은 이 큰 책임을 멋지게 해내고 있어요.', title_nl = 'Een toost op je overwinning 🥂', body_nl = 'Je bent heelhuids door een zware dag vol koppigheid gekomen. Ga tegenover je partner zitten en klink met je thee. Jullie kunnen deze grote verantwoordelijkheid aan.', title_pl = 'Toast za zwycięstwo 🥂', body_pl = 'Szczęśliwie zakończyłaś trudny dzień pełen uporu. Usiądźcie z partnerem naprzeciw siebie i stuknijcie się herbatą. Dajecie radę z tą wielką odpowiedzialnością.', title_pt = 'Um brinde à vitória 🥂', body_pt = 'Chegaram ao fim de um dia difícil e cheio de teimosias. Sentem-se frente a frente com o seu companheiro e brindem com as chávenas de chá. Estão a dar conta desta grande responsabilidade.', title_sv = 'Segerskål 🥂', body_sv = 'Ni har tagit er helskinnade igenom en tuff dag full av envishet. Sätt dig mittemot din partner och skåla med teet. Ni klarar detta stora ansvar.', title_vi = 'Nâng ly chiến thắng 🥂', body_vi = 'Mẹ đã vượt qua một ngày khó khăn đầy bướng bỉnh. Hãy ngồi đối diện với bạn đời và cụng tách trà. Hai người đang làm tốt trách nhiệm lớn lao này.', title_zh = '胜利干杯 🥂', body_zh = '你们平安熬过了充满倔强的艰难一天。和另一半面对面坐下，碰一碰茶杯吧。你们正在扛起这份巨大的责任。' WHERE id = 'ce9a0c9c-c1ca-4fbc-ad47-53a33a6c199f' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Pequeño ayudante 🧹', body_es = '¿Cuando doblas la ropa o friegas el suelo, intenta quitártelo de las manos? Se siente mayor. Dale un trapo pequeño y deja que te ayude.', title_fr = 'Petit assistant 🧹', body_fr = 'Il essaie de vous prendre le linge ou la serpillière des mains ? Il se sent grand. Donnez-lui un petit chiffon et laissez-le vous aider.', title_hi = 'नन्हा मददगार 🧹', body_hi = 'आप कपड़े तह करती हैं या फ़र्श पोंछती हैं तो वह आपके हाथ से लेने की कोशिश करता है? वह खुद को बड़ा महसूस करता है। उसे एक छोटा कपड़ा दीजिए और मदद करने दीजिए।', title_id = 'Asisten cilik 🧹', body_id = 'Mencoba merebut dari tangan Anda saat Anda melipat baju atau mengepel lantai? Ia merasa sudah besar. Beri ia kain kecil dan biarkan ia membantu.', title_ja = '小さなお手伝いさん 🧹', body_ja = 'あなたが洗濯物をたたんだり、床を拭いたりしていると、手から取ろうとしますか？自分が大きくなった気分なんです。小さな布を渡して、お手伝いさせてあげましょう。', title_ko = '꼬마 도우미 🧹', body_ko = '엄마가 빨래를 개거나 바닥을 닦을 때 손에서 가져가려 하나요? 자기가 다 컸다고 느끼는 거예요. 작은 걸레를 주고 돕게 해 주세요.', title_nl = 'Kleine hulp 🧹', body_nl = 'Probeert hij het van je over te nemen als je de was vouwt of de vloer dweilt? Hij voelt zich groot. Geef hem een klein doekje en laat hem helpen.', title_pl = 'Mały pomocnik 🧹', body_pl = 'Gdy składasz pranie albo myjesz podłogę, próbuje ci to zabrać? Czuje się duży. Daj mu małą ściereczkę i pozwól pomagać.', title_pt = 'Pequeno ajudante 🧹', body_pt = 'Quando dobra a roupa ou limpa o chão, tenta tirar-lhe as coisas da mão? Sente-se crescido. Dê-lhe um paninho e deixe-o ajudar.', title_sv = 'Liten hjälpreda 🧹', body_sv = 'Försöker barnet ta över när du viker tvätt eller torkar golvet? Barnet känner sig stort. Ge barnet en liten trasa och låt hen hjälpa till.', title_vi = 'Người giúp việc nhỏ 🧹', body_vi = 'Mẹ gấp quần áo hay lau nhà thì bé cố giành lấy? Bé cảm thấy mình đã lớn. Hãy đưa bé một chiếc khăn nhỏ và để bé phụ giúp.', title_zh = '小帮手 🧹', body_zh = '你叠衣服或拖地时，宝宝想从你手里抢过去？宝宝觉得自己长大了。给宝宝一块小抹布，让宝宝来帮忙吧。' WHERE id = '25092d10-5861-4eec-8fa9-86857d835418' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El castillo de cojines 🏰', body_es = 'Esta noche convierte la habitación en un parque de juegos. Construid un pequeño castillo con los cojines del sofá y meteos dentro. Habrá algo de desorden, pero las risas lo valen.', title_fr = 'Château de coussins 🏰', body_fr = 'Ce soir, transformez la chambre en aire de jeux. Construisez un petit château avec les coussins du canapé et glissez-vous dedans. Il y aura un peu de désordre, mais ces fous rires en valent vraiment la peine.', title_hi = 'तकियों का किला 🏰', body_hi = 'आज शाम कमरे को खेल का मैदान बना दीजिए। सोफ़े के तकियों से एक छोटा किला बनाइए और अंदर घुस जाइए। थोड़ा बिखराव होगा, पर ये हँसी उसके लायक है।', title_id = 'Benteng bantal 🏰', body_id = 'Malam ini, ubah kamar menjadi taman bermain. Buat benteng kecil dari bantal sofa dan masuklah ke dalamnya. Pasti sedikit berantakan, tapi tawa itu sangat sepadan.', title_ja = 'クッションのお城 🏰', body_ja = '今夜は部屋を遊び場に変えましょう。ソファのクッションで小さなお城をつくって、中に入りましょう。少し散らかりますが、この笑い声にはそれだけの価値があります。', title_ko = '베개 성 🏰', body_ko = '오늘 저녁 방을 놀이터로 바꿔 보세요. 소파 쿠션으로 작은 성을 쌓고 그 안에 들어가 보세요. 조금 어질러지겠지만 그 웃음은 충분히 그만한 가치가 있어요.', title_nl = 'Kussenkasteel 🏰', body_nl = 'Maak vanavond van de kamer een speelplaats. Bouw een klein kasteel van bankkussens en kruip erin. Het wordt een beetje een rommel, maar het gelach is het zeker waard.', title_pl = 'Zamek z poduszek 🏰', body_pl = 'Zamień dziś wieczorem pokój w plac zabaw. Zbudujcie z poduszek z kanapy mały zamek i wejdźcie do środka. Będzie trochę bałaganu, ale ten śmiech jest tego wart.', title_pt = 'O castelo de almofadas 🏰', body_pt = 'Esta noite, transforme o quarto num parque de diversões. Construam um pequeno castelo com as almofadas do sofá e entrem lá para dentro. Vai haver alguma desarrumação, mas as gargalhadas valem a pena.', title_sv = 'Kuddslott 🏰', body_sv = 'Gör rummet till en lekplats i kväll. Bygg ett litet slott av soffkuddarna och kryp in. Det blir lite stökigt, men skratten är det absolut värda.', title_vi = 'Lâu đài gối 🏰', body_vi = 'Tối nay hãy biến căn phòng thành sân chơi. Dùng gối sofa xây một lâu đài nhỏ rồi chui vào trong. Sẽ hơi bừa một chút, nhưng những tiếng cười ấy hoàn toàn xứng đáng.', title_zh = '枕头城堡 🏰', body_zh = '今晚把房间变成游乐场吧。用沙发靠垫搭一座小城堡，一起钻进去。会弄乱一点，但这些笑声绝对值得。' WHERE id = '739e50cd-5199-4e7e-9448-99a52d59a069' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Prueba de atención 🧩', body_es = '¿Ya juega 10-15 minutos con un mismo juguete? Su capacidad de atención está creciendo.', title_fr = 'Test d''attention 🧩', body_fr = 'Il joue maintenant 10 à 15 minutes avec le même jouet ? Sa capacité de concentration s''allonge.', title_hi = 'ध्यान का टेस्ट 🧩', body_hi = 'एक खिलौने से खेलने का समय अब 10-15 मिनट तक पहुँच गया है? उसका ध्यान देर तक टिकने लगा है।', title_id = 'Tes fokus 🧩', body_id = 'Waktunya bermain dengan satu mainan sudah mencapai 10-15 menit? Rentang perhatiannya makin panjang.', title_ja = '集中力テスト 🧩', body_ja = 'ひとつのおもちゃで遊ぶ時間が、もう10-15分になりましたか？集中できる時間が長くなっています。', title_ko = '집중력 테스트 🧩', body_ko = '장난감 하나로 노는 시간이 벌써 10~15분이 되었나요? 집중하는 시간이 길어지고 있어요.', title_nl = 'Concentratietest 🧩', body_nl = 'Speelt hij al 10-15 minuten met één speeltje? Zijn concentratie wordt langer.', title_pl = 'Test uwagi 🧩', body_pl = 'Bawi się jedną zabawką już 10-15 minut? Jego uwaga staje się coraz dłuższa.', title_pt = 'Teste de atenção 🧩', body_pt = 'Já consegue brincar com o mesmo brinquedo 10-15 minutos? A capacidade de atenção está a aumentar.', title_sv = 'Koncentrationstest 🧩', body_sv = 'Leker barnet redan 10-15 minuter med samma leksak? Koncentrationsförmågan blir längre.', title_vi = 'Bài kiểm tra tập trung 🧩', body_vi = 'Thời gian bé chơi với một món đồ chơi đã lên đến 10-15 phút? Khả năng tập trung của bé đang dài hơn.', title_zh = '专注力测试 🧩', body_zh = '玩一个玩具的时间已经能达到10-15分钟了？注意力的持续时间在变长。' WHERE id = 'a9e6d37d-aa66-4119-abcb-6619dfc78256' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rutina de sueño con papá 👨‍🍼', body_es = 'Esta noche encarga a papá preparar a tu peque para dormir, lavarle los dientes y ponerle el pijama, y tómate el té en silencio.', title_fr = 'Le rituel du coucher avec papa 👨‍🍼', body_fr = 'Ce soir, confiez à papa la préparation au coucher, le brossage des dents et le pyjama, et buvez votre thé au calme.', title_hi = 'पापा के साथ सोने का रूटीन 👨‍🍼', body_hi = 'आज रात बच्चे को सुलाने की तैयारी, दाँत ब्रश करवाना और पायजामा पहनाना पापा को सौंपिए और आप शांति से अपनी चाय पीजिए।', title_id = 'Rutinitas tidur bersama Ayah 👨‍🍼', body_id = 'Malam ini, serahkan rutinitas menyiapkan si kecil tidur, menyikat gigi dan memakaikan piyama, kepada Ayah, lalu nikmati teh Anda dalam keheningan.', title_ja = 'パパと寝る前の習慣 👨‍🍼', body_ja = '夕方の寝る準備、歯みがき、パジャマへの着替えを今夜はパパにお任せして、静かにお茶を飲みましょう。', title_ko = '아빠와 함께하는 잠자리 일과 👨‍🍼', body_ko = '오늘 밤에는 아이 재울 준비, 양치, 잠옷 입히기를 아빠에게 맡기고 조용히 차를 즐기세요.', title_nl = 'Slaapritueel met papa 👨‍🍼', body_nl = 'Laat vanavond het klaarmaken voor bed, tandenpoetsen en pyjama aantrekken over aan papa, en drink in alle rust je thee.', title_pl = 'Wieczorny rytuał z tatą 👨‍🍼', body_pl = 'Powierz dziś tacie przygotowanie malucha do snu: mycie ząbków i zakładanie piżamy, a sama w ciszy wypij herbatę.', title_pt = 'A rotina de sono com o pai 👨‍🍼', body_pt = 'Esta noite, deixe ao pai a preparação para dormir, lavar os dentes e vestir o pijama, e beba o seu chá em silêncio.', title_sv = 'Läggrutin med pappa 👨‍🍼', body_sv = 'Låt pappa ta hand om kvällens förberedelser i kväll: tandborstning och pyjamas, medan du dricker ditt te i lugn och ro.', title_vi = 'Nếp ngủ cùng bố 👨‍🍼', body_vi = 'Tối nay hãy giao cho bố việc chuẩn bị cho bé đi ngủ, đánh răng và mặc pyjama, còn mẹ thì yên tĩnh thưởng thức tách trà.', title_zh = '和爸爸的睡前流程 👨‍🍼', body_zh = '今晚把傍晚哄孩子准备睡觉、刷牙、换睡衣的流程交给爸爸，你安安静静地喝杯茶吧。' WHERE id = '1a9b02d2-5d73-4e72-a7df-f4672edf0835' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Líquidos y estreñimiento 💩', title_fr = 'Hydratation et constipation 💩', title_hi = 'तरल और कब्ज़ 💩', title_id = 'Asupan cairan dan sembelit 💩', title_ja = '水分補給と便秘 💩', title_ko = '수분 섭취와 변비 💩', title_nl = 'Drinken en verstopping 💩', title_pl = 'Picie a zaparcia 💩', title_pt = 'Líquidos e prisão de ventre 💩', title_sv = 'Vätskeintag och förstoppning 💩', title_vi = 'Uống nước và táo bón 💩', title_zh = '饮水与便秘 💩' WHERE id = '99409d74-b463-47c8-b5a8-30d9e195253d' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El dilema del menú 🍲', body_es = '¿No tienes ni idea de qué cocinar hoy? No te pierdas en internet: encuentra recetas nuevas y fáciles en los artículos sobre alimentación infantil del Blog de la app.', title_fr = 'Casse-tête du menu 🍲', body_fr = 'Aucune idée de ce que vous allez cuisiner aujourd''hui ? Ne vous perdez pas sur Internet, trouvez des recettes nouvelles et faciles dans les articles sur l''alimentation de l''enfant de la rubrique Blogs de l''appli.', title_hi = 'मेन्यू की चिंता 🍲', body_hi = 'आज क्या बनाएँ, कुछ समझ नहीं आ रहा? इंटरनेट में मत उलझिए, ऐप के ब्लॉग सेक्शन में बच्चों के खाने वाले लेखों से नई और आसान रेसिपी ढूँढिए।', title_id = 'Pusing soal menu 🍲', body_id = 'Tidak punya ide mau masak apa hari ini? Jangan tersesat di internet, temukan resep baru yang mudah dari artikel nutrisi anak di bagian Blog aplikasi.', title_ja = '献立の悩み 🍲', body_ja = '今日は何をつくるか、まったく思いつかない？ネットで迷わず、アプリのブログにある子どもの食事の記事から、新しくて簡単なレシピを見つけましょう。', title_ko = '메뉴 고민 🍲', body_ko = '오늘 뭘 만들지 전혀 모르겠나요? 인터넷에서 헤매지 말고 앱의 블로그에 있는 아이 영양 관련 글에서 새롭고 쉬운 레시피를 찾아보세요.', title_nl = 'Wat eten we vandaag? 🍲', body_nl = 'Geen idee wat je vandaag moet koken? Verdwaal niet op internet, maar vind nieuwe, makkelijke recepten in de artikelen over kindervoeding in Blogs in de app.', title_pl = 'Kłopot z menu 🍲', body_pl = 'Nie masz pomysłu, co dziś ugotować? Nie gub się w internecie, znajdź nowe i łatwe przepisy w artykułach o żywieniu dzieci w sekcji Blog w aplikacji.', title_pt = 'A dor de cabeça da ementa 🍲', body_pt = 'Não faz ideia do que cozinhar hoje? Não se perca na internet: encontre receitas novas e fáceis nos artigos sobre alimentação infantil da secção Blogues da app.', title_sv = 'Menyhuvudvärk 🍲', body_sv = 'Har du ingen aning om vad du ska laga i dag? Gå inte vilse på internet, hitta nya och enkla recept i artiklarna om barnmat i appens Bloggar.', title_vi = 'Nỗi lo thực đơn 🍲', body_vi = 'Mẹ không biết hôm nay nấu gì? Đừng lạc giữa internet, hãy tìm công thức mới, dễ làm trong các bài viết về dinh dưỡng cho trẻ ở mục Blog của ứng dụng.', title_zh = '菜单烦恼 🍲', body_zh = '今天完全不知道做什么吃？别在网上迷失，去应用博客板块的儿童营养文章里找找新的简单食谱吧。' WHERE id = '6c74968c-8cc0-4bee-8ae3-eae708b5b244' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Buscando causas y efectos 🤔', body_es = '«¿Qué pasa si tiro esto?», «¿Para qué sirve este botón?» No para de hacer pruebas físicas. Vuelve a revisar la seguridad de la casa.', title_fr = 'À la recherche de la cause et de l''effet 🤔', body_fr = '« Qu''est-ce qui se passe si je jette ça ? », « Ce bouton, il sert à quoi ? » Il fait sans cesse des expériences physiques. Vérifiez encore une fois la sécurité de la maison.', title_hi = 'कारण और नतीजे की खोज 🤔', body_hi = '''इसे फेंकूँ तो क्या होगा?'', ''यह बटन किसलिए है?'' वह लगातार शारीरिक प्रयोग करता है। घर की सुरक्षा एक बार फिर जाँच लीजिए।', title_id = 'Mencari sebab-akibat 🤔', body_id = 'Kalau aku lempar ini, apa yang terjadi?, Tombol ini untuk apa? Ia terus melakukan percobaan fisik. Periksa kembali keamanan rumah Anda.', title_ja = '原因と結果を探して 🤔', body_ja = '「これを投げたらどうなる？」「このボタンはなんのため？」いつも体を使って実験しています。家の安全対策をもう一度見直しましょう。', title_ko = '원인과 결과 찾기 🤔', body_ko = '''이걸 던지면 어떻게 될까?'', ''이 버튼은 뭐지?'' 쉬지 않고 실험하고 있어요. 집 안 안전을 한 번 더 점검해 보세요.', title_nl = 'Op zoek naar oorzaak en gevolg 🤔', body_nl = 'Wat gebeurt er als ik dit gooi? Waar is dit knopje voor? Hij doet voortdurend lichamelijke proefjes. Controleer de veiligheid van je huis nog eens.', title_pl = 'W poszukiwaniu przyczyny i skutku 🤔', body_pl = '„Co się stanie, jak to rzucę?”, „Do czego jest ten przycisk?” Bez przerwy robi fizyczne eksperymenty. Jeszcze raz sprawdź bezpieczeństwo w domu.', title_pt = 'À procura de causa e efeito 🤔', body_pt = '"O que acontece se eu atirar isto?", "Para que serve este botão?" Faz experiências físicas sem parar. Reveja mais uma vez a segurança da casa.', title_sv = 'På jakt efter orsak och verkan 🤔', body_sv = '”Vad händer om jag kastar den här?”, ”Vad är den här knappen till för?” Barnet gör ständigt fysiska experiment. Gå igenom säkerheten hemma en gång till.', title_vi = 'Tìm hiểu nguyên nhân và kết quả 🤔', body_vi = '"Ném cái này thì sao nhỉ?", "Nút này để làm gì?" Bé liên tục thử nghiệm bằng hành động. Hãy kiểm tra lại mức độ an toàn trong nhà một lần nữa.', title_zh = '探索因果关系 🤔', body_zh = '“扔了这个会怎样？”“这个按钮是干什么的？”宝宝在不停地做实验。再检查一遍家里的安全措施吧。' WHERE id = '855cedcf-292a-4a61-b049-6fd355b3a599' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rabietas en el súper 🛒', title_fr = 'Crises au supermarché 🛒', title_hi = 'बाज़ार में नखरे 🛒', title_id = 'Tantrum di supermarket 🛒', title_ja = 'お店でのかんしゃく 🛒', title_ko = '마트에서 떼쓰기 🛒', title_nl = 'Driftbuien in de supermarkt 🛒', title_pl = 'Histerie w sklepie 🛒', title_pt = 'Birras no supermercado 🛒', title_sv = 'Utbrott i affären 🛒', title_vi = 'Ăn vạ ở siêu thị 🛒', title_zh = '超市里的崩溃 🛒' WHERE id = '274e44c7-f2f2-4e14-a2db-692e3ab50d92' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Calma musical 🎶', body_es = 'La forma más fácil de calmar el llanto de última hora de la tarde es poner su melodía favorita, abrazarle y bailar despacito juntos.', title_fr = 'Sérénité en musique 🎶', body_fr = 'Le plus simple pour apaiser les pleurnicheries de fin de journée : mettez une mélodie qu''il aime, prenez-le dans vos bras et dansez doucement.', title_hi = 'संगीत भरा सुकून 🎶', body_hi = 'शाम को होने वाली चिड़चिड़ाहट को संभालने का सबसे आसान तरीका है उसकी पसंदीदा धुन लगाकर उसे गले लगाकर धीरे-धीरे नाचना।', title_id = 'Damai bersama musik 🎶', body_id = 'Cara termudah meredakan rewel di sore hari adalah memutar melodi favoritnya, memeluknya, lalu berdansa pelan bersamanya.', title_ja = '音楽でほっとひと息 🎶', body_ja = '夕方のぐずりをいちばん簡単に落ち着かせる方法は、好きな曲をかけて、ぎゅっと抱っこしながらゆっくり踊ることです。', title_ko = '음악과 함께 평온하게 🎶', body_ko = '저녁 무렵의 칭얼거림을 달래는 가장 쉬운 방법은 좋아하는 노래를 틀고 꼭 안은 채 천천히 춤추는 거예요.', title_nl = 'Muzikale rust 🎶', body_nl = 'De makkelijkste manier om het gezeur aan het eind van de middag op te lossen: zet zijn lievelingsmelodie op, knuffel hem en dans samen langzaam.', title_pl = 'Muzyczny spokój 🎶', body_pl = 'Najprostszy sposób na wieczorne marudzenie to włączyć jego ulubioną melodię, przytulić go i powoli razem zatańczyć.', title_pt = 'Tranquilidade com música 🎶', body_pt = 'A forma mais fácil de acalmar a rabugice do fim da tarde é pôr uma melodia de que ele goste, abraçá-lo e dançar devagarinho.', title_sv = 'Lugn med musik 🎶', body_sv = 'Det enklaste sättet att lösa gnälligheten framåt kvällen är att sätta på en favoritmelodi, krama barnet och dansa långsamt tillsammans.', title_vi = 'Bình yên cùng âm nhạc 🎶', body_vi = 'Cách dễ nhất để xoa dịu cơn quấy khóc lúc chiều tối là bật giai điệu bé yêu thích, ôm bé vào lòng và nhẹ nhàng nhảy cùng bé.', title_zh = '音乐中的安宁 🎶', body_zh = '解决傍晚哭闹最简单的办法，就是放一首宝宝喜欢的曲子，抱着宝宝慢慢跳舞。' WHERE id = '90cdd9aa-f5c9-402b-8ee4-af9073e319ae' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
