UPDATE public.mommy_day_notifications SET title_es = 'Sin cuento no se duerme 🪄', title_fr = 'Pas de dodo sans conte 🪄', title_hi = 'बिना कहानी के नींद नहीं 🪄', title_id = 'Tak bisa tidur tanpa dongeng 🪄', title_ja = 'お話がないと眠れない 🪄', title_ko = '동화 없이는 못 자요 🪄', title_nl = 'Niet slapen zonder sprookje 🪄', title_pl = 'Bez bajki nie zasypiamy 🪄', title_pt = 'Sem história não se dorme 🪄', title_sv = 'Ingen sömn utan saga 🪄', title_vi = 'Không có truyện thì không ngủ 🪄', title_zh = '没有故事不睡觉 🪄' WHERE id = 'f1a78ec7-6b62-43e2-8747-e4f8c033a5e7' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET body_es = 'Cuando tu peque se duerma, sírvete un té con tu pareja para soltar el estrés del día y reconoceos mutuamente diciendo: «Somos un gran equipo».', body_fr = 'Une fois qu''il dort, évacuez le stress du jour en partageant un thé avec votre conjoint et félicitez-vous en disant « on forme une super équipe ».', body_hi = 'बच्चे के सो जाने के बाद दिन का तनाव उतारने के लिए अपने साथी के साथ चाय पीजिए और ''हम बढ़िया टीम हैं'' कहकर एक-दूसरे की तारीफ़ कीजिए।', body_id = 'Setelah si kecil tidur, lepaskan stres hari ini dengan menuang teh bersama pasangan dan saling menghargai sambil berkata: kita tim yang hebat.', body_ja = 'お子さんが眠ったら、一日のストレスを手放すために、パートナーとお茶をいれて「わたしたち、最高のチームだね」とお互いをねぎらいましょう。', body_ko = '아이가 잠든 뒤 하루의 스트레스를 풀도록 배우자와 차 한 잔을 나누며 ''우리 정말 좋은 팀이야'' 하고 서로를 칭찬해 주세요.', body_nl = 'Schenk, als je kindje slaapt, een kop thee in met je partner om de stress van de dag los te laten, en waardeer elkaar: we zijn een top team.', body_pl = 'Gdy maluch zaśnie, zrzućcie stres dnia: nalejcie sobie z partnerem herbaty i doceńcie się nawzajem, mówiąc „jesteśmy świetną drużyną”.', body_pt = 'Depois de ele adormecer, para largar o stress do dia, sirvam-se de um chá com o seu companheiro e valorizem-se um ao outro dizendo: "Somos uma ótima equipa".', body_sv = 'När barnet somnat, häll upp en kopp te med din partner för att släppa dagens stress och uppskatta varandra med orden ”vi är ett fantastiskt team”.', body_vi = 'Sau khi bé ngủ, để xua tan căng thẳng cả ngày, hãy cùng bạn đời rót một tách trà và khen ngợi nhau: "Chúng mình là một đội tuyệt vời".', body_zh = '孩子睡着后，为了卸下一天的压力，和另一半倒杯茶，说一句“我们是很棒的团队”，互相肯定一下吧。' WHERE id = '3469bb77-d2d2-406c-8c90-287cb3502fb6' AND coalesce(body_es,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(body_id,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El cuento de papá 📖', body_es = 'Esta noche deja descansar tus cuerdas vocales. Que papá se encargue de leer los libros favoritos de tu peque con voces distintas y de forma divertida.', title_fr = 'L''histoire de papa 📖', body_fr = 'Ce soir, reposez vos cordes vocales. Laissez papa lire ses livres préférés en changeant de voix, de façon rigolote.', title_hi = 'पापा की कहानी 📖', body_hi = 'आज शाम अपनी आवाज़ को आराम दीजिए। बच्चे की सबसे पसंदीदा किताबें अलग-अलग आवाज़ों में, मज़ेदार ढंग से पढ़ने का काम पापा को करने दीजिए।', title_id = 'Cerita dari Ayah 📖', body_id = 'Istirahatkan pita suara Anda malam ini. Biarkan Ayah yang bertugas membacakan buku favorit si kecil dengan berbagai nada suara yang lucu.', title_ja = 'パパのお話 📖', body_ja = '今夜はあなたののどを休ませましょう。お子さんの大好きな絵本を、いろいろな声色でおもしろく読む役目は、パパにお任せして。', title_ko = '아빠의 이야기 시간 📖', body_ko = '오늘 밤엔 목을 쉬게 해 주세요. 아이가 가장 좋아하는 책을 다양한 목소리로 재미있게 읽어 주는 일은 아빠에게 맡기세요.', title_nl = 'Papa''s verhaal 📖', body_nl = 'Laat je stembanden vanavond rusten. Laat papa de lievelingsboeken van je kindje grappig voorlezen met verschillende stemmetjes.', title_pl = 'Bajka od taty 📖', body_pl = 'Daj dziś wieczorem odpocząć strunom głosowym. Niech to tata czyta ulubione książeczki malucha zabawnie, różnymi głosami.', title_pt = 'A história do pai 📖', body_pt = 'Esta noite, descanse as cordas vocais. Deixe o pai ler os livros preferidos dele com vozes diferentes e de forma divertida.', title_sv = 'Pappas berättelse 📖', body_sv = 'Vila stämbanden i kväll. Låt pappa läsa barnets favoritböcker med olika röster och på ett roligt sätt.', title_vi = 'Câu chuyện của bố 📖', body_vi = 'Tối nay hãy để dây thanh quản của mẹ được nghỉ. Để bố đảm nhận việc đọc những cuốn sách bé yêu thích bằng nhiều giọng khác nhau thật hài hước.', title_zh = '爸爸讲故事 📖', body_zh = '今晚让你的嗓子休息一下。让爸爸用不同的声音、搞笑地读宝宝最爱的书吧。' WHERE id = 'befcea5e-21fe-4c91-b025-35c7c94f17a1' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'El héroe del cuento 🪄', body_es = 'Esta noche crea en Cuentos inteligentes una historia especial cuyo héroe sea tu peque: «El pequeño valiente al que le encanta lavarse los dientes».', title_fr = 'Le héros du conte 🪄', body_fr = 'Ce soir, créez dans les Contes intelligents une histoire spéciale dont votre enfant est le héros : « Le petit courageux qui adore se brosser les dents ».', title_hi = 'कहानी का हीरो 🪄', body_hi = 'आज शाम स्मार्ट कहानियों में एक खास कहानी बनाइए जिसका हीरो आपका अपना बच्चा हो: दाँत ब्रश करना पसंद करने वाला एक बहादुर नन्हा।', title_id = 'Tokoh utama dongeng 🪄', body_id = 'Malam ini, buat cerita istimewa di Dongeng Pintar dengan anak Anda sebagai tokoh utamanya: Si kecil pemberani yang suka menyikat gigi.', title_ja = 'お話の主人公 🪄', body_ja = '今夜は「スマートおはなし」で、お子さんが主人公の特別なお話をつくりましょう：「歯みがきが大好きな勇敢なおちびさん」。', title_ko = '동화 속 주인공 🪄', body_ko = '오늘 밤 스마트 동화에서 우리 아이가 주인공인 특별한 이야기를 만들어 보세요: ''양치를 좋아하는 용감한 꼬마''.', title_nl = 'De held van het sprookje 🪄', body_nl = 'Maak vanavond in Slimme sprookjes een speciaal verhaal met je eigen kindje als held: de dappere kleine die graag zijn tanden poetst.', title_pl = 'Bohater bajki 🪄', body_pl = 'Dziś wieczorem stwórz w Mądrych bajkach wyjątkową historię, w której bohaterem jest twoje dziecko: „Dzielny maluch, który uwielbia myć ząbki”.', title_pt = 'O herói da história 🪄', body_pt = 'Esta noite, crie nas Histórias Inteligentes uma história especial em que o herói é o seu filho: "O pequeno corajoso que adora escovar os dentes".', title_sv = 'Sagans hjälte 🪄', body_sv = 'Skapa i kväll en speciell berättelse i Smarta sagor där ditt eget barn är hjälten: den modiga lilla som älskar att borsta tänderna.', title_vi = 'Nhân vật chính của câu chuyện 🪄', body_vi = 'Tối nay, hãy tạo một câu chuyện đặc biệt trong Truyện cổ tích thông minh với nhân vật chính là bé: "Em bé dũng cảm thích đánh răng".', title_zh = '故事的主角 🪄', body_zh = '今晚在智能故事里创作一个以你的孩子为主角的特别故事：一个爱刷牙的勇敢小家伙。' WHERE id = '8139ee6f-daa0-4072-ad02-2be67ee8488d' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
