UPDATE public.mommy_day_notifications SET title_es = 'Operación verdura secreta 🥦', title_fr = 'Opération légumes cachés 🥦', title_hi = 'छिपी सब्ज़ी का मिशन 🥦', title_id = 'Misi sayuran rahasia 🥦', title_ja = 'こっそり野菜作戦 🥦', title_ko = '채소 몰래 작전 🥦', title_nl = 'Geheime groente-operatie 🥦', title_pl = 'Tajna misja warzywna 🥦', title_pt = 'Operação legumes escondidos 🥦', title_sv = 'Hemlig grönsaksoperation 🥦', title_vi = 'Chiến dịch giấu rau củ 🥦', title_zh = '秘密蔬菜行动 🥦' WHERE id = '5e96bc6a-ca0b-4e3c-9cde-441c31566ab3' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Respira hondo 🧘‍♀️', body_es = 'Se te ha secado la garganta de responder preguntas todo el día. En cuanto llegue el silencio a la habitación, sin mirar ninguna pantalla, simplemente respira hondo y descansa.', title_fr = 'Respirez profondément 🧘‍♀️', body_fr = 'Vous avez la gorge sèche à force de répondre à ses questions toute la journée. Dès que le silence tombe dans la chambre, reposez-vous en respirant profondément, sans regarder aucun écran.', title_hi = 'गहरी साँस 🧘‍♀️', body_hi = 'दिनभर सवालों के जवाब देते-देते गला सूख गया है। कमरे में खामोशी होते ही किसी स्क्रीन को देखे बिना बस गहरी साँस लीजिए-छोड़िए और आराम कीजिए।', title_id = 'Tarik napas dalam-dalam 🧘‍♀️', body_id = 'Tenggorokan Anda kering karena menjawab pertanyaan seharian. Begitu kamar hening, jangan lihat layar apa pun, cukup tarik dan embuskan napas dalam-dalam dan beristirahatlah.', title_ja = '深呼吸 🧘‍♀️', body_ja = '一日中質問に答えて、のどがからからですね。部屋が静かになったら、画面は見ずに、ただ深く息を吸って吐いて、休みましょう。', title_ko = '깊은 숨 🧘‍♀️', body_ko = '하루 종일 질문에 대답하느라 목이 다 말랐죠. 방이 조용해지면 화면은 보지 말고 그냥 깊게 숨을 들이쉬고 내쉬며 쉬세요.', title_nl = 'Diep ademhalen 🧘‍♀️', body_nl = 'Je keel is droog van de hele dag vragen beantwoorden. Zodra het stil is in de kamer: kijk naar geen enkel scherm, adem gewoon diep in en uit en rust uit.', title_pl = 'Głęboki oddech 🧘‍♀️', body_pl = 'Od całodziennego odpowiadania na pytania zaschło ci w gardle. Gdy tylko w pokoju zapadnie cisza, nie patrz na żaden ekran, po prostu oddychaj głęboko i odpocznij.', title_pt = 'Respire fundo 🧘‍♀️', body_pt = 'Ficou com a garganta seca de responder a perguntas o dia todo. Assim que o quarto ficar em silêncio, sem olhar para nenhum ecrã, simplesmente respire fundo e descanse.', title_sv = 'Djupt andetag 🧘‍♀️', body_sv = 'Halsen är torr efter att ha svarat på frågor hela dagen. Så fort det blir tyst i rummet, titta inte på någon skärm, andas bara djupt in och ut och vila.', title_vi = 'Hít thở sâu 🧘‍♀️', body_vi = 'Trả lời câu hỏi cả ngày khiến cổ họng mẹ khô khốc. Ngay khi phòng yên tĩnh, đừng nhìn vào màn hình nào cả, chỉ cần hít thở sâu và nghỉ ngơi.', title_zh = '深呼吸 🧘‍♀️', body_zh = '回答了一整天的问题，嗓子都干了。房间一安静下来，就别看任何屏幕，只是深深地呼吸，好好休息。' WHERE id = '91db0bda-d980-4153-bb7d-0ed55ffcd626' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'La pronunciación de las palabras 🗣️', title_fr = 'La prononciation des mots 🗣️', title_hi = 'शब्दों का उच्चारण 🗣️', title_id = 'Pelafalan kata 🗣️', title_ja = '言葉の発音 🗣️', title_ko = '단어 발음 🗣️', title_nl = 'Woorden uitspreken 🗣️', title_pl = 'Wymowa słów 🗣️', title_pt = 'A pronúncia das palavras 🗣️', title_sv = 'Uttalet av ord 🗣️', title_vi = 'Cách phát âm 🗣️', title_zh = '词语发音 🗣️' WHERE id = 'de182c61-510f-445a-9f50-8ed2459f90cf' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Juego libre 🧸', body_es = 'No tienes que entretenerle cada minuto. Aburrirse es el principio de la creatividad en los niños. Deja que descubra algo él solo en la habitación.', title_fr = 'Jeu libre 🧸', body_fr = 'Vous n''êtes pas obligée de l''amuser à chaque minute. S''ennuyer, c''est le début de la créativité chez l''enfant. Laissez-le découvrir quelque chose tout seul dans la pièce.', title_hi = 'खुला खेल 🧸', body_hi = 'आपको हर पल उसका मनोरंजन करना ज़रूरी नहीं। ऊबना बच्चों के लिए रचनात्मकता की शुरुआत है। उसे कमरे में अकेले कुछ खोजने दीजिए।', title_id = 'Bermain bebas 🧸', body_id = 'Anda tidak harus menghiburnya setiap menit. Rasa bosan adalah awal kreativitas bagi anak. Biarkan ia menemukan sesuatu sendiri di kamar.', title_ja = '自由に遊ぶ 🧸', body_ja = 'いつもお子さんを楽しませなくても大丈夫。退屈は、子どもにとって創造力のはじまりです。部屋でひとりで何かを探検させてあげましょう。', title_ko = '자유 놀이 🧸', body_ko = '매 순간 아이를 즐겁게 해 줄 필요는 없어요. 심심함은 아이에게 창의력의 시작이에요. 방에서 혼자 무언가를 발견하게 두세요.', title_nl = 'Vrij spel 🧸', body_nl = 'Je hoeft hem niet elke minuut te vermaken. Verveling is voor kinderen het begin van creativiteit. Laat hem zelf iets ontdekken in de kamer.', title_pl = 'Swobodna zabawa 🧸', body_pl = 'Nie musisz zabawiać go w każdej minucie. Nuda to dla dzieci początek kreatywności. Pozwól mu samodzielnie coś odkryć w pokoju.', title_pt = 'Brincadeira livre 🧸', body_pt = 'Não tem de o entreter a cada minuto. Aborrecer-se é, para as crianças, o início da criatividade. Deixe-o descobrir alguma coisa sozinho no quarto.', title_sv = 'Fri lek 🧸', body_sv = 'Du måste inte underhålla barnet varje minut. Uttråkning är början på kreativitet för barn. Låt barnet upptäcka något på egen hand i rummet.', title_vi = 'Chơi tự do 🧸', body_vi = 'Mẹ không cần lúc nào cũng phải giải trí cho bé. Cảm giác buồn chán chính là khởi đầu của sự sáng tạo ở trẻ. Hãy để bé tự khám phá điều gì đó trong phòng.', title_zh = '自由玩耍 🧸', body_zh = '你不必每分钟都陪宝宝玩。无聊是孩子创造力的起点。让宝宝在房间里自己去探索吧。' WHERE id = 'f4bf03e5-dc33-4bfa-a875-42962b014227' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Líquidos y estreñimiento 💩', title_fr = 'Hydratation et constipation 💩', title_hi = 'तरल और कब्ज़ 💩', title_id = 'Asupan cairan dan sembelit 💩', title_ja = '水分補給と便秘 💩', title_ko = '수분 섭취와 변비 💩', title_nl = 'Drinken en verstopping 💩', title_pl = 'Picie a zaparcia 💩', title_pt = 'Líquidos e prisão de ventre 💩', title_sv = 'Vätskeintag och förstoppning 💩', title_vi = 'Uống nước và táo bón 💩', title_zh = '饮水与便秘 💩' WHERE id = '0727c4e7-7433-410a-9da5-27fff69d9877' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Rechazo de la siesta 🥱', title_fr = 'Refus de la sieste 🥱', title_hi = 'दिन की नींद से इनकार 🥱', title_id = 'Menolak tidur siang 🥱', title_ja = 'お昼寝を嫌がる 🥱', title_ko = '낮잠 거부 🥱', title_nl = 'Geen middagdutje 🥱', title_pl = 'Odmowa drzemki 🥱', title_pt = 'Recusa a sesta 🥱', title_sv = 'Vägrar dagsömn 🥱', title_vi = 'Từ chối giấc ngủ ngày 🥱', title_zh = '拒绝午睡 🥱' WHERE id = '100fc6ed-66a7-4e9e-939c-15af0683652e' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Cuando mamá está cansada 🛑', body_es = 'No eres un robot. Si hoy no tienes fuerzas para cocinar, pide comida a domicilio. Ser una madre perfecta no significa hacerlo todo sola.', title_fr = 'Quand maman est fatiguée 🛑', body_fr = 'Vous n''êtes pas un robot. Si vous n''avez pas la force de cuisiner aujourd''hui, commandez à manger. Être une maman parfaite ne veut pas dire tout faire seule.', title_hi = 'जब माँ थक जाए 🛑', body_hi = 'आप रोबोट नहीं हैं। अगर आज खाना बनाने की ताकत नहीं है, तो बाहर से मँगवा लीजिए। परफ़ेक्ट माँ होने का मतलब सब कुछ अकेले करना नहीं है।', title_id = 'Saat ibu lelah 🛑', body_id = 'Anda bukan robot. Jika hari ini tidak punya tenaga untuk memasak, pesan saja dari luar. Menjadi ibu yang sempurna bukan berarti melakukan semuanya sendirian.', title_ja = 'ママが疲れたとき 🛑', body_ja = 'あなたはロボットではありません。今日料理をする元気がないなら、出前をとりましょう。完璧なママとは、すべてをひとりでこなすことではありません。', title_ko = '엄마가 지칠 때 🛑', body_ko = '엄마는 로봇이 아니에요. 오늘 요리할 힘이 없다면 배달을 시키세요. 완벽한 엄마라고 모든 걸 혼자 해야 하는 건 아니에요.', title_nl = 'Als mama moe is 🛑', body_nl = 'Je bent geen robot. Heb je vandaag geen energie om te koken, bestel dan eten. Een perfecte moeder zijn betekent niet alles alleen doen.', title_pl = 'Gdy mama jest zmęczona 🛑', body_pl = 'Nie jesteś robotem. Jeśli dziś nie masz siły gotować, zamów jedzenie. Bycie idealną mamą nie oznacza robienia wszystkiego samej.', title_pt = 'Quando a mãe se cansa 🛑', body_pt = 'Não é um robô. Se hoje não tem forças para cozinhar, encomende comida. Ser uma mãe perfeita não significa fazer tudo sozinha.', title_sv = 'När mamma är trött 🛑', body_sv = 'Du är ingen robot. Om du inte orkar laga mat i dag, beställ hem. Att vara en perfekt mamma betyder inte att göra allt på egen hand.', title_vi = 'Khi mẹ mệt mỏi 🛑', body_vi = 'Mẹ không phải là robot. Nếu hôm nay không còn sức nấu ăn, hãy gọi đồ ăn bên ngoài. Làm mẹ hoàn hảo không có nghĩa là tự mình làm tất cả.', title_zh = '当妈妈累了 🛑', body_zh = '你不是机器人。如果今天没力气做饭，就点外卖吧。做完美妈妈，不等于什么都要自己做。' WHERE id = '2a429f3f-0b1b-49c6-befd-28bf5cd2cf98' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
