UPDATE public.mommy_day_notifications SET title_es = 'Escudo de calcio 🦴', title_fr = 'Bouclier calcium 🦴', title_hi = 'कैल्शियम की ढाल 🦴', title_id = 'Perisai kalsium 🦴', title_ja = 'カルシウムのシールド 🦴', title_ko = '칼슘 방패 🦴', title_nl = 'Calciumschild 🦴', title_pl = 'Tarcza z wapnia 🦴', title_pt = 'Escudo de cálcio 🦴', title_sv = 'Kalciumskölden 🦴', title_vi = 'Lá chắn canxi 🦴', title_zh = '钙的护盾 🦴' WHERE id = '6c779bea-dc2a-41ad-8ebb-96d5620eee3b' AND coalesce(title_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(title_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Estirón de talla y peso! 📏', body_es = '¿Al vestirle has notado que las camisetas le quedan estrechas o le aprietan los zapatos? Introduce su talla y medidas actuales en el Registro de peso y mira con orgullo cómo sube su curva de crecimiento.', title_fr = 'Pic de taille et de poids ! 📏', body_fr = 'En l''habillant, vous avez remarqué que les t-shirts serraient ou que les chaussures étaient étroites ? Entrez sa taille et ses mesures actuelles dans le Suivi du poids et regardez fièrement sa courbe grimper.', title_hi = 'लंबाई और वज़न में उछाल! 📏', body_hi = 'कपड़े पहनाते समय लगा कि कमीज़ें तंग हो गईं या जूते काट रहे हैं? वेट ट्रैकर में मौजूदा लंबाई और माप दर्ज कीजिए और गर्व से देखिए कि ग्रोथ कर्व कैसे ऊपर जा रहा है।', title_id = 'Lonjakan tinggi dan berat badan! 📏', body_id = 'Saat memakaikan baju, Anda melihat kausnya mulai sempit atau sepatunya sesak? Masukkan tinggi dan ukuran terbarunya ke Pelacak Berat Badan dan lihat dengan bangga kurva pertumbuhannya naik.', title_ja = '身長と体重がぐんと伸びた！📏', body_ja = '着替えのときに、シャツがきつくなったり、靴が小さくなったりしたことに気づきましたか？「体重トラッカー」に今の身長とサイズを入力して、成長曲線が伸びていく様子を誇らしく眺めましょう。', title_ko = '키와 몸무게가 쑥! 📏', body_ko = '옷을 입힐 때 셔츠가 끼거나 신발이 작아진 걸 느꼈나요? 체중 기록에 현재 키와 치수를 입력하고 성장 곡선이 올라가는 모습을 뿌듯하게 지켜보세요.', title_nl = 'Groeispurt in lengte en gewicht! 📏', body_nl = 'Merk je bij het aankleden dat shirtjes krap zitten of schoenen knellen? Voer zijn huidige lengte en maten in de Gewichtstracker in en kijk trots hoe zijn groeicurve stijgt.', title_pl = 'Skok wzrostu i wagi! 📏', body_pl = 'Przy ubieraniu zauważyłaś, że koszulki są ciasne, a buty uciskają? Wpisz aktualny wzrost i wymiary w Liczniku wagi i z dumą patrz, jak pnie się krzywa rozwoju.', title_pt = 'Salto na altura e no peso! 📏', body_pt = 'Ao vesti-lo, reparou que as camisolas estão apertadas ou que os sapatos apertam? Introduza a altura e as medidas atuais no Registo de Peso e veja com orgulho a curva de crescimento a subir.', title_sv = 'Längd- och viktspurt! 📏', body_sv = 'Märkte du att tröjorna blivit trånga eller att skorna klämmer när du klädde på barnet? Ange aktuell längd och mått i Viktspåraren och titta stolt på hur tillväxtkurvan stiger.', title_vi = 'Tăng vọt chiều cao và cân nặng! 📏', body_vi = 'Khi mặc đồ cho bé, mẹ thấy áo chật hơn hay giày bị bó? Hãy nhập chiều cao và số đo hiện tại vào Theo dõi cân nặng và tự hào ngắm đường cong phát triển đi lên.', title_zh = '身高体重猛长！📏', body_zh = '穿衣服时发现上衣变紧，或者鞋子挤脚？在体重记录里输入当前的身高和尺寸，骄傲地看看成长曲线是怎么往上走的。' WHERE id = '5613e3d7-d67b-4e9a-b92f-7ce15054b42e' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¡Oficialmente 2 años! 🎈', body_es = '2 años de esfuerzo sin descanso, amor y noches sin dormir. Escribe en el Diario de ánimo el orgullo de estos {milestone_days} días. ¡Eres una madre realmente increíble!', title_fr = 'Officiellement 2 ans ! 🎈', body_fr = '2 ans d''efforts sans pause, d''amour et de nuits blanches. Écrivez dans le Journal d''humeur la fierté de ces {milestone_days} jours. Vous êtes vraiment une maman formidable !', title_hi = 'अब पूरे 2 साल का! 🎈', body_hi = '2 साल की लगातार मेहनत, प्यार और जागी हुई रातें। इन पूरे {milestone_days} दिनों का गर्व मूड डायरी में लिखिए। आप सच में एक शानदार माँ हैं!', title_id = 'Resmi 2 tahun! 🎈', body_id = '2 tahun kerja keras tanpa henti, cinta, dan kurang tidur. Tuliskan rasa bangga atas {milestone_days} hari ini di Buku Harian Suasana Hati. Anda sungguh ibu yang luar biasa!', title_ja = 'いよいよ2歳！🎈', body_ja = '2年間休みなく続いたがんばり、愛情、そして眠れない夜。この{milestone_days}日間の誇りを「気分日記」に書きましょう。あなたは本当にすばらしいママです！', title_ko = '드디어 두 살! 🎈', body_ko = '쉼 없는 노력과 사랑, 잠 못 이룬 2년. 기분 일기에 지난 {milestone_days}일의 뿌듯함을 적어 보세요. 엄마는 정말 대단한 엄마예요!', title_nl = 'Officieel 2 jaar! 🎈', body_nl = '2 jaar onafgebroken werk, liefde en slapeloosheid. Schrijf de trots van al deze {milestone_days} dagen op in je Stemmingsdagboek. Je bent echt een geweldige moeder!', title_pl = 'Oficjalnie 2 latka! 🎈', body_pl = '2 lata nieustannej pracy, miłości i nieprzespanych nocy. Zapisz w Dzienniku nastroju dumę z tych {milestone_days} dni. Jesteś naprawdę wspaniałą mamą!', title_pt = 'Oficialmente 2 anos! 🎈', body_pt = '2 anos de esforço sem pausa, amor e noites sem dormir. Escreva no Diário de Humor o orgulho de todos estes {milestone_days} dias. É mesmo uma mãe fantástica!', title_sv = 'Officiellt 2 år! 🎈', body_sv = '2 år av oavbrutet arbete, kärlek och sömnlöshet. Skriv ner stoltheten över alla dessa {milestone_days} dagar i Humördagboken. Du är verkligen en fantastisk mamma!', title_vi = 'Chính thức 2 tuổi! 🎈', body_vi = '2 năm không ngừng nghỉ với công sức, tình yêu và những đêm mất ngủ. Hãy viết niềm tự hào của trọn {milestone_days} ngày ấy vào Nhật ký tâm trạng. Mẹ thật sự là một người mẹ tuyệt vời!', title_zh = '正式2岁啦！🎈', body_zh = '2年不间断的付出、爱和不眠之夜。把这{milestone_days}天的骄傲都写进心情日记吧。你真的是一位了不起的妈妈！' WHERE id = '19814a91-cb64-4bf7-bdcb-7655e0d384a4' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Preparando una tarta sin azúcar 🎂', body_es = '¡Para el día especial de mañana hace falta una tarta sana! Descubre en Recetas para bebé tartas sin azúcar refinado, con fruta y totalmente pensadas para niños.', title_fr = 'Préparer un gâteau sans sucre 🎂', body_fr = 'Il faut un gâteau sain pour le grand jour de demain ! Découvrez dans les Recettes pour bébés des gâteaux aux fruits, sans sucre raffiné et parfaitement adaptés aux enfants.', title_hi = 'बिना चीनी का केक 🎂', body_hi = 'कल के खास दिन के लिए सेहतमंद केक चाहिए! बच्चों की रेसिपी में बिना रिफ़ाइंड चीनी वाले, फलों से बने और पूरी तरह बच्चों के लिए सही केक खोजिए।', title_id = 'Menyiapkan kue tanpa gula 🎂', body_id = 'Butuh kue yang sehat untuk hari istimewa besok! Temukan resep kue buah tanpa gula rafinasi yang sepenuhnya ramah anak di Resep Bayi.', title_ja = '砂糖不使用のケーキづくり 🎂', body_ja = '明日の特別な日のために、ヘルシーなケーキが必要です！「離乳食を始める赤ちゃんのレシピ」で、精製糖を使わない、フルーツたっぷりで子どもにやさしいケーキのレシピを見つけましょう。', title_ko = '설탕 없는 케이크 준비 🎂', body_ko = '내일 특별한 날을 위해 건강한 케이크가 필요해요! 아기 레시피에서 정제 설탕 없이 과일로 만드는 아이 친화적인 케이크 레시피를 찾아보세요.', title_nl = 'Taart zonder suiker 🎂', body_nl = 'Voor de speciale dag van morgen is een gezonde taart nodig! Ontdek in Babyrecepten taarten zonder geraffineerde suiker, met fruit en helemaal kindvriendelijk.', title_pl = 'Przygotowanie tortu bez cukru 🎂', body_pl = 'Na jutrzejszy wyjątkowy dzień potrzebny jest zdrowy tort! Odkryj w Przepisach dla niemowląt owocowe torty bez rafinowanego cukru, w pełni przyjazne dzieciom.', title_pt = 'Preparar um bolo sem açúcar 🎂', body_pt = 'Para o dia especial de amanhã, é preciso um bolo saudável! Descubra nas Receitas para bebés receitas de bolo sem açúcar refinado, com fruta e totalmente pensadas para crianças.', title_sv = 'Vi bakar sockerfri tårta 🎂', body_sv = 'Morgondagens speciella dag behöver en nyttig tårta! Upptäck tårtrecept utan raffinerat socker, med frukt och helt barnvänliga, i Recept för bebisar.', title_vi = 'Chuẩn bị bánh kem không đường 🎂', body_vi = 'Ngày đặc biệt mai cần một chiếc bánh kem lành mạnh! Hãy khám phá các công thức bánh kem trái cây không đường tinh luyện, hoàn toàn phù hợp cho trẻ trong Công thức cho bé.', title_zh = '准备无糖蛋糕 🎂', body_zh = '明天的特别日子需要一个健康的蛋糕！在宝宝食谱里发现不含精制糖、加水果、完全适合孩子的蛋糕食谱。' WHERE id = '50a05ffc-5382-423e-b256-bdeac07c78eb' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = 'Lo has conseguido 🥂', body_es = '¡Dos años de entrega! Si tu peque se ha dormido, deja las tareas de casa. Abre el Diario de ánimo, escríbete un agradecimiento y simplemente descansa.', title_fr = 'Vous avez réussi 🥂', body_fr = 'Deux ans de dévouement ! S''il dort, laissez les tâches ménagères. Ouvrez le Journal d''humeur, écrivez-vous un merci et reposez-vous simplement.', title_hi = 'आपने कर दिखाया 🥂', body_hi = 'दो साल का त्याग! बच्चा सो गया है तो घर के काम छोड़िए। मूड डायरी खोलिए, खुद को एक धन्यवाद लिखिए और बस आराम कीजिए।', title_id = 'Anda berhasil 🥂', body_id = 'Dua tahun penuh pengorbanan! Jika si kecil sudah tidur, tinggalkan pekerjaan rumah. Buka Buku Harian Suasana Hati, tulis ucapan terima kasih untuk diri sendiri, dan beristirahatlah.', title_ja = 'やりとげましたね 🥂', body_ja = '2年間の献身！お子さんが眠ったら、家事はそのままで。「気分日記」を開いて、自分に「ありがとう」を書き、ただゆっくり休みましょう。', title_ko = '해냈어요 🥂', body_ko = '2년간의 헌신! 아이가 잠들었다면 집안일은 내려놓으세요. 기분 일기를 열어 나에게 고맙다는 말을 적고 그냥 쉬세요.', title_nl = 'Het is je gelukt 🥂', body_nl = 'Twee jaar toewijding! Slaapt je kindje? Laat het huishouden liggen. Open je Stemmingsdagboek, schrijf jezelf een bedankje en rust gewoon uit.', title_pl = 'Udało ci się 🥂', body_pl = 'Dwa lata poświęcenia! Jeśli maluch śpi, zostaw obowiązki. Otwórz Dziennik nastroju, napisz sobie podziękowanie i po prostu odpocznij.', title_pt = 'Conseguiu 🥂', body_pt = 'Dois anos de dedicação! Se ele já adormeceu, deixe as tarefas da casa. Abra o Diário de Humor, escreva um agradecimento a si própria e simplesmente descanse.', title_sv = 'Du klarade det 🥂', body_sv = 'Två år av uppoffringar! Sover barnet, släpp hushållssysslorna. Öppna Humördagboken, skriv ett tack till dig själv och vila bara.', title_vi = 'Mẹ đã làm được rồi 🥂', body_vi = 'Hai năm hy sinh! Nếu bé đã ngủ, hãy gác lại việc nhà. Mở Nhật ký tâm trạng, viết một lời cảm ơn cho chính mình và chỉ cần nghỉ ngơi thôi.', title_zh = '你做到了 🥂', body_zh = '两年的付出！孩子睡着了的话，就放下家务。打开心情日记，给自己写一句感谢，然后好好休息。' WHERE id = '6a49b5e2-afea-42a7-8643-310e7b5b7642' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
UPDATE public.mommy_day_notifications SET title_es = '¿El síndrome de los 2 años? 🌪️', body_es = '¿Hay más «noes» y más gritos? Para pasar esta famosa etapa con tranquilidad, pide ya a Anacan AI estrategias para gestionar las crisis emocionales.', title_fr = 'Le terrible two ? 🌪️', body_fr = 'Les « non » et les cris se multiplient ? Pour traverser sereinement cette célèbre période, demandez tout de suite à Anacan AI des techniques pour gérer les crises émotionnelles.', title_hi = '2 साल का दौर? 🌪️', body_hi = '''नहीं'' और चीखें बढ़ गई हैं? इस मशहूर दौर को आराम से पार करने के लिए तुरंत Anacan AI से भावनात्मक तूफ़ान संभालने के तरीके जानिए।', title_id = 'Sindrom usia 2 tahun? 🌪️', body_id = 'Kata tidak dan teriakan makin sering? Untuk melewati masa terkenal ini dengan tenang, segera dapatkan taktik menghadapi ledakan emosi dari Anacan AI.', title_ja = '2歳のイヤイヤ期？🌪️', body_ja = '「いや」と叫び声が増えてきましたか？このよく知られた時期を楽に乗りこえるために、気持ちの爆発に対応するコツを、すぐにAnacan AIから教えてもらいましょう。', title_ko = '미운 두 살? 🌪️', body_ko = '''싫어''와 울음이 늘었나요? 이 유명한 시기를 편하게 지나도록 Anacan AI에게 감정 폭발을 다루는 요령을 바로 받아 보세요.', title_nl = 'Peuterpuberteit? 🌪️', body_nl = 'Meer nee''s en geschreeuw? Haal meteen bij Anacan AI tactieken om emotionele buien aan te pakken, zodat je deze bekende fase rustig doorkomt.', title_pl = 'Bunt dwulatka? 🌪️', body_pl = 'Coraz więcej „nie” i krzyków? Aby spokojnie przejść przez ten słynny okres, od razu poznaj z Anacan AI sposoby radzenia sobie z kryzysami emocjonalnymi.', title_pt = 'A crise dos 2 anos? 🌪️', body_pt = 'Os "nãos" e os gritos aumentaram? Para passar com tranquilidade esta fase famosa, peça já ao Anacan AI estratégias para gerir as crises emocionais.', title_sv = '2-årstrots? 🌪️', body_sv = 'Fler ”nej” och skrik? Få direkt taktiker från Anacan AI för att hantera känslomässiga utbrott och ta er lugnt igenom den här välkända perioden.', title_vi = 'Khủng hoảng tuổi lên 2? 🌪️', body_vi = 'Những tiếng "Không" và la hét nhiều hơn? Để vượt qua giai đoạn nổi tiếng này nhẹ nhàng, hãy nhận ngay từ Anacan AI chiến thuật xử lý khủng hoảng cảm xúc.', title_zh = '2岁综合征？🌪️', body_zh = '“不要”和尖叫变多了？为了平稳度过这个出了名的阶段，马上向Anacan AI获取应对情绪崩溃的策略。' WHERE id = 'e00156cd-d1b9-4727-b3d4-e86b004b8681' AND coalesce(title_es,'') = '' AND coalesce(body_es,'') = '' AND coalesce(title_fr,'') = '' AND coalesce(body_fr,'') = '' AND coalesce(title_hi,'') = '' AND coalesce(body_hi,'') = '' AND coalesce(title_id,'') = '' AND coalesce(body_id,'') = '' AND coalesce(title_ja,'') = '' AND coalesce(body_ja,'') = '' AND coalesce(title_ko,'') = '' AND coalesce(body_ko,'') = '' AND coalesce(title_nl,'') = '' AND coalesce(body_nl,'') = '' AND coalesce(title_pl,'') = '' AND coalesce(body_pl,'') = '' AND coalesce(title_pt,'') = '' AND coalesce(body_pt,'') = '' AND coalesce(title_sv,'') = '' AND coalesce(body_sv,'') = '' AND coalesce(title_vi,'') = '' AND coalesce(body_vi,'') = '' AND coalesce(title_zh,'') = '' AND coalesce(body_zh,'') = '';
COMMIT;
